        if( (ap.rows(a)!=ap.len(al)) || (ap.rows(a)!=ap.len(au)))
            throw new alglibexception("Error while calling 'minnlcsetlc2dense': looks like one of arguments has wrong size");
    
        k = ap.rows(a);
        minnlc.minnlcsetlc2dense(state.innerobj, a, al, au, k, null);
    
        return;
    }
            
