        /*************************************************************************
        A single quadratic constraint:
        * NVars         0<=NVars<=N, number of variables actually present in the constraint
        * VarIdx        array[NVars], distinct variable indexes sorted by ascending
        * B             array[NVars], linear term
        * LowerQ        sparse symmetric NVars*NVars matrix in the CRS format,
                        a lower triangle is stored. Diagonal elements are always present.
        * CL, CU        lower and upper bounds, CL<=CU, one or both can be infinite
        * ApplyOrigin   if False, the constraint has the form CL<=f(x)<=CU.
                        if True,  the constraint has the form CL<=f(x-xorigin)<=CU,
                        with origin being specified as a part of the problem.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        public class xquadraticconstraint : apobject
        {
            public int nvars;
            public int[] varidx;
            public double[] b;
            public sparse.sparsematrix lowerq;
            public double cl;
            public double cu;
