        /*************************************************************************
        A general QP problem (a linear/quadratic target subject to a mix  of  box,
        linear, quadratic and conic constraints).

          -- ALGLIB --
             Copyright 20.07.2021 by Bochkanov Sergey
        *************************************************************************/
        public class qpxproblem : apobject
        {
            public int n;
            public bool hasknowntarget;
            public double targetf;
            public bool hasinitialpoint;
            public double[] x0;
            public bool hasknownsolution;
            public double[] solx;
            public bool hasscale;
            public double[] s;
            public bool hasorigin;
            public double[] xorigin;
            public double[] c;
            public bool hasq;
            public sparse.sparsematrix q;
            public bool isupperq;
            public double[] bndl;
            public double[] bndu;
            public int mlc;
            public sparse.sparsematrix a;
            public double[] al;
            public double[] au;
            public int mqc;
            public xquadraticconstraints qc;
            public int mcc;
            public sparse.sparsematrix dummysparse;
            public qpxproblem()
            {
                init();
            }
            public override void init()
            {
                x0 = new double[0];
                solx = new double[0];
                s = new double[0];
                xorigin = new double[0];
                c = new double[0];
                q = new sparse.sparsematrix();
                bndl = new double[0];
                bndu = new double[0];
                a = new sparse.sparsematrix();
                al = new double[0];
                au = new double[0];
                qc = new xquadraticconstraints();
                dummysparse = new sparse.sparsematrix();
            }
            public override alglib.apobject make_copy()
            {
                qpxproblem _result = new qpxproblem();
                _result.n = n;
                _result.hasknowntarget = hasknowntarget;
                _result.targetf = targetf;
                _result.hasinitialpoint = hasinitialpoint;
                _result.x0 = (double[])x0.Clone();
                _result.hasknownsolution = hasknownsolution;
                _result.solx = (double[])solx.Clone();
                _result.hasscale = hasscale;
                _result.s = (double[])s.Clone();
                _result.hasorigin = hasorigin;
                _result.xorigin = (double[])xorigin.Clone();
                _result.c = (double[])c.Clone();
                _result.hasq = hasq;
                _result.q = q!=null ? (sparse.sparsematrix)q.make_copy() : null;
                _result.isupperq = isupperq;
                _result.bndl = (double[])bndl.Clone();
                _result.bndu = (double[])bndu.Clone();
                _result.mlc = mlc;
                _result.a = a!=null ? (sparse.sparsematrix)a.make_copy() : null;
                _result.al = (double[])al.Clone();
                _result.au = (double[])au.Clone();
                _result.mqc = mqc;
                _result.qc = qc!=null ? (xquadraticconstraints)qc.make_copy() : null;
                _result.mcc = mcc;
                _result.dummysparse = dummysparse!=null ? (sparse.sparsematrix)dummysparse.make_copy() : null;
                return _result;
            }
        };


        /*************************************************************************
        This is a test problem class  intended  for  internal  performance  tests.
        Never use it directly in your projects.

        *************************************************************************/
        public class lptestproblem : apobject
        {
            public int n;
            public bool hasknowntarget;
            public double targetf;
            public double[] s;
            public double[] c;
            public double[] bndl;
            public double[] bndu;
            public int m;
            public sparse.sparsematrix a;
            public double[] al;
            public double[] au;
            public lptestproblem()
            {
                init();
            }
            public override void init()
            {
                s = new double[0];
                c = new double[0];
                bndl = new double[0];
                bndu = new double[0];
                a = new sparse.sparsematrix();
                al = new double[0];
                au = new double[0];
            }
            public override alglib.apobject make_copy()
            {
                lptestproblem _result = new lptestproblem();
                _result.n = n;
                _result.hasknowntarget = hasknowntarget;
                _result.targetf = targetf;
                _result.s = (double[])s.Clone();
                _result.c = (double[])c.Clone();
                _result.bndl = (double[])bndl.Clone();
                _result.bndu = (double[])bndu.Clone();
                _result.m = m;
                _result.a = a!=null ? (sparse.sparsematrix)a.make_copy() : null;
                _result.al = (double[])al.Clone();
                _result.au = (double[])au.Clone();
                return _result;
            }
        };




