            ablasf.rsetallocv(n, Double.NegativeInfinity, ref p.bndl, _params);
            ablasf.rsetallocv(n, Double.PositiveInfinity, ref p.bndu, _params);
            p.mlc = 0;
            p.mqc = 0;
            p.mcc = 0;
            xqcinit(n, p.qc, _params);
        }


