        /*************************************************************************
        Set quadratic term; Q can be in any sparse matrix format.

        Only one triangle (lower or upper) is referenced by this function.

          -- ALGLIB --
             Copyright 25.08.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void qpxproblemsetquadraticterm(qpxproblem p,
            sparse.sparsematrix q,
            bool isupper,
            alglib.xparams _params)
        {
            alglib.ap.assert(sparse.sparseiscrs(q, _params), "QPXProblemSetQuadraticTerm: Q is non-CRS matrix");
            p.hasq = true;
            p.isupperq = isupper;
            sparse.sparsecopytocrsbuf(q, p.q, _params);
        }


        /*************************************************************************
        Get quadratic term, returns zero matrix if no quadratic term is present

          -- ALGLIB --
             Copyright 25.08.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void qpxproblemgetquadraticterm(qpxproblem p,
            sparse.sparsematrix q,
            ref bool isupper,
            alglib.xparams _params)
        {
            isupper = new bool();

            if( !p.hasq )
            {
                q.matrixtype = 1;
                q.m = p.n;
                q.n = p.n;
                q.ninitialized = 0;
                ablasf.isetallocv(p.n, 0, ref q.didx, _params);
                ablasf.isetallocv(p.n, 0, ref q.uidx, _params);
                ablasf.isetallocv(p.n+1, 0, ref q.ridx, _params);
                isupper = false;
                return;
            }
            isupper = p.isupperq;
            sparse.sparsecopybuf(p.q, q, _params);
        }


        /*************************************************************************
        Returns False if no quadratic term was specified, or quadratic term is
        numerically zero.

          -- ALGLIB --
             Copyright 25.08.2024 by Bochkanov Sergey
        *************************************************************************/
        public static bool qpxproblemhasquadraticterm(qpxproblem p,
            alglib.xparams _params)
        {
            bool result = new bool();

            if( !p.hasq )
            {
                result = false;
                return result;
            }
            result = p.q.ridx[p.n]>0;
            return result;
        }


