            double[] bndu,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(alglib.ap.len(bndl)>=p.n, "QPXProblemSetBC: len(BndL)<N");
            alglib.ap.assert(alglib.ap.len(bndu)>=p.n, "QPXProblemSetBC: len(BndU)<N");
            for(i=0; i<=p.n-1; i++)
            {
                alglib.ap.assert(math.isfinite(bndl[i]) || Double.IsNegativeInfinity(bndl[i]), "QPXProblemSetBC: BndL contains positive infinity");
                alglib.ap.assert(math.isfinite(bndu[i]) || Double.IsPositiveInfinity(bndu[i]), "QPXProblemSetBC: BndL contains negative infinity");
                p.bndl[i] = bndl[i];
                p.bndu[i] = bndu[i];
            }
        }


