        }


        /*************************************************************************
        Passes entire set of quadratic constraints, overwriting internally
        stored ones.

          -- ALGLIB --
             Copyright 19.08.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void qpxproblemsetxqc(qpxproblem p,
            xquadraticconstraints src,
            alglib.xparams _params)
        {
            xqccopy(src, p.qc, _params);
            p.mqc = xqcgetcount(p.qc, _params);
        }


        /*************************************************************************
        Append two-sided quadratic constraint, same format as minqpaddqc2()

          -- ALGLIB --
             Copyright 19.08.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void qpxproblemaddqc2(qpxproblem p,
            sparse.sparsematrix q,
            bool isupper,
            double[] b,
            double cl,
            double cu,
            bool applyorigin,
            alglib.xparams _params)
        {
            alglib.ap.assert(sparse.sparsegetnrows(q, _params)==p.n && sparse.sparsegetncols(q, _params)==p.n, "QPXProblemAddQC2: rows(Q)<>N or cols(Q)<>N");
            alglib.ap.assert(alglib.ap.len(b)>=p.n, "QPXProblemAddQC2: Length(B)<N");
            alglib.ap.assert(apserv.isfinitevector(b, p.n, _params), "QPXProblemAddQC2: B contains infinite or NaN values!");
            alglib.ap.assert(math.isfinite(cl) || Double.IsNegativeInfinity(cl), "QPXProblemAddQC2: AL is NAN or +INF");
            alglib.ap.assert(math.isfinite(cu) || Double.IsPositiveInfinity(cu), "QPXProblemAddQC2: AU is NAN or -INF");
            if( !sparse.sparseiscrs(q, _params) )
            {
                sparse.sparsecopytocrsbuf(q, p.dummysparse, _params);
                xqcaddqc2(p.qc, p.dummysparse, isupper, b, cl, cu, applyorigin, _params);
            }
            else
            {
                xqcaddqc2(p.qc, q, isupper, b, cl, cu, applyorigin, _params);
            }
            p.mqc = p.mqc+1;
        }


        /*************************************************************************
        Get IDX-th two-sided quadratic constraint, same format as minqpaddqc2(),
        except for the fact that it always returns isUpper=False, even if the
        original matrix was an upper triangular one.

        NOTE: this function is not optimized for big matrices. Whilst still having
              O(max(N,Nonzeros)) running time, it may  be  somewhat  slow  due  to
              dynamic structures being used internally.
              

          -- ALGLIB --
             Copyright 19.08.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void qpxproblemgetqc2i(qpxproblem p,
            int idx,
            sparse.sparsematrix q,
            ref bool isupper,
            ref double[] b,
            ref double cl,
            ref double cu,
            ref bool applyorigin,
            alglib.xparams _params)
        {
            xquadraticconstraint qci = null;
            int i = 0;
            int j0 = 0;
            int j1 = 0;
            int jj = 0;
            int j = 0;
            double v = 0;

            isupper = new bool();
            b = new double[0];
            cl = 0;
            cu = 0;
            applyorigin = new bool();

            alglib.ap.assert(idx>=0 && idx<p.mqc, "QPXProblemGetQC2i: Idx is outside of [0,MQC) range");
            p.qc.constraints.get(idx, ref qci);
            if( qci.nvars==0 )
            {
                q.matrixtype = 1;
                q.m = p.n;
                q.n = p.n;
                q.ninitialized = 0;
                ablasf.isetallocv(p.n, 0, ref q.didx, _params);
                ablasf.isetallocv(p.n, 0, ref q.uidx, _params);
                ablasf.isetallocv(p.n+1, 0, ref q.ridx, _params);
                isupper = false;
                ablasf.rsetallocv(p.n, 0.0, ref b, _params);
                cl = qci.cl;
                cu = qci.cu;
                applyorigin = qci.applyorigin;
                return;
            }
            sparse.sparsecreatebuf(p.n, p.n, qci.lowerq.ridx[qci.nvars], q, _params);
            for(i=0; i<=qci.nvars-1; i++)
            {
                j0 = qci.lowerq.ridx[i];
                j1 = qci.lowerq.ridx[i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    j = qci.lowerq.idx[jj];
                    v = qci.lowerq.vals[jj];
                    sparse.sparseset(q, qci.varidx[i], qci.varidx[j], v, _params);
                }
            }
            sparse.sparseconverttocrs(q, _params);
            isupper = false;
            ablasf.rsetallocv(p.n, 0.0, ref b, _params);
            for(i=0; i<=qci.nvars-1; i++)
            {
                b[qci.varidx[i]] = qci.b[i];
            }
            cl = qci.cl;
            cu = qci.cu;
            applyorigin = qci.applyorigin;
        }


        /*************************************************************************
        Initialize quadratic constraints structure
        *************************************************************************/
        public static void xqcinit(int n,
            xquadraticconstraints state,
            alglib.xparams _params)
        {
            alglib.ap.assert(n>=1, "xqcInit: N<1");
            state.n = n;
            state.constraints.clear();
        }


        /*************************************************************************
        Clear quadratic constraints structure
        *************************************************************************/
        public static void xqcclear(xquadraticconstraints state,
            alglib.xparams _params)
        {
            state.constraints.clear();
        }


        /*************************************************************************
        Update N, only larger values are possible
        *************************************************************************/
        public static void xqcupdaten(xquadraticconstraints state,
            int newn,
            alglib.xparams _params)
        {
            alglib.ap.assert(newn>=state.n, "xqcUpdateN: newN<N");
            state.n = newn;
        }


        /*************************************************************************
        Copies quadratic constraints structure, target structure is cleared,
        previously allocated memory is ignored.
        *************************************************************************/
        public static void xqccopy(xquadraticconstraints src,
            xquadraticconstraints dst,
            alglib.xparams _params)
        {
            int i = 0;
            int m = 0;
            xquadraticconstraint c = null;
            xquadraticconstraint c1 = null;

            dst.n = src.n;
            m = src.constraints.getlength();
            dst.constraints.clear();
            for(i=0; i<=m-1; i++)
            {
                src.constraints.get(i, ref c);
                c1 = new xquadraticconstraint();
                c1.nvars = c.nvars;
                c1.cl = c.cl;
                c1.cu = c.cu;
                c1.applyorigin = c.applyorigin;
                if( c.nvars>0 )
                {
                    ablasf.icopyallocv(c.nvars, c.varidx, ref c1.varidx, _params);
                    ablasf.rcopyallocv(c.nvars, c.b, ref c1.b, _params);
                    sparse.sparsecopybuf(c.lowerq, c1.lowerq, _params);
                }
                dst.constraints.append(c1);
            }
        }


        /*************************************************************************
        Get constraints count
        *************************************************************************/
        public static int xqcgetcount(xquadraticconstraints xqc,
            alglib.xparams _params)
        {
            int result = 0;

            result = xqc.constraints.getlength();
            return result;
        }


        /*************************************************************************
        Append quadratic constraint given by a sparse quadratic matrix
        *************************************************************************/
        public static void xqcaddqc2(xquadraticconstraints xqc,
            sparse.sparsematrix q,
            bool isupper,
            double[] b,
            double cl,
            double cu,
            bool applyorigin,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int offs = 0;
            int n = 0;
            int isrc = 0;
            double vq = 0;
            xquadraticconstraint c = null;

            alglib.ap.assert(math.isfinite(cl) || Double.IsNegativeInfinity(cl), "xqcAppendDense: CL is not finite or -INF");
            alglib.ap.assert(math.isfinite(cu) || Double.IsPositiveInfinity(cu), "xqcAppendDense: CU is not finite or +INF");
            n = xqc.n;
            c = new xquadraticconstraint();
            ablasf.isetallocv(n, 0, ref xqc.tmpi, _params);
            for(i=0; i<=n-1; i++)
            {
                if( b[i]!=0.0 )
                {
                    xqc.tmpi[i] = 1;
                }
            }
            for(i=0; i<=n-1; i++)
            {
                if( isupper )
                {
                    j0 = q.didx[i];
                    j1 = q.ridx[i+1]-1;
                }
                else
                {
                    j0 = q.ridx[i];
                    j1 = q.uidx[i]-1;
                }
                for(jj=j0; jj<=j1; jj++)
                {
                    if( q.vals[jj]!=0.0 )
                    {
                        xqc.tmpi[i] = 1;
                        xqc.tmpi[q.idx[jj]] = 1;
                    }
                }
            }
            c.nvars = 0;
            for(i=0; i<=n-1; i++)
            {
                if( xqc.tmpi[i]!=0 )
                {
                    ablasf.igrowv(c.nvars+1, ref c.varidx, _params);
                    c.varidx[c.nvars] = i;
                    c.nvars = c.nvars+1;
                }
            }
            c.applyorigin = applyorigin;
            c.cl = cl;
            c.cu = cu;
            if( c.nvars>0 )
            {
                ablasf.isetallocv(n, -999999999, ref xqc.tmpi, _params);
                for(i=0; i<=c.nvars-1; i++)
                {
                    xqc.tmpi[c.varidx[i]] = i;
                }
                ablasf.rallocv(c.nvars, ref c.b, _params);
                for(i=0; i<=c.nvars-1; i++)
                {
                    c.b[i] = b[c.varidx[i]];
                }
                c.lowerq.matrixtype = 1;
                c.lowerq.m = c.nvars;
                c.lowerq.n = c.nvars;
                ablasf.iallocv(c.nvars, ref c.lowerq.uidx, _params);
                ablasf.isetallocv(c.nvars, 1, ref c.lowerq.didx, _params);
                ablasf.iallocv(c.nvars+1, ref c.lowerq.ridx, _params);
                if( isupper )
                {
                    for(i=0; i<=c.nvars-1; i++)
                    {
                        isrc = c.varidx[i];
                        j0 = q.uidx[isrc];
                        j1 = q.ridx[isrc+1]-1;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            vq = q.vals[jj];
                            if( vq==0.0 )
                            {
                                continue;
                            }
                            j = xqc.tmpi[q.idx[jj]];
                            c.lowerq.didx[j] = c.lowerq.didx[j]+1;
                        }
                    }
                    c.lowerq.ridx[0] = 0;
                    for(i=0; i<=c.nvars-1; i++)
                    {
                        c.lowerq.ridx[i+1] = c.lowerq.ridx[i]+c.lowerq.didx[i];
                    }
                    ablasf.iallocv(c.lowerq.ridx[c.nvars], ref c.lowerq.idx, _params);
                    ablasf.rallocv(c.lowerq.ridx[c.nvars], ref c.lowerq.vals, _params);
                    ablasf.icopyv(c.nvars, c.lowerq.ridx, c.lowerq.didx, _params);
                    for(i=0; i<=c.nvars-1; i++)
                    {
                        isrc = c.varidx[i];
                        vq = 0;
                        if( q.didx[isrc]!=q.uidx[isrc] )
                        {
                            vq = q.vals[q.didx[isrc]];
                        }
                        offs = c.lowerq.didx[i];
                        c.lowerq.idx[offs] = i;
                        c.lowerq.vals[offs] = vq;
                        c.lowerq.didx[i] = offs+1;
                        j0 = q.uidx[isrc];
                        j1 = q.ridx[isrc+1]-1;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            vq = q.vals[jj];
                            if( vq==0.0 )
                            {
                                continue;
                            }
                            j = xqc.tmpi[q.idx[jj]];
                            offs = c.lowerq.didx[j];
                            c.lowerq.idx[offs] = i;
                            c.lowerq.vals[offs] = vq;
                            c.lowerq.didx[j] = offs+1;
                        }
                    }
                    for(i=0; i<=c.nvars-1; i++)
                    {
                        if( c.lowerq.didx[i]!=c.lowerq.ridx[i+1] )
                        {
                            alglib.ap.assert(false, "OPTSERV: integrity check 5050 failed");
                        }
                    }
                    for(i=0; i<=c.nvars-1; i++)
                    {
                        c.lowerq.didx[i] = c.lowerq.ridx[i+1]-1;
                        c.lowerq.uidx[i] = c.lowerq.ridx[i+1];
                    }
                    c.lowerq.ninitialized = c.lowerq.ridx[c.nvars];
                }
                else
                {
                    c.lowerq.ridx[0] = 0;
                    for(i=0; i<=c.nvars-1; i++)
                    {
                        isrc = c.varidx[i];
                        offs = c.lowerq.ridx[i];
                        ablasf.igrowv(offs+c.nvars, ref c.lowerq.idx, _params);
                        ablasf.rgrowv(offs+c.nvars, ref c.lowerq.vals, _params);
                        j0 = q.ridx[isrc];
                        j1 = q.didx[isrc]-1;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            vq = q.vals[jj];
                            if( vq==0.0 )
                            {
                                continue;
                            }
                            c.lowerq.idx[offs] = xqc.tmpi[q.idx[jj]];
                            c.lowerq.vals[offs] = vq;
                            offs = offs+1;
                        }
                        if( q.didx[isrc]!=q.uidx[isrc] )
                        {
                            c.lowerq.idx[offs] = i;
                            c.lowerq.vals[offs] = q.vals[q.didx[isrc]];
                            offs = offs+1;
                        }
                        else
                        {
                            c.lowerq.idx[offs] = i;
                            c.lowerq.vals[offs] = 0.0;
                            offs = offs+1;
                        }
                        c.lowerq.ridx[i+1] = offs;
                    }
                    for(i=0; i<=c.nvars-1; i++)
                    {
                        c.lowerq.didx[i] = c.lowerq.ridx[i+1]-1;
                        c.lowerq.uidx[i] = c.lowerq.ridx[i+1];
                    }
                    c.lowerq.ninitialized = c.lowerq.ridx[c.nvars];
                }
            }
            xqc.constraints.append(c);
        }


    }
