        }


        /*************************************************************************
        This function starts aggressive probing of the Lagrangian for a  range  of
        step lengths [0,StpMax].

        INPUT PARAMETERS:
            Monitor         -   monitor object
            LagMult         -   array[K-1], lagrange multipliers for nonlinear
                                constraints
            X               -   array[N], initial point for probing
            D               -   array[N], probing direction
            StpMax          -   range of steps to probe
            

          -- ALGLIB --
             Copyright 10.10.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void smoothnessmonitorstartlagrangianprobing(smoothnessmonitor monitor,
            double[] x,
            double[] d,
            double stpmax,
            int inneriter,
            int outeriter,
            alglib.xparams _params)
        {
            int n = 0;
            int k = 0;
            int i = 0;

            n = monitor.n;
            k = monitor.k;
            alglib.ap.assert(apserv.isfinitevector(x, n, _params), "SmoothnessMonitorStartLagrangianProbing: bad X[] array");
            alglib.ap.assert(apserv.isfinitevector(d, n, _params), "SmoothnessMonitorStartLagrangianProbing: bad D[] array");
            alglib.ap.assert(math.isfinite(stpmax) && (double)(stpmax)>(double)(0), "SmoothnessMonitorStartLagrangianProbing: StpMax<=0");
            alglib.ap.assert(k>=1, "SmoothnessMonitorStartLagrangianProbing: monitor object is initialized with K<=0");
            monitor.lagprobnstepsstored = 0;
            monitor.lagprobstepmax = stpmax;
            monitor.lagprobinneriter = inneriter;
            monitor.lagprobouteriter = outeriter;
            apserv.rvectorsetlengthatleast(ref monitor.lagprobxs, n, _params);
            apserv.rvectorsetlengthatleast(ref monitor.lagprobd, n, _params);
            for(i=0; i<=n-1; i++)
            {
                monitor.lagprobxs[i] = x[i];
                monitor.lagprobd[i] = d[i];
            }
            apserv.rvectorsetlengthatleast(ref monitor.lagprobx, n, _params);
            apserv.rvectorsetlengthatleast(ref monitor.lagprobfi, k, _params);
            apserv.rmatrixsetlengthatleast(ref monitor.lagprobj, k, n, _params);
            monitor.lagrangianprobingrcomm.ia = new int[3+1];
            monitor.lagrangianprobingrcomm.ra = new double[4+1];
            monitor.lagrangianprobingrcomm.stage = -1;
            monitor.lagrangianprobingrcomm.clear_handler();
        }


        /*************************************************************************
        This function performs aggressive probing and sends points  to  smoothness
        monitoring queue via EnqueuePoint() call.

        After  each  call  it  returns  point to evaluate in  Monitor.LagProbX and
        current step in Monitor.LagProbStp. Caller has to load function values and
        Jacobian at X into Monitor.LagProbFi and Monitor.LagProbJ, current Lagrangian
        to Monitor.LagProbRawLag and continue iteration.

        NOTE: LagProbX[] is not guarded against constraint violation. Both non-box
              and box constraints are ignored.  It  is  caller  responsibility  to
              provide appropriate  X[],  D[]  and  StpMax  which  do  not  violate
              important constraints

          -- ALGLIB --
             Copyright 10.10.2019 by Bochkanov Sergey
        *************************************************************************/
        public static bool smoothnessmonitorprobelagrangian(smoothnessmonitor monitor,
            alglib.xparams _params)
        {
            bool result = new bool();
            int stpidx = 0;
            int i = 0;
            int j = 0;
            int idx = 0;
            double stp = 0;
            double vlargest = 0;
            double v = 0;
            double v0 = 0;
            double v1 = 0;

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( monitor.lagrangianprobingrcomm.stage>=0 )
            {
                stpidx = monitor.lagrangianprobingrcomm.ia[0];
                i = monitor.lagrangianprobingrcomm.ia[1];
                j = monitor.lagrangianprobingrcomm.ia[2];
                idx = monitor.lagrangianprobingrcomm.ia[3];
                stp = monitor.lagrangianprobingrcomm.ra[0];
                vlargest = monitor.lagrangianprobingrcomm.ra[1];
                v = monitor.lagrangianprobingrcomm.ra[2];
                v0 = monitor.lagrangianprobingrcomm.ra[3];
                v1 = monitor.lagrangianprobingrcomm.ra[4];
            }
            else
            {
                stpidx = 359;
                i = -58;
                j = -919;
                idx = -909;
                stp = 81.0;
                vlargest = 255.0;
                v = 74.0;
                v0 = -788.0;
                v1 = 809.0;
            }
            if( monitor.lagrangianprobingrcomm.stage==0 )
            {
                goto lbl_0;
            }
            
            //
            // Routine body
            //
            monitor.lagprobrawlag = 0;
            monitor.lagprobcvpred = 0;
            monitor.lagprobcvactual = 0;
            stpidx = 0;
        lbl_1:
            if( stpidx>40 )
            {
                goto lbl_3;
            }
            
            //
            // Increase storage size
            //
            apserv.rvectorgrowto(ref monitor.lagprobsteps, monitor.lagprobnstepsstored+1, _params);
            apserv.rvectorgrowto(ref monitor.lagproblagrangians, monitor.lagprobnstepsstored+1, _params);
            apserv.rvectorgrowto(ref monitor.lagprobpredictedcv, monitor.lagprobnstepsstored+1, _params);
            apserv.rvectorgrowto(ref monitor.lagprobactualcv, monitor.lagprobnstepsstored+1, _params);
            apserv.rmatrixgrowrowsto(ref monitor.lagprobvalues, monitor.lagprobnstepsstored+1, monitor.k, _params);
            apserv.rmatrixgrowrowsto(ref monitor.lagprobjacobians, monitor.lagprobnstepsstored+1, monitor.n*monitor.k, _params);
            
            //
            // Determine probing step length, save step to the end of the storage
            //
            if( stpidx<=10 )
            {
                
                //
                // First 11 steps are performed over equidistant grid
                //
                stp = (double)stpidx/(double)10*monitor.lagprobstepmax;
            }
            else
            {
                
                //
                // Subsequent steps target interesting points
                //
                alglib.ap.assert(monitor.lagprobnstepsstored>=3, "SMonitor: critical integrity check failed");
                stp = 0;
                if( stpidx%3==0 )
                {
                    
                    //
                    // Target interval with maximum change in Lagrangian
                    //
                    idx = -1;
                    vlargest = 0;
                    for(j=0; j<=monitor.lagprobnstepsstored-2; j++)
                    {
                        v = Math.Abs(monitor.lagproblagrangians[j+1]-monitor.lagproblagrangians[j]);
                        if( idx<0 || (double)(v)>(double)(vlargest) )
                        {
                            idx = j;
                            vlargest = v;
                        }
                    }
                    stp = 0.5*(monitor.lagprobsteps[idx]+monitor.lagprobsteps[idx+1]);
                }
                if( stpidx%3==1 )
                {
                    
                    //
                    // Target interval [J,J+2] with maximum change in slope of Lagrangian,
                    // select subinterval [J,J+1] or [J+1,J+2] (one with maximum length).
                    //
                    idx = -1;
                    vlargest = 0;
                    for(j=0; j<=monitor.lagprobnstepsstored-3; j++)
                    {
                        v0 = (monitor.lagproblagrangians[j+1]-monitor.lagproblagrangians[j+0])/(monitor.lagprobsteps[j+1]-monitor.lagprobsteps[j+0]+math.machineepsilon);
                        v1 = (monitor.lagproblagrangians[j+2]-monitor.lagproblagrangians[j+1])/(monitor.lagprobsteps[j+2]-monitor.lagprobsteps[j+1]+math.machineepsilon);
                        v = Math.Abs(v0-v1);
                        if( idx<0 || (double)(v)>(double)(vlargest) )
                        {
                            idx = j;
                            vlargest = v;
                        }
                    }
                    if( (double)(monitor.lagprobsteps[idx+2]-monitor.lagprobsteps[idx+1])>(double)(monitor.lagprobsteps[idx+1]-monitor.lagprobsteps[idx+0]) )
                    {
                        stp = 0.5*(monitor.lagprobsteps[idx+2]+monitor.lagprobsteps[idx+1]);
                    }
                    else
                    {
                        stp = 0.5*(monitor.lagprobsteps[idx+1]+monitor.lagprobsteps[idx+0]);
                    }
                }
                if( stpidx%3==2 )
                {
                    
                    //
                    // Target interval with maximum change in sum of squared Jacobian differences
                    //
                    idx = -1;
                    vlargest = 0;
                    for(j=0; j<=monitor.lagprobnstepsstored-2; j++)
                    {
                        v = 0;
                        for(i=0; i<=monitor.k*monitor.n-1; i++)
                        {
                            v = v+math.sqr(monitor.lagprobjacobians[j+1,i]-monitor.lagprobjacobians[j,i]);
                        }
                        if( idx<0 || (double)(v)>(double)(vlargest) )
                        {
                            idx = j;
                            vlargest = v;
                        }
                    }
                    stp = 0.5*(monitor.lagprobsteps[idx]+monitor.lagprobsteps[idx+1]);
                }
            }
            monitor.lagprobsteps[monitor.lagprobnstepsstored] = stp;
            
            //
            // Retrieve user values
            //
            for(i=0; i<=monitor.n-1; i++)
            {
                monitor.lagprobx[i] = monitor.lagprobxs[i]+monitor.lagprobd[i]*stp;
            }
            monitor.lagprobstp = stp;
            monitor.lagrangianprobingrcomm.stage = 0;
            if( monitor.lagrangianprobingrcomm.rcomm2_handler!=null && monitor.lagrangianprobingrcomm.requesttype!=0 && monitor.lagrangianprobingrcomm.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                monitor.lagrangianprobingrcomm.rcomm2_handler(monitor.lagrangianprobingrcomm, monitor.lagrangianprobingrcomm.handler_p0, monitor.lagrangianprobingrcomm.handler_p1, monitor.lagrangianprobingrcomm.handler_p2, monitor.lagrangianprobingrcomm.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
            for(i=0; i<=monitor.k-1; i++)
            {
                monitor.lagprobvalues[monitor.lagprobnstepsstored,i] = monitor.lagprobfi[i];
                for(j=0; j<=monitor.n-1; j++)
                {
                    monitor.lagprobjacobians[monitor.lagprobnstepsstored,i*monitor.n+j] = monitor.lagprobj[i,j];
                }
            }
            monitor.lagproblagrangians[monitor.lagprobnstepsstored] = monitor.lagprobrawlag;
            monitor.lagprobpredictedcv[monitor.lagprobnstepsstored] = monitor.lagprobcvpred;
            monitor.lagprobactualcv[monitor.lagprobnstepsstored] = monitor.lagprobcvactual;
            apserv.inc(ref monitor.lagprobnstepsstored, _params);
            if( stpidx==0 )
            {
                alglib.ap.assert((double)(stp)==(double)(0), "SmoothnessMonitorProbeLagrangian: integrity check failed");
                smoothnessmonitorstartlinesearch(monitor, monitor.lagprobx, monitor.lagprobfi, monitor.lagprobj, monitor.lagprobinneriter, monitor.lagprobouteriter, _params);
            }
            else
            {
                smoothnessmonitorenqueuepoint(monitor, monitor.lagprobd, stp, monitor.lagprobx, monitor.lagprobfi, monitor.lagprobj, _params);
            }
            
            //
            // Resort
            //
            for(j=monitor.lagprobnstepsstored-1; j>=1; j--)
            {
                if( (double)(monitor.lagprobsteps[j-1])<=(double)(monitor.lagprobsteps[j]) )
                {
                    break;
                }
                apserv.swapelements(monitor.lagprobsteps, j-1, j, _params);
                apserv.swapelements(monitor.lagproblagrangians, j-1, j, _params);
                apserv.swapelements(monitor.lagprobpredictedcv, j-1, j, _params);
                apserv.swapelements(monitor.lagprobactualcv, j-1, j, _params);
                apserv.swaprows(monitor.lagprobvalues, j-1, j, monitor.k, _params);
                apserv.swaprows(monitor.lagprobjacobians, j-1, j, monitor.n*monitor.k, _params);
            }
            stpidx = stpidx+1;
            goto lbl_1;
        lbl_3:
            smoothnessmonitorfinalizelinesearch(monitor, _params);
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            monitor.lagrangianprobingrcomm.ia[0] = stpidx;
            monitor.lagrangianprobingrcomm.ia[1] = i;
            monitor.lagrangianprobingrcomm.ia[2] = j;
            monitor.lagrangianprobingrcomm.ia[3] = idx;
            monitor.lagrangianprobingrcomm.ra[0] = stp;
            monitor.lagrangianprobingrcomm.ra[1] = vlargest;
            monitor.lagrangianprobingrcomm.ra[2] = v;
            monitor.lagrangianprobingrcomm.ra[3] = v0;
            monitor.lagrangianprobingrcomm.ra[4] = v1;
            return result;
        }


        /*************************************************************************
        This function prints probing results to trace log.

        Tracing is performed using fixed width for all columns, so you  may  print
        a header before printing trace - and reasonably expect that its width will
        match that of the trace. This function promises that it wont change  trace
        output format without introducing breaking changes into its signature.

        NOTE: this function ALWAYS tries to print results; it is caller's responsibility
              to decide whether he needs tracing or not.

          -- ALGLIB --
             Copyright 10.10.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void smoothnessmonitortracelagrangianprobingresults(smoothnessmonitor monitor,
            alglib.xparams _params)
        {
            smoothnessmonitortracelagrangianprobingresultsx(monitor, false, _params);
        }


        /*************************************************************************
        This function prints probing results to trace log.

        Tracing is performed using fixed width for all columns, so you  may  print
        a header before printing trace - and reasonably expect that its width will
        match that of the trace. This function promises that it wont change  trace
        output format without introducing breaking changes into its signature.

        NOTE: this function ALWAYS tries to print results; it is caller's responsibility
              to decide whether he needs tracing or not.

          -- ALGLIB --
             Copyright 10.10.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void smoothnessmonitortracelagrangianprobingresultsx(smoothnessmonitor monitor,
            bool needcv,
            alglib.xparams _params)
        {
            int i = 0;
            double steplen = 0;
            double mxd = 0;
            double[] lagrangianslopes = new double[0];
            double[] targetslopes = new double[0];

            
            //
            // Compute slopes
            //
            alglib.ap.assert(monitor.lagprobnstepsstored>=2, "SmoothnessMonitorTraceLagrangianProbingResults: less than 2 probing steps");
            lagrangianslopes = new double[monitor.lagprobnstepsstored];
            targetslopes = new double[monitor.lagprobnstepsstored];
            mxd = 0;
            for(i=0; i<=monitor.n-1; i++)
            {
                mxd = Math.Max(mxd, Math.Abs(monitor.lagprobd[i]));
            }
            for(i=0; i<=monitor.lagprobnstepsstored-2; i++)
            {
                steplen = monitor.lagprobsteps[i+1]-monitor.lagprobsteps[i]+100*math.machineepsilon;
                steplen = steplen*(mxd+100*math.machineepsilon);
                lagrangianslopes[i] = (monitor.lagproblagrangians[i+1]-monitor.lagproblagrangians[i])/steplen;
                targetslopes[i] = (monitor.lagprobvalues[i+1,0]-monitor.lagprobvalues[i,0])/steplen;
            }
            lagrangianslopes[monitor.lagprobnstepsstored-1] = lagrangianslopes[monitor.lagprobnstepsstored-2];
            targetslopes[monitor.lagprobnstepsstored-1] = targetslopes[monitor.lagprobnstepsstored-2];
            
            //
            // Print to trace log
            //
            alglib.ap.trace("*** ------------------------------------------------------------");
            if( needcv )
            {
                alglib.ap.trace("--------------------------");
            }
            alglib.ap.trace("\n");
            for(i=0; i<=monitor.lagprobnstepsstored-1; i++)
            {
                alglib.ap.trace(System.String.Format("*** | {0,0:F4} |", monitor.lagprobsteps[i]));
                alglib.ap.trace(System.String.Format(" {0,11:E3} {1,10:E2} |", monitor.lagproblagrangians[i]-monitor.lagproblagrangians[0], lagrangianslopes[i]));
                alglib.ap.trace(System.String.Format(" {0,11:E3} {1,10:E2} |", monitor.lagprobvalues[i,0]-monitor.lagprobvalues[0,0], targetslopes[i]));
                if( needcv )
                {
                    alglib.ap.trace(System.String.Format(" {0,11:E3} {1,11:E3} |", monitor.lagprobactualcv[i], monitor.lagprobpredictedcv[i]));
                }
                alglib.ap.trace("\n");
            }
            alglib.ap.trace("*** ------------------------------------------------------------");
            if( needcv )
            {
                alglib.ap.trace("--------------------------");
            }
            alglib.ap.trace("\n");
        }


        /*************************************************************************
        This subroutine tells monitor to output trace info.

        If CallerSuggestsTrace=True, monitor  ALWAYS  prints  trace,  even  if  no
        suspicions were raised during optimization. If  CallerSuggestsTrace=False,
        the monitor will print trace only if:
        * trace was requested by trace tag 'OPTGUARD' AND suspicious  points  were
          found during optimization
        * trace was requested by trace tag 'OPTGUARD.ALWAYS' - always

          -- ALGLIB --
             Copyright 11.10.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void smoothnessmonitortracestatus(smoothnessmonitor monitor,
            bool callersuggeststrace,
            alglib.xparams _params)
        {
            bool needreport = new bool();
            bool needxdreport = new bool();
            bool suspicionsraised = new bool();
            int i = 0;
            double slope = 0;

            
            //
            // Do we need trace report?
            //
            suspicionsraised = (monitor.rep.nonc0suspected || monitor.rep.nonc1suspected) || monitor.rep.badgradsuspected;
            needreport = false;
            needreport = needreport || callersuggeststrace;
            needreport = needreport || ap.istraceenabled("OPTGUARD.ALWAYS", _params);
            needreport = needreport || (ap.istraceenabled("OPTGUARD", _params) && suspicionsraised);
            if( !needreport )
            {
                return;
            }
            needxdreport = needreport && ap.istraceenabled("OPTIMIZERS.X", _params);
            
            //
            //
            //
            alglib.ap.trace("\n");
            alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
            alglib.ap.trace("// OPTGUARD INTEGRITY CHECKER REPORT                                                              //\n");
            alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
            if( !suspicionsraised )
            {
                alglib.ap.trace("> no discontinuity/nonsmoothness/bad-gradient suspicions were raised during optimization\n");
                return;
            }
            if( monitor.rep.nonc0suspected )
            {
                alglib.ap.trace("> [WARNING] suspected discontinuity (aka C0-discontinuity)\n");
            }
            if( monitor.rep.nonc1suspected )
            {
                alglib.ap.trace("> [WARNING] suspected nonsmoothness (aka C1-discontinuity)\n");
            }
            alglib.ap.trace("> printing out test reports...\n");
            if( monitor.rep.nonc0suspected && monitor.rep.nonc0test0positive )
            {
                alglib.ap.trace("> printing out discontinuity test #0 report:\n");
                alglib.ap.trace("*** -------------------------------------------------------\n");
                alglib.ap.trace("*** | Test #0 for discontinuity was triggered  (this test |\n");
                alglib.ap.trace("*** | analyzes changes in function values).               |\n");
                alglib.ap.trace("*** |                                                     |\n");
                alglib.ap.trace("*** | Function information:                               |\n");
                alglib.ap.trace(System.String.Format("*** | * function index:       {0,10:d}", monitor.nonc0lngrep.fidx));
                if( monitor.nonc0lngrep.fidx==0 )
                {
                    alglib.ap.trace(" (target)         |\n");
                }
                else
                {
                    alglib.ap.trace(" (constraint)     |\n");
                }
                alglib.ap.trace(System.String.Format("*** | * F() Lipschitz const:  {0,10:E2}                  |\n", monitor.rep.nonc0lipschitzc));
                alglib.ap.trace("*** |                                                     |\n");
                alglib.ap.trace("*** | Iteration information:                              |\n");
                if( monitor.nonc0lngrep.inneriter>=0 )
                {
                    alglib.ap.trace(System.String.Format("*** | * inner iter idx:       {0,10:d}                  |\n", monitor.nonc0lngrep.inneriter));
                }
                if( monitor.nonc0lngrep.outeriter>=0 )
                {
                    alglib.ap.trace(System.String.Format("*** | * outer iter idx:       {0,10:d}                  |\n", monitor.nonc0lngrep.outeriter));
                }
                alglib.ap.trace("*** |                                                     |\n");
                alglib.ap.trace("*** | Printing out log of suspicious line search XK+Stp*D |\n");
                alglib.ap.trace("*** | Look for abrupt changes in slope.                   |\n");
                if( !needxdreport )
                {
                    alglib.ap.trace("*** | NOTE: XK and D are  not printed  by default. If you |\n");
                    alglib.ap.trace("*** |       need them, add trace tag OPTIMIZERS.X         |\n");
                }
                alglib.ap.trace("*** -------------------------------------------------------\n");
                alglib.ap.trace("*** |  step along D   |     delta F     |      slope      |\n");
                alglib.ap.trace("*** ------------------------------------------------------|\n");
                for(i=0; i<=monitor.nonc0lngrep.cnt-1; i++)
                {
                    slope = monitor.nonc0lngrep.f[Math.Min(i+1, monitor.nonc0lngrep.cnt-1)]-monitor.nonc0lngrep.f[i];
                    slope = slope/(1.0e-15+monitor.nonc0lngrep.stp[Math.Min(i+1, monitor.nonc0lngrep.cnt-1)]-monitor.nonc0lngrep.stp[i]);
                    alglib.ap.trace(System.String.Format("*** |  {0,13:E5}  |  {1,13:E5}  |   {2,11:E3}   |", monitor.nonc0lngrep.stp[i], monitor.nonc0lngrep.f[i]-monitor.nonc0lngrep.f[0], slope));
                    if( i>=monitor.nonc0lngrep.stpidxa && i<=monitor.nonc0lngrep.stpidxb )
                    {
                        alglib.ap.trace(" <---");
                    }
                    alglib.ap.trace("\n");
                }
                alglib.ap.trace("*** ------------------------------------------------------|\n");
                if( needxdreport )
                {
                    alglib.ap.trace("*** > printing raw variables\n");
                    alglib.ap.trace("*** XK = ");
                    apserv.tracevectorunscaledunshiftedautoprec(monitor.nonc0lngrep.x0, monitor.n, monitor.s, true, monitor.s, false, _params);
                    alglib.ap.trace("\n");
                    alglib.ap.trace("*** D  = ");
                    apserv.tracevectorunscaledunshiftedautoprec(monitor.nonc0lngrep.d, monitor.n, monitor.s, true, monitor.s, false, _params);
                    alglib.ap.trace("\n");
                    alglib.ap.trace("*** > printing scaled variables (values are divided by user-specified scales)\n");
                    alglib.ap.trace("*** XK = ");
                    apserv.tracevectorautoprec(monitor.nonc0lngrep.x0, 0, monitor.n, _params);
                    alglib.ap.trace("\n");
                    alglib.ap.trace("*** D  = ");
                    apserv.tracevectorautoprec(monitor.nonc0lngrep.d, 0, monitor.n, _params);
                    alglib.ap.trace("\n");
                }
            }
            if( monitor.rep.nonc1suspected && monitor.rep.nonc1test0positive )
            {
                alglib.ap.trace("> printing out nonsmoothness test #0 report:\n");
                alglib.ap.trace("*** -------------------------------------------------------\n");
                alglib.ap.trace("*** | Test #0 for nonsmoothness was triggered  (this test |\n");
                alglib.ap.trace("*** | analyzes changes in  function  values  and  ignores |\n");
                alglib.ap.trace("*** | gradient info).                                     |\n");
                alglib.ap.trace("*** |                                                     |\n");
                alglib.ap.trace("*** | Function information:                               |\n");
                alglib.ap.trace(System.String.Format("*** | * function index:         {0,10:d}", monitor.nonc1test0lngrep.fidx));
                if( monitor.nonc1test0lngrep.fidx==0 )
                {
                    alglib.ap.trace(" (target)       |\n");
                }
                else
                {
                    alglib.ap.trace(" (constraint)   |\n");
                }
                alglib.ap.trace(System.String.Format("*** | * dF/dX Lipschitz const:  {0,10:E2}                |\n", monitor.rep.nonc1lipschitzc));
                alglib.ap.trace("*** |                                                     |\n");
                alglib.ap.trace("*** | Iteration information:                              |\n");
                if( monitor.nonc1test0lngrep.inneriter>=0 )
                {
                    alglib.ap.trace(System.String.Format("*** | * inner iter idx:       {0,10:d}                  |\n", monitor.nonc1test0lngrep.inneriter));
                }
                if( monitor.nonc1test0lngrep.outeriter>=0 )
                {
                    alglib.ap.trace(System.String.Format("*** | * outer iter idx:       {0,10:d}                  |\n", monitor.nonc1test0lngrep.outeriter));
                }
                alglib.ap.trace("*** |                                                     |\n");
                alglib.ap.trace("*** | Printing out log of suspicious line search XK+Stp*D |\n");
                alglib.ap.trace("*** | Look for abrupt changes in slope.                   |\n");
                if( !needxdreport )
                {
                    alglib.ap.trace("*** | NOTE: XK and D are  not printed  by default. If you |\n");
                    alglib.ap.trace("*** |       need them, add trace tag OPTIMIZERS.X         |\n");
                }
                alglib.ap.trace("*** -------------------------------------------------------\n");
                alglib.ap.trace("*** |  step along D   |     delta F     |      slope      |\n");
                alglib.ap.trace("*** ------------------------------------------------------|\n");
                for(i=0; i<=monitor.nonc1test0lngrep.cnt-1; i++)
                {
                    slope = monitor.nonc1test0lngrep.f[Math.Min(i+1, monitor.nonc1test0lngrep.cnt-1)]-monitor.nonc1test0lngrep.f[i];
                    slope = slope/(1.0e-15+monitor.nonc1test0lngrep.stp[Math.Min(i+1, monitor.nonc1test0lngrep.cnt-1)]-monitor.nonc1test0lngrep.stp[i]);
                    alglib.ap.trace(System.String.Format("*** |  {0,13:E5}  |  {1,13:E5}  |   {2,11:E3}   |", monitor.nonc1test0lngrep.stp[i], monitor.nonc1test0lngrep.f[i]-monitor.nonc1test0lngrep.f[0], slope));
                    if( i>=monitor.nonc1test0lngrep.stpidxa && i<=monitor.nonc1test0lngrep.stpidxb )
                    {
                        alglib.ap.trace(" <---");
                    }
                    alglib.ap.trace("\n");
                }
                alglib.ap.trace("*** ------------------------------------------------------|\n");
                if( needxdreport )
                {
                    alglib.ap.trace("*** > printing raw variables\n");
                    alglib.ap.trace("*** XK = ");
                    apserv.tracevectorunscaledunshiftedautoprec(monitor.nonc1test0lngrep.x0, monitor.n, monitor.s, true, monitor.s, false, _params);
                    alglib.ap.trace("\n");
                    alglib.ap.trace("*** D  = ");
                    apserv.tracevectorunscaledunshiftedautoprec(monitor.nonc1test0lngrep.d, monitor.n, monitor.s, true, monitor.s, false, _params);
                    alglib.ap.trace("\n");
                    alglib.ap.trace("*** > printing scaled variables (values are divided by user-specified scales)\n");
                    alglib.ap.trace("*** XK = ");
                    apserv.tracevectorautoprec(monitor.nonc1test0lngrep.x0, 0, monitor.n, _params);
                    alglib.ap.trace("\n");
                    alglib.ap.trace("*** D  = ");
                    apserv.tracevectorautoprec(monitor.nonc1test0lngrep.d, 0, monitor.n, _params);
                    alglib.ap.trace("\n");
                }
            }
            if( monitor.rep.nonc1suspected && monitor.rep.nonc1test1positive )
            {
                alglib.ap.trace("> printing out nonsmoothness test #1 report:\n");
                alglib.ap.trace("*** -------------------------------------------------------\n");
                alglib.ap.trace("*** | Test #1 for nonsmoothness was triggered  (this test |\n");
                alglib.ap.trace("*** | analyzes changes in gradient components).           |\n");
                alglib.ap.trace("*** |                                                     |\n");
                alglib.ap.trace("*** | Function information:                               |\n");
                alglib.ap.trace(System.String.Format("*** | * function index:         {0,10:d}", monitor.nonc1test1lngrep.fidx));
                if( monitor.nonc1test1lngrep.fidx==0 )
                {
                    alglib.ap.trace(" (target)       |\n");
                }
                else
                {
                    alglib.ap.trace(" (constraint)   |\n");
                }
                alglib.ap.trace(System.String.Format("*** | * variable index I:       {0,10:d}                |\n", monitor.nonc1test1lngrep.vidx));
                alglib.ap.trace(System.String.Format("*** | * dF/dX Lipschitz const:  {0,10:E2}                |\n", monitor.rep.nonc1lipschitzc));
                alglib.ap.trace("*** |                                                     |\n");
                alglib.ap.trace("*** | Iteration information:                              |\n");
                if( monitor.nonc1test1lngrep.inneriter>=0 )
                {
                    alglib.ap.trace(System.String.Format("*** | * inner iter idx:       {0,10:d}                  |\n", monitor.nonc1test1lngrep.inneriter));
                }
                if( monitor.nonc1test1lngrep.outeriter>=0 )
                {
                    alglib.ap.trace(System.String.Format("*** | * outer iter idx:       {0,10:d}                  |\n", monitor.nonc1test1lngrep.outeriter));
                }
                alglib.ap.trace("*** |                                                     |\n");
                alglib.ap.trace("*** | Printing out log of suspicious line search XK+Stp*D |\n");
                alglib.ap.trace("*** | Look for abrupt changes in slope.                   |\n");
                if( !needxdreport )
                {
                    alglib.ap.trace("*** | NOTE: XK and D are  not printed  by default. If you |\n");
                    alglib.ap.trace("*** |       need them, add trace tag OPTIMIZERS.X         |\n");
                }
                alglib.ap.trace("*** -------------------------------------------------------\n");
                alglib.ap.trace("*** |  step along D   |     delta Gi    |      slope      |\n");
                alglib.ap.trace("*** ------------------------------------------------------|\n");
                for(i=0; i<=monitor.nonc1test1lngrep.cnt-1; i++)
                {
                    slope = monitor.nonc1test1lngrep.g[Math.Min(i+1, monitor.nonc1test1lngrep.cnt-1)]-monitor.nonc1test1lngrep.g[i];
                    slope = slope/(1.0e-15+monitor.nonc1test1lngrep.stp[Math.Min(i+1, monitor.nonc1test1lngrep.cnt-1)]-monitor.nonc1test1lngrep.stp[i]);
                    alglib.ap.trace(System.String.Format("*** |  {0,13:E5}  |  {1,13:E5}  |   {2,11:E3}   |", monitor.nonc1test1lngrep.stp[i], monitor.nonc1test1lngrep.g[i]-monitor.nonc1test1lngrep.g[0], slope));
                    if( i>=monitor.nonc1test1lngrep.stpidxa && i<=monitor.nonc1test1lngrep.stpidxb )
                    {
                        alglib.ap.trace(" <---");
                    }
                    alglib.ap.trace("\n");
                }
                alglib.ap.trace("*** ------------------------------------------------------|\n");
                if( needxdreport )
                {
                    alglib.ap.trace("*** > printing raw variables\n");
                    alglib.ap.trace("*** XK = ");
                    apserv.tracevectorunscaledunshiftedautoprec(monitor.nonc1test1lngrep.x0, monitor.n, monitor.s, true, monitor.s, false, _params);
                    alglib.ap.trace("\n");
                    alglib.ap.trace("*** D  = ");
                    apserv.tracevectorunscaledunshiftedautoprec(monitor.nonc1test1lngrep.d, monitor.n, monitor.s, true, monitor.s, false, _params);
                    alglib.ap.trace("\n");
                    alglib.ap.trace("*** > printing scaled variables (values are divided by user-specified scales)\n");
                    alglib.ap.trace("*** XK = ");
                    apserv.tracevectorautoprec(monitor.nonc1test1lngrep.x0, 0, monitor.n, _params);
                    alglib.ap.trace("\n");
                    alglib.ap.trace("*** D  = ");
                    apserv.tracevectorautoprec(monitor.nonc1test1lngrep.d, 0, monitor.n, _params);
                    alglib.ap.trace("\n");
                }
            }
        }


        /*************************************************************************
        This subroutine exports report to user-readable representation (all arrays
        are forced to have exactly same size as needed; unused arrays are  set  to
        zero length).

          -- ALGLIB --
             Copyright 19.11.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void smoothnessmonitorexportreport(smoothnessmonitor monitor,
            optguardapi.optguardreport rep,
            alglib.xparams _params)
        {
            
            //
            // Finalize last line search, just to be sure
            //
            if( monitor.enqueuedcnt>0 )
            {
                smoothnessmonitorfinalizelinesearch(monitor, _params);
            }
            
            //
            // Export report
            //
            optguardapi.optguardexportreport(monitor.rep, monitor.n, monitor.k, monitor.badgradhasxj, rep, _params);
        }


        /*************************************************************************
        Check numerical gradient at point X0 (unscaled variables!), with  optional
        box constraints [BndL,BndU] (if  HasBoxConstraints=True)  and  with  scale
        vector S[].

        Step S[i]*TestStep is performed along I-th variable.

        NeedFiJ rcomm protocol is used to request derivative information.

        Box constraints BndL/BndU are expected to be feasible. It is  possible  to
        have BndL=BndU.

          -- ALGLIB --
             Copyright 06.12.2018 by Bochkanov Sergey
        *************************************************************************/
        public static bool smoothnessmonitorcheckgradientatx0(smoothnessmonitor monitor,
            double[] unscaledx0,
            double[] s,
            double[] bndl,
            double[] bndu,
            bool hasboxconstraints,
            double teststep,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int k = 0;
            int i = 0;
            int j = 0;
            int varidx = 0;
            double v = 0;
            double vp = 0;
            double vm = 0;
            double vc = 0;

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( monitor.rstateg0.stage>=0 )
            {
                n = monitor.rstateg0.ia[0];
                k = monitor.rstateg0.ia[1];
                i = monitor.rstateg0.ia[2];
                j = monitor.rstateg0.ia[3];
                varidx = monitor.rstateg0.ia[4];
                v = monitor.rstateg0.ra[0];
                vp = monitor.rstateg0.ra[1];
                vm = monitor.rstateg0.ra[2];
                vc = monitor.rstateg0.ra[3];
            }
            else
            {
                n = 205;
                k = -838;
                i = 939;
                j = -526;
                varidx = 763;
                v = -541.0;
                vp = -698.0;
                vm = -900.0;
                vc = -318.0;
            }
            if( monitor.rstateg0.stage==0 )
            {
                goto lbl_0;
            }
            if( monitor.rstateg0.stage==1 )
            {
                goto lbl_1;
            }
            if( monitor.rstateg0.stage==2 )
            {
                goto lbl_2;
            }
            if( monitor.rstateg0.stage==3 )
            {
                goto lbl_3;
            }
            
            //
            // Routine body
            //
            n = monitor.n;
            k = monitor.k;
            monitor.needfij = false;
            
            //
            // Quick exit
            //
            if( ((n<=0 || k<=0) || !math.isfinite(teststep)) || (double)(teststep)==(double)(0) )
            {
                result = false;
                return result;
            }
            teststep = Math.Abs(teststep);
            
            //
            // Allocate storage
            //
            apserv.rvectorsetlengthatleast(ref monitor.x, n, _params);
            apserv.rvectorsetlengthatleast(ref monitor.fi, k, _params);
            apserv.rmatrixsetlengthatleast(ref monitor.j, k, n, _params);
            apserv.rvectorsetlengthatleast(ref monitor.xbase, n, _params);
            apserv.rvectorsetlengthatleast(ref monitor.fbase, k, _params);
            apserv.rvectorsetlengthatleast(ref monitor.fm, k, _params);
            apserv.rvectorsetlengthatleast(ref monitor.fc, k, _params);
            apserv.rvectorsetlengthatleast(ref monitor.fp, k, _params);
            apserv.rvectorsetlengthatleast(ref monitor.jm, k, _params);
            apserv.rvectorsetlengthatleast(ref monitor.jc, k, _params);
            apserv.rvectorsetlengthatleast(ref monitor.jp, k, _params);
            apserv.rmatrixsetlengthatleast(ref monitor.jbaseusr, k, n, _params);
            apserv.rmatrixsetlengthatleast(ref monitor.jbasenum, k, n, _params);
            apserv.rvectorsetlengthatleast(ref monitor.rep.badgradxbase, n, _params);
            apserv.rmatrixsetlengthatleast(ref monitor.rep.badgraduser, k, n, _params);
            apserv.rmatrixsetlengthatleast(ref monitor.rep.badgradnum, k, n, _params);
            
            //
            // Set XBase/Jacobian presence flag
            //
            monitor.badgradhasxj = true;
            
            //
            // Determine reference point, compute function vector and user-supplied Jacobian
            //
            for(i=0; i<=n-1; i++)
            {
                v = unscaledx0[i];
                if( (hasboxconstraints && math.isfinite(bndl[i])) && (double)(v)<(double)(bndl[i]) )
                {
                    v = bndl[i];
                }
                if( (hasboxconstraints && math.isfinite(bndu[i])) && (double)(v)>(double)(bndu[i]) )
                {
                    v = bndu[i];
                }
                monitor.xbase[i] = v;
                monitor.rep.badgradxbase[i] = v;
                monitor.x[i] = v;
            }
            monitor.needfij = true;
            monitor.rstateg0.stage = 0;
            if( monitor.rstateg0.rcomm2_handler!=null && monitor.rstateg0.requesttype!=0 && monitor.rstateg0.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                monitor.rstateg0.rcomm2_handler(monitor.rstateg0, monitor.rstateg0.handler_p0, monitor.rstateg0.handler_p1, monitor.rstateg0.handler_p2, monitor.rstateg0.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
            monitor.needfij = false;
            for(i=0; i<=k-1; i++)
            {
                monitor.fbase[i] = monitor.fi[i];
                for(j=0; j<=n-1; j++)
                {
                    monitor.jbaseusr[i,j] = monitor.j[i,j];
                    monitor.rep.badgraduser[i,j] = monitor.j[i,j];
                }
            }
            
            //
            // Check Jacobian column by column
            //
            varidx = 0;
        lbl_4:
            if( varidx>n-1 )
            {
                goto lbl_6;
            }
            
            //
            // Determine test location.
            //
            v = monitor.xbase[varidx];
            vm = v-s[varidx]*teststep;
            vp = v+s[varidx]*teststep;
            if( (hasboxconstraints && math.isfinite(bndl[varidx])) && (double)(vm)<(double)(bndl[varidx]) )
            {
                vm = bndl[varidx];
            }
            if( (hasboxconstraints && math.isfinite(bndu[varidx])) && (double)(vp)>(double)(bndu[varidx]) )
            {
                vp = bndu[varidx];
            }
            vc = vm+(vp-vm)/2;
            
            //
            // Quickly skip fixed variables
            //
            if( ((double)(vm)==(double)(vp) || (double)(vc)==(double)(vm)) || (double)(vc)==(double)(vp) )
            {
                for(i=0; i<=k-1; i++)
                {
                    monitor.rep.badgradnum[i,varidx] = 0;
                }
                goto lbl_5;
            }
            
            //
            // Compute F/J at three trial points
            //
            for(i=0; i<=n-1; i++)
            {
                monitor.x[i] = monitor.xbase[i];
            }
            monitor.x[varidx] = vm;
            monitor.needfij = true;
            monitor.rstateg0.stage = 1;
            if( monitor.rstateg0.rcomm2_handler!=null && monitor.rstateg0.requesttype!=0 && monitor.rstateg0.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                monitor.rstateg0.rcomm2_handler(monitor.rstateg0, monitor.rstateg0.handler_p0, monitor.rstateg0.handler_p1, monitor.rstateg0.handler_p2, monitor.rstateg0.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            monitor.needfij = false;
            for(i=0; i<=k-1; i++)
            {
                monitor.fm[i] = monitor.fi[i];
                monitor.jm[i] = monitor.j[i,varidx];
            }
            for(i=0; i<=n-1; i++)
            {
                monitor.x[i] = monitor.xbase[i];
            }
            monitor.x[varidx] = vc;
            monitor.needfij = true;
            monitor.rstateg0.stage = 2;
            if( monitor.rstateg0.rcomm2_handler!=null && monitor.rstateg0.requesttype!=0 && monitor.rstateg0.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                monitor.rstateg0.rcomm2_handler(monitor.rstateg0, monitor.rstateg0.handler_p0, monitor.rstateg0.handler_p1, monitor.rstateg0.handler_p2, monitor.rstateg0.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_2:
            monitor.needfij = false;
            for(i=0; i<=k-1; i++)
            {
                monitor.fc[i] = monitor.fi[i];
                monitor.jc[i] = monitor.j[i,varidx];
            }
            for(i=0; i<=n-1; i++)
            {
                monitor.x[i] = monitor.xbase[i];
            }
            monitor.x[varidx] = vp;
            monitor.needfij = true;
            monitor.rstateg0.stage = 3;
            if( monitor.rstateg0.rcomm2_handler!=null && monitor.rstateg0.requesttype!=0 && monitor.rstateg0.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                monitor.rstateg0.rcomm2_handler(monitor.rstateg0, monitor.rstateg0.handler_p0, monitor.rstateg0.handler_p1, monitor.rstateg0.handler_p2, monitor.rstateg0.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_3:
            monitor.needfij = false;
            for(i=0; i<=k-1; i++)
            {
                monitor.fp[i] = monitor.fi[i];
                monitor.jp[i] = monitor.j[i,varidx];
            }
            
            //
            // Check derivative
            //
            for(i=0; i<=k-1; i++)
            {
                monitor.rep.badgradnum[i,varidx] = (monitor.fp[i]-monitor.fm[i])/(vp-vm);
                if( !derivativecheck(monitor.fm[i], monitor.jm[i]*s[varidx], monitor.fp[i], monitor.jp[i]*s[varidx], monitor.fc[i], monitor.jc[i]*s[varidx], (vp-vm)/s[varidx], _params) )
                {
                    monitor.rep.badgradsuspected = true;
                    monitor.rep.badgradfidx = i;
                    monitor.rep.badgradvidx = varidx;
                }
            }
        lbl_5:
            varidx = varidx+1;
            goto lbl_4;
        lbl_6:
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            monitor.rstateg0.ia[0] = n;
            monitor.rstateg0.ia[1] = k;
            monitor.rstateg0.ia[2] = i;
            monitor.rstateg0.ia[3] = j;
            monitor.rstateg0.ia[4] = varidx;
            monitor.rstateg0.ra[0] = v;
            monitor.rstateg0.ra[1] = vp;
            monitor.rstateg0.ra[2] = vm;
            monitor.rstateg0.ra[3] = vc;
            return result;
        }


        /*************************************************************************
        This function initializes approximation of a Hessian.

        Direct BFGS (Hessian matrix H is stored) with stability improvements is used.

        INPUT PARAMETERS:
            Hess            -   Hessian structure, initial state is ignored, but
                                previously allocated memory is reused as much as
                                possible
            N               -   dimensions count
            ResetFreq       -   reset frequency for BFGS :
                                * ResetFreq=0 for standard BFGS
                                * ResetFreq>0 for BFGS with periodic resets (helps
                                  to maintain fresh curvature information, works
                                  better for highly nonquadratic problems)
            StpShort        -   short step length (INF-norm); steps shorter than that
                                are not used for Hessian updates
                                

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianinitbfgs(xbfgshessian hess,
            int n,
            int resetfreq,
            double stpshort,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(resetfreq>=0, "HessianInit: ResetFreq<0");
            resetfreq = Math.Min(resetfreq, n);
            hess.htype = 0;
            hess.n = n;
            hess.resetfreq = resetfreq;
            hess.stpshort = stpshort;
            hess.hage = 0;
            hess.gammasml = 0.000001;
            hess.reg = 100*Math.Sqrt(math.machineepsilon);
            hess.smallreg = 0.01*Math.Sqrt(math.machineepsilon);
            hess.microreg = (1000+Math.Sqrt(n))*math.machineepsilon;
            hess.wolfeeps = 0.001;
            hess.maxhess = 1.0E8;
            hess.sumsy = math.sqr(math.machineepsilon);
            hess.sumy2 = hess.sumsy*hess.gammasml;
            hess.sums2 = 0;
            hess.updatestatus = 0;
            apserv.rvectorsetlengthatleast(ref hess.sk, n, _params);
            apserv.rvectorsetlengthatleast(ref hess.yk, n, _params);
            ablasf.rsetallocm(n, n, 0.0, ref hess.hcurrent, _params);
            ablasf.rsetallocm(n, n, 0.0, ref hess.hincoming, _params);
            for(i=0; i<=n-1; i++)
            {
                hess.hcurrent[i,i] = 1;
                hess.hincoming[i,i] = 1;
            }
        }


        /*************************************************************************
        This function initializes approximation of a Hessian.

        Explicit low-rank representation of LBFGS is used.

        INPUT PARAMETERS:
            Hess            -   Hessian structure, initial state is ignored, but
                                previously allocated memory is reused as much as
                                possible
            N               -   dimensions count, N>0
            M               -   memory size, M>=0 (values above N will be reduced
                                to N)
            StpShort        -   short step length (INF-norm); steps shorter than that
                                are not used for Hessian updates
            MaxHess         -   maximum Hessian curvature; steps producing curvature
                                larger than that are rejected

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianinitlowrank(xbfgshessian hess,
            int n,
            int m,
            double stpshort,
            double maxhess,
            alglib.xparams _params)
        {
            alglib.ap.assert(n>0, "HessianInitLowRank: N<=0");
            alglib.ap.assert(m>=0, "HessianInitLowRank: M<0");
            m = Math.Min(m, n);
            
            //
            // Initialize generic fields
            //
            hess.htype = 3;
            hess.n = n;
            
            //
            // Initialize mode-specific fields
            //
            hess.m = m;
            hess.memlen = 0;
            hess.sigma = 1;
            if( m>0 )
            {
                ablasf.rallocm(m, n, ref hess.s, _params);
                ablasf.rallocm(m, n, ref hess.y, _params);
                ablasf.rallocm(m, m, ref hess.lowranksst, _params);
                ablasf.rallocm(m, m, ref hess.lowranksyt, _params);
            }
            resetlowrankmodel(hess, _params);
            
            //
            // Other fields
            //
            hess.resetfreq = 0;
            hess.stpshort = stpshort;
            hess.hage = 0;
            hess.gammasml = 0.000001;
            hess.reg = 100*Math.Sqrt(math.machineepsilon);
            hess.smallreg = 0.01*Math.Sqrt(math.machineepsilon);
            hess.microreg = (1000+Math.Sqrt(n))*math.machineepsilon;
            hess.sumsy = math.sqr(math.machineepsilon);
            hess.sumy2 = hess.sumsy*hess.gammasml;
            hess.sums2 = math.sqr(math.machineepsilon);
            hess.wolfeeps = 0.001;
            hess.maxhess = maxhess;
            hess.updatestatus = 0;
            ablasf.rallocv(n, ref hess.sk, _params);
            ablasf.rallocv(n, ref hess.yk, _params);
        }


        /*************************************************************************
        This function initializes approximation of a Hessian as a  limited  memory
        SR1 model.

        INPUT PARAMETERS:
            Hess            -   Hessian structure, initial state is ignored, but
                                previously allocated memory is reused as much as
                                possible
            N               -   dimensions count, N>0
            M               -   memory size, M>=0 (values above N will be reduced
                                to N)
            StpShort        -   short step length (INF-norm); steps shorter than that
                                are not used for Hessian updates
            MaxHess         -   maximum Hessian curvature; steps producing curvature
                                larger than that are rejected

          -- ALGLIB --
             Copyright 08.02.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianinitlowranksr1(xbfgshessian hess,
            int n,
            int m,
            double stpshort,
            double maxhess,
            alglib.xparams _params)
        {
            hessianinitlowranksr1x(hess, n, m, stpshort, maxhess, 1, _params);
        }


        /*************************************************************************
        This function initializes approximation of a Hessian as a  limited  memory
        SR1 model with V2 heuristic to handle indefinite model (eigenvalues are
        unifirmly shifted to make the matrix positive definite instead of truncating
        negative ones)

        INPUT PARAMETERS:
            Hess            -   Hessian structure, initial state is ignored, but
                                previously allocated memory is reused as much as
                                possible
            N               -   dimensions count, N>0
            M               -   memory size, M>=0 (values above N will be reduced
                                to N)
            StpShort        -   short step length (INF-norm); steps shorter than that
                                are not used for Hessian updates
            MaxHess         -   maximum Hessian curvature; steps producing curvature
                                larger than that are rejected

          -- ALGLIB --
             Copyright 08.02.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianinitlowranksr1v2(xbfgshessian hess,
            int n,
            int m,
            double stpshort,
            double maxhess,
            alglib.xparams _params)
        {
            hessianinitlowranksr1x(hess, n, m, stpshort, maxhess, 2, _params);
