        /*************************************************************************
        This function changes upper limit on Hessian norm. It will take effect
        upon the next model recomputation.

          -- ALGLIB --
             Copyright 23.09.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void hessiansetmaxhess(xbfgshessian hess,
            double maxhess,
            alglib.xparams _params)
        {
            hess.maxhess = maxhess;
        }


        /*************************************************************************
        This function changes variable scales. The model is invalidated.

        Variable scales must be strictly positive. Variable scales are ignored by
        models other than SR1.

          -- ALGLIB --
             Copyright 23.09.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void hessiansetscales(xbfgshessian hess,
            double[] s,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            alglib.ap.assert((hess.htype==0 || hess.htype==3) || hess.htype==4, "HessianSetScales: Hessian mode not supported");
            if( hess.htype!=4 )
            {
                return;
            }
            n = hess.n;
            for(i=0; i<=n-1; i++)
            {
                if( s[i]<=0.0 )
                {
                    alglib.ap.assert(false, "HessianSetScales: non-positive scales were supplied");
                }
            }
            ablasf.rcopyv(n, s, hess.varscale, _params);
            ablasf.rsetv(n, 1.0, hess.invscale, _params);
            ablasf.rmergedivv(n, s, hess.invscale, _params);
            resetlowrankmodel(hess, _params);
        }


        /*************************************************************************
        This function changes variable scales, trying to move them closer to user-
        supplied ones, but staying within [0.5,2.0] of the former  ones  in  order
        to avoid sharp changes in the Hessian  curvature.  Specific  interval  may
        change in future versions without notice.

        This function invalidates the model.

        Variable scales must be strictly positive. Variable scales are ignored by
        models other than SR1.

          -- ALGLIB --
             Copyright 23.09.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void hessiansetscalesinertial(xbfgshessian hess,
            double[] s,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;
            double s0 = 0;
            double s1 = 0;

            alglib.ap.assert((hess.htype==0 || hess.htype==3) || hess.htype==4, "HessianSetScales: Hessian mode not supported");
            if( hess.htype!=4 )
            {
                return;
            }
            n = hess.n;
            for(i=0; i<=n-1; i++)
            {
                s0 = hess.varscale[i];
                s1 = s[i];
                if( s1<=0.0 )
                {
                    alglib.ap.assert(false, "HessianSetScales: non-positive scales were supplied");
                }
                if( s1<0.5*s0 )
                {
                    s1 = 0.5*s0;
                }
                if( s1>2.0*s0 )
                {
                    s1 = 2.0*s0;
                }
                hess.varscale[i] = s1;
                hess.invscale[i] = 1/s1;
            }
            resetlowrankmodel(hess, _params);
        }


        /*************************************************************************
        Updates Hessian estimate, uses regularized formula which prevents  Hessian
        eigenvalues from decreasing below ~sqrt(Eps)  and  rejects  updates larger
        than ~1/sqrt(Eps) in magnitude.

        Either BFGS or LBFGS formula is used, depending on Hessian model settings.
        Exception is generated if called for SR1.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            X0, G0          -   point #0 and gradient at #0, array[N]
            X1, G1          -   point #1 and gradient at #1, array[N]
            DoTrace         -   True if we want to print trace messages

        On return sets Hess.UpdateStatus flag

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianupdate(xbfgshessian hess,
            double[] x0,
            double[] g0,
            double[] x1,
            double[] g1,
            bool dotrace,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;
            double gamma = 0;
            double sy = 0;
            double snrm2 = 0;
            double ynrm2 = 0;
            double ski = 0;
            double yki = 0;
            double yk2 = 0;
            double skyk = 0;
            double skg0 = 0;
            double skg1 = 0;
            double wolfedecay = 0;

            n = hess.n;
            
            //
            // Prepare Sk, Yk
            //
            sy = 0;
            snrm2 = 0;
            ynrm2 = 0;
            skg0 = 0;
            skg1 = 0;
            for(i=0; i<=n-1; i++)
            {
                ski = x1[i]-x0[i];
                yki = g1[i]-g0[i];
                hess.sk[i] = ski;
                hess.yk[i] = yki;
                sy = sy+ski*yki;
                snrm2 = snrm2+ski*ski;
                ynrm2 = ynrm2+yki*yki;
                skg0 = skg0+ski*g0[i];
                skg1 = skg1+ski*g1[i];
            }
            hess.updatestatus = 0;
            
            //
            // Update current and incoming Hessians
            //
            alglib.ap.assert(hess.htype==0 || hess.htype==3, "HessianUpdate: Hessian mode not supported");
            if( hess.htype==0 )
            {
                
                //
                // Update dense Hessian using BFGS formula for Bk
                //
                hessianupdatelowlevel(hess, hess.hcurrent, hess.sk, hess.yk, ref hess.updatestatus, _params);
                hessianupdatelowlevel(hess, hess.hincoming, hess.sk, hess.yk, ref i, _params);
                if( (double)(sy)>(double)(0) )
                {
                    hess.sumsy = hess.sumsy+sy;
                    hess.sumy2 = hess.sumy2+ynrm2;
                }
                hess.sums2 = hess.sums2+snrm2;
                hess.hage = hess.hage+1;
                
                //
                // Perform Hessian reset if needed
                //
                if( hess.resetfreq>0 && hess.hage>=hess.resetfreq )
                {
                    ablas.rmatrixcopy(n, n, hess.hincoming, 0, 0, hess.hcurrent, 0, 0, _params);
                    gamma = hess.sumy2/(hess.sumsy+hess.reg*hess.sumy2+hess.smallreg*hess.sums2);
                    ablasf.rsetm(n, n, 0.0, hess.hincoming, _params);
                    for(i=0; i<=n-1; i++)
                    {
                        hess.hincoming[i,i] = gamma;
                    }
                    hess.sumsy = math.sqr(math.machineepsilon);
                    hess.sumy2 = hess.sumsy*hess.gammasml;
                    hess.sums2 = 0;
                    hess.hage = 0;
                    hess.updatestatus = 3;
                }
                return;
            }
            if( hess.htype==3 )
            {
                if( dotrace )
                {
                    alglib.ap.trace(System.String.Format("> analyzing Hessian update:\n>> (Sk,G0)={0,0:E15}  (Sk,G1)={1,0:E15}  (Yk,Yk)/(Sk.Yk)={2,0:E15}\n", skg0, skg1, ynrm2/sy));
                }
                
                //
                // Decide whether update is good enough to be remembered
                //
                if( hess.m==0 )
                {
                    
                    //
                    // Zero memory was specified, update ignored
                    //
                    if( dotrace )
                    {
                        alglib.ap.trace(">> zero memory length, update rejected\n");
                    }
                    return;
                }
                if( (double)(ablasf.rmaxabsv(n, hess.sk, _params))<=(double)(hess.stpshort) )
                {
                    
                    //
                    // Sk is too small, skip update
                    //
                    if( dotrace )
                    {
                        alglib.ap.trace(">> step is too short, update rejected\n");
                    }
                    return;
                }
                
                //
                // Reject bad steps
                //
                if( (double)(ablasf.rdotv2(n, hess.yk, _params))==(double)(0) )
                {
                    
                    //
                    // The function is linear in the step direction, no update applied
                    //
                    popfrontxy(hess, _params);
                    hess.sigma = Math.Max(0.1*hess.sigma, 1.0E-4);
                    resetlowrankmodel(hess, _params);
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format(">> zero Yk (linear function?), update rejected, queue size decreased by 1, diagonal scaling sigma={0,0:E2} (decreased)\n", hess.sigma));
                    }
                    return;
                }
                wolfedecay = 1-hess.wolfeeps*Math.Min(Math.Sqrt(snrm2), 1.0);
                if( !(((double)(skg0)<(double)(0) && (double)(skg1)>(double)(wolfedecay*skg0)) || ((double)(skg1)>(double)(0) && (double)(skg0)<(double)(wolfedecay*skg1))) )
                {
                    
                    //
                    // Wolfe decay condition does not hold
                    //
                    popfrontxy(hess, _params);
                    hess.sigma = Math.Max(0.1*hess.sigma, 1.0E-4);
                    resetlowrankmodel(hess, _params);
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format(">> Wolfe decay condition does not hold, update rejected, queue size decreased by 1, diagonal scaling sigma={0,0:E2} (decreased)\n", hess.sigma));
                    }
                    return;
                }
                if( (double)(sy)>(double)(0) && (double)(ynrm2/sy)>(double)(hess.maxhess) )
                {
                    
                    //
                    // Hessian norm is too high
                    //
                    popfrontxy(hess, _params);
                    hess.sigma = Math.Max(0.1*hess.sigma, 1.0E-4);
                    resetlowrankmodel(hess, _params);
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format(">> Hessian norm is too high ({0,0:E2}), update rejected, queue size decreased by 1, diagonal scaling sigma={1,0:E2} (decreased)\n", ynrm2/sy, hess.sigma));
                    }
                    return;
                }
                
                //
                // Update historical averages
                //
                hess.sumsy = hess.sumsy+sy;
                hess.sumy2 = hess.sumy2+ynrm2;
                hess.sums2 = hess.sums2+snrm2;
                
                //
                // Apply regularization:
                // * first,  add REG*Sk to Yk in order to make model at least slightly convex (Sigma is at least REG
                // * second, add REG*Yk to Xk in order to limit model curvature (Sigma is at most 1/REG)
                //
                // Whilst specific order of these operations is not very important, we prefer to Yk+=REG*Sk be first
                // due to Sk being better guarded away from zero.
                //
                ablasf.raddv(n, hess.reg, hess.sk, hess.yk, _params);
                ablasf.raddv(n, hess.reg, hess.yk, hess.sk, _params);
                
                //
                // Update low rank Hessian data
                //
                alglib.ap.assert(hess.memlen<=hess.m, "HessianUpdate: integrity check 5763 failed");
                if( hess.memlen==hess.m )
                {
                    popfrontxy(hess, _params);
                }
                
                //
                // Append to S and Y
                //
                alglib.ap.assert(hess.memlen<hess.m, "HessianUpdate: integrity check 5764 failed");
                hess.memlen = hess.memlen+1;
                ablasf.rcopyvr(n, hess.sk, hess.s, hess.memlen-1, _params);
                ablasf.rcopyvr(n, hess.yk, hess.y, hess.memlen-1, _params);
                
                //
                // Append row/col to LowRankSST and LowRankSYT
                //
                ablasf.rallocv(hess.memlen, ref hess.buf, _params);
                ablasf.rgemv(hess.memlen, n, 1.0, hess.s, 0, hess.sk, 0.0, hess.buf, _params);
                ablasf.rcopyvr(hess.memlen, hess.buf, hess.lowranksst, hess.memlen-1, _params);
                ablasf.rcopyvc(hess.memlen, hess.buf, hess.lowranksst, hess.memlen-1, _params);
                ablasf.rgemv(hess.memlen, n, 1.0, hess.y, 0, hess.sk, 0.0, hess.buf, _params);
                ablasf.rcopyvr(hess.memlen, hess.buf, hess.lowranksyt, hess.memlen-1, _params);
                ablasf.rgemv(hess.memlen, n, 1.0, hess.s, 0, hess.yk, 0.0, hess.buf, _params);
                ablasf.rcopyvc(hess.memlen, hess.buf, hess.lowranksyt, hess.memlen-1, _params);
                
                //
                // Recompute scaling
                //
                yk2 = ablasf.rdotv2(n, hess.yk, _params);
                skyk = ablasf.rdotv(n, hess.sk, hess.yk, _params);
                hess.sigma = apserv.boundval(yk2/skyk, 0.1*hess.sigma, 10*hess.sigma, _params);
                hess.sigma = Math.Min(hess.sigma, 1/(hess.reg+math.machineepsilon));
                if( dotrace )
                {
                    alglib.ap.trace(System.String.Format(">> diagonal scaling sigma={0,0:E2}\n", hess.sigma));
                }
                
                //
                // Invalidate model
                //
                resetlowrankmodel(hess, _params);
            }
        }


        /*************************************************************************
        Updates Hessian estimate,  uses  damped  formula  which  prevents  Hessian
        eigenvalues from decreasing below ~sqrt(Eps)  and  rejects  updates larger
        than ~1/sqrt(Eps) in magnitude.

        Either BFGS, LBFGS or SR1 formula is used, depending on Hessian model
        settings. For SR1 models it simply forwards call to HessianUpdateSR1().

        INPUT PARAMETERS:
            Hess            -   Hessian state
            X0, G0          -   point #0 and gradient at #0, array[N]
            X1, G1          -   point #1 and gradient at #1, array[N]
            Strategy        -   update stabilization strategy:
                                * 0     do nothing
                                * 1     apply damped (L)BFGS, safeguarding from
                                        rapid curvature increase and decrease
                                * 2     apply damped (L)BFGS for too high curvature,
                                        ignore Y and decrease curvature conservatively
                                        for low values of S'Y
                                Ignored by SR1 update.
            TryReplaceLast  -   whether we append update or try to replace the last
                                one in a queue:
                                * if False, update is applied as usual
                                * if True, then:
                                  * if we have BFGS Hessian - applied as usual
                                  * if we have L-BFGS Hessian, we pop the last one
                                    in a memory (if have any), then add this update
            DoTrace         -   True if we want to print trace messages
            TraceLevel      -   amount of ">" symbols to append to trace messages


          -- ALGLIB --
             Copyright 28.09.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianupdatev2(xbfgshessian hess,
            double[] x0,
            double[] g0,
            double[] x1,
            double[] g1,
            int strategy,
            bool tryreplacelast,
            bool dotrace,
            int tracelevel,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;
            double gamma = 0;
            double sy = 0;
            double snrm2 = 0;
            double ynrm2 = 0;
            double ski = 0;
            double yki = 0;
            double skg0 = 0;
            double skg1 = 0;
            double shs = 0;
            double tau = 0;
            double phi = 0;
            double eps2 = 0;
            double eps3 = 0;
            double v = 0;

            if( hess.htype==4 )
            {
                hessianupdatesr1(hess, x0, g0, x1, g1, dotrace, tracelevel, _params);
                return;
            }
            n = hess.n;
            eps2 = 10*Math.Sqrt(math.machineepsilon);
            eps3 = 10*math.machineepsilon*(1+Math.Sqrt(n));
            
            //
            // Print initial trace line
            //
            if( dotrace )
            {
                apserv.traceangles(tracelevel, _params);
                alglib.ap.trace(" analyzing Hessian update\n");
            }
            
            //
            // Prepare Sk, Yk, compute some necessary quantities
            //
            sy = 0;
            snrm2 = 0;
            ynrm2 = 0;
            skg0 = 0;
            skg1 = 0;
            for(i=0; i<=n-1; i++)
            {
                ski = x1[i]-x0[i];
                yki = g1[i]-g0[i];
                hess.sk[i] = ski;
                hess.yk[i] = yki;
                sy = sy+ski*yki;
                snrm2 = snrm2+ski*ski;
                ynrm2 = ynrm2+yki*yki;
                skg0 = skg0+ski*g0[i];
                skg1 = skg1+ski*g1[i];
            }
            hess.updatestatus = 0;
            
            //
            // Skip updates with zero or short steps
            //
            if( (double)(ablasf.rmaxabsv(n, hess.sk, _params))<=(double)(hess.stpshort) )
            {
                
                //
                // Sk is too small, skip update
                //
                if( dotrace )
                {
                    apserv.traceangles(tracelevel+1, _params);
                    alglib.ap.trace(" step is too short, update rejected\n");
                }
                return;
            }
            
            //
            // Analyze existing curvature along S
            //
            hessianmv(hess, hess.sk, ref hess.hsk, _params);
            shs = ablasf.rdotv(n, hess.sk, hess.hsk, _params);
            if( (double)(shs)>(double)(eps3*snrm2) )
            {
                
                //
                // Hessian has sufficiently good curvature along Sk, can proceed with analysis of update.
                // Apply damping or other stabilization
                //
                alglib.ap.assert((strategy==0 || strategy==1) || strategy==2, "OPTSERV: integrity check 9223 failed");
                phi = 1.0;
                tau = sy/shs;
                if( strategy==1 && (double)(tau)<(double)(xbfgssigma2) )
                {
                    if( dotrace )
                    {
                        apserv.traceangles(tracelevel+1, _params);
                        alglib.ap.trace(" applying damping to correct too low (or rapidly changing) curvature\n");
                    }
                    phi = (1-xbfgssigma2)/(1-tau);
                }
                if( strategy==2 && (double)(tau)<(double)(xbfgssigma2) )
                {
                    if( dotrace )
                    {
                        apserv.traceangles(tracelevel+1, _params);
                        alglib.ap.trace(" applying conservative curvature decrease to correct too low (or rapidly changing) curvature\n");
                    }
                    ablasf.rcopyv(n, hess.hsk, hess.yk, _params);
                    ablasf.rmulv(n, xbfgssigma2, hess.yk, _params);
                    sy = xbfgssigma2*shs;
                    ynrm2 = ablasf.rdotv2(n, hess.yk, _params);
                }
                if( (strategy==1 || strategy==2) && (double)(tau)>(double)(xbfgssigma3) )
                {
                    if( dotrace )
                    {
                        apserv.traceangles(tracelevel+1, _params);
                        alglib.ap.trace(" applying damping to correct too high (or rapidly changing) curvature\n");
                    }
                    phi = (xbfgssigma3-1)/(tau-1);
                }
                if( (double)(phi)!=(double)(1) )
                {
                    ablasf.rmulv(n, phi, hess.yk, _params);
                    ablasf.raddv(n, 1-phi, hess.hsk, hess.yk, _params);
                    sy = ablasf.rdotv(n, hess.sk, hess.yk, _params);
                    ynrm2 = ablasf.rdotv2(n, hess.yk, _params);
                }
            }
            else
            {
                
                //
                // Hessian is not sufficiently good along Sk, propose conservative curvature-preserving update
                //
                if( dotrace )
                {
                    apserv.traceangles(tracelevel+1, _params);
                    alglib.ap.trace(" Hessian curvature along Sk is too low, proposing conservative corrector update\n");
                }
                ablasf.rcopymulv(n, eps2, hess.sk, hess.yk, _params);
                sy = ablasf.rdotv(n, hess.sk, hess.yk, _params);
                ynrm2 = ablasf.rdotv2(n, hess.yk, _params);
            }
            
            //
            // Do not allow a  lower bound on Hessian eigenvalues (S'Y)/(S'S) to decrease below Eps2,
            // do not allow an upper bound on Hessian eigenvalues (Y'Y)/(S'Y) to increase above 1/Eps2
            //
            if( (double)(sy)<=(double)(0) || (double)(sy/snrm2)<(double)(eps2) )
            {
                if( dotrace )
                {
                    apserv.traceangles(tracelevel+1, _params);
                    alglib.ap.trace(System.String.Format(" damped curvature is still too low (lower estimate is SY/SS={0,0:E2}), truncating to ~sqrt(epsilon)\n", sy/snrm2));
                }
                ablasf.rcopymulv(n, eps2, hess.sk, hess.yk, _params);
                sy = ablasf.rdotv(n, hess.sk, hess.yk, _params);
                ynrm2 = ablasf.rdotv2(n, hess.yk, _params);
            }
            if( (double)(sy)>(double)(0) && (double)(ynrm2/sy)>(double)(1/eps2) )
            {
                if( dotrace )
                {
                    apserv.traceangles(tracelevel+1, _params);
                    alglib.ap.trace(System.String.Format(" damped curvature is still too high (upper estimate is YY/SY={0,0:E2}), truncating to ~1/sqrt(epsilon)\n", ynrm2/sy));
                }
                v = 1/eps2/(ynrm2/sy);
                ablasf.rmulv(n, v, hess.yk, _params);
                sy = v*sy;
                ynrm2 = v*v*ynrm2;
            }
            
            //
            // Update current and incoming Hessians
            //
            alglib.ap.assert(hess.htype==0 || hess.htype==3, "HessianUpdate: Hessian mode not supported");
            if( hess.htype==0 )
            {
                
                //
                // Update dense Hessian using BFGS formula for Bk
                //
                hessianupdatelowlevel2(hess, hess.hcurrent, hess.sk, hess.yk, ref hess.updatestatus, _params);
                hessianupdatelowlevel2(hess, hess.hincoming, hess.sk, hess.yk, ref i, _params);
                if( (double)(sy)>(double)(0) )
                {
                    hess.sumsy = hess.sumsy+sy;
                    hess.sumy2 = hess.sumy2+ynrm2;
                }
                hess.sums2 = hess.sums2+snrm2;
                hess.hage = hess.hage+1;
                if( dotrace )
                {
                    apserv.traceangles(tracelevel+1, _params);
                    alglib.ap.trace(" BFGS update applied\n");
                }
                
                //
                // Perform Hessian reset if needed
                //
                if( hess.resetfreq>0 && hess.hage>=hess.resetfreq )
                {
                    ablas.rmatrixcopy(n, n, hess.hincoming, 0, 0, hess.hcurrent, 0, 0, _params);
                    gamma = hess.sumy2/(hess.sumsy+hess.reg*hess.sumy2+hess.smallreg*hess.sums2);
                    ablasf.rsetm(n, n, 0.0, hess.hincoming, _params);
                    for(i=0; i<=n-1; i++)
                    {
                        hess.hincoming[i,i] = gamma;
                    }
                    hess.sumsy = math.sqr(math.machineepsilon);
                    hess.sumy2 = hess.sumsy*hess.gammasml;
                    hess.sums2 = 0;
                    hess.hage = 0;
                    hess.updatestatus = 3;
                }
                return;
            }
            if( hess.htype==3 )
            {
                
                //
                // Decide whether update is good enough to be remembered
                //
                if( hess.m==0 )
                {
                    
                    //
                    // Zero memory was specified, update ignored
                    //
                    if( dotrace )
                    {
                        apserv.traceangles(tracelevel+1, _params);
                        alglib.ap.trace(" zero memory length, update rejected\n");
                    }
                    return;
                }
                
                //
                // Update historical averages
                //
                hess.sumsy = hess.sumsy+sy;
                hess.sumy2 = hess.sumy2+ynrm2;
                hess.sums2 = hess.sums2+snrm2;
                
                //
                // Remove items from memory, if necessary
                //
                alglib.ap.assert(hess.memlen<=hess.m, "HessianUpdate: integrity check 5763 failed");
                if( tryreplacelast )
                {
                    if( dotrace )
                    {
                        apserv.traceangles(tracelevel+1, _params);
                        alglib.ap.trace(" rewriting most recent update pair\n");
                    }
                    hessianpoplatestifpossible(hess, _params);
                }
                if( hess.memlen==hess.m )
                {
                    popfrontxy(hess, _params);
                }
                
                //
                // Append to S and Y
                //
                alglib.ap.assert(hess.memlen<hess.m, "HessianUpdate: integrity check 5764 failed");
                hess.memlen = hess.memlen+1;
                ablasf.rcopyvr(n, hess.sk, hess.s, hess.memlen-1, _params);
                ablasf.rcopyvr(n, hess.yk, hess.y, hess.memlen-1, _params);
                
                //
                // Append row/col to LowRankSST and LowRankSYT
                //
                ablasf.rallocv(hess.memlen, ref hess.buf, _params);
                ablasf.rgemv(hess.memlen, n, 1.0, hess.s, 0, hess.sk, 0.0, hess.buf, _params);
                ablasf.rcopyvr(hess.memlen, hess.buf, hess.lowranksst, hess.memlen-1, _params);
                ablasf.rcopyvc(hess.memlen, hess.buf, hess.lowranksst, hess.memlen-1, _params);
                ablasf.rgemv(hess.memlen, n, 1.0, hess.y, 0, hess.sk, 0.0, hess.buf, _params);
                ablasf.rcopyvr(hess.memlen, hess.buf, hess.lowranksyt, hess.memlen-1, _params);
                ablasf.rgemv(hess.memlen, n, 1.0, hess.s, 0, hess.yk, 0.0, hess.buf, _params);
                ablasf.rcopyvc(hess.memlen, hess.buf, hess.lowranksyt, hess.memlen-1, _params);
                
                //
                // Recompute scaling
                //
                hess.sigma = apserv.boundval(ynrm2/sy, eps2, 1/eps2, _params);
                if( dotrace )
                {
                    apserv.traceangles(tracelevel+1, _params);
                    alglib.ap.trace(System.String.Format(" LBFGS update applied, diagonal scaling sigma={0,0:E2}\n", hess.sigma));
                }
                
                //
                // Invalidate model
                //
                resetlowrankmodel(hess, _params);
            }
        }


        /*************************************************************************
        Updates Hessian estimate using SR1 formula. Fails for other model types.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            X0, G0          -   point #0 and gradient at #0, array[N]
            X1, G1          -   point #1 and gradient at #1, array[N]
            DoTrace         -   True if we want to print trace messages
            TraceLevel      -   amount of ">" symbols to append to trace messages


          -- ALGLIB --
             Copyright 08.02.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianupdatesr1(xbfgshessian hess,
            double[] x0,
            double[] g0,
            double[] x1,
            double[] g1,
            bool dotrace,
            int tracelevel,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;
            double dbgsigma = 0;
            double dbgsy = 0;
            double dbgsnrm2 = 0;

            alglib.ap.assert(hess.htype==4, "HessianUpdateSR1: only SR1 models are supported");
            n = hess.n;
            
            //
            // Print initial trace line
            //
            if( dotrace )
            {
                apserv.traceangles(tracelevel, _params);
                alglib.ap.trace(" analyzing Hessian update\n");
            }
            
            //
            // Prepare Sk, Yk, compute some necessary quantities
            //
            for(i=0; i<=n-1; i++)
            {
                hess.sk[i] = x1[i]-x0[i];
                hess.yk[i] = g1[i]-g0[i];
            }
            
            //
            // Skip updates with zero or short steps, zero memory, etc
            //
            if( hess.m==0 )
            {
                
                //
                // Zero memory was specified, update ignored
                //
                if( dotrace )
                {
                    apserv.traceangles(tracelevel+1, _params);
                    alglib.ap.trace(" zero memory length, update rejected\n");
                }
                return;
            }
            if( (double)(ablasf.rmaxabsv(n, hess.sk, _params))<=(double)(hess.stpshort) )
            {
                
                //
                // Sk is too small, skip update
                //
                if( dotrace )
                {
                    apserv.traceangles(tracelevel+1, _params);
                    alglib.ap.trace(" step is too short, update rejected, enforcing Hessian decay\n");
                }
                hessianmultiplyby(hess, 0.2, _params);
                return;
            }
            
            //
            // Prepare update
            //
            alglib.ap.assert(hess.memlen<=hess.m, "HessianUpdateSR1: integrity check 7929 failed");
            if( hess.memlen==hess.m )
            {
                popfrontxy(hess, _params);
            }
            alglib.ap.assert(hess.memlen<hess.m, "HessianUpdateSR1: integrity check 7930 failed");
            hess.memlen = hess.memlen+1;
            ablasf.rcopyvr(n, hess.sk, hess.s, hess.memlen-1, _params);
            ablasf.rcopyvr(n, hess.yk, hess.y, hess.memlen-1, _params);
            if( dotrace )
            {
                apserv.traceangles(tracelevel+1, _params);
                dbgsy = 0;
                dbgsnrm2 = 0;
                for(i=0; i<=n-1; i++)
                {
                    dbgsy = dbgsy+hess.sk[i]*hess.yk[i];
                    dbgsnrm2 = dbgsnrm2+math.sqr(hess.sk[i]/hess.varscale[i]);
                }
                dbgsigma = dbgsy/(dbgsnrm2+math.machineepsilon*math.machineepsilon);
                alglib.ap.trace(System.String.Format(" SR1 update applied, diagonal scaling sigma=SY/SS={0,0:E2} (SY={1,0:E2}, SS={2,0:E2} in scaled vars)\n", dbgsigma, dbgsy, dbgsnrm2));
            }
            resetlowrankmodel(hess, _params);
        }


        /*************************************************************************
        Removes newest update pair from the limited memory Hessian model and
        invalidates Hessian model. If Hessian does not allow to pop latest pair,
        does nothing.

          -- ALGLIB --
             Copyright 28.09.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianpoplatestifpossible(xbfgshessian hess,
            alglib.xparams _params)
        {
            alglib.ap.assert(hess.htype==0 || hess.htype==3, "HessianPopLatestIfPossible: Hessian mode is not supported");
            if( hess.htype==0 )
            {
                return;
            }
            if( hess.memlen==0 )
            {
                return;
            }
            alglib.ap.assert(hess.htype==3, "OPTSERV: integrity check 0140 failed");
            hess.memlen = hess.memlen-1;
            resetlowrankmodel(hess, _params);
        }


        /*************************************************************************
        Multiplies internally stored model (and all internally stored corrections)
        by S.

        This function works only with the following Hessian modes:
        * direct BFGS
        * low-rank LBFGS

        Any attempt to call it for other Hessian type will result in exception.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            S               -   scale factor

          -- ALGLIB --
             Copyright 05.06.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianmultiplyby(xbfgshessian hess,
            double s,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int n = 0;

            alglib.ap.assert((hess.htype==0 || hess.htype==3) || hess.htype==4, "HessianMultiplyBy: Hessian mode is not supported");
            n = hess.n;
            if( hess.htype==0 )
            {
                
                //
                // Explicit dense Hessian
                //
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        hess.hcurrent[i,j] = hess.hcurrent[i,j]*s;
                        hess.hincoming[i,j] = hess.hincoming[i,j]*s;
                    }
                }
            }
            if( hess.htype==3 )
            {
                
                //
                // Low rank model
                //
                hess.sigma = s*hess.sigma;
                for(i=0; i<=hess.memlen-1; i++)
                {
                    ablasf.rmulr(n, s, hess.y, i, _params);
                    ablasf.rmulr(hess.memlen, s, hess.lowranksyt, i, _params);
                }
                resetlowrankmodel(hess, _params);
            }
            if( hess.htype==4 )
            {
                
                //
                // Low rank model
                //
                for(i=0; i<=hess.memlen-1; i++)
                {
                    ablasf.rmulr(n, s, hess.y, i, _params);
                }
                resetlowrankmodel(hess, _params);
            }
        }


        /*************************************************************************
        Get diagonal of the Hessian.

        This function works only with the following Hessian modes:
        * direct BFGS
        * low-rank LBFGS

        Any attempt to call it for other Hessian type will result in exception.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            D               -   possibly preallocated array; resized if needed
            
        OUTPUT PARAMETERS:
            D               -   first N elements are filled with Hessian diagonal

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void hessiangetdiagonal(xbfgshessian hess,
            ref double[] d,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            alglib.ap.assert((hess.htype==0 || hess.htype==3) || hess.htype==4, "HessianGetDiagonal: Hessian mode is not supported");
            n = hess.n;
            ablasf.rallocv(n, ref d, _params);
            if( hess.htype==0 )
            {
                
                //
                // Explicit dense Hessian
                //
                for(i=0; i<=n-1; i++)
                {
                    d[i] = hess.hcurrent[i,i];
                }
            }
            if( hess.htype==3 )
            {
                
                //
                // Low-rank model
                //
                recomputelowrankmodel(hess, _params);
                recomputelowrankdiagonal(hess, _params);
                ablasf.rcopyv(n, hess.lowrankeffd, d, _params);
            }
            if( hess.htype==4 )
            {
                
                //
                // Low-rank model
                //
                recomputelowrankmodel(hess, _params);
                recomputelowrankdiagonal(hess, _params);
                ablasf.rcopyv(n, hess.sr1effd, d, _params);
            }
        }


        /*************************************************************************
        Get Hessian matrix in a dense format.

        This function works only with the following Hessian modes:
        * direct BFGS
        * low-rank LBFGS (needs k*N*N operations)

        Any attempt to call it for other Hessian type will result in exception.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            IsUpper         -   whether upper or lower triangle is needed
            H               -   possibly preallocated array; resized if needed
            
        OUTPUT PARAMETERS:
            H               -   either upper or lower NxN elements are filled
                                with Hessian

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void hessiangetmatrix(xbfgshessian hess,
            bool isupper,
            ref double[,] h,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            alglib.ap.assert((hess.htype==0 || hess.htype==3) || hess.htype==4, "HessianGetMatrix: Hessian mode is not supported");
            n = hess.n;
            ablasf.rallocm(n, n, ref h, _params);
            if( hess.htype==0 )
            {
                
                //
                // Dense direct Hessian
                //
                ablasf.rcopym(n, n, hess.hcurrent, h, _params);
            }
            if( hess.htype==3 )
            {
                
                //
                // Low-rank BFGS model
                //
                recomputelowrankmodel(hess, _params);
                ablasf.rsetm(n, n, 0.0, h, _params);
                for(i=0; i<=n-1; i++)
                {
                    h[i,i] = hess.sigma;
                }
                ablas.rmatrixgemm(n, n, hess.lowrankk, 1.0, hess.lowrankcp, 0, 0, 1, hess.lowrankcp, 0, 0, 0, 1.0, h, 0, 0, _params);
                ablas.rmatrixgemm(n, n, hess.lowrankk, -1.0, hess.lowrankcm, 0, 0, 1, hess.lowrankcm, 0, 0, 0, 1.0, h, 0, 0, _params);
            }
            if( hess.htype==4 )
            {
                
                //
                // Low-rank SR1 model
                //
                recomputelowrankmodel(hess, _params);
                ablasf.rsetm(n, n, 0.0, h, _params);
                for(i=0; i<=n-1; i++)
                {
                    h[i,i] = hess.sr1d[i];
                }
                if( hess.sr1k>0 )
                {
                    alglib.ap.assert(hess.sr1k<=hess.m, "OPTSERV: integrity check 4215 failed");
                    ablasf.rcopym(hess.sr1k, n, hess.sr1c, hess.corr2, _params);
                    for(i=0; i<=hess.sr1k-1; i++)
                    {
                        ablasf.rmulr(n, hess.sr1z[i], hess.corr2, i, _params);
                    }
                    ablas.rmatrixgemm(n, n, hess.sr1k, 1.0, hess.sr1c, 0, 0, 1, hess.corr2, 0, 0, 0, 1.0, h, 0, 0, _params);
                }
            }
        }


        /*************************************************************************
        Returns 2-norm of the Hessian (can be cheaply computed due to its low-rank
        structure, always computed during the update)

        This function works only with the following Hessian modes:
        * low-rank SR1

        Any attempt to call it for other Hessian type will result in exception.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            
        RESULT:
            2-norm of the unmodified Hessian (no positive-definiteness correction).
            The norm is computed in scaled variables, as set by HessianSetScales.
            

          -- ALGLIB --
             Copyright 28.02.2024 by Bochkanov Sergey
        *************************************************************************/
        public static double hessiangetnrm2(xbfgshessian hess,
            alglib.xparams _params)
        {
            double result = 0;

            alglib.ap.assert(hess.htype==4, "HessianGetNrm2: Hessian mode is not supported");
            result = 0;
            if( hess.htype==4 )
            {
                
                //
                // Low-rank SR1 model
                //
                recomputelowrankmodel(hess, _params);
                result = hess.sr1nrm2;
            }
            return result;
        }


        /*************************************************************************
        Returns 2-norm of the stabilized Hessian (can be cheaply computed  due  to
        its low-rank structure, always computed during the update)

        This function works only with the following Hessian modes:
        * low-rank SR1

        Any attempt to call it for other Hessian type will result in exception.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            
        RESULT:
            2-norm of the stabilized Hessian (positive-definiteness correction).
            The norm is computed in scaled variables, as set by HessianSetScales.
            

          -- ALGLIB --
             Copyright 28.02.2024 by Bochkanov Sergey
        *************************************************************************/
        public static double hessiangetnrm2stab(xbfgshessian hess,
            alglib.xparams _params)
        {
            double result = 0;

            alglib.ap.assert(hess.htype==4, "HessianGetNrm2: Hessian mode is not supported");
            result = 0;
            if( hess.htype==4 )
            {
                
                //
                // Low-rank SR1 model
                //
                recomputelowrankmodel(hess, _params);
                result = hess.sr1nrm2stab;
            }
            return result;
        }


        /*************************************************************************
        Get Hessian matrix in a low-rank format D + C'*S*C where D is  a  diagonal
        matrix, C is a low rank matrix, S is a matrix of +1 and -1.

        This function works only with the following Hessian modes:
        * low-rank LBFGS (needs k*N operations)

        Any attempt to call it for other Hessian type will result in an exception.

        IMPORTANT: thus function uses original formulas  from  'REPRESENTATIONS OF
                   QUASI-NEWTON MATRICES AND THEIR USE IN LIMITED MEMORY  METHODS'
                   which produce a positive definite D+C'*S*C.
                   However, only  the  final  result  is  positive  definite.  Any
                   partial update D+G'*U*G, where G/U are subsets of C/S,  is  NOT
                   guaranteed to be positive definite. Lack  of  these  guarantees
                   usually destabilizes interior point low rank  QP   solvers  and
                   other algorithms which rely on positive definiteness of partial
                   updates.
                   Use HessianGetLowRankStabilized() if you need robust updates.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            D               -   possibly preallocated array, reused if large enough
            CorrC           -   possibly preallocated array, reused if large enough
            CorrS           -   possibly preallocated array, reused if large enough
            
        OUTPUT PARAMETERS:
            D               -   array[N], diagonal matrix
            CorrC           -   array[CorrK,N], low rank correction
            CorrS           -   array[CorrK], signs
            CorrK           -   correction rank, CorrK>=0

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void hessiangetlowrank(xbfgshessian hess,
            ref double[] d,
            ref double[,] corrc,
            ref double[] corrs,
            ref int corrk,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int n = 0;

            corrk = 0;

            alglib.ap.assert(hess.htype==3 || hess.htype==4, "HessianGetMatrixLowRank: Hessian mode is not supported");
            n = hess.n;
            if( hess.htype==3 )
            {
                
                //
                // Low-rank model
                //
                recomputelowrankmodel(hess, _params);
                corrk = 2*hess.lowrankk;
                ablasf.rsetallocv(n, hess.sigma, ref d, _params);
                if( hess.lowrankk>0 )
                {
                    ablasf.rallocm(corrk, n, ref corrc, _params);
                    ablasf.rallocv(corrk, ref corrs, _params);
                    for(i=0; i<=hess.lowrankk-1; i++)
                    {
                        for(j=0; j<=n-1; j++)
                        {
                            corrc[2*i+0,j] = hess.lowrankcp[i,j];
                            corrc[2*i+1,j] = hess.lowrankcm[i,j];
                        }
                        corrs[2*i+0] = 1;
                        corrs[2*i+1] = -1;
                    }
                }
            }
            if( hess.htype==4 )
            {
                
                //
                // Low-rank model
                //
                recomputelowrankmodel(hess, _params);
                corrk = hess.sr1k;
                ablasf.rcopyallocv(n, hess.sr1d, ref d, _params);
                if( hess.sr1k>0 )
                {
                    ablasf.rcopyallocm(corrk, n, hess.sr1c, ref corrc, _params);
                    ablasf.rcopyallocv(corrk, hess.sr1z, ref corrs, _params);
                }
            }
        }


        /*************************************************************************
        Get LBFGS memory contents:
        * steps S
        * gradient changes Y
        * diagonal scaling Sigma

        The function guarantees that for each k we have (Sk,Yk)>0, however it does
        NOT guarantee that all steps are stored and that steps are stored  as  is.
        It may modify S and Y in order to improve conditioning, and  it  may  skip
        some update pairs if it decides to do so.

        This function works only with the following Hessian modes:
        * low-rank LBFGS

        Any attempt to call it for other Hessian type will result in an exception.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            S               -   possibly preallocated array, reused if large enough
            Y               -   possibly preallocated array, reused if large enough
            
        OUTPUT PARAMETERS:
            Sigma           -   Hessian diagonal magnitude, Sigma>0
            S               -   array[UpdCnt,N], steps stored (latest steps are
                                stored at the end)
            Y               -   array[UpdCnt,N], gradient changes
            UpdCnt          -   updates count

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void hessiangetlowrankmemory(xbfgshessian hess,
            ref double sigma,
            ref double[,] s,
            ref double[,] y,
            ref int updcnt,
            alglib.xparams _params)
        {
            int n = 0;

            sigma = 0;
            updcnt = 0;

            alglib.ap.assert(hess.htype==3, "HessianGetMatrixLowRank: Hessian mode is not supported");
            n = hess.n;
            if( hess.htype==3 )
            {
                sigma = hess.sigma;
                updcnt = hess.memlen;
                if( hess.memlen>0 )
                {
                    ablasf.rcopyallocm(hess.memlen, n, hess.s, ref s, _params);
                    ablasf.rcopyallocm(hess.memlen, n, hess.y, ref y, _params);
                }
            }
        }


        /*************************************************************************
        Get Hessian matrix in a low-rank format D + C'*S*C where D is  a  diagonal
        matrix, C is a low rank matrix, S is a matrix of +1 and -1.

        This is a stabilized version of a low rank representation which guarantees
        that both complete update C'*S*C of D and any partial update are  positive
        definite. It is more expensive  than  HessianGetLowRank()  because  a  KxK
        symmetric eigenproblem has to be solved in order to compute robust update.

        Unlike non-stabilized version, this function produces  C  with  orthogonal
        rows (rows are mutually orthogonal, although not normalized and  can  even
        be zero).

        This function works only with the following Hessian modes:
        * low-rank LBFGS
        * low-rank SR1, in which case it returns a positive definite approximation

        Any attempt to call it for other Hessian type will result in an exception.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            D               -   possibly preallocated array, reused if large enough
            CorrC           -   possibly preallocated array, reused if large enough
            CorrS           -   possibly preallocated array, reused if large enough
            
        OUTPUT PARAMETERS:
            D               -   array[N], diagonal matrix
            CorrC           -   array[CorrK,N], low rank correction
            CorrS           -   array[CorrK], signs
            CorrK           -   correction rank, CorrK>=0

          -- ALGLIB --
             Copyright 10.02.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void hessiangetlowrankstabilized(xbfgshessian hess,
            ref double[] d,
            ref double[,] corrc,
            ref double[] corrs,
            ref int corrk,
            alglib.xparams _params)
        {
            corrk = 0;

            alglib.ap.assert(hess.htype==3 || hess.htype==4, "HessianGetMatrixLowRankStabilized: Hessian mode is not supported");
            if( hess.htype==3 )
            {
                hessiangetlowrankstabilizedlbfgs(hess, ref d, ref corrc, ref corrs, ref corrk, _params);
            }
            if( hess.htype==4 )
            {
                hessiangetlowrankstabilizedsr1(hess, ref d, ref corrc, ref corrs, ref corrk, _params);
            }
        }


        /*************************************************************************
        Low rank stabilized LBFGS model

          -- ALGLIB --
             Copyright 06.06.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void hessiangetlowrankstabilizedlbfgs(xbfgshessian hess,
            ref double[] d,
            ref double[,] corrc,
            ref double[] corrs,
            ref int corrk,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            corrk = 0;

            alglib.ap.assert(hess.htype==3, "HessianGetMatrixLowRankStabilized: Hessian mode is not supported");
            n = hess.n;
            
            //
            // Get non-modified low rank representation D+C'*S*C
            //
            hessiangetlowrank(hess, ref d, ref hess.tmpunstablec, ref hess.tmpunstables, ref corrk, _params);
            if( corrk==0 )
            {
                return;
            }
            
            //
            // Handle low-dimensional case where K>N. We handle it by
            // forming C'*S*C explicitly and by performing its EVD
            // decomposition.
            //
            // As a result, CorrK is decreased down to N.
            //
            // A degenerate case which does not need much sophistication.
            //
            if( corrk>n )
            {
                ablasf.rallocm(corrk, n, ref hess.tmpsl, _params);
                ablasf.rallocm(corrk, n, ref hess.tmpl, _params);
                for(i=0; i<=corrk-1; i++)
                {
                    ablasf.rcopyrr(n, hess.tmpunstablec, i, hess.tmpl, i, _params);
                    ablasf.rcopyrr(n, hess.tmpunstablec, i, hess.tmpsl, i, _params);
                    ablasf.rmulr(n, hess.tmpunstables[i], hess.tmpsl, i, _params);
                }
                ablasf.rallocm(n, n, ref hess.tmpw, _params);
                ablas.rmatrixgemm(n, n, corrk, 1.0, hess.tmpl, 0, 0, 1, hess.tmpsl, 0, 0, 0, 0.0, hess.tmpw, 0, 0, _params);
                if( !evd.smatrixevd(hess.tmpw, n, 1, false, ref hess.tmpe, ref hess.tmpq, _params) )
                {
                    alglib.ap.assert(false, "HessianGetLowRankStabilizedLBFGS: eigensolver failure");
                }
                corrk = n;
                ablasf.rallocm(n, n, ref corrc, _params);
                ablas.rmatrixtranspose(n, n, hess.tmpq, 0, 0, corrc, 0, 0, _params);
                for(i=0; i<=n-1; i++)
                {
                    ablasf.rmulr(n, Math.Sqrt(Math.Abs(hess.tmpe[i])), corrc, i, _params);
                }
                ablasf.rallocv(n, ref corrs, _params);
                for(i=0; i<=n-1; i++)
                {
                    corrs[i] = apserv.rcase2((double)(hess.tmpe[i])>=(double)(0), 1, -1, _params);
                }
                return;
            }
            
            //
            // A non-degenerate case with CorrK<=N.
            //
            // Compute LQ decomposition of C, use it to transform C'*S*C to
            // U'*W*U with orthogonal U being a factor from LQ decomposition
            // and W being a KxK matrix equal to L'*S*L
            // 
            //
            ortfac.rmatrixlq(hess.tmpunstablec, corrk, n, ref hess.tmptau, _params);
            ortfac.rmatrixlqunpackq(hess.tmpunstablec, corrk, n, hess.tmptau, corrk, ref hess.tmpu, _params);
            ablasf.rsetallocm(corrk, corrk, 0.0, ref hess.tmpsl, _params);
            ablasf.rsetallocm(corrk, corrk, 0.0, ref hess.tmpl, _params);
            for(i=0; i<=corrk-1; i++)
            {
                ablasf.rcopyrr(i+1, hess.tmpunstablec, i, hess.tmpl, i, _params);
                ablasf.rcopyrr(i+1, hess.tmpunstablec, i, hess.tmpsl, i, _params);
                ablasf.rmulr(i+1, hess.tmpunstables[i], hess.tmpsl, i, _params);
            }
            ablasf.rallocm(corrk, corrk, ref hess.tmpw, _params);
            ablas.rmatrixgemm(corrk, corrk, corrk, 1.0, hess.tmpl, 0, 0, 1, hess.tmpsl, 0, 0, 0, 0.0, hess.tmpw, 0, 0, _params);
            
            //
            // Now we have C'*S*C = U'*W*U, with S being diagonal and W being a general matrix.
            // Another different is that C is non-orthogonal whilst U is orthogonal.
            //
            // Use EVD to obtain orthogonal decomposition W=Q*E*Q' with orthogonal Q and diagonal E.
            //
            if( !evd.smatrixevd(hess.tmpw, corrk, 1, false, ref hess.tmpe, ref hess.tmpq, _params) )
            {
                alglib.ap.assert(false, "HessianGetLowRankStabilizedLBFGS: eigensolver failure");
            }
            
            //
            // Finally, output robust representation:
            // * C = sqrt(abs(E))*Q'*U
            // * S = E/abs(E)
            //
            ablasf.rallocm(corrk, n, ref corrc, _params);
            ablas.rmatrixgemm(corrk, n, corrk, 1.0, hess.tmpq, 0, 0, 1, hess.tmpu, 0, 0, 0, 0.0, corrc, 0, 0, _params);
            for(i=0; i<=corrk-1; i++)
            {
                ablasf.rmulr(n, Math.Sqrt(Math.Abs(hess.tmpe[i])), corrc, i, _params);
            }
            ablasf.rallocv(corrk, ref corrs, _params);
            for(i=0; i<=corrk-1; i++)
            {
                corrs[i] = apserv.rcase2((double)(hess.tmpe[i])>=(double)(0), 1, -1, _params);
            }
        }


        /*************************************************************************
        Stabilized low rank model for SR1 update.

          -- ALGLIB --
             Copyright 10.02.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void hessiangetlowrankstabilizedsr1(xbfgshessian hess,
            ref double[] d,
            ref double[,] corrc,
            ref double[] corrs,
            ref int corrk,
            alglib.xparams _params)
        {
            int n = 0;

            corrk = 0;

            alglib.ap.assert(hess.htype==4, "HessianGetMatrixLowRankStabilizedSR1: Hessian mode is not supported");
            n = hess.n;
            recomputelowrankmodel(hess, _params);
            ablasf.rcopyallocv(n, hess.sr1stabd, ref d, _params);
            ablasf.rcopyallocm(hess.sr1k, n, hess.sr1stabc, ref corrc, _params);
            ablasf.rcopyallocv(hess.sr1k, hess.sr1stabz, ref corrs, _params);
            corrk = hess.sr1k;
        }


        /*************************************************************************
        Returns maximum rank of the models returned by the HessianGetLowRank()
        function.

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        public static int hessiangetmaxrank(xbfgshessian hess,
            alglib.xparams _params)
        {
            int result = 0;

            alglib.ap.assert(hess.htype==3 || hess.htype==4, "HessianGetMaxRank: Hessian mode is not supported");
            result = 0;
            if( hess.htype==3 )
            {
                result = 2*hess.m;
            }
            if( hess.htype==4 )
            {
                result = hess.m;
            }
            return result;
        }


        /*************************************************************************
        Computes direct product H*x (here H is a Hessian matrix, not its inverse).
        Either BFGS or LBFGS formula is used, depending on Hessian model settings.

        NOTE: this function modifies internal state of Hess,  it  uses  temporary
              arrays allocated in Hess. Thus, it is not thread-safe.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            X               -   array[N]

        OUTPUT PARAMETERS:
            HX              -   array[N], H*x

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianmv(xbfgshessian hess,
            double[] x,
            ref double[] hx,
            alglib.xparams _params)
        {
            int n = 0;

            alglib.ap.assert((hess.htype==0 || hess.htype==3) || hess.htype==4, "HessianMV: Hessian mode is not supported");
            n = hess.n;
            ablasf.rallocv(n, ref hx, _params);
            if( hess.htype==0 )
            {
                
                //
                // Dense direct Hessian
                //
                ablasf.rgemv(n, n, 1.0, hess.hcurrent, 0, x, 0.0, hx, _params);
            }
            if( hess.htype==3 )
            {
                
                //
                // Low-rank model
                //
                recomputelowrankmodel(hess, _params);
                ablasf.rcopymulv(n, hess.sigma, x, hx, _params);
                if( hess.lowrankk>0 )
                {
                    ablasf.rallocv(hess.lowrankk, ref hess.buf, _params);
                    ablasf.rgemv(hess.lowrankk, n, 1.0, hess.lowrankcp, 0, x, 0.0, hess.buf, _params);
                    ablasf.rgemv(n, hess.lowrankk, 1.0, hess.lowrankcp, 1, hess.buf, 1.0, hx, _params);
                    ablasf.rgemv(hess.lowrankk, n, 1.0, hess.lowrankcm, 0, x, 0.0, hess.buf, _params);
                    ablasf.rgemv(n, hess.lowrankk, -1.0, hess.lowrankcm, 1, hess.buf, 1.0, hx, _params);
                }
            }
            if( hess.htype==4 )
            {
                
                //
                // Low-rank model
                //
                recomputelowrankmodel(hess, _params);
                ablasf.rcopyv(n, x, hx, _params);
                ablasf.rmergemulv(n, hess.sr1d, hx, _params);
                if( hess.sr1k>0 )
                {
                    ablasf.rallocv(hess.sr1k, ref hess.buf, _params);
                    ablasf.rgemv(hess.sr1k, n, 1.0, hess.sr1c, 0, x, 0.0, hess.buf, _params);
                    ablasf.rmergemulv(hess.sr1k, hess.sr1z, hess.buf, _params);
                    ablasf.rgemv(n, hess.sr1k, 1.0, hess.sr1c, 1, hess.buf, 1.0, hx, _params);
                }
            }
        }


        /*************************************************************************
        Computes direct product x'*H*x (here H is a Hessian matrix, not its inverse).
        Either BFGS or LBFGS formula is used, depending on Hessian model settings.

        NOTE: this function modifies internal state of Hess,  it  uses  temporary
              arrays allocated in Hess. Thus, it is not thread-safe.

        NOTE: for low-rank models this function is much more precise than computing
              H*x and then computing dot product with x.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            X               -   array[N]

        RESULT:
            x'*H*x

          -- ALGLIB --
             Copyright 14.03.2023 by Bochkanov Sergey
        *************************************************************************/
        public static double hessianvmv(xbfgshessian hess,
            double[] x,
            alglib.xparams _params)
        {
            double result = 0;
            int n = 0;
            int i = 0;

            alglib.ap.assert((hess.htype==0 || hess.htype==3) || hess.htype==4, "HessianVMV: Hessian mode is not supported");
            result = 0;
            n = hess.n;
            if( hess.htype==0 )
            {
                
                //
                // Dense direct Hessian
                //
                hessianmv(hess, x, ref hess.bufvmv, _params);
                result = ablasf.rdotv(n, x, hess.bufvmv, _params);
                return result;
            }
            if( hess.htype==3 )
            {
                
                //
                // Low-rank model
                //
                recomputelowrankmodel(hess, _params);
                result = hess.sigma*ablasf.rdotv2(n, x, _params);
                if( hess.lowrankk>0 )
                {
                    ablasf.rallocv(hess.lowrankk, ref hess.bufvmv, _params);
                    ablasf.rgemv(hess.lowrankk, n, 1.0, hess.lowrankcp, 0, x, 0.0, hess.bufvmv, _params);
                    result = result+ablasf.rdotv2(hess.lowrankk, hess.bufvmv, _params);
                    ablasf.rgemv(hess.lowrankk, n, 1.0, hess.lowrankcm, 0, x, 0.0, hess.bufvmv, _params);
                    result = result-ablasf.rdotv2(hess.lowrankk, hess.bufvmv, _params);
                }
                return result;
            }
            if( hess.htype==4 )
            {
                
                //
                // Low-rank model
                //
                recomputelowrankmodel(hess, _params);
                result = 0;
                for(i=0; i<=n-1; i++)
                {
                    result = result+hess.sr1d[i]*(x[i]*x[i]);
                }
                if( hess.sr1k>0 )
                {
                    ablasf.rallocv(hess.sr1k, ref hess.bufvmv, _params);
                    ablasf.rgemv(hess.sr1k, n, 1.0, hess.sr1c, 0, x, 0.0, hess.bufvmv, _params);
                    for(i=0; i<=hess.sr1k-1; i++)
                    {
                        result = result+hess.sr1z[i]*(hess.bufvmv[i]*hess.bufvmv[i]);
                    }
                }
                return result;
            }
            return result;
        }


        /*************************************************************************
        Computes direct product x'*H*x (here H is a Hessian matrix, not its inverse)
        along with direct product H*x.

        Either BFGS or LBFGS formula is used, depending on Hessian model settings.

        NOTE: this function modifies internal state of Hess,  it  uses  temporary
              arrays allocated in Hess. Thus, it is not thread-safe.

        NOTE: for low-rank models this function computes more precise x'*H*x than
              H*x multiplied by x.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            X               -   array[N]

        OUTPUT PARAMETERS:
            HX              -   array[N], H*x
            XHX             -   x'*H*x

          -- ALGLIB --
             Copyright 14.03.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void hessianxmv(xbfgshessian hess,
            double[] x,
            ref double[] hx,
            ref double xhx,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;

            xhx = 0;

            alglib.ap.assert((hess.htype==0 || hess.htype==3) || hess.htype==4, "HessianXMV: Hessian mode is not supported");
            n = hess.n;
            ablasf.rallocv(n, ref hx, _params);
            xhx = 0;
            if( hess.htype==0 )
            {
                
                //
                // Dense direct Hessian
                //
                ablasf.rgemv(n, n, 1.0, hess.hcurrent, 0, x, 0.0, hx, _params);
                xhx = ablasf.rdotv(n, x, hx, _params);
                return;
            }
            if( hess.htype==3 )
            {
                
                //
                // Low-rank model
                //
                recomputelowrankmodel(hess, _params);
                ablasf.rcopymulv(n, hess.sigma, x, hx, _params);
                xhx = hess.sigma*ablasf.rdotv2(n, x, _params);
                if( hess.lowrankk>0 )
                {
                    ablasf.rallocv(hess.lowrankk, ref hess.buf, _params);
                    ablasf.rgemv(hess.lowrankk, n, 1.0, hess.lowrankcp, 0, x, 0.0, hess.buf, _params);
                    ablasf.rgemv(n, hess.lowrankk, 1.0, hess.lowrankcp, 1, hess.buf, 1.0, hx, _params);
                    xhx = xhx+ablasf.rdotv2(hess.lowrankk, hess.buf, _params);
                    ablasf.rgemv(hess.lowrankk, n, 1.0, hess.lowrankcm, 0, x, 0.0, hess.buf, _params);
                    ablasf.rgemv(n, hess.lowrankk, -1.0, hess.lowrankcm, 1, hess.buf, 1.0, hx, _params);
                    xhx = xhx-ablasf.rdotv2(hess.lowrankk, hess.buf, _params);
                }
                return;
            }
            if( hess.htype==4 )
            {
                
                //
                // Low-rank model
                //
                recomputelowrankmodel(hess, _params);
                ablasf.rcopyv(n, x, hx, _params);
                ablasf.rmergemulv(n, hess.sr1d, hx, _params);
                xhx = ablasf.rdotv(n, x, hx, _params);
                if( hess.sr1k>0 )
                {
                    ablasf.rallocv(hess.sr1k, ref hess.buf, _params);
                    ablasf.rgemv(hess.sr1k, n, 1.0, hess.sr1c, 0, x, 0.0, hess.buf, _params);
                    for(i=0; i<=hess.sr1k-1; i++)
                    {
                        xhx = xhx+hess.sr1z[i]*(hess.buf[i]*hess.buf[i]);
                        hess.buf[i] = hess.sr1z[i]*hess.buf[i];
                    }
                    ablasf.rgemv(n, hess.sr1k, 1.0, hess.sr1c, 1, hess.buf, 1.0, hx, _params);
                }
                return;
            }
        }


        /*************************************************************************
        Creates random multiobjective test problem with no known answers

        INPUT PARAMETERS:
            N               -   vars cnt
            M               -   targets cnt
            NEquality       -   desired count of equality constraints of all kinds
                                (box, linear, nonlinear)
            NInequality     -   desired count of non-box inequality constraints
            TaskKind        -   task type:
                                * 0 = convex quartic
                                * 1 = convex quadratic
                                * 2 = convex low rank quadratic
                                * 3 = linear
                                * 4 = constant
            NLQuadratic     -   scale of the quadratic term of nonlinear constraints
            NLQuartic       -   scale of the quadratic term of nonlinear constraints

        NOTE: this function does NOT set Lagrange multipliers because it does not
              know them.

          -- ALGLIB --
             Copyright 04.03.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void motfcreaterandomunknown(int n,
            int m,
            int nequality,
            int ninequality,
            int taskkind,
            double nlquadratic,
            double nlquartic,
            hqrnd.hqrndstate rs,
            multiobjectivetestfunction problem,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            int rk = 0;
            double[,] q = new double[0,0];
            double[] grad = new double[0];
            double[] x = new double[0];
            double[] ax = new double[0];
            double[] c = new double[0];
            bool issemidefinite = new bool();
            bool haslinearterm = new bool();
            bool hasnonlinearterms = new bool();
            bool hasquadraticterm = new bool();
            bool hasquarticterm = new bool();
            int ngenerated = 0;
            int cidx = 0;
            int ctype = 0;
            double v = 0;
            double vmul = 0;
            double[] xtrial = new double[0];
            int passcount = 0;
            int nboxinequality = 0;
            int nlinearinequality = 0;
            int nnonlinearinequality = 0;

            haslinearterm = false;
            hasnonlinearterms = false;
            hasquadraticterm = false;
            hasquarticterm = false;
            issemidefinite = false;
            apserv.touchboolean(ref haslinearterm, _params);
            apserv.touchboolean(ref hasnonlinearterms, _params);
            apserv.touchboolean(ref hasquadraticterm, _params);
            apserv.touchboolean(ref hasquarticterm, _params);
            apserv.touchboolean(ref issemidefinite, _params);
            
            //
            // Generate random test functions
            //
            problem.isrotated = false;
            problem.problemtype = 0;
            problem.n = n;
            problem.m = m;
            ablasf.rsetallocv(m, 0.0, ref problem.tgtc, _params);
            ablasf.rsetallocm(m, n, 0.0, ref problem.tgtb, _params);
            ablasf.rsetallocm(m*n, n, 0.0, ref problem.tgta, _params);
            ablasf.rsetallocm(m, n, 0.0, ref problem.tgtd, _params);
            alglib.ap.assert(taskkind>=0 && taskkind<=4, "MOTFCreate: incorrect TaskKind");
            if( taskkind==0 )
            {
                
                //
                // Quartic term
                //
                for(i=0; i<=m-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        problem.tgtd[i,j] = Math.Pow(2, 0.33*hqrnd.hqrndnormal(rs, _params));
                    }
                }
                hasnonlinearterms = true;
                hasquarticterm = true;
            }
            if( taskkind<=2 )
            {
                
                //
                // Quadratic term
                //
                if( taskkind!=2 )
                {
                    
                    //
                    // well conditioned matrix
                    //
                    for(k=0; k<=m-1; k++)
                    {
                        matgen.spdmatrixrndcond(n, 100.0, ref q, _params);
                        ablas.rmatrixcopy(n, n, q, 0, 0, problem.tgta, k*n, 0, _params);
                    }
                }
                else
                {
                    
                    //
                    // Low rank matrix
                    //
                    rk = Math.Min(n, 1+hqrnd.hqrnduniformi(rs, 5, _params));
                    for(k=0; k<=m-1; k++)
                    {
                        hqrnd.hqrndnormalm(rs, rk, n, ref q, _params);
                        ablas.rmatrixgemm(n, n, rk, 1.0, q, 0, 0, 1, q, 0, 0, 0, 0.0, problem.tgta, k*n, 0, _params);
                    }
                }
                hasquadraticterm = true;
                hasnonlinearterms = true;
            }
            if( taskkind<=3 )
            {
                
                //
                // Linear term
                //
                hqrnd.hqrndnormalm(rs, m, n, ref problem.tgtb, _params);
                haslinearterm = true;
            }
            if( taskkind<=4 )
            {
                
                //
                // Constant term
                //
                hqrnd.hqrndnormalv(rs, m, ref problem.tgtc, _params);
            }
            issemidefinite = taskkind>=2;
            
            //
            // No initial points
            //
            problem.x0 = new double[0, 0];
            problem.k0 = 0;
            
            //
            // No known solutions
            //
            problem.xsol = new double[0, 0];
            problem.fsol = new double[0, 0];
            problem.ksol = 0;
            
            //
            // No Lagrange multipliers
            //
            problem.lagmultbc = new double[0];
            problem.lagmultlc = new double[0];
            problem.lagmultnlc = new double[0];
            
            //
            // Generate random trial point which will be strictly feasible
            //
            hqrnd.hqrndnormalv(rs, n, ref xtrial, _params);
            
            //
            //
            // Generate empty set of constraints
            //
            ablasf.rsetallocv(n, Double.NegativeInfinity, ref problem.bndl, _params);
            ablasf.rsetallocv(n, Double.PositiveInfinity, ref problem.bndu, _params);
            problem.nlinear = 0;
            problem.nnonlinear = 0;
            
            //
            // Randomly generate equality constraints using trial point
            //
            ngenerated = 0;
            passcount = 0;
            while( ngenerated<nequality && passcount<2*n )
            {
                passcount = passcount+1;
                ctype = hqrnd.hqrnduniformi(rs, 3, _params);
                
                //
                // Try adding a box constraint
                //
                if( ctype==0 )
                {
                    
                    //
                    // Try to find a box constraint that is not defined yet
                    //
                    i = hqrnd.hqrnduniformi(rs, n, _params);
                    if( Double.IsNegativeInfinity(problem.bndl[i]) && Double.IsPositiveInfinity(problem.bndu[i]) )
                    {
                        
                        //
                        // Use this box constraint.
                        // Fix a bound corresponding to the Lagrange multiplier direction,
                        // with probability 15% fix other bound too (when it is free).
                        //
                        problem.bndl[i] = xtrial[i];
                        problem.bndu[i] = xtrial[i];
                        ngenerated = ngenerated+1;
                    }
                }
                
                //
                // Add a linear equality constraint.
                //
                if( ctype==1 )
                {
                    hqrnd.hqrndnormalv(rs, n, ref c, _params);
                    v = ablasf.rdotv(n, c, xtrial, _params);
                    apserv.rmatrixgrowrowsto(ref problem.densea, problem.nlinear+1, n, _params);
                    ablasf.rgrowv(problem.nlinear+1, ref problem.al, _params);
                    ablasf.rgrowv(problem.nlinear+1, ref problem.au, _params);
                    ablasf.rcopyvr(n, c, problem.densea, problem.nlinear, _params);
                    problem.al[problem.nlinear] = v;
                    problem.au[problem.nlinear] = v;
                    problem.nlinear = problem.nlinear+1;
                    ngenerated = ngenerated+1;
                }
                
                //
                // Add a nonlinear equality constraint.
                //
                if( ctype==2 )
                {
                    
                    //
                    // Allocate place
                    //
                    ablasf.rgrowv(problem.nnonlinear+1, ref problem.nlc, _params);
                    apserv.rmatrixgrowrowsto(ref problem.nlb, problem.nnonlinear+1, n, _params);
                    apserv.rmatrixgrowrowsto(ref problem.nla, (problem.nnonlinear+1)*n, n, _params);
                    apserv.rmatrixgrowrowsto(ref problem.nld, problem.nnonlinear+1, n, _params);
                    ablasf.rgrowv(problem.nnonlinear+1, ref problem.hl, _params);
                    ablasf.rgrowv(problem.nnonlinear+1, ref problem.hu, _params);
                    
                    //
                    // Generate and compute nonlinear constraint
                    //
                    v = 0;
                    problem.nlc[problem.nnonlinear] = hqrnd.hqrndnormal(rs, _params);
                    v = v+problem.nlc[problem.nnonlinear];
                    hqrnd.hqrndnormalv(rs, n, ref c, _params);
                    ablasf.rcopyvr(n, c, problem.nlb, problem.nnonlinear, _params);
                    v = v+ablasf.rdotv(n, c, xtrial, _params);
                    matgen.spdmatrixrndcond(n, 10.0, ref q, _params);
                    vmul = nlquadratic*Math.Abs(hqrnd.hqrndnormal(rs, _params));
                    for(i=0; i<=n-1; i++)
                    {
                        ablasf.rmulr(n, vmul, q, i, _params);
                    }
                    ablas.rmatrixcopy(n, n, q, 0, 0, problem.nla, problem.nnonlinear*n, 0, _params);
                    for(i=0; i<=n-1; i++)
                    {
                        for(j=0; j<=n-1; j++)
                        {
                            v = v+0.5*xtrial[i]*q[i,j]*xtrial[j];
                        }
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        problem.nld[problem.nnonlinear,i] = nlquartic*Math.Pow(2, 0.33*hqrnd.hqrndnormal(rs, _params));
                        v = v+problem.nld[problem.nnonlinear,i]*Math.Pow(xtrial[i], 4);
                    }
                    problem.hl[problem.nnonlinear] = v;
                    problem.hu[problem.nnonlinear] = v;
                    problem.nnonlinear = problem.nnonlinear+1;
                    ngenerated = ngenerated+1;
                }
            }
            
            //
            // Decide on desired count of inequality constraints of all types (for box constraints - only approximate count)
            //
            nboxinequality = hqrnd.hqrnduniformi(rs, ninequality+1, _params);
            nlinearinequality = hqrnd.hqrnduniformi(rs, ninequality-nboxinequality+1, _params);
            nnonlinearinequality = ninequality-nboxinequality-nlinearinequality;
            
            //
            // Randomly generate box/linear/nonlinear inequality constraints inactive at the trial point
            //
            for(k=0; k<=nboxinequality-1; k++)
            {
                i = hqrnd.hqrnduniformi(rs, n, _params);
                if( Double.IsNegativeInfinity(problem.bndl[i]) && Double.IsPositiveInfinity(problem.bndu[i]) )
                {
                    ctype = hqrnd.hqrnduniformi(rs, 3, _params);
                    problem.bndl[i] = apserv.rcase2(ctype==0 || ctype==2, xtrial[i]-Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.NegativeInfinity, _params);
                    problem.bndu[i] = apserv.rcase2(ctype==1 || ctype==2, xtrial[i]+Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.PositiveInfinity, _params);
                }
            }
            for(cidx=0; cidx<=nlinearinequality-1; cidx++)
            {
                hqrnd.hqrndnormalv(rs, n, ref c, _params);
                v = ablasf.rdotv(n, c, xtrial, _params);
                ctype = hqrnd.hqrnduniformi(rs, 3, _params);
                apserv.rmatrixgrowrowsto(ref problem.densea, problem.nlinear+1, n, _params);
                ablasf.rgrowv(problem.nlinear+1, ref problem.al, _params);
                ablasf.rgrowv(problem.nlinear+1, ref problem.au, _params);
                ablasf.rcopyvr(n, c, problem.densea, problem.nlinear, _params);
                problem.al[problem.nlinear] = apserv.rcase2(ctype==0 || ctype==2, v-Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.NegativeInfinity, _params);
                problem.au[problem.nlinear] = apserv.rcase2(ctype==1 || ctype==2, v+Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.PositiveInfinity, _params);
                problem.nlinear = problem.nlinear+1;
            }
            for(cidx=0; cidx<=nnonlinearinequality-1; cidx++)
            {
                
                //
                // Allocate place
                //
                ablasf.rgrowv(problem.nnonlinear+1, ref problem.nlc, _params);
                apserv.rmatrixgrowrowsto(ref problem.nlb, problem.nnonlinear+1, n, _params);
                apserv.rmatrixgrowrowsto(ref problem.nla, (problem.nnonlinear+1)*n, n, _params);
                apserv.rmatrixgrowrowsto(ref problem.nld, problem.nnonlinear+1, n, _params);
                ablasf.rgrowv(problem.nnonlinear+1, ref problem.hl, _params);
                ablasf.rgrowv(problem.nnonlinear+1, ref problem.hu, _params);
                
                //
                // Generate and compute nonlinear constraint
                //
                v = 0;
                problem.nlc[problem.nnonlinear] = hqrnd.hqrndnormal(rs, _params);
                v = v+problem.nlc[problem.nnonlinear];
                hqrnd.hqrndnormalv(rs, n, ref c, _params);
                ablasf.rcopyvr(n, c, problem.nlb, problem.nnonlinear, _params);
                v = v+ablasf.rdotv(n, c, xtrial, _params);
                matgen.spdmatrixrndcond(n, 10.0, ref q, _params);
                vmul = nlquadratic*Math.Abs(hqrnd.hqrndnormal(rs, _params));
                for(i=0; i<=n-1; i++)
                {
                    ablasf.rmulr(n, vmul, q, i, _params);
                }
                ablas.rmatrixcopy(n, n, q, 0, 0, problem.nla, problem.nnonlinear*n, 0, _params);
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        v = v+0.5*xtrial[i]*q[i,j]*xtrial[j];
                    }
                }
                for(i=0; i<=n-1; i++)
                {
                    problem.nld[problem.nnonlinear,i] = nlquartic*Math.Pow(2, 0.33*hqrnd.hqrndnormal(rs, _params));
                    v = v+problem.nld[problem.nnonlinear,i]*Math.Pow(xtrial[i], 4);
                }
                ctype = hqrnd.hqrnduniformi(rs, 3, _params);
                problem.hl[problem.nnonlinear] = apserv.rcase2(ctype==0 || ctype==2, v-Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.NegativeInfinity, _params);
                problem.hu[problem.nnonlinear] = apserv.rcase2(ctype==1 || ctype==2, v+Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.PositiveInfinity, _params);
                problem.nnonlinear = problem.nnonlinear+1;
            }
        }


        /*************************************************************************
        Creates random multiobjective test problem with known answer and Lagrange
        multipliers

        INPUT PARAMETERS:
            N               -   vars cnt, N>=3
            NLQuadratic     -   scale of the quadratic term of nonlinear constraints
            NLQuartic       -   scale of the quartic term of nonlinear constraints

          -- ALGLIB --
             Copyright 04.03.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void motfcreate1knownanswer(int n,
            double nlquadratic,
            double nlquartic,
            hqrnd.hqrndstate rs,
            multiobjectivetestfunction problem,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            double[] grad = new double[0];
            double[] c = new double[0];
            int nactive = 0;
            int ngenerated = 0;
            int nadditionallin = 0;
            int nadditionalnl = 0;
            double lagmult = 0;
            int passcount = 0;
            int ctype = 0;
            double v = 0;
            double vmul = 0;
            double[,] q = new double[0,0];
            double padinactive = 0;

            padinactive = 10.0;
            
            //
            // Set problem metrics
            //
            problem.isrotated = false;
            problem.problemtype = 0;
            problem.n = n;
            problem.m = 1;
            
            //
            // Set empty constraints
            //
            ablasf.rsetallocv(n, Double.NegativeInfinity, ref problem.bndl, _params);
            ablasf.rsetallocv(n, Double.PositiveInfinity, ref problem.bndu, _params);
            problem.nlinear = 0;
            problem.nnonlinear = 0;
            
            //
            // No initial points
            //
            problem.x0 = new double[0, 0];
            problem.k0 = 0;
            
            //
            // Generate a priori known solution
            //
            problem.xsol = new double[1, n];
            problem.fsol = new double[1, 1];
            for(i=0; i<=n-1; i++)
            {
                problem.xsol[0,i] = hqrnd.hqrndnormal(rs, _params);
            }
            problem.fsol[0,0] = 0;
            problem.ksol = 1;
            
            //
            // Initial state of Lagrange multipliers
            //
            problem.lagmultbc = new double[n];
            ablasf.rsetv(n, 0.0, problem.lagmultbc, _params);
            problem.lagmultlc = new double[0];
            problem.lagmultnlc = new double[0];
            
            //
            // Compute gradient introduced by constraints multiplied by Lagrange coefficients
            // Randomly generate set of active (equality or inequality) constraints
            //
            alglib.ap.assert(n>=3, "MOTFCreate1KnownAnswer: N<3");
            ablasf.rsetallocv(n, 0.0, ref grad, _params);
            ngenerated = 0;
            nactive = hqrnd.hqrnduniformi(rs, n-2, _params);
            passcount = 0;
            while( ngenerated<nactive && passcount<2*n )
            {
                passcount = passcount+1;
                ctype = hqrnd.hqrnduniformi(rs, 3, _params);
                lagmult = hqrnd.hqrndnormal(rs, _params);
                lagmult = lagmult+0.05*apserv.possign(lagmult, _params);
                
                //
                // Try adding a box constraint
                //
                if( ctype==0 )
                {
                    
                    //
                    // Try to find a box constraint that is not defined yet
                    //
                    i = hqrnd.hqrnduniformi(rs, n, _params);
                    if( Double.IsNegativeInfinity(problem.bndl[i]) && Double.IsPositiveInfinity(problem.bndu[i]) )
                    {
                        
                        //
                        // Use this box constraint.
                        // Fix a bound corresponding to the Lagrange multiplier direction,
                        // with probability 15% fix other bound too (when it is free).
                        //
                        alglib.ap.assert((double)(lagmult)!=(double)(0), "OPTSERV: integrity check 0948 failed");
                        if( (double)(lagmult)<(double)(0) )
                        {
                            problem.bndl[i] = problem.xsol[0,i];
                        }
                        if( (double)(lagmult)>(double)(0) )
                        {
                            problem.bndu[i] = problem.xsol[0,i];
                        }
                        if( (double)(hqrnd.hqrnduniformr(rs, _params))<(double)(0.15) )
                        {
                            problem.bndl[i] = problem.xsol[0,i];
                            problem.bndu[i] = problem.xsol[0,i];
                        }
                        grad[i] = grad[i]+lagmult;
                        problem.lagmultbc[i] = problem.lagmultbc[i]+lagmult;
                        ngenerated = ngenerated+1;
                    }
                    continue;
                }
                
                //
                // Add a linear constraint.
                //
                if( ctype==1 )
                {
                    alglib.ap.assert((double)(lagmult)!=(double)(0), "OPTSERV: integrity check 0948 failed");
                    hqrnd.hqrndnormalv(rs, n, ref c, _params);
                    v = ablasf.rdotvr(n, c, problem.xsol, 0, _params);
                    apserv.rmatrixgrowrowsto(ref problem.densea, problem.nlinear+1, n, _params);
                    ablasf.rgrowv(problem.nlinear+1, ref problem.al, _params);
                    ablasf.rgrowv(problem.nlinear+1, ref problem.au, _params);
                    ablasf.rcopyvr(n, c, problem.densea, problem.nlinear, _params);
                    problem.al[problem.nlinear] = Double.NegativeInfinity;
                    problem.au[problem.nlinear] = Double.PositiveInfinity;
                    if( (double)(lagmult)<(double)(0) )
                    {
                        problem.al[problem.nlinear] = v;
                    }
                    if( (double)(lagmult)>(double)(0) )
                    {
                        problem.au[problem.nlinear] = v;
                    }
                    if( (double)(hqrnd.hqrnduniformr(rs, _params))<(double)(0.15) )
                    {
                        problem.al[problem.nlinear] = v;
                        problem.au[problem.nlinear] = v;
                    }
                    ablasf.raddv(n, lagmult, c, grad, _params);
                    apserv.rvectorresize(ref problem.lagmultlc, problem.nlinear+1, _params);
                    problem.lagmultlc[problem.nlinear] = lagmult;
                    problem.nlinear = problem.nlinear+1;
                    ngenerated = ngenerated+1;
                    continue;
                }
                
                //
                // Add a nonlinear constraint.
                //
                if( ctype==2 )
                {
                    alglib.ap.assert((double)(lagmult)!=(double)(0), "OPTSERV: integrity check 0948 failed");
                    
                    //
                    // Allocate place
                    //
                    ablasf.rgrowv(problem.nnonlinear+1, ref problem.nlc, _params);
                    apserv.rmatrixgrowrowsto(ref problem.nlb, problem.nnonlinear+1, n, _params);
                    apserv.rmatrixgrowrowsto(ref problem.nla, (problem.nnonlinear+1)*n, n, _params);
                    apserv.rmatrixgrowrowsto(ref problem.nld, problem.nnonlinear+1, n, _params);
                    ablasf.rgrowv(problem.nnonlinear+1, ref problem.hl, _params);
                    ablasf.rgrowv(problem.nnonlinear+1, ref problem.hu, _params);
                    
                    //
                    // Generate and compute value of the nonlinear constraint, update gradient
                    //
                    v = 0;
                    problem.nlc[problem.nnonlinear] = hqrnd.hqrndnormal(rs, _params);
                    v = v+problem.nlc[problem.nnonlinear];
                    hqrnd.hqrndnormalv(rs, n, ref c, _params);
                    ablasf.rcopyvr(n, c, problem.nlb, problem.nnonlinear, _params);
                    v = v+ablasf.rdotvr(n, c, problem.xsol, 0, _params);
                    ablasf.raddv(n, lagmult, c, grad, _params);
                    matgen.spdmatrixrndcond(n, 10.0, ref q, _params);
                    vmul = nlquadratic*Math.Abs(hqrnd.hqrndnormal(rs, _params));
                    for(i=0; i<=n-1; i++)
                    {
                        ablasf.rmulr(n, vmul, q, i, _params);
                    }
                    ablas.rmatrixcopy(n, n, q, 0, 0, problem.nla, problem.nnonlinear*n, 0, _params);
                    for(i=0; i<=n-1; i++)
                    {
                        for(j=0; j<=n-1; j++)
                        {
                            v = v+0.5*problem.xsol[0,i]*q[i,j]*problem.xsol[0,j];
                            grad[i] = grad[i]+lagmult*q[i,j]*problem.xsol[0,j];
                        }
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        problem.nld[problem.nnonlinear,i] = nlquartic*Math.Pow(2, 0.33*hqrnd.hqrndnormal(rs, _params));
                        v = v+problem.nld[problem.nnonlinear,i]*Math.Pow(problem.xsol[0,i], 4);
                        grad[i] = grad[i]+lagmult*problem.nld[problem.nnonlinear,i]*4*Math.Pow(problem.xsol[0,i], 3);
                    }
                    problem.hl[problem.nnonlinear] = Double.NegativeInfinity;
                    problem.hu[problem.nnonlinear] = Double.PositiveInfinity;
                    if( (double)(lagmult)<(double)(0) )
                    {
                        problem.hl[problem.nnonlinear] = v;
                        if( (double)(hqrnd.hqrnduniformr(rs, _params))<(double)(0.15) )
                        {
                            problem.hu[problem.nnonlinear] = v+0.1+Math.Pow(2, 0.33*hqrnd.hqrndnormal(rs, _params));
                        }
                    }
                    if( (double)(lagmult)>(double)(0) )
                    {
                        problem.hu[problem.nnonlinear] = v;
                        if( (double)(hqrnd.hqrnduniformr(rs, _params))<(double)(0.15) )
                        {
                            problem.hl[problem.nnonlinear] = v-0.1-Math.Pow(2, 0.33*hqrnd.hqrndnormal(rs, _params));
                        }
                    }
                    if( (double)(hqrnd.hqrnduniformr(rs, _params))<(double)(0.15) )
                    {
                        problem.hl[problem.nnonlinear] = v;
                        problem.hu[problem.nnonlinear] = v;
                    }
                    apserv.rvectorresize(ref problem.lagmultnlc, problem.nnonlinear+1, _params);
                    problem.lagmultnlc[problem.nnonlinear] = lagmult;
                    problem.nnonlinear = problem.nnonlinear+1;
                    ngenerated = ngenerated+1;
                    continue;
                }
            }
            
            //
            // Generate convex target which exactly balances gradient introduced by constraints
            //
            ablasf.rsetallocv(1, 0.0, ref problem.tgtc, _params);
            ablasf.rsetallocm(1, n, 0.0, ref problem.tgtb, _params);
            ablasf.rsetallocm(n, n, 0.0, ref problem.tgta, _params);
            ablasf.rsetallocm(1, n, 0.0, ref problem.tgtd, _params);
            for(i=0; i<=n-1; i++)
            {
                problem.tgtd[0,i] = 0.05*Math.Pow(2, 0.33*hqrnd.hqrndnormal(rs, _params));
                problem.fsol[0,0] = problem.fsol[0,0]+problem.tgtd[0,i]*Math.Pow(problem.xsol[0,i], 4);
                grad[i] = grad[i]+problem.tgtd[0,i]*4*Math.Pow(problem.xsol[0,i], 3);
            }
            for(i=0; i<=n-1; i++)
            {
                problem.tgtb[0,i] = -grad[i];
                problem.fsol[0,0] = problem.fsol[0,0]+problem.tgtb[0,i]*problem.xsol[0,i];
            }
            
            //
            // Randomly generate constraints which are inactive at the trial point
            //
            k = hqrnd.hqrnduniformi(rs, Math.Min(1+n/2, 5), _params);
            nadditionallin = hqrnd.hqrnduniformi(rs, k+1, _params);
            nadditionalnl = k-nadditionallin;
            for(i=0; i<=n-1; i++)
            {
                if( ((double)(hqrnd.hqrnduniformr(rs, _params))<(double)(0.5) && Double.IsNegativeInfinity(problem.bndl[i])) && Double.IsPositiveInfinity(problem.bndu[i]) )
                {
                    ctype = hqrnd.hqrnduniformi(rs, 3, _params);
                    problem.bndl[i] = apserv.rcase2(ctype==0 || ctype==2, problem.xsol[0,i]-padinactive-Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.NegativeInfinity, _params);
                    problem.bndu[i] = apserv.rcase2(ctype==1 || ctype==2, problem.xsol[0,i]+padinactive+Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.PositiveInfinity, _params);
                }
            }
            for(k=0; k<=nadditionallin-1; k++)
            {
                hqrnd.hqrndnormalv(rs, n, ref c, _params);
                v = ablasf.rdotvr(n, c, problem.xsol, 0, _params);
                apserv.rmatrixgrowrowsto(ref problem.densea, problem.nlinear+1, n, _params);
                ablasf.rgrowv(problem.nlinear+1, ref problem.al, _params);
                ablasf.rgrowv(problem.nlinear+1, ref problem.au, _params);
                ablasf.rcopyvr(n, c, problem.densea, problem.nlinear, _params);
                ctype = hqrnd.hqrnduniformi(rs, 3, _params);
                problem.al[problem.nlinear] = apserv.rcase2(ctype==0 || ctype==2, v-padinactive-Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.NegativeInfinity, _params);
                problem.au[problem.nlinear] = apserv.rcase2(ctype==1 || ctype==2, v+padinactive+Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.PositiveInfinity, _params);
                problem.nlinear = problem.nlinear+1;
            }
            for(k=0; k<=nadditionalnl-1; k++)
            {
                
                //
                // Allocate place
                //
                ablasf.rgrowv(problem.nnonlinear+1, ref problem.nlc, _params);
                apserv.rmatrixgrowrowsto(ref problem.nlb, problem.nnonlinear+1, n, _params);
                apserv.rmatrixgrowrowsto(ref problem.nla, (problem.nnonlinear+1)*n, n, _params);
                apserv.rmatrixgrowrowsto(ref problem.nld, problem.nnonlinear+1, n, _params);
                ablasf.rgrowv(problem.nnonlinear+1, ref problem.hl, _params);
                ablasf.rgrowv(problem.nnonlinear+1, ref problem.hu, _params);
                
                //
                // Generate and compute value of the nonlinear constraint
                //
                v = 0;
                problem.nlc[problem.nnonlinear] = hqrnd.hqrndnormal(rs, _params);
                v = v+problem.nlc[problem.nnonlinear];
                hqrnd.hqrndnormalv(rs, n, ref c, _params);
                ablasf.rcopyvr(n, c, problem.nlb, problem.nnonlinear, _params);
                v = v+ablasf.rdotvr(n, c, problem.xsol, 0, _params);
                matgen.spdmatrixrndcond(n, 10.0, ref q, _params);
                vmul = nlquadratic*Math.Abs(hqrnd.hqrndnormal(rs, _params));
                for(i=0; i<=n-1; i++)
                {
                    ablasf.rmulr(n, vmul, q, i, _params);
                }
                ablas.rmatrixcopy(n, n, q, 0, 0, problem.nla, problem.nnonlinear*n, 0, _params);
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        v = v+0.5*problem.xsol[0,i]*q[i,j]*problem.xsol[0,j];
                    }
                }
                for(i=0; i<=n-1; i++)
                {
                    problem.nld[problem.nnonlinear,i] = nlquartic*Math.Pow(2, 0.33*hqrnd.hqrndnormal(rs, _params));
                    v = v+problem.nld[problem.nnonlinear,i]*Math.Pow(problem.xsol[0,i], 4);
                }
                ctype = hqrnd.hqrnduniformi(rs, 3, _params);
                problem.hl[problem.nnonlinear] = apserv.rcase2(ctype==0 || ctype==2, v-padinactive-Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.NegativeInfinity, _params);
                problem.hu[problem.nnonlinear] = apserv.rcase2(ctype==1 || ctype==2, v+padinactive+Math.Pow(2, hqrnd.hqrndnormal(rs, _params)), Double.PositiveInfinity, _params);
                problem.nnonlinear = problem.nnonlinear+1;
            }
        }


