            //
            // Set problem metrics
            //
            problem.isrotated = false;
            problem.problemtype = 3;
            problem.problemsubtype = problemidx;
            problem.m = 1;
            problem.nlinear = 0;
            problem.nnonlinear = 0;
            problem.ksol = 0;
            problem.k0 = 0;
            problem.x0 = new double[0, 0];
            problem.xsol = new double[0, 0];
            problem.fsol = new double[0, 0];
            problem.lagmultbc = new double[0];
            problem.lagmultlc = new double[0];
            problem.lagmultnlc = new double[0];
            
            //
            // Handle various problems from the collection
            //
            processed = false;
            if( problemidx==0 )
            {
                
                //
                // Trigonometric 1 Function
                //
                problem.n = 10;
                ablasf.rsetallocv(problem.n, 0, ref problem.bndl, _params);
                ablasf.rsetallocv(problem.n, Math.PI, ref problem.bndu, _params);
                problem.ksol = 1;
                ablasf.rsetallocm(1, problem.n, 0.0, ref problem.xsol, _params);
                ablasf.rsetallocm(1, 1, 0.0, ref problem.fsol, _params);
                ablasf.rsetallocv(problem.n, 0.0, ref problem.lagmultbc, _params);
                processed = true;
            }
            if( problemidx==1 )
            {
                
                //
                // Xin-She Yang (Function 2)
                //
                problem.n = 2;
                ablasf.rsetallocv(problem.n, -(2*Math.PI), ref problem.bndl, _params);
                ablasf.rsetallocv(problem.n, 2*Math.PI, ref problem.bndu, _params);
                for(i=0; i<=problem.n-1; i++)
                {
                    problem.bndl[i] = problem.bndl[i]*(0.5+0.5*math.sqr(Math.Sin(117+89*i)));
                    problem.bndu[i] = problem.bndu[i]*(0.5+0.5*math.sqr(Math.Sin(653+83*i)));
                }
                problem.ksol = 1;
                ablasf.rsetallocm(1, problem.n, 0.0, ref problem.xsol, _params);
                ablasf.rsetallocm(1, 1, 0.0, ref problem.fsol, _params);
                ablasf.rsetallocv(problem.n, 0.0, ref problem.lagmultbc, _params);
                processed = true;
            }
            if( problemidx==2 )
            {
                
                //
                // Xin-She Yang (Function 4)
                //
                problem.n = 2;
                ablasf.rsetallocv(problem.n, -10, ref problem.bndl, _params);
                ablasf.rsetallocv(problem.n, 10, ref problem.bndu, _params);
                for(i=0; i<=problem.n-1; i++)
                {
                    problem.bndl[i] = problem.bndl[i]*(0.1+0.9*math.sqr(Math.Sin(117+89*i)));
                    problem.bndu[i] = problem.bndu[i]*(0.1+0.9*math.sqr(Math.Sin(653+83*i)));
                }
                problem.ksol = 1;
                ablasf.rsetallocm(1, problem.n, 0.0, ref problem.xsol, _params);
                ablasf.rsetallocm(1, 1, -1.0, ref problem.fsol, _params);
                ablasf.rsetallocv(problem.n, 0.0, ref problem.lagmultbc, _params);
                processed = true;
            }
            if( problemidx==3 )
            {
                
                //
                // Big Rosenbrock
                //
                problem.n = 5;
                ablasf.rsetallocv(problem.n, -30, ref problem.bndl, _params);
                ablasf.rsetallocv(problem.n, 30, ref problem.bndu, _params);
                for(i=0; i<=problem.n-1; i++)
                {
                    problem.bndl[i] = problem.bndl[i]*(0.5+0.5*math.sqr(Math.Sin(117+89*i)));
                    problem.bndu[i] = problem.bndu[i]*(0.5+0.5*math.sqr(Math.Sin(653+83*i)));
                }
                problem.ksol = 1;
                ablasf.rsetallocm(1, problem.n, 0.0, ref problem.xsol, _params);
                ablasf.rsetallocm(1, 1, 0.0, ref problem.fsol, _params);
                ablasf.rsetallocv(problem.n, 0.0, ref problem.lagmultbc, _params);
                processed = true;
            }
            alglib.ap.assert(processed, "MOTFCreateMetaheuristicU3: incorrect ProblemIdx");
        }


        /*************************************************************************
        Creates a nonlinear least squares test problem from the NLS1 collection.
        Usually comes with initial points.

        INPUT PARAMETERS:
