                problem.bndl[3] = 1.0;
                ablasf.rsetallocv(problem.n, 0.0, ref problem.lagmultbc, _params);
                problem.k0 = 1;
                ablasf.rallocm(1, problem.n, ref problem.x0, _params);
                problem.x0[0,0] = 10;
                problem.x0[0,1] = 10;
                problem.x0[0,2] = 10;
                problem.x0[0,3] = 10;
                processed = true;
            }
            if( problemidx==12 )
            {
                
                //
                // Hyperellipsoid function
                //
                problem.n = 8;
                problem.m = 9;
                ablasf.rsetallocv(problem.n, Double.NegativeInfinity, ref problem.bndl, _params);
                ablasf.rsetallocv(problem.n, Double.PositiveInfinity, ref problem.bndu, _params);
                ablasf.rsetallocv(problem.n, 0.0, ref problem.lagmultbc, _params);
                problem.k0 = 1;
                ablasf.rallocm(1, problem.n, ref problem.x0, _params);
                problem.x0[0,0] = -1;
                problem.x0[0,1] = 2;
                problem.x0[0,2] = -3;
                problem.x0[0,3] = 4;
                problem.x0[0,4] = -5;
                problem.x0[0,5] = 6;
                problem.x0[0,6] = -7;
                problem.x0[0,7] = 8;
                processed = true;
            }
            if( problemidx==13 )
            {
                
                //
                // Kowalik and Osborne Function
                //
                problem.n = 4;
                problem.m = 11;
