                ablasf.rsetallocv(problem.n, Double.PositiveInfinity, ref problem.bndu, _params);
                ablasf.rsetallocv(problem.n, 0.0, ref problem.lagmultbc, _params);
                problem.k0 = 1;
                ablasf.rallocm(1, problem.n, ref problem.x0, _params);
                problem.x0[0,0] = 0.25;
                problem.x0[0,1] = 0.39;
                problem.x0[0,2] = 0.415;
                problem.x0[0,3] = 0.39;
                processed = true;
            }
            if( problemidx==14 )
            {
                
                //
                // Biggs EXP6 Function
                //
                problem.n = 6;
                problem.m = 13;
                ablasf.rsetallocv(problem.n, Double.NegativeInfinity, ref problem.bndl, _params);
                ablasf.rsetallocv(problem.n, Double.PositiveInfinity, ref problem.bndu, _params);
                ablasf.rsetallocv(problem.n, 0.0, ref problem.lagmultbc, _params);
                problem.k0 = 1;
                ablasf.rallocm(1, problem.n, ref problem.x0, _params);
                problem.x0[0,0] = 1;
                problem.x0[0,1] = 2;
                problem.x0[0,2] = 1;
                problem.x0[0,3] = 1;
                problem.x0[0,4] = 1;
                problem.x0[0,5] = 1;
                processed = true;
            }
            if( problemidx==15 )
            {
                
                //
                // Highly ill-conditioned Rosenbrock
                //
                problem.n = 2;
                problem.m = 2;
                ablasf.rsetallocv(problem.n, Double.NegativeInfinity, ref problem.bndl, _params);
                ablasf.rsetallocv(problem.n, Double.PositiveInfinity, ref problem.bndu, _params);
                ablasf.rsetallocv(problem.n, 0.0, ref problem.lagmultbc, _params);
