        /*************************************************************************
        Evaluate multiobjective test problem and its nonlinear constraints.

        INPUT PARAMETERS:
            Problem             -   problem structure
            X                   -   trial point
            Fi                  -   preallocated array for M objectives and 
                                    Problem.NNonLinear constraints
            NeedFi              -   whether Fi is needed or not
            Jac                 -   preallocated Jacobian array
            NeedJac             -   whether Jac is needed or not

          -- ALGLIB --
             Copyright 04.03.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void motfeval(multiobjectivetestfunction problem,
            double[] x,
            double[] fi,
            bool needfi,
            double[,] jac,
            bool needjac,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            int n = 0;
            int m = 0;
            int dst = 0;
            double[] ax = new double[0];
            double[] y = new double[0];
            double vsum = 0;
            double vprod = 0;
            double v = 0;
            double ui = 0;
            double vi = 0;
            double wi = 0;
            double yi = 0;
            double ti = 0;
            double thetai = 0;
            double ai = 0;
            double bi = 0;
            double ci = 0;

            alglib.ap.assert(((((problem.problemtype==0 || problem.problemtype==1) || problem.problemtype==2) || problem.problemtype==3) || problem.problemtype==50) || problem.problemtype==51, "MOTFEval: unknown problem type");
            alglib.ap.assert(!needfi || alglib.ap.len(fi)>=problem.m+problem.nnonlinear, "MOTFEval: Fi is too short");
            alglib.ap.assert(!needjac || alglib.ap.rows(jac)>=problem.m+problem.nnonlinear, "MOTFEval: Jac is too short");
            alglib.ap.assert(!needjac || alglib.ap.cols(jac)>=problem.n, "MOTFEval: Jac is too short");
            n = problem.n;
            m = problem.m;
            
            //
            // Problem type #0
            //
            if( problem.problemtype==0 )
            {
                alglib.ap.assert(!problem.isrotated, "OPTSERV: integrity check 0009 failed");
                
                //
                // Evaluate objectives
                //
                for(k=0; k<=m-1; k++)
                {
                    dst = k;
                    
                    //
                    // Initial values (constant term)
                    //
                    if( needfi )
                    {
                        fi[dst] = problem.tgtc[k];
                    }
                    if( needjac )
                    {
                        ablasf.rsetr(n, 0.0, jac, dst, _params);
                    }
                    
                    //
                    // Linear term
                    //
                    if( needfi )
                    {
                        fi[dst] = fi[dst]+ablasf.rdotvr(n, x, problem.tgtb, k, _params);
                    }
                    if( needjac )
                    {
                        ablasf.raddrr(n, 1.0, problem.tgtb, k, jac, dst, _params);
                    }
                    
                    //
                    // Quadratic term
                    //
                    ablasf.rallocv(n, ref ax, _params);
                    ablas.rmatrixgemv(n, n, 1.0, problem.tgta, k*n, 0, 0, x, 0, 0.0, ax, 0, _params);
                    if( needfi )
                    {
                        fi[dst] = fi[dst]+0.5*ablasf.rdotv(n, x, ax, _params);
                    }
                    if( needjac )
                    {
                        ablasf.raddvr(n, 1.0, ax, jac, dst, _params);
                    }
                    
                    //
                    // Quartic term
                    //
                    for(i=0; i<=n-1; i++)
                    {
                        if( needfi )
                        {
                            fi[dst] = fi[dst]+problem.tgtd[k,i]*Math.Pow(x[i], 4);
                        }
                        if( needjac )
                        {
                            jac[dst,i] = jac[dst,i]+problem.tgtd[k,i]*4*Math.Pow(x[i], 3);
                        }
                    }
                }
                
                //
                // Nonlinear constraints
                //
                for(k=0; k<=problem.nnonlinear-1; k++)
                {
                    dst = m+k;
                    
                    //
                    // Initial values (constant term)
                    //
                    if( needfi )
                    {
                        fi[dst] = problem.nlc[k];
                    }
                    if( needjac )
                    {
                        ablasf.rsetr(n, 0.0, jac, dst, _params);
                    }
                    
                    //
                    // Linear term
                    //
                    if( needfi )
                    {
                        fi[dst] = fi[dst]+ablasf.rdotvr(n, x, problem.nlb, k, _params);
                    }
                    if( needjac )
                    {
                        ablasf.raddrr(n, 1.0, problem.nlb, k, jac, dst, _params);
                    }
                    
                    //
                    // Quadratic term
                    //
                    ablasf.rallocv(n, ref ax, _params);
                    ablas.rmatrixgemv(n, n, 1.0, problem.nla, k*n, 0, 0, x, 0, 0.0, ax, 0, _params);
                    if( needfi )
                    {
                        fi[dst] = fi[dst]+0.5*ablasf.rdotv(n, x, ax, _params);
                    }
                    if( needjac )
                    {
                        ablasf.raddvr(n, 1.0, ax, jac, dst, _params);
                    }
                    
                    //
                    // Quartic term
                    //
                    for(i=0; i<=n-1; i++)
                    {
                        if( needfi )
                        {
                            fi[dst] = fi[dst]+problem.nld[k,i]*Math.Pow(x[i], 4);
                        }
                        if( needjac )
                        {
                            jac[dst,i] = jac[dst,i]+problem.nld[k,i]*4*Math.Pow(x[i], 3);
                        }
                    }
                }
                
                //
                // Done
                //
                return;
            }
            
            //
            // METAHEURISTICS-U1 collection
            //
            if( problem.problemtype==1 )
            {
                alglib.ap.assert(!needjac, "OPTSERV: the METAHEURISTICS-U1 collection does not support Jacobians");
                if( !needfi )
                {
                    return;
                }
                ablasf.rallocv(problem.n, ref y, _params);
                if( problem.isrotated )
                {
                    ablasf.rgemv(problem.n, problem.n, 1.0, problem.rotq, 0, x, 0.0, y, _params);
                }
                else
                {
                    ablasf.rcopyv(problem.n, x, y, _params);
                }
                fi[0] = 0;
                if( problem.problemsubtype==0 )
                {
                    for(i=0; i<=problem.n-1; i++)
                    {
                        fi[0] = fi[0]+math.sqr(y[i]);
                    }
                    return;
                }
                if( problem.problemsubtype==1 )
                {
                    vsum = 0;
                    vprod = 1;
                    for(i=0; i<=problem.n-1; i++)
                    {
                        vsum = vsum+Math.Abs(y[i]);
                        vprod = vprod*Math.Abs(y[i]);
                    }
                    fi[0] = vsum+vprod;
                    return;
                }
                if( problem.problemsubtype==2 )
                {
                    for(i=0; i<=problem.n-1; i++)
                    {
                        v = 0;
                        for(j=0; j<=i; j++)
                        {
                            v = v+y[i];
                        }
                        fi[0] = fi[0]+math.sqr(v);
                    }
                    return;
                }
                if( problem.problemsubtype==3 )
                {
                    for(i=0; i<=problem.n-1; i++)
                    {
                        fi[0] = Math.Max(fi[0], Math.Abs(y[i]));
                    }
                    return;
                }
                if( problem.problemsubtype==4 )
                {
                    for(i=0; i<=problem.n-2; i++)
                    {
                        fi[0] = fi[0]+(100*math.sqr(y[i+1]-y[i]*y[i])+math.sqr(y[i]-1));
                    }
                    return;
                }
                if( problem.problemsubtype==5 )
                {
                    v = ablasf.rdotv2(problem.n, y, _params);
                    fi[0] = v/(v+1);
                    return;
                }
                if( problem.problemsubtype==6 )
                {
                    v = Math.Sqrt(ablasf.rdotv2(problem.n, y, _params));
                    fi[0] = v/(v+1);
