                        if( i==14 )
                        {
                            yi = 3307;
                        }
                        if( i==15 )
                        {
                            yi = 2872;
                        }
                        thetai = 45+5*(i+1);
                        if( (double)(thetai+x[2])>(double)(0) && (double)(x[1]/(thetai+x[2]))<(double)(Math.Log(math.maxrealnumber)) )
                        {
                            if( needfi )
                            {
                                fi[i] = x[0]*Math.Exp(x[1]/(thetai+x[2]))-yi;
                            }
                            if( needjac )
                            {
                                jac[i,0] = Math.Exp(x[1]/(thetai+x[2]));
                                jac[i,1] = x[0]*Math.Exp(x[1]/(thetai+x[2]))/(thetai+x[2]);
                                jac[i,2] = x[0]*Math.Exp(x[1]/(thetai+x[2]))*x[1]*-1/math.sqr(thetai+x[2]);
                            }
                        }
                        else
                        {
                            if( needfi )
                            {
                                fi[i] = Math.Sqrt(math.maxrealnumber);
                            }
                            if( needjac )
                            {
                                jac[i,0] = 0;
                                jac[i,1] = 0;
                                jac[i,2] = 0;
                            }
                        }
                    }
                    return;
                }
            }
            
            //
            // METAHEURISTICS-U3 collection
            //
            if( problem.problemtype==3 )
            {
                alglib.ap.assert(!problem.isrotated, "OPTSERV: integrity check 9609 failed");
                alglib.ap.assert(!needjac, "OPTSERV: the METAHEURISTICS-U3 collection does not support Jacobians");
                if( !needfi )
                {
                    return;
                }
                fi[0] = 0;
                if( problem.problemsubtype==0 )
                {
                    fi[0] = 0;
                    for(i=0; i<=problem.n-1; i++)
                    {
                        v = problem.n;
                        for(j=0; j<=problem.n-1; j++)
                        {
                            v = v-Math.Cos(x[j]);
                        }
                        v = v+(1+i)*(1-Math.Cos(x[i])-Math.Sin(x[i]));
                        fi[0] = fi[0]+v*v;
                    }
                    return;
                }
                if( problem.problemsubtype==1 )
                {
                    ai = 0;
                    bi = 0;
                    for(i=0; i<=problem.n-1; i++)
                    {
                        ai = ai+Math.Abs(x[i]);
                        bi = bi+Math.Sin(x[i]*x[i]);
                    }
                    fi[0] = ai*Math.Exp(-bi);
                    return;
                }
                if( problem.problemsubtype==2 )
                {
                    ai = 0;
                    bi = 0;
                    ci = 0;
                    for(i=0; i<=problem.n-1; i++)
                    {
                        ai = ai+math.sqr(Math.Sin(x[i]));
                        bi = bi+x[i]*x[i];
                        ci = ci+math.sqr(Math.Sin(Math.Sqrt(Math.Abs(x[i]))));
                    }
                    fi[0] = (ai-Math.Exp(-bi))*Math.Exp(-ci);
                    return;
                }
                if( problem.problemsubtype==3 )
                {
                    fi[0] = 0;
                    for(i=0; i<=problem.n-2; i++)
                    {
                        fi[0] = fi[0]+(100*math.sqr(x[i+1]-x[i]*x[i])+math.sqr(x[i]-1));
                    }
                    return;
                }
                
                //
                // Error
                //
                alglib.ap.assert(false, "OPTSERV: integrity check 1559 failed");
            }
            
            //
            // Error
            //
            alglib.ap.assert(false, "OPTSERV: integrity check 4407 failed");
        }


        /*************************************************************************
        Converts modern two-sided mixed sparse/dense linear constraints to an  old
        dense single-sided format.

        NOTE: this function ignores inconsistent bounds, like CL>CU, assuming that
              either they were already noticed, or will be noticed later.
        *************************************************************************/
        public static void converttwosidedlctoonesidedold(sparse.sparsematrix sparsec,
            int ksparse,
            double[,] densec,
            int kdense,
            int n,
            double[] cl,
            double[] cu,
            ref double[,] olddensec,
            ref int[] olddensect,
            ref int olddensek,
            alglib.xparams _params)
        {
            int i = 0;
            int k = 0;
            int k0 = 0;
            int k1 = 0;
            int idxout = 0;

            
            //
            // Compute required amount of single-sided constraints
            //
            olddensek = 0;
            for(i=0; i<=ksparse+kdense-1; i++)
            {
                alglib.ap.assert(math.isfinite(cl[i]) || Double.IsNegativeInfinity(cl[i]), "OPTSERV: integrity check 7117 failed");
                alglib.ap.assert(math.isfinite(cu[i]) || Double.IsPositiveInfinity(cu[i]), "OPTSERV: integrity check 7118 failed");
                if( (math.isfinite(cl[i]) && math.isfinite(cu[i])) && (double)(cl[i])==(double)(cu[i]) )
                {
                    olddensek = olddensek+1;
                    continue;
                }
                if( math.isfinite(cl[i]) )
                {
                    olddensek = olddensek+1;
                }
                if( math.isfinite(cu[i]) )
                {
                    olddensek = olddensek+1;
                }
            }
            if( olddensek==0 )
            {
                return;
            }
            
            //
            // Convert two-sided constraints into single-sided
            //
            idxout = 0;
            ablasf.rallocm(olddensek, n+1, ref olddensec, _params);
            ablasf.iallocv(olddensek, ref olddensect, _params);
            for(i=0; i<=ksparse+kdense-1; i++)
            {
                
                //
                // Ignore non-binding rows
                //
                if( !math.isfinite(cl[i]) && !math.isfinite(cu[i]) )
                {
                    continue;
                }
                
                //
                // Extract row
                //
                alglib.ap.assert(idxout<olddensek, "OPTSERV: integrity check 0324 failed");
                if( i<ksparse )
                {
                    
                    //
                    // Extract from the sparse matrix
                    //
                    ablasf.rsetr(n, 0.0, olddensec, idxout, _params);
                    k0 = sparsec.ridx[i];
                    k1 = sparsec.ridx[i+1]-1;
                    for(k=k0; k<=k1; k++)
                    {
                        olddensec[idxout,sparsec.idx[k]] = sparsec.vals[k];
                    }
                }
                else
                {
                    
                    //
                    // Copy from the dense matrix
                    //
                    ablasf.rcopyrr(n, densec, i-ksparse, olddensec, idxout, _params);
                }
                
                //
                // Two bounds are present
                //
                if( math.isfinite(cl[i]) && math.isfinite(cu[i]) )
                {
                    if( (double)(cl[i])==(double)(cu[i]) )
                    {
                        
                        //
                        // Two bounds = equality constraints, one row is output
                        //
                        olddensect[idxout] = 0;
                        olddensec[idxout,n] = cl[i];
                        idxout = idxout+1;
                        continue;
                    }
                    else
                    {
                        
                        //
                        // Two bounds = range constraint, two rows are output
                        //
                        ablasf.rcopyrr(n, olddensec, idxout, olddensec, idxout+1, _params);
                        olddensect[idxout+0] = 1;
                        olddensect[idxout+1] = -1;
                        olddensec[idxout+0,n] = cl[i];
                        olddensec[idxout+1,n] = cu[i];
                        idxout = idxout+2;
                        continue;
                    }
                }
                
                //
                // Only one bound is present
                //
                if( math.isfinite(cl[i]) )
                {
                    olddensect[idxout] = 1;
                    olddensec[idxout,n] = cl[i];
                    idxout = idxout+1;
                    continue;
                }
                if( math.isfinite(cu[i]) )
                {
                    olddensect[idxout] = -1;
                    olddensec[idxout,n] = cu[i];
                    idxout = idxout+1;
                    continue;
                }
                alglib.ap.assert(false, "OPTSERV: integrity check 7025 failed");
            }
            alglib.ap.assert(idxout==olddensek, "OPTSERV: integrity check 0214 failed");
        }


        /*************************************************************************
        Prepares conversion of the modern two-sided nonlinear constraints to an old
        single-sided zero-bounded format.

        NOTE: this function ignores inconsistent bounds, like NL>NU, assuming that
              either they were already noticed, or will be noticed later.
        *************************************************************************/
        public static void converttwosidednlctoonesidedold(double[] nl,
            double[] nu,
            int nnlc,
            ref int[] nlcidx,
            ref double[] nlcmul,
            ref double[] nlcadd,
            ref int cntnlec,
            ref int cntnlic,
            alglib.xparams _params)
        {
            int i = 0;
            int idxoutnlec = 0;
            int idxoutnlic = 0;

            
            //
            // Compute required amount of single-sided constraints
            //
            cntnlec = 0;
            cntnlic = 0;
            for(i=0; i<=nnlc-1; i++)
            {
                alglib.ap.assert(math.isfinite(nl[i]) || Double.IsNegativeInfinity(nl[i]), "OPTSERV: integrity check 0017 failed");
                alglib.ap.assert(math.isfinite(nu[i]) || Double.IsPositiveInfinity(nu[i]), "OPTSERV: integrity check 0018 failed");
                if( (math.isfinite(nl[i]) && math.isfinite(nu[i])) && (double)(nl[i])==(double)(nu[i]) )
                {
                    cntnlec = cntnlec+1;
                    continue;
                }
                if( math.isfinite(nl[i]) )
                {
                    cntnlic = cntnlic+1;
                }
                if( math.isfinite(nu[i]) )
                {
                    cntnlic = cntnlic+1;
                }
            }
            if( cntnlec+cntnlic==0 )
            {
                return;
            }
            
            //
            // Convert two-sided constraints into single-sided ones
            //
            idxoutnlec = 0;
            idxoutnlic = cntnlec;
            ablasf.iallocv(cntnlec+cntnlic, ref nlcidx, _params);
            ablasf.rallocv(cntnlec+cntnlic, ref nlcmul, _params);
            ablasf.rallocv(cntnlec+cntnlic, ref nlcadd, _params);
            for(i=0; i<=nnlc-1; i++)
            {
                
                //
                // Ignore non-binding rows
                //
                if( !math.isfinite(nl[i]) && !math.isfinite(nu[i]) )
                {
                    continue;
                }
                
                //
                //
                // Two bounds are present
                //
                if( math.isfinite(nl[i]) && math.isfinite(nu[i]) )
                {
                    if( (double)(nl[i])==(double)(nu[i]) )
                    {
                        
                        //
                        // Two bounds = equality constraints, one row is output
                        //
                        nlcidx[idxoutnlec] = i;
                        nlcmul[idxoutnlec] = 1.0;
                        nlcadd[idxoutnlec] = -nl[i];
                        idxoutnlec = idxoutnlec+1;
                        continue;
                    }
                    else
                    {
                        
                        //
                        // Two bounds = range constraint, two rows are output
                        //
                        nlcidx[idxoutnlic+0] = i;
                        nlcmul[idxoutnlic+0] = -1.0;
                        nlcadd[idxoutnlic+0] = nl[i];
                        nlcidx[idxoutnlic+1] = i;
                        nlcmul[idxoutnlic+1] = 1.0;
                        nlcadd[idxoutnlic+1] = -nu[i];
                        idxoutnlic = idxoutnlic+2;
                        continue;
                    }
                }
                
                //
                // Only one bound is present
                //
                if( math.isfinite(nl[i]) )
                {
                    nlcidx[idxoutnlic+0] = i;
                    nlcmul[idxoutnlic+0] = -1.0;
                    nlcadd[idxoutnlic+0] = nl[i];
                    idxoutnlic = idxoutnlic+1;
                    continue;
                }
                if( math.isfinite(nu[i]) )
                {
                    nlcidx[idxoutnlic+0] = i;
                    nlcmul[idxoutnlic+0] = 1.0;
                    nlcadd[idxoutnlic+0] = -nu[i];
                    idxoutnlic = idxoutnlic+1;
                    continue;
                }
                alglib.ap.assert(false, "OPTSERV: integrity check 9041 failed");
            }
            alglib.ap.assert(idxoutnlec==cntnlec, "OPTSERV: integrity check 9242 failed");
            alglib.ap.assert(idxoutnlic==cntnlec+cntnlic, "OPTSERV: integrity check 9243 failed");
        }


        /*************************************************************************
        Increases trust region growth factor until maximum growth reached.
        *************************************************************************/
        public static void trustradincreasemomentum(ref double growthfactor,
            double growthincrease,
            double maxgrowthfactor,
            alglib.xparams _params)
        {
            growthfactor = Math.Min(growthfactor*growthincrease, maxgrowthfactor);
        }


        /*************************************************************************
        Resets trust region growth factor to its default state.
        *************************************************************************/
        public static void trustradresetmomentum(ref double growthfactor,
            double mingrowthfactor,
            alglib.xparams _params)
        {
            growthfactor = mingrowthfactor;
        }


        /*************************************************************************
        Initialize V-F-J structure by allocating uninitialized fields
        *************************************************************************/
        public static void vfjallocdense(int n,
            int m,
            varsfuncjac s,
            alglib.xparams _params)
        {
            alglib.ap.assert(n>=1, "vfjAllocDense: N<1");
            alglib.ap.assert(m>=1, "vfjAllocDense: M<1");
            s.n = n;
            s.m = m;
            s.isdense = true;
            ablasf.rallocv(n, ref s.x, _params);
            ablasf.rallocv(m, ref s.fi, _params);
            ablasf.rallocm(m, n, ref s.jac, _params);
        }


        /*************************************************************************
        Initialize V-F-J structure by allocating uninitialized fields
        *************************************************************************/
        public static void vfjallocsparse(int n,
            int m,
            varsfuncjac s,
            alglib.xparams _params)
        {
            alglib.ap.assert(n>=1, "vfjAllocSparse: N<1");
            alglib.ap.assert(m>=1, "vfjAllocSparse: M<1");
            s.n = n;
            s.m = m;
            s.isdense = false;
            ablasf.rallocv(n, ref s.x, _params);
            ablasf.rallocv(m, ref s.fi, _params);
            s.sj.matrixtype = -1;
            s.sj.m = -1;
            s.sj.n = -1;
        }


        /*************************************************************************
        Initialize V-F-J structure from user-supplied data
        *************************************************************************/
        public static void vfjinitfromdense(double[] x,
            int n,
            double[] fi,
            int m,
            double[,] jac,
            varsfuncjac s,
            alglib.xparams _params)
        {
            alglib.ap.assert(n>=1, "vfjInitFromDense: N<1");
            alglib.ap.assert(m>=1, "vfjInitFromDense: M<1");
            s.n = n;
            s.m = m;
            s.isdense = true;
            ablasf.rcopyallocv(n, x, ref s.x, _params);
            ablasf.rcopyallocv(m, fi, ref s.fi, _params);
            ablasf.rcopyallocm(m, n, jac, ref s.jac, _params);
        }


        /*************************************************************************
        Initialize V-F-J structure from user-supplied data
        *************************************************************************/
        public static void vfjinitfromsparse(double[] x,
            int n,
            double[] fi,
            int m,
            sparse.sparsematrix jac,
            varsfuncjac s,
            alglib.xparams _params)
        {
            alglib.ap.assert(n>=1, "vfjInitFromSparse: N<1");
            alglib.ap.assert(m>=1, "vfjInitFromSparse: M<1");
            alglib.ap.assert(sparse.sparsegetnrows(jac, _params)==m, "vfjInitFromSparse: Jac has incorrect rows count");
            alglib.ap.assert(sparse.sparsegetncols(jac, _params)==n, "vfjInitFromSparse: Jac has incorrect cols count");
            s.n = n;
            s.m = m;
            s.isdense = false;
            ablasf.rcopyallocv(n, x, ref s.x, _params);
            ablasf.rcopyallocv(m, fi, ref s.fi, _params);
            sparse.sparsecopytocrsbuf(jac, s.sj, _params);
        }


        /*************************************************************************
        Copy V-F-J structure
        *************************************************************************/
        public static void vfjcopy(varsfuncjac src,
            varsfuncjac dst,
            alglib.xparams _params)
        {
            dst.n = src.n;
            dst.m = src.m;
            dst.isdense = src.isdense;
            ablasf.rcopyallocv(src.n, src.x, ref dst.x, _params);
            ablasf.rcopyallocv(src.m, src.fi, ref dst.fi, _params);
            if( src.isdense )
            {
                ablasf.rcopyallocm(src.m, src.n, src.jac, ref dst.jac, _params);
            }
            else
            {
                sparse.sparsecopybuf(src.sj, dst.sj, _params);
            }
        }


        /*************************************************************************
        Initialize criteria with default settings
        *************************************************************************/
        public static void critinitdefault(nlpstoppingcriteria crit,
            alglib.xparams _params)
        {
            crit.epsf = 0;
            crit.eps = 0;
            crit.maxits = 0;
        }


        /*************************************************************************
        Copy criteria
        *************************************************************************/
        public static void critcopy(nlpstoppingcriteria src,
            nlpstoppingcriteria dst,
            alglib.xparams _params)
        {
            dst.epsf = src.epsf;
            dst.eps = src.eps;
            dst.maxits = src.maxits;
        }


        /*************************************************************************
        Overwrites stopping CONDITIONS (not TOLERANCES) by values  passed  by  the
        user.

        Future versions of the structure may introduce additional conditions, these
        condifitons will be set to zero by this version-1 function.
        *************************************************************************/
        public static void critsetcondv1(nlpstoppingcriteria crit,
            double epsf,
            double eps,
            int maxits,
            alglib.xparams _params)
        {
            alglib.ap.assert(math.isfinite(epsf) && (double)(epsf)>=(double)(0), "critSetCondV1: EpsF is infinite or negative");
            alglib.ap.assert(math.isfinite(eps) && (double)(eps)>=(double)(0), "critSetCondV1: Eps is infinite or negative");
            alglib.ap.assert(maxits>=0, "critSetCondV1: MaxIts is negative");
            crit.epsf = epsf;
            crit.eps = eps;
            crit.maxits = maxits;
        }


        /*************************************************************************
        Returns the value of the EpsF stopping condition:
        * if user specified nonzero value, it will be returned
        * if user specified zero value of EpsF, but non-zero value for  any  other
          condition or tolerance, zero will be returned
        * if user specified zero value of EpsF and zero values for all  other
          conditions and tolerances, a default value will be returned
        *************************************************************************/
        public static double critgetepsf(nlpstoppingcriteria crit,
            alglib.xparams _params)
        {
            double result = 0;

            if( apserv.rmax3(crit.epsf, crit.eps, crit.maxits, _params)==0.0 )
            {
                result = 1.0E-8;
            }
            else
            {
                result = crit.epsf;
            }
            return result;
        }


        /*************************************************************************
        Returns the value of the EpsX stopping condition:
        * if user specified nonzero value, it will be returned
        * if user specified zero value of EpsX, but non-zero value for  any  other
          condition or tolerance, zero will be returned
        * if user specified zero value of EpsX and zero values for all  other
          conditions and tolerances, a default value will be returned
        *************************************************************************/
        public static double critgeteps(nlpstoppingcriteria crit,
            alglib.xparams _params)
        {
            double result = 0;

            result = critgetepswithdefault(crit, 1.0E-7, _params);
            return result;
        }


        /*************************************************************************
        Returns the value of the EpsX stopping condition:
        * if user specified nonzero value, it will be returned
        * if user specified zero value of EpsX, but non-zero value for  any  other
          condition or tolerance, zero will be returned
        * if user specified zero value of EpsX and zero values for all  other
          conditions and tolerances, a default value will be returned
        *************************************************************************/
        public static double critgetepswithdefault(nlpstoppingcriteria crit,
            double defval,
            alglib.xparams _params)
        {
            double result = 0;

            if( apserv.rmax3(crit.epsf, crit.eps, crit.maxits, _params)==0.0 )
            {
                result = defval;
            }
            else
            {
                result = crit.eps;
            }
            return result;
        }


        /*************************************************************************
        Returns the value of the MaxIts stopping condition:
        * the value specified by the user (either zero or nonzero) will be returned
        *************************************************************************/
        public static int critgetmaxits(nlpstoppingcriteria crit,
            alglib.xparams _params)
        {
            int result = 0;

            result = crit.maxits;
            return result;
        }


        /*************************************************************************
        Initializes line search using bisection

        NOTES:
        * MaxIts>=2 is required
        *************************************************************************/
        public static void linesearchinitbisect(double f0,
            double g0,
            double alpha1,
            double alphamax,
            double c1,
            double c2,
            bool strongwolfecond,
            int maxits,
            bool dotrace,
            int tracelevel,
            linesearchstate state,
            alglib.xparams _params)
        {
            alglib.ap.assert(math.isfinite(f0), "OPTSERV: integrity check 9420 failed");
            alglib.ap.assert(math.isfinite(g0), "OPTSERV: integrity check 9421 failed");
            alglib.ap.assert(math.isfinite(alpha1), "OPTSERV: integrity check 9422 failed");
            alglib.ap.assert(math.isfinite(alphamax), "OPTSERV: integrity check 9422A failed");
            alglib.ap.assert((double)(alpha1)>(double)(0), "OPTSERV: integrity check 9423 failed");
            alglib.ap.assert((double)(alphamax)>=(double)(alpha1), "OPTSERV: integrity check 9423A failed");
            alglib.ap.assert(maxits>=2, "OPTSERV: integrity check 9424 failed");
            alglib.ap.assert(math.isfinite(c1), "OPTSERV: integrity check 9425 failed");
            alglib.ap.assert(math.isfinite(c2), "OPTSERV: integrity check 9426 failed");
            alglib.ap.assert((double)(c1)>(double)(0) && (double)(c1)<(double)(1), "OPTSERV: integrity check 9427 failed");
            alglib.ap.assert((double)(c2)>(double)(0) && (double)(c2)<(double)(1), "OPTSERV: integrity check 9428 failed");
            state.f0 = f0;
            state.g0 = g0;
            state.alpha1 = alpha1;
            state.alphamax = alphamax;
            state.c1 = c1;
            state.c2 = c2;
            state.strongwolfecond = strongwolfecond;
            state.maxits = maxits;
            state.dotrace = dotrace;
            state.tracelevel = tracelevel;
            state.rstate.stage = -1;
            state.rstate.clear_handler();
        }


        /*************************************************************************
        Performs iteration.

        After the end it stores the best  step  to  State.AlphaSol.  The  function
        warrants that either:
        * AlphaSol is the last Alpha tried
        * AlphaSol=0, which means that a non-descent direction was specified.
          In the latter case no search was performed.

        The function also sets TerminationType field  to  a  value  which  roughly
        corresponds to ones returned by MCSRCH:
        * 0 for non-descent direction
        * 1 for search ended with the sufficient decrease condition and the
            curvature condition satisfied
        * 3 for iteration budget being exhausted, stopping at the best point so far
        * 5 for a step being at the upper bound
        *************************************************************************/
        public static bool linesearchiteration(linesearchstate state,
            alglib.xparams _params)
        {
            bool result = new bool();

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rstate.stage>=0 )
            {
            }
            else
            {
            }
            if( state.rstate.stage==0 )
            {
                goto lbl_0;
            }
            if( state.rstate.stage==1 )
            {
                goto lbl_1;
            }
            if( state.rstate.stage==2 )
            {
                goto lbl_2;
            }
            if( state.rstate.stage==3 )
            {
                goto lbl_3;
            }
            if( state.rstate.stage==4 )
            {
                goto lbl_4;
            }
            
            //
            // Routine body
            //
            
            //
            // Initial checks
            //
            if( state.dotrace )
            {
                apserv.traceangles(state.tracelevel, _params);
                alglib.ap.trace(" starting line search\n");
            }
            if( (double)(state.g0)>=(double)(0) )
            {
                if( state.dotrace )
                {
                    apserv.traceangles(state.tracelevel, _params);
                    alglib.ap.trace(System.String.Format(" directional derivative non-negative ({0,0:E2}), stopping\n", state.g0));
                }
                state.alphasol = 0.0;
                state.terminationtype = 0;
                result = false;
                return result;
            }
            state.nfev = 0;
            
            //
            // Phase 1: bracket step
            //
            state.fprev = state.f0;
            state.gprev = state.g0;
            state.alphaprev = 0;
            state.alphacur = state.alpha1;
            state.bestalphasofar = 0;
            state.bestfsofar = state.f0;
        lbl_5:
            if( false )
            {
                goto lbl_6;
            }
            
            //
            // RComm
            //
            state.alphatrial = state.alphacur;
            state.rstate.stage = 0;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
            state.fcur = state.ftrial;
            state.gcur = state.gtrial;
            state.nfev = state.nfev+1;
            if( state.dotrace )
            {
                apserv.traceangles(state.tracelevel, _params);
                alglib.ap.trace(System.String.Format(" target evaluated at stp={0,0:E3}, deltaF={1,0:E3}, dg={2,0:E3}\n", state.alphacur, state.fcur-state.f0, state.gcur));
            }
            
            //
            // Update best point so far
            //
            // NOTE: strict inequality is essential
            //
            if( (double)(state.bestalphasofar)==(double)(0) || (double)(state.fcur)<(double)(state.bestfsofar) )
            {
                state.bestalphasofar = state.alphacur;
                state.bestfsofar = state.fcur;
            }
            
            //
            // Tests
            //
            if( state.nfev<state.maxits-1 )
            {
                goto lbl_7;
            }
            
            //
            // Function budget is almost exhausted. We may have to terminate before exhausting it completely
            // in order to be able to evaluate the target at the last point known.
            //
            alglib.ap.assert((double)(state.bestalphasofar)>(double)(0), "OPTSERV: integrity check 1224 failed");
            if( (double)(state.alphacur)==(double)(state.bestalphasofar) )
            {
                goto lbl_9;
            }
            
            //
            // Make one reverse communication request.
            //
            // We do not use its results, it is here merely for caller to evaluate the target at the point where we stopped
            //
            state.alphatrial = state.bestalphasofar;
            state.rstate.stage = 1;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            state.nfev = state.nfev+1;
        lbl_9:
            state.alphasol = state.bestalphasofar;
            state.terminationtype = 3;
            if( state.dotrace )
            {
                apserv.traceangles(state.tracelevel, _params);
                alglib.ap.trace(System.String.Format(" iteration budget of {0,0:d} evaluations is used, stopping\n", state.maxits));
            }
            result = false;
            return result;
        lbl_7:
            if( (double)(state.fcur)<=(double)(state.f0+state.c1*state.alphacur*state.g0) && ((double)(Math.Abs(state.gcur))<=(double)(-(state.c2*state.g0)) || (!state.strongwolfecond && (double)(state.gcur)>=(double)(state.c2*state.g0))) )
            {
                
                //
                // Found
                //
                state.alphasol = state.alphacur;
                state.terminationtype = 1;
                if( state.dotrace )
                {
                    apserv.traceangles(state.tracelevel, _params);
                    alglib.ap.trace(" sufficient decrease and curvature conditions hold, stopping\n");
                }
                result = false;
                return result;
            }
            if( (double)(state.fcur)>=(double)(state.f0+state.c1*state.alphacur*state.g0) || (double)(state.fcur)>=(double)(state.fprev) )
            {
                
                //
                // Bracketed by target value
                //
                state.alphalo = state.alphaprev;
                state.alphahi = state.alphacur;
                state.flo = state.fprev;
                state.fhi = state.fcur;
                state.glo = state.gprev;
                state.ghi = state.gcur;
                if( state.dotrace )
                {
                    apserv.traceangles(state.tracelevel, _params);
                    alglib.ap.trace(System.String.Format(" the minimum is bracketed by the target, stp=[{0,0:E3},{1,0:E3}], proceeding to phase 2\n", state.alphalo, state.alphahi));
                }
                goto lbl_6;
            }
            if( (double)(state.gcur)>=(double)(0) )
            {
                
                //
                // Bracketed by gradient value
                //
                state.alphahi = state.alphaprev;
                state.alphalo = state.alphacur;
                state.fhi = state.fprev;
                state.flo = state.fcur;
                state.ghi = state.gprev;
                state.glo = state.gcur;
                if( state.dotrace )
                {
                    apserv.traceangles(state.tracelevel, _params);
                    alglib.ap.trace(System.String.Format(" the minimum is bracketed by the gradient, stp=[{0,0:E3},{1,0:E3}], proceeding to phase 2\n", state.alphahi, state.alphalo));
                }
                goto lbl_6;
            }
            if( !((double)(state.alphacur)>=(double)(0.999*state.alphamax) || (double)(state.alphacur)==(double)(state.alphaprev)) )
            {
                goto lbl_11;
            }
            
            //
            // We reached upper bound on the step length (or the step stagnated due to numerical errors)
            //
            alglib.ap.assert((double)(state.bestalphasofar)>(double)(0), "OPTSERV: integrity check 1224 failed");
            if( (double)(state.alphacur)==(double)(state.bestalphasofar) )
            {
                goto lbl_13;
            }
            
            //
            // Make one reverse communication request.
            //
            // We do not use its results, it is here merely for caller to evaluate the target at the point where we stopped
            //
            state.alphatrial = state.bestalphasofar;
            state.rstate.stage = 2;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_2:
            state.nfev = state.nfev+1;
        lbl_13:
            if( state.dotrace )
            {
                apserv.traceangles(state.tracelevel, _params);
                alglib.ap.trace(System.String.Format(" reached an upper bound on the step length, stopping at the best point so far (stp={0,0:E3})\n", state.bestalphasofar));
            }
            state.alphasol = state.bestalphasofar;
            state.terminationtype = 5;
            result = false;
            return result;
        lbl_11:
            
            //
            // Next step
            //
            state.fprev = state.fcur;
            state.gprev = state.gcur;
            state.alphaprev = state.alphacur;
            state.alphacur = Math.Min(2*state.alphacur, state.alphamax);
            goto lbl_5;
        lbl_6:
            
            //
            // Phase 2: perform bisection on bracketed step
            //
        lbl_15:
            if( false )
            {
                goto lbl_16;
            }
            
            //
            // Compute AlphaTrial and evaluate target
            //
            state.alphacur = 0.5*(state.alphalo+state.alphahi);
            state.alphatrial = state.alphacur;
            state.rstate.stage = 3;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_3:
            state.fcur = state.ftrial;
            state.gcur = state.gtrial;
            state.nfev = state.nfev+1;
            if( state.dotrace )
            {
                apserv.traceangles(state.tracelevel, _params);
                alglib.ap.trace(System.String.Format(" target evaluated at stp={0,0:E3}, deltaF={1,0:E3}, dg={2,0:E3}, interval of uncertainty is [{3,0:E3},{4,0:E3}]\n", state.alphacur, state.fcur-state.f0, state.gcur, Math.Min(state.alphalo, state.alphahi), Math.Max(state.alphalo, state.alphahi)));
            }
            
            //
            // Update best point so far
            //
            // NOTE: strict inequality is essential
            //
            alglib.ap.assert((double)(state.bestalphasofar)!=(double)(0), "OPTSERV: integrity check 1130 failed");
            if( (double)(state.fcur)<(double)(state.bestfsofar) )
            {
                state.bestalphasofar = state.alphacur;
                state.bestfsofar = state.fcur;
            }
            
            //
            // Check iteration budget
            //
            if( state.nfev<state.maxits-1 )
            {
                goto lbl_17;
            }
            
            //
            // Function budget is almost exhausted. We may have to terminate before exhausting it completely
            // in order to be able to evaluate the target at the last point known.
            //
            alglib.ap.assert((double)(state.bestalphasofar)>(double)(0), "OPTSERV: integrity check 1224 failed");
            if( (double)(state.alphacur)==(double)(state.bestalphasofar) )
            {
                goto lbl_19;
            }
            
            //
            // Make one reverse communication request.
            //
            // We do not use its results, it is here merely for caller to evaluate the target at the point where we stopped
            //
            state.alphatrial = state.bestalphasofar;
            state.rstate.stage = 4;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_4:
            state.nfev = state.nfev+1;
        lbl_19:
            state.alphasol = state.bestalphasofar;
            state.terminationtype = 3;
            if( state.dotrace )
            {
                apserv.traceangles(state.tracelevel, _params);
                alglib.ap.trace(System.String.Format(" iteration budget of {0,0:d} evaluations is used, stopping\n", state.maxits));
            }
            result = false;
            return result;
        lbl_17:
            
            //
            // Check stopping criteria
            //
            if( (double)(state.fcur)<=(double)(state.f0+state.c1*state.alphacur*state.g0) && ((double)(Math.Abs(state.gcur))<=(double)(-(state.c2*state.g0)) || (!state.strongwolfecond && (double)(state.gcur)>=(double)(state.c2*state.g0))) )
            {
                
                //
                // Found
                //
                state.alphasol = state.alphacur;
                state.terminationtype = 1;
                if( state.dotrace )
                {
                    apserv.traceangles(state.tracelevel, _params);
                    alglib.ap.trace(" sufficient decrease and curvature conditions hold, stopping\n");
                }
                result = false;
                return result;
            }
            
            //
            // Analyze
            //
            if( (double)(state.fcur)>=(double)(state.f0+state.c1*state.alphatrial*state.g0) || (double)(state.fcur)>=(double)(state.flo) )
            {
                state.alphahi = state.alphacur;
                state.fhi = state.fcur;
                state.ghi = state.gcur;
            }
            else
            {
                if( (double)(state.gcur*(state.alphahi-state.alphalo))>=(double)(0) )
                {
                    state.alphahi = state.alphalo;
                    state.fhi = state.flo;
                    state.ghi = state.glo;
                }
                state.alphalo = state.alphacur;
                state.flo = state.fcur;
                state.glo = state.gcur;
            }
            goto lbl_15;
        lbl_16:
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            return result;
        }


        /*************************************************************************
        Create a filter for NLP solver
        *************************************************************************/
        public static void nlpfinit(double maxh,
            nlpfilter s,
            alglib.xparams _params)
        {
            s.maxh = maxh;
            s.filtersize = 0;
            s.gammaf = 0.0;
            s.gammah = 1.0;
            s.maxdominating = 0;
        }


        /*************************************************************************
        Copy filter
        *************************************************************************/
        public static void nlpfinitfrom(nlpfilter src,
            nlpfilter dst,
            alglib.xparams _params)
        {
            dst.maxh = src.maxh;
            dst.filtersize = src.filtersize;
            dst.maxdominating = src.maxdominating;
            dst.gammaf = src.gammaf;
            dst.gammah = src.gammah;
            dst.violationistoohigh = src.violationistoohigh;
            ablasf.rcopyallocv(dst.filtersize, src.filterf, ref dst.filterf, _params);
            ablasf.rcopyallocv(dst.filtersize, src.filterh, ref dst.filterh, _params);
        }


        /*************************************************************************
        Create a filter for NLP solver with the possibility of points being accepted
        when dominated by no more than MD>=0 ones.

        MD=0 corresponds to the traditional filter.
        *************************************************************************/
        public static void nlpfinitx(double maxh,
            int md,
            nlpfilter s,
            alglib.xparams _params)
        {
            alglib.ap.assert(md>=0, "nlpfInitX: MD<0");
            s.maxh = maxh;
            s.filtersize = 0;
            s.gammaf = 0.0;
            s.gammah = 1.0;
            s.maxdominating = md;
        }


        /*************************************************************************
        Check point for acceptance.

        On failure sets S.ViolationIsTooHigh.
        *************************************************************************/
        public static bool nlpfisacceptable(nlpfilter s,
            double f0,
            double h0,
            double f1,
            double h1,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int dcnt = 0;

            if( h1>s.maxh )
            {
                s.violationistoohigh = true;
                result = false;
                return result;
            }
            s.violationistoohigh = false;
            if( f1>=f0-s.gammaf*h0 && h1>=h0*s.gammah )
            {
                result = false;
                return result;
            }
            dcnt = 0;
            for(i=0; i<=s.filtersize-1; i++)
            {
                if( f1>=s.filterf[i]-s.gammaf*h1 && h1>=s.filterh[i]*s.gammah )
                {
                    dcnt = dcnt+1;
                }
                if( dcnt>s.maxdominating )
                {
                    result = false;
                    return result;
                }
            }
            result = true;
            return result;
        }


        /*************************************************************************
        Check point for acceptance.

        On failure sets S.ViolationIsTooHigh.
        *************************************************************************/
        public static bool nlpfisacceptable1(nlpfilter s,
            double f,
            double h,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int dcnt = 0;

            if( h>=s.maxh )
            {
                s.violationistoohigh = true;
                result = false;
                return result;
            }
            s.violationistoohigh = false;
            dcnt = 0;
            for(i=0; i<=s.filtersize-1; i++)
            {
                if( f>=s.filterf[i]-s.gammaf*h && h>=s.filterh[i]*s.gammah )
                {
                    dcnt = dcnt+1;
                }
                if( dcnt>s.maxdominating )
                {
                    result = false;
                    return result;
                }
            }
            result = true;
            return result;
        }


        /*************************************************************************
        Append point, if acceptable. Behavior is undefined for unacceptable points.
        *************************************************************************/
        public static void nlpfappend(nlpfilter s,
            double f,
            double h,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int dcnt = 0;
            int newsize = 0;
            double fcand = 0;
            double hcand = 0;

            if( s.maxdominating==0 )
            {
                
                //
                // Quick O(FilterSize) code for the traditional filter
                //
                i = 0;
                while( i<s.filtersize )
                {
                    if( f<=s.filterf[i] && h<=s.filterh[i] )
                    {
                        
                        //
                        // The point being added dominates the I-th one, remove it
                        //
                        s.filterf[i] = s.filterf[s.filtersize-1];
                        s.filterh[i] = s.filterh[s.filtersize-1];
                        s.filtersize = s.filtersize-1;
                        continue;
                    }
                    i = i+1;
                }
                ablasf.rgrowv(s.filtersize+1, ref s.filterf, _params);
                ablasf.rgrowv(s.filtersize+1, ref s.filterh, _params);
                s.filterf[s.filtersize] = f;
                s.filterh[s.filtersize] = h;
                s.filtersize = s.filtersize+1;
            }
            else
            {
                
                //
                // Slower O(FilterSize^2) code for the D-dominating filter.
                //
                // First, insert new point to the beginning. This way we make sure
                // that it is always retained, even under rounding errors.
                //
                ablasf.rgrowv(s.filtersize+1, ref s.filterf, _params);
                ablasf.rgrowv(s.filtersize+1, ref s.filterh, _params);
                s.filterf[s.filtersize] = s.filterf[0];
                s.filterh[s.filtersize] = s.filterh[0];
                s.filterf[0] = f;
                s.filterh[0] = h;
                s.filtersize = s.filtersize+1;
                
                //
                // Then, for each point compute how many times it is dominated
                //
                newsize = 1;
                for(i=1; i<=s.filtersize-1; i++)
                {
                    dcnt = 0;
                    fcand = s.filterf[i];
                    hcand = s.filterh[i];
                    for(j=0; j<=newsize-1; j++)
                    {
                        if( fcand>=s.filterf[j] && hcand>=s.filterh[j] )
                        {
                            dcnt = dcnt+1;
                        }
                    }
                    if( dcnt<=s.maxdominating )
                    {
                        s.filterf[newsize] = fcand;
                        s.filterh[newsize] = hcand;
                        newsize = newsize+1;
                    }
                }
                
                //
                // Done
                //
                s.filtersize = newsize;
            }
        }


        /*************************************************************************
        Drop all points stored in the filter
        *************************************************************************/
        public static void nlpfclear(nlpfilter s,
            alglib.xparams _params)
        {
            s.filtersize = 0;
        }


        /*************************************************************************
        Updates maximum violation
        *************************************************************************/
        public static void nlpfsetmaxh(nlpfilter s,
            double maxh,
            alglib.xparams _params)
        {
            s.maxh = maxh;
        }


        /*************************************************************************
        Initialize linear constraints structure
        *************************************************************************/
        public static void xlcinit(int n,
            opts.xlinearconstraints state,
            alglib.xparams _params)
        {
            alglib.ap.assert(n>=1, "xlcInit: N<1");
            state.n = n;
            state.ndense = 0;
            state.nsparse = 0;
        }


        /*************************************************************************
        SINGLE-SIDED CONSTRANTS USING LEGACY FORMAT

        This function sets mixed linear constraints, which include a set of  dense
        rows, and a set of sparse rows.

        This function overrides results of previous constraint modifications.

        INPUT PARAMETERS:
            State   -   structure previously allocated with MinQPCreate call.
            SparseC -   linear constraints, sparse  matrix with dimensions EXACTLY
                        EQUAL TO [SparseK,N+1].  Each  row  of  C  represents  one
                        constraint, either equality or inequality (see below):
                        * first N elements correspond to coefficients,
                        * last element corresponds to the right part.
                        All elements of C (including right part) must be finite.
            SparseCT-   type of sparse constraints, array[K]:
                        * if SparseCT[i]>0, then I-th constraint is SparseC[i,*]*x >= SparseC[i,n+1]
                        * if SparseCT[i]=0, then I-th constraint is SparseC[i,*]*x  = SparseC[i,n+1]
                        * if SparseCT[i]<0, then I-th constraint is SparseC[i,*]*x <= SparseC[i,n+1]
            SparseK -   number of sparse equality/inequality constraints, K>=0
            DenseC  -   dense linear constraints, array[K,N+1].
                        Each row of DenseC represents one constraint, either equality
                        or inequality (see below):
                        * first N elements correspond to coefficients,
                        * last element corresponds to the right part.
                        All elements of DenseC (including right part) must be finite.
            DenseCT -   type of constraints, array[K]:
                        * if DenseCT[i]>0, then I-th constraint is DenseC[i,*]*x >= DenseC[i,n+1]
                        * if DenseCT[i]=0, then I-th constraint is DenseC[i,*]*x  = DenseC[i,n+1]
                        * if DenseCT[i]<0, then I-th constraint is DenseC[i,*]*x <= DenseC[i,n+1]
            DenseK  -   number of equality/inequality constraints, DenseK>=0

          -- ALGLIB --
             Copyright 13.04.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void xlcsetlcmixed(opts.xlinearconstraints state,
            sparse.sparsematrix sparsec,
            int[] sparsect,
            int sparsek,
            double[,] densec,
            int[] densect,
            int densek,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            int j = 0;
            int j0 = 0;
            double v = 0;
            int[] srcidx = new int[0];
            int[] dstidx = new int[0];
            double[] s = new double[0];
            int[] rs = new int[0];
            int[] eoffs = new int[0];
            int[] roffs = new int[0];
            double[] v2 = new double[0];
            int[] eidx = new int[0];
            double[] eval = new double[0];
            int t0 = 0;
            int t1 = 0;
            int nnz = 0;

            n = state.n;
            
            //
            // First, check for errors in the inputs
            //
            alglib.ap.assert(densek>=0, "xlcSetLCMixed: K<0");
            alglib.ap.assert(densek==0 || alglib.ap.cols(densec)>=n+1, "xlcSetLCMixed: Cols(C)<N+1");
            alglib.ap.assert(alglib.ap.rows(densec)>=densek, "xlcSetLCMixed: Rows(DenseC)<DenseK");
            alglib.ap.assert(alglib.ap.len(densect)>=densek, "xlcSetLCMixed: Length(DenseCT)<DenseK");
            alglib.ap.assert(apserv.apservisfinitematrix(densec, densek, n+1, _params), "xlcSetLCMixed: C contains infinite or NaN values!");
            alglib.ap.assert(sparsek>=0, "xlcSetLCMixed: SparseK<0");
            alglib.ap.assert(sparsek==0 || sparse.sparsegetncols(sparsec, _params)>=n+1, "xlcSetLCMixed: Cols(SparseC)<N+1");
            alglib.ap.assert(sparsek==0 || sparse.sparsegetnrows(sparsec, _params)>=sparsek, "xlcSetLCMixed: Rows(SparseC)<SparseK");
            alglib.ap.assert(alglib.ap.len(sparsect)>=sparsek, "xlcSetLCMixed: Length(SparseCT)<SparseK");
            
            //
            // Init
            //
            state.ndense = densek;
            state.nsparse = sparsek;
            if( sparsek>0 )
            {
                ablasf.rallocv(sparsek, ref state.scl, _params);
                ablasf.rallocv(sparsek, ref state.scu, _params);
                
                //
                // Evaluate row sizes for new storage
                //
                rs = new int[sparsek];
                for(i=0; i<=sparsek-1; i++)
                {
                    rs[i] = 0;
                }
                t0 = 0;
                t1 = 0;
                nnz = 0;
                while( sparse.sparseenumerate(sparsec, ref t0, ref t1, ref i, ref j, ref v, _params) )
                {
                    if( i>sparsek-1 || j>n-1 )
                    {
                        continue;
                    }
                    alglib.ap.assert(math.isfinite(v), "xlcSetLCSparse: C contains infinite or NAN values");
                    nnz = nnz+1;
                    rs[i] = rs[i]+1;
                }
                
                //
                // Prepare new sparse CRS storage, copy leading SparseK*N submatrix into the storage
                //
                for(i=0; i<=sparsek-1; i++)
                {
                    state.scl[i] = 0;
                    state.scu[i] = 0;
                }
                state.sparsec.m = sparsek;
                state.sparsec.n = n;
                apserv.ivectorsetlengthatleast(ref state.sparsec.ridx, sparsek+1, _params);
                apserv.ivectorsetlengthatleast(ref state.sparsec.idx, nnz, _params);
                apserv.rvectorsetlengthatleast(ref state.sparsec.vals, nnz, _params);
                eoffs = new int[sparsek+1];
                state.sparsec.ridx[0] = 0;
                eoffs[0] = 0;
                for(i=1; i<=sparsek; i++)
                {
                    state.sparsec.ridx[i] = state.sparsec.ridx[i-1]+rs[i-1];
                    eoffs[i] = state.sparsec.ridx[i];
                }
                t0 = 0;
                t1 = 0;
                while( sparse.sparseenumerate(sparsec, ref t0, ref t1, ref i, ref j, ref v, _params) )
                {
                    if( i>sparsek-1 || j>n )
                    {
                        continue;
                    }
                    if( j<n )
                    {
                        
                        //
                        // Copy left part of constraint
                        //
                        j0 = eoffs[i];
                        state.sparsec.idx[j0] = j;
                        state.sparsec.vals[j0] = v;
                        eoffs[i] = j0+1;
                    }
                    else
                    {
                        
                        //
                        // Handle right part of the constraint
                        //
                        state.scl[i] = v;
                        state.scu[i] = v;
                    }
                }
                for(i=0; i<=sparsek-1; i++)
                {
                    alglib.ap.assert(eoffs[i]==state.sparsec.ridx[i+1], "xlc: critical integrity check failed (sparse copying)");
                }
                sparse.sparsecreatecrsinplace(state.sparsec, _params);
                for(i=0; i<=sparsek-1; i++)
                {
                    if( sparsect[i]>0 )
                    {
                        state.scu[i] = Double.PositiveInfinity;
                    }
                    if( sparsect[i]<0 )
                    {
                        state.scl[i] = Double.NegativeInfinity;
                    }
                }
            }
            if( densek>0 )
            {
                
                //
                // Copy dense constraints
                //
                ablasf.rallocv(densek, ref state.dcl, _params);
                ablasf.rallocv(densek, ref state.dcu, _params);
                apserv.rmatrixsetlengthatleast(ref state.densec, densek, n, _params);
                for(i=0; i<=densek-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        state.densec[i,j] = densec[i,j];
                    }
                    if( densect[i]>0 )
                    {
                        state.dcl[i] = densec[i,n];
                        state.dcu[i] = Double.PositiveInfinity;
                        continue;
                    }
                    if( densect[i]<0 )
                    {
                        state.dcl[i] = Double.NegativeInfinity;
                        state.dcu[i] = densec[i,n];
                        continue;
                    }
                    state.dcl[i] = densec[i,n];
                    state.dcu[i] = densec[i,n];
                }
            }
        }


        /*************************************************************************
        This  function  sets  two-sided linear  constraints  AL <= A*x <= AU  with
        mixed constraining matrix A including sparse part (first SparseK rows) and
        dense part (last DenseK rows). Recommended for large-scale problems.

        This function overwrites modifications set  by  previous  calls  (if  such
        calls were made).

        This function may be useful if constraint matrix includes large number  of
        both types of rows - dense and sparse. If you have just a few sparse rows,
        you  may  represent  them  in  dense  format  without losing  performance.
        Similarly, if you have just a few dense rows, you may store them in sparse
        format with almost same performance.

        INPUT PARAMETERS:
            State   -   linear constraints structure
            SparseA -   sparse matrix with size [K,N] (exactly!).
                        Each row of A represents one general linear constraint.
                        A can be stored in any sparse storage format.
            SparseK -   number of sparse constraints, SparseK>=0
            DenseA  -   linear constraints, array[K,N], set of dense constraints.
                        Each row of A represents one general linear constraint.
            DenseK  -   number of dense constraints, DenseK>=0
            AL, AU  -   lower and upper bounds, array[SparseK+DenseK], with former
                        SparseK elements corresponding to sparse constraints,  and
                        latter DenseK elements corresponding to dense constraints;
                        * AL[i]=AU[i] => equality constraint Ai*x
                        * AL[i]<AU[i] => two-sided constraint AL[i]<=Ai*x<=AU[i]
                        * AL[i]=-INF  => one-sided constraint Ai*x<=AU[i]
                        * AU[i]=+INF  => one-sided constraint AL[i]<=Ai*x
                        * AL[i]=-INF, AU[i]=+INF => constraint is ignored
            K       -   number  of equality/inequality constraints, K>=0.  If  K=0
                        is specified, A, AL, AU are ignored.

          -- ALGLIB --
             Copyright 13.04.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void xlcsetlc2mixed(opts.xlinearconstraints state,
            sparse.sparsematrix sparsea,
            int ksparse,
            double[,] densea,
            int kdense,
            double[] al,
            double[] au,
            alglib.xparams _params)
        {
            int n = 0;
            int m = 0;
            int i = 0;

            n = state.n;
            m = kdense+ksparse;
            
            //
            // Check input arguments
            //
            alglib.ap.assert(ksparse>=0, "xlcSetLC2Mixed: KSparse<0");
            alglib.ap.assert(ksparse==0 || sparse.sparsegetncols(sparsea, _params)==n, "xlcSetLC2: Cols(SparseA)<>N");
            alglib.ap.assert(ksparse==0 || sparse.sparsegetnrows(sparsea, _params)==ksparse, "xlcSetLC2: Rows(SparseA)<>K");
            alglib.ap.assert(kdense>=0, "xlcSetLC2Mixed: KDense<0");
            alglib.ap.assert(kdense==0 || alglib.ap.cols(densea)>=n, "xlcSetLC2Mixed: Cols(DenseA)<N");
            alglib.ap.assert(kdense==0 || alglib.ap.rows(densea)>=kdense, "xlcSetLC2Mixed: Rows(DenseA)<K");
            alglib.ap.assert(apserv.apservisfinitematrix(densea, kdense, n, _params), "xlcSetLC2Mixed: DenseA contains infinite or NaN values!");
            alglib.ap.assert(alglib.ap.len(al)>=kdense+ksparse, "xlcSetLC2Mixed: Length(AL)<K");
            alglib.ap.assert(alglib.ap.len(au)>=kdense+ksparse, "xlcSetLC2Mixed: Length(AU)<K");
            for(i=0; i<=m-1; i++)
            {
                alglib.ap.assert(math.isfinite(al[i]) || Double.IsNegativeInfinity(al[i]), "xlcSetLC2Mixed: AL contains NAN or +INF");
                alglib.ap.assert(math.isfinite(au[i]) || Double.IsPositiveInfinity(au[i]), "xlcSetLC2Mixed: AU contains NAN or -INF");
            }
            
            //
            // Quick exit if needed
            //
            if( m==0 )
            {
                state.ndense = 0;
                state.nsparse = 0;
                return;
            }
            
            //
            // Prepare
            //
            ablasf.rallocv(ksparse, ref state.scl, _params);
            ablasf.rallocv(ksparse, ref state.scu, _params);
            ablasf.rallocv(kdense, ref state.dcl, _params);
            ablasf.rallocv(kdense, ref state.dcu, _params);
            ablasf.rcopyvx(ksparse, al, 0, state.scl, 0, _params);
            ablasf.rcopyvx(ksparse, au, 0, state.scu, 0, _params);
            ablasf.rcopyvx(kdense, al, ksparse, state.dcl, 0, _params);
            ablasf.rcopyvx(kdense, au, ksparse, state.dcu, 0, _params);
            state.ndense = kdense;
            state.nsparse = ksparse;
            
            //
            // Copy dense and sparse terms
            //
            if( ksparse>0 )
            {
                sparse.sparsecopytocrsbuf(sparsea, state.sparsec, _params);
            }
            if( kdense>0 )
            {
                ablasf.rcopyallocm(kdense, n, densea, ref state.densec, _params);
            }
        }


        /*************************************************************************
        This function appends two-sided linear constraint  AL <= A*x <= AU  to the
        matrix of currently present dense constraints.

        INPUT PARAMETERS:
            State   -   current constraints
            A       -   linear constraint coefficient, array[N], right side is NOT
                        included.
            AL, AU  -   lower and upper bounds;
                        * AL=AU    => equality constraint Ai*x
                        * AL<AU    => two-sided constraint AL<=A*x<=AU
                        * AL=-INF  => one-sided constraint Ai*x<=AU
                        * AU=+INF  => one-sided constraint AL<=Ai*x
                        * AL=-INF, AU=+INF => constraint is ignored

          -- ALGLIB --
             Copyright 19.07.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void xlcaddlc2dense(opts.xlinearconstraints state,
            double[] a,
            double al,
            double au,
            alglib.xparams _params)
        {
            int n = 0;

            n = state.n;
            alglib.ap.assert(alglib.ap.len(a)>=n, "xlcAddLC2Dense: Length(A)<N");
            alglib.ap.assert(apserv.isfinitevector(a, n, _params), "xlcAddLC2Dense: A contains infinite or NaN values!");
            alglib.ap.assert(math.isfinite(al) || Double.IsNegativeInfinity(al), "xlcAddLC2Dense: AL is NAN or +INF");
            alglib.ap.assert(math.isfinite(au) || Double.IsPositiveInfinity(au), "xlcAddLC2Dense: AU is NAN or -INF");
            ablasf.rgrowv(state.ndense+1, ref state.dcl, _params);
            ablasf.rgrowv(state.ndense+1, ref state.dcu, _params);
            apserv.rmatrixgrowrowsto(ref state.densec, state.ndense+1, n, _params);
            ablasf.rcopyvr(n, a, state.densec, state.ndense, _params);
            state.dcl[state.ndense] = al;
            state.dcu[state.ndense] = au;
            state.ndense = state.ndense+1;
        }


        /*************************************************************************
        This function appends two-sided linear constraint  AL <= A*x <= AU  to the
        list of currently present sparse constraints.

        Constraint is passed in compressed format: as list of non-zero entries  of
        coefficient vector A. Such approach is more efficient than  dense  storage
        for highly sparse constraint vectors.

        INPUT PARAMETERS:
            State   -   structure
            IdxA    -   array[NNZ], indexes of non-zero elements of A:
                        * can be unsorted
                        * can include duplicate indexes (corresponding entries  of
                          ValA[] will be summed)
            ValA    -   array[NNZ], values of non-zero elements of A
            NNZ     -   number of non-zero coefficients in A
            AL, AU  -   lower and upper bounds;
                        * AL=AU    => equality constraint A*x
                        * AL<AU    => two-sided constraint AL<=A*x<=AU
                        * AL=-INF  => one-sided constraint A*x<=AU
                        * AU=+INF  => one-sided constraint AL<=A*x
                        * AL=-INF, AU=+INF => constraint is ignored

          -- ALGLIB --
             Copyright 19.07.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void xlcaddlc2(opts.xlinearconstraints state,
            int[] idxa,
            double[] vala,
            int nnz,
            double al,
            double au,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            int offs = 0;
            int offsdst = 0;
            int n = 0;
            int didx = 0;
            int uidx = 0;

            n = state.n;
            
            //
            // Check inputs
            //
            alglib.ap.assert(nnz>=0, "xlcAddLC2: NNZ<0");
            alglib.ap.assert(alglib.ap.len(idxa)>=nnz, "xlcAddLC2: Length(IdxA)<NNZ");
            alglib.ap.assert(alglib.ap.len(vala)>=nnz, "xlcAddLC2: Length(ValA)<NNZ");
            for(i=0; i<=nnz-1; i++)
            {
                alglib.ap.assert(idxa[i]>=0 && idxa[i]<n, "xlcAddLC2: IdxA contains indexes outside of [0,N) range");
            }
            alglib.ap.assert(apserv.isfinitevector(vala, nnz, _params), "xlcAddLC2: ValA contains infinite or NaN values!");
            alglib.ap.assert(math.isfinite(al) || Double.IsNegativeInfinity(al), "xlcAddLC2: AL is NAN or +INF");
            alglib.ap.assert(math.isfinite(au) || Double.IsPositiveInfinity(au), "xlcAddLC2: AU is NAN or -INF");
            
            //
            // If M=0, it means that A is uninitialized.
            // Prepare sparse matrix structure
            //
            if( state.nsparse==0 )
            {
                state.sparsec.matrixtype = 1;
                state.sparsec.m = 0;
                state.sparsec.n = n;
                state.sparsec.ninitialized = 0;
                apserv.ivectorsetlengthatleast(ref state.sparsec.ridx, 1, _params);
                state.sparsec.ridx[0] = 0;
            }
            alglib.ap.assert(state.sparsec.matrixtype==1 && state.sparsec.m==state.nsparse, "xlcAddLC2: integrity check failed!");
            
            //
            // Reallocate inequality bounds
            //
            ablasf.rgrowv(state.nsparse+1, ref state.scl, _params);
            ablasf.rgrowv(state.nsparse+1, ref state.scu, _params);
            state.scl[state.nsparse] = al;
            state.scu[state.nsparse] = au;
            
            //
            // Reallocate sparse storage
            //
            offs = state.sparsec.ridx[state.nsparse];
            apserv.ivectorgrowto(ref state.sparsec.idx, offs+nnz, _params);
            apserv.rvectorgrowto(ref state.sparsec.vals, offs+nnz, _params);
            apserv.ivectorgrowto(ref state.sparsec.didx, state.nsparse+1, _params);
            apserv.ivectorgrowto(ref state.sparsec.uidx, state.nsparse+1, _params);
            apserv.ivectorgrowto(ref state.sparsec.ridx, state.nsparse+2, _params);
            
            //
            // If NNZ=0, perform quick and simple row append. 
            //
            if( nnz==0 )
            {
                state.sparsec.didx[state.nsparse] = state.sparsec.ridx[state.nsparse];
                state.sparsec.uidx[state.nsparse] = state.sparsec.ridx[state.nsparse];
                state.sparsec.ridx[state.nsparse+1] = state.sparsec.ridx[state.nsparse];
                apserv.inc(ref state.sparsec.m, _params);
                apserv.inc(ref state.nsparse, _params);
                return;
            }
            
            //
            // Now we are sure that SparseC contains properly initialized sparse
            // matrix (or some appropriate dummy for M=0) and we have NNZ>0
            // (no need to care about degenerate cases).
            //
            // Append rows to SparseC:
            // * append data
            // * sort in place
            // * merge duplicate indexes
            // * compute DIdx and UIdx
            //
            //
            for(i=0; i<=nnz-1; i++)
            {
                state.sparsec.idx[offs+i] = idxa[i];
                state.sparsec.vals[offs+i] = vala[i];
            }
            tsort.tagsortmiddleir(ref state.sparsec.idx, ref state.sparsec.vals, offs, nnz, _params);
            offsdst = offs;
            for(i=1; i<=nnz-1; i++)
            {
                if( state.sparsec.idx[offsdst]!=state.sparsec.idx[offs+i] )
                {
                    offsdst = offsdst+1;
                    state.sparsec.idx[offsdst] = state.sparsec.idx[offs+i];
                    state.sparsec.vals[offsdst] = state.sparsec.vals[offs+i];
                }
                else
                {
                    state.sparsec.vals[offsdst] = state.sparsec.vals[offsdst]+state.sparsec.vals[offs+i];
                }
            }
            nnz = offsdst-offs+1;
            uidx = -1;
            didx = -1;
            for(j=offs; j<=offsdst; j++)
            {
                k = state.sparsec.idx[j];
                if( k==state.nsparse )
                {
                    didx = j;
                }
                else
                {
                    if( k>state.nsparse && uidx==-1 )
                    {
                        uidx = j;
                        break;
                    }
                }
            }
            if( uidx==-1 )
            {
                uidx = offsdst+1;
            }
            if( didx==-1 )
            {
                didx = uidx;
            }
            state.sparsec.didx[state.nsparse] = didx;
            state.sparsec.uidx[state.nsparse] = uidx;
            state.sparsec.ridx[state.nsparse+1] = offsdst+1;
            state.sparsec.ninitialized = state.sparsec.ridx[state.nsparse+1];
            apserv.inc(ref state.sparsec.m, _params);
            apserv.inc(ref state.nsparse, _params);
        }


        /*************************************************************************
        This function appends two-sided linear constraint  AL <= A*x <= AU  to the
        list of currently present sparse constraints.

        Constraint vector A is  passed  as  a  dense  array  which  is  internally
        sparsified by this function.

        INPUT PARAMETERS:
            State   -   structure
            DA      -   array[N], constraint vector
            AL, AU  -   lower and upper bounds;
                        * AL=AU    => equality constraint A*x
                        * AL<AU    => two-sided constraint AL<=A*x<=AU
                        * AL=-INF  => one-sided constraint A*x<=AU
                        * AU=+INF  => one-sided constraint AL<=A*x
                        * AL=-INF, AU=+INF => constraint is ignored

          -- ALGLIB --
             Copyright 19.07.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void xlcaddlc2sparsefromdense(opts.xlinearconstraints state,
            double[] da,
            double al,
            double au,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            int nzi = 0;
            int offs = 0;
            int n = 0;
            int nnz = 0;
            int didx = 0;
            int uidx = 0;

            n = state.n;
            
            //
            // Check inputs
            //
            alglib.ap.assert(alglib.ap.len(da)>=n, "xlcAddLC2SparseFromDense: Length(DA)<N");
            alglib.ap.assert(apserv.isfinitevector(da, n, _params), "xlcAddLC2SparseFromDense: DA contains infinities/NANs");
            alglib.ap.assert(math.isfinite(al) || Double.IsNegativeInfinity(al), "xlcAddLC2SparseFromDense: AL is NAN or +INF");
            alglib.ap.assert(math.isfinite(au) || Double.IsPositiveInfinity(au), "xlcAddLC2SparseFromDense: AU is NAN or -INF");
            
            //
            // If M=0, it means that A is uninitialized.
            // Prepare sparse matrix structure
            //
            if( state.nsparse==0 )
            {
                state.sparsec.matrixtype = 1;
                state.sparsec.m = 0;
                state.sparsec.n = n;
                state.sparsec.ninitialized = 0;
                apserv.ivectorsetlengthatleast(ref state.sparsec.ridx, 1, _params);
                state.sparsec.ridx[0] = 0;
            }
            alglib.ap.assert(state.sparsec.matrixtype==1 && state.sparsec.m==state.nsparse, "xlcAddLC2SparseFromDense: integrity check failed!");
            
            //
            // Reallocate inequality bounds
            //
            apserv.rvectorgrowto(ref state.scl, state.nsparse+1, _params);
            apserv.rvectorgrowto(ref state.scu, state.nsparse+1, _params);
            state.scl[state.nsparse] = al;
            state.scu[state.nsparse] = au;
            
            //
            // Determine nonzeros count.
            // Reallocate sparse storage.
            //
            nnz = 0;
            for(i=0; i<=n-1; i++)
            {
                if( !(da[i]==0.0) )
                {
                    nnz = nnz+1;
                }
            }
            offs = state.sparsec.ridx[state.nsparse];
            apserv.ivectorgrowto(ref state.sparsec.idx, offs+nnz, _params);
            apserv.rvectorgrowto(ref state.sparsec.vals, offs+nnz, _params);
            apserv.ivectorgrowto(ref state.sparsec.didx, state.nsparse+1, _params);
            apserv.ivectorgrowto(ref state.sparsec.uidx, state.nsparse+1, _params);
            apserv.ivectorgrowto(ref state.sparsec.ridx, state.nsparse+2, _params);
            
            //
            // If NNZ=0, perform quick and simple row append. 
            //
            if( nnz==0 )
            {
                state.sparsec.didx[state.nsparse] = state.sparsec.ridx[state.nsparse];
                state.sparsec.uidx[state.nsparse] = state.sparsec.ridx[state.nsparse];
                state.sparsec.ridx[state.nsparse+1] = state.sparsec.ridx[state.nsparse];
                apserv.inc(ref state.sparsec.m, _params);
                apserv.inc(ref state.nsparse, _params);
                return;
            }
            
            //
            // Now we are sure that SparseC contains properly initialized sparse
            // matrix (or some appropriate dummy for M=0) and we have NNZ>0
            // (no need to care about degenerate cases).
            //
            // Append rows to SparseC:
            // * append data
            // * compute DIdx and UIdx
            //
            //
            nzi = 0;
            for(i=0; i<=n-1; i++)
            {
                if( !(da[i]==0.0) )
                {
                    state.sparsec.idx[offs+nzi] = i;
                    state.sparsec.vals[offs+nzi] = da[i];
                    nzi = nzi+1;
                }
            }
            uidx = -1;
            didx = -1;
            for(j=offs; j<=offs+nnz-1; j++)
            {
                k = state.sparsec.idx[j];
                if( k==state.nsparse )
                {
                    didx = j;
                }
                else
                {
                    if( k>state.nsparse && uidx==-1 )
                    {
                        uidx = j;
                        break;
                    }
                }
            }
            if( uidx==-1 )
            {
                uidx = offs+nnz;
            }
            if( didx==-1 )
            {
                didx = uidx;
            }
            state.sparsec.didx[state.nsparse] = didx;
            state.sparsec.uidx[state.nsparse] = uidx;
            state.sparsec.ridx[state.nsparse+1] = offs+nnz;
            state.sparsec.ninitialized = state.sparsec.ridx[state.nsparse+1];
            apserv.inc(ref state.sparsec.m, _params);
            apserv.inc(ref state.nsparse, _params);
        }


        /*************************************************************************
        Converts linear constraints to the legacy dense single-sided format. Sets
        State.NEC, State.NIC, State.CLEIC, State.LCSrcIdx, State.LCSrcMult

        NOTE: this function ignores inconsistent bounds, like CL>CU, assuming that
              either they were already noticed, or will be noticed later.
        *************************************************************************/
        public static void xlcconverttoold(opts.xlinearconstraints state,
            alglib.xparams _params)
        {
            int i = 0;
            int k = 0;
            int k0 = 0;
            int k1 = 0;
            int idxoutec = 0;
            int idxoutic = 0;
            int dstrow0 = 0;
            int dstrow1 = 0;
            double vdst0 = 0;
            double vdst1 = 0;
            double rhsdst0 = 0;
            double rhsdst1 = 0;
            int n = 0;
            double vl = 0;
            double vu = 0;

            n = state.n;
            state.nec = 0;
            state.nic = 0;
            
            //
            // Compute required amount of single-sided constraints
            //
            for(i=0; i<=state.nsparse+state.ndense-1; i++)
            {
                if( i<state.nsparse )
                {
                    vl = state.scl[i];
                    vu = state.scu[i];
                }
                else
                {
                    vl = state.dcl[i-state.nsparse];
                    vu = state.dcu[i-state.nsparse];
                }
                alglib.ap.assert(math.isfinite(vl) || Double.IsNegativeInfinity(vl), "OPTSERV: integrity check 0354 failed");
                alglib.ap.assert(math.isfinite(vu) || Double.IsPositiveInfinity(vu), "OPTSERV: integrity check 0355 failed");
                if( (math.isfinite(vl) && math.isfinite(vu)) && (double)(vl)==(double)(vu) )
                {
                    state.nec = state.nec+1;
                    continue;
                }
                if( math.isfinite(vl) )
                {
                    state.nic = state.nic+1;
                }
                if( math.isfinite(vu) )
                {
                    state.nic = state.nic+1;
                }
            }
            if( state.nec+state.nic==0 )
            {
                return;
            }
            
            //
            // Convert two-sided constraints into single-sided
            //
            idxoutec = 0;
            idxoutic = state.nec;
            ablasf.rallocm(state.nec+state.nic, n+1, ref state.cleic, _params);
            ablasf.isetallocv(state.nec+state.nic, -1, ref state.lcsrcidx, _params);
            ablasf.rsetallocv(state.nec+state.nic, 0.0, ref state.lcsrcmult, _params);
            for(i=0; i<=state.nsparse+state.ndense-1; i++)
            {
                
                //
                // Extract bounds
                //
                if( i<state.nsparse )
                {
                    vl = state.scl[i];
                    vu = state.scu[i];
                }
                else
                {
                    vl = state.dcl[i-state.nsparse];
                    vu = state.dcu[i-state.nsparse];
                }
                
                //
                // Ignore non-binding rows
                //
                if( !math.isfinite(vl) && !math.isfinite(vu) )
                {
                    continue;
                }
                
                //
                // Analyze bounds
                //
                dstrow0 = -1;
                dstrow1 = -1;
                vdst0 = 0;
                vdst1 = 0;
                rhsdst0 = 0;
                rhsdst1 = 0;
                if( math.isfinite(vl) && math.isfinite(vu) )
                {
                    if( (double)(vl)==(double)(vu) )
                    {
                        
                        //
                        // Two bounds = equality constraints, one row is output
                        //
                        dstrow0 = idxoutec;
                        vdst0 = 1.0;
                        rhsdst0 = vl;
                        idxoutec = idxoutec+1;
                    }
                    else
                    {
                        
                        //
                        // Two bounds = range constraint, two rows are output
                        //
                        dstrow0 = idxoutic;
                        dstrow1 = idxoutic+1;
                        vdst0 = -1.0;
                        vdst1 = 1.0;
                        rhsdst0 = -vl;
                        rhsdst1 = vu;
                        idxoutic = idxoutic+2;
                    }
                }
                else
                {
                    
                    //
                    // Only one bound is present
                    //
                    if( math.isfinite(vl) )
                    {
                        dstrow0 = idxoutic;
                        vdst0 = -1.0;
                        rhsdst0 = -vl;
                        idxoutic = idxoutic+1;
                    }
                    if( math.isfinite(vu) )
                    {
                        dstrow0 = idxoutic;
                        vdst0 = 1.0;
                        rhsdst0 = vu;
                        idxoutic = idxoutic+1;
                    }
                }
                
                //
                // Extract row
                //
                alglib.ap.assert(idxoutec<=state.nec, "OPTSERV: integrity check 2607 failed");
                alglib.ap.assert(idxoutic<=state.nec+state.nic, "OPTSERV: integrity check 2608 failed");
                if( i<state.nsparse )
                {
                    
                    //
                    // Extract from the sparse matrix
                    //
                    if( dstrow0>=0 )
                    {
                        ablasf.rsetr(n, 0.0, state.cleic, dstrow0, _params);
                        k0 = state.sparsec.ridx[i];
                        k1 = state.sparsec.ridx[i+1]-1;
                        for(k=k0; k<=k1; k++)
                        {
                            state.cleic[dstrow0,state.sparsec.idx[k]] = vdst0*state.sparsec.vals[k];
                        }
                        state.cleic[dstrow0,n] = rhsdst0;
                    }
                    if( dstrow1>=0 )
                    {
                        ablasf.rsetr(n, 0.0, state.cleic, dstrow1, _params);
                        k0 = state.sparsec.ridx[i];
                        k1 = state.sparsec.ridx[i+1]-1;
                        for(k=k0; k<=k1; k++)
                        {
                            state.cleic[dstrow1,state.sparsec.idx[k]] = vdst1*state.sparsec.vals[k];
                        }
                        state.cleic[dstrow1,n] = rhsdst1;
                    }
                }
                else
                {
                    
                    //
                    // Copy from the dense matrix
                    //
                    if( dstrow0>=0 )
                    {
                        ablasf.rcopyrr(n, state.densec, i-state.nsparse, state.cleic, dstrow0, _params);
                        ablasf.rmulr(n, vdst0, state.cleic, dstrow0, _params);
                        state.cleic[dstrow0,n] = rhsdst0;
                    }
                    if( dstrow1>=0 )
                    {
                        ablasf.rcopyrr(n, state.densec, i-state.nsparse, state.cleic, dstrow1, _params);
                        ablasf.rmulr(n, vdst1, state.cleic, dstrow1, _params);
                        state.cleic[dstrow1,n] = rhsdst1;
                    }
                }
                if( dstrow0>=0 )
                {
                    state.lcsrcidx[dstrow0] = i;
                    state.lcsrcmult[dstrow0] = vdst0;
                }
                if( dstrow1>=0 )
                {
                    state.lcsrcidx[dstrow1] = i;
                    state.lcsrcmult[dstrow1] = vdst1;
                }
            }
        }


        /*************************************************************************
        Converts linear constraints to the modern 2-sided sparse-only format.

        Sets State.EffSparseA, State.EffAL, State.EffAU. After  these  fields  are
        set, they can be modified by the user (e.g. by adding rows and/or slack
        variables).

        Additionally sets State.LCSrcIdx to an identity map.

        NOTE: this function ignores inconsistent bounds, like CL>CU, assuming that
              either they were already noticed, or will be noticed later.
        *************************************************************************/
        public static void xlcconverttosparse(opts.xlinearconstraints state,
            alglib.xparams _params)
        {
            int i = 0;

            if( state.nsparse+state.ndense==0 )
            {
                return;
            }
            ablasf.rallocv(state.nsparse+state.ndense, ref state.effal, _params);
            ablasf.rallocv(state.nsparse+state.ndense, ref state.effau, _params);
            if( state.nsparse>0 )
            {
                sparse.sparsecopytocrsbuf(state.sparsec, state.effsparsea, _params);
                ablasf.rcopyvx(state.nsparse, state.scl, 0, state.effal, 0, _params);
                ablasf.rcopyvx(state.nsparse, state.scu, 0, state.effau, 0, _params);
            }
            else
            {
                sparse.sparsecreatecrsemptybuf(state.n, state.effsparsea, _params);
            }
            if( state.ndense>0 )
            {
                sparse.sparsecreatecrsfromdensebuf(state.densec, state.ndense, state.n, state.tmps, _params);
                sparse.sparseappendmatrix(state.effsparsea, state.tmps, _params);
                ablasf.rcopyvx(state.ndense, state.dcl, 0, state.effal, state.nsparse, _params);
                ablasf.rcopyvx(state.ndense, state.dcu, 0, state.effau, state.nsparse, _params);
            }
            ablasf.iallocv(state.nsparse+state.ndense, ref state.lcsrcidx, _params);
            for(i=0; i<=state.nsparse+state.ndense-1; i++)
            {
                state.lcsrcidx[i] = i;
            }
        }


        /*************************************************************************
        Append quadratic constraint given by a list of nonzeros
        *************************************************************************/
        public static void xqcaddqc2list(opts.xquadraticconstraints xqc,
            int[] qridx,
            int[] qcidx,
            double[] qvals,
            int qnnz,
            bool isupper,
            int[] bidx,
            double[] bvals,
            int bnnz,
            double cl,
            double cu,
            bool applyorigin,
            alglib.xparams _params)
        {
            int[] allitems = new int[0];
            opts.xquadraticconstraint c = null;
            int n = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            int offs = 0;
            double[] b = new double[0];
            sparse.sparsematrix q = new sparse.sparsematrix();

            n = xqc.n;
            c = new opts.xquadraticconstraint();
            
            //
            // Determine unique variable indexes
            //
            ablasf.iallocv(2*qnnz+bnnz, ref allitems, _params);
            offs = 0;
            for(i=0; i<=qnnz-1; i++)
            {
                if( (isupper && qcidx[i]>=qridx[i]) || (!isupper && qridx[i]>=qcidx[i]) )
                {
                    if( qvals[i]!=0 )
                    {
                        allitems[offs+0] = qridx[i];
                        allitems[offs+1] = qcidx[i];
                        offs = offs+2;
                    }
                }
            }
            for(i=0; i<=bnnz-1; i++)
            {
                if( bvals[i]!=0 )
                {
                    allitems[offs] = bidx[i];
                    offs = offs+1;
                }
            }
            if( offs==0 )
            {
                
                //
                // Quick exit
                //
                c.nvars = 0;
                c.applyorigin = applyorigin;
                c.cl = cl;
                c.cu = cu;
                xqc.constraints.append(c);
                return;
            }
            tsort.tagsortmiddlei(ref allitems, 0, offs, _params);
            alglib.ap.assert(allitems[0]>=0 && allitems[offs-1]<n, "xqcAddQC2List: one of nonzero indexes is outside of [0,N) range");
            c.nvars = 0;
            for(i=0; i<=offs-1; i++)
            {
                if( c.nvars==0 || c.varidx[c.nvars-1]!=allitems[i] )
                {
                    ablasf.igrowv(c.nvars+1, ref c.varidx, _params);
                    c.varidx[c.nvars] = allitems[i];
                    c.nvars = c.nvars+1;
                }
            }
            
            //
            // Save constraints
            //
            c.applyorigin = applyorigin;
            c.cl = cl;
            c.cu = cu;
            if( c.nvars>0 )
            {
                
                //
                // Compress B
                //
                ablasf.rsetallocv(c.nvars, 0.0, ref c.b, _params);
                for(i=0; i<=bnnz-1; i++)
                {
                    c.b[apserv.ibinarysearchexisting(c.varidx, 0, c.nvars, bidx[i], _params)] = bvals[i];
                }
                
                //
                // Compress Q
                //
                c.lowerq.m = c.nvars;
                c.lowerq.n = c.nvars;
                ablasf.isetallocv(c.nvars, 0, ref c.lowerq.didx, _params);
                for(k=0; k<=qnnz-1; k++)
                {
                    if( (isupper && qcidx[k]>=qridx[k]) || (!isupper && qridx[k]>=qcidx[k]) )
                    {
                        if( qvals[k]!=0.0 )
                        {
                            if( isupper )
                            {
                                i = apserv.ibinarysearchexisting(c.varidx, 0, c.nvars, qcidx[k], _params);
                            }
                            else
                            {
                                i = apserv.ibinarysearchexisting(c.varidx, 0, c.nvars, qridx[k], _params);
                            }
                            c.lowerq.didx[i] = c.lowerq.didx[i]+1;
                        }
                    }
                }
                ablasf.iallocv(c.nvars+1, ref c.lowerq.ridx, _params);
                c.lowerq.ridx[0] = 0;
                for(i=0; i<=c.nvars-1; i++)
                {
                    c.lowerq.ridx[i+1] = c.lowerq.ridx[i]+c.lowerq.didx[i];
                }
                ablasf.iallocv(c.lowerq.ridx[c.nvars], ref c.lowerq.idx, _params);
                ablasf.rallocv(c.lowerq.ridx[c.nvars], ref c.lowerq.vals, _params);
                ablasf.icopyv(c.nvars, c.lowerq.ridx, c.lowerq.didx, _params);
                for(k=0; k<=qnnz-1; k++)
                {
                    if( (isupper && qcidx[k]>=qridx[k]) || (!isupper && qridx[k]>=qcidx[k]) )
                    {
                        if( qvals[k]!=0.0 )
                        {
                            if( isupper )
                            {
                                i = apserv.ibinarysearchexisting(c.varidx, 0, c.nvars, qcidx[k], _params);
                                j = apserv.ibinarysearchexisting(c.varidx, 0, c.nvars, qridx[k], _params);
                            }
                            else
                            {
                                i = apserv.ibinarysearchexisting(c.varidx, 0, c.nvars, qridx[k], _params);
                                j = apserv.ibinarysearchexisting(c.varidx, 0, c.nvars, qcidx[k], _params);
                            }
                            offs = c.lowerq.didx[i];
                            c.lowerq.idx[offs] = j;
                            c.lowerq.vals[offs] = qvals[k];
                            c.lowerq.didx[i] = offs+1;
                        }
                    }
                }
                for(i=0; i<=c.nvars-1; i++)
                {
                    if( c.lowerq.didx[i]!=c.lowerq.ridx[i+1] )
                    {
                        alglib.ap.assert(false, "OPTSERV: integrity check 4227 failed");
                    }
                }
                sparse.sparsecreatecrsinplace(c.lowerq, _params);
            }
            xqc.constraints.append(c);
        }


        /*************************************************************************
        Append quadratic constraint given by dense quadratic matrix
        *************************************************************************/
        public static void xqcaddqc2dense(opts.xquadraticconstraints xqc,
            double[,] q,
            bool isupper,
            double[] b,
            double cl,
            double cu,
            bool applyorigin,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int j0 = 0;
            int j1 = 0;
            int offs = 0;
            int n = 0;
            double vq = 0;
            opts.xquadraticconstraint c = null;

            alglib.ap.assert(math.isfinite(cl) || Double.IsNegativeInfinity(cl), "xqcAppendDense: CL is not finite or -INF");
            alglib.ap.assert(math.isfinite(cu) || Double.IsPositiveInfinity(cu), "xqcAppendDense: CU is not finite or +INF");
            n = xqc.n;
            c = new opts.xquadraticconstraint();
            
            //
            // Determine working variables
            //
            ablasf.isetallocv(n, 0, ref xqc.tmpi, _params);
            for(i=0; i<=n-1; i++)
            {
                if( b[i]!=0.0 )
                {
                    xqc.tmpi[i] = 1;
                }
            }
            for(i=0; i<=n-1; i++)
            {
                if( isupper )
                {
                    j0 = i;
                    j1 = n-1;
                }
                else
                {
                    j0 = 0;
                    j1 = i;
                }
                for(j=j0; j<=j1; j++)
                {
                    if( q[i,j]!=0.0 )
                    {
                        xqc.tmpi[i] = 1;
                        xqc.tmpi[j] = 1;
                    }
                }
            }
            c.nvars = 0;
            for(i=0; i<=n-1; i++)
            {
                if( xqc.tmpi[i]!=0 )
                {
                    ablasf.igrowv(c.nvars+1, ref c.varidx, _params);
                    c.varidx[c.nvars] = i;
                    c.nvars = c.nvars+1;
                }
            }
            
            //
            // Save constraints
            //
            c.applyorigin = applyorigin;
            c.cl = cl;
            c.cu = cu;
            if( c.nvars>0 )
            {
                ablasf.rallocv(c.nvars, ref c.b, _params);
                for(i=0; i<=c.nvars-1; i++)
                {
                    c.b[i] = b[c.varidx[i]];
                }
                c.lowerq.m = c.nvars;
                c.lowerq.n = c.nvars;
                ablasf.iallocv(c.nvars+1, ref c.lowerq.ridx, _params);
                c.lowerq.ridx[0] = 0;
                for(i=0; i<=c.nvars-1; i++)
                {
                    offs = c.lowerq.ridx[i];
                    ablasf.igrowv(offs+c.nvars, ref c.lowerq.idx, _params);
                    ablasf.rgrowv(offs+c.nvars, ref c.lowerq.vals, _params);
                    for(j=0; j<=i; j++)
                    {
                        if( isupper )
                        {
                            vq = q[c.varidx[j],c.varidx[i]];
                        }
                        else
                        {
                            vq = q[c.varidx[i],c.varidx[j]];
                        }
                        if( vq!=0.0 || j==i )
                        {
                            c.lowerq.idx[offs] = j;
                            c.lowerq.vals[offs] = vq;
                            offs = offs+1;
                        }
                    }
                    c.lowerq.ridx[i+1] = offs;
                }
                sparse.sparsecreatecrsinplace(c.lowerq, _params);
            }
            xqc.constraints.append(c);
        }


