        /*************************************************************************
        Initialize conic constraints structure
        *************************************************************************/
        public static void xccinit(int n,
            opts.xconicconstraints state,
            alglib.xparams _params)
        {
            alglib.ap.assert(n>=1, "qccInit: N<1");
            state.n = n;
            state.constraints.clear();
        }


        /*************************************************************************
        Clear quadratic constraints structure
        *************************************************************************/
        public static void xccclear(opts.xconicconstraints state,
            alglib.xparams _params)
        {
            state.constraints.clear();
        }


        /*************************************************************************
        Update N, only larger values are possible
        *************************************************************************/
        public static void xccupdaten(opts.xconicconstraints state,
            int newn,
            alglib.xparams _params)
        {
            alglib.ap.assert(newn>=state.n, "xccUpdateN: newN<N");
            state.n = newn;
        }


        /*************************************************************************
        Copies conic constraints structure, target structure is cleared,
        previously allocated memory is ignored.
        *************************************************************************/
        public static void xcccopy(opts.xconicconstraints src,
            opts.xconicconstraints dst,
            alglib.xparams _params)
        {
            int i = 0;
            int m = 0;
            opts.xconicconstraint c = null;
            opts.xconicconstraint c1 = null;
            bool donecc = new bool();

            dst.n = src.n;
            m = src.constraints.getlength();
            dst.constraints.clear();
            for(i=0; i<=m-1; i++)
            {
                src.constraints.get(i, ref c);
                c1 = new opts.xconicconstraint();
                donecc = false;
                c1.conetype = c.conetype;
                c1.nvars = c.nvars;
                c1.applyorigin = c.applyorigin;
                if( c.conetype==-1 || c.conetype==1 )
                {
                    
                    //
                    // Canonic/noncanonic orthogonal cones
                    //
                    if( c.nvars>0 )
                    {
                        ablasf.icopyallocv(c.nvars, c.varidx, ref c1.varidx, _params);
                        ablasf.rcopyallocv(c.nvars, c.diaga, ref c1.diaga, _params);
                        ablasf.rcopyallocv(c.nvars+1, c.shftc, ref c1.shftc, _params);
                    }
                    donecc = true;
                }
                if( c.conetype==xccgenericorthogonalpowerconetype(_params) || c.conetype==xccprimitivepowerconetype(_params) )
                {
                    
                    //
                    // Power cones
                    //
                    alglib.ap.assert(c.nvars>0, "xccCopy: integrity check 561151 failed");
                    ablasf.icopyallocv(c.nvars, c.varidx, ref c1.varidx, _params);
                    ablasf.rcopyallocv(c.nvars, c.diaga, ref c1.diaga, _params);
                    ablasf.rcopyallocv(c.nvars+1, c.shftc, ref c1.shftc, _params);
                    c1.kpow = c.kpow;
                    ablasf.rcopyallocv(c.kpow, c.alphapow, ref c1.alphapow, _params);
                    donecc = true;
                }
                alglib.ap.assert(donecc, "xccCopy: unexpected cone type");
                dst.constraints.append(c1);
            }
        }


        /*************************************************************************
        Copies conic constraints structure, skipping some constraints and permuting
        variables using so-called 'pack' permutation that monotonically maps increasing
        indexes into increasing indexes.

        The target structure is cleared, previously allocated memory is ignored.
        *************************************************************************/
        public static void xcccopywithskipandpack(opts.xconicconstraints src,
            bool[] skipflags,
            int[] packxperm,
            opts.xconicconstraints dst,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int srcm = 0;
            opts.xconicconstraint c = null;
            opts.xconicconstraint c1 = null;
            bool donecc = new bool();

            dst.n = src.n;
            srcm = src.constraints.getlength();
            dst.constraints.clear();
            for(i=0; i<=srcm-1; i++)
            {
                if( !skipflags[i] )
                {
                    src.constraints.get(i, ref c);
                    c1 = new opts.xconicconstraint();
                    donecc = false;
                    c1.conetype = c.conetype;
                    c1.nvars = c.nvars;
                    c1.applyorigin = c.applyorigin;
                    if( c.conetype==-1 || c.conetype==1 )
                    {
                        
                        //
                        // Canonic/noncanonic orthogonal cones
                        //
                        if( c.nvars>0 )
                        {
                            ablasf.rcopyallocv(c.nvars, c.diaga, ref c1.diaga, _params);
                            ablasf.rcopyallocv(c.nvars+1, c.shftc, ref c1.shftc, _params);
                            ablasf.iallocv(c.nvars, ref c1.varidx, _params);
                            for(j=0; j<=c.nvars-1; j++)
                            {
                                c1.varidx[j] = packxperm[c.varidx[j]];
                            }
                        }
                        donecc = true;
                    }
                    if( c.conetype==xccprimitivepowerconetype(_params) )
                    {
                        
                        //
                        // Power cones
                        //
                        alglib.ap.assert(c.nvars>0, "OPTSERV: integrity check 625237 failed");
                        ablasf.rcopyallocv(c.nvars, c.diaga, ref c1.diaga, _params);
                        ablasf.rcopyallocv(c.nvars+1, c.shftc, ref c1.shftc, _params);
                        ablasf.iallocv(c.nvars, ref c1.varidx, _params);
                        for(j=0; j<=c.nvars-1; j++)
                        {
                            c1.varidx[j] = packxperm[c.varidx[j]];
                        }
                        c1.kpow = c.kpow;
                        ablasf.rcopyallocv(c.kpow, c.alphapow, ref c1.alphapow, _params);
                        donecc = true;
                    }
                    alglib.ap.assert(donecc, "xccCopyWithSkipAndPack: unexpected cone type");
                    dst.constraints.append(c1);
                }
            }
        }


        /*************************************************************************
        Get constraints count
        *************************************************************************/
        public static int xccgetcount(opts.xconicconstraints xcc,
            alglib.xparams _params)
        {
            int result = 0;

            result = xcc.constraints.getlength();
            return result;
        }


        /*************************************************************************
        Adds noncanonic orthogonal second order cone.

        INPUT PARAMETERS:
            XCC         -   a set of conic constraints
            VarIdx      -   array[NVars], can be unsorted and non-distinct
            Diag        -   array[NVars], diagonal multipliers before variables
            Shft        -   array[NVars], shifts applied to variables
            NVars       -   1<=NVars, variables count (can be larger than N).
                            The last variable is the cone axis.
            Theta       -   theta^2 is added to the term under the square root
            ApplyOrigin -   whether conic constraint applies as f(x-origin)<=0
                            (ApplyOrigin=True) or as f(x)<=0.
        *************************************************************************/
        public static void xccaddsoccorthogonalnoncanonic(opts.xconicconstraints xcc,
            int[] varidx,
            double[] diag,
            double[] shft,
            int nvars,
            double theta,
            bool applyorigin,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            opts.xconicconstraint c = null;

            n = xcc.n;
            alglib.ap.assert(nvars>=1, "xccAddSOCCOrthogonalNoncanonic: NVars<1");
            alglib.ap.assert(alglib.ap.len(varidx)>=nvars, "xccAddSOCCOrthogonalNoncanonic: len(VarIdx)<NVars");
            alglib.ap.assert(alglib.ap.len(diag)>=nvars, "xccAddSOCCOrthogonalNoncanonic: len(Diag)<NVars");
            alglib.ap.assert(alglib.ap.len(shft)>=nvars, "xccAddSOCCOrthogonalNoncanonic: len(Shft)<NVars");
            for(i=0; i<=nvars-1; i++)
            {
                alglib.ap.assert(varidx[i]>=0 && varidx[i]<n, "xccAddSOCCOrthogonalNoncanonic: VarIdx[] contains values outside of [0,N)");
                alglib.ap.assert(math.isfinite(diag[i]), "xccAddSOCCOrthogonalNoncanonic: Diaga[] contains infinite values");
                alglib.ap.assert(math.isfinite(shft[i]), "xccAddSOCCOrthogonalNoncanonic: Shft[] contains infinite values");
            }
            alglib.ap.assert(math.isfinite(theta), "xccAddSOCCOrthogonalNoncanonic: theta is not a finite number");
            c = new opts.xconicconstraint();
            c.conetype = -1;
            c.nvars = nvars;
            c.applyorigin = applyorigin;
            ablasf.icopyallocv(nvars, varidx, ref c.varidx, _params);
            ablasf.rcopyallocv(nvars, diag, ref c.diaga, _params);
            ablasf.rallocv(nvars+1, ref c.shftc, _params);
            ablasf.rcopyv(nvars, shft, c.shftc, _params);
            c.shftc[nvars] = theta*theta;
            xcc.constraints.append(c);
        }


        /*************************************************************************
        Adds canonic primitive second order cone. The canonic primitive  cone  has
        requirement that all variables are distinct.

        INPUT PARAMETERS:
            XCC         -   a set of conic constraints
            VarIdx      -   array[NVars], sorted by ascending (except for the
                            last element)
            Diag        -   array[NVars], diagonal multipliers before variables
            Shft        -   array[NVars], shifts applied to variables
            NVars       -   1<=NVars<=N, variables count. The last variable is the
                            cone axis.
            ApplyOrigin -   whether conic constraint applies as f(x-origin)<=0
                            (ApplyOrigin=True) or as f(x)<=0.
        *************************************************************************/
        public static void xccaddsoccprimitivecanonic(opts.xconicconstraints xcc,
            int[] varidx,
            double[] diag,
            double[] shft,
            int nvars,
            bool applyorigin,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            opts.xconicconstraint c = null;

            n = xcc.n;
            alglib.ap.assert(nvars>=1 && nvars<=xcc.n, "xccAddSOCCPrimitiveCanonic: NVars<1 or NVars>N");
            alglib.ap.assert(varidx[0]>=0 && varidx[0]<n, "xccAddSOCCPrimitiveCanonic: VarIdx[] contains values outside of [0,N)");
            alglib.ap.assert(varidx[nvars-1]>=0 && varidx[nvars-1]<n, "xccAddSOCCPrimitiveCanonic: VarIdx[] contains values outside of [0,N)");
            for(i=1; i<=nvars-2; i++)
            {
                alglib.ap.assert(varidx[i]>varidx[i-1], "xccAddSOCCPrimitiveCanonic: VarIdx[] is unsorted and/or has nondistinct values");
                alglib.ap.assert(varidx[i]<n, "xccAddSOCCPrimitiveCanonic: VarIdx[] contains values outside of [0,N)");
            }
            c = new opts.xconicconstraint();
            c.conetype = 1;
            c.nvars = nvars;
            c.applyorigin = applyorigin;
            ablasf.icopyallocv(nvars, varidx, ref c.varidx, _params);
            ablasf.rcopyallocv(nvars, diag, ref c.diaga, _params);
            ablasf.rallocv(nvars+1, ref c.shftc, _params);
            ablasf.rcopyv(nvars, shft, c.shftc, _params);
            c.shftc[nvars] = 0.0;
            xcc.constraints.append(c);
        }


        /*************************************************************************
        Adds canonic primitive power cone. The canonic primitive  cone  has
        requirement that all variables are distinct.

        INPUT PARAMETERS:
            XCC         -   a set of conic constraints
            VarIdx      -   array[NVars]:
                            * first NVars-KPow elements are sorted by ascending,
                              all elements within the subsequence are distinct
                            * last KPow elements are sorted by ascending,
                              all elements within the subsequence are distinct
            Diag        -   array[NVars], diagonal multipliers before variables;
                            Diag[i] is nonzero for NVars-KPow <= i < NVars.
            Shft        -   array[NVars], shifts applied to variables
            NVars       -   1<=NVars<=N, variables count. The last KPow variables
                            are the cone axis.
            AlphaPow    -   array[KPow], powers:
                            * AlphaPow[I]>0
                            * 0 < SUM(AlphaPow[]) <= 1
            KPow        -   1<=NPow<=NVars
            ApplyOrigin -   whether conic constraint applies as f(x-origin)<=0
                            (ApplyOrigin=True) or as f(x)<=0.
        *************************************************************************/
        public static void xccaddpowccprimitivecanonic(opts.xconicconstraints xcc,
            int[] varidx,
            double[] diag,
            double[] shft,
            int nvars,
            double[] alphapow,
            int kpow,
            bool applyorigin,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            opts.xconicconstraint c = null;
            double vs = 0;

            n = xcc.n;
            alglib.ap.assert(nvars>=1 && nvars<=xcc.n, "xccAddPOWCCPrimitiveCanonic: NVars<1 or NVars>N");
            alglib.ap.assert(kpow>=1 && kpow<=nvars, "xccAddPOWCCPrimitiveCanonic: KPow<1 or KPow>NVars");
            if( kpow<nvars )
            {
                alglib.ap.assert(varidx[0]>=0 && varidx[0]<n, "xccAddPOWCCPrimitiveCanonic: VarIdx[] contains values outside of [0,N)");
                alglib.ap.assert(varidx[nvars-kpow-1]>=0 && varidx[nvars-kpow-1]<n, "xccAddPOWCCPrimitiveCanonic: VarIdx[] contains values outside of [0,N)");
                for(i=1; i<=nvars-kpow-2; i++)
                {
                    alglib.ap.assert(varidx[i]>varidx[i-1], "xccAddPOWCCPrimitiveCanonic: VarIdx[] is unsorted and/or has nondistinct values");
                    alglib.ap.assert(varidx[i]<n, "xccAddPOWCCPrimitiveCanonic: VarIdx[] contains values outside of [0,N)");
                }
            }
            alglib.ap.assert(varidx[nvars-kpow]>=0 && varidx[nvars-kpow]<n, "xccAddPOWCCPrimitiveCanonic: VarIdx[] contains values outside of [0,N)");
            alglib.ap.assert(varidx[nvars-1]>=0 && varidx[nvars-1]<n, "xccAddPOWCCPrimitiveCanonic: VarIdx[] contains values outside of [0,N)");
            for(i=nvars-kpow+1; i<=nvars-1; i++)
            {
                alglib.ap.assert(varidx[i]>varidx[i-1], "xccAddPOWCCPrimitiveCanonic: VarIdx[] is unsorted and/or has nondistinct values");
                alglib.ap.assert(varidx[i]<n, "xccAddPOWCCPrimitiveCanonic: VarIdx[] contains values outside of [0,N)");
            }
            vs = 0;
            for(i=0; i<=kpow-1; i++)
            {
                alglib.ap.assert(math.isfinite(alphapow[i]), "xccAddPOWCCPrimitiveCanonic: AlphaPow[] contains INF/NAN values");
                alglib.ap.assert((double)(alphapow[i])>(double)(0) && (double)(alphapow[i])<=(double)(1), "xccAddPOWCCPrimitiveCanonic: AlphaPow[] is outside of (0,1]");
                alglib.ap.assert((double)(diag[nvars-kpow+i])!=(double)(0), "xccAddPOWCCPrimitiveCanonic: scaling coefficient for power terms is zero");
                vs = vs+alphapow[i];
            }
            alglib.ap.assert((double)(vs)>(double)(0) && (double)(vs)<=(double)(1+10*kpow*math.machineepsilon), "xccAddPOWCCPrimitiveCanonic: AlphaPow[] sum is is outside of (0,1]");
            c = new opts.xconicconstraint();
            c.conetype = xccprimitivepowerconetype(_params);
            c.nvars = nvars;
            c.kpow = kpow;
            c.applyorigin = applyorigin;
            ablasf.icopyallocv(nvars, varidx, ref c.varidx, _params);
            ablasf.rcopyallocv(nvars, diag, ref c.diaga, _params);
            ablasf.rallocv(nvars+1, ref c.shftc, _params);
            ablasf.rcopyv(nvars, shft, c.shftc, _params);
            c.shftc[nvars] = 0.0;
            ablasf.rcopyallocv(kpow, alphapow, ref c.alphapow, _params);
            xcc.constraints.append(c);
        }


        /*************************************************************************
        Adds noncanonic orthogonal second order cone.

        INPUT PARAMETERS:
            XCC         -   a set of conic constraints
            VarIdx      -   array[NVars], can be unsorted and non-distinct
            Diag        -   array[NVars], diagonal multipliers before variables
            Shft        -   array[NVars], shifts applied to variables
            NVars       -   1<=NVars, variables count (can be larger than N).
                            The last variable is the cone axis.
            Theta       -   theta^2 is added to the term under the square root
            AlphaPow    -   array[KPow], power coeffs
            KPow        -   1<=KPow<=NVars, number of power terms
            ApplyOrigin -   whether conic constraint applies as f(x-origin)<=0
                            (ApplyOrigin=True) or as f(x)<=0.
        *************************************************************************/
        public static void xccaddpowccorthogonalnoncanonic(opts.xconicconstraints xcc,
            int[] varidx,
            double[] diag,
            double[] shft,
            int nvars,
            double theta,
            double[] alphapow,
            int kpow,
            bool applyorigin,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            double vs = 0;
            opts.xconicconstraint c = null;

            n = xcc.n;
            alglib.ap.assert(nvars>=1, "xccAddPOWCCOrthogonalNoncanonic: NVars<1");
            alglib.ap.assert(alglib.ap.len(varidx)>=nvars, "xccAddPOWCCOrthogonalNoncanonic: len(VarIdx)<NVars");
            alglib.ap.assert(alglib.ap.len(diag)>=nvars, "xccAddPOWCCOrthogonalNoncanonic: len(Diag)<NVars");
            alglib.ap.assert(alglib.ap.len(shft)>=nvars, "xccAddPOWCCOrthogonalNoncanonic: len(Shft)<NVars");
            for(i=0; i<=nvars-1; i++)
            {
                alglib.ap.assert(varidx[i]>=0 && varidx[i]<n, "xccAddPOWCCOrthogonalNoncanonic: VarIdx[] contains values outside of [0,N)");
                alglib.ap.assert(math.isfinite(diag[i]), "xccAddPOWCCOrthogonalNoncanonic: Diaga[] contains infinite values");
                alglib.ap.assert(math.isfinite(shft[i]), "xccAddPOWCCOrthogonalNoncanonic: Shft[] contains infinite values");
            }
            alglib.ap.assert(math.isfinite(theta), "xccAddPOWCCOrthogonalNoncanonic: theta is not a finite number");
            vs = 0;
            for(i=0; i<=kpow-1; i++)
            {
                alglib.ap.assert(math.isfinite(alphapow[i]), "xccAddPOWCCOrthogonalNoncanonic: AlphaPow[] contains INF/NAN values");
                alglib.ap.assert((double)(alphapow[i])>(double)(0) && (double)(alphapow[i])<=(double)(1), "xccAddPOWCCOrthogonalNoncanonic: AlphaPow[] is outside of (0,1]");
                vs = vs+alphapow[i];
            }
            alglib.ap.assert((double)(vs)>(double)(0) && (double)(vs)<=(double)(1+10*kpow*math.machineepsilon), "xccAddPOWCCOrthogonalNoncanonic: AlphaPow[] sum is is outside of (0,1]");
            c = new opts.xconicconstraint();
            c.conetype = xccgenericorthogonalpowerconetype(_params);
            c.nvars = nvars;
            c.kpow = kpow;
            c.applyorigin = applyorigin;
            ablasf.icopyallocv(nvars, varidx, ref c.varidx, _params);
            ablasf.rcopyallocv(nvars, diag, ref c.diaga, _params);
            ablasf.rallocv(nvars+1, ref c.shftc, _params);
            ablasf.rcopyv(nvars, shft, c.shftc, _params);
            c.shftc[nvars] = theta*theta;
            ablasf.rcopyallocv(kpow, alphapow, ref c.alphapow, _params);
            xcc.constraints.append(c);
        }


        /*************************************************************************
        Factors out non-axial variable K0 from a conic constraint by making a
        substitution X[k0]:=alpha0 + alpha1*X[k1]. Both K0 and K1 must be non-axial
        variables. If Alpha1 is zero, then K1 must be equal to -1.

        Returns:
        * HadK0     -   True if K0 was found in the original (unmodified) VarIdx[].
                        If HadK0=False it means that no modification was applied.
        * HadK1     -   True if K1 was found in the original (unmodified) VarIdx[]

        Works with the following cones:
        * xccPrimitiveConeType()

          -- ALGLIB --
             Copyright 01.11.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void xccfactoroutnonaxial(opts.xconicconstraint c,
            int k0,
            double alpha0,
            double alpha1,
            int k1,
            ref bool hadk0,
            ref bool hadk1,
            alglib.xparams _params)
        {
            int nv = 0;
            int nradial = 0;
            int localk0 = 0;
            int localk1 = 0;
            int j = 0;
            double a0 = 0;
            double a1 = 0;
            double c0 = 0;
            double c1 = 0;
            double f = 0;
            double g = 0;
            double h = 0;

            hadk0 = new bool();
            hadk1 = new bool();

            nv = c.nvars;
            hadk0 = false;
            hadk1 = false;
            if( nv==0 )
            {
                return;
            }
            if( c.conetype==xccprimitiveconetype(_params) || c.conetype==xccprimitivepowerconetype(_params) )
            {
                
                //
                // Analyze cone
                //
                nradial = -1;
                if( c.conetype==xccprimitiveconetype(_params) )
                {
                    nradial = nv-1;
                    alglib.ap.assert(c.varidx[nv-1]!=k0 && c.varidx[nv-1]!=k1, "xccFactorOutNonAxial: K0 or K1 is an axial variable for the cone");
                }
                if( c.conetype==xccprimitivepowerconetype(_params) )
                {
                    nradial = nv-c.kpow;
                    alglib.ap.assert(!apserv.ilinearsearchispresent(c.varidx, nradial, nv, k0, _params) && !apserv.ilinearsearchispresent(c.varidx, nradial, nv, k1, _params), "xccFactorOutNonAxial: K0 or K1 is an axial variable for the power cone");
                }
                alglib.ap.assert(nradial>=1, "xccFactorOutNonAxial: unrecognized cone type");
                
                //
                // Determine variable locations in the array
                // Quick exit if variable K0 is not found
                //
                localk0 = -1;
                localk1 = -1;
                for(j=0; j<=nradial-1; j++)
                {
                    if( c.varidx[j]==k0 )
                    {
                        localk0 = j;
                    }
                    if( c.varidx[j]==k1 )
                    {
                        localk1 = j;
                    }
                }
                hadk0 = localk0>=0;
                hadk1 = localk1>=0;
                if( localk0<0 )
                {
                    return;
                }
                if( (double)(alpha1)==(double)(0) )
                {
                    alglib.ap.assert(k1==-1, "xccFactorOutNonAxial: alpha1=0, but K1 is different from -1");
                    c.shftc[nv] = c.shftc[nv]+math.sqr(c.diaga[localk0]*alpha0+c.shftc[localk0]);
                    for(j=localk0; j<=nv-2; j++)
                    {
                        c.varidx[j] = c.varidx[j+1];
                        c.diaga[j] = c.diaga[j+1];
                        c.shftc[j] = c.shftc[j+1];
                    }
                    c.shftc[nv-1] = c.shftc[nv];
                    c.nvars = nv-1;
                    return;
                }
                alglib.ap.assert(k1>=0, "xccFactorOutNonAxial: alpha1<>0, but K1 negative");
                
                //
                // Different algorithms for K1 being present or absent
                //
                if( localk1<0 )
                {
                    
                    //
                    // The element K1 is not present, we can simply replace K0 by K1 as follows. Let A0 and
                    // C0 are multiplier and shift for K0. Substituting Xk0:=Alpha0+Xk1*Alpha1 gives us
                    //
                    //     (A0*Xk0+C0)^2 =
                    //     = (A0*(Alpha0+Xk1*Alpha1)+C0)^2 =
                    //     = (A0*Alpha1*Xk1+(C0+A0*Alpha0))^2
                    //
                    a0 = c.diaga[localk0];
                    c0 = c.shftc[localk0];
                    c.varidx[localk0] = k1;
                    c.diaga[localk0] = a0*alpha1;
                    c.shftc[localk0] = c0+a0*alpha0;
                    tsort.tagsortmiddleirr(c.varidx, c.diaga, c.shftc, 0, nradial, _params);
                }
                else
                {
                    
                    //
                    // The element K1 is present.
                    //
                    // Let A0 and C0 are multiplier and shift for K0, and similarly A1 and C1 are multiplier
                    // and shift for K1. Substituting Xk0:=Alpha0+Xk1*Alpha1 gives us
                    //
                    //     (A0*Xk0+C0)^2 + (A1*Xk1+C1)^2 =
                    //     = (A0*(Alpha0+Xk1*Alpha1)+C0)^2 + (A1*Xk1+C1)^2 =
                    //     = (A0*Alpha1*Xk1+C0+A0*Alpha0)^2 + (A1*Xk1+C1)^2 =
                    //     = (A0*Alpha1)^2*Xk1^2 + 2*(A0*Alpha1)*(C0+A0*Alpha0)*Xk1 + (C0+A0*Alpha0)^2 + A1^2*Xk1^2 + 2*A1*C1*Xk1 + C1^2 =
                    //     = ((A0*Alpha1)^2+A1^2)*Xk1^2 + 2*((A0*Alpha1)*(C0+A0*Alpha0)+A1*C1)*Xk1 + ((C0+A0*Alpha0)^2+C1^2) =
                    //     = f^2*Xk1^2 + 2*g*Xk1 + h =
                    //     = (f*Xk1)^2 + 2*(g/f)*(f*Xk1) + (g/f)^2 + h-(g/f)^2 =
                    //     = (f*Xk1 + g/f)^2 + h-(g/f)^2
                    //
                    // Modify coefficients for K1.
                    //
                    a0 = c.diaga[localk0];
                    a1 = c.diaga[localk1];
                    c0 = c.shftc[localk0];
                    c1 = c.shftc[localk1];
                    f = Math.Sqrt(a0*alpha1*(a0*alpha1)+a1*a1);
                    g = a0*alpha1*(c0+a0*alpha0)+a1*c1;
                    h = (c0+a0*alpha0)*(c0+a0*alpha0)+c1*c1;
                    alglib.ap.assert((double)(f)>(double)(0), "xccFactorOutNonAxial: diagonal term is zero");
                    c.diaga[localk1] = f;
                    c.shftc[localk1] = g/f;
                    c.shftc[nv] = c.shftc[nv]+Math.Max(h-g/f*(g/f), 0.0);
                    
                    //
                    // Remove K0 
                    //
                    for(j=localk0; j<=nv-2; j++)
                    {
                        c.varidx[j] = c.varidx[j+1];
                        c.diaga[j] = c.diaga[j+1];
                        c.shftc[j] = c.shftc[j+1];
                    }
                    c.shftc[nv-1] = c.shftc[nv];
                    c.nvars = nv-1;
                }
                return;
            }
            alglib.ap.assert(false, "xccFactorOutNonAxial: unexpected cone type");
        }


        /*************************************************************************
        Unscales X (converts from scaled variables to original ones), paying special
        attention to box constraints (output is always feasible; active constraints
        are mapped to active ones).

        Can handle batch requests.

        Parameters:
            XS              array[N*BatchSize] - scaled variables. The function
                            assumes that vars are feasible with respect to SCALED
                            box constraints.
            SclFiniteBndL,
            SclFiniteBndU   array[N], lower/upper bounds for SCALED variables with
                            infinities being replaced by big numbers
            RawFiniteBndL,
            RawFiniteBndU   array[N], lower/upper bounds for ORIGINAL variables with
                            infinities being replaced by big numbers
                            
        output:
            XU              array[N*BatchSize], vars after unscaling
        *************************************************************************/
        public static void unscalexbatchfinitebnd(double[] xs,
            int batchsize,
            double[] s,
            int n,
            double[] sclfinitebndl,
            double[] sclfinitebndu,
            double[] rawfinitebndl,
            double[] rawfinitebndu,
            double[] xu,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            double vs = 0;

            if( unscalexbatchfinitebndkernel(xs, batchsize, s, n, sclfinitebndl, sclfinitebndu, rawfinitebndl, rawfinitebndu, xu, _params) )
            {
                return;
            }
            for(k=0; k<=batchsize-1; k++)
            {
                for(j=0; j<=n-1; j++)
                {
                    i = k*n+j;
                    vs = xs[i];
                    if( vs<=sclfinitebndl[j] )
                    {
                        xu[i] = rawfinitebndl[j];
                        continue;
                    }
                    if( vs>=sclfinitebndu[j] )
                    {
                        xu[i] = rawfinitebndu[j];
                        continue;
                    }
                    xu[i] = vs*s[j];
                    if( xu[i]<rawfinitebndl[j] )
                    {
                        xu[i] = rawfinitebndl[j];
                    }
                    if( xu[i]>rawfinitebndu[j] )
                    {
                        xu[i] = rawfinitebndu[j];
                    }
                }
            }
        }


        /*************************************************************************
        This function calculates feasibility error (square root of sum of  squared
        errors) for a Kx(NMain+NSlack) system of linear equalities.
            
        INPUT PARAMETERS:
            CE      -   set of K equality constraints, array[K,NMain+NSlack+1]
            X       -   candidate point, array [NMain+NSlack]
            NMain   -   number of primary variables
            NSlack  -   number of slack variables
            K       -   number of constraints
            Tmp0    -   possible preallocated buffer, automatically resized

        RESULT:
            Sqrt(SUM(Err^2))
            
          -- ALGLIB --
             Copyright 17.09.2015 by Bochkanov Sergey
        *************************************************************************/
        private static double feasibilityerror(double[,] ce,
            double[] x,
            int nmain,
            int nslack,
            int k,
            ref double[] tmp0,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;

            apserv.rvectorsetlengthatleast(ref tmp0, k, _params);
            for(i=0; i<=k-1; i++)
            {
                tmp0[i] = -ce[i,nmain+nslack];
            }
            ablas.rmatrixgemv(k, nmain+nslack, 1.0, ce, 0, 0, 0, x, 0, 1.0, tmp0, 0, _params);
            result = 0.0;
            for(i=0; i<=k-1; i++)
            {
                result = result+tmp0[i]*tmp0[i];
            }
            result = Math.Sqrt(result);
            return result;
        }


        /*************************************************************************
        This function calculates feasibility error (square root of sum of  squared
        errors) for a Kx(NMain+NSlack)  system  of  linear  equalities  and  error
        gradient (with respect to x)
            
        INPUT PARAMETERS:
            CE      -   set of K equality constraints, array[K,NMain+NSlack+1]
            X       -   candidate point, array [NMain+NSlack]
            NMain   -   number of primary variables
            NSlack  -   number of slack variables
            K       -   number of constraints
            Grad    -   preallocated array[NMain+NSlack]
            Tmp0    -   possible preallocated buffer, automatically resized

        RESULT:
            Err     -   Sqrt(SUM(Err^2))
            Grad    -   error gradient with respect to X, array[NMain+NSlack]
            
          -- ALGLIB --
             Copyright 17.09.2015 by Bochkanov Sergey
        *************************************************************************/
        private static void feasibilityerrorgrad(double[,] ce,
            double[] x,
            int nmain,
            int nslack,
            int k,
            ref double err,
            double[] grad,
            ref double[] tmp0,
            alglib.xparams _params)
        {
            int i = 0;
            double v = 0;

            err = 0;

            alglib.ap.assert(alglib.ap.len(grad)>=nmain+nslack, "FeasibilityErrorGrad: integrity check failed");
            apserv.rvectorsetlengthatleast(ref tmp0, k, _params);
            ablas.rmatrixgemv(k, nmain+nslack, 1.0, ce, 0, 0, 0, x, 0, 0.0, tmp0, 0, _params);
            err = 0.0;
            for(i=0; i<=k-1; i++)
            {
                v = tmp0[i]-ce[i,nmain+nslack];
                tmp0[i] = v;
                err = err+v*v;
            }
            err = Math.Sqrt(err);
            ablas.rmatrixgemv(nmain+nslack, k, 1.0, ce, 0, 0, 1, tmp0, 0, 0.0, grad, 0, _params);
        }


        /*************************************************************************
        This  subroutine  checks  C0  continuity  and  returns  continuity  rating
        (normalized value, with values above 50-500 being good indication  of  the
        discontinuity) and Lipschitz constant.

        An interval between F1 and F2 is  tested  for  (dis)continuity.  Per-point
        noise estimates are provided. Delta[i] is a step from F[i] to F[i+1].

        ApplySpecialCorrection parameter should be set to True  if  you  use  this
        function to estimate continuity of  the  model  around  minimum;  it  adds
        special correction which helps to detect "max(0,1/x)"-like discontinuities.
        Without this correction algorithm will still work, but will be a bit  less
        powerful. Do not use this correction  for  situations  when  you  want  to
        estimate continuity around some non-extremal point  -  it  may  result  in
        spurious discontinuities being reported.

          -- ALGLIB --
             Copyright 19.11.2018 by Bochkanov Sergey
        *************************************************************************/
        private static void testc0continuity(double f0,
            double f1,
            double f2,
            double f3,
            double noise0,
            double noise1,
            double noise2,
            double noise3,
            double delta0,
            double delta1,
            double delta2,
            bool applyspecialcorrection,
            ref double rating,
            ref double lipschitz,
            alglib.xparams _params)
        {
            double lipschitz01 = 0;
            double lipschitz12 = 0;
            double lipschitz23 = 0;

            rating = 0;
            lipschitz = 0;

            
            //
            // Compute Lipschitz constant for the interval [0,1],
            // add noise correction in order to get increased estimate (makes
            // comparison below more conservative).
            //
            lipschitz01 = (Math.Abs(f1-f0)+(noise0+noise1))/delta0;
            
            //
            // Compute Lipschitz constant for the interval [StpIdx+1,StpIdx+2],
            // SUBTRACT noise correction in order to get decreased estimate (makes
            // comparison below more conservative).
            //
            lipschitz12 = Math.Max(Math.Abs(f2-f1)-(noise1+noise2), 0.0)/delta1;
            
            //
            // Compute Lipschitz constant for the interval [StpIdx+2,StpIdx+3]
            // using special algorithm:
            // a) if F3<F2-Noise23, Lipschitz constant is assumed to be zero
            // b) otherwise, we compute Lipschitz constant as usual,
            //    with noise correction term being added
            //
            // We need case (a) because some kinds of discontinuities
            // (like one introduced by max(1/x,0)) manifest themselves
            // in a quite special way.
            //
            if( applyspecialcorrection && f3<f2-(noise2+noise3) )
            {
                lipschitz23 = 0;
            }
            else
            {
                lipschitz23 = (Math.Abs(f3-f2)+(noise2+noise3))/delta2;
            }
            
            //
            // Compute rating (ratio of two Lipschitz constants)
            //
            alglib.ap.assert(Math.Max(lipschitz01, lipschitz23)>0, "OptGuard: integrity check failed");
            rating = lipschitz12/Math.Max(lipschitz01, lipschitz23);
            lipschitz = lipschitz12;
        }


        /*************************************************************************
        This subroutine checks C1 continuity using test #0 (function  values  from
        the line search log are studied, gradient is not used).

        An interval between F[StpIdx+0] and F[StpIdx+5]is  tested for  continuity.
        An normalized error metric (Lipschitz constant growth for the  derivative)
        for the interval in question is calculated. Values above  50  are  a  good
        indication of the discontinuity.

        A six-point algorithm is used for testing, so we expect that Monitor.F and
        Monitor.Stp have enough points for this test.

          -- ALGLIB --
             Copyright 19.11.2018 by Bochkanov Sergey
        *************************************************************************/
        private static void c1continuitytest0(smoothnessmonitor monitor,
            int funcidx,
            int stpidx,
            int sortedcnt,
            alglib.xparams _params)
        {
            double f0 = 0;
            double f1 = 0;
            double f2 = 0;
            double f3 = 0;
            double f4 = 0;
            double f5 = 0;
            double noise0 = 0;
            double noise1 = 0;
            double noise2 = 0;
            double noise3 = 0;
            double noise4 = 0;
            double noise5 = 0;
            double delta0 = 0;
            double delta1 = 0;
            double delta2 = 0;
            double delta3 = 0;
            double delta4 = 0;
            double d0 = 0;
            double d1 = 0;
            double d2 = 0;
            double d3 = 0;
            double newnoise0 = 0;
            double newnoise1 = 0;
            double newnoise2 = 0;
            double newnoise3 = 0;
            double newdelta0 = 0;
            double newdelta1 = 0;
            double newdelta2 = 0;
            double rating = 0;
            double lipschitz = 0;
            double lengthrating = 0;
            int i = 0;
            int n = 0;
            double nrm = 0;

            n = monitor.n;
            alglib.ap.assert(stpidx+5<sortedcnt, "C1ContinuityTest0: integrity check failed");
            alglib.ap.assert((double)(monitor.sortedstp[0])==(double)(0), "C1ContinuityTest0: integrity check failed");
            alglib.ap.assert((double)(monitor.sortedstp[sortedcnt-1])>(double)(0), "C1ContinuityTest0: integrity check failed");
            
            //
            // Fetch F, noise, Delta's
            //
            f0 = monitor.f[stpidx+0];
            f1 = monitor.f[stpidx+1];
            f2 = monitor.f[stpidx+2];
            f3 = monitor.f[stpidx+3];
            f4 = monitor.f[stpidx+4];
            f5 = monitor.f[stpidx+5];
            noise0 = ognoiselevelf*Math.Max(Math.Abs(f0), 1.0);
            noise1 = ognoiselevelf*Math.Max(Math.Abs(f1), 1.0);
            noise2 = ognoiselevelf*Math.Max(Math.Abs(f2), 1.0);
            noise3 = ognoiselevelf*Math.Max(Math.Abs(f3), 1.0);
            noise4 = ognoiselevelf*Math.Max(Math.Abs(f4), 1.0);
            noise5 = ognoiselevelf*Math.Max(Math.Abs(f5), 1.0);
            delta0 = monitor.sortedstp[stpidx+1]-monitor.sortedstp[stpidx+0];
            delta1 = monitor.sortedstp[stpidx+2]-monitor.sortedstp[stpidx+1];
            delta2 = monitor.sortedstp[stpidx+3]-monitor.sortedstp[stpidx+2];
            delta3 = monitor.sortedstp[stpidx+4]-monitor.sortedstp[stpidx+3];
            delta4 = monitor.sortedstp[stpidx+5]-monitor.sortedstp[stpidx+4];
            
            //
            // Differentiate functions, get derivative values and noise
            // estimates at points (0+1)/2, (1+2)/2, (3+4)/2, (3+4)/2,
            // (4+5)/2. Compute new step values NewDelta[i] and new
            // noise estimates.
            //
            d0 = (f1-f0)/delta0;
            d1 = (f2-f1)/delta1;
            d2 = (f4-f3)/delta3;
            d3 = (f5-f4)/delta4;
            newnoise0 = (noise0+noise1)/delta0;
            newnoise1 = (noise1+noise2)/delta1;
            newnoise2 = (noise3+noise4)/delta3;
            newnoise3 = (noise4+noise5)/delta4;
            newdelta0 = 0.5*(delta0+delta1);
            newdelta1 = 0.5*delta1+delta2+0.5*delta3;
            newdelta2 = 0.5*(delta3+delta4);
            
            //
            // Test with C0 continuity tester. "Special correction" is
            // turned off for this test.
            //
            testc0continuity(d0, d1, d2, d3, newnoise0, newnoise1, newnoise2, newnoise3, newdelta0, newdelta1, newdelta2, false, ref rating, ref lipschitz, _params);
            
            //
            // Store results
            //
            if( rating>ogminrating1 )
            {
                
                //
                // Store to total report
                //
                monitor.rep.nonc1test0positive = true;
                if( rating>monitor.nonc1currentrating )
                {
                    monitor.nonc1currentrating = rating;
                    monitor.rep.nonc1suspected = true;
                    monitor.rep.nonc1lipschitzc = lipschitz;
                    monitor.rep.nonc1fidx = funcidx;
                }
                
                //
                // Store to "strongest" report
                //
                if( rating>monitor.nonc1test0strrating )
                {
                    monitor.nonc1test0strrating = rating;
                    monitor.nonc1test0strrep.positive = true;
                    monitor.nonc1test0strrep.fidx = funcidx;
                    monitor.nonc1test0strrep.n = n;
                    monitor.nonc1test0strrep.cnt = sortedcnt;
                    monitor.nonc1test0strrep.stpidxa = stpidx+1;
                    monitor.nonc1test0strrep.stpidxb = stpidx+4;
                    monitor.nonc1test0strrep.inneriter = monitor.linesearchinneridx;
                    monitor.nonc1test0strrep.outeriter = monitor.linesearchouteridx;
                    apserv.rvectorsetlengthatleast(ref monitor.nonc1test0strrep.x0, n, _params);
                    apserv.rvectorsetlengthatleast(ref monitor.nonc1test0strrep.d, n, _params);
                    for(i=0; i<=n-1; i++)
                    {
                        monitor.nonc1test0strrep.x0[i] = monitor.enqueuedx[monitor.sortedidx[0]*n+i];
                        monitor.nonc1test0strrep.d[i] = monitor.dcur[i];
                    }
                    apserv.rvectorsetlengthatleast(ref monitor.nonc1test0strrep.stp, sortedcnt, _params);
                    apserv.rvectorsetlengthatleast(ref monitor.nonc1test0strrep.f, sortedcnt, _params);
                    for(i=0; i<=sortedcnt-1; i++)
                    {
                        monitor.nonc1test0strrep.stp[i] = monitor.sortedstp[i];
                        monitor.nonc1test0strrep.f[i] = monitor.f[i];
                    }
                }
                
                //
                // Store to "longest" report
                //
                nrm = 0;
                for(i=0; i<=n-1; i++)
                {
                    nrm = nrm+math.sqr(monitor.enqueuedx[monitor.sortedidx[0]*n+i]-monitor.enqueuedx[monitor.sortedidx[sortedcnt-1]*n+i]);
                }
                nrm = Math.Sqrt(nrm);
                nrm = apserv.coalesce(nrm, math.machineepsilon, _params);
                lengthrating = nrm;
                if( lengthrating>monitor.nonc1test0lngrating )
                {
                    monitor.nonc1test0lngrating = lengthrating;
                    monitor.nonc1test0lngrep.positive = true;
                    monitor.nonc1test0lngrep.fidx = funcidx;
                    monitor.nonc1test0lngrep.n = n;
                    monitor.nonc1test0lngrep.cnt = sortedcnt;
                    monitor.nonc1test0lngrep.stpidxa = stpidx+1;
                    monitor.nonc1test0lngrep.stpidxb = stpidx+4;
                    monitor.nonc1test0lngrep.inneriter = monitor.linesearchinneridx;
                    monitor.nonc1test0lngrep.outeriter = monitor.linesearchouteridx;
                    apserv.rvectorsetlengthatleast(ref monitor.nonc1test0lngrep.x0, n, _params);
                    apserv.rvectorsetlengthatleast(ref monitor.nonc1test0lngrep.d, n, _params);
                    for(i=0; i<=n-1; i++)
                    {
                        monitor.nonc1test0lngrep.x0[i] = monitor.enqueuedx[monitor.sortedidx[0]*n+i];
                        monitor.nonc1test0lngrep.d[i] = monitor.dcur[i];
                    }
                    apserv.rvectorsetlengthatleast(ref monitor.nonc1test0lngrep.stp, sortedcnt, _params);
                    apserv.rvectorsetlengthatleast(ref monitor.nonc1test0lngrep.f, sortedcnt, _params);
                    for(i=0; i<=sortedcnt-1; i++)
                    {
                        monitor.nonc1test0lngrep.stp[i] = monitor.sortedstp[i];
                        monitor.nonc1test0lngrep.f[i] = monitor.f[i];
                    }
                }
            }
        }


        /*************************************************************************
        This  subroutine checks C1 continuity using test #1  (individual  gradient
        components from the line search log are studied for continuity).

        An interval between F[StpIdx+0] and F[StpIdx+3]is  tested for  continuity.
        An normalized error metric (Lipschitz constant growth for the  derivative)
        for the interval in question is calculated. Values above  50  are  a  good
        indication of the discontinuity.

          -- ALGLIB --
             Copyright 19.11.2018 by Bochkanov Sergey
        *************************************************************************/
        private static void c1continuitytest1(smoothnessmonitor monitor,
            int funcidx,
            int stpidx,
            int sortedcnt,
            alglib.xparams _params)
        {
            int i = 0;
            int varidx = 0;
            int n = 0;
            double f0 = 0;
            double f1 = 0;
            double f2 = 0;
            double f3 = 0;
            double noise0 = 0;
            double noise1 = 0;
            double noise2 = 0;
            double noise3 = 0;
            double nrm = 0;
            double rating = 0;
            double lengthrating = 0;
            double lipschitz = 0;

            n = monitor.n;
            alglib.ap.assert(stpidx+3<sortedcnt, "C1ContinuityTest1: integrity check failed");
            alglib.ap.assert((double)(monitor.sortedstp[0])==(double)(0), "C1ContinuityTest1: integrity check failed");
            alglib.ap.assert((double)(monitor.sortedstp[sortedcnt-1])>(double)(0), "C1ContinuityTest1: integrity check failed");
            
            //
            // Study each component of the gradient in the interval in question
            //
            for(varidx=0; varidx<=n-1; varidx++)
            {
                f0 = monitor.g[(stpidx+0)*n+varidx];
                f1 = monitor.g[(stpidx+1)*n+varidx];
                f2 = monitor.g[(stpidx+2)*n+varidx];
                f3 = monitor.g[(stpidx+3)*n+varidx];
                noise0 = ognoiselevelg*Math.Max(Math.Abs(f0), 1.0);
                noise1 = ognoiselevelg*Math.Max(Math.Abs(f1), 1.0);
                noise2 = ognoiselevelg*Math.Max(Math.Abs(f2), 1.0);
                noise3 = ognoiselevelg*Math.Max(Math.Abs(f3), 1.0);
                testc0continuity(f0, f1, f2, f3, noise0, noise1, noise2, noise3, monitor.sortedstp[stpidx+1]-monitor.sortedstp[stpidx+0], monitor.sortedstp[stpidx+2]-monitor.sortedstp[stpidx+1], monitor.sortedstp[stpidx+3]-monitor.sortedstp[stpidx+2], false, ref rating, ref lipschitz, _params);
                
                //
                // Store results
                //
                if( rating>ogminrating1 )
                {
                    
                    //
                    // Store to total report
                    //
                    monitor.rep.nonc1test1positive = true;
                    if( rating>monitor.nonc1currentrating )
                    {
                        monitor.nonc1currentrating = rating;
                        monitor.rep.nonc1suspected = true;
                        monitor.rep.nonc1lipschitzc = lipschitz;
                        monitor.rep.nonc1fidx = funcidx;
                    }
                    
                    //
                    // Store to "strongest" report
                    //
                    if( rating>monitor.nonc1test1strrating )
                    {
                        monitor.nonc1test1strrating = rating;
                        monitor.nonc1test1strrep.positive = true;
                        monitor.nonc1test1strrep.fidx = funcidx;
                        monitor.nonc1test1strrep.vidx = varidx;
                        monitor.nonc1test1strrep.n = n;
                        monitor.nonc1test1strrep.cnt = sortedcnt;
                        monitor.nonc1test1strrep.stpidxa = stpidx+0;
                        monitor.nonc1test1strrep.stpidxb = stpidx+3;
                        monitor.nonc1test1strrep.inneriter = monitor.linesearchinneridx;
                        monitor.nonc1test1strrep.outeriter = monitor.linesearchouteridx;
                        apserv.rvectorsetlengthatleast(ref monitor.nonc1test1strrep.x0, n, _params);
                        apserv.rvectorsetlengthatleast(ref monitor.nonc1test1strrep.d, n, _params);
                        for(i=0; i<=n-1; i++)
                        {
                            monitor.nonc1test1strrep.x0[i] = monitor.enqueuedx[monitor.sortedidx[0]*n+i];
                            monitor.nonc1test1strrep.d[i] = monitor.dcur[i];
                        }
                        apserv.rvectorsetlengthatleast(ref monitor.nonc1test1strrep.stp, sortedcnt, _params);
                        apserv.rvectorsetlengthatleast(ref monitor.nonc1test1strrep.g, sortedcnt, _params);
                        for(i=0; i<=sortedcnt-1; i++)
                        {
                            monitor.nonc1test1strrep.stp[i] = monitor.sortedstp[i];
                            monitor.nonc1test1strrep.g[i] = monitor.g[i*n+varidx];
                        }
                    }
                    
                    //
                    // Store to "longest" report
                    //
                    nrm = 0;
                    for(i=0; i<=n-1; i++)
                    {
                        nrm = nrm+math.sqr(monitor.enqueuedx[monitor.sortedidx[0]*n+i]-monitor.enqueuedx[monitor.sortedidx[sortedcnt-1]*n+i]);
                    }
                    nrm = Math.Sqrt(nrm);
                    nrm = apserv.coalesce(nrm, math.machineepsilon, _params);
                    lengthrating = nrm;
                    if( lengthrating>monitor.nonc1test1lngrating )
                    {
                        monitor.nonc1test1lngrating = lengthrating;
                        monitor.nonc1test1lngrep.positive = true;
                        monitor.nonc1test1lngrep.fidx = funcidx;
                        monitor.nonc1test1lngrep.vidx = varidx;
                        monitor.nonc1test1lngrep.n = n;
                        monitor.nonc1test1lngrep.cnt = sortedcnt;
                        monitor.nonc1test1lngrep.stpidxa = stpidx+0;
                        monitor.nonc1test1lngrep.stpidxb = stpidx+3;
                        monitor.nonc1test1lngrep.inneriter = monitor.linesearchinneridx;
                        monitor.nonc1test1lngrep.outeriter = monitor.linesearchouteridx;
                        apserv.rvectorsetlengthatleast(ref monitor.nonc1test1lngrep.x0, n, _params);
                        apserv.rvectorsetlengthatleast(ref monitor.nonc1test1lngrep.d, n, _params);
                        for(i=0; i<=n-1; i++)
                        {
                            monitor.nonc1test1lngrep.x0[i] = monitor.enqueuedx[monitor.sortedidx[0]*n+i];
                            monitor.nonc1test1lngrep.d[i] = monitor.dcur[i];
                        }
                        apserv.rvectorsetlengthatleast(ref monitor.nonc1test1lngrep.stp, sortedcnt, _params);
                        apserv.rvectorsetlengthatleast(ref monitor.nonc1test1lngrep.g, sortedcnt, _params);
                        for(i=0; i<=sortedcnt-1; i++)
                        {
                            monitor.nonc1test1lngrep.stp[i] = monitor.sortedstp[i];
                            monitor.nonc1test1lngrep.g[i] = monitor.g[i*n+varidx];
                        }
                    }
                }
            }
        }


        /*************************************************************************
        This function initializes approximation of a Hessian as a  limited  memory
        SR1 model.

        INPUT PARAMETERS:
            Hess            -   Hessian structure, initial state is ignored, but
                                previously allocated memory is reused as much as
                                possible
            N               -   dimensions count, N>0
            M               -   memory size, M>=0 (values above N will be reduced
                                to N)
            StpShort        -   short step length (INF-norm); steps shorter than that
                                are not used for Hessian updates
            MaxHess         -   maximum Hessian curvature; steps producing curvature
                                larger than that are rejected

          -- ALGLIB --
             Copyright 08.02.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void hessianinitlowranksr1x(xbfgshessian hess,
            int n,
            int m,
            double stpshort,
            double maxhess,
            int sr1ver,
            alglib.xparams _params)
        {
            alglib.ap.assert(n>0, "HessianInitLowRankSR1: N<=0");
            alglib.ap.assert(m>=0, "HessianInitLowRankSR1: M<0");
            m = Math.Min(m, n);
            
            //
            // Initialize generic fields
            //
            hess.htype = 4;
            hess.n = n;
            hess.sr1ver = sr1ver;
            
            //
            // Initialize mode-specific fields
            //
            hess.m = m;
            hess.memlen = 0;
            ablasf.rsetallocv(n, 1.0, ref hess.varscale, _params);
            ablasf.rsetallocv(n, 1.0, ref hess.invscale, _params);
            if( m>0 )
            {
                ablasf.rallocm(m, n, ref hess.s, _params);
                ablasf.rallocm(m, n, ref hess.y, _params);
                ablasf.rallocm(m, n, ref hess.corr2, _params);
            }
            resetlowrankmodel(hess, _params);
            
            //
            // Other fields
            //
            hess.stpshort = stpshort;
            hess.hage = 0;
            hess.maxhess = maxhess;
            hess.updatestatus = 0;
            hess.mincostheta = 500*Math.Sqrt(math.machineepsilon);
            hess.mincrv = 10*Math.Sqrt(math.machineepsilon);
            ablasf.rallocv(n, ref hess.sk, _params);
            ablasf.rallocv(n, ref hess.yk, _params);
            ablasf.rallocv(n, ref hess.rk, _params);
        }


        /*************************************************************************
        Removes oldest update pair from the limited memory Hessian model and
        invalidates Hessian model

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void popfrontxy(xbfgshessian hess,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;

            alglib.ap.assert(hess.htype==3 || hess.htype==4, "PopFrontXY: Hessian mode is not supported");
            if( hess.memlen==0 )
            {
                return;
            }
            for(i=0; i<=hess.memlen-2; i++)
            {
                ablasf.rcopyrr(hess.n, hess.s, i+1, hess.s, i, _params);
                ablasf.rcopyrr(hess.n, hess.y, i+1, hess.y, i, _params);
            }
            if( hess.htype==3 )
            {
                for(i=0; i<=hess.memlen-2; i++)
                {
                    for(j=0; j<=hess.memlen-2; j++)
                    {
                        hess.lowranksst[i,j] = hess.lowranksst[i+1,j+1];
                        hess.lowranksyt[i,j] = hess.lowranksyt[i+1,j+1];
                    }
                }
            }
            hess.memlen = hess.memlen-1;
            resetlowrankmodel(hess, _params);
        }


        /*************************************************************************
        Lowe-level Hessian update function, to be used by HessianUpdate()

        INPUT PARAMETERS:
            Hess            -   Hessian state
            H               -   specific Hessian matrix to update, usually one
                                of the Hess fields
            X0, G0          -   point #0 and gradient at #0, array[N]
            X1, G1          -   point #1 and gradient at #1, array[N]

        OUTPUT PARAMETERS:
            Status          -   sets update status (informative)

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void hessianupdatelowlevel(xbfgshessian hess,
            double[,] h,
            double[] sk,
            double[] yk,
            ref int status,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;
            double shs = 0;
            double sy = 0;
            double snrm2 = 0;
            double hsnrm2 = 0;
            double ynrm2 = 0;
            double ski = 0;
            double yki = 0;
            double mxs = 0;
            double mxy = 0;
            double mxhs = 0;
            double mxd = 0;
            double big = 0;

            status = 0;

            n = hess.n;
            status = 0;
            big = 1/hess.reg;
            
            //
            // Perform preliminary analysis
            //
            apserv.rvectorsetlengthatleast(ref hess.hsk, n, _params);
            ablas.rmatrixgemv(n, n, 1.0, h, 0, 0, 0, sk, 0, 0.0, hess.hsk, 0, _params);
            shs = 0;
            sy = 0;
            snrm2 = 0;
            ynrm2 = 0;
            mxs = 0;
            mxy = 0;
            mxhs = 0;
            hsnrm2 = 0;
            mxd = 0;
            for(i=0; i<=n-1; i++)
            {
                ski = sk[i];
                yki = yk[i];
                shs = shs+ski*hess.hsk[i];
                sy = sy+ski*yki;
                snrm2 = snrm2+ski*ski;
                ynrm2 = ynrm2+yki*yki;
                mxs = Math.Max(mxs, Math.Abs(ski));
                mxy = Math.Max(mxy, Math.Abs(yki));
                mxhs = Math.Max(mxhs, Math.Abs(hess.hsk[i]));
                hsnrm2 = hsnrm2+math.sqr(hess.hsk[i]);
                mxd = Math.Max(mxd, Math.Abs(h[i,i]));
            }
            
            //
            // Completely skip updates with too short steps and degenerate updates
            //
            // NOTE: may prevent us from updating Hessian near the solution
            //
            if( (double)(mxs)<=(double)(hess.stpshort) )
            {
                
                //
                // Sk is too small
                //
                return;
            }
            if( (double)(hsnrm2)==(double)(0) )
            {
                
                //
                // H*Sk is exactly zero, exit
                //
                return;
            }
            if( (double)(shs)<=(double)(0) || (double)(shs)<=(double)(mxs*mxd*mxs*hess.microreg) )
            {
                
                //
                // Sk'*H*Sk is too small.
                //
                // Apply regularization to Hessian before exiting
                //
                alglib.ap.assert((double)(hsnrm2)>(double)(0), "UpdateHessian: integrity check failed");
                ablas.rmatrixger(n, n, h, 0, 0, hess.reg/hsnrm2, hess.hsk, 0, hess.hsk, 0, _params);
                return;
            }
            
            //
            // First, we discard Hessian components which give non-zero product with Sk.
            //
            // We apply some damping in order to avoid problems arising with very small
            // Sk'*H*Sk, and we apply some regularization term in order to have Sk'*Hnew*Sk
            // still slightly larger than zero.
            //
            // Traditional BFGS update adds -(Hk*Sk)*(Hk*Sk)'/(Sk'*H*Sk). We use
            // modified, more robust formula (below Z=(H*Sk)/|H*Sk|)
            //
            //     (                         (H*Sk,H*Sk)                               )
            //     ( - --------------------------------------------------------- + Reg ) * Z * Z'
            //     (    Sk'*H*Sk + Reg*(H*Sk,H*Sk) + MicroReg*(max(H)*max(S))^2        )
            //
            alglib.ap.assert((double)(hsnrm2)>(double)(0), "UpdateHessian: integrity check failed");
            ablas.rmatrixger(n, n, h, 0, 0, -(1/(shs+hsnrm2*hess.reg+math.sqr(mxd*mxs)*hess.microreg))+hess.reg/hsnrm2, hess.hsk, 0, hess.hsk, 0, _params);
            status = 1;
            
            //
            // Before we update Hessian with Yk, decide whether we need this update - or
            // maybe it is better to leave Hessian as is, with small curvature along Sk
            // (in the latter case we still treat BFGS update as successful).
            //
            // Traditional BFGS update adds Yk*Yk'/(Sk,Yk) to the Hessian. Instead we
            // use modified update (below U=Yk/|Yk|)
            //
            //               (Yk,Yk)
            //     -------------------------------------- * U * U'
            //      (Sk,Yk)+Reg*(Yk,Yk)+MicroReg*(Sk,Sk)
            //
            if( (double)(ynrm2)==(double)(0) )
            {
                return;
            }
            if( (double)(sy)<=(double)(0) )
            {
                return;
            }
            if( (double)(math.sqr(mxy)/sy)>=(double)(big) )
            {
                return;
            }
            alglib.ap.assert((double)(sy)>(double)(0), "UpdateHessian: integrity check failed");
            ablas.rmatrixger(n, n, h, 0, 0, 1/(sy+hess.reg*ynrm2+hess.microreg*snrm2), yk, 0, yk, 0, _params);
            status = 2;
        }


        /*************************************************************************
        Low-level Hessian update function, to be used by HessianUpdate().

        Performs no integrity checks.

        INPUT PARAMETERS:
            Hess            -   Hessian state
            H               -   specific Hessian matrix to update, usually one
                                of the Hess fields
            X0, G0          -   point #0 and gradient at #0, array[N]
            X1, G1          -   point #1 and gradient at #1, array[N]

        OUTPUT PARAMETERS:
            Status          -   sets update status (informative)

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void hessianupdatelowlevel2(xbfgshessian hess,
            double[,] h,
            double[] sk,
            double[] yk,
            ref int status,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;
            double shs = 0;
            double sy = 0;
            double snrm2 = 0;
            double hsnrm2 = 0;
            double ynrm2 = 0;
            double ski = 0;
            double yki = 0;
            double mxs = 0;
            double mxy = 0;
            double mxhs = 0;
            double mxd = 0;

            status = 0;

            n = hess.n;
            status = 0;
            
            //
            // Perform preliminary analysis
            //
            apserv.rvectorsetlengthatleast(ref hess.hsk, n, _params);
            ablas.rmatrixgemv(n, n, 1.0, h, 0, 0, 0, sk, 0, 0.0, hess.hsk, 0, _params);
            shs = 0;
            sy = 0;
            snrm2 = 0;
            ynrm2 = 0;
            mxs = 0;
            mxy = 0;
            mxhs = 0;
            hsnrm2 = 0;
            mxd = 0;
            for(i=0; i<=n-1; i++)
            {
                ski = sk[i];
                yki = yk[i];
                shs = shs+ski*hess.hsk[i];
                sy = sy+ski*yki;
                snrm2 = snrm2+ski*ski;
                ynrm2 = ynrm2+yki*yki;
                mxs = Math.Max(mxs, Math.Abs(ski));
                mxy = Math.Max(mxy, Math.Abs(yki));
                mxhs = Math.Max(mxhs, Math.Abs(hess.hsk[i]));
                hsnrm2 = hsnrm2+math.sqr(hess.hsk[i]);
                mxd = Math.Max(mxd, Math.Abs(h[i,i]));
            }
            
            //
            // First, we discard Hessian components which give non-zero product with Sk.
            //
            alglib.ap.assert((double)(hsnrm2)>(double)(0), "UpdateHessian: integrity check failed");
            ablas.rmatrixger(n, n, h, 0, 0, -(1/shs), hess.hsk, 0, hess.hsk, 0, _params);
            status = 1;
            alglib.ap.assert((double)(sy)>(double)(0), "UpdateHessian: integrity check failed");
            ablas.rmatrixger(n, n, h, 0, 0, 1/sy, yk, 0, yk, 0, _params);
            status = 2;
        }


        /*************************************************************************
        Invalidate low-rank model

        INPUT PARAMETERS:
            Hess            -   Hessian state

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void resetlowrankmodel(xbfgshessian hess,
            alglib.xparams _params)
        {
            alglib.ap.assert(hess.htype==3 || hess.htype==4, "OPTSERV: integrity check 9940 failed");
            if( hess.htype==3 )
            {
                hess.lowrankmodelvalid = false;
                hess.lowrankeffdvalid = false;
            }
            if( hess.htype==4 )
            {
                hess.sr1modelvalid = false;
                hess.sr1effdvalid = false;
            }
        }


        /*************************************************************************
        Recomputes low-rank LBFGS or SR1 model

        INPUT PARAMETERS:
            Hess            -   Hessian state

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void recomputelowrankmodel(xbfgshessian hess,
            alglib.xparams _params)
        {
            alglib.ap.assert(hess.htype==3 || hess.htype==4, "RecomputeLowRankModel: Hessian mode is not supported");
            if( hess.htype==3 )
            {
                recomputelowrankmodellbfgs(hess, _params);
            }
            if( hess.htype==4 )
            {
                recomputelowrankmodelsr1(hess, _params);
            }
        }


        /*************************************************************************
        Recomputes low-rank model (DIAG and CORR fields) according to the  current
        state of the LBFGS memory

        INPUT PARAMETERS:
            Hess            -   Hessian state

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void recomputelowrankmodellbfgs(xbfgshessian hess,
            alglib.xparams _params)
        {
            int n = 0;
            int memlen = 0;
            int i = 0;
            int j = 0;
            double reg = 0;
            double mx = 0;

            alglib.ap.assert(hess.htype==3, "RecomputeLowRankModelLBFGS: Hessian mode is not supported");
            n = hess.n;
            memlen = hess.memlen;
            
            //
            // If the model is valid, exit.
            // Otherwise, recompute it from scratch
            //
            if( hess.lowrankmodelvalid )
            {
                return;
            }
            resetlowrankmodel(hess, _params);
            
            //
            // Quick exit for MemLen=0.
            // After this block we assume that MemLen>0
            //
            if( memlen==0 )
            {
                hess.lowrankmodelvalid = true;
                hess.lowrankk = 0;
                return;
            }
            
            //
            // Prepare RAW_CORR2, a right part of correction matrix
            //
            //     Bk = sigma*I - RAW_CORR2'*RAW_BLOCK*RAW_CORR2
            //
            // with RAW_CORR2 being 2MEMLEN*N matrix and RAW_BLOCK being 2MEMLEN*2MEMLEN matrix,
            // as defined by equations 2.17 and 3.22 in 'REPRESENTATION OF QUASI-NEWTON MATRICES
            // AND THEIR USE IN LIMITED MEMORY METHODS' by Byrd, Nocedal and Schnabel.
            //
            // The initial form for Bk is
            //
            //                    [          ]   [ -Dk     Lk' ]-1 [  Y   ]
            //     Bk = sigma*I - [ Y' B0*S' ] * [             ] * [      ]
            //                    [          ]   [ Lk  S*B0*S' ]   [ S*B0 ]
            //
            // with
            //
            //     Lk[i,j]=(Si,Yj) for i>j, 0 otherwise
            //     Dk = diag[(Si,Yj)]
            //
            //
            ablasf.rallocm(2*memlen, n, ref hess.corr2, _params);
            for(i=0; i<=memlen-1; i++)
            {
                ablasf.rcopyrr(n, hess.s, i, hess.corr2, memlen+i, _params);
                ablasf.rmulr(n, hess.sigma, hess.corr2, memlen+i, _params);
                ablasf.rcopyrr(n, hess.y, i, hess.corr2, i, _params);
            }
            
            //
            // Start factorizing central block. Whilst it is indefinite, it has
            // pretty simple factorization
            //
            //     [ -Dk     Lk' ]   [ Dk^(0.5)          ]   [ -I      ]   [ Dk^(0.5)  -Dk^(-0.5)*Lk' ]
            //     [             ] = [                   ] * [         ] * [                          ]
            //     [ Lk  S*B0*S' ]   [ -Lk*Dk^(-0.5)  Jk ]   [      +I ]   [                      Jk' ]
            //
            // First, we compute lower triangular Jk such that Jk*Jk' = S*B0*S' + Lk*inv(Dk)*Lk'
            //
            ablasf.rallocv(memlen, ref hess.buf, _params);
            for(i=0; i<=memlen-1; i++)
            {
                hess.buf[i] = 1/Math.Sqrt(hess.lowranksyt[i,i]);
            }
            ablasf.rsetallocm(memlen, memlen, 0.0, ref hess.invsqrtdlk, _params);
            for(i=1; i<=memlen-1; i++)
            {
                ablasf.rcopyrr(i, hess.lowranksyt, i, hess.invsqrtdlk, i, _params);
                ablasf.rmergemulvr(i, hess.buf, hess.invsqrtdlk, i, _params);
            }
            reg = 0;
            mx = 0;
            while( true )
            {
                
                //
                // Try Cholesky decomposition
                //
                ablasf.rcopyallocm(memlen, memlen, hess.lowranksst, ref hess.jk, _params);
                ablas.rmatrixgemm(memlen, memlen, memlen, 1.0, hess.invsqrtdlk, 0, 0, 0, hess.invsqrtdlk, 0, 0, 1, hess.sigma, hess.jk, 0, 0, _params);
                for(i=0; i<=memlen-1; i++)
                {
                    mx = Math.Max(mx, Math.Abs(hess.jk[i,i]));
                    hess.jk[i,i] = hess.jk[i,i]+reg;
                }
                if( trfac.spdmatrixcholeskyrec(hess.jk, 0, memlen, false, ref hess.buf, _params) )
                {
                    break;
                }
                
                //
                // Cholesky decomposition failed, increase regularization
                //
                mx = apserv.coalesce(mx, math.machineepsilon, _params);
                reg = apserv.coalesce(10*reg, Math.Sqrt(math.machineepsilon)*mx, _params);
            }
            
            //
            // After computing Jk we proceed to form triangular factorization of the entire block matrix
            //
            ablasf.rsetallocm(2*memlen, 2*memlen, 0.0, ref hess.blk, _params);
            for(i=0; i<=memlen-1; i++)
            {
                hess.blk[i,i] = Math.Sqrt(hess.lowranksyt[i,i]);
            }
            for(i=0; i<=memlen-1; i++)
            {
                for(j=0; j<=i-1; j++)
                {
                    hess.blk[memlen+i,j] = -hess.invsqrtdlk[i,j];
                }
            }
            for(i=0; i<=memlen-1; i++)
            {
                for(j=0; j<=i; j++)
                {
                    hess.blk[memlen+i,memlen+j] = hess.jk[i,j];
                }
            }
            
            //
            // And finally we merge triangular factor into CORR2 in order to get desired two-factor
            // low rank representation without additional middle matrix. This representation is
            // computed in CORR2 and unpacked into LowRankCp and LowRankCm ('minus' and 'plus' terms).
            //
            ablas.rmatrixlefttrsm(2*memlen, n, hess.blk, 0, 0, false, false, 0, hess.corr2, 0, 0, _params);
            ablasf.rallocm(memlen, n, ref hess.lowrankcp, _params);
            for(i=0; i<=memlen-1; i++)
            {
                ablasf.rcopyrr(n, hess.corr2, i, hess.lowrankcp, i, _params);
            }
            ablasf.rallocm(memlen, n, ref hess.lowrankcm, _params);
            for(i=0; i<=memlen-1; i++)
            {
                ablasf.rcopyrr(n, hess.corr2, memlen+i, hess.lowrankcm, i, _params);
            }
            
            //
            // The model was created
            //
            hess.lowrankmodelvalid = true;
            hess.lowrankk = memlen;
        }


        /*************************************************************************
        Recomputes low-rank SR1 model

        INPUT PARAMETERS:
            Hess            -   Hessian state

          -- ALGLIB --
             Copyright 09.02.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void recomputelowrankmodelsr1(xbfgshessian hess,
            alglib.xparams _params)
        {
            int n = 0;
            int memlen = 0;
            int i = 0;
            int j = 0;
            double v = 0;
            double ev = 0;
            double eps = 0;
            double scaledsigma = 0;
            double stabsigma = 0;
            double minimalcurvature = 0;
            double absoluteminimum = 0;
            double shiftby = 0;
            bool done = new bool();

            alglib.ap.assert(hess.htype==4, "RecomputeLowRankModelSR1: Hessian mode is not supported");
            n = hess.n;
            eps = Math.Sqrt(math.machineepsilon);
            
            //
            // If the model is valid, exit.
            // Otherwise, recompute it from scratch
            //
            if( hess.sr1modelvalid )
            {
                return;
            }
            resetlowrankmodel(hess, _params);
            
            //
            // Rescale S and Y to internal scale, as set in Hess.varScale.
            //
            // Prepare a low-rank representation of SR1 update with additional orthogonality
            // properties. The original form of low-rank SR1 update is
            //
            //                    [              ]   [                          ]-1 [             ]
            //     Bk = sigma*I + [ Y'- Sigma*S' ] * [ Dk+Lk+Lk' - Sigma*Sk*Sk' ] * [ Y - Sigma*S ]
            //                    [              ]   [                          ]   [             ]
            //
            // with
            //
            //     Lk[i,j]=(Si,Yj) for i>j, 0 otherwise
            //     Dk = diag[(Si,Yj)]
            //
            // as defined by equations 2.17 and 5.2 in 'REPRESENTATION OF QUASI-NEWTON MATRICES
            // AND THEIR USE IN LIMITED MEMORY METHODS' by Byrd, Nocedal and Schnabel.
            //
            // We plan to transform it into
            //
            //     Bk = sigma*I + C'*Z*C
            //
            // with Z being diagonal with +1 or -1 elements, and C being orthogonal (but not necessarily
            // orthonormal) matrices, with some rows maybe being zero.
            //
            //
            // First, we perform initial finiteness assurance (dropping degenerate SR1 updates). This
            // function, as defined in 'A study of the limited memory SR1 method in practice' by
            // Xuehua Lu, drops degenerate updates and, additionally, returns a decomposition
            //
            //     inv(M) = Lm'*Dm*Lm, with M=Dk+Lk+Lk'-Sigma*Sk*Sk'
            //
            // An important point is that M=Dk+Lk+Lk'-Sigma*Sk*Sk' is guaranteed to be non-degenerate
            // after the finiteness assurance; however, corresponding Y-sigma*S still can have zero rows,
            // i.e. be rank-deficient. Thus, operations involving potentially rank-deficient Y-sigma*S
            // have to be performed very carefully.
            //
            scaleandperformfinitenessassurance(hess, ref hess.tmps, ref hess.tmpy, ref scaledsigma, ref hess.tmpl, ref hess.tmpe, ref memlen, _params);
            absoluteminimum = 100*math.machineepsilon;
            minimalcurvature = Math.Max(Math.Min(scaledsigma, hess.mincrv), absoluteminimum);
            if( memlen==0 )
            {
                stabsigma = Math.Max(scaledsigma, minimalcurvature);
                hess.sr1modelvalid = true;
                hess.sr1k = 0;
                hess.sr1nrm2 = Math.Abs(scaledsigma);
                hess.sr1nrm2stab = stabsigma;
                ablasf.rsetallocv(n, scaledsigma, ref hess.sr1d, _params);
                ablasf.rsetallocv(n, stabsigma, ref hess.sr1stabd, _params);
                ablasf.rmergemulv(n, hess.invscale, hess.sr1d, _params);
                ablasf.rmergemulv(n, hess.invscale, hess.sr1d, _params);
                ablasf.rmergemulv(n, hess.invscale, hess.sr1stabd, _params);
                ablasf.rmergemulv(n, hess.invscale, hess.sr1stabd, _params);
                return;
            }
            alglib.ap.assert(memlen>0 && memlen<=n, "OPTSERV: integrity check 9823 failed");
            
            //
            // Decompose Y-sigma*S into L*Q with orthogonal Q and lower triangular L and store
            // Q to Hess.tmpU (here L is not to be confused with Lk and/or Lm). The factor L
            // can have exactly zero rows and/or be rank-deficient.
            //
            for(i=0; i<=memlen-1; i++)
            {
                ablasf.rcopyrr(n, hess.tmpy, i, hess.corr2, i, _params);
                ablasf.raddrr(n, -scaledsigma, hess.tmps, i, hess.corr2, i, _params);
            }
            ortfac.rmatrixlq(hess.corr2, memlen, n, ref hess.tmptau, _params);
            ortfac.rmatrixlqunpackq(hess.corr2, memlen, n, hess.tmptau, memlen, ref hess.tmpu, _params);
            
            //
            // Now we have
            //
            //     Bk = sigma*I + Q'*L'*Lm'*Dm*Lm*L*Q
            //
            // which can be transformed into
            //
            //     Bk = sigma*I + Q'*(Lm'*L'*Dm*Lm*L)*Q
            //        = sigma*I + Q'*BLK*Q
            //
            for(i=0; i<=memlen-1; i++)
            {
                for(j=i+1; j<=memlen-1; j++)
                {
                    hess.corr2[i,j] = 0.0;
                    hess.tmpl[i,j] = 0.0;
                }
            }
            ablasf.rallocm(memlen, memlen, ref hess.blk2, _params);
            ablas.rmatrixgemm(memlen, memlen, memlen, 1.0, hess.tmpl, 0, 0, 0, hess.corr2, 0, 0, 0, 0.0, hess.blk2, 0, 0, _params);
            ablasf.rcopyallocm(memlen, memlen, hess.blk2, ref hess.blk3, _params);
            for(i=0; i<=memlen-1; i++)
            {
                ablasf.rmulr(memlen, hess.tmpe[i], hess.blk2, i, _params);
            }
            ablasf.rallocm(memlen, memlen, ref hess.blk, _params);
            ablas.rmatrixgemm(memlen, memlen, memlen, 1.0, hess.blk3, 0, 0, 1, hess.blk2, 0, 0, 0, 0.0, hess.blk, 0, 0, _params);
            
            //
            // Perform eigendecomposition BLK=W*D*W', get
            //
            //     Bk = sigma*I + Q'*BLK*Q
            //        = sigma*I + Q'*W*D*W'*Q
            //        = sigma*I + (W'Q)'*D*(W'Q)
            //
            // then transform diagonal D (not to be confused with Dk) into one
            // with +1 or -1 on its diagonal.
            //
            // Produces both raw and positive definite stabilized updates.
            // Computes SR1Nrm2.
            //
            done = false;
            if( hess.sr1ver==1 )
            {
                
                //
                // Version 1 update: truncate negative eigenvalues
                //
                stabsigma = Math.Max(scaledsigma, minimalcurvature);
                hess.sr1nrm2 = Math.Abs(scaledsigma);
                hess.sr1nrm2stab = stabsigma;
                if( !evd.smatrixevd(hess.blk, memlen, 1, false, ref hess.tmpe, ref hess.tmpq, _params) )
                {
                    alglib.ap.assert(false, "HessianGetLowRankStabilizedSR1: eigensolver failure");
                }
                ablasf.rallocm(memlen, n, ref hess.sr1c, _params);
                ablas.rmatrixgemm(memlen, n, memlen, 1.0, hess.tmpq, 0, 0, 1, hess.tmpu, 0, 0, 0, 0.0, hess.sr1c, 0, 0, _params);
                ablasf.rallocv(memlen, ref hess.sr1z, _params);
                ablasf.rcopyallocm(memlen, n, hess.sr1c, ref hess.sr1stabc, _params);
                ablasf.rallocv(memlen, ref hess.sr1stabz, _params);
                ablasf.rsetallocv(n, scaledsigma, ref hess.sr1d, _params);
                ablasf.rsetallocv(n, stabsigma, ref hess.sr1stabd, _params);
                for(i=0; i<=memlen-1; i++)
                {
                    
                    //
                    // Update SR1Nrm2
                    //
                    hess.sr1nrm2 = Math.Max(hess.sr1nrm2, Math.Abs(scaledsigma+hess.tmpe[i]));
                    hess.sr1nrm2stab = Math.Max(hess.sr1nrm2stab, stabsigma+hess.tmpe[i]);
                    
                    //
                    // Produce raw update
                    //
                    ev = hess.tmpe[i];
                    v = Math.Abs(ev);
                    v = Math.Min(v, (Math.Abs(scaledsigma)+1)/eps);
                    ablasf.rmulr(n, Math.Sqrt(v), hess.sr1c, i, _params);
                    hess.sr1z[i] = apserv.possign(ev, _params);
                    
                    //
                    // Produce stabilized update
                    //
                    ev = hess.tmpe[i]-(stabsigma-scaledsigma);
                    v = Math.Abs(ev);
                    v = Math.Min(v, (Math.Abs(stabsigma)+1)/eps);
                    if( (double)(ev)<(double)(0) )
                    {
                        v = Math.Min(v, stabsigma-minimalcurvature);
                    }
                    ablasf.rmulr(n, Math.Sqrt(v), hess.sr1stabc, i, _params);
                    hess.sr1stabz[i] = apserv.possign(ev, _params);
                }
                hess.sr1k = memlen;
                done = true;
            }
            if( hess.sr1ver==2 )
            {
                
                //
                // Version 2 update: shift all eigenvalues so that the model becomes positive definite
                //
                if( !evd.smatrixevd(hess.blk, memlen, 1, false, ref hess.tmpe, ref hess.tmpq, _params) )
                {
                    alglib.ap.assert(false, "HessianGetLowRankStabilizedSR1: eigensolver failure");
                }
                shiftby = Math.Max(0.0, minimalcurvature-scaledsigma);
                for(i=0; i<=memlen-1; i++)
                {
                    shiftby = Math.Max(shiftby, minimalcurvature-(scaledsigma+hess.tmpe[i]));
                }
                stabsigma = scaledsigma+shiftby;
                hess.sr1nrm2 = Math.Abs(scaledsigma);
                hess.sr1nrm2stab = scaledsigma+shiftby;
                ablasf.rallocm(memlen, n, ref hess.sr1c, _params);
                ablas.rmatrixgemm(memlen, n, memlen, 1.0, hess.tmpq, 0, 0, 1, hess.tmpu, 0, 0, 0, 0.0, hess.sr1c, 0, 0, _params);
                ablasf.rallocv(memlen, ref hess.sr1z, _params);
                ablasf.rcopyallocm(memlen, n, hess.sr1c, ref hess.sr1stabc, _params);
                ablasf.rallocv(memlen, ref hess.sr1stabz, _params);
                ablasf.rsetallocv(n, scaledsigma, ref hess.sr1d, _params);
                ablasf.rsetallocv(n, scaledsigma+shiftby, ref hess.sr1stabd, _params);
                for(i=0; i<=memlen-1; i++)
                {
                    
                    //
                    // Update SR1Nrm2
                    //
                    hess.sr1nrm2 = Math.Max(hess.sr1nrm2, Math.Abs(scaledsigma+hess.tmpe[i]));
                    hess.sr1nrm2stab = Math.Max(hess.sr1nrm2stab, scaledsigma+shiftby+hess.tmpe[i]);
                    
                    //
                    // Produce raw update
                    //
                    ev = hess.tmpe[i];
                    v = Math.Abs(ev);
                    v = Math.Min(v, (Math.Abs(scaledsigma)+1)/eps);
                    ablasf.rmulr(n, Math.Sqrt(v), hess.sr1c, i, _params);
                    hess.sr1z[i] = apserv.possign(ev, _params);
                    
                    //
                    // Produce stabilized update
                    //
                    ev = hess.tmpe[i];
                    v = Math.Abs(ev);
                    v = Math.Min(v, (Math.Abs(scaledsigma)+1)/eps);
                    ablasf.rmulr(n, Math.Sqrt(v), hess.sr1stabc, i, _params);
                    hess.sr1stabz[i] = apserv.possign(ev, _params);
                }
                hess.sr1k = memlen;
                done = true;
            }
            alglib.ap.assert(done, "OPTSERV: 979921 failed");
            
            //
            // Perform unscaling
            //
            ablasf.rmergemulv(n, hess.invscale, hess.sr1d, _params);
            ablasf.rmergemulv(n, hess.invscale, hess.sr1d, _params);
            ablasf.rmergemulv(n, hess.invscale, hess.sr1stabd, _params);
            ablasf.rmergemulv(n, hess.invscale, hess.sr1stabd, _params);
            for(i=0; i<=hess.sr1k-1; i++)
            {
                ablasf.rmergemulvr(n, hess.invscale, hess.sr1c, i, _params);
                ablasf.rmergemulvr(n, hess.invscale, hess.sr1stabc, i, _params);
            }
            
            //
            // Done
            //
            hess.sr1modelvalid = true;
        }


        /*************************************************************************
        Filters update pairs Hess.S, Hess.Y for the SR1 model, removing ill-defined
        updates. May reorder pairs during the pocess, or drop some or all of them.

          -- ALGLIB --
             Copyright 09.02.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void scaleandperformfinitenessassurance(xbfgshessian hess,
            ref double[,] s,
            ref double[,] y,
            ref double sigma,
            ref double[,] l,
            ref double[] d,
            ref int filteredlen,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            int i0 = 0;
            int i1 = 0;
            int memlen = 0;
            int n = 0;
            int wrksize = 0;
            double v = 0;
            double v0 = 0;
            double v1 = 0;
            double costheta = 0;
            double lintol = 0;

            alglib.ap.assert(hess.htype==4, "FinitenessAssurance: Hessian mode is not supported");
            memlen = hess.memlen;
            n = hess.n;
            lintol = 100*Math.Sqrt(math.machineepsilon);
            if( memlen==0 )
            {
                sigma = 1;
                filteredlen = 0;
                return;
            }
            
            //
            // Copy and scale S and Y, compute initial scaling factor Sigma (after the variable scaling)
            //
            ablasf.rcopyallocm(hess.m, hess.n, hess.s, ref s, _params);
            ablasf.rcopyallocm(hess.m, hess.n, hess.y, ref y, _params);
            for(i=0; i<=memlen-1; i++)
            {
                ablasf.rmergemulvr(n, hess.invscale, s, i, _params);
                ablasf.rmergemulvr(n, hess.varscale, y, i, _params);
            }
            sigma = ablasf.rdotrr(n, s, memlen-1, y, memlen-1, _params)/(ablasf.rdotrr(n, s, memlen-1, s, memlen-1, _params)+math.machineepsilon*math.machineepsilon);
            if( memlen==1 )
            {
                
                //
                // There is no need to build an SR1 model for MemLen=1 update because it produces nearly-zero (and
                // sometimes degenerate) correction to the original diagonal matrix.
                //
                filteredlen = 0;
                return;
            }
            
            //
            // Enforce sufficient linear independence by zeroing out redundant rows. Rows which are exactly zero
            // will be dropped during the finiteness assurance iteration. The last row (the most recent update)
            // is always retained, that's why we start orthogonalization from the end.
            //
            ablasf.rcopym(memlen, n, hess.s, hess.corr2, _params);
            for(i=0; i<=memlen-1; i++)
            {
                ablasf.rmulr(n, 1/apserv.coalesce(Math.Sqrt(ablasf.rdotrr(n, hess.corr2, i, hess.corr2, i, _params)), 1, _params), hess.corr2, i, _params);
            }
            for(i=memlen-1; i>=0; i--)
            {
                v0 = ablasf.rdotrr(n, hess.corr2, i, hess.corr2, i, _params);
                if( (double)(v0)<(double)(lintol*lintol) )
                {
                    ablasf.rsetr(n, 0.0, s, i, _params);
                    ablasf.rsetr(n, 0.0, y, i, _params);
                    ablasf.rsetr(n, 0.0, hess.corr2, i, _params);
                    continue;
                }
                for(j=i-1; j>=0; j--)
                {
                    ablasf.raddrr(n, -(ablasf.rdotrr(n, hess.corr2, i, hess.corr2, j, _params)/v0), hess.corr2, i, hess.corr2, j, _params);
                }
            }
            
            //
            // Prepare finiteness assurance iteration
            //
            ablasf.rsetallocm(memlen, memlen, 0.0, ref l, _params);
            ablasf.rallocv(memlen, ref d, _params);
            for(i=0; i<=memlen-1; i++)
            {
                ablasf.rcopyrr(n, y, i, hess.corr2, i, _params);
                ablasf.raddrr(n, -sigma, s, i, hess.corr2, i, _params);
            }
            ablasf.rallocm(memlen, memlen, ref hess.blk, _params);
            ablas.rmatrixgemm(memlen, memlen, n, 1.0, s, 0, 0, 0, y, 0, 0, 1, 0.0, hess.blk, 0, 0, _params);
            for(i=0; i<=memlen-1; i++)
            {
                for(j=0; j<=i-1; j++)
                {
                    hess.blk[j,i] = hess.blk[i,j];
                }
            }
            ablas.rmatrixgemm(memlen, memlen, n, -sigma, s, 0, 0, 0, s, 0, 0, 1, 1.0, hess.blk, 0, 0, _params);
            
            //
            // Iterate until all updates are processed: approved or dropped
            //
            ablasf.rallocv(memlen, ref hess.buf, _params);
            ablasf.rallocv(memlen, ref hess.buf2, _params);
            filteredlen = 0;
            j = 0;
            wrksize = hess.memlen;
            while( j<wrksize )
            {
                
                //
                // Compute provisional J-th row of Mk (as defined in the formula 3.7 of 'A study of the
                // limited memory SR1 method in practice' by Xuehua Lu.
                //
                if( j>0 )
                {
                    ablasf.rcopyrv(j, hess.blk, j, hess.buf, _params);
                    ablasf.rgemv(j, j, 1.0, l, 0, hess.buf, 0.0, hess.buf2, _params);
                    ablasf.rmergedivv(j, d, hess.buf2, _params);
                    ablasf.rgemv(j, j, -1.0, l, 1, hess.buf2, 0.0, hess.buf, _params);
                    ablasf.rcopyvr(j, hess.buf, l, j, _params);
                }
                l[j,j] = 1.0;
                d[j] = ablasf.rdotrr(j+1, l, j, hess.blk, j, _params);
                
                //
                // Compute cos(theta) as defined by the formula 3.13 of 'A study of the
                // limited memory SR1 method in practice' by Xuehua Lu:
                // * first, compute v0=norm2(L[0:MemLen-1,J]*CORR2[J,0:N-1]) and v1=norm2(S[J,0:N-1])
                // * then, compute cos(theta)=D[J]/(v0*v1)
                //
                v0 = 0.0;
                for(i=0; i<=n-1; i++)
                {
                    v = 0.0;
                    for(k=0; k<=j; k++)
                    {
                        v = v+l[j,k]*hess.corr2[k,i];
                    }
                    v0 = v0+v*v;
                }
                v0 = Math.Sqrt(v0);
                v1 = Math.Sqrt(ablasf.rdotrr(n, s, j, s, j, _params));
                if( (double)(d[j])!=(double)(0) && (double)(v0*v1)!=(double)(0) )
                {
                    costheta = d[j]/(v0*v1);
                }
                else
                {
                    costheta = 0.0;
                }
                
                //
                // If CosTheta is too low, swap the last row with the J-th one and update S, Y, BLK, CORR2.
                // Otherwise, accept the row.
                //
                if( (double)(Math.Abs(costheta))<=(double)(hess.mincostheta) )
                {
                    if( j!=wrksize-1 )
                    {
                        for(i0=j; i0<=wrksize-2; i0++)
                        {
                            ablasf.rcopyrr(n, s, i0+1, s, i0, _params);
                            ablasf.rcopyrr(n, y, i0+1, y, i0, _params);
                            ablasf.rcopyrr(n, hess.corr2, i0+1, hess.corr2, i0, _params);
                        }
                        for(i0=0; i0<=wrksize-2; i0++)
                        {
                            for(i1=0; i1<=wrksize-2; i1++)
                            {
                                hess.blk[i0,i1] = hess.blk[apserv.icase2(i0<j, i0, i0+1, _params),apserv.icase2(i1<j, i1, i1+1, _params)];
                            }
                        }
                    }
                    wrksize = wrksize-1;
                }
                else
                {
                    j = j+1;
                    filteredlen = filteredlen+1;
                }
            }
            for(j=0; j<=filteredlen-1; j++)
            {
                d[j] = 1/d[j];
            }
        }


        /*************************************************************************
        Recomputes diagonal of the low-rank model, either LBFGS or SR1 one

        INPUT PARAMETERS:
            Hess            -   Hessian state

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void recomputelowrankdiagonal(xbfgshessian hess,
            alglib.xparams _params)
        {
            alglib.ap.assert(hess.htype==3 || hess.htype==4, "RecomputeLowRankDiagonal: Hessian mode is not supported");
            if( hess.htype==3 )
            {
                recomputelowrankdiagonalbfgs(hess, _params);
            }
            if( hess.htype==4 )
            {
                recomputelowrankdiagonalsr1(hess, _params);
            }
        }


        /*************************************************************************
        Recomputes diagonal of the low-rank model (EFFD) according to the  current
        state of the LBFGS memory

        INPUT PARAMETERS:
            Hess            -   Hessian state

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void recomputelowrankdiagonalbfgs(xbfgshessian hess,
            alglib.xparams _params)
        {
            int n = 0;
            int memlen = 0;
            int i = 0;

            alglib.ap.assert(hess.htype==3, "RecomputeLowRankDiagonalBFGS: Hessian mode is not supported");
            n = hess.n;
            memlen = hess.memlen;
            
            //
            // If the diagonal is valid, exit.
            // Otherwise, recompute it from scratch
            //
            if( hess.lowrankeffdvalid )
            {
                return;
            }
            recomputelowrankmodel(hess, _params);
            
            //
            // Quick exit for MemLen=0
            //
            if( memlen==0 )
            {
                hess.lowrankeffdvalid = true;
                ablasf.rsetallocv(n, hess.sigma, ref hess.lowrankeffd, _params);
                return;
            }
            
            //
            // Assuming MemLen>0
            //
            ablasf.rsetallocv(n, hess.sigma, ref hess.lowrankeffd, _params);
            ablasf.rallocv(n, ref hess.buf, _params);
            for(i=0; i<=hess.lowrankk-1; i++)
            {
                ablasf.rcopyrv(n, hess.lowrankcp, i, hess.buf, _params);
                ablasf.rmuladdv(n, hess.buf, hess.buf, hess.lowrankeffd, _params);
                ablasf.rcopyrv(n, hess.lowrankcm, i, hess.buf, _params);
                ablasf.rnegmuladdv(n, hess.buf, hess.buf, hess.lowrankeffd, _params);
            }
            hess.lowrankeffdvalid = true;
        }


        /*************************************************************************
        Recomputes diagonal of the low-rank SR1 model

        INPUT PARAMETERS:
            Hess            -   Hessian state

          -- ALGLIB --
             Copyright 28.11.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void recomputelowrankdiagonalsr1(xbfgshessian hess,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;

            alglib.ap.assert(hess.htype==4, "RecomputeLowRankDiagonalSR1: Hessian mode is not supported");
            n = hess.n;
            if( hess.sr1effdvalid )
            {
                return;
            }
            recomputelowrankmodelsr1(hess, _params);
            if( hess.sr1k==0 )
            {
                hess.sr1effdvalid = true;
                ablasf.rcopyallocv(n, hess.sr1d, ref hess.sr1effd, _params);
                return;
            }
            
            //
            // Assuming SR1K>0
            //
            ablasf.rcopyallocv(n, hess.sr1d, ref hess.sr1effd, _params);
            ablasf.rallocv(n, ref hess.buf, _params);
            for(i=0; i<=hess.sr1k-1; i++)
            {
                alglib.ap.assert((double)(hess.sr1z[i]*hess.sr1z[i])==(double)(1), "OPTSERV: ingegrity check 3416 failed");
                ablasf.rcopyrv(n, hess.sr1c, i, hess.buf, _params);
                if( (double)(hess.sr1z[i])>(double)(0) )
                {
                    ablasf.rmuladdv(n, hess.buf, hess.buf, hess.sr1effd, _params);
                }
                else
                {
                    ablasf.rnegmuladdv(n, hess.buf, hess.buf, hess.sr1effd, _params);
                }
            }
            hess.sr1effdvalid = true;
        }


        /*************************************************************************
        Fast kernel for unscalexbatchfinitebnd()
        *************************************************************************/
        private static bool unscalexbatchfinitebndkernel(double[] xs,
            int batchsize,
            double[] s,
            int n,
            double[] sclfinitebndl,
            double[] sclfinitebndu,
            double[] rawfinitebndl,
            double[] rawfinitebndu,
            double[] xu,
            alglib.xparams _params)
        {
            bool result = new bool();

            result = false;
            return result;
        }


    }
    public partial class cqmodels
    {
        /*************************************************************************
        This structure describes convex quadratic model of the form:
            f(x) = 0.5*(Alpha*x'*A*x + Tau*x'*D*x) + 0.5*Theta*(Q*x-r)'*(Q*x-r) + b'*x
        where:
            * Alpha>=0, Tau>=0, Theta>=0, Alpha+Tau>0.
            * A is NxN matrix, Q is NxK matrix (N>=1, K>=0), b is Nx1 vector,
              D is NxN diagonal matrix.
            * "main" quadratic term Alpha*A+Lambda*D is symmetric
              positive definite
        Structure may contain optional equality constraints of the form x[i]=x0[i],
        in this case functions provided by this unit calculate Newton step subject
        to these equality constraints.
        *************************************************************************/
        public class convexquadraticmodel : apobject
        {
            public int n;
            public int k;
            public double alpha;
            public double tau;
            public double theta;
            public double[,] a;
            public double[,] q;
            public double[] b;
            public double[] r;
            public double[] xc;
            public double[] d;
            public bool[] activeset;
            public double[,] tq2dense;
            public double[,] tk2;
            public double[] tq2diag;
            public double[] tq1;
            public double[] tk1;
            public double tq0;
            public double tk0;
            public double[] txc;
            public double[] tb;
            public int nfree;
            public int ecakind;
            public double[,] ecadense;
            public double[,] eq;
            public double[,] eccm;
            public double[] ecadiag;
            public double[] eb;
            public double ec;
            public double[] tmp0;
            public double[] tmp1;
            public double[] tmpg;
            public double[,] tmp2;
            public bool ismaintermchanged;
            public bool issecondarytermchanged;
            public bool islineartermchanged;
            public bool isactivesetchanged;
            public convexquadraticmodel()
            {
                init();
            }
            public override void init()
            {
                a = new double[0,0];
                q = new double[0,0];
                b = new double[0];
                r = new double[0];
                xc = new double[0];
                d = new double[0];
                activeset = new bool[0];
                tq2dense = new double[0,0];
                tk2 = new double[0,0];
                tq2diag = new double[0];
                tq1 = new double[0];
                tk1 = new double[0];
                txc = new double[0];
                tb = new double[0];
                ecadense = new double[0,0];
                eq = new double[0,0];
                eccm = new double[0,0];
                ecadiag = new double[0];
                eb = new double[0];
                tmp0 = new double[0];
                tmp1 = new double[0];
                tmpg = new double[0];
                tmp2 = new double[0,0];
            }
            public override alglib.apobject make_copy()
            {
                convexquadraticmodel _result = new convexquadraticmodel();
                _result.n = n;
                _result.k = k;
                _result.alpha = alpha;
                _result.tau = tau;
                _result.theta = theta;
                _result.a = (double[,])a.Clone();
                _result.q = (double[,])q.Clone();
                _result.b = (double[])b.Clone();
                _result.r = (double[])r.Clone();
                _result.xc = (double[])xc.Clone();
                _result.d = (double[])d.Clone();
                _result.activeset = (bool[])activeset.Clone();
                _result.tq2dense = (double[,])tq2dense.Clone();
                _result.tk2 = (double[,])tk2.Clone();
                _result.tq2diag = (double[])tq2diag.Clone();
                _result.tq1 = (double[])tq1.Clone();
                _result.tk1 = (double[])tk1.Clone();
                _result.tq0 = tq0;
                _result.tk0 = tk0;
                _result.txc = (double[])txc.Clone();
                _result.tb = (double[])tb.Clone();
                _result.nfree = nfree;
                _result.ecakind = ecakind;
                _result.ecadense = (double[,])ecadense.Clone();
                _result.eq = (double[,])eq.Clone();
                _result.eccm = (double[,])eccm.Clone();
                _result.ecadiag = (double[])ecadiag.Clone();
                _result.eb = (double[])eb.Clone();
                _result.ec = ec;
                _result.tmp0 = (double[])tmp0.Clone();
                _result.tmp1 = (double[])tmp1.Clone();
                _result.tmpg = (double[])tmpg.Clone();
                _result.tmp2 = (double[,])tmp2.Clone();
                _result.ismaintermchanged = ismaintermchanged;
                _result.issecondarytermchanged = issecondarytermchanged;
                _result.islineartermchanged = islineartermchanged;
                _result.isactivesetchanged = isactivesetchanged;
                return _result;
            }
        };




        public const int newtonrefinementits = 3;


        /*************************************************************************
        This subroutine is used to initialize CQM. By default, empty NxN model  is
        generated, with Alpha=Lambda=Theta=0.0 and zero b.

        Previously allocated buffer variables are reused as much as possible.

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqminit(int n,
            convexquadraticmodel s,
            alglib.xparams _params)
        {
            int i = 0;

            s.n = n;
            s.k = 0;
            s.nfree = n;
            s.ecakind = -1;
            s.alpha = 0.0;
            s.tau = 0.0;
            s.theta = 0.0;
            s.ismaintermchanged = true;
            s.issecondarytermchanged = true;
            s.islineartermchanged = true;
            s.isactivesetchanged = true;
            apserv.bvectorsetlengthatleast(ref s.activeset, n, _params);
            apserv.rvectorsetlengthatleast(ref s.xc, n, _params);
            apserv.rvectorsetlengthatleast(ref s.eb, n, _params);
            apserv.rvectorsetlengthatleast(ref s.tq1, n, _params);
            apserv.rvectorsetlengthatleast(ref s.txc, n, _params);
            apserv.rvectorsetlengthatleast(ref s.tb, n, _params);
            apserv.rvectorsetlengthatleast(ref s.b, s.n, _params);
            apserv.rvectorsetlengthatleast(ref s.tk1, s.n, _params);
            for(i=0; i<=n-1; i++)
            {
                s.activeset[i] = false;
                s.xc[i] = 0.0;
                s.b[i] = 0.0;
            }
        }


        /*************************************************************************
        This subroutine changes main quadratic term of the model.

        INPUT PARAMETERS:
            S       -   model
            A       -   NxN matrix, only upper or lower triangle is referenced
            IsUpper -   True, when matrix is stored in upper triangle
            Alpha   -   multiplier; when Alpha=0, A is not referenced at all

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmseta(convexquadraticmodel s,
            double[,] a,
            bool isupper,
            double alpha,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            double v = 0;

            alglib.ap.assert(math.isfinite(alpha) && (double)(alpha)>=(double)(0), "CQMSetA: Alpha<0 or is not finite number");
            alglib.ap.assert((double)(alpha)==(double)(0) || apserv.isfinitertrmatrix(a, s.n, isupper, _params), "CQMSetA: A is not finite NxN matrix");
            s.alpha = alpha;
            if( (double)(alpha)>(double)(0) )
            {
                apserv.rmatrixsetlengthatleast(ref s.a, s.n, s.n, _params);
                apserv.rmatrixsetlengthatleast(ref s.ecadense, s.n, s.n, _params);
                apserv.rmatrixsetlengthatleast(ref s.tq2dense, s.n, s.n, _params);
                for(i=0; i<=s.n-1; i++)
                {
                    for(j=i; j<=s.n-1; j++)
                    {
                        if( isupper )
                        {
                            v = a[i,j];
                        }
                        else
                        {
                            v = a[j,i];
                        }
                        s.a[i,j] = v;
                        s.a[j,i] = v;
                    }
                }
            }
            s.ismaintermchanged = true;
        }


        /*************************************************************************
        This subroutine changes main quadratic term of the model.

        INPUT PARAMETERS:
            S       -   model
            A       -   possibly preallocated buffer
            
        OUTPUT PARAMETERS:
            A       -   NxN matrix, full matrix is returned.
                        Zero matrix is returned if model is empty.

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmgeta(convexquadraticmodel s,
            ref double[,] a,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            double v = 0;
            int n = 0;

            n = s.n;
            apserv.rmatrixsetlengthatleast(ref a, n, n, _params);
            if( (double)(s.alpha)>(double)(0) )
            {
                v = s.alpha;
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        a[i,j] = v*s.a[i,j];
                    }
                }
            }
            else
            {
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        a[i,j] = 0.0;
                    }
                }
            }
        }


        /*************************************************************************
        This subroutine rewrites diagonal of the main quadratic term of the  model
        (dense  A)  by  vector  Z/Alpha (current value of the Alpha coefficient is
        used).

        IMPORTANT: in  case  model  has  no  dense  quadratic  term, this function
                   allocates N*N dense matrix of zeros, and fills its diagonal  by
                   non-zero values.

        INPUT PARAMETERS:
            S       -   model
            Z       -   new diagonal, array[N]

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmrewritedensediagonal(convexquadraticmodel s,
            double[] z,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            int j = 0;

            n = s.n;
            if( (double)(s.alpha)==(double)(0) )
            {
                apserv.rmatrixsetlengthatleast(ref s.a, s.n, s.n, _params);
                apserv.rmatrixsetlengthatleast(ref s.ecadense, s.n, s.n, _params);
                apserv.rmatrixsetlengthatleast(ref s.tq2dense, s.n, s.n, _params);
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        s.a[i,j] = 0.0;
                    }
                }
                s.alpha = 1.0;
            }
            for(i=0; i<=s.n-1; i++)
            {
                s.a[i,i] = z[i]/s.alpha;
            }
            s.ismaintermchanged = true;
        }


        /*************************************************************************
        This subroutine changes diagonal quadratic term of the model.

        INPUT PARAMETERS:
            S       -   model
            D       -   array[N], semidefinite diagonal matrix
            Tau     -   multiplier; when Tau=0, D is not referenced at all

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmsetd(convexquadraticmodel s,
            double[] d,
            double tau,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(math.isfinite(tau) && (double)(tau)>=(double)(0), "CQMSetD: Tau<0 or is not finite number");
            alglib.ap.assert((double)(tau)==(double)(0) || apserv.isfinitevector(d, s.n, _params), "CQMSetD: D is not finite Nx1 vector");
            s.tau = tau;
            if( (double)(tau)>(double)(0) )
            {
                apserv.rvectorsetlengthatleast(ref s.d, s.n, _params);
                apserv.rvectorsetlengthatleast(ref s.ecadiag, s.n, _params);
                apserv.rvectorsetlengthatleast(ref s.tq2diag, s.n, _params);
                for(i=0; i<=s.n-1; i++)
                {
                    alglib.ap.assert((double)(d[i])>=(double)(0), "CQMSetD: D[i]<0");
                    s.d[i] = d[i];
                }
            }
            s.ismaintermchanged = true;
        }


        /*************************************************************************
        This subroutine drops main quadratic term A from the model. It is same  as
        call  to  CQMSetA()  with  zero  A,   but gives better performance because
        algorithm  knows  that  matrix  is  zero  and  can  optimize    subsequent
        calculations.

        INPUT PARAMETERS:
            S       -   model

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmdropa(convexquadraticmodel s,
            alglib.xparams _params)
        {
            s.alpha = 0.0;
            s.ismaintermchanged = true;
        }


        /*************************************************************************
        This subroutine changes linear term of the model

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmsetb(convexquadraticmodel s,
            double[] b,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(apserv.isfinitevector(b, s.n, _params), "CQMSetB: B is not finite vector");
            apserv.rvectorsetlengthatleast(ref s.b, s.n, _params);
            for(i=0; i<=s.n-1; i++)
            {
                s.b[i] = b[i];
            }
            s.islineartermchanged = true;
        }


        /*************************************************************************
        This subroutine changes linear term of the model

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmsetq(convexquadraticmodel s,
            double[,] q,
            double[] r,
            int k,
            double theta,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;

            alglib.ap.assert(k>=0, "CQMSetQ: K<0");
            alglib.ap.assert((k==0 || (double)(theta)==(double)(0)) || apserv.apservisfinitematrix(q, k, s.n, _params), "CQMSetQ: Q is not finite matrix");
            alglib.ap.assert((k==0 || (double)(theta)==(double)(0)) || apserv.isfinitevector(r, k, _params), "CQMSetQ: R is not finite vector");
            alglib.ap.assert(math.isfinite(theta) && (double)(theta)>=(double)(0), "CQMSetQ: Theta<0 or is not finite number");
            
            //
            // degenerate case: K=0 or Theta=0
            //
            if( k==0 || (double)(theta)==(double)(0) )
            {
                s.k = 0;
                s.theta = 0;
                s.issecondarytermchanged = true;
                return;
            }
            
            //
            // General case: both Theta>0 and K>0
            //
            s.k = k;
            s.theta = theta;
            apserv.rmatrixsetlengthatleast(ref s.q, s.k, s.n, _params);
            apserv.rvectorsetlengthatleast(ref s.r, s.k, _params);
            apserv.rmatrixsetlengthatleast(ref s.eq, s.k, s.n, _params);
            apserv.rmatrixsetlengthatleast(ref s.eccm, s.k, s.k, _params);
            apserv.rmatrixsetlengthatleast(ref s.tk2, s.k, s.n, _params);
            for(i=0; i<=s.k-1; i++)
            {
                for(j=0; j<=s.n-1; j++)
                {
                    s.q[i,j] = q[i,j];
                }
                s.r[i] = r[i];
            }
            s.issecondarytermchanged = true;
        }


        /*************************************************************************
        This subroutine changes active set

        INPUT PARAMETERS
            S       -   model
            X       -   array[N], constraint values
            ActiveSet-  array[N], active set. If ActiveSet[I]=True, then I-th
                        variables is constrained to X[I].

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmsetactiveset(convexquadraticmodel s,
            double[] x,
            bool[] activeset,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(alglib.ap.len(x)>=s.n, "CQMSetActiveSet: Length(X)<N");
            alglib.ap.assert(alglib.ap.len(activeset)>=s.n, "CQMSetActiveSet: Length(ActiveSet)<N");
            for(i=0; i<=s.n-1; i++)
            {
                s.isactivesetchanged = s.isactivesetchanged || (s.activeset[i] && !activeset[i]);
                s.isactivesetchanged = s.isactivesetchanged || (activeset[i] && !s.activeset[i]);
                s.activeset[i] = activeset[i];
                if( activeset[i] )
                {
                    alglib.ap.assert(math.isfinite(x[i]), "CQMSetActiveSet: X[] contains infinite constraints");
                    s.isactivesetchanged = s.isactivesetchanged || (double)(s.xc[i])!=(double)(x[i]);
                    s.xc[i] = x[i];
                }
            }
        }


        /*************************************************************************
        This subroutine evaluates model at X. Active constraints are ignored.

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static double cqmeval(convexquadraticmodel s,
            double[] x,
            alglib.xparams _params)
        {
            double result = 0;
            int n = 0;
            int i = 0;
            int j = 0;
            double v = 0;
            int i_ = 0;

            n = s.n;
            alglib.ap.assert(apserv.isfinitevector(x, n, _params), "CQMEval: X is not finite vector");
            result = 0.0;
            
            //
            // main quadratic term
            //
            if( (double)(s.alpha)>(double)(0) )
            {
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        result = result+s.alpha*0.5*x[i]*s.a[i,j]*x[j];
                    }
                }
            }
            if( (double)(s.tau)>(double)(0) )
            {
                for(i=0; i<=n-1; i++)
                {
                    result = result+0.5*math.sqr(x[i])*s.tau*s.d[i];
                }
            }
            
            //
            // secondary quadratic term
            //
            if( (double)(s.theta)>(double)(0) )
            {
                for(i=0; i<=s.k-1; i++)
                {
                    v = 0.0;
                    for(i_=0; i_<=n-1;i_++)
                    {
                        v += s.q[i,i_]*x[i_];
                    }
                    result = result+0.5*s.theta*math.sqr(v-s.r[i]);
                }
            }
            
            //
            // linear term
            //
            for(i=0; i<=s.n-1; i++)
            {
                result = result+x[i]*s.b[i];
            }
            return result;
        }


        /*************************************************************************
        This subroutine evaluates model at X. Active constraints are ignored.
        It returns:
            R   -   model value
            Noise-  estimate of the numerical noise in data

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmevalx(convexquadraticmodel s,
            double[] x,
            ref double r,
            ref double noise,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            int j = 0;
            double v = 0;
            double v2 = 0;
            double mxq = 0;
            double eps = 0;

            r = 0;
            noise = 0;

            n = s.n;
            alglib.ap.assert(apserv.isfinitevector(x, n, _params), "CQMEval: X is not finite vector");
            r = 0.0;
            noise = 0.0;
            eps = 2*math.machineepsilon;
            mxq = 0.0;
            
            //
            // Main quadratic term.
            //
            // Noise from the main quadratic term is equal to the
            // maximum summand in the term.
            //
            if( (double)(s.alpha)>(double)(0) )
            {
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=n-1; j++)
                    {
                        v = s.alpha*0.5*x[i]*s.a[i,j]*x[j];
                        r = r+v;
                        noise = Math.Max(noise, eps*Math.Abs(v));
                    }
                }
            }
            if( (double)(s.tau)>(double)(0) )
            {
                for(i=0; i<=n-1; i++)
                {
                    v = 0.5*math.sqr(x[i])*s.tau*s.d[i];
                    r = r+v;
                    noise = Math.Max(noise, eps*Math.Abs(v));
                }
            }
            
            //
            // secondary quadratic term
            //
            // Noise from the secondary quadratic term is estimated as follows:
            // * noise in qi*x-r[i] is estimated as
            //   Eps*MXQ = Eps*max(|r[i]|, |q[i,j]*x[j]|)
            // * noise in (qi*x-r[i])^2 is estimated as
            //   NOISE = (|qi*x-r[i]|+Eps*MXQ)^2-(|qi*x-r[i]|)^2
            //         = Eps*MXQ*(2*|qi*x-r[i]|+Eps*MXQ)
            //
            if( (double)(s.theta)>(double)(0) )
            {
                for(i=0; i<=s.k-1; i++)
                {
                    v = 0.0;
                    mxq = Math.Abs(s.r[i]);
                    for(j=0; j<=n-1; j++)
                    {
                        v2 = s.q[i,j]*x[j];
                        v = v+v2;
                        mxq = Math.Max(mxq, Math.Abs(v2));
                    }
                    r = r+0.5*s.theta*math.sqr(v-s.r[i]);
                    noise = Math.Max(noise, eps*mxq*(2*Math.Abs(v-s.r[i])+eps*mxq));
                }
            }
            
            //
            // linear term
            //
            for(i=0; i<=s.n-1; i++)
            {
                r = r+x[i]*s.b[i];
                noise = Math.Max(noise, eps*Math.Abs(x[i]*s.b[i]));
            }
            
            //
            // Final update of the noise
            //
            noise = n*noise;
        }


        /*************************************************************************
        This  subroutine  evaluates  gradient of the model; active constraints are
        ignored.

        INPUT PARAMETERS:
            S       -   convex model
            X       -   point, array[N]
            G       -   possibly preallocated buffer; resized, if too small

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmgradunconstrained(convexquadraticmodel s,
            double[] x,
            ref double[] g,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            int j = 0;
            double v = 0;
            int i_ = 0;

            n = s.n;
            alglib.ap.assert(apserv.isfinitevector(x, n, _params), "CQMEvalGradUnconstrained: X is not finite vector");
            apserv.rvectorsetlengthatleast(ref g, n, _params);
            for(i=0; i<=n-1; i++)
            {
                g[i] = 0;
            }
            
            //
            // main quadratic term
            //
            if( (double)(s.alpha)>(double)(0) )
            {
                for(i=0; i<=n-1; i++)
                {
                    v = 0.0;
                    for(j=0; j<=n-1; j++)
                    {
                        v = v+s.alpha*s.a[i,j]*x[j];
                    }
                    g[i] = g[i]+v;
                }
            }
            if( (double)(s.tau)>(double)(0) )
            {
                for(i=0; i<=n-1; i++)
                {
                    g[i] = g[i]+x[i]*s.tau*s.d[i];
                }
            }
            
            //
            // secondary quadratic term
            //
            if( (double)(s.theta)>(double)(0) )
            {
                for(i=0; i<=s.k-1; i++)
                {
                    v = 0.0;
                    for(i_=0; i_<=n-1;i_++)
                    {
                        v += s.q[i,i_]*x[i_];
                    }
                    v = s.theta*(v-s.r[i]);
                    for(i_=0; i_<=n-1;i_++)
                    {
                        g[i_] = g[i_] + v*s.q[i,i_];
                    }
                }
            }
            
            //
            // linear term
            //
            for(i=0; i<=n-1; i++)
            {
                g[i] = g[i]+s.b[i];
            }
        }


        /*************************************************************************
        This subroutine evaluates x'*(0.5*alpha*A+tau*D)*x

        NOTE: Tmp[] must be preallocated array whose length is at least N

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static double cqmxtadx2(convexquadraticmodel s,
            double[] x,
            double[] tmp,
            alglib.xparams _params)
        {
            double result = 0;
            int n = 0;
            int i = 0;

            n = s.n;
            alglib.ap.assert(apserv.isfinitevector(x, n, _params), "CQMXTADX2: X is not finite vector");
            alglib.ap.assert(alglib.ap.len(tmp)>=n, "CQMXTADX2: Length(Tmp)<N");
            result = 0.0;
            
            //
            // main quadratic term
            //
            if( (double)(s.alpha)>(double)(0) )
            {
                result = result+s.alpha*0.5*ablas.rmatrixsyvmv(n, s.a, 0, 0, true, x, 0, tmp, _params);
            }
            if( (double)(s.tau)>(double)(0) )
            {
                for(i=0; i<=n-1; i++)
                {
                    result = result+0.5*math.sqr(x[i])*s.tau*s.d[i];
                }
            }
            return result;
        }


        /*************************************************************************
        This subroutine evaluates (0.5*alpha*A+tau*D)*x

        Y is automatically resized if needed

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmadx(convexquadraticmodel s,
            double[] x,
            ref double[] y,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;

            n = s.n;
            alglib.ap.assert(apserv.isfinitevector(x, n, _params), "CQMEval: X is not finite vector");
            apserv.rvectorsetlengthatleast(ref y, n, _params);
            
            //
            // main quadratic term
            //
            for(i=0; i<=n-1; i++)
            {
                y[i] = 0;
            }
            if( (double)(s.alpha)>(double)(0) )
            {
                ablas.rmatrixsymv(n, s.alpha, s.a, 0, 0, true, x, 0, 1.0, y, 0, _params);
            }
            if( (double)(s.tau)>(double)(0) )
            {
                for(i=0; i<=n-1; i++)
                {
                    y[i] = y[i]+x[i]*s.tau*s.d[i];
                }
            }
        }


        /*************************************************************************
        This subroutine finds optimum of the model. It returns  False  on  failure
        (indefinite/semidefinite matrix).  Optimum  is  found  subject  to  active
        constraints.

        INPUT PARAMETERS
            S       -   model
            X       -   possibly preallocated buffer; automatically resized, if
                        too small enough.

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static bool cqmconstrainedoptimum(convexquadraticmodel s,
            ref double[] x,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int nfree = 0;
            int k = 0;
            int i = 0;
            double v = 0;
            int cidx0 = 0;
            int itidx = 0;
            int i_ = 0;

            
            //
            // Rebuild internal structures
            //
            if( !cqmrebuild(s, _params) )
            {
                result = false;
                return result;
            }
            n = s.n;
            k = s.k;
            nfree = s.nfree;
            result = true;
            
            //
            // Calculate initial point for the iterative refinement:
            // * free components are set to zero
            // * constrained components are set to their constrained values
            //
            apserv.rvectorsetlengthatleast(ref x, n, _params);
            for(i=0; i<=n-1; i++)
            {
                if( s.activeset[i] )
                {
                    x[i] = s.xc[i];
                }
                else
                {
                    x[i] = 0;
                }
            }
            
            //
            // Iterative refinement.
            //
            // In an ideal world without numerical errors it would be enough
            // to make just one Newton step from initial point:
            //   x_new = -H^(-1)*grad(x=0)
            // However, roundoff errors can significantly deteriorate quality
            // of the solution. So we have to recalculate gradient and to
            // perform Newton steps several times.
            //
            // Below we perform fixed number of Newton iterations.
            //
            for(itidx=0; itidx<=newtonrefinementits-1; itidx++)
            {
                
                //
                // Calculate gradient at the current point.
                // Move free components of the gradient in the beginning.
                //
                cqmgradunconstrained(s, x, ref s.tmpg, _params);
                cidx0 = 0;
                for(i=0; i<=n-1; i++)
                {
                    if( !s.activeset[i] )
                    {
                        s.tmpg[cidx0] = s.tmpg[i];
                        cidx0 = cidx0+1;
                    }
                }
                
                //
                // Free components of the extrema are calculated in the first NFree elements of TXC.
                //
                // First, we have to calculate original Newton step, without rank-K perturbations
                //
                for(i_=0; i_<=nfree-1;i_++)
                {
                    s.txc[i_] = -s.tmpg[i_];
                }
                cqmsolveea(s, ref s.txc, ref s.tmp0, _params);
                
                //
                // Then, we account for rank-K correction.
                // Woodbury matrix identity is used.
                //
                if( s.k>0 && (double)(s.theta)>(double)(0) )
                {
                    apserv.rvectorsetlengthatleast(ref s.tmp0, Math.Max(nfree, k), _params);
                    apserv.rvectorsetlengthatleast(ref s.tmp1, Math.Max(nfree, k), _params);
                    for(i_=0; i_<=nfree-1;i_++)
                    {
                        s.tmp1[i_] = -s.tmpg[i_];
                    }
                    cqmsolveea(s, ref s.tmp1, ref s.tmp0, _params);
                    for(i=0; i<=k-1; i++)
                    {
                        v = 0.0;
                        for(i_=0; i_<=nfree-1;i_++)
                        {
                            v += s.eq[i,i_]*s.tmp1[i_];
                        }
                        s.tmp0[i] = v;
                    }
                    fbls.fblscholeskysolve(s.eccm, 1.0, k, true, s.tmp0, ref s.tmp1, _params);
                    for(i=0; i<=nfree-1; i++)
                    {
                        s.tmp1[i] = 0.0;
                    }
                    for(i=0; i<=k-1; i++)
                    {
                        v = s.tmp0[i];
                        for(i_=0; i_<=nfree-1;i_++)
                        {
                            s.tmp1[i_] = s.tmp1[i_] + v*s.eq[i,i_];
                        }
                    }
                    cqmsolveea(s, ref s.tmp1, ref s.tmp0, _params);
                    for(i_=0; i_<=nfree-1;i_++)
                    {
                        s.txc[i_] = s.txc[i_] - s.tmp1[i_];
                    }
                }
                
                //
                // Unpack components from TXC into X. We pass through all
                // free components of X and add our step.
                //
                cidx0 = 0;
                for(i=0; i<=n-1; i++)
                {
                    if( !s.activeset[i] )
                    {
                        x[i] = x[i]+s.txc[cidx0];
                        cidx0 = cidx0+1;
                    }
                }
            }
            return result;
        }


        /*************************************************************************
        This function scales vector  by  multiplying it by inverse of the diagonal
        of the Hessian matrix. It should be used to  accelerate  steepest  descent
        phase of the QP solver.

        Although  it  is  called  "scale-grad",  it  can be called for any vector,
        whether it is gradient, anti-gradient, or just some vector.

        This function does NOT takes into account current set of  constraints,  it
        just performs matrix-vector multiplication  without  taking  into  account
        constraints.

        INPUT PARAMETERS:
            S       -   model
            X       -   vector to scale

        OUTPUT PARAMETERS:
            X       -   scaled vector
            
        NOTE:
            when called for non-SPD matrices, it silently skips components of X
            which correspond to zero or negative diagonal elements.
            
        NOTE:
            this function uses diagonals of A and D; it ignores Q - rank-K term of
            the quadratic model.

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmscalevector(convexquadraticmodel s,
            ref double[] x,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            double v = 0;

            n = s.n;
            for(i=0; i<=n-1; i++)
            {
                v = 0.0;
                if( (double)(s.alpha)>(double)(0) )
                {
                    v = v+s.a[i,i];
                }
                if( (double)(s.tau)>(double)(0) )
                {
                    v = v+s.d[i];
                }
                if( (double)(v)>(double)(0) )
                {
                    x[i] = x[i]/v;
                }
            }
        }


        /*************************************************************************
        This function returns diagonal of the A-term.

        INPUT PARAMETERS:
            S       -   model

        OUTPUT PARAMETERS:
            D       -   diagonal of the A (or zero)

          -- ALGLIB --
             Copyright 26.12.2017 by Bochkanov Sergey
        *************************************************************************/
        public static void cqmgetdiaga(convexquadraticmodel s,
            ref double[] x,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;

            n = s.n;
            apserv.rvectorsetlengthatleast(ref x, n, _params);
            for(i=0; i<=n-1; i++)
            {
                if( (double)(s.alpha)>(double)(0) )
                {
                    x[i] = s.a[i,i];
                }
                else
                {
                    x[i] = 0;
                }
            }
        }


        /*************************************************************************
        This subroutine calls CQMRebuild() and evaluates model at X subject to
        active constraints.

        It  is  intended  for  debug  purposes only, because it evaluates model by
        means of temporaries, which were calculated  by  CQMRebuild().  The   only
        purpose of this function  is  to  check  correctness  of  CQMRebuild()  by
        comparing results of this function with ones obtained by CQMEval(),  which
        is  used  as  reference  point. The  idea is that significant deviation in
        results  of  these  two  functions  is  evidence  of  some  error  in  the
        CQMRebuild().

        NOTE: suffix T denotes that temporaries marked by T-prefix are used. There
              is one more variant of this function, which uses  "effective"  model
              built by CQMRebuild().

        NOTE2: in case CQMRebuild() fails (due to model non-convexity), this
              function returns NAN.

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static double cqmdebugconstrainedevalt(convexquadraticmodel s,
            double[] x,
            alglib.xparams _params)
        {
            double result = 0;
            int n = 0;
            int nfree = 0;
            int i = 0;
            int j = 0;
            double v = 0;

            n = s.n;
            alglib.ap.assert(apserv.isfinitevector(x, n, _params), "CQMDebugConstrainedEvalT: X is not finite vector");
            if( !cqmrebuild(s, _params) )
            {
                result = Double.NaN;
                return result;
            }
            result = 0.0;
            nfree = s.nfree;
            
            //
            // Reorder variables
            //
            j = 0;
            for(i=0; i<=n-1; i++)
            {
                if( !s.activeset[i] )
                {
                    alglib.ap.assert(j<nfree, "CQMDebugConstrainedEvalT: internal error");
                    s.txc[j] = x[i];
                    j = j+1;
                }
            }
            
            //
            // TQ2, TQ1, TQ0
            //
            //
            if( (double)(s.alpha)>(double)(0) )
            {
                
                //
                // Dense TQ2
                //
                for(i=0; i<=nfree-1; i++)
                {
                    for(j=0; j<=nfree-1; j++)
                    {
                        result = result+0.5*s.txc[i]*s.tq2dense[i,j]*s.txc[j];
                    }
                }
            }
            else
            {
                
                //
                // Diagonal TQ2
                //
                for(i=0; i<=nfree-1; i++)
                {
                    result = result+0.5*s.tq2diag[i]*math.sqr(s.txc[i]);
                }
            }
            for(i=0; i<=nfree-1; i++)
            {
                result = result+s.tq1[i]*s.txc[i];
            }
            result = result+s.tq0;
            
            //
            // TK2, TK1, TK0
            //
            if( s.k>0 && (double)(s.theta)>(double)(0) )
            {
                for(i=0; i<=s.k-1; i++)
                {
                    v = 0;
                    for(j=0; j<=nfree-1; j++)
                    {
                        v = v+s.tk2[i,j]*s.txc[j];
                    }
                    result = result+0.5*math.sqr(v);
                }
                for(i=0; i<=nfree-1; i++)
                {
                    result = result+s.tk1[i]*s.txc[i];
                }
                result = result+s.tk0;
            }
            
            //
            // TB (Bf and Bc parts)
            //
            for(i=0; i<=n-1; i++)
            {
                result = result+s.tb[i]*s.txc[i];
            }
            return result;
        }


        /*************************************************************************
        This subroutine calls CQMRebuild() and evaluates model at X subject to
        active constraints.

        It  is  intended  for  debug  purposes only, because it evaluates model by
        means of "effective" matrices built by CQMRebuild(). The only  purpose  of
        this function is to check correctness of CQMRebuild() by comparing results
        of this function with  ones  obtained  by  CQMEval(),  which  is  used  as
        reference  point.  The  idea  is  that significant deviation in results of
        these two functions is evidence of some error in the CQMRebuild().

        NOTE: suffix E denotes that effective matrices. There is one more  variant
              of this function, which uses temporary matrices built by
              CQMRebuild().

        NOTE2: in case CQMRebuild() fails (due to model non-convexity), this
              function returns NAN.

          -- ALGLIB --
             Copyright 12.06.2012 by Bochkanov Sergey
        *************************************************************************/
        public static double cqmdebugconstrainedevale(convexquadraticmodel s,
            double[] x,
            alglib.xparams _params)
        {
            double result = 0;
            int n = 0;
            int nfree = 0;
            int i = 0;
            int j = 0;
            double v = 0;

            n = s.n;
            alglib.ap.assert(apserv.isfinitevector(x, n, _params), "CQMDebugConstrainedEvalE: X is not finite vector");
            if( !cqmrebuild(s, _params) )
            {
                result = Double.NaN;
                return result;
            }
            result = 0.0;
            nfree = s.nfree;
            
            //
            // Reorder variables
            //
            j = 0;
            for(i=0; i<=n-1; i++)
            {
                if( !s.activeset[i] )
                {
                    alglib.ap.assert(j<nfree, "CQMDebugConstrainedEvalE: internal error");
                    s.txc[j] = x[i];
                    j = j+1;
                }
            }
            
            //
            // ECA
            //
            alglib.ap.assert((s.ecakind==0 || s.ecakind==1) || (s.ecakind==-1 && nfree==0), "CQMDebugConstrainedEvalE: unexpected ECAKind");
            if( s.ecakind==0 )
            {
                
                //
                // Dense ECA
                //
                for(i=0; i<=nfree-1; i++)
                {
                    v = 0.0;
                    for(j=i; j<=nfree-1; j++)
                    {
                        v = v+s.ecadense[i,j]*s.txc[j];
                    }
                    result = result+0.5*math.sqr(v);
                }
            }
            if( s.ecakind==1 )
            {
                
                //
                // Diagonal ECA
                //
                for(i=0; i<=nfree-1; i++)
                {
                    result = result+0.5*math.sqr(s.ecadiag[i]*s.txc[i]);
                }
            }
            
            //
            // EQ
            //
            for(i=0; i<=s.k-1; i++)
            {
                v = 0.0;
                for(j=0; j<=nfree-1; j++)
                {
                    v = v+s.eq[i,j]*s.txc[j];
                }
                result = result+0.5*math.sqr(v);
            }
            
            //
            // EB
            //
            for(i=0; i<=nfree-1; i++)
            {
                result = result+s.eb[i]*s.txc[i];
            }
            
            //
            // EC
            //
            result = result+s.ec;
            return result;
        }


        /*************************************************************************
        Internal function, rebuilds "effective" model subject to constraints.
        Returns False on failure (non-SPD main quadratic term)

          -- ALGLIB --
             Copyright 10.05.2011 by Bochkanov Sergey
        *************************************************************************/
        private static bool cqmrebuild(convexquadraticmodel s,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int nfree = 0;
            int k = 0;
            int i = 0;
            int j = 0;
            int ridx0 = 0;
            int ridx1 = 0;
            int cidx0 = 0;
            int cidx1 = 0;
            double v = 0;
            int i_ = 0;

            if( (double)(s.alpha)==(double)(0) && (double)(s.tau)==(double)(0) )
            {
                
                //
                // Non-SPD model, quick exit
                //
                result = false;
                return result;
            }
            result = true;
            n = s.n;
            k = s.k;
            
            //
            // Determine number of free variables.
            // Fill TXC - array whose last N-NFree elements store constraints.
            //
            if( s.isactivesetchanged )
            {
                s.nfree = 0;
                for(i=0; i<=n-1; i++)
                {
                    if( !s.activeset[i] )
                    {
                        s.nfree = s.nfree+1;
                    }
                }
                j = s.nfree;
                for(i=0; i<=n-1; i++)
                {
                    if( s.activeset[i] )
                    {
                        s.txc[j] = s.xc[i];
                        j = j+1;
                    }
                }
            }
            nfree = s.nfree;
            
            //
            // Re-evaluate TQ2/TQ1/TQ0, if needed
            //
            if( s.isactivesetchanged || s.ismaintermchanged )
            {
                
                //
                // Handle cases Alpha>0 and Alpha=0 separately:
                // * in the first case we have dense matrix
                // * in the second one we have diagonal matrix, which can be
                //   handled more efficiently
                //
                if( (double)(s.alpha)>(double)(0) )
                {
                    
                    //
                    // Alpha>0, dense QP
                    //
                    // Split variables into two groups - free (F) and constrained (C). Reorder
                    // variables in such way that free vars come first, constrained are last:
                    // x = [xf, xc].
                    // 
                    // Main quadratic term x'*(alpha*A+tau*D)*x now splits into quadratic part,
                    // linear part and constant part:
                    //                   ( alpha*Aff+tau*Df  alpha*Afc        ) ( xf )              
                    //   0.5*( xf' xc' )*(                                    )*(    ) =
                    //                   ( alpha*Acf         alpha*Acc+tau*Dc ) ( xc )
                    //
                    //   = 0.5*xf'*(alpha*Aff+tau*Df)*xf + (alpha*Afc*xc)'*xf + 0.5*xc'(alpha*Acc+tau*Dc)*xc
                    //                    
                    // We store these parts into temporary variables:
                    // * alpha*Aff+tau*Df, alpha*Afc, alpha*Acc+tau*Dc are stored into upper
                    //   triangle of TQ2
                    // * alpha*Afc*xc is stored into TQ1
                    // * 0.5*xc'(alpha*Acc+tau*Dc)*xc is stored into TQ0
                    //
                    // Below comes first part of the work - generation of TQ2:
                    // * we pass through rows of A and copy I-th row into upper block (Aff/Afc) or
                    //   lower one (Acf/Acc) of TQ2, depending on presence of X[i] in the active set.
                    //   RIdx0 variable contains current position for insertion into upper block,
                    //   RIdx1 contains current position for insertion into lower one.
                    // * within each row, we copy J-th element into left half (Aff/Acf) or right
                    //   one (Afc/Acc), depending on presence of X[j] in the active set. CIdx0
                    //   contains current position for insertion into left block, CIdx1 contains
                    //   position for insertion into right one.
                    // * during copying, we multiply elements by alpha and add diagonal matrix D.
                    //
                    ridx0 = 0;
                    ridx1 = s.nfree;
                    for(i=0; i<=n-1; i++)
                    {
                        cidx0 = 0;
                        cidx1 = s.nfree;
                        for(j=0; j<=n-1; j++)
                        {
                            if( !s.activeset[i] && !s.activeset[j] )
                            {
                                
                                //
                                // Element belongs to Aff
                                //
                                v = s.alpha*s.a[i,j];
                                if( i==j && (double)(s.tau)>(double)(0) )
                                {
                                    v = v+s.tau*s.d[i];
                                }
                                s.tq2dense[ridx0,cidx0] = v;
                            }
                            if( !s.activeset[i] && s.activeset[j] )
                            {
                                
                                //
                                // Element belongs to Afc
                                //
                                s.tq2dense[ridx0,cidx1] = s.alpha*s.a[i,j];
                            }
                            if( s.activeset[i] && !s.activeset[j] )
                            {
                                
                                //
                                // Element belongs to Acf
                                //
                                s.tq2dense[ridx1,cidx0] = s.alpha*s.a[i,j];
                            }
                            if( s.activeset[i] && s.activeset[j] )
                            {
                                
                                //
                                // Element belongs to Acc
                                //
                                v = s.alpha*s.a[i,j];
                                if( i==j && (double)(s.tau)>(double)(0) )
                                {
                                    v = v+s.tau*s.d[i];
                                }
                                s.tq2dense[ridx1,cidx1] = v;
                            }
                            if( s.activeset[j] )
                            {
                                cidx1 = cidx1+1;
                            }
                            else
                            {
                                cidx0 = cidx0+1;
                            }
                        }
                        if( s.activeset[i] )
                        {
                            ridx1 = ridx1+1;
                        }
                        else
                        {
                            ridx0 = ridx0+1;
                        }
                    }
                    
                    //
                    // Now we have TQ2, and we can evaluate TQ1.
                    // In the special case when we have Alpha=0, NFree=0 or NFree=N,
                    // TQ1 is filled by zeros.
                    //
                    for(i=0; i<=n-1; i++)
                    {
                        s.tq1[i] = 0.0;
                    }
                    if( s.nfree>0 && s.nfree<n )
                    {
                        ablas.rmatrixmv(s.nfree, n-s.nfree, s.tq2dense, 0, s.nfree, 0, s.txc, s.nfree, s.tq1, 0, _params);
                    }
                    
                    //
                    // And finally, we evaluate TQ0.
                    //
                    v = 0.0;
                    for(i=s.nfree; i<=n-1; i++)
                    {
                        for(j=s.nfree; j<=n-1; j++)
                        {
                            v = v+0.5*s.txc[i]*s.tq2dense[i,j]*s.txc[j];
                        }
                    }
                    s.tq0 = v;
                }
                else
                {
                    
                    //
                    // Alpha=0, diagonal QP
                    //
                    // Split variables into two groups - free (F) and constrained (C). Reorder
                    // variables in such way that free vars come first, constrained are last:
                    // x = [xf, xc].
                    // 
                    // Main quadratic term x'*(tau*D)*x now splits into quadratic and constant
                    // parts:
                    //                   ( tau*Df        ) ( xf )              
                    //   0.5*( xf' xc' )*(               )*(    ) =
                    //                   (        tau*Dc ) ( xc )
                    //
                    //   = 0.5*xf'*(tau*Df)*xf + 0.5*xc'(tau*Dc)*xc
                    //                    
                    // We store these parts into temporary variables:
                    // * tau*Df is stored in TQ2Diag
                    // * 0.5*xc'(tau*Dc)*xc is stored into TQ0
                    //
                    s.tq0 = 0.0;
                    ridx0 = 0;
                    for(i=0; i<=n-1; i++)
                    {
                        if( !s.activeset[i] )
                        {
                            s.tq2diag[ridx0] = s.tau*s.d[i];
                            ridx0 = ridx0+1;
                        }
                        else
                        {
                            s.tq0 = s.tq0+0.5*s.tau*s.d[i]*math.sqr(s.xc[i]);
                        }
                    }
                    for(i=0; i<=n-1; i++)
                    {
                        s.tq1[i] = 0.0;
                    }
                }
            }
            
            //
            // Re-evaluate TK2/TK1/TK0, if needed
            //
            if( s.isactivesetchanged || s.issecondarytermchanged )
            {
                
                //
                // Split variables into two groups - free (F) and constrained (C). Reorder
                // variables in such way that free vars come first, constrained are last:
                // x = [xf, xc].
                // 
                // Secondary term theta*(Q*x-r)'*(Q*x-r) now splits into quadratic part,
                // linear part and constant part:
                //             (          ( xf )     )'  (          ( xf )     )
                //   0.5*theta*( (Qf Qc)'*(    ) - r ) * ( (Qf Qc)'*(    ) - r ) =
                //             (          ( xc )     )   (          ( xc )     )
                //
                //   = 0.5*theta*xf'*(Qf'*Qf)*xf + theta*((Qc*xc-r)'*Qf)*xf + 
                //     + theta*(-r'*(Qc*xc-r)-0.5*r'*r+0.5*xc'*Qc'*Qc*xc)
                //                    
                // We store these parts into temporary variables:
                // * sqrt(theta)*Qf is stored into TK2
                // * theta*((Qc*xc-r)'*Qf) is stored into TK1
                // * theta*(-r'*(Qc*xc-r)-0.5*r'*r+0.5*xc'*Qc'*Qc*xc) is stored into TK0
                //
                // We use several other temporaries to store intermediate results:
                // * Tmp0 - to store Qc*xc-r
                // * Tmp1 - to store Qc*xc
                //
                // Generation of TK2/TK1/TK0 is performed as follows:
                // * we fill TK2/TK1/TK0 (to handle K=0 or Theta=0)
                // * other steps are performed only for K>0 and Theta>0
                // * we pass through columns of Q and copy I-th column into left block (Qf) or
                //   right one (Qc) of TK2, depending on presence of X[i] in the active set.
                //   CIdx0 variable contains current position for insertion into upper block,
                //   CIdx1 contains current position for insertion into lower one.
                // * we calculate Qc*xc-r and store it into Tmp0
                // * we calculate TK0 and TK1
                // * we multiply leading part of TK2 which stores Qf by sqrt(theta)
                //   it is important to perform this step AFTER calculation of TK0 and TK1,
                //   because we need original (non-modified) Qf to calculate TK0 and TK1.
                //
                for(j=0; j<=n-1; j++)
                {
                    for(i=0; i<=k-1; i++)
                    {
                        s.tk2[i,j] = 0.0;
                    }
                    s.tk1[j] = 0.0;
                }
                s.tk0 = 0.0;
                if( s.k>0 && (double)(s.theta)>(double)(0) )
                {
                    
                    //
                    // Split Q into Qf and Qc
                    // Calculate Qc*xc-r, store in Tmp0
                    //
                    apserv.rvectorsetlengthatleast(ref s.tmp0, k, _params);
                    apserv.rvectorsetlengthatleast(ref s.tmp1, k, _params);
                    cidx0 = 0;
                    cidx1 = nfree;
                    for(i=0; i<=k-1; i++)
                    {
                        s.tmp1[i] = 0.0;
                    }
                    for(j=0; j<=n-1; j++)
                    {
                        if( s.activeset[j] )
                        {
                            for(i=0; i<=k-1; i++)
                            {
                                s.tk2[i,cidx1] = s.q[i,j];
                                s.tmp1[i] = s.tmp1[i]+s.q[i,j]*s.txc[cidx1];
                            }
                            cidx1 = cidx1+1;
                        }
                        else
                        {
                            for(i=0; i<=k-1; i++)
                            {
                                s.tk2[i,cidx0] = s.q[i,j];
                            }
                            cidx0 = cidx0+1;
                        }
                    }
                    for(i=0; i<=k-1; i++)
                    {
                        s.tmp0[i] = s.tmp1[i]-s.r[i];
                    }
                    
                    //
                    // Calculate TK0
                    //
                    v = 0.0;
                    for(i=0; i<=k-1; i++)
                    {
                        v = v+s.theta*(0.5*math.sqr(s.tmp1[i])-s.r[i]*s.tmp0[i]-0.5*math.sqr(s.r[i]));
                    }
                    s.tk0 = v;
                    
                    //
                    // Calculate TK1
                    //
                    if( nfree>0 )
                    {
                        for(i=0; i<=k-1; i++)
                        {
                            v = s.theta*s.tmp0[i];
                            for(i_=0; i_<=nfree-1;i_++)
                            {
                                s.tk1[i_] = s.tk1[i_] + v*s.tk2[i,i_];
                            }
                        }
                    }
                    
                    //
                    // Calculate TK2
                    //
                    if( nfree>0 )
                    {
                        v = Math.Sqrt(s.theta);
                        for(i=0; i<=k-1; i++)
                        {
                            for(i_=0; i_<=nfree-1;i_++)
                            {
                                s.tk2[i,i_] = v*s.tk2[i,i_];
                            }
                        }
                    }
                }
            }
            
            //
            // Re-evaluate TB
            //
            if( s.isactivesetchanged || s.islineartermchanged )
            {
                ridx0 = 0;
                ridx1 = nfree;
                for(i=0; i<=n-1; i++)
                {
                    if( s.activeset[i] )
                    {
                        s.tb[ridx1] = s.b[i];
                        ridx1 = ridx1+1;
                    }
                    else
                    {
                        s.tb[ridx0] = s.b[i];
                        ridx0 = ridx0+1;
                    }
                }
            }
            
            //
            // Compose ECA: either dense ECA or diagonal ECA
            //
            if( (s.isactivesetchanged || s.ismaintermchanged) && nfree>0 )
            {
                if( (double)(s.alpha)>(double)(0) )
                {
                    
                    //
                    // Dense ECA
                    //
                    s.ecakind = 0;
                    for(i=0; i<=nfree-1; i++)
                    {
                        for(j=i; j<=nfree-1; j++)
                        {
                            s.ecadense[i,j] = s.tq2dense[i,j];
                        }
                    }
                    if( !trfac.spdmatrixcholeskyrec(s.ecadense, 0, nfree, true, ref s.tmp0, _params) )
                    {
                        result = false;
                        return result;
                    }
                }
                else
                {
                    
                    //
                    // Diagonal ECA
                    //
                    s.ecakind = 1;
                    for(i=0; i<=nfree-1; i++)
                    {
                        if( (double)(s.tq2diag[i])<(double)(0) )
                        {
                            result = false;
                            return result;
                        }
                        s.ecadiag[i] = Math.Sqrt(s.tq2diag[i]);
                    }
                }
            }
            
            //
            // Compose EQ
            //
            if( s.isactivesetchanged || s.issecondarytermchanged )
            {
                for(i=0; i<=k-1; i++)
                {
                    for(j=0; j<=nfree-1; j++)
                    {
                        s.eq[i,j] = s.tk2[i,j];
                    }
                }
            }
            
            //
            // Calculate ECCM
            //
            if( ((((s.isactivesetchanged || s.ismaintermchanged) || s.issecondarytermchanged) && s.k>0) && (double)(s.theta)>(double)(0)) && nfree>0 )
            {
                
                //
                // Calculate ECCM - Cholesky factor of the "effective" capacitance
                // matrix CM = I + EQ*inv(EffectiveA)*EQ'.
                //
                // We calculate CM as follows:
                //   CM = I + EQ*inv(EffectiveA)*EQ'
                //      = I + EQ*ECA^(-1)*ECA^(-T)*EQ'
                //      = I + (EQ*ECA^(-1))*(EQ*ECA^(-1))'
                //
                // Then we perform Cholesky decomposition of CM.
                //
                apserv.rmatrixsetlengthatleast(ref s.tmp2, k, n, _params);
                ablas.rmatrixcopy(k, nfree, s.eq, 0, 0, s.tmp2, 0, 0, _params);
                alglib.ap.assert(s.ecakind==0 || s.ecakind==1, "CQMRebuild: unexpected ECAKind");
                if( s.ecakind==0 )
                {
                    ablas.rmatrixrighttrsm(k, nfree, s.ecadense, 0, 0, true, false, 0, s.tmp2, 0, 0, _params);
                }
                if( s.ecakind==1 )
                {
                    for(i=0; i<=k-1; i++)
                    {
                        for(j=0; j<=nfree-1; j++)
                        {
                            s.tmp2[i,j] = s.tmp2[i,j]/s.ecadiag[j];
                        }
                    }
                }
                for(i=0; i<=k-1; i++)
                {
                    for(j=0; j<=k-1; j++)
                    {
                        s.eccm[i,j] = 0.0;
                    }
                    s.eccm[i,i] = 1.0;
                }
                ablas.rmatrixsyrk(k, nfree, 1.0, s.tmp2, 0, 0, 0, 1.0, s.eccm, 0, 0, true, _params);
                if( !trfac.spdmatrixcholeskyrec(s.eccm, 0, k, true, ref s.tmp0, _params) )
                {
                    result = false;
                    return result;
                }
            }
            
            //
            // Compose EB and EC
            //
            // NOTE: because these quantities are cheap to compute, we do not
            // use caching here.
            //
            for(i=0; i<=nfree-1; i++)
            {
                s.eb[i] = s.tq1[i]+s.tk1[i]+s.tb[i];
            }
            s.ec = s.tq0+s.tk0;
            for(i=nfree; i<=n-1; i++)
            {
                s.ec = s.ec+s.tb[i]*s.txc[i];
            }
            
            //
            // Change cache status - everything is cached 
            //
            s.ismaintermchanged = false;
            s.issecondarytermchanged = false;
            s.islineartermchanged = false;
            s.isactivesetchanged = false;
            return result;
        }


        /*************************************************************************
        Internal function, solves system Effective_A*x = b.
        It should be called after successful completion of CQMRebuild().

        INPUT PARAMETERS:
            S       -   quadratic model, after call to CQMRebuild()
            X       -   right part B, array[S.NFree]
            Tmp     -   temporary array, automatically reallocated if needed

        OUTPUT PARAMETERS:
            X       -   solution, array[S.NFree]
            
        NOTE: when called with zero S.NFree, returns silently
        NOTE: this function assumes that EA is non-degenerate

          -- ALGLIB --
             Copyright 10.05.2011 by Bochkanov Sergey
        *************************************************************************/
        private static void cqmsolveea(convexquadraticmodel s,
            ref double[] x,
            ref double[] tmp,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert((s.ecakind==0 || s.ecakind==1) || (s.ecakind==-1 && s.nfree==0), "CQMSolveEA: unexpected ECAKind");
            if( s.ecakind==0 )
            {
                
                //
                // Dense ECA, use FBLSCholeskySolve() dense solver.
                //
                fbls.fblscholeskysolve(s.ecadense, 1.0, s.nfree, true, x, ref tmp, _params);
            }
            if( s.ecakind==1 )
            {
                
                //
                // Diagonal ECA
                //
                for(i=0; i<=s.nfree-1; i++)
                {
                    x[i] = x[i]/math.sqr(s.ecadiag[i]);
                }
            }
        }


    }
    public partial class snnls
    {
        /*************************************************************************
        This structure is a SNNLS (Specialized Non-Negative Least Squares) solver.

        It solves problems of the form |A*x-b|^2 => min subject to  non-negativity
        constraints on SOME components of x, with structured A (first  NS  columns
        are just unit matrix, next ND columns store dense part).

        This solver is suited for solution of many sequential NNLS  subproblems  -
        it keeps track of previously allocated memory and reuses  it  as  much  as
        possible.
        *************************************************************************/
        public class snnlssolver : apobject
        {
            public int ns;
            public int nd;
            public int nr;
            public double[,] densea;
            public double[] b;
            public bool[] nnc;
            public double debugflops;
            public int debugmaxinnerits;
            public double[] xn;
            public double[] xp;
            public double[,] tmpca;
            public double[,] tmplq;
            public double[,] trda;
            public double[] trdd;
            public double[] crb;
            public double[] g;
            public double[] d;
            public double[] dx;
            public double[] diagaa;
            public double[] cb;
            public double[] cx;
            public double[] cborg;
            public double[] tmpcholesky;
            public double[] r;
            public double[] regdiag;
            public double[] tmp0;
            public double[] tmp1;
            public double[] tmp2;
            public int[] rdtmprowmap;
            public snnlssolver()
            {
                init();
            }
            public override void init()
            {
                densea = new double[0,0];
                b = new double[0];
                nnc = new bool[0];
                xn = new double[0];
                xp = new double[0];
                tmpca = new double[0,0];
                tmplq = new double[0,0];
                trda = new double[0,0];
                trdd = new double[0];
                crb = new double[0];
                g = new double[0];
                d = new double[0];
                dx = new double[0];
                diagaa = new double[0];
                cb = new double[0];
                cx = new double[0];
                cborg = new double[0];
                tmpcholesky = new double[0];
                r = new double[0];
                regdiag = new double[0];
                tmp0 = new double[0];
                tmp1 = new double[0];
                tmp2 = new double[0];
                rdtmprowmap = new int[0];
            }
            public override alglib.apobject make_copy()
            {
                snnlssolver _result = new snnlssolver();
                _result.ns = ns;
                _result.nd = nd;
                _result.nr = nr;
                _result.densea = (double[,])densea.Clone();
                _result.b = (double[])b.Clone();
                _result.nnc = (bool[])nnc.Clone();
                _result.debugflops = debugflops;
                _result.debugmaxinnerits = debugmaxinnerits;
                _result.xn = (double[])xn.Clone();
                _result.xp = (double[])xp.Clone();
                _result.tmpca = (double[,])tmpca.Clone();
                _result.tmplq = (double[,])tmplq.Clone();
                _result.trda = (double[,])trda.Clone();
                _result.trdd = (double[])trdd.Clone();
                _result.crb = (double[])crb.Clone();
                _result.g = (double[])g.Clone();
                _result.d = (double[])d.Clone();
                _result.dx = (double[])dx.Clone();
                _result.diagaa = (double[])diagaa.Clone();
                _result.cb = (double[])cb.Clone();
                _result.cx = (double[])cx.Clone();
                _result.cborg = (double[])cborg.Clone();
                _result.tmpcholesky = (double[])tmpcholesky.Clone();
                _result.r = (double[])r.Clone();
                _result.regdiag = (double[])regdiag.Clone();
                _result.tmp0 = (double[])tmp0.Clone();
                _result.tmp1 = (double[])tmp1.Clone();
                _result.tmp2 = (double[])tmp2.Clone();
                _result.rdtmprowmap = (int[])rdtmprowmap.Clone();
                return _result;
            }
        };




        /*************************************************************************
        This subroutine is used to initialize SNNLS solver.

        By default, empty NNLS problem is produced, but we allocated enough  space
        to store problems with NSMax+NDMax columns and  NRMax  rows.  It  is  good
        place to provide algorithm with initial estimate of the space requirements,
        although you may underestimate problem size or even pass zero estimates  -
        in this case buffer variables will be resized automatically  when  you set
        NNLS problem.

        Previously allocated buffer variables are reused as much as possible. This
        function does not clear structure completely, it tries to preserve as much
        dynamically allocated memory as possible.

          -- ALGLIB --
             Copyright 10.10.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void snnlsinit(int nsmax,
            int ndmax,
            int nrmax,
            snnlssolver s,
            alglib.xparams _params)
        {
            s.ns = 0;
            s.nd = 0;
            s.nr = 0;
            apserv.rmatrixsetlengthatleast(ref s.densea, nrmax, ndmax, _params);
            apserv.rmatrixsetlengthatleast(ref s.tmpca, nrmax, ndmax, _params);
            apserv.rvectorsetlengthatleast(ref s.b, nrmax, _params);
            apserv.bvectorsetlengthatleast(ref s.nnc, nsmax+ndmax, _params);
            s.debugflops = 0.0;
            s.debugmaxinnerits = 0;
        }


        /*************************************************************************
        This subroutine is used to set NNLS problem:

                ( [ 1     |      ]   [   ]   [   ] )^2
                ( [   1   |      ]   [   ]   [   ] )
            min ( [     1 |  Ad  ] * [ x ] - [ b ] )    s.t. x>=0
                ( [       |      ]   [   ]   [   ] )
                ( [       |      ]   [   ]   [   ] )

        where:
        * identity matrix has NS*NS size (NS<=NR, NS can be zero)
        * dense matrix Ad has NR*ND size
        * b is NR*1 vector
        * x is (NS+ND)*1 vector
        * all elements of x are non-negative (this constraint can be removed later
          by calling SNNLSDropNNC() function)

        Previously allocated buffer variables are reused as much as possible.
        After you set problem, you can solve it with SNNLSSolve().

        INPUT PARAMETERS:
            S   -   SNNLS solver, must be initialized with SNNLSInit() call
            A   -   array[NR,ND], dense part of the system
            B   -   array[NR], right part
            NS  -   size of the sparse part of the system, 0<=NS<=NR
            ND  -   size of the dense part of the system, ND>=0
            NR  -   rows count, NR>0

        NOTE:
            1. You can have NS+ND=0, solver will correctly accept such combination
               and return empty array as problem solution.
            
          -- ALGLIB --
             Copyright 10.10.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void snnlssetproblem(snnlssolver s,
            double[,] a,
            double[] b,
            int ns,
            int nd,
            int nr,
            alglib.xparams _params)
        {
            int i = 0;
            int i_ = 0;

            alglib.ap.assert(nd>=0, "SNNLSSetProblem: ND<0");
            alglib.ap.assert(ns>=0, "SNNLSSetProblem: NS<0");
            alglib.ap.assert(nr>0, "SNNLSSetProblem: NR<=0");
            alglib.ap.assert(ns<=nr, "SNNLSSetProblem: NS>NR");
            alglib.ap.assert(alglib.ap.rows(a)>=nr || nd==0, "SNNLSSetProblem: rows(A)<NR");
            alglib.ap.assert(alglib.ap.cols(a)>=nd, "SNNLSSetProblem: cols(A)<ND");
            alglib.ap.assert(alglib.ap.len(b)>=nr, "SNNLSSetProblem: length(B)<NR");
            alglib.ap.assert(apserv.apservisfinitematrix(a, nr, nd, _params), "SNNLSSetProblem: A contains INF/NAN");
            alglib.ap.assert(apserv.isfinitevector(b, nr, _params), "SNNLSSetProblem: B contains INF/NAN");
            
            //
            // Copy problem
            //
            s.ns = ns;
            s.nd = nd;
            s.nr = nr;
            if( nd>0 )
            {
                apserv.rmatrixsetlengthatleast(ref s.densea, nr, nd, _params);
                for(i=0; i<=nr-1; i++)
                {
                    for(i_=0; i_<=nd-1;i_++)
                    {
                        s.densea[i,i_] = a[i,i_];
                    }
                }
            }
            apserv.rvectorsetlengthatleast(ref s.b, nr, _params);
            for(i_=0; i_<=nr-1;i_++)
            {
                s.b[i_] = b[i_];
            }
            apserv.bvectorsetlengthatleast(ref s.nnc, ns+nd, _params);
            for(i=0; i<=ns+nd-1; i++)
            {
                s.nnc[i] = true;
            }
        }


        /*************************************************************************
        This subroutine drops non-negativity constraint from the  problem  set  by
        SNNLSSetProblem() call. This function must be called AFTER problem is set,
        because each SetProblem() call resets constraints to their  default  state
        (all constraints are present).

        INPUT PARAMETERS:
            S   -   SNNLS solver, must be initialized with SNNLSInit() call,
                    problem must be set with SNNLSSetProblem() call.
            Idx -   constraint index, 0<=IDX<NS+ND
            
          -- ALGLIB --
             Copyright 10.10.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void snnlsdropnnc(snnlssolver s,
            int idx,
            alglib.xparams _params)
        {
            alglib.ap.assert(idx>=0, "SNNLSDropNNC: Idx<0");
            alglib.ap.assert(idx<s.ns+s.nd, "SNNLSDropNNC: Idx>=NS+ND");
            s.nnc[idx] = false;
        }


        /*************************************************************************
        This subroutine is used to solve NNLS problem.

        INPUT PARAMETERS:
            S   -   SNNLS solver, must be initialized with SNNLSInit() call and
                    problem must be set up with SNNLSSetProblem() call.
            X   -   possibly preallocated buffer, automatically resized if needed

        OUTPUT PARAMETERS:
            X   -   array[NS+ND], solution
            
        NOTE:
            1. You can have NS+ND=0, solver will correctly accept such combination
               and return empty array as problem solution.
            
            2. Internal field S.DebugFLOPS contains rough estimate of  FLOPs  used
               to solve problem. It can be used for debugging purposes. This field
               is real-valued.
            
          -- ALGLIB --
             Copyright 10.10.2012 by Bochkanov Sergey
        *************************************************************************/
        public static void snnlssolve(snnlssolver s,
            ref double[] x,
            alglib.xparams _params)
        {
            int i = 0;
            int ns = 0;
            int nd = 0;
            int nr = 0;
            bool wasactivation = new bool();
            double lambdav = 0;
            double v0 = 0;
            double v1 = 0;
            double v = 0;
            int outerits = 0;
            int innerits = 0;
            int maxouterits = 0;
            double xtol = 0;
            double kicklength = 0;
            bool kickneeded = new bool();
            double f0 = 0;
            double f1 = 0;
            double dnrm = 0;
            int actidx = 0;
            double stp = 0;
            double stpmax = 0;

            
            //
            // Prepare
            //
            ns = s.ns;
            nd = s.nd;
            nr = s.nr;
            s.debugflops = 0.0;
            
            //
            // Handle special cases:
            // * NS+ND=0
            // * ND=0
            //
            if( ns+nd==0 )
            {
                return;
            }
            if( nd==0 )
            {
                apserv.rvectorsetlengthatleast(ref x, ns, _params);
                for(i=0; i<=ns-1; i++)
                {
                    x[i] = s.b[i];
                    if( s.nnc[i] )
                    {
                        x[i] = Math.Max(x[i], 0.0);
                    }
                }
                return;
            }
            
            //
            // Main cycle of BLEIC-SNNLS algorithm.
            // Below we assume that ND>0.
            //
            apserv.rvectorsetlengthatleast(ref x, ns+nd, _params);
            apserv.rvectorsetlengthatleast(ref s.xn, ns+nd, _params);
            apserv.rvectorsetlengthatleast(ref s.xp, ns+nd, _params);
            apserv.rvectorsetlengthatleast(ref s.g, ns+nd, _params);
            apserv.rvectorsetlengthatleast(ref s.d, ns+nd, _params);
            apserv.rvectorsetlengthatleast(ref s.r, nr, _params);
            apserv.rvectorsetlengthatleast(ref s.diagaa, nd, _params);
            apserv.rvectorsetlengthatleast(ref s.regdiag, ns+nd, _params);
            apserv.rvectorsetlengthatleast(ref s.dx, ns+nd, _params);
            for(i=0; i<=ns+nd-1; i++)
            {
                x[i] = 0.0;
                s.regdiag[i] = 1.0;
            }
            lambdav = 1.0E6*math.machineepsilon;
            maxouterits = 10;
            outerits = 0;
            innerits = 0;
            xtol = 1.0E3*math.machineepsilon;
            kicklength = Math.Sqrt(math.minrealnumber);
            while( true )
            {
                
                //
                // Initial check for correctness of X
                //
                for(i=0; i<=ns+nd-1; i++)
                {
                    alglib.ap.assert(!s.nnc[i] || (double)(x[i])>=(double)(0), "SNNLS: integrity check failed");
                }
                
                //
                // Calculate gradient G and constrained descent direction D
                //
                funcgradu(s, x, s.r, s.g, ref f0, _params);
                for(i=0; i<=ns+nd-1; i++)
                {
                    if( (s.nnc[i] && (double)(x[i])==(double)(0)) && (double)(s.g[i])>(double)(0) )
                    {
                        s.d[i] = 0.0;
                    }
                    else
                    {
                        s.d[i] = -s.g[i];
                    }
                }
                
                //
                // Decide whether we need "kick" stage: special stage
                // that moves us away from boundary constraints which are
                // not strictly active (i.e. such constraints that x[i]=0.0 and d[i]>0).
                //
                // If we need kick stage, we make a kick - and restart iteration.
                // If not, after this block we can rely on the fact that
                // for all x[i]=0.0 we have d[i]=0.0
                //
                // NOTE: we do not increase outer iterations counter here
                //
                kickneeded = false;
                for(i=0; i<=ns+nd-1; i++)
                {
                    if( (s.nnc[i] && (double)(x[i])==(double)(0.0)) && (double)(s.d[i])>(double)(0.0) )
                    {
                        kickneeded = true;
                    }
                }
                if( kickneeded )
                {
                    
                    //
                    // Perform kick.
                    // Restart.
                    // Do not increase iterations counter.
                    //
                    for(i=0; i<=ns+nd-1; i++)
                    {
                        if( (double)(x[i])==(double)(0.0) && (double)(s.d[i])>(double)(0.0) )
                        {
                            x[i] = x[i]+kicklength;
                        }
                    }
                    continue;
                }
                
                //
                // Newton phase
                // Reduce problem to constrained triangular form and perform Newton
                // steps with quick activation of constrants  (triangular  form  is
                // updated in order to handle changed constraints).
                //
                for(i=0; i<=ns+nd-1; i++)
                {
                    s.xp[i] = x[i];
                }
                trdprepare(s, x, s.regdiag, lambdav, ref s.trdd, ref s.trda, ref s.tmp0, ref s.tmp1, ref s.tmp2, ref s.tmplq, _params);
                while( true )
                {
                    
                    //
                    // Skip if debug limit on inner iterations count is turned on.
                    //
                    if( s.debugmaxinnerits>0 && innerits>=s.debugmaxinnerits )
                    {
                        break;
                    }
                    
                    //
                    // Prepare step vector.
                    //
                    funcgradu(s, x, s.r, s.g, ref f0, _params);
                    for(i=0; i<=ns+nd-1; i++)
                    {
                        s.d[i] = -s.g[i];
                        if( s.nnc[i] && (double)(x[i])==(double)(0.0) )
                        {
                            s.d[i] = 0.0;
                        }
                    }
                    trdsolve(s.trdd, s.trda, ns, nd, s.d, _params);
                    
                    //
                    // Perform unconstrained trial step and compare function values.
                    //
                    for(i=0; i<=ns+nd-1; i++)
                    {
                        s.xn[i] = x[i]+s.d[i];
                    }
                    func(s, s.xn, ref f1, _params);
                    if( (double)(f1)>=(double)(f0) )
                    {
                        break;
                    }
                    
                    //
                    // Calculate length of D, maximum step and component which is
                    // activated by this step. Break if D is exactly zero.
                    //
                    dnrm = 0.0;
                    for(i=0; i<=ns+nd-1; i++)
                    {
                        dnrm = dnrm+math.sqr(s.d[i]);
                    }
                    dnrm = Math.Sqrt(dnrm);
                    actidx = -1;
                    stpmax = 1.0E50;
                    for(i=0; i<=ns+nd-1; i++)
                    {
                        if( s.nnc[i] && (double)(s.d[i])<(double)(0.0) )
                        {
                            v = stpmax;
                            stpmax = apserv.safeminposrv(x[i], -s.d[i], stpmax, _params);
                            if( (double)(stpmax)<(double)(v) )
                            {
                                actidx = i;
                            }
                        }
                    }
                    if( (double)(dnrm)==(double)(0.0) )
                    {
                        break;
                    }
                    
                    //
                    // Perform constrained step and update X
                    // and triangular model.
                    //
                    stp = Math.Min(1.0, stpmax);
                    for(i=0; i<=ns+nd-1; i++)
                    {
                        v = x[i]+stp*s.d[i];
                        if( s.nnc[i] )
                        {
                            v = Math.Max(v, 0.0);
                        }
                        s.xn[i] = v;
                    }
                    if( (double)(stp)==(double)(stpmax) && actidx>=0 )
                    {
                        s.xn[actidx] = 0.0;
                    }
                    wasactivation = false;
                    for(i=0; i<=ns+nd-1; i++)
                    {
                        if( (double)(s.xn[i])==(double)(0.0) && (double)(x[i])!=(double)(0.0) )
                        {
                            wasactivation = true;
                            trdfixvariable(s.trdd, s.trda, ns, nd, i, ref s.tmpcholesky, _params);
                        }
                    }
                    for(i=0; i<=ns+nd-1; i++)
                    {
                        x[i] = s.xn[i];
                    }
                    
                    //
                    // Increment iterations counter.
                    // Terminate if no constraint was activated.
                    //
                    apserv.inc(ref innerits, _params);
                    if( !wasactivation )
                    {
                        break;
                    }
                }
                
                //
                // Update outer iterations counter.
                //
                // Break if necessary:
                // * maximum number of outer iterations performed
                // * relative change in X is small enough
                //
                apserv.inc(ref outerits, _params);
                if( outerits>=maxouterits )
                {
                    break;
                }
                v = 0;
                for(i=0; i<=ns+nd-1; i++)
                {
                    v0 = Math.Abs(s.xp[i]);
                    v1 = Math.Abs(x[i]);
                    if( (double)(v0)!=(double)(0) || (double)(v1)!=(double)(0) )
                    {
                        v = Math.Max(v, Math.Abs(x[i]-s.xp[i])/Math.Max(v0, v1));
                    }
                }
                if( (double)(v)<=(double)(xtol) )
                {
                    break;
                }
            }
        }


        /*************************************************************************
        This function calculates:
        * residual vector R = A*x-b
        * unconstrained gradient vector G
        * function value F = 0.5*|R|^2

        R and G must have at least N elements.

          -- ALGLIB --
             Copyright 15.07.2015 by Bochkanov Sergey
        *************************************************************************/
        private static void funcgradu(snnlssolver s,
            double[] x,
            double[] r,
            double[] g,
            ref double f,
            alglib.xparams _params)
        {
            int i = 0;
            int nr = 0;
            int nd = 0;
            int ns = 0;
            double v = 0;
            int i_ = 0;
            int i1_ = 0;

            f = 0;

            nr = s.nr;
            nd = s.nd;
            ns = s.ns;
            f = 0.0;
            for(i=0; i<=nr-1; i++)
            {
                i1_ = (ns)-(0);
                v = 0.0;
                for(i_=0; i_<=nd-1;i_++)
                {
                    v += s.densea[i,i_]*x[i_+i1_];
                }
                if( i<ns )
                {
                    v = v+x[i];
                }
                v = v-s.b[i];
                r[i] = v;
                f = f+0.5*v*v;
            }
            for(i=0; i<=ns-1; i++)
            {
                g[i] = r[i];
            }
            for(i=ns; i<=ns+nd-1; i++)
            {
                g[i] = 0.0;
            }
            for(i=0; i<=nr-1; i++)
            {
                v = r[i];
                i1_ = (0) - (ns);
                for(i_=ns; i_<=ns+nd-1;i_++)
                {
                    g[i_] = g[i_] + v*s.densea[i,i_+i1_];
                }
            }
        }


        /*************************************************************************
        This function calculates function value F = 0.5*|R|^2 at X.

          -- ALGLIB --
             Copyright 15.07.2015 by Bochkanov Sergey
        *************************************************************************/
        private static void func(snnlssolver s,
            double[] x,
            ref double f,
            alglib.xparams _params)
        {
            int i = 0;
            int nr = 0;
            int nd = 0;
            int ns = 0;
            double v = 0;
            int i_ = 0;
            int i1_ = 0;

            f = 0;

            nr = s.nr;
            nd = s.nd;
            ns = s.ns;
            f = 0.0;
            for(i=0; i<=nr-1; i++)
            {
                i1_ = (ns)-(0);
                v = 0.0;
                for(i_=0; i_<=nd-1;i_++)
                {
                    v += s.densea[i,i_]*x[i_+i1_];
                }
                if( i<ns )
                {
                    v = v+x[i];
                }
                v = v-s.b[i];
                f = f+0.5*v*v;
            }
        }


        private static void trdprepare(snnlssolver s,
            double[] x,
            double[] diag,
            double lambdav,
            ref double[] trdd,
            ref double[,] trda,
            ref double[] tmp0,
            ref double[] tmp1,
            ref double[] tmp2,
            ref double[,] tmplq,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int ns = 0;
            int nd = 0;
            int nr = 0;
            double v = 0;
            double cs = 0;
            double sn = 0;
            double r = 0;

            
            //
            // Prepare
            //
            ns = s.ns;
            nd = s.nd;
            nr = s.nr;
            
            //
            // Triangular reduction
            //
            apserv.rvectorsetlengthatleast(ref trdd, ns, _params);
            apserv.rmatrixsetlengthatleast(ref trda, ns+nd, nd, _params);
            apserv.rmatrixsetlengthatleast(ref tmplq, nd, nr+nd, _params);
            for(i=0; i<=ns-1; i++)
            {
                
                //
                // Apply rotation to I-th row and corresponding row of
                // regularizer. Here V is diagonal element of I-th row,
                // which is set to 1.0 or 0.0 depending on variable
                // status (constrained or not).
                //
                v = 1.0;
                if( s.nnc[i] && (double)(x[i])==(double)(0.0) )
                {
                    v = 0.0;
                }
                rotations.generaterotation(v, lambdav, ref cs, ref sn, ref r, _params);
                trdd[i] = cs*v+sn*lambdav;
                for(j=0; j<=nd-1; j++)
                {
                    v = s.densea[i,j];
                    trda[i,j] = cs*v;
                    tmplq[j,i] = -(sn*v);
                }
            }
            for(j=0; j<=nd-1; j++)
            {
                for(i=ns; i<=nr-1; i++)
                {
                    tmplq[j,i] = s.densea[i,j];
                }
            }
            for(j=0; j<=nd-1; j++)
            {
                if( s.nnc[ns+j] && (double)(x[ns+j])==(double)(0.0) )
                {
                    
                    //
                    // Variable is constrained, entire row is set to zero.
                    //
                    for(i=0; i<=nr-1; i++)
                    {
                        tmplq[j,i] = 0.0;
                    }
                    for(i=0; i<=ns-1; i++)
                    {
                        trda[i,j] = 0.0;
                    }
                }
            }
            for(i=0; i<=nd-1; i++)
            {
                for(j=0; j<=nd-1; j++)
                {
                    tmplq[j,nr+i] = 0.0;
                }
                tmplq[i,nr+i] = lambdav*diag[i];
            }
            apserv.rvectorsetlengthatleast(ref tmp0, nr+nd+1, _params);
            apserv.rvectorsetlengthatleast(ref tmp1, nr+nd+1, _params);
            apserv.rvectorsetlengthatleast(ref tmp2, nr+nd+1, _params);
            ortfac.rmatrixlqbasecase(ref tmplq, nd, nr+nd, ref tmp0, ref tmp1, ref tmp2, _params);
            for(i=0; i<=nd-1; i++)
            {
                if( (double)(tmplq[i,i])<(double)(0.0) )
                {
                    for(j=i; j<=nd-1; j++)
                    {
                        tmplq[j,i] = -tmplq[j,i];
                    }
                }
            }
            for(i=0; i<=nd-1; i++)
            {
                for(j=0; j<=i; j++)
                {
                    trda[ns+j,i] = tmplq[i,j];
                }
            }
        }


        private static void trdsolve(double[] trdd,
            double[,] trda,
            int ns,
            int nd,
            double[] d,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            double v = 0;

            
            //
            // Solve U'*y=d first.
            //
            // This section includes two parts:
            // * solve diagonal part of U'
            // * solve dense part of U'
            //
            for(i=0; i<=ns-1; i++)
            {
                d[i] = d[i]/trdd[i];
                v = d[i];
                for(j=0; j<=nd-1; j++)
                {
                    d[ns+j] = d[ns+j]-v*trda[i,j];
                }
            }
            for(i=0; i<=nd-1; i++)
            {
                d[ns+i] = d[ns+i]/trda[ns+i,i];
                v = d[ns+i];
                for(j=i+1; j<=nd-1; j++)
                {
                    d[ns+j] = d[ns+j]-v*trda[ns+i,j];
                }
            }
            
            //
            // Solve U*x=y then.
            //
            // This section includes two parts:
            // * solve trailing triangular part of U
            // * solve combination of diagonal and dense parts of U
            //
            for(i=nd-1; i>=0; i--)
            {
                v = 0.0;
                for(j=i+1; j<=nd-1; j++)
                {
                    v = v+trda[ns+i,j]*d[ns+j];
                }
                d[ns+i] = (d[ns+i]-v)/trda[ns+i,i];
            }
            for(i=ns-1; i>=0; i--)
            {
                v = 0.0;
                for(j=0; j<=nd-1; j++)
                {
                    v = v+trda[i,j]*d[ns+j];
                }
                d[i] = (d[i]-v)/trdd[i];
            }
        }


        private static void trdfixvariable(double[] trdd,
            double[,] trda,
            int ns,
            int nd,
            int idx,
            ref double[] tmp,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            double cs = 0;
            double sn = 0;
            double r = 0;
            double v = 0;
            double vv = 0;

            alglib.ap.assert(ns>=0, "TRDFixVariable: integrity error");
            alglib.ap.assert(nd>=0, "TRDFixVariable: integrity error");
            alglib.ap.assert(ns+nd>0, "TRDFixVariable: integrity error");
            alglib.ap.assert(idx>=0, "TRDFixVariable: integrity error");
            alglib.ap.assert(idx<ns+nd, "TRDFixVariable: integrity error");
            apserv.rvectorsetlengthatleast(ref tmp, nd, _params);
            
            //
            // Depending on variable index, two situations are possible
            //
            if( idx<ns )
            {
                
                //
                // We fix variable in the diagonal part of the model. It means
                // that prior to fixing we have:
                //
                //     (     |     )
                //     (  D  |     )
                //     (     |     )
                //     (-----|  A  )
                //     (     |0    )
                //     (     |00   )
                //     (     |000  )
                //     (     |0000 )
                //     (     |00000)
                //
                // then we replace idx-th column by zeros:
                //
                //     (D 0  |     )
                //     (  0  |     )
                //     (  0 D|     )
                //     (-----|  A  )
                //     (     |     )
                //     (     |     )
                //     (     |     )
                //
                // and append row with unit element to bottom, in order to
                // regularize problem
                //
                //     (D 0  |     )
                //     (  0  |     )
                //     (  0 D|     )
                //     (-----|  A  )
                //     (     |     )
                //     (     |     )
                //     (     |     )
                //     (00100|00000) <- appended
                //
                // and then we nullify this row by applying rotations:
                //
                //     (D 0  |     )
                //     (  0  |     ) <- first rotation is applied here
                //     (  0 D|     )
                //     (-----|  A  ) <- subsequent rotations are applied to this row and rows below
                //     (     |     )
                //     (     |     )
                //     (     |     )
                //     (  0  |  0  ) <- as result, row becomes zero
                //
                // and triangular structure is preserved
                //
                if( nd==0 )
                {
                    
                    //
                    // Quick exit for empty dense part
                    //
                    trdd[idx] = 1.0;
                    return;
                }
                for(j=0; j<=nd-1; j++)
                {
                    
                    //
                    // Apply first rotation
                    //
                    tmp[j] = trda[idx,j];
                    trda[idx,j] = 0.0;
                }
                trdd[idx] = 1.0;
                for(i=0; i<=nd-1; i++)
                {
                    if( (double)(tmp[i])!=(double)(0) )
                    {
                        
                        //
                        // Apply subsequent rotations with bottom triangular part of A
                        //
                        rotations.generaterotation(trda[ns+i,i], tmp[i], ref cs, ref sn, ref r, _params);
                        for(j=i; j<=nd-1; j++)
                        {
                            v = trda[ns+i,j];
                            vv = tmp[j];
                            trda[ns+i,j] = v*cs+vv*sn;
                            tmp[j] = vv*cs-v*sn;
                        }
                    }
                }
            }
            else
            {
                
                //
                // We fix variable in the dense part of the model. It means
                // that prior to fixing we have:
                //
                //     (     |     )
                //     (  D  |     )
                //     (     |     )
                //     (-----|  A  )
                //     (     |0    )
                //     (     |00   )
                //     (     |000  )
                //     (     |0000 )
                //     (     |00000)
                //
                // then we replace idx-th column by zeros:
                //
                //     (     |  0  )
                //     (  D  |  0  )
                //     (     |  0  )
                //     (-----|A 0 A)
                //     (     |  0  )
                //     (     |  0  )
                //     (     |  0  )
                //
                // and append row with unit element to bottom, in order to
                // regularize problem
                //
                //     (     |  0  )
                //     (  D  |  0  )
                //     (     |  0  )
                //     (-----|A 0 A)
                //     (     |  0  )
                //     (     |  0  )
                //     (     |  0  )
                //     (00000|00100) <- appended
                //
                // and then we nullify this row by applying rotations:
                //
                //     (D 0  |     )
                //     (  0  |     )
                //     (  0 D|     )
                //     (-----|  A  )
                //     (     |     )
                //     (     |     ) <- first rotation is applied here
                //     (     |     ) <- subsequent rotations are applied to rows below
                //     (  0  |  0  ) <- as result, row becomes zero
                //
                // and triangular structure is preserved.
                //
                k = idx-ns;
                for(i=0; i<=ns+nd-1; i++)
                {
                    trda[i,k] = 0.0;
                }
                for(j=k+1; j<=nd-1; j++)
                {
                    
                    //
                    // Apply first rotation
                    //
                    tmp[j] = trda[idx,j];
                    trda[idx,j] = 0.0;
                }
                trda[idx,k] = 1.0;
                for(i=k+1; i<=nd-1; i++)
                {
                    if( (double)(tmp[i])!=(double)(0) )
                    {
                        
                        //
                        // Apply subsequent rotations with bottom triangular part of A
                        //
                        rotations.generaterotation(trda[ns+i,i], tmp[i], ref cs, ref sn, ref r, _params);
                        for(j=i; j<=nd-1; j++)
                        {
                            v = trda[ns+i,j];
                            vv = tmp[j];
                            trda[ns+i,j] = v*cs+vv*sn;
                            tmp[j] = vv*cs-v*sn;
                        }
                    }
                }
            }
        }


    }
    public partial class sactivesets
    {
        /*************************************************************************
        This structure describes set of linear constraints (boundary  and  general
        ones) which can be active and inactive. It also has functionality to  work
        with current point and current  gradient  (determine  active  constraints,
        move current point, project gradient into  constrained  subspace,  perform
        constrained preconditioning and so on.

        This  structure  is  intended  to  be  used  by constrained optimizers for
        management of all constraint-related functionality.

        External code may access following internal fields of the structure:
            XC          -   stores current point, array[N].
                            can be accessed only in optimization mode
            CStatus     -   active set, array[N+NEC+NIC]:
                            * CStatus[I]>0    I-th constraint is in the active set
                            * CStatus[I]=0    I-th constraint is at the boundary, but inactive
                            * CStatus[I]<0    I-th constraint is far from the boundary (and inactive)
                            * elements from 0 to N-1 correspond to boundary constraints
                            * elements from N to N+NEC+NIC-1 correspond to linear constraints
                            * elements from N to N+NEC-1 are always +1
            FeasInitPt  -   SASStartOptimization() sets this flag to True if, after
                            enforcement  of  box  constraints,  initial  point was
                            feasible w.r.t. general linear constraints.
                            This field can be used by unit test to  validate  some
                            details of initial point calculation algorithm.
            SparseBatch -   indices of box constraints which are NOT included into
                            dense batch (were activated at the beginning of the
                            orthogonalization); SparseBatchSize elements are stored.
            SparseBatchSize-size of sparse batcj
            PDenseBatch,
            IDenseBatch,
            SDenseBatch -   after call to SASRebuildBasis() these  matrices  store
                            active constraints (except for ones included into sparse
                            batch), reorthogonalized with respect to some inner
                            product:
                            a) for "P" batch - one  given  by preconditioner matrix
                               (inverse Hessian)
                            b) for "S" one - one given by square of the scale matrix
                            c) for "I" one - traditional dot product
                            array[DenseBatchSize,N+1]
                            All three matrices are linearly equivalent to each
                            other.
                            
                            IMPORTANT: you have to call  SASRebuildBasis()  before
                                       accessing these arrays  in  order  to  make
                                       sure that they are up to date.
            DenseBatchSize   -   dense batch size (PBasis/SBasis/IBasis)
        *************************************************************************/
        public class sactiveset : apobject
        {
            public int n;
            public int algostate;
            public double[] xc;
            public bool hasxc;
            public double[] s;
            public double[] h;
            public int[] cstatus;
            public bool basisisready;
            public double[,] sdensebatch;
            public double[,] pdensebatch;
            public double[,] idensebatch;
            public int densebatchsize;
            public int[] sparsebatch;
            public int sparsebatchsize;
            public int basisage;
            public bool feasinitpt;
            public bool constraintschanged;
            public bool[] hasbndl;
            public bool[] hasbndu;
            public double[] bndl;
            public double[] bndu;
            public double[,] cleic;
            public int nec;
            public int nic;
            public bool[] mtnew;
            public double[] mtx;
            public int[] mtas;
            public double[] cdtmp;
            public double[] corrtmp;
            public double[] unitdiagonal;
            public snnls.snnlssolver solver;
            public double[] scntmp;
            public double[] tmp0;
            public double[] tmpfeas;
            public double[,] tmpm0;
            public double[] rctmps;
            public double[] rctmpg;
            public double[] rctmprightpart;
            public double[,] rctmpdense0;
            public double[,] rctmpdense1;
            public bool[] rctmpisequality;
            public int[] rctmpconstraintidx;
            public double[] rctmplambdas;
            public double[,] tmpbasis;
            public double[] tmpnormestimates;
            public double[] tmpreciph;
            public double[] tmpprodp;
            public double[] tmpprods;
            public double[] tmpcp;
            public double[] tmpcs;
            public double[] tmpci;
            public sactiveset()
            {
                init();
            }
            public override void init()
            {
                xc = new double[0];
                s = new double[0];
                h = new double[0];
                cstatus = new int[0];
                sdensebatch = new double[0,0];
                pdensebatch = new double[0,0];
                idensebatch = new double[0,0];
                sparsebatch = new int[0];
                hasbndl = new bool[0];
                hasbndu = new bool[0];
