        /*************************************************************************
        This function generates scaled (by S) reformulation of dense quadratic and
        linear terms in QP problem.

        INPUT PARAMETERS:
            N               -   number of variables.
            DenseA          -   array[NMain,NMain], quadratic term
            IsUpper         -   whether upper or lower triangle is present
            NMain           -   number of nonslack vars, 1<=NMain<=NTotal
            DenseB          -   array[NTotal], linear term
            NTotal          -   total number of variables, NTotal>=1
            S               -   scale vector, array[NTotal]:
                                * I-th element contains scale of I-th variable,
                                * SC[I]>0

        OUTPUT PARAMETERS:
            DenseA          -   replaced by scaled term, array[N,N]
            DenseB          -   replaced by scaled term, array[N]

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void scaledenseqpinplace(double[,] densea,
            bool isupper,
            int nmain,
            double[] denseb,
            int ntotal,
            double[] s,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int j0 = 0;
            int j1 = 0;
            double si = 0;

            for(i=0; i<=nmain-1; i++)
            {
                si = s[i];
                if( isupper )
                {
                    j0 = i;
                    j1 = nmain-1;
                }
                else
                {
                    j0 = 0;
                    j1 = i;
                }
                for(j=j0; j<=j1; j++)
                {
                    densea[i,j] = densea[i,j]*si*s[j];
                }
            }
            for(i=0; i<=ntotal-1; i++)
            {
                denseb[i] = denseb[i]*s[i];
            }
        }


        /*************************************************************************
        This function generates scaled (by S) reformulation of sparse quadratic and
        linear terms in QP problem.

        INPUT PARAMETERS:
            S               -   scale vector, array[N]:
                                * I-th element contains scale of I-th variable,
                                * SC[I]>0
            N               -   number of variables.
            SparseA         -   quadratic term, NxN SparseMatrix in CRS format
                                (any triangle can be present, we will scale everything)
            DenseCorrC      -   array[CorrRank,N], low rank correction C'*D*C being
                                added to the quadratic term
            DenseCorrD      -   array[CorrRank], low rank correction, diagonal factors
            CorrRank        -   correction rank, >=0
            DenseB          -   array[N], linear term

        OUTPUT PARAMETERS:
            SparseA         -   replaced by scaled term
            DenseB          -   replaced by scaled term

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void scalesparseqpinplace(double[] s,
            int n,
            sparse.sparsematrix sparsea,
            double[,] densecorrc,
            double[] densecorrd,
            int corrrank,
            double[] denseb,
            alglib.xparams _params)
        {
            int i = 0;
            int k0 = 0;
            int k1 = 0;
            int k = 0;
            double si = 0;

            alglib.ap.assert((sparsea.matrixtype==1 && sparsea.m==n) && sparsea.n==n, "ScaleSparseQPInplace: SparseA in unexpected format");
            for(i=0; i<=n-1; i++)
            {
                si = s[i];
                k0 = sparsea.ridx[i];
                k1 = sparsea.ridx[i+1]-1;
                for(k=k0; k<=k1; k++)
                {
                    sparsea.vals[k] = sparsea.vals[k]*si*s[sparsea.idx[k]];
                }
                denseb[i] = denseb[i]*si;
            }
            for(k=0; k<=corrrank-1; k++)
            {
                for(i=0; i<=n-1; i++)
                {
                    densecorrc[k,i] = densecorrc[k,i]*s[i];
                }
            }
        }


        /*************************************************************************
        This function normalizes two-sided "lower-bound/range" constraints  stored
        in dense format in such a way that L2 norms of rows (right hand  side  NOT
        included) become equal to 1.0. Exactly zero rows are handled correctly.

        INPUT PARAMETERS:
            DenseA          -   array[M,N], constraint matrix
            AB              -   lower bounds for constraints, always present and
                                finite, array[M]
            AR              -   ranges for constraints, can be zero (equality
                                constraint), positive (range constraint) or +INF
                                (lower bound constraint), array[M]
            N               -   number of variables, N>=1.
            M               -   constraint count, M>=0
            NeedNorms       -   whether we need row norms or not

        OUTPUT PARAMETERS:
            DenseA          -   replaced by normalized constraints, array[M,N]
            AB              -   replaced by normalized lower bounds, array[M]
            AR              -   replaced by normalized ranges, array[M]
            RowNorms        -   if NeedNorms is true, leading M elements (resized
                                if length is less than M) are filled by row norms
                                before normalization was performed.
            

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void normalizedensebrlcinplace(double[,] densea,
            double[] ab,
            double[] ar,
            int n,
            int m,
            ref double[] rownorms,
            bool neednorms,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            double v = 0;
            double vv = 0;

            if( neednorms )
            {
                apserv.rvectorsetlengthatleast(ref rownorms, m, _params);
            }
            for(i=0; i<=m-1; i++)
            {
                vv = 0.0;
                for(j=0; j<=n-1; j++)
                {
                    v = densea[i,j];
                    vv = vv+v*v;
                }
                vv = Math.Sqrt(vv);
                if( neednorms )
                {
                    rownorms[i] = vv;
                }
                if( (double)(vv)>(double)(0) )
                {
                    vv = 1/vv;
                    for(j=0; j<=n-1; j++)
                    {
                        densea[i,j] = densea[i,j]*vv;
                    }
                    ab[i] = ab[i]*vv;
                    if( math.isfinite(ar[i]) )
                    {
                        ar[i] = ar[i]*vv;
                    }
                }
            }
        }


        /*************************************************************************
        This function normalizes two-sided "lower-bound/range" constraints  stored
        in dense format in such a way that L2 norms of rows (right hand  side  NOT
        included) become equal to 1.0. Exactly zero rows are handled correctly.

        INPUT PARAMETERS:
            SparseA         -   sparse MSparse*N constraint matrix in CRS format;
                                ignored if MSparse=0.
            MSparse         -   dense constraint count, MSparse>=0
            DenseA          -   array[MDense,N], constraint matrix;
                                ignored if MDense=0.
            MDense          -   dense constraint count, MDense>=0
            AB              -   lower bounds for constraints, always present and
                                finite, array[MSparse+MDense]
            AR              -   ranges for constraints, can be zero (equality
                                constraint), positive (range constraint) or +INF
                                (lower bound constraint), array[MSparse+MDense]
            N               -   number of variables, N>=1.
            LimitedAmplification-   whether row amplification is limited or not:
                                * if False, rows with small norms (less than 1.0)
                                  are always normalized
                                * if True, we do not increase individual row norms
                                  during normalization - only decrease. However,
                                  we may apply one amplification round to the entire
                                  constraint matrix, i.e. amplify all rows by the same
                                  coefficient. As result, we do not overamplify
                                  any single row, but still make sure than the entire
                                  problem is well scaled.
                                * large rows are always normalized
            NeedNorms       -   whether we need row norms or not

        OUTPUT PARAMETERS:
            DenseA          -   replaced by normalized constraints, array[M,N]
            AB              -   replaced by normalized lower bounds, array[M]
            AR              -   replaced by normalized ranges, array[M]
            RowNorms        -   if NeedNorms is true, leading M elements (resized
                                if length is less than M) are filled by row norms
                                before normalization was performed.
            

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void normalizemixedbrlcinplace(sparse.sparsematrix sparsea,
            int msparse,
            double[,] densea,
            int mdense,
            double[] ab,
            double[] ar,
            int n,
            bool limitedamplification,
            ref double[] rownorms,
            bool neednorms,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            int k0 = 0;
            int k1 = 0;
            double v = 0;
            double vv = 0;
            double maxnrm2 = 0;

            alglib.ap.assert(msparse==0 || ((sparsea.matrixtype==1 && sparsea.m==msparse) && sparsea.n==n), "ScaleShiftMixedBRLCInplace: non-CRS sparse constraint matrix!");
            if( neednorms )
            {
                apserv.rvectorsetlengthatleast(ref rownorms, mdense+msparse, _params);
            }
            
            //
            // First round of normalization - normalize row 2-norms subject to limited amplification status
            //
            maxnrm2 = 0;
            for(i=0; i<=msparse-1; i++)
            {
                vv = 0.0;
                k0 = sparsea.ridx[i];
                k1 = sparsea.ridx[i+1]-1;
                for(k=k0; k<=k1; k++)
                {
                    v = sparsea.vals[k];
                    vv = vv+v*v;
                }
                vv = Math.Sqrt(vv);
                maxnrm2 = Math.Max(maxnrm2, vv);
                if( limitedamplification )
                {
                    vv = Math.Max(vv, 1.0);
                }
                if( neednorms )
                {
                    rownorms[i] = vv;
                }
                if( (double)(vv)>(double)(0) )
                {
                    vv = 1/vv;
                    for(k=k0; k<=k1; k++)
                    {
                        sparsea.vals[k] = sparsea.vals[k]*vv;
                    }
                    ab[i] = ab[i]*vv;
                    if( math.isfinite(ar[i]) )
                    {
                        ar[i] = ar[i]*vv;
                    }
                }
            }
            for(i=0; i<=mdense-1; i++)
            {
                vv = 0.0;
                for(j=0; j<=n-1; j++)
                {
                    v = densea[i,j];
                    vv = vv+v*v;
                }
                vv = Math.Sqrt(vv);
                maxnrm2 = Math.Max(maxnrm2, vv);
                if( limitedamplification )
                {
                    vv = Math.Max(vv, 1.0);
                }
                if( neednorms )
                {
                    rownorms[msparse+i] = vv;
                }
                if( (double)(vv)>(double)(0) )
                {
                    vv = 1/vv;
                    for(j=0; j<=n-1; j++)
                    {
                        densea[i,j] = densea[i,j]*vv;
                    }
                    ab[msparse+i] = ab[msparse+i]*vv;
                    if( math.isfinite(ar[msparse+i]) )
                    {
                        ar[msparse+i] = ar[msparse+i]*vv;
                    }
                }
            }
            
            //
            // If amplification was limited, perform second round of normalization
            //
            if( limitedamplification )
            {
                
                //
                // Recompute maximum norm
                //
                maxnrm2 = 0;
                for(i=0; i<=msparse-1; i++)
                {
                    vv = 0.0;
                    k0 = sparsea.ridx[i];
                    k1 = sparsea.ridx[i+1]-1;
                    for(k=k0; k<=k1; k++)
                    {
                        v = sparsea.vals[k];
                        vv = vv+v*v;
                    }
                    vv = Math.Sqrt(vv);
                    maxnrm2 = Math.Max(maxnrm2, vv);
                }
                for(i=0; i<=mdense-1; i++)
                {
                    maxnrm2 = Math.Max(maxnrm2, Math.Sqrt(ablasf.rdotrr(n, densea, i, densea, i, _params)));
                }
                
                //
                // Amplify, if needed 
                //
                if( (double)(maxnrm2)<(double)(1.0) && (double)(maxnrm2)>(double)(0) )
                {
                    if( neednorms )
                    {
                        ablasf.rmulv(mdense+msparse, maxnrm2, rownorms, _params);
                    }
                    vv = 1/maxnrm2;
                    for(i=0; i<=msparse-1; i++)
                    {
                        k0 = sparsea.ridx[i];
                        k1 = sparsea.ridx[i+1]-1;
                        for(k=k0; k<=k1; k++)
                        {
                            sparsea.vals[k] = sparsea.vals[k]*vv;
                        }
                        ab[i] = ab[i]*vv;
                        if( math.isfinite(ar[i]) )
                        {
                            ar[i] = ar[i]*vv;
                        }
                    }
                    for(i=0; i<=mdense-1; i++)
                    {
                        ablasf.rmulr(n, vv, densea, i, _params);
                        ab[msparse+i] = ab[msparse+i]*vv;
                        if( math.isfinite(ar[msparse+i]) )
                        {
                            ar[msparse+i] = ar[msparse+i]*vv;
                        }
                    }
                }
            }
        }


        /*************************************************************************
        This function normalizes two-sided  "lower-bound/upper-bound"  constraints
        stored in dense  format in such a way that L2 norms of  rows  (right  hand
        side NOT included) become equal to 1.0. 

        Exactly zero rows are handled correctly.

        INPUT PARAMETERS:
            DenseA          -   dense M*N constraint matrix;
                                ignored if M=0.
            M               -   constraint count, M>=0
            AL              -   lower bounds for constraints, array[M]
            AU              -   upper bounds for constraints, array[M]
            N               -   number of variables, N>=1.
            LimitedAmplification-   whether row amplification is limited or not:
                                * if False, rows with small norms (less than 1.0)
                                  are always normalized
                                * if True, we do not increase individual row norms
                                  during normalization - only decrease. However,
                                  we may apply one amplification rount to entire
                                  constraint matrix, i.e. amplify all rows by same
                                  coefficient. As result, we do not overamplify
                                  any single row, but still make sure than entire
                                  problem is well scaled.
                                * large rows are always normalized
            NeedNorms       -   whether we need row norms or not

        OUTPUT PARAMETERS:
            SparseA         -   replaced by normalized constraints
            AL              -   replaced by normalized lower bounds
            AU              -   replaced by normalized upper bounds
            RowNorms        -   if NeedNorms is true, leading M elements (resized
                                if length is less than M) are filled by row norms
                                before normalization was performed.
            

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void normalizedenselcinplace(double[,] densea,
            int m,
            double[] al,
            double[] au,
            int n,
            bool limitedamplification,
            ref double[] rownorms,
            bool neednorms,
            alglib.xparams _params)
        {
            int i = 0;
            double vv = 0;
            double maxnrm2 = 0;

            alglib.ap.assert(m==0 || (alglib.ap.rows(densea)>=m && alglib.ap.cols(densea)>=n), "NormalizeDenseLCInplace: matrix size is too small");
            if( neednorms )
            {
                ablasf.rallocv(m, ref rownorms, _params);
            }
            
            //
            // First round of normalization - normalize row 2-norms subject to limited amplification status
            //
            for(i=0; i<=m-1; i++)
            {
                vv = Math.Sqrt(ablasf.rdotrr(n, densea, i, densea, i, _params));
                if( limitedamplification )
                {
                    vv = Math.Max(vv, 1.0);
                }
                if( neednorms )
                {
                    rownorms[i] = vv;
                }
                if( (double)(vv)>(double)(0) )
                {
                    vv = 1/vv;
                    ablasf.rmulr(n, vv, densea, i, _params);
                    al[i] = al[i]*vv;
                    au[i] = au[i]*vv;
                }
            }
            
            //
            // If amplification was limited, perform second round of normalization
            //
            if( limitedamplification )
            {
                maxnrm2 = 0;
                for(i=0; i<=m-1; i++)
                {
                    maxnrm2 = Math.Max(maxnrm2, Math.Sqrt(ablasf.rdotrr(n, densea, i, densea, i, _params)));
                }
                if( (double)(maxnrm2)<(double)(1.0) && (double)(maxnrm2)>(double)(0) )
                {
                    if( neednorms )
                    {
                        ablasf.rmulv(m, maxnrm2, rownorms, _params);
                    }
                    vv = 1/maxnrm2;
                    for(i=0; i<=m-1; i++)
                    {
                        ablasf.rmulr(n, vv, densea, i, _params);
                        al[i] = al[i]*vv;
                        au[i] = au[i]*vv;
                    }
                }
            }
        }


        /*************************************************************************
        This function normalizes two-sided  "lower-bound/upper-bound"  constraints
        stored in sparse format in such a way that L2 norms of  rows  (right  hand
        side NOT included) become equal to 1.0. 

        Exactly zero rows are handled correctly.

        INPUT PARAMETERS:
            SparseA         -   sparse M*N constraint matrix in CRS format;
                                ignored if M=0.
            M               -   constraint count, M>=0
            AL              -   lower bounds for constraints, array[M]
            AU              -   upper bounds for constraints, array[M]
            N               -   number of variables, N>=1.
            LimitedAmplification-   whether row amplification is limited or not:
                                * if False, rows with small norms (less than 1.0)
                                  are always normalized
                                * if True, we do not increase individual row norms
                                  during normalization - only decrease. However,
                                  we may apply one amplification rount to entire
                                  constraint matrix, i.e. amplify all rows by same
                                  coefficient. As result, we do not overamplify
                                  any single row, but still make sure than entire
                                  problem is well scaled.
                                * large rows are always normalized
            NeedNorms       -   whether we need row norms or not

        OUTPUT PARAMETERS:
            SparseA         -   replaced by normalized constraints
            AL              -   replaced by normalized lower bounds
            AU              -   replaced by normalized upper bounds
            RowNorms        -   if NeedNorms is true, leading M elements (resized
                                if length is less than M) are filled by row norms
                                before normalization was performed.
            

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void normalizesparselcinplace(sparse.sparsematrix sparsea,
            int m,
            double[] al,
            double[] au,
            int n,
            bool limitedamplification,
            ref double[] rownorms,
            bool neednorms,
            alglib.xparams _params)
        {
            int i = 0;
            int k = 0;
            int k0 = 0;
            int k1 = 0;
            double v = 0;
            double vv = 0;
            double maxnrm2 = 0;

            alglib.ap.assert(m==0 || ((sparsea.matrixtype==1 && sparsea.m==m) && sparsea.n==n), "ScaleShiftMixedBRLCInplace: non-CRS sparse constraint matrix!");
            if( neednorms )
            {
                ablasf.rallocv(m, ref rownorms, _params);
            }
            
            //
            // First round of normalization - normalize row 2-norms subject to limited amplification status
            //
            maxnrm2 = 0;
            for(i=0; i<=m-1; i++)
            {
                vv = 0.0;
                k0 = sparsea.ridx[i];
                k1 = sparsea.ridx[i+1]-1;
                for(k=k0; k<=k1; k++)
                {
                    v = sparsea.vals[k];
                    vv = vv+v*v;
                }
                vv = Math.Sqrt(vv);
                maxnrm2 = Math.Max(maxnrm2, vv);
                if( limitedamplification )
                {
                    vv = Math.Max(vv, 1.0);
                }
                if( neednorms )
                {
                    rownorms[i] = vv;
                }
                if( (double)(vv)>(double)(0) )
                {
                    vv = 1/vv;
                    for(k=k0; k<=k1; k++)
                    {
                        sparsea.vals[k] = sparsea.vals[k]*vv;
                    }
                    al[i] = al[i]*vv;
                    au[i] = au[i]*vv;
                }
            }
            
            //
            // If amplification was limited, perform second round of normalization
            //
            if( limitedamplification )
            {
                
                //
                // Recompute maximum row norm
                //
                maxnrm2 = 0;
                for(i=0; i<=m-1; i++)
                {
                    vv = 0.0;
                    k0 = sparsea.ridx[i];
                    k1 = sparsea.ridx[i+1]-1;
                    for(k=k0; k<=k1; k++)
                    {
                        v = sparsea.vals[k];
                        vv = vv+v*v;
                    }
                    vv = Math.Sqrt(vv);
                    maxnrm2 = Math.Max(maxnrm2, vv);
                }
                
                //
                // Perform limited amplification, if needed
                //
                if( (double)(maxnrm2)<(double)(1.0) && (double)(maxnrm2)>(double)(0) )
                {
                    if( neednorms )
                    {
                        ablasf.rmulv(m, maxnrm2, rownorms, _params);
                    }
                    vv = 1/maxnrm2;
                    for(i=0; i<=m-1; i++)
                    {
                        k0 = sparsea.ridx[i];
                        k1 = sparsea.ridx[i+1]-1;
                        for(k=k0; k<=k1; k++)
                        {
                            sparsea.vals[k] = sparsea.vals[k]*vv;
                        }
                        al[i] = al[i]*vv;
                        au[i] = au[i]*vv;
                    }
                }
            }
        }


        /*************************************************************************
        This function normalizes two-sided  "lower-bound/upper-bound"  constraints
        stored in sparse format in such a way that maximum of row L2 norms  (right
        hand side NOT included) become equal to 1.0. 

        Exactly zero rows are handled correctly.

        INPUT PARAMETERS:
            SparseA         -   sparse M*N constraint matrix in CRS format;
                                ignored if M=0.
            M               -   constraint count, M>=0
            AL              -   lower bounds for constraints, array[M]
            AU              -   upper bounds for constraints, array[M]
            N               -   number of variables, N>=1.
            NeedScales      -   whether we need rescaling factors or not

        OUTPUT PARAMETERS:
            SparseA         -   replaced by normalized constraints
            AL              -   replaced by normalized lower bounds
            AU              -   replaced by normalized upper bounds
            AScales         -   if NeedScales is true, leading M elements (resized
                                if length is less than M) are filled by the same
                                number which was used to scale a matrix. If all
                                rows are zero, AScales[] is set to 1.0
            

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void normalizesparselcinplaceuniform(sparse.sparsematrix sparsea,
            int m,
            double[] al,
            double[] au,
            int n,
            ref double[] ascales,
            bool needscales,
            alglib.xparams _params)
        {
            int i = 0;
            int k = 0;
            int k0 = 0;
            int k1 = 0;
            double v = 0;
            double vv = 0;
            double maxnrm2 = 0;

            alglib.ap.assert(m==0 || ((sparsea.matrixtype==1 && sparsea.m==m) && sparsea.n==n), "ScaleShiftMixedBRLCInplace: non-CRS sparse constraint matrix!");
            if( needscales )
            {
                ablasf.rallocv(m, ref ascales, _params);
            }
            
            //
            // Compute maximum row norm
            //
            maxnrm2 = 0;
            for(i=0; i<=m-1; i++)
            {
                vv = 0.0;
                k0 = sparsea.ridx[i];
                k1 = sparsea.ridx[i+1]-1;
                for(k=k0; k<=k1; k++)
                {
                    v = sparsea.vals[k];
                    vv = vv+v*v;
                }
                vv = Math.Sqrt(vv);
                maxnrm2 = Math.Max(maxnrm2, vv);
            }
            if( (double)(maxnrm2)==(double)(0) )
            {
                if( needscales )
                {
                    ablasf.rsetv(m, 1.0, ascales, _params);
                }
                return;
            }
            
            //
            // Renormalize
            //
            vv = 1/maxnrm2;
            if( needscales )
            {
                ablasf.rsetv(m, maxnrm2, ascales, _params);
            }
            for(i=0; i<=m-1; i++)
            {
                k0 = sparsea.ridx[i];
                k1 = sparsea.ridx[i+1]-1;
                for(k=k0; k<=k1; k++)
                {
                    sparsea.vals[k] = sparsea.vals[k]*vv;
                }
                al[i] = al[i]*vv;
                au[i] = au[i]*vv;
            }
        }


        /*************************************************************************
        This function normalizes dense QP problem in such a way that maximum  over
        its linear/quadratic coefficients max(max(A),max(B)) becomes equal to 1.0.

        NOTE: completely zero A and B are handled correctly.

        INPUT PARAMETERS:
            DenseA          -   array[NMain,NMain], quadratic term
            IsUpper         -   whether upper or lower triangle is present
            NMain           -   number of nonslack vars, 1<=NMain<=NTotal
            DenseB          -   array[NTotal], linear term
            NTotal          -   total number of variables.

        OUTPUT PARAMETERS:
            DenseA          -   replaced by normalized term
            DenseB          -   replaced by normalized term
            
        RESULT:
            max(max(A),max(B)) is returned

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        public static double normalizedenseqpinplace(double[,] densea,
            bool isupper,
            int nmain,
            double[] denseb,
            int ntotal,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            int j = 0;
            int j0 = 0;
            int j1 = 0;
            double mx = 0;
            double v = 0;

            mx = 0;
            for(i=0; i<=nmain-1; i++)
            {
                if( isupper )
                {
                    j0 = i;
                    j1 = nmain-1;
                }
                else
                {
                    j0 = 0;
                    j1 = i;
                }
                for(j=j0; j<=j1; j++)
                {
                    mx = Math.Max(mx, Math.Abs(densea[i,j]));
                }
            }
            for(i=0; i<=ntotal-1; i++)
            {
                mx = Math.Max(mx, Math.Abs(denseb[i]));
            }
            result = mx;
            if( (double)(mx)==(double)(0) )
            {
                return result;
            }
            v = 1/mx;
            for(i=0; i<=nmain-1; i++)
            {
                if( isupper )
                {
                    j0 = i;
                    j1 = nmain-1;
                }
                else
                {
                    j0 = 0;
                    j1 = i;
                }
                for(j=j0; j<=j1; j++)
                {
                    densea[i,j] = densea[i,j]*v;
                }
            }
            for(i=0; i<=ntotal-1; i++)
            {
                denseb[i] = denseb[i]*v;
            }
            return result;
        }


        /*************************************************************************
        This function normalizes sparse QP problem in such a way that maximum over
        its linear/quadratic coefficients max(max(A),max(B)) becomes equal to 1.0.

        NOTE: completely zero A and B are handled correctly.

        INPUT PARAMETERS:
            SparseA         -   Sparse NxN matrix, either upper or lower triangle,
                                diagonal MUST be present
            IsUpper         -   which triangle is present (other one is ignored)
            DenseCorrC      -   array[CorrRank,N], low rank correction C'*D*C being
                                added to the quadratic term
            DenseCorrD      -   array[CorrRank], low rank correction, diagonal factors
            CorrRank        -   correction rank, >=0
            DenseB          -   array[N], linear term
            N               -   number of variables.

        OUTPUT PARAMETERS:
            DenseA          -   replaced by normalized term, array[N,N]
            DenseB          -   replaced by normalized term, array[N]
            
        RESULT:
            max(max(A),max(B)) is returned

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        public static double normalizesparseqpinplace(sparse.sparsematrix sparsea,
            bool isupper,
            double[,] densecorrc,
            double[] densecorrd,
            int corrrank,
            double[] denseb,
            int n,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            int k = 0;
            int k0 = 0;
            int k1 = 0;
            double mx = 0;
            double v = 0;

            alglib.ap.assert((sparsea.matrixtype==1 && sparsea.m==n) && sparsea.n==n, "NormalizeSparseQPInplace: SparseA in unexpected format");
            mx = 0;
            for(i=0; i<=n-1; i++)
            {
                alglib.ap.assert(sparsea.didx[i]+1==sparsea.uidx[i], "NormalizeSparseQPInplace: critical integrity check failed, sparse diagonal not found");
                v = sparsea.vals[sparsea.didx[i]];
                for(k=0; k<=corrrank-1; k++)
                {
                    v = v+densecorrd[k]*math.sqr(densecorrc[k,i]);
                }
                mx = Math.Max(mx, Math.Abs(v));
                mx = Math.Max(mx, Math.Abs(denseb[i]));
            }
            result = mx;
            if( (double)(mx)==(double)(0) )
            {
                return result;
            }
            v = 1/mx;
            for(i=0; i<=n-1; i++)
            {
                k0 = sparsea.ridx[i];
                k1 = sparsea.ridx[i+1]-1;
                for(k=k0; k<=k1; k++)
                {
                    sparsea.vals[k] = sparsea.vals[k]*v;
                }
                denseb[i] = denseb[i]*v;
            }
            for(k=0; k<=corrrank-1; k++)
            {
                ablasf.rmulr(n, Math.Sqrt(v), densecorrc, k, _params);
            }
            return result;
        }


        /*************************************************************************
        This function performs transformation of X from scaled/shifted coordinates
        to unscaled/unshifted ones, paying special attention to box constraints:
        * points which were exactly at the boundary before scaling will be  mapped
          to corresponding boundary after scaling
        * in any case, unscaled box constraints will be satisfied

          -- ALGLIB --
             Copyright 02.06.2015 by Bochkanov Sergey
        *************************************************************************/
        public static void unscaleunshiftpointbc(double[] s,
            double[] xorigin,
            double[] rawbndl,
            double[] rawbndu,
            double[] sclsftbndl,
            double[] sclsftbndu,
            bool[] hasbndl,
            bool[] hasbndu,
            double[] x,
            int n,
            alglib.xparams _params)
        {
            int i = 0;

            for(i=0; i<=n-1; i++)
            {
                if( hasbndl[i] && (double)(x[i])<=(double)(sclsftbndl[i]) )
                {
                    x[i] = rawbndl[i];
                    continue;
                }
                if( hasbndu[i] && (double)(x[i])>=(double)(sclsftbndu[i]) )
                {
                    x[i] = rawbndu[i];
                    continue;
                }
                x[i] = x[i]*s[i]+xorigin[i];
                if( hasbndl[i] && (double)(x[i])<=(double)(rawbndl[i]) )
                {
                    x[i] = rawbndl[i];
                }
                if( hasbndu[i] && (double)(x[i])>=(double)(rawbndu[i]) )
                {
                    x[i] = rawbndu[i];
                }
            }
        }


        /*************************************************************************
        Converts dense/sparse linear and quadratic terms (the latter can be given
        by the upper/lower triangle) to the dense lower triangular form.

        INPUT PARAMETERS:
            RawC                -   array[N], linear term
            N                   -   variables count
            DenseH              -   if HKind=0: array[NMain,NMain], dense quadratic term
                                    (either upper or lower triangle)
            SparseH             -   if HKind=1: array[NMain,NMain], sparse quadratic term
                                    (either upper or lower triangle)
            HKind               -   0 or 1, quadratic term format
            IsUpper             -   whether dense/sparse H contains lower or upper
                                    triangle of the quadratic term
            H                   -   possibly preallocated matrix
            
        OUTPUT PARAMETERS:
            C                   -   array[N], scaled linear term
            H                   -   array[N,N], lower triangle is converted H

          -- ALGLIB --
             Copyright 23.05.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void quadraticlinearconverttodenseltr(double[] rawc,
            int n,
            double[,] denseh,
            sparse.sparsematrix sparseh,
            int hkind,
            bool isupper,
            ref double[] c,
            ref double[,] h,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int j0 = 0;
            int j1 = 0;
            double v = 0;

            alglib.ap.assert(hkind==0 || hkind==1, "QuadraticLinearScaleConvertToDenseLTR: incorrect HKind");
            alglib.ap.assert(n>=1, "QuadraticLinearScaleConvertToDenseLTR: N<1");
            
            //
            // Raw linear term
            //
            ablasf.rcopyallocv(n, rawc, ref c, _params);
            
            //
            // Quadratic term, without normalization
            //
            // NOTE: we perform integrity check for inifinities/NANs by
            //       computing sum of all matrix elements and checking its
            //       value for being finite. It is a bit faster than checking
            //       each element individually.
            //
            ablasf.rallocm(n, n, ref h, _params);
            if( hkind==0 )
            {
                
                //
                // Copy dense quadratic term
                //
                if( isupper )
                {
                    ablas.rmatrixtranspose(n, n, denseh, 0, 0, h, 0, 0, _params);
                }
                else
                {
                    ablas.rmatrixcopy(n, n, denseh, 0, 0, h, 0, 0, _params);
                }
            }
            if( hkind==1 )
            {
                
                //
                // Extract sparse quadratic term
                //
                alglib.ap.assert(sparseh.matrixtype==1, "QuadraticLinearScaleConvertToDenseLTR: unexpected sparse matrix format");
                alglib.ap.assert(sparseh.m==n, "QuadraticLinearScaleConvertToDenseLTR: unexpected sparse matrix size");
                alglib.ap.assert(sparseh.n==n, "QuadraticLinearScaleConvertToDenseLTR: unexpected sparse matrix size");
                ablasf.rsetm(n, n, 0.0, h, _params);
                for(i=0; i<=n-1; i++)
                {
                    
                    //
                    // diagonal element
                    //
                    if( sparseh.didx[i]!=sparseh.uidx[i] )
                    {
                        h[i,i] = sparseh.vals[sparseh.didx[i]];
                    }
                    
                    //
                    // Off-diagonal elements
                    //
                    if( isupper )
                    {
                        
                        //
                        // superdiagonal elements are moved to the subdiagonal part
                        //
                        j0 = sparseh.uidx[i];
                        j1 = sparseh.ridx[i+1]-1;
                        for(j=j0; j<=j1; j++)
                        {
                            h[sparseh.idx[j],i] = sparseh.vals[j];
                        }
                    }
                    else
                    {
                        
                        //
                        // subdiagonal elements are moved to the subdiagonal part
                        //
                        j0 = sparseh.ridx[i];
                        j1 = sparseh.didx[i]-1;
                        for(j=j0; j<=j1; j++)
                        {
                            h[i,sparseh.idx[j]] = sparseh.vals[j];
                        }
                    }
                }
            }
            v = 0;
            for(i=0; i<=n-1; i++)
            {
                v = v+ablasf.rdotrr(i+1, h, i, h, i, _params);
            }
            alglib.ap.assert(math.isfinite(v), "QuadraticLinearScaleConvertToDenseLTR: H contains infinite or NaN values!");
        }


    }
