            public double[] tus;
            public double[] tgl;
            public double[] tgu;
            public double[] ts;
            public double[] ta;
            public double[] t0;
            public double[] t1;
            public double[] t2;
            public double[] t3;
            public double[] t4;
            public double[] t5;
            public double[] wx;
            public double[] wy;
            public double[] wyv;
            public double[] d0;
            public double[] d1;
            public double[] d1v;
            public gipmcondensedsystem()
            {
                init();
            }
            public override void init()
            {
                tls = new double[0];
                tus = new double[0];
                tgl = new double[0];
                tgu = new double[0];
                ts = new double[0];
                ta = new double[0];
                t0 = new double[0];
                t1 = new double[0];
                t2 = new double[0];
                t3 = new double[0];
                t4 = new double[0];
                t5 = new double[0];
                wx = new double[0];
                wy = new double[0];
                wyv = new double[0];
                d0 = new double[0];
                d1 = new double[0];
                d1v = new double[0];
            }
            public override alglib.apobject make_copy()
            {
                gipmcondensedsystem _result = new gipmcondensedsystem();
                _result.tls = (double[])tls.Clone();
                _result.tus = (double[])tus.Clone();
                _result.tgl = (double[])tgl.Clone();
                _result.tgu = (double[])tgu.Clone();
                _result.ts = (double[])ts.Clone();
                _result.ta = (double[])ta.Clone();
                _result.t0 = (double[])t0.Clone();
                _result.t1 = (double[])t1.Clone();
                _result.t2 = (double[])t2.Clone();
                _result.t3 = (double[])t3.Clone();
                _result.t4 = (double[])t4.Clone();
                _result.t5 = (double[])t5.Clone();
                _result.wx = (double[])wx.Clone();
                _result.wy = (double[])wy.Clone();
                _result.wyv = (double[])wyv.Clone();
                _result.d0 = (double[])d0.Clone();
                _result.d1 = (double[])d1.Clone();
                _result.d1v = (double[])d1v.Clone();
                return _result;
            }
        };


        /*************************************************************************
        This object stores temporaries of the GIPM (nonconvex nonlinear IPM) solver.

        The solvers solves finds a solution for the following problem:

            min f(xp) s.t. c(xp)-xs=0, XL<=[xp,xs]<=XU, v(x)<=VU

        for primal xp and slack xs, which allows one to have a random mix of
        equality, inequality and range constraints on individual variables and,
        nonlinear constraints c() and v().

        Here c() are constraints that are handled using infeasible approach (thus
        they do not require strictly feasible initial point, but may be violated in
        the intermediate points, and slightly violated in the final point), and v()
        are constraints that require strictly feasible initial point and that are
        handled exactly (they are always strictly satisfied).

        After adding slack variables GL and GU for nonlinear constraints c() and
        adding stabilizing term such that fmod(xp,xs)=f(xp)+mu*TAU*x^2+mu*TAU*xs^2, we have:
            
            min fmod(xp,xs) subject to
                c(xp)-xs=0
                v(xp)<=VU
                BL<=xp<=BU,
                xs free,
                xs-GL=CL
                xs+GU=CU
                GL, GU>=0

        The barrier problem formulation is (below nu=mu*penaltyfactor)

                  (                                                                                                                                                               )
            min_x ( fmod(xp,mu) - mu*ELP*ln(xp-bl) - mu*EUP*SUM[ln(bu-xp)] - mu*ELS*ln(gl) - mu*EUS*ln(gu) - mu*ln(vu-v(xp)) + (2*nu)^-1*(|c(xp)-xs|^2+|xs-gl-cl|^2+|xs+gu-cu|^2) )
                  (                                                                                                                                                               )
                  
        subject to
            
            c(xp)-xs = 0
            ce(xp)=bndu_e
            v(xp)<=vu
            bl<=xp<=bu, bl<bu (strictly)
            xs free,
            xs-gl=cl
            xs+gu=cu
            gl, gu>=0
            
        where ELP, EUP, ELS and EUS are lower/upper bound masks for primary and slacks vars
        with 1 for present bound and 0 for absent bound.

        The primal-dual equations for the barrier problem are:

            [xp,xs,gl,gu]
            
            gmod(xp) + [J,-I,0,0]'*yp + [Jv,0,0,0]'*yv + [0,I,-I,0]'*yl + [0,I,0,I]*yu + [-ZLP,0,-ZLS,0] + [ZUP,0,0,-ZUS]  = 0
            c(xp)-xs - nu*yp                                = 0
            ce(xp)   - nu*ype                               = bndu_e
            xs-gl    - nu*yl                                = cl-rlx*mu
            xs+gu    - nu*yu                                = cu+rlx*mu
            ZLP*(xp-bl)                                     = mu*ELP
            ZUP*(bu-xp)                                     = mu*EUP
            ZLS*gl                                          = mu*ELS
            ZUS*gu                                          = mu*EUS
            Yv*(vu-v(xp))                                   = mu

        where J is a Jacobian of c(), and Jv is a Jacobian of v(), and the Newton system
        (subject to the additional damping term LAMBDA) is
            
            (diag(Hmod+L+TAU,0,0,0))*[d_xp,d_xs,d_gl,d_gu] + [J,-I,0,0]'*d_yp + [Jv,0,0,0]'*d_yv + [0,I,-I,0]'*d_yl + [0,I,0,I]*d_yu + [-d_zlp,0,-d_zls,0] + [d_zup,0,0,-d_zus] = 
                                                                                          = -( [gmod(xp),0,0,0]+[J,-I,0,0,]'*yp+[Jv,0,0,0]*yv+[0,I,-I,0]'*yl + [0,I,0,I]*yu + [-zlp,0,-zls,0] + [zup,0,0,-zus] ) 
                                                                                          = [ Rp, Rs,Rgl,Rgu ]                                              (1)
                    (Hmod+L+TAU)*d_xp + J'*d_yp +Jv'*d_yv - d_zlp + d_zup                 = Rp                                                              (1A)
                    -d_yp + d_yl + d_yu                                                   = Rs                                                              (1B)
                    -d_yl - d_zls                                                         = Rgl                                                             (1C)
                    d_yu - d_zus                                                          = Rgu                                                             (1D)
            J*d_xp - d_xs - nu*d_yp                                                       =   -(c(xp)-xs-nu*yp)                             = Ry            (2)
            d_xs - d_gl   - nu*d_yl                                                       =    ELS*(cl-rlx*mu-xs+gl+nu*yl)                  = Rcl           (3)
            d_xs + d_gu   - nu*d_yu                                                       =    ELU*(cu+rlx*mu-xs-gu+nu*yu)                  = Rcu           (4)
            ZLP*d_xp + (XP-BL)*d_zlp                                                      =    mu*ELP - ZLP*(xp-bl)                         = Rlp           (5)
            -ZUP*d_xp + (BU-XP)*d_zup                                                     =    mu*EUP - ZUP*(bu-xp)                         = Rup           (6)
            GL*d_zls + ZLS*d_gl                                                           =    mu*ELS - ZLS*gl                              = Rls           (7)
            GU*d_zus + ZUS*d_gu                                                           =    mu*EUS - ZUS*gu                              = Rus           (8)
            YV*Jv*d_xp - (vu-v(xp))*d_yv                                                  =    (vu-v(xp))*yv-mu                             = Rv            (9)
            
            
            -v*y=mu
            -Y*J*dx - v*dy = mu+vy

        From (3) and (4) we get expressions for d_gl and d_gu

            d_gl = ELS*(d_xs - nu*d_yl - Rcl)
            d_gu = ELU*(Rcu  + nu*d_yu - d_xs)

        which are substituted to (7) and (8) to get

            GL*d_zls + ZLS*d_xs - nu*ZLS*d_yl = Rls + ZLS*Rcl = TLS
            GU*d_zus + nu*ZUS*d_yu - ZUS*d_xs = Rus - ZUS*Rcu = TUS
            
        and then to get

            T0 = inv(GL)*ZLS
            T1 = inv(GU)*ZUS
            d_zls = inv(GL)*TLS - T0*d_xs + nu*T0*d_yl
            d_zus = inv(GU)*TUS + T1*d_xs - nu*T1*d_yu

        which can be substituted to (1C) and (1D) to get
            
            -(1+nu*T0)*d_yl + T0*d_xs = Rgl + inv(GL)*TLS = TGL
            +(1+nu*T1)*d_yu - T1*d_xs = Rgu + inv(GU)*TUS = TGU
            
        and then to get

            T2 = inv(1+nu*T0)
            T3 = inv(1+nu*T1)    
            d_yl = T2*(T0*d_xs - TGL)
            d_yu = T3*(T1*d_xs + TGU)
            
        which can be substituted to (1B) to get

            -d_yp + (T2*T0+T3*T1)*d_xs = Rs - T3*TGU + T2*TGL = TS
            
        and then to get
            
            TA = inv(T2*T0+T3*T1)
            d_xs = TA*(TS+d_yp)
            
        which can be substituted to (2) to get

            D1 = -(TA+nu)
            J*d_xp + D1*d_yp = Ry + TA*TS = WY

        Finally, we use (5) and (6) to get

            T4 = inv(XP-BL)
            T5 = inv(BU-XP)
            d_zlp = T4*(Rlp - ZLP*d_xp)
            d_zup = T5*(Rup + ZUP*d_xp)

        and transform (1A) to

            D0 = L+TAU+T4*ZLP+T5*ZUP
            (Hmod+D0)*d_xp + J'*d_yp +Jv'*d_yv = Rp + T4*Rlp - T5*Rup = WX
            
        We also transform (9) by dividing it by diag(Yv), which gives us

            D1V = -inv(YV)*(vu-v(xp))
            Jv*d_xp + D1V*d_yv = inv(YV)*Rv = WYV
            
        Finally, combining WX, WY and WYV gives us the final condensed system

            (Hmod+D0)*d_xp + J'*d_yp + Jv'*d_yv = WX
                    J*d_xp + D1*d_yp            = WY
                   Jv*d_xp           + D1V*d_yv = WYV
                    
        with D0>0, D1<0, D1V<0. For the ease of notation the code belows refers
        to the single combined J which includes both J and Jv.
        *************************************************************************/
        public class gipmstate : apobject
        {
            public int nraw;
            public int mflex;
            public int mhard;
            public double[] x0;
            public double[] bndlx;
            public double[] bndux;
