                finitebndux = new double[0];
                safeguardbndlp = new double[0];
                safeguardbndup = new double[0];
                current = new gipmvars();
                best = new gipmvars();
                currentfj = new optserv.varsfuncjac();
                bestfj = new optserv.varsfuncjac();
