                _result.trial = trial!=null ? (gipmvars)trial.make_copy() : null;
                _result.trialfj = trialfj!=null ? (optserv.varsfuncjac)trialfj.make_copy() : null;
                _result.rstate = rstate!=null ? (ap.rcommstate)rstate.make_copy() : null;
                return _result;
            }
        };




        public const double initmu = 0.1;
        public const double maxmu = 10000;
        public const double tightendist = 5.0;
        public const double relaxdist = 2.0;
        public const double penaltygrowth = 1.0;
        public const double maxnu = 0.001;
        public const double relaxfactor = 1.0;
        public const double maxrelaxation = 0.0001;
        public const double lambdamax = 1.0E6;
        public const double lambdagrowth = 2.0;
        public const double lambdarapidgrowth = 100.0;
        public const double lambdadecayacc = 0.90;
        public const int maxsubsequentfailuresforweakgrowth = 5;
        public const double damptau = 0.0001;
        public const double fractobnd = 0.98;
        public const double mudecaylinear = 0.2;
        public const double mudecaypower = 1.2;
        public const double checkpointacceptance = 0.9;
        public const int maxcheckpointstagnationits = 25;
        public const double firstiterationcheckpointstagnationeps = 0.001;
        public const double rhsstagnationtol1 = 0.001;
        public const double rhsstagnationtol2 = 0.05;
        public const int maxrhsstagnationits = 5;
        public const double smallstep = 1.0E-8;
        public const double initbigval = 1.0E9;
        public const double initbiggrowth = 1.0E9;
        public const double maxbigval = 1.0E50;
        public const double maxbiggrowth = 1.0E20;
        public const double vggrowth = 1.0E3;
        public const int maxsmalltrials = 3;
        public const int maxrfsits = 5;
        public const double rhstol = 100*math.machineepsilon;
        public const int maxnd = 2;
        public const int maxnonmonotonic = 1;
        public const int nonmonotonicdelay = 10;
