        /*************************************************************************
        Get recommended initial value for mu.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        public static double gipmgetinitprimdual(alglib.xparams _params)
        {
            double result = 0;

            result = Math.Sqrt(initmu);
            return result;
        }


        /*************************************************************************
        Initialize GIPM structure

        NOTES: 

            FScales             -   objective/constraint scales, used merely for
                                    reporting
            DoQNReport          -   array[MFlex+MHard+1], flags for quasi-Newton
                                    reports.
                                    
                                    If DoQNReport[i] is true, then (I-1)-th constraint
                                    is included into report sent with the code 1004.
                                    The first element  corresponds to the objective.
                                    Ignored when IsFirstOrder=False

        IMPORTANT: equality box constraints on X are NOT supported! you have to
                   reformulate your problem in order to avoid equality constraints
                   on primal variables. Box constraints on them should be have
                   width bounded away from zero.
                   Nonlinear equality constraints are supported.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void gipminitbuf(double[] bndl,
            double[] bndu,
            double[] x0,
            int nraw,
            double[] nl,
            double[] nu,
            int mflex,
            int mhard,
            double[] fscales,
            bool[] doqnreport,
            double eps,
            int maxits,
            bool isfirstorder,
            gipmstate state,
            alglib.xparams _params)
        {
            int i = 0;
            double eqeps = 0;

            state.nraw = nraw;
            state.mflex = mflex;
            state.mhard = mhard;
            state.mudependent = false;
            state.isfirstorder = isfirstorder;
            eqeps = Math.Max(1.0E-3*eps, 1.0E3*math.machineepsilon);
            if( isfirstorder )
            {
                ablasf.rsetallocv(1+mflex+mhard, 0.0, ref state.qnmask, _params);
                state.isqnmasknonzero = false;
                for(i=0; i<=mflex+mhard; i++)
                {
                    if( doqnreport[i] )
                    {
                        state.qnmask[i] = 1.0;
                        state.isqnmasknonzero = true;
                    }
                }
            }
            
            //
            // Save initial point for further processing
            //
            ablasf.rcopyallocv(nraw, x0, ref state.x0, _params);
            
            //
            // Function scales
            //
            ablasf.rcopyallocv(1+mflex+mhard, fscales, ref state.fscales, _params);
            
            //
            // Prepare RCOMM-V2 protocol
            //
            state.rstate.ia = new int[13+1];
            state.rstate.ba = new bool[6+1];
            state.rstate.ra = new double[30+1];
            state.rstate.stage = -1;
            state.rstate.clear_handler();
            
            //
            // Box constraints: convert from the original form into a slack representation
            //
            ablasf.bsetallocv(mflex, false, ref state.isequality, _params);
            ablasf.rsetallocv(nraw+mflex, Double.NegativeInfinity, ref state.bndlx, _params);
            ablasf.bsetallocv(nraw+mflex, false, ref state.hasbndlx, _params);
            ablasf.rsetallocv(nraw+mflex+mhard, Double.PositiveInfinity, ref state.bndux, _params);
            ablasf.bsetallocv(nraw+mflex+mhard, false, ref state.hasbndux, _params);
            for(i=0; i<=nraw-1; i++)
            {
                if( math.isfinite(bndl[i]) )
                {
                    state.bndlx[i] = bndl[i];
                    state.hasbndlx[i] = true;
                }
                if( math.isfinite(bndu[i]) )
                {
                    state.bndux[i] = bndu[i];
                    state.hasbndux[i] = true;
                }
                if( state.hasbndlx[i] && state.hasbndux[i] )
                {
                    alglib.ap.assert((double)(state.bndlx[i])<(double)(state.bndux[i]), "GIPM: equality box constraints on primal variables are NOT supported by design");
                }
            }
            for(i=0; i<=mflex-1; i++)
            {
                alglib.ap.assert(math.isfinite(nl[i]) || math.isfinite(nu[i]), "GIPM: one of general constraints has both bounds absent");
                if( math.isfinite(nl[i]) )
                {
                    state.bndlx[nraw+i] = nl[i];
                    state.hasbndlx[nraw+i] = true;
                }
                if( math.isfinite(nu[i]) )
                {
                    state.bndux[nraw+i] = nu[i];
                    state.hasbndux[nraw+i] = true;
                }
                if( state.hasbndlx[nraw+i] && state.hasbndux[nraw+i] )
                {
                    alglib.ap.assert((double)(state.bndlx[nraw+i])<=(double)(state.bndux[nraw+i]), "GIPM: one of nonlinear constraints has incompatible range");
                    if( (double)(Math.Abs(state.bndlx[nraw+i]-state.bndux[nraw+i]))<=(double)(eqeps) )
                    {
                        state.isequality[i] = true;
                    }
                }
            }
            for(i=mflex; i<=mflex+mhard-1; i++)
            {
                alglib.ap.assert(Double.IsNegativeInfinity(nl[i]) && math.isfinite(nu[i]), "GIPM: one of hard constraints has infinite upper bound or has finite upper bound");
                state.bndux[nraw+i] = nu[i];
                state.hasbndux[nraw+i] = true;
            }
            
            //
            // Stopping criteria and settings
            //
            alglib.ap.assert((double)(eps)>=(double)(0), "GIPM: integrity check 9756 failed");
            state.eps = apserv.coalesce(eps, 10*Math.Sqrt(math.machineepsilon), _params);
            state.maxits = maxits;
            
            //
            // Report fields
            //
            state.repterminationtype = 0;
            state.repiterationscount = 0;
            
            //
            // Trace status
            //
            state.dolaconictrace = ap.istraceenabled("GENIPM.LACONIC", _params);
            state.dotrace = ap.istraceenabled("GENIPM", _params) && !state.dolaconictrace;
            state.dodetailedtrace = state.dotrace && ap.istraceenabled("GENIPM.DETAILED", _params);
        }


