            if( state.rstate.stage==9 )
            {
                goto lbl_9;
            }
            if( state.rstate.stage==10 )
            {
                goto lbl_10;
            }
            
            //
            // Routine body
            //
            nraw = state.nraw;
            mflex = state.mflex;
            mhard = state.mhard;
            mtotal = mflex+mhard;
            nxf = state.nraw+state.mflex;
            nxh = state.nraw+state.mflex+state.mhard;
            
            //
            // Prepare debug timers and temporaries
            //
            apserv.stimerinit(state.timertotal, _params);
            state.mnx1pool.alloc_double(Math.Max(nxh, mtotal)+1);
            apserv.stimerstart(state.timertotal, _params);
            
            //
            // Trace output (if needed)
            //
            if( state.dotrace )
            {
                alglib.ap.trace("\n\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace("//  NONLINEAR IPM SOLVER STARTED                                                                  //\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace(System.String.Format("N             = {0,6:d}\n", nraw));
                alglib.ap.trace(System.String.Format("M             = {0,6:d} (incl {1,0:d} non-relaxable inequalities)\n", mflex+mhard, mhard));
            }
            
            //
            // Prepare quantities used during iterations
            //
            ablasf.rsetallocv(nraw, 0.0, ref state.elp, _params);
            ablasf.rsetallocv(nraw, 0.0, ref state.eup, _params);
            ablasf.rsetallocv(mflex, 0.0, ref state.els, _params);
            ablasf.rsetallocv(mflex, 0.0, ref state.eus, _params);
            for(i=0; i<=nxf-1; i++)
            {
                if( state.hasbndlx[i] )
                {
                    if( i<nraw )
                    {
                        state.elp[i] = 1;
                    }
                    if( i>=nraw && !state.isequality[i-nraw] )
                    {
                        state.els[i-nraw] = 1;
                    }
                }
                if( state.hasbndux[i] )
                {
                    if( i<nraw )
                    {
                        state.eup[i] = 1;
                    }
                    if( i>=nraw && !state.isequality[i-nraw] )
                    {
                        state.eus[i-nraw] = 1;
                    }
                }
            }
            ablasf.rsetallocv(nxf, -Math.Sqrt(math.maxrealnumber), ref state.finitebndlx, _params);
            ablasf.rsetallocv(nxh, Math.Sqrt(math.maxrealnumber), ref state.finitebndux, _params);
            for(i=0; i<=nxf-1; i++)
            {
                if( state.hasbndlx[i] )
                {
                    state.finitebndlx[i] = state.bndlx[i];
                }
                if( state.hasbndux[i] )
                {
                    state.finitebndux[i] = state.bndux[i];
                }
            }
            for(i=nxf; i<=nxh-1; i++)
            {
                state.finitebndux[i] = state.bndux[i];
            }
            safeboundsfromfinitetightened(state, _params);
            
            //
            // Choose initial mu
            //
            state.mu = initmu;
            mumin = Math.Max(0.0001*state.eps/(1+relaxfactor), 100*math.machineepsilon);
            
            //
            // Initial point: perform RCOMM request, prepare the initial point
            //
            initprimdual = gipmgetinitprimdual(_params);
            varsinitbyzero(state.current, nraw, mflex, mhard, _params);
            varsinitbyzero(state.delta, nraw, mflex, mhard, _params);
            varsinitbyzero(state.corr, nraw, mflex, mhard, _params);
            for(i=0; i<=nraw-1; i++)
            {
                if( state.hasbndlx[i] )
                {
                    alglib.ap.assert((double)(state.x0[i])>(double)(state.bndlx[i]), "GIPM: the initial point is not strictly feasible wrt box constraints");
                }
                if( state.hasbndux[i] )
                {
                    alglib.ap.assert((double)(state.x0[i])<(double)(state.bndux[i]), "GIPM: the initial point is not strictly feasible wrt box constraints");
                }
            }
            ablasf.rcopyv(nraw, state.x0, state.current.xp, _params);
            ablasf.rmergemaxv(nraw, state.safeguardbndlp, state.current.xp, _params);
            ablasf.rmergeminv(nraw, state.safeguardbndup, state.current.xp, _params);
            for(i=0; i<=mflex-1; i++)
            {
                if( state.hasbndlx[nraw+i] && !state.hasbndux[nraw+i] )
                {
                    state.current.yp[i] = -initprimdual;
                }
                if( state.hasbndux[nraw+i] && !state.hasbndlx[nraw+i] )
                {
                    state.current.yp[i] = initprimdual;
                }
            }
            ablasf.rsetv(mhard, initprimdual, state.current.yv, _params);
            state.requesttype = 1;
            state.querymu = state.mu;
            ablasf.rallocv(nxh, ref state.querydata, _params);
            ablasf.rcopyvx(nraw, state.current.xp, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(mflex, state.current.yp, 0, state.querydata, nraw, _params);
            ablasf.rcopyvx(mhard, state.current.yv, 0, state.querydata, nraw+mflex, _params);
            ablasf.rallocv(1+mtotal, ref state.replyfi, _params);
            state.rstate.stage = 0;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
            optserv.vfjinitfromsparse(state.current.xp, nraw, state.replyfi, 1+mtotal, state.replysj, state.currentfj, _params);
            for(i=0; i<=nraw-1; i++)
            {
                if( state.hasbndlx[i] )
                {
                    state.current.zlp[i] = apserv.boundval(initmu/(state.current.xp[i]-state.bndlx[i]), 100*Math.Sqrt(math.machineepsilon), initprimdual, _params);
                }
                if( state.hasbndux[i] )
                {
                    state.current.zup[i] = apserv.boundval(initmu/(state.bndux[i]-state.current.xp[i]), 100*Math.Sqrt(math.machineepsilon), initprimdual, _params);
                }
            }
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    state.current.xs[i] = state.replyfi[1+i];
                    if( state.hasbndlx[nraw+i] )
                    {
                        state.current.gl[i] = Math.Max(initprimdual, state.current.xs[i]-state.bndlx[nraw+i]);
                        state.current.zls[i] = apserv.boundval(initmu/state.current.gl[i], 100*Math.Sqrt(math.machineepsilon), initprimdual, _params);
                    }
                    if( state.hasbndux[nraw+i] )
                    {
                        state.current.gu[i] = Math.Max(initprimdual, state.bndux[nraw+i]-state.current.xs[i]);
                        state.current.zus[i] = apserv.boundval(initmu/state.current.gu[i], 100*Math.Sqrt(math.machineepsilon), initprimdual, _params);
                    }
                }
            }
            for(i=0; i<=mhard-1; i++)
            {
                alglib.ap.assert((double)(state.replyfi[1+mflex+i])<(double)(state.finitebndux[nxf+i]), "GIPM: the initial point is infeasible with respect to hard inequality constraints");
                state.current.yv[i] = apserv.boundval(initmu/(state.finitebndux[nxf+i]-state.replyfi[1+mflex+i]), 100*Math.Sqrt(math.machineepsilon), initprimdual, _params);
            }
            state.nrmx0 = ablasf.rmaxabsv(nraw, state.current.xp, _params);
            state.absf0 = Math.Abs(state.replyfi[0]);
            
            //
            // Outer iterations
            //
            curbigval = initbigval;
            curbiggrowth = initbiggrowth;
            state.lambdav = 0.0;
            state.lambdadecay = 0.0;
            state.besterr = math.maxrealnumber;
            varscopy(state.current, state.best, _params);
            infinitiesdetected = false;
            failedtorecoverfrominfinities = false;
            lambdafound = false;
            state.subsequentfactfailures = 0;
            firstouteriteration = true;
            barrierpenaltyandcmplerror(state, state.current, state.currentfj, state.mu, ref f0, ref p0, ref cmpl0, _params);
            lastprim = Math.Sqrt(math.maxrealnumber);
            lastdual = lastprim;
            lastcmpl = lastprim;
            gnrm = 1;
            maxabsf = 0;
        lbl_11:
            if( false )
            {
                goto lbl_12;
            }
            
            //
            // Reset parameters and flags at the beginning of inner iterations
            //
            unboundednesssuspected = false;
            lastcheckpointp = math.maxrealnumber;
            lastcheckpointd = math.maxrealnumber;
            lastcheckpointc = math.maxrealnumber;
            lastcheckpointidx = state.repiterationscount;
            innerloopstart = state.repiterationscount;
            state.rhsstagnationcounter = 0;
            goodinnerits = 0;
            if( (double)(state.lambdav)>=(double)(lambdamax) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> regularization is at maximum, resetting to 1.0\n");
                }
                state.lambdav = 1;
                state.lambdadecay = 1;
            }
            state.filterready = false;
            state.nonmonotonicmemlen = -1;
            minmeritv0 = math.maxrealnumber;
            curmeritv0 = minmeritv0;
            
            //
            // If the problem formulation is mu-dependent, recompute target/objective using
            // current value of Mu.
            //
            if( !state.mudependent )
            {
                goto lbl_13;
            }
            state.requesttype = 1;
            state.querymu = state.mu;
            ablasf.rallocv(nraw+mtotal, ref state.querydata, _params);
            ablasf.rcopyvx(nraw, state.current.xp, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(mflex, state.current.yp, 0, state.querydata, nraw, _params);
            ablasf.rcopyvx(mhard, state.current.yv, 0, state.querydata, nraw+mflex, _params);
            ablasf.rallocv(1+mtotal, ref state.replyfi, _params);
            state.rstate.stage = 1;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            optserv.vfjinitfromsparse(state.current.xp, nraw, state.replyfi, 1+mtotal, state.replysj, state.currentfj, _params);
        lbl_13:
            
            //
            // Inner iterations for fixed Mu.
            //
            // After this loop is done we have current point in State.Current/State.CurrentFJ and
            // current residual in State.RHS. Additionally, the current point is remembered as the
            // one where the Hessian should be calculated.
            //
        lbl_15:
            if( false )
            {
                goto lbl_16;
            }
            if( userterminationneeded )
            {
                goto lbl_16;
            }
            if( state.maxits>0 && state.repiterationscount>=state.maxits )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> maximum number of iterations performed, stopping\n");
                }
                state.repterminationtype = 5;
                goto lbl_16;
            }
            
            //
            // Trace iteration start
            //
            if( state.dotrace )
            {
                alglib.ap.trace(System.String.Format("\n=== ITERATION {0,5:d} STARTED ========================================================================\n", state.repiterationscount));
                alglib.ap.trace(System.String.Format("mu            = {0,11:E3}\n", state.mu));
                alglib.ap.trace(System.String.Format("lambda        = {0,11:E3} (damping term for the Hessian)\n", state.lambdav));
                alglib.ap.trace(System.String.Format("lambda_decay  = {0,7:F4}     (decay for the damping term)\n", state.lambdadecay));
                alglib.ap.trace(System.String.Format("|x|inf        = {0,11:E3}\n", ablasf.rmaxabsv(nraw, state.current.xp, _params)));
                alglib.ap.trace(System.String.Format("|y|inf        = {0,11:E3}\n", Math.Max(ablasf.rmaxabsv(mflex, state.current.yp, _params), ablasf.rmaxabsv(mhard, state.current.yv, _params))));
                alglib.ap.trace("\n");
            }
            
            //
            // Print variable stats if necessary
            //
            if( state.dotrace )
            {
                alglib.ap.trace("> var stats     min.abs     max.abs    \n");
                alglib.ap.trace(System.String.Format("x (prim)        {0,11:E3} {1,11:E3}\n", minabsnz(state.current.xp, nraw, _params), ablasf.rmaxabsv(nraw, state.current.xp, _params)));
                alglib.ap.trace(System.String.Format("x (slck)        {0,11:E3} {1,11:E3}\n", minabsnz(state.current.xs, mflex, _params), ablasf.rmaxabsv(mflex, state.current.xs, _params)));
                alglib.ap.trace(System.String.Format("g (lo)          {0,11:E3} {1,11:E3}\n", minabsnz(state.current.gl, mflex, _params), ablasf.rmaxabsv(mflex, state.current.gl, _params)));
                alglib.ap.trace(System.String.Format("g (hi)          {0,11:E3} {1,11:E3}\n", minabsnz(state.current.gu, mflex, _params), ablasf.rmaxabsv(mflex, state.current.gu, _params)));
                alglib.ap.trace(System.String.Format("z (prim.lo)     {0,11:E3} {1,11:E3}\n", minabsnz(state.current.zlp, nraw, _params), ablasf.rmaxabsv(nraw, state.current.zlp, _params)));
                alglib.ap.trace(System.String.Format("z (prim.hi)     {0,11:E3} {1,11:E3}\n", minabsnz(state.current.zup, nraw, _params), ablasf.rmaxabsv(nraw, state.current.zup, _params)));
                alglib.ap.trace(System.String.Format("y (prim)        {0,11:E3} {1,11:E3}\n", minabsnz(state.current.yp, mflex, _params), ablasf.rmaxabsv(mflex, state.current.yp, _params)));
                alglib.ap.trace(System.String.Format("y (lo)          {0,11:E3} {1,11:E3}\n", minabsnz(state.current.yl, mflex, _params), ablasf.rmaxabsv(mflex, state.current.yl, _params)));
                alglib.ap.trace(System.String.Format("y (hi)          {0,11:E3} {1,11:E3}\n", minabsnz(state.current.yu, mflex, _params), ablasf.rmaxabsv(mflex, state.current.yu, _params)));
                alglib.ap.trace(System.String.Format("y (hard)        {0,11:E3} {1,11:E3}\n", minabsnz(state.current.yv, mhard, _params), ablasf.rmaxabsv(mhard, state.current.yv, _params)));
                alglib.ap.trace(System.String.Format("z (slck.lo)     {0,11:E3} {1,11:E3}\n", minabsnz(state.current.zls, mflex, _params), ablasf.rmaxabsv(mflex, state.current.zls, _params)));
                alglib.ap.trace(System.String.Format("z (slck.hi)     {0,11:E3} {1,11:E3}\n", minabsnz(state.current.zus, mflex, _params), ablasf.rmaxabsv(mflex, state.current.zus, _params)));
                if( state.dodetailedtrace )
                {
                    alglib.ap.trace("> printing detailed data\n");
                    alglib.ap.trace("X (scaled)    = ");
                    apserv.tracevectorautoprec(state.current.xp, 0, nraw, _params);
                    alglib.ap.trace("\n");
                    alglib.ap.trace("XS (scaled)   = ");
                    apserv.tracevectorautoprec(state.current.xs, 0, mflex, _params);
                    alglib.ap.trace("\n");
                }
            }
            
            //
            // Compute residual for the non-condensed unsymmetric primal-dual system.
            // Compute erorrs, check stopping and stagnation criteria.
            //
            computerhs(state, state.current, state.currentfj, state.mu, state.rhs, ref eprim, ref edual, ref ecmpl, ref v, ref vv, ref v2, _params);
            gnrm = Math.Sqrt(ablasf.rdotv2(nraw, state.rhs.rp, _params));
            rhs0 = apserv.rmax3(eprim, edual, ecmpl, _params);
            if( state.dotrace )
            {
                alglib.ap.trace("> computing absolute errors:\n");
                alglib.ap.trace(System.String.Format("primal        = {0,0:E3}\n", eprim));
                alglib.ap.trace(System.String.Format("dual          = {0,0:E3}\n", edual));
                alglib.ap.trace(System.String.Format("compl         = {0,0:E3}\n", ecmpl));
                alglib.ap.trace(System.String.Format("rhs.max       = {0,0:E3}\n", rhs0));
            }
            if( ((double)(eprim)<(double)(checkpointacceptance*lastcheckpointp) || (double)(edual)<(double)(checkpointacceptance*lastcheckpointd)) || (double)(ecmpl)<(double)(checkpointacceptance*lastcheckpointc) )
            {
                
                //
                // Significant progress achieved for at least one parameter. Save checkpoint (used to detect stagnation).
                //
                // NOTE: it is important that the comparison is strict! Non-strict comparison is likely to cause inability to
                //       detect stagnation should any error become exactly zero.
                //
                alglib.ap.assert(((double)(eprim)!=(double)(lastcheckpointp) || (double)(edual)!=(double)(lastcheckpointd)) || (double)(ecmpl)!=(double)(lastcheckpointc), "GIPM: integrity check 1500 failed");
                lastcheckpointp = Math.Min(lastcheckpointp, eprim);
                lastcheckpointd = Math.Min(lastcheckpointd, edual);
                lastcheckpointc = Math.Min(lastcheckpointc, ecmpl);
                lastcheckpointidx = state.repiterationscount;
            }
            if( (double)(apserv.rmax3(eprim/v, edual/vv, ecmpl/v2, _params))<=(double)(state.mu) )
            {
                
                //
                // NOTE: the additional 0.9 multiplier prevents the situation when internal iteration always finishes with error
                //       just below Eps, but outer iteration always sees the error just above Eps (due to mu being set to zero).
                //
                if( state.dotrace )
                {
                    alglib.ap.trace("> stopping criteria for inner iterations met (relative error is small enough), exit to outer iterations\n");
                }
                goto lbl_16;
            }
            if( (double)(state.lambdav)>=(double)(lambdamax) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> regularization is at maximum, stopping inner iterations\n");
                }
                state.lambdav = 1;
                state.lambdadecay = 1;
                goto lbl_16;
            }
            if( !firstouteriteration )
            {
                
