                    // Midgame stopping condition: RHS stagnation
                    //
                    if( firstouteriteration )
                    {
                        state.rhsstagnationcounter = 0;
                    }
                    if( (double)(Math.Abs(eprim-lastprim))>(double)(apserv.rmaxabs2(rhsstagnationtol1*lastprim, rhsstagnationtol2*state.eps, _params)) )
                    {
                        state.rhsstagnationcounter = 0;
                    }
                    if( (double)(Math.Abs(edual-lastdual))>(double)(apserv.rmaxabs2(rhsstagnationtol1*lastdual, rhsstagnationtol2*state.eps, _params)) )
                    {
                        state.rhsstagnationcounter = 0;
                    }
