                    {
                        state.rhsstagnationcounter = 0;
                    }
                    if( state.rhsstagnationcounter>maxrhsstagnationits )
                    {
                        if( state.dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> RHS stagnated (no significant changes for {0,0:d} its)\n", maxrhsstagnationits));
                        }
                        goto lbl_16;
                    }
                }
            }
            if( !firstouteriteration || (double)(apserv.rmax3(eprim/v, edual/vv, ecmpl/v2, _params))<=(double)(firstiterationcheckpointstagnationeps) )
            {
                
                //
                // This stopping condition is checked at the first outer iteration, in the midgame and at the late phase
                //
                if( state.repiterationscount>lastcheckpointidx+maxcheckpointstagnationits )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> iteration stagnated (no new checkpoints for {0,0:d} its)\n", maxcheckpointstagnationits));
                    }
                    goto lbl_16;
                }
            }
            
            //
            // Condense LHS (system matrix) and perform modified RCOMM request to factorize it
            //
            condenselhs(state, state.current, state.currentfj, state.mu, state.condensed, _params);
            state.requesttype = 1001;
            state.factsuccess = false;
            ablasf.rallocv(nxh, ref state.querydata, _params);
            ablasf.rcopyvx(nraw, state.condensed.d0, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(mflex, state.condensed.d1, 0, state.querydata, nraw, _params);
            ablasf.rcopyvx(mhard, state.condensed.d1v, 0, state.querydata, nraw+mflex, _params);
            state.rstate.stage = 2;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_2:
            if( !state.factsuccess )
            {
                if( state.subsequentfactfailures<=maxsubsequentfailuresforweakgrowth )
                {
                    
                    //
                    // Slowly growing Lambda
                    //
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> factorization failed, Hessian is not sufficiently positive definite, increasing damping factor\n");
                    }
