                    state.lambdadecay = 1.0;
                }
                else
                {
                    
                    //
                    // Many subsequent failures, rapid growth
                    //
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> factorization failed too many times in a row, rapid growth of LambdaV is activated\n");
                    }
                    state.lambdav = Math.Max(lambdarapidgrowth*state.lambdav, 0.001*state.mu);
                    state.lambdadecay = 1.0;
                }
                state.subsequentfactfailures = state.subsequentfactfailures+1;
