            }
            state.subsequentfactfailures = 0;
            lambdafound = lambdafound || (double)(state.lambdav)!=(double)(0);
            
            //
            // Run iterative refinement
            //
            rhsk = math.maxrealnumber;
            varsinitbyzero(state.delta, nraw, mflex, mhard, _params);
            rfsidx = 0;
        lbl_17:
            if( rfsidx>maxrfsits-1 )
            {
                goto lbl_19;
            }
            condenserhs(state, state.current, state.currentfj, state.mu, state.rhs, state.condensed, _params);
            state.requesttype = 1002;
            ablasf.rallocv(nraw+mtotal, ref state.querydata, _params);
            ablasf.rcopyvx(nraw, state.condensed.wx, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(mflex, state.condensed.wy, 0, state.querydata, nraw, _params);
            ablasf.rcopyvx(mhard, state.condensed.wyv, 0, state.querydata, nraw+mflex, _params);
            ablasf.rallocv(nraw+mtotal, ref state.replysol, _params);
            state.rstate.stage = 3;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_3:
            unpacksolution(state, state.current, state.currentfj, state.mu, state.rhs, state.condensed, state.replysol, state.corr, _params);
            varsapplystep(state.delta, state.corr, 1.0, _params);
            state.requesttype = 1003;
            ablasf.rallocv(nraw+mtotal, ref state.querydata, _params);
            ablasf.rallocv(nraw+mtotal+nraw, ref state.replyprod, _params);
            ablasf.rcopyvx(nraw, state.corr.xp, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(mflex, state.corr.yp, 0, state.querydata, nraw, _params);
            ablasf.rcopyvx(mhard, state.corr.yv, 0, state.querydata, nraw+mflex, _params);
            state.rstate.stage = 4;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_4:
            ablasf.rallocv(nraw, ref state.tmphdxp, _params);
            ablasf.rallocv(mtotal, ref state.tmpjdxp, _params);
            ablasf.rallocv(nraw, ref state.tmpjtdy, _params);
            ablasf.rcopyvx(nraw, state.replyprod, 0, state.tmphdxp, 0, _params);
            ablasf.rcopyvx(mtotal, state.replyprod, nraw, state.tmpjdxp, 0, _params);
            ablasf.rcopyvx(nraw, state.replyprod, nraw+mtotal, state.tmpjtdy, 0, _params);
            rhsk = computeupdateresidual(state, state.current, state.currentfj, state.mu, state.lambdav, state.corr, state.tmphdxp, state.tmpjdxp, state.tmpjtdy, state.rhs, _params);
            if( state.dotrace )
            {
                alglib.ap.trace(System.String.Format("> analyzing solution to the linear system, relative residual norm is {0,0:E2}\n", rhsk/apserv.coalesce(rhs0, 1, _params)));
            }
            if( (double)(rhsk)<(double)(rhstol*rhs0) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> residual norm is small enough, stopping refinement\n");
                }
                goto lbl_19;
            }
            rfsidx = rfsidx+1;
            goto lbl_17;
        lbl_19:
            if( (double)(rhsk)>(double)(Math.Max(2*rhstol, 0.001)*rhs0) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> iterative refinement failed to sufficiently decrease residual, increasing Lambda and retrying\n");
                }
                state.lambdav = apserv.coalesce(10*state.lambdav, 1000*math.machineepsilon*(1/state.mu), _params);
                state.lambdadecay = 1.0;
                state.repiterationscount = state.repiterationscount+1;
                goto lbl_15;
            }
            
            //
            // Perform line search
            //
            if( state.dodetailedtrace )
            {
                alglib.ap.trace("> printing detailed step information\n");
                alglib.ap.trace("dX            = ");
                apserv.tracevectorautoprec(state.delta.xp, 0, nraw, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace("dXS           = ");
                apserv.tracevectorautoprec(state.delta.xs, 0, mflex, _params);
                alglib.ap.trace("\n");
            }
            alpha = computesteplength(state, state.current, state.delta, _params);
            if( state.dotrace )
            {
                alglib.ap.trace(System.String.Format("> computed maximum step length: alpha={0,0:F6}\n", alpha));
            }
            barrierpenaltyandcmplerror(state, state.current, state.currentfj, state.mu, ref f0, ref p0, ref cmpl0, _params);
            merit0 = meritfunctionpd(state, state.current, state.currentfj, state.mu, _params);
            if( !state.filterready )
            {
