            }
            smalltrials = 0;
            btits = 0;
        lbl_20:
            if( false )
            {
                goto lbl_21;
            }
            
            //
            // Preliminary checks
            //
            if( (double)(alpha)<(double)(smallstep) )
            {
                smalltrials = smalltrials+1;
            }
