            varsapplystep(state.trial, state.delta, alpha, _params);
            ablasf.rmergemaxv(nraw, state.safeguardbndlp, state.trial.xp, _params);
            ablasf.rmergeminv(nraw, state.safeguardbndup, state.trial.xp, _params);
            state.requesttype = 1;
            state.querymu = state.mu;
            ablasf.rallocv(nraw+mtotal, ref state.querydata, _params);
            ablasf.rcopyvx(nraw, state.trial.xp, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(mflex, state.trial.yp, 0, state.querydata, nraw, _params);
            ablasf.rcopyvx(mhard, state.trial.yv, 0, state.querydata, nraw+mflex, _params);
            ablasf.rallocv(1+mtotal, ref state.replyfi, _params);
            state.rstate.stage = 5;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_5:
            optserv.vfjinitfromsparse(state.trial.xp, nraw, state.replyfi, 1+mtotal, state.replysj, state.trialfj, _params);
            barrierpenaltyandcmplerror(state, state.trial, state.trialfj, state.mu, ref f1, ref p1, ref cmpl1, _params);
            merit1 = meritfunctionpd(state, state.trial, state.trialfj, state.mu, _params);
            
