            ablasf.rallocv(1+mtotal, ref state.replyfi, _params);
            state.rstate.stage = 8;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_8:
            optserv.vfjinitfromsparse(state.current.xp, nraw, state.replyfi, 1+mtotal, state.replysj, state.currentfj, _params);
            barrierpenaltyandcmplerror(state, state.current, state.currentfj, state.mu, ref f1, ref p1, ref cmpl1, _params);
        lbl_30:
            state.filterready = false;
            state.nonmonotonicmemlen = -1;
            curmeritv0 = meritv0(state, state.current, state.currentfj, state.mu, _params);
            minmeritv0 = curmeritv0;
        lbl_28:
        lbl_26:
            
            //
            // Next iteration
            //
            lastprim = eprim;
            lastdual = edual;
            lastcmpl = ecmpl;
            if( (double)(state.lambdav)!=(double)(0) )
            {
                state.lambdav = state.lambdav*state.lambdadecay;
                state.lambdadecay = Math.Max(state.lambdadecay*lambdadecayacc, Math.Sqrt(Math.Sqrt(math.machineepsilon)));
                if( (double)(state.lambdav)<(double)(state.mu*math.machineepsilon) )
                {
                    state.lambdav = 0;
                    state.lambdadecay = 0;
                }
            }
            state.repiterationscount = state.repiterationscount+1;
            state.rhsstagnationcounter = state.rhsstagnationcounter+1;
            goodinnerits = goodinnerits+1;
            goto lbl_15;
        lbl_16:
            firstouteriteration = false;
            if( state.dotrace )
            {
                alglib.ap.trace("\n----- outer iteration ------------------------------------------------------------------------------\n");
            }
            if( userterminationneeded )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> user requested immediate termination, stopping\n");
                }
                state.repterminationtype = 8;
                goto lbl_12;
            }
            if( state.repterminationtype!=0 )
            {
                goto lbl_12;
            }
            if( unboundednesssuspected )
            {
                if( ((double)(state.mu)<=(double)(1.001*mumin) && (double)(curbigval)>=(double)(0.999*maxbigval)) && (double)(curbiggrowth)>=(double)(0.999*maxbiggrowth) )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> unboundedness detected (mu at minimum, thresholds at maximum, the problem is still unbounded)\n");
                    }
                    state.repterminationtype = -4;
                    goto lbl_12;
                }
                if( state.dotrace )
                {
                    alglib.ap.trace("> decreasing mu, increasing unboundedness detection thresholds, continuing iterations\n");
                }
                state.mu = Math.Max(mumin, 0.01*state.mu);
                curbigval = Math.Min(vggrowth*curbigval, maxbigval);
                curbiggrowth = Math.Min(vggrowth*curbiggrowth, maxbiggrowth);
                goto lbl_11;
            }
            
            //
            // Recompute RHS from scratch (less dependency on the internal loop).
            // Check primal/dual/complementarity errors for the original problem (mu=0).
            //
            if( !state.mudependent )
            {
                goto lbl_32;
            }
            
            //
            // If the problem formulation is mu-dependent, recompute target/objective using zero Mu.
            //
            state.requesttype = 1;
            state.querymu = 0.0;
            ablasf.rallocv(nraw+mtotal, ref state.querydata, _params);
            ablasf.rcopyvx(nraw, state.current.xp, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(mflex, state.current.yp, 0, state.querydata, nraw, _params);
            ablasf.rcopyvx(mhard, state.current.yv, 0, state.querydata, nraw+mflex, _params);
            ablasf.rallocv(1+mtotal, ref state.replyfi, _params);
            state.rstate.stage = 9;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_9:
            optserv.vfjinitfromsparse(state.current.xp, nraw, state.replyfi, 1+mtotal, state.replysj, state.currentfj, _params);
        lbl_32:
            computerhs(state, state.current, state.currentfj, 0.0, state.rhs, ref eprim, ref edual, ref ecmpl, ref v, ref vv, ref v2, _params);
            if( state.dotrace )
            {
                alglib.ap.trace("> computing absolute errors for the original problem (mu=0):\n");
                alglib.ap.trace(System.String.Format("primal        = {0,0:E3}\n", eprim));
                alglib.ap.trace(System.String.Format("dual          = {0,0:E3}\n", edual));
                alglib.ap.trace(System.String.Format("compl         = {0,0:E3}\n", ecmpl));
            }
            if( (double)(apserv.rmax3(eprim, edual, ecmpl, _params))<(double)(state.besterr) )
            {
                
                //
                // Save the best point so far
                //
                varscopy(state.current, state.best, _params);
                optserv.vfjcopy(state.currentfj, state.bestfj, _params);
                state.besterr = apserv.rmax3(eprim, edual, ecmpl, _params);
                if( state.dotrace )
                {
                    alglib.ap.trace("> the point provides the best prim/dual/cmpl errors so far, saving\n");
                }
            }
            else
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> the point does not improve over the best prim/dual/cmpl errors so far, not saved\n");
                }
            }
            if( (double)(apserv.rmax3(eprim/v, edual/vv, ecmpl/v2, _params))<=(double)(state.eps) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format("> stopping criteria for outer iterations met (relative error is below Eps={0,0:E2}), solved\n", state.eps));
                }
                state.repterminationtype = 2;
                goto lbl_12;
            }
            if( (double)(state.mu)<=(double)(1.001*mumin) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> mu is at minimum, stagnation detected, stopping\n");
                }
                state.repterminationtype = 7;
                goto lbl_12;
            }
            
            //
            // Inner iterations are over, tighten/relax bounds if necessary and decrease Mu
            //
            tightenrelaxbounds(state, _params);
            state.mu = Math.Max(mumin, Math.Min(mudecaylinear*state.mu, Math.Pow(state.mu, mudecaypower)));
            goto lbl_11;
        lbl_12:
            
            //
            // Almost done:
            // * compare error at State.Current with one at State.Best, restore from State.Best
            //   if optimizer went in wrong direction
            // * set completion flags
            //
            if( state.dotrace )
            {
                alglib.ap.trace("\n=== STOPPED ========================================================================================\n");
            }
            if( !state.mudependent )
            {
                goto lbl_34;
            }
            
            //
            // If the problem formulation is mu-dependent, recompute target/objective using zero Mu.
            //
            state.requesttype = 1;
            state.querymu = 0.0;
            ablasf.rallocv(nraw+mtotal, ref state.querydata, _params);
            ablasf.rcopyvx(nraw, state.current.xp, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(mflex, state.current.yp, 0, state.querydata, nraw, _params);
            ablasf.rcopyvx(mhard, state.current.yv, 0, state.querydata, nraw+mflex, _params);
            ablasf.rallocv(1+mtotal, ref state.replyfi, _params);
            state.rstate.stage = 10;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_10:
            optserv.vfjinitfromsparse(state.current.xp, nraw, state.replyfi, 1+mtotal, state.replysj, state.currentfj, _params);
        lbl_34:
            computerhs(state, state.current, state.currentfj, 0.0, state.rhs, ref eprim, ref edual, ref ecmpl, ref v, ref vv, ref v2, _params);
            if( (double)(apserv.rmax3(eprim, edual, ecmpl, _params))>(double)(state.besterr) )
            {
                
                //
                // Restore best point so far
                //
                varscopy(state.best, state.current, _params);
                optserv.vfjcopy(state.bestfj, state.currentfj, _params);
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format("> the last accepted point is worse than the best one seen so far (p/d/c err: {0,0:E2} vs {1,0:E2}), restoring the best one\n", apserv.rmax3(eprim, edual, ecmpl, _params), state.besterr));
                }
            }
            if( infinitiesdetected )
            {
                state.repterminationtype = apserv.icase2(failedtorecoverfrominfinities, -8, state.repterminationtype+800, _params);
            }
            apserv.stimerstop(state.timertotal, _params);
            if( state.dotrace )
            {
                if( infinitiesdetected && failedtorecoverfrominfinities )
                {
                    alglib.ap.trace("> infinities were detected, but we failed to recover by decreasing trust radius; declaring failure with the code -8\n");
                }
                alglib.ap.trace(System.String.Format("raw target:     {0,20:E12}\n", state.currentfj.fi[0]*state.fscales[0]));
                alglib.ap.trace(System.String.Format("total time:     {0,10:F1} ms\n", apserv.stimergetms(state.timertotal, _params)));
            }
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rstate.ia[0] = nraw;
            state.rstate.ia[1] = mtotal;
            state.rstate.ia[2] = mflex;
            state.rstate.ia[3] = mhard;
            state.rstate.ia[4] = nxf;
            state.rstate.ia[5] = nxh;
            state.rstate.ia[6] = i;
            state.rstate.ia[7] = rfsidx;
            state.rstate.ia[8] = j;
            state.rstate.ia[9] = innerloopstart;
            state.rstate.ia[10] = smalltrials;
            state.rstate.ia[11] = lastcheckpointidx;
            state.rstate.ia[12] = btits;
            state.rstate.ia[13] = goodinnerits;
            state.rstate.ba[0] = firstouteriteration;
            state.rstate.ba[1] = infinitiesdetected;
            state.rstate.ba[2] = failedtorecoverfrominfinities;
            state.rstate.ba[3] = unboundednesssuspected;
            state.rstate.ba[4] = lambdafound;
            state.rstate.ba[5] = accepted;
            state.rstate.ba[6] = violated;
            state.rstate.ra[0] = v;
            state.rstate.ra[1] = vv;
            state.rstate.ra[2] = v2;
            state.rstate.ra[3] = alpha;
            state.rstate.ra[4] = f0;
            state.rstate.ra[5] = f1;
            state.rstate.ra[6] = p0;
            state.rstate.ra[7] = p1;
            state.rstate.ra[8] = cmpl0;
            state.rstate.ra[9] = cmpl1;
            state.rstate.ra[10] = gnrm;
            state.rstate.ra[11] = initprimdual;
            state.rstate.ra[12] = eprim;
            state.rstate.ra[13] = edual;
            state.rstate.ra[14] = ecmpl;
            state.rstate.ra[15] = mumin;
            state.rstate.ra[16] = curbigval;
            state.rstate.ra[17] = curbiggrowth;
            state.rstate.ra[18] = rhs0;
            state.rstate.ra[19] = rhsk;
            state.rstate.ra[20] = lastcheckpointp;
            state.rstate.ra[21] = lastcheckpointd;
            state.rstate.ra[22] = lastcheckpointc;
            state.rstate.ra[23] = lastprim;
            state.rstate.ra[24] = lastdual;
            state.rstate.ra[25] = lastcmpl;
            state.rstate.ra[26] = maxabsf;
            state.rstate.ra[27] = minmeritv0;
            state.rstate.ra[28] = curmeritv0;
            state.rstate.ra[29] = merit0;
            state.rstate.ra[30] = merit1;
            return result;
        }


        /*************************************************************************
        Extract solution

        INPUT PARAMETERS:
            State               -   solver instance
            
        OUTPUT PARAMETERS:
            XS                  -   array[N], solution
            LagBC               -   array[N], Lagrange multipliers for box constraints
            LagXC               -   array[M], Lagrange multipliers for linear, quadratic, conic constraints
            TerminationType     -   completion code, positive values for success,
                                    negative for failures (XS constrains best point
                                    found so far):
                                    * -2    the task is either unbounded or infeasible;
                                            the IPM solver has difficulty distinguishing between these two.
                                    * +1    stopping criteria are met
                                    * +7    stopping criteria are too stringent

        RESULT:

        This function ALWAYS returns something  meaningful in XS, LagBC, LagLC - 
        either solution or the best point so far, even for negative TerminationType.

          -- ALGLIB --
             Copyright 25.05.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void gipmresults(gipmstate state,
            ref double[] xs,
            ref double[] lagbc,
            ref double[] lagxc,
            ref int terminationtype,
            alglib.xparams _params)
        {
            terminationtype = 0;

            terminationtype = state.repterminationtype;
            ablasf.rcopyallocv(state.nraw, state.current.xp, ref xs, _params);
            ablasf.rcopyallocv(state.nraw, state.current.zup, ref lagbc, _params);
            ablasf.raddv(state.nraw, -1.0, state.current.zlp, lagbc, _params);
            ablasf.rcopyallocv(state.mflex, state.current.yp, ref lagxc, _params);
        }


        /*************************************************************************
        Allocates place for variables of IPM and fills by zeros.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void varsinitbyzero(gipmvars vstate,
            int nraw,
            int mflex,
            int mhard,
            alglib.xparams _params)
        {
            alglib.ap.assert(nraw>=1, "VarsInitByZero: N<1");
            alglib.ap.assert(mflex>=0, "VarsInitByZero: MFlex<0");
            alglib.ap.assert(mhard>=0, "VarsInitByZero: MHard<0");
            vstate.np = nraw;
            vstate.nf = nraw+mflex;
            vstate.mflex = mflex;
            vstate.mhard = mhard;
            ablasf.rsetallocv(nraw, 0.0, ref vstate.xp, _params);
            ablasf.rsetallocv(nraw, 0.0, ref vstate.zlp, _params);
            ablasf.rsetallocv(nraw, 0.0, ref vstate.zup, _params);
            ablasf.rsetallocv(mflex, 0.0, ref vstate.yp, _params);
            ablasf.rsetallocv(mflex, 0.0, ref vstate.yl, _params);
            ablasf.rsetallocv(mflex, 0.0, ref vstate.yu, _params);
            ablasf.rsetallocv(mflex, 0.0, ref vstate.xs, _params);
            ablasf.rsetallocv(mflex, 0.0, ref vstate.gl, _params);
            ablasf.rsetallocv(mflex, 0.0, ref vstate.gu, _params);
            ablasf.rsetallocv(mflex, 0.0, ref vstate.zls, _params);
            ablasf.rsetallocv(mflex, 0.0, ref vstate.zus, _params);
            ablasf.rsetallocv(mhard, 0.0, ref vstate.yv, _params);
        }


        /*************************************************************************
        Apply step

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void varsapplystep(gipmvars vstate,
            gipmvars delta,
            double alpha,
            alglib.xparams _params)
        {
            ablasf.raddv(vstate.np, alpha, delta.xp, vstate.xp, _params);
            ablasf.raddv(vstate.np, alpha, delta.zlp, vstate.zlp, _params);
            ablasf.raddv(vstate.np, alpha, delta.zup, vstate.zup, _params);
            ablasf.raddv(vstate.mflex, alpha, delta.yp, vstate.yp, _params);
            ablasf.raddv(vstate.mflex, alpha, delta.yl, vstate.yl, _params);
            ablasf.raddv(vstate.mflex, alpha, delta.yu, vstate.yu, _params);
            ablasf.raddv(vstate.mflex, alpha, delta.xs, vstate.xs, _params);
            ablasf.raddv(vstate.mflex, alpha, delta.gl, vstate.gl, _params);
            ablasf.raddv(vstate.mflex, alpha, delta.gu, vstate.gu, _params);
            ablasf.raddv(vstate.mflex, alpha, delta.zls, vstate.zls, _params);
            ablasf.raddv(vstate.mflex, alpha, delta.zus, vstate.zus, _params);
            ablasf.raddv(vstate.mhard, alpha, delta.yv, vstate.yv, _params);
        }


        /*************************************************************************
        Copy vars

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void varscopy(gipmvars src,
            gipmvars dst,
            alglib.xparams _params)
        {
            dst.np = src.np;
            dst.nf = src.nf;
            dst.mflex = src.mflex;
            dst.mhard = src.mhard;
            ablasf.rcopyallocv(src.np, src.xp, ref dst.xp, _params);
            ablasf.rcopyallocv(src.np, src.zlp, ref dst.zlp, _params);
            ablasf.rcopyallocv(src.np, src.zup, ref dst.zup, _params);
            ablasf.rcopyallocv(src.mflex, src.yp, ref dst.yp, _params);
            ablasf.rcopyallocv(src.mflex, src.yl, ref dst.yl, _params);
            ablasf.rcopyallocv(src.mflex, src.yu, ref dst.yu, _params);
            ablasf.rcopyallocv(src.mflex, src.xs, ref dst.xs, _params);
            ablasf.rcopyallocv(src.mflex, src.gl, ref dst.gl, _params);
            ablasf.rcopyallocv(src.mflex, src.gu, ref dst.gu, _params);
            ablasf.rcopyallocv(src.mflex, src.zls, ref dst.zls, _params);
            ablasf.rcopyallocv(src.mflex, src.zus, ref dst.zus, _params);
            ablasf.rcopyallocv(src.mhard, src.yv, ref dst.yv, _params);
        }


        /*************************************************************************
        Computes step length

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double computesteplength(gipmstate state,
            gipmvars current,
            gipmvars delta,
            alglib.xparams _params)
        {
            double result = 0;
            int np = 0;
            int mflex = 0;
            int mhard = 0;
            int i = 0;
            double eps2 = 0;

            np = state.nraw;
            mflex = state.mflex;
            mhard = state.mhard;
            eps2 = 1/Math.Sqrt(math.maxrealnumber);
            result = math.maxrealnumber;
            
            //
            // Analyze NP-sized components
            //
            for(i=0; i<=np-1; i++)
            {
                if( delta.xp[i]<0.0 )
                {
                    result = Math.Min(result, (current.xp[i]-state.finitebndlx[i])/(eps2-delta.xp[i]));
                }
                if( delta.xp[i]>0.0 )
                {
                    result = Math.Min(result, (state.finitebndux[i]-current.xp[i])/(eps2+delta.xp[i]));
                }
                if( delta.zlp[i]<0.0 )
                {
                    result = Math.Min(result, current.zlp[i]/(eps2-delta.zlp[i]));
                }
                if( delta.zup[i]<0.0 )
                {
                    result = Math.Min(result, current.zup[i]/(eps2-delta.zup[i]));
                }
            }
            
            //
            // analyze MFlex-sized components
            //
            for(i=0; i<=mflex-1; i++)
            {
                if( delta.gl[i]<0.0 )
                {
                    result = Math.Min(result, current.gl[i]/(eps2-delta.gl[i]));
                }
                if( delta.gu[i]<0.0 )
                {
                    result = Math.Min(result, current.gu[i]/(eps2-delta.gu[i]));
                }
                if( delta.zls[i]<0.0 )
                {
                    result = Math.Min(result, current.zls[i]/(eps2-delta.zls[i]));
                }
                if( delta.zus[i]<0.0 )
                {
                    result = Math.Min(result, current.zus[i]/(eps2-delta.zus[i]));
                }
            }
            
            //
            // analyze MHard-sized components
            //
            for(i=0; i<=mhard-1; i++)
            {
                if( delta.yv[i]<0.0 )
                {
                    result = Math.Min(result, current.yv[i]/(eps2-delta.yv[i]));
                }
            }
            
            //
            // Apply fraction to boundary
            //
            result = Math.Min(fractobnd*result, 1.0);
            return result;
        }


        /*************************************************************************
        Compute RHS for a Newton system.
        Returns inf-norms of raw (unnormalized) primal, dual, complementarity errors.
        Also returns normalizing coefficients for errors.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void computerhs(gipmstate state,
            gipmvars currentvars,
            optserv.varsfuncjac currentfj,
            double currentmu,
            gipmrhs rhs,
            ref double eprim2,
            ref double edual2,
            ref double ecmpl2,
            ref double sprim,
            ref double sdual,
            ref double scmpl,
            alglib.xparams _params)
        {
            int mflex = 0;
            int mhard = 0;
            int np = 0;
            int i = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            double v = 0;
            double[] tmp = new double[0];
            double nu = 0;
            double relaxby = 0;
            int nprim2 = 0;
            int ndual2 = 0;
            int ncmpl2 = 0;

            eprim2 = 0;
            edual2 = 0;
            ecmpl2 = 0;
            sprim = 0;
            sdual = 0;
            scmpl = 0;

            mflex = currentvars.mflex;
            mhard = currentvars.mhard;
            np = currentvars.np;
            state.mnx1pool.retrieve(ref tmp);
            alglib.ap.assert(alglib.ap.len(tmp)>=mflex+mhard+1, "GIPM: integrity check 7328 failed");
            nu = getnu(currentmu, _params);
            relaxby = Math.Min(relaxfactor*currentmu, maxrelaxation);
            eprim2 = 0;
            edual2 = 0;
            ecmpl2 = 0;
            sprim = 1;
            sdual = 1;
            scmpl = 1;
            nprim2 = 0;
            ndual2 = 0;
            ncmpl2 = 0;
            
            //
            // Compute RP = -(gmod(xp) + J'*yp + Jv'*yv - ZLP + ZUP)
            //
            ablasf.rsetallocv(np, 0.0, ref rhs.rp, _params);
            alglib.ap.assert(!currentfj.isdense, "GIPM: integrity check 8517 failed");
            j0 = currentfj.sj.ridx[0];
            j1 = currentfj.sj.ridx[1]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                rhs.rp[currentfj.sj.idx[jj]] = currentfj.sj.vals[jj];
            }
            ablasf.raddv(np, damptau*currentmu, currentvars.xp, rhs.rp, _params);
            tmp[0] = 0;
            ablasf.rcopyvx(mflex, currentvars.yp, 0, tmp, 1, _params);
            ablasf.rcopyvx(mhard, currentvars.yv, 0, tmp, 1+mflex, _params);
            sparse.sparsegemv(currentfj.sj, 1.0, 1, tmp, 0, 1.0, rhs.rp, 0, _params);
            ablasf.raddv(np, -1.0, currentvars.zlp, rhs.rp, _params);
            ablasf.raddv(np, 1.0, currentvars.zup, rhs.rp, _params);
            ablasf.rmulv(np, -1.0, rhs.rp, _params);
            edual2 = edual2+ablasf.rdotv2(np, rhs.rp, _params);
            ndual2 = ndual2+np;
            
            //
            // Compute RS = yp - yl - yu
            //
            ablasf.rsetallocv(mflex, 0.0, ref rhs.rs, _params);
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    rhs.rs[i] = currentvars.yp[i]-currentvars.yl[i]-currentvars.yu[i];
                }
            }
            edual2 = edual2+ablasf.rdotv2(mflex, rhs.rs, _params);
            ndual2 = ndual2+mflex;
            
            //
            // Compute RGL = yl + ZLS
            //
            ablasf.rsetallocv(mflex, 0.0, ref rhs.rgl, _params);
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    rhs.rgl[i] = currentvars.yl[i]+currentvars.zls[i];
                }
            }
            edual2 = edual2+ablasf.rdotv2(mflex, rhs.rgl, _params);
            ndual2 = ndual2+mflex;
            
            //
            // Compute RGU = ZUS-yu
            //
            ablasf.rsetallocv(mflex, 0.0, ref rhs.rgu, _params);
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    rhs.rgu[i] = currentvars.zus[i]-currentvars.yu[i];
                }
            }
            edual2 = edual2+ablasf.rdotv2(mflex, rhs.rgu, _params);
            ndual2 = ndual2+mflex;
            
            //
            // Compute RLP = mu*ELP-ZLP*(xp-bl)
            //         RUP = mu*EUP-ZUP*(bu-xp)
            //
            ablasf.rallocv(np, ref rhs.rlp, _params);
            ablasf.rallocv(np, ref rhs.rup, _params);
            for(i=0; i<=np-1; i++)
            {
                rhs.rlp[i] = currentmu*state.elp[i]-currentvars.zlp[i]*(currentvars.xp[i]-state.finitebndlx[i]);
                rhs.rup[i] = currentmu*state.eup[i]-currentvars.zup[i]*(state.finitebndux[i]-currentvars.xp[i]);
            }
            ecmpl2 = ecmpl2+ablasf.rdotv2(np, rhs.rlp, _params);
            ncmpl2 = ncmpl2+np;
            ecmpl2 = ecmpl2+ablasf.rdotv2(np, rhs.rup, _params);
            ncmpl2 = ncmpl2+np;
            
            //
            //              / xs-c(xp)+nu*yp        for I in range/slack constraints
            // Compute RY = |
            //              \ nu*y-(c(xp)-bndu)     for I in equality constraints
            //
            ablasf.rallocv(mflex, ref rhs.ry, _params);
            for(i=0; i<=mflex-1; i++)
            {
                if( state.isequality[i] )
                {
                    rhs.ry[i] = nu*currentvars.yp[i]-(currentfj.fi[1+i]-state.finitebndux[np+i]);
                }
                else
                {
                    rhs.ry[i] = currentvars.xs[i]-currentfj.fi[1+i]+nu*currentvars.yp[i];
                }
            }
            eprim2 = eprim2+ablasf.rdotv2(mflex, rhs.ry, _params);
            nprim2 = nprim2+mflex;
            
            //
            // Compute RCL = ELS*(cl-rlx*mu+gl-xs+nu*yl)
            //         RCU = EUS*(cu+rlx*mu-gu-xs+nu*yu)
            //
            ablasf.rsetallocv(mflex, 0.0, ref rhs.rcl, _params);
            ablasf.rsetallocv(mflex, 0.0, ref rhs.rcu, _params);
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    rhs.rcl[i] = state.els[i]*(state.finitebndlx[np+i]-relaxby+currentvars.gl[i]-currentvars.xs[i]+nu*currentvars.yl[i]);
                    rhs.rcu[i] = state.eus[i]*(state.finitebndux[np+i]+relaxby-currentvars.xs[i]-currentvars.gu[i]+nu*currentvars.yu[i]);
                }
            }
            eprim2 = eprim2+ablasf.rdotv2(mflex, rhs.rcl, _params);
            nprim2 = nprim2+mflex;
            eprim2 = eprim2+ablasf.rdotv2(mflex, rhs.rcu, _params);
            nprim2 = nprim2+mflex;
            
            //
            // Compute RLS = mu*ELS-ZLS*gl
            //         RUS = mu*EUS-ZUS*gu
            //
            ablasf.rsetallocv(mflex, 0.0, ref rhs.rls, _params);
            ablasf.rsetallocv(mflex, 0.0, ref rhs.rus, _params);
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    rhs.rls[i] = currentmu*state.els[i]-currentvars.zls[i]*currentvars.gl[i];
                    rhs.rus[i] = currentmu*state.eus[i]-currentvars.zus[i]*currentvars.gu[i];
                }
            }
            ecmpl2 = ecmpl2+ablasf.rdotv2(mflex, rhs.rls, _params);
            ncmpl2 = ncmpl2+mflex;
            ecmpl2 = ecmpl2+ablasf.rdotv2(mflex, rhs.rus, _params);
            ncmpl2 = ncmpl2+mflex;
            
            //
            // Compute RV = mu-YV*(vu-v())
            //
            ablasf.rallocv(mhard, ref rhs.rv, _params);
            for(i=0; i<=mhard-1; i++)
            {
                rhs.rv[i] = currentvars.yv[i]*(state.finitebndux[np+mflex+i]-currentfj.fi[1+mflex+i])-currentmu;
            }
            ecmpl2 = ecmpl2+ablasf.rdotv2(mhard, rhs.rv, _params);
            ncmpl2 = ncmpl2+mhard;
            
            //
            // Compute scales
            //
            sdual = Math.Max(sdual, ablasf.rmaxabsv(mflex, currentvars.yp, _params));
            sdual = Math.Max(sdual, ablasf.rmaxabsv(mflex, currentvars.yl, _params));
            sdual = Math.Max(sdual, ablasf.rmaxabsv(mflex, currentvars.yu, _params));
            sdual = Math.Max(sdual, ablasf.rmaxabsv(mhard, currentvars.yv, _params));
            v = ablasf.rmaxabsv(np, currentvars.zlp, _params);
            sdual = Math.Max(sdual, v);
            scmpl = Math.Max(scmpl, v);
            v = ablasf.rmaxabsv(np, currentvars.zup, _params);
            sdual = Math.Max(sdual, v);
            scmpl = Math.Max(scmpl, v);
            v = ablasf.rmaxabsv(mflex, currentvars.zls, _params);
            sdual = Math.Max(sdual, v);
            scmpl = Math.Max(scmpl, v);
            v = ablasf.rmaxabsv(mflex, currentvars.zus, _params);
            sdual = Math.Max(sdual, v);
            scmpl = Math.Max(scmpl, v);
            sprim = Math.Max(sprim/1000, 1);
            sdual = Math.Max(sdual/1000, 1);
            scmpl = Math.Max(scmpl/1000, 1);
            
            //
            // Done
            //
            eprim2 = Math.Sqrt(eprim2/apserv.coalesce(nprim2, 1, _params));
            edual2 = Math.Sqrt(edual2/apserv.coalesce(ndual2, 1, _params));
            ecmpl2 = Math.Sqrt(ecmpl2/apserv.coalesce(ncmpl2, 1, _params));
            state.mnx1pool.recycle(ref tmp);
        }


        /*************************************************************************
        Compute residual from the candidate solution for the already compute RHS:

            RHS := RHS - [SYSTEM]*delta
            
        Inputs include current location, candidate solution Delta and precomputed
        products H*Delta.XP, J*Delta.XP, J'*Delta.Y

        Returns inf-norm of the residual.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double computeupdateresidual(gipmstate state,
            gipmvars currentvars,
            optserv.varsfuncjac currentfj,
            double currentmu,
            double lambdatouse,
            gipmvars delta,
            double[] hdxp,
            double[] jdxp,
            double[] jtdy,
            gipmrhs rhs,
            alglib.xparams _params)
        {
            double result = 0;
            int mflex = 0;
            int mhard = 0;
            int np = 0;
            int i = 0;
            double nu = 0;
            double lambdatau = 0;

            mflex = currentvars.mflex;
            mhard = currentvars.mhard;
            np = currentvars.np;
            nu = getnu(currentmu, _params);
            lambdatau = lambdatouse+currentmu*damptau;
            result = 0;
            
            //
            // Update RP  := RP  - (Hmod+L+TAU)*d_xp - (J'*d_yp + Jv'*d_yv) + d_zlp - d_zup
            //        RS  := RS  + d_yp - d_yl - d_yu
            //        RGL := RGL + d_yl + d_zls
            //        RGU := RGU - d_yu + d_zus
            //
            //
            ablasf.raddv(np, -1.0, hdxp, rhs.rp, _params);
            ablasf.raddv(np, -lambdatau, delta.xp, rhs.rp, _params);
            ablasf.raddv(np, -1.0, jtdy, rhs.rp, _params);
            ablasf.raddv(np, 1.0, delta.zlp, rhs.rp, _params);
            ablasf.raddv(np, -1.0, delta.zup, rhs.rp, _params);
            result = Math.Max(result, ablasf.rmaxabsv(np, rhs.rp, _params));
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    rhs.rs[i] = rhs.rs[i]+delta.yp[i]-delta.yl[i]-delta.yu[i];
                }
            }
            result = Math.Max(result, ablasf.rmaxabsv(mflex, rhs.rs, _params));
            ablasf.raddv(mflex, 1.0, delta.yl, rhs.rgl, _params);
            ablasf.raddv(mflex, 1.0, delta.zls, rhs.rgl, _params);
            result = Math.Max(result, ablasf.rmaxabsv(mflex, rhs.rgl, _params));
            ablasf.raddv(mflex, -1.0, delta.yu, rhs.rgu, _params);
            ablasf.raddv(mflex, 1.0, delta.zus, rhs.rgu, _params);
            result = Math.Max(result, ablasf.rmaxabsv(mflex, rhs.rgu, _params));
            
            //
            // Update RLP := RLP - ZLP*dxp-(XP-BL)*dzlp
            //        RUP := RUP + ZUP*dxp-(BU-XP)*dzup
            //
            for(i=0; i<=np-1; i++)
            {
                rhs.rlp[i] = rhs.rlp[i]-currentvars.zlp[i]*delta.xp[i]-(currentvars.xp[i]-state.finitebndlx[i])*delta.zlp[i];
                rhs.rup[i] = rhs.rup[i]+currentvars.zup[i]*delta.xp[i]-(state.finitebndux[i]-currentvars.xp[i])*delta.zup[i];
            }
            result = Math.Max(result, ablasf.rmaxabsv(np, rhs.rlp, _params));
            result = Math.Max(result, ablasf.rmaxabsv(np, rhs.rup, _params));
            
            //
            // Update RY := RY-J*d_xp + d_xs + nu*d_yp
            //
            for(i=0; i<=mflex-1; i++)
            {
                rhs.ry[i] = rhs.ry[i]-jdxp[i]+nu*delta.yp[i];
                if( !state.isequality[i] )
                {
                    rhs.ry[i] = rhs.ry[i]+delta.xs[i];
                }
            }
            result = Math.Max(result, ablasf.rmaxabsv(mflex, rhs.ry, _params));
            
            //
            // Update RCL := RCL - ELS*(dxs - dgl - nu*dyl)
            //        RCU := RCU - EUS*(dxs + dgu - nu*dyu)
            //
            for(i=0; i<=mflex-1; i++)
            {
                rhs.rcl[i] = rhs.rcl[i]-state.els[i]*(delta.xs[i]-delta.gl[i]-nu*delta.yl[i]);
                rhs.rcu[i] = rhs.rcu[i]-state.eus[i]*(delta.xs[i]+delta.gu[i]-nu*delta.yu[i]);
            }
            result = Math.Max(result, ablasf.rmaxabsv(mflex, rhs.rcl, _params));
            result = Math.Max(result, ablasf.rmaxabsv(mflex, rhs.rcu, _params));
            
            //
            // Update RLS := RLS-(GL*d_zls + ZLS*d_gl)
            //        RUS := RUS-(GU*d_zus + ZUS*d_gu)
            //
            for(i=0; i<=mflex-1; i++)
            {
                rhs.rls[i] = rhs.rls[i]-(currentvars.gl[i]*delta.zls[i]+currentvars.zls[i]*delta.gl[i]);
                rhs.rus[i] = rhs.rus[i]-(currentvars.gu[i]*delta.zus[i]+currentvars.zus[i]*delta.gu[i]);
            }
            result = Math.Max(result, ablasf.rmaxabsv(mflex, rhs.rls, _params));
            result = Math.Max(result, ablasf.rmaxabsv(mflex, rhs.rus, _params));
            
            //
            // Update RV := RV - (YV*Jv*d_xp - (vu-v(xp))*d_yv)
            //
            for(i=0; i<=mhard-1; i++)
            {
                rhs.rv[i] = rhs.rv[i]-(currentvars.yv[i]*jdxp[mflex+i]-(state.finitebndux[np+mflex+i]-currentfj.fi[1+mflex+i])*delta.yv[i]);
            }
            result = Math.Max(result, ablasf.rmaxabsv(mhard, rhs.rv, _params));
            return result;
        }


        /*************************************************************************
        Transforms nonsymmetric primal-dual Newtom system into a symmetric condensed form

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void condenselhs(gipmstate state,
            gipmvars currentvars,
            optserv.varsfuncjac currentfj,
            double currentmu,
            gipmcondensedsystem c,
            alglib.xparams _params)
        {
            int np = 0;
            int mflex = 0;
            int mhard = 0;
            int i = 0;
            double nu = 0;
            double smallnumber = 0;

            np = state.nraw;
            mflex = state.mflex;
            mhard = state.mhard;
            nu = getnu(currentmu, _params);
            smallnumber = Math.Sqrt(1/math.maxrealnumber);
            ablasf.rallocv(mhard, ref c.d1v, _params);
            for(i=0; i<=mhard-1; i++)
            {
                c.d1v[i] = -((state.finitebndux[np+mflex+i]-currentfj.fi[1+mflex+i])/currentvars.yv[i]);
            }
            ablasf.rallocv(mflex, ref c.t0, _params);
            ablasf.rallocv(mflex, ref c.t1, _params);
            ablasf.rallocv(mflex, ref c.t2, _params);
            ablasf.rallocv(mflex, ref c.t3, _params);
            ablasf.rallocv(mflex, ref c.ta, _params);
            ablasf.rallocv(mflex, ref c.d1, _params);
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    c.t0[i] = currentvars.zls[i]/(smallnumber+currentvars.gl[i]);
                    c.t1[i] = currentvars.zus[i]/(smallnumber+currentvars.gu[i]);
                    c.t2[i] = 1/(1+nu*c.t0[i]);
                    c.t3[i] = 1/(1+nu*c.t1[i]);
                    c.ta[i] = 1/(c.t2[i]*c.t0[i]+c.t3[i]*c.t1[i]);
                    c.d1[i] = -c.ta[i]-nu;
                }
                else
                {
                    c.d1[i] = -nu;
                }
            }
            ablasf.rallocv(np, ref c.t4, _params);
            ablasf.rallocv(np, ref c.t5, _params);
            ablasf.rallocv(np, ref c.d0, _params);
            for(i=0; i<=np-1; i++)
            {
                c.t4[i] = 1/(currentvars.xp[i]-state.finitebndlx[i]);
                c.t5[i] = 1/(state.finitebndux[i]-currentvars.xp[i]);
                c.d0[i] = state.lambdav+currentmu*damptau+c.t4[i]*currentvars.zlp[i]+c.t5[i]*currentvars.zup[i];
            }
        }


        /*************************************************************************
        Condense only right-hand-side using already condensed left hand side.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void condenserhs(gipmstate state,
            gipmvars currentvars,
            optserv.varsfuncjac currentfj,
            double currentmu,
            gipmrhs rhs,
            gipmcondensedsystem c,
            alglib.xparams _params)
        {
            int np = 0;
            int mflex = 0;
            int mhard = 0;
            int i = 0;
            double invgli = 0;
            double invgui = 0;
            double smallnumber = 0;

            np = state.nraw;
            mflex = state.mflex;
            mhard = state.mhard;
            smallnumber = Math.Sqrt(1/math.maxrealnumber);
            ablasf.rallocv(mhard, ref c.wyv, _params);
            for(i=0; i<=mhard-1; i++)
            {
                c.wyv[i] = rhs.rv[i]/currentvars.yv[i];
            }
            ablasf.rallocv(mflex, ref c.tls, _params);
            ablasf.rallocv(mflex, ref c.tus, _params);
            ablasf.rallocv(mflex, ref c.tgl, _params);
            ablasf.rallocv(mflex, ref c.tgu, _params);
            ablasf.rallocv(mflex, ref c.ts, _params);
            ablasf.rallocv(mflex, ref c.wy, _params);
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    invgli = 1/(smallnumber+currentvars.gl[i]);
                    invgui = 1/(smallnumber+currentvars.gu[i]);
                    c.tls[i] = rhs.rls[i]+currentvars.zls[i]*rhs.rcl[i];
                    c.tus[i] = rhs.rus[i]-currentvars.zus[i]*rhs.rcu[i];
                    c.tgl[i] = rhs.rgl[i]+invgli*c.tls[i];
                    c.tgu[i] = rhs.rgu[i]+invgui*c.tus[i];
                    c.ts[i] = rhs.rs[i]-c.t3[i]*c.tgu[i]+c.t2[i]*c.tgl[i];
                    c.wy[i] = rhs.ry[i]+c.ta[i]*c.ts[i];
                }
                else
                {
                    c.wy[i] = rhs.ry[i];
                }
            }
            ablasf.rallocv(np, ref c.wx, _params);
            for(i=0; i<=np-1; i++)
            {
                c.wx[i] = rhs.rp[i]+c.t4[i]*rhs.rlp[i]-c.t5[i]*rhs.rup[i];
            }
        }


        /*************************************************************************
        Unpack reply to Request=1002 into a solution to the original primal-dual system.
        Returns maximum over step components;

        Delta must be properly allocated GIPMVars; however, initial values of
        its variables are ignored.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void unpacksolution(gipmstate state,
            gipmvars currentvars,
            optserv.varsfuncjac currentfj,
            double currentmu,
            gipmrhs rhs,
            gipmcondensedsystem c,
            double[] replysol,
            gipmvars delta,
            alglib.xparams _params)
        {
            int np = 0;
            int mflex = 0;
            int mhard = 0;
            int i = 0;
            double v0 = 0;
            double v1 = 0;
            double nu = 0;
            double invgli = 0;
            double invgui = 0;
            double smallnumber = 0;

            np = state.nraw;
            mflex = state.mflex;
            mhard = state.mhard;
            nu = getnu(currentmu, _params);
            smallnumber = Math.Sqrt(1/math.maxrealnumber);
            ablasf.rcopyvx(np, state.replysol, 0, delta.xp, 0, _params);
            ablasf.rcopyvx(mflex, state.replysol, np, delta.yp, 0, _params);
            ablasf.rcopyvx(mhard, state.replysol, np+mflex, delta.yv, 0, _params);
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    invgli = 1/(smallnumber+currentvars.gl[i]);
                    invgui = 1/(smallnumber+currentvars.gu[i]);
                    delta.xs[i] = c.ta[i]*(c.ts[i]+delta.yp[i]);
                    delta.yl[i] = c.t2[i]*(c.t0[i]*delta.xs[i]-c.tgl[i]);
                    delta.yu[i] = c.t3[i]*(c.t1[i]*delta.xs[i]+c.tgu[i]);
                    v0 = delta.xs[i]-nu*delta.yl[i];
                    v1 = delta.xs[i]-nu*delta.yu[i];
                    delta.zls[i] = invgli*c.tls[i]-c.t0[i]*v0;
                    delta.zus[i] = invgui*c.tus[i]+c.t1[i]*v1;
                    delta.gl[i] = state.els[i]*(v0-rhs.rcl[i]);
                    delta.gu[i] = state.eus[i]*(rhs.rcu[i]-v1);
                }
                else
                {
                    delta.xs[i] = 0;
                    delta.yl[i] = 0;
                    delta.yu[i] = 0;
                    delta.zls[i] = 0;
                    delta.zus[i] = 0;
                    delta.gl[i] = 0;
                    delta.gu[i] = 0;
                }
            }
            for(i=0; i<=np-1; i++)
            {
                delta.zlp[i] = c.t4[i]*(rhs.rlp[i]-currentvars.zlp[i]*delta.xp[i]);
                delta.zup[i] = c.t5[i]*(rhs.rup[i]+currentvars.zup[i]*delta.xp[i]);
            }
        }


        /*************************************************************************
        Compute barrier function, L2 penalty and complementarity errors
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void barrierpenaltyandcmplerror(gipmstate state,
            gipmvars currentvars,
            optserv.varsfuncjac currentfj,
            double currentmu,
            ref double barrierf,
            ref double penaltyf,
            ref double cmplerr,
            alglib.xparams _params)
        {
            int np = 0;
            int mflex = 0;
            int mhard = 0;
            int i = 0;
            double nu = 0;
            double relaxby = 0;

            barrierf = 0;
            penaltyf = 0;
            cmplerr = 0;

            np = state.nraw;
            mflex = state.mflex;
            mhard = state.mhard;
            relaxby = Math.Min(relaxfactor*currentmu, maxrelaxation);
            nu = getnu(currentmu, _params);
            
            //
            // Compute fmod(xp,mu) and barrier terms with respect to primal variables XP
            //
            barrierf = currentfj.fi[0]+0.5*currentmu*damptau*ablasf.rdotv2(np, currentvars.xp, _params);
            for(i=0; i<=np-1; i++)
            {
                if( state.hasbndlx[i] )
                {
                    barrierf = barrierf-currentmu*Math.Log(currentvars.xp[i]-state.finitebndlx[i]);
                }
                if( state.hasbndux[i] )
                {
                    barrierf = barrierf-currentmu*Math.Log(state.finitebndux[i]-currentvars.xp[i]);
                }
            }
            
            //
            // Handle barrier terms on primal variables GL and GU
            //
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    if( state.hasbndlx[np+i] )
                    {
                        barrierf = barrierf-currentmu*Math.Log(currentvars.gl[i]);
                    }
                    if( state.hasbndux[np+i] )
                    {
                        barrierf = barrierf-currentmu*Math.Log(currentvars.gu[i]);
                    }
                }
            }
            
            //
            // Handle barrier terms on 'hard' constraints V()
            //
            for(i=0; i<=mhard-1; i++)
            {
                barrierf = barrierf-currentmu*Math.Log(state.finitebndux[np+mflex+i]-currentfj.fi[1+mflex+i]);
            }
            
            //
            // Handle penalty for violation of equality constraints c(xp)-xs=0, xs-gl=cl-rlx*mu, xs+gu=cu+rlx*mu
            //
            penaltyf = 0.0;
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    penaltyf = penaltyf+0.5*math.sqr(currentfj.fi[1+i]-currentvars.xs[i]-nu*currentvars.yp[i]);
                    if( state.hasbndlx[np+i] )
                    {
                        penaltyf = penaltyf+0.5*math.sqr(currentvars.xs[i]-currentvars.gl[i]-state.finitebndlx[np+i]-nu*currentvars.yl[i]+relaxby);
                    }
                    if( state.hasbndux[np+i] )
                    {
                        penaltyf = penaltyf+0.5*math.sqr(currentvars.xs[i]+currentvars.gu[i]-state.finitebndux[np+i]-nu*currentvars.yu[i]-relaxby);
                    }
                }
                else
                {
                    penaltyf = penaltyf+0.5*math.sqr(currentfj.fi[1+i]-state.finitebndux[np+i]-nu*currentvars.yp[i]);
                }
            }
            
            //
            // Compute complementarity error
            //
            cmplerr = 0;
            for(i=0; i<=np-1; i++)
            {
                if( state.hasbndlx[i] )
                {
                    cmplerr = cmplerr+math.sqr((currentvars.xp[i]-state.finitebndlx[i])*currentvars.zlp[i]-currentmu);
                }
                if( state.hasbndux[i] )
                {
                    cmplerr = cmplerr+math.sqr((state.finitebndux[i]-currentvars.xp[i])*currentvars.zup[i]-currentmu);
                }
            }
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    if( state.hasbndlx[np+i] )
                    {
                        cmplerr = cmplerr+math.sqr(currentvars.gl[i]*currentvars.zls[i]-currentmu);
                    }
                    if( state.hasbndux[np+i] )
                    {
                        cmplerr = cmplerr+math.sqr(currentvars.gu[i]*currentvars.zus[i]-currentmu);
                    }
                }
            }
        }


        /*************************************************************************
        Merit function V0
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritv0(gipmstate state,
            gipmvars currentvars,
            optserv.varsfuncjac currentfj,
            double currentmu,
            alglib.xparams _params)
        {
            double result = 0;
            int np = 0;
            int mflex = 0;
            int mhard = 0;
            int i = 0;
            double nu = 0;
            double relaxby = 0;
            double penaltyf = 0;

            np = state.nraw;
            mflex = state.mflex;
            mhard = state.mhard;
            relaxby = Math.Min(relaxfactor*currentmu, maxrelaxation);
            nu = getnu(currentmu, _params);
            
            //
            // Compute fmod(xp,mu) and barrier terms with respect to primal variables XP
            //
            result = currentfj.fi[0]+0.5*currentmu*damptau*ablasf.rdotv2(np, currentvars.xp, _params);
            for(i=0; i<=np-1; i++)
            {
                if( state.hasbndlx[i] )
                {
                    result = result-currentmu*Math.Log(currentvars.xp[i]-state.finitebndlx[i]);
                }
                if( state.hasbndux[i] )
                {
                    result = result-currentmu*Math.Log(state.finitebndux[i]-currentvars.xp[i]);
                }
            }
            
            //
            // Handle barrier terms on primal variables GL and GU
            //
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    if( state.hasbndlx[np+i] )
                    {
                        result = result-currentmu*Math.Log(currentvars.gl[i]);
                    }
                    if( state.hasbndux[np+i] )
                    {
                        result = result-currentmu*Math.Log(currentvars.gu[i]);
                    }
                }
            }
            
            //
            // Handle barrier terms on 'hard' constraints V()
            //
            for(i=0; i<=mhard-1; i++)
            {
                result = result-currentmu*Math.Log(state.finitebndux[np+mflex+i]-currentfj.fi[1+mflex+i]);
            }
            
            //
            // Handle penalty for violation of equality constraints c(xp)-xs=0, xs-gl=cl-rlx*mu, xs+gu=cu+rlx*mu
            //
            penaltyf = 0.0;
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    penaltyf = penaltyf+0.5*math.sqr(currentfj.fi[1+i]-currentvars.xs[i]);
                    if( state.hasbndlx[np+i] )
                    {
                        penaltyf = penaltyf+0.5*math.sqr(currentvars.xs[i]-currentvars.gl[i]-state.finitebndlx[np+i]+relaxby);
                    }
                    if( state.hasbndux[np+i] )
                    {
                        penaltyf = penaltyf+0.5*math.sqr(currentvars.xs[i]+currentvars.gu[i]-state.finitebndux[np+i]-relaxby);
                    }
                }
                else
                {
                    penaltyf = penaltyf+0.5*math.sqr(currentfj.fi[1+i]-state.finitebndux[np+i]);
                }
            }
            result = result+penaltyf/(2*nu);
            return result;
        }


        /*************************************************************************
        Merit function V0
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctionpd(gipmstate state,
            gipmvars currentvars,
            optserv.varsfuncjac currentfj,
            double currentmu,
            alglib.xparams _params)
        {
            double result = 0;
            double v = 0;
            double vv = 0;
            int np = 0;
            int mflex = 0;
            int mhard = 0;
            int i = 0;
            double nu = 0;
            double relaxby = 0;
            double penaltyf = 0;
            double invmu = 0;

            np = state.nraw;
            mflex = state.mflex;
            mhard = state.mhard;
            relaxby = Math.Min(relaxfactor*currentmu, maxrelaxation);
            nu = getnu(currentmu, _params);
            invmu = 1/currentmu;
            
            //
            // Compute fmod(xp,mu) and barrier terms with respect to primal variables XP
            //
            result = currentfj.fi[0]+0.5*currentmu*damptau*ablasf.rdotv2(np, currentvars.xp, _params);
            for(i=0; i<=np-1; i++)
            {
                if( state.hasbndlx[i] )
                {
                    v = currentvars.xp[i]-state.finitebndlx[i];
                    vv = v*currentvars.zlp[i]*invmu;
                    result = result-currentmu*(Math.Log(v)+dualmeritnu*(Math.Log(vv)+1-vv));
                }
                if( state.hasbndux[i] )
                {
                    v = state.finitebndux[i]-currentvars.xp[i];
                    vv = v*currentvars.zup[i]*invmu;
                    result = result-currentmu*(Math.Log(v)+dualmeritnu*(Math.Log(vv)+1-vv));
                }
            }
            
            //
            // Handle barrier terms on primal variables GL and GU
            //
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    if( state.hasbndlx[np+i] )
                    {
                        v = currentvars.gl[i];
                        vv = v*currentvars.zls[i]*invmu;
                        result = result-currentmu*(Math.Log(v)+dualmeritnu*(Math.Log(vv)+1-vv));
                    }
                    if( state.hasbndux[np+i] )
                    {
                        v = currentvars.gu[i];
                        vv = v*currentvars.zus[i]*invmu;
                        result = result-currentmu*(Math.Log(v)+dualmeritnu*(Math.Log(vv)+1-vv));
                    }
                }
            }
            
            //
            // Handle barrier terms on 'hard' constraints V()
            //
            for(i=0; i<=mhard-1; i++)
            {
                v = state.finitebndux[np+mflex+i]-currentfj.fi[1+mflex+i];
                vv = v*currentvars.yv[i]*invmu;
                result = result-currentmu*(Math.Log(v)+dualmeritnu*(Math.Log(vv)+1-vv));
            }
            
            //
            // Handle penalty for violation of equality constraints c(xp)-xs=0, xs-gl=cl-rlx*mu, xs+gu=cu+rlx*mu
            //
            penaltyf = 0.0;
            for(i=0; i<=mflex-1; i++)
            {
                if( !state.isequality[i] )
                {
                    v = currentfj.fi[1+i]-currentvars.xs[i];
                    vv = v+nu*currentvars.yp[i];
                    penaltyf = penaltyf+0.5*v*v+dualmeritnu*vv*vv;
                    if( state.hasbndlx[np+i] )
                    {
                        v = currentvars.xs[i]-currentvars.gl[i]-state.finitebndlx[np+i]+relaxby;
                        vv = v+nu*currentvars.yl[i];
                        penaltyf = penaltyf+0.5*v*v+dualmeritnu*vv*vv;
                    }
                    if( state.hasbndux[np+i] )
                    {
                        v = currentvars.xs[i]+currentvars.gu[i]-state.finitebndux[np+i]-relaxby;
                        vv = v+nu*currentvars.yu[i];
                        penaltyf = penaltyf+0.5*v*v+dualmeritnu*vv*vv;
                    }
                }
                else
                {
                    v = currentfj.fi[1+i]-state.finitebndux[np+i];
                    vv = v+nu*currentvars.yp[i];
                    penaltyf = penaltyf+0.5*v*v+dualmeritnu*vv*vv;
                }
            }
            result = result+penaltyf/(2*nu);
            return result;
        }


        /*************************************************************************
        Prepare quasi-Newton update information
            
          -- ALGLIB --
             Copyright 11.04.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void preparequasinewtonupdate(gipmstate state,
            alglib.xparams _params)
        {
            int mflex = 0;
            int mhard = 0;
            int np = 0;
            double[] tmp0 = new double[0];

            mflex = state.mflex;
            mhard = state.mhard;
            np = state.nraw;
            state.mnx1pool.retrieve(ref tmp0);
            alglib.ap.assert(alglib.ap.len(tmp0)>=mflex+mhard+1, "GIPM: integrity check 943226 failed");
            tmp0[0] = 1;
            ablasf.rcopyvx(mflex, state.trial.yp, 0, tmp0, 1, _params);
            ablasf.rcopyvx(mhard, state.trial.yv, 0, tmp0, 1+mflex, _params);
            ablasf.rmergemulv(1+mflex+mhard, state.qnmask, tmp0, _params);
            ablasf.rsetallocv(4*np, 0.0, ref state.querydata, _params);
            ablasf.rcopyvx(np, state.current.xp, 0, state.querydata, 0*np, _params);
            ablasf.rcopyvx(np, state.trial.xp, 0, state.querydata, 1*np, _params);
            alglib.ap.assert(!state.currentfj.isdense && !state.trialfj.isdense, "GIPM: integrity check 418223 failed");
            sparse.sparsegemv(state.currentfj.sj, 1.0, 1, tmp0, 0, 0.0, state.querydata, 2*np, _params);
            ablasf.raddvx(np, damptau*state.mu, state.current.xp, 0, state.querydata, 2*np, _params);
            sparse.sparsegemv(state.trialfj.sj, 1.0, 1, tmp0, 0, 0.0, state.querydata, 3*np, _params);
            ablasf.raddvx(np, damptau*state.mu, state.trial.xp, 0, state.querydata, 3*np, _params);
            state.mnx1pool.recycle(ref tmp0);
        }


        /*************************************************************************
        Computes minimum nonzero value of the vector. Returns 0 if all components
        are nonpositive.

        INPUT PARAMETERS:
            X               -   vector
            N               -   length

          -- ALGLIB --
             Copyright 01.11.2020 by Bochkanov Sergey
        *************************************************************************/
        private static double minabsnz(double[] x,
            int n1,
            alglib.xparams _params)
        {
            double result = 0;
            int n0 = 0;
            int i = 0;
            bool nz = new bool();

            result = 0;
            n0 = 0;
            nz = false;
            for(i=n0; i<=n1-1; i++)
            {
                if( (double)(x[i])!=(double)(0) )
                {
                    if( !nz )
                    {
                        result = Math.Abs(x[i]);
                        nz = true;
                    }
                    else
                    {
                        result = Math.Min(result, Math.Abs(x[i]));
                    }
                }
            }
            return result;
        }


        /*************************************************************************
        Compute safeguard BndLP/UP from FiniteBndLX/UX.

          -- ALGLIB --
             Copyright 25.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void safeboundsfromfinitetightened(gipmstate state,
            alglib.xparams _params)
        {
            int nraw = 0;
            int i = 0;
            double vmid = 0;
            double v = 0;

            nraw = state.nraw;
            ablasf.rallocv(nraw, ref state.safeguardbndlp, _params);
            ablasf.rallocv(nraw, ref state.safeguardbndup, _params);
            v = 10*math.machineepsilon;
            for(i=0; i<=nraw-1; i++)
            {
                
                //
                // Safeguard bounds on primal variables and check interval width
                //
                vmid = 0.5*(state.finitebndlx[i]+state.finitebndux[i]);
                state.safeguardbndlp[i] = Math.Min(state.finitebndlx[i]+Math.Max(Math.Abs(state.finitebndlx[i]), 1.0)*v, vmid);
                state.safeguardbndup[i] = Math.Max(state.finitebndux[i]-Math.Max(Math.Abs(state.finitebndux[i]), 1.0)*v, vmid);
                alglib.ap.assert((double)(state.safeguardbndup[i])>=(double)(state.safeguardbndlp[i]), "GIPM: bounds on primal variables are too tight, bad problem preprocessing");
            }
        }


        /*************************************************************************
        Tightens/relaxes bounds, recomputes safeguarded BndLP/UP if necessary.

          -- ALGLIB --
             Copyright 25.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void tightenrelaxbounds(gipmstate state,
            alglib.xparams _params)
        {
            int nraw = 0;
            int mflex = 0;
            int nxf = 0;
            int ntightened = 0;
            int nrelaxed = 0;
            int i = 0;
            double xpnrm = 0;
            double xsnrm = 0;
            double vtgt = 0;
            double vrlx = 0;
            double vmid = 0;
            double vx = 0;
            double vnrm = 0;
            double vprev = 0;
            double targetdist = 0;

            alglib.ap.assert((double)(relaxdist)<(double)(tightendist), "GIPM: integrity check 1821 failed");
            targetdist = Math.Sqrt(relaxdist*tightendist);
            nraw = state.nraw;
            mflex = state.mflex;
            nxf = nraw+mflex;
            xpnrm = Math.Max(ablasf.rmaxabsv(nraw, state.current.xp, _params), 1);
            xsnrm = Math.Max(ablasf.rmaxabsv(mflex, state.current.xs, _params), 1);
            ntightened = 0;
            nrelaxed = 0;
            for(i=0; i<=nxf-1; i++)
            {
                if( i<nraw || !state.isequality[i-nraw] )
                {
                    
                    //
                    // Variable value and distance scaling factor
                    //
                    if( i<nraw )
                    {
                        vx = state.current.xp[i];
                        vnrm = xpnrm;
                    }
                    else
                    {
                        vx = state.current.xs[i-nraw];
                        vnrm = xsnrm;
                    }
                    if( state.hasbndlx[i] )
                    {
                        vtgt = Math.Max(vx-vnrm*tightendist, state.bndlx[i]);
                        vrlx = Math.Max(vx-vnrm*relaxdist, state.bndlx[i]);
                        vmid = Math.Max(vx-vnrm*targetdist, state.bndlx[i]);
                        vprev = state.finitebndlx[i];
                        if( (double)(state.finitebndlx[i])<(double)(vtgt) )
                        {
                            state.finitebndlx[i] = vmid;
                            ntightened = ntightened+1;
                        }
                        if( (double)(state.finitebndlx[i])>(double)(vrlx) )
                        {
                            state.finitebndlx[i] = vmid;
                            nrelaxed = nrelaxed+1;
                        }
                        if( i>=nraw )
                        {
                            state.current.gl[i-nraw] = Math.Max(state.current.gl[i-nraw]-(state.finitebndlx[i]-vprev), math.machineepsilon);
                        }
                    }
                    if( state.hasbndux[i] )
                    {
                        vtgt = Math.Min(vx+vnrm*tightendist, state.bndux[i]);
                        vrlx = Math.Min(vx+vnrm*relaxdist, state.bndux[i]);
                        vmid = Math.Min(vx+vnrm*targetdist, state.bndux[i]);
                        vprev = state.finitebndux[i];
                        if( (double)(state.finitebndux[i])>(double)(vtgt) )
                        {
                            state.finitebndux[i] = vmid;
                            ntightened = ntightened+1;
                        }
                        if( (double)(state.finitebndux[i])<(double)(vrlx) )
                        {
                            state.finitebndux[i] = vmid;
                            nrelaxed = nrelaxed+1;
                        }
                        if( i>=nraw )
                        {
                            state.current.gu[i-nraw] = Math.Max(state.current.gu[i-nraw]-(vprev-state.finitebndux[i]), math.machineepsilon);
                        }
                    }
                }
            }
            safeboundsfromfinitetightened(state, _params);
            if( state.dotrace && nrelaxed+ntightened>0 )
            {
                alglib.ap.trace(System.String.Format("> {0,0:d} bounds tightened, {1,0:d} bounds relaxed\n", ntightened, nrelaxed));
            }
        }


        /*************************************************************************
        Compute recommended penalty coefficient Nu

          -- ALGLIB --
             Copyright 25.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double getnu(double currentmu,
            alglib.xparams _params)
        {
            double result = 0;

            result = Math.Min(currentmu/penaltygrowth, maxnu*Math.Max(currentmu, 1));
            return result;
        }


        /*************************************************************************
        Initialize memory for nonmonotonic merit function optimization

          -- ALGLIB --
             Copyright 25.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void nonmonotonicinit(gipmstate state,
            int memlen,
            double merit0,
            alglib.xparams _params)
        {
            alglib.ap.assert(memlen>=0, "GIPM: integrity check 696157 failed");
            state.nonmonotonicmemlen = memlen;
            state.nonmonotonicpos = 0;
            ablasf.rsetallocv(memlen+1, merit0, ref state.nonmonotonicmerit, _params);
            state.nonmonotonicmerit[memlen] = merit0;
        }


        /*************************************************************************
        Push new value to the nonmonotonic memory

          -- ALGLIB --
             Copyright 25.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void nonmonotonicpush(gipmstate state,
            double meritv,
            alglib.xparams _params)
        {
            state.nonmonotonicmerit[state.nonmonotonicpos] = meritv;
            state.nonmonotonicpos = (state.nonmonotonicpos+1)%(state.nonmonotonicmemlen+1);
        }


        /*************************************************************************
        Returns nonmonotonic correction that should be added to MeritV

          -- ALGLIB --
             Copyright 25.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static double nonmonotonicgetcorr(gipmstate state,
            double meritv,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double mx = 0;

            mx = meritv;
            for(i=0; i<=state.nonmonotonicmemlen; i++)
            {
                mx = Math.Max(mx, state.nonmonotonicmerit[i]);
            }
            result = Math.Max(mx-meritv, 0.0);
            return result;
        }


    }
    public partial class gqpipm
    {
        /*************************************************************************
        A sparse Hessian for a conic constraint with precomputed offsets that
        allow to propagate its values into SparseHDeps every time the constraint
        Hessian changes.

        * LowerH            lower triangular NV*NV matrix in CRS format; its entries
                            are copied into SparseHDeps matrix prior to using SparseHDeps
                            to compute a Lagrangian Hessian.
        * OrderVarIdx       array[NV], index of a permutation that sorts VarIdx[]
                            (remember that conic constraints have one/several special
                            VarIdx elements unordered)
        * InjectionOffsets  array[LowerH.RIdx[NV]], offsets in SparseHDeps.Vals[]
                            where elements of LowerH are stored.
        *************************************************************************/
        public class gqpsparseconichessian : apobject
        {
            public sparse.sparsematrix lowerh;
            public int[] ordervaridx;
            public int[] injectionoffsets;
            public gqpsparseconichessian()
            {
                init();
            }
            public override void init()
            {
                lowerh = new sparse.sparsematrix();
                ordervaridx = new int[0];
                injectionoffsets = new int[0];
            }
            public override alglib.apobject make_copy()
            {
                gqpsparseconichessian _result = new gqpsparseconichessian();
                _result.lowerh = lowerh!=null ? (sparse.sparsematrix)lowerh.make_copy() : null;
                _result.ordervaridx = (int[])ordervaridx.Clone();
                _result.injectionoffsets = (int[])injectionoffsets.Clone();
                return _result;
            }
        };


        /*************************************************************************
        An optional dense representation of a sparse quadratic term, that is used
        to accelerate sparse matrix-vector products with big dense matrices.

        VarIdx are guaranteed to be sorted.
        *************************************************************************/
        public class gqpoptionaldense : apobject
        {
            public bool hasdenseterm;
            public int nvars;
            public int[] varidx;
            public double[,] q;
            public gqpoptionaldense()
            {
                init();
            }
            public override void init()
            {
                varidx = new int[0];
                q = new double[0,0];
            }
            public override alglib.apobject make_copy()
            {
                gqpoptionaldense _result = new gqpoptionaldense();
                _result.hasdenseterm = hasdenseterm;
                _result.nvars = nvars;
                _result.varidx = (int[])varidx.Clone();
                _result.q = (double[,])q.Clone();
                return _result;
            }
        };


