            int tmpi = 0;

            initprimdual = gipm.gipmgetinitprimdual(_params);
            ablasf.rsetallocv(n, Double.NegativeInfinity, ref impliedbndl, _params);
            ablasf.rsetallocv(n, Double.PositiveInfinity, ref impliedbndu, _params);
            ablasf.rsetallocv(n, -math.maxrealnumber, ref lagbcmin, _params);
            ablasf.rsetallocv(n, math.maxrealnumber, ref lagbcmax, _params);
            for(coneidx=0; coneidx<=optserv.xccgetcount(xcc, _params)-1; coneidx++)
            {
                xcc.constraints.get(coneidx, ref cci);
                nv = cci.nvars;
                if( nv==0 )
                {
                    continue;
                }
                if( cci.conetype==optserv.xccgenericorthogonalconetype(_params) )
                {
                    tsort.tagsortmiddleirr(cci.varidx, cci.diaga, cci.shftc, 0, nv-1, _params);
                    newnradial = 0;
                    for(i=0; i<=nv-2; i++)
                    {
                        if( (double)(cci.diaga[i])==(double)(0.0) )
                        {
                            cci.shftc[nv] = cci.shftc[nv]+cci.shftc[i]*cci.shftc[i];
                            continue;
                        }
                        if( newnradial>0 && cci.varidx[i]==cci.varidx[newnradial-1] )
                        {
                            a0 = cci.diaga[newnradial-1];
                            b0 = cci.shftc[newnradial-1];
                            a1 = cci.diaga[i];
                            b1 = cci.shftc[i];
                            cci.diaga[newnradial-1] = Math.Sqrt(a0*a0+a1*a1);
                            alglib.ap.assert((double)(cci.diaga[newnradial-1])>(double)(0), "GQPIPM: integrity check 248622 failed");
                            cci.shftc[newnradial-1] = (a0*b0+a1*b1)/cci.diaga[newnradial-1];
                            cci.shftc[nv] = cci.shftc[nv]+Math.Max(b0*b0+b1*b1-cci.shftc[newnradial-1]*cci.shftc[newnradial-1], 0.0);
                            continue;
                        }
                        cci.varidx[newnradial] = cci.varidx[i];
                        cci.diaga[newnradial] = cci.diaga[i];
                        cci.shftc[newnradial] = cci.shftc[i];
                        newnradial = newnradial+1;
                    }
                    cci.varidx[newnradial] = cci.varidx[nv-1];
                    cci.diaga[newnradial] = cci.diaga[nv-1];
                    cci.shftc[newnradial] = cci.shftc[nv-1];
                    newnradial = newnradial+1;
                    cci.shftc[newnradial] = cci.shftc[nv];
                    nv = newnradial;
                    cci.nvars = nv;
                    cci.conetype = optserv.xccprimitiveconetype(_params);
