                {
                    kpow = cci.kpow;
                    newnradial = 0;
                    if( kpow<nv )
                    {
                        tsort.tagsortmiddleirr(cci.varidx, cci.diaga, cci.shftc, 0, nv-kpow, _params);
                        for(i=0; i<=nv-kpow-1; i++)
                        {
                            if( (double)(cci.diaga[i])==(double)(0.0) )
                            {
                                cci.shftc[nv] = cci.shftc[nv]+cci.shftc[i]*cci.shftc[i];
                                continue;
                            }
                            if( newnradial>0 && cci.varidx[i]==cci.varidx[newnradial-1] )
                            {
                                a0 = cci.diaga[newnradial-1];
                                b0 = cci.shftc[newnradial-1];
                                a1 = cci.diaga[i];
                                b1 = cci.shftc[i];
                                cci.diaga[newnradial-1] = Math.Sqrt(a0*a0+a1*a1);
                                alglib.ap.assert((double)(cci.diaga[newnradial-1])>(double)(0), "GQPIPM: integrity check 248622 failed");
                                cci.shftc[newnradial-1] = (a0*b0+a1*b1)/cci.diaga[newnradial-1];
                                cci.shftc[nv] = cci.shftc[nv]+Math.Max(b0*b0+b1*b1-cci.shftc[newnradial-1]*cci.shftc[newnradial-1], 0.0);
                                continue;
                            }
                            cci.varidx[newnradial] = cci.varidx[i];
                            cci.diaga[newnradial] = cci.diaga[i];
                            cci.shftc[newnradial] = cci.shftc[i];
                            newnradial = newnradial+1;
                        }
                    }
                    newaxial = 0;
                    for(i=nv-kpow; i<=nv-1; i++)
                    {
                        cci.varidx[newnradial+newaxial] = cci.varidx[i];
                        cci.diaga[newnradial+newaxial] = cci.diaga[i];
                        cci.shftc[newnradial+newaxial] = cci.shftc[i];
                        newaxial = newaxial+1;
                    }
                    cci.shftc[newnradial+newaxial] = cci.shftc[nv];
                    nv = newnradial+newaxial;
                    cci.nvars = nv;
                    cci.conetype = optserv.xccdenormalizedprimitivepowerconetype(_params);
                    continue;
                }
                if( cci.conetype==optserv.xccprimitiveconetype(_params) )
                {
                    continue;
                }
                if( cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                {
                    continue;
                }
                alglib.ap.assert(false, "GQPIPM: integrity check 227420 failed");
            }
            ablasf.bsetallocv(n, false, ref isconicradial, _params);
            ablasf.bsetallocv(n, false, ref isconicaxial, _params);
            ablasf.isetallocv(n, 0, ref cntradial, _params);
            ablasf.isetallocv(n, 0, ref cntupwardaxial, _params);
            ablasf.isetallocv(n, 0, ref cntdownwardaxial, _params);
            for(coneidx=0; coneidx<=optserv.xccgetcount(xcc, _params)-1; coneidx++)
            {
                xcc.constraints.get(coneidx, ref cci);
                nv = cci.nvars;
                if( nv==0 )
                {
                    continue;
                }
                if( cci.conetype==optserv.xccdenormalizedprimitiveconetype(_params) || cci.conetype==optserv.xccprimitiveconetype(_params) )
                {
                    for(i=0; i<=nv-2; i++)
                    {
                        cntradial[cci.varidx[i]] = cntradial[cci.varidx[i]]+1;
                    }
                    if( (double)(cci.diaga[nv-1])>(double)(0) )
                    {
                        cntupwardaxial[cci.varidx[nv-1]] = cntupwardaxial[cci.varidx[nv-1]]+1;
                    }
                    if( (double)(cci.diaga[nv-1])<(double)(0) )
                    {
                        cntdownwardaxial[cci.varidx[nv-1]] = cntdownwardaxial[cci.varidx[nv-1]]+1;
                    }
                    continue;
                }
                if( cci.conetype==optserv.xccdenormalizedprimitivepowerconetype(_params) || cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                {
                    kpow = cci.kpow;
                    for(i=0; i<=nv-kpow-1; i++)
                    {
                        cntradial[cci.varidx[i]] = cntradial[cci.varidx[i]]+1;
                    }
                    for(i=nv-kpow; i<=nv-1; i++)
                    {
                        if( (double)(cci.diaga[i])>(double)(0) )
                        {
                            cntupwardaxial[cci.varidx[i]] = cntupwardaxial[cci.varidx[i]]+1;
                        }
                        if( (double)(cci.diaga[i])<(double)(0) )
                        {
                            cntdownwardaxial[cci.varidx[i]] = cntdownwardaxial[cci.varidx[i]]+1;
                        }
                    }
                    continue;
                }
                alglib.ap.assert(false, "GQPIPM: integrity check 397122 failed");
            }
            for(coneidx=0; coneidx<=optserv.xccgetcount(xcc, _params)-1; coneidx++)
            {
                xcc.constraints.get(coneidx, ref cci);
                nv = cci.nvars;
                if( nv==0 )
                {
                    continue;
                }
                donecc = false;
                if( cci.conetype==optserv.xccprimitiveconetype(_params) )
                {
