                    ccscale = Math.Max(ccscale, 1);
                    axisidx = cci.varidx[nv-1];
                    a0 = cci.diaga[nv-1];
                    b0 = cci.shftc[nv-1];
                    needslacks = (needslacks || (double)(ccscale)==(double)(0)) || (double)(Math.Abs(a0*s[axisidx]))<=(double)(minconicdenominator*ccscale);
                    needslacks = needslacks || apserv.ibinarysearchispresent(cci.varidx, 0, nv-1, axisidx, _params);
                    needslacks = needslacks || ((math.isfinite(bndl[axisidx]) && math.isfinite(bndu[axisidx])) && (double)(bndu[axisidx]-bndl[axisidx])<=(double)(tootightconstraints*s[axisidx]));
                    if( !needslacks )
                    {
                        vbnd = -(b0/a0);
                        if( (double)(a0)>(double)(0) )
                        {
                            if( !math.isfinite(bndl[axisidx]) || (double)(vbnd)>(double)(bndl[axisidx]) )
                            {
                                bndl[axisidx] = vbnd;
                                lagbcmin[axisidx] = 0.0;
                            }
                        }
                        else
                        {
                            if( !math.isfinite(bndu[axisidx]) || (double)(vbnd)<(double)(bndu[axisidx]) )
                            {
                                bndu[axisidx] = vbnd;
                                lagbcmax[axisidx] = 0.0;
                            }
                        }
                        continue;
                    }
                }
                if( cci.conetype==optserv.xccdenormalizedprimitiveconetype(_params) || cci.conetype==optserv.xccprimitiveconetype(_params) )
                {
                    alglib.ap.assert(!donecc, "GQIPM: integrity check 314116 failed");
                    a0 = cci.diaga[nv-1];
                    b0 = cci.shftc[nv-1];
                    axisidx = cci.varidx[nv-1];
                    ablasf.rgrowappendv(n+1, ref s, s[axisidx], _params);
                    ablasf.rgrowappendv(n+1, ref xorigin, 0.0, _params);
                    ablasf.rgrowappendv(n+1, ref b, 0.0, _params);
                    ablasf.rgrowappendv(n+1, ref bndl, 0.0, _params);
                    ablasf.rgrowappendv(n+1, ref bndu, Double.PositiveInfinity, _params);
                    ablasf.rgrowappendv(n+1, ref xs, initprimdual, _params);
                    if( hash )
                    {
                        alglib.ap.assert(sparseh.n==n && sparseh.m==n, "GQPIPM: integrity check 243517 failed");
                        sparseh.n = sparseh.n+1;
                        sparse.sparseappendemptyrow(sparseh, _params);
                    }
                    if( m==0 )
                    {
