                    }
                    alglib.ap.assert(a.n==n && a.m==m, "GQPIPM: integrity check 243517 failed");
                    a.n = n+1;
                    sparse.sparseappendemptyrow(a, _params);
                    sparse.sparseappendelement(a, axisidx, -a0, _params);
                    sparse.sparseappendelement(a, n, 1.0, _params);
                    rhs = cci.shftc[nv-1];
                    if( cci.applyorigin )
                    {
                        rhs = rhs-a0*xorigin[axisidx];
                    }
                    ablasf.rgrowappendv(m+1, ref al, rhs, _params);
                    ablasf.rgrowappendv(m+1, ref au, rhs, _params);
                    ablasf.rgrowappendv(n+1, ref lagbcmin, -math.maxrealnumber, _params);
                    ablasf.rgrowappendv(n+1, ref lagbcmax, math.maxrealnumber, _params);
                    ablasf.rgrowappendv(n+1, ref impliedbndl, 0.0, _params);
                    ablasf.rgrowappendv(n+1, ref impliedbndu, Double.PositiveInfinity, _params);
                    ablasf.bgrowappendv(n+1, ref isconicradial, false, _params);
                    ablasf.bgrowappendv(n+1, ref isconicaxial, true, _params);
                    cci.diaga[nv-1] = 1.0;
                    cci.shftc[nv-1] = 0.0;
                    cci.varidx[nv-1] = n;
                    if( (double)(a0)!=(double)(0) && (double)(Math.Abs(b0/a0))<(double)(bigboxconstraint*s[axisidx]) )
                    {
                        vbnd = -(b0/a0);
                        if( ((double)(a0)>(double)(0) && (!math.isfinite(bndl[axisidx]) || (double)(vbnd)>(double)(bndl[axisidx]))) && (!math.isfinite(bndu[axisidx]) || (double)(vbnd)<(double)(bndu[axisidx]-tootightconstraints*s[axisidx])) )
                        {
                            bndl[axisidx] = vbnd;
                            lagbcmin[axisidx] = 0.0;
                        }
                        if( ((double)(a0)<(double)(0) && (!math.isfinite(bndu[axisidx]) || (double)(vbnd)<(double)(bndu[axisidx]))) && (!math.isfinite(bndl[axisidx]) || (double)(vbnd)>(double)(bndl[axisidx]+tootightconstraints*s[axisidx])) )
                        {
                            bndu[axisidx] = vbnd;
                            lagbcmax[axisidx] = 0.0;
                        }
                    }
                    if( (double)(a0)>(double)(0) )
                    {
                        alglib.ap.assert(cntupwardaxial[axisidx]>0, "GQPIPM: integrity check 395304 failed");
                        cntupwardaxial[axisidx] = cntupwardaxial[axisidx]-1;
                        ablasf.igrowappendv(n+1, ref cntupwardaxial, 1, _params);
                    }
                    if( (double)(a0)<(double)(0) )
                    {
                        alglib.ap.assert(cntdownwardaxial[axisidx]>0, "GQPIPM: integrity check 400305 failed");
                        cntdownwardaxial[axisidx] = cntdownwardaxial[axisidx]-1;
                        ablasf.igrowappendv(n+1, ref cntdownwardaxial, 1, _params);
                    }
                    cci.conetype = optserv.xccprimitiveconetype(_params);
                    n = n+1;
                    m = m+1;
                    donecc = true;
                }
                if( cci.conetype==optserv.xccdenormalizedprimitivepowerconetype(_params) || cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                {
                    alglib.ap.assert(!donecc, "GQIPM: integrity check 497219 failed");
                    kpow = cci.kpow;
                    ccscale = 0;
                    for(i=0; i<=nv-kpow-1; i++)
                    {
                        ccscale = Math.Max(ccscale, Math.Abs(cci.diaga[i]*s[cci.varidx[i]]));
                    }
                    ccscale = Math.Max(ccscale, 1);
                    for(i=nv-kpow; i<=nv-1; i++)
                    {
                        axisidx = cci.varidx[i];
                        a0 = cci.diaga[i];
                        b0 = cci.shftc[i];
                        needslacks = false;
                        needslacks = (needslacks || (double)(ccscale)==(double)(0)) || (double)(Math.Abs(a0*s[axisidx]))<=(double)(minconicdenominator*ccscale);
                        needslacks = (needslacks || apserv.ibinarysearchispresent(cci.varidx, 0, nv-kpow, axisidx, _params)) || apserv.ilinearsearchispresent(cci.varidx, nv-kpow, i, axisidx, _params);
                        needslacks = needslacks || ((math.isfinite(bndl[axisidx]) && math.isfinite(bndu[axisidx])) && (double)(bndu[axisidx]-bndl[axisidx])<=(double)(tootightconstraints*s[axisidx]));
                        if( !needslacks )
                        {
                            vbnd = -(b0/a0);
                            if( (double)(a0)>(double)(0) )
                            {
                                if( !math.isfinite(bndl[axisidx]) || (double)(vbnd)>(double)(bndl[axisidx]) )
                                {
                                    bndl[axisidx] = vbnd;
                                    lagbcmin[axisidx] = 0.0;
                                }
                            }
                            else
                            {
                                if( !math.isfinite(bndu[axisidx]) || (double)(vbnd)<(double)(bndu[axisidx]) )
                                {
                                    bndu[axisidx] = vbnd;
                                    lagbcmax[axisidx] = 0.0;
                                }
                            }
                            continue;
                        }
                        ablasf.rgrowappendv(n+1, ref s, s[axisidx], _params);
                        ablasf.rgrowappendv(n+1, ref xorigin, 0.0, _params);
                        ablasf.rgrowappendv(n+1, ref b, 0.0, _params);
                        ablasf.rgrowappendv(n+1, ref bndl, 0.0, _params);
                        ablasf.rgrowappendv(n+1, ref bndu, Double.PositiveInfinity, _params);
                        ablasf.rgrowappendv(n+1, ref xs, initprimdual, _params);
                        if( hash )
                        {
                            alglib.ap.assert(sparseh.n==n && sparseh.m==n, "GQPIPM: integrity check 567225 failed");
                            sparseh.n = sparseh.n+1;
                            sparse.sparseappendemptyrow(sparseh, _params);
                        }
                        if( m==0 )
                        {
                            sparse.sparsecreatecrsemptybuf(n, a, _params);
                        }
                        alglib.ap.assert(a.n==n && a.m==m, "GQPIPM: integrity check 573226 failed");
                        a.n = n+1;
                        sparse.sparseappendemptyrow(a, _params);
                        sparse.sparseappendelement(a, axisidx, -a0, _params);
                        sparse.sparseappendelement(a, n, 1.0, _params);
                        rhs = b0;
                        if( cci.applyorigin )
                        {
                            rhs = rhs-a0*xorigin[axisidx];
                        }
                        ablasf.rgrowappendv(m+1, ref al, rhs, _params);
                        ablasf.rgrowappendv(m+1, ref au, rhs, _params);
                        ablasf.rgrowappendv(n+1, ref lagbcmin, -math.maxrealnumber, _params);
                        ablasf.rgrowappendv(n+1, ref lagbcmax, math.maxrealnumber, _params);
                        ablasf.rgrowappendv(n+1, ref impliedbndl, 0.0, _params);
                        ablasf.rgrowappendv(n+1, ref impliedbndu, Double.PositiveInfinity, _params);
                        ablasf.bgrowappendv(n+1, ref isconicradial, false, _params);
                        ablasf.bgrowappendv(n+1, ref isconicaxial, true, _params);
                        cci.diaga[i] = 1.0;
                        cci.shftc[i] = 0.0;
                        cci.varidx[i] = n;
                        if( (double)(a0)!=(double)(0) && (double)(Math.Abs(b0/a0))<(double)(bigboxconstraint*s[axisidx]) )
                        {
                            vbnd = -(b0/a0);
                            if( ((double)(a0)>(double)(0) && (!math.isfinite(bndl[axisidx]) || (double)(vbnd)>(double)(bndl[axisidx]))) && (!math.isfinite(bndu[axisidx]) || (double)(vbnd)<(double)(bndu[axisidx]-tootightconstraints*s[axisidx])) )
                            {
                                bndl[axisidx] = vbnd;
                                lagbcmin[axisidx] = 0.0;
                            }
                            if( ((double)(a0)<(double)(0) && (!math.isfinite(bndu[axisidx]) || (double)(vbnd)<(double)(bndu[axisidx]))) && (!math.isfinite(bndl[axisidx]) || (double)(vbnd)>(double)(bndl[axisidx]+tootightconstraints*s[axisidx])) )
                            {
                                bndu[axisidx] = vbnd;
                                lagbcmax[axisidx] = 0.0;
                            }
                        }
                        if( (double)(a0)>(double)(0) )
                        {
                            alglib.ap.assert(cntupwardaxial[axisidx]>0, "GQPIPM: integrity check 395304 failed");
                            cntupwardaxial[axisidx] = cntupwardaxial[axisidx]-1;
                            ablasf.igrowappendv(n+1, ref cntupwardaxial, 1, _params);
                        }
                        if( (double)(a0)<(double)(0) )
                        {
                            alglib.ap.assert(cntdownwardaxial[axisidx]>0, "GQPIPM: integrity check 400305 failed");
                            cntdownwardaxial[axisidx] = cntdownwardaxial[axisidx]-1;
                            ablasf.igrowappendv(n+1, ref cntdownwardaxial, 1, _params);
                        }
                        n = n+1;
                        m = m+1;
                    }
                    for(i=nv-kpow; i<=nv-2; i++)
                    {
                        for(j=i; j<=nv-2; j++)
                        {
                            if( cci.varidx[j]>cci.varidx[j+1] )
                            {
                                tmpi = cci.varidx[j];
                                cci.varidx[j] = cci.varidx[j+1];
                                cci.varidx[j+1] = tmpi;
                                tmpr = cci.diaga[j];
                                cci.diaga[j] = cci.diaga[j+1];
                                cci.diaga[j+1] = tmpr;
                                tmpr = cci.shftc[j];
                                cci.shftc[j] = cci.shftc[j+1];
                                cci.shftc[j+1] = tmpr;
                                tmpr = cci.alphapow[j-(nv-kpow)];
                                cci.alphapow[j-(nv-kpow)] = cci.alphapow[j+1-(nv-kpow)];
                                cci.alphapow[j+1-(nv-kpow)] = tmpr;
                            }
                        }
                    }
                    cci.conetype = optserv.xccprimitivepowerconetype(_params);
                    donecc = true;
                }
                alglib.ap.assert(donecc, "GQPIPM: integrity check 218502 failed (unexpected cone type and/or barrier type)");
            }
            opts.xqcupdaten(xqc, n, _params);
            optserv.xccupdaten(xcc, n, _params);
        }


        /*************************************************************************
        Initialize GQPIPM structure.

        X0      -   initial point; must be:
                    * strictly feasible wrt non-equality box constraints
                    * non-strictly feasible wrt equality box constraints
                    * strictly feasible wrt conic constraints, if present
                    Failure to satisfy these properties will lead to an  exception
                    generated either during  initialization  or  during  the  very
                    first iteration.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void gqpipminitbuf(double[] bndl,
            double[] bndu,
            double[] x0,
            int n,
            bool isdense,
            bool isfirstorder,
            double eps,
            int maxits,
            gqpipmstate state,
            alglib.xparams _params)
        {
            int i = 0;
            double fixtol = 0;
            bool bflg = new bool();

            alglib.ap.assert(!(isdense && isfirstorder), "QPIPM: dense problems do not support first order iteration, only second order one");
            fixtol = Math.Max(apserv.coalesce(eps, 0.01*Math.Sqrt(math.machineepsilon), _params), Math.Pow(math.machineepsilon, 0.75));
            state.algomode = amdense;
            if( !isdense )
            {
                state.algomode = apserv.icase2(isfirstorder, amhybrid, amsparse, _params);
            }
            state.basehrank = 0;
            if( state.algomode==amhybrid )
            {
                ablasf.rsetallocv(n, 0.0, ref state.basehsr1diag, _params);
            }
            state.n = n;
            state.mlc = 0;
            state.mqc = 0;
            state.msocc = 0;
            state.hessmemlen = 0;
            state.hessmaxoffdiag = 0;
            state.cvxobjective = 0;
            state.cvxqc = 0;
            state.cvxcc = 0;
            opts.xqcinit(n, state.xqc, _params);
            optserv.xccinit(n, state.xcc, _params);
            state.optionaldenseq1.hasdenseterm = false;
            state.optionaldensexqc.clear();
            state.fixedvarscnt = 0;
            ablasf.rsetallocv(n, Double.NegativeInfinity, ref state.wrkbndl, _params);
            ablasf.rsetallocv(n, Double.PositiveInfinity, ref state.wrkbndu, _params);
            ablasf.rsetallocv(n, -Math.Sqrt(math.maxrealnumber), ref state.finiterawbndl, _params);
            ablasf.rsetallocv(n, Math.Sqrt(math.maxrealnumber), ref state.finiterawbndu, _params);
            ablasf.bsetallocv(n, false, ref state.isfixed, _params);
            ablasf.iallocv(n, ref state.fixedidx, _params);
            ablasf.rallocv(n, ref state.x0, _params);
            for(i=0; i<=n-1; i++)
            {
                if( (math.isfinite(bndl[i]) && math.isfinite(bndu[i])) && (double)(bndu[i]-bndl[i])<(double)(fixtol) )
                {
                    state.isfixed[i] = true;
                    state.fixedidx[state.fixedvarscnt] = i;
                    state.fixedvarscnt = state.fixedvarscnt+1;
                }
                state.x0[i] = x0[i];
                if( math.isfinite(bndl[i]) )
                {
                    state.wrkbndl[i] = bndl[i];
                    state.finiterawbndl[i] = bndl[i];
                }
                if( math.isfinite(bndu[i]) )
                {
                    state.wrkbndu[i] = bndu[i];
                    state.finiterawbndu[i] = bndu[i];
                }
            }
            ablasf.rsetallocv(n, 0.0, ref state.c, _params);
            ablasf.iallocv(n, ref state.iotac, _params);
            for(i=0; i<=n-1; i++)
            {
                state.iotac[i] = i;
            }
            state.nq = 0;
            bflg = false;
            if( state.algomode==amdense )
            {
                ablasf.rsetallocm(n, n, 0.0, ref state.denseq, _params);
                bflg = true;
            }
            if( state.algomode==amsparse || state.algomode==amhybrid )
            {
                state.sparseq1.m = n;
                state.sparseq1.n = n;
                ablasf.iallocv(n+1, ref state.sparseq1.ridx, _params);
                ablasf.iallocv(n, ref state.sparseq1.idx, _params);
                ablasf.rallocv(n, ref state.sparseq1.vals, _params);
                for(i=0; i<=n-1; i++)
                {
                    state.sparseq1.ridx[i] = i;
                    state.sparseq1.idx[i] = i;
                    state.sparseq1.vals[i] = 0.0;
                }
                state.sparseq1.ridx[n] = n;
                sparse.sparsecreatecrsinplace(state.sparseq1, _params);
                bflg = true;
            }
            alglib.ap.assert(bflg, "GQPIPM: 896235 failed");
            alglib.ap.assert((double)(eps)>=(double)(0), "QPIPM: integrity check 9756 failed");
            state.eps = apserv.coalesce(eps, 10*Math.Sqrt(math.machineepsilon), _params);
            state.maxits = maxits;
            state.pctype = 0;
            state.repterminationtype = 0;
            state.repiterationscount = 0;
            state.dolaconictrace = ap.istraceenabled("GENIPM.LACONIC", _params);
            state.dotrace = ap.istraceenabled("GENIPM", _params) && !state.dolaconictrace;
        }


        /*************************************************************************
        Set linear and quadratic terms

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void gqpipmsetquadraticlinear(gqpipmstate state,
            double[,] denseh,
            sparse.sparsematrix sparseh,
            int hkind,
            double[] c,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;

            if( state.algomode==amdense )
            {
                lpqpserv.quadraticlinearconverttodenseltr(c, state.n, denseh, sparseh, hkind, false, ref state.c, ref state.denseq, _params);
                for(i=0; i<=state.n-1; i++)
                {
                    for(j=0; j<=i-1; j++)
                    {
                        state.denseq[j,i] = state.denseq[i,j];
                    }
                }
                for(i=state.n-1; i>=0; i--)
                {
                    if( (double)(ablasf.rmaxabsr(state.n, state.denseq, i, _params))>(double)(0) )
                    {
                        state.nq = Math.Max(state.nq, i+1);
                        break;
                    }
                }
            }
            else
            {
                alglib.ap.assert(state.algomode==amsparse || state.algomode==amhybrid, "QPGIPM: integrity check 945236 failed");
                alglib.ap.assert(hkind==0 || hkind==1, "QPGIPM: integrity check 5022 failed");
                ablasf.rcopyv(state.n, c, state.c, _params);
                if( hkind==0 )
                {
                    sparse.sparsecreatecrsfromdensebuf(denseh, state.n, state.n, state.sparseq1, _params);
                }
                if( hkind==1 )
                {
                    sparse.sparsecopytocrsbuf(sparseh, state.sparseq1, _params);
                }
                ablasf.rsetallocv(state.n, 0.0, ref state.tmp0, _params);
                for(i=0; i<=state.n-1; i++)
                {
                    j0 = state.sparseq1.ridx[i];
                    j1 = state.sparseq1.uidx[i]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        if( (double)(state.sparseq1.vals[jj])!=(double)(0) )
                        {
                            state.tmp0[i] = 1;
                            state.tmp0[state.sparseq1.idx[jj]] = 1;
                        }
                    }
                }
                for(i=state.n-1; i>=0; i--)
                {
                    if( (double)(state.tmp0[i])!=(double)(0) )
                    {
                        state.nq = Math.Max(state.nq, i+1);
                        break;
                    }
                }
            }
        }


        /*************************************************************************
        Set linear constraints

        INPUT PARAMETERS:
            State               -   instance initialized with one of the initialization
                                    functions
            SparseA             -   sparse constraint matrix, CRS format
            CL, CU              -   lower and upper bounds for constraints
                                    -INF <= CL[I] <= CU[I] <= +INF.
            XQC                 -   quadratic constraints
            XCC                 -   conic constraints

          -- ALGLIB --
             Copyright 25.05.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void gqpipmsetconstraints(gqpipmstate state,
            sparse.sparsematrix sparsea,
            double[] cl,
            double[] cu,
            int m,
            opts.xquadraticconstraints xqc,
            opts.xconicconstraints xcc,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            opts.xquadraticconstraint qci = null;

            n = state.n;
            alglib.ap.assert(m>=0, "GQPIPMSetConstraints: M<0");
            alglib.ap.assert(m==0 || ((sparsea.matrixtype==1 && sparsea.m==m) && sparsea.n==n), "GQPIPMSetConstraints: constraint matrix has incorrect size");
            alglib.ap.assert(alglib.ap.len(cl)>=m, "GQPIPMSetConstraints: CL is too short!");
            alglib.ap.assert(alglib.ap.len(cu)>=m, "GQPIPMSetConstraints: CU is too short!");
            state.mlc = m;
            if( m>0 )
            {
                sparse.sparsecopytocrsbuf(sparsea, state.sparselc, _params);
                ablasf.rallocv(m, ref state.lcbndl, _params);
                ablasf.rallocv(m, ref state.lcbndu, _params);
                for(i=0; i<=m-1; i++)
                {
                    alglib.ap.assert(math.isfinite(cl[i]) || Double.IsNegativeInfinity(cl[i]), "GQPIPMSetConstraints: CL is not finite number or -INF");
                    alglib.ap.assert(math.isfinite(cu[i]) || Double.IsPositiveInfinity(cu[i]), "GQPIPMSetConstraints: CU is not finite number or +INF");
                    state.lcbndl[i] = cl[i];
                    state.lcbndu[i] = cu[i];
                }
            }
            state.mqc = opts.xqcgetcount(xqc, _params);
            opts.xqccopy(xqc, state.xqc, _params);
            for(i=0; i<=state.mqc-1; i++)
            {
                state.xqc.constraints.get(i, ref qci);
                for(j=0; j<=qci.nvars-1; j++)
                {
                    j0 = qci.lowerq.ridx[j];
                    j1 = qci.lowerq.didx[j]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        state.nq = Math.Max(state.nq, qci.varidx[j]);
                        state.nq = Math.Max(state.nq, qci.varidx[qci.lowerq.idx[jj]]);
                    }
                }
            }
            state.msocc = optserv.xccgetcount(xcc, _params);
            optserv.xcccopy(xcc, state.xcc, _params);
        }


        /*************************************************************************
        Set quasi-Newton parameters

        INPUT PARAMETERS:
            State               -   instance initialized with one of the initialization
                                    functions
            MemLen              -   memory length
            MaxOffdiag          -   threshold for moving quadratic terms to a
                                    quasi-Newton approximation

          -- ALGLIB --
             Copyright 25.05.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void gqpipmsetquasinewtonparams(gqpipmstate state,
            int memlen,
            int maxoffdiag,
            alglib.xparams _params)
        {
            alglib.ap.assert(memlen>=0, "GQPIPMSetQuasiNewtonParams: MemLen<0");
            alglib.ap.assert(maxoffdiag>=0, "GQPIPMSetQuasiNewtonParams: MaxOffdiag<0");
            state.hessmemlen = memlen;
            state.hessmaxoffdiag = maxoffdiag;
        }


        /*************************************************************************
        Solve QP problem.

        INPUT PARAMETERS:
            State               -   solver instance
            
        OUTPUT PARAMETERS:
            XS                  -   array[N], solution
            LagBC               -   array[N], Lagrange multipliers for box constraints
            LagLC               -   array[MLC], Lagrange multipliers for linear constraints
            LagQC               -   array[MQC], Lagrange multipliers for quadratic constraints
            TerminationType     -   completion code, positive values for success,
                                    negative for failures (XS constrains best point
                                    found so far):
                                    * -2    the task is either unbounded or infeasible;
                                            the IPM solver has difficulty distinguishing between these two.
                                    * +1    stopping criteria are met
                                    * +7    stopping criteria are too stringent

        RESULT:

        This function ALWAYS returns something  meaningful in XS, LagBC, LagLC - 
        either solution or the best point so far, even for negative TerminationType.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void gqpipmoptimize(gqpipmstate state,
            ref double[] xs,
            ref double[] lagbc,
            ref double[] laglc,
            ref double[] lagqc,
            ref int terminationtype,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            int j = 0;
            int nnz = 0;
            double initprimdual = 0;
            int mlc = 0;
            int mtotal = 0;
            int offslast = 0;
            int offslc = 0;
            int offsqc = 0;
            int offscc = 0;
            int offsec = 0;
            bool remembered = new bool();
            bool factorized = new bool();
            bool donecc = new bool();
            opts.xquadraticconstraint qci = null;
            opts.xconicconstraint cci = null;

            terminationtype = 0;

            n = state.n;
            mlc = state.mlc;
            offslast = 0;
            mtotal = 0;
            state.nrealpool.alloc_double(n);
            ablasf.rsetallocv(1, 1.0, ref state.fscales, _params);
            offslc = offslast;
            offslast = offslast+mlc;
            for(i=0; i<=mlc-1; i++)
            {
                ablasf.rgrowv(mtotal+1, ref state.totalnl, _params);
                ablasf.rgrowv(mtotal+1, ref state.totalnu, _params);
                state.totalnl[mtotal] = state.lcbndl[i];
                state.totalnu[mtotal] = state.lcbndu[i];
                ablasf.rgrowv(1+mtotal+1, ref state.fscales, _params);
                state.fscales[1+mtotal] = 1.0;
                mtotal = mtotal+1;
            }
            offsec = offslast;
            offslast = offsec+state.fixedvarscnt;
            for(i=0; i<=n-1; i++)
            {
                if( state.isfixed[i] )
                {
                    ablasf.rgrowv(mtotal+1, ref state.totalnl, _params);
                    ablasf.rgrowv(mtotal+1, ref state.totalnu, _params);
                    state.totalnl[mtotal] = state.wrkbndl[i];
                    state.totalnu[mtotal] = state.wrkbndu[i];
                    ablasf.rgrowv(1+mtotal+1, ref state.fscales, _params);
                    state.fscales[1+mtotal] = 1.0;
                    state.wrkbndl[i] = Double.NegativeInfinity;
                    state.wrkbndu[i] = Double.PositiveInfinity;
                    mtotal = mtotal+1;
                }
            }
            offsqc = offslast;
            offslast = offslast+state.mqc;
            for(i=0; i<=state.mqc-1; i++)
            {
                ablasf.rgrowv(mtotal+1, ref state.totalnl, _params);
                ablasf.rgrowv(mtotal+1, ref state.totalnu, _params);
                state.xqc.constraints.get(i, ref qci);
                state.totalnl[mtotal] = qci.cl;
                state.totalnu[mtotal] = qci.cu;
                ablasf.rgrowv(1+mtotal+1, ref state.fscales, _params);
                state.fscales[1+mtotal] = 1.0;
                mtotal = mtotal+1;
            }
            offscc = offslast;
            offslast = offslast+state.msocc;
            for(i=0; i<=state.msocc-1; i++)
            {
                ablasf.rgrowv(mtotal+1, ref state.totalnl, _params);
                ablasf.rgrowv(mtotal+1, ref state.totalnu, _params);
                state.xcc.constraints.get(i, ref cci);
                alglib.ap.assert(cci.conetype>=0, "GQPIPM: non-canonic cone constraints are provided");
                donecc = false;
                if( cci.conetype==optserv.xccprimitiveconetype(_params) )
                {
                    state.totalnl[mtotal] = Double.NegativeInfinity;
                    state.totalnu[mtotal] = 0.0;
                    donecc = true;
                }
                if( cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                {
                    state.totalnl[mtotal] = Double.NegativeInfinity;
                    state.totalnu[mtotal] = 0.0;
                    donecc = true;
                }
                alglib.ap.assert(donecc, "GQPIPM: unexpected cone type");
                ablasf.rgrowv(1+mtotal+1, ref state.fscales, _params);
                state.fscales[1+mtotal] = 1.0;
                mtotal = mtotal+1;
            }
            alglib.ap.assert(mtotal==offslast, "GQPIPM: integrity check 5535 failed");
            ablasf.bsetallocv(1+mtotal, false, ref state.doqnupdates, _params);
            if( state.algomode==amhybrid )
            {
                nnz = 0;
                for(i=0; i<=n-1; i++)
                {
                    nnz = nnz+(state.sparseq1.didx[i]-state.sparseq1.ridx[i]);
                }
                state.doqnupdates[0] = nnz>state.hessmaxoffdiag;
                for(i=0; i<=state.mqc-1; i++)
                {
                    state.xqc.constraints.get(i, ref qci);
                    nnz = 0;
                    for(j=0; j<=qci.nvars-1; j++)
                    {
                        nnz = nnz+(qci.lowerq.didx[j]-qci.lowerq.ridx[j]);
                    }
                    state.doqnupdates[1+offsqc+i] = nnz>state.hessmaxoffdiag;
                }
            }
            initializehessjac(state, offslc, offsqc, offsec, offscc, mtotal, _params);
            ablasf.rsetallocv(n, 0.0, ref xs, _params);
            ablasf.rsetallocv(n, 0.0, ref lagbc, _params);
            ablasf.rsetallocv(state.mlc, 0.0, ref laglc, _params);
            ablasf.rsetallocv(state.mqc, 0.0, ref lagqc, _params);
            initprimdual = gipm.gipmgetinitprimdual(_params);
            for(i=0; i<=n-1; i++)
            {
                if( !math.isfinite(state.wrkbndl[i]) && !math.isfinite(state.wrkbndu[i]) )
                {
                    continue;
                }
                if( math.isfinite(state.wrkbndl[i]) && !math.isfinite(state.wrkbndu[i]) )
                {
                    state.x0[i] = Math.Max(state.x0[i], state.wrkbndl[i]+initprimdual);
                    continue;
                }
                if( math.isfinite(state.wrkbndu[i]) && !math.isfinite(state.wrkbndl[i]) )
                {
                    state.x0[i] = Math.Min(state.x0[i], state.wrkbndu[i]-initprimdual);
                    continue;
                }
                if( (double)(state.wrkbndu[i]-state.wrkbndl[i])>(double)(2*initprimdual) )
                {
                    state.x0[i] = Math.Max(state.x0[i], state.wrkbndl[i]+initprimdual);
                    state.x0[i] = Math.Min(state.x0[i], state.wrkbndu[i]-initprimdual);
                    continue;
                }
                alglib.ap.assert((double)(state.wrkbndl[i])<(double)(state.wrkbndu[i]), "GQPIPM: integrity check 609424 failed");
                state.x0[i] = 0.5*(state.wrkbndl[i]+state.wrkbndu[i]);
                alglib.ap.assert((double)(state.x0[i])>(double)(state.wrkbndl[i]), "GQPIPM: integrity check 609425 failed");
                alglib.ap.assert((double)(state.x0[i])<(double)(state.wrkbndu[i]), "GQPIPM: integrity check 609426 failed");
            }
            for(i=0; i<=state.msocc-1; i++)
            {
                state.xcc.constraints.get(i, ref cci);
                if( cci.nvars==0 )
                {
                    continue;
                }
                donecc = false;
                if( cci.conetype==optserv.xccprimitiveconetype(_params) )
                {
                    donecc = true;
                }
                if( cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                {
                    donecc = true;
                }
                alglib.ap.assert(donecc, "GQPIPM: integrity check 876620 failed");
            }
            alglib.ap.assert(alglib.ap.len(state.fscales)>=1+mtotal, "GQPIPM: integrity check 8248 failed");
            gipm.gipminitbuf(state.wrkbndl, state.wrkbndu, state.x0, n, state.totalnl, state.totalnu, mtotal-0*state.msocc, 0*state.msocc, state.fscales, state.doqnupdates, state.eps, state.maxits, state.algomode==amhybrid, state.solver, _params);
            if( state.dotrace )
            {
                alglib.ap.trace("\n----- printing additional problem info -------------------------------------------------------------\n");
                if( (state.cvxobjective!=0 || state.cvxqc!=0) || state.cvxcc!=0 )
                {
                    alglib.ap.trace("> analyzing problem convexity:\n");
                    if( state.cvxobjective>0 )
                    {
                        alglib.ap.trace(">> objective = convex\n");
                    }
                    if( state.cvxobjective<0 )
                    {
                        alglib.ap.trace(">> objective = non-convex\n");
                    }
                    if( state.cvxobjective==0 )
                    {
                        alglib.ap.trace(">> objective = convexity is unknown\n");
                    }
                    if( opts.xqcgetcount(state.xqc, _params)>0 )
                    {
                        if( state.cvxqc>0 )
                        {
                            alglib.ap.trace(">> quadratic constraints = all convex\n");
                        }
                        if( state.cvxqc<0 )
                        {
                            alglib.ap.trace(">> quadratic constraints = non-convex (at least one)\n");
                        }
                        if( state.cvxqc==0 )
                        {
                            alglib.ap.trace(">> quadratic constraints = convexity is unknown\n");
                        }
                    }
                    else
                    {
                        alglib.ap.trace(">> no quadratic constraints\n");
                    }
                    if( optserv.xccgetcount(state.xcc, _params)>0 )
                    {
                        if( state.cvxcc>0 )
                        {
                            alglib.ap.trace(">> conic constraints = all convex\n");
                        }
                        if( state.cvxcc<0 )
                        {
                            alglib.ap.trace(">> conic constraints = non-convex (at least one)\n");
                        }
                        if( state.cvxcc==0 )
                        {
                            alglib.ap.trace(">> conic constraints = convexity is unknown\n");
                        }
                    }
                    else
                    {
                        alglib.ap.trace(">> no conic constraints\n");
                    }
                }
                alglib.ap.trace("\n");
            }
            remembered = false;
            factorized = false;
            while( gipm.gipmiteration(state.solver, false, _params) )
            {
                if( state.solver.requesttype==1 )
                {
                    handlecomputeandremember(state, offslc, offsqc, offsec, offscc, mtotal, ref remembered, ref factorized, _params);
                    continue;
                }
                if( state.solver.requesttype==1001 )
                {
                    handlefactorize(state, mtotal, ref remembered, ref factorized, _params);
                    continue;
                }
                if( state.solver.requesttype==1002 )
                {
                    handlesolve(state, mtotal, ref remembered, ref factorized, _params);
                    continue;
                }
                if( state.solver.requesttype==1003 )
                {
                    handlemv(state, offslc, offsqc, offsec, offscc, mtotal, ref remembered, ref factorized, _params);
                    continue;
                }
                if( state.solver.requesttype==1004 )
                {
                    if( state.algomode==amhybrid && state.nq>0 )
                    {
                        ablasf.rallocv(n, ref state.tmp0, _params);
                        ablasf.rallocv(n, ref state.tmp1, _params);
                        ablasf.rallocv(n, ref state.tmp2, _params);
                        ablasf.rallocv(n, ref state.tmp3, _params);
                        ablasf.rcopyvx(n, state.solver.querydata, 0*n, state.tmp0, 0, _params);
                        ablasf.rcopyvx(n, state.solver.querydata, 1*n, state.tmp1, 0, _params);
                        ablasf.rcopyvx(n, state.solver.querydata, 2*n, state.tmp2, 0, _params);
                        ablasf.rcopyvx(n, state.solver.querydata, 3*n, state.tmp3, 0, _params);
                        optserv.hessianupdatev2(state.hess, state.tmp0, state.tmp2, state.tmp1, state.tmp3, 2, false, state.dotrace, 2, _params);
                        optserv.hessianmultiplyby(state.hess, 0.95, _params);
                    }
                    continue;
                }
                alglib.ap.assert(false, "GQPIPM: request not implemented");
            }
            gipm.gipmresults(state.solver, ref xs, ref lagbc, ref state.tmp0, ref terminationtype, _params);
            state.repiterationscount = state.solver.repiterationscount;
            for(i=0; i<=state.fixedvarscnt-1; i++)
            {
                lagbc[state.fixedidx[i]] = state.tmp0[offsec+i];
            }
            for(i=0; i<=mlc-1; i++)
            {
                laglc[i] = state.tmp0[offslc+i];
            }
            for(i=0; i<=state.mqc-1; i++)
            {
                lagqc[i] = state.tmp0[offsqc+i];
            }
            ablasf.rmergemaxv(n, state.finiterawbndl, xs, _params);
            ablasf.rmergeminv(n, state.finiterawbndu, xs, _params);
        }


        /*************************************************************************
        Appends a lower triangular sparse matrix to the list of row/column/id/value
        elements. Grows list as necessary, returns modified list length.

        If VarIdx[] is unordered, i.e. VarIdx[i0]>VarIdx[i1] for some i0<i1, then
        this function correctly reorders mapped indexes of Q so that they correspond
        to the lower triangle of a matrix.

          -- ALGLIB --
             Copyright 25.10.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void appendtorckv(int[] varidx,
            sparse.sparsematrix q,
            int nv,
            int id,
            ref int[] hr,
            ref int[] hc,
            ref int[] hk,
            ref double[] hv,
            ref int hcnt,
            alglib.xparams _params)
        {
            int tgt0 = 0;
            int j0 = 0;
            int j1 = 0;
            int k0 = 0;
            int k1 = 0;
            int jj = 0;
            int w = 0;
            double v = 0;

            if( nv==0 )
            {
                return;
            }
            for(tgt0=0; tgt0<=nv-1; tgt0++)
            {
                j0 = q.ridx[tgt0];
                j1 = q.didx[tgt0]-1;
                w = j1-j0+1+1;
                ablasf.igrowv(hcnt+w, ref hr, _params);
                ablasf.igrowv(hcnt+w, ref hc, _params);
                ablasf.igrowv(hcnt+w, ref hk, _params);
                ablasf.rgrowv(hcnt+w, ref hv, _params);
                for(jj=j0; jj<=j1; jj++)
                {
                    k0 = varidx[tgt0];
                    k1 = varidx[q.idx[jj]];
                    if( k0>=k1 )
                    {
                        hr[hcnt] = k0;
                        hc[hcnt] = k1;
                    }
                    else
                    {
                        hr[hcnt] = k1;
                        hc[hcnt] = k0;
                    }
                    hk[hcnt] = id;
                    hv[hcnt] = q.vals[jj];
                    hcnt = hcnt+1;
                }
                v = 0.0;
                if( j1+1<q.uidx[tgt0] )
                {
                    v = q.vals[j1+1];
                }
                hr[hcnt] = varidx[tgt0];
                hc[hcnt] = varidx[tgt0];
                hk[hcnt] = id;
                hv[hcnt] = v;
                hcnt = hcnt+1;
            }
        }


        /*************************************************************************
        Prepares sparse Hessian, dependencies of its elements on Lagrange multipliers,
        SPSymmAnalyze(), etc.

          -- ALGLIB --
             Copyright 25.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void initializehessjac(gqpipmstate state,
            int offslc,
            int offsqc,
            int offsec,
            int offscc,
            int mtotal,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            int w = 0;
            int n = 0;
            int mlc = 0;
            int offs = 0;
            int dstrow = 0;
            int cidx = 0;
            int kpow = 0;
            double v = 0;
            int j0 = 0;
            int j1 = 0;
            int jj = 0;
            int jprev = 0;
            int nv = 0;
            int tgt0 = 0;
            int tgt1 = 0;
            int tgtx = 0;
            opts.xquadraticconstraint qci = null;
            opts.xconicconstraint cci = null;
            gqpsparseconichessian chi = null;
            gqpoptionaldense opti = null;
            int hcnt = 0;
            int dstidx = 0;
            int srcidx = 0;
            int srcrange1 = 0;
            int facttype = 0;

            n = state.n;
            mlc = state.mlc;
            ablasf.iallocv(n, ref state.tmpi, _params);
            state.xchsparse.clear();
            for(i=0; i<=state.msocc-1; i++)
            {
                state.xcc.constraints.get(i, ref cci);
                chi = new gqpsparseconichessian();
                state.xchsparse.append(chi);
                nv = cci.nvars;
                if( nv==0 )
                {
                    continue;
                }
                if( cci.conetype==optserv.xccprimitiveconetype(_params) )
                {
                    chi.lowerh.n = nv;
                    chi.lowerh.m = nv;
                    ablasf.iallocv(nv+1, ref chi.lowerh.ridx, _params);
                    ablasf.iallocv(2*(nv-1)+1, ref chi.lowerh.idx, _params);
                    ablasf.rallocv(2*(nv-1)+1, ref chi.lowerh.vals, _params);
                    offs = 0;
                    for(j=0; j<=nv-2; j++)
                    {
                        chi.lowerh.ridx[j] = offs;
                        chi.lowerh.idx[offs] = j;
                        chi.lowerh.vals[offs] = 0.0;
                        offs = offs+1;
                    }
                    chi.lowerh.ridx[nv-1] = offs;
                    for(j=0; j<=nv-1; j++)
                    {
                        chi.lowerh.idx[offs] = j;
                        chi.lowerh.vals[offs] = 0.0;
                        offs = offs+1;
                    }
                    chi.lowerh.ridx[nv] = offs;
                    alglib.ap.assert(offs==2*nv-1, "GQPIPM: integrity check 136309 failed");
                    sparse.sparsecreatecrsinplace(chi.lowerh, _params);
                    ablasf.icopyv(nv, cci.varidx, state.tmpi, _params);
                    ablasf.iallocv(nv, ref chi.ordervaridx, _params);
                    for(j=0; j<=nv-1; j++)
                    {
                        chi.ordervaridx[j] = j;
                    }
                    tsort.tagsortmiddleii(ref state.tmpi, ref chi.ordervaridx, 0, nv, _params);
                    continue;
                }
                if( cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                {
                    alglib.ap.assert(state.pctype==0, "GQPIPM: integrity check 446815 failed");
                    kpow = cci.kpow;
                    chi.lowerh.n = nv;
                    chi.lowerh.m = nv;
                    ablasf.iallocv(nv+1, ref chi.lowerh.ridx, _params);
                    ablasf.iallocv(nv+kpow*nv, ref chi.lowerh.idx, _params);
                    ablasf.rallocv(nv+kpow*nv, ref chi.lowerh.vals, _params);
                    offs = 0;
                    for(j=0; j<=nv-kpow-1; j++)
                    {
                        chi.lowerh.ridx[j] = offs;
                        chi.lowerh.idx[offs] = j;
                        chi.lowerh.vals[offs] = 0.0;
                        offs = offs+1;
                    }
                    for(j=nv-kpow; j<=nv-1; j++)
                    {
                        chi.lowerh.ridx[j] = offs;
                        for(j1=0; j1<=j; j1++)
                        {
                            chi.lowerh.idx[offs] = j1;
                            chi.lowerh.vals[offs] = 0.0;
                            offs = offs+1;
                        }
                    }
                    chi.lowerh.ridx[nv] = offs;
                    sparse.sparsecreatecrsinplace(chi.lowerh, _params);
                    ablasf.icopyv(nv, cci.varidx, state.tmpi, _params);
                    ablasf.iallocv(nv, ref chi.ordervaridx, _params);
                    for(j=0; j<=nv-1; j++)
                    {
                        chi.ordervaridx[j] = j;
                    }
                    tsort.tagsortmiddleii(ref state.tmpi, ref chi.ordervaridx, 0, nv, _params);
                    continue;
                }
                alglib.ap.assert(false, "GQPIPM: integrity check 140309 failed");
            }
            alglib.ap.assert(state.xcc.constraints.getlength()==state.xchsparse.getlength(), "GQPIPM: integrity check 142310 failed");
            state.curjac.m = mtotal;
            state.curjac.n = n;
            ablasf.iallocv(mtotal+1, ref state.curjac.ridx, _params);
            state.curjac.ridx[0] = 0;
            dstrow = 0;
            alglib.ap.assert(dstrow==offslc, "GQPIPM: integrity check 2900 failed");
            if( mlc>0 )
            {
                k = state.sparselc.ridx[mlc];
                ablasf.igrowv(state.curjac.ridx[dstrow]+k, ref state.curjac.idx, _params);
                ablasf.rgrowv(state.curjac.ridx[dstrow]+k, ref state.curjac.vals, _params);
                for(i=0; i<=mlc-1; i++)
                {
                    k = state.sparselc.ridx[i+1]-state.sparselc.ridx[i];
                    ablasf.icopyvx(k, state.sparselc.idx, state.sparselc.ridx[i], state.curjac.idx, state.curjac.ridx[dstrow], _params);
                    ablasf.rsetvx(k, 0.0, state.curjac.vals, state.curjac.ridx[dstrow], _params);
                    state.curjac.ridx[dstrow+1] = state.curjac.ridx[dstrow]+k;
                    dstrow = dstrow+1;
                }
            }
            alglib.ap.assert(dstrow==offsec, "GQPIPM: integrity check 945839 failed");
            ablasf.igrowv(state.curjac.ridx[dstrow]+state.fixedvarscnt, ref state.curjac.idx, _params);
            ablasf.rgrowv(state.curjac.ridx[dstrow]+state.fixedvarscnt, ref state.curjac.vals, _params);
            for(i=0; i<=state.fixedvarscnt-1; i++)
            {
                k = state.curjac.ridx[dstrow];
                state.curjac.idx[k] = state.fixedidx[i];
                state.curjac.vals[k] = 0.0;
                state.curjac.ridx[dstrow+1] = k+1;
                dstrow = dstrow+1;
            }
            alglib.ap.assert(dstrow==offsqc, "GQPIPM: integrity check 949844 failed");
            for(i=0; i<=state.mqc-1; i++)
            {
                state.xqc.constraints.get(i, ref qci);
                ablasf.igrowv(state.curjac.ridx[dstrow]+qci.nvars, ref state.curjac.idx, _params);
                ablasf.rgrowv(state.curjac.ridx[dstrow]+qci.nvars, ref state.curjac.vals, _params);
                ablasf.icopyvx(qci.nvars, qci.varidx, 0, state.curjac.idx, state.curjac.ridx[dstrow], _params);
                ablasf.rsetvx(qci.nvars, 0.0, state.curjac.vals, state.curjac.ridx[dstrow], _params);
                state.curjac.ridx[dstrow+1] = state.curjac.ridx[dstrow]+qci.nvars;
                dstrow = dstrow+1;
            }
            for(i=0; i<=state.msocc-1; i++)
            {
                state.xcc.constraints.get(i, ref cci);
                ablasf.igrowv(state.curjac.ridx[dstrow]+cci.nvars, ref state.curjac.idx, _params);
                ablasf.rgrowv(state.curjac.ridx[dstrow]+cci.nvars, ref state.curjac.vals, _params);
                ablasf.icopyvx(cci.nvars, cci.varidx, 0, state.curjac.idx, state.curjac.ridx[dstrow], _params);
                tsort.tagsortmiddlei(ref state.curjac.idx, state.curjac.ridx[dstrow], cci.nvars, _params);
                ablasf.rsetvx(cci.nvars, 0.0, state.curjac.vals, state.curjac.ridx[dstrow], _params);
                state.curjac.ridx[dstrow+1] = state.curjac.ridx[dstrow]+cci.nvars;
                dstrow = dstrow+1;
            }
            alglib.ap.assert(dstrow==mtotal, "GQPIPM: integrity check 993315 failed");
            if( mtotal>0 )
            {
                sparse.sparsecreatecrsinplace(state.curjac, _params);
            }
            if( state.algomode==amdense )
            {
                ablasf.rallocm(n, n, ref state.currenth, _params);
                return;
            }
            alglib.ap.assert(state.algomode==amsparse || state.algomode==amhybrid, "QPGIPM: 654249 failed");
            if( state.algomode==amhybrid && state.nq>0 )
            {
                state.hessmemlen = Math.Min(state.nq, apserv.icoalesce(state.hessmemlen, xbfgsdefaultmemlen, _params));
                optserv.hessianinitlowranksr1(state.hess, state.nq, state.hessmemlen, Math.Max(state.eps, Math.Sqrt(math.machineepsilon)), xbfgsmaxhess, _params);
            }
            hcnt = 0;
            if( state.algomode==amhybrid && state.doqnupdates[0] )
            {
                ablasf.igrowv(hcnt+n, ref state.tmphr, _params);
                ablasf.igrowv(hcnt+n, ref state.tmphc, _params);
                ablasf.igrowv(hcnt+n, ref state.tmphk, _params);
                ablasf.rgrowv(hcnt+n, ref state.tmphv, _params);
                for(i=0; i<=n-1; i++)
                {
                    state.tmphr[hcnt] = i;
                    state.tmphc[hcnt] = i;
                    state.tmphk[hcnt] = mtotal;
                    state.tmphv[hcnt] = 0.0;
                    hcnt = hcnt+1;
                }
            }
            else
            {
                for(i=0; i<=n-1; i++)
                {
                    j0 = state.sparseq1.ridx[i];
                    j1 = state.sparseq1.didx[i]-1;
                    w = j1-j0+1+1;
                    ablasf.igrowv(hcnt+w, ref state.tmphr, _params);
                    ablasf.igrowv(hcnt+w, ref state.tmphc, _params);
                    ablasf.igrowv(hcnt+w, ref state.tmphk, _params);
                    ablasf.rgrowv(hcnt+w, ref state.tmphv, _params);
                    for(jj=j0; jj<=j1; jj++)
                    {
                        state.tmphr[hcnt] = i;
                        state.tmphc[hcnt] = state.sparseq1.idx[jj];
                        state.tmphk[hcnt] = mtotal;
                        state.tmphv[hcnt] = state.sparseq1.vals[jj];
                        hcnt = hcnt+1;
                    }
                    v = 0.0;
                    if( j1+1<state.sparseq1.uidx[i] )
                    {
                        v = state.sparseq1.vals[j1+1];
                    }
                    state.tmphr[hcnt] = i;
                    state.tmphc[hcnt] = i;
                    state.tmphk[hcnt] = mtotal;
                    state.tmphv[hcnt] = v;
                    hcnt = hcnt+1;
                }
            }
            for(i=0; i<=state.mqc-1; i++)
            {
                if( state.algomode!=amhybrid || !state.doqnupdates[1+offsqc+i] )
                {
                    state.xqc.constraints.get(i, ref qci);
                    if( qci.nvars==0 )
                    {
                        continue;
                    }
                    appendtorckv(qci.varidx, qci.lowerq, qci.nvars, offsqc+i, ref state.tmphr, ref state.tmphc, ref state.tmphk, ref state.tmphv, ref hcnt, _params);
                }
            }
            for(i=0; i<=state.msocc-1; i++)
            {
                alglib.ap.assert(state.algomode!=amhybrid || !state.doqnupdates[1+offscc+i], "GQPIPM: integrity check 832348 failed");
                state.xcc.constraints.get(i, ref cci);
                state.xchsparse.get(i, ref chi);
                nv = cci.nvars;
                if( nv==0 )
                {
                    continue;
                }
                appendtorckv(cci.varidx, chi.lowerh, nv, offscc+i, ref state.tmphr, ref state.tmphc, ref state.tmphk, ref state.tmphv, ref hcnt, _params);
            }
            alglib.ap.assert(state.xcc.constraints.getlength()==state.xchsparse.getlength(), "GQPIPM: integrity check 142310 failed");
            alglib.ap.assert(hcnt>=n, "GQPIPN: integrity check 937222 failed");
            sortrck(state.tmphr, state.tmphc, state.tmphk, state.tmphv, hcnt, ref state.tmphr2, ref state.tmphc2, ref state.tmphk2, ref state.tmphv2, _params);
            state.sparseh.m = n;
            state.sparseh.n = n;
            ablasf.iallocv(n+1, ref state.sparseh.ridx, _params);
            state.sparseh.ridx[0] = 0;
            state.sparsehdeps.m = 0;
            state.sparsehdeps.n = mtotal+1;
            ablasf.iallocv(1, ref state.sparsehdeps.ridx, _params);
            state.sparsehdeps.ridx[0] = 0;
            srcidx = 0;
            dstidx = 0;
            for(dstrow=0; dstrow<=n-1; dstrow++)
            {
                alglib.ap.assert(state.tmphr[srcidx]==dstrow, "GQPIPM: integrity check 951223 failed");
                dstidx = state.sparseh.ridx[dstrow];
                jprev = -1;
                while( srcidx<hcnt && state.tmphr[srcidx]==dstrow )
                {
                    j = state.tmphc[srcidx];
                    if( j<=jprev || j>dstrow )
                    {
                        alglib.ap.assert(false, "GQPIPM: integrity check 958230 failed");
                    }
                    srcrange1 = srcidx;
                    offs = state.sparsehdeps.ridx[state.sparsehdeps.m];
                    while( (srcrange1<hcnt && state.tmphr[srcrange1]==dstrow) && state.tmphc[srcrange1]==j )
                    {
                        ablasf.igrowv(offs+1, ref state.sparsehdeps.idx, _params);
                        ablasf.rgrowv(offs+1, ref state.sparsehdeps.vals, _params);
                        state.sparsehdeps.idx[offs] = state.tmphk[srcrange1];
                        state.sparsehdeps.vals[offs] = state.tmphv[srcrange1];
                        srcrange1 = srcrange1+1;
                        offs = offs+1;
                    }
                    state.sparsehdeps.m = state.sparsehdeps.m+1;
                    ablasf.igrowv(state.sparsehdeps.m+1, ref state.sparsehdeps.ridx, _params);
                    state.sparsehdeps.ridx[state.sparsehdeps.m] = offs;
                    ablasf.igrowv(dstidx+1, ref state.sparseh.idx, _params);
                    ablasf.rgrowv(dstidx+1, ref state.sparseh.vals, _params);
                    state.sparseh.idx[dstidx] = j;
                    state.sparseh.vals[dstidx] = 0.0;
                    dstidx = dstidx+1;
                    srcidx = srcrange1;
                    jprev = j;
                }
                state.sparseh.ridx[dstrow+1] = dstidx;
            }
            sparse.sparsecreatecrsinplace(state.sparseh, _params);
            sparse.sparsecreatecrsinplace(state.sparsehdeps, _params);
            for(cidx=0; cidx<=state.msocc-1; cidx++)
            {
                alglib.ap.assert(state.algomode!=amhybrid || !state.doqnupdates[1+offscc+cidx], "GQPIPM: integrity check 912350 failed");
                state.xcc.constraints.get(cidx, ref cci);
                state.xchsparse.get(cidx, ref chi);
                nv = cci.nvars;
                if( nv==0 )
                {
                    continue;
                }
                ablasf.iallocv(chi.lowerh.ridx[nv], ref chi.injectionoffsets, _params);
                for(i=0; i<=nv-1; i++)
                {
                    j0 = chi.lowerh.ridx[i];
                    j1 = chi.lowerh.ridx[i+1]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        tgt0 = cci.varidx[i];
                        tgt1 = cci.varidx[chi.lowerh.idx[jj]];
                        if( tgt1>tgt0 )
                        {
                            tgtx = tgt0;
                            tgt0 = tgt1;
                            tgt1 = tgtx;
                        }
                        offs = apserv.ibinarysearchexisting(state.sparseh.idx, state.sparseh.ridx[tgt0], state.sparseh.uidx[tgt0], tgt1, _params);
                        chi.injectionoffsets[jj] = apserv.ibinarysearchexisting(state.sparsehdeps.idx, state.sparsehdeps.ridx[offs], state.sparsehdeps.ridx[offs+1], offscc+cidx, _params);
                    }
                }
            }
            alglib.ap.assert(state.algomode==amhybrid || state.hessmemlen==0, "QPGIPM: 838258 failed");
            state.sparsesys.m = n+mtotal+2*state.hessmemlen;
            state.sparsesys.n = state.sparsesys.m;
            ablasf.iallocv(state.sparsesys.m+1, ref state.sparsesys.ridx, _params);
            state.sparsesys.ridx[0] = 0;
            offs = 0;
            for(i=0; i<=n-1; i++)
            {
                ablasf.igrowv(offs+n, ref state.sparsesys.idx, _params);
                ablasf.rgrowv(offs+n, ref state.sparsesys.vals, _params);
                j0 = state.sparseh.ridx[i];
                j1 = state.sparseh.didx[i]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    state.sparsesys.idx[offs] = state.sparseh.idx[jj];
                    state.sparsesys.vals[offs] = 1.0;
                    offs = offs+1;
                }
                state.sparsesys.idx[offs] = i;
                state.sparsesys.vals[offs] = 1.0;
                offs = offs+1;
                state.sparsesys.ridx[i+1] = offs;
            }
            for(i=0; i<=mtotal-1; i++)
            {
                ablasf.igrowv(offs+n+1, ref state.sparsesys.idx, _params);
                ablasf.rgrowv(offs+n+1, ref state.sparsesys.vals, _params);
                j0 = state.curjac.ridx[i];
                j1 = state.curjac.ridx[i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    state.sparsesys.idx[offs] = state.curjac.idx[jj];
                    state.sparsesys.vals[offs] = 1.0;
                    offs = offs+1;
                }
                state.sparsesys.idx[offs] = n+i;
                state.sparsesys.vals[offs] = 1.0;
                offs = offs+1;
                state.sparsesys.ridx[n+i+1] = offs;
            }
            for(i=0; i<=2*state.hessmemlen-1; i++)
            {
                ablasf.igrowv(offs+state.nq+1, ref state.sparsesys.idx, _params);
                ablasf.rgrowv(offs+state.nq+1, ref state.sparsesys.vals, _params);
                for(jj=0; jj<=state.nq-1; jj++)
                {
                    state.sparsesys.idx[offs] = jj;
                    state.sparsesys.vals[offs] = 0.0;
                    offs = offs+1;
                }
                state.sparsesys.idx[offs] = n+mtotal+i;
                state.sparsesys.vals[offs] = 1.0;
                offs = offs+1;
                state.sparsesys.ridx[n+mtotal+i+1] = offs;
            }
            sparse.sparsecreatecrsinplace(state.sparsesys, _params);
            optionaldensefromsparse(state.optionaldenseq1, state.sparseq1, state.nq, _params);
            state.optionaldensexqc.clear();
            for(i=0; i<=state.mqc-1; i++)
            {
                state.xqc.constraints.get(i, ref qci);
                opti = new gqpoptionaldense();
                optionaldensefromsparseqc(opti, qci, _params);
                state.optionaldensexqc.append(opti);
            }
            facttype = 1;
            ablasf.isetallocv(n+mtotal+2*state.hessmemlen, 0, ref state.priorities, _params);
            if( state.algomode!=amhybrid )
            {
                for(i=0; i<=n-1; i++)
                {
                    state.priorities[i] = 1;
                }
                for(i=n; i<=n+mtotal-1; i++)
                {
                    state.priorities[i] = 0;
                }
            }
            for(i=n+mtotal; i<=n+mtotal+2*state.hessmemlen-1; i++)
            {
                state.priorities[i] = 2;
            }
            if( !spchol.spsymmanalyze(state.sparsesys, state.priorities, mupromote, 0, facttype, 3, 1, state.analysis, _params) )
            {
                alglib.ap.assert(false, "QPGIPM: critical integrity check failed, symbolically degenerate KKT system encountered");
            }
        }


        /*************************************************************************
        Lexicographically sorts a list of row-column-index elements.

          -- ALGLIB --
             Copyright 25.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void sortrck(int[] vecr,
            int[] vecc,
            int[] veck,
            double[] vecv,
            int n,
            ref int[] tmpr,
            ref int[] tmpc,
            ref int[] tmpk,
            ref double[] tmpv,
            alglib.xparams _params)
        {
            if( n==0 )
            {
                return;
            }
            ablasf.iallocv(n, ref tmpr, _params);
            ablasf.iallocv(n, ref tmpc, _params);
            ablasf.iallocv(n, ref tmpk, _params);
            ablasf.rallocv(n, ref tmpv, _params);
            sortrckrec(vecr, vecc, veck, vecv, 0, n, tmpr, tmpc, tmpk, tmpv, _params);
        }


        /*************************************************************************
        Recursive sorting routine.

          -- ALGLIB --
             Copyright 25.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void sortrckrec(int[] vecr,
            int[] vecc,
            int[] veck,
            double[] vecv,
            int idx0,
            int idx1,
            int[] tmpr,
            int[] tmpc,
            int[] tmpk,
            double[] tmpv,
            alglib.xparams _params)
        {
            int idxmid = 0;
            int src0 = 0;
            int src1 = 0;
            int end0 = 0;
            int end1 = 0;
            int dst = 0;
            int s = 0;

            if( idx1-idx0<=1 )
            {
                return;
            }
            idxmid = idx0+(idx1-idx0)/2;
            sortrckrec(vecr, vecc, veck, vecv, idx0, idxmid, tmpr, tmpc, tmpk, tmpv, _params);
            sortrckrec(vecr, vecc, veck, vecv, idxmid, idx1, tmpr, tmpc, tmpk, tmpv, _params);
            src0 = idx0;
            end0 = idxmid;
            src1 = idxmid;
            end1 = idx1;
            dst = idx0;
            while( src0<end0 && src1<end1 )
            {
                s = 0;
                if( vecr[src0]<vecr[src1] )
                {
                    s = -1;
                }
                if( vecr[src0]>vecr[src1] )
                {
                    s = 1;
                }
                if( s==0 )
                {
                    if( vecc[src0]<vecc[src1] )
                    {
                        s = -1;
                    }
                    if( vecc[src0]>vecc[src1] )
                    {
                        s = 1;
                    }
                }
                if( s==0 )
                {
                    if( veck[src0]<veck[src1] )
                    {
                        s = -1;
                    }
                    if( veck[src0]>veck[src1] )
                    {
                        s = 1;
                    }
                }
                if( s==0 )
                {
                    alglib.ap.assert(false, "SortRCKRec: integrity check failed, non-distinct entries");
                }
                if( s<0 )
                {
                    tmpr[dst] = vecr[src0];
                    tmpc[dst] = vecc[src0];
                    tmpk[dst] = veck[src0];
                    tmpv[dst] = vecv[src0];
                    src0 = src0+1;
                    dst = dst+1;
                }
                else
                {
                    tmpr[dst] = vecr[src1];
                    tmpc[dst] = vecc[src1];
                    tmpk[dst] = veck[src1];
                    tmpv[dst] = vecv[src1];
                    src1 = src1+1;
                    dst = dst+1;
                }
            }
            while( src0<end0 )
            {
                tmpr[dst] = vecr[src0];
                tmpc[dst] = vecc[src0];
                tmpk[dst] = veck[src0];
                tmpv[dst] = vecv[src0];
                src0 = src0+1;
                dst = dst+1;
            }
            while( src1<end1 )
            {
                tmpr[dst] = vecr[src1];
                tmpc[dst] = vecc[src1];
                tmpk[dst] = veck[src1];
                tmpv[dst] = vecv[src1];
                src1 = src1+1;
                dst = dst+1;
            }
            alglib.ap.assert(dst==idx1, "SortRCKRec: integrity check 211811 failed");
            ablasf.icopyvx(idx1-idx0, tmpr, idx0, vecr, idx0, _params);
            ablasf.icopyvx(idx1-idx0, tmpc, idx0, vecc, idx0, _params);
            ablasf.icopyvx(idx1-idx0, tmpk, idx0, veck, idx0, _params);
            ablasf.rcopyvx(idx1-idx0, tmpv, idx0, vecv, idx0, _params);
        }


        /*************************************************************************
        Handle compute-and-remember request

          -- ALGLIB --
             Copyright 25.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void handlecomputeandremember(gqpipmstate state,
            int offslc,
            int offsqc,
            int offsec,
            int offscc,
            int mtotal,
            ref bool remembered,
            ref bool factorized,
            alglib.xparams _params)
        {
            int n = 0;
            int mlc = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int tgt0 = 0;
            int tgt1 = 0;
            int jmid = 0;
            int offs = 0;
            int nv = 0;
            double v = 0;
            double vlag = 0;
            double valpha = 0;
            int kpow = 0;
            opts.xquadraticconstraint qci = null;
            opts.xconicconstraint cci = null;
            gqpsparseconichessian chi = null;
            gqpoptionaldense opti = null;
            bool donecc = new bool();
            bool donemv = new bool();
            double[] ccy = new double[0];
            double vv = 0;
            double vy = 0;
            double invvy = 0;
            double vz = 0;
            double u2 = 0;

            alglib.ap.assert((state.algomode==amdense || state.algomode==amsparse) || state.algomode==amhybrid, "QPGIPM: 087304 failed");
            n = state.n;
            mlc = state.mlc;
            state.nrealpool.retrieve(ref ccy);
            sparse.sparsecreatecrsemptybuf(n, state.solver.replysj, _params);
            ablasf.rallocv(n, ref state.tmp0, _params);
            ablasf.iallocv(n, ref state.tmpi, _params);
            ablasf.rcopyallocv(n, state.solver.querydata, ref state.tmpx, _params);
            ablasf.rallocv(n, ref state.currentx, _params);
            ablasf.rallocv(mtotal, ref state.currentlag, _params);
            ablasf.rcopyvx(n, state.solver.querydata, 0, state.currentx, 0, _params);
            ablasf.rcopyvx(mtotal, state.solver.querydata, n, state.currentlag, 0, _params);
            for(i=0; i<=state.msocc-1; i++)
            {
                state.currentlag[offscc+i] = Math.Max(state.currentlag[offscc+i], 0.0);
            }
            remembered = true;
            factorized = false;
            if( state.algomode==amdense )
            {
                ablasf.rgemv(n, n, 1.0, state.denseq, 0, state.tmpx, 0.0, state.tmp0, _params);
            }
            else
            {
                alglib.ap.assert(state.algomode==amsparse || state.algomode==amhybrid, "GQPIPM: integrity check 387218 failed");
                if( state.optionaldenseq1.hasdenseterm && state.optionaldenseq1.nvars>0 )
                {
                    alglib.ap.assert((state.optionaldenseq1.nvars>0 && state.optionaldenseq1.varidx[0]==0) && state.optionaldenseq1.varidx[state.optionaldenseq1.nvars-1]==state.optionaldenseq1.nvars-1, "GQPIPM: integrity check 390220 failed");
                    ablas.rmatrixsymv(state.optionaldenseq1.nvars, 1.0, state.optionaldenseq1.q, 0, 0, false, state.tmpx, 0, 0.0, state.tmp0, 0, _params);
                    ablasf.rsetvx(n-state.optionaldenseq1.nvars, 0.0, state.tmp0, state.optionaldenseq1.nvars, _params);
                }
                else
                {
                    sparse.sparsesmv(state.sparseq1, false, state.tmpx, ref state.tmp0, _params);
                }
            }
            state.solver.replyfi[0] = ablasf.rdotv(n, state.tmpx, state.c, _params)+0.5*ablasf.rdotv(n, state.tmpx, state.tmp0, _params);
            ablasf.raddv(n, 1.0, state.c, state.tmp0, _params);
            sparse.sparseappendcompressedrow(state.solver.replysj, state.iotac, state.tmp0, n, _params);
            if( state.algomode==amdense )
            {
                ablasf.rcopyallocm(n, n, state.denseq, ref state.currenth, _params);
            }
            if( mlc>0 )
            {
                sparse.sparsemv(state.sparselc, state.tmpx, ref state.tmp0, _params);
                ablasf.rcopyvx(mlc, state.tmp0, 0, state.solver.replyfi, 1+offslc, _params);
                alglib.ap.assert(state.curjac.ridx[offslc+mlc]-state.curjac.ridx[offslc]==state.sparselc.ridx[mlc], "GQPIPM: integrity check 3638 failed");
                ablasf.rcopyvx(state.sparselc.ridx[mlc], state.sparselc.vals, 0, state.curjac.vals, state.curjac.ridx[offslc], _params);
            }
            for(i=0; i<=state.fixedvarscnt-1; i++)
            {
                j = state.fixedidx[i];
                v = state.tmpx[j];
                state.solver.replyfi[1+offsec+i] = v;
                alglib.ap.assert(state.curjac.ridx[offsec+i+1]-state.curjac.ridx[offsec+i]==1, "GQPIPM: integrity check 6240 failed");
                state.curjac.vals[state.curjac.ridx[offsec+i]] = 1.0;
            }
            for(i=0; i<=state.mqc-1; i++)
            {
                ablasf.rallocv(n, ref state.tmp0, _params);
                ablasf.rallocv(n, ref state.tmp1, _params);
                state.xqc.constraints.get(i, ref qci);
                if( qci.nvars==0 )
                {
                    state.solver.replyfi[1+offsqc+i] = 0.0;
                    continue;
                }
                for(j=0; j<=qci.nvars-1; j++)
                {
                    state.tmp0[j] = state.tmpx[qci.varidx[j]];
                }
                donemv = false;
                if( state.optionaldensexqc.getlength()==state.mqc )
                {
                    state.optionaldensexqc.get(i, ref opti);
                    if( opti.hasdenseterm )
                    {
                        ablas.rmatrixsymv(opti.nvars, 1.0, opti.q, 0, 0, false, state.tmp0, 0, 0.0, state.tmp1, 0, _params);
                        donemv = true;
                    }
                }
                if( !donemv )
                {
                    sparse.sparsesmv(qci.lowerq, false, state.tmp0, ref state.tmp1, _params);
                }
                state.solver.replyfi[1+offsqc+i] = ablasf.rdotv(qci.nvars, qci.b, state.tmp0, _params)+0.5*ablasf.rdotv(qci.nvars, state.tmp0, state.tmp1, _params);
                ablasf.raddv(qci.nvars, 1.0, qci.b, state.tmp1, _params);
                if( state.algomode==amdense )
                {
                    vlag = state.currentlag[offsqc+i];
                    for(j=0; j<=qci.nvars-1; j++)
                    {
                        alglib.ap.assert(qci.lowerq.didx[j]==qci.lowerq.uidx[j]-1, "GQPIPM: integrity check 2148 failed");
                        j0 = qci.lowerq.ridx[j];
                        j1 = qci.lowerq.didx[j]-1;
                        tgt0 = qci.varidx[j];
                        for(jj=j0; jj<=j1; jj++)
                        {
                            tgt1 = qci.varidx[qci.lowerq.idx[jj]];
                            state.currenth[tgt0,tgt1] = state.currenth[tgt0,tgt1]+vlag*qci.lowerq.vals[jj];
                        }
                        state.currenth[tgt0,tgt0] = state.currenth[tgt0,tgt0]+vlag*qci.lowerq.vals[qci.lowerq.didx[j]];
                    }
                }
                alglib.ap.assert(state.curjac.ridx[offsqc+i+1]-state.curjac.ridx[offsqc+i]==qci.nvars, "GQPIPM: integrity check 2645 failed");
                ablasf.rcopyvx(qci.nvars, state.tmp1, 0, state.curjac.vals, state.curjac.ridx[offsqc+i], _params);
            }
            for(i=0; i<=state.msocc-1; i++)
            {
                ablasf.rallocv(n, ref state.tmp0, _params);
                ablasf.rallocv(n, ref state.tmp1, _params);
                state.xcc.constraints.get(i, ref cci);
                state.xchsparse.get(i, ref chi);
                if( cci.nvars==0 )
                {
                    state.solver.replyfi[1+offscc+i] = 0.0;
                    continue;
                }
                nv = cci.nvars;
                kpow = cci.kpow;
                for(j=0; j<=cci.nvars-1; j++)
                {
                    state.tmp0[j] = state.tmpx[cci.varidx[j]];
                }
                donecc = false;
                v = 0;
                u2 = 0;
                if( cci.conetype==optserv.xccprimitiveconetype(_params) )
                {
                    vy = state.tmp0[cci.nvars-1]*cci.diaga[cci.nvars-1]+cci.shftc[cci.nvars-1];
                    ccy[cci.nvars-1] = vy;
                    alglib.ap.assert((double)(vy)>(double)(0), "GQPIPM: integrity check 251633 failed");
                    u2 = cci.shftc[cci.nvars];
                    for(j=0; j<=cci.nvars-2; j++)
                    {
                        vv = state.tmp0[j]*cci.diaga[j]+cci.shftc[j];
                        ccy[j] = vv;
                        u2 = u2+vv*vv;
                        state.tmp1[j] = 2*vv*cci.diaga[j];
                    }
                    ablasf.rmulv(cci.nvars-1, 1/vy, state.tmp1, _params);
                    state.tmp1[cci.nvars-1] = (-(u2/(vy*vy))-1)*cci.diaga[cci.nvars-1];
                    v = u2/vy-vy;
                    donecc = true;
                }
                if( cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                {
                    u2 = cci.shftc[nv];
                    for(j=0; j<=nv-kpow-1; j++)
                    {
                        vv = state.tmp0[j]*cci.diaga[j]+cci.shftc[j];
                        ccy[j] = vv;
                        u2 = u2+vv*vv;
                    }
                    vy = 1;
                    vz = 1;
                    for(j=nv-kpow; j<=nv-1; j++)
                    {
                        vv = state.tmp0[j]*cci.diaga[j]+cci.shftc[j];
                        ccy[j] = vv;
                        alglib.ap.assert((double)(vv)>(double)(0), "GQPIPM: integrity check 063327 failed");
                        vy = vy*Math.Pow(vv, cci.alphapow[j-(nv-kpow)]);
                        vz = vz*vv;
                    }
                    invvy = 1/vy;
                    if( state.pctype==0 )
                    {
                        v = u2*invvy-vy;
                        for(j=0; j<=nv-kpow-1; j++)
                        {
                            state.tmp1[j] = 2*ccy[j]*invvy*cci.diaga[j];
                        }
                        for(j=nv-kpow; j<=nv-1; j++)
                        {
                            state.tmp1[j] = cci.diaga[j]*(-(u2*invvy)-vy)*cci.alphapow[j-(nv-kpow)]/ccy[j];
                        }
                        donecc = true;
                    }
                    if( state.pctype==1 )
                    {
                        v = u2*vz*invvy-vz*vy;
                        for(j=0; j<=nv-kpow-1; j++)
                        {
                            state.tmp1[j] = 2*ccy[j]*vz*invvy*cci.diaga[j];
                        }
                        for(j=nv-kpow; j<=nv-1; j++)
                        {
                            valpha = cci.alphapow[j-(nv-kpow)];
                            state.tmp1[j] = (u2*(1-valpha)*invvy-(1+valpha)*vy)*vz/ccy[j]*cci.diaga[j];
                        }
                        donecc = true;
                    }
                }
                alglib.ap.assert(donecc, "GQPIPM: integrity check 189820 failed (unexpected cone type and/or barrier type)");
                state.solver.replyfi[1+offscc+i] = v;
                alglib.ap.assert(state.curjac.ridx[offscc+i+1]-state.curjac.ridx[offscc+i]==cci.nvars, "GQPIPM: integrity check 811110 failed");
                offs = state.curjac.ridx[offscc+i];
                for(j=0; j<=cci.nvars-1; j++)
                {
                    state.curjac.vals[offs+j] = state.tmp1[chi.ordervaridx[j]];
                }
                if( state.algomode==amdense )
                {
                    vlag = state.currentlag[offscc+i];
                    donecc = false;
                    if( cci.conetype==optserv.xccprimitiveconetype(_params) )
                    {
                        vy = ccy[cci.nvars-1];
                        alglib.ap.assert((double)(vy)>(double)(0), "GQPIPM: integrity check 323638 failed");
                        v = 2/vy;
                        tgt1 = cci.varidx[cci.nvars-1];
                        jmid = apserv.ibinarysearchlft(cci.varidx, 0, cci.nvars-1, tgt1, _params);
                        alglib.ap.assert(jmid==cci.nvars-1 || cci.varidx[jmid]>tgt1, "GQPIPM: integrity check 547204 failed");
                        for(j=0; j<=jmid-1; j++)
                        {
                            tgt0 = cci.varidx[j];
                            state.currenth[tgt0,tgt0] = state.currenth[tgt0,tgt0]+vlag*v*(cci.diaga[j]*cci.diaga[j]);
                            state.currenth[tgt1,tgt0] = state.currenth[tgt1,tgt0]-vlag*v*(cci.diaga[j]*cci.diaga[cci.nvars-1]*ccy[j]/vy);
                        }
                        state.currenth[tgt1,tgt1] = state.currenth[tgt1,tgt1]+vlag*v*(cci.diaga[cci.nvars-1]*cci.diaga[cci.nvars-1]*u2/(vy*vy));
                        for(j=jmid; j<=cci.nvars-2; j++)
                        {
                            tgt0 = cci.varidx[j];
                            state.currenth[tgt0,tgt0] = state.currenth[tgt0,tgt0]+vlag*v*(cci.diaga[j]*cci.diaga[j]);
                            state.currenth[tgt0,tgt1] = state.currenth[tgt0,tgt1]-vlag*v*(cci.diaga[j]*cci.diaga[cci.nvars-1]*ccy[j]/vy);
                        }
                        donecc = true;
                    }
                    if( cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                    {
                        alglib.ap.assert(state.pctype==0, "GQPIPM: integrity check 194815 failed");
                        u2 = cci.shftc[nv];
                        for(j=0; j<=nv-kpow-1; j++)
                        {
                            u2 = u2+ccy[j]*ccy[j];
                        }
                        vy = 1;
                        for(j=nv-kpow; j<=nv-1; j++)
                        {
                            vy = vy*Math.Pow(ccy[j], cci.alphapow[j-(nv-kpow)]);
                        }
                        invvy = 1/vy;
                        v = 2/vy;
                        for(j=0; j<=nv-kpow-1; j++)
                        {
                            tgt0 = cci.varidx[j];
                            state.currenth[tgt0,tgt0] = state.currenth[tgt0,tgt0]+vlag*v*(cci.diaga[j]*cci.diaga[j]);
                        }
                        for(j0=nv-kpow; j0<=nv-1; j0++)
                        {
                            for(j1=nv-kpow; j1<=j0-1; j1++)
                            {
                                tgt0 = cci.varidx[j0];
                                tgt1 = cci.varidx[j1];
                                if( tgt1>tgt0 )
                                {
                                    jj = tgt0;
                                    tgt0 = tgt1;
                                    tgt1 = jj;
                                }
                                v = cci.alphapow[j0-(nv-kpow)]*cci.alphapow[j1-(nv-kpow)]/(ccy[j0]*ccy[j1]);
                                state.currenth[tgt0,tgt1] = state.currenth[tgt0,tgt1]+vlag*v*(u2*invvy-vy)*(cci.diaga[j0]*cci.diaga[j1]);
                            }
                            tgt0 = cci.varidx[j0];
                            valpha = cci.alphapow[j0-(nv-kpow)];
                            v = valpha/(ccy[j0]*ccy[j0]);
                            state.currenth[tgt0,tgt0] = state.currenth[tgt0,tgt0]+vlag*v*((valpha+1)*u2*invvy-(valpha-1)*vy)*(cci.diaga[j0]*cci.diaga[j0]);
                        }
                        v = 2/vy;
                        for(j0=nv-kpow; j0<=nv-1; j0++)
                        {
                            for(j1=0; j1<=nv-kpow-1; j1++)
                            {
                                tgt0 = cci.varidx[j0];
                                tgt1 = cci.varidx[j1];
                                if( tgt1>tgt0 )
                                {
                                    jj = tgt0;
                                    tgt0 = tgt1;
                                    tgt1 = jj;
                                }
                                valpha = cci.alphapow[j0-(nv-kpow)];
                                state.currenth[tgt0,tgt1] = state.currenth[tgt0,tgt1]+vlag*v*-(valpha*ccy[j1]/ccy[j0])*(cci.diaga[j0]*cci.diaga[j1]);
                            }
                        }
                        donecc = true;
                    }
                    alglib.ap.assert(donecc, "GQPIPM: integrity check 251026 failed");
                }
                else
                {
                    donecc = false;
                    if( cci.conetype==optserv.xccprimitiveconetype(_params) )
                    {
                        vy = ccy[cci.nvars-1];
                        alglib.ap.assert((double)(vy)>(double)(0), "GQPIPM: integrity check 323638 failed");
                        v = 2/vy;
                        offs = 0;
                        for(j=0; j<=nv-2; j++)
                        {
                            chi.lowerh.vals[offs] = v*(cci.diaga[j]*cci.diaga[j]);
                            offs = offs+1;
                        }
                        for(j=0; j<=nv-2; j++)
                        {
                            chi.lowerh.vals[offs] = -(v*(cci.diaga[j]*cci.diaga[cci.nvars-1]*ccy[j]/vy));
                            offs = offs+1;
                        }
                        chi.lowerh.vals[offs] = v*(cci.diaga[cci.nvars-1]*cci.diaga[cci.nvars-1]*u2/(vy*vy));
                        offs = offs+1;
                        alglib.ap.assert(offs==2*nv-1, "GQPIPM: integrity check 895149 failed");
                        k = chi.lowerh.ridx[nv];
                        for(j=0; j<=k-1; j++)
                        {
                            state.sparsehdeps.vals[chi.injectionoffsets[j]] = chi.lowerh.vals[j];
                        }
                        donecc = true;
                    }
                    if( cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                    {
                        alglib.ap.assert(state.pctype==0, "GQPIPM: integrity check 311816 failed");
                        u2 = cci.shftc[nv];
                        for(j=0; j<=nv-kpow-1; j++)
                        {
                            u2 = u2+ccy[j]*ccy[j];
                        }
                        vy = 1;
                        for(j=nv-kpow; j<=nv-1; j++)
                        {
                            vy = vy*Math.Pow(ccy[j], cci.alphapow[j-(nv-kpow)]);
                        }
                        invvy = 1/vy;
                        offs = 0;
                        v = 2/vy;
                        for(j0=0; j0<=nv-kpow-1; j0++)
                        {
                            chi.lowerh.vals[offs] = v*(cci.diaga[j0]*cci.diaga[j0]);
                            offs = offs+1;
                        }
                        for(j0=nv-kpow; j0<=nv-1; j0++)
                        {
                            for(j1=0; j1<=nv-kpow-1; j1++)
                            {
                                chi.lowerh.vals[offs] = 2*invvy*-(cci.alphapow[j0-(nv-kpow)]*ccy[j1]/ccy[j0])*(cci.diaga[j0]*cci.diaga[j1]);
                                offs = offs+1;
                            }
                            for(j1=nv-kpow; j1<=j0-1; j1++)
                            {
                                v = cci.alphapow[j0-(nv-kpow)]*cci.alphapow[j1-(nv-kpow)]/(ccy[j0]*ccy[j1]);
                                chi.lowerh.vals[offs] = v*(u2*invvy-vy)*(cci.diaga[j0]*cci.diaga[j1]);
                                offs = offs+1;
                            }
                            valpha = cci.alphapow[j0-(nv-kpow)];
                            v = valpha/(ccy[j0]*ccy[j0]);
                            chi.lowerh.vals[offs] = v*((valpha+1)*u2*invvy-(valpha-1)*vy)*(cci.diaga[j0]*cci.diaga[j0]);
                            offs = offs+1;
                        }
                        alglib.ap.assert(offs==chi.lowerh.ridx[nv], "GQPIPM: integrity check 318256 failed");
                        k = chi.lowerh.ridx[nv];
                        for(j=0; j<=k-1; j++)
                        {
                            state.sparsehdeps.vals[chi.injectionoffsets[j]] = chi.lowerh.vals[j];
                        }
                        donecc = true;
                    }
                    alglib.ap.assert(donecc, "GQPIPM: integrity check 895132 failed");
                }
            }
            if( mtotal>0 )
            {
                sparse.sparseappendmatrix(state.solver.replysj, state.curjac, _params);
            }
            if( state.algomode!=amdense )
            {
                ablasf.rallocv(mtotal+1, ref state.tmp0, _params);
                ablasf.rcopyvx(mtotal, state.solver.querydata, n, state.tmp0, 0, _params);
                for(i=0; i<=state.msocc-1; i++)
                {
                    state.tmp0[offscc+i] = Math.Max(state.tmp0[offscc+i], 0.0);
                }
                state.tmp0[mtotal] = 1.0;
                sparse.sparsemv(state.sparsehdeps, state.tmp0, ref state.sparseh.vals, _params);
            }
            state.nrealpool.recycle(ref ccy);
        }


        /*************************************************************************
        Handle factorization request

          -- ALGLIB --
             Copyright 25.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void handlefactorize(gqpipmstate state,
            int mtotal,
            ref bool remembered,
            ref bool factorized,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int offs = 0;
            double v = 0;

            n = state.n;
            alglib.ap.assert(remembered, "GQPIPM: integrity check 8128 failed");
            if( state.algomode==amdense )
            {
                ablasf.rallocv(n, ref state.tmpd1, _params);
                ablasf.rcopyvx(n, state.solver.querydata, 0, state.tmpd1, 0, _params);
                ablasf.rallocv(mtotal, ref state.tmpd2, _params);
                ablasf.rcopyvx(mtotal, state.solver.querydata, n, state.tmpd2, 0, _params);
                ablasf.rcopyallocm(n, n, state.currenth, ref state.currentch, _params);
                for(i=0; i<=n-1; i++)
                {
                    state.currentch[i,i] = state.currentch[i,i]+state.tmpd1[i];
                }
                if( mtotal>0 )
                {
                    ablasf.rallocm(mtotal, n, ref state.tmpwj, _params);
                    for(i=0; i<=mtotal-1; i++)
                    {
                        ablasf.rsetr(n, 0.0, state.tmpwj, i, _params);
                        v = Math.Sqrt(-(1/state.tmpd2[i]));
                        j0 = state.curjac.ridx[i];
                        j1 = state.curjac.ridx[i+1]-1;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            state.tmpwj[i,state.curjac.idx[jj]] = v*state.curjac.vals[jj];
                        }
                    }
                    ablas.rmatrixsyrk(n, mtotal, 1.0, state.tmpwj, 0, 0, 2, 1.0, state.currentch, 0, 0, false, _params);
                }
                factorized = trfac.spdmatrixcholeskyrec(state.currentch, 0, n, false, ref state.tmp0, _params);
            }
            else
            {
                alglib.ap.assert(state.algomode==amsparse || state.algomode==amhybrid, "GQPIPM: integrity check 577311 failed");
                alglib.ap.assert(state.algomode==amhybrid || state.hessmemlen==0, "GQPIPM: integrity check 578312 failed");
                if( state.algomode==amhybrid && state.nq>0 )
                {
                    alglib.ap.assert(state.basehrank<=2*state.hessmemlen, "GQPIPM: integrity check 533316 failed");
                    optserv.hessiangetlowrankstabilized(state.hess, ref state.basehsr1diag, ref state.basehsr1corrc, ref state.basehsr1corrd, ref state.basehrank, _params);
                }
                ablasf.ballocv(n+mtotal+2*state.hessmemlen, ref state.tmpb, _params);
                state.sparsesys.m = n+mtotal+2*state.hessmemlen;
                state.sparsesys.n = n+mtotal+2*state.hessmemlen;
                ablasf.iallocv(n+mtotal+1, ref state.sparsesys.ridx, _params);
                state.sparsesys.ridx[0] = 0;
                offs = 0;
                for(i=0; i<=n-1; i++)
                {
                    ablasf.igrowv(offs+n, ref state.sparsesys.idx, _params);
                    ablasf.rgrowv(offs+n, ref state.sparsesys.vals, _params);
                    j0 = state.sparseh.ridx[i];
                    j1 = state.sparseh.didx[i]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        state.sparsesys.idx[offs] = state.sparseh.idx[jj];
                        state.sparsesys.vals[offs] = state.sparseh.vals[jj];
                        offs = offs+1;
                    }
                    v = 0.0;
                    if( state.sparseh.didx[i]<state.sparseh.uidx[i] )
                    {
                        v = state.sparseh.vals[state.sparseh.didx[i]];
                    }
                    if( state.algomode==amhybrid && i<state.nq )
                    {
                        v = v+state.basehsr1diag[i];
                    }
                    v = v+state.solver.querydata[i];
                    state.sparsesys.idx[offs] = i;
                    state.sparsesys.vals[offs] = v;
                    offs = offs+1;
                    state.sparsesys.ridx[i+1] = offs;
                    state.tmpb[i] = true;
                }
                for(i=0; i<=mtotal-1; i++)
                {
                    ablasf.igrowv(offs+n+1, ref state.sparsesys.idx, _params);
                    ablasf.rgrowv(offs+n+1, ref state.sparsesys.vals, _params);
                    j0 = state.curjac.ridx[i];
                    j1 = state.curjac.ridx[i+1]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        state.sparsesys.idx[offs] = state.curjac.idx[jj];
                        state.sparsesys.vals[offs] = state.curjac.vals[jj];
                        offs = offs+1;
                    }
                    v = state.solver.querydata[n+i];
                    state.sparsesys.idx[offs] = n+i;
                    state.sparsesys.vals[offs] = v;
                    offs = offs+1;
                    state.sparsesys.ridx[n+i+1] = offs;
                    state.tmpb[n+i] = false;
                }
                for(i=0; i<=2*state.hessmemlen-1; i++)
                {
                    if( state.nq>0 && i<state.basehrank )
                    {
                        for(j=0; j<=state.nq-1; j++)
                        {
                            state.sparsesys.vals[offs+j] = state.basehsr1corrc[i,j];
                        }
                        state.sparsesys.vals[offs+state.nq] = -state.basehsr1corrd[i];
                    }
                    else
                    {
                        for(j=0; j<=state.nq-1; j++)
                        {
                            state.sparsesys.vals[offs+j] = 0;
                        }
                        state.sparsesys.vals[offs+state.nq] = 1;
                    }
                    state.tmpb[n+mtotal+i] = (double)(state.sparsesys.vals[offs+state.nq])>(double)(0);
                    offs = offs+state.nq+1;
                    state.sparsesys.ridx[n+mtotal+i+1] = offs;
                }
                sparse.sparsecreatecrsinplace(state.sparsesys, _params);
                spchol.spsymmreload(state.analysis, state.sparsesys, _params);
                spchol.spsymmcontrolsign(state.analysis, state.tmpb, 0.0, _params);
                factorized = spchol.spsymmfactorize(state.analysis, _params);
            }
            state.solver.factsuccess = factorized;
        }


        /*************************************************************************
        Handle solve request

          -- ALGLIB --
             Copyright 25.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void handlesolve(gqpipmstate state,
            int mtotal,
            ref bool remembered,
            ref bool factorized,
            alglib.xparams _params)
        {
            int n = 0;

            n = state.n;
            alglib.ap.assert(factorized, "GQPIPM: integrity check 2043 failed");
            if( state.algomode==amdense )
            {
                ablasf.rallocv(mtotal, ref state.tmprhsy, _params);
                ablasf.rcopyvx(mtotal, state.solver.querydata, n, state.tmprhsy, 0, _params);
                ablasf.rcopyallocv(mtotal, state.tmprhsy, ref state.tmp1, _params);
                ablasf.rmergedivv(mtotal, state.tmpd2, state.tmp1, _params);
                ablasf.rcopyv(n, state.solver.querydata, state.solver.replysol, _params);
                if( mtotal>0 )
                {
                    sparse.sparsegemv(state.curjac, -1.0, 1, state.tmp1, 0, 1.0, state.solver.replysol, 0, _params);
                }
                ablasf.rtrsvx(n, state.currentch, 0, 0, false, false, 0, state.solver.replysol, 0, _params);
                ablasf.rtrsvx(n, state.currentch, 0, 0, false, false, 1, state.solver.replysol, 0, _params);
                if( mtotal>0 )
                {
                    sparse.sparsegemv(state.curjac, -1.0, 0, state.solver.replysol, 0, 1.0, state.tmprhsy, 0, _params);
                }
                ablasf.rmergedivv(mtotal, state.tmpd2, state.tmprhsy, _params);
                ablasf.rcopyvx(mtotal, state.tmprhsy, 0, state.solver.replysol, n, _params);
                return;
            }
            if( state.algomode==amsparse )
            {
                ablasf.rcopyv(n+mtotal, state.solver.querydata, state.solver.replysol, _params);
                spchol.spsymmsolve(state.analysis, state.solver.replysol, _params);
                return;
            }
            if( state.algomode==amhybrid )
            {
                ablasf.rallocv(n+mtotal+2*state.hessmemlen, ref state.tmp0, _params);
                ablasf.rcopyv(n+mtotal, state.solver.querydata, state.tmp0, _params);
                ablasf.rsetvx(2*state.hessmemlen, 0.0, state.tmp0, n+mtotal, _params);
                spchol.spsymmsolve(state.analysis, state.tmp0, _params);
                ablasf.rcopyv(n+mtotal, state.tmp0, state.solver.replysol, _params);
                return;
            }
            alglib.ap.assert(false, "GQPIPM: integrity check 721333 failed");
        }


        /*************************************************************************
        Handle matrix-vector product request

          -- ALGLIB --
             Copyright 25.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void handlemv(gqpipmstate state,
            int offslc,
            int offsqc,
            int offsec,
            int offscc,
            int mtotal,
            ref bool remembered,
            ref bool factorized,
            alglib.xparams _params)
        {
            int n = 0;
            int i = 0;
            int j = 0;
            double vlag = 0;
            opts.xquadraticconstraint qci = null;
            opts.xconicconstraint cci = null;
            gqpsparseconichessian chi = null;

            n = state.n;
            alglib.ap.assert(remembered, "GQPIPM: integrity check 4322 failed");
            if( state.algomode==amdense )
            {
                ablasf.rallocv(Math.Max(n, mtotal), ref state.tmp0, _params);
                ablasf.rallocv(Math.Max(n, mtotal), ref state.tmp1, _params);
                ablasf.rcopyvx(n, state.solver.querydata, 0, state.tmp0, 0, _params);
                ablas.rmatrixsymv(n, 1.0, state.currenth, 0, 0, false, state.tmp0, 0, 0.0, state.tmp1, 0, _params);
                ablasf.rcopyvx(n, state.tmp1, 0, state.solver.replyprod, 0, _params);
                if( mtotal>0 )
                {
                    sparse.sparsegemv(state.curjac, 1.0, 0, state.tmp0, 0, 0.0, state.tmp1, 0, _params);
                }
                else
                {
                    ablasf.rsetv(mtotal, 0.0, state.tmp1, _params);
                }
                ablasf.rcopyvx(mtotal, state.tmp1, 0, state.solver.replyprod, n, _params);
                ablasf.rcopyvx(mtotal, state.solver.querydata, n, state.tmp0, 0, _params);
                if( mtotal>0 )
                {
                    sparse.sparsegemv(state.curjac, 1.0, 1, state.tmp0, 0, 0.0, state.tmp1, 0, _params);
                }
                else
                {
                    ablasf.rsetv(n, 0.0, state.tmp1, _params);
                }
                ablasf.rcopyvx(n, state.tmp1, 0, state.solver.replyprod, n+mtotal, _params);
            }
            else
            {
                alglib.ap.assert(state.algomode==amsparse || state.algomode==amhybrid, "GQPIPM: integrity check 777338 failed");
                ablasf.rallocv(Math.Max(n, mtotal), ref state.tmp0, _params);
                ablasf.rallocv(Math.Max(n, mtotal), ref state.tmp1, _params);
                if( state.algomode==amhybrid )
                {
                    if( state.nq>0 )
                    {
                        ablasf.rcopyv(state.nq, state.solver.querydata, state.tmp0, _params);
                        ablasf.rmergemulv(state.nq, state.basehsr1diag, state.tmp0, _params);
                        if( state.basehrank>0 )
                        {
                            ablasf.rgemv(state.basehrank, state.nq, 1.0, state.basehsr1corrc, 0, state.solver.querydata, 0.0, state.tmp1, _params);
                            ablasf.rmergemulv(state.basehrank, state.basehsr1corrd, state.tmp1, _params);
                            ablasf.rgemv(state.nq, state.basehrank, 1.0, state.basehsr1corrc, 1, state.tmp1, 1.0, state.tmp0, _params);
                        }
                        ablasf.rcopyvx(state.nq, state.tmp0, 0, state.solver.replyprod, 0, _params);
                    }
                    ablasf.rsetvx(n-state.nq, 0.0, state.solver.replyprod, state.nq, _params);
                }
                else
                {
                    ablasf.rsetv(n, 0.0, state.solver.replyprod, _params);
                }
                if( state.algomode!=amhybrid || !state.doqnupdates[0] )
                {
                    sparse.sparsesmv(state.sparseq1, false, state.solver.querydata, ref state.tmp0, _params);
                    ablasf.raddv(n, 1.0, state.tmp0, state.solver.replyprod, _params);
                }
                for(i=0; i<=state.mqc-1; i++)
                {
                    if( state.algomode!=amhybrid || !state.doqnupdates[1+offsqc+i] )
                    {
                        state.xqc.constraints.get(i, ref qci);
                        if( qci.nvars==0 )
                        {
                            continue;
                        }
                        for(j=0; j<=qci.nvars-1; j++)
                        {
                            state.tmp0[j] = state.solver.querydata[qci.varidx[j]];
                        }
                        sparse.sparsesmv(qci.lowerq, false, state.tmp0, ref state.tmp1, _params);
                        vlag = state.currentlag[offsqc+i];
                        for(j=0; j<=qci.nvars-1; j++)
                        {
                            state.solver.replyprod[qci.varidx[j]] = state.solver.replyprod[qci.varidx[j]]+vlag*state.tmp1[j];
                        }
                    }
                }
                for(i=0; i<=state.msocc-1; i++)
                {
                    alglib.ap.assert(state.algomode!=amhybrid || !state.doqnupdates[1+offscc+i], "GQPIPM: integrity check 907345 failed");
                    state.xcc.constraints.get(i, ref cci);
                    state.xchsparse.get(i, ref chi);
                    if( cci.nvars==0 )
                    {
                        continue;
                    }
                    for(j=0; j<=cci.nvars-1; j++)
                    {
                        state.tmp0[j] = state.solver.querydata[cci.varidx[j]];
                    }
                    sparse.sparsesmv(chi.lowerh, false, state.tmp0, ref state.tmp1, _params);
                    vlag = state.currentlag[offscc+i];
                    for(j=0; j<=cci.nvars-1; j++)
                    {
                        state.solver.replyprod[cci.varidx[j]] = state.solver.replyprod[cci.varidx[j]]+vlag*state.tmp1[j];
                    }
                }
                if( mtotal>0 )
                {
                    sparse.sparsemv(state.curjac, state.solver.querydata, ref state.tmp1, _params);
                    ablasf.rcopyvx(mtotal, state.tmp1, 0, state.solver.replyprod, n, _params);
                    ablasf.rcopyvx(mtotal, state.solver.querydata, n, state.tmp0, 0, _params);
                    sparse.sparsemtv(state.curjac, state.tmp0, ref state.tmp1, _params);
                    ablasf.rcopyvx(n, state.tmp1, 0, state.solver.replyprod, n+mtotal, _params);
                }
                else
                {
                    ablasf.rsetvx(n, 0.0, state.solver.replyprod, n+mtotal, _params);
                }
            }
        }


        /*************************************************************************
        Create optional-dense quadratic term from a sparse quadratic objective term.

          -- ALGLIB --
             Copyright 02.05.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void optionaldensefromsparse(gqpoptionaldense opt,
            sparse.sparsematrix s,
            int nq,
            alglib.xparams _params)
        {
            int i = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int k = 0;

            alglib.ap.assert((sparse.sparseiscrs(s, _params) && s.n==s.m) && s.n>=nq, "GQPIPM: integrity check 127140 failed");
            opt.hasdenseterm = false;
            k = 0;
            for(i=0; i<=nq-1; i++)
            {
                k = k+(s.didx[i]-s.ridx[i])+1;
            }
            if( nq<=2 || (double)(k)<(double)(0.5*((double)(nq*(nq-1))/(double)2)) )
            {
                return;
            }
            opt.nvars = nq;
            ablasf.iallocv(nq, ref opt.varidx, _params);
            for(i=0; i<=nq-1; i++)
            {
                opt.varidx[i] = i;
            }
            ablasf.rallocm(nq, nq, ref opt.q, _params);
            for(i=0; i<=nq-1; i++)
            {
                ablasf.rsetr(i+1, 0.0, opt.q, i, _params);
                j0 = s.ridx[i];
                j1 = s.didx[i]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    opt.q[i,s.idx[jj]] = s.vals[jj];
                }
                if( s.didx[i]<s.uidx[i] )
                {
                    opt.q[i,i] = s.vals[s.didx[i]];
                }
            }
            opt.hasdenseterm = true;
        }


        /*************************************************************************
        Create optional-dense quadratic term from sparse quadratic constraint term

          -- ALGLIB --
             Copyright 02.05.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void optionaldensefromsparseqc(gqpoptionaldense opt,
            opts.xquadraticconstraint qc,
            alglib.xparams _params)
        {
            int i = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int k = 0;
            int nq = 0;

            opt.hasdenseterm = false;
            if( qc.nvars<=2 )
            {
                return;
            }
            nq = qc.nvars;
            k = 0;
            for(i=0; i<=nq-1; i++)
            {
                k = k+(qc.lowerq.didx[i]-qc.lowerq.ridx[i])+1;
            }
            if( (double)(k)<(double)(0.5*((double)(nq*(nq-1))/(double)2)) )
            {
                return;
            }
            opt.nvars = nq;
            ablasf.iallocv(nq, ref opt.varidx, _params);
            for(i=0; i<=nq-1; i++)
            {
                opt.varidx[i] = qc.varidx[i];
            }
            ablasf.rallocm(nq, nq, ref opt.q, _params);
            for(i=0; i<=nq-1; i++)
            {
                ablasf.rsetr(i+1, 0.0, opt.q, i, _params);
                j0 = qc.lowerq.ridx[i];
                j1 = qc.lowerq.didx[i]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    opt.q[i,qc.lowerq.idx[jj]] = qc.lowerq.vals[jj];
                }
                if( qc.lowerq.didx[i]<qc.lowerq.uidx[i] )
                {
                    opt.q[i,i] = qc.lowerq.vals[qc.lowerq.didx[i]];
                }
            }
            opt.hasdenseterm = true;
        }


    }
