            {
                rawsystem = new sparse.sparsematrix();
                effectivediag = new double[0];
                isdiagonal = new bool[0];
                rowdegrees = new int[0];
                coldegrees = new int[0];
                analysis = new spchol.spcholanalysis();
                priorities = new int[0];
                diagterm = new double[0];
