        /*************************************************************************
        Right-hand side for a big (non-condensed) KKT system of the form

        -(ST+Eps)*(dT/T) - T*dS                             = -GammaST
        -(GZ+Eps)*(dG/G) - G*dZ                             = -GammaGZ
        -(H+Eps)*dX + A'*dY + dZ - dS - W'*dQ               = ED
        A*dX + Eps*dY                                       = EA
        -G*(dG/G) + dX + Eps*dZ                             = EL
        -T*(dT/T) - dX + Eps*dS                             = EU

        where
            GammaST = mu-ST
            GammaGZ = mu-GZ
            ED      = c-A'*y-Z+S+H*x+W'*Q
            EA      = -A*X
            EL      = L-X+G
            EU      = T+X-U
        *************************************************************************/
        public class ipm2righthandside : apobject
        {
            public double[] gammagz;
            public double[] gammats;
            public double[] ed;
            public double[] ea;
            public double[] el;
            public double[] eu;
            public ipm2righthandside()
            {
                init();
            }
            public override void init()
            {
                gammagz = new double[0];
                gammats = new double[0];
                ed = new double[0];
                ea = new double[0];
                el = new double[0];
                eu = new double[0];
            }
            public override alglib.apobject make_copy()
            {
                ipm2righthandside _result = new ipm2righthandside();
                _result.gammagz = (double[])gammagz.Clone();
                _result.gammats = (double[])gammats.Clone();
                _result.ed = (double[])ed.Clone();
                _result.ea = (double[])ea.Clone();
                _result.el = (double[])el.Clone();
                _result.eu = (double[])eu.Clone();
                return _result;
            }
        };


