                _result.rhsprogress = rhsprogress!=null ? (ipm2righthandside)rhsprogress.make_copy() : null;
                _result.tmphx = (double[])tmphx.Clone();
                _result.tmpax = (double[])tmpax.Clone();
                _result.tmpaty = (double[])tmpaty.Clone();
                _result.dummyr = (double[])dummyr.Clone();
                _result.tmp0 = (double[])tmp0.Clone();
                _result.tmpr2 = (double[,])tmpr2.Clone();
                _result.tmpa = tmpa!=null ? (sparse.sparsematrix)tmpa.make_copy() : null;
                _result.tmpal = (double[])tmpal.Clone();
                _result.tmpau = (double[])tmpau.Clone();
                _result.tmpsparse0 = tmpsparse0!=null ? (sparse.sparsematrix)tmpsparse0.make_copy() : null;
                _result.tmplowerh = tmplowerh!=null ? (sparse.sparsematrix)tmplowerh.make_copy() : null;
                _result.tmpccorr = (double[,])tmpccorr.Clone();
                _result.tmpdcorr = (double[])tmpdcorr.Clone();
                return _result;
            }
        };




        public const int spsymmfacttype = 21;
        public const double muquasidense = 10.0;
        public const double mupromote = 10.0;
        public const int defipmits = 200;
        public const double initslackval = 100.0;
        public const double steplengthdecay = 0.95;
        public const double stagnationdelta = 0.99999;
        public const double primalinfeasible1 = 1.0E-3;
        public const double dualinfeasible1 = 1.0E-3;
        public const double bigy = 1.0E8;
        public const double ygrowth = 1.0E6;
        public const int itersfortoostringentcond = 25;
        public const int minitersbeforeinfeasible = 3;
        public const int minitersbeforestagnation = 5;
        public const int minitersbeforeeworststagnation = 15;
        public const int primalstagnationlen = 5;
        public const int dualstagnationlen = 7;
        public const double minitersbeforesafeguards = 5;
        public const double badsteplength = 1.0E-3;


        /*************************************************************************
        Initializes QP-IPM state and prepares it to receive quadratic/linear terms
        and constraints.

        INPUT PARAMETERS:
            State       -   solver  state  to  be configured; previously allocated
                            memory is reused as much as possible
            S           -   scale vector, array[N]:
                            * I-th element contains scale of I-th variable,
                            * S[I]>0
            XOrigin     -   origin term, array[N]. Can be zero. The solver solves
                            problem of the form
                            >
                            > min(0.5*(x-x_origin)'*A*(x-x_origin)+b'*(x-x_origin))
                            >
                            The terms A and b (as well as constraints) will be
                            specified later with separate calls.
            N           -   total number of variables, N>=1
            TargetScale -   target scale:
                            * >=0
                            * recommended to be max(nrm2(C),nrm2(H+corr))
                            * if zero, autodetected by performing several iterations
                              of a subspace eigensolver

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void ipm2init(ipm2state state,
            double[] s,
            double[] xorigin,
            int nuser,
            double[,] denseh,
            sparse.sparsematrix sparseh,
            int hkind,
            bool isupper,
            double[,] ccorr,
            double[] dcorr,
            int kcorr,
            double[] c,
            double targetscale,
            double[] bndl,
            double[] bndu,
            sparse.sparsematrix sparsea,
            int msparse,
            double[,] densea,
            int mdense,
            double[] cl,
            double[] cu,
            bool uniformlcscale,
            bool skipnormalization,
            alglib.xparams _params)
        {
            int ntotal = 0;
            int naug = 0;
            int m = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            int j0 = 0;
            int j1 = 0;
            double v = 0;
            double vv = 0;
            int nnz = 0;
            int offs = 0;

            alglib.ap.assert(nuser>=1, "IPM2Init: N<1");
            alglib.ap.assert(apserv.isfinitevector(s, nuser, _params), "IPM2Init: S contains infinite or NaN elements");
            alglib.ap.assert(apserv.isfinitevector(xorigin, nuser, _params), "IPM2Init: XOrigin contains infinite or NaN elements");
            alglib.ap.assert(hkind==0 || hkind==1, "IPM2Init: incorrect HKind");
            alglib.ap.assert(apserv.isfinitevector(c, nuser, _params), "IPM2Init: C contains infinite or NaN elements");
            alglib.ap.assert(mdense>=0, "IPM2Init: MDense<0");
            alglib.ap.assert(msparse>=0, "IPM2Init: MSparse<0");
            alglib.ap.assert(apserv.apservisfinitematrix(densea, mdense, nuser, _params), "IPM2Init: DenseA contains infinite or NaN values!");
            alglib.ap.assert(msparse==0 || sparsea.matrixtype==1, "IPM2Init: non-CRS constraint matrix!");
            alglib.ap.assert(msparse==0 || (sparsea.m==msparse && sparsea.n==nuser), "IPM2Init: constraint matrix has incorrect size");
            alglib.ap.assert(alglib.ap.len(cl)>=mdense+msparse, "IPM2Init: CL is too short!");
            alglib.ap.assert(alglib.ap.len(cu)>=mdense+msparse, "IPM2Init: CU is too short!");
            alglib.ap.assert(kcorr>=0, "IPM2Init: KCorr<0");
            alglib.ap.assert(kcorr==0 || alglib.ap.rows(ccorr)>=kcorr, "IPM2Init: CCorr size is not KCorr*N, rows count is too small");
            alglib.ap.assert(kcorr==0 || alglib.ap.cols(ccorr)>=nuser, "IPM2Init: CCorr size is not KCorr*N, cols count is too small");
            alglib.ap.assert(kcorr==0 || alglib.ap.len(dcorr)>=kcorr, "IPM2Init: DCorr size is not [KCorr]");
            for(i=0; i<=kcorr-1; i++)
            {
                alglib.ap.assert((double)(Math.Abs(dcorr[i]))==(double)(1), "IPM2Init: |DCorr[I]|<>1");
            }
            alglib.ap.assert(math.isfinite(targetscale) && (double)(targetscale)>=(double)(0), "IPM2Init: TargetScale<0 or is not finite number");
            
            //
            // Problem metrics, settings and type
            //
            ntotal = nuser+kcorr+msparse+mdense;
            naug = nuser+kcorr;
            state.nuser = nuser;
            state.naug = naug;
            state.ntotal = ntotal;
            state.islinear = false;
            state.hasuserpermutation = false;
            ipm2setcond(state, 0.0, 0.0, 0.0, _params);
            state.maxipmits = defipmits;
            
            //
            // Reports
            //
            state.repiterationscount = 0;
            state.repncholesky = 0;
            
            //
            // Trace
            //
            state.dotrace = false;
            state.dotimers = false;
            state.dodetailedtrace = false;
            
            //
            // Scale and origin
            //
            ablasf.rsetallocv(ntotal, 1.0, ref state.sclx, _params);
            ablasf.rsetallocv(ntotal, 1.0, ref state.invsclx, _params);
            ablasf.rsetallocv(ntotal, 0.0, ref state.xoriginx, _params);
            for(i=0; i<=nuser-1; i++)
            {
                alglib.ap.assert(s[i]>0.0, "IPM2Init: S[i] is non-positive");
                state.sclx[i] = s[i];
                state.invsclx[i] = 1/s[i];
                state.xoriginx[i] = xorigin[i];
            }
            
            //
            // Extended linear term
            //
            ablasf.rsetallocv(ntotal, 0.0, ref state.ce, _params);
            ablasf.rcopyv(nuser, c, state.ce, _params);
            
            //
            // Generate sparse lower triangular representation of the quadratic term H and dense
            // corrector CCorr/DCorr. Apply scaling and normalization.
            //
            state.tmplowerh.matrixtype = 1;
            state.tmplowerh.m = nuser;
            state.tmplowerh.n = nuser;
            ablasf.iallocv(nuser+1, ref state.tmplowerh.ridx, _params);
            if( hkind==0 )
            {
                
                //
                // Sparsify dense term, generate leading N*N part of HX
                //
                nnz = 0;
                for(i=0; i<=nuser-1; i++)
                {
                    nnz = nnz+1;
                    if( isupper )
                    {
                        j0 = i+1;
                        j1 = nuser-1;
                    }
                    else
                    {
                        j0 = 0;
                        j1 = i-1;
                    }
                    for(j=j0; j<=j1; j++)
                    {
                        if( denseh[i,j]!=0 )
                        {
                            nnz = nnz+1;
                        }
                    }
                }
                ablasf.iallocv(nnz+nuser, ref state.tmplowerh.idx, _params);
                ablasf.rallocv(nnz+nuser, ref state.tmplowerh.vals, _params);
                state.tmplowerh.ridx[0] = 0;
                offs = 0;
                vv = 0;
                for(i=0; i<=state.nuser-1; i++)
                {
                    
                    //
                    // Off-diagonal elements are copied only when nonzero
                    //
                    if( !isupper )
                    {
                        for(j=0; j<=i-1; j++)
                        {
                            if( denseh[i,j]!=0 )
                            {
                                v = denseh[i,j];
                                state.tmplowerh.idx[offs] = j;
                                state.tmplowerh.vals[offs] = v;
                                vv = vv+v;
                                offs = offs+1;
                            }
                        }
                    }
                    
                    //
                    // Diagonal element is always copied
                    //
                    v = denseh[i,i];
                    state.tmplowerh.idx[offs] = i;
                    state.tmplowerh.vals[offs] = v;
                    vv = vv+v;
                    offs = offs+1;
                    
                    //
                    // Off-diagonal elements are copied only when nonzero
                    //
                    if( isupper )
                    {
                        for(j=i+1; j<=nuser-1; j++)
                        {
                            if( denseh[i,j]!=0 )
                            {
                                v = denseh[i,j];
                                state.tmplowerh.idx[offs] = j;
                                state.tmplowerh.vals[offs] = v;
                                vv = vv+v;
                                offs = offs+1;
                            }
                        }
                    }
                    
                    //
                    // Finalize row
                    //
                    state.tmplowerh.ridx[i+1] = offs;
                }
                alglib.ap.assert(math.isfinite(vv), "VIPMSetQuadraticLinear: DenseH contains infinite or NaN values!");
                alglib.ap.assert(offs==nnz, "VIPMSetQuadraticLinear: integrity check failed");
                alglib.ap.assert(offs<=alglib.ap.len(state.tmplowerh.vals) && offs<=alglib.ap.len(state.tmplowerh.idx), "IPM2Init: integrity check failed");
                sparse.sparsecreatecrsinplace(state.tmplowerh, _params);
            }
            if( hkind==1 )
            {
                
                //
                // Copy sparse quadratic term, but make sure that we have diagonal elements
                // present (we add diagonal if it is not present)
                //
                alglib.ap.assert(sparseh.matrixtype==1, "VIPMSetQuadraticLinear: unexpected sparse matrix format");
                alglib.ap.assert(sparseh.m==nuser, "VIPMSetQuadraticLinear: unexpected sparse matrix size");
                alglib.ap.assert(sparseh.n==nuser, "VIPMSetQuadraticLinear: unexpected sparse matrix size");
                ablasf.iallocv(sparseh.ridx[nuser]+nuser, ref state.tmplowerh.idx, _params);
                ablasf.rallocv(sparseh.ridx[nuser]+nuser, ref state.tmplowerh.vals, _params);
                state.tmplowerh.ridx[0] = 0;
                offs = 0;
                vv = 0;
                for(i=0; i<=state.nuser-1; i++)
                {
                    
                    //
                    // Copy subdiagonal elements (if needed)
                    //
                    if( !isupper )
                    {
                        j0 = sparseh.ridx[i];
                        j1 = sparseh.didx[i]-1;
                        for(k=j0; k<=j1; k++)
                        {
                            v = sparseh.vals[k];
                            state.tmplowerh.idx[offs] = sparseh.idx[k];
                            state.tmplowerh.vals[offs] = v;
                            vv = vv+v;
                            offs = offs+1;
                        }
                    }
                    
                    //
                    // Diagonal element is always copied
                    //
                    v = 0;
                    if( sparseh.uidx[i]!=sparseh.didx[i] )
                    {
                        v = sparseh.vals[sparseh.didx[i]];
                    }
                    state.tmplowerh.idx[offs] = i;
                    state.tmplowerh.vals[offs] = v;
                    vv = vv+v;
                    offs = offs+1;
                    
                    //
                    // Copy superdiagonal elements (if needed)
                    //
                    if( isupper )
                    {
                        j0 = sparseh.uidx[i];
                        j1 = sparseh.ridx[i+1]-1;
                        for(k=j0; k<=j1; k++)
                        {
                            v = sparseh.vals[k];
                            state.tmplowerh.idx[offs] = sparseh.idx[k];
                            state.tmplowerh.vals[offs] = v;
                            vv = vv+v;
                            offs = offs+1;
                        }
                    }
                    
                    //
                    // Finalize row
                    //
                    state.tmplowerh.ridx[i+1] = offs;
                }
                alglib.ap.assert(math.isfinite(vv), "IPM2Init: SparseH contains infinite or NaN values!");
                alglib.ap.assert(offs<=alglib.ap.len(state.tmplowerh.vals) && offs<=alglib.ap.len(state.tmplowerh.idx), "IPM2Init: integrity check failed");
                sparse.sparsecreatecrsinplace(state.tmplowerh, _params);
            }
            if( isupper )
            {
                sparse.sparsecopytransposecrsbuf(state.tmplowerh, state.tmpsparse0, _params);
                sparse.sparsecopybuf(state.tmpsparse0, state.tmplowerh, _params);
            }
            if( kcorr>0 )
            {
                for(i=0; i<=kcorr-1; i++)
                {
                    alglib.ap.assert((double)(Math.Abs(dcorr[i]))==(double)(1.0), "IPM2: DCorr[i] is neither 1 nor -1");
                }
                ablasf.rcopyallocm(kcorr, state.nuser, ccorr, ref state.tmpccorr, _params);
                ablasf.rcopyallocv(kcorr, dcorr, ref state.tmpdcorr, _params);
            }
            lpqpserv.scalesparseqpinplace(state.sclx, state.nuser, state.tmplowerh, state.tmpccorr, state.tmpdcorr, kcorr, state.ce, _params);
            if( !skipnormalization )
            {
                if( (double)(targetscale)==(double)(0) )
                {
                    state.targetscale = lpqpserv.normalizesparseqpinplace(state.tmplowerh, false, state.tmpccorr, state.tmpdcorr, kcorr, state.ce, state.nuser, _params);
                    state.targetscale = apserv.coalesce(state.targetscale, 1.0, _params);
                }
                else
                {
                    v = 1/targetscale;
                    ablasf.rmulv(state.tmplowerh.ridx[state.nuser], v, state.tmplowerh.vals, _params);
                    ablasf.rmulv(ntotal, v, state.ce, _params);
                    for(k=0; k<=kcorr-1; k++)
                    {
                        ablasf.rmulr(state.nuser, Math.Sqrt(v), state.tmpccorr, k, _params);
                    }
                    state.targetscale = targetscale;
                }
            }
            else
            {
                state.targetscale = 1.0;
            }
            
            //
            // Extended quadratic term: copy, extend
            //
            // NOTE: we perform integrity check for inifinities/NANs by
            //       computing sum of all matrix elements and checking its
            //       value for being finite. It is a bit faster than checking
            //       each element individually.
            //
            state.sparsehe.matrixtype = 1;
            state.sparsehe.m = ntotal;
            state.sparsehe.n = ntotal;
            ablasf.iallocv(ntotal+1, ref state.sparsehe.ridx, _params);
            alglib.ap.assert(state.tmplowerh.matrixtype==1, "VIPMSetQuadraticLinear: unexpected sparse matrix format");
            alglib.ap.assert(state.tmplowerh.m==nuser, "VIPMSetQuadraticLinear: unexpected sparse matrix size");
            alglib.ap.assert(state.tmplowerh.n==nuser, "VIPMSetQuadraticLinear: unexpected sparse matrix size");
            ablasf.iallocv(state.tmplowerh.ridx[nuser]+kcorr*(nuser+1)+(state.ntotal-nuser), ref state.sparsehe.idx, _params);
            ablasf.rallocv(state.tmplowerh.ridx[nuser]+kcorr*(nuser+1)+(state.ntotal-nuser), ref state.sparsehe.vals, _params);
            state.sparsehe.ridx[0] = 0;
            offs = 0;
            vv = 0;
            for(i=0; i<=state.nuser-1; i++)
            {
                
                //
                // Copy subdiagonal elements (if needed)
                //
                j0 = state.tmplowerh.ridx[i];
                j1 = state.tmplowerh.didx[i]-1;
                for(k=j0; k<=j1; k++)
                {
                    v = state.tmplowerh.vals[k];
                    state.sparsehe.idx[offs] = state.tmplowerh.idx[k];
                    state.sparsehe.vals[offs] = v;
                    vv = vv+v;
                    offs = offs+1;
                }
                
                //
                // The diagonal element is always copied
                //
                v = 0;
                if( state.tmplowerh.uidx[i]!=state.tmplowerh.didx[i] )
                {
                    v = state.tmplowerh.vals[state.tmplowerh.didx[i]];
                }
                state.sparsehe.idx[offs] = i;
                state.sparsehe.vals[offs] = v;
                vv = vv+v;
                offs = offs+1;
                
                //
                // Finalize row
                //
                state.sparsehe.ridx[i+1] = offs;
            }
            alglib.ap.assert(math.isfinite(vv), "IPM2Init: SparseH contains infinite or NaN values!");
            for(i=state.nuser; i<=state.naug-1; i++)
            {
                
                //
                // Augmentation row
                //
                offs = state.sparsehe.ridx[i];
                for(j=0; j<=nuser-1; j++)
                {
                    if( state.tmpccorr[i-state.nuser,j]!=0.0 )
                    {
                        state.sparsehe.idx[offs] = j;
                        state.sparsehe.vals[offs] = state.tmpccorr[i-state.nuser,j];
                        offs = offs+1;
                    }
                }
                
                //
                // Diagonal element
                //
                state.sparsehe.idx[offs] = i;
                state.sparsehe.vals[offs] = -state.tmpdcorr[i-state.nuser];
                offs = offs+1;
                
                //
                // Finalize row
                //
                state.sparsehe.ridx[i+1] = offs;
            }
            for(i=state.naug; i<=state.ntotal-1; i++)
            {
                
                //
                // Extend with zeros
                //
                state.sparsehe.idx[offs] = i;
                state.sparsehe.vals[offs] = 0.0;
                offs = offs+1;
                state.sparsehe.ridx[i+1] = offs;
            }
            alglib.ap.assert(offs<=alglib.ap.len(state.sparsehe.vals) && offs<=alglib.ap.len(state.sparsehe.idx), "IPM2Init: integrity check failed");
            sparse.sparsecreatecrsinplace(state.sparsehe, _params);
            state.isdiagonalh = state.sparsehe.ridx[state.ntotal]==state.ntotal;
            
            //
            // Primary part of the box constraints
            //
            ablasf.rcopyallocv(state.nuser, bndl, ref state.rawbndl, _params);
            ablasf.rcopyallocv(state.nuser, bndu, ref state.rawbndu, _params);
            ablasf.rsetallocv(state.ntotal, Double.NegativeInfinity, ref state.bndle, _params);
            ablasf.rsetallocv(state.ntotal, Double.PositiveInfinity, ref state.bndue, _params);
            ablasf.bsetallocv(state.ntotal, false, ref state.hasbndle, _params);
            ablasf.bsetallocv(state.ntotal, false, ref state.hasbndue, _params);
            for(i=0; i<=state.nuser-1; i++)
            {
                state.hasbndle[i] = math.isfinite(bndl[i]);
                state.hasbndue[i] = math.isfinite(bndu[i]);
                alglib.ap.assert(!((state.hasbndle[i] && state.hasbndue[i]) && (double)(bndl[i])>(double)(bndu[i])), "IPM2Init: inconsistent range for box constraints");
                state.bndle[i] = bndl[i];
                state.bndue[i] = bndu[i];
            }
            lpqpserv.scaleshiftbcinplace(state.sclx, state.xoriginx, state.bndle, state.bndue, state.ntotal, _params);
            
            //
            // Linear constraints (sparsified):
            // * copy to TmpA, normalize here
            // * extend with slack variables, save to RawAE
            // * append constraint bounds to the extended box constraints
            //
            m = mdense+msparse;
            state.mraw = m;
            for(i=0; i<=m-1; i++)
            {
                alglib.ap.assert(math.isfinite(cl[i]) || Double.IsNegativeInfinity(cl[i]), "IPM2: CL is not finite number or -INF");
                alglib.ap.assert(math.isfinite(cu[i]) || Double.IsPositiveInfinity(cu[i]), "IPM2: CU is not finite number or +INF");
            }
            state.mraw = m;
            state.tmpa.m = m;
            state.tmpa.n = state.ntotal;
            ablasf.iallocv(m+1, ref state.tmpa.ridx, _params);
            state.tmpa.ridx[0] = 0;
            for(i=0; i<=msparse-1; i++)
            {
                offs = state.tmpa.ridx[i];
                ablasf.igrowv(offs+state.ntotal, ref state.tmpa.idx, _params);
                ablasf.rgrowv(offs+state.ntotal, ref state.tmpa.vals, _params);
                j0 = sparsea.ridx[i];
                j1 = sparsea.ridx[i+1]-1;
                for(j=j0; j<=j1; j++)
                {
                    state.tmpa.idx[offs] = sparsea.idx[j];
                    state.tmpa.vals[offs] = sparsea.vals[j];
                    offs = offs+1;
                }
                state.tmpa.ridx[i+1] = offs;
            }
            for(i=0; i<=mdense-1; i++)
            {
                offs = state.tmpa.ridx[msparse+i];
                ablasf.igrowv(offs+state.ntotal, ref state.tmpa.idx, _params);
                ablasf.rgrowv(offs+state.ntotal, ref state.tmpa.vals, _params);
                for(k=0; k<=state.nuser-1; k++)
                {
                    if( densea[i,k]!=0 )
                    {
                        state.tmpa.idx[offs] = k;
                        state.tmpa.vals[offs] = densea[i,k];
                        offs = offs+1;
                    }
                }
                state.tmpa.ridx[msparse+i+1] = offs;
            }
            sparse.sparsecreatecrsinplace(state.tmpa, _params);
            ablasf.rcopyallocv(m, cl, ref state.tmpal, _params);
            ablasf.rcopyallocv(m, cu, ref state.tmpau, _params);
            lpqpserv.scaleshiftsparselcinplace(state.sclx, state.xoriginx, state.ntotal, state.tmpa, m, state.tmpal, state.tmpau, _params);
            if( !skipnormalization )
            {
                if( uniformlcscale )
                {
                    lpqpserv.normalizesparselcinplaceuniform(state.tmpa, m, state.tmpal, state.tmpau, state.ntotal, ref state.ascales, true, _params);
                }
                else
                {
                    lpqpserv.normalizesparselcinplace(state.tmpa, m, state.tmpal, state.tmpau, state.ntotal, true, ref state.ascales, true, _params);
                }
            }
            else
            {
                ablasf.rsetallocv(m, 1.0, ref state.ascales, _params);
            }
            for(i=0; i<=m-1; i++)
            {
                if( state.ascales[i]==0.0 )
                {
                    state.ascales[i] = 1.0;
                }
            }
            state.rawae.m = m;
            state.rawae.n = state.ntotal;
            ablasf.iallocv(m+1, ref state.rawae.ridx, _params);
            state.rawae.ridx[0] = 0;
            for(i=0; i<=m-1; i++)
            {
                
                //
                // Copy I-th row of TmpA to RawAE, extend with slacks
                //
                offs = state.rawae.ridx[i];
                ablasf.igrowv(offs+state.ntotal, ref state.rawae.idx, _params);
                ablasf.rgrowv(offs+state.ntotal, ref state.rawae.vals, _params);
                j0 = state.tmpa.ridx[i];
                j1 = state.tmpa.ridx[i+1]-1;
                for(j=j0; j<=j1; j++)
                {
                    state.rawae.idx[offs] = state.tmpa.idx[j];
                    state.rawae.vals[offs] = state.tmpa.vals[j];
                    offs = offs+1;
                }
                state.rawae.idx[offs] = state.naug+i;
                state.rawae.vals[offs] = -1.0;
                offs = offs+1;
                state.rawae.ridx[i+1] = offs;
                
                //
                // Extend box constraints
                //
                state.bndle[state.naug+i] = state.tmpal[i];
                state.bndue[state.naug+i] = state.tmpau[i];
                state.hasbndle[state.naug+i] = math.isfinite(state.tmpal[i]);
                state.hasbndue[state.naug+i] = math.isfinite(state.tmpau[i]);
            }
            sparse.sparsecreatecrsinplace(state.rawae, _params);
            
            //
            // Global regularized, default state (zero)
            //
            state.greg = 0.0;
            
            //
            // Finite version of box constraints - infinities replaced by very big numbers.
            // Allows us to avoid conditional checks during KKT system generation.
            //
            ablasf.rallocv(state.ntotal, ref state.bndlef, _params);
            ablasf.rallocv(state.ntotal, ref state.bnduef, _params);
            for(i=0; i<=state.ntotal-1; i++)
            {
                state.bndlef[i] = apserv.rcase2(math.isfinite(state.bndle[i]), state.bndle[i], -(0.001*math.maxrealnumber), _params);
                state.bnduef[i] = apserv.rcase2(math.isfinite(state.bndue[i]), state.bndue[i], 0.001*math.maxrealnumber, _params);
            }
        }


        /*************************************************************************
        Sets global regularization for X and Y and origin

        INPUT PARAMETERS:
            State               -   instance initialized with one of the initialization
                                    functions
            RegXY               -   >=0, global regularization
            OriginX             -   array[NUser]
            OriginY             -   array[MSparse+MDense]

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void ipm2setreg(ipm2state state,
            double regxy,
            double[] originx,
            double[] originy,
            alglib.xparams _params)
        {
            alglib.ap.assert(math.isfinite(regxy) && (double)(regxy)>=(double)(0), "IPM2SetReg: RegXY is infinite or negative");
            alglib.ap.assert(alglib.ap.len(originx)>=state.nuser, "IPM2SetReg: OriginX is too short");
            alglib.ap.assert(alglib.ap.len(originy)>=state.mraw, "IPM2SetReg: OriginY is too short");
            alglib.ap.assert(apserv.isfinitevector(originx, state.nuser, _params), "IPM2SetReg: OriginX contains infinite values");
            alglib.ap.assert(apserv.isfinitevector(originy, state.mraw, _params), "IPM2SetReg: OriginY contains infinite values");
            state.greg = regxy;
            ablasf.rcopyallocv(state.nuser, originx, ref state.gregoriginxuser, _params);
            ablasf.rcopyallocv(state.mraw, originy, ref state.gregoriginyuser, _params);
        }


        /*************************************************************************
        Sets stopping criteria for QP-IPM solver.

        You can set all epsilon-values to one small value, about 1.0E-6.

        INPUT PARAMETERS:
            State               -   instance initialized with one of the initialization
                                    functions
            EpsP                -   maximum primal error allowed in the  solution,
                                    EpsP>=0. Zero will be  automatically  replaced
                                    by recommended default value,  which is  equal
                                    to 10*Sqrt(Epsilon) in the current version
            EpsD                -   maximum  dual  error allowed in the  solution,
                                    EpsP>=0. Zero will be  automatically  replaced
                                    by recommended default value,  which is  equal
                                    to 10*Sqrt(Epsilon) in the current version
            EpsGap              -   maximum  duality gap allowed in the  solution,
                                    EpsP>=0. Zero will be  automatically  replaced
                                    by recommended default value,  which is  equal
                                    to 10*Sqrt(Epsilon) in the current version

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void ipm2setcond(ipm2state state,
            double epsp,
            double epsd,
            double epsgap,
            alglib.xparams _params)
        {
            double sml = 0;

            alglib.ap.assert(math.isfinite(epsp) && (double)(epsp)>=(double)(0), "IPM2SetCond: EpsP is infinite or negative");
            alglib.ap.assert(math.isfinite(epsd) && (double)(epsd)>=(double)(0), "IPM2SetCond: EpsD is infinite or negative");
            alglib.ap.assert(math.isfinite(epsgap) && (double)(epsgap)>=(double)(0), "IPM2SetCond: EpsP is infinite or negative");
            sml = Math.Sqrt(math.machineepsilon);
            state.epsp = apserv.coalesce(epsp, sml, _params);
            state.epsd = apserv.coalesce(epsd, sml, _params);
            state.epsgap = apserv.coalesce(epsgap, sml, _params);
        }


        /*************************************************************************
        Sets maximum iterations count for IPM.

        INPUT PARAMETERS:
            State               -   instance initialized with one of the initialization
                                    functions
            MaxIts              -   maximum iterations count;
                                    recommended in 100..200.
                                    Zero means default value (200).

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void ipm2setmaxits(ipm2state state,
            int maxits,
            alglib.xparams _params)
        {
            alglib.ap.assert(maxits>=0, "IPM2SetMaxIts: MaxIts<0");
            state.maxipmits = maxits;
        }


        /*************************************************************************
        This function proposes user ordering for a KKT system, as accepted by
        IPM2SetOrdering().

        This function accepts linear constraints matrix and it assumes that the
        quadratic term is diagonal (a placeholder parameter is used to ensure that
        the caller is aware of the fact). Only sparsity patter is used, not specific
        coefficient values.

        It returns proposed ordering. An instance of IPM2State structure is passed
        to be used as a temporary buffer; its initial state is invalidated. However,
        large internal temporaries are left intact and memory allocated by them can
        be reused later.

        INPUT PARAMETERS:
            State               -   uninitialized or initialized instance
            N                   -   variables count
            IsDiagonalQ         -   must be true to confirm that the caller is aware
                                    of absence of support for non-diagonal quadratic
                                    terms
            HasBndL             -   array[N], I-th element is true if bound is finite
            HasBndU             -   array[N], I-th element is true if bound is finite
            C                   -   if M>0, sparse constraints in CRS format
            CL, CU              -   array[M], lower and upper bounds for linear
                                    constrains
            M                   -   >=0, linear constraints count
            P                   -   potentially preallocated buffer, array[N+M],
                                    resized if needed
            
        OUTPUT PARAMETERS:
            P                   -   array[N+M] that maps original indexes of a
                                    KKT matrix (between 0 and N-1 for variables,
                                    between N and N+M-1 for constraints) to
                                    permuted indexes
                                    
        NOTE: the function assumes that all variables are boxed
                                    
        NOTE: the optimizer also allows to work with QP problems with low rank
              correction applied to the quadratic term.
              
              This function and IPM2SetOrdering() assume that independently of
              modification actual sparsity pattern its rows are assumed to be dense
              and are moved to the end. So, these rows are not included into the
              analysis. It allows us to reuse the same ordering for multiple problems
              with varying correction sizes but the same sparsity pattern for the
              rest of problem.

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void ipm2proposeordering(ipm2state state,
            int n,
            bool isdiagonalq,
            bool[] hasbndl,
            bool[] hasbndu,
            sparse.sparsematrix c,
            double[] cl,
            double[] cu,
            int m,
            ref int[] p,
            alglib.xparams _params)
        {
            int offs = 0;
            int i = 0;
            int j = 0;
            int j0 = 0;
            int j1 = 0;
            int k = 0;
            int colthreshold = 0;
            int rowthreshold = 0;
            int sumcoldeg = 0;
            int sumrowdeg = 0;
            int groupcols = 0;
            int grouprows = 0;
            int groupequality = 0;
            int groupfree = 0;
            int densegroup = 0;

            alglib.ap.assert(isdiagonalq, "IPM2ProposeOrdering: does not support non-diagonal Q");
            
            //
            // Allocate sparse matrix
            //
            sumcoldeg = 0;
            sumrowdeg = 0;
            ablasf.isetallocv(n, 0, ref state.reducedsystem.coldegrees, _params);
            ablasf.isetallocv(m, 0, ref state.reducedsystem.rowdegrees, _params);
            state.reducedsystem.compactkkt.matrixtype = 1;
            state.reducedsystem.compactkkt.m = n+m;
            state.reducedsystem.compactkkt.n = n+m;
            ablasf.iallocv(state.reducedsystem.compactkkt.m+1, ref state.reducedsystem.compactkkt.ridx, _params);
            state.reducedsystem.compactkkt.ridx[0] = 0;
            for(i=0; i<=n-1; i++)
            {
                offs = state.reducedsystem.compactkkt.ridx[i];
                ablasf.igrowv(offs+1, ref state.reducedsystem.compactkkt.idx, _params);
                ablasf.rgrowv(offs+1, ref state.reducedsystem.compactkkt.vals, _params);
                state.reducedsystem.compactkkt.idx[offs] = i;
                state.reducedsystem.compactkkt.vals[offs] = 1.0;
                offs = offs+1;
                state.reducedsystem.compactkkt.ridx[i+1] = offs;
            }
            for(i=0; i<=m-1; i++)
            {
                offs = state.reducedsystem.compactkkt.ridx[n+i];
                ablasf.igrowv(offs+n+1, ref state.reducedsystem.compactkkt.idx, _params);
                ablasf.rgrowv(offs+n+1, ref state.reducedsystem.compactkkt.vals, _params);
                j0 = c.ridx[i];
                j1 = c.ridx[i+1]-1;
                for(j=j0; j<=j1; j++)
                {
                    k = c.idx[j];
                    state.reducedsystem.compactkkt.idx[offs] = k;
                    state.reducedsystem.compactkkt.vals[offs] = 1.0;
                    state.reducedsystem.rowdegrees[i] = state.reducedsystem.rowdegrees[i]+1;
                    state.reducedsystem.coldegrees[k] = state.reducedsystem.coldegrees[k]+1;
                    sumrowdeg = sumrowdeg+1;
                    sumcoldeg = sumcoldeg+1;
                    offs = offs+1;
                }
                state.reducedsystem.compactkkt.idx[offs] = n+i;
                state.reducedsystem.compactkkt.vals[offs] = 1.0;
                offs = offs+1;
                state.reducedsystem.compactkkt.ridx[n+i+1] = offs;
            }
            sparse.sparsecreatecrsinplace(state.reducedsystem.compactkkt, _params);
            
            //
            // Determine elimination priorities
            //
            colthreshold = (int)Math.Round(muquasidense*sumcoldeg/n)+1;
            rowthreshold = (int)Math.Round(muquasidense*sumrowdeg/apserv.coalesce(m, 1, _params))+1;
            if( (double)((double)sumcoldeg/(double)n)<=(double)(sumrowdeg/apserv.coalesce(m, 1, _params)) )
            {
                groupcols = 0;
                grouprows = 1;
            }
            else
            {
                groupcols = 1;
                grouprows = 0;
            }
            groupequality = 2;
            groupfree = 3;
            densegroup = Math.Max(groupfree, groupequality);
            ablasf.isetallocv(n+m, 0, ref state.reducedsystem.compactpriorities, _params);
            for(i=0; i<=n-1; i++)
            {
                state.reducedsystem.compactpriorities[i] = groupcols;
                if( !hasbndl[i] && !hasbndu[i] )
                {
                    state.reducedsystem.compactpriorities[i] = groupfree;
                }
                if( state.reducedsystem.coldegrees[i]>colthreshold )
                {
                    state.reducedsystem.compactpriorities[i] = densegroup;
                }
            }
            for(i=0; i<=m-1; i++)
            {
                state.reducedsystem.compactpriorities[n+i] = grouprows;
                if( (math.isfinite(cl[i]) && math.isfinite(cu[i])) && (double)(cl[i]-cu[i])<(double)(1000*Math.Sqrt(math.machineepsilon)*apserv.rmaxabs3(cl[i], cu[i], 1.0, _params)) )
                {
                    state.reducedsystem.compactpriorities[n+i] = groupequality;
                }
                if( state.reducedsystem.rowdegrees[i]>rowthreshold )
                {
                    state.reducedsystem.compactpriorities[n+i] = densegroup;
                }
            }
            if( !spchol.spsymmanalyze(state.reducedsystem.compactkkt, state.reducedsystem.compactpriorities, mupromote, densegroup, spsymmfacttype, 3, 1, state.reducedsystem.analysis, _params) )
            {
                alglib.ap.assert(false, "ReducedSystemPowerUp: critical integrity check failed, symbolically degenerate KKT system encountered");
            }
            ablasf.icopyallocv(n+m, state.reducedsystem.analysis.fillinperm, ref p, _params);
        }


        /*************************************************************************
        Sets KKT system ordering to that produced by IPM2ProposeOrdering().

        INPUT PARAMETERS:
            State               -   instance initialized with one of the initialization
                                    functions
            P                   -   array[N+M], ordering

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void ipm2setordering(ipm2state state,
            int[] p,
            alglib.xparams _params)
        {
            ablasf.icopyallocv(state.nuser+state.mraw, p, ref state.userpermutation, _params);
            state.hasuserpermutation = true;
        }


        /*************************************************************************
        Solve QP problem.

        INPUT PARAMETERS:
            State               -   solver instance
            DropBigBounds       -   If True, algorithm may drop box and linear constraints
                                    with huge bound values that destabilize algorithm.
            
        OUTPUT PARAMETERS:
            XS                  -   array[N], solution
            LagBC               -   array[N], Lagrange multipliers for box constraints
            LagLC               -   array[M], Lagrange multipliers for linear constraints
            TerminationType     -   completion code, positive values for success,
                                    negative for failures (XS constrains best point
                                    found so far):
                                    * -2    the task is either unbounded or infeasible;
                                            the IPM solver has difficulty distinguishing between these two.
                                    * +1    stopping criteria are met
                                    * +7    stopping criteria are too stringent

        RESULT:

        This function ALWAYS returns something  meaningful in XS, LagBC, LagLC - 
        either solution or the best point so far, even for negative TerminationType.

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        public static void ipm2optimize(ipm2state state,
            bool dropbigbounds,
            ref double[] xs,
            ref double[] lagbc,
            ref double[] laglc,
            ref int terminationtype,
            alglib.xparams _params)
        {
            int nuser = 0;
            int ntotal = 0;
            int m = 0;
            int i = 0;
            double regfree = 0;
            double dampeps = 0;
            double maxdampeps = 0;
            double dampepsmu = 0;
            double dampepszs = 0;
            int iteridx = 0;
            double mu0 = 0;
            double mu1 = 0;
            double alpha = 0;
            double alphaprev = 0;
            double alphac = 0;
            int primalstagnationcnt = 0;
            int dualstagnationcnt = 0;
            double errp2 = 0;
            double errd2 = 0;
            double errpinf = 0;
            double errdinf = 0;
            double preverrp2 = 0;
            double preverrd2 = 0;
            double errgap = 0;
            double eprimal = 0;
            double edual = 0;
            double egap = 0;
            double y0nrm = 0;
            double bady = 0;
            int bestiteridx = 0;
            double besterr = 0;
            double bestegap = 0;
            double besteprimal = 0;
            double bestedual = 0;
            bool loadbest = new bool();
            double mustop = 0;

            terminationtype = 0;

            nuser = state.nuser;
            ntotal = state.ntotal;
            m = state.mraw;
            state.dotrace = ap.istraceenabled("IPM", _params);
            state.dotimers = state.dotrace || ap.istraceenabled("TIMERS.IPM", _params);
            state.dodetailedtrace = state.dotrace && ap.istraceenabled("IPM.DETAILED", _params);
            
            //
            // Prepare outputs
            //
            ablasf.rsetallocv(nuser, 0.0, ref xs, _params);
            ablasf.rsetallocv(nuser, 0.0, ref lagbc, _params);
            ablasf.rsetallocv(m, 0.0, ref laglc, _params);
            
            //
            // Some integrity checks:
            // * we need PrimalStagnationLen<DualStagnationLen in order to be able to correctly
            //   detect infeasible instances (stagnated dual error is present in both infeasible
            //   and unbounded instances, so we should check for primal stagnation a few iters
            //   before checking for dual stagnation)
            //
            alglib.ap.assert(primalstagnationlen<dualstagnationlen, "IPM2: critical integrity failure - incorrect configuration parameters");
            
            //
            // Trace output (if needed), setup timers
            //
            if( state.dotimers )
            {
                apserv.stimerinit(state.timertotal, _params);
                apserv.stimerinit(state.timeranalyze, _params);
                apserv.stimerinit(state.timerfactorize, _params);
                apserv.stimerinit(state.timerspsymmsolve, _params);
                apserv.stimerinit(state.timerothersolve, _params);
                apserv.stimerstart(state.timertotal, _params);
            }
            if( state.dotrace || state.dotimers )
            {
                alglib.ap.trace("\n\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace("// IPM SOLVER STARTED                                                                             //\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
            }
            
            //
            // Prepare regularization coefficients:
            // * DampEps - damping coefficient for damped Newton step. Comes along with SafeDampEps 
            //   (threshold value when some safeguards are turned off in order to preserve convergence
            //   speed) and MaxDampEps - threshold value when we consider problem overregularized and stop.
            //
            regfree = Math.Pow(math.machineepsilon, 0.75);
            dampepsmu = math.machineepsilon;
            dampepszs = math.machineepsilon;
            dampeps = 10*math.machineepsilon;
            maxdampeps = Math.Sqrt(Math.Sqrt(math.machineepsilon));
            
            //
            // Set up initial state
            //
            state.repiterationscount = 0;
            state.repncholesky = 0;
            mustop = 100*math.machineepsilon;
            ipm2powerup(state, regfree, _params);
            varsinitfrom(state.best, state.current, _params);
            varsinitbyzero(state.delta, ntotal, m, _params);
            varsinitbyzero(state.corr, ntotal, m, _params);
            bestiteridx = -1;
            besterr = math.maxrealnumber;
            bestegap = math.maxrealnumber;
            besteprimal = math.maxrealnumber;
            bestedual = math.maxrealnumber;
            traceprogress(state, 0.0, 0.0, 0.0, _params);
            y0nrm = 0;
            y0nrm = Math.Max(y0nrm, ablasf.rmaxabsv(m, state.current.y, _params));
            y0nrm = Math.Max(y0nrm, ablasf.rmaxabsv(ntotal, state.current.z, _params));
            y0nrm = Math.Max(y0nrm, ablasf.rmaxabsv(ntotal, state.current.s, _params));
            
            //
            // Start iteration
            //
            loadbest = true;
            primalstagnationcnt = 0;
            dualstagnationcnt = 0;
            terminationtype = 7;
            errp2 = math.maxrealnumber;
            errd2 = math.maxrealnumber;
            alphaprev = 0.0;
            ipm2multiply(state, state.current.x, state.current.y, ref state.currenthx, ref state.currentax, ref state.currentaty, _params);
            mu0 = varscomputemu(state, state.current, _params);
            rhscomputeprimdual(state, state.current, state.currenthx, state.currentax, state.currentaty, state.rhstarget, _params);
            for(iteridx=0; iteridx<=state.maxipmits-1; iteridx++)
            {
                
                //
                // Trace beginning
                //
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format("=== PREDICTOR-CORRECTOR STEP {0,2:d} ====================================================================\n", iteridx));
                }
                
                //
                // Check regularization status, terminate if overregularized
                //
                if( (double)(dampeps)>=(double)(maxdampeps) )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> tried to increase regularization parameter, but it is too large\n");
                        alglib.ap.trace("> it is likely that stopping conditions are too stringent, stopping at the best point found so far\n");
                    }
                    terminationtype = 7;
                    break;
                }
                
                //
                // Precompute factorization
                //
                if( !reducedsystemcomputefactorization(state.reducedsystem, state, state.current, dampepsmu, dampepszs, dampeps, dampeps, _params) )
                {
                    
                    //
                    // KKT factorization failed.
                    // Increase regularization parameter and skip this iteration.
                    //
                    dampeps = 10*dampeps;
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> LDLT factorization failed due to rounding errors\n");
                        alglib.ap.trace(System.String.Format("> increasing DampEps coefficient to {0,0:E2}, skipping iteration\n", dampeps));
                    }
                    continue;
                }
                
                //
                // Mehrotra predictor-corrector.
                // Prepare initial predictor step
                //
                rhsrecomputegammapredictor(state, state.current, 0.0, state.rhstarget, _params);
                if( !reducedsystemsolve(state.reducedsystem, state, state.current, state.rhstarget, state.delta, _params) )
                {
                    
                    //
                    // Initial affine scaling step failed due to numerical errors.
                    // Increase regularization parameter and skip this iteration.
                    //
                    dampeps = 10*dampeps;
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> initial affine scaling step failed to decrease residual due to rounding errors\n");
                        alglib.ap.trace(System.String.Format("> increasing DampEps coefficient to {0,0:E2}, skipping iteration\n", dampeps));
                    }
                    continue;
                }
                ipm2computesteplength(state, state.current, state.delta, ref alpha, _params);
                mu1 = varscomputemutrial(state, state.current, state.delta, alpha, _params);
                
                //
                // Perform corrector step
                //
                rhsrecomputegammamehrotra(state, state.current, Math.Pow(mu1/(mu0+math.machineepsilon), 3)*mu0, state.delta, state.rhstarget, _params);
                if( !reducedsystemsolve(state.reducedsystem, state, state.current, state.rhstarget, state.corr, _params) )
                {
                    dampeps = 10*dampeps;
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> corrector failed to decrease residual due to rounding errors\n");
                        alglib.ap.trace(System.String.Format("> increasing DampEps coefficient to {0,0:E2}, skipping iteration\n", dampeps));
                    }
                    continue;
                }
                
                //
                // Finally, computing a step length and making a step
                //
                ipm2computesteplength(state, state.current, state.corr, ref alphac, _params);
                if( (double)(iteridx)>=(double)(minitersbeforesafeguards) && ((double)(alphac)<=(double)(badsteplength) && (double)(alphaprev)>(double)(badsteplength)) )
                {
                    
                    //
                    // Previous step was good, but this step is too short, likely to fail due to numerical errors.
                    // Increase regularization parameter and skip this iteration.
                    //
                    dampeps = 10*dampeps;
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> step length is too short (after having a good step before), suspecting rounding errors\n");
                        alglib.ap.trace(System.String.Format("> increasing DampEps coefficient to {0,0:E2}, skipping iteration\n", dampeps));
                    }
                    continue;
                }
                varsaddstep(state.current, state.corr, alphac, _params);
                apserv.inc(ref state.repiterationscount, _params);
                alphaprev = alphac;
                traceprogress(state, mu0, alpha, alphac, _params);
                ipm2multiply(state, state.current.x, state.current.y, ref state.currenthx, ref state.currentax, ref state.currentaty, _params);
                rhscomputeprimdual(state, state.current, state.currenthx, state.currentax, state.currentaty, state.rhstarget, _params);
                mu0 = varscomputemu(state, state.current, _params);
                
                //
                // Check stopping criteria
                // * primal and dual stagnation are checked only when following criteria are met:
                //   1) Mu is smaller than 1 (we already converged close enough)
                //   2) we performed more than MinItersBeforeStagnation iterations
                //
                preverrp2 = errp2;
                preverrd2 = errd2;
                computeerrors(state, state.rhstarget, state.currenthx, state.currentax, state.currentaty, ref errp2, ref errd2, ref errpinf, ref errdinf, ref errgap, _params);
                egap = errgap;
                eprimal = errpinf;
                edual = errdinf;
                if( (double)(apserv.rmax3(egap, eprimal, edual, _params))<(double)(besterr) )
                {
                    
                    //
                    // Save best point found so far
                    //
                    varsinitfrom(state.best, state.current, _params);
                    bestiteridx = iteridx;
                    besterr = apserv.rmax3(egap, eprimal, edual, _params);
                    bestegap = egap;
                    besteprimal = eprimal;
                    bestedual = edual;
                }
                if( bestiteridx>0 && iteridx>bestiteridx+minitersbeforeeworststagnation )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> worst of primal/dual/gap errors stagnated for {0,0:d} its, stopping at the best point found so far\n", minitersbeforeeworststagnation));
                    }
                    break;
                }
                if( (((double)(egap)<=(double)(state.epsgap) && (double)(errp2)>=(double)(stagnationdelta*preverrp2)) && (double)(errpinf)>=(double)(primalinfeasible1)) && iteridx>=minitersbeforestagnation )
                {
                    apserv.inc(ref primalstagnationcnt, _params);
                    if( primalstagnationcnt>=primalstagnationlen )
                    {
                        if( state.dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> primal error stagnated for {0,0:d} its, stopping at the best point found so far\n", primalstagnationlen));
                        }
                        break;
                    }
                }
                else
                {
                    primalstagnationcnt = 0;
                }
                if( (((double)(egap)<=(double)(state.epsgap) && (double)(errd2)>=(double)(stagnationdelta*preverrd2)) && (double)(errdinf)>=(double)(dualinfeasible1)) && iteridx>=minitersbeforestagnation )
                {
                    apserv.inc(ref dualstagnationcnt, _params);
                    if( dualstagnationcnt>=dualstagnationlen )
                    {
                        if( state.dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> dual error stagnated for {0,0:d} its, stopping at the best point found so far\n", dualstagnationlen));
                        }
                        break;
                    }
                }
                else
                {
                    dualstagnationcnt = 0;
                }
                if( (double)(mu0)<=(double)(mustop) && iteridx>=itersfortoostringentcond )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> stopping conditions are too stringent, stopping at the best point found so far\n");
                    }
                    terminationtype = 7;
                    break;
                }
                if( ((double)(egap)<=(double)(state.epsgap) && (double)(eprimal)<=(double)(state.epsp)) && (double)(edual)<=(double)(state.epsd) )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> stopping criteria are met\n");
                    }
                    terminationtype = 1;
                    loadbest = false;
                    break;
                }
                bady = bigy;
                bady = Math.Max(bady, ygrowth*y0nrm);
                bady = Math.Max(bady, ygrowth*ablasf.rmaxabsv(ntotal, state.current.x, _params));
                bady = Math.Max(bady, ygrowth*ablasf.rmaxabsv(ntotal, state.current.g, _params));
                bady = Math.Max(bady, ygrowth*ablasf.rmaxabsv(ntotal, state.current.t, _params));
                if( (double)(ablasf.rmaxabsv(m, state.current.y, _params))>=(double)(bady) && iteridx>=minitersbeforeinfeasible )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> |Y| increased beyond {0,0:E1}, stopping at the best point found so far\n", bady));
                    }
                    break;
                }
            }
            
            //
            // Load best point, perform some checks
            //
            if( loadbest )
            {
                
                //
                // Load best point
                //
                // NOTE: TouchReal() is used to avoid spurious compiler warnings about 'set but unused'
                //
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format("> the best point so far is one from iteration {0,0:d}\n", bestiteridx));
                }
                varsinitfrom(state.current, state.best, _params);
                apserv.touchreal(ref besteprimal, _params);
                apserv.touchreal(ref bestedual, _params);
                apserv.touchreal(ref bestegap, _params);
                
                //
                // If no error flags were set yet, check solution quality
                //
                bady = bigy;
                bady = Math.Max(bady, ygrowth*y0nrm);
                bady = Math.Max(bady, ygrowth*ablasf.rmaxabsv(ntotal, state.current.x, _params));
                bady = Math.Max(bady, ygrowth*ablasf.rmaxabsv(ntotal, state.current.g, _params));
                bady = Math.Max(bady, ygrowth*ablasf.rmaxabsv(ntotal, state.current.t, _params));
                if( terminationtype>0 && (double)(ablasf.rmaxabsv(m, state.current.y, _params))>=(double)(bady) )
                {
                    terminationtype = -2;
                    if( state.dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> |Y| increased beyond {0,0:E1}, declaring infeasibility/unboundedness\n", bady));
                    }
                }
                if( terminationtype>0 && (double)(besteprimal)>=(double)(primalinfeasible1) )
                {
                    terminationtype = -2;
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> primal error at the best point is too high, declaring infeasibility/unboundedness\n");
                    }
                }
                if( terminationtype>0 && (double)(bestedual)>=(double)(dualinfeasible1) )
                {
                    terminationtype = -2;
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> dual error at the best point is too high, declaring infeasibility/unboundedness\n");
                    }
                }
            }
            
            //
            // Output
            //
            for(i=0; i<=nuser-1; i++)
            {
                xs[i] = state.current.x[i];
                lagbc[i] = 0.0;
                if( state.hasgz[i] )
                {
                    lagbc[i] = lagbc[i]-state.current.z[i];
                }
                if( state.hasts[i] )
                {
                    lagbc[i] = lagbc[i]+state.current.s[i];
                }
            }
            for(i=0; i<=m-1; i++)
            {
                laglc[i] = -state.current.y[i];
            }
            
            //
            // Unscale point and Lagrange multipliers
            //
            lpqpserv.unscaleunshiftpointbc(state.sclx, state.xoriginx, state.rawbndl, state.rawbndu, state.bndle, state.bndue, state.hasbndle, state.hasbndue, xs, nuser, _params);
            for(i=0; i<=nuser-1; i++)
            {
                lagbc[i] = lagbc[i]*state.targetscale/state.sclx[i];
            }
            for(i=0; i<=m-1; i++)
            {
                laglc[i] = laglc[i]*state.targetscale/state.ascales[i];
            }
            
            //
            // Timers and reports
            //
            if( state.dotimers )
            {
                apserv.stimerstop(state.timertotal, _params);
                alglib.ap.trace("\n> printing internal timers (can be zero when run in OS-agnostic mode)\n");
                alglib.ap.trace(System.String.Format("> total time:            {0,10:F1} ms\n", apserv.stimergetms(state.timertotal, _params)));
                alglib.ap.trace(System.String.Format("> * in analyze:          {0,10:F1} ms\n", apserv.stimergetms(state.timeranalyze, _params)));
                alglib.ap.trace(System.String.Format("> * in factorize:        {0,10:F1} ms\n", apserv.stimergetms(state.timerfactorize, _params)));
                alglib.ap.trace(System.String.Format("> * in spsymmsolve():    {0,10:F1} ms\n", apserv.stimergetms(state.timerspsymmsolve, _params)));
                alglib.ap.trace(System.String.Format("> * in other solve:      {0,10:F1} ms\n", apserv.stimergetms(state.timerothersolve, _params)-apserv.stimergetms(state.timerspsymmsolve, _params)));
            }
        }


        /*************************************************************************
        Allocates place for variables of IPM and fills by zeros.

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void varsinitbyzero(ipm2vars vstate,
            int ntotal,
            int m,
            alglib.xparams _params)
        {
            alglib.ap.assert(ntotal>=1, "VarsInitByZero: NTotal<1");
            alglib.ap.assert(m>=0, "VarsInitByZero: M<0");
            vstate.ntotal = ntotal;
            vstate.m = m;
            ablasf.rsetallocv(ntotal, 0.0, ref vstate.x, _params);
            ablasf.rsetallocv(ntotal, 0.0, ref vstate.g, _params);
            ablasf.rsetallocv(ntotal, 0.0, ref vstate.t, _params);
            ablasf.rsetallocv(ntotal, 0.0, ref vstate.z, _params);
            ablasf.rsetallocv(ntotal, 0.0, ref vstate.s, _params);
            ablasf.rsetallocv(m, 0.0, ref vstate.y, _params);
        }


        /*************************************************************************
        Allocates place for variables of IPM and fills them by values of
        the source

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void varsinitfrom(ipm2vars vstate,
            ipm2vars vsrc,
            alglib.xparams _params)
        {
            alglib.ap.assert(vsrc.ntotal>=1, "VarsInitFrom: NTotal<1");
            alglib.ap.assert(vsrc.m>=0, "VarsInitFrom: M<0");
            vstate.ntotal = vsrc.ntotal;
            vstate.m = vsrc.m;
            ablasf.rcopyallocv(vsrc.ntotal, vsrc.x, ref vstate.x, _params);
            ablasf.rcopyallocv(vsrc.ntotal, vsrc.g, ref vstate.g, _params);
            ablasf.rcopyallocv(vsrc.ntotal, vsrc.t, ref vstate.t, _params);
            ablasf.rcopyallocv(vsrc.ntotal, vsrc.z, ref vstate.z, _params);
            ablasf.rcopyallocv(vsrc.ntotal, vsrc.s, ref vstate.s, _params);
            ablasf.rcopyallocv(vsrc.m, vsrc.y, ref vstate.y, _params);
        }


        /*************************************************************************
        Adds to variables direction vector times step length. Different
        lengths are used for primal and dual steps.

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        private static void varsaddstep(ipm2vars vstate,
            ipm2vars vdir,
            double stp,
            alglib.xparams _params)
        {
            ablasf.raddv(vstate.ntotal, stp, vdir.x, vstate.x, _params);
            ablasf.raddv(vstate.ntotal, stp, vdir.g, vstate.g, _params);
            ablasf.raddv(vstate.ntotal, stp, vdir.z, vstate.z, _params);
            ablasf.raddv(vstate.ntotal, stp, vdir.t, vstate.t, _params);
            ablasf.raddv(vstate.ntotal, stp, vdir.s, vstate.s, _params);
            ablasf.raddv(vstate.m, stp, vdir.y, vstate.y, _params);
        }


        /*************************************************************************
        Computes complementarity gap

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        private static double varscomputecomplementaritygap(ipm2vars vstate,
            alglib.xparams _params)
        {
            double result = 0;

            result = ablasf.rdotv(vstate.ntotal, vstate.g, vstate.z, _params)+ablasf.rdotv(vstate.ntotal, vstate.t, vstate.s, _params);
            return result;
        }


        /*************************************************************************
        Computes empirical value of the barrier parameter Mu

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        private static double varscomputemu(ipm2state state,
            ipm2vars vstate,
            alglib.xparams _params)
        {
            double result = 0;

            result = (ablasf.rdotv(state.ntotal, vstate.z, vstate.g, _params)+ablasf.rdotv(state.ntotal, vstate.s, vstate.t, _params))/apserv.coalesce(state.cntgz+state.cntts, 1, _params);
            return result;
        }


        /*************************************************************************
        Computes empirical value of the barrier parameter Mu at the trial point
        Current+Alpha*Delta without computing the point itself.

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static double varscomputemutrial(ipm2state state,
            ipm2vars current,
            ipm2vars delta,
            double alpha,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            int nx = 0;

            nx = state.ntotal;
            result = 0;
            for(i=0; i<=nx-1; i++)
            {
                result = result+(current.g[i]+alpha*delta.g[i])*(current.z[i]+alpha*delta.z[i]);
                result = result+(current.t[i]+alpha*delta.t[i])*(current.s[i]+alpha*delta.s[i]);
            }
            result = result/apserv.coalesce(state.cntgz+state.cntts, 1, _params);
            return result;
        }


        /*************************************************************************
        Computes

            Y := alpha*A*x + beta*Y

        where A is constraint matrix, X is user-specified source, Y is target.

        Beta can be zero (in this case original contents of Y is ignored).
        If Beta is nonzero, we expect that Y contains preallocated array.

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        private static void multiplygeax(ipm2state state,
            double alpha,
            double[] x,
            int offsx,
            double beta,
            ref double[] y,
            int offsax,
            alglib.xparams _params)
        {
            int m = 0;

            m = state.mraw;
            if( (double)(beta)==(double)(0) )
            {
                ablasf.rallocv(offsax+m, ref y, _params);
            }
            else
            {
                alglib.ap.assert(alglib.ap.len(y)>=offsax+m, "MultiplyGEAX: Y is too short");
            }
            if( (double)(alpha)!=(double)(0) && m!=0 )
            {
                sparse.sparsegemv(state.rawae, alpha, 0, x, offsx, beta, y, offsax, _params);
            }
        }


        /*************************************************************************
        Computes

            Y := alpha*A'*x + beta*Y

        where A is constraint matrix, X is user-specified source, Y is target.

        Beta can be zero, in this case we automatically reallocate target if it is
        too short (but do NOT reallocate it if its size is large enough).
        If Beta is nonzero, we expect that Y contains preallocated array.

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        private static void multiplygeatx(ipm2state state,
            double alpha,
            double[] x,
            int offsx,
            double beta,
            ref double[] y,
            int offsy,
            alglib.xparams _params)
        {
            int ntotal = 0;
            int m = 0;

            ntotal = state.ntotal;
            m = state.mraw;
            if( (double)(beta)==(double)(0) )
            {
                ablasf.rallocv(offsy+ntotal, ref y, _params);
                ablasf.rsetvx(ntotal, 0.0, y, offsy, _params);
            }
            else
            {
                alglib.ap.assert(alglib.ap.len(y)>=offsy+ntotal, "MultiplyGEATX: Y is too short");
                ablasf.rmulvx(ntotal, beta, y, offsy, _params);
            }
            if( (double)(alpha)!=(double)(0) && m!=0 )
            {
                sparse.sparsegemv(state.rawae, alpha, 1, x, offsx, 1.0, y, offsy, _params);
            }
        }


        /*************************************************************************
        Computes H*x, does not support advanced functionality of GEAX/GEATX

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void multiplyhx(ipm2state state,
            double[] x,
            ref double[] hx,
            alglib.xparams _params)
        {
            int ntotal = 0;
            int i = 0;

            ntotal = state.ntotal;
            ablasf.rallocv(ntotal, ref hx, _params);
            alglib.ap.assert(state.sparsehe.n==ntotal && state.sparsehe.m==ntotal, "IPM2MultiplyHX: sparse H has incorrect size");
            if( state.isdiagonalh )
            {
                
                //
                // H is known to be diagonal, much faster code can be used
                //
                ablasf.rcopyv(ntotal, state.diagr, hx, _params);
                ablasf.raddv(ntotal, 1.0, state.sparsehe.vals, hx, _params);
                ablasf.rmergemulv(ntotal, x, hx, _params);
            }
            else
            {
                
                //
                // H is a general sparse matrix, use generic sparse matrix-vector multiply
                //
                sparse.sparsesmv(state.sparsehe, false, x, ref hx, _params);
                for(i=0; i<=ntotal-1; i++)
                {
                    hx[i] = hx[i]+x[i]*state.diagr[i];
                }
            }
        }


        /*************************************************************************
        Computes products H*x, A*x, A^T*y

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void ipm2multiply(ipm2state state,
            double[] x,
            double[] y,
            ref double[] hx,
            ref double[] ax,
            ref double[] aty,
            alglib.xparams _params)
        {
            multiplygeax(state, 1.0, x, 0, 0.0, ref ax, 0, _params);
            multiplygeatx(state, 1.0, y, 0, 0.0, ref aty, 0, _params);
            multiplyhx(state, x, ref hx, _params);
        }


        /*************************************************************************
        This function "powers up" factorization, i.e. prepares some important
        temporaries. It should be called once prior to the first call to
        VIPMInitialPoint() or VIPMFactorize().

        Parameters:
            RegFree     -   regularization for free variables;
                            good value sqrt(MachineEpsilon)

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        private static void ipm2powerup(ipm2state state,
            double regfree,
            alglib.xparams _params)
        {
            int ntotal = 0;
            int m = 0;
            int i = 0;
            double initprimslack = 0;
            double initdualslack = 0;

            ntotal = state.ntotal;
            m = state.mraw;
            
            //
            // Set up information about presence of slack variables.
            // Compute diagonal regularization matrix R.
            //
            ablasf.bcopyallocv(ntotal, state.hasbndle, ref state.hasgz, _params);
            ablasf.bcopyallocv(ntotal, state.hasbndue, ref state.hasts, _params);
            ablasf.rsetallocv(ntotal, 0.0, ref state.diagr, _params);
            varsinitbyzero(state.current, ntotal, m, _params);
            ablasf.rsetallocv(ntotal, 0.0, ref state.maskgz, _params);
            ablasf.rsetallocv(ntotal, 0.0, ref state.maskts, _params);
            state.cntgz = 0;
            state.cntts = 0;
            for(i=0; i<=ntotal-1; i++)
            {
                if( state.hasgz[i] )
                {
                    state.maskgz[i] = 1.0;
                    state.cntgz = state.cntgz+1;
                }
                if( state.hasts[i] )
                {
                    state.maskts[i] = 1.0;
                    state.cntts = state.cntts+1;
                }
                if( !state.hasgz[i] && !state.hasts[i] )
                {
                    state.diagr[i] = regfree;
                }
            }
            
            //
            // Compute global regularizer for X and Y
            //
            if( (double)(state.greg)!=(double)(0) )
            {
                
                //
                // Compute diagonal modifications to LHS and RHS
                //
                ablasf.rsetallocv(ntotal+m, 0.0, ref state.gregdiag, _params);
                ablasf.rsetvx(state.nuser, -state.greg, state.gregdiag, 0, _params);
                ablasf.rsetvx(m, state.greg, state.gregdiag, ntotal, _params);
                ablasf.rallocv(ntotal, ref state.gregrhsx, _params);
                ablasf.rsetvx(state.nuser, state.greg, state.gregrhsx, 0, _params);
                ablasf.rsetvx(ntotal-state.nuser, 0.0, state.gregrhsx, state.nuser, _params);
                ablasf.rsetallocv(m, -state.greg, ref state.gregrhsy, _params);
                
                //
                // Combine X-origin and Y-origin
                //
                ablasf.rsetallocv(ntotal, 0.0, ref state.gregoriginx, _params);
                ablasf.rcopyv(state.nuser, state.gregoriginxuser, state.gregoriginx, _params);
                ablasf.rmergemulv(state.nuser, state.invsclx, state.gregoriginx, _params);
                ablasf.rcopyallocv(m, state.gregoriginyuser, ref state.gregoriginy, _params);
                ablasf.rmergemulv(m, state.ascales, state.gregoriginy, _params);
                ablasf.rmulv(m, 1/state.targetscale, state.gregoriginy, _params);
            }
            
            //
            // Initialize sparse system
            // Set up current primal and dual slacks
            //
            reducedsystempowerup(state.reducedsystem, state, state.current.x, state.current.y, _params);
            initprimslack = Math.Max(initslackval, ablasf.rmaxabsv(ntotal, state.current.x, _params));
            initdualslack = Math.Max(initslackval, ablasf.rmaxabsv(m, state.current.y, _params));
            ablasf.rsetv(ntotal, 0.0, state.current.g, _params);
            ablasf.rsetv(ntotal, 0.0, state.current.z, _params);
            ablasf.rsetv(ntotal, 0.0, state.current.t, _params);
            ablasf.rsetv(ntotal, 0.0, state.current.s, _params);
            for(i=0; i<=ntotal-1; i++)
            {
                if( state.hasgz[i] )
                {
                    state.current.g[i] = Math.Max(initprimslack, state.current.x[i]-state.bndle[i]);
                    state.current.z[i] = Math.Min(initdualslack, initprimslack*initdualslack/state.current.g[i]);
                }
                if( state.hasts[i] )
                {
                    state.current.t[i] = Math.Max(initprimslack, state.bndue[i]-state.current.x[i]);
                    state.current.s[i] = Math.Min(initdualslack, initprimslack*initdualslack/state.current.t[i]);
                }
            }
            
            //
            // Almost done
            //
            if( state.dotrace )
            {
                alglib.ap.trace("> initial point was generated\n");
            }
        }


        /*************************************************************************
        This function "powers up" reduced (NX+M)*(NX+M) system, i.e. prepares data
        structures to receive data necessary for the factorization and solution.

        It should be called once at the beginning of the optimization.

        This function also proposes initial X and Y by solving strongly damped
        augmented system. It expects X and Y to be preallocated arrays long enough
        to store the result.

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void reducedsystempowerup(ipm2reducedsystem s,
            ipm2state state,
            double[] x,
            double[] y,
            alglib.xparams _params)
        {
            int nuser = 0;
            int naug = 0;
            int ntotal = 0;
            int m = 0;
            int offs = 0;
            double v = 0;
            int i = 0;
            int j = 0;
            int j0 = 0;
            int j1 = 0;
            int k = 0;
            int colthreshold = 0;
            int rowthreshold = 0;
            int sumcoldeg = 0;
            int sumrowdeg = 0;
            int n0 = 0;
            int n1 = 0;
            int n2 = 0;
            int n3 = 0;
            int n4 = 0;
            int groupcols = 0;
            int grouprows = 0;
            int groupequality = 0;
            int groupfree = 0;
            int densegroup = 0;
            int denseupdatesgroup = 0;
            int orderingtouse = 0;

            nuser = state.nuser;
            naug = state.naug;
            ntotal = state.ntotal;
            m = state.mraw;
            
            //
            // Allocate sparse matrix
            //
            sumcoldeg = 0;
            sumrowdeg = 0;
            ablasf.isetallocv(naug, 0, ref s.coldegrees, _params);
            ablasf.isetallocv(m, 0, ref s.rowdegrees, _params);
            ablasf.rallocv(ntotal+m, ref s.extendedrawdiagonal, _params);
            s.compactkkt.matrixtype = 1;
            s.compactkkt.m = ntotal;
            s.compactkkt.n = ntotal;
            ablasf.iallocv(s.compactkkt.m+1, ref s.compactkkt.ridx, _params);
            s.compactkkt.ridx[0] = 0;
            for(i=0; i<=naug-1; i++)
            {
                offs = s.compactkkt.ridx[i];
                ablasf.igrowv(offs+naug+1, ref s.compactkkt.idx, _params);
                ablasf.rgrowv(offs+naug+1, ref s.compactkkt.vals, _params);
                
                //
                // Offdiagonal elements
                //
                j0 = state.sparsehe.ridx[i];
                j1 = state.sparsehe.didx[i]-1;
                for(j=j0; j<=j1; j++)
                {
                    k = state.sparsehe.idx[j];
                    s.compactkkt.idx[offs] = k;
                    s.compactkkt.vals[offs] = -state.sparsehe.vals[j];
                    s.coldegrees[i] = s.coldegrees[i]+1;
                    s.coldegrees[k] = s.coldegrees[k]+1;
                    sumcoldeg = sumcoldeg+2;
                    offs = offs+1;
                }
                
                //
                // Diagonal element
                //
                j1 = state.sparsehe.didx[i];
                s.extendedrawdiagonal[i] = -(state.sparsehe.vals[j1]+state.diagr[i]);
                s.compactkkt.idx[offs] = state.sparsehe.idx[j1];
                s.compactkkt.vals[offs] = s.extendedrawdiagonal[i];
                offs = offs+1;
                
                //
                // Done
                //
                s.compactkkt.ridx[i+1] = offs;
            }
            for(i=naug; i<=ntotal-1; i++)
            {
                alglib.ap.assert(state.sparsehe.ridx[i]==state.sparsehe.didx[i], "IPM2: integrity check 0546 failed");
                alglib.ap.assert(state.sparsehe.didx[i]==state.sparsehe.uidx[i]-1, "IPM2: integrity check 0547 failed");
                alglib.ap.assert((double)(state.sparsehe.vals[state.sparsehe.didx[i]])==(double)(0.0), "IPM2: integrity check 0548 failed");
                s.extendedrawdiagonal[i] = -(state.sparsehe.vals[state.sparsehe.didx[i]]+state.diagr[i]);
            }
            for(i=0; i<=m-1; i++)
            {
                alglib.ap.assert(state.rawae.ridx[i+1]>state.rawae.ridx[i], "IPM2: integrity check 1251 failed");
                alglib.ap.assert(state.rawae.idx[state.rawae.ridx[i+1]-1]==naug+i, "IPM2: integrity check 1252 failed");
                alglib.ap.assert((double)(state.rawae.vals[state.rawae.ridx[i+1]-1])==(double)(-1.0), "IPM2: integrity check 1253 failed");
                offs = s.compactkkt.ridx[naug+i];
                ablasf.igrowv(offs+naug+1, ref s.compactkkt.idx, _params);
                ablasf.rgrowv(offs+naug+1, ref s.compactkkt.vals, _params);
                j0 = state.rawae.ridx[i];
                j1 = state.rawae.ridx[i+1]-2;
                for(j=j0; j<=j1; j++)
                {
                    k = state.rawae.idx[j];
                    s.compactkkt.idx[offs] = k;
                    s.compactkkt.vals[offs] = state.rawae.vals[j];
                    s.rowdegrees[i] = s.rowdegrees[i]+1;
                    s.coldegrees[k] = s.coldegrees[k]+1;
                    sumrowdeg = sumrowdeg+1;
                    sumcoldeg = sumcoldeg+1;
                    offs = offs+1;
                }
                s.compactkkt.idx[offs] = naug+i;
                s.compactkkt.vals[offs] = 0.0;
                offs = offs+1;
                s.extendedrawdiagonal[ntotal+i] = 0.0;
                s.compactkkt.ridx[naug+i+1] = offs;
            }
            sparse.sparsecreatecrsinplace(s.compactkkt, _params);
            
            //
            // Determine elimination priorities
            //
            if( state.hasuserpermutation )
            {
                
                //
                // Use permutation proposed by user
                //
                ablasf.isetallocv(ntotal, -1, ref s.compactpriorities, _params);
                for(i=0; i<=state.nuser-1; i++)
                {
                    s.compactpriorities[i] = state.userpermutation[i];
                }
                for(i=state.nuser; i<=state.naug-1; i++)
                {
                    s.compactpriorities[i] = state.nuser+state.mraw+(i-state.nuser);
                }
                for(i=state.naug; i<=state.ntotal-1; i++)
                {
                    s.compactpriorities[i] = state.userpermutation[state.nuser+(i-state.naug)];
                }
                orderingtouse = -4;
                densegroup = 0;
            }
            else
            {
                
                //
                // Use AMD to determine elimination priorities
                //
                colthreshold = (int)Math.Round(muquasidense*sumcoldeg/naug)+1;
                rowthreshold = (int)Math.Round(muquasidense*sumrowdeg/apserv.coalesce(m, 1, _params))+1;
                if( (double)((double)sumcoldeg/(double)naug)<=(double)(sumrowdeg/apserv.coalesce(m, 1, _params)) )
                {
                    groupcols = 0;
                    grouprows = 1;
                }
                else
                {
                    groupcols = 1;
                    grouprows = 0;
                }
                groupequality = 2;
                groupfree = 3;
                densegroup = Math.Max(groupfree, groupequality);
                denseupdatesgroup = densegroup+1;
                ablasf.isetallocv(ntotal, 0, ref s.compactpriorities, _params);
                for(i=0; i<=nuser-1; i++)
                {
                    s.compactpriorities[i] = groupcols;
                    if( !state.hasbndle[i] && !state.hasbndue[i] )
                    {
                        s.compactpriorities[i] = groupfree;
                    }
                    if( s.coldegrees[i]>colthreshold )
                    {
                        s.compactpriorities[i] = densegroup;
                    }
                }
                for(i=nuser; i<=naug-1; i++)
                {
                    s.compactpriorities[i] = denseupdatesgroup;
                }
                for(i=0; i<=m-1; i++)
                {
                    s.compactpriorities[naug+i] = grouprows;
                    if( (state.hasbndle[naug+i] && state.hasbndue[naug+i]) && (double)(state.bndue[naug+i]-state.bndle[naug+i])<(double)(1000*Math.Max(state.epsp, Math.Sqrt(math.machineepsilon))*apserv.rmax3(Math.Abs(state.bndue[naug+i]), Math.Abs(state.bndle[naug+i]), 1.0, _params)) )
                    {
                        s.compactpriorities[naug+i] = groupequality;
                    }
                    if( s.rowdegrees[i]>rowthreshold )
                    {
                        s.compactpriorities[naug+i] = densegroup;
                    }
                }
                if( state.dotrace )
                {
                    n0 = 0;
                    n1 = 0;
                    n2 = 0;
                    n3 = 0;
                    n4 = 0;
                    for(i=0; i<=ntotal-1; i++)
                    {
                        if( s.compactpriorities[i]==0 )
                        {
                            apserv.inc(ref n0, _params);
                        }
                        if( s.compactpriorities[i]==1 )
                        {
                            apserv.inc(ref n1, _params);
                        }
                        if( s.compactpriorities[i]==2 )
                        {
                            apserv.inc(ref n2, _params);
                        }
                        if( s.compactpriorities[i]==3 )
                        {
                            apserv.inc(ref n3, _params);
                        }
                        if( s.compactpriorities[i]==4 )
                        {
                            apserv.inc(ref n4, _params);
                        }
                    }
                    alglib.ap.trace("> KKT matrix formed, elimination groups determined:\n");
                    if( groupcols==0 )
                    {
                        alglib.ap.trace(System.String.Format(">> group 0 (variables): {0,7:d} columns\n", n0));
                        alglib.ap.trace(System.String.Format(">> group 1 (equations): {0,7:d} columns\n", n1));
                    }
                    else
                    {
                        alglib.ap.trace(System.String.Format(">> group 0 (equations): {0,7:d} columns\n", n0));
                        alglib.ap.trace(System.String.Format(">> group 1 (variables): {0,7:d} columns\n", n1));
                    }
                    alglib.ap.trace(System.String.Format(">> group 2 (equality ): {0,7:d} columns\n", n2));
                    alglib.ap.trace(System.String.Format(">> group 3 (free     ): {0,7:d} columns\n", n3));
                    alglib.ap.trace(System.String.Format(">> group 4 (dense    ): {0,7:d} columns\n", n4));
                }
                orderingtouse = 3;
            }
            
            //
            // Analyze
            //
            apserv.stimerstartcond(state.timeranalyze, state.dotimers, _params);
            if( !spchol.spsymmanalyze(s.compactkkt, s.compactpriorities, mupromote, densegroup, spsymmfacttype, orderingtouse, 1, s.analysis, _params) )
            {
                alglib.ap.assert(false, "ReducedSystemPowerUp: critical integrity check failed, symbolically degenerate KKT system encountered");
            }
            apserv.stimerstopcond(state.timeranalyze, state.dotimers, _params);
            
            //
            // Prepare initial X and Y by solving strongly factorized system
            //
            alglib.ap.assert(alglib.ap.len(x)>=ntotal, "IPM2: integrity check 7400 failed");
            alglib.ap.assert(alglib.ap.len(y)>=m, "IPM2: integrity check 7401 failed");
            ablasf.rallocv(ntotal+m, ref s.extendedeffdiagonal, _params);
            for(i=0; i<=nuser-1; i++)
            {
                s.extendedeffdiagonal[i] = Math.Min(s.extendedrawdiagonal[i], 0.0)-1.0;
            }
            for(i=nuser; i<=naug-1; i++)
            {
                s.extendedeffdiagonal[i] = s.extendedrawdiagonal[i]+apserv.possign(s.extendedrawdiagonal[i], _params);
            }
            for(i=naug; i<=ntotal-1; i++)
            {
                s.extendedeffdiagonal[i] = Math.Min(s.extendedrawdiagonal[i], 0.0)-1.0;
            }
            for(i=ntotal; i<=ntotal+m-1; i++)
            {
                s.extendedeffdiagonal[i] = Math.Max(s.extendedrawdiagonal[i], 0.0)+1.0;
            }
            ablasf.rallocv(naug+m, ref s.compacteffdiagonal, _params);
            for(i=0; i<=naug-1; i++)
            {
                s.compacteffdiagonal[i] = s.extendedeffdiagonal[i];
            }
            for(i=0; i<=m-1; i++)
            {
                s.compacteffdiagonal[naug+i] = -(1/s.extendedeffdiagonal[naug+i])+s.extendedeffdiagonal[ntotal+i];
            }
            apserv.stimerstartcond(state.timerfactorize, state.dotimers, _params);
            spchol.spsymmreloaddiagonal(s.analysis, s.compacteffdiagonal, _params);
            if( !spchol.spsymmfactorize(s.analysis, _params) )
            {
                alglib.ap.assert(false, "ReducedSystemPowerUp: unexpected failure during decomposition of a strongly damped system");
            }
            apserv.stimerstopcond(state.timerfactorize, state.dotimers, _params);
            ablasf.rallocv(ntotal+m, ref s.extendedrhs, _params);
            ablasf.rcopyv(ntotal, state.ce, s.extendedrhs, _params);
            for(i=0; i<=m-1; i++)
            {
                v = 0;
                if( state.hasbndle[naug+i] && (double)(state.bndle[naug+i])>(double)(v) )
                {
                    v = state.bndle[naug+i];
                }
                if( state.hasbndue[naug+i] && (double)(state.bndue[naug+i])<(double)(v) )
                {
                    v = state.bndue[naug+i];
                }
                s.extendedrhs[ntotal+i] = v;
            }
            ablasf.rallocv(ntotal, ref s.compactrhs, _params);
            for(i=0; i<=naug-1; i++)
            {
                s.compactrhs[i] = s.extendedrhs[i];
            }
            for(i=0; i<=m-1; i++)
            {
                s.compactrhs[naug+i] = s.extendedrhs[ntotal+i]+s.extendedrhs[naug+i]/s.extendedeffdiagonal[naug+i];
            }
            apserv.stimerstartcond(state.timerspsymmsolve, state.dotimers, _params);
            spchol.spsymmsolve(s.analysis, s.compactrhs, _params);
            apserv.stimerstopcond(state.timerspsymmsolve, state.dotimers, _params);
            for(i=0; i<=naug-1; i++)
            {
                s.extendedrhs[i] = s.compactrhs[i];
            }
            for(i=0; i<=m-1; i++)
            {
                s.extendedrhs[ntotal+i] = s.compactrhs[naug+i];
                s.extendedrhs[naug+i] = (s.extendedrhs[naug+i]+s.compactrhs[naug+i])/s.extendedeffdiagonal[naug+i];
            }
            ablasf.rcopyvx(ntotal, s.extendedrhs, 0, x, 0, _params);
            ablasf.rcopyvx(m, s.extendedrhs, ntotal, y, 0, _params);
        }


        /*************************************************************************
        Generates precomputed temporary  vectors  and  KKT  factorization  at  the
        beginning of the current iteration.

        This function uses representation of QP problem as a box-constrained one
        with linear equality constraints A*x=0.

        On successful factorization returns True; on failure returns False - it is
        recommended to increase regularization parameter and try one more time.

        --- DESCRIPTION ----------------------------------------------------------


          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static bool reducedsystemcomputefactorization(ipm2reducedsystem redsys,
            ipm2state sstate,
            ipm2vars current,
            double dampepsmu,
            double dampepszs,
            double dampepsp,
            double dampepsd,
            alglib.xparams _params)
        {
            bool result = new bool();
            int naug = 0;
            int ntotal = 0;
            int m = 0;
            int i = 0;
            double gz = 0;
            double st = 0;
            double sumsq = 0;
            double errsq = 0;
            double badchol = 0;

            naug = sstate.naug;
            ntotal = sstate.ntotal;
            m = sstate.mraw;
            result = true;
            badchol = 1.0E50;
            
            //
            // Pivot out dT and dS, dG and dZ
            //
            ablasf.rallocv(ntotal, ref redsys.d0, _params);
            ablasf.rallocv(ntotal, ref redsys.d1, _params);
            ablasf.rallocv(ntotal, ref redsys.d2, _params);
            ablasf.rallocv(ntotal, ref redsys.d3, _params);
            ablasf.rallocv(ntotal, ref redsys.d4, _params);
            ablasf.rallocv(ntotal, ref redsys.d5, _params);
            ablasf.rallocv(ntotal, ref redsys.d6, _params);
            ablasf.rallocv(ntotal, ref redsys.d7, _params);
            ablasf.rallocv(ntotal+m, ref redsys.extendedeffdiagonal, _params);
            ablasf.rsetvx(ntotal, -dampepsp, redsys.extendedeffdiagonal, 0, _params);
            ablasf.rsetvx(m, dampepsd, redsys.extendedeffdiagonal, ntotal, _params);
            if( (double)(sstate.greg)>(double)(0) )
            {
                ablasf.raddv(ntotal+m, 1.0, sstate.gregdiag, redsys.extendedeffdiagonal, _params);
            }
            ablasf.raddv(ntotal+m, 1.0, redsys.extendedrawdiagonal, redsys.extendedeffdiagonal, _params);
            for(i=0; i<=ntotal-1; i++)
            {
                st = current.s[i]*current.t[i];
                redsys.d0[i] = 1/(dampepsmu+st);
                redsys.d1[i] = redsys.d0[i]*current.t[i];
                redsys.d3[i] = sstate.maskts[i]/(dampepszs+redsys.d1[i]*current.t[i]);
                gz = current.g[i]*current.z[i];
                redsys.d4[i] = 1/(dampepsmu+gz);
                redsys.d5[i] = redsys.d4[i]*current.g[i];
                redsys.d7[i] = sstate.maskgz[i]/(dampepszs+redsys.d5[i]*current.g[i]);
            }
            ablasf.raddv(ntotal, -1.0, redsys.d3, redsys.extendedeffdiagonal, _params);
            ablasf.raddv(ntotal, -1.0, redsys.d7, redsys.extendedeffdiagonal, _params);
            ablasf.rallocv(ntotal, ref redsys.compacteffdiagonal, _params);
            for(i=0; i<=naug-1; i++)
            {
                redsys.compacteffdiagonal[i] = redsys.extendedeffdiagonal[i];
            }
            for(i=0; i<=m-1; i++)
            {
                redsys.compacteffdiagonal[naug+i] = -(1/redsys.extendedeffdiagonal[naug+i])+redsys.extendedeffdiagonal[ntotal+i];
            }
            spchol.spsymmreloaddiagonal(redsys.analysis, redsys.compacteffdiagonal, _params);
            spchol.spsymmsetmodificationstrategy(redsys.analysis, 1, math.machineepsilon, badchol, 0.0, 0.0, _params);
            apserv.stimerstartcond(sstate.timerfactorize, sstate.dotimers, _params);
            if( !spchol.spsymmfactorize(redsys.analysis, _params) )
            {
                apserv.stimerstopcond(sstate.timerfactorize, sstate.dotimers, _params);
                result = false;
                return result;
            }
            apserv.stimerstopcond(sstate.timerfactorize, sstate.dotimers, _params);
            spchol.spsymmdiagerr(redsys.analysis, ref sumsq, ref errsq, _params);
            if( sstate.dotrace )
            {
                alglib.ap.trace(System.String.Format("LDLT-diag-err= {0,0:E3} (diagonal reproduction error)\n", Math.Sqrt(errsq/(1+sumsq))));
            }
            if( (double)(Math.Sqrt(errsq/(1+sumsq)))>(double)(Math.Sqrt(math.machineepsilon)) )
            {
                result = false;
                return result;
            }
            return result;
        }


        /*************************************************************************
        This function estimates primal and dual step lengths (subject to step
        decay parameter, which should be in [0,1] range).

        Current version returns same step lengths for primal and dual steps.

        INPUT PARAMETERS:
            State               -   solver state
            V0                  -   current point (we ignore one stored in State.Current)
            VS                  -   step direction
            StepDecay           -   decay parameter, the step is multiplied by this
                                    coefficient. 1.0 corresponds to full step
                                    length being returned. Values in (0,1] range.
            SeparateStep        -   separate step for primal and dual vars
            
        OUTPUT PARAMETERS:
            AlphaP              -   primal step (after applying decay coefficient)
            AlphaD              -   dual   step (after applying decay coefficient)

          -- ALGLIB --
             Copyright 01.11.2019 by Bochkanov Sergey
        *************************************************************************/
        private static void ipm2computesteplength(ipm2state state,
            ipm2vars current,
            ipm2vars delta,
            ref double alpha,
            alglib.xparams _params)
        {
            int ntotal = 0;
            int i = 0;

            alpha = 0;

            ntotal = state.ntotal;
            alpha = 1;
            for(i=0; i<=ntotal-1; i++)
            {
                
                //
                // Primal
                //
                if( delta.g[i]<0.0 )
                {
                    alpha = apserv.safeminposrv(current.g[i], -delta.g[i], alpha, _params);
                }
                if( delta.t[i]<0.0 )
                {
                    alpha = apserv.safeminposrv(current.t[i], -delta.t[i], alpha, _params);
                }
                
                //
                // Dual
                //
                if( delta.z[i]<0.0 )
                {
                    alpha = apserv.safeminposrv(current.z[i], -delta.z[i], alpha, _params);
                }
                if( delta.s[i]<0.0 )
                {
                    alpha = apserv.safeminposrv(current.s[i], -delta.s[i], alpha, _params);
                }
            }
            alpha = steplengthdecay*alpha;
        }


        /*************************************************************************
        Compute primal/dual errors and complementarity gap

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void computeerrors(ipm2state state,
            ipm2righthandside rhs,
            double[] currenthx,
            double[] currentax,
            double[] currentaty,
            ref double errp2,
            ref double errd2,
            ref double errpinf,
            ref double errdinf,
            ref double egap,
            alglib.xparams _params)
        {
            int m = 0;
            int ntotal = 0;
            int cntp2 = 0;
            int cntd2 = 0;
            double vtgt = 0;

            errp2 = 0;
            errd2 = 0;
            errpinf = 0;
            errdinf = 0;
            egap = 0;

            m = state.mraw;
            ntotal = state.ntotal;
            
            //
            // Compute primal error
            //
            cntp2 = 0;
            errp2 = 0;
            errpinf = 0;
            errp2 = errp2+ablasf.rdotv2(m, rhs.ea, _params);
            errpinf = Math.Max(errpinf, ablasf.rmaxabsv(m, rhs.ea, _params));
            cntp2 = cntp2+m;
            errp2 = errp2+ablasf.rdotv2(ntotal, rhs.el, _params);
            errpinf = Math.Max(errpinf, ablasf.rmaxabsv(ntotal, rhs.el, _params));
            cntp2 = cntp2+state.cntgz;
            errp2 = errp2+ablasf.rdotv2(ntotal, rhs.eu, _params);
            errpinf = Math.Max(errpinf, ablasf.rmaxabsv(ntotal, rhs.eu, _params));
            cntp2 = cntp2+state.cntts;
            errp2 = Math.Sqrt(errp2/apserv.coalesce(cntp2, 1, _params));
            
            //
            // Compute dual error
            //
            cntd2 = 0;
            errd2 = 0;
            errdinf = 0;
            errd2 = errd2+ablasf.rdotv2(ntotal, rhs.ed, _params);
            errdinf = Math.Max(errdinf, ablasf.rmaxabsv(ntotal, rhs.ed, _params));
            cntd2 = cntd2+m;
            errd2 = Math.Sqrt(errd2/apserv.coalesce(cntd2, 1, _params));
            
            //
            // Compute complementarity gap
            //
            vtgt = 0.5*ablasf.rdotv(ntotal, currenthx, state.current.x, _params)+ablasf.rdotv(ntotal, state.ce, state.current.x, _params);
            egap = varscomputecomplementaritygap(state.current, _params)/(1.0+Math.Abs(vtgt));
        }


        /*************************************************************************
        Evaluate progress so far, outputs trace data, if requested to do so.

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void traceprogress(ipm2state state,
            double muinit,
            double alphaaff,
            double alphafin,
            alglib.xparams _params)
        {
            int naug = 0;
            int mraw = 0;
            int ntotal = 0;
            double errp2 = 0;
            double errd2 = 0;
            double errpinf = 0;
            double errdinf = 0;
            double errgap = 0;

            naug = state.naug;
            mraw = state.mraw;
            ntotal = state.ntotal;
            if( !state.dotrace )
            {
                return;
            }
            
            //
            // Compute temporary products, RHS and errors
            //
            ipm2multiply(state, state.current.x, state.current.y, ref state.tmphx, ref state.tmpax, ref state.tmpaty, _params);
            rhscomputeprimdual(state, state.current, state.tmphx, state.tmpax, state.tmpaty, state.rhsprogress, _params);
            computeerrors(state, state.rhsprogress, state.tmphx, state.tmpax, state.tmpaty, ref errp2, ref errd2, ref errpinf, ref errdinf, ref errgap, _params);
            
            //
            // Print high-level information
            //
            alglib.ap.trace("--- step report ------------------------------------------------------------------------------------\n");
            alglib.ap.trace("> step information\n");
            alglib.ap.trace(System.String.Format("mu_init = {0,0:E3}    (at the beginning)\n", muinit));
            if( (double)(alphafin)!=(double)(0) )
            {
                alglib.ap.trace(System.String.Format("alphaA  = {0,0:E3} (initial affine scaling step)\n", alphaaff));
                alglib.ap.trace(System.String.Format("alphaR  = {0,0:E3} (refined step)\n", alphafin));
            }
            else
            {
                alglib.ap.trace(System.String.Format("alpha   = {0,0:E3}\n", alphaaff));
            }
            alglib.ap.trace(System.String.Format("mu_cur  = {0,0:E3}    (after the step)\n", varscomputemu(state, state.current, _params)));
            alglib.ap.trace("> errors\n");
            alglib.ap.trace(System.String.Format("errP    = {0,0:E3}    (primal infeasibility, inf-norm)\n", errpinf));
            alglib.ap.trace(System.String.Format("errD    = {0,0:E3}    (dual infeasibility,   inf-norm)\n", errdinf));
            alglib.ap.trace(System.String.Format("errGap  = {0,0:E3}    (complementarity gap)\n", errgap));
            alglib.ap.trace("> current point information (inf-norm, x-suffix stands for N raw vars, a-suffix stands for M slacks)\n");
            alglib.ap.trace(System.String.Format("|Xx|={0,8:E1},  |Xa|={1,8:E1},  |Gx|={2,8:E1},  |Tx|={3,8:E1},  |Ga|={4,8:E1},  |Ta|={5,8:E1}\n", maxabsrange(state.current.x, 0, naug, _params), maxabsrange(state.current.x, naug, ntotal, _params), maxabsrange(state.current.g, 0, naug, _params), maxabsrange(state.current.t, 0, naug, _params), maxabsrange(state.current.g, naug, ntotal, _params), maxabsrange(state.current.t, naug, ntotal, _params)));
            alglib.ap.trace(System.String.Format("                 |Y|={0,8:E1},  |Zx|={1,8:E1},  |Sx|={2,8:E1},  |Za|={3,8:E1},  |Sa|={4,8:E1}\n", maxabsrange(state.current.y, 0, mraw, _params), maxabsrange(state.current.z, 0, naug, _params), maxabsrange(state.current.s, 0, naug, _params), maxabsrange(state.current.z, naug, ntotal, _params), maxabsrange(state.current.s, naug, ntotal, _params)));
            
            //
            // Print variable stats, if required
            //
            if( state.dotrace )
            {
                alglib.ap.trace("--- variable statistics ----------------------------------------------------------------------------\n");
                alglib.ap.trace("> smallest values for nonnegative vars\n");
                alglib.ap.trace(System.String.Format("primal:                        minGx={0,8:E1}  minTx={1,8:E1}  minGa={2,8:E1}  minTa={3,8:E1}\n", minnz(state.current.g, 0, naug, _params), minnz(state.current.t, 0, naug, _params), minnz(state.current.g, naug, ntotal, _params), minnz(state.current.t, naug, ntotal, _params)));
                alglib.ap.trace(System.String.Format("dual:                          minZx={0,8:E1}  minSx={1,8:E1}  minGa={2,8:E1}  minSa={3,8:E1}\n", minnz(state.current.z, 0, naug, _params), minnz(state.current.s, 0, naug, _params), minnz(state.current.z, naug, ntotal, _params), minnz(state.current.s, naug, ntotal, _params)));
                alglib.ap.trace("> min and max complementary slackness\n");
                alglib.ap.trace(System.String.Format("min:                             GZx={0,8:E1}    TSx={1,8:E1}    GZa={2,8:E1}    TSa={3,8:E1}\n", minprodnz(state.current.g, state.current.z, 0, naug, _params), minprodnz(state.current.t, state.current.s, 0, naug, _params), minprodnz(state.current.g, state.current.z, naug, ntotal, _params), minprodnz(state.current.t, state.current.s, naug, ntotal, _params)));
                alglib.ap.trace(System.String.Format("max:                             GZx={0,8:E1}    TSx={1,8:E1}    GZa={2,8:E1}    TSa={3,8:E1}\n", maxprodnz(state.current.g, state.current.z, 0, naug, _params), maxprodnz(state.current.t, state.current.s, 0, naug, _params), maxprodnz(state.current.g, state.current.z, naug, ntotal, _params), maxprodnz(state.current.t, state.current.s, naug, ntotal, _params)));
            }
            alglib.ap.trace("\n");
        }


        /*************************************************************************
        Computes primal-dual right-hand side for a KKT system.

        GammaGZ and GammaTS are not computed by this function.

        INPUT PARAMETERS:
            State           -   IPM state
            Current         -   current point (used to compute RHS)
            CurrentHX       -   precomputed H*Current.X
            CurrentAX       -   precomputed A*Current.X
            CurrentATY      -   precomputed A'*Current.Y
            
        OUTPUT PARAMETERS:
            Rhs             -   RHS

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void rhscomputeprimdual(ipm2state state,
            ipm2vars current,
            double[] currenthx,
            double[] currentax,
            double[] currentaty,
            ipm2righthandside rhs,
            alglib.xparams _params)
        {
            int ntotal = 0;
            int m = 0;

            ntotal = state.ntotal;
            m = state.mraw;
            
            //
            // ED
            //
            ablasf.rallocv(ntotal, ref rhs.ed, _params);
            if( (double)(state.greg)>(double)(0) )
            {
                ablasf.rcopyv(ntotal, current.x, rhs.ed, _params);
                ablasf.raddv(ntotal, -1.0, state.gregoriginx, rhs.ed, _params);
                ablasf.rmergemulv(ntotal, state.gregrhsx, rhs.ed, _params);
                ablasf.raddv(ntotal, 1.0, state.ce, rhs.ed, _params);
            }
            else
            {
                ablasf.rcopyv(ntotal, state.ce, rhs.ed, _params);
            }
            ablasf.raddv(ntotal, -1.0, currentaty, rhs.ed, _params);
            ablasf.raddv(ntotal, 1.0, currenthx, rhs.ed, _params);
            ablasf.raddv(ntotal, -1.0, current.z, rhs.ed, _params);
            ablasf.raddv(ntotal, 1.0, current.s, rhs.ed, _params);
            
            //
            // EA
            //
            ablasf.rallocv(m, ref rhs.ea, _params);
            if( (double)(state.greg)>(double)(0) )
            {
                ablasf.rcopyv(m, current.y, rhs.ea, _params);
                ablasf.raddv(m, -1.0, state.gregoriginy, rhs.ea, _params);
                ablasf.rmergemulv(m, state.gregrhsy, rhs.ea, _params);
                ablasf.raddv(m, -1.0, currentax, rhs.ea, _params);
            }
            else
            {
                ablasf.rcopymulv(m, -1.0, currentax, rhs.ea, _params);
            }
            
            //
            // EL
            //
            ablasf.rcopyallocv(ntotal, state.bndlef, ref rhs.el, _params);
            ablasf.raddv(ntotal, -1.0, current.x, rhs.el, _params);
            ablasf.raddv(ntotal, 1.0, current.g, rhs.el, _params);
            ablasf.rmergemulv(ntotal, state.maskgz, rhs.el, _params);
            
            //
            // EU
            //
            ablasf.rcopyallocv(ntotal, current.x, ref rhs.eu, _params);
            ablasf.raddv(ntotal, 1.0, current.t, rhs.eu, _params);
            ablasf.raddv(ntotal, -1.0, state.bnduef, rhs.eu, _params);
            ablasf.rmergemulv(ntotal, state.maskts, rhs.eu, _params);
        }


        /*************************************************************************
        Recomputes GammaGZ/TS according to a predictor (affine scaling) step

        INPUT PARAMETERS:
            State           -   IPM state
            Current         -   current point (used to compute RHS)
            MuTarget        -   target Mu (can be zero),
                                used to compute GammaGZ and GammaST
            
        OUTPUT PARAMETERS:
            Rhs             -   RHS

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void rhsrecomputegammapredictor(ipm2state state,
            ipm2vars current,
            double mutarget,
            ipm2righthandside rhs,
            alglib.xparams _params)
        {
            int ntotal = 0;

            ntotal = state.ntotal;
            
            //
            // GammaGZ
            //
            ablasf.rallocv(ntotal, ref rhs.gammagz, _params);
            ablasf.rcopymulv(ntotal, mutarget, state.maskgz, rhs.gammagz, _params);
            ablasf.rnegmuladdv(ntotal, current.g, current.z, rhs.gammagz, _params);
            
            //
            // GammaTS
            //
            ablasf.rallocv(ntotal, ref rhs.gammats, _params);
            ablasf.rcopymulv(ntotal, mutarget, state.maskts, rhs.gammats, _params);
            ablasf.rnegmuladdv(ntotal, current.t, current.s, rhs.gammats, _params);
        }


        /*************************************************************************
        Recomputes GammaGZ/GammaTS part of RHS according to the Mehrotra corrector
        heuristic. The rest of the right-hand side is unchanged.

        INPUT PARAMETERS:
            State           -   IPM state
            Current         -   current point (used to compute RHS)
            MuTarget        -   target Mu, used to compute GammaGZ and GammaST
            Delta           -   affine-scaling step produced by predictor stage
                                of the Mehrotra algorithm
            
        OUTPUT PARAMETERS:
            Rhs             -   RHS.GammaGZ, Rhs.GammaTS are recomputed

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void rhsrecomputegammamehrotra(ipm2state state,
            ipm2vars current,
            double mutarget,
            ipm2vars deltaaff,
            ipm2righthandside rhs,
            alglib.xparams _params)
        {
            int ntotal = 0;

            ntotal = state.ntotal;
            
            //
            // GammaGZ
            //
            ablasf.rallocv(ntotal, ref rhs.gammagz, _params);
            ablasf.rcopymulv(ntotal, mutarget, state.maskgz, rhs.gammagz, _params);
            ablasf.rnegmuladdv(ntotal, current.g, current.z, rhs.gammagz, _params);
            ablasf.rnegmuladdv(ntotal, deltaaff.g, deltaaff.z, rhs.gammagz, _params);
            
            //
            // GammaTS
            //
            ablasf.rallocv(ntotal, ref rhs.gammats, _params);
            ablasf.rcopymulv(ntotal, mutarget, state.maskts, rhs.gammats, _params);
            ablasf.rnegmuladdv(ntotal, current.t, current.s, rhs.gammats, _params);
            ablasf.rnegmuladdv(ntotal, deltaaff.t, deltaaff.s, rhs.gammats, _params);
        }


        /*************************************************************************
        Solves KKT system with given right-hand side

        INPUT PARAMETERS:
            State           -   IPM state
            Current         -   current point (beginning of the iteration)
            RHS             -   right-hand side
            
        OUTPUT PARAMETERS:
            Delta           -   solution

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        private static bool reducedsystemsolve(ipm2reducedsystem redsys,
            ipm2state sstate,
            ipm2vars current,
            ipm2righthandside rhs,
            ipm2vars delta,
            alglib.xparams _params)
        {
            bool result = new bool();
            int naug = 0;
            int ntotal = 0;
            int m = 0;

            apserv.stimerstartcond(sstate.timerothersolve, sstate.dotimers, _params);
            naug = sstate.naug;
            ntotal = sstate.ntotal;
            m = sstate.mraw;
            ablasf.rallocv(ntotal+m, ref redsys.extendedrhs, _params);
            ablasf.rcopymuladdv(ntotal, redsys.d1, rhs.gammats, rhs.eu, redsys.d2, _params);
            ablasf.rcopymuladdv(ntotal, redsys.d5, rhs.gammagz, rhs.el, redsys.d6, _params);
            ablasf.rcopymuladdv(ntotal, redsys.d3, redsys.d2, rhs.ed, redsys.extendedrhs, _params);
            ablasf.rnegmuladdv(ntotal, redsys.d7, redsys.d6, redsys.extendedrhs, _params);
            ablasf.rcopyvx(m, rhs.ea, 0, redsys.extendedrhs, ntotal, _params);
            
            //
            // Reduce (NTotal+M)*(NTotal+M) extended system to a (N+M)*(N+M) compact one
            //
            ablasf.rallocv(m, ref redsys.vm0, _params);
            ablasf.rsetallocv(m, 1.0, ref redsys.um0, _params);
            ablasf.rcopyvx(m, redsys.extendedeffdiagonal, naug, redsys.vm0, 0, _params);
            ablasf.rmergedivv(m, redsys.vm0, redsys.um0, _params);
            ablasf.rcopyvx(m, redsys.extendedrhs, naug, redsys.vm0, 0, _params);
            ablasf.rallocv(m, ref redsys.vm1, _params);
            ablasf.rcopymuladdv(m, redsys.um0, redsys.vm0, rhs.ea, redsys.vm1, _params);
            ablasf.rcopyvx(naug, redsys.extendedrhs, 0, redsys.compactrhs, 0, _params);
            ablasf.rcopyvx(m, redsys.vm1, 0, redsys.compactrhs, naug, _params);
            apserv.stimerstartcond(sstate.timerspsymmsolve, sstate.dotimers, _params);
            spchol.spsymmsolve(redsys.analysis, redsys.compactrhs, _params);
            apserv.stimerstopcond(sstate.timerspsymmsolve, sstate.dotimers, _params);
            
            //
            // Perform backsubstitution
            //
            ablasf.raddvx(m, 1.0, redsys.compactrhs, naug, redsys.vm0, 0, _params);
            ablasf.rmergemulv(m, redsys.um0, redsys.vm0, _params);
            ablasf.rcopyvx(naug, redsys.compactrhs, 0, delta.x, 0, _params);
            ablasf.rcopyvx(m, redsys.vm0, 0, delta.x, naug, _params);
            ablasf.rcopyv(ntotal, redsys.d2, delta.s, _params);
            ablasf.raddv(ntotal, 1.0, delta.x, delta.s, _params);
            ablasf.rmergemulv(ntotal, redsys.d3, delta.s, _params);
            ablasf.rcopyv(ntotal, redsys.d6, delta.z, _params);
            ablasf.raddv(ntotal, -1.0, delta.x, delta.z, _params);
            ablasf.rmergemulv(ntotal, redsys.d7, delta.z, _params);
            ablasf.rcopynegmuladdv(ntotal, current.t, delta.s, rhs.gammats, delta.t, _params);
            ablasf.rcopynegmuladdv(ntotal, current.g, delta.z, rhs.gammagz, delta.g, _params);
            ablasf.rmergemulv(ntotal, redsys.d1, delta.t, _params);
            ablasf.rmergemulv(ntotal, redsys.d5, delta.g, _params);
            ablasf.rcopyvx(m, redsys.compactrhs, naug, delta.y, 0, _params);
            apserv.stimerstopcond(sstate.timerothersolve, sstate.dotimers, _params);
            result = true;
            return result;
        }


        /*************************************************************************
        Computes minimum nonzero value of the vector. Returns 0 if all components
        are nonpositive.

        INPUT PARAMETERS:
            X               -   vector
            N               -   length

          -- ALGLIB --
             Copyright 01.11.2020 by Bochkanov Sergey
        *************************************************************************/
        private static double minnz(double[] x,
            int n0,
            int n1,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            bool nz = new bool();

            result = 0;
            nz = false;
            for(i=n0; i<=n1-1; i++)
            {
                if( (double)(x[i])>(double)(0) )
                {
                    if( !nz )
                    {
                        result = x[i];
                        nz = true;
                    }
                    else
                    {
                        result = Math.Min(result, x[i]);
                    }
                }
            }
            return result;
        }


        /*************************************************************************
        Computes minimum product of nonzero components.
        Returns 0 if all components are nonpositive.

        INPUT PARAMETERS:
            X               -   vector
            Y               -   vector
            N               -   length

          -- ALGLIB --
             Copyright 01.11.2020 by Bochkanov Sergey
        *************************************************************************/
        private static double minprodnz(double[] x,
            double[] y,
            int n0,
            int n1,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            bool nz = new bool();

            result = 0;
            nz = false;
            for(i=n0; i<=n1-1; i++)
            {
                if( (double)(x[i])>(double)(0) && (double)(y[i])>(double)(0) )
                {
                    if( !nz )
                    {
                        result = x[i]*y[i];
                        nz = true;
                    }
                    else
                    {
                        result = Math.Min(result, x[i]*y[i]);
                    }
                }
            }
            return result;
        }


        /*************************************************************************
        Computes maximum product of nonzero components.
        Returns 0 if all components are nonpositive.

        INPUT PARAMETERS:
            X               -   vector
            Y               -   vector
            N               -   length

          -- ALGLIB --
             Copyright 01.11.2020 by Bochkanov Sergey
        *************************************************************************/
        private static double maxprodnz(double[] x,
            double[] y,
            int n0,
            int n1,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            bool nz = new bool();

            result = 0;
            nz = false;
            for(i=n0; i<=n1-1; i++)
            {
                if( (double)(x[i])>(double)(0) && (double)(y[i])>(double)(0) )
                {
                    if( !nz )
                    {
                        result = x[i]*y[i];
                        nz = true;
                    }
                    else
                    {
                        result = Math.Max(result, x[i]*y[i]);
                    }
                }
            }
            return result;
        }


        /*************************************************************************
        Computes maximum absolute value within a range of elements.
        Debug function, not optimized.

        INPUT PARAMETERS:
            X               -   vector
            R0,R1           -   range [R0,R1)

          -- ALGLIB --
             Copyright 01.11.2020 by Bochkanov Sergey
        *************************************************************************/
        private static double maxabsrange(double[] x,
            int r0,
            int r1,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;

            result = 0;
            for(i=r0; i<=r1-1; i++)
            {
                result = Math.Max(result, Math.Abs(x[i]));
            }
            return result;
        }


    }
