        public const double sqpdeltadecrease = 0.05;
        public const double sqpdeltaincrease = 0.99;
        public const double maxtrustraddecay = 0.1;
        public const double deftrustradgrowth = 1.41;
        public const double maxtrustradgrowth = 10.0;
        public const double momentumgrowth = 2;
        public const double augmentationfactor = 0.1;
        public const double definittrustrad = 0.1;
        public const double stagnationepsf = 1.0E-12;
        public const int fstagnationlimit = 20;
        public const int trustradstagnationlimit = 5;
        public const int defaultbfgsresetfreq = 999999;
        public const double sufficientdecreasesigma = 0.1;
        public const int xbfgsmemlen = 8;
        public const double xbfgsmaxhess = 1.0E6;
        public const double defsqpbigscale = 4.0;
        public const double defsqpsmallscale = 0.1;
        public const double sqpsmallscaledecrease = 0.5;
        public const double sqpmaxrescale = 10.0;
        public const double sqpminrescale = 0.1;
        public const int maxipmits = 100;


        public static void minfsqpinitbuf(double[] bndl,
            double[] bndu,
            double[] s,
            double[] x0,
            int n,
            sparse.sparsematrix sparsea,
            double[] al,
            double[] au,
            int[] lcsrcidx,
            int lccnt,
            double[] nl,
            double[] nu,
            int nnlc,
            optserv.nlpstoppingcriteria criteria,
            bool usedensebfgs,
            minfsqpstate state,
            alglib.xparams _params)
        {
            int i = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            double v = 0;
            double vv = 0;
            int nslack = 0;

            nslack = n+2*lccnt+2*nnlc;
            state.n = n;
            state.lccnt = lccnt;
            state.nnlc = nnlc;
            state.additsforctol = 0;
            state.ctol = 0;
            
            //
            // Prepare RCOMM state
            //
            state.rstate.ia = new int[4+1];
            state.rstate.ba = new bool[14+1];
            state.rstate.ra = new double[17+1];
            state.rstate.stage = -1;
            state.rstate.clear_handler();
            state.needfisj = false;
            state.xupdated = false;
            ablasf.rallocv(n, ref state.x, _params);
            ablasf.rallocv(1+nnlc, ref state.fi, _params);
            
            //
            // Allocate memory.
            //
            ablasf.rallocv(n, ref state.x0, _params);
            ablasf.rallocv(n, ref state.xprev, _params);
            apserv.rvectorsetlengthatleast(ref state.s, n, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndl, n, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndu, n, _params);
            apserv.rvectorsetlengthatleast(ref state.scaledbndl, n, _params);
            apserv.rvectorsetlengthatleast(ref state.scaledbndu, n, _params);
            apserv.rvectorsetlengthatleast(ref state.dtrial, nslack, _params);
            apserv.rvectorsetlengthatleast(ref state.d0, nslack, _params);
            apserv.rvectorsetlengthatleast(ref state.dmu, nslack, _params);
            apserv.rvectorsetlengthatleast(ref state.lagbcmult, n, _params);
            apserv.rvectorsetlengthatleast(ref state.dummylagbcmult, n, _params);
            apserv.rvectorsetlengthatleast(ref state.lagxcmult, lccnt+nnlc, _params);
            apserv.rvectorsetlengthatleast(ref state.dummylagxcmult, lccnt+nnlc, _params);
            ablasf.ballocv(nnlc, ref state.hasnl, _params);
            ablasf.ballocv(nnlc, ref state.hasnu, _params);
            ablasf.rallocv(nnlc, ref state.rawnl, _params);
            ablasf.rallocv(nnlc, ref state.rawnu, _params);
            
            //
            // Prepare scaled problem
            //
            for(i=0; i<=n-1; i++)
            {
                state.hasbndl[i] = math.isfinite(bndl[i]);
                state.hasbndu[i] = math.isfinite(bndu[i]);
                if( state.hasbndl[i] )
                {
                    state.scaledbndl[i] = bndl[i]/s[i];
                }
                if( state.hasbndu[i] )
                {
                    state.scaledbndu[i] = bndu[i]/s[i];
                }
                if( state.hasbndl[i] && state.hasbndu[i] )
                {
                    alglib.ap.assert((double)(bndl[i])<=(double)(bndu[i]), "SQP: integrity check failed, box constraints are inconsistent");
                }
                state.x0[i] = x0[i]/s[i];
                state.s[i] = s[i];
            }
            if( lccnt>0 )
            {
                ablasf.rsetallocv(lccnt, 1.0, ref state.lcscales, _params);
                ablasf.iallocv(lccnt, ref state.lcsrcidx, _params);
                ablasf.bsetallocv(lccnt, false, ref state.hasal, _params);
                ablasf.bsetallocv(lccnt, false, ref state.hasau, _params);
                ablasf.rallocv(lccnt, ref state.sclal, _params);
                ablasf.rallocv(lccnt, ref state.sclau, _params);
                sparse.sparsecopytocrsbuf(sparsea, state.scla, _params);
                for(i=0; i<=lccnt-1; i++)
                {
                    state.lcsrcidx[i] = lcsrcidx[i];
                    
                    //
                    // Scale and normalize linear constraints
                    //
                    vv = 0.0;
                    j0 = state.scla.ridx[i];
                    j1 = state.scla.ridx[i+1]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        v = state.scla.vals[jj]*s[state.scla.idx[jj]];
                        state.scla.vals[jj] = v;
                        vv = vv+v*v;
                    }
                    vv = apserv.coalesce(Math.Sqrt(vv), 1, _params);
                    state.lcscales[i] = vv;
                    vv = 1/vv;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        state.scla.vals[jj] = state.scla.vals[jj]*vv;
                    }
                    if( math.isfinite(al[i]) )
                    {
                        state.hasal[i] = true;
                        state.sclal[i] = al[i]*vv;
                    }
                    else
                    {
                        state.sclal[i] = Double.NegativeInfinity;
                    }
                    if( math.isfinite(au[i]) )
                    {
                        state.hasau[i] = true;
                        state.sclau[i] = au[i]*vv;
                    }
                    else
                    {
                        state.sclau[i] = Double.PositiveInfinity;
                    }
                }
            }
            for(i=0; i<=nnlc-1; i++)
            {
                state.hasnl[i] = math.isfinite(nl[i]);
                state.hasnu[i] = math.isfinite(nu[i]);
                state.rawnl[i] = nl[i];
                state.rawnu[i] = nu[i];
            }
            
            //
            // Initial enforcement of box constraints
            //
            for(i=0; i<=n-1; i++)
            {
                if( state.hasbndl[i] )
                {
                    state.x0[i] = Math.Max(state.x0[i], state.scaledbndl[i]);
                }
                if( state.hasbndu[i] )
                {
                    state.x0[i] = Math.Min(state.x0[i], state.scaledbndu[i]);
                }
            }
            
            //
            // Stopping criteria and settings
            //
            optserv.critcopy(criteria, state.criteria, _params);
            state.bfgsresetfreq = defaultbfgsresetfreq;
            state.usedensebfgs = usedensebfgs;
            state.inittrustrad = definittrustrad;
            
            //
            // Report fields
            //
            state.repterminationtype = 0;
            state.repbcerr = 0;
            state.repbcidx = -1;
            state.replcerr = 0;
            state.replcidx = -1;
            state.repnlcerr = 0;
            state.repnlcidx = -1;
            state.repsclerr = 0;
            state.repiterationscount = 0;
            
            //
            // Integrity checks
            //
            alglib.ap.assert((double)(sqpdeltadecrease)<(double)(sqpdeltaincrease), "MinSQP: integrity check failed");
        }


        /*************************************************************************
        This function sets the number additional iterations that can be  performed
        after reaching MaxIts limit, if the current  point  is  infeasible (scaled
        constraint violation is above CTol), but there was a feasible point in the
        optimization history.

        Up to AddIts iterations will be performed, with iterations being terminated
        immediately after reaching CTol level of error.

        INPUT PARAMETERS:
            State           -   solver state
            CTol            -   scaled constraint violation tolerance. Points with
                                violation below or at CTol are considered feasible
                                
                                Do not use zero value  because  it  is  likely  to
                                reject points with even a tiny violation of
                                constraints.

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void minfsqpsetadditsforctol(minfsqpstate state,
            int addits,
            double ctol,
            alglib.xparams _params)
        {
            state.additsforctol = addits;
            state.ctol = ctol;
        }


        /*************************************************************************
        This function sets initial trust radius

        INPUT PARAMETERS:
            State           -   solver state
            Rad0            -   initial trust radius, Rad0>0

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void minfsqpsetinittrustrad(minfsqpstate state,
            double rad0,
            alglib.xparams _params)
        {
            state.inittrustrad = rad0;
        }


        /*************************************************************************
        This function performs actual processing for  SQP  algorithm.  It  expects
        that caller redirects its reverse communication  requests NeedFiJ/XUpdated
        to external user who will provide analytic derivative (or  handle  reports
        about progress).

        In case external user does not have analytic derivative, it is responsibility
        of caller to intercept NeedFiJ request and  replace  it  with  appropriate
        numerical differentiation scheme.

        Results are stored:
        * point - in State.StepKX.X, State.StepKX.Fi

        IMPORTANT: this function works with scaled problem formulation; it is
                   responsibility of the caller to unscale request and scale
                   Jacobian.
                   
        NOTE: SMonitor is expected to be correctly initialized smoothness monitor.

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        public static bool minfsqpiteration(minfsqpstate state,
            optserv.smoothnessmonitor smonitor,
            bool userterminationneeded,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int lccnt = 0;
            int nnlc = 0;
            int i = 0;
            int j = 0;
            double v = 0;
            double vv = 0;
            double mx = 0;
            double deltamax = 0;
            double multiplyby = 0;
            double setscaleto = 0;
            double prevtrustrad = 0;
            bool trustradstagnated = new bool();
            double relativetargetdecrease = 0;
            bool dotrace = new bool();
            bool dotracelaconic = new bool();
            bool doprobingalways = new bool();
            bool doprobingonfailure = new bool();
            bool dodetailedtrace = new bool();
            bool meritfstagnated = new bool();
            double tgt0 = 0;
            double h0 = 0;
            double tgt1 = 0;
            double h1 = 0;
            double tol = 0;
            double stepklagval = 0;
            double stepknlagval = 0;
            double d2trustradratio = 0;
            double predictedchangemodel = 0;
            double predictedchangepenalty = 0;
            bool infinitiesdetected = new bool();
            bool failedtorecoverfrominfinities = new bool();
            bool isinfeasible = new bool();
            bool feasibilityrestoration = new bool();
            bool firstrestorationiteration = new bool();
            bool stepfailed = new bool();
            bool restartiteration = new bool();
            bool leavefeasibilityrestoration = new bool();

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rstate.stage>=0 )
            {
                n = state.rstate.ia[0];
                lccnt = state.rstate.ia[1];
                nnlc = state.rstate.ia[2];
                i = state.rstate.ia[3];
                j = state.rstate.ia[4];
                trustradstagnated = state.rstate.ba[0];
                dotrace = state.rstate.ba[1];
                dotracelaconic = state.rstate.ba[2];
                doprobingalways = state.rstate.ba[3];
                doprobingonfailure = state.rstate.ba[4];
                dodetailedtrace = state.rstate.ba[5];
                meritfstagnated = state.rstate.ba[6];
                infinitiesdetected = state.rstate.ba[7];
                failedtorecoverfrominfinities = state.rstate.ba[8];
                isinfeasible = state.rstate.ba[9];
                feasibilityrestoration = state.rstate.ba[10];
                firstrestorationiteration = state.rstate.ba[11];
                stepfailed = state.rstate.ba[12];
                restartiteration = state.rstate.ba[13];
                leavefeasibilityrestoration = state.rstate.ba[14];
                v = state.rstate.ra[0];
                vv = state.rstate.ra[1];
                mx = state.rstate.ra[2];
                deltamax = state.rstate.ra[3];
                multiplyby = state.rstate.ra[4];
                setscaleto = state.rstate.ra[5];
                prevtrustrad = state.rstate.ra[6];
                relativetargetdecrease = state.rstate.ra[7];
                tgt0 = state.rstate.ra[8];
                h0 = state.rstate.ra[9];
                tgt1 = state.rstate.ra[10];
                h1 = state.rstate.ra[11];
                tol = state.rstate.ra[12];
