            {
                ablasf.rallocv(n, ref state.tmplaggrad, _params);
                ablasf.rallocv(n, ref state.tmpcandlaggrad, _params);
                lagrangianfg(state, state.stepk.x, state.trustrad, state.stepk.fi, state.stepk.sj, state.lagbcmult, state.lagxcmult, true, ref stepklagval, state.tmplaggrad, _params);
                lagrangianfg(state, state.cand.x, state.trustrad, state.cand.fi, state.cand.sj, state.lagbcmult, state.lagxcmult, true, ref stepknlagval, state.tmpcandlaggrad, _params);
                optserv.hessianupdatev2(state.hess, state.stepk.x, state.tmplaggrad, state.cand.x, state.tmpcandlaggrad, 2, false, dotrace, 1, _params);
                if( dotrace )
                {
                    optserv.hessiangetdiagonal(state.hess, ref state.tmphdiag, _params);
                    alglib.ap.trace(">> printing information about Hessian:\n");
                    v = state.tmphdiag[0];
                    for(i=0; i<=n-1; i++)
                    {
                        v = Math.Min(v, state.tmphdiag[i]);
                    }
                    alglib.ap.trace(System.String.Format("mindiag(Bk) = {0,0:E3}\n", v));
                    v = state.tmphdiag[0];
                    for(i=0; i<=n-1; i++)
                    {
                        v = Math.Max(v, state.tmphdiag[i]);
                    }
                    alglib.ap.trace(System.String.Format("maxdiag(Bk) = {0,0:E3}\n", v));
                    alglib.ap.trace("\n");
                }
            }
            
            //
            // Analyze current step and decide what to do: to continue iteration or to restart it.
            //
            // The latter option has two possible choices: to restart it with trust radius decreased
            // (StepFailed=True) or with the same trust radius (StepFailed=False, performed when exiting
            // from the feasibility restoration phase).
            //
            // Depending on the outcome, we set/clear FeasibilityRestoration, RestartIteration and StepFailed.
            // Then we do some other work like printing trace logs, and finally restart iteration if needed.
            //
            if( feasibilityrestoration )
            {
                
                //
                // Feasibility restoration phase
                //
                if( (!firstrestorationiteration && !isinfeasible) && optserv.nlpfisacceptable1(state.filter, tgt0, h0, _params) )
                {
                    
                    //
                    // Exit restoration if initial point is feasible and acceptable, and we performed at least one restoration iteration
                    //
                    if( dotrace )
                    {
                        alglib.ap.trace("> the initial point is feasible and accepted by the filter, exiting feasibility restoration phase\n");
                    }
                    optserv.trustradresetmomentum(ref state.trustradgrowth, deftrustradgrowth, _params);
                    leavefeasibilityrestoration = true;
                    restartiteration = true;
                }
                else
                {
                    
                    //
                    // Check sufficient decrease condition for modified penalty
                    //
                    // NOTE: it is essential to have strict ">" for both conditions below in order to be able
                    //       to properly handle situations with zero predicted change
                    //
                    if( (double)(predictedchangepenalty)>(double)(0) || (double)(h1-h0)>(double)(sufficientdecreasesigma*predictedchangepenalty) )
                    {
                        if( dotrace )
                        {
                            alglib.ap.trace("> the sufficient decrease condition does not hold, decreasing trust radius\n");
                        }
                        restartiteration = true;
                        stepfailed = true;
                    }
                }
                meritfstagnated = (double)(Math.Abs(h1-h0))<=(double)(stagnationepsf*Math.Max(h0, h1));
                firstrestorationiteration = false;
            }
            else
            {
                
                //
                // SQP phase
                //
                if( !isacceptable(state, tgt0, h0, tgt1, h1, predictedchangemodel, predictedchangepenalty, dotrace, _params) )
                {
                    
                    //
                    // The point is not acceptable, decrease trust radius and retry
                    //
                    if( dotrace )
                    {
                        alglib.ap.trace("> decreasing trust radius\n");
                    }
                    restartiteration = true;
                    stepfailed = true;
                }
                meritfstagnated = (double)(Math.Abs(tgt1-tgt0))<=(double)(stagnationepsf*Math.Abs(tgt0)) && (double)(Math.Abs(h1-h0))<=(double)(stagnationepsf*Math.Max(h0, h1));
            }
            if( !dotrace )
            {
                goto lbl_7;
            }
            
            //
            // Perform agressive probing of the search direction - additional function evaluations
            // which help us to determine possible discontinuity and nonsmoothness of the problem
            //
            if( !(doprobingalways || (doprobingonfailure && stepfailed)) )
            {
                goto lbl_9;
            }
            optserv.smoothnessmonitorstartlagrangianprobing(smonitor, state.stepk.x, state.dtrial, 1.0, state.repiterationscount, -1, _params);
        lbl_11:
            if( !optserv.smoothnessmonitorprobelagrangian(smonitor, _params) )
            {
                goto lbl_12;
            }
            for(j=0; j<=n-1; j++)
            {
                state.probe.x[j] = smonitor.lagprobx[j];
                if( state.hasbndl[j] )
                {
                    state.probe.x[j] = Math.Max(state.probe.x[j], state.scaledbndl[j]);
                }
                if( state.hasbndu[j] )
                {
                    state.probe.x[j] = Math.Min(state.probe.x[j], state.scaledbndu[j]);
                }
            }
            sqpsendx(state, state.probe.x, _params);
            state.needfisj = true;
            if( dotrace )
            {
                apserv.stimerstart(state.timercallback, _params);
            }
            state.rstate.stage = 3;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_3:
            if( dotrace )
            {
                apserv.stimerstop(state.timercallback, _params);
            }
            state.needfisj = false;
            if( !sqpretrievefij(state, state.probe, _params) )
            {
                goto lbl_12;
            }
            ablasf.rcopyallocv(1+nnlc, state.probe.fi, ref smonitor.lagprobfi, _params);
            sparse2dense(state.probe.sj, ref smonitor.lagprobj, _params);
            smonitor.lagprobrawlag = rawlagrangian(state, state.probe.x, state.probe.fi, state.lagbcmult, state.lagxcmult, _params);
            predictedconstraints(state, state.stepk, state.probe.x, ref smonitor.lagprobcvpred, _params);
            targetandconstraints(state, state.probe, ref v, ref smonitor.lagprobcvactual, _params);
            goto lbl_11;
        lbl_12:
            alglib.ap.trace("*** --------------------------------------------------------------------------------------\n");
            alglib.ap.trace("*** |                                                                                    |\n");
            alglib.ap.trace("*** |              Probing search direction suggested by QP subproblem                   |\n");
            alglib.ap.trace("*** |                                                                                    |\n");
            alglib.ap.trace("*** | NOTE: the target/Lagrangian  may  increase  along  the  search  direction  due  to |\n");
            alglib.ap.trace("*** |       constraints enforcement steps or nonmonotonic steps of  the  fSQP.  However, |\n");
            alglib.ap.trace("*** |       they MUST be smooth and continuous.                                          |\n");
            alglib.ap.trace("*** |                                                                                    |\n");
            alglib.ap.trace("*** | NOTE: constraint violations column reports sub of absolute violations, thus it  is |\n");
            alglib.ap.trace("*** |       piecewise linear in nature. The predicted violation will be  monotonic  with |\n");
            alglib.ap.trace("*** |       respect to step length, the actual violation can be nonmonotonic and can  be |\n");
            alglib.ap.trace("*** |       nonsmooth due to sign changes. It is ok for the  actual violation to deviate |\n");
            alglib.ap.trace("*** |       from the prediction closer to the end of the step. However, they MUST  agree |\n");
            alglib.ap.trace("*** |       at the beginning of the line (have similar slopes), especially  for  smaller |\n");
            alglib.ap.trace("*** |       steps. Any major difference in slopes is a sign of an error in gradients.    |\n");
            alglib.ap.trace("*** |                                                                                    |\n");
            alglib.ap.trace("*** --------------------------------------------------------------------------------------\n");
            alglib.ap.trace("*** |  Step  | Lagrangian (unaugmentd)|    Target  function    |   L1 constraints error  |\n");
            alglib.ap.trace("*** |along  D|     must be smooth     |     must be smooth     |     can be nonsmooth    |\n");
            alglib.ap.trace("*** |        | function   |    slope  | function   |    slope  |   actual   |  predicted |\n");
            optserv.smoothnessmonitortracelagrangianprobingresultsx(smonitor, true, _params);
            alglib.ap.trace("\n");
        lbl_9:
            
            //
            // Output other information
            //
        lbl_7:
            if( leavefeasibilityrestoration )
            {
                feasibilityrestoration = false;
            }
            if( restartiteration )
            {
                if( stepfailed )
                {
                    state.trustrad = state.trustrad*0.5;
                    optserv.trustradresetmomentum(ref state.trustradgrowth, deftrustradgrowth, _params);
                }
                if( dotrace )
                {
                    alglib.ap.trace("> restarting iteration\n\n");
                }
                apserv.inc(ref state.repiterationscount, _params);
                goto lbl_5;
            }
            if( dotrace )
            {
                alglib.ap.trace("> the step was successfully performed\n");
            }
            if( (!feasibilityrestoration && ((double)(predictedchangemodel)>=(double)(0) || (double)(tgt1-tgt0)>(double)(sufficientdecreasesigma*predictedchangemodel))) && (double)(h0)>(double)(0) )
            {
                optserv.nlpfappend(state.filter, tgt0, h0, _params);
                if( dotrace )
                {
                    alglib.ap.trace(System.String.Format(">> the initial point was added to the filter ({0,0:d} entries in the filter)\n", state.filter.filtersize));
                }
            }
            if( dotrace )
            {
                alglib.ap.trace("\n");
            }
            
            //
            // Analyze merit F for stagnation
            //
            relativetargetdecrease = Math.Max(Math.Abs(tgt1-tgt0)/apserv.rmaxabs3(tgt0, tgt1, 1, _params), Math.Abs(h1-h0)/apserv.rmaxabs3(h0, h1, 1, _params));
            
            //
            // Move to new point
            // Report one more inner iteration
            // Update constraint violations
            //
            optserv.vfjcopy(state.cand, state.stepk, _params);
            failedtorecoverfrominfinities = false;
            sqpsendx(state, state.stepk.x, _params);
            state.f = state.stepk.fi[0]*state.fscaleszzz[0];
            state.xupdated = true;
            state.rstate.stage = 4;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_4:
            state.xupdated = false;
            optserv.checklc2violation(state.scla, state.sclal, state.sclau, state.lcsrcidx, lccnt, state.stepk.x, ref state.replcerr, ref state.replcidx, _params);
            optserv.unscaleandchecknlc2violation(state.stepk.fi, state.fscaleszzz, state.rawnl, state.rawnu, nnlc, ref state.repnlcerr, ref state.repnlcidx, _params);
            optserv.checknlc2violation(state.stepk.fi, state.scalednl, state.scalednu, nnlc, ref state.repsclerr, ref i, _params);
            state.repsclerr = apserv.rmaxabs3(state.repsclerr, state.repbcerr, state.replcerr, _params);
            state.werepointsbelowctol = state.werepointsbelowctol || (double)(state.repsclerr)<=(double)(state.ctol);
            
            //
            // Update trust region.
            //
            // NOTE: when trust region radius remains fixed for a long time it may mean that we 
            //       stagnated in eternal loop. In such cases we decrease it slightly in order
            //       to break possible loop. If such decrease was unnecessary, it may be easily
            //       fixed within few iterations.
            //
            trustradstagnated = true;
            prevtrustrad = state.trustrad;
            deltamax = 0;
            for(i=0; i<=n-1; i++)
            {
                deltamax = Math.Max(deltamax, Math.Abs(state.xprev[i]-state.stepk.x[i])/gettrustregionk(state.xprev, i, state.trustrad, _params));
            }
            if( (double)(deltamax)<=(double)(sqpdeltadecrease) )
            {
                state.trustrad = state.trustrad*Math.Max(deltamax/sqpdeltadecrease, maxtrustraddecay);
                trustradstagnated = false;
                optserv.trustradresetmomentum(ref state.trustradgrowth, deftrustradgrowth, _params);
            }
            if( (double)(deltamax)>=(double)(sqpdeltaincrease) )
            {
                state.trustrad = state.trustrad*state.trustradgrowth;
                trustradstagnated = false;
                optserv.trustradincreasemomentum(ref state.trustradgrowth, momentumgrowth, maxtrustradgrowth, _params);
            }
            else
            {
                optserv.trustradresetmomentum(ref state.trustradgrowth, deftrustradgrowth, _params);
            }
            state.trustradstagnationcnt = apserv.icase2(trustradstagnated, state.trustradstagnationcnt+1, 0, _params);
            if( state.trustradstagnationcnt>=trustradstagnationlimit )
            {
                
                //
                // Trust radius stagnated for too long, decrease it and reset stagnation counter
                //
                if( dotrace )
                {
                    alglib.ap.trace("> detected stagnation of a trust radius, forcing decrease\n");
                }
                state.trustrad = state.trustrad*0.5;
                state.trustradstagnationcnt = 0;
                optserv.trustradresetmomentum(ref state.trustradgrowth, deftrustradgrowth, _params);
            }
            
            //
            // Trace
            //
            if( dotrace )
            {
                alglib.ap.trace("\n--- iteration ends ---------------------------------------------------------------------------------\n");
                alglib.ap.trace(System.String.Format("deltaMax    = {0,0:F3} (ratio of step length to trust radius)\n", deltamax));
                alglib.ap.trace(System.String.Format("newTrustRad = {0,0:E3}", state.trustrad));
                if( (double)(state.trustrad)>(double)(prevtrustrad) )
                {
                    alglib.ap.trace(", trust radius increased");
                }
                if( (double)(state.trustrad)<(double)(prevtrustrad) )
                {
                    alglib.ap.trace(", trust radius decreased");
                }
                alglib.ap.trace("\n");
            }
            
            //
            // Advance outer iteration counter
            //
            apserv.inc(ref state.repiterationscount, _params);
            state.fstagnationcnt = apserv.icase2(meritfstagnated, state.fstagnationcnt+1, 0, _params);
            goto lbl_5;
        lbl_6:
            
            //
            // Almost done
            //
            if( infinitiesdetected )
            {
                state.repterminationtype = apserv.icase2(failedtorecoverfrominfinities, -8, state.repterminationtype+800, _params);
            }
            if( dotrace )
            {
                apserv.stimerstop(state.timertotal, _params);
                alglib.ap.trace("\n=== STOPPED ========================================================================================\n");
                if( infinitiesdetected && failedtorecoverfrominfinities )
                {
                    alglib.ap.trace("> infinities were detected, but we failed to recover by decreasing trust radius; declaring failure with the code -8\n");
                }
                alglib.ap.trace(System.String.Format("raw target:     {0,20:E12}\n", state.stepk.fi[0]*state.fscaleszzz[0]));
                alglib.ap.trace(System.String.Format("total time:     {0,10:F1} ms\n", apserv.stimergetms(state.timertotal, _params)));
                alglib.ap.trace(System.String.Format("* cbck:         {0,10:F1} ms\n", apserv.stimergetms(state.timercallback, _params)));
                alglib.ap.trace(System.String.Format("* QP gen:       {0,10:F1} ms\n", apserv.stimergetms(state.timerqpgen, _params)));
                alglib.ap.trace(System.String.Format("* IPM init:     {0,10:F1} ms\n", apserv.stimergetms(state.timeripminit, _params)));
                alglib.ap.trace(System.String.Format("* IPM solve:    {0,10:F1} ms\n", apserv.stimergetms(state.timeripmsolve, _params)));
            }
            if( dotracelaconic )
            {
                targetandconstraints(state, state.stepk, ref tgt0, ref h0, _params);
                alglib.ap.trace(System.String.Format("STOPPED                 {0,23:E15}    {1,14:E6}    {2,10:F3}s\n", tgt0*state.fscaleszzz[0], h0, 0.001*apserv.stimergetmsrunning(state.timertotal, _params)));
            }
            optserv.smoothnessmonitortracestatus(smonitor, dotrace, _params);
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rstate.ia[0] = n;
            state.rstate.ia[1] = lccnt;
            state.rstate.ia[2] = nnlc;
            state.rstate.ia[3] = i;
            state.rstate.ia[4] = j;
            state.rstate.ba[0] = trustradstagnated;
            state.rstate.ba[1] = dotrace;
            state.rstate.ba[2] = dotracelaconic;
            state.rstate.ba[3] = doprobingalways;
            state.rstate.ba[4] = doprobingonfailure;
            state.rstate.ba[5] = dodetailedtrace;
            state.rstate.ba[6] = meritfstagnated;
            state.rstate.ba[7] = infinitiesdetected;
            state.rstate.ba[8] = failedtorecoverfrominfinities;
            state.rstate.ba[9] = isinfeasible;
            state.rstate.ba[10] = feasibilityrestoration;
            state.rstate.ba[11] = firstrestorationiteration;
            state.rstate.ba[12] = stepfailed;
            state.rstate.ba[13] = restartiteration;
            state.rstate.ba[14] = leavefeasibilityrestoration;
            state.rstate.ra[0] = v;
            state.rstate.ra[1] = vv;
            state.rstate.ra[2] = mx;
            state.rstate.ra[3] = deltamax;
            state.rstate.ra[4] = multiplyby;
            state.rstate.ra[5] = setscaleto;
            state.rstate.ra[6] = prevtrustrad;
            state.rstate.ra[7] = relativetargetdecrease;
            state.rstate.ra[8] = tgt0;
            state.rstate.ra[9] = h0;
            state.rstate.ra[10] = tgt1;
            state.rstate.ra[11] = h1;
            state.rstate.ra[12] = tol;
            state.rstate.ra[13] = stepklagval;
            state.rstate.ra[14] = stepknlagval;
            state.rstate.ra[15] = d2trustradratio;
            state.rstate.ra[16] = predictedchangemodel;
            state.rstate.ra[17] = predictedchangepenalty;
            return result;
        }


        /*************************************************************************
        This function initializes SQP subproblem.
        Should be called once in the beginning of the optimization.

        INPUT PARAMETERS:
            SState          -   solver state
            Subsolver       -   SQP subproblem to initialize
                                
                                
        RETURN VALUE:
            True on success
            False on failure of the QP solver (unexpected... but possible due to numerical errors)
                                

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        private static void initqpsubsolver(minfsqpstate sstate,
            minfsqpsubsolver subsolver,
            alglib.xparams _params)
        {
            int n = 0;
            int nslack = 0;
            int nnlc = 0;
            int i = 0;
            int lccnt = 0;

            n = sstate.n;
            nnlc = sstate.nnlc;
            nslack = n+2*sstate.lccnt+2*nnlc;
            lccnt = sstate.lccnt+nnlc;
            
            //
            // Initial ordering state
            //
            ablasf.iallocv(n+lccnt, ref subsolver.ordering, _params);
            for(i=0; i<=n+lccnt-1; i++)
            {
                subsolver.ordering[i] = i;
            }
            ablasf.iallocv(nslack+lccnt, ref subsolver.elasticordering, _params);
            for(i=0; i<=nslack+lccnt-1; i++)
            {
                subsolver.elasticordering[i] = i;
            }
            sparse.sparsecreatecrsempty(n, subsolver.pattern, _params);
            for(i=0; i<=lccnt-1; i++)
            {
                sparse.sparseappendemptyrow(subsolver.pattern, _params);
            }
            sparse.sparsecreatecrsempty(nslack, subsolver.elasticpattern, _params);
            for(i=0; i<=lccnt-1; i++)
            {
                sparse.sparseappendemptyrow(subsolver.elasticpattern, _params);
            }
            
            //
            // Allocate temporaries
            //
            apserv.rvectorsetlengthatleast(ref subsolver.cural, lccnt, _params);
            apserv.rvectorsetlengthatleast(ref subsolver.curau, lccnt, _params);
            apserv.rvectorsetlengthatleast(ref subsolver.curbndl, nslack, _params);
            apserv.rvectorsetlengthatleast(ref subsolver.curbndu, nslack, _params);
            apserv.rvectorsetlengthatleast(ref subsolver.curb, nslack, _params);
            
            //
            // Linear constraints do not change across subiterations, that's
            // why we allocate storage for them at the start of the program.
            //
            // A full set of "raw" constraints is stored; later we will filter
            // out inequality ones which are inactive anywhere in the current
            // trust region.
            //
            // NOTE: because sparserawlc object stores only linear constraint
            //       (linearizations of nonlinear ones are not stored) we
            //       allocate only minimum necessary space.
            //
            if( sstate.lccnt>0 )
            {
                sparse.sparsecopytocrsbuf(sstate.scla, subsolver.sparserawlc, _params);
            }
            
            //
            // Initialize prior for regularization
            //
            ablasf.rsetallocv(lccnt, 0.0, ref subsolver.lastlaglc, _params);
        }


        /*************************************************************************
        This function solves QP subproblem
            
        This function returns:
        * search direction D[]
        * estimates of Lagrangian multipliers
        * predicted change in the quadratic model of the target, and in the L1-penalty
          added to the model

        Additionally it sets the following fields of the Subsolver:
        * Penalty0 - sum of constraint violations at the initial point X
        * Penalty1 - sum of constraint violations at X+D

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        private static bool qpsubproblemsolvesqp(minfsqpstate state,
            minfsqpsubsolver subsolver,
            optserv.varsfuncjac model,
            optserv.xbfgshessian hess,
            double[] d,
            double[] lagbcmult,
            double[] lagxcmult,
            bool dotrace,
            ref bool isinfeasible,
            ref int terminationtype,
            ref double predictedchangemodel,
            ref double predictedchangepenalty,
            ref double d2trustradratio,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int lccnt = 0;
            int nnlc = 0;
            int i = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int k = 0;
            double v = 0;
            double vv = 0;
            double vright = 0;
            double vmax = 0;
            double vmin = 0;
            int xccnt = 0;
            int offs = 0;
            int nnz = 0;
            bool bndlinactive = new bool();
            bool bnduinactive = new bool();
            double rescaleby = 0;
            double targetscale = 0;

            isinfeasible = new bool();
            terminationtype = 0;
            predictedchangemodel = 0;
            predictedchangepenalty = 0;
            d2trustradratio = 0;

            alglib.ap.assert(!model.isdense, "FSQP: integrity check 2314 failed");
            n = state.n;
            lccnt = state.lccnt;
            nnlc = state.nnlc;
            xccnt = lccnt+nnlc;
            
            //
            // Prepare temporary structures
            //
            apserv.rvectorgrowto(ref subsolver.cural, xccnt, _params);
            apserv.rvectorgrowto(ref subsolver.curau, xccnt, _params);
            ablasf.rallocv(xccnt, ref subsolver.rescalelag, _params);
            
            //
            // Prepare default solution: all zeros
            //
            result = true;
            terminationtype = 0;
            predictedchangemodel = 0;
            predictedchangepenalty = 0;
            d2trustradratio = 0.0;
            isinfeasible = false;
            subsolver.penalty0 = 0.0;
            subsolver.penalty1 = 0.0;
            ablasf.rsetv(n, 0.0, d, _params);
            ablasf.rsetv(n, 0.0, lagbcmult, _params);
            ablasf.rsetv(xccnt, 0.0, lagxcmult, _params);
            ablasf.bsetallocv(xccnt, false, ref subsolver.isinactive, _params);
            
            //
            // Linear term B
            //
            penalizedfg(state, model.x, model.fi, model.sj, ref v, subsolver.curb, _params);
            
            //
            // Trust radius constraints for primary variables
            //
            ablasf.bsetallocv(n, false, ref subsolver.retainnegativebclm, _params);
            ablasf.bsetallocv(n, false, ref subsolver.retainpositivebclm, _params);
            for(i=0; i<=n-1; i++)
            {
                subsolver.curbndl[i] = -gettrustregionk(model.x, i, state.trustrad, _params);
                subsolver.curbndu[i] = gettrustregionk(model.x, i, state.trustrad, _params);
                if( state.hasbndl[i] && (double)(state.scaledbndl[i]-model.x[i])>(double)(subsolver.curbndl[i]) )
                {
                    subsolver.curbndl[i] = state.scaledbndl[i]-model.x[i];
                    subsolver.retainnegativebclm[i] = true;
                }
                if( state.hasbndu[i] && (double)(state.scaledbndu[i]-model.x[i])<(double)(subsolver.curbndu[i]) )
                {
                    subsolver.curbndu[i] = state.scaledbndu[i]-model.x[i];
                    subsolver.retainpositivebclm[i] = true;
                }
            }
            
            //
            // Prepare storage for the "effective" constraining matrix (one with rows guaranteed to be
            // inactive removed) and for the upcoming pattern matrix (one that is not subject to
            // removal of any rows).
            //
            nnz = 0;
            if( lccnt>0 )
            {
                nnz = nnz+subsolver.sparserawlc.ridx[lccnt];
            }
            nnz = nnz+(model.sj.ridx[1+nnlc]-model.sj.ridx[1]);
            apserv.ivectorgrowto(ref subsolver.sparseefflc.ridx, xccnt+1, _params);
            apserv.rvectorgrowto(ref subsolver.sparseefflc.vals, nnz, _params);
            apserv.ivectorgrowto(ref subsolver.sparseefflc.idx, nnz, _params);
            apserv.ivectorsetlengthatleast(ref subsolver.sparseefflc.didx, xccnt, _params);
            apserv.ivectorsetlengthatleast(ref subsolver.sparseefflc.uidx, xccnt, _params);
            subsolver.sparseefflc.ridx[0] = 0;
            subsolver.sparseefflc.m = 0;
            subsolver.sparseefflc.n = n;
            subsolver.sparseefflc.matrixtype = 1;
            sparse.sparsecreatecrsemptybuf(n, subsolver.upcomingpattern, _params);
            
            //
            // Append linear equality/inequality constraints
            //
            // Scan sparsified linear constraints stored in sparserawlc[], skip ones
            // which are inactive anywhere in the trust region.
            //
            for(i=0; i<=lccnt-1; i++)
            {
                
                //
                // Calculate:
                // * VRight - product of X[]  and AR[i] - Ith row of sparserawlc matrix.
                // * VMin   - minimum value of X*ARi computed over trust region
                // * VMax   - maximum value of X*ARi computed over trust region
                //
                vright = 0;
                vmax = 0;
                vmin = 0;
                j0 = subsolver.sparserawlc.ridx[i];
                j1 = subsolver.sparserawlc.ridx[i+1]-1;
                for(k=j0; k<=j1; k++)
                {
                    j = subsolver.sparserawlc.idx[k];
                    v = model.x[j];
                    vv = subsolver.sparserawlc.vals[k];
                    vright = vright+vv*v;
                    if( vv>=0 )
                    {
                        vmax = vmax+vv*(v+subsolver.curbndu[j]);
                        vmin = vmin+vv*(v+subsolver.curbndl[j]);
                    }
                    else
                    {
                        vmax = vmax+vv*(v+subsolver.curbndl[j]);
                        vmin = vmin+vv*(v+subsolver.curbndu[j]);
                    }
                }
                bndlinactive = !state.hasal[i] || vmin>state.sclal[i];
                bnduinactive = !state.hasau[i] || vmax<state.sclau[i];
                
                //
                // Linear constraints are passed 'as is', without additional rescaling
                //
                subsolver.rescalelag[i] = 1.0;
                
                //
                // Always append full row to the upcoming pattern; rows to the effective linear
                // constraints matrix are added subject to basic presolve (remove constraints that
                // are guaranteed to be inactive).
                //
                appendscaledsparserow(subsolver.upcomingpattern, 1.0, subsolver.sparserawlc, i, _params);
                
                //
                // If constraint is an inequality one and guaranteed to be inactive
                // within trust region, it is skipped (the row itself is retained but
                // filled by zeros).
                //
                if( bndlinactive && bnduinactive )
                {
                    subsolver.sparseefflc.ridx[i+1] = subsolver.sparseefflc.ridx[i];
                    subsolver.cural[i] = 0.0;
                    subsolver.curau[i] = 0.0;
                    subsolver.rescalelag[i] = 0.0;
                    subsolver.isinactive[i] = true;
                    continue;
                }
                
                //
                // Copy constraint from sparserawlc[] to sparseefflc[]
                //
                offs = subsolver.sparseefflc.ridx[i];
                j0 = subsolver.sparserawlc.ridx[i];
                j1 = subsolver.sparserawlc.ridx[i+1]-1;
                for(k=j0; k<=j1; k++)
                {
                    subsolver.sparseefflc.idx[offs] = subsolver.sparserawlc.idx[k];
                    subsolver.sparseefflc.vals[offs] = subsolver.sparserawlc.vals[k];
                    offs = offs+1;
                }
                subsolver.sparseefflc.ridx[i+1] = offs;
                
                //
                // Set up bounds and slack part of D0.
                //
                // NOTE: bounds for equality and inequality constraints are
                //       handled differently
                //
                subsolver.cural[i] = Double.NegativeInfinity;
                subsolver.curau[i] = Double.PositiveInfinity;
                if( !bndlinactive )
                {
                    subsolver.cural[i] = state.sclal[i]-vright;
                }
                if( !bnduinactive )
                {
                    subsolver.curau[i] = state.sclau[i]-vright;
                }
            }
            subsolver.sparseefflc.m = subsolver.sparseefflc.m+lccnt;
            
            //
            // Append nonlinear equality/inequality constraints
            //
            for(i=0; i<=nnlc-1; i++)
            {
                
                //
                // Calculate:
                // * rescale coefficient used to normalize constraints
                // * VMax - maximum of constraint value over trust region
                //
                vmax = model.fi[1+i];
                vmin = model.fi[1+i];
                vv = 0;
                j0 = model.sj.ridx[1+i];
                j1 = model.sj.ridx[1+i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    j = model.sj.idx[jj];
                    v = model.sj.vals[jj];
                    vv = vv+v*v;
                    if( v>=0 )
                    {
                        vmax = vmax+v*subsolver.curbndu[j];
                        vmin = vmin+v*subsolver.curbndl[j];
                    }
                    else
                    {
                        vmax = vmax+v*subsolver.curbndl[j];
                        vmin = vmin+v*subsolver.curbndu[j];
                    }
                }
                rescaleby = 1/apserv.coalesce(Math.Sqrt(vv), 1, _params);
                bndlinactive = !state.hasnl[i] || vmin>state.scalednl[i];
                bnduinactive = !state.hasnu[i] || vmax<state.scalednu[i];
                
                //
                // Nonlinear constraints are passed with normalization
                //
                subsolver.rescalelag[lccnt+i] = rescaleby;
                
                //
                // Always append full row to the upcoming pattern; rows to the effective linear
                // constraints matrix are added subject to basic presolve (remove constraints that
                // are guaranteed to be inactive).
                //
                appendscaledsparserow(subsolver.upcomingpattern, rescaleby, model.sj, 1+i, _params);
                
                //
                // If constraint is an inequality one and guaranteed to be inactive
                // within trust region, it is skipped (row itself is retained but
                // filled by zeros).
                //
                if( bndlinactive && bnduinactive )
                {
                    subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i+1] = subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i];
                    subsolver.cural[subsolver.sparseefflc.m+i] = 0.0;
                    subsolver.curau[subsolver.sparseefflc.m+i] = 0.0;
                    subsolver.rescalelag[lccnt+i] = 0.0;
                    subsolver.isinactive[lccnt+i] = true;
                    continue;
                }
                
                //
                // Copy scaled row
                //
                j0 = model.sj.ridx[1+i];
                j1 = model.sj.ridx[1+i+1]-1;
                offs = subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i];
                for(jj=j0; jj<=j1; jj++)
                {
                    j = model.sj.idx[jj];
                    v = model.sj.vals[jj];
                    subsolver.sparseefflc.vals[offs] = rescaleby*v;
                    subsolver.sparseefflc.idx[offs] = j;
                    offs = offs+1;
                }
                subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i+1] = offs;
                
                //
                // Set bounds on linear equality/inequality constraints
                //
                subsolver.cural[subsolver.sparseefflc.m+i] = Double.NegativeInfinity;
                subsolver.curau[subsolver.sparseefflc.m+i] = Double.PositiveInfinity;
                if( !bndlinactive )
                {
                    subsolver.cural[subsolver.sparseefflc.m+i] = rescaleby*(state.scalednl[i]-model.fi[1+i]);
                }
                if( !bnduinactive )
                {
                    subsolver.curau[subsolver.sparseefflc.m+i] = rescaleby*(state.scalednu[i]-model.fi[1+i]);
                }
            }
            subsolver.sparseefflc.m = subsolver.sparseefflc.m+nnlc;
            
            //
            // Finalize sparse matrix structure
            //
            alglib.ap.assert(subsolver.sparseefflc.ridx[subsolver.sparseefflc.m]<=alglib.ap.len(subsolver.sparseefflc.idx), "QPSubproblemSolve: critical integrity check failed");
            alglib.ap.assert(subsolver.sparseefflc.ridx[subsolver.sparseefflc.m]<=alglib.ap.len(subsolver.sparseefflc.vals), "QPSubproblemSolve: critical integrity check failed");
            subsolver.sparseefflc.ninitialized = subsolver.sparseefflc.ridx[subsolver.sparseefflc.m];
            sparse.sparseinitduidx(subsolver.sparseefflc, _params);
            
            //
            // Solve quadratic program with IPM.
            //
            // We always treat its result as a valid solution, even for TerminationType<=0.
            // In case anything is wrong with solution vector, we will detect it during line
            // search phase (merit function does not increase).
            //
            // NOTE: because we cleaned up constraints that are DEFINITELY inactive within
            //       trust region, we do not have to worry about StopOnExcessiveBounds option.
            //
            ablasf.rallocv(n, ref subsolver.tmps, _params);
            for(i=0; i<=n-1; i++)
            {
                subsolver.tmps[i] = gettrustregionk(model.x, i, state.trustrad, _params);
            }
            ablasf.rsetallocv(n, 0.0, ref subsolver.tmporigin, _params);
            if( state.usedensebfgs )
            {
                
                //
                // Dense BFGS is used to generate a quasi-Newton matrix,
                // dense IPM is used to solve QP subproblems.
                //
                if( dotrace )
                {
                    apserv.stimerstart(state.timerqpgen, _params);
                }
                optserv.hessiangetmatrix(hess, true, ref subsolver.denseh, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timerqpgen, _params);
                }
                if( dotrace )
                {
                    apserv.stimerstart(state.timeripminit, _params);
                }
                vipmsolver.vipminitdensewithslacks(subsolver.ipmsolver, subsolver.tmps, subsolver.tmporigin, n, n, true, _params);
                vipmsolver.vipmsetquadraticlinear(subsolver.ipmsolver, subsolver.denseh, subsolver.sparsedummy, 0, true, subsolver.curb, _params);
                vipmsolver.vipmsetconstraints(subsolver.ipmsolver, subsolver.curbndl, subsolver.curbndu, subsolver.sparseefflc, subsolver.sparseefflc.m, subsolver.densedummy, 0, subsolver.cural, subsolver.curau, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timeripminit, _params);
                }
                if( dotrace )
                {
                    apserv.stimerstart(state.timeripmsolve, _params);
                }
                vipmsolver.vipmoptimize(subsolver.ipmsolver, false, ref subsolver.tmp0, ref subsolver.tmp1, ref subsolver.tmp2, ref terminationtype, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timeripmsolve, _params);
                }
            }
            else
            {
                
                //
                // Prepare ordering for QP subproblem or reuse previously computed one
                //
                if( xccnt>0 && !sparse.sparsetrygatherclear(subsolver.pattern, subsolver.upcomingpattern, _params) )
                {
                    sparse.sparsemergepatterns(subsolver.pattern, subsolver.upcomingpattern, subsolver.sparsetmp, _params);
                    sparse.sparsecopybuf(subsolver.sparsetmp, subsolver.pattern, _params);
                    ablasf.bsetallocv(n, true, ref subsolver.isbounded, _params);
                    ipm2solver.ipm2proposeordering(subsolver.ipm2, n, true, subsolver.isbounded, subsolver.isbounded, subsolver.pattern, subsolver.cural, subsolver.curau, xccnt, ref subsolver.ordering, _params);
                }
                
                //
                // Low-rank quasi-Newton matrix with positive-only corrections is used,
                // sparse IPM with low-rank updates is used to solve QP subproblems.
                //
                if( dotrace )
                {
                    apserv.stimerstart(state.timerqpgen, _params);
                }
                optserv.hessiangetlowrankstabilized(hess, ref subsolver.tmpdiag, ref subsolver.tmpcorrc, ref subsolver.hesscorrd, ref subsolver.hessrank, _params);
                subsolver.hesssparsediag.matrixtype = 1;
                subsolver.hesssparsediag.m = n;
                subsolver.hesssparsediag.n = n;
                ablasf.iallocv(n+1, ref subsolver.hesssparsediag.ridx, _params);
                ablasf.iallocv(n, ref subsolver.hesssparsediag.idx, _params);
                ablasf.rallocv(n, ref subsolver.hesssparsediag.vals, _params);
                subsolver.hesssparsediag.ridx[0] = 0;
                for(i=0; i<=n-1; i++)
                {
                    subsolver.hesssparsediag.idx[i] = i;
                    subsolver.hesssparsediag.vals[i] = subsolver.tmpdiag[i];
                    subsolver.hesssparsediag.ridx[i+1] = i+1;
                }
                sparse.sparsecreatecrsinplace(subsolver.hesssparsediag, _params);
                if( subsolver.hessrank>0 )
                {
                    ablasf.rcopyallocm(subsolver.hessrank, n, subsolver.tmpcorrc, ref subsolver.hesscorrc, _params);
                }
                targetscale = 0;
                for(i=0; i<=n-1; i++)
                {
                    v = subsolver.curb[i]*state.varscales[i];
                    targetscale = targetscale+v*v;
                }
                targetscale = Math.Sqrt(targetscale)*state.trustrad;
                targetscale = Math.Max(targetscale, optserv.hessiangetnrm2stab(hess, _params)*math.sqr(state.trustrad));
                targetscale = apserv.coalesce(targetscale, 1, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timerqpgen, _params);
                }
                if( dotrace )
                {
                    apserv.stimerstart(state.timeripminit, _params);
                }
                ipm2solver.ipm2init(subsolver.ipm2, subsolver.tmps, subsolver.tmporigin, n, subsolver.densedummy, subsolver.hesssparsediag, 1, true, subsolver.hesscorrc, subsolver.hesscorrd, subsolver.hessrank, subsolver.curb, targetscale, subsolver.curbndl, subsolver.curbndu, subsolver.sparseefflc, subsolver.sparseefflc.m, subsolver.densedummy, 0, subsolver.cural, subsolver.curau, true, false, _params);
                ipm2solver.ipm2setmaxits(subsolver.ipm2, maxipmits, _params);
                ipm2solver.ipm2setordering(subsolver.ipm2, subsolver.ordering, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timeripminit, _params);
                }
                if( dotrace )
                {
                    apserv.stimerstart(state.timeripmsolve, _params);
                }
                ipm2solver.ipm2optimize(subsolver.ipm2, false, ref subsolver.tmp0, ref subsolver.tmp1, ref subsolver.tmp2, ref terminationtype, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timeripmsolve, _params);
                }
                ablasf.rcopyv(xccnt, subsolver.tmp2, subsolver.lastlaglc, _params);
            }
            ablasf.rcopyv(n, subsolver.tmp0, d, _params);
            
            //
            // Analyze constraint violation
            //
            isinfeasible = isinfeasible || terminationtype<=0;
            
            //
            // Unpack results
            //
            for(i=0; i<=n-1; i++)
            {
                lagbcmult[i] = 0;
                if( subsolver.retainpositivebclm[i] && (double)(subsolver.tmp1[i])>(double)(0) )
                {
                    lagbcmult[i] = subsolver.tmp1[i];
                }
                if( subsolver.retainnegativebclm[i] && (double)(subsolver.tmp1[i])<(double)(0) )
                {
                    lagbcmult[i] = subsolver.tmp1[i];
                }
            }
            ablasf.rcopyv(xccnt, subsolver.tmp2, lagxcmult, _params);
            ablasf.rmergemulv(xccnt, subsolver.rescalelag, lagxcmult, _params);
            
            //
            // Compute predicted decrease in an L1-penalized quadratic model
            //
            for(i=0; i<=lccnt-1; i++)
            {
                v = sparse.spdotvr(model.x, state.scla, i, _params);
                vv = v+sparse.spdotvr(d, state.scla, i, _params);
                if( state.hasal[i] )
                {
                    subsolver.penalty0 = subsolver.penalty0+Math.Max(state.sclal[i]-v, 0);
                    subsolver.penalty1 = subsolver.penalty1+Math.Max(state.sclal[i]-vv, 0);
                }
                if( state.hasau[i] )
                {
                    subsolver.penalty0 = subsolver.penalty0+Math.Max(v-state.sclau[i], 0);
                    subsolver.penalty1 = subsolver.penalty1+Math.Max(vv-state.sclau[i], 0);
                }
            }
            for(i=0; i<=nnlc-1; i++)
            {
                v = model.fi[1+i];
                vv = v+sparse.spdotvr(d, model.sj, 1+i, _params);
                if( state.hasnl[i] )
                {
                    subsolver.penalty0 = subsolver.penalty0+Math.Max(state.scalednl[i]-v, 0);
                    subsolver.penalty1 = subsolver.penalty1+Math.Max(state.scalednl[i]-vv, 0);
                }
                if( state.hasnu[i] )
                {
                    subsolver.penalty0 = subsolver.penalty0+Math.Max(v-state.scalednu[i], 0);
                    subsolver.penalty1 = subsolver.penalty1+Math.Max(vv-state.scalednu[i], 0);
                }
            }
            predictedchangemodel = ablasf.rdotv(n, d, subsolver.curb, _params)+0.5*optserv.hessianvmv(hess, d, _params);
            predictedchangepenalty = subsolver.penalty1-subsolver.penalty0;
            isinfeasible = isinfeasible || (double)(subsolver.penalty1)>(double)(subsolver.penalty0*sufficientdecreasesigma+Math.Max(optserv.critgetepsf(state.criteria, _params), 100*Math.Sqrt(math.machineepsilon))*apserv.rmaxabs3(subsolver.penalty0, subsolver.penalty1, 1, _params));
            
            //
            // Analyze length of D
            //
            alglib.ap.assert((double)(d2trustradratio)==(double)(0.0), "SQP: integrity check 0157 failed");
            for(i=0; i<=n-1; i++)
            {
                d2trustradratio = Math.Max(d2trustradratio, Math.Abs(d[i]/gettrustregionk(model.x, i, state.trustrad, _params)));
            }
            return result;
        }


        /*************************************************************************
        This function solves elastic  QP  subproblem  arising  during  feasibility
        restoration phase.

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        private static bool qpsubproblemsolveelastic(minfsqpstate state,
            minfsqpsubsolver subsolver,
            optserv.varsfuncjac model,
            optserv.xbfgshessian hess,
            double[] d,
            double[] lagbcmult,
            double[] lagxcmult,
            bool dotrace,
            ref bool isinfeasible,
            ref int terminationtype,
            ref double predictedchangemodel,
            ref double predictedchangepenalty,
            ref double d2trustradratio,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int nslack = 0;
            int lccnt = 0;
            int nnlc = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            int jj = 0;
            double v = 0;
            double vv = 0;
            double vright = 0;
            double vmax = 0;
            double vmin = 0;
            int xccnt = 0;
            int offsslacklc = 0;
            int offsslacknnlc = 0;
            int offs = 0;
            int nnz = 0;
            int j0 = 0;
            int j1 = 0;
            double rescaleby = 0;
            bool bndlinactive = new bool();
            bool bnduinactive = new bool();
            double targetscale = 0;

            isinfeasible = new bool();
            terminationtype = 0;
            predictedchangemodel = 0;
            predictedchangepenalty = 0;
            d2trustradratio = 0;

            alglib.ap.assert(!model.isdense, "SQP: integrity check 8637 failed");
            n = state.n;
            lccnt = state.lccnt;
            nnlc = state.nnlc;
            nslack = n+2*lccnt+2*nnlc;
            xccnt = lccnt+nnlc;
            
            //
            // Locations of slack variables
            //
            offsslacklc = n;
            offsslacknnlc = n+2*lccnt;
            
            //
            // Scales
            //
            ablasf.rsetallocv(nslack, state.trustrad, ref subsolver.tmps, _params);
            for(i=0; i<=n-1; i++)
            {
                subsolver.tmps[i] = gettrustregionk(model.x, i, state.trustrad, _params);
            }
            
            //
            // Prepare temporary structures
            //
            apserv.rvectorgrowto(ref subsolver.cural, xccnt, _params);
            apserv.rvectorgrowto(ref subsolver.curau, xccnt, _params);
            ablasf.rallocv(xccnt, ref subsolver.rescalelag, _params);
            
            //
            // Prepare default solution: all zeros
            //
            result = true;
            terminationtype = 0;
            predictedchangemodel = 0;
            predictedchangepenalty = 0;
            d2trustradratio = 0.0;
            isinfeasible = false;
            ablasf.rsetv(n, 0.0, d, _params);
            ablasf.rsetv(n, 0.0, lagbcmult, _params);
            ablasf.rsetv(xccnt, 0.0, lagxcmult, _params);
            ablasf.bsetallocv(lccnt+nnlc, false, ref subsolver.isinactive, _params);
            
            //
            // Linear term B
            //
            ablasf.rsetv(n, 0.0, subsolver.curb, _params);
            for(i=n; i<=nslack-1; i++)
            {
                subsolver.curb[i] = 1.0/subsolver.tmps[i];
            }
            
            //
            // Trust radius constraints for primary variables
            //
            ablasf.bsetallocv(n, false, ref subsolver.retainnegativebclm, _params);
            ablasf.bsetallocv(n, false, ref subsolver.retainpositivebclm, _params);
            for(i=0; i<=n-1; i++)
            {
                subsolver.curbndl[i] = -gettrustregionk(model.x, i, state.trustrad, _params);
                subsolver.curbndu[i] = gettrustregionk(model.x, i, state.trustrad, _params);
                if( state.hasbndl[i] && (double)(state.scaledbndl[i]-model.x[i])>(double)(subsolver.curbndl[i]) )
                {
                    subsolver.curbndl[i] = state.scaledbndl[i]-model.x[i];
                    subsolver.retainnegativebclm[i] = true;
                }
                if( state.hasbndu[i] && (double)(state.scaledbndu[i]-model.x[i])<(double)(subsolver.curbndu[i]) )
                {
                    subsolver.curbndu[i] = state.scaledbndu[i]-model.x[i];
                    subsolver.retainpositivebclm[i] = true;
                }
            }
            
            //
            // Prepare storage for "effective" constraining matrix
            //
            nnz = 0;
            if( lccnt>0 )
            {
                nnz = nnz+subsolver.sparserawlc.ridx[lccnt];
            }
            nnz = nnz+(model.sj.ridx[1+nnlc]-model.sj.ridx[1]);
            nnz = nnz+2*lccnt;
            nnz = nnz+2*nnlc;
            apserv.ivectorgrowto(ref subsolver.sparseefflc.ridx, xccnt+1, _params);
            apserv.rvectorgrowto(ref subsolver.sparseefflc.vals, nnz, _params);
            apserv.ivectorgrowto(ref subsolver.sparseefflc.idx, nnz, _params);
            apserv.ivectorsetlengthatleast(ref subsolver.sparseefflc.didx, xccnt, _params);
            apserv.ivectorsetlengthatleast(ref subsolver.sparseefflc.uidx, xccnt, _params);
            subsolver.sparseefflc.ridx[0] = 0;
            subsolver.sparseefflc.m = 0;
            subsolver.sparseefflc.n = nslack;
            subsolver.sparseefflc.matrixtype = 1;
            sparse.sparsecreatecrsemptybuf(nslack, subsolver.upcomingpattern, _params);
            
            //
            // Append linear equality/inequality constraints
            //
            // Scan sparsified linear constraints stored in sparserawlc[], skip ones
            // which are inactive anywhere in the trust region.
            //
            apserv.rvectorsetlengthatleast(ref subsolver.tmp0, nslack, _params);
            for(i=0; i<=n-1; i++)
            {
                subsolver.tmp0[i] = model.x[i];
            }
            for(i=n; i<=nslack-1; i++)
            {
                subsolver.tmp0[i] = 0;
            }
            for(i=0; i<=lccnt-1; i++)
            {
                
                //
                // Calculate:
                // * VRight - product of X[] (extended with zeros up to NSlack elements)
                //            and AR[i] - Ith row of sparserawlc matrix.
                // * VMax   - maximum value of X*ARi computed over trust region
                //
                vright = 0;
                vmax = 0;
                vmin = 0;
                j0 = subsolver.sparserawlc.ridx[i];
                j1 = subsolver.sparserawlc.ridx[i+1]-1;
                for(k=j0; k<=j1; k++)
                {
                    j = subsolver.sparserawlc.idx[k];
                    v = model.x[j];
                    vv = subsolver.sparserawlc.vals[k];
                    vright = vright+vv*v;
                    if( vv>=0 )
                    {
                        vmax = vmax+vv*(v+subsolver.curbndu[j]);
                        vmin = vmin+vv*(v+subsolver.curbndl[j]);
                    }
                    else
                    {
                        vmax = vmax+vv*(v+subsolver.curbndl[j]);
                        vmin = vmin+vv*(v+subsolver.curbndu[j]);
                    }
                }
                bndlinactive = !state.hasal[i] || vmin>state.sclal[i];
                bnduinactive = !state.hasau[i] || vmax<state.sclau[i];
                
                //
                // Linear constraints are passed 'as is', without additional rescaling
                //
                subsolver.rescalelag[i] = 1.0;
                
                //
                // Always append full row to the upcoming pattern; rows to the effective linear
                // constraints matrix are added subject to basic presolve (remove constraints that
                // are guaranteed to be inactive).
                //
                appendscaledsparserow(subsolver.upcomingpattern, 1.0, subsolver.sparserawlc, i, _params);
                sparse.sparseappendelement(subsolver.upcomingpattern, offsslacklc+2*i+0, 1.0, _params);
                sparse.sparseappendelement(subsolver.upcomingpattern, offsslacklc+2*i+1, -1.0, _params);
                
                //
                // If constraint is an inequality one and guaranteed to be inactive
                // within trust region, it is skipped (the row itself is retained but
                // filled by zeros).
                //
                if( bndlinactive && bnduinactive )
                {
                    offs = subsolver.sparseefflc.ridx[i];
                    subsolver.sparseefflc.vals[offs+0] = 1;
                    subsolver.sparseefflc.vals[offs+1] = -1;
                    subsolver.sparseefflc.idx[offs+0] = offsslacklc+2*i+0;
                    subsolver.sparseefflc.idx[offs+1] = offsslacklc+2*i+1;
                    subsolver.sparseefflc.ridx[i+1] = offs+2;
                    subsolver.cural[i] = 0.0;
                    subsolver.curau[i] = 0.0;
                    subsolver.curbndl[offsslacklc+2*i+0] = 0;
                    subsolver.curbndl[offsslacklc+2*i+1] = 0;
                    subsolver.curbndu[offsslacklc+2*i+0] = Double.PositiveInfinity;
                    subsolver.curbndu[offsslacklc+2*i+1] = Double.PositiveInfinity;
                    subsolver.rescalelag[i] = 0.0;
                    subsolver.isinactive[i] = true;
                    continue;
                }
                
                //
                // Start working on row I
                //
                offs = subsolver.sparseefflc.ridx[i];
                
                //
                // Copy constraint from sparserawlc[] to sparseefflc[], add slack terms
                //
                j0 = subsolver.sparserawlc.ridx[i];
                j1 = subsolver.sparserawlc.ridx[i+1]-1;
                for(k=j0; k<=j1; k++)
                {
                    subsolver.sparseefflc.idx[offs] = subsolver.sparserawlc.idx[k];
                    subsolver.sparseefflc.vals[offs] = subsolver.sparserawlc.vals[k];
                    offs = offs+1;
                }
                if( !bndlinactive )
                {
                    subsolver.sparseefflc.vals[offs] = 1;
                    subsolver.sparseefflc.idx[offs] = offsslacklc+2*i+0;
                    offs = offs+1;
                }
                if( !bnduinactive )
                {
                    subsolver.sparseefflc.vals[offs] = -1;
                    subsolver.sparseefflc.idx[offs] = offsslacklc+2*i+1;
                    offs = offs+1;
                }
                subsolver.sparseefflc.ridx[i+1] = offs;
                
                //
                // Set box constraints on slack variables and bounds on linear equality/inequality constraints
                //
                if( !bndlinactive )
                {
                    subsolver.cural[i] = state.sclal[i]-vright;
                    subsolver.curbndl[offsslacklc+2*i+0] = 0;
                    subsolver.curbndu[offsslacklc+2*i+0] = Math.Max(state.sclal[i]-vright, 0.0);
                }
                else
                {
                    subsolver.cural[i] = Double.NegativeInfinity;
                    subsolver.curbndl[offsslacklc+2*i+0] = 0;
                    subsolver.curbndu[offsslacklc+2*i+0] = Double.PositiveInfinity;
                }
                if( !bnduinactive )
                {
                    subsolver.curau[i] = state.sclau[i]-vright;
                    subsolver.curbndl[offsslacklc+2*i+1] = 0;
                    subsolver.curbndu[offsslacklc+2*i+1] = Math.Max(vright-state.sclau[i], 0.0);
                }
                else
                {
                    subsolver.curau[i] = Double.PositiveInfinity;
                    subsolver.curbndl[offsslacklc+2*i+1] = 0;
                    subsolver.curbndu[offsslacklc+2*i+1] = Double.PositiveInfinity;
                }
                
                //
                // Additional integrity check to fix rounding bugs, to make sure that curAL<=curAU.
                //
                if( !bndlinactive && !bnduinactive )
                {
                    subsolver.curau[i] = Math.Max(subsolver.curau[i], subsolver.cural[i]);
                }
            }
            subsolver.sparseefflc.m = subsolver.sparseefflc.m+lccnt;
            
            //
            // Append nonlinear equality/inequality constraints
            //
            for(i=0; i<=nnlc-1; i++)
            {
                
                //
                // Calculate:
                // * rescale coefficient used to normalize constraints
                // * VMax - maximum of constraint value over trust region
                //
                vmax = model.fi[1+i];
                vmin = model.fi[1+i];
                j0 = model.sj.ridx[1+i];
                j1 = model.sj.ridx[1+i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    j = model.sj.idx[jj];
                    v = model.sj.vals[jj];
                    if( v>=0 )
                    {
                        vmax = vmax+v*subsolver.curbndu[j];
                        vmin = vmin+v*subsolver.curbndl[j];
                    }
                    else
                    {
                        vmax = vmax+v*subsolver.curbndl[j];
                        vmin = vmin+v*subsolver.curbndu[j];
                    }
                }
                rescaleby = 1.0;
                bndlinactive = !state.hasnl[i] || vmin>state.scalednl[i];
                bnduinactive = !state.hasnu[i] || vmax<state.scalednu[i];
                
                //
                // Nonlinear constraints are passed with normalization
                //
                subsolver.rescalelag[lccnt+i] = rescaleby;
                
                //
                // Always append full row to the upcoming pattern; rows to the effective linear
                // constraints matrix are added subject to basic presolve (remove constraints that
                // are guaranteed to be inactive).
                //
                appendscaledsparserow(subsolver.upcomingpattern, rescaleby, model.sj, 1+i, _params);
                sparse.sparseappendelement(subsolver.upcomingpattern, offsslacknnlc+2*i+0, 1.0, _params);
                sparse.sparseappendelement(subsolver.upcomingpattern, offsslacknnlc+2*i+1, -1.0, _params);
                
                //
                // If constraint is an inequality one and guaranteed to be inactive
                // within trust region, it is skipped (row itself is retained but
                // filled by zeros).
                //
                if( bndlinactive && bnduinactive )
                {
                    offs = subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i];
                    subsolver.sparseefflc.vals[offs+0] = 1;
                    subsolver.sparseefflc.vals[offs+1] = -1;
                    subsolver.sparseefflc.idx[offs+0] = offsslacknnlc+2*i+0;
                    subsolver.sparseefflc.idx[offs+1] = offsslacknnlc+2*i+1;
                    subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i+1] = offs+2;
                    subsolver.cural[subsolver.sparseefflc.m+i] = 0.0;
                    subsolver.curau[subsolver.sparseefflc.m+i] = 0.0;
                    subsolver.curbndl[offsslacknnlc+2*i+0] = 0.0;
                    subsolver.curbndu[offsslacknnlc+2*i+0] = Double.PositiveInfinity;
                    subsolver.curbndl[offsslacknnlc+2*i+1] = 0.0;
                    subsolver.curbndu[offsslacknnlc+2*i+1] = Double.PositiveInfinity;
                    subsolver.rescalelag[lccnt+i] = 0.0;
                    subsolver.isinactive[lccnt+i] = true;
                    continue;
                }
                
                //
                // Copy scaled row, add slack terms
                //
                offs = subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i];
                j0 = model.sj.ridx[1+i];
                j1 = model.sj.ridx[1+i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    j = model.sj.idx[jj];
                    v = model.sj.vals[jj];
                    subsolver.sparseefflc.vals[offs] = rescaleby*v;
                    subsolver.sparseefflc.idx[offs] = j;
                    offs = offs+1;
                }
                if( !bndlinactive )
                {
                    subsolver.sparseefflc.vals[offs] = 1;
                    subsolver.sparseefflc.idx[offs] = offsslacknnlc+2*i+0;
                    offs = offs+1;
                }
                if( !bnduinactive )
                {
                    subsolver.sparseefflc.vals[offs] = -1;
                    subsolver.sparseefflc.idx[offs] = offsslacknnlc+2*i+1;
                    offs = offs+1;
                }
                subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i+1] = offs;
                
                //
                // Set box constraints on slack variables and bounds on linear equality/inequality constraints
                //
                if( !bndlinactive )
                {
                    subsolver.cural[subsolver.sparseefflc.m+i] = rescaleby*(state.scalednl[i]-model.fi[1+i]);
                    subsolver.curbndl[offsslacknnlc+2*i+0] = 0;
                    subsolver.curbndu[offsslacknnlc+2*i+0] = rescaleby*Math.Max(state.scalednl[i]-model.fi[1+i], 0.0);
                }
                else
                {
                    subsolver.cural[subsolver.sparseefflc.m+i] = Double.NegativeInfinity;
                    subsolver.curbndl[offsslacknnlc+2*i+0] = 0;
                    subsolver.curbndu[offsslacknnlc+2*i+0] = Double.PositiveInfinity;
                }
                if( !bnduinactive )
                {
                    subsolver.curau[subsolver.sparseefflc.m+i] = rescaleby*(state.scalednu[i]-model.fi[1+i]);
                    subsolver.curbndl[offsslacknnlc+2*i+1] = 0;
                    subsolver.curbndu[offsslacknnlc+2*i+1] = rescaleby*Math.Max(model.fi[1+i]-state.scalednu[i], 0.0);
                }
                else
                {
                    subsolver.curau[subsolver.sparseefflc.m+i] = Double.PositiveInfinity;
                    subsolver.curbndl[offsslacknnlc+2*i+1] = 0;
                    subsolver.curbndu[offsslacknnlc+2*i+1] = Double.PositiveInfinity;
                }
            }
            subsolver.sparseefflc.m = subsolver.sparseefflc.m+nnlc;
            
            //
            // Finalize sparse matrix structure
            //
            alglib.ap.assert(subsolver.sparseefflc.ridx[subsolver.sparseefflc.m]<=alglib.ap.len(subsolver.sparseefflc.idx), "QPSubproblemSolve: critical integrity check failed");
            alglib.ap.assert(subsolver.sparseefflc.ridx[subsolver.sparseefflc.m]<=alglib.ap.len(subsolver.sparseefflc.vals), "QPSubproblemSolve: critical integrity check failed");
            subsolver.sparseefflc.ninitialized = subsolver.sparseefflc.ridx[subsolver.sparseefflc.m];
            sparse.sparseinitduidx(subsolver.sparseefflc, _params);
            
            //
            // Solve quadratic program with IPM.
            //
            // We always treat its result as a valid solution, even for TerminationType<=0.
            // In case anything is wrong with solution vector, we will detect it during line
            // search phase (merit function does not increase).
            //
            // NOTE: because we cleaned up constraints that are DEFINITELY inactive within
            //       trust region, we do not have to worry about StopOnExcessiveBounds option.
            //
            ablasf.rsetallocv(nslack, 0.0, ref subsolver.tmporigin, _params);
            if( state.usedensebfgs )
            {
                
                //
                // Dense BFGS is used to generate a quasi-Newton matrix,
                // dense IPM is used to solve QP subproblems.
                //
                if( dotrace )
                {
                    apserv.stimerstart(state.timerqpgen, _params);
                }
                ablasf.rsetallocm(n, n, 0.0, ref subsolver.denseh, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timerqpgen, _params);
                }
                if( dotrace )
                {
                    apserv.stimerstart(state.timeripminit, _params);
                }
                vipmsolver.vipminitdensewithslacks(subsolver.ipmsolver, subsolver.tmps, subsolver.tmporigin, n, nslack, true, _params);
                vipmsolver.vipmsetquadraticlinear(subsolver.ipmsolver, subsolver.denseh, subsolver.sparsedummy, 0, true, subsolver.curb, _params);
                vipmsolver.vipmsetconstraints(subsolver.ipmsolver, subsolver.curbndl, subsolver.curbndu, subsolver.sparseefflc, subsolver.sparseefflc.m, subsolver.densedummy, 0, subsolver.cural, subsolver.curau, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timeripminit, _params);
                }
                if( dotrace )
                {
                    apserv.stimerstart(state.timeripmsolve, _params);
                }
                vipmsolver.vipmoptimize(subsolver.ipmsolver, false, ref subsolver.tmp0, ref subsolver.tmp1, ref subsolver.tmp2, ref terminationtype, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timeripmsolve, _params);
                }
            }
            else
            {
                
                //
                // Prepare ordering for QP subproblem or reuse previously computed one
                //
                if( xccnt>0 && !sparse.sparsetrygatherclear(subsolver.elasticpattern, subsolver.upcomingpattern, _params) )
                {
                    sparse.sparsemergepatterns(subsolver.elasticpattern, subsolver.upcomingpattern, subsolver.sparsetmp, _params);
                    sparse.sparsecopybuf(subsolver.sparsetmp, subsolver.elasticpattern, _params);
                    ablasf.bsetallocv(nslack, true, ref subsolver.isbounded, _params);
                    ipm2solver.ipm2proposeordering(subsolver.ipm2, nslack, true, subsolver.isbounded, subsolver.isbounded, subsolver.elasticpattern, subsolver.cural, subsolver.curau, xccnt, ref subsolver.elasticordering, _params);
                }
                
                //
                // Low-rank quasi-Newton matrix with positive-only corrections is used,
                // sparse IPM with low-rank updates is used to solve QP subproblems.
                //
                if( dotrace )
                {
                    apserv.stimerstart(state.timerqpgen, _params);
                }
                subsolver.hesssparsediag.matrixtype = 1;
                subsolver.hesssparsediag.m = nslack;
                subsolver.hesssparsediag.n = nslack;
                ablasf.iallocv(nslack+1, ref subsolver.hesssparsediag.ridx, _params);
                ablasf.iallocv(nslack, ref subsolver.hesssparsediag.idx, _params);
                ablasf.rallocv(nslack, ref subsolver.hesssparsediag.vals, _params);
                subsolver.hesssparsediag.ridx[0] = 0;
                for(i=0; i<=nslack-1; i++)
                {
                    subsolver.hesssparsediag.idx[i] = i;
                    subsolver.hesssparsediag.vals[i] = Math.Sqrt(math.machineepsilon)/math.sqr(subsolver.tmps[i]);
                    subsolver.hesssparsediag.ridx[i+1] = i+1;
                }
                targetscale = 0;
                for(i=0; i<=nslack-1; i++)
                {
                    v = subsolver.curb[i];
                    if( i<n )
                    {
                        v = v*state.varscales[i];
                    }
                    targetscale = targetscale+v*v;
                }
                targetscale = Math.Sqrt(targetscale)*state.trustrad;
                sparse.sparsecreatecrsinplace(subsolver.hesssparsediag, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timerqpgen, _params);
                }
                if( dotrace )
                {
                    apserv.stimerstart(state.timeripminit, _params);
                }
                ipm2solver.ipm2init(subsolver.ipm2, subsolver.tmps, subsolver.tmporigin, nslack, subsolver.densedummy, subsolver.hesssparsediag, 1, true, subsolver.hesscorrc, subsolver.hesscorrd, 0, subsolver.curb, targetscale, subsolver.curbndl, subsolver.curbndu, subsolver.sparseefflc, subsolver.sparseefflc.m, subsolver.densedummy, 0, subsolver.cural, subsolver.curau, true, false, _params);
                ipm2solver.ipm2setmaxits(subsolver.ipm2, maxipmits, _params);
                ipm2solver.ipm2setordering(subsolver.ipm2, subsolver.elasticordering, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timeripminit, _params);
                }
                if( dotrace )
                {
                    apserv.stimerstart(state.timeripmsolve, _params);
                }
                ipm2solver.ipm2optimize(subsolver.ipm2, false, ref subsolver.tmp0, ref subsolver.tmp1, ref subsolver.tmp2, ref terminationtype, _params);
                if( dotrace )
                {
                    apserv.stimerstop(state.timeripmsolve, _params);
                }
            }
            ablasf.rcopyv(n, subsolver.tmp0, d, _params);
            isinfeasible = !qpsubproblemisfeasible(state, subsolver, model, d, _params);
            
            //
            // Unpack results
            //
            for(i=0; i<=n-1; i++)
            {
                lagbcmult[i] = 0;
                if( subsolver.retainpositivebclm[i] && (double)(subsolver.tmp1[i])>(double)(0) )
                {
                    lagbcmult[i] = subsolver.tmp1[i];
                }
                if( subsolver.retainnegativebclm[i] && (double)(subsolver.tmp1[i])<(double)(0) )
                {
                    lagbcmult[i] = subsolver.tmp1[i];
                }
            }
            ablasf.rcopyv(xccnt, subsolver.tmp2, lagxcmult, _params);
            ablasf.rmergemulv(xccnt, subsolver.rescalelag, lagxcmult, _params);
            
            //
            // Compute predicted decrease in an L1-penalized quadratic model
            //
            penalizedfg(state, model.x, model.fi, model.sj, ref v, subsolver.tmp0, _params);
            predictedchangemodel = ablasf.rdotv(n, d, subsolver.tmp0, _params)+0.5*optserv.hessianvmv(hess, d, _params);
            predictedchangepenalty = 0;
            for(i=0; i<=lccnt-1; i++)
            {
                v = sparse.spdotvr(model.x, state.scla, i, _params);
                vv = v+sparse.spdotvr(d, state.scla, i, _params);
                if( state.hasal[i] )
                {
                    predictedchangepenalty = predictedchangepenalty+(Math.Max(state.sclal[i]-vv, 0)-Math.Max(state.sclal[i]-v, 0));
                }
                if( state.hasau[i] )
                {
                    predictedchangepenalty = predictedchangepenalty+(Math.Max(vv-state.sclau[i], 0)-Math.Max(v-state.sclau[i], 0));
                }
            }
            for(i=0; i<=nnlc-1; i++)
            {
                v = model.fi[1+i];
                vv = v+sparse.spdotvr(d, model.sj, 1+i, _params);
                if( state.hasnl[i] )
                {
                    predictedchangepenalty = predictedchangepenalty+(Math.Max(state.scalednl[i]-vv, 0)-Math.Max(state.scalednl[i]-v, 0));
                }
                if( state.hasnu[i] )
                {
                    predictedchangepenalty = predictedchangepenalty+(Math.Max(vv-state.scalednu[i], 0)-Math.Max(v-state.scalednu[i], 0));
                }
            }
            
            //
            // Analyze length of D
            //
            alglib.ap.assert((double)(d2trustradratio)==(double)(0.0), "SQP: integrity check 0157 failed");
            for(i=0; i<=n-1; i++)
            {
                d2trustradratio = Math.Max(d2trustradratio, Math.Abs(d[i]/gettrustregionk(model.x, i, state.trustrad, _params)));
            }
            return result;
        }


        /*************************************************************************
        This function checks feasibility of a QP subproblem solution D (which
        corresponds to X+D after correcting for origin)

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        private static bool qpsubproblemisfeasible(minfsqpstate state,
            minfsqpsubsolver subsolver,
            optserv.varsfuncjac model,
            double[] d,
            alglib.xparams _params)
        {
            bool result = new bool();
            double tol = 0;
            double v0 = 0;
            double v1 = 0;
            double v2 = 0;
            double vv = 0;
            int lccnt = 0;
            int nnlc = 0;
            int i = 0;
            int k = 0;
            int j0 = 0;
            int j1 = 0;
            bool isinfeasible = new bool();

            alglib.ap.assert(!model.isdense, "SQP: integrity check 5436 failed");
            lccnt = state.lccnt;
            nnlc = state.nnlc;
            tol = Math.Max(optserv.critgeteps(state.criteria, _params), Math.Sqrt(math.machineepsilon));
            tol = Math.Max(tol, 1.0E-5*state.trustrad);
            isinfeasible = false;
            for(i=0; i<=lccnt-1; i++)
            {
                if( !subsolver.isinactive[i] )
                {
                    
                    //
                    // Calculate product of X+D with I-th linear constraint
                    //
                    v0 = 0;
                    v1 = 0;
                    v2 = 0;
                    j0 = subsolver.sparserawlc.ridx[i];
                    j1 = subsolver.sparserawlc.ridx[i+1]-1;
                    for(k=j0; k<=j1; k++)
                    {
                        vv = subsolver.sparserawlc.vals[k];
                        v0 = v0+vv*model.x[subsolver.sparserawlc.idx[k]];
                        v1 = v1+vv*d[subsolver.sparserawlc.idx[k]];
                        v2 = v2+vv*vv;
                    }
                    v1 = v1+v0;
                    if( state.hasal[i] )
                    {
                        isinfeasible = isinfeasible || Math.Max(state.sclal[i]-v1, 0.0)/apserv.coalesce(Math.Sqrt(v2), 1, _params)>tol;
                    }
                    if( state.hasau[i] )
                    {
                        isinfeasible = isinfeasible || Math.Max(v1-state.sclau[i], 0.0)/apserv.coalesce(Math.Sqrt(v2), 1, _params)>tol;
                    }
                }
            }
            for(i=0; i<=nnlc-1; i++)
            {
                if( !subsolver.isinactive[lccnt+i] )
                {
                    v1 = model.fi[1+i]+sparse.spdotvr(d, model.sj, 1+i, _params);
                    v2 = sparse.spdotr2(model.sj, 1+i, _params);
                    if( state.hasnl[i] )
                    {
                        isinfeasible = isinfeasible || Math.Max(state.scalednl[i]-v1, 0.0)/apserv.coalesce(Math.Sqrt(v2), 1, _params)>tol;
                    }
                    if( state.hasnu[i] )
                    {
                        isinfeasible = isinfeasible || Math.Max(v1-state.scalednu[i], 0.0)/apserv.coalesce(Math.Sqrt(v2), 1, _params)>tol;
                    }
                }
            }
            result = !isinfeasible;
            return result;
        }


        /*************************************************************************
        Copies X to State.X
        *************************************************************************/
        private static void sqpsendx(minfsqpstate state,
            double[] xs,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            n = state.n;
            for(i=0; i<=n-1; i++)
            {
                if( state.hasbndl[i] && xs[i]<=state.scaledbndl[i] )
                {
                    state.x[i] = state.scaledbndl[i];
                    continue;
                }
                if( state.hasbndu[i] && xs[i]>=state.scaledbndu[i] )
                {
                    state.x[i] = state.scaledbndu[i];
                    continue;
                }
                state.x[i] = xs[i];
            }
        }


        /*************************************************************************
        Retrieves F-vector and scaled Jacobian, copies them to FiS and JS.

        Returns True on success, False on failure (when F or J are not finite numbers).
        *************************************************************************/
        private static bool sqpretrievefij(minfsqpstate state,
            optserv.varsfuncjac vfj,
            alglib.xparams _params)
        {
            bool result = new bool();

            alglib.ap.assert(!vfj.isdense, "SQP: integrity check 0016 failed");
            
            //
            // Retrieve function vector and Jacobian
            //
            ablasf.rcopyv(state.nnlc+1, state.fi, vfj.fi, _params);
            sparse.sparsecopybuf(state.sj, vfj.sj, _params);
            ablasf.rmergemulv(state.nnlc+1, state.invfscales, vfj.fi, _params);
            sparse.sparsemultiplyrowsby(vfj.sj, state.invfscales, _params);
            
            //
            // Check finiteness
            //
            result = math.isfinite(ablasf.rdotv2(state.nnlc+1, vfj.fi, _params)) && math.isfinite(ablasf.rdotv2(vfj.sj.ridx[state.nnlc+1], vfj.sj.vals, _params));
            return result;
        }


        /*************************************************************************
        This function calculates Lagrangian of the problem (in scaled variables):
        its value and gradient.

        Additionally it also estimates violation of linear constraints at the point
        as well as index of the most violated constraint
        *************************************************************************/
        private static void lagrangianfg(minfsqpstate state,
            double[] x,
            double trustrad,
            double[] fi,
            sparse.sparsematrix sj,
            double[] lagbcmult,
            double[] lagxcmult,
            bool uselagrangeterms,
            ref double f,
            double[] g,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;
            int lccnt = 0;
            int nnlc = 0;
            double v = 0;
            double vlag = 0;
            double vact = 0;
            double vd = 0;
            double vs = 0;
            double lagalpha = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;

            f = 0;

            n = state.n;
            lccnt = state.lccnt;
            nnlc = state.nnlc;
            lagalpha = apserv.rcase2(uselagrangeterms, 1, 0, _params);
            
            //
            // Target function
            //
            ablasf.rsetv(n, 0.0, g, _params);
            f = fi[0];
            j0 = sj.ridx[0];
            j1 = sj.ridx[1]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                g[sj.idx[jj]] = sj.vals[jj];
            }
            
            //
            // Lagrangian terms for box constraints
            //
            for(i=0; i<=n-1; i++)
            {
                f = f+lagalpha*lagbcmult[i]*x[i];
                g[i] = g[i]+lagalpha*lagbcmult[i];
            }
            
            //
            // Lagrangian terms for linear constraints, constraint violations
            //
            if( lccnt>0 )
            {
                apserv.rvectorsetlengthatleast(ref state.sclagtmp0, Math.Max(lccnt, n), _params);
                apserv.rvectorsetlengthatleast(ref state.sclagtmp1, Math.Max(lccnt, n), _params);
                sparse.sparsemv(state.scla, x, ref state.sclagtmp0, _params);
                for(i=0; i<=lccnt-1; i++)
                {
                    
                    //
                    // Prepare
                    //
                    v = state.sclagtmp0[i];
                    vlag = lagalpha*lagxcmult[i];
                    state.sclagtmp1[i] = 0;
                    
                    //
                    // Primary Lagrangian term
                    //
                    vact = v;
                    vd = 1;
                    f = f+vlag*vact;
                    state.sclagtmp1[i] = state.sclagtmp1[i]+vlag*vd;
                    
                    //
                    // Quadratic augmentation term
                    //
                    if( state.hasal[i] && v<state.sclal[i] )
                    {
                        vact = v-state.sclal[i];
                        f = f+0.5*augmentationfactor*vact*vact;
                        state.sclagtmp1[i] = state.sclagtmp1[i]+augmentationfactor*vact;
                    }
                    if( state.hasau[i] && v>state.sclau[i] )
                    {
                        vact = v-state.sclau[i];
                        f = f+0.5*augmentationfactor*vact*vact;
                        state.sclagtmp1[i] = state.sclagtmp1[i]+augmentationfactor*vact;
                    }
                }
                sparse.sparsemtv(state.scla, state.sclagtmp1, ref state.sclagtmp0, _params);
                for(i=0; i<=n-1; i++)
                {
                    g[i] = g[i]+state.sclagtmp0[i];
                }
            }
            
            //
            // Lagrangian terms for nonlinear constraints
            //
            apserv.rvectorsetlengthatleast(ref state.sclagtmp1, nnlc, _params);
            for(i=0; i<=nnlc-1; i++)
            {
                v = fi[1+i];
                vlag = lagalpha*lagxcmult[lccnt+i];
                vs = 0;
                
                //
                // Lagrangian term
                //
                vact = v;
                vd = 1;
                f = f+vlag*vact;
                vs = vs+vlag*vd;
                
                //
                // Augmentation term
                //
                vact = 0;
                vd = 0;
                if( state.hasnl[i] && v<state.scalednl[i] )
                {
                    vact = state.scalednl[i]-v;
                    vd = -1;
                }
                if( state.hasnu[i] && v>state.scalednu[i] )
                {
                    vact = v-state.scalednu[i];
                    vd = 1;
                }
                f = f+0.5*augmentationfactor*vact*vact;
                vs = vs+augmentationfactor*vact*vd;
                
                //
                // Modify gradient
                //
                j0 = sj.ridx[1+i];
                j1 = sj.ridx[1+i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    g[sj.idx[jj]] = g[sj.idx[jj]]+vs*sj.vals[jj];
                }
            }
        }


        /*************************************************************************
        This function calculates Lagrangian of the problem (in scaled variables):
        its value and gradient.

        Additionally it also estimates violation of linear constraints at the point
        as well as index of the most violated constraint
        *************************************************************************/
        private static void penalizedfg(minfsqpstate state,
            double[] x,
            double[] fi,
            sparse.sparsematrix sj,
            ref double f,
            double[] g,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;
            int lccnt = 0;
            int nnlc = 0;
            double v = 0;
            double vact = 0;
            double vd = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;

            f = 0;

            n = state.n;
            lccnt = state.lccnt;
            nnlc = state.nnlc;
            
            //
            // Target function
            //
            ablasf.rsetv(n, 0.0, g, _params);
            f = fi[0];
            j0 = sj.ridx[0];
            j1 = sj.ridx[1]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                g[sj.idx[jj]] = sj.vals[jj];
            }
            
            //
            // penalties for linear constraints
            //
            if( lccnt>0 )
            {
                apserv.rvectorsetlengthatleast(ref state.sclagtmp0, Math.Max(lccnt, n), _params);
                apserv.rvectorsetlengthatleast(ref state.sclagtmp1, Math.Max(lccnt, n), _params);
                sparse.sparsemv(state.scla, x, ref state.sclagtmp0, _params);
                for(i=0; i<=lccnt-1; i++)
                {
                    v = state.sclagtmp0[i];
                    state.sclagtmp1[i] = 0;
                    if( state.hasal[i] && v<state.sclal[i] )
                    {
                        vact = v-state.sclal[i];
                        f = f+0.5*augmentationfactor*vact*vact;
                        state.sclagtmp1[i] = state.sclagtmp1[i]+augmentationfactor*vact;
                    }
                    if( state.hasau[i] && v>state.sclau[i] )
                    {
                        vact = v-state.sclau[i];
                        f = f+0.5*augmentationfactor*vact*vact;
                        state.sclagtmp1[i] = state.sclagtmp1[i]+augmentationfactor*vact;
                    }
                }
                sparse.sparsemtv(state.scla, state.sclagtmp1, ref state.sclagtmp0, _params);
                for(i=0; i<=n-1; i++)
                {
                    g[i] = g[i]+state.sclagtmp0[i];
                }
            }
            
            //
            // Lagrangian terms for nonlinear constraints
            //
            for(i=0; i<=nnlc-1; i++)
            {
                v = fi[1+i];
                vact = 0;
                vd = 0;
                if( state.hasnl[i] && v<state.scalednl[i] )
                {
                    vact = state.scalednl[i]-v;
                    vd = -1;
                }
                if( state.hasnu[i] && v>state.scalednu[i] )
                {
                    vact = v-state.scalednu[i];
                    vd = 1;
                }
                f = f+0.5*augmentationfactor*vact*vact;
                j0 = sj.ridx[1+i];
                j1 = sj.ridx[1+i+1]-1;
                v = augmentationfactor*vact*vd;
                for(jj=j0; jj<=j1; jj++)
                {
                    g[sj.idx[jj]] = g[sj.idx[jj]]+v*sj.vals[jj];
                }
            }
        }


        /*************************************************************************
        This function calculates target and constraint violation
        *************************************************************************/
        private static void targetandconstraints(minfsqpstate state,
            optserv.varsfuncjac vfj,
            ref double tgt,
            ref double cv,
            alglib.xparams _params)
        {
            int i = 0;
            int lccnt = 0;
            int nnlc = 0;
            double v = 0;
            double vv = 0;

            tgt = 0;
            cv = 0;

            lccnt = state.lccnt;
            nnlc = state.nnlc;
            
            //
            // Target and constraints: initial state
            //
            tgt = vfj.fi[0];
            cv = 0;
            
            //
            // Constraint violation
            //
            if( lccnt>0 )
            {
                apserv.rvectorsetlengthatleast(ref state.mftmp0, lccnt, _params);
                sparse.sparsemv(state.scla, vfj.x, ref state.mftmp0, _params);
                for(i=0; i<=lccnt-1; i++)
                {
                    v = state.mftmp0[i];
                    if( state.hasal[i] && v<state.sclal[i] )
                    {
                        vv = state.sclal[i]-v;
                        tgt = tgt+0.5*augmentationfactor*vv*vv;
                        cv = cv+vv;
                    }
                    if( state.hasau[i] && v>state.sclau[i] )
                    {
                        vv = v-state.sclau[i];
                        tgt = tgt+0.5*augmentationfactor*vv*vv;
                        cv = cv+vv;
                    }
                }
            }
            for(i=0; i<=nnlc-1; i++)
            {
                v = vfj.fi[1+i];
                if( state.hasnl[i] && v<state.scalednl[i] )
                {
                    vv = state.scalednl[i]-v;
                    cv = cv+vv;
                    tgt = tgt+0.5*augmentationfactor*vv*vv;
                }
                if( state.hasnu[i] && v>state.scalednu[i] )
                {
                    vv = v-state.scalednu[i];
                    cv = cv+vv;
                    tgt = tgt+0.5*augmentationfactor*vv*vv;
                }
            }
        }


        /*************************************************************************
        This function calculates predicted constraint violation at X1 using initial
        values at VFJ0 and linearized model of nonlinear constraints.
        *************************************************************************/
        private static void predictedconstraints(minfsqpstate state,
            optserv.varsfuncjac vfj0,
            double[] x1,
            ref double cv,
            alglib.xparams _params)
        {
            int i = 0;
            int lccnt = 0;
            int nnlc = 0;
            double v = 0;

            cv = 0;

            alglib.ap.assert(!vfj0.isdense, "SQP: 835006 failed");
            lccnt = state.lccnt;
            nnlc = state.nnlc;
            if( lccnt>0 )
            {
                apserv.rvectorsetlengthatleast(ref state.mftmp0, lccnt, _params);
                sparse.sparsemv(state.scla, x1, ref state.mftmp0, _params);
                for(i=0; i<=lccnt-1; i++)
                {
                    v = state.mftmp0[i];
                    if( state.hasal[i] && v<state.sclal[i] )
                    {
                        cv = cv+(state.sclal[i]-v);
                    }
                    if( state.hasau[i] && v>state.sclau[i] )
                    {
                        cv = cv+(v-state.sclau[i]);
                    }
                }
            }
            for(i=0; i<=nnlc-1; i++)
            {
                v = vfj0.fi[1+i]+(sparse.spdotvr(x1, vfj0.sj, 1+i, _params)-sparse.spdotvr(vfj0.x, vfj0.sj, 1+i, _params));
                if( state.hasnl[i] && v<state.scalednl[i] )
                {
                    cv = cv+(state.scalednl[i]-v);
                }
                if( state.hasnu[i] && v>state.scalednu[i] )
                {
                    cv = cv+(v-state.scalednu[i]);
                }
            }
        }


        /*************************************************************************
        This function calculates raw (unaugmented and smooth) Lagrangian
        *************************************************************************/
        private static double rawlagrangian(minfsqpstate state,
            double[] x,
            double[] fi,
            double[] lagbcmult,
            double[] lagxcmult,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            int n = 0;
            int lccnt = 0;
            int nnlc = 0;

            n = state.n;
            lccnt = state.lccnt;
            nnlc = state.nnlc;
            
            //
            // Lagrangian: primary term
            //
            result = fi[0];
            
            //
            // Lagrangian: handle box constraints
            //
            // NOTE: we do not add box constrained term to the merit function because
            //       box constraints are handled exactly and we do not violate them.
            //
            for(i=0; i<=n-1; i++)
            {
                result = result+lagbcmult[i]*x[i];
            }
            
            //
            // Merit function: augmentation and penalty for linear constraints
            //
            if( lccnt>0 )
            {
                apserv.rvectorsetlengthatleast(ref state.mftmp0, lccnt, _params);
                sparse.sparsemv(state.scla, x, ref state.mftmp0, _params);
                for(i=0; i<=lccnt-1; i++)
                {
                    result = result+lagxcmult[i]*state.mftmp0[i];
                }
            }
            
            //
            // Merit function: augmentation and penalty for nonlinear constraints
            //
            for(i=0; i<=nnlc-1; i++)
            {
                result = result+lagxcmult[lccnt+i]*fi[1+i];
            }
            return result;
        }


        /*************************************************************************
        Returns k-th component of the trust region

          -- ALGLIB --
             Copyright 25.09.2023 by Bochkanov Sergey
        *************************************************************************/
        private static double gettrustregionk(double[] xcur,
            int k,
            double trustrad,
            alglib.xparams _params)
        {
            double result = 0;

            result = trustrad*Math.Max(Math.Abs(xcur[k]), 1.0);
            return result;
        }


        /*************************************************************************
        Checks acceptability by the filter

          -- ALGLIB --
             Copyright 25.09.2023 by Bochkanov Sergey
        *************************************************************************/
        private static bool isacceptable(minfsqpstate state,
            double tgt0,
            double h0,
            double tgt1,
            double h1,
            double predictedchangemodel,
            double predictedchangepenalty,
            bool dotraceunacceptability,
            alglib.xparams _params)
        {
            bool result = new bool();

            if( (double)(tgt1)>=(double)(tgt0) && (double)(h1)>=(double)(h0) )
            {
                
                //
                // Neither the target nor constraints were improved
                //
                if( dotraceunacceptability )
                {
                    alglib.ap.trace("> the filter rejects step: both meritf and constraint violations increase\n");
                }
                result = false;
                return result;
            }
            if( (double)(predictedchangemodel)<(double)(0) && (double)(tgt1-tgt0)>(double)(sufficientdecreasesigma*predictedchangemodel) )
            {
                
                //
                // The model is predicted to decrease, but it does not decrease fast enough, or does not decrease at all
                //
                if( dotraceunacceptability )
                {
                    alglib.ap.trace("> the filter rejects step: sufficient decrease condition for meritf does not hold\n");
                }
                result = false;
                return result;
            }
            if( !optserv.nlpfisacceptable(state.filter, tgt0, h0, tgt1, h1, _params) )
            {
                
                //
                // Dominated by another point
                //
                if( dotraceunacceptability )
                {
                    if( state.filter.violationistoohigh )
                    {
                        alglib.ap.trace(System.String.Format("> the filter rejects step: constraint violation cv={0,0:E9} is too high (higher than maxcv={1,0:E9})\n", h1, state.filter.maxh));
                    }
                    else
                    {
                        alglib.ap.trace("> the filter rejects step: the new point is dominated\n");
                    }
                }
                result = false;
                return result;
            }
            result = true;
            return result;
        }


        /*************************************************************************
        Rescale target/constraints if gradients deviate from 1.0 too much. Compute
        diagonal scales for the Hessian.

        Parameters:
            Model               current function vector and Jacobian, already
                                scaled according to the present scaling.
            FirstScaling        if True, this function exactly normalizes everything,
                                except for the case when norms are less than 1.
                                If False, it tries to normalize but performs only
                                limited renormalization in order to avoid destabilization
                                of the process.

          -- ALGLIB --
             Copyright 23.02.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void autoscalevarstargetconstraints(minfsqpstate state,
            optserv.varsfuncjac model,
            bool firstscaling,
            bool dotrace,
            alglib.xparams _params)
        {
            int n = 0;
            int nnlc = 0;
            int i = 0;
            int j0 = 0;
            int j1 = 0;
            int jj = 0;
            double nrm2 = 0;
            double v = 0;
            double multiplyby = 0;
            double setscaleto = 0;
            bool wasrescale = new bool();
            bool bigscaletriggered = new bool();
            bool smallscaletriggered = new bool();

            alglib.ap.assert(!model.isdense, "FSQP: integrity check 3219 failed");
            n = state.n;
            nnlc = state.nnlc;
            
            //
            // Hessian scale
            //
            ablasf.rallocv(n, ref state.varscales, _params);
            for(i=0; i<=n-1; i++)
            {
                state.varscales[i] = gettrustregionk(state.stepk.x, i, 1.0, _params);
            }
            
            //
            // Target/constraints
            //
            wasrescale = false;
            bigscaletriggered = false;
            smallscaletriggered = false;
            for(i=0; i<=nnlc; i++)
            {
                
                //
                // Determine (a) multiplicative coefficient applied to function value
                // and Jacobian row, and (b) new value of the function scale.
                //
                j0 = model.sj.ridx[i];
                j1 = model.sj.ridx[i+1]-1;
                nrm2 = 0;
                for(jj=j0; jj<=j1; jj++)
                {
                    v = model.sj.vals[jj]*state.varscales[model.sj.idx[jj]];
                    nrm2 = nrm2+v*v;
                }
                nrm2 = Math.Sqrt(nrm2);
                multiplyby = 1.0;
                setscaleto = state.fscaleszzz[i];
                if( (double)(nrm2)>=(double)(state.sqpbigscale) )
                {
                    v = nrm2;
                    if( !firstscaling )
                    {
                        v = Math.Min(v, sqpmaxrescale);
                    }
                    multiplyby = 1/v;
                    setscaleto = state.fscaleszzz[i]*v;
                    bigscaletriggered = true;
                }
                if( (double)(nrm2)<=(double)(state.sqpsmallscale) && (double)(state.fscaleszzz[i])>(double)(1.0) )
                {
                    v = nrm2;
                    if( !firstscaling )
                    {
                        v = Math.Max(v, sqpminrescale);
                    }
                    if( (double)(state.fscaleszzz[i]*v)>(double)(1) )
                    {
                        multiplyby = 1/v;
                        setscaleto = state.fscaleszzz[i]*v;
                    }
                    else
                    {
                        multiplyby = state.fscaleszzz[i];
                        setscaleto = 1.0;
                    }
                    smallscaletriggered = true;
                }
                if( (double)(multiplyby)!=(double)(1.0) )
                {
                    model.fi[i] = model.fi[i]*multiplyby;
                    j0 = model.sj.ridx[i];
                    j1 = model.sj.ridx[i+1]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        model.sj.vals[jj] = model.sj.vals[jj]*multiplyby;
                    }
                    state.fscaleszzz[i] = setscaleto;
                    state.invfscales[i] = 1/setscaleto;
                    if( i>=1 )
                    {
                        if( state.hasnl[i-1] )
                        {
                            state.scalednl[i-1] = state.rawnl[i-1]/setscaleto;
                        }
                        if( state.hasnu[i-1] )
                        {
                            state.scalednu[i-1] = state.rawnu[i-1]/setscaleto;
                        }
                    }
                    wasrescale = true;
                }
            }
            if( wasrescale )
            {
                optserv.nlpfclear(state.filter, _params);
                if( dotrace )
                {
                    alglib.ap.trace("> target/constraints were rescaled due to gradient norms deviating too much from 1.0, filter cleared");
                }
                if( dotrace && bigscaletriggered )
                {
                    alglib.ap.trace(", downscaled");
                }
                if( smallscaletriggered )
                {
                    state.sqpsmallscale = state.sqpsmallscale*sqpsmallscaledecrease;
                    if( dotrace )
                    {
                        alglib.ap.trace(", upscaled and decreased the lower bound");
                    }
                }
                if( dotrace )
                {
                    alglib.ap.trace("\n");
                }
            }
        }


        /*************************************************************************
        Returns effective iteration limit (MaxIts + modification), given additional
        iterations for feasibility restoration:

        * 0 if MaxIts=0
        * otherwise: MaxIts if AddItsForCTol=0
        * otherwise: MaxIts if not WerePointsBelowCTol
        * otherwise: MaxIts if RepSclErr<=CTol
        : otherwise: MaxIts+AddItsForCTol

          -- ALGLIB --
             Copyright 10.06.2025 by Bochkanov Sergey
        *************************************************************************/
        private static int geteffectivemaxits(minfsqpstate state,
            alglib.xparams _params)
        {
            int result = 0;

            result = optserv.critgetmaxits(state.criteria, _params);
            if( (result==0 || state.additsforctol==0) || !state.werepointsbelowctol )
            {
                return result;
            }
            if( (double)(state.repsclerr)>(double)(state.ctol) )
            {
                result = result+state.additsforctol;
            }
            return result;
        }


        /*************************************************************************
        Convert sparse matrix to a dense one
        *************************************************************************/
        private static void sparse2dense(sparse.sparsematrix s,
            ref double[,] d,
            alglib.xparams _params)
        {
            int i = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;

            alglib.ap.assert((s.matrixtype==1 && s.m>=1) && s.n>=1, "SQP: integrity check 5541 failed");
            ablasf.rsetallocm(s.m, s.n, 0.0, ref d, _params);
            for(i=0; i<=s.m-1; i++)
            {
                j0 = s.ridx[i];
                j1 = s.ridx[i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    d[i,s.idx[jj]] = s.vals[jj];
                }
            }
        }


        /*************************************************************************
        Append matrix row multiplied by a scaling factor; silently switches
        MatrixType=-10083 to MatrixType=1
        *************************************************************************/
        private static void appendscaledsparserow(sparse.sparsematrix dst,
            double alpha,
            sparse.sparsematrix src,
            int rowidx,
            alglib.xparams _params)
        {
            int m = 0;
            int offs = 0;
            int j0 = 0;
            int j1 = 0;
            int jj = 0;
            int nnz = 0;

            alglib.ap.assert((dst.matrixtype==1 || dst.matrixtype==-10083) && dst.ninitialized==dst.ridx[dst.m], "FSQP.AppendScaledSparseRow: Dst is not completely initialized");
            m = dst.m;
            offs = dst.ridx[m];
            j0 = src.ridx[rowidx];
            j1 = src.ridx[rowidx+1]-1;
            nnz = j1-j0+1;
            dst.matrixtype = 1;
            ablasf.igrowv(m+1, ref dst.didx, _params);
            ablasf.igrowv(m+1, ref dst.uidx, _params);
            ablasf.igrowv(m+2, ref dst.ridx, _params);
            ablasf.igrowv(dst.ridx[m]+nnz, ref dst.idx, _params);
            ablasf.rgrowv(dst.ridx[m]+nnz, ref dst.vals, _params);
            offs = dst.ridx[m];
            for(jj=j0; jj<=j1; jj++)
            {
                dst.idx[offs] = src.idx[jj];
                dst.vals[offs] = alpha*src.vals[jj];
                offs = offs+1;
            }
            dst.ridx[m+1] = offs;
            dst.didx[m] = apserv.ibinarysearchlft(dst.idx, dst.ridx[m], dst.ridx[m+1], m, _params);
            dst.uidx[m] = dst.didx[m]+apserv.icase2(dst.didx[m]<dst.ridx[m+1] && dst.idx[dst.didx[m]]==m, 1, 0, _params);
            dst.ninitialized = dst.ridx[m+1];
            dst.m = m+1;
        }


    }
