        public const double defaultpenalty = 100;
        public const int paramscnt = 4;
        public const int minpowerupits = 10;
        public const int minpopsizefortightening = 5;
        public const double tighteningmu = 0.66;
        public const double bndlimit = 0.85;
        public const double mulearningrate = 0.2;
        public const int stcurrenttobest1 = 2;
        public const int stcurrenttoordbest1 = 10;


        public static void gdemoinitbuf(double[] bndl,
            double[] bndu,
            double[] s,
            int n,
            int m,
            double[,] a,
            double[] al,
            double[] au,
            int cntlc,
            double[] nl,
            double[] nu,
            int cntnlc,
            int popsize,
            int epochscnt,
            int seed,
            gdemostate state,
            alglib.xparams _params)
        {
            int i = 0;

            
            //
            // Integrity checks
            //
            alglib.ap.assert(m==1, "GDEMO: M<>1");
            alglib.ap.assert(popsize>=0, "GDEMO: PopSize<=0");
            alglib.ap.assert(epochscnt>0, "GDEMO: EpochsCnt<=0");
            
            //
            // Initialization
            //
            popsize = Math.Max(apserv.coalescei(popsize, 10*n, _params), 10);
            state.n = n;
            state.m = m;
            state.cntlc = cntlc;
            state.cntnlc = cntnlc;
            state.popsize = popsize;
            state.epochscnt = epochscnt;
            state.constrmode = 0;
            state.rho1 = defaultpenalty;
            state.rho2 = defaultpenalty;
            state.eps = 0.0;
            state.nsample = 1;
            state.fixedparams = false;
            state.hasx0 = false;
            state.stoponsmallf = false;
            state.condfxepsf = 0.0;
            state.condfxepsx = 0.0;
            if( seed<=0 )
            {
                seed = math.randominteger(30000);
            }
            hqrnd.hqrndseed(seed, seed+1172, state.rs, _params);
            ablasf.rsetallocm(m, n, 0.0, ref state.xbest, _params);
            ablasf.rsetallocv(m, Double.NaN, ref state.fitbest, _params);
            ablasf.rsetallocv(m, Double.NaN, ref state.rawfbest, _params);
            gdemosetprofile(state, 0, _params);
            
            //
            // Prepare RCOMM state
            //
            state.rstate.ia = new int[10+1];
            state.rstate.ba = new bool[2+1];
            state.rstate.ra = new double[3+1];
            state.rstate.stage = -1;
            state.rstate.clear_handler();
            
            //
            // Prepare scaled problem
            //
            ablasf.rallocv(n, ref state.s, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndl, n, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndu, n, _params);
            ablasf.rsetallocv(n, -math.maxrealnumber, ref state.finitebndl, _params);
            ablasf.rsetallocv(n, math.maxrealnumber, ref state.finitebndu, _params);
            for(i=0; i<=n-1; i++)
            {
                state.hasbndl[i] = math.isfinite(bndl[i]);
                state.hasbndu[i] = math.isfinite(bndu[i]);
                if( state.hasbndl[i] )
                {
                    state.finitebndl[i] = bndl[i]/s[i];
                }
                if( state.hasbndu[i] )
                {
                    state.finitebndu[i] = bndu[i]/s[i];
                }
                if( state.hasbndl[i] && state.hasbndu[i] )
                {
                    alglib.ap.assert((double)(bndl[i])<=(double)(bndu[i]), "GDEMO: integrity check failed, box constraints are inconsistent");
                }
                state.s[i] = s[i];
            }
            if( cntlc>0 )
            {
                ablasf.rsetallocv(n, 0.0, ref state.tmpzero, _params);
                ablasf.rcopyallocm(cntlc, n, a, ref state.densea, _params);
                ablasf.rcopyallocv(cntlc, al, ref state.al, _params);
                ablasf.rcopyallocv(cntlc, au, ref state.au, _params);
                lpqpserv.scaleshiftmixedlcinplace(s, state.tmpzero, n, state.dummysparsea, 0, state.densea, cntlc, state.al, state.au, _params);
                lpqpserv.normalizedenselcinplace(state.densea, cntlc, state.al, state.au, n, true, ref state.ascales, true, _params);
                ablasf.ballocv(cntlc, ref state.hasal, _params);
                ablasf.ballocv(cntlc, ref state.hasau, _params);
                for(i=0; i<=cntlc-1; i++)
                {
                    state.hasal[i] = math.isfinite(state.al[i]);
                    state.hasau[i] = math.isfinite(state.au[i]);
                }
            }
            if( cntnlc>0 )
            {
                ablasf.rcopyallocv(cntnlc, nl, ref state.rawnl, _params);
                ablasf.rcopyallocv(cntnlc, nu, ref state.rawnu, _params);
                ablasf.ballocv(cntnlc, ref state.hasnl, _params);
                ablasf.ballocv(cntnlc, ref state.hasnu, _params);
                for(i=0; i<=cntnlc-1; i++)
                {
                    state.hasnl[i] = math.isfinite(state.rawnl[i]);
                    state.hasnu[i] = math.isfinite(state.rawnu[i]);
                }
            }
        }


        /*************************************************************************
        Sets performance profile:
