        /*************************************************************************
        This function performs actual processing for GDEMO  algorithm.

          -- ALGLIB --
             Copyright 07.12.2023 by Bochkanov Sergey
        *************************************************************************/
        public static bool gdemoiteration(gdemostate state,
            bool userterminationneeded,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int m = 0;
            int cntlc = 0;
            int cntnlc = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            int k1 = 0;
            double v = 0;
            double vv = 0;
            double vleft = 0;
            double vright = 0;
            bool dotrace = new bool();
            bool dodetailedtrace = new bool();
            int popsize = 0;
            int residualsize = 0;
            int iteridx = 0;
            bool bad = new bool();

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rstate.stage>=0 )
            {
                n = state.rstate.ia[0];
                m = state.rstate.ia[1];
                cntlc = state.rstate.ia[2];
                cntnlc = state.rstate.ia[3];
                i = state.rstate.ia[4];
                j = state.rstate.ia[5];
                k = state.rstate.ia[6];
                k1 = state.rstate.ia[7];
                popsize = state.rstate.ia[8];
                residualsize = state.rstate.ia[9];
                iteridx = state.rstate.ia[10];
                dotrace = state.rstate.ba[0];
                dodetailedtrace = state.rstate.ba[1];
                bad = state.rstate.ba[2];
                v = state.rstate.ra[0];
                vv = state.rstate.ra[1];
                vleft = state.rstate.ra[2];
                vright = state.rstate.ra[3];
            }
            else
            {
                n = 359;
                m = -58;
                cntlc = -919;
                cntnlc = -909;
                i = 81;
                j = 255;
                k = 74;
                k1 = -788;
                popsize = 809;
                residualsize = 205;
                iteridx = -838;
                dotrace = true;
                dodetailedtrace = false;
                bad = true;
                v = -541.0;
                vv = -698.0;
                vleft = -900.0;
                vright = -318.0;
            }
            if( state.rstate.stage==0 )
            {
                goto lbl_0;
            }
            if( state.rstate.stage==1 )
            {
                goto lbl_1;
            }
            if( state.rstate.stage==2 )
            {
                goto lbl_2;
            }
            if( state.rstate.stage==3 )
            {
                goto lbl_3;
            }
            
            //
            // Routine body
            //
            n = state.n;
            m = state.m;
            cntlc = state.cntlc;
            cntnlc = state.cntnlc;
            popsize = state.popsize;
            dotrace = ap.istraceenabled("GDEMO", _params);
            dodetailedtrace = dotrace && ap.istraceenabled("GDEMO.DETAILED", _params);
            alglib.ap.assert(m==1, "GDEMO: integrity check 0732 failed");
            
            //
            // Init
            //
            state.repiterationscount = 0;
            state.repterminationtype = 5;
            state.replcerr = 0.0;
            state.replcidx = -1;
            state.repnlcerr = 0.0;
            state.repnlcidx = -1;
            ablasf.rallocv(n, ref state.reportx, _params);
            if( dotrace )
            {
                alglib.ap.trace("\n\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace("//  GDEMO SOLVER HAS STARTED                                                                      //\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace(System.String.Format("N             = {0,6:d}\n", n));
                alglib.ap.trace(System.String.Format("M             = {0,6:d}\n", m));
                alglib.ap.trace(System.String.Format("cntLC         = {0,6:d}\n", cntlc));
                alglib.ap.trace(System.String.Format("cntNLC        = {0,6:d}\n", cntnlc));
                alglib.ap.trace("parameters    = ");
                if( state.fixedparams )
                {
                    alglib.ap.trace("fixed\n");
                }
                else
                {
                    alglib.ap.trace("adaptive\n");
                }
            }
            
            //
            // Initial state of memory, pools, etc
            //
            state.mucr = 0.5;
            state.muf = 0.5;
            
            //
            // Generate initial population, perform several iterations dropping invalid candidates
            // (ones with infinite target/constraint values) until the entire population is generated:
            // * generate initial population using INIT heuristic, compute empirical bounds (per-variable
            //   max and min of population elements)
            // * repeatedly query targets, keep good ones, drop bad ones, tighten empirical bounds
            //   approaching them closer to points that resulted in good values
            //
            state.population.cnt = popsize;
            ablasf.rallocm(popsize, n, ref state.population.x, _params);
            ablasf.rallocm(popsize, m+cntnlc, ref state.population.rawreplies, _params);
            ablasf.rallocm(popsize, m, ref state.population.fitness, _params);
            ablasf.rsetallocm(popsize, paramscnt, 0.0, ref state.population.deparams, _params);
            ablasf.rallocv(n, ref state.empiricalbndl, _params);
            ablasf.rallocv(n, ref state.empiricalbndu, _params);
            for(i=0; i<=popsize-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    if( state.hasx0 && i==0 )
                    {
                        
                        //
                        // Add user-provided initial point to the population
                        //
                        state.population.x[i,j] = apserv.boundval(state.x0[j], state.finitebndl[j], state.finitebndu[j], _params);
                    }
                    else
                    {
                        
                        //
                        // Generate population individual using hints from box constraints
                        //
                        if( state.hasbndl[j] && state.hasbndu[j] )
                        {
                            state.population.x[i,j] = state.finitebndl[j]+(state.finitebndu[j]-state.finitebndl[j])*hqrnd.hqrnduniformr(state.rs, _params);
                            continue;
                        }
                        if( state.hasbndl[j] && !state.hasbndu[j] )
                        {
                            state.population.x[i,j] = state.finitebndl[j]+Math.Pow(2, hqrnd.hqrndnormal(state.rs, _params));
                            continue;
                        }
                        if( state.hasbndu[j] && !state.hasbndl[j] )
                        {
                            state.population.x[i,j] = state.finitebndu[j]-Math.Pow(2, hqrnd.hqrndnormal(state.rs, _params));
                            continue;
                        }
                        state.population.x[i,j] = hqrnd.hqrndnormal(state.rs, _params);
                    }
                }
                if( i==0 )
                {
                    ablasf.rcopyrv(n, state.population.x, i, state.empiricalbndl, _params);
                    ablasf.rcopyrv(n, state.population.x, i, state.empiricalbndu, _params);
                }
                else
                {
                    ablasf.rmergeminrv(n, state.population.x, i, state.empiricalbndl, _params);
                    ablasf.rmergemaxrv(n, state.population.x, i, state.empiricalbndu, _params);
                }
            }
            ablasf.rsetallocv(n, math.maxrealnumber, ref state.goodbndl, _params);
            ablasf.rsetallocv(n, -math.maxrealnumber, ref state.goodbndu, _params);
            residualsize = popsize;
            iteridx = 0;
        lbl_4:
            if( iteridx>Math.Max(minpowerupits, (int)Math.Round(0.25*state.epochscnt))-1 )
            {
                goto lbl_6;
            }
            
            //
            // query target values
            //
            state.requesttype = 4;
            state.querysize = residualsize;
            ablasf.rallocv(n*residualsize, ref state.querydata, _params);
            for(i=0; i<=residualsize-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    state.querydata[i*n+j] = state.population.x[i,j];
                }
            }
            ablasf.rallocv(residualsize*(m+cntnlc), ref state.replyfi, _params);
            state.rstate.stage = 0;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
            for(i=0; i<=residualsize-1; i++)
            {
                for(j=0; j<=m+cntnlc-1; j++)
                {
                    state.population.rawreplies[i,j] = state.replyfi[i*(m+cntnlc)+j];
                }
            }
            
            //
            // Move good candidates (ones with finite targets/constraints) to the end, decrease residual size
            //
            i = residualsize-1;
            while( i>=0 )
            {
                bad = false;
                for(j=0; j<=m+cntnlc-1; j++)
                {
                    bad = bad || !math.isfinite(state.population.rawreplies[i,j]);
                }
                if( !bad )
                {
                    
                    //
                    // Move candidate to the end of the current subpopulation, update box containing good values, decrease residual size
                    //
                    if( i!=residualsize-1 )
                    {
                        ablasf.rcopyrr(n, state.population.x, i, state.population.x, residualsize-1, _params);
                        ablasf.rcopyrr(m+cntnlc, state.population.rawreplies, i, state.population.rawreplies, residualsize-1, _params);
                    }
                    ablasf.rmergeminrv(n, state.population.x, residualsize-1, state.goodbndl, _params);
                    ablasf.rmergemaxrv(n, state.population.x, residualsize-1, state.goodbndu, _params);
                    residualsize = residualsize-1;
                }
                i = i-1;
            }
            if( residualsize==0 )
            {
                goto lbl_6;
            }
            
            //
            // Tighten empirical bounds used to generate new candidates. 
            //
            if( residualsize<=popsize-minpopsizefortightening )
            {
                alglib.ap.assert(minpopsizefortightening>=2, "GDEMO: integrity check 0618 failed");
                for(j=0; j<=n-1; j++)
                {
                    state.empiricalbndl[j] = tighteningmu*state.empiricalbndl[j]+(1-tighteningmu)*state.goodbndl[j];
                    state.empiricalbndu[j] = tighteningmu*state.empiricalbndu[j]+(1-tighteningmu)*state.goodbndu[j];
                }
            }
            
            //
            // Generate new candidates in the empirical box
            //
            for(i=0; i<=residualsize-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    state.population.x[i,j] = state.empiricalbndl[j]+(state.empiricalbndu[j]-state.empiricalbndl[j])*hqrnd.hqrnduniformr(state.rs, _params);
                }
            }
            iteridx = iteridx+1;
            goto lbl_4;
        lbl_6:
            if( residualsize>0 )
            {
                
                //
                // We failed to generate complete population, return with error
                //
                state.repterminationtype = -8;
                result = false;
                return result;
            }
            computefitness(state, state.population, false, state.population, _params);
            updatebest(state, _params);
            alglib.ap.assert(m==1, "GDEMO: integrity check 566226 failed");
            state.requesttype = -1;
            ablasf.rallocv(n, ref state.reportx, _params);
            ablasf.rcopyrv(n, state.xbest, 0, state.reportx, _params);
            state.reportf = state.rawfbest[0];
            state.rstate.stage = 1;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            
            //
            // Run iterations
            //
            if( dotrace )
            {
                alglib.ap.trace(System.String.Format("> ALGLIB GDEMO solver started, {0,0:d} variables, {1,0:d} linear constraints, {2,0:d} general constraints\n", n, cntlc, cntnlc));
                alglib.ap.trace("   ITS                 MERIT FUNC                  OBJECTIVE      muCR       muF\n");
            }
            iteridx = 0;
        lbl_7:
            if( iteridx>state.epochscnt-1 )
            {
                goto lbl_9;
            }
            if( dotrace )
            {
                i = 0;
                if( state.repiterationscount<=10 )
                {
                    i = 1;
                }
                if( state.repiterationscount<=100 && state.repiterationscount%5==0 )
                {
                    i = 1;
                }
                if( state.repiterationscount%50==0 )
                {
                    i = 1;
                }
                if( i>0 )
                {
                    alglib.ap.trace(System.String.Format("{0,6:d}    {1,23:E15}    {2,23:E15}    {3,16:F14}    {4,16:F14}\n", state.repiterationscount, state.fitbest[0], state.rawfbest[0], state.mucr, state.muf));
                }
            }
            
            //
            // Generate candidates
            //
            generatetrialpoints(state, state.population, state.offspring, _params);
            
            //
            // RComm request and fitness computation
            //
            state.requesttype = 4;
            state.querysize = state.offspring.cnt;
            ablasf.rallocv(n*state.offspring.cnt, ref state.querydata, _params);
            for(i=0; i<=state.offspring.cnt-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    state.querydata[i*n+j] = state.offspring.x[i,j];
                }
            }
            ablasf.rallocv(state.offspring.cnt*(m+cntnlc), ref state.replyfi, _params);
            state.rstate.stage = 2;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_2:
            for(i=0; i<=state.offspring.cnt-1; i++)
            {
                for(j=0; j<=m+cntnlc-1; j++)
                {
                    state.offspring.rawreplies[i,j] = state.replyfi[i*(m+cntnlc)+j];
                }
            }
            computefitness(state, state.population, true, state.offspring, _params);
            
            //
            // Update population with candidates
            //
            updatepopulation(state, state.offspring, _params);
            
            //
            // Update best value so far and other counters, check stopping criteria
            //
            updatebest(state, _params);
            alglib.ap.assert(m==1, "GDEMO: integrity check 566226 failed");
            state.requesttype = -1;
            ablasf.rallocv(n, ref state.reportx, _params);
            ablasf.rcopyrv(n, state.xbest, 0, state.reportx, _params);
            state.reportf = state.rawfbest[0];
            state.rstate.stage = 3;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_3:
            state.repiterationscount = state.repiterationscount+1;
            if( (state.stoponsmallf && m==1) && (double)(state.rawfbest[0])<=(double)(state.smallf) )
            {
                state.repterminationtype = 6;
                goto lbl_9;
            }
            if( ((double)(state.condfxepsf)>(double)(0) || (double)(state.condfxepsx)>(double)(0)) && m==1 )
            {
                alglib.ap.assert(!Double.IsNaN(state.fitbest[0]), "GDEMO: integrity check 2618 failed");
                
                //
                // Count agents within EpsF near the optimal one
                //
                k = 0;
                k1 = 0;
                v = state.fitbest[0]+state.condfxepsf*apserv.rmaxabs2(state.fitbest[0], 1.0, _params);
                for(i=0; i<=popsize-1; i++)
                {
                    
                    //
                    // Try to filter out individuals based on:
                    // * target value (if epsF>0); tried first because it is the cheapest condition
                    // * distance towards the best one
                    //
                    if( state.condfxepsf>0.0 && state.population.fitness[i,0]>v )
                    {
                        continue;
                    }
                    k = k+1;
                    if( state.condfxepsx>0.0 )
                    {
                        vv = 0.0;
                        for(j=0; j<=n-1; j++)
                        {
                            vv = vv+(state.population.x[i,j]-state.xbest[0,j])*(state.population.x[i,j]-state.xbest[0,j]);
                        }
                        if( vv/n>state.condfxepsx*state.condfxepsx )
                        {
                            continue;
                        }
                    }
                    k1 = k1+1;
                }
                if( (double)(k)>=(double)(Math.Min(2*n+1, popsize)) && (double)(k1)>=(double)(Math.Min(2*n+1, popsize)) )
                {
                    state.repterminationtype = 1;
                    goto lbl_9;
                }
            }
            iteridx = iteridx+1;
            goto lbl_7;
        lbl_9:
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rstate.ia[0] = n;
            state.rstate.ia[1] = m;
            state.rstate.ia[2] = cntlc;
            state.rstate.ia[3] = cntnlc;
            state.rstate.ia[4] = i;
            state.rstate.ia[5] = j;
            state.rstate.ia[6] = k;
            state.rstate.ia[7] = k1;
            state.rstate.ia[8] = popsize;
            state.rstate.ia[9] = residualsize;
            state.rstate.ia[10] = iteridx;
            state.rstate.ba[0] = dotrace;
            state.rstate.ba[1] = dodetailedtrace;
            state.rstate.ba[2] = bad;
            state.rstate.ra[0] = v;
            state.rstate.ra[1] = vv;
            state.rstate.ra[2] = vleft;
            state.rstate.ra[3] = vright;
            return result;
        }


        /*************************************************************************
        Compute fitness from raw replies

        INPUT PARAMETERS:
            State                   -   solver
            Population2RawReplies   -   present population, used by fitness computation
                                        methods which analyze distribution of constraint
                                        violations in the current population
            PopSize                 -   population size, or zero, if this
                                        function is called at the initialization
                                        phase when we compute fitness for the initial
                                        population
            RawReplies              -   raw replies to process
            BatchSize               -   size of the set being processed
            Fitness                 -   preallocated output array
            

          -- ALGLIB --
             Copyright 07.12.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void computefitness(gdemostate state,
            gdemopopulation refpopulation,
            bool hasreference,
            gdemopopulation trial,
            alglib.xparams _params)
        {
            int n = 0;
            int m = 0;
            int cntlc = 0;
            int cntnlc = 0;
            int i = 0;
            int j = 0;
            double p = 0;
            double v = 0;
            double vv = 0;
            bool bad = new bool();

            n = state.n;
            m = state.m;
            cntlc = state.cntlc;
            cntnlc = state.cntnlc;
            alglib.ap.assert(alglib.ap.rows(trial.fitness)>=trial.cnt && alglib.ap.cols(trial.fitness)>=m, "GDEMO: integrity check 5831 failed");
            alglib.ap.assert((double)(state.nsample)==(double)(1), "GDEMO: integrity check 5632 failed");
            
            //
            // Quick exit
            //
            if( cntlc+cntnlc==0 )
            {
                for(i=0; i<=trial.cnt-1; i++)
                {
                    bad = false;
                    for(j=0; j<=m-1; j++)
                    {
                        v = trial.rawreplies[i,j];
                        trial.fitness[i,j] = v;
                        bad = bad || !math.isfinite(v);
                    }
                    if( bad )
                    {
                        for(j=0; j<=m-1; j++)
                        {
                            trial.fitness[i,j] = math.maxrealnumber;
                        }
                    }
                }
                return;
            }
            
            //
            // Default constraint handling strategy: L1 penalty
            //
            if( state.constrmode==0 )
            {
                for(i=0; i<=trial.cnt-1; i++)
                {
                    
                    //
                    // Handle bad targets/constraints
                    //
                    bad = false;
                    for(j=0; j<=m+cntnlc-1; j++)
                    {
                        bad = bad || !math.isfinite(trial.rawreplies[i,j]);
                    }
                    if( bad )
                    {
                        for(j=0; j<=m-1; j++)
                        {
                            trial.fitness[i,j] = math.maxrealnumber;
                        }
                        continue;
                    }
                    
                    //
                    // No infinities, normal processing
                    //
                    p = 0;
                    for(j=0; j<=cntlc-1; j++)
                    {
                        v = ablasf.rdotrr(n, trial.x, i, state.densea, j, _params);
                        if( state.hasal[j] )
                        {
                            vv = Math.Max(state.al[j]-v, 0.0);
                            p = p+state.rho1*vv+state.rho2*vv*vv;
                        }
                        if( state.hasau[j] )
                        {
                            vv = Math.Max(v-state.au[j], 0.0);
                            p = p+state.rho1*vv+state.rho2*vv*vv;
                        }
                    }
                    for(j=0; j<=cntnlc-1; j++)
                    {
                        v = trial.rawreplies[i,m+j];
                        if( state.hasnl[j] )
                        {
                            vv = Math.Max(state.rawnl[j]-v, 0.0);
                            p = p+state.rho1*vv+state.rho2*vv*vv;
                        }
                        if( state.hasnu[j] )
                        {
                            vv = Math.Max(v-state.rawnu[j], 0.0);
                            p = p+state.rho1*vv+state.rho2*vv*vv;
                        }
                    }
                    for(j=0; j<=m-1; j++)
                    {
                        trial.fitness[i,j] = trial.rawreplies[i,j]+p;
                    }
                }
                return;
            }
            
            //
            // Unknown constrmode
            //
            alglib.ap.assert(false, "GDEMO: integrity check 2202 failed");
        }


        /*************************************************************************
        Updates best value so far. For multiobjective models - fails.

          -- ALGLIB --
             Copyright 07.12.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void updatebest(gdemostate state,
            alglib.xparams _params)
        {
            int n = 0;
            int m = 0;
            int cntlc = 0;
            int cntnlc = 0;
            int i = 0;
            int j = 0;
            double v = 0;
            double vv = 0;

            n = state.n;
            m = state.m;
            cntlc = state.cntlc;
            cntnlc = state.cntnlc;
            alglib.ap.assert((double)(state.nsample)==(double)(1), "GDEMO: integrity check 9242 failed");
            alglib.ap.assert(m==1, "GDEMO: integrity check 9243 failed");
            for(i=0; i<=state.population.cnt-1; i++)
            {
                if( Double.IsNaN(state.fitbest[0]) || (double)(state.population.fitness[i,0])<(double)(state.fitbest[0]) )
                {
                    
                    //
                    // Save best value
                    //
                    ablasf.rcopyrr(n, state.population.x, i, state.xbest, 0, _params);
                    state.fitbest[0] = state.population.fitness[i,0];
                    state.rawfbest[0] = state.population.rawreplies[i,0];
                    
                    //
                    // Update errors
                    //
                    state.replcerr = 0.0;
                    state.replcidx = -1;
                    for(j=0; j<=cntlc-1; j++)
                    {
                        v = ablasf.rdotrr(n, state.xbest, 0, state.densea, j, _params);
                        if( state.hasal[j] )
                        {
                            vv = state.ascales[j]*Math.Max(state.al[j]-v, 0.0);
                            if( (double)(vv)>(double)(state.replcerr) )
                            {
                                state.replcerr = vv;
                                state.replcidx = j;
                            }
                        }
                        if( state.hasau[j] )
                        {
                            vv = state.ascales[j]*Math.Max(v-state.au[j], 0.0);
                            if( (double)(vv)>(double)(state.replcerr) )
                            {
                                state.replcerr = vv;
                                state.replcidx = j;
                            }
                        }
                    }
                    state.repnlcerr = 0.0;
                    state.repnlcidx = -1;
                    for(j=0; j<=cntnlc-1; j++)
                    {
                        v = state.population.rawreplies[i,m+j];
                        if( state.hasnl[j] )
                        {
                            vv = Math.Max(state.rawnl[j]-v, 0.0);
                            if( (double)(vv)>(double)(state.repnlcerr) )
                            {
                                state.repnlcerr = vv;
                                state.repnlcidx = j;
                            }
                        }
                        if( state.hasnu[j] )
                        {
                            vv = Math.Max(v-state.rawnu[j], 0.0);
                            if( (double)(vv)>(double)(state.repnlcerr) )
                            {
                                state.repnlcerr = vv;
                                state.repnlcidx = j;
                            }
                        }
                    }
                }
            }
        }


        /*************************************************************************
        This function generates candidates

          -- ALGLIB --
             Copyright 07.12.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void generatetrialpoints(gdemostate state,
            gdemopopulation population,
            gdemopopulation trial,
            alglib.xparams _params)
        {
            int n = 0;
            int m = 0;
            int rngmax = 0;
            double invmax = 0;
            int i = 0;
            int popsize = 0;
            double v0 = 0;
            double v1 = 0;

            n = state.n;
            m = state.m;
            popsize = state.popsize;
            alglib.ap.assert(m==1, "GDEMO: integrity check 4959 failed");
            rngmax = hqrnd.hqrndgetmax(_params);
            invmax = (double)1/(double)rngmax;
            
            //
            // Generate DE parameters for candidates and allocate space
            //
            alglib.ap.assert(popsize>=10, "GDEMO: integrity check 7156 failed");
            ablasf.rgrowrowsfixedcolsm(popsize, n, ref trial.x, _params);
            ablasf.rgrowrowsfixedcolsm(popsize, m+state.cntnlc, ref trial.rawreplies, _params);
            ablasf.rgrowrowsfixedcolsm(popsize, m, ref trial.fitness, _params);
            ablasf.rgrowrowsfixedcolsm(popsize, paramscnt, ref trial.deparams, _params);
            trial.cnt = 0;
            for(i=0; i<=popsize-1; i++)
            {
                alglib.ap.assert(paramscnt==4, "GDEMO: integrity check 6759 failed");
                if( state.fixedparams )
                {
                    trial.deparams[trial.cnt,0] = state.fixedstrategy;
                    trial.deparams[trial.cnt,1] = state.fixedcrossoverprob;
                    trial.deparams[trial.cnt,2] = state.fixeddifferentialweight;
                    trial.deparams[trial.cnt,3] = state.fixeddifferentialweight;
                }
                else
                {
                    
                    //
                    // Generate a pair of normal numbers V0 and V1, with V1 being guarded away from zero.
                    //
                    // Use V0 to compute perturbed CR, and use V1 (or ratio V0/V1) to compute perturbed F.
                    // Because V0 is sometimes used to perturb both CR and F, there is some inter-dependence
                    // between two perturbations. However, numerical experiments show that it does not
                    // impact algorithm convergence.
                    //
                    trial.deparams[trial.cnt,0] = stcurrenttoordbest1;
                    do
                    {
                        hqrnd.hqrndnormal2(state.rs, ref v0, ref v1, _params);
                    }
                    while( (double)(Math.Abs(v1))<=(double)(1.0E-9) );
                    trial.deparams[trial.cnt,1] = apserv.boundval(state.mucr+0.1*v0, 0.01, 1, _params);
                    if( state.profile==0 )
                    {
                        
                        //
                        // Use 'ROBUST' profile for DE weight
                        //
                        trial.deparams[trial.cnt,2] = apserv.boundval(state.muf+0.1*(v0/v1), 0.01, 2, _params);
                    }
                    else
                    {
                        
                        //
                        // Use 'QUICK' profile for DE weight
                        //
                        trial.deparams[trial.cnt,2] = apserv.boundval(state.muf+0.1*(2.0*(hqrnd.hqrndintegerbase(state.rs, _params)*invmax)-1), 0.01, 1, _params);
                    }
                    trial.deparams[trial.cnt,3] = trial.deparams[trial.cnt,2];
                }
                trial.cnt = trial.cnt+1;
            }
            alglib.ap.assert(trial.cnt==popsize, "GDEMO: integrity check 0719 failed");
            
            //
            // Generate candidates
            //
            gencand(trial.deparams, population.x, population.fitness, n, m, popsize, state.xbest, state.finitebndl, state.finitebndu, state.rs, trial.x, _params);
        }


        /*************************************************************************
        This is an internal function that generates candidates given DE params

          -- ALGLIB --
             Copyright 07.12.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void gencand(double[,] deparams,
            double[,] populationx,
            double[,] populationfitness,
            int n,
            int m,
            int popsize,
            double[,] xbest,
            double[] finitebndl,
            double[] finitebndu,
            hqrnd.hqrndstate rs,
            double[,] trialx,
            alglib.xparams _params)
        {
            int rngmax = 0;
            double invmax = 0;
            int i = 0;
            int j = 0;
            int k0 = 0;
            int k1 = 0;
            int k2 = 0;
            int k3 = 0;
            int r = 0;
            bool processed = new bool();
            int strategytype = 0;
            double crossoverprob = 0;
            double differentialweight = 0;
            double differentialweight2 = 0;
            double[] donor = new double[0];
            double[] donorbase = new double[0];

            
            //
            // Try fast kernel
            //
            if( gdemogencandkernel(deparams, populationx, populationfitness, n, m, popsize, xbest, finitebndl, finitebndu, bndlimit, hqrnd.hqrndintegerbase(rs, _params), trialx, _params) )
            {
                return;
            }
            
            //
            // Use generic code
            //
            alglib.ap.assert(m==1, "GDEMO: integrity check 4959 failed");
            alglib.ap.assert(popsize>=10, "GDEMO: integrity check 7156 failed");
            alglib.ap.assert(alglib.ap.rows(trialx)>=popsize && alglib.ap.cols(trialx)>=n, "GDEMO: integrity check 7530 failed");
            rngmax = hqrnd.hqrndgetmax(_params);
            invmax = (double)1/(double)rngmax;
            ablasf.rallocv(n, ref donor, _params);
            ablasf.rallocv(n, ref donorbase, _params);
            for(i=0; i<=popsize-1; i++)
            {
                
                //
                // Load candidate parameters
                //
                strategytype = (int)Math.Round(deparams[i,0]);
                crossoverprob = deparams[i,1];
                differentialweight = deparams[i,2];
                differentialweight2 = deparams[i,3];
                
                //
                // Generate a set of 4 indexes, possibly nondistinct (enforcing distinctness makes the code slower,
                // whislt not providing significant improvement in quality)
                //
                k0 = hqrnd.hqrndintegerbase(rs, _params)%popsize;
                k1 = hqrnd.hqrndintegerbase(rs, _params)%popsize;
                k2 = hqrnd.hqrndintegerbase(rs, _params)%popsize;
                k3 = hqrnd.hqrndintegerbase(rs, _params)%popsize;
                
                //
                // Generate donor vector
                //
                processed = false;
                if( strategytype==0 )
                {
                    
                    //
                    // DE/rand/1
                    //
                    ablasf.rcopyrv(n, populationx, k0, donor, _params);
                    ablasf.raddrv(n, -1.0, populationx, k1, donor, _params);
                    ablasf.rmulv(n, differentialweight, donor, _params);
                    ablasf.rcopyrv(n, populationx, k2, donorbase, _params);
                    processed = true;
                }
                if( strategytype==1 )
                {
                    
                    //
                    // DE/best/2
                    //
                    ablasf.rsetv(n, 0.0, donor, _params);
                    ablasf.raddrv(n, 1.0, populationx, k0, donor, _params);
                    ablasf.raddrv(n, -1.0, populationx, k1, donor, _params);
                    ablasf.raddrv(n, 1.0, populationx, k2, donor, _params);
                    ablasf.raddrv(n, -1.0, populationx, k3, donor, _params);
                    ablasf.rmulv(n, differentialweight, donor, _params);
                    ablasf.rcopyrv(n, xbest, hqrnd.hqrndintegerbase(rs, _params)%m, donorbase, _params);
                    processed = true;
                }
                if( strategytype==stcurrenttobest1 )
                {
                    
                    //
                    // DE/current-to-best/1
                    //
                    ablasf.rsetv(n, 0.0, donor, _params);
                    ablasf.raddrv(n, differentialweight, populationx, k0, donor, _params);
                    ablasf.raddrv(n, -differentialweight, populationx, k1, donor, _params);
                    ablasf.raddrv(n, differentialweight2, xbest, hqrnd.hqrndintegerbase(rs, _params)%m, donor, _params);
                    ablasf.raddrv(n, -differentialweight2, populationx, i, donor, _params);
                    ablasf.rcopyrv(n, populationx, i, donorbase, _params);
                    processed = true;
                }
                if( strategytype==stcurrenttoordbest1 )
                {
                    
                    //
                    // DE/current-to-ord_best/1
                    //
                    if( m!=1 )
                    {
                        alglib.ap.assert(false, "GDEMO: integrity check 091405 failed");
                    }
                    ablasf.rsetv(n, 0.0, donor, _params);
                    if( (double)(populationfitness[k0,0])<(double)(populationfitness[k1,0]) )
                    {
                        ablasf.raddrv(n, differentialweight, populationx, k0, donor, _params);
                        ablasf.raddrv(n, -differentialweight, populationx, k1, donor, _params);
                    }
                    else
                    {
                        ablasf.raddrv(n, differentialweight, populationx, k1, donor, _params);
                        ablasf.raddrv(n, -differentialweight, populationx, k0, donor, _params);
                    }
                    ablasf.raddrv(n, differentialweight2, xbest, hqrnd.hqrndintegerbase(rs, _params)%m, donor, _params);
                    ablasf.raddrv(n, -differentialweight2, populationx, i, donor, _params);
                    ablasf.rcopyrv(n, populationx, i, donorbase, _params);
                    processed = true;
                }
                alglib.ap.assert(processed, "GDEMO: integrity check 7131 failed");
                ablasf.raddv(n, 1.0, donorbase, donor, _params);
                for(j=0; j<=n-1; j++)
                {
                    donor[j] = Math.Max(donor[j], bndlimit*donorbase[j]+(1-bndlimit)*finitebndl[j]);
                    donor[j] = Math.Min(donor[j], bndlimit*donorbase[j]+(1-bndlimit)*finitebndu[j]);
                }
                
                //
                // Perform crossover with the target, apply box constraints to the donor in the process
                //
                r = hqrnd.hqrndintegerbase(rs, _params)%n;
                ablasf.rcopyrr(n, populationx, i, trialx, i, _params);
                for(j=0; j<=n-1; j++)
                {
                    if( hqrnd.hqrndintegerbase(rs, _params)*invmax<=crossoverprob || j==r )
                    {
                        trialx[i,j] = donor[j];
                    }
                }
            }
        }


        /*************************************************************************
        This is an internal function that generates candidates given DE params
        using SIMD kernels

          -- ALGLIB --
             Copyright 07.12.2023 by Bochkanov Sergey
        *************************************************************************/
        private static bool gdemogencandkernel(double[,] deparams,
            double[,] populationx,
            double[,] populationfitness,
            int n,
            int m,
            int popsize,
            double[,] xbest,
            double[] finitebndl,
            double[] finitebndu,
            double bndsmooth,
            int seedval,
            double[,] trialx,
            alglib.xparams _params)
        {
            bool result = new bool();

            result = false;
            return result;
        }


        /*************************************************************************
        Promote candidates

          -- ALGLIB --
             Copyright 07.12.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void updatepopulation(gdemostate state,
            gdemopopulation children,
            alglib.xparams _params)
        {
            int n = 0;
            int m = 0;
            int cntnlc = 0;
            int i = 0;
            double avgcr = 0;
            double sumf = 0;
            double sumf2 = 0;
            double df = 0;
            double sumdf = 0;
            int avgcnt = 0;

            n = state.n;
            m = state.m;
            cntnlc = state.cntnlc;
            
            //
            // Perform competition.
            //
            // NOTE: it is important to compare fitness as follows: "if CandFitness<=PopFitness",
            //       using <= instead of <, because it promotes explorational behavior in areas
            //       with vanishing gradient.
            //
            alglib.ap.assert((double)(state.nsample)==(double)(1), "GDEMO: integrity check 2649 failed");
            alglib.ap.assert(m==1, "GDEMO: integrity check 2650 failed");
            alglib.ap.assert(state.popsize==children.cnt, "GDEMO: integrity check 9300 failed");
            avgcr = 0.0;
            sumf = 0.0;
            sumf2 = 0.0;
            sumdf = 0.0;
            avgcnt = 0;
            for(i=0; i<=state.popsize-1; i++)
            {
                if( (double)(children.fitness[i,0])<=(double)(state.population.fitness[i,0]) )
                {
                    df = state.population.fitness[i,0]-children.fitness[i,0];
                    
                    //
                    // The candidate wins! Copy the candidate data
                    //
                    ablasf.rcopyrr(n, children.x, i, state.population.x, i, _params);
                    ablasf.rcopyrr(m+cntnlc, children.rawreplies, i, state.population.rawreplies, i, _params);
                    ablasf.rcopyrr(m, children.fitness, i, state.population.fitness, i, _params);
                    
                    //
                    // Update average params
                    //
                    alglib.ap.assert(paramscnt==4, "GDEMO: integrity check 207213 failed");
                    if( df>0 )
                    {
                        avgcr = avgcr+df*children.deparams[i,1];
                        sumf = sumf+df*children.deparams[i,2];
                        sumf2 = sumf2+df*math.sqr(children.deparams[i,2]);
                        sumdf = sumdf+df;
                        avgcnt = avgcnt+1;
                    }
                }
            }
            if( avgcnt>0 )
            {
                state.mucr = (1-mulearningrate)*state.mucr+mulearningrate*(avgcr/sumdf);
                state.muf = (1-mulearningrate)*state.muf+mulearningrate*(sumf2/sumdf/(sumf/sumdf));
            }
        }


    }
