        public const double secanttoblurratio = 1.0;
        public const double defaultpenalty = 100;
        public const double sqjmomentum = 0.05;


        public static void ssgdinitbuf(double[] bndl,
            double[] bndu,
            double[] s,
            double[] x0,
            int n,
            double[,] a,
            double[] al,
            double[] au,
            int cntlc,
            double[] nl,
            double[] nu,
            int cntnlc,
            double rad0,
            double rad1,
            int outerits,
            double rate0,
            double rate1,
            double momentum,
            int maxits,
            double rho,
            ssgdstate state,
            alglib.xparams _params)
        {
            int i = 0;

            
            //
            // Integrity checks
            //
            alglib.ap.assert(math.isfinite(rate0), "SSGD: Rate0 is not a finite number");
            alglib.ap.assert(math.isfinite(rate1), "SSGD: Rate1 is not a finite number");
            alglib.ap.assert(math.isfinite(momentum), "SSGD: Momentum is not a finite number");
            alglib.ap.assert(math.isfinite(rad0), "SSGD: Rad0 is not a finite number");
            alglib.ap.assert(math.isfinite(rad1), "SSGD: Rad1 is not a finite number");
            alglib.ap.assert(math.isfinite(rho), "SSGD: Rho is not a finite number");
            alglib.ap.assert((double)(rate0)>(double)(0), "SSGD: Rate0<=0");
            alglib.ap.assert((double)(rate1)>(double)(0), "SSGD: Rate1<=0");
            alglib.ap.assert((double)(momentum)>=(double)(0), "SSGD: Momentum<0");
            alglib.ap.assert((double)(momentum)<(double)(1), "SSGD: Momentum>=1");
            alglib.ap.assert((double)(rad0)>(double)(0), "SSGD: Rad0<=0");
            alglib.ap.assert((double)(rad1)>(double)(0), "SSGD: Rad1<=0");
            alglib.ap.assert((double)(rate0)>=(double)(rate1), "SSGD: Rate0<Rate1");
            alglib.ap.assert((double)(rad0)>=(double)(rad1), "SSGD: Rad0<Rad1");
            alglib.ap.assert(maxits>0, "SSGD: MaxIts<=0");
            alglib.ap.assert(outerits>0, "SSGD: OuterIts<=0");
            alglib.ap.assert((double)(rho)>=(double)(0), "SSGD: Rho<0");
            
            //
            // Initialization
            //
            state.n = n;
            state.cntlc = cntlc;
            state.cntnlc = cntnlc;
            state.rate0 = rate0;
            state.rate1 = rate1;
            state.blur0 = rad0;
            state.blur1 = rad1;
            state.outerits = outerits;
            state.maxits = maxits;
            state.rho = apserv.coalesce(rho, defaultpenalty, _params);
            
            //
            // Prepare RCOMM state
            //
            state.rstate.ia = new int[6+1];
            state.rstate.ba = new bool[1+1];
            state.rstate.ra = new double[7+1];
            state.rstate.stage = -1;
            state.rstate.clear_handler();
            state.needfi = false;
            state.xupdated = false;
            state.x = new double[n];
            state.fi = new double[1+cntnlc];
            
            //
            // Allocate memory.
            //
            ablasf.rallocv(n, ref state.x0, _params);
            ablasf.rallocv(n, ref state.s, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndl, n, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndu, n, _params);
            ablasf.rsetallocv(n, -math.maxrealnumber, ref state.finitebndl, _params);
            ablasf.rsetallocv(n, math.maxrealnumber, ref state.finitebndu, _params);
            
            //
            // Prepare scaled problem
            //
            for(i=0; i<=n-1; i++)
            {
                state.hasbndl[i] = math.isfinite(bndl[i]);
                state.hasbndu[i] = math.isfinite(bndu[i]);
                if( state.hasbndl[i] )
                {
                    state.finitebndl[i] = bndl[i]/s[i];
                }
                if( state.hasbndu[i] )
                {
                    state.finitebndu[i] = bndu[i]/s[i];
                }
                if( state.hasbndl[i] && state.hasbndu[i] )
                {
                    alglib.ap.assert((double)(bndl[i])<=(double)(bndu[i]), "SSGD: integrity check failed, box constraints are inconsistent");
                }
                state.x0[i] = x0[i]/s[i];
                state.s[i] = s[i];
            }
            if( cntlc>0 )
            {
                ablasf.rsetallocv(n, 0.0, ref state.tmpzero, _params);
                ablasf.rcopyallocm(cntlc, n, a, ref state.densea, _params);
                ablasf.rcopyallocv(cntlc, al, ref state.al, _params);
                ablasf.rcopyallocv(cntlc, au, ref state.au, _params);
                lpqpserv.scaleshiftmixedlcinplace(s, state.tmpzero, n, state.dummysparsea, 0, state.densea, cntlc, state.al, state.au, _params);
                lpqpserv.normalizedenselcinplace(state.densea, cntlc, state.al, state.au, n, true, ref state.ascales, true, _params);
                ablasf.ballocv(cntlc, ref state.hasal, _params);
                ablasf.ballocv(cntlc, ref state.hasau, _params);
                for(i=0; i<=cntlc-1; i++)
                {
                    state.hasal[i] = math.isfinite(state.al[i]);
                    state.hasau[i] = math.isfinite(state.au[i]);
                }
            }
            if( cntnlc>0 )
            {
                ablasf.rcopyallocv(cntnlc, nl, ref state.rawnl, _params);
                ablasf.rcopyallocv(cntnlc, nu, ref state.rawnu, _params);
                ablasf.ballocv(cntnlc, ref state.hasnl, _params);
                ablasf.ballocv(cntnlc, ref state.hasnu, _params);
                for(i=0; i<=cntnlc-1; i++)
                {
                    state.hasnl[i] = math.isfinite(state.rawnl[i]);
                    state.hasnu[i] = math.isfinite(state.rawnu[i]);
                }
            }
        }


        /*************************************************************************
        This function performs actual processing for SSGD  algorithm.  It  expects
        that the caller redirects its reverse communication  requests  NeedFiJ  or
        XUpdated to the external user,  possibly  wrapping  them  in  a  numerical
        differentiation code.

          -- ALGLIB --
             Copyright 26.07.2023 by Bochkanov Sergey
        *************************************************************************/
        public static bool ssgditeration(ssgdstate state,
            bool userterminationneeded,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int cntlc = 0;
            int cntnlc = 0;
            bool dotrace = new bool();
            bool dodetailedtrace = new bool();
            int outeridx = 0;
            int iteridx = 0;
            int i = 0;
            int j = 0;
            double f0 = 0;
            double fbest = 0;
            double fleft = 0;
            double fright = 0;
            double avgsqg = 0;
            double finalscale = 0;
            double t = 0;
            double v = 0;

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rstate.stage>=0 )
            {
                n = state.rstate.ia[0];
                cntlc = state.rstate.ia[1];
                cntnlc = state.rstate.ia[2];
                outeridx = state.rstate.ia[3];
                iteridx = state.rstate.ia[4];
                i = state.rstate.ia[5];
                j = state.rstate.ia[6];
                dotrace = state.rstate.ba[0];
                dodetailedtrace = state.rstate.ba[1];
                f0 = state.rstate.ra[0];
                fbest = state.rstate.ra[1];
                fleft = state.rstate.ra[2];
                fright = state.rstate.ra[3];
                avgsqg = state.rstate.ra[4];
                finalscale = state.rstate.ra[5];
                t = state.rstate.ra[6];
                v = state.rstate.ra[7];
            }
            else
            {
                n = 359;
                cntlc = -58;
                cntnlc = -919;
                outeridx = -909;
                iteridx = 81;
                i = 255;
                j = 74;
                dotrace = false;
                dodetailedtrace = true;
                f0 = 205.0;
                fbest = -838.0;
                fleft = 939.0;
                fright = -526.0;
                avgsqg = 763.0;
                finalscale = -541.0;
                t = -698.0;
                v = -900.0;
            }
            if( state.rstate.stage==0 )
            {
                goto lbl_0;
            }
            if( state.rstate.stage==1 )
            {
                goto lbl_1;
            }
            if( state.rstate.stage==2 )
            {
                goto lbl_2;
            }
            if( state.rstate.stage==3 )
            {
                goto lbl_3;
            }
            
            //
            // Routine body
            //
            n = state.n;
            cntlc = state.cntlc;
            cntnlc = state.cntnlc;
            dotrace = ap.istraceenabled("SSGD", _params);
            dodetailedtrace = dotrace && ap.istraceenabled("SSGD.DETAILED", _params);
            
            //
            // Prepare rcomm interface
            //
            clearrequestfields(state, _params);
            
            //
            // Initialize algorithm state.
            //
            hqrnd.hqrndseed(3366544, 86335763, state.rs, _params);
            ablasf.rallocv(n, ref state.xoffs0, _params);
            ablasf.rallocv(n, ref state.xoffs1, _params);
            ablasf.rallocv(n, ref state.gcur, _params);
            ablasf.rcopyallocv(n, state.x0, ref state.xcur, _params);
            ablasf.rmergemaxv(n, state.finitebndl, state.xcur, _params);
            ablasf.rmergeminv(n, state.finitebndu, state.xcur, _params);
            ablasf.rsetallocv(n, 0.0, ref state.dcur, _params);
            state.repiterationscount = 0;
            state.repnfev = 0;
            avgsqg = math.machineepsilon;
            ablasf.rsetallocv(1+cntnlc, math.machineepsilon, ref state.avgsqj, _params);
            ablasf.rsetallocv(1+cntnlc, 1.0, ref state.fscales, _params);
            finalscale = 1.0;
            ablasf.rcopyallocv(n, state.xcur, ref state.xbest, _params);
            ablasf.rcopyv(n, state.xbest, state.x, _params);
            state.needfi = true;
            state.rstate.stage = 0;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
            state.needfi = false;
            ablasf.rcopyallocv(1+cntnlc, state.fi, ref state.fibest, _params);
            ablasf.rallocv(n, ref state.xleft, _params);
            ablasf.rallocv(n, ref state.xright, _params);
            ablasf.rallocv(1+cntnlc, ref state.fileft, _params);
            ablasf.rallocv(1+cntnlc, ref state.firight, _params);
            
            //
            // Trace output (if needed)
            //
            if( dotrace )
            {
                alglib.ap.trace("\n\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace("//  Smoothed SGD SOLVER STARTED                                                                   //\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace(System.String.Format("N             = {0,6:d}\n", n));
                alglib.ap.trace(System.String.Format("cntLC         = {0,6:d}\n", cntlc));
                alglib.ap.trace(System.String.Format("cntNLC        = {0,6:d}\n", cntnlc));
            }
            
            //
            // Perform SGD iterations
            //
            outeridx = 0;
        lbl_4:
            if( outeridx>state.outerits-1 )
            {
                goto lbl_6;
            }
            
            //
            // Choose initial point for an outer iteration as the best point found so far
            //
            ablasf.rcopyv(n, state.xbest, state.xcur, _params);
            
            //
            // Inner iteration: perform MaxIts SGD steps
            //
            iteridx = 0;
        lbl_7:
            if( iteridx>state.maxits-1 )
            {
                goto lbl_9;
            }
            
            //
            // Determine iteration parameters
            //
            t = (double)iteridx/(double)Math.Max(state.maxits-1, 1);
            state.currate = state.rate0*Math.Exp(Math.Log(state.rate1/state.rate0)*Math.Max(2*t-1, 0));
            state.curblur = state.blur0*Math.Exp(Math.Log(state.blur1/state.blur0)*outeridx/Math.Max(state.outerits-1, 1));
            state.zcursecantstep = secanttoblurratio*state.curblur;
            if( dotrace )
            {
                alglib.ap.trace(System.String.Format("\n=== INNER ITERATION {0,5:d}, OUTER ITERATION {1,5:d} ===================================================\n", iteridx, outeridx));
                alglib.ap.trace(System.String.Format("learn.Rate    = {0,0:E3}\n", state.currate));
                alglib.ap.trace(System.String.Format("smooth.Rad    = {0,0:E3}\n", state.curblur));
                alglib.ap.trace(System.String.Format("secantStep    = {0,0:E3}\n", state.zcursecantstep));
            }
            
            //
            // Compute target value at the current point, update best value so far
            //
            ablasf.rcopyv(n, state.xcur, state.x, _params);
            state.needfi = true;
            state.rstate.stage = 1;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            state.needfi = false;
            f0 = penalizedtarget(state, state.x, state.fi, _params);
            fbest = penalizedtarget(state, state.xbest, state.fibest, _params);
            if( dodetailedtrace )
            {
                alglib.ap.trace("> printing current location and status:\n");
                alglib.ap.trace("X (raw)       = ");
                apserv.tracevectorunscaledunshiftedautoprec(state.xcur, n, state.s, true, state.s, false, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace("X (scaled)    = ");
                apserv.tracevectorautoprec(state.xcur, 0, n, _params);
                alglib.ap.trace("\n");
            }
            if( (double)(f0)<(double)(fbest) )
            {
                ablasf.rcopyv(n, state.xcur, state.xbest, _params);
                ablasf.rcopyallocv(1+cntnlc, state.fi, ref state.fibest, _params);
            }
            if( dotrace )
            {
                alglib.ap.trace("\n--- current target ---------------------------------------------------------------------------------\n");
                alglib.ap.trace(System.String.Format("F             = {0,0:E12}\n", state.fi[0]));
                alglib.ap.trace(System.String.Format("F-penalized   = {0,0:E12}\n", f0));
                alglib.ap.trace(System.String.Format("lin.violation = {0,0:E3}\n", lcviolation(state, state.xcur, _params)));
                alglib.ap.trace("\n--- best point so far ------------------------------------------------------------------------------\n");
                alglib.ap.trace(System.String.Format("F             = {0,0:E12}\n", state.fibest[0]));
                alglib.ap.trace(System.String.Format("F-penalized   = {0,0:E12}\n", fbest));
                alglib.ap.trace(System.String.Format("lin.violation = {0,0:E3}\n", lcviolation(state, state.xbest, _params)));
            }
            
            //
            // Compute gradients (target, linear penalties, nonlinear penalties) using secant update
            //
            for(i=0; i<=n-1; i++)
            {
                state.xoffs0[i] = hqrnd.hqrnduniformr(state.rs, _params)-0.5;
                state.xoffs1[i] = state.xoffs0[i];
            }
            ablasf.rsetallocv(1+cntnlc, 0.0, ref state.sqj, _params);
            i = 0;
        lbl_10:
            if( i>n-1 )
            {
                goto lbl_12;
            }
            
            //
            // Compute f(x-SecantStep) and f(x+SecantStep)
            //
            ablasf.rcopyv(n, state.xcur, state.x, _params);
            ablasf.raddv(n, state.curblur, state.xoffs0, state.x, _params);
            state.x[i] = state.x[i]-state.zcursecantstep;
            ablasf.rmergemaxv(n, state.finitebndl, state.x, _params);
            ablasf.rmergeminv(n, state.finitebndu, state.x, _params);
            state.needfi = true;
            state.rstate.stage = 2;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_2:
            state.needfi = false;
            ablasf.rcopyv(n, state.x, state.xleft, _params);
            ablasf.rcopyv(1+cntnlc, state.fi, state.fileft, _params);
            ablasf.rcopyv(n, state.xcur, state.x, _params);
            ablasf.raddv(n, state.curblur, state.xoffs1, state.x, _params);
            state.x[i] = state.x[i]+state.zcursecantstep;
            ablasf.rmergemaxv(n, state.finitebndl, state.x, _params);
            ablasf.rmergeminv(n, state.finitebndu, state.x, _params);
            state.needfi = true;
            state.rstate.stage = 3;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_3:
            state.needfi = false;
            ablasf.rcopyv(n, state.x, state.xright, _params);
            ablasf.rcopyv(1+cntnlc, state.fi, state.firight, _params);
            
            //
            // Compute squared norms of target/constraint gradients
            //
            for(j=0; j<=cntnlc; j++)
            {
                v = (state.firight[j]-state.fileft[j])/(2*state.zcursecantstep);
                state.sqj[j] = state.sqj[j]+v*v;
            }
            
            //
            // Compute gradient using current target/constraint scales
            //
            state.gcur[i] = (state.firight[0]-state.fileft[0])/(2*state.fscales[0]*state.zcursecantstep);
            for(j=0; j<=cntnlc-1; j++)
            {
                state.gcur[i] = state.gcur[i]+(scalednlcpenalty(state, state.firight, j, state.fscales[1+j], _params)-scalednlcpenalty(state, state.fileft, j, state.fscales[1+j], _params))/(2*state.zcursecantstep);
            }
            state.gcur[i] = state.gcur[i]+(lcpenalty(state, state.xright, _params)-lcpenalty(state, state.xleft, _params))/(2*state.zcursecantstep);
            i = i+1;
            goto lbl_10;
        lbl_12:
            
            //
            // Recompute scales using data collected during gradient calculation
            //
            for(i=0; i<=cntnlc; i++)
            {
                state.avgsqj[i] = state.avgsqj[i]*(1-sqjmomentum)+sqjmomentum*Math.Sqrt(state.sqj[j]);
                state.fscales[i] = Math.Max(state.avgsqj[i], 1.0);
            }
            if( dotrace )
            {
                alglib.ap.trace(System.String.Format("scale(F)      = {0,0:E3}\n", state.fscales[0]));
            }
            v = Math.Sqrt(ablasf.rdotv2(n, state.gcur, _params));
            avgsqg = avgsqg*(1-sqjmomentum)+sqjmomentum*v;
            finalscale = apserv.rmax3(avgsqg, v, 1.0, _params);
            ablasf.rmulv(n, 1/finalscale, state.gcur, _params);
            
            //
            // Perform step
            //
            ablasf.rmulv(n, state.momentum, state.dcur, _params);
            ablasf.raddv(n, 1-state.momentum, state.gcur, state.dcur, _params);
            ablasf.raddv(n, -state.currate, state.dcur, state.xcur, _params);
            ablasf.rmergemaxv(n, state.finitebndl, state.xcur, _params);
            ablasf.rmergeminv(n, state.finitebndu, state.xcur, _params);
            state.repiterationscount = state.repiterationscount+1;
            iteridx = iteridx+1;
            goto lbl_7;
        lbl_9:
            outeridx = outeridx+1;
            goto lbl_4;
        lbl_6:
            if( dotrace )
            {
                alglib.ap.trace("> reached iterations limit, stopping\n");
            }
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rstate.ia[0] = n;
            state.rstate.ia[1] = cntlc;
            state.rstate.ia[2] = cntnlc;
            state.rstate.ia[3] = outeridx;
            state.rstate.ia[4] = iteridx;
            state.rstate.ia[5] = i;
            state.rstate.ia[6] = j;
            state.rstate.ba[0] = dotrace;
            state.rstate.ba[1] = dodetailedtrace;
            state.rstate.ra[0] = f0;
            state.rstate.ra[1] = fbest;
            state.rstate.ra[2] = fleft;
            state.rstate.ra[3] = fright;
            state.rstate.ra[4] = avgsqg;
            state.rstate.ra[5] = finalscale;
            state.rstate.ra[6] = t;
            state.rstate.ra[7] = v;
            return result;
        }


        /*************************************************************************
        Clears request fileds (to be sure that we didn't forget to clear something)
        *************************************************************************/
        private static void clearrequestfields(ssgdstate state,
            alglib.xparams _params)
        {
            state.needfi = false;
            state.xupdated = false;
        }


        /*************************************************************************
        Compute penalized target
        *************************************************************************/
        private static double penalizedtarget(ssgdstate state,
            double[] x,
            double[] fi,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;

            result = fi[0]/state.fscales[0];
            for(i=0; i<=state.cntnlc-1; i++)
            {
                result = result+scalednlcpenalty(state, fi, i, state.fscales[1+i], _params);
            }
            result = result+lcpenalty(state, x, _params);
            return result;
        }


        /*************************************************************************
        Compute penalty for linear constraints
        *************************************************************************/
        private static double lcpenalty(ssgdstate state,
            double[] x,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double v = 0;

            result = 0.0;
            for(i=0; i<=state.cntlc-1; i++)
            {
                v = ablasf.rdotvr(state.n, x, state.densea, i, _params);
                if( state.hasal[i] && v<state.al[i] )
                {
                    result = result+0*(state.al[i]-v)+state.rho*(state.al[i]-v)*(state.al[i]-v);
                }
                if( state.hasau[i] && v>state.au[i] )
                {
                    result = result+0*(v-state.au[i])+state.rho*(v-state.au[i])*(v-state.au[i]);
                }
            }
            return result;
        }


        /*************************************************************************
        Compute penalty for a single nonlinear constraint
        *************************************************************************/
        private static double scalednlcpenalty(ssgdstate state,
            double[] fi,
            int idx,
            double fscale,
            alglib.xparams _params)
        {
            double result = 0;
            double v = 0;

            fi = (double[])fi.Clone();

            result = 0.0;
            if( state.hasnl[idx] && fi[1+idx]<state.rawnl[idx] )
            {
                v = (state.rawnl[idx]-fi[1+idx])/fscale;
                result = result+0*v+state.rho*v*v;
            }
            if( state.hasnu[idx] && fi[1+idx]>state.rawnu[idx] )
            {
                v = (fi[1+idx]-state.rawnu[idx])/fscale;
                result = result+0*v+state.rho*v*v;
            }
            return result;
        }


        /*************************************************************************
        Compute violation of linear constraints
        *************************************************************************/
        private static double lcviolation(ssgdstate state,
            double[] x,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double v = 0;

            result = 0.0;
            for(i=0; i<=state.cntlc-1; i++)
            {
                v = ablasf.rdotvr(state.n, x, state.densea, i, _params);
                if( state.hasal[i] )
                {
                    result = Math.Max(result, state.al[i]-v);
                }
                if( state.hasau[i] )
                {
                    result = Math.Max(result, v-state.au[i]);
                }
            }
            return result;
        }


    }
    public partial class ecqpsolver
    {
        /*************************************************************************
        VIPM state
        *************************************************************************/
        public class ecqpstate : apobject
        {
            public sparse.sparsematrix haug;
            public int[] priorities;
            public spchol.spcholanalysis analysis;
            public double[] effdiagonal;
            public double[] dampdiagonal;
            public double[] dx;
            public double[] bx;
            public double[] dh;
            public fbls.fblsgmresstate gmressolver;
            public int repiterationscount;
            public int repncholesky;
            public bool dotrace;
            public bool dotimers;
            public apserv.stimer timertotal;
            public apserv.stimer timeranalyze;
            public apserv.stimer timerfactorize;
            public apserv.stimer timerspsymmsolve;
            public apserv.stimer timerothersolve;
            public ecqpstate()
            {
                init();
            }
            public override void init()
            {
                haug = new sparse.sparsematrix();
                priorities = new int[0];
                analysis = new spchol.spcholanalysis();
                effdiagonal = new double[0];
                dampdiagonal = new double[0];
                dx = new double[0];
                bx = new double[0];
                dh = new double[0];
                gmressolver = new fbls.fblsgmresstate();
                timertotal = new apserv.stimer();
                timeranalyze = new apserv.stimer();
                timerfactorize = new apserv.stimer();
                timerspsymmsolve = new apserv.stimer();
                timerothersolve = new apserv.stimer();
            }
            public override alglib.apobject make_copy()
            {
                ecqpstate _result = new ecqpstate();
                _result.haug = haug!=null ? (sparse.sparsematrix)haug.make_copy() : null;
                _result.priorities = (int[])priorities.Clone();
                _result.analysis = analysis!=null ? (spchol.spcholanalysis)analysis.make_copy() : null;
                _result.effdiagonal = (double[])effdiagonal.Clone();
                _result.dampdiagonal = (double[])dampdiagonal.Clone();
                _result.dx = (double[])dx.Clone();
                _result.bx = (double[])bx.Clone();
                _result.dh = (double[])dh.Clone();
                _result.gmressolver = gmressolver!=null ? (fbls.fblsgmresstate)gmressolver.make_copy() : null;
                _result.repiterationscount = repiterationscount;
                _result.repncholesky = repncholesky;
                _result.dotrace = dotrace;
                _result.dotimers = dotimers;
                _result.timertotal = timertotal!=null ? (apserv.stimer)timertotal.make_copy() : null;
                _result.timeranalyze = timeranalyze!=null ? (apserv.stimer)timeranalyze.make_copy() : null;
                _result.timerfactorize = timerfactorize!=null ? (apserv.stimer)timerfactorize.make_copy() : null;
                _result.timerspsymmsolve = timerspsymmsolve!=null ? (apserv.stimer)timerspsymmsolve.make_copy() : null;
                _result.timerothersolve = timerothersolve!=null ? (apserv.stimer)timerothersolve.make_copy() : null;
                return _result;
            }
        };




        public const double mupromote = 10.0;


        /*************************************************************************
        Initializes QP-IPM state and prepares it to receive quadratic/linear terms
        and constraints.

        INPUT PARAMETERS:
            State       -   solver  state  to  be configured; previously allocated
                            memory is reused as much as possible
            S           -   scale vector, array[N]:
                            * I-th element contains scale of I-th variable,
                            * S[I]>0
            XOrigin     -   origin term, array[N]. Can be zero. The solver solves
                            problem of the form
                            >
                            > min(0.5*(x-x_origin)'*A*(x-x_origin)+b'*(x-x_origin))
                            >
                            The terms A and b (as well as constraints) will be
                            specified later with separate calls.
            N           -   total number of variables, N>=1
            TargetScale -   target scale:
                            * >=0
                            * recommended to be max(nrm2(C),nrm2(H+corr))
                            * if zero, autodetected by performing several iterations
                              of a subspace eigensolver

          -- ALGLIB --
             Copyright 21.12.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void ecqpsolve(ecqpstate state,
            int nuser,
            sparse.sparsematrix lowerh,
            double[] c,
            sparse.sparsematrix sparsea,
            double[] ae,
            int m,
            ref double[] xs,
            ref double[] laglc,
            ref int terminationtype,
            alglib.xparams _params)
        {
            int nnza = 0;
            int ntotal = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            int j0 = 0;
            int j1 = 0;
            double v = 0;
            double vv = 0;
            int offs = 0;
            double damp = 0;
            double reg = 0;
            double badchol = 0;
            double sumsq = 0;
            double errsq = 0;
            int rfsidx = 0;
            int facttype = 0;

            terminationtype = 0;

            alglib.ap.assert(nuser>=1, "ECQPInit: N<1");
            alglib.ap.assert(apserv.isfinitevector(c, nuser, _params), "ECQPInit: C contains infinite or NaN elements");
            alglib.ap.assert(m>=0, "ECQPInit: M<0");
            alglib.ap.assert(m==0 || sparsea.matrixtype==1, "ECQPInit: non-CRS constraint matrix!");
            alglib.ap.assert(m==0 || (sparsea.m==m && sparsea.n==nuser), "ECQPInit: constraint matrix has incorrect size");
            alglib.ap.assert(alglib.ap.len(ae)>=m, "ECQPInit: AE is too short!");
            
            //
            // Problem metrics, settings and type
            //
            nnza = 0;
            if( m>0 )
            {
                nnza = sparsea.ridx[m];
            }
            ntotal = nuser+m;
            
            //
            // Reports
            //
            state.repiterationscount = 0;
            state.repncholesky = 0;
            
            //
            // Trace
            //
            state.dotrace = ap.istraceenabled("ECQP", _params);
            state.dotimers = state.dotrace || ap.istraceenabled("TIMERS.ECQP", _params);
            if( state.dotimers )
            {
                apserv.stimerinit(state.timertotal, _params);
                apserv.stimerinit(state.timeranalyze, _params);
                apserv.stimerinit(state.timerfactorize, _params);
                apserv.stimerinit(state.timerspsymmsolve, _params);
                apserv.stimerinit(state.timerothersolve, _params);
                apserv.stimerstart(state.timertotal, _params);
            }
            if( state.dotrace || state.dotimers )
            {
                alglib.ap.trace("\n\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace("// SPARSE ECQP SOLVER STARTED                                                                     //\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
            }
            
            //
            // Generate extended (N+M)x(N+M) matrix
            //
            ablasf.rallocv(ntotal, ref state.effdiagonal, _params);
            state.haug.matrixtype = 1;
            state.haug.m = ntotal;
            state.haug.n = ntotal;
            ablasf.iallocv(ntotal+1, ref state.haug.ridx, _params);
            alglib.ap.assert(lowerh.matrixtype==1, "ECQP: unexpected sparse matrix format");
            alglib.ap.assert(lowerh.m==nuser, "ECQP: unexpected sparse matrix size");
            alglib.ap.assert(lowerh.n==nuser, "ECQP: unexpected sparse matrix size");
            ablasf.iallocv(lowerh.ridx[nuser]+nuser+nnza+nuser, ref state.haug.idx, _params);
            ablasf.rallocv(lowerh.ridx[nuser]+nuser+nnza+nuser, ref state.haug.vals, _params);
            state.haug.ridx[0] = 0;
            offs = 0;
            vv = 0;
            for(i=0; i<=nuser-1; i++)
            {
                
                //
                // Copy subdiagonal elements (if needed)
                //
                j0 = lowerh.ridx[i];
                j1 = lowerh.didx[i]-1;
                for(k=j0; k<=j1; k++)
                {
                    v = lowerh.vals[k];
                    state.haug.idx[offs] = lowerh.idx[k];
                    state.haug.vals[offs] = v;
                    vv = vv+v;
                    offs = offs+1;
                }
                
                //
                // Diagonal element is always copied
                //
                v = 0;
                if( lowerh.uidx[i]!=lowerh.didx[i] )
                {
                    v = lowerh.vals[lowerh.didx[i]];
                }
                state.haug.idx[offs] = i;
                state.haug.vals[offs] = v;
                state.effdiagonal[i] = v;
                vv = vv+v;
                offs = offs+1;
                
                //
                // Finalize row
                //
                state.haug.ridx[i+1] = offs;
            }
            for(i=0; i<=m-1; i++)
            {
                offs = state.haug.ridx[nuser+i];
                j0 = sparsea.ridx[i];
                j1 = sparsea.ridx[i+1]-1;
                for(j=j0; j<=j1; j++)
                {
                    state.haug.idx[offs] = sparsea.idx[j];
                    state.haug.vals[offs] = sparsea.vals[j];
                    offs = offs+1;
                }
                state.haug.idx[offs] = nuser+i;
                state.haug.vals[offs] = 0.0;
                state.effdiagonal[nuser+i] = 0.0;
                offs = offs+1;
                state.haug.ridx[nuser+i+1] = offs;
            }
            alglib.ap.assert(math.isfinite(vv), "ECQPInit: LowerH contains infinite or NaN values!");
            alglib.ap.assert(offs<=alglib.ap.len(state.haug.vals) && offs<=alglib.ap.len(state.haug.idx), "ECQPInit: integrity check failed");
            sparse.sparsecreatecrsinplace(state.haug, _params);
            
            //
            // Prepare sparse Cholesky
            //
            facttype = 21;
            ablasf.isetallocv(state.haug.n, 0, ref state.priorities, _params);
            ablasf.isetv(nuser, 1, state.priorities, _params);
            apserv.stimerstartcond(state.timeranalyze, state.dotimers, _params);
            if( !spchol.spsymmanalyze(state.haug, state.priorities, mupromote, 0, facttype, 3, 1, state.analysis, _params) )
            {
                alglib.ap.assert(false, "ReducedSystemPowerUp: critical integrity check failed, symbolically degenerate KKT system encountered");
            }
            apserv.stimerstopcond(state.timeranalyze, state.dotimers, _params);
            
            //
            // Regularize until factorization succeeds
            //
            ablasf.rallocv(ntotal, ref state.dampdiagonal, _params);
            damp = Math.Sqrt(math.machineepsilon);
            badchol = 1.0E50;
            while( true )
            {
                for(i=0; i<=nuser-1; i++)
                {
                    state.dampdiagonal[i] = state.effdiagonal[i]+damp;
                }
                for(i=nuser; i<=ntotal-1; i++)
                {
                    state.dampdiagonal[i] = state.effdiagonal[i]-damp;
                }
                spchol.spsymmreloaddiagonal(state.analysis, state.dampdiagonal, _params);
                spchol.spsymmsetmodificationstrategy(state.analysis, 1, math.machineepsilon, badchol, 0.0, 0.0, _params);
                apserv.stimerstartcond(state.timerfactorize, state.dotimers, _params);
                if( !spchol.spsymmfactorize(state.analysis, _params) )
                {
                    apserv.stimerstopcond(state.timerfactorize, state.dotimers, _params);
                    damp = 10*damp;
                    if( state.dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> cholesky factorization failed, increasing damping to {0,0:E2}\n", damp));
                    }
                    continue;
                }
                apserv.stimerstopcond(state.timerfactorize, state.dotimers, _params);
                spchol.spsymmdiagerr(state.analysis, ref sumsq, ref errsq, _params);
                if( (double)(Math.Sqrt(errsq/(1+sumsq)))>(double)(100*Math.Sqrt(math.machineepsilon)) )
                {
                    damp = 10*damp;
                    if( state.dotrace )
                    {
                        alglib.ap.trace(System.String.Format("LDLT-diag-err= {0,0:E3} (diagonal reproduction error), increasing damping to {1,0:E2}\n", Math.Sqrt(errsq/(1+sumsq)), damp));
                    }
                    continue;
                }
                if( state.dotrace )
                {
                    alglib.ap.trace("> factorization accepted\n");
                }
                break;
            }
            
            //
            // Solve
            //
            apserv.stimerstartcond(state.timerothersolve, state.dotimers, _params);
            reg = 1000*math.machineepsilon;
            ablasf.rallocv(ntotal, ref state.bx, _params);
            ablasf.rcopymulv(nuser, -1.0, c, state.bx, _params);
            ablasf.rcopyvx(m, ae, 0, state.bx, nuser, _params);
            fbls.fblsgmrescreate(state.bx, ntotal, Math.Min(25, ntotal), state.gmressolver, _params);
            state.gmressolver.epsres = 100*math.machineepsilon;
            state.gmressolver.epsred = 0.999999;
            rfsidx = 0;
            while( fbls.fblsgmresiteration(state.gmressolver, _params) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format(">> GMRES iteration {0,2:d}: {1,0:E2} relative residual\n", rfsidx, state.gmressolver.reprelres));
                }
                for(i=0; i<=nuser-1; i++)
                {
                    state.gmressolver.ax[i] = reg*state.gmressolver.x[i];
                }
                for(i=nuser; i<=ntotal-1; i++)
                {
                    state.gmressolver.ax[i] = -(reg*state.gmressolver.x[i]);
                }
                ablasf.rcopyallocv(ntotal, state.gmressolver.x, ref state.dx, _params);
                apserv.stimerstartcond(state.timerspsymmsolve, state.dotimers, _params);
                spchol.spsymmsolve(state.analysis, state.dx, _params);
                apserv.stimerstopcond(state.timerspsymmsolve, state.dotimers, _params);
                sparse.sparsesmv(lowerh, false, state.dx, ref state.dh, _params);
                ablasf.raddvx(nuser, 1.0, state.dh, 0, state.gmressolver.ax, 0, _params);
                if( m>0 )
                {
                    sparse.sparsegemv(sparsea, 1.0, 1, state.dx, nuser, 1.0, state.gmressolver.ax, 0, _params);
                    sparse.sparsegemv(sparsea, 1.0, 0, state.dx, 0, 1.0, state.gmressolver.ax, nuser, _params);
                }
                rfsidx = rfsidx+1;
            }
            apserv.stimerstartcond(state.timerspsymmsolve, state.dotimers, _params);
            spchol.spsymmsolve(state.analysis, state.gmressolver.xs, _params);
            apserv.stimerstopcond(state.timerspsymmsolve, state.dotimers, _params);
            apserv.stimerstopcond(state.timerothersolve, state.dotimers, _params);
            ablasf.rallocv(nuser, ref xs, _params);
            ablasf.rallocv(m, ref laglc, _params);
            ablasf.rcopyvx(nuser, state.gmressolver.xs, 0, xs, 0, _params);
            ablasf.rcopyvx(m, state.gmressolver.xs, nuser, laglc, 0, _params);
            state.repiterationscount = 1;
            state.repncholesky = 1;
            terminationtype = 1;
            
            //
            // Timers and reports
            //
            if( state.dotimers )
            {
                apserv.stimerstop(state.timertotal, _params);
                alglib.ap.trace("\n> printing internal timers (can be zero when run in OS-agnostic mode)\n");
                alglib.ap.trace(System.String.Format("> total time:            {0,10:F1} ms\n", apserv.stimergetms(state.timertotal, _params)));
                alglib.ap.trace(System.String.Format("> * in analyze:          {0,10:F1} ms\n", apserv.stimergetms(state.timeranalyze, _params)));
                alglib.ap.trace(System.String.Format("> * in factorize:        {0,10:F1} ms\n", apserv.stimergetms(state.timerfactorize, _params)));
                alglib.ap.trace(System.String.Format("> * in spsymmsolve():    {0,10:F1} ms\n", apserv.stimergetms(state.timerspsymmsolve, _params)));
                alglib.ap.trace(System.String.Format("> * in other solve:      {0,10:F1} ms\n", apserv.stimergetms(state.timerothersolve, _params)-apserv.stimergetms(state.timerspsymmsolve, _params)));
            }
        }


    }
    public partial class gipm3
    {
        /*************************************************************************
        Primal and dual vars, objective and Jacobian
        *************************************************************************/
        public class gipm3vars : apobject
        {
            public int n;
            public int meq;
