            public double[] ze;
            public double[] zi;
            public double[] zh;
            public double[] zs;
            public bool hasfunctions;
            public double f;
            public double[] g;
            public double[] ce;
            public double[] ci;
            public double[] ch;
            public bool haslaggrad;
            public double[] laggrad;
            public double[] fi;
            public gipm3vars()
            {
                init();
            }
            public override void init()
            {
                x = new double[0];
                s = new double[0];
                ze = new double[0];
                zi = new double[0];
                zh = new double[0];
                zs = new double[0];
                g = new double[0];
                ce = new double[0];
                ci = new double[0];
                ch = new double[0];
                laggrad = new double[0];
                fi = new double[0];
            }
            public override alglib.apobject make_copy()
            {
                gipm3vars _result = new gipm3vars();
                _result.n = n;
                _result.meq = meq;
                _result.mi = mi;
                _result.mh = mh;
                _result.mxx = mxx;
                _result.x = (double[])x.Clone();
                _result.s = (double[])s.Clone();
                _result.ze = (double[])ze.Clone();
                _result.zi = (double[])zi.Clone();
                _result.zh = (double[])zh.Clone();
                _result.zs = (double[])zs.Clone();
                _result.hasfunctions = hasfunctions;
                _result.f = f;
                _result.g = (double[])g.Clone();
                _result.ce = (double[])ce.Clone();
                _result.ci = (double[])ci.Clone();
                _result.ch = (double[])ch.Clone();
                _result.haslaggrad = haslaggrad;
                _result.laggrad = (double[])laggrad.Clone();
                _result.fi = (double[])fi.Clone();
                return _result;
            }
        };


