        /*************************************************************************
        Get recommended initial value for mu.

          -- ALGLIB --
             Copyright 01.02.2025 by Bochkanov Sergey
        *************************************************************************/
        public static double gipm3getinitprimdual(alglib.xparams _params)
        {
            double result = 0;

            result = initmu;
            return result;
        }


        /*************************************************************************
        Initialize GIPM structure

            TraceLevel              trace level:
                                    * 0 for no trace
                                    * 1 for laconic
                                    * 2 for normal

          -- ALGLIB --
             Copyright 01.02.2025 by Bochkanov Sergey
        *************************************************************************/
        public static void gipm3initbuf(double[] x0,
            int n,
            double eps,
            int maxits,
            int tracelevel,
            bool probeonfailure,
            bool analyzestep,
            gipm3state state,
            alglib.xparams _params)
        {
            state.n = n;
            state.meq = 0;
            state.mi = 0;
            state.mh = 0;
            state.mxx = 0;
            state.primalbound = Double.PositiveInfinity;
            state.dualbound = Double.NegativeInfinity;
            state.eshasintmask = false;
            state.esdualbound = Double.NegativeInfinity;
            state.esprimbound = Double.PositiveInfinity;
            state.esminits = 0;
            state.estol = 1.0E-6;
            ablasf.bsetallocv(state.n, false, ref state.esintmask, _params);
            gipm3setprofilequasinewton(state, _params);
            
            //
            // Save initial point for further processing
            //
            ablasf.rcopyallocv(n, x0, ref state.x0, _params);
            
            //
            // Prepare RCOMM-V2 protocol
            //
            state.rstate.ia = new int[4+1];
            state.rstate.ba = new bool[1+1];
            state.rstate.ra = new double[16+1];
            state.rstate.stage = -1;
            state.rstate.clear_handler();
            
            //
            // Initial penalty to enforce bounded level sets
            //
            ablasf.rsetallocv(n, 0.0, ref state.pg, _params);
            
            //
            // Stopping criteria and settings
            //
            alglib.ap.assert((double)(eps)>=(double)(0), "GIPM3: integrity check 554904 failed");
            state.eps = apserv.coalesce(eps, 10*Math.Sqrt(math.machineepsilon), _params);
            state.maxits = maxits;
            
            //
            // Report fields
            //
            state.repnfev = 0;
            state.repnfact = 0;
            state.repnllsfact = 0;
            state.repterminationtype = 0;
            state.repiterationscount = 0;
            state.repearlyerrorestimate = 0;
            state.repsclerr = 0;
            
            //
            // Trace status
            //
            state.dotracelaconic = tracelevel==1;
            state.dotrace = tracelevel>=2;
            state.doanytrace = state.dotrace || state.dotracelaconic;
            state.dodetailedtrace = tracelevel>=3;
            state.doprobeonfailure = tracelevel>=2 && probeonfailure;
            state.doanalyzestep = tracelevel>=2 && analyzestep;
        }


        /*************************************************************************
        Set profile for a quasi-Newton version of the step (linear convergence)

          -- ALGLIB --
             Copyright 01.02.2025 by Bochkanov Sergey
        *************************************************************************/
        public static void gipm3setprofilequasinewton(gipm3state state,
            alglib.xparams _params)
        {
            state.sendqnupdates = true;
            state.sendqnupdatesonfailedstep = true;
            state.refactorizeafterqnupdate = true;
            state.longsteps = true;
            state.maxnewtontrustratio = 50;
            state.muepsfactor = 20;
            state.dualerrwgt = 10.0;
            state.mudecaylinear = 0.2;
            state.mudecaypower = 1.0;
            state.smalltrustrad = 0.01*Math.Sqrt(math.machineepsilon);
            state.maxcheckpointstagnationits = 100;
        }


        public static void gipm3setconstr(gipm3state state,
            double[] ceq,
            int meq,
            double[] ci,
            int mi,
            double[] ch,
            bool[] chislinear,
            int mh,
            alglib.xparams _params)
        {
            int i = 0;

            state.meq = meq;
            state.mi = mi;
            state.mh = mh;
            ablasf.rcopyallocv(meq, ceq, ref state.rhseq, _params);
            ablasf.rcopyallocv(mi, ci, ref state.rhsi, _params);
            ablasf.rcopyallocv(mh, ch, ref state.rhsh, _params);
            ablasf.rsetallocv(mh, defaultfractohard, ref state.fractohard, _params);
            for(i=0; i<=mh-1; i++)
            {
                if( chislinear[i] )
                {
                    state.fractohard[i] = fractobnd;
                }
            }
        }


        /*************************************************************************
        This function allows to set optional primal bound for  the  algorithm.  If
        a solver determines that it converges to a value  well  above  the  primal
        bound, it will terminate prematurely with the Rep.TerminationType=6

        Presently, only nonlinear IPM method supports primal bounds.

        INPUT PARAMETERS:
            State   -   structure
            Bnd     -   primal bound, finite number or +INF (if no bound)

          -- ALGLIB --
             Copyright 02.02.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void gipm3setprimalbound(gipm3state state,
            double bnd,
            alglib.xparams _params)
        {
            alglib.ap.assert(math.isfinite(bnd) || Double.IsPositiveInfinity(bnd), "GIPM3SetPrimalBound: Bnd is not finite or +INF");
            state.primalbound = bnd;
        }


        /*************************************************************************
        This function allows to set optional dual bound for the  algorithm.

        INPUT PARAMETERS:
            State   -   structure
            Bnd     -   dual bound, finite number or -INF (if no bound)

          -- ALGLIB --
             Copyright 02.02.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void gipm3setdualbound(gipm3state state,
            double bnd,
            alglib.xparams _params)
        {
            alglib.ap.assert(math.isfinite(bnd) || Double.IsNegativeInfinity(bnd), "GIPM3SetDualBound: Bnd is not finite or +INF");
            state.dualbound = bnd;
        }


        /*************************************************************************
        This function allows to set optional early stopping on integer variables


          -- ALGLIB --
             Copyright 02.02.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void gipm3setearlystopping(gipm3state state,
            bool[] intmask,
            double dualbound,
            double primbound,
            int minearlyits,
            double etol,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(alglib.ap.len(intmask)>=state.n, "GIPM3SetEarlyStopping: Length(intMask)<N");
            ablasf.bcopyv(state.n, intmask, state.esintmask, _params);
            state.eshasintmask = false;
            for(i=0; i<=state.n-1; i++)
            {
                state.eshasintmask = state.eshasintmask || intmask[i];
            }
            state.esdualbound = dualbound;
            state.esprimbound = primbound;
            state.esminits = minearlyits;
            state.estol = etol;
        }


