                //
                // Failed to retrieve function/Jacobian, infinities detected!
                //
                if( state.doanytrace )
                {
                    alglib.ap.trace("> initial point has INF/NAN in objective, constraints or Jacobian; immediate termination\n");
                }
                state.repterminationtype = -8;
                result = false;
                return result;
            }
            for(i=0; i<=state.mh-1; i++)
            {
                if( (double)(state.current.ch[i])<=(double)(0) )
                {
                    
                    //
                    //
                    //
                    if( state.doanytrace )
                    {
                        alglib.ap.trace("> hard inequality constrains are violated at the initial point; immediate termination\n");
                    }
                    state.repterminationtype = -9;
                    result = false;
                    return result;
                }
            }
            for(i=0; i<=state.meq-1; i++)
            {
                state.current.ze[i] = -(state.current.ce[i]/state.currentmu);
            }
            for(i=0; i<=state.mi-1; i++)
            {
                state.current.s[i] = Math.Max(state.current.ci[i], initprimdual);
                state.current.zi[i] = apserv.boundval(-((state.current.ci[i]-state.current.s[i])/state.currentmu), -100, 100, _params);
                state.current.zs[i] = state.currentmu/state.current.s[i];
            }
            for(i=0; i<=state.mh-1; i++)
            {
                state.current.zh[i] = state.currentmu/state.current.ch[i];
            }
            state.requesttype = 1000;
            state.rstate.stage = 1;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            ablasf.rallocv(n, ref state.replyprod, _params);
            ablasf.rcopyvx(state.current.meq, state.current.ze, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(state.current.mi, state.current.zi, 0, state.querydata, state.current.meq, _params);
            ablasf.rcopyvx(state.current.mh, state.current.zh, 0, state.querydata, state.current.meq+state.current.mi, _params);
            state.requesttype = 1012;
            state.rstate.stage = 2;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_2:
            ablasf.rcopyallocv(n, state.current.g, ref state.current.laggrad, _params);
            ablasf.raddv(n, -1.0, state.replyprod, state.current.laggrad, _params);
            state.current.haslaggrad = true;
            state.hasqnlag0 = false;
            state.requesttype = 1005;
            state.rstate.stage = 3;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_3:
            ablasf.rcopyallocv(1+mtotal, state.replyv, ref state.callerfscales, _params);
            state.nrmx0 = ablasf.rmaxabsv(n, state.current.x, _params);
            state.absf0 = Math.Abs(state.current.fi[0])*state.callerfscales[0];
            ablasf.rcopyv(state.n, state.current.x, state.reportx, _params);
            state.reportf = state.current.fi[0];
            state.requesttype = -1;
            state.rstate.stage = 4;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_4:
            updateerrorreports(state, _params);
            
            //
            // Prepare best point.
            //
            // NOTE: BestErr is initialized by MaxRealNumber, which is intentional - it means that
            //       during the very first iteration any point is better than the best, and some
            //       code (in particular, one using SengLagrangianInfo()  function) relies on the property.
