            state.subsequentfactfailures = 0;
            state.firstouteriteration = true;
            alglib.ap.assert(state.mxx==0, "GIPM3: 789002 (unable to recompute scaling coefficient)");
            state.trustradscale = Math.Sqrt(n+state.mi);
            state.trustrad = 1.0*state.trustradscale;
            lastcheckpointd = math.maxrealnumber;
            lastcheckpointdidx = state.repiterationscount;
        lbl_20:
            if( false )
            {
                goto lbl_21;
            }
            
            //
            // Reset parameters and flags at the beginning of inner iterations
            //
            state.unboundednesssuspected = false;
            state.inneriterationidx = 0;
            nonmonotonicinit(state, nonmonotonicmemlen, _params);
            state.currentmerit = meritfunction(state, state.current, state.currentmu, _params);
            
            //
            // Inner iterations for fixed Mu.
            //
            // After this loop is done we have current point in State.Current and current residual
            // in State.RHS. Additionally, the current point is remembered as the one where the
            // Hessian should be calculated.
            //
        lbl_22:
            if( false )
            {
                goto lbl_23;
            }
            
            //
            // Check stopping criteria that should be checked early
            //
            if( state.userterminationneeded )
            {
                goto lbl_23;
            }
            if( state.maxits>0 && state.repiterationscount>=state.maxits )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> maximum number of iterations performed, stopping\n");
                }
                state.repterminationtype = 5;
                goto lbl_23;
            }
            if( (double)(state.trustrad)<=(double)(state.smalltrustrad*state.trustradscale) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format("> trust region size is too small (below {0,0:E2}), stopping\n", state.smalltrustrad*state.trustradscale));
                }
                state.repterminationtype = 7;
                goto lbl_23;
            }
            if( (double)(state.lambdav)>=(double)(lambdamax) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> regularization is at maximum, stopping with completion code 7\n");
                }
                state.repterminationtype = 7;
                goto lbl_23;
            }
            
            //
            // Issue rescale request, recompute merit function at the initial point, prepare regularization diagonal
            //
            state.requesttype = 1004;
            state.rstate.stage = 6;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_6:
            if( !state.replywasrescale )
            {
                goto lbl_24;
            }
            
            //
            // Handle rescale request
            //
            if( state.dotrace )
            {
                alglib.ap.trace("> target/constraints were rescaled due to gradient norms deviating too much from 1.0, clearing nonmonotonic memory");
            }
            if( state.dotrace )
            {
                alglib.ap.trace("\n");
            }
            rescalemodel(state, state.replyv, _params);
            state.currentmerit = meritfunction(state, state.current, state.currentmu, _params);
            
            //
            // Update callerFScales[]
            //
            state.requesttype = 1005;
            state.rstate.stage = 7;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_7:
            ablasf.rcopyallocv(1+mtotal, state.replyv, ref state.callerfscales, _params);
            lastcheckpointd = math.maxrealnumber;
            lastcheckpointdidx = state.repiterationscount;
        lbl_24:
            if( state.current.haslaggrad )
            {
                goto lbl_26;
            }
            ablasf.rallocv(n, ref state.replyprod, _params);
            ablasf.rcopyvx(state.current.meq, state.current.ze, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(state.current.mi, state.current.zi, 0, state.querydata, state.current.meq, _params);
            ablasf.rcopyvx(state.current.mh, state.current.zh, 0, state.querydata, state.current.meq+state.current.mi, _params);
            state.requesttype = 1012;
            state.rstate.stage = 8;
