                state.curbigval = apserv.rmaxabs3(state.curbigval, v, v1, _params);
                state.repiterationscount = state.repiterationscount+1;
                goto lbl_23;
            }
            
            //
            // Next iteration
            //
            state.requesttype = 1000;
            state.rstate.stage = 18;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_18:
            state.inneriterationidx = state.inneriterationidx+1;
            state.repiterationscount = state.repiterationscount+1;
            updateerrorreports(state, _params);
            goto lbl_22;
        lbl_23:
            state.lambdav = Math.Max(state.lambdav*state.lambdadecay, math.machineepsilon*math.machineepsilon);
            state.lambdadecay = Math.Max(state.lambdadecay*lambdadecayacc, Math.Sqrt(Math.Sqrt(math.machineepsilon)));
            state.firstouteriteration = false;
            if( state.dotrace )
            {
                alglib.ap.trace("\n----- outer iteration ------------------------------------------------------------------------------\n");
            }
            if( state.userterminationneeded )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> user requested immediate termination, stopping\n");
                }
                state.repterminationtype = 8;
                goto lbl_21;
            }
            if( state.repterminationtype!=0 )
            {
                goto lbl_21;
            }
            if( state.unboundednesssuspected )
            {
                if( ((double)(state.currentmu)<=(double)(1.001*state.mumin) && (double)(state.curbigval)>=(double)(0.999*maxbigval)) && (double)(state.curbiggrowth)>=(double)(0.999*maxbiggrowth) )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> unboundedness detected (mu at minimum, thresholds at maximum, the problem is still unbounded)\n");
                    }
                    state.repterminationtype = -4;
                    goto lbl_21;
                }
                if( state.dotrace )
                {
                    alglib.ap.trace("> decreasing mu, increasing unboundedness detection thresholds, continuing iterations\n");
                }
                state.currentmu = Math.Max(state.mumin, 0.01*state.currentmu);
                state.curbigval = Math.Min(vggrowth*state.curbigval, maxbigval);
                state.curbiggrowth = Math.Min(vggrowth*state.curbiggrowth, maxbiggrowth);
                goto lbl_20;
            }
            
            //
            // Recompute RHS from scratch (less dependency on the internal loop).
            // Check primal/dual/complementarity errors.
            //
            computerhs(state, state.current, 0.0, state.rhs, _params);
            computeerrors(state.current, state.rhs, ref eprim, ref edual, ref ecmpl, _params);
            emax = apserv.rmax3(eprim, edual, ecmpl, _params);
            if( state.dotrace )
            {
                alglib.ap.trace("> recomputing absolute errors:\n");
                alglib.ap.trace(System.String.Format("primal        = {0,0:E3}\n", eprim));
                alglib.ap.trace(System.String.Format("dual          = {0,0:E3}\n", edual));
                alglib.ap.trace(System.String.Format("cmpl          = {0,0:E3}\n", ecmpl));
            }
            if( (double)(emax)<=(double)(state.eps) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format("> stopping criteria for outer iterations are met (relative error is below Eps={0,0:E2}), solved\n", state.eps));
                }
                state.repterminationtype = 2;
                goto lbl_21;
            }
            if( (double)(state.currentmu)<=(double)(1.001*state.mumin) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> mu is at minimum, stagnation detected, stopping\n");
                }
                state.repterminationtype = 7;
                goto lbl_21;
            }
            
            //
            // Stopping criteria are not met, continuing iteration, save the best point so far
            //
            if( (double)(emax)>=(double)(0.5*state.besterr) )
            {
                goto lbl_42;
            }
            state.besterrchange = emax-state.besterr;
            state.besterr = emax;
            state.requesttype = 1006;
            state.rstate.stage = 19;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_19:
            if( state.dotrace )
            {
                alglib.ap.trace("> the point provides the best prim/dual errors so far, saving\n");
            }
            if( (math.isfinite(state.primalbound) && (double)(emax)<=(double)(primalboundmaxerr)) && (double)(state.current.fi[0]*state.callerfscales[0])>(double)(state.primalbound+primalboundsafetyfactor*Math.Abs(state.besterrchange)*state.callerfscales[0]) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> primal-bound-based stopping criteria for outer iterations are met:\n");
                }
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format("> objective value ({0,0:E6}) plus objective change between iterations ({1,0:E6}) times safety factor ({2,0:F1}) is larger than the primal bound ({3,0:E6})\n", state.current.fi[0]*state.callerfscales[0], Math.Abs(state.besterrchange), primalboundsafetyfactor, state.primalbound));
                }
                state.repearlyerrorestimate = primalboundsafetyfactor*Math.Abs(state.besterrchange)*state.callerfscales[0];
                varscopy(state.current, state.best, _params);
                state.repterminationtype = 21;
                goto lbl_21;
            }
            if( state.eshasintmask && (double)(emax)<=(double)(state.estol) )
            {
                v = dualboundsafetyfactor*Math.Abs(state.besterrchange)*state.callerfscales[0];
                b = true;
                if( math.isfinite(state.esdualbound) && (double)(state.current.fi[0]*state.callerfscales[0])<=(double)(state.esdualbound+v) )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> early stopping check: rejected by proximity to dual bound (raw_f={0,0:E9}, raw_dual_bnd={1,0:E9}, safety_bnd={2,0:E2})\n", state.current.fi[0]*state.callerfscales[0], state.esdualbound, v));
                    }
                    b = false;
                }
                if( b )
                {
                    if( state.dotrace )
                    {
                        v = 0.0;
                        v1 = 0;
                        for(i=0; i<=n-1; i++)
                        {
                            if( state.esintmask[i] && (double)(earlystoppingsafetyfactor*Math.Abs(state.current.x[i]-state.best.x[i]))<(double)(Math.Min(state.current.x[i]-(int)Math.Floor(state.current.x[i]), (int)Math.Ceiling(state.current.x[i])-state.current.x[i])) )
                            {
                                v = Math.Max(v, Math.Min(state.current.x[i]-(int)Math.Floor(state.current.x[i]), (int)Math.Ceiling(state.current.x[i])-state.current.x[i]));
                                v1 = v1+1;
                            }
                        }
                        if( state.dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> early stopping check: {0,0:d} integer vars converged, most fractional is {1,0:E2}\n", (int)Math.Round(v1), v));
                        }
                    }
                    v = 0.0;
                    for(i=0; i<=n-1; i++)
                    {
                        if( state.esintmask[i] && (double)(earlystoppingsafetyfactor*Math.Abs(state.current.x[i]-state.best.x[i]))<(double)(Math.Min(state.current.x[i]-(int)Math.Floor(state.current.x[i]), (int)Math.Ceiling(state.current.x[i])-state.current.x[i])) )
                        {
                            v = Math.Max(v, Math.Min(state.current.x[i]-(int)Math.Floor(state.current.x[i]), (int)Math.Ceiling(state.current.x[i])-state.current.x[i]));
                        }
                    }
                    if( (double)(v)>(double)(earlystoppingminfrac) )
                    {
                        if( state.dotrace )
                        {
                            alglib.ap.trace("> early stopping criteria for outer iterations are met: at least one integral variable converged\n");
                        }
                        state.repearlyerrorestimate = dualboundsafetyfactor*Math.Abs(state.besterrchange)*state.callerfscales[0];
                        varscopy(state.current, state.best, _params);
                        state.repterminationtype = 22;
                        goto lbl_21;
                    }
                }
            }
            varscopy(state.current, state.best, _params);
            goto lbl_43;
        lbl_42:
            if( state.dotrace )
            {
                alglib.ap.trace("> the point does not improve over the best prim/dual errors so far, not saved\n");
            }
        lbl_43:
            
            //
            // Inner iterations are over, tighten/relax bounds if necessary and decrease Mu
            //
            state.currentmu = Math.Max(state.mumin, Math.Min(state.mudecaylinear*state.currentmu, Math.Pow(state.currentmu, state.mudecaypower)));
            goto lbl_20;
        lbl_21:
            
            //
            // Almost done:
            // * compare error at State.Current with one at State.Best, restore from State.Best
            //   if optimizer went in wrong direction
            // * set completion flags
            //
            if( state.dotrace )
            {
                alglib.ap.trace("\n=== STOPPED ========================================================================================\n");
            }
            computerhs(state, state.current, state.currentmu, state.rhs, _params);
            if( state.infinitiesdetected )
            {
                state.repterminationtype = apserv.icase2(state.failedtorecoverfrominfinities, -8, state.repterminationtype+800, _params);
            }
            if( state.dotrace )
            {
                if( state.infinitiesdetected && state.failedtorecoverfrominfinities )
                {
                    alglib.ap.trace("> infinities were detected, but we failed to recover by decreasing trust radius; declaring failure with the code -8\n");
                }
                alglib.ap.trace(System.String.Format("raw target:     {0,20:E12}\n", state.current.fi[0]*state.callerfscales[0]));
                alglib.ap.trace(System.String.Format("iterations:     {0,0:d}\n", state.repiterationscount));
                alglib.ap.trace(System.String.Format("evaluations:    {0,0:d}\n", state.repnfev));
                alglib.ap.trace(System.String.Format("factorizations: {0,0:d} (KKT) + {1,0:d} (LLS)\n", state.repnfact, state.repnllsfact));
            }
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rstate.ia[0] = n;
            state.rstate.ia[1] = mtotal;
            state.rstate.ia[2] = i;
            state.rstate.ia[3] = rfsidx;
            state.rstate.ia[4] = lastcheckpointdidx;
            state.rstate.ba[0] = b;
            state.rstate.ba[1] = corrected;
            state.rstate.ra[0] = initprimdual;
            state.rstate.ra[1] = eprim;
            state.rstate.ra[2] = edual;
            state.rstate.ra[3] = ecmpl;
            state.rstate.ra[4] = emax;
            state.rstate.ra[5] = errorscale;
            state.rstate.ra[6] = rhs0;
            state.rstate.ra[7] = rhsk;
            state.rstate.ra[8] = rhsreq;
            state.rstate.ra[9] = v;
            state.rstate.ra[10] = v0;
            state.rstate.ra[11] = v1;
            state.rstate.ra[12] = lastcheckpointd;
            state.rstate.ra[13] = q0;
            state.rstate.ra[14] = q1;
            state.rstate.ra[15] = q2;
            state.rstate.ra[16] = corrmag;
            return result;
        }


        /*************************************************************************
        Extract solution

        INPUT PARAMETERS:
            State               -   solver instance
            
        OUTPUT PARAMETERS:
            XS                  -   array[N], solution
            Lag                 -   array[MEq+Mi+Mh], Lagrange multipliers.
                                    Multiplier signs are computed assuming that Lagrangian is
                                    equal to f(x) + SUM(lag[i]*con[i]).
            TerminationType     -   completion code, positive values for success,
                                    negative for failures (XS constrains best point
                                    found so far):
                                    * -2    the task is either unbounded or infeasible;
                                            the IPM solver has difficulty distinguishing between these two.
                                    * +1    stopping criteria are met
                                    * +7    stopping criteria are too stringent

        RESULT:

        This function ALWAYS returns something  meaningful in XS, LagBC, LagLC - 
        either solution or the best point so far, even for negative TerminationType.

          -- ALGLIB --
             Copyright 25.05.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void gipm3results(gipm3state state,
            ref double[] xs,
            ref double[] lag,
            ref int terminationtype,
            alglib.xparams _params)
        {
            terminationtype = 0;

            terminationtype = state.repterminationtype;
            ablasf.rcopyallocv(state.n, state.current.x, ref xs, _params);
            ablasf.rallocv(state.meq+state.mi+state.mh, ref lag, _params);
            ablasf.rcopyvx(state.meq, state.current.ze, 0, lag, 0, _params);
            ablasf.rcopyvx(state.mi, state.current.zi, 0, lag, state.meq, _params);
            ablasf.rcopyvx(state.mh, state.current.zh, 0, lag, state.meq+state.mi, _params);
            ablasf.rmulv(state.meq+state.mi+state.mh, -1.0, lag, _params);
        }


        /*************************************************************************
        Allocates place for variables of IPM, but do not fill it with any particular
        values

          -- ALGLIB --
             Copyright 11.12.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void varsalloc(gipm3vars vstate,
            int n,
            int meq,
            int mi,
            int mh,
            alglib.xparams _params)
        {
            
            //
            // Metrics
            //
            vstate.n = n;
            vstate.meq = meq;
            vstate.mi = mi;
            vstate.mh = mh;
            vstate.mxx = 0;
            
            //
            // Variables
            //
            ablasf.rallocv(n, ref vstate.x, _params);
            ablasf.rallocv(mi, ref vstate.s, _params);
            ablasf.rallocv(meq, ref vstate.ze, _params);
            ablasf.rallocv(mi, ref vstate.zi, _params);
            ablasf.rallocv(mh, ref vstate.zh, _params);
            ablasf.rallocv(mi, ref vstate.zs, _params);
            
            //
            // Function data
            //
            vstate.hasfunctions = false;
            vstate.haslaggrad = false;
        }


        /*************************************************************************
        Allocates place for variables of IPM and fills by zeros,
        clears HasFunctions flag.

          -- ALGLIB --
             Copyright 11.12.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void varsinitbyzero(gipm3vars vstate,
            int n,
            int meq,
            int mi,
            int mh,
            alglib.xparams _params)
        {
            
            //
            // Metrics
            //
            vstate.n = n;
            vstate.meq = meq;
            vstate.mi = mi;
            vstate.mh = mh;
            vstate.mxx = 0;
            
            //
            // Variables
            //
            ablasf.rsetallocv(n, 0.0, ref vstate.x, _params);
            ablasf.rsetallocv(mi, 0.0, ref vstate.s, _params);
            ablasf.rsetallocv(meq, 0.0, ref vstate.ze, _params);
            ablasf.rsetallocv(mi, 0.0, ref vstate.zi, _params);
            ablasf.rsetallocv(mh, 0.0, ref vstate.zh, _params);
            ablasf.rsetallocv(mi, 0.0, ref vstate.zs, _params);
            
            //
            // No function information at this point
            //
            vstate.hasfunctions = false;
            vstate.haslaggrad = false;
        }


        /*************************************************************************
        Applies step to primal and dual vars. 

        Invalidates function vector and Jacobian

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void varsapplystep(gipm3vars vstate,
            gipm3vars delta,
            double alpha,
            alglib.xparams _params)
        {
            ablasf.raddv(vstate.n, alpha, delta.x, vstate.x, _params);
            ablasf.raddv(vstate.mi, alpha, delta.s, vstate.s, _params);
            ablasf.raddv(vstate.meq, alpha, delta.ze, vstate.ze, _params);
            ablasf.raddv(vstate.mi, alpha, delta.zi, vstate.zi, _params);
            ablasf.raddv(vstate.mh, alpha, delta.zh, vstate.zh, _params);
            ablasf.raddv(vstate.mi, alpha, delta.zs, vstate.zs, _params);
            vstate.hasfunctions = false;
            vstate.haslaggrad = false;
        }


        /*************************************************************************
        Applies step to dual vars only, adjust Lagrangian gradient using product
        of Delta.multipliers with the current gradient.

        Doesn not invalidate function vector.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void varsapplydualstepx(gipm3vars vstate,
            gipm3vars delta,
            double alpha,
            double[] jdeltay,
            alglib.xparams _params)
        {
            ablasf.raddv(vstate.meq, alpha, delta.ze, vstate.ze, _params);
            ablasf.raddv(vstate.mi, alpha, delta.zi, vstate.zi, _params);
            ablasf.raddv(vstate.mh, alpha, delta.zh, vstate.zh, _params);
            ablasf.raddv(vstate.mi, alpha, delta.zs, vstate.zs, _params);
            if( vstate.haslaggrad )
            {
                ablasf.raddv(vstate.n, -alpha, jdeltay, vstate.laggrad, _params);
            }
        }


        /*************************************************************************
        Copy vars

          -- ALGLIB --
             Copyright 06.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void varscopy(gipm3vars src,
            gipm3vars dst,
            alglib.xparams _params)
        {
            alglib.ap.assert(src.mxx==0, "GIPM3: 712034 failed");
            
            //
            // Metrics
            //
            dst.n = src.n;
            dst.meq = src.meq;
            dst.mi = src.mi;
            dst.mh = src.mh;
            dst.mxx = 0;
            
            //
            // Variables
            //
            ablasf.rcopyallocv(src.n, src.x, ref dst.x, _params);
            ablasf.rcopyallocv(src.mi, src.s, ref dst.s, _params);
            ablasf.rcopyallocv(src.meq, src.ze, ref dst.ze, _params);
            ablasf.rcopyallocv(src.mi, src.zi, ref dst.zi, _params);
            ablasf.rcopyallocv(src.mh, src.zh, ref dst.zh, _params);
            ablasf.rcopyallocv(src.mi, src.zs, ref dst.zs, _params);
            
            //
            // Function information
            //
            dst.hasfunctions = src.hasfunctions;
            if( src.hasfunctions )
            {
                dst.f = src.f;
                ablasf.rcopyallocv(src.n, src.g, ref dst.g, _params);
                ablasf.rcopyallocv(src.meq, src.ce, ref dst.ce, _params);
                ablasf.rcopyallocv(src.mi, src.ci, ref dst.ci, _params);
                ablasf.rcopyallocv(src.mh, src.ch, ref dst.ch, _params);
                ablasf.rcopyallocv(1+src.meq+src.mi+src.mh, src.fi, ref dst.fi, _params);
            }
            
            //
            // Lagrange information
            //
            dst.haslaggrad = src.haslaggrad;
            if( src.haslaggrad )
            {
                ablasf.rcopyallocv(src.n, src.laggrad, ref dst.laggrad, _params);
            }
        }


        /*************************************************************************
        Multiplies all variables by scalar. Does NOT work for variables with function
        values or Lagrangian gradient stored.

          -- ALGLIB --
             Copyright 06.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void varsmultiplyby(gipm3vars vfj,
            double v,
            alglib.xparams _params)
        {
            alglib.ap.assert(vfj.mxx==0, "GIPM3: 869847 failed");
            alglib.ap.assert(!vfj.hasfunctions && !vfj.haslaggrad, "GIPM3: 870848 failed");
            ablasf.rmulv(vfj.n, v, vfj.x, _params);
            ablasf.rmulv(vfj.mi, v, vfj.s, _params);
            ablasf.rmulv(vfj.meq, v, vfj.ze, _params);
            ablasf.rmulv(vfj.mi, v, vfj.zi, _params);
            ablasf.rmulv(vfj.mh, v, vfj.zh, _params);
            ablasf.rmulv(vfj.mi, v, vfj.zs, _params);
        }


        /*************************************************************************
        Rescale vars according to multiplier vector passed by the caller.

        An additional vector for temporary storage of size max(N,MEq+Mi+Mh)+1 is
        passed.

          -- ALGLIB --
             Copyright 06.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void varsrescale(gipm3vars dst,
            double[] rescaleby,
            double[] tmp,
            alglib.xparams _params)
        {
            
            //
            // Rescale primary variables
            //
            ablasf.rcopyvx(dst.n, rescaleby, 1+dst.meq+dst.mi+dst.mh, tmp, 0, _params);
            ablasf.rmergemulv(dst.n, tmp, dst.x, _params);
            
            //
            // Rescale slacks and multipliers
            //
            ablasf.rcopyvx(dst.meq, rescaleby, 1, tmp, 0, _params);
            ablasf.rmergedivv(dst.meq, tmp, dst.ze, _params);
            ablasf.rcopyvx(dst.mi, rescaleby, 1+dst.meq, tmp, 0, _params);
            ablasf.rmergemulv(dst.mi, tmp, dst.s, _params);
            ablasf.rmergedivv(dst.mi, tmp, dst.zs, _params);
            ablasf.rmergedivv(dst.mi, tmp, dst.zi, _params);
            ablasf.rcopyvx(dst.mh, rescaleby, 1+dst.meq+dst.mi, tmp, 0, _params);
            ablasf.rmergedivv(dst.mh, tmp, dst.zh, _params);
            
            //
            // Rescale functionss
            //
            if( dst.hasfunctions )
            {
                dst.f = rescaleby[0]*dst.f;
                ablasf.rmulv(dst.n, rescaleby[0], dst.g, _params);
                ablasf.rcopyvx(dst.meq, rescaleby, 1, tmp, 0, _params);
                ablasf.rmergemulv(dst.meq, tmp, dst.ce, _params);
                ablasf.rcopyvx(dst.mi, rescaleby, 1+dst.meq, tmp, 0, _params);
                ablasf.rmergemulv(dst.mi, tmp, dst.ci, _params);
                ablasf.rcopyvx(dst.mh, rescaleby, 1+dst.meq+dst.mi, tmp, 0, _params);
                ablasf.rmergemulv(dst.mh, tmp, dst.ch, _params);
                ablasf.rmergemulv(1+dst.meq+dst.mi+dst.mh, rescaleby, dst.fi, _params);
            }
            
            //
            // Lagrangian gradient invalidated
            //
            dst.haslaggrad = false;
        }


        /*************************************************************************
        Compute scaled 2-norm of primal variables combined; primarily used in the
        scald trust region method to compute step length.

        The scaled norm of a vector is (S*x,S*x)

          -- ALGLIB --
             Copyright 06.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static double varssclnrmprimal(gipm3vars vfj,
            gipm3vars s,
            alglib.xparams _params)
        {
            double result = 0;

            alglib.ap.assert(vfj.mxx==0, "GIPM3: 075819 failed");
            result = 0;
            result = result+ablasf.rdotscl1v2(vfj.n, vfj.x, s.x, _params);
            result = result+ablasf.rdotscl1v2(vfj.mi, vfj.s, s.s, _params);
            result = Math.Sqrt(result);
            return result;
        }


        /*************************************************************************
        Computes baseline scaling vector

          -- ALGLIB --
             Copyright 06.02.2026 by Bochkanov Sergey
        *************************************************************************/
        private static void varsbaselinescaling(gipm3vars current,
            gipm3vars scaling,
            alglib.xparams _params)
        {
            int i = 0;
            double vs = 0;

            vs = 0.01;
            varsalloc(scaling, current.n, current.meq, current.mi, current.mh, _params);
            for(i=0; i<=current.n-1; i++)
            {
                scaling.x[i] = 1/(Math.Abs(current.x[i])*vs+1);
            }
            for(i=0; i<=current.meq-1; i++)
            {
                scaling.ze[i] = 1/(Math.Abs(current.ze[i])*vs+1);
            }
            for(i=0; i<=current.mi-1; i++)
            {
                scaling.s[i] = 1/(current.s[i]*vs+1);
                scaling.zs[i] = 1/(current.zs[i]*vs+1);
                scaling.zi[i] = 1/(Math.Abs(current.zi[i])*vs+1);
            }
            for(i=0; i<=current.mh-1; i++)
            {
                scaling.zh[i] = 1/(current.zh[i]*vs+1);
            }
        }


        /*************************************************************************
        Compute primal multipliers

          -- ALGLIB --
             Copyright 11.12.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void computeprimalmult(gipm3vars vfj,
            double currentmu,
            gipm3primalmult mult,
            alglib.xparams _params)
        {
            alglib.ap.assert(vfj.mxx==0, "GIPM3: 768211 failed");
            alglib.ap.assert(vfj.hasfunctions, "GIPM3: 768212 failed");
            
            //
            // Allocate place
            //
            ablasf.rallocv(vfj.meq, ref mult.zeprim, _params);
            ablasf.rallocv(vfj.mi, ref mult.ziprim, _params);
            ablasf.rallocv(vfj.mh, ref mult.zhprim, _params);
            ablasf.rallocv(vfj.mi, ref mult.zsprim, _params);
            
            //
            // Compute
            //
            ablasf.rcopymulv(vfj.meq, -(1/currentmu), vfj.ce, mult.zeprim, _params);
            ablasf.rcopymulv(vfj.mi, -(1/currentmu), vfj.ci, mult.ziprim, _params);
            ablasf.raddv(vfj.mi, 1/currentmu, vfj.s, mult.ziprim, _params);
            ablasf.rsetv(vfj.mh, currentmu, mult.zhprim, _params);
            ablasf.rmergedivv(vfj.mh, vfj.ch, mult.zhprim, _params);
            ablasf.rsetv(vfj.mi, currentmu, mult.zsprim, _params);
            ablasf.rmergedivv(vfj.mi, vfj.s, mult.zsprim, _params);
        }


        /*************************************************************************
        Computes step length limit due to variables nonnegativity; a large value
        is returned if the step is unlimited.

        The fraction-to-boundary rule is applied prior to return, with different
        values being applied to slack variables, linear models of hard constraints
        that are known to be linear, and ones that are known to be nonlinear in
        nature.

          -- ALGLIB --
             Copyright 11.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static double computemaxsteplength(gipm3vars current,
            gipm3vars delta,
            double[] jdeltax,
            double[] fractohard,
            alglib.xparams _params)
        {
            double result = 0;
            int meq = 0;
            int mi = 0;
            int mh = 0;
            int i = 0;
            double v = 0;
            double v0 = 0;
            double v1 = 0;
            double eps2 = 0;

            meq = current.meq;
            mi = current.mi;
            mh = current.mh;
            eps2 = 1/Math.Sqrt(math.maxrealnumber);
            result = Math.Sqrt(math.maxrealnumber);
            for(i=0; i<=mi-1; i++)
            {
                if( delta.zs[i]<0.0 )
                {
                    v = fractobnd*current.zs[i]/(eps2-delta.zs[i]);
                    if( v<result )
                    {
                        result = v;
                    }
                }
                if( delta.s[i]<0.0 )
                {
                    v = fractobnd*current.s[i]/(eps2-delta.s[i]);
                    if( v<result )
                    {
                        result = v;
                    }
                }
            }
            for(i=0; i<=mh-1; i++)
            {
                if( delta.zh[i]<0.0 )
                {
                    v = fractobnd*current.zh[i]/(eps2-delta.zh[i]);
                    if( v<result )
                    {
                        result = v;
                    }
                }
            }
            for(i=0; i<=mh-1; i++)
            {
                v = jdeltax[meq+mi+i];
                v0 = current.ch[i];
                v1 = fractohard[i]*v0/Math.Max(-v, 1.0E-50*v0);
                if( v1<result )
                {
                    result = v1;
                }
            }
            return result;
        }


        /*************************************************************************
        Computes step length limit for dual variables due to variables nonnegativity;
        a large value is returned if the step is unlimited.

        Only dual variables are counted!

        The fraction-to-boundary rule is applied prior to return, with different
        values being applied to slack variables, linear models of hard constraints
        that are known to be linear, and ones that are known to be nonlinear in
        nature.

          -- ALGLIB --
             Copyright 11.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static double computemaxdualsteplength(gipm3vars current,
            gipm3vars delta,
            double fracto,
            alglib.xparams _params)
        {
            double result = 0;
            int mi = 0;
            int mh = 0;
            int i = 0;
            double v = 0;
            double eps2 = 0;

            mi = current.mi;
            mh = current.mh;
            eps2 = 1/Math.Sqrt(math.maxrealnumber);
            result = Math.Sqrt(math.maxrealnumber);
            for(i=0; i<=mi-1; i++)
            {
                if( delta.zs[i]<0.0 )
                {
                    v = fracto*current.zs[i]/(eps2-delta.zs[i]);
                    if( v<result )
                    {
                        result = v;
                    }
                }
            }
            for(i=0; i<=mh-1; i++)
            {
                if( delta.zh[i]<0.0 )
                {
                    v = fracto*current.zh[i]/(eps2-delta.zh[i]);
                    if( v<result )
                    {
                        result = v;
                    }
                }
            }
            return result;
        }


        /*************************************************************************
        Compute RHS for a Newton system, additionally saving dual multiplier
        estimates into RHS.

        Returns inf-norms of raw (unnormalized) primal, dual, complementarity errors.
        Also returns normalizing coefficients for errors.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void computerhs(gipm3state state,
            gipm3vars vfj,
            double currentmu,
            gipm3rhs rhs,
            alglib.xparams _params)
        {
            int n = 0;

            n = state.n;
            alglib.ap.assert(state.mxx==0, "GIPM3: 280114 failed");
            alglib.ap.assert(vfj.hasfunctions && vfj.haslaggrad, "GIPM3: 560828 failed");
            
            //
            // Compute RPX
            //
            ablasf.rallocv(n, ref rhs.rpx, _params);
            ablasf.rcopymulv(n, -1.0, vfj.laggrad, rhs.rpx, _params);
            ablasf.raddv(n, -currentmu, state.pg, rhs.rpx, _params);
            
            //
            // Compute RPS
            //
            if( vfj.mi>0 )
            {
                ablasf.rcopyallocv(vfj.mi, vfj.zs, ref rhs.rps, _params);
                ablasf.raddv(vfj.mi, -1.0, vfj.zi, rhs.rps, _params);
            }
            
            //
            // Compute RZE
            //
            if( vfj.meq>0 )
            {
                ablasf.rallocv(vfj.meq, ref rhs.rze, _params);
                ablasf.rcopymulv(vfj.meq, -1.0, vfj.ce, rhs.rze, _params);
                ablasf.raddv(vfj.meq, -currentmu, vfj.ze, rhs.rze, _params);
            }
            
            //
            // Compute RZI
            //
            if( vfj.mi>0 )
            {
                ablasf.rallocv(vfj.mi, ref rhs.rzi, _params);
                ablasf.rcopymulv(vfj.mi, -1.0, vfj.ci, rhs.rzi, _params);
                ablasf.raddv(vfj.mi, 1.0, vfj.s, rhs.rzi, _params);
                ablasf.raddv(vfj.mi, -currentmu, vfj.zi, rhs.rzi, _params);
            }
            
            //
            // Compute RZh
            //
            if( vfj.mh>0 )
            {
                alglib.ap.assert((double)(ablasf.rminv(vfj.mh, vfj.ch, _params))>(double)(0), "GIPM3: 335117 hard inequality violated");
                ablasf.rsetallocv(vfj.mh, currentmu, ref rhs.rzh, _params);
                ablasf.rnegmuladdv(vfj.mh, vfj.ch, vfj.zh, rhs.rzh, _params);
            }
            
            //
            // Compute RZs
            //
            if( vfj.mi>0 )
            {
                ablasf.rsetallocv(vfj.mi, currentmu, ref rhs.rzs, _params);
                ablasf.rnegmuladdv(vfj.mi, vfj.s, vfj.zs, rhs.rzs, _params);
            }
        }


        /*************************************************************************
        Given RHS, compute quadratic model of its squared norm along dual direction
        of Delta (primal variables are considered fixed).

        JTDY is an array [MTotal] containing a product of J' and appropriate dual
        variables.

        Returns coefficients of Q0+Q1*alpha+Q2*alpha^2, with alpha=1 corresponding
        to a unit step across the direction.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void rhscomputequadraticmodelalongdualdirection(gipm3state state,
            gipm3vars vfj,
            double currentmu,
            gipm3rhs rhs,
            gipm3vars delta,
            double[] jtdy,
            double dualerrwgt,
            ref double q0,
            ref double q1,
            ref double q2,
            alglib.xparams _params)
        {
            int n = 0;
            int mtotal = 0;
            double[] tmp = new double[0];

            q0 = 0;
            q1 = 0;
            q2 = 0;

            n = state.n;
            mtotal = state.meq+state.mi+state.mh+state.mxx;
            alglib.ap.assert(vfj.hasfunctions, "GIPM3: 284133 failed");
            
            //
            // Prepare
            //
            state.mnx1pool.retrieve(ref tmp);
            alglib.ap.assert(alglib.ap.len(tmp)>=Math.Max(n, mtotal+1), "GIPM3: 286116 failed");
            q0 = 0;
            q1 = 0;
            q2 = 0;
            
            //
            // RPX(alpha)   = RPX(0) + JTDY*alpha
            // RPX(alpha)^2 = RPX(0)^2 + 2*(RPX(0)'*JTDY)*alpha + (JTDY'*JTDY)*alpha^2
            //
            q0 = q0+dualerrwgt*ablasf.rdotv2(n, rhs.rpx, _params);
            q1 = q1+dualerrwgt*2*ablasf.rdotv(n, rhs.rpx, jtdy, _params);
            q2 = q2+dualerrwgt*ablasf.rdotv2(n, jtdy, _params);
            
            //
            // RPS(alpha)   = RPS(0) + (Delta.dZs-Delta.Zi)*alpha
            // RPS(alpha)^2 = RPS(0)^2 + 2*(RPS(0)*(Delta.dZs-Delta.Zi))*alpha + (Delta.dZs-Delta.Zi^2)*alpha^2
            //
            if( vfj.mi>0 )
            {
                ablasf.rcopyv(vfj.mi, delta.zs, tmp, _params);
                ablasf.raddv(vfj.mi, -1, delta.zi, tmp, _params);
                q0 = q0+dualerrwgt*ablasf.rdotv2(vfj.mi, rhs.rps, _params);
                q1 = q1+dualerrwgt*2*ablasf.rdotv(vfj.mi, rhs.rps, tmp, _params);
                q2 = q2+dualerrwgt*ablasf.rdotv2(vfj.mi, tmp, _params);
            }
            
            //
            // RZE(alpha)   = RZE(0) + (-mu*Delta.Ze)*alpha
            // RZE(alpha)^2 = RZE(0)^2 + 2*RZE(0)*(-mu*Delta.Ze)*alpha + (-mu*Delta.Ze)^2*alpha^2
            //
            if( vfj.meq>0 )
            {
                ablasf.rcopymulv(vfj.meq, -currentmu, delta.ze, tmp, _params);
                q0 = q0+ablasf.rdotv2(vfj.meq, rhs.rze, _params);
                q1 = q1+2*ablasf.rdotv(vfj.meq, rhs.rze, tmp, _params);
                q2 = q2+ablasf.rdotv2(vfj.meq, tmp, _params);
            }
            
            //
            // RZI(alpha)   = RZI(0) + (-mu*Delta.Zi)*alpha
            // RZI(alpha)^2 = RZI(0)^2 + 2*RZI(0)*(-mu*Delta.Zi)*alpha + (-mu*Delta.Zi)^2*alpha^2
            //
            if( vfj.mi>0 )
            {
                ablasf.rcopymulv(vfj.mi, -currentmu, delta.zi, tmp, _params);
                q0 = q0+ablasf.rdotv2(vfj.mi, rhs.rzi, _params);
                q1 = q1+2*ablasf.rdotv(vfj.mi, rhs.rzi, tmp, _params);
                q2 = q2+ablasf.rdotv2(vfj.mi, tmp, _params);
            }
            
            //
            // RZH(alpha)   = RZH(0) + (-CH*Delta.Zh)*alpha
            // RZH(alpha)^2 = RZH(0)^2 + 2*RZH(0)*(-CH*Delta.Zh)*alpha + (-CH*Delta.Zh)^2*alpha^2
            //
            if( vfj.mh>0 )
            {
                ablasf.rcopymulv(vfj.mh, -1.0, vfj.ch, tmp, _params);
                ablasf.rmergemulv(vfj.mh, delta.zh, tmp, _params);
                q0 = q0+ablasf.rdotv2(vfj.mh, rhs.rzh, _params);
                q1 = q1+2*ablasf.rdotv(vfj.mh, rhs.rzh, tmp, _params);
                q2 = q2+ablasf.rdotv2(vfj.mh, tmp, _params);
            }
            
            //
            // RZS(alpha)   = RZS(0) + (-S*Delta.Zs)*alpha
            // RZS(alpha)^2 = RZS(0)^2 + 2*RZS(0)*(-S*Delta.Zs)*alpha + (-S*Delta.Zs)^2*alpha^2
            //
            if( vfj.mi>0 )
            {
                ablasf.rcopymulv(vfj.mi, -1.0, vfj.s, tmp, _params);
                ablasf.rmergemulv(vfj.mi, delta.zs, tmp, _params);
                q0 = q0+ablasf.rdotv2(vfj.mi, rhs.rzs, _params);
                q1 = q1+2*ablasf.rdotv(vfj.mi, rhs.rzs, tmp, _params);
                q2 = q2+ablasf.rdotv2(vfj.mi, tmp, _params);
            }
            
            //
            // Done
            //
            state.mnx1pool.recycle(ref tmp);
        }


        /*************************************************************************
        Compute inf-norm primal, dual and complementarity errors (primal errors
        are reported subject to relaxation induced by the dual regularization).

          -- ALGLIB --
             Copyright 11.05.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void computeerrors(gipm3vars vfj,
            gipm3rhs rhs,
            ref double eprim,
            ref double edual,
            ref double ecmpl,
            alglib.xparams _params)
        {
            eprim = 0;
            edual = 0;
            ecmpl = 0;

            alglib.ap.assert(vfj.mxx==0, "GIPM3: 327231 failed");
            eprim = Math.Max(ablasf.rmaxabsv(vfj.meq, rhs.rze, _params), ablasf.rmaxabsv(vfj.mi, rhs.rzi, _params));
            edual = Math.Max(ablasf.rmaxabsv(vfj.n, rhs.rpx, _params), ablasf.rmaxabsv(vfj.mi, rhs.rps, _params));
            ecmpl = Math.Max(ablasf.rmaxabsv(vfj.mh, rhs.rzh, _params), ablasf.rmaxabsv(vfj.mi, rhs.rzs, _params));
        }


        /*************************************************************************
        Compute residual from the candidate solution for the already compute RHS:

            RHS := RHS - [SYSTEM]*delta
            
        Inputs include current location, candidate solution Delta and precomputed
        products H*Delta.XP, J*Delta.XP, J'*Delta.Y

        Returns inf-norm of the residual.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double computeupdateresidual(gipm3state state,
            gipm3vars vfj,
            double currentmu,
            double[] currentdiag,
            gipm3vars delta,
            double[] hdx,
            double[] jdx,
            double[] jtdy,
            gipm3rhs rhs,
            alglib.xparams _params)
        {
            double result = 0;
            int n = 0;
            int mtotal = 0;
            double[] tmp = new double[0];

            n = state.n;
            mtotal = state.meq+state.mi+state.mh+state.mxx;
            alglib.ap.assert(state.mxx==0, "GIPM3: 280114 failed");
            alglib.ap.assert(vfj.hasfunctions, "GIPM3: 284133 failed");
            state.mnx1pool.retrieve(ref tmp);
            alglib.ap.assert(alglib.ap.len(tmp)>=Math.Max(n, mtotal+1), "GIPM3: 468626 failed");
            result = 0;
            
            //
            // Update RPX
            //
            ablasf.raddv(n, -1.0, hdx, rhs.rpx, _params);
            ablasf.rnegmuladdv(n, currentdiag, delta.x, rhs.rpx, _params);
            ablasf.raddv(n, 1.0, jtdy, rhs.rpx, _params);
            result = Math.Max(result, ablasf.rmaxabsv(n, rhs.rpx, _params));
            
            //
            // Update RPS
            //
            if( vfj.mi>0 )
            {
                ablasf.raddv(vfj.mi, -1.0, delta.zi, rhs.rps, _params);
                ablasf.raddv(vfj.mi, 1.0, delta.zs, rhs.rps, _params);
                result = Math.Max(result, ablasf.rmaxabsv(vfj.mi, rhs.rps, _params));
            }
            
            //
            // Update RZE
            //
            if( vfj.meq>0 )
            {
                ablasf.raddvx(vfj.meq, -1.0, jdx, 0, rhs.rze, 0, _params);
                ablasf.raddv(vfj.meq, -currentmu, delta.ze, rhs.rze, _params);
                result = Math.Max(result, ablasf.rmaxabsv(vfj.meq, rhs.rze, _params));
            }
            
            //
            // Update RZI
            //
            if( vfj.mi>0 )
            {
                ablasf.raddvx(vfj.mi, -1.0, jdx, vfj.meq, rhs.rzi, 0, _params);
                ablasf.raddv(vfj.mi, 1.0, delta.s, rhs.rzi, _params);
                ablasf.raddv(vfj.mi, -currentmu, delta.zi, rhs.rzi, _params);
                result = Math.Max(result, ablasf.rmaxabsv(vfj.mi, rhs.rzi, _params));
            }
            
            //
            // Update RZh
            //
            if( vfj.mh>0 )
            {
                ablasf.rcopyvx(vfj.mh, jdx, vfj.meq+vfj.mi, tmp, 0, _params);
                ablasf.rnegmuladdv(vfj.mh, vfj.zh, tmp, rhs.rzh, _params);
                ablasf.rnegmuladdv(vfj.mh, vfj.ch, delta.zh, rhs.rzh, _params);
                result = Math.Max(result, ablasf.rmaxabsv(vfj.mh, rhs.rzh, _params));
            }
            
            //
            // Compute RZs
            //
            if( vfj.mi>0 )
            {
                ablasf.rnegmuladdv(vfj.mi, vfj.zs, delta.s, rhs.rzs, _params);
                ablasf.rnegmuladdv(vfj.mi, vfj.s, delta.zs, rhs.rzs, _params);
                result = Math.Max(result, ablasf.rmaxabsv(vfj.mi, rhs.rzs, _params));
            }
            
            //
            // Recycle temporary array
            //
            state.mnx1pool.recycle(ref tmp);
            return result;
        }


        /*************************************************************************
        Transforms nonsymmetric Newton system into a symmetric condensed form

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void condenselhs(gipm3state state,
            gipm3vars current,
            double currentmu,
            double[] currentdiag,
            gipm3condensedsystem c,
            alglib.xparams _params)
        {
            int n = 0;
            int mtotal = 0;
            double[] tmp0 = new double[0];

            n = state.n;
            mtotal = state.meq+state.mi+state.mh+state.mxx;
            alglib.ap.assert(state.mxx==0, "GIPM3: 641159 failed");
            state.mnx1pool.retrieve(ref tmp0);
            
            //
            // Initial D0 and D1
            //
            ablasf.rcopyallocv(n, currentdiag, ref c.d0, _params);
            ablasf.rsetallocv(mtotal, 0.0, ref c.d1, _params);
            
            //
            // Handle various constraint types
            //
            if( current.meq>0 )
            {
                ablasf.rsetvx(current.meq, -currentmu, c.d1, 0, _params);
            }
            if( current.mi>0 )
            {
                ablasf.rcopyv(current.mi, current.s, tmp0, _params);
                ablasf.rmergedivv(current.mi, current.zs, tmp0, _params);
                ablasf.rsetvx(current.mi, -currentmu, c.d1, current.meq, _params);
                ablasf.raddvx(current.mi, -1.0, tmp0, 0, c.d1, current.meq, _params);
            }
            if( current.mh>0 )
            {
                ablasf.rcopyv(current.mh, current.ch, tmp0, _params);
                ablasf.rmergedivv(current.mh, current.zh, tmp0, _params);
                ablasf.raddvx(current.mh, -1.0, tmp0, 0, c.d1, current.meq+current.mi, _params);
            }
            
            //
            // Done, recycle temporaries
            //
            state.mnx1pool.recycle(ref tmp0);
        }


        /*************************************************************************
        Transforms nonsymmetric augmented system for least squares subproblem into
        a symmetric condensed form

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void condenseleastsquareslhs(gipm3state state,
            gipm3vars current,
            double currentmu,
            double dualerrwgt,
            gipm3condensedleastsquaressystem c,
            alglib.xparams _params)
        {
            int n = 0;
            int mtotal = 0;
            double[] tmp0 = new double[0];

            n = state.n;
            mtotal = state.meq+state.mi+state.mh+state.mxx;
            alglib.ap.assert(state.mxx==0, "GIPM3: 610104 failed");
            state.mnx1pool.retrieve(ref tmp0);
            
            //
            // Settings
            //
            c.vscl = 1;
            c.rege = Math.Sqrt(math.machineepsilon);
            c.regi = Math.Sqrt(math.machineepsilon);
            c.regh = Math.Sqrt(math.machineepsilon);
            c.regs = Math.Sqrt(math.machineepsilon);
            
            //
            // Condensing LHS
            //
            ablasf.rsetallocv(current.meq, c.rege+currentmu*currentmu/c.vscl, ref c.regem, _params);
            ablasf.rsetallocv(current.mi, c.regi+currentmu*currentmu/c.vscl, ref c.regim, _params);
            ablasf.rsetallocv(current.mh, c.regh*c.vscl, ref c.reghm, _params);
            ablasf.rmuladdv(current.mh, current.ch, current.ch, c.reghm, _params);
            ablasf.rmulv(current.mh, 1/c.vscl, c.reghm, _params);
            ablasf.rsetallocv(current.mi, c.regs*c.vscl, ref c.regsm, _params);
            ablasf.rmuladdv(current.mi, current.s, current.s, c.regsm, _params);
            ablasf.rmulv(current.mi, 1/c.vscl, c.regsm, _params);
            ablasf.rsetv(current.mi, dualerrwgt*dualerrwgt, tmp0, _params);
            ablasf.raddv(current.mi, c.vscl, c.regsm, tmp0, _params);
            ablasf.rsetallocv(current.mi, dualerrwgt, ref c.regs3, _params);
            ablasf.rmergedivv(current.mi, tmp0, c.regs3, _params);
            ablasf.rcopyallocv(current.mi, c.regim, ref c.regi3, _params);
            ablasf.rcopyv(current.mi, c.regsm, tmp0, _params);
            ablasf.rmergemulv(current.mi, c.regs3, tmp0, _params);
            ablasf.raddv(current.mi, dualerrwgt, tmp0, c.regi3, _params);
            ablasf.rsetallocv(n, c.vscl/dualerrwgt, ref c.d0, _params);
            ablasf.rallocv(mtotal, ref c.d1, _params);
            ablasf.rcopyvx(current.meq, c.regem, 0, c.d1, 0, _params);
            ablasf.rcopyvx(current.mi, c.regi3, 0, c.d1, current.meq, _params);
            ablasf.rcopyvx(current.mh, c.reghm, 0, c.d1, current.meq+current.mi, _params);
            ablasf.rmulv(mtotal, -1.0, c.d1, _params);
            
            //
            // Done, recycle temporaries
            //
            state.mnx1pool.recycle(ref tmp0);
        }


        /*************************************************************************
        Copy RHS

          -- ALGLIB --
             Copyright 07.05.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void rhscopy(gipm3state state,
            gipm3rhs rhs,
            gipm3rhs dst,
            alglib.xparams _params)
        {
            alglib.ap.assert(state.mxx==0, "GIPM3: 688226 failed");
            ablasf.rcopyallocv(state.n, rhs.rpx, ref dst.rpx, _params);
            ablasf.rcopyallocv(state.meq, rhs.rze, ref dst.rze, _params);
            ablasf.rcopyallocv(state.mi, rhs.rzi, ref dst.rzi, _params);
            ablasf.rcopyallocv(state.mi, rhs.rps, ref dst.rps, _params);
            ablasf.rcopyallocv(state.mi, rhs.rzs, ref dst.rzs, _params);
            ablasf.rcopyallocv(state.mh, rhs.rzh, ref dst.rzh, _params);
        }


        /*************************************************************************
        Condense only right-hand-side using already condensed left hand side.

          -- ALGLIB --
             Copyright 07.05.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void condenserhs(gipm3state state,
            gipm3vars current,
            gipm3rhs rhs,
            double currentmu,
            double[] currentdiag,
            gipm3condensedsystem condensed,
            alglib.xparams _params)
        {
            int n = 0;
            int mtotal = 0;
            double[] tmp0 = new double[0];

            n = state.n;
            mtotal = state.meq+state.mi+state.mh+state.mxx;
            alglib.ap.assert(state.mxx==0, "GIPM3: 708201 failed");
            state.mnx1pool.retrieve(ref tmp0);
            
            //
            // Initialize WX
            //
            ablasf.rcopyallocv(n, rhs.rpx, ref condensed.wx, _params);
            
            //
            // Initialize WY
            //
            ablasf.rsetallocv(mtotal, 0.0, ref condensed.wy, _params);
            if( state.meq>0 )
            {
                ablasf.rcopyvx(state.meq, rhs.rze, 0, condensed.wy, 0, _params);
            }
            if( state.mi>0 )
            {
                ablasf.rcopyvx(state.mi, rhs.rzi, 0, condensed.wy, state.meq, _params);
                ablasf.rallocv(state.mi, ref condensed.cached0, _params);
                ablasf.rcopymuladdv(state.mi, current.s, rhs.rps, rhs.rzs, condensed.cached0, _params);
                ablasf.rmergedivv(state.mi, current.zs, condensed.cached0, _params);
                ablasf.raddvx(state.mi, 1.0, condensed.cached0, 0, condensed.wy, state.meq, _params);
            }
            if( state.mh>0 )
            {
                ablasf.rcopyv(state.mh, rhs.rzh, tmp0, _params);
                ablasf.rmergedivv(state.mh, current.zh, tmp0, _params);
                ablasf.rcopyvx(state.mh, tmp0, 0, condensed.wy, state.meq+state.mi, _params);
            }
            
            //
            // Done, recycle temporaries
            //
            state.mnx1pool.recycle(ref tmp0);
        }


        /*************************************************************************
        Condense only right-hand-side using already condensed left hand side.

          -- ALGLIB --
             Copyright 07.05.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void condenseleastsquaresrhs(gipm3state state,
            gipm3vars current,
            gipm3rhs rhs,
            double currentmu,
            double dualerrwgt,
            gipm3condensedleastsquaressystem c,
            alglib.xparams _params)
        {
            int n = 0;
            int mtotal = 0;
            double[] tmp0 = new double[0];
            double[] tmp1 = new double[0];

            n = state.n;
            mtotal = state.meq+state.mi+state.mh+state.mxx;
            alglib.ap.assert(state.mxx==0, "GIPM3: 708201 failed");
            state.mnx1pool.retrieve(ref tmp0);
            state.mnx1pool.retrieve(ref tmp1);
            
            //
            // Precomputed quantities
            //
            ablasf.rallocv(current.mi, ref c.cached1, _params);
            ablasf.rcopymulv(current.mi, 1/dualerrwgt, current.s, c.cached1, _params);
            ablasf.rmergemulv(current.mi, rhs.rzs, c.cached1, _params);
            ablasf.raddv(current.mi, -dualerrwgt, rhs.rps, c.cached1, _params);
            
            //
            // Initialize WX
            //
            ablasf.rallocv(n, ref c.wx, _params);
            ablasf.rcopymulv(n, -1.0, rhs.rpx, c.wx, _params);
            
            //
            //                 [ -mu/Vscl*Rze                                    ]
            // Initialize WY = [ -mu/Vscl*Rzi - S/Vscl*Rzs + REGsm*REGs3*Cached1 ]
            //                 [ -Ch/Vscl*Rzh                                    ]
            //
            ablasf.rsetallocv(mtotal, 0.0, ref c.wy, _params);
            if( current.meq>0 )
            {
                ablasf.rcopymulv(current.meq, -(currentmu/c.vscl), rhs.rze, c.wy, _params);
            }
            if( current.mi>0 )
            {
                ablasf.rcopymulv(current.mi, currentmu, rhs.rzi, tmp0, _params);
                ablasf.rmuladdv(current.mi, current.s, rhs.rzs, tmp0, _params);
                ablasf.rmulv(current.mi, -(1/c.vscl), tmp0, _params);
                ablasf.rcopyv(current.mi, c.cached1, tmp1, _params);
                ablasf.rmergemulv(current.mi, c.regs3, tmp1, _params);
                ablasf.rmuladdv(current.mi, c.regsm, tmp1, tmp0, _params);
                ablasf.rcopyvx(current.mi, tmp0, 0, c.wy, current.meq, _params);
            }
            if( current.mh>0 )
            {
                ablasf.rcopymulv(current.mh, -(1/c.vscl), rhs.rzh, tmp0, _params);
                ablasf.rmergemulv(current.mh, current.ch, tmp0, _params);
                ablasf.rcopyvx(current.mh, tmp0, 0, c.wy, current.meq+current.mi, _params);
            }
            
            //
            // Done, recycle temporaries
            //
            state.mnx1pool.recycle(ref tmp0);
            state.mnx1pool.recycle(ref tmp1);
        }


        /*************************************************************************
        Unpack reply to Request=1002 into a solution to the original primal-dual system.
        Returns maximum over step components;

        Delta must be properly allocated GIPMVars; however, initial values of
        its variables are ignored.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void unpacksolution(gipm3state state,
            gipm3vars current,
            double currentmu,
            double[] currentdiag,
            gipm3rhs rhs,
            gipm3condensedsystem condensed,
            double[] replysol,
            gipm3vars delta,
            alglib.xparams _params)
        {
            int n = 0;
            int offs = 0;
            double[] tmp0 = new double[0];

            n = state.n;
            alglib.ap.assert(state.mxx==0, "GIPM3: 760225 failed");
            state.mnx1pool.retrieve(ref tmp0);
            varsalloc(delta, current.n, current.meq, current.mi, current.mh, _params);
            
            //
            // Extract what is immediately available: dX, dZe, dZi, dZh
            //
            ablasf.rcopyvx(n, replysol, 0, delta.x, 0, _params);
            offs = n;
            if( current.meq>0 )
            {
                ablasf.rcopyvx(current.meq, replysol, offs, delta.ze, 0, _params);
                ablasf.rmulv(current.meq, -1.0, delta.ze, _params);
                offs = offs+current.meq;
            }
            if( current.mi>0 )
            {
                ablasf.rcopyvx(current.mi, replysol, offs, delta.zi, 0, _params);
                ablasf.rmulv(current.mi, -1.0, delta.zi, _params);
                offs = offs+current.mi;
            }
            if( current.mh>0 )
            {
                ablasf.rcopyvx(current.mh, replysol, offs, delta.zh, 0, _params);
                ablasf.rmulv(current.mh, -1.0, delta.zh, _params);
                offs = offs+current.mh;
            }
            
            //
            // Compute dS and dZs
            //
            if( current.mi>0 )
            {
                
                //
                // dZs = dZi-Rps
                // dS = Rzs/Zs + (S/Zs)*Rps - (S/Zs)*dZi
                //
                ablasf.rcopyv(current.mi, delta.zi, delta.zs, _params);
                ablasf.raddv(current.mi, -1, rhs.rps, delta.zs, _params);
                ablasf.rcopyv(current.mi, condensed.cached0, delta.s, _params);
                ablasf.rcopyv(current.mi, current.s, tmp0, _params);
                ablasf.rmergedivv(current.mi, current.zs, tmp0, _params);
                ablasf.rnegmuladdv(current.mi, tmp0, delta.zi, delta.s, _params);
            }
            
            //
            // Done, recycle temporaries
            //
            state.mnx1pool.recycle(ref tmp0);
        }


        /*************************************************************************
        Unpacks reply to least squares solve request into a solution to the
        least squares subproblem. Returns maximum over step components;

        Delta must be properly allocated GIPMVars; however, initial values of
        its variables are ignored.

          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void unpacksolutionls(gipm3state state,
            gipm3vars current,
            double currentmu,
            gipm3rhs rhs,
            gipm3condensedleastsquaressystem condensed,
            double dualerrwgt,
            double[] replysol,
            gipm3vars delta,
            alglib.xparams _params)
        {
            int n = 0;

            n = state.n;
            alglib.ap.assert(state.mxx==0, "GIPM3: 760225 failed");
            varsalloc(delta, current.n, current.meq, current.mi, current.mh, _params);
            ablasf.rsetv(n, 0.0, delta.x, _params);
            ablasf.rsetv(current.mi, 0.0, delta.s, _params);
            ablasf.rcopyvx(current.meq, replysol, n, delta.ze, 0, _params);
            ablasf.rcopyvx(current.mi, replysol, n+current.meq, delta.zi, 0, _params);
            ablasf.rcopyvx(current.mh, replysol, n+current.meq+current.mi, delta.zh, 0, _params);
            ablasf.rcopyv(current.mi, condensed.cached1, delta.zs, _params);
            ablasf.raddv(current.mi, dualerrwgt, delta.zi, delta.zs, _params);
            ablasf.rmergemulv(current.mi, condensed.regs3, delta.zs, _params);
        }


        /*************************************************************************
        Merit function

        The formula is from 'PRIMAL-DUAL INTERIOR METHODS FOR NONCONVEX NONLINEAR
        PROGRAMMING' by ANDERS FORSGREN AND PHILIP E. GILL, (3.1).
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunction(gipm3state state,
            gipm3vars current,
            double currentmu,
            alglib.xparams _params)
        {
            double result = 0;
            int n = 0;
            int i = 0;
            double barrierf = 0;
            double penaltyf = 0;
            double v = 0;

            n = state.n;
            alglib.ap.assert(current.hasfunctions, "GIPM3: 842952 failed");
            result = 0;
            barrierf = 0;
            penaltyf = 0;
            
            //
            // Compute f+mu*pg'*x
            //
            result = result+current.fi[0]+currentmu*ablasf.rdotv(n, state.pg, current.x, _params);
            
            //
            // Equality constraints
            //
            for(i=0; i<=state.meq-1; i++)
            {
                v = current.ce[i];
                penaltyf = penaltyf+v*v;
            }
            
            //
            // Soft inequality constraints
            //
            for(i=0; i<=state.mi-1; i++)
            {
                
                //
                // Penalty for the equality constraint
                //
                v = current.ci[i]-current.s[i];
                penaltyf = penaltyf+v*v;
                
                //
                // Barrier term for the slack variable
                //
                v = current.s[i];
                barrierf = barrierf-Math.Log(v);
            }
            
            //
            // Hard inequality constraints
            //
            for(i=0; i<=state.mh-1; i++)
            {
                v = current.ch[i];
                barrierf = barrierf-Math.Log(v);
            }
            
            //
            // Done
            //
            result = result+barrierf*currentmu+penaltyf/(2*currentmu);
            return result;
        }


        /*************************************************************************
        Directional first derivative of the merit function.

        Uses:
        * current point
        * step direction (delta)
        * current Mu and primal multipliers vector
        * product J*Delta.X

        The first directional derivative is computed accurately (assuming that J*dx
        and J'*dy are computed accurately). The second directional derivative is
        computed approximately, because merit function Hessian has additional terms
        that are not present in the model Hessian.

        The formula is from 'PRIMAL-DUAL INTERIOR METHODS FOR NONCONVEX NONLINEAR
        PROGRAMMING' by ANDERS FORSGREN AND PHILIP E. GILL, (3.1), (3.2a) and (3.2b).
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void meritfunctiondg1(gipm3state state,
            gipm3vars current,
            gipm3vars delta,
            gipm3primalmult primalmult,
            double[] jdx,
            double currentmu,
            ref double df,
            alglib.xparams _params)
        {
            int offs = 0;
            double[] tmp0 = new double[0];

            df = 0;

            alglib.ap.assert(state.mxx==0, "GIPM3: 842940 failed");
            alglib.ap.assert(current.hasfunctions, "GIPM3: 842952 failed");
            state.mnx1pool.retrieve(ref tmp0);
            df = 0;
            offs = 0;
            
            //
            // Objective + linear penalty
            //
            df = df+ablasf.rdotv(current.n, current.g, delta.x, _params)+currentmu*ablasf.rdotv(current.n, state.pg, delta.x, _params);
            
            //
            // Equality constraints
            //
            if( current.meq>0 )
            {
                ablasf.rcopyvx(current.meq, jdx, offs, tmp0, 0, _params);
                df = df-ablasf.rdotv(current.meq, primalmult.zeprim, tmp0, _params);
            }
            offs = offs+current.meq;
            
            //
            // Soft inequality constraints
            //
            if( current.mi>0 )
            {
                
                //
                // equality constraint ci(x)-s=0: first derivative
                //
                ablasf.rcopyvx(current.mi, jdx, offs, tmp0, 0, _params);
                ablasf.raddv(current.mi, -1.0, delta.s, tmp0, _params);
                df = df-ablasf.rdotv(current.mi, primalmult.ziprim, tmp0, _params);
                
                //
                // inequality constraint s>0: first derivative
                //
                df = df-ablasf.rdotv(current.mi, primalmult.zsprim, delta.s, _params);
            }
            offs = offs+current.mi;
            
            //
            // Hard inequality constraints
            //
            if( current.mh>0 )
            {
                
                //
                // inequality constraint ch(x)>0: first derivative
                //
                ablasf.rcopyvx(current.mh, jdx, offs, tmp0, 0, _params);
                df = df-ablasf.rdotv(current.mh, primalmult.zhprim, tmp0, _params);
            }
            offs = offs+current.mh;
            
            //
            // Recycle temporaries
            //
            state.mnx1pool.recycle(ref tmp0);
        }


        /*************************************************************************
        Merit function: component corresponding to objective
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctionobj(gipm3state state,
            gipm3vars current,
            double currentmu,
            alglib.xparams _params)
        {
            double result = 0;

            result = current.fi[0]+currentmu*ablasf.rdotv(state.n, state.pg, current.x, _params);
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to equalities
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctioneq(gipm3state state,
            gipm3vars current,
            double currentmu,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double penaltyf = 0;
            double v = 0;

            penaltyf = 0;
            for(i=0; i<=state.meq-1; i++)
            {
                v = current.ce[i];
                penaltyf = penaltyf+v*v;
            }
            result = penaltyf/(2*currentmu);
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to equalities, predict value at
        Current+Stp*Delta, having J*Delta.X
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctioneqpredict(gipm3state state,
            gipm3vars current,
            double currentmu,
            gipm3vars delta,
            double[] jdeltax,
            double stp,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double penaltyf = 0;
            double v = 0;

            penaltyf = 0;
            for(i=0; i<=state.meq-1; i++)
            {
                v = current.ce[i]+stp*jdeltax[i];
                penaltyf = penaltyf+v*v;
            }
            result = penaltyf/(2*currentmu);
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to equalities, predict value at
        Current+Delta using quartic model (quadratic model squared),
        having J*Delta.X at Current, 0<Stp<1, and values at Probe=Current+Stp*Delta.
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctioneqpredictq1(gipm3state state,
            gipm3vars current,
            double currentmu,
            gipm3vars delta,
            double[] jdeltax,
            double stp,
            gipm3vars probe,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double penaltyf = 0;
            double a = 0;
            double b = 0;
            double c = 0;
            double v = 0;

            penaltyf = 0;
            for(i=0; i<=state.meq-1; i++)
            {
                
                //
                // Build quadratic model of Ce = c + b*stp + a*stp^2
                //
                c = current.ce[i];
                b = jdeltax[i];
                a = (probe.ce[i]-current.ce[i]-stp*b)/math.sqr(stp);
                v = c+b+a;
                penaltyf = penaltyf+v*v;
            }
            result = penaltyf/(2*currentmu);
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to soft inequalities reformulated
        as equalities
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctionsoft(gipm3state state,
            gipm3vars current,
            double currentmu,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double penaltyf = 0;
            double v = 0;

            penaltyf = 0;
            for(i=0; i<=state.mi-1; i++)
            {
                v = current.ci[i]-current.s[i];
                penaltyf = penaltyf+v*v;
            }
            result = penaltyf/(2*currentmu);
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to soft inequalities reformulated
        as equalities; predict value at Current+Delta, having J*Delta.X
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctionsoftpredict(gipm3state state,
            gipm3vars current,
            double currentmu,
            gipm3vars delta,
            double[] jdeltax,
            double stp,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double penaltyf = 0;
            double v = 0;

            penaltyf = 0;
            for(i=0; i<=state.mi-1; i++)
            {
                v = current.ci[i]+stp*jdeltax[state.meq+i]-(current.s[i]+stp*delta.s[i]);
                penaltyf = penaltyf+v*v;
            }
            result = penaltyf/(2*currentmu);
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to soft inequalities reformulated
        as equalities; predict value at
        Current+Delta using quartic model (quadratic model squared),
        having J*Delta.X at Current, 0<Stp<1, and values at Probe=Current+Stp*Delta.
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctionsoftpredictq1(gipm3state state,
            gipm3vars current,
            double currentmu,
            gipm3vars delta,
            double[] jdeltax,
            double stp,
            gipm3vars probe,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double penaltyf = 0;
            double a = 0;
            double b = 0;
            double c = 0;
            double v = 0;

            penaltyf = 0;
            for(i=0; i<=state.mi-1; i++)
            {
                
                //
                // Build quadratic model of f = c + b*stp + a*stp^2
                //
                c = current.ci[i]-current.s[i];
                b = jdeltax[state.meq+i]-delta.s[i];
                a = (probe.ci[i]-probe.s[i]-c-stp*b)/math.sqr(stp);
                v = c+b+a;
                penaltyf = penaltyf+v*v;
            }
            result = penaltyf/(2*currentmu);
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to slacks Si
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctionslk(gipm3state state,
            gipm3vars current,
            double currentmu,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double barrierf = 0;
            double v = 0;

            barrierf = 0;
            for(i=0; i<=state.mi-1; i++)
            {
                v = current.s[i];
                barrierf = barrierf-Math.Log(v);
            }
            result = barrierf*currentmu;
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to slacks Si
        predict value at Current+Delta
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctionslkpredict(gipm3state state,
            gipm3vars current,
            double currentmu,
            gipm3vars delta,
            double stp,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double barrierf = 0;

            barrierf = 0;
            for(i=0; i<=state.mi-1; i++)
            {
                barrierf = barrierf-(Math.Log(current.s[i])+stp*delta.s[i]/current.s[i]);
            }
            result = barrierf*currentmu;
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to hard inequalities
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctionhard(gipm3state state,
            gipm3vars current,
            double currentmu,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double barrierf = 0;
            double v = 0;

            barrierf = 0;
            for(i=0; i<=state.mh-1; i++)
            {
                v = current.ch[i];
                barrierf = barrierf-Math.Log(v);
            }
            result = barrierf*currentmu;
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to hard inequalities
        predict value at Current+Delta, having J*Delta.X
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctionhardpredict(gipm3state state,
            gipm3vars current,
            double currentmu,
            gipm3vars delta,
            double[] jdeltax,
            double stp,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double barrierf = 0;
            double v = 0;

            barrierf = 0;
            for(i=0; i<=state.mh-1; i++)
            {
                v = current.ch[i];
                barrierf = barrierf-(Math.Log(v)+1/v*(stp*jdeltax[state.meq+state.mi+i]));
            }
            result = barrierf*currentmu;
            return result;
        }


        /*************************************************************************
        Merit function: component corresponding to hard inequalities
        predict value at Current+Delta using log-quadratic model
        having 0<Stp<1, and values at Probe=Current+Stp*Delta.
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctionhardpredictq1(gipm3state state,
            gipm3vars current,
            double currentmu,
            gipm3vars delta,
            double[] jdeltax,
            double stp,
            gipm3vars probe,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double barrierf = 0;
            double a = 0;
            double b = 0;
            double c = 0;
            double v = 0;

            barrierf = 0;
            for(i=0; i<=state.mh-1; i++)
            {
                
                //
                // Build quadratic model of Ch = f = c + stp*b + stp^2*a
                //
                c = current.ch[i];
                b = jdeltax[state.meq+state.mi+i];
                a = (probe.ch[i]-c-stp*b)/math.sqr(stp);
                v = c+b+a;
                barrierf = barrierf-Math.Log(Math.Max(v, math.machineepsilon*math.machineepsilon));
            }
            result = barrierf*currentmu;
            return result;
        }


        /*************************************************************************
        Directional first derivative of the merit function:

        component corresponding to the objective
            
          -- ALGLIB --
             Copyright 11.05.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double meritfunctiondg1obj(gipm3state state,
            gipm3vars current,
            gipm3vars delta,
            gipm3primalmult primalmult,
            double[] jdx,
            double currentmu,
            alglib.xparams _params)
        {
            double result = 0;

            result = ablasf.rdotv(current.n, current.g, delta.x, _params)+currentmu*ablasf.rdotv(current.n, state.pg, delta.x, _params);
            return result;
        }


