        /*************************************************************************
        Update error reports
        *************************************************************************/
        private static void updateerrorreports(gipm3state state,
            alglib.xparams _params)
        {
            int i = 0;

            state.repsclerr = 0;
            for(i=0; i<=state.meq-1; i++)
            {
                state.repsclerr = Math.Max(state.repsclerr, Math.Abs(state.current.ce[i]));
            }
            for(i=0; i<=state.mi-1; i++)
            {
                state.repsclerr = Math.Max(state.repsclerr, -state.current.ci[i]);
            }
            for(i=0; i<=state.mh-1; i++)
            {
                state.repsclerr = Math.Max(state.repsclerr, -state.current.ch[i]);
            }
        }


        /*************************************************************************
        Send X and Lagrange coefficients.

        If ZeroLag is True, Lagrange coefficients stored in VFJ are ignored and
        zeros are sent (this option is used at the very first objective evaluation
        when no Lagrange coeffs are known)
        *************************************************************************/
        private static void sendxlag(gipm3state state,
            gipm3vars vfj,
            bool zerolag,
            alglib.xparams _params)
        {
            ablasf.rcopyv(vfj.n, vfj.x, state.querydata, _params);
            if( !zerolag )
            {
                ablasf.rcopyvx(vfj.meq, vfj.ze, 0, state.querydata, vfj.n, _params);
                ablasf.rcopyvx(vfj.mi, vfj.zi, 0, state.querydata, vfj.n+vfj.meq, _params);
                ablasf.rcopyvx(vfj.mh, vfj.zh, 0, state.querydata, vfj.n+vfj.meq+vfj.mi, _params);
                ablasf.rmulvx(vfj.meq+vfj.mi+vfj.mh, -1.0, state.querydata, vfj.n, _params);
            }
            else
            {
                ablasf.rsetvx(vfj.meq+vfj.mi+vfj.mh, 0.0, state.querydata, vfj.n, _params);
            }
        }


        /*************************************************************************
        Send Lagrangian
        *************************************************************************/
        private static void sendqnupdate(gipm3state state,
            gipm3vars current,
            double[] currentlag,
            gipm3vars cand,
            double[] candlag,
            alglib.xparams _params)
        {
            int n = 0;

            n = state.n;
            ablasf.rallocv(4*n, ref state.querydata, _params);
            ablasf.rcopyvx(n, current.x, 0, state.querydata, 0, _params);
            ablasf.rcopyvx(n, currentlag, 0, state.querydata, n, _params);
            ablasf.rcopyvx(n, cand.x, 0, state.querydata, 2*n, _params);
            ablasf.rcopyvx(n, candlag, 0, state.querydata, 3*n, _params);
        }


        /*************************************************************************
        Retrieves F-vector and scaled gradient of the objective, copies them to VFJ,
        applying reordering permutation if needed.

        Returns True on success, False on failure (when F or J are not finite numbers).
        *************************************************************************/
        private static bool retrievefij(double[] fi,
            double[] g,
            double[] rhse,
            double[] rhsi,
            double[] rhsh,
            gipm3vars vfj,
            alglib.xparams _params)
        {
            bool result = new bool();
            int mtotal = 0;

            alglib.ap.assert(vfj.mxx==0, "GIPM3: 738009 failed");
            mtotal = vfj.meq+vfj.mi+vfj.mh;
            
            //
            // First, copy raw values and perform integrity checks
            //
            ablasf.rcopyallocv(1+mtotal, fi, ref vfj.fi, _params);
            result = math.isfinite(ablasf.rdotv2(1+mtotal, vfj.fi, _params)+ablasf.rdotv2(vfj.n, g, _params));
            vfj.hasfunctions = true;
            
            //
            // Copy F/G
            //
            vfj.f = fi[0];
            ablasf.rcopyallocv(vfj.n, g, ref vfj.g, _params);
            
            //
            // Copy Ce/Ci/Ch
            //
            ablasf.rallocv(vfj.meq, ref vfj.ce, _params);
            ablasf.rallocv(vfj.mi, ref vfj.ci, _params);
            ablasf.rallocv(vfj.mh, ref vfj.ch, _params);
            ablasf.rcopyvx(vfj.meq, fi, 1, vfj.ce, 0, _params);
            ablasf.rcopyvx(vfj.mi, fi, 1+vfj.meq, vfj.ci, 0, _params);
            ablasf.rcopyvx(vfj.mh, fi, 1+vfj.meq+vfj.mi, vfj.ch, 0, _params);
            ablasf.raddv(vfj.meq, -1.0, rhse, vfj.ce, _params);
            ablasf.raddv(vfj.mi, -1.0, rhsi, vfj.ci, _params);
            ablasf.raddv(vfj.mh, -1.0, rhsh, vfj.ch, _params);
            return result;
        }


        /*************************************************************************
        Initialize memory for nonmonotonic merit function optimization

          -- ALGLIB --
             Copyright 25.01.2026 by Bochkanov Sergey
        *************************************************************************/
        private static void nonmonotonicinit(gipm3state state,
            int memlen,
            alglib.xparams _params)
        {
            alglib.ap.assert(memlen>=0, "GIPM3: integrity check 267047 failed");
            state.nonmonotonicmaxstored = memlen+1;
            state.nonmonotoniccurstored = 0;
            state.nonmonotonicpos = 0;
            ablasf.rallocv(state.nonmonotonicmaxstored, ref state.nonmonotonicmerit, _params);
        }


        /*************************************************************************
        Push new value to the nonmonotonic memory

          -- ALGLIB --
             Copyright 25.01.2026 by Bochkanov Sergey
        *************************************************************************/
        private static void nonmonotonicpush(gipm3state state,
            double meritv,
            alglib.xparams _params)
        {
            state.nonmonotonicmerit[state.nonmonotonicpos] = meritv;
            state.nonmonotonicpos = (state.nonmonotonicpos+1)%state.nonmonotonicmaxstored;
            state.nonmonotoniccurstored = Math.Min(state.nonmonotoniccurstored+1, state.nonmonotonicmaxstored);
        }


        /*************************************************************************
        Push new value to the nonmonotonic memory ONLY if the memory is empty (on
        the very beginning), used to push initial value at the origin

          -- ALGLIB --
             Copyright 25.01.2026 by Bochkanov Sergey
        *************************************************************************/
        private static void nonmonotonicpushifempty(gipm3state state,
            double meritv,
            alglib.xparams _params)
        {
            if( state.nonmonotoniccurstored==0 )
            {
                nonmonotonicpush(state, meritv, _params);
            }
        }


        /*************************************************************************
        Returns nonmonotonic correction that should be added to MeritV (value at
        the initial point for the current step)

          -- ALGLIB --
             Copyright 25.01.2026 by Bochkanov Sergey
        *************************************************************************/
        private static double nonmonotonicgetcorr(gipm3state state,
            double meritv,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            double mx = 0;

            result = 0;
            if( state.nonmonotoniccurstored==0 )
            {
                return result;
            }
            mx = state.nonmonotonicmerit[0];
            for(i=1; i<=state.nonmonotoniccurstored-1; i++)
            {
                mx = Math.Max(mx, state.nonmonotonicmerit[i]);
            }
            result = Math.Max(mx-meritv, 0.0);
            return result;
        }


        /*************************************************************************
        Rescale model

          -- ALGLIB --
             Copyright 25.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void rescalemodel(gipm3state state,
            double[] rescaleby,
            alglib.xparams _params)
        {
            double[] tmp = new double[0];

            state.mnx1pool.retrieve(ref tmp);
            alglib.ap.assert((double)(ablasf.rmaxabsv(state.n, state.pg, _params))==(double)(0), "GIPM3: 366028 failed");
            
            //
            // Clear nonmonotonic memory
            //
            nonmonotonicinit(state, nonmonotonicmemlen, _params);
            
            //
            // Rescale f-sized quantities
            //
            ablasf.rcopyvx(state.meq, rescaleby, 1, tmp, 0, _params);
            ablasf.rmergemulv(state.meq, tmp, state.rhseq, _params);
            ablasf.rcopyvx(state.mi, rescaleby, 1+state.meq, tmp, 0, _params);
            ablasf.rmergemulv(state.mi, tmp, state.rhsi, _params);
            ablasf.rcopyvx(state.mh, rescaleby, 1+state.meq+state.mi, tmp, 0, _params);
            ablasf.rmergemulv(state.mh, tmp, state.rhsh, _params);
            
            //
            // Rescale variables
            //
            varsrescale(state.current, rescaleby, tmp, _params);
            varsrescale(state.best, rescaleby, tmp, _params);
            
            //
            // Done, recycle temporaries
            //
            state.mnx1pool.recycle(ref tmp);
        }


        /*************************************************************************
        Convert sparse matrix to a dense one
        *************************************************************************/
        private static void sparse2dense(sparse.sparsematrix s,
            ref double[,] d,
            alglib.xparams _params)
        {
            int i = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;

            alglib.ap.assert((s.matrixtype==1 && s.m>=1) && s.n>=1, "GIPM3: integrity check 5541 failed");
            ablasf.rsetallocm(s.m, s.n, 0.0, ref d, _params);
            for(i=0; i<=s.m-1; i++)
            {
                j0 = s.ridx[i];
                j1 = s.ridx[i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    d[i,s.idx[jj]] = s.vals[jj];
                }
            }
        }


    }
