        public const double mupromote = 10.0;
        public const int xbfgsmemlen = 8;
        public const double xbfgsmaxhess = 1.0E6;
        public const double maxrescale = 10.0;
        public const double minrescale = 0.1;
        public const double mindistforhard = 0.01;
        public const double maxscalerelativetoinitial = 100.0;


        /*************************************************************************
        Initialize GQPIPM structure.

        X0      -   initial point; must be:
                    * strictly feasible wrt non-equality box constraints
                    * non-strictly feasible wrt equality box constraints
                    * strictly feasible wrt conic constraints, if present
                    Failure to satisfy these properties will lead to an  exception
                    generated either during  initialization  or  during  the  very
                    first iteration.

          -- ALGLIB --
             Copyright 11.02.2025 by Bochkanov Sergey
        *************************************************************************/
        public static void nlpgipm3initbuf(double[] bndl,
            double[] bndu,
            double[] s,
            double[] x0,
            int n,
            optserv.nlpstoppingcriteria criteria,
            bool isdense,
            nlpgipm3state state,
            alglib.xparams _params)
        {
            int i = 0;
            double v = 0;
            double vmid = 0;
            double initshift = 0;

            alglib.ap.assert(!isdense, "NLPGIPM2: 225301");
            state.isdense = isdense;
            state.isconvex = false;
            state.nraw = n;
            state.nwrk = n;
            state.nnonlinear = n;
            state.mlc = 0;
            state.mnlc = 0;
            state.mxx = 0;
            state.primalbound = Double.PositiveInfinity;
            state.dualbound = Double.NegativeInfinity;
            state.eshasintmask = false;
            state.esdualbound = Double.NegativeInfinity;
            state.esprimbound = Double.PositiveInfinity;
            state.esminits = 0;
            state.estol = 1.0E-6;
            ablasf.bsetallocv(state.nraw, false, ref state.esintmask, _params);
            ablasf.bsetallocv(state.nraw, false, ref state.islinear, _params);
            ablasf.iallocv(state.nraw, ref state.idxnonlinear, _params);
            for(i=0; i<=state.nraw-1; i++)
            {
                state.idxnonlinear[i] = i;
            }
            state.qnmemlen = 0;
            state.dononlinearityreports = false;
            state.hasbc = false;
            state.hasfixedbc = false;
            state.hasnonfixedbc = false;
            ablasf.rcopyallocv(n, s, ref state.raws, _params);
            ablasf.rsetallocv(n, Double.NegativeInfinity, ref state.scaledbndl, _params);
            ablasf.rsetallocv(n, Double.PositiveInfinity, ref state.scaledbndu, _params);
            ablasf.rsetallocv(n, -Math.Sqrt(math.maxrealnumber), ref state.finitescaledbndl, _params);
            ablasf.rsetallocv(n, Math.Sqrt(math.maxrealnumber), ref state.finitescaledbndu, _params);
            ablasf.bsetallocv(n, false, ref state.isfixed, _params);
            ablasf.rallocv(n, ref state.scaledx0, _params);
            state.fixtol = Math.Sqrt(math.machineepsilon);
            initshift = gipm3.gipm3getinitprimdual(_params);
            state.cntfixed = 0;
            for(i=0; i<=n-1; i++)
            {
                state.scaledx0[i] = x0[i]/s[i];
                if( (math.isfinite(bndl[i]) && math.isfinite(bndu[i])) && (double)(bndu[i]-bndl[i])<(double)(state.fixtol*s[i]) )
                {
                    v = 0.5*(bndl[i]+bndu[i])/s[i];
                    state.scaledbndl[i] = v;
                    state.scaledbndu[i] = v;
                    state.scaledx0[i] = v;
                    state.finitescaledbndl[i] = v;
                    state.finitescaledbndu[i] = v;
                    state.hasbc = true;
                    state.hasfixedbc = true;
                    state.isfixed[i] = true;
                    state.cntfixed = state.cntfixed+1;
                    ablasf.igrowappendv(state.cntfixed, ref state.idxfixed, i, _params);
                    continue;
                }
                if( math.isfinite(bndl[i]) )
                {
                    state.scaledbndl[i] = bndl[i]/s[i];
                    state.finitescaledbndl[i] = state.scaledbndl[i];
                    state.hasbc = true;
                    state.hasnonfixedbc = true;
                }
                if( math.isfinite(bndu[i]) )
                {
                    state.scaledbndu[i] = bndu[i]/s[i];
                    state.finitescaledbndu[i] = state.scaledbndu[i];
                    state.hasbc = true;
                    state.hasnonfixedbc = true;
                }
                vmid = 0.5*(state.finitescaledbndl[i]+state.finitescaledbndu[i]);
                state.scaledx0[i] = Math.Max(Math.Min(state.finitescaledbndl[i]+initshift, vmid), state.scaledx0[i]);
                state.scaledx0[i] = Math.Min(Math.Max(state.finitescaledbndu[i]-initshift, vmid), state.scaledx0[i]);
            }
            state.maxits = optserv.critgetmaxits(criteria, _params);
            state.eps = optserv.critgetepswithdefault(criteria, 1.0E-7, _params);
            state.repterminationtype = 0;
            state.repiterationscount = 0;
            state.repbcerr = 0;
            state.repbcidx = -1;
            state.replcerr = 0;
            state.replcidx = -1;
            state.repnlcerr = 0;
            state.repnlcidx = -1;
            state.repsclerr = 0;
            state.repearlyerrorestimate = 0;
            ablasf.rcopyallocv(n, x0, ref state.xs, _params);
            ablasf.rsetallocv(n, 1.0, ref state.repnonlinearityreport, _params);
            state.dolaconictrace = ap.istraceenabled("NLPIPM.LACONIC", _params);
            state.dotrace = ap.istraceenabled("NLPIPM", _params) && !state.dolaconictrace;
            state.doprobeonfailure = state.dotrace && ap.istraceenabled("NLPIPM.PROBINGONFAILURE", _params);
            state.doanalyzestep = state.dotrace && ap.istraceenabled("NLPIPM.ANALYZESTEP", _params);
            state.dotracedetailedmodel = state.dotrace && ap.istraceenabled("NLPIPM.DETAILEDMODEL", _params);
            state.userterminationneeded = false;
            state.rstate.ia = new int[1+1];
            state.rstate.ra = new double[2+1];
            state.rstate.stage = -1;
            state.rstate.clear_handler();
        }


        /*************************************************************************
        Set linear constraints

        INPUT PARAMETERS:
            State               -   instance initialized with one of the initialization
                                    functions
            SparseA             -   sparse constraint matrix, CRS format
            CL, CU              -   lower and upper bounds for constraints
                                    -INF <= CL[I] <= CU[I] <= +INF.
            M                   -   constraints count
            NormalizeA          -   if True, the solver will normalize A so that its
                                    rows all have unit norms. Otherwise, the matrix
                                    will be used 'as is'.

        The constraint matrix is NOT scaled according to variable scales; the
        solver will internally rescale it.

          -- ALGLIB --
             Copyright 25.02.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlpgipm3setlinearconstraints(nlpgipm3state state,
            sparse.sparsematrix sparsea,
            double[] cl,
            double[] cu,
            int[] lcsrcidx,
            int m,
            bool normalizea,
            alglib.xparams _params)
        {
            int nraw = 0;
            int i = 0;

            nraw = state.nraw;
            alglib.ap.assert(m>=0, "NLPGIPM3SetLinearConstraints: M<0");
            alglib.ap.assert(m==0 || ((sparsea.matrixtype==1 && sparsea.m==m) && sparsea.n==nraw), "NLPGIPM3SetLinearConstraints: constraint matrix has incorrect size");
            alglib.ap.assert(alglib.ap.len(cl)>=m, "NLPGIPM3SetLinearConstraints: CL is too short!");
            alglib.ap.assert(alglib.ap.len(cu)>=m, "NLPGIPM3SetLinearConstraints: CU is too short!");
            state.mlc = m;
            if( m>0 )
            {
                sparse.sparsecopytocrsbuf(sparsea, state.sparselc, _params);
                ablasf.rallocv(m, ref state.lcbndl, _params);
                ablasf.rallocv(m, ref state.lcbndu, _params);
                for(i=0; i<=m-1; i++)
                {
                    alglib.ap.assert(math.isfinite(cl[i]) || Double.IsNegativeInfinity(cl[i]), "NLPGIPM3SetLinearConstraints: CL is not finite number or -INF");
                    alglib.ap.assert(math.isfinite(cu[i]) || Double.IsPositiveInfinity(cu[i]), "NLPGIPM3SetLinearConstraints: CU is not finite number or +INF");
                    state.lcbndl[i] = cl[i];
                    state.lcbndu[i] = cu[i];
                }
                ablasf.icopyallocv(m, lcsrcidx, ref state.lcsrcidx, _params);
                ablasf.rsetallocv(nraw, 0.0, ref state.tmp0, _params);
                lpqpserv.scaleshiftsparselcinplace(state.raws, state.tmp0, nraw, state.sparselc, m, state.lcbndl, state.lcbndu, _params);
                if( normalizea )
                {
                    lpqpserv.normalizesparselcinplace(state.sparselc, m, state.lcbndl, state.lcbndu, nraw, true, ref state.lcscales, true, _params);
                }
                else
                {
                    ablasf.rsetallocv(m, 1.0, ref state.lcscales, _params);
                }
            }
        }


        /*************************************************************************
        Set nonlinear constraints

        INPUT PARAMETERS:
            State               -   instance initialized with one of the initialization
                                    functions
            NL, NU              -   lower and upper bounds for constraints
                                    -INF <= NL[I] <= NU[I] <= +INF.
            IsHard              -   hardness flag; hard constraints are always satisfied
                                    exactly; they can have at most one bound
                                    present, initial point must be feasible wrt such constraints
            NNLC                -   constraints count

          -- ALGLIB --
             Copyright 25.02.2025 by Bochkanov Sergey
        *************************************************************************/
        public static void nlpgipm3setnonlinearconstraints(nlpgipm3state state,
            double[] nl,
            double[] nu,
            bool[] ishard,
            int nnlc,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(nnlc>=0, "NLPGIPM3SetNonlinearConstraints: NNLC<0");
            alglib.ap.assert(alglib.ap.len(nl)>=nnlc, "NLPGIPM3SetNonlinearConstraints: CL is too short!");
            alglib.ap.assert(alglib.ap.len(nu)>=nnlc, "NLPGIPM3SetNonlinearConstraints: CU is too short!");
            state.mnlc = nnlc;
            if( nnlc>0 )
            {
                ablasf.rallocv(nnlc, ref state.rawnl, _params);
                ablasf.rallocv(nnlc, ref state.rawnu, _params);
                ablasf.ballocv(nnlc, ref state.nlcishard, _params);
                for(i=0; i<=nnlc-1; i++)
                {
                    alglib.ap.assert(math.isfinite(nl[i]) || Double.IsNegativeInfinity(nl[i]), "NLPGIPM3SetNonlinearConstraints: NL is not finite number or -INF");
                    alglib.ap.assert(math.isfinite(nu[i]) || Double.IsPositiveInfinity(nu[i]), "NLPGIPM3SetNonlinearConstraints: NU is not finite number or +INF");
                    state.rawnl[i] = nl[i];
                    state.rawnu[i] = nu[i];
                    state.nlcishard[i] = ishard[i];
                }
            }
        }


        /*************************************************************************
        This function allows to set optional primal bound for  the  algorithm.  If
        a solver determines that it converges to a value  well  above  the  primal
        bound, it will terminate prematurely with the Rep.TerminationType=6

        Presently, only nonlinear IPM method supports primal bounds.

        INPUT PARAMETERS:
            State   -   structure
            Bnd     -   primal bound, finite number or +INF (if no bound)

          -- ALGLIB --
             Copyright 02.02.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlpgipm3setprimalbound(nlpgipm3state state,
            double bnd,
            alglib.xparams _params)
        {
            alglib.ap.assert(math.isfinite(bnd) || Double.IsPositiveInfinity(bnd), "NLPGIPM3SetPrimalBound: Bnd is not finite or +INF");
            state.primalbound = bnd;
        }


        /*************************************************************************
        This function activates nonlinearity reports for the  NLPIPM  solver:  the
        solver will report, in State.RepNonlinearityReport[], a lower bound on the
        diagonal of the Hessian after applying some kind of variable  scaling.  By
        default it is filled by zeros.

        Specific numeric values do not matter that much, what matters  is  whether
        they are significantly different from zero or not. It helps MINLP subsolvers
        to decide which variables in a tree became linear after fixing some of them
        in the previous round.

        INPUT PARAMETERS:
            State   -       structure
            DoReports-      True or False

          -- ALGLIB --
             Copyright 02.04.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlpgipm3setnonlinearityreports(nlpgipm3state state,
            bool doreports,
            alglib.xparams _params)
        {
            state.dononlinearityreports = doreports;
        }


        /*************************************************************************
        This function allows to set optional dual bound for the  algorithm.

        INPUT PARAMETERS:
            State   -   structure
            Bnd     -   dual bound, finite number or -INF (if no bound)

          -- ALGLIB --
             Copyright 02.02.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlpgipm3setdualbound(nlpgipm3state state,
            double bnd,
            alglib.xparams _params)
        {
            alglib.ap.assert(math.isfinite(bnd) || Double.IsNegativeInfinity(bnd), "NLPGIPM3SetDualBound: Bnd is not finite or +INF");
            state.dualbound = bnd;
        }


        /*************************************************************************
        This function allows to set optional early stopping using integrality mask
        for integer variables and early stopping criteria.

        INPUT PARAMETERS:
            State   -   structure previously allocated with MinNLCCreate call.
            intMask -   array[N], if I-th element is True, then I-th variable
                        is integer

          -- ALGLIB --
             Copyright 02.02.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlpgipm3setearlystopping(nlpgipm3state state,
            bool[] intmask,
            double dualbound,
            double primbound,
            int minearlyits,
            double etol,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(alglib.ap.len(intmask)>=state.nwrk, "NLPGIPM3SetEarlyStopping: Length(intMask)<N");
            ablasf.bcopyv(state.nwrk, intmask, state.esintmask, _params);
            state.eshasintmask = false;
            for(i=0; i<=state.nwrk-1; i++)
            {
                state.eshasintmask = state.eshasintmask || intmask[i];
            }
            state.esdualbound = dualbound;
            state.esprimbound = primbound;
            state.esminits = minearlyits;
            state.estol = etol;
        }


        /*************************************************************************
        This function allows to set optional linearity mask for variables.

        The linear variable can appear in objective and all constraint types (box,
        linear and nonlinear), but the problem must be linear with respect to this
        variable.

        Knowning that some variables are linear  allows  the  solver  to  do avoid
        modelling nonlinearities associated with  these  variables  (corresponding
        rows/cols of a quasi-Newton Hessian will be zero), and, potentially, to do
        some otherwise unavailable reductions, decreasing linear algebra  overhead
        and improving convergence.

        By default all variables are nonlinear.

        INPUT PARAMETERS:
            State   -   state
            linMask -   array[N], if I-th element is True, then I-th variable
                        is linear

          -- ALGLIB --
             Copyright 02.02.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlpgipm3setlinearmask(nlpgipm3state state,
            bool[] linmask,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(alglib.ap.len(linmask)>=state.nwrk, "NLPGIPM3SetLinearMask: Length(linMask)<N");
            ablasf.bcopyv(state.nwrk, linmask, state.islinear, _params);
            state.nnonlinear = 0;
            for(i=0; i<=state.nwrk-1; i++)
            {
                if( !state.islinear[i] )
                {
                    state.nnonlinear = state.nnonlinear+1;
                    ablasf.igrowappendv(state.nnonlinear, ref state.idxnonlinear, i, _params);
                }
            }
        }


        /*************************************************************************
        This function allows to set memory length for LM-SR1 update

        INPUT PARAMETERS:
            State   -   structure
            MemLen  -   * 0 means default value which may change in future versions;
                          presently it is 8.
                        * 8 is a good default value for moderately nonlinear tasks
                        * 32 is a good value for problems with more nonlinear
                          objective/constraints
                        * values larger than the variables count N  are  possible;
                          these will be silently truncated to N.

          -- ALGLIB --
             Copyright 02.02.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlpgipm3setmemlen(nlpgipm3state state,
            int memlen,
            alglib.xparams _params)
        {
            alglib.ap.assert(memlen>=0, "NLPGIPM3SetMemLen: MemLen<0");
            state.qnmemlen = memlen;
        }


        /*************************************************************************
        This function performs actual processing for GIPM3 algorithm.

          -- ALGLIB --
             Copyright 01.02.2025 by Bochkanov Sergey
        *************************************************************************/
        public static bool nlpgipm3iteration(nlpgipm3state state,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int offs = 0;
            double v = 0;
            double v1 = 0;
            double vv = 0;

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rstate.stage>=0 )
            {
                i = state.rstate.ia[0];
                offs = state.rstate.ia[1];
                v = state.rstate.ra[0];
                v1 = state.rstate.ra[1];
                vv = state.rstate.ra[2];
            }
            else
            {
                i = 359;
                offs = -58;
                v = -919.0;
                v1 = -909.0;
                vv = 81.0;
            }
            if( state.rstate.stage==0 )
            {
                goto lbl_0;
            }
            if( state.rstate.stage==1 )
            {
                goto lbl_1;
            }
            if( state.rstate.stage==2 )
            {
                goto lbl_2;
            }
            if( state.rstate.stage==3 )
            {
                goto lbl_3;
            }
            if( state.rstate.stage==4 )
            {
                goto lbl_4;
            }
            
            //
            // Routine body
            //
            state.needfisj = false;
            state.xupdated = false;
            ablasf.rallocv(state.nraw, ref state.x, _params);
            alglib.ap.assert(state.mxx==0, "NLPGIPM: integrity check 377132 failed");
            ablasf.rallocv(1+state.mnlc+state.mlc, ref state.rawreplyfi, _params);
            ablasf.rallocv(1+state.mnlc+state.mlc, ref state.rawreplyfs, _params);
            state.hasinitialpointinrawreply = false;
