                alglib.ap.trace(System.String.Format("* analyze:      {0,10:F1} ms\n", apserv.stimergetms(state.timeranalyze, _params)));
                alglib.ap.trace(System.String.Format("* factorize:    {0,10:F1} ms\n", apserv.stimergetms(state.timerfactorize, _params)));
                alglib.ap.trace(System.String.Format("* solve:        {0,10:F1} ms\n", apserv.stimergetms(state.timersolve, _params)));
                alglib.ap.trace(System.String.Format("* gemv:         {0,10:F1} ms\n", apserv.stimergetms(state.timermv, _params)));
                alglib.ap.trace(System.String.Format("* rescale:      {0,10:F1} ms\n", apserv.stimergetms(state.timerrescale, _params)));
            }
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rstate.ia[0] = i;
            state.rstate.ia[1] = offs;
            state.rstate.ra[0] = v;
            state.rstate.ra[1] = v1;
            state.rstate.ra[2] = vv;
            return result;
        }


        /*************************************************************************
        Converts reply to internal formats used by GIPM3 solver, saves to the
        destination point ('last' or 'probing') given by a set of related arrays.

          -- ALGLIB --
             Copyright 07.11.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void loadreplyto(nlpgipm3state state,
            double[] xtoload,
            ref double[] dstx,
            ref double[] dstfi,
            sparse.sparsematrix dstsj,
            bool donotloadhardbcjac,
            ref double[] dstfs,
            alglib.xparams _params)
        {
            int i = 0;
            int k = 0;
            int srcidx = 0;
            int mtotalall = 0;
            int offs = 0;
            double srcscl = 0;

            mtotalall = state.mtotale+state.mtotali+state.mtotalh;
            offs = 0;
            ablasf.rcopyallocv(state.nwrk, xtoload, ref dstx, _params);
            ablasf.rallocv(1+mtotalall, ref dstfi, _params);
            ablasf.rallocv(1+mtotalall, ref dstfs, _params);
            sparse.sparsecreatecrsemptybuf(state.nwrk, dstsj, _params);
            dstfi[0] = state.rawreplyfi[0];
            dstfs[0] = state.rawreplyfs[0];
            if( !spaddscaledrowsubjecttofix(dstsj, state.rawreplysj, 0, 1.0, state.isfixed, _params) )
            {
                dstfi[0] = Double.NaN;
            }
            for(i=0; i<=state.mtotale-state.cntfixed-1; i++)
            {
                srcscl = state.srceihscl[offs];
                if( state.srceihidx[offs]<state.mnlc )
                {
                    srcidx = 1+state.srceihidx[offs];
                    dstfi[1+offs] = state.rawreplyfi[srcidx]*srcscl+state.srceihsft[offs];
                    dstfs[1+offs] = state.rawreplyfs[srcidx]*Math.Abs(srcscl);
                    if( !spaddscaledrowsubjecttofix(dstsj, state.rawreplysj, srcidx, srcscl, state.isfixed, _params) )
                    {
                        dstfi[1+offs] = Double.NaN;
                    }
                }
                else
                {
                    srcidx = state.srceihidx[offs]-state.mnlc;
                    dstfi[1+offs] = sparse.spdotvr(dstx, state.sparselc, srcidx, _params)*srcscl+state.srceihsft[offs];
                    dstfs[1+offs] = 1.0;
                    if( !spaddscaledrowsubjecttofix(dstsj, state.sparselc, srcidx, srcscl, state.isfixed, _params) )
                    {
                        dstfi[1+offs] = Double.NaN;
                    }
                }
                if( state.srceqslkidx[offs]>=0 )
                {
                    dstfi[1+offs] = dstfi[1+offs]+state.wrkfscales[1+offs]*(dstx[state.srceqslkidx[offs]]*state.srceqslkscl[offs]);
                    sparse.sparseappendelement(dstsj, state.srceqslkidx[offs], state.wrkfscales[1+offs]*state.srceqslkscl[offs], _params);
                }
                offs = offs+1;
            }
            alglib.ap.assert(offs==state.offsbce, "NLPGIPM3: 003041 failed");
            for(i=0; i<=state.cntfixed-1; i++)
            {
                dstfi[1+offs] = dstx[state.idxfixed[i]]-state.scaledbndl[state.idxfixed[i]]+state.ceq[state.offsbce+i];
                dstfs[1+offs] = 1.0;
                sparse.spappendelementrow(dstsj, state.idxfixed[i], 1.0, _params);
                alglib.ap.assert(state.srceqslkidx[offs]<0, "NLPGIPM3: 211138 failed");
                offs = offs+1;
            }
            for(i=0; i<=state.mtotali-1; i++)
            {
                srcscl = state.srceihscl[offs];
                if( state.srceihidx[offs]<state.mnlc )
                {
                    srcidx = 1+state.srceihidx[offs];
                    dstfi[1+offs] = state.rawreplyfi[srcidx]*srcscl+state.srceihsft[offs];
                    dstfs[1+offs] = state.rawreplyfs[srcidx]*Math.Abs(srcscl);
                    if( !spaddscaledrowsubjecttofix(dstsj, state.rawreplysj, srcidx, srcscl, state.isfixed, _params) )
                    {
                        dstfi[1+offs] = Double.NaN;
                    }
                }
                else
                {
                    srcidx = state.srceihidx[offs]-state.mnlc;
                    dstfi[1+offs] = sparse.spdotvr(dstx, state.sparselc, srcidx, _params)*srcscl+state.srceihsft[offs];
                    dstfs[1+offs] = 1.0;
                    if( !spaddscaledrowsubjecttofix(dstsj, state.sparselc, srcidx, srcscl, state.isfixed, _params) )
                    {
                        dstfi[1+offs] = Double.NaN;
                    }
                }
                offs = offs+1;
            }
            for(i=0; i<=state.mtotalh-state.mhardbc-1; i++)
            {
                srcscl = state.srceihscl[offs];
                if( state.srceihidx[offs]<state.mnlc )
                {
                    srcidx = 1+state.srceihidx[offs];
                    dstfi[1+offs] = state.rawreplyfi[srcidx]*srcscl+state.srceihsft[offs];
                    dstfs[1+offs] = state.rawreplyfs[srcidx]*Math.Abs(srcscl);
                    if( !spaddscaledrowsubjecttofix(dstsj, state.rawreplysj, srcidx, srcscl, state.isfixed, _params) )
                    {
                        dstfi[1+offs] = Double.NaN;
                    }
                }
                else
                {
                    srcidx = state.srceihidx[offs]-state.mnlc;
                    dstfi[1+offs] = sparse.spdotvr(dstx, state.sparselc, srcidx, _params)*srcscl+state.srceihsft[offs];
                    dstfs[1+offs] = 1.0;
                    if( !spaddscaledrowsubjecttofix(dstsj, state.sparselc, srcidx, srcscl, state.isfixed, _params) )
                    {
                        dstfi[1+offs] = Double.NaN;
                    }
                }
                offs = offs+1;
            }
            alglib.ap.assert(offs==state.offshardbc, "NLPGIPM3: 014047 failed");
            if( state.hasnonfixedbc )
            {
                alglib.ap.assert(state.mhardbc==2*state.nwrk, "NLPIPM3: 464137 failed");
                ablasf.rcopymuladdvx(state.nwrk, dstx, 0, state.hardbca, 0, state.hardbcb, 0, dstfi, 1+offs, _params);
                ablasf.rcopymuladdvx(state.nwrk, dstx, 0, state.hardbca, state.nwrk, state.hardbcb, state.nwrk, dstfi, 1+offs+state.nwrk, _params);
                ablasf.rsetvx(2*state.nwrk, 1.0, dstfs, 1+offs, _params);
                offs = offs+2*state.nwrk;
                if( !donotloadhardbcjac )
                {
                    for(k=0; k<=1; k++)
                    {
                        for(i=0; i<=state.nwrk-1; i++)
                        {
                            sparse.spappendelementrow(dstsj, i, state.hardbca[state.nwrk*k+i], _params);
                        }
                    }
                }
            }
            alglib.ap.assert(offs==mtotalall, "NLPGIPM3: 030048 failed");
            ablasf.rmergemulv(1+state.mtotale+state.mtotali+state.mtotalh, state.invwrkfscales, dstfi, _params);
            ablasf.rmergemulv(1+state.mtotale+state.mtotali+state.mtotalh, state.invwrkfscales, dstfs, _params);
            sparse.sparsemultiplyrowsby(dstsj, state.invwrkfscales, _params);
        }


        /*************************************************************************
        Update nonlinearity report using lower bound on second derivatives

          -- ALGLIB --
             Copyright 07.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void updatenonlinearityreport(double[] x0,
            double[] x1,
            int n,
            sparse.sparsematrix sj0,
            sparse.sparsematrix sj1,
            int mtotal,
            nlpgipm3state state,
            double[] repnonlinearityreport,
            alglib.xparams _params)
        {
            double xsnrm = 0;
            int j0 = 0;
            int j1 = 0;
            int k0 = 0;
            int k1 = 0;
            int jj = 0;
            int kk = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            double v = 0;

            ablasf.rallocv(n, ref state.tmp0, _params);
            ablasf.rv1scale(n, 0.01, x1, state.tmp0, _params);
            ablasf.rcopyallocv(n, x1, ref state.tmp1, _params);
            ablasf.raddv(n, -1.0, x0, state.tmp1, _params);
            xsnrm = Math.Sqrt(ablasf.rdotscl1v2(n, state.tmp1, state.tmp0, _params));
            if( (double)(xsnrm)==(double)(0) )
            {
                return;
            }
            ablasf.rsetallocv(n, 0.0, ref state.tmp1, _params);
            ablasf.rsetallocv(n, 0.0, ref state.tmp2, _params);
            for(i=0; i<=mtotal-1; i++)
            {
                if( i==0 || (state.srceihidx[i-1]>=0 && state.srceihidx[i-1]<state.mnlc) )
                {
                    j0 = sj0.ridx[i];
                    j1 = sj0.ridx[i+1]-1;
                    k0 = sj1.ridx[i];
                    k1 = sj1.ridx[i+1]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        state.tmp2[sj0.idx[jj]] = sj0.vals[jj];
                    }
                    for(kk=k0; kk<=k1; kk++)
                    {
                        state.tmp1[sj1.idx[kk]] = sj1.vals[kk];
                    }
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = sj0.idx[jj];
                        v = Math.Max(Math.Abs(sj0.vals[jj]), Math.Abs(state.tmp1[j]))+1;
                        repnonlinearityreport[j] = Math.Max(repnonlinearityreport[j], Math.Abs(sj0.vals[jj]-state.tmp1[j])/v);
                    }
                    for(kk=k0; kk<=k1; kk++)
                    {
                        k = sj1.idx[kk];
                        v = Math.Max(Math.Abs(sj1.vals[kk]), Math.Abs(state.tmp2[k]))+1;
                        repnonlinearityreport[k] = Math.Max(repnonlinearityreport[k], Math.Abs(sj1.vals[kk]-state.tmp2[k])/v);
                    }
                    for(jj=j0; jj<=j1; jj++)
                    {
                        state.tmp2[sj0.idx[jj]] = 0.0;
                    }
                    for(kk=k0; kk<=k1; kk++)
                    {
                        state.tmp1[sj1.idx[kk]] = 0.0;
                    }
                }
            }
        }


        /*************************************************************************
        Mark last point as the base one

          -- ALGLIB --
             Copyright 07.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void lastpointasbase(nlpgipm3state state,
            alglib.xparams _params)
        {
            int mtotalall = 0;

            mtotalall = state.mtotale+state.mtotali+state.mtotalh;
            alglib.ap.assert(state.mxx==0, "NLPGIPM: integrity check 403144 failed");
            if( (state.dononlinearityreports && state.haslast) && state.hasbase )
            {
                updatenonlinearityreport(state.basex, state.lastx, state.nwrk, state.xxbasesj, state.xxlastsj, mtotalall, state, state.repnonlinearityreport, _params);
            }
            if( state.haslast )
            {
                alglib.ap.swap(ref state.lastx, ref state.basex);
                alglib.ap.swap(ref state.xxlastfi, ref state.xxbasefi);
                alglib.ap.swap(ref state.xxlastfs, ref state.xxbasefs);
                sparse.sparseswap(state.xxlastsj, state.xxbasesj, _params);
                state.baserawf0 = state.lastrawf0;
                state.hasbase = true;
                state.hasbaseh = false;
                state.haslast = false;
            }
            ablasf.rallocv(state.nwrk, ref state.baselinecurvaturediag, _params);
            ablasf.rrcpsqv1scale(state.nwrk, 0.001, state.basex, state.baselinecurvaturev, state.baselinecurvaturediag, _params);
            if( state.dotracedetailedmodel )
            {
                alglib.ap.trace("> updating base point, tracing new base:\n");
                alglib.ap.trace(">> X  = ");
                apserv.tracevectore615(state.basex, 0, state.nwrk, true, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace(">> Fi = ");
                apserv.tracevectore615(state.xxbasefi, 0, 1+mtotalall, true, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace(">> J  = ");
                sparse.spcrstraceenumerateonelinee6e15(state.xxbasesj, true, true, _params);
            }
        }


        /*************************************************************************
        Save base point as best

          -- ALGLIB --
             Copyright 07.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void basepointasbest(nlpgipm3state state,
            alglib.xparams _params)
        {
            int mtotalall = 0;

            mtotalall = state.mtotale+state.mtotali+state.mtotalh;
            alglib.ap.assert(state.hasbase, "NLPGIPM: integrity check 141338 failed");
            alglib.ap.assert(state.mxx==0, "NLPGIPM: integrity check 142338 failed");
            ablasf.rcopyallocv(state.nwrk, state.basex, ref state.bestx, _params);
            ablasf.rcopyallocv(1+mtotalall, state.xxbasefi, ref state.xxbestfi, _params);
            ablasf.rcopyallocv(1+mtotalall, state.xxbasefs, ref state.xxbestfs, _params);
            sparse.sparsecopybuf(state.xxbasesj, state.ccbestsj, _params);
            state.bestrawf0 = state.baserawf0;
            state.hasbest = true;
        }


        /*************************************************************************
        Handle factorization request

          -- ALGLIB --
             Copyright 07.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void factorizematrix(nlpgipm3state state,
            alglib.xparams _params)
        {
            int nwrk = 0;
            int i = 0;
            int j = 0;
            int offs = 0;
            int mtotalnonbc = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;

            alglib.ap.assert(state.hasbase, "NLPGIPM: integrity check 453018 failed (no base point)");
            nwrk = state.nwrk;
            mtotalnonbc = state.mtotale+state.mtotali+(state.mtotalh-state.mhardbc);
            if( state.nnonlinear>0 )
            {
                alglib.ap.assert(!state.isdense, "NLPGIPM2: integrity check 017312 failed");
                optserv.hessiangetlowrankstabilized(state.hess, ref state.basehsr1diag, ref state.basehsr1corrc, ref state.basehsr1corrd, ref state.basehrank, _params);
            }
            else
            {
                state.basehrank = 0;
            }
            state.hasbaseh = true;
            alglib.ap.assert(!state.isdense, "NLPGIPM2: integrity check 017313 failed");
            alglib.ap.assert(state.hassparsityanalyzed, "NLPGIPM2: integrity check 018312 failed (sparsity pattern was not analyzed)");
            ablasf.rsetv(state.nonbcsparsesys.ridx[nwrk+mtotalnonbc+state.hessmaxrank], 0.0, state.nonbcsparsesys.vals, _params);
            ablasf.rcopyv(nwrk, state.baselinecurvaturediag, state.nonbcsparsesys.vals, _params);
            ablasf.raddv(nwrk, 1.0, state.solver.querydata, state.nonbcsparsesys.vals, _params);
            if( state.nnonlinear<nwrk )
            {
                ablasf.rscatteraddv(state.nnonlinear, 1.0, state.basehsr1diag, state.nonbcsparsesys.vals, state.idxnonlinear, _params);
            }
            else
            {
                ablasf.raddv(state.nnonlinear, 1.0, state.basehsr1diag, state.nonbcsparsesys.vals, _params);
            }
            for(i=0; i<=mtotalnonbc-1; i++)
            {
                offs = state.nonbcsparsesys.ridx[nwrk+i];
                j0 = state.xxlastanalyzedjac.ridx[1+i];
                j1 = state.xxlastanalyzedjac.ridx[1+i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    state.nonbcsparsesys.vals[offs] = state.xxlastanalyzedjac.vals[jj];
                    offs = offs+1;
                }
                state.nonbcsparsesys.vals[offs] = state.solver.querydata[nwrk+i];
                offs = offs+1;
                alglib.ap.assert(offs==state.nonbcsparsesys.ridx[nwrk+i+1], "GIPM2: integrity check 066230 failed, LastAnalyzedJac sparsity pattern is inconsistent with the what was analyzed");
            }
            if( state.mhardbc>0 )
            {
                alglib.ap.assert(state.mhardbc==2*state.nwrk, "GIPM3: 654334 failed");
                ablasf.rallocv(state.mhardbc, ref state.cholinvdh, _params);
                ablasf.rcopyrcpvx(state.mhardbc, state.solver.querydata, nwrk+mtotalnonbc, state.cholinvdh, 0, _params);
                ablasf.rcopyallocv(state.mhardbc, state.cholinvdh, ref state.cholinvdhhardbca, _params);
                ablasf.rmergemulv(state.mhardbc, state.hardbca, state.cholinvdhhardbca, _params);
                ablasf.rnegmuladdvx(state.nwrk, state.cholinvdhhardbca, 0, state.hardbca, 0, state.nonbcsparsesys.vals, 0, _params);
                ablasf.rnegmuladdvx(state.nwrk, state.cholinvdhhardbca, state.nwrk, state.hardbca, state.nwrk, state.nonbcsparsesys.vals, 0, _params);
            }
            for(i=0; i<=state.basehrank-1; i++)
            {
                alglib.ap.assert(state.nonbcsparsesys.uidx[nwrk+mtotalnonbc+i]-state.nonbcsparsesys.ridx[nwrk+mtotalnonbc+i]==state.nnonlinear+1, "NLCGIPM2: 049020");
                offs = state.nonbcsparsesys.ridx[nwrk+mtotalnonbc+i];
                for(j=0; j<=state.nnonlinear-1; j++)
                {
                    state.nonbcsparsesys.vals[offs+j] = state.basehsr1corrc[i,j];
                }
                state.nonbcsparsesys.vals[offs+state.nnonlinear] = -state.basehsr1corrd[i];
            }
            for(i=state.basehrank; i<=state.hessmaxrank-1; i++)
            {
                alglib.ap.assert(state.nonbcsparsesys.didx[nwrk+mtotalnonbc+i]<state.nonbcsparsesys.uidx[nwrk+mtotalnonbc+i], "NLCGIPM2: 065212");
                state.nonbcsparsesys.vals[state.nonbcsparsesys.didx[nwrk+mtotalnonbc+i]] = 1.0;
            }
            ablasf.ballocv(nwrk+mtotalnonbc+state.hessmaxrank, ref state.tmpb, _params);
            for(i=0; i<=nwrk-1; i++)
            {
                state.tmpb[i] = true;
            }
            for(i=nwrk; i<=mtotalnonbc+nwrk-1; i++)
            {
                state.tmpb[i] = false;
            }
            for(i=mtotalnonbc+nwrk; i<=state.hessmaxrank+mtotalnonbc+nwrk-1; i++)
            {
                state.tmpb[i] = (double)(state.nonbcsparsesys.vals[state.nonbcsparsesys.didx[i]])>=(double)(0.0);
            }
            spchol.spsymmcontrolsign(state.nonbcanalysis, state.tmpb, 0.0, _params);
            spchol.spsymmreload(state.nonbcanalysis, state.nonbcsparsesys, _params);
            state.factorized = spchol.spsymmfactorize(state.nonbcanalysis, _params);
            state.solver.factsuccess = state.factorized;
            if( !state.factorized )
            {
                return;
            }
            if( state.solver.dotrace )
            {
                if( state.nnonlinear>0 )
                {
                    alglib.ap.trace(System.String.Format("> Hessian factorized, |stabilized.diagonal|={0,0:E2}\n", ablasf.rmaxabsv(state.nnonlinear, state.basehsr1diag, _params)));
                }
            }
            state.solver.factsuccess = state.factorized;
        }


        /*************************************************************************
        Handle LLS factorization request

          -- ALGLIB --
             Copyright 07.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void factorizellsmatrix(nlpgipm3state state,
            alglib.xparams _params)
        {
            int nwrk = 0;
            int i = 0;
            int offs = 0;
            int mtotalnonbc = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;

            alglib.ap.assert(state.haslast, "NLPGIPM: integrity check 350249 failed (no base point)");
            nwrk = state.nwrk;
            mtotalnonbc = state.mtotale+state.mtotali+state.mtotalh-state.mhardbc;
            alglib.ap.assert(!state.isdense, "NLPGIPM: integrity check 357250 failed");
            alglib.ap.assert(state.hasllssparsityanalyzed, "NLPGIPM: integrity check 358250 failed (sparsity pattern was not analyzed)");
            ablasf.rsetv(state.nonbcsparsellssys.ridx[nwrk+mtotalnonbc], 0.0, state.nonbcsparsellssys.vals, _params);
            for(i=0; i<=nwrk-1; i++)
            {
                state.nonbcsparsellssys.vals[i] = state.solver.querydata[i];
            }
            for(i=0; i<=mtotalnonbc-1; i++)
            {
                offs = state.nonbcsparsellssys.ridx[nwrk+i];
                j0 = state.xxlastanalyzedllsjac.ridx[1+i];
                j1 = state.xxlastanalyzedllsjac.ridx[1+i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    state.nonbcsparsellssys.vals[offs] = state.xxlastanalyzedllsjac.vals[jj];
                    offs = offs+1;
                }
                state.nonbcsparsellssys.vals[offs] = state.solver.querydata[nwrk+i];
                offs = offs+1;
                alglib.ap.assert(offs==state.nonbcsparsellssys.ridx[nwrk+i+1], "NLPIPM: integrity check 374251 failed, LastAnalyzedLLSJac sparsity pattern is inconsistent with the what was analyzed");
            }
            if( state.mhardbc>0 )
            {
                alglib.ap.assert(state.mhardbc==2*state.nwrk, "GIPM3: 737151 failed");
                ablasf.rallocv(state.mhardbc, ref state.llscholinvdh, _params);
                ablasf.rcopyrcpvx(state.mhardbc, state.solver.querydata, nwrk+mtotalnonbc, state.llscholinvdh, 0, _params);
                ablasf.rcopyallocv(state.mhardbc, state.llscholinvdh, ref state.llscholinvdhhardbca, _params);
                ablasf.rmergemulv(state.mhardbc, state.hardbca, state.llscholinvdhhardbca, _params);
                ablasf.rnegmuladdvx(state.nwrk, state.llscholinvdhhardbca, 0, state.hardbca, 0, state.nonbcsparsellssys.vals, 0, _params);
                ablasf.rnegmuladdvx(state.nwrk, state.llscholinvdhhardbca, state.nwrk, state.hardbca, state.nwrk, state.nonbcsparsellssys.vals, 0, _params);
            }
            ablasf.ballocv(nwrk+mtotalnonbc, ref state.tmpb, _params);
            for(i=0; i<=nwrk-1; i++)
            {
                state.tmpb[i] = true;
            }
            for(i=nwrk; i<=mtotalnonbc+nwrk-1; i++)
            {
                state.tmpb[i] = false;
            }
            spchol.spsymmcontrolsign(state.nonbcanalysislls, state.tmpb, 0.0, _params);
            spchol.spsymmreload(state.nonbcanalysislls, state.nonbcsparsellssys, _params);
            state.factorizedlls = spchol.spsymmfactorize(state.nonbcanalysislls, _params);
            state.solver.factsuccess = state.factorizedlls;
            if( !state.factorizedlls )
            {
                return;
            }
            if( state.solver.dotrace )
            {
                alglib.ap.trace("> LLS system factorized\n");
            }
            state.solver.factsuccess = state.factorizedlls;
        }


        /*************************************************************************
        Handle solve request

          -- ALGLIB --
             Copyright 25.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void solvesystem(nlpgipm3state state,
            alglib.xparams _params)
        {
            int mtotalnonbc = 0;
            int mhardbc = 0;

            mtotalnonbc = state.mtotale+state.mtotali+(state.mtotalh-state.mhardbc);
            mhardbc = state.mhardbc;
            alglib.ap.assert(state.factorized, "NLPGIPM: integrity check 577120 failed");
            ablasf.rsetallocv(state.nwrk+mtotalnonbc+state.hessmaxrank, 0.0, ref state.tmp0, _params);
            ablasf.rcopyv(state.nwrk+mtotalnonbc, state.solver.querydata, state.tmp0, _params);
            if( mhardbc>0 )
            {
                alglib.ap.assert(mhardbc==2*state.nwrk, "NLPIPM: 768457 failed");
                ablasf.rnegmuladdvx(state.nwrk, state.cholinvdhhardbca, 0, state.solver.querydata, state.nwrk+mtotalnonbc, state.tmp0, 0, _params);
                ablasf.rnegmuladdvx(state.nwrk, state.cholinvdhhardbca, state.nwrk, state.solver.querydata, state.nwrk+mtotalnonbc+state.nwrk, state.tmp0, 0, _params);
            }
            spchol.spsymmsolve(state.nonbcanalysis, state.tmp0, _params);
            ablasf.rcopyv(state.nwrk+mtotalnonbc, state.tmp0, state.solver.replysol, _params);
            if( mhardbc>0 )
            {
                alglib.ap.assert(mhardbc==2*state.nwrk, "NLPIPM: 768457 failed");
                ablasf.rcopynegmuladdvx(state.nwrk, state.hardbca, 0, state.tmp0, 0, state.solver.querydata, state.nwrk+mtotalnonbc, state.solver.replysol, state.nwrk+mtotalnonbc, _params);
                ablasf.rcopynegmuladdvx(state.nwrk, state.hardbca, state.nwrk, state.tmp0, 0, state.solver.querydata, state.nwrk+mtotalnonbc+state.nwrk, state.solver.replysol, state.nwrk+mtotalnonbc+state.nwrk, _params);
                ablasf.rmergemulvx(mhardbc, state.cholinvdh, 0, state.solver.replysol, state.nwrk+mtotalnonbc, _params);
            }
        }


        /*************************************************************************
        Handle solve request

          -- ALGLIB --
             Copyright 25.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void solvellssystem(nlpgipm3state state,
            alglib.xparams _params)
        {
            int mtotalnonbc = 0;

            mtotalnonbc = state.mtotale+state.mtotali+(state.mtotalh-state.mhardbc);
            alglib.ap.assert(state.factorizedlls, "NLPGIPM: integrity check 577120 failed");
            ablasf.rallocv(state.nwrk+mtotalnonbc, ref state.tmp0, _params);
            ablasf.rcopyv(state.nwrk+mtotalnonbc, state.solver.querydata, state.tmp0, _params);
            if( state.mhardbc>0 )
            {
                alglib.ap.assert(state.mhardbc==2*state.nwrk, "NLPIPM: 814153 failed");
                ablasf.rnegmuladdvx(state.nwrk, state.llscholinvdhhardbca, 0, state.solver.querydata, state.nwrk+mtotalnonbc, state.tmp0, 0, _params);
                ablasf.rnegmuladdvx(state.nwrk, state.llscholinvdhhardbca, state.nwrk, state.solver.querydata, state.nwrk+mtotalnonbc+state.nwrk, state.tmp0, 0, _params);
            }
            spchol.spsymmsolve(state.nonbcanalysislls, state.tmp0, _params);
            ablasf.rcopyv(state.nwrk+mtotalnonbc, state.tmp0, state.solver.replysol, _params);
            if( state.mhardbc>0 )
            {
                alglib.ap.assert(state.mhardbc==2*state.nwrk, "NLPIPM: 822154 failed");
                ablasf.rcopynegmuladdvx(state.nwrk, state.hardbca, 0, state.tmp0, 0, state.solver.querydata, state.nwrk+mtotalnonbc, state.solver.replysol, state.nwrk+mtotalnonbc, _params);
                ablasf.rcopynegmuladdvx(state.nwrk, state.hardbca, state.nwrk, state.tmp0, 0, state.solver.querydata, state.nwrk+mtotalnonbc+state.nwrk, state.solver.replysol, state.nwrk+mtotalnonbc+state.nwrk, _params);
                ablasf.rmergemulvx(state.mhardbc, state.llscholinvdh, 0, state.solver.replysol, state.nwrk+mtotalnonbc, _params);
            }
        }


        /*************************************************************************
        Handle matrix-vector product request at the base point

          -- ALGLIB --
             Copyright 25.10.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void matrixvectorbaseall(nlpgipm3state state,
            alglib.xparams _params)
        {
            int nwrk = 0;
            int mtotalall = 0;

            nwrk = state.nwrk;
            mtotalall = state.mtotale+state.mtotali+state.mtotalh;
            alglib.ap.assert(state.hasbase && state.hasbaseh, "NLPGIPM: integrity check 4322 failed");
            alglib.ap.assert(!state.isdense, "NLCGIPM: integrity check 217017 failed");
            ablasf.rallocv(Math.Max(nwrk, mtotalall+1), ref state.tmp0, _params);
            ablasf.rallocv(Math.Max(nwrk, mtotalall+1), ref state.tmp1, _params);
            ablasf.rallocv(Math.Max(nwrk, mtotalall+1), ref state.tmp2, _params);
            ablasf.rcopyv(nwrk, state.solver.querydata, state.solver.replyprod, _params);
            ablasf.rmergemulv(nwrk, state.baselinecurvaturediag, state.solver.replyprod, _params);
            if( state.nnonlinear==nwrk )
            {
                ablasf.rcopyvx(nwrk, state.solver.querydata, 0, state.tmp0, 0, _params);
                ablasf.rcopyv(nwrk, state.tmp0, state.tmp1, _params);
                ablasf.rmergemulv(nwrk, state.basehsr1diag, state.tmp1, _params);
                if( state.basehrank>0 )
                {
                    alglib.ap.assert(state.basehrank<=nwrk, "NLCGIPM: integrity check 235014 failed");
                    ablasf.rgemv(state.basehrank, nwrk, 1.0, state.basehsr1corrc, 0, state.tmp0, 0.0, state.tmp2, _params);
                    ablasf.rmergemulv(state.basehrank, state.basehsr1corrd, state.tmp2, _params);
                    ablasf.rgemv(nwrk, state.basehrank, 1.0, state.basehsr1corrc, 1, state.tmp2, 1.0, state.tmp1, _params);
                }
                ablasf.raddv(nwrk, 1.0, state.tmp1, state.solver.replyprod, _params);
            }
            if( state.nnonlinear<nwrk && state.nnonlinear>0 )
            {
                ablasf.rgathercopyv(state.nnonlinear, state.solver.querydata, state.idxnonlinear, state.tmp0, _params);
                ablasf.rcopyv(state.nnonlinear, state.tmp0, state.tmp1, _params);
                ablasf.rmergemulv(state.nnonlinear, state.basehsr1diag, state.tmp1, _params);
                if( state.basehrank>0 )
                {
                    alglib.ap.assert(state.basehrank<=state.nnonlinear, "NLCGIPM: integrity check 710414 failed");
                    ablasf.rgemv(state.basehrank, state.nnonlinear, 1.0, state.basehsr1corrc, 0, state.tmp0, 0.0, state.tmp2, _params);
                    ablasf.rmergemulv(state.basehrank, state.basehsr1corrd, state.tmp2, _params);
                    ablasf.rgemv(state.nnonlinear, state.basehrank, 1.0, state.basehsr1corrc, 1, state.tmp2, 1.0, state.tmp1, _params);
                }
                ablasf.rscatteraddv(state.nnonlinear, 1.0, state.tmp1, state.solver.replyprod, state.idxnonlinear, _params);
            }
            sparse.sparsegemv(state.xxbasesj, 1.0, 0, state.solver.querydata, 0, 0.0, state.tmp1, 0, _params);
            if( state.mhardbc>0 )
            {
                alglib.ap.assert(state.mhardbc==2*nwrk, "NLPIPM: 896227 failed");
                ablasf.rcopyvx(state.nwrk, state.solver.querydata, 0, state.tmp1, 1+mtotalall-state.mhardbc, _params);
                ablasf.rcopyvx(state.nwrk, state.solver.querydata, 0, state.tmp1, 1+mtotalall-state.mhardbc+nwrk, _params);
                ablasf.rmergemulvx(state.mhardbc, state.hardbca, 0, state.tmp1, 1+mtotalall-state.mhardbc, _params);
            }
            ablasf.rcopyvx(mtotalall, state.tmp1, 1, state.solver.replyprod, nwrk, _params);
            state.tmp2[0] = 0;
            ablasf.rcopyvx(mtotalall-state.mhardbc, state.solver.querydata, nwrk, state.tmp2, 1, _params);
            sparse.sparsegemv(state.xxbasesj, 1.0, 1, state.tmp2, 0, 0.0, state.tmp1, 0, _params);
            if( state.mhardbc>0 )
            {
                alglib.ap.assert(state.mhardbc==2*nwrk, "NLPIPM: 908238 failed");
                ablasf.rmuladdvx(nwrk, state.solver.querydata, nwrk+(mtotalall-state.mhardbc), state.hardbca, 0, state.tmp1, 0, _params);
                ablasf.rmuladdvx(nwrk, state.solver.querydata, nwrk+(mtotalall-state.mhardbc)+nwrk, state.hardbca, nwrk, state.tmp1, 0, _params);
            }
            ablasf.rcopyvx(nwrk, state.tmp1, 0, state.solver.replyprod, nwrk+mtotalall, _params);
        }


        /*************************************************************************
        Handle matrix-vector product request at the last point

          -- ALGLIB --
             Copyright 25.10.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void matrixvectorbase(nlpgipm3state state,
            int requesttype,
            alglib.xparams _params)
        {
            int mtotalall = 0;
            int nwrk = 0;

            nwrk = state.nwrk;
            mtotalall = state.mtotale+state.mtotali+state.mtotalh;
            alglib.ap.assert(state.hasbase, "NLPGIPM: integrity check 440249 failed");
            if( requesttype==1011 )
            {
                ablasf.rallocv(mtotalall+1, ref state.tmp0, _params);
                sparse.sparsegemv(state.xxbasesj, 1.0, 0, state.solver.querydata, 0, 0.0, state.tmp0, 0, _params);
                if( state.mhardbc>0 )
                {
                    alglib.ap.assert(state.mhardbc==2*nwrk, "NLPIPM: 941241 failed");
                    ablasf.rcopyvx(state.nwrk, state.solver.querydata, 0, state.tmp0, 1+mtotalall-state.mhardbc, _params);
                    ablasf.rcopyvx(state.nwrk, state.solver.querydata, 0, state.tmp0, 1+mtotalall-state.mhardbc+nwrk, _params);
                    ablasf.rmergemulvx(state.mhardbc, state.hardbca, 0, state.tmp0, 1+mtotalall-state.mhardbc, _params);
                }
                ablasf.rcopyvx(mtotalall, state.tmp0, 1, state.solver.replyprod, 0, _params);
                return;
            }
            if( requesttype==1012 )
            {
                ablasf.rallocv(mtotalall+1, ref state.tmp0, _params);
                state.tmp0[0] = 0;
                ablasf.rcopyvx(mtotalall-state.mhardbc, state.solver.querydata, 0, state.tmp0, 1, _params);
                sparse.sparsegemv(state.xxbasesj, 1.0, 1, state.tmp0, 0, 0.0, state.solver.replyprod, 0, _params);
                if( state.mhardbc>0 )
                {
                    alglib.ap.assert(state.mhardbc==2*nwrk, "NLPIPM: 953243 failed");
                    ablasf.rmuladdvx(nwrk, state.solver.querydata, mtotalall-state.mhardbc, state.hardbca, 0, state.solver.replyprod, 0, _params);
                    ablasf.rmuladdvx(nwrk, state.solver.querydata, mtotalall-state.mhardbc+nwrk, state.hardbca, nwrk, state.solver.replyprod, 0, _params);
                }
                return;
            }
            if( requesttype==1010 )
            {
                ablasf.rcopyv(nwrk, state.solver.querydata, state.solver.replyprod, _params);
                ablasf.rmergemulv(nwrk, state.baselinecurvaturediag, state.solver.replyprod, _params);
                if( state.nnonlinear==nwrk )
                {
                    ablasf.rcopyvx(nwrk, state.solver.querydata, 0, state.tmp0, 0, _params);
                    ablasf.rcopyv(nwrk, state.tmp0, state.tmp1, _params);
                    ablasf.rmergemulv(nwrk, state.basehsr1diag, state.tmp1, _params);
                    if( state.basehrank>0 )
                    {
                        alglib.ap.assert(state.basehrank<=nwrk, "NLCGIPM: integrity check 235014 failed");
                        ablasf.rgemv(state.basehrank, nwrk, 1.0, state.basehsr1corrc, 0, state.tmp0, 0.0, state.tmp2, _params);
                        ablasf.rmergemulv(state.basehrank, state.basehsr1corrd, state.tmp2, _params);
                        ablasf.rgemv(nwrk, state.basehrank, 1.0, state.basehsr1corrc, 1, state.tmp2, 1.0, state.tmp1, _params);
                    }
                    ablasf.raddv(nwrk, 1.0, state.tmp1, state.solver.replyprod, _params);
                }
                if( state.nnonlinear<nwrk && state.nnonlinear>0 )
                {
                    ablasf.rgathercopyv(state.nnonlinear, state.solver.querydata, state.idxnonlinear, state.tmp0, _params);
                    ablasf.rcopyv(state.nnonlinear, state.tmp0, state.tmp1, _params);
                    ablasf.rmergemulv(state.nnonlinear, state.basehsr1diag, state.tmp1, _params);
                    if( state.basehrank>0 )
                    {
                        alglib.ap.assert(state.basehrank<=state.nnonlinear, "NLCGIPM: integrity check 710414 failed");
                        ablasf.rgemv(state.basehrank, state.nnonlinear, 1.0, state.basehsr1corrc, 0, state.tmp0, 0.0, state.tmp2, _params);
                        ablasf.rmergemulv(state.basehrank, state.basehsr1corrd, state.tmp2, _params);
                        ablasf.rgemv(state.nnonlinear, state.basehrank, 1.0, state.basehsr1corrc, 1, state.tmp2, 1.0, state.tmp1, _params);
                    }
                    ablasf.rscatteraddv(state.nnonlinear, 1.0, state.tmp1, state.solver.replyprod, state.idxnonlinear, _params);
                }
                return;
            }
            alglib.ap.assert(false, "NLPGIPM: integrity check 437328 failed");
        }


        /*************************************************************************
        Handle matrix-vector product request at the last point

          -- ALGLIB --
             Copyright 25.10.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void matrixvectorlast(nlpgipm3state state,
            int requesttype,
            alglib.xparams _params)
        {
            int mtotalall = 0;
            int nwrk = 0;

            mtotalall = state.mtotale+state.mtotali+state.mtotalh;
            nwrk = state.nwrk;
            if( state.haslast )
            {
                if( requesttype==1020 )
                {
                    alglib.ap.assert(false, "NLPGIPM: RequestType=1020 not implemented");
                    return;
                }
                if( requesttype==1021 )
                {
                    ablasf.rallocv(mtotalall+1, ref state.tmp0, _params);
                    sparse.sparsegemv(state.xxlastsj, 1.0, 0, state.solver.querydata, 0, 0.0, state.tmp0, 0, _params);
                    if( state.mhardbc>0 )
                    {
                        alglib.ap.assert(state.mhardbc==2*nwrk, "NLPIPM: 035247 failed");
                        ablasf.rcopyvx(state.nwrk, state.solver.querydata, 0, state.tmp0, 1+mtotalall-state.mhardbc, _params);
                        ablasf.rcopyvx(state.nwrk, state.solver.querydata, 0, state.tmp0, 1+mtotalall-state.mhardbc+nwrk, _params);
                        ablasf.rmergemulvx(state.mhardbc, state.hardbca, 0, state.tmp0, 1+mtotalall-state.mhardbc, _params);
                    }
                    ablasf.rcopyvx(mtotalall, state.tmp0, 1, state.solver.replyprod, 0, _params);
                    return;
                }
                if( requesttype==1022 )
                {
                    ablasf.rallocv(mtotalall+1, ref state.tmp0, _params);
                    state.tmp0[0] = 0;
                    ablasf.rcopyvx(mtotalall-state.mhardbc, state.solver.querydata, 0, state.tmp0, 1, _params);
                    sparse.sparsegemv(state.xxlastsj, 1.0, 1, state.tmp0, 0, 0.0, state.solver.replyprod, 0, _params);
                    if( state.mhardbc>0 )
                    {
                        alglib.ap.assert(state.mhardbc==2*nwrk, "NLPIPM: 057247 failed");
                        ablasf.rmuladdvx(nwrk, state.solver.querydata, mtotalall-state.mhardbc, state.hardbca, 0, state.solver.replyprod, 0, _params);
                        ablasf.rmuladdvx(nwrk, state.solver.querydata, mtotalall-state.mhardbc+nwrk, state.hardbca, nwrk, state.solver.replyprod, 0, _params);
                    }
                    return;
                }
            }
            else
            {
                alglib.ap.assert(state.hasbase, "NLPGIPM: 908406 failed");
                if( requesttype==1020 )
                {
                    matrixvectorbase(state, 1010, _params);
                    return;
                }
                if( requesttype==1021 )
                {
                    matrixvectorbase(state, 1011, _params);
                    return;
                }
                if( requesttype==1022 )
                {
                    matrixvectorbase(state, 1012, _params);
                    return;
                }
            }
            alglib.ap.assert(false, "NLPGIPM: integrity check 437328 failed");
        }


        /*************************************************************************
        Initialize model converted to GIPM3 style (equalities, followed by soft
        inequalities, followed by hard inequalities)

          -- ALGLIB --
             Copyright 23.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static bool gipm3styledmodelinit(nlpgipm3state state,
            double[] rawfiatx0,
            sparse.sparsematrix rawsjatx0,
            double[] rawfsatx0,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int offs = 0;
            double v = 0;
            double v1 = 0;
            double vv = 0;

            result = true;
            ablasf.rgrowappendv(1, ref state.wrkfscales, Math.Max(rawfsatx0[0], 1), _params);
            ablasf.iallocv(state.mnlc+state.mlc, ref state.constrbucket, _params);
            for(i=0; i<=state.mnlc-1; i++)
            {
                v = rawfiatx0[1+i];
                v1 = Math.Max(rawfsatx0[1+i], 1);
                if( !math.isfinite(state.rawnl[i]) && !math.isfinite(state.rawnu[i]) )
                {
                    state.constrbucket[i] = -1;
                    continue;
                }
                if( state.nlcishard[i] )
                {
                    if( math.isfinite(state.rawnl[i]) && math.isfinite(state.rawnu[i]) )
                    {
                        if( state.dotrace )
                        {
                            alglib.ap.trace(System.String.Format("[ERROR] nonlinear constraint {0,0:d} that has both bounds present (NL={1,0:E3}, NU={2,0:E3}) is marked as strict; only single-sided constraints can be marked as hard; terminating\n", i, state.rawnl[i], state.rawnu[i]));
                        }
                        state.repterminationtype = -6;
                        result = false;
                        return result;
                    }
                    alglib.ap.assert(math.isfinite(state.rawnl[i]) || math.isfinite(state.rawnu[i]), "GIPM3: 474155 failed");
                    if( math.isfinite(state.rawnl[i]) && (double)(v)<=(double)(state.rawnl[i]) )
                    {
                        if( state.dotrace )
                        {
                            alglib.ap.trace(System.String.Format("[ERROR] initial point is not in a strict interior of a nonlinear constraint {0,0:d} (lower bound is {1,0:E15}, constraint value is {2,0:E15})\n", i, state.rawnl[i], v));
                        }
                        state.repterminationtype = -9;
                        result = false;
                        return result;
                    }
                    if( math.isfinite(state.rawnu[i]) && (double)(v)>=(double)(state.rawnu[i]) )
                    {
                        if( state.dotrace )
                        {
                            alglib.ap.trace(System.String.Format("[ERROR] initial point is not in a strict interior of a nonlinear constraint {0,0:d} (upper bound is {1,0:E15}, constraint value is {2,0:E15})\n", i, state.rawnu[i], v));
                        }
                        state.repterminationtype = -9;
                        result = false;
                        return result;
                    }
                    state.constrbucket[i] = 2;
                    continue;
                }
                if( math.isfinite(state.rawnl[i]) && math.isfinite(state.rawnu[i]) )
                {
                    state.constrbucket[i] = apserv.icase2((double)(Math.Abs(state.rawnu[i]-state.rawnl[i]))<=(double)(state.fixtol*v1), 0, 3, _params);
                    continue;
                }
                state.constrbucket[i] = 1;
            }
            for(i=0; i<=state.mlc-1; i++)
            {
                if( math.isfinite(state.lcbndl[i]) && math.isfinite(state.lcbndu[i]) )
                {
                    state.constrbucket[state.mnlc+i] = apserv.icase2((double)(Math.Abs(state.lcbndu[i]-state.lcbndl[i]))<=(double)(state.fixtol), 0, 3, _params);
                    continue;
                }
                if( !math.isfinite(state.lcbndl[i]) && !math.isfinite(state.lcbndu[i]) )
                {
                    state.constrbucket[state.mnlc+i] = -1;
                    continue;
                }
                v = sparse.spdotvr(state.scaledx0, state.sparselc, i, _params);
                if( math.isfinite(state.lcbndl[i]) )
                {
                    state.constrbucket[state.mnlc+i] = apserv.icase2((double)(v)>(double)(state.lcbndl[i]+mindistforhard), 2, 1, _params);
                }
                else
                {
                    state.constrbucket[state.mnlc+i] = apserv.icase2((double)(v)<(double)(state.lcbndu[i]-mindistforhard), 2, 1, _params);
                }
            }
            state.meqnlc = 0;
            state.meqlc = 0;
            state.meqxx = 0;
            state.minlc = 0;
            state.milc = 0;
            state.mixx = 0;
            state.mhnlc = 0;
            state.mhlc = 0;
            state.mhxx = 0;
            state.mtotale = 0;
            state.mtotali = 0;
            state.mtotalh = 0;
            offs = 0;
            for(i=0; i<=state.mnlc-1; i++)
            {
                if( (state.constrbucket[i]==-1 || state.constrbucket[i]==1) || state.constrbucket[i]==2 )
                {
                    continue;
                }
                if( state.constrbucket[i]==0 )
                {
                    ablasf.igrowappendv(offs+1, ref state.srceihidx, i, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihscl, 1.0, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                    ablasf.igrowappendv(offs+1, ref state.srceqslkidx, -1, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceqslkscl, 0.0, _params);
                    vv = Math.Max(rawfsatx0[1+i], 1);
                    ablasf.rgrowappendv(state.mtotale+1, ref state.ceq, state.rawnl[i]/vv, _params);
                    ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, vv, _params);
                    state.mtotale = state.mtotale+1;
                    offs = offs+1;
                    continue;
                }
                if( state.constrbucket[i]==3 )
                {
                    v = rawfiatx0[1+i];
                    vv = Math.Max(rawfsatx0[1+i], 1);
                    v1 = vv*gipm3.gipm3getinitprimdual(_params);
                    v = Math.Max(Math.Min(state.rawnl[i]+v1, 0.5*(state.rawnl[i]+state.rawnu[i])), v);
                    v = Math.Min(Math.Max(state.rawnu[i]-v1, 0.5*(state.rawnl[i]+state.rawnu[i])), v);
                    ablasf.rgrowappendv(state.nwrk+1, ref state.scaledx0, v/vv, _params);
                    ablasf.rgrowappendv(state.nwrk+1, ref state.scaledbndl, state.rawnl[i]/vv, _params);
                    ablasf.rgrowappendv(state.nwrk+1, ref state.scaledbndu, state.rawnu[i]/vv, _params);
                    ablasf.rgrowappendv(state.nwrk+1, ref state.finitescaledbndl, state.rawnl[i]/vv, _params);
                    ablasf.rgrowappendv(state.nwrk+1, ref state.finitescaledbndu, state.rawnu[i]/vv, _params);
                    ablasf.bgrowappendv(state.nwrk+1, ref state.isfixed, false, _params);
                    ablasf.bgrowappendv(state.nwrk+1, ref state.esintmask, false, _params);
                    ablasf.bgrowappendv(state.nwrk+1, ref state.islinear, true, _params);
                    ablasf.igrowappendv(offs+1, ref state.srceihidx, i, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihscl, 1.0, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                    ablasf.igrowappendv(offs+1, ref state.srceqslkidx, state.nwrk, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceqslkscl, -1.0, _params);
                    ablasf.rgrowappendv(state.mtotale+1, ref state.ceq, 0.0, _params);
                    ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, vv, _params);
                    state.mtotale = state.mtotale+1;
                    offs = offs+1;
                    state.nwrk = state.nwrk+1;
                    state.hasnonfixedbc = true;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 635132 failed");
            }
            for(i=0; i<=state.mlc-1; i++)
            {
                if( (state.constrbucket[state.mnlc+i]==-1 || state.constrbucket[state.mnlc+i]==1) || state.constrbucket[state.mnlc+i]==2 )
                {
                    continue;
                }
                if( state.constrbucket[state.mnlc+i]==0 )
                {
                    ablasf.igrowappendv(offs+1, ref state.srceihidx, state.mnlc+i, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihscl, 1.0, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                    ablasf.igrowappendv(offs+1, ref state.srceqslkidx, -1, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceqslkscl, 0.0, _params);
                    ablasf.rgrowappendv(state.mtotale+1, ref state.ceq, state.lcbndl[i], _params);
                    ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, 1.0, _params);
                    state.mtotale = state.mtotale+1;
                    offs = offs+1;
                    continue;
                }
                if( state.constrbucket[state.mnlc+i]==3 )
                {
                    v = sparse.spdotvr(state.scaledx0, state.sparselc, i, _params);
                    v = Math.Max(Math.Min(state.lcbndl[i]+gipm3.gipm3getinitprimdual(_params), 0.5*(state.lcbndl[i]+state.lcbndu[i])), v);
                    v = Math.Min(Math.Max(state.lcbndu[i]-gipm3.gipm3getinitprimdual(_params), 0.5*(state.lcbndl[i]+state.lcbndu[i])), v);
                    ablasf.rgrowappendv(state.nwrk+1, ref state.scaledx0, v, _params);
                    ablasf.rgrowappendv(state.nwrk+1, ref state.scaledbndl, state.lcbndl[i], _params);
                    ablasf.rgrowappendv(state.nwrk+1, ref state.scaledbndu, state.lcbndu[i], _params);
                    ablasf.rgrowappendv(state.nwrk+1, ref state.finitescaledbndl, state.lcbndl[i], _params);
                    ablasf.rgrowappendv(state.nwrk+1, ref state.finitescaledbndu, state.lcbndu[i], _params);
                    ablasf.bgrowappendv(state.nwrk+1, ref state.isfixed, false, _params);
                    ablasf.bgrowappendv(state.nwrk+1, ref state.esintmask, false, _params);
                    ablasf.bgrowappendv(state.nwrk+1, ref state.islinear, true, _params);
                    ablasf.igrowappendv(offs+1, ref state.srceihidx, state.mnlc+i, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihscl, 1.0, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                    ablasf.igrowappendv(offs+1, ref state.srceqslkidx, state.nwrk, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceqslkscl, -1.0, _params);
                    ablasf.rgrowappendv(state.mtotale+1, ref state.ceq, 0.0, _params);
                    ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, 1.0, _params);
                    state.mtotale = state.mtotale+1;
                    offs = offs+1;
                    state.nwrk = state.nwrk+1;
                    state.hasnonfixedbc = true;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 622952 failed");
            }
            state.offsbce = offs;
            for(i=0; i<=state.cntfixed-1; i++)
            {
                ablasf.igrowappendv(offs+1, ref state.srceihidx, -999999, _params);
                ablasf.rgrowappendv(offs+1, ref state.srceihscl, 0.0, _params);
                ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                ablasf.igrowappendv(offs+1, ref state.srceqslkidx, -1, _params);
                ablasf.rgrowappendv(offs+1, ref state.srceqslkscl, 0.0, _params);
                ablasf.rgrowappendv(state.mtotale+1, ref state.ceq, state.scaledbndl[state.idxfixed[i]], _params);
                ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, 1.0, _params);
                state.mtotale = state.mtotale+1;
                offs = offs+1;
            }
            state.msofteqbc = state.cntfixed;
            for(i=0; i<=state.mnlc-1; i++)
            {
                if( ((state.constrbucket[i]==-1 || state.constrbucket[i]==0) || state.constrbucket[i]==2) || state.constrbucket[i]==3 )
                {
                    continue;
                }
                if( state.constrbucket[i]==1 )
                {
                    vv = Math.Max(rawfsatx0[1+i], 1);
                    ablasf.igrowappendv(offs+1, ref state.srceihidx, i, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihscl, apserv.rcase2(math.isfinite(state.rawnl[i]), 1.0, -1.0, _params), _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                    ablasf.rgrowappendv(state.mtotali+1, ref state.ci, apserv.rcase2(math.isfinite(state.rawnl[i]), state.rawnl[i]/vv, -(state.rawnu[i]/vv), _params), _params);
                    ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, vv, _params);
                    state.mtotali = state.mtotali+1;
                    offs = offs+1;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 651953 failed");
            }
            for(i=0; i<=state.mlc-1; i++)
            {
                if( ((state.constrbucket[state.mnlc+i]==-1 || state.constrbucket[state.mnlc+i]==0) || state.constrbucket[state.mnlc+i]==2) || state.constrbucket[state.mnlc+i]==3 )
                {
                    continue;
                }
                if( state.constrbucket[state.mnlc+i]==1 )
                {
                    ablasf.igrowappendv(offs+1, ref state.srceihidx, state.mnlc+i, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihscl, apserv.rcase2(math.isfinite(state.lcbndl[i]), 1.0, -1.0, _params), _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                    ablasf.rgrowappendv(state.mtotali+1, ref state.ci, apserv.rcase2(math.isfinite(state.lcbndl[i]), state.lcbndl[i], -state.lcbndu[i], _params), _params);
                    ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, 1.0, _params);
                    state.mtotali = state.mtotali+1;
                    offs = offs+1;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 651953 failed");
            }
            for(i=0; i<=state.mnlc-1; i++)
            {
                if( ((state.constrbucket[i]==-1 || state.constrbucket[i]==0) || state.constrbucket[i]==1) || state.constrbucket[i]==3 )
                {
                    continue;
                }
                if( state.constrbucket[i]==2 )
                {
                    vv = Math.Max(rawfsatx0[1+i], 1);
                    ablasf.igrowappendv(offs+1, ref state.srceihidx, i, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihscl, apserv.rcase2(math.isfinite(state.rawnl[i]), 1.0, -1.0, _params), _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                    ablasf.rgrowappendv(state.mtotalh+1, ref state.ch, apserv.rcase2(math.isfinite(state.rawnl[i]), state.rawnl[i]/vv, -(state.rawnu[i]/vv), _params), _params);
                    ablasf.bgrowappendv(state.mtotalh+1, ref state.chislinear, false, _params);
                    ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, vv, _params);
                    state.mtotalh = state.mtotalh+1;
                    offs = offs+1;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 702135 failed");
            }
            for(i=0; i<=state.mlc-1; i++)
            {
                if( ((state.constrbucket[state.mnlc+i]==-1 || state.constrbucket[state.mnlc+i]==0) || state.constrbucket[state.mnlc+i]==1) || state.constrbucket[state.mnlc+i]==3 )
                {
                    continue;
                }
                if( state.constrbucket[state.mnlc+i]==2 )
                {
                    ablasf.igrowappendv(offs+1, ref state.srceihidx, state.mnlc+i, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihscl, apserv.rcase2(math.isfinite(state.lcbndl[i]), 1.0, -1.0, _params), _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                    ablasf.rgrowappendv(state.mtotalh+1, ref state.ch, apserv.rcase2(math.isfinite(state.lcbndl[i]), state.lcbndl[i], -state.lcbndu[i], _params), _params);
                    ablasf.bgrowappendv(state.mtotalh+1, ref state.chislinear, true, _params);
                    ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, 1.0, _params);
                    state.mtotalh = state.mtotalh+1;
                    offs = offs+1;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 669037 failed");
            }
            state.mhardbc = 0;
            state.offshardbc = offs;
            state.hardbcfirstch = state.mtotalh;
            if( state.hasnonfixedbc )
            {
                state.mhardbc = 2*state.nwrk;
                ablasf.rsetallocv(2*state.nwrk, 0.0, ref state.hardbca, _params);
                ablasf.rsetallocv(2*state.nwrk, 1.0, ref state.hardbcb, _params);
                for(i=0; i<=state.nwrk-1; i++)
                {
                    if( !state.isfixed[i] && math.isfinite(state.scaledbndl[i]) )
                    {
                        state.hardbca[i] = 1.0;
                        state.hardbcb[i] = 0.0;
                        ablasf.rgrowappendv(state.mtotalh+1, ref state.ch, state.scaledbndl[i], _params);
                    }
                    else
                    {
                        ablasf.rgrowappendv(state.mtotalh+1, ref state.ch, 0.0, _params);
                    }
                    ablasf.igrowappendv(offs+1, ref state.srceihidx, -999999, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihscl, 0.0, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                    ablasf.bgrowappendv(state.mtotalh+1, ref state.chislinear, true, _params);
                    ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, 1.0, _params);
                    state.mtotalh = state.mtotalh+1;
                    offs = offs+1;
                }
                for(i=0; i<=state.nwrk-1; i++)
                {
                    if( !state.isfixed[i] && math.isfinite(state.scaledbndu[i]) )
                    {
                        state.hardbca[state.nwrk+i] = -1.0;
                        state.hardbcb[state.nwrk+i] = 0.0;
                        ablasf.rgrowappendv(state.mtotalh+1, ref state.ch, -state.scaledbndu[i], _params);
                    }
                    else
                    {
                        ablasf.rgrowappendv(state.mtotalh+1, ref state.ch, 0.0, _params);
                    }
                    ablasf.igrowappendv(offs+1, ref state.srceihidx, -999999, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihscl, 0.0, _params);
                    ablasf.rgrowappendv(offs+1, ref state.srceihsft, 0.0, _params);
                    ablasf.bgrowappendv(state.mtotalh+1, ref state.chislinear, true, _params);
                    ablasf.rgrowappendv(1+offs+1, ref state.wrkfscales, 1.0, _params);
                    state.mtotalh = state.mtotalh+1;
                    offs = offs+1;
                }
            }
            alglib.ap.assert(offs==state.mtotale+state.mtotali+state.mtotalh, "NLPIPM3: 803105 failed");
            ablasf.rsetallocv(1+state.mtotale+state.mtotali+state.mtotalh, 1.0, ref state.invwrkfscales, _params);
            ablasf.rmergedivv(1+state.mtotale+state.mtotali+state.mtotalh, state.wrkfscales, state.invwrkfscales, _params);
            ablasf.rcopyallocv(1+state.mtotale+state.mtotali+state.mtotalh, state.wrkfscales, ref state.initwrkfscales, _params);
            state.fbigscale = 5.0;
            state.fsmallscale = 0.1;
            return result;
        }


        /*************************************************************************
        Rescales GIPM3 styled-model (equalities, followed by soft inequalities,
        followed by hard inequalities) according to rescale applied to the raw
        model.

        The result is loaded into State.Solver.ReplyV and State.Solver.ReplyWasRescale

          -- ALGLIB --
             Copyright 23.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void gipm3styledmodelrescale(nlpgipm3state state,
            alglib.xparams _params)
        {
            int mtotalall = 0;
            int i = 0;
            int offs = 0;
            double v = 0;
            double vv = 0;
            int currente = 0;
            int currenti = 0;
            int currenth = 0;
            int currentwrk = 0;
            double nrm = 0;
            double multiplyby = 0;
            double setscaleto = 0;
            bool bigscaletriggered = new bool();
            bool smallscaletriggered = new bool();

            alglib.ap.assert(state.hasbase, "NLPIPM3: 934230 failed");
            mtotalall = state.mtotale+state.mtotali+state.mtotalh;
            bigscaletriggered = false;
            smallscaletriggered = false;
            ablasf.rallocv(1+mtotalall, ref state.tmpmrnrm, _params);
            ablasf.rallocv(1+mtotalall, ref state.tmpmrmultiply, _params);
            ablasf.rallocv(1+mtotalall, ref state.tmpmrset, _params);
            for(i=0; i<=mtotalall; i++)
            {
                nrm = Math.Max(state.xxbasefs[i], 1);
                nrm = Math.Min(nrm, maxscalerelativetoinitial*state.initwrkfscales[i]/state.wrkfscales[i]);
                multiplyby = 1.0;
                setscaleto = state.wrkfscales[i];
                if( i==0 || (state.srceihidx[i-1]>=0 && state.srceihidx[i-1]<state.mnlc) )
                {
                    if( (double)(nrm)>=(double)(state.fbigscale) )
                    {
                        v = Math.Min(nrm, maxrescale);
                        multiplyby = 1/v;
                        setscaleto = state.wrkfscales[i]*v;
                        bigscaletriggered = true;
                    }
                    if( (double)(nrm)<=(double)(state.fsmallscale) && (double)(state.wrkfscales[i])>(double)(1.0) )
                    {
                        v = Math.Max(nrm, minrescale);
                        if( (double)(state.wrkfscales[i]*v)>(double)(1) )
                        {
                            multiplyby = 1/v;
                            setscaleto = state.wrkfscales[i]*v;
                        }
                        else
                        {
                            multiplyby = state.wrkfscales[i];
                            setscaleto = 1.0;
                        }
                        smallscaletriggered = true;
                    }
                }
                state.tmpmrnrm[i] = nrm;
                state.tmpmrmultiply[i] = multiplyby;
                state.tmpmrset[i] = setscaleto;
            }
            state.solver.replywasrescale = bigscaletriggered || smallscaletriggered;
            ablasf.rsetv(1+mtotalall+state.nwrk, 1.0, state.solver.replyv, _params);
            if( !state.solver.replywasrescale )
            {
                return;
            }
            currente = 0;
            currenti = 0;
            currenth = 0;
            currentwrk = state.nraw;
            ablasf.rsetallocv(state.nwrk, 1.0, ref state.tmpmrmultiplyvars, _params);
            ablasf.rsetallocv(state.nwrk, 1.0, ref state.tmpmrmultiplycols, _params);
            state.solver.replyv[0] = state.tmpmrmultiply[0];
            offs = 0;
            for(i=0; i<=state.mnlc-1; i++)
            {
                if( (state.constrbucket[i]==-1 || state.constrbucket[i]==1) || state.constrbucket[i]==2 )
                {
                    continue;
                }
                if( state.constrbucket[i]==0 )
                {
                    alglib.ap.assert(state.srceihidx[offs]==i, "NLPGIPM: constraint structure mismatch (014932)");
                    vv = state.tmpmrmultiply[1+offs];
                    state.ceq[currente] = state.ceq[currente]*vv;
                    state.solver.replyv[1+offs] = vv;
                    currente = currente+1;
                    offs = offs+1;
                    continue;
                }
                if( state.constrbucket[i]==3 )
                {
                    alglib.ap.assert(state.srceihidx[offs]==i, "NLPGIPM: constraint structure mismatch (029939)");
                    alglib.ap.assert(state.srceqslkidx[offs]==currentwrk, "NLPGIPM: constraint structure mismatch (030940)");
                    alglib.ap.assert((double)(state.hardbcb[0*state.nwrk+currentwrk])==(double)(0.0), "NLPGIPM: constraint structure mismatch (031012)");
                    alglib.ap.assert((double)(state.hardbcb[1*state.nwrk+currentwrk])==(double)(0.0), "NLPGIPM: constraint structure mismatch (032013)");
                    vv = state.tmpmrmultiply[1+offs];
                    state.scaledbndl[currentwrk] = vv*state.scaledbndl[currentwrk];
                    state.scaledbndu[currentwrk] = vv*state.scaledbndu[currentwrk];
                    state.finitescaledbndl[currentwrk] = vv*state.finitescaledbndl[currentwrk];
                    state.finitescaledbndu[currentwrk] = vv*state.finitescaledbndu[currentwrk];
                    state.ceq[currente] = state.ceq[currente]*vv;
                    state.ch[state.hardbcfirstch+0*state.nwrk+currentwrk] = state.ch[state.hardbcfirstch+0*state.nwrk+currentwrk]*vv;
                    state.ch[state.hardbcfirstch+1*state.nwrk+currentwrk] = state.ch[state.hardbcfirstch+1*state.nwrk+currentwrk]*vv;
                    state.solver.replyv[1+offs] = vv;
                    state.solver.replyv[1+mtotalall+currentwrk] = vv;
                    state.tmpmrmultiplyvars[currentwrk] = vv;
                    state.tmpmrmultiplycols[currentwrk] = 1/vv;
                    currente = currente+1;
                    offs = offs+1;
                    currentwrk = currentwrk+1;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 044940 failed");
            }
            for(i=0; i<=state.mlc-1; i++)
            {
                if( (state.constrbucket[state.mnlc+i]==-1 || state.constrbucket[state.mnlc+i]==1) || state.constrbucket[state.mnlc+i]==2 )
                {
                    continue;
                }
                alglib.ap.assert((double)(state.tmpmrmultiply[1+offs])==(double)(1), "NLPGIPM: 048941 failed");
                if( state.constrbucket[state.mnlc+i]==0 )
                {
                    currente = currente+1;
                    offs = offs+1;
                    continue;
                }
                if( state.constrbucket[state.mnlc+i]==3 )
                {
                    currente = currente+1;
                    offs = offs+1;
                    currentwrk = currentwrk+1;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 064942 failed");
            }
            state.offsbce = offs;
            for(i=0; i<=state.cntfixed-1; i++)
            {
                currente = currente+1;
                offs = offs+1;
            }
            state.msofteqbc = state.cntfixed;
            for(i=0; i<=state.mnlc-1; i++)
            {
                if( ((state.constrbucket[i]==-1 || state.constrbucket[i]==0) || state.constrbucket[i]==2) || state.constrbucket[i]==3 )
                {
                    continue;
                }
                if( state.constrbucket[i]==1 )
                {
                    alglib.ap.assert(state.srceihidx[offs]==i, "NLPGIPM: constraint structure mismatch (083943)");
                    vv = state.tmpmrmultiply[1+offs];
                    state.ci[currenti] = state.ci[currenti]*vv;
                    state.solver.replyv[1+offs] = vv;
                    currenti = currenti+1;
                    offs = offs+1;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 091945 failed");
            }
            for(i=0; i<=state.mlc-1; i++)
            {
                if( ((state.constrbucket[state.mnlc+i]==-1 || state.constrbucket[state.mnlc+i]==0) || state.constrbucket[state.mnlc+i]==2) || state.constrbucket[state.mnlc+i]==3 )
                {
                    continue;
                }
                alglib.ap.assert((double)(state.tmpmrmultiply[1+offs])==(double)(1), "NLPGIPM: 095945 failed");
                if( state.constrbucket[state.mnlc+i]==1 )
                {
                    currenti = currenti+1;
                    offs = offs+1;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 651953 failed");
            }
            for(i=0; i<=state.mnlc-1; i++)
            {
                if( ((state.constrbucket[i]==-1 || state.constrbucket[i]==0) || state.constrbucket[i]==1) || state.constrbucket[i]==3 )
                {
                    continue;
                }
                if( state.constrbucket[i]==2 )
                {
                    alglib.ap.assert(state.srceihidx[offs]==i, "NLPGIPM: constraint structure mismatch (117947)");
                    vv = state.tmpmrmultiply[1+offs];
                    state.ch[currenth] = state.ch[currenth]*vv;
                    state.solver.replyv[1+offs] = vv;
                    currenth = currenth+1;
                    offs = offs+1;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 125948 failed");
            }
            for(i=0; i<=state.mlc-1; i++)
            {
                if( ((state.constrbucket[state.mnlc+i]==-1 || state.constrbucket[state.mnlc+i]==0) || state.constrbucket[state.mnlc+i]==1) || state.constrbucket[state.mnlc+i]==3 )
                {
                    continue;
                }
                alglib.ap.assert((double)(state.tmpmrmultiply[1+offs])==(double)(1), "NLPGIPM: 129948 failed");
                if( state.constrbucket[state.mnlc+i]==2 )
                {
                    currenth = currenth+1;
                    offs = offs+1;
                    continue;
                }
                alglib.ap.assert(false, "NLPGIPM: 138948 failed");
            }
            alglib.ap.assert(state.offshardbc==offs, "NLPGIPM: constraint structure mismatch (140949)");
            if( state.hasnonfixedbc )
            {
                for(i=0; i<=state.nwrk-1; i++)
                {
                    currenth = currenth+1;
                    offs = offs+1;
                }
                for(i=0; i<=state.nwrk-1; i++)
                {
                    currenth = currenth+1;
                    offs = offs+1;
                }
            }
            alglib.ap.assert(currente==state.mtotale, "NLPGIPM: constraint structure mismatch (161019)");
            alglib.ap.assert(currenti==state.mtotali, "NLPGIPM: constraint structure mismatch (162019)");
            alglib.ap.assert(currenth==state.mtotalh, "NLPGIPM: constraint structure mismatch (163019)");
            alglib.ap.assert(currentwrk==state.nwrk, "NLPGIPM: constraint structure mismatch (164019)");
            alglib.ap.assert(offs==mtotalall, "NLPGIPM: constraint structure mismatch (165019)");
            ablasf.rcopyv(1+mtotalall, state.tmpmrset, state.wrkfscales, _params);
            ablasf.rsetallocv(1+mtotalall, 1.0, ref state.invwrkfscales, _params);
            ablasf.rmergedivv(1+mtotalall, state.wrkfscales, state.invwrkfscales, _params);
            optserv.hessianmultiplyby(state.hess, state.tmpmrmultiply[0], _params);
            if( state.haslast )
            {
                ablasf.rmergemulv(state.nwrk, state.tmpmrmultiplyvars, state.lastx, _params);
                ablasf.rmergemulv(1+mtotalall, state.tmpmrmultiply, state.xxlastfi, _params);
                ablasf.rmergemulv(1+mtotalall, state.tmpmrmultiply, state.xxlastfs, _params);
                sparse.sparsemultiplyrowscolsby(state.xxlastsj, state.tmpmrmultiply, state.tmpmrmultiplycols, _params);
            }
            if( state.hasbase )
            {
                ablasf.rmergemulv(state.nwrk, state.tmpmrmultiplyvars, state.basex, _params);
                ablasf.rmergemulv(1+mtotalall, state.tmpmrmultiply, state.xxbasefi, _params);
                ablasf.rmergemulv(1+mtotalall, state.tmpmrmultiply, state.xxbasefs, _params);
                sparse.sparsemultiplyrowscolsby(state.xxbasesj, state.tmpmrmultiply, state.tmpmrmultiplycols, _params);
            }
            if( state.hasbest )
            {
                ablasf.rmergemulv(state.nwrk, state.tmpmrmultiplyvars, state.bestx, _params);
                ablasf.rmergemulv(1+mtotalall, state.tmpmrmultiply, state.xxbestfi, _params);
                ablasf.rmergemulv(1+mtotalall, state.tmpmrmultiply, state.xxbestfs, _params);
                sparse.sparsemultiplyrowscolsby(state.ccbestsj, state.tmpmrmultiply, state.tmpmrmultiplycols, _params);
            }
            state.hasbaseh = false;
            state.hasbasekkt = false;
        }


        /*************************************************************************
        Analyze sparsity pattern of KKT system and generate SparseSys; recompute
        if anything has changed.

          -- ALGLIB --
             Copyright 23.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void generatesparsesys(nlpgipm3state state,
            sparse.sparsematrix upcomingsj,
            alglib.xparams _params)
        {
            int nwrk = 0;
            int mtotalnonbc = 0;
            int i = 0;
            int j = 0;
            int offs = 0;
            int j0 = 0;
            int j1 = 0;
            int jj = 0;

            nwrk = state.nwrk;
            mtotalnonbc = state.mtotale+state.mtotali+state.mtotalh-state.mhardbc;
            alglib.ap.assert((sparse.sparseiscrs(upcomingsj, _params) && upcomingsj.m==mtotalnonbc+1) && upcomingsj.n==nwrk, "NLCGIPM: 484120");
            if( state.hassparsityanalyzed && sparse.sparsetrygatherclear(state.xxlastanalyzedjac, upcomingsj, _params) )
            {
                return;
            }
            if( state.hassparsityanalyzed )
            {
                sparse.sparsemergepatterns(state.xxlastanalyzedjac, upcomingsj, state.tmpsparse, _params);
                sparse.sparsecopybuf(state.tmpsparse, state.xxlastanalyzedjac, _params);
                if( !sparse.sparsetrygatherclear(state.xxlastanalyzedjac, upcomingsj, _params) )
                {
                    alglib.ap.assert(false, "NLCGIPM: integrity check 765614 failed");
                }
            }
            else
            {
                sparse.sparsecopybuf(upcomingsj, state.xxlastanalyzedjac, _params);
            }
            state.nonbcsparsesys.m = nwrk+mtotalnonbc+state.hessmaxrank;
            state.nonbcsparsesys.n = nwrk+mtotalnonbc+state.hessmaxrank;
            ablasf.iallocv(nwrk+state.hessmaxrank+mtotalnonbc+1, ref state.nonbcsparsesys.ridx, _params);
            state.nonbcsparsesys.ridx[0] = 0;
            offs = 0;
            ablasf.igrowv(offs+nwrk, ref state.nonbcsparsesys.idx, _params);
            ablasf.rgrowv(offs+nwrk, ref state.nonbcsparsesys.vals, _params);
            for(i=0; i<=nwrk-1; i++)
            {
                state.nonbcsparsesys.idx[offs] = i;
                state.nonbcsparsesys.vals[offs] = 0.0;
                offs = offs+1;
                state.nonbcsparsesys.ridx[i+1] = offs;
            }
            for(i=0; i<=mtotalnonbc-1; i++)
            {
                ablasf.igrowv(offs+nwrk+1, ref state.nonbcsparsesys.idx, _params);
                ablasf.rgrowv(offs+nwrk+1, ref state.nonbcsparsesys.vals, _params);
                j0 = state.xxlastanalyzedjac.ridx[1+i];
                j1 = state.xxlastanalyzedjac.ridx[1+i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    state.nonbcsparsesys.idx[offs] = state.xxlastanalyzedjac.idx[jj];
                    state.nonbcsparsesys.vals[offs] = 1.0;
                    offs = offs+1;
                }
                state.nonbcsparsesys.idx[offs] = nwrk+i;
                state.nonbcsparsesys.vals[offs] = 1.0;
                offs = offs+1;
                state.nonbcsparsesys.ridx[nwrk+i+1] = offs;
            }
            ablasf.igrowv(offs+state.hessmaxrank*(state.nnonlinear+1), ref state.nonbcsparsesys.idx, _params);
            ablasf.rgrowv(offs+state.hessmaxrank*(state.nnonlinear+1), ref state.nonbcsparsesys.vals, _params);
            for(i=0; i<=state.hessmaxrank-1; i++)
            {
                for(j=0; j<=state.nnonlinear-1; j++)
                {
                    state.nonbcsparsesys.idx[offs] = state.idxnonlinear[j];
                    state.nonbcsparsesys.vals[offs] = 0.0;
                    offs = offs+1;
                }
                state.nonbcsparsesys.idx[offs] = nwrk+mtotalnonbc+i;
                state.nonbcsparsesys.vals[offs] = 0.0;
                offs = offs+1;
                state.nonbcsparsesys.ridx[nwrk+mtotalnonbc+i+1] = offs;
            }
            sparse.sparsecreatecrsinplace(state.nonbcsparsesys, _params);
            ablasf.iallocv(nwrk+mtotalnonbc+state.hessmaxrank, ref state.priorities, _params);
            for(i=0; i<=nwrk-1; i++)
            {
                state.priorities[i] = 0;
            }
            for(i=nwrk; i<=mtotalnonbc+nwrk-1; i++)
            {
                state.priorities[i] = 0;
            }
            for(i=mtotalnonbc+nwrk; i<=state.hessmaxrank+mtotalnonbc+nwrk-1; i++)
            {
                state.priorities[i] = 2;
            }
            if( !spchol.spsymmanalyze(state.nonbcsparsesys, state.priorities, mupromote, 0, 1, 3, 1, state.nonbcanalysis, _params) )
            {
                alglib.ap.assert(false, "NLCGIPM2: critical integrity check failed, symbolically degenerate KKT system encountered");
            }
            state.hassparsityanalyzed = true;
        }


        /*************************************************************************
        Analyze sparsity pattern of LLS system and generate SparseLLSSys;
        recompute if anything has changed.

          -- ALGLIB --
             Copyright 23.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static void generatesparsellssys(nlpgipm3state state,
            sparse.sparsematrix upcomingsj,
            alglib.xparams _params)
        {
            int nwrk = 0;
            int mtotalnonbc = 0;
            int i = 0;
            int offs = 0;
            int j0 = 0;
            int j1 = 0;
            int jj = 0;

            nwrk = state.nwrk;
            mtotalnonbc = state.mtotale+state.mtotali+state.mtotalh-state.mhardbc;
            alglib.ap.assert((sparse.sparseiscrs(upcomingsj, _params) && upcomingsj.m==mtotalnonbc+1) && upcomingsj.n==nwrk, "NLCGIPM: 441242");
            if( state.hasllssparsityanalyzed && sparse.sparsetrygatherclear(state.xxlastanalyzedllsjac, upcomingsj, _params) )
            {
                return;
            }
            if( state.hasllssparsityanalyzed )
            {
                sparse.sparsemergepatterns(state.xxlastanalyzedllsjac, upcomingsj, state.tmpsparse, _params);
                sparse.sparsecopybuf(state.tmpsparse, state.xxlastanalyzedllsjac, _params);
                if( !sparse.sparsetrygatherclear(state.xxlastanalyzedllsjac, upcomingsj, _params) )
                {
                    alglib.ap.assert(false, "NLCGIPM: integrity check 765614 failed");
                }
            }
            else
            {
                sparse.sparsecopybuf(upcomingsj, state.xxlastanalyzedllsjac, _params);
            }
            state.nonbcsparsellssys.m = nwrk+mtotalnonbc;
            state.nonbcsparsellssys.n = nwrk+mtotalnonbc;
            ablasf.iallocv(nwrk+mtotalnonbc+1, ref state.nonbcsparsellssys.ridx, _params);
            state.nonbcsparsellssys.ridx[0] = 0;
            offs = 0;
            ablasf.igrowv(offs+nwrk, ref state.nonbcsparsellssys.idx, _params);
            ablasf.rgrowv(offs+nwrk, ref state.nonbcsparsellssys.vals, _params);
            for(i=0; i<=nwrk-1; i++)
            {
                state.nonbcsparsellssys.idx[offs] = i;
                state.nonbcsparsellssys.vals[offs] = 0.0;
                offs = offs+1;
                state.nonbcsparsellssys.ridx[i+1] = offs;
            }
            for(i=0; i<=mtotalnonbc-1; i++)
            {
                ablasf.igrowv(offs+nwrk+1, ref state.nonbcsparsellssys.idx, _params);
                ablasf.rgrowv(offs+nwrk+1, ref state.nonbcsparsellssys.vals, _params);
                j0 = state.xxlastanalyzedllsjac.ridx[1+i];
                j1 = state.xxlastanalyzedllsjac.ridx[1+i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    state.nonbcsparsellssys.idx[offs] = state.xxlastanalyzedllsjac.idx[jj];
                    state.nonbcsparsellssys.vals[offs] = 1.0;
                    offs = offs+1;
                }
                state.nonbcsparsellssys.idx[offs] = nwrk+i;
                state.nonbcsparsellssys.vals[offs] = 1.0;
                offs = offs+1;
                state.nonbcsparsellssys.ridx[nwrk+i+1] = offs;
            }
            sparse.sparsecreatecrsinplace(state.nonbcsparsellssys, _params);
            ablasf.isetallocv(nwrk+mtotalnonbc, 0, ref state.priorities, _params);
            if( !spchol.spsymmanalyze(state.nonbcsparsellssys, state.priorities, mupromote, 0, 1, 3, 1, state.nonbcanalysislls, _params) )
            {
                alglib.ap.assert(false, "NLCGIPM2: critical integrity check failed, symbolically degenerate KKT system encountered");
            }
            state.hasllssparsityanalyzed = true;
        }


        /*************************************************************************
        Appends a row from one sparse matrix to another one, skipping fixed elements
        and multiplying all other elements by ScaleBy. If ScaleBy=0, an empty row
        will be added.

        The target matrix can be 'empty CRS' which will be converted to a fully
        initialized CRS upon the very first call.

        Returns True if the row was successfully added; False if NAN/INF elements
        were found in Src[RowIdx]

          -- ALGLIB --
             Copyright 23.02.2025 by Bochkanov Sergey
        *************************************************************************/
        private static bool spaddscaledrowsubjecttofix(sparse.sparsematrix dst,
            sparse.sparsematrix src,
            int rowidx,
            double scaleby,
            bool[] isfixed,
            alglib.xparams _params)
        {
            bool result = new bool();
            int mdst = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int offs = 0;
            double v = 0;
            double vs = 0;

            result = true;
            mdst = dst.m;
            dst.matrixtype = 1;
            ablasf.igrowv(mdst+1, ref dst.didx, _params);
            ablasf.igrowv(mdst+1, ref dst.uidx, _params);
            ablasf.igrowv(mdst+1+1, ref dst.ridx, _params);
            if( (double)(scaleby)==(double)(0.0) )
            {
                dst.didx[mdst] = dst.ridx[mdst];
                dst.uidx[mdst] = dst.ridx[mdst];
                dst.ridx[mdst+1] = dst.ridx[mdst];
                dst.m = mdst+1;
                dst.ninitialized = dst.ridx[mdst+1];
                return result;
            }
            j0 = src.ridx[rowidx];
            j1 = src.ridx[rowidx+1]-1;
            ablasf.igrowv(dst.ridx[mdst]+j1-j0+1, ref dst.idx, _params);
            ablasf.rgrowv(dst.ridx[mdst]+j1-j0+1, ref dst.vals, _params);
            offs = dst.ridx[mdst];
            vs = 0;
            for(jj=j0; jj<=j1; jj++)
            {
                j = src.idx[jj];
                if( isfixed[j] )
                {
                    continue;
                }
                v = src.vals[jj];
                dst.idx[offs] = j;
                dst.vals[offs] = scaleby*v;
                vs = vs+v;
                offs = offs+1;
            }
            dst.ridx[mdst+1] = offs;
            dst.didx[mdst] = apserv.ibinarysearchlft(dst.idx, dst.ridx[mdst], dst.ridx[mdst+1], mdst, _params);
            dst.uidx[mdst] = dst.didx[mdst]+apserv.icase2(dst.didx[mdst]<dst.ridx[mdst+1] && dst.idx[dst.didx[mdst]]==mdst, 1, 0, _params);
            dst.m = mdst+1;
            dst.ninitialized = dst.ridx[mdst+1];
            result = math.isfinite(vs);
            return result;
        }


    }
