                _result.sparseefflc = sparseefflc!=null ? (sparse.sparsematrix)sparseefflc.make_copy() : null;
                _result.d0 = (double[])d0.Clone();
                _result.denseh = (double[,])denseh.Clone();
                _result.dummy1 = (double[])dummy1.Clone();
                _result.densedummy = (double[,])densedummy.Clone();
                _result.sparsedummy = sparsedummy!=null ? (sparse.sparsematrix)sparsedummy.make_copy() : null;
                _result.tmps = (double[])tmps.Clone();
