                tracegamma = new double[0];
                subsolver = new minsqpsubsolver();
                hess = new optserv.xbfgshessian();
                nonmonotonicmem = new ap.objarray();
                lagbcmult = new double[0];
                lagxcmult = new double[0];
                cand = new optserv.varsfuncjac();
                corr = new optserv.varsfuncjac();
                probe = new optserv.varsfuncjac();
                currentlinearization = new optserv.varsfuncjac();
                dtrial = new double[0];
                d0 = new double[0];
                d1 = new double[0];
                dmu = new double[0];
                tmppend = new double[0];
                tmphd = new double[0];
                dummylagbcmult = new double[0];
                dummylagxcmult = new double[0];
                tmplaggrad = new double[0];
                tmpcandlaggrad = new double[0];
                tmphdiag = new double[0];
                sclagtmp0 = new double[0];
                sclagtmp1 = new double[0];
