                timertotal = new apserv.stimer();
                timerqp = new apserv.stimer();
                timercallback = new apserv.stimer();
                rstate = new ap.rcommstate();
            }
            public override alglib.apobject make_copy()
            {
                minsqpstate _result = new minsqpstate();
                _result.n = n;
                _result.nec = nec;
                _result.nic = nic;
                _result.nlec = nlec;
