                _result.tracegamma = (double[])tracegamma.Clone();
                _result.subsolver = subsolver!=null ? (minsqpsubsolver)subsolver.make_copy() : null;
                _result.hess = hess!=null ? (optserv.xbfgshessian)hess.make_copy() : null;
                _result.nonmonotonicmem = nonmonotonicmem!=null ? (ap.objarray)nonmonotonicmem.make_copy() : null;
                _result.nonmonotoniccnt = nonmonotoniccnt;
                _result.lagbcmult = (double[])lagbcmult.Clone();
                _result.lagxcmult = (double[])lagxcmult.Clone();
                _result.cand = cand!=null ? (optserv.varsfuncjac)cand.make_copy() : null;
                _result.corr = corr!=null ? (optserv.varsfuncjac)corr.make_copy() : null;
                _result.probe = probe!=null ? (optserv.varsfuncjac)probe.make_copy() : null;
                _result.currentlinearization = currentlinearization!=null ? (optserv.varsfuncjac)currentlinearization.make_copy() : null;
                _result.dtrial = (double[])dtrial.Clone();
                _result.d0 = (double[])d0.Clone();
                _result.d1 = (double[])d1.Clone();
                _result.dmu = (double[])dmu.Clone();
                _result.tmppend = (double[])tmppend.Clone();
                _result.tmphd = (double[])tmphd.Clone();
                _result.dummylagbcmult = (double[])dummylagbcmult.Clone();
                _result.dummylagxcmult = (double[])dummylagxcmult.Clone();
                _result.tmplaggrad = (double[])tmplaggrad.Clone();
                _result.tmpcandlaggrad = (double[])tmpcandlaggrad.Clone();
                _result.tmphdiag = (double[])tmphdiag.Clone();
                _result.sclagtmp0 = (double[])sclagtmp0.Clone();
                _result.sclagtmp1 = (double[])sclagtmp1.Clone();
                _result.mftmp0 = (double[])mftmp0.Clone();
                _result.repiterationscount = repiterationscount;
                _result.repterminationtype = repterminationtype;
                _result.repbcerr = repbcerr;
                _result.repbcidx = repbcidx;
                _result.replcerr = replcerr;
                _result.replcidx = replcidx;
                _result.repnlcerr = repnlcerr;
                _result.repnlcidx = repnlcidx;
                _result.timertotal = timertotal!=null ? (apserv.stimer)timertotal.make_copy() : null;
                _result.timerqp = timerqp!=null ? (apserv.stimer)timerqp.make_copy() : null;
                _result.timercallback = timercallback!=null ? (apserv.stimer)timercallback.make_copy() : null;
                _result.rstate = rstate!=null ? (ap.rcommstate)rstate.make_copy() : null;
                return _result;
            }
        };




        public const double sqpdeltadecrease = 0.50;
        public const double sqpdeltaincrease = 0.99;
        public const double maxtrustraddecay = 0.1;
        public const double deftrustradgrowth = 1.41;
        public const double maxtrustradgrowth = 10.0;
        public const double momentumgrowth = 2;
        public const double maxmeritmu = 1.0E5;
        public const double augmentationfactor = 0.0;
        public const double inittrustrad = 0.1;
        public const double stagnationepsf = 1.0E-12;
        public const int fstagnationlimit = 20;
        public const int trustradstagnationlimit = 10;
        public const double sqpbigscale = 5.0;
        public const double sqpsmallscale = 0.2;
        public const double sqpmaxrescale = 10.0;
        public const double sqpminrescale = 0.1;
        public const int defaultbfgsresetfreq = 999999;
        public const double sufficientdecreasesigma = 0.001;
        public const double meritmueps = 0.15;
        public const int xbfgsmemlen = 8;
        public const double xbfgsmaxhess = 1.0E6;
        public const int nonmonotoniclen = 3;
        public const double constraintsstagnationeps = 1.0E-5;


        public static void minsqpinitbuf(double[] bndl,
            double[] bndu,
            double[] s,
            double[] x0,
            int n,
            double[,] cleic,
            int[] lcsrcidx,
            int nec,
            int nic,
            int nlec,
            int nlic,
            optserv.nlpstoppingcriteria criteria,
            bool usedensebfgs,
            minsqpstate state,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            double v = 0;
            double vv = 0;
            int nslack = 0;

            nslack = n+2*(nec+nlec)+(nic+nlic);
            state.n = n;
            state.nec = nec;
            state.nic = nic;
            state.nlec = nlec;
            state.nlic = nlic;
            
            //
            // Prepare RCOMM state
            //
            state.rstate.ia = new int[9+1];
            state.rstate.ba = new bool[14+1];
            state.rstate.ra = new double[23+1];
            state.rstate.stage = -1;
            state.rstate.clear_handler();
            state.needfij = false;
            state.xupdated = false;
            state.x = new double[n];
            state.fi = new double[1+nlec+nlic];
            state.j = new double[1+nlec+nlic, n];
            
            //
            // Allocate memory.
            //
            ablasf.rallocv(n, ref state.x0, _params);
            ablasf.rallocv(n, ref state.xprev, _params);
            apserv.rvectorsetlengthatleast(ref state.s, n, _params);
            apserv.rvectorsetlengthatleast(ref state.fscales, 1+nlec+nlic, _params);
            apserv.rvectorsetlengthatleast(ref state.tracegamma, 1+nlec+nlic, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndl, n, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndu, n, _params);
            apserv.rvectorsetlengthatleast(ref state.scaledbndl, n, _params);
            apserv.rvectorsetlengthatleast(ref state.scaledbndu, n, _params);
            apserv.rmatrixsetlengthatleast(ref state.scaledcleic, nec+nic, n+1, _params);
            apserv.ivectorsetlengthatleast(ref state.lcsrcidx, nec+nic, _params);
            apserv.rvectorsetlengthatleast(ref state.dtrial, nslack, _params);
            apserv.rvectorsetlengthatleast(ref state.d0, nslack, _params);
            apserv.rvectorsetlengthatleast(ref state.d1, nslack, _params);
            apserv.rvectorsetlengthatleast(ref state.dmu, nslack, _params);
            apserv.rvectorsetlengthatleast(ref state.lagbcmult, n, _params);
            apserv.rvectorsetlengthatleast(ref state.dummylagbcmult, n, _params);
            apserv.rvectorsetlengthatleast(ref state.lagxcmult, nec+nic+nlec+nlic, _params);
            apserv.rvectorsetlengthatleast(ref state.dummylagxcmult, nec+nic+nlec+nlic, _params);
            
            //
            // Prepare scaled problem
            //
            for(i=0; i<=n-1; i++)
            {
                state.hasbndl[i] = math.isfinite(bndl[i]);
                state.hasbndu[i] = math.isfinite(bndu[i]);
                if( state.hasbndl[i] )
                {
                    state.scaledbndl[i] = bndl[i]/s[i];
                }
                if( state.hasbndu[i] )
                {
                    state.scaledbndu[i] = bndu[i]/s[i];
                }
                if( state.hasbndl[i] && state.hasbndu[i] )
                {
                    alglib.ap.assert((double)(bndl[i])<=(double)(bndu[i]), "SQP: integrity check failed, box constraints are inconsistent");
                }
                state.x0[i] = x0[i]/s[i];
                state.s[i] = s[i];
            }
            for(i=0; i<=nec+nic-1; i++)
            {
                
                //
                // Permutation
                //
                state.lcsrcidx[i] = lcsrcidx[i];
                
                //
                // Scale and normalize linear constraints
                //
                vv = 0.0;
                for(j=0; j<=n-1; j++)
                {
                    v = cleic[i,j]*s[j];
                    state.scaledcleic[i,j] = v;
                    vv = vv+v*v;
                }
                vv = Math.Sqrt(vv);
                state.scaledcleic[i,n] = cleic[i,n];
                if( (double)(vv)>(double)(0) )
                {
                    for(j=0; j<=n; j++)
                    {
                        state.scaledcleic[i,j] = state.scaledcleic[i,j]/vv;
                    }
                }
            }
            
            //
            // Initial enforcement of box constraints
            //
            for(i=0; i<=n-1; i++)
            {
                if( state.hasbndl[i] )
                {
                    state.x0[i] = Math.Max(state.x0[i], state.scaledbndl[i]);
                }
                if( state.hasbndu[i] )
                {
                    state.x0[i] = Math.Min(state.x0[i], state.scaledbndu[i]);
                }
            }
            
            //
            // Stopping criteria and settings
            //
            optserv.critcopy(criteria, state.criteria, _params);
            state.bfgsresetfreq = defaultbfgsresetfreq;
            state.usedensebfgs = usedensebfgs;
            
            //
            // Report fields
            //
            state.repterminationtype = 0;
            state.repbcerr = 0;
            state.repbcidx = -1;
            state.replcerr = 0;
            state.replcidx = -1;
            state.repnlcerr = 0;
            state.repnlcidx = -1;
            state.repiterationscount = 0;
            
            //
            // Integrity checks
            //
            alglib.ap.assert((double)(sqpdeltadecrease)<(double)(sqpdeltaincrease), "MinSQP: integrity check failed");
        }


        /*************************************************************************
        This function performs actual processing for  SQP  algorithm.  It  expects
        that caller redirects its reverse communication  requests NeedFiJ/XUpdated
        to external user who will provide analytic derivative (or  handle  reports
        about progress).

        In case external user does not have analytic derivative, it is responsibility
        of caller to intercept NeedFiJ request and  replace  it  with  appropriate
        numerical differentiation scheme.

        Results are stored:
        * point - in State.StepKX

        IMPORTANT: this function works with scaled problem formulation; it is
                   responsibility of the caller to unscale request and scale
                   Jacobian.
                   
        NOTE: SMonitor is expected to be correctly initialized smoothness monitor.

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        public static bool minsqpiteration(minsqpstate state,
            optserv.smoothnessmonitor smonitor,
            bool userterminationneeded,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int nslack = 0;
            int nec = 0;
            int nic = 0;
            int nlec = 0;
            int nlic = 0;
            int i = 0;
            int j = 0;
            double v = 0;
            double vv = 0;
            double mx = 0;
            double deltamax = 0;
            double multiplyby = 0;
            double setscaleto = 0;
            double prevtrustrad = 0;
            int subiterationidx = 0;
            bool trustradstagnated = new bool();
            double relativetargetdecrease = 0;
            bool dotrace = new bool();
            bool doprobingalways = new bool();
            bool doprobingonfailure = new bool();
            bool dodetailedtrace = new bool();
            bool increasemeritmu = new bool();
            bool meritfstagnated = new bool();
            double f0 = 0;
            double f0raw = 0;
            double f1 = 0;
            double tol = 0;
            double stepklagval = 0;
            double stepknlagval = 0;
            double expandedrad = 0;
            bool socperformed = new bool();
            double d2trustradratio = 0;
            int didx = 0;
            double sksk = 0;
            double ykyk = 0;
            double skyk = 0;
            double sumc1 = 0;
            double sumc1soc = 0;
            double predictedchange = 0;
            double predictedchangemodel = 0;
            double predictedchangepenalty = 0;
            bool meritdecreasefailed = new bool();
            bool stepperformed = new bool();
            bool goodstep = new bool();
            bool firstrescale = new bool();
            bool infinitiesdetected = new bool();
            bool failedtorecoverfrominfinities = new bool();
            bool needsoc = new bool();

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rstate.stage>=0 )
            {
                n = state.rstate.ia[0];
                nslack = state.rstate.ia[1];
                nec = state.rstate.ia[2];
                nic = state.rstate.ia[3];
                nlec = state.rstate.ia[4];
                nlic = state.rstate.ia[5];
                i = state.rstate.ia[6];
                j = state.rstate.ia[7];
                subiterationidx = state.rstate.ia[8];
                didx = state.rstate.ia[9];
                trustradstagnated = state.rstate.ba[0];
                dotrace = state.rstate.ba[1];
                doprobingalways = state.rstate.ba[2];
                doprobingonfailure = state.rstate.ba[3];
                dodetailedtrace = state.rstate.ba[4];
                increasemeritmu = state.rstate.ba[5];
                meritfstagnated = state.rstate.ba[6];
                socperformed = state.rstate.ba[7];
                meritdecreasefailed = state.rstate.ba[8];
                stepperformed = state.rstate.ba[9];
                goodstep = state.rstate.ba[10];
                firstrescale = state.rstate.ba[11];
                infinitiesdetected = state.rstate.ba[12];
                failedtorecoverfrominfinities = state.rstate.ba[13];
                needsoc = state.rstate.ba[14];
                v = state.rstate.ra[0];
                vv = state.rstate.ra[1];
                mx = state.rstate.ra[2];
                deltamax = state.rstate.ra[3];
                multiplyby = state.rstate.ra[4];
                setscaleto = state.rstate.ra[5];
                prevtrustrad = state.rstate.ra[6];
                relativetargetdecrease = state.rstate.ra[7];
                f0 = state.rstate.ra[8];
                f0raw = state.rstate.ra[9];
                f1 = state.rstate.ra[10];
                tol = state.rstate.ra[11];
                stepklagval = state.rstate.ra[12];
                stepknlagval = state.rstate.ra[13];
                expandedrad = state.rstate.ra[14];
                d2trustradratio = state.rstate.ra[15];
                sksk = state.rstate.ra[16];
                ykyk = state.rstate.ra[17];
                skyk = state.rstate.ra[18];
                sumc1 = state.rstate.ra[19];
                sumc1soc = state.rstate.ra[20];
                predictedchange = state.rstate.ra[21];
                predictedchangemodel = state.rstate.ra[22];
                predictedchangepenalty = state.rstate.ra[23];
            }
            else
            {
                n = 359;
                nslack = -58;
                nec = -919;
                nic = -909;
                nlec = 81;
                nlic = 255;
                i = 74;
                j = -788;
                subiterationidx = 809;
                didx = 205;
                trustradstagnated = false;
                dotrace = true;
                doprobingalways = false;
                doprobingonfailure = true;
                dodetailedtrace = true;
                increasemeritmu = false;
                meritfstagnated = false;
                socperformed = false;
                meritdecreasefailed = false;
                stepperformed = false;
                goodstep = true;
                firstrescale = false;
                infinitiesdetected = true;
                failedtorecoverfrominfinities = true;
                needsoc = false;
                v = 346.0;
                vv = -722.0;
                mx = -413.0;
                deltamax = -461.0;
                multiplyby = 927.0;
                setscaleto = 201.0;
                prevtrustrad = 922.0;
                relativetargetdecrease = -154.0;
                f0 = 306.0;
                f0raw = -1011.0;
                f1 = 951.0;
                tol = -463.0;
                stepklagval = 88.0;
                stepknlagval = -861.0;
                expandedrad = -678.0;
                d2trustradratio = -731.0;
                sksk = -675.0;
                ykyk = -763.0;
                skyk = -233.0;
                sumc1 = -936.0;
                sumc1soc = -279.0;
                predictedchange = 94.0;
                predictedchangemodel = -812.0;
                predictedchangepenalty = 427.0;
            }
            if( state.rstate.stage==0 )
            {
                goto lbl_0;
            }
            if( state.rstate.stage==1 )
            {
                goto lbl_1;
            }
            if( state.rstate.stage==2 )
            {
                goto lbl_2;
            }
            if( state.rstate.stage==3 )
            {
                goto lbl_3;
            }
            if( state.rstate.stage==4 )
            {
                goto lbl_4;
            }
            if( state.rstate.stage==5 )
            {
                goto lbl_5;
            }
            
            //
            // Routine body
            //
            n = state.n;
            nec = state.nec;
            nic = state.nic;
            nlec = state.nlec;
            nlic = state.nlic;
            nslack = n+2*(nec+nlec)+(nic+nlic);
            dotrace = ap.istraceenabled("SQP", _params) && !ap.istraceenabled("SQP.LACONIC", _params);
            dodetailedtrace = dotrace && ap.istraceenabled("SQP.DETAILED", _params);
            doprobingalways = dotrace && ap.istraceenabled("SQP.PROBING", _params);
            doprobingonfailure = dotrace && ap.istraceenabled("SQP.PROBINGONFAILURE", _params);
            
            //
            // Prepare rcomm interface
            //
            state.needfij = false;
            state.xupdated = false;
            
            //
            // Prepare debug timers
            //
            apserv.stimerinit(state.timertotal, _params);
            apserv.stimerinit(state.timerqp, _params);
            apserv.stimerinit(state.timercallback, _params);
            apserv.stimerstart(state.timertotal, _params);
            
            //
            // Initialize algorithm data:
            // * Lagrangian and "Big C" estimates
            // * trust region
            // * initial function scales (vector of 1's)
            // * current approximation of the Hessian matrix H (unit matrix)
            // * initial linearized constraints
            // * initial violation of linear/nonlinear constraints
            //
            state.fstagnationcnt = 0;
            state.trustradstagnationcnt = 0;
            state.trustrad = inittrustrad;
            state.trustradgrowth = deftrustradgrowth;
            for(i=0; i<=nlec+nlic; i++)
            {
                state.fscales[i] = 1.0;
                state.tracegamma[i] = 0.0;
            }
            state.nonmonotonicmem.clear();
            state.nonmonotoniccnt = 0;
            
            //
            // Evaluate function vector and Jacobian at X0, send first location report.
            // Compute initial violation of constraints.
            //
            optserv.vfjallocdense(n, 1+nlec+nlic, state.stepk, _params);
            optserv.vfjallocdense(n, 1+nlec+nlic, state.cand, _params);
            optserv.vfjallocdense(n, 1+nlec+nlic, state.corr, _params);
            optserv.vfjallocdense(n, 1+nlec+nlic, state.probe, _params);
            optserv.vfjallocdense(n, 1+nlec+nlic, state.currentlinearization, _params);
            ablasf.rcopyv(n, state.x0, state.stepk.x, _params);
            sqpsendx(state, state.stepk.x, _params);
            state.needfij = true;
            if( dotrace )
            {
                apserv.stimerstart(state.timercallback, _params);
            }
            state.rstate.stage = 0;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
            if( dotrace )
            {
                apserv.stimerstop(state.timercallback, _params);
            }
            state.needfij = false;
            if( !sqpretrievefij(state, state.stepk, _params) )
            {
                
                //
                // Failed to retrieve function/Jacobian, infinities detected!
                //
                state.repterminationtype = -8;
                result = false;
                return result;
            }
            sqpsendx(state, state.stepk.x, _params);
            state.f = state.stepk.fi[0]*state.fscales[0];
            state.xupdated = true;
            state.rstate.stage = 1;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            state.xupdated = false;
            optserv.checklcviolation(state.scaledcleic, state.lcsrcidx, nec, nic, state.stepk.x, n, ref state.replcerr, ref state.replcidx, _params);
