            else
            {
                optserv.smoothnessmonitorstartlagrangianprobing(smonitor, state.stepk.x, state.d1, 1.0, state.repiterationscount, -1, _params);
            }
        lbl_17:
            if( !optserv.smoothnessmonitorprobelagrangian(smonitor, _params) )
            {
                goto lbl_18;
            }
            for(j=0; j<=n-1; j++)
            {
                state.probe.x[j] = smonitor.lagprobx[j];
                if( state.hasbndl[j] )
                {
                    state.probe.x[j] = Math.Max(state.probe.x[j], state.scaledbndl[j]);
                }
                if( state.hasbndu[j] )
                {
                    state.probe.x[j] = Math.Min(state.probe.x[j], state.scaledbndu[j]);
                }
            }
            sqpsendx(state, state.probe.x, _params);
            state.needfij = true;
            if( dotrace )
            {
                apserv.stimerstart(state.timercallback, _params);
            }
            state.rstate.stage = 4;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_4:
            if( dotrace )
            {
                apserv.stimerstop(state.timercallback, _params);
            }
            state.needfij = false;
            if( !sqpretrievefij(state, state.probe, _params) )
            {
                goto lbl_18;
            }
            ablasf.rcopyallocv(1+nlec+nlic, state.probe.fi, ref smonitor.lagprobfi, _params);
            ablasf.rcopyallocm(1+nlec+nlic, n, state.probe.jac, ref smonitor.lagprobj, _params);
            smonitor.lagprobrawlag = rawlagrangian(state, state.probe.x, state.probe.fi, state.lagbcmult, state.lagxcmult, state.meritmu, _params);
            goto lbl_17;
        lbl_18:
            alglib.ap.trace("*** ------------------------------------------------------------\n");
            alglib.ap.trace("*** |                 probing search direction                 |\n");
            if( didx==0 )
            {
                alglib.ap.trace("*** |          suggested by first-order QP subproblem          |\n");
            }
            if( didx==1 )
            {
                alglib.ap.trace("*** |          suggested by second-order QP subproblem         |\n");
            }
            alglib.ap.trace("*** ------------------------------------------------------------\n");
            alglib.ap.trace("*** |  Step  | Lagrangian (unaugmentd)|    Target  function    |\n");
            alglib.ap.trace("*** |along  D|     must be smooth     |     must be smooth     |\n");
            alglib.ap.trace("*** |        | function   |    slope  | function   |    slope  |\n");
            optserv.smoothnessmonitortracelagrangianprobingresults(smonitor, _params);
            didx = didx+1;
            goto lbl_14;
        lbl_16:
        lbl_12:
            
            //
            // Output other information
            //
            mx = 0;
            for(i=0; i<=n-1; i++)
            {
                mx = Math.Max(mx, Math.Abs(state.dtrial[i])/gettrustregionk(state.stepk.x, i, state.trustrad, _params));
            }
            if( stepperformed && goodstep )
            {
                alglib.ap.trace("> sufficient decrease step was performed\n");
            }
            else
            {
                if( stepperformed )
                {
                    alglib.ap.trace("> nonmonotonic step was performed\n");
                }
                else
                {
                    alglib.ap.trace("> no step was performed\n");
                }
            }
            alglib.ap.trace(System.String.Format("max(|Di|)/TrustRad = {0,0:F6}\n", mx));
            if( dodetailedtrace )
            {
                alglib.ap.trace("LagBoxMlt   = ");
                apserv.tracevectorautoprec(state.lagbcmult, 0, n, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace("LagNonBoxMlt= ");
                apserv.tracevectorautoprec(state.lagxcmult, 0, nec+nic+nlec+nlic, _params);
                alglib.ap.trace("\n");
            }
            if( dodetailedtrace )
            {
                alglib.ap.trace("X0 (scaled) = ");
                apserv.tracevectorautoprec(state.stepk.x, 0, n, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace("D  (scaled) = ");
                apserv.tracevectorautoprec(state.dtrial, 0, n, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace("X1 (scaled) = ");
                apserv.tracevectorautoprec(state.cand.x, 0, n, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace("\n");
                alglib.ap.trace("grad F(X0)  = ");
                apserv.tracerowautoprec(state.stepk.jac, 0, 0, n, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace("grad F(X1)  = ");
                apserv.tracerowautoprec(state.cand.jac, 0, 0, n, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace("\n");
                alglib.ap.trace("grad L(X0)  = ");
                apserv.tracevectorautoprec(state.tmplaggrad, 0, n, _params);
                alglib.ap.trace("\n");
                alglib.ap.trace("grad L(X1)  = ");
                apserv.tracevectorautoprec(state.tmpcandlaggrad, 0, n, _params);
                alglib.ap.trace("\n");
            }
            alglib.ap.trace(System.String.Format("targetF:        {0,17:E9} -> {1,17:E9} (delta={2,11:E3})\n", state.fscales[0]*state.stepk.fi[0], state.fscales[0]*state.cand.fi[0], state.fscales[0]*(state.cand.fi[0]-state.stepk.fi[0])));
            alglib.ap.trace(System.String.Format("scaled-meritF:  {0,17:E9} -> {1,17:E9} (delta={2,11:E3})\n", f0, f1, f1-f0));
            alglib.ap.trace(System.String.Format("scaled-targetF: {0,17:E9} -> {1,17:E9} (delta={2,11:E3})\n", state.stepk.fi[0], state.cand.fi[0], state.cand.fi[0]-state.stepk.fi[0]));
            alglib.ap.trace(System.String.Format("max|lag-grad|:  {0,17:E9} -> {1,17:E9}\n", ablasf.rmaxabsv(n, state.tmplaggrad, _params), ablasf.rmaxabsv(n, state.tmpcandlaggrad, _params)));
            alglib.ap.trace(System.String.Format("nrm2|lag-grad|: {0,17:E9} -> {1,17:E9} (ratio={2,0:F6})\n", Math.Sqrt(ablasf.rdotv2(n, state.tmplaggrad, _params)), Math.Sqrt(ablasf.rdotv2(n, state.tmpcandlaggrad, _params)), Math.Sqrt(ablasf.rdotv2(n, state.tmpcandlaggrad, _params))/Math.Sqrt(ablasf.rdotv2(n, state.tmplaggrad, _params))));
            optserv.hessiangetdiagonal(state.hess, ref state.tmphdiag, _params);
            v = state.tmphdiag[0];
            for(i=0; i<=n-1; i++)
            {
                v = Math.Min(v, state.tmphdiag[i]);
            }
            alglib.ap.trace(System.String.Format("mindiag(Bk) = {0,0:E3}\n", v));
            v = state.tmphdiag[0];
            for(i=0; i<=n-1; i++)
            {
                v = Math.Max(v, state.tmphdiag[i]);
            }
            alglib.ap.trace(System.String.Format("maxdiag(Bk) = {0,0:E3}\n", v));
        lbl_10:
            
            //
            // Move to new point
            //
            if( !stepperformed )
            {
                goto lbl_19;
            }
            
            //
            // Save current point to the nonmonotonic memory buffer
            //
            nonmonotonicsave(state, state.cand, _params);
            
            //
            // Update current state
            //
            optserv.vfjcopy(state.cand, state.stepk, _params);
            failedtorecoverfrominfinities = false;
            
            //
            // Report one more inner iteration
            //
            sqpsendx(state, state.stepk.x, _params);
            state.f = state.stepk.fi[0]*state.fscales[0];
            state.xupdated = true;
            state.rstate.stage = 5;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_5:
            state.xupdated = false;
            
            //
            // Update constraint violations
            //
            optserv.checklcviolation(state.scaledcleic, state.lcsrcidx, nec, nic, state.stepk.x, n, ref state.replcerr, ref state.replcidx, _params);
            optserv.unscaleandchecknlcviolation(state.stepk.fi, state.fscales, nlec, nlic, ref state.repnlcerr, ref state.repnlcidx, _params);
        lbl_19:
            
            //
            // Update MeritMu
            //
            if( increasemeritmu )
            {
                state.meritmu = Math.Min(2*state.meritmu, maxmeritmu);
            }
            
            //
            // Update trust region.
            //
            // NOTE: when trust region radius remains fixed for a long time it may mean that we 
            //       stagnated in eternal loop. In such cases we decrease it slightly in order
            //       to break possible loop. If such decrease was unnecessary, it may be easily
            //       fixed within few iterations.
            //
            trustradstagnated = false;
            prevtrustrad = state.trustrad;
            deltamax = 0;
            for(i=0; i<=n-1; i++)
            {
                deltamax = Math.Max(deltamax, Math.Abs(state.xprev[i]-state.stepk.x[i])/gettrustregionk(state.xprev, i, state.trustrad, _params));
            }
            apserv.inc(ref state.trustradstagnationcnt, _params);
            if( (double)(deltamax)<=(double)(sqpdeltadecrease) )
            {
                state.trustrad = state.trustrad*Math.Max(deltamax/sqpdeltadecrease, maxtrustraddecay);
            }
            if( (double)(deltamax)>=(double)(sqpdeltaincrease) && goodstep )
            {
                state.trustrad = state.trustrad*state.trustradgrowth;
                optserv.trustradincreasemomentum(ref state.trustradgrowth, momentumgrowth, maxtrustradgrowth, _params);
            }
            else
            {
                optserv.trustradresetmomentum(ref state.trustradgrowth, deftrustradgrowth, _params);
            }
            if( (double)(state.trustrad)<(double)(0.99*prevtrustrad) || (double)(state.trustrad)>(double)(1.01*prevtrustrad) )
            {
                state.trustradstagnationcnt = 0;
            }
            if( state.trustradstagnationcnt>=trustradstagnationlimit )
            {
                state.trustrad = 0.5*state.trustrad;
                state.trustradstagnationcnt = 0;
                trustradstagnated = true;
            }
            
            //
            // Trace
            //
            if( dotrace )
            {
                alglib.ap.trace("\n--- outer iteration ends ---------------------------------------------------------------------------\n");
                alglib.ap.trace(System.String.Format("deltaMax    = {0,0:F3} (ratio of step length to trust radius)\n", deltamax));
                alglib.ap.trace(System.String.Format("newTrustRad = {0,0:E3}", state.trustrad));
                if( !trustradstagnated )
                {
                    if( (double)(state.trustrad)>(double)(prevtrustrad) )
                    {
                        alglib.ap.trace(", trust radius increased");
                    }
                    if( (double)(state.trustrad)<(double)(prevtrustrad) )
                    {
                        alglib.ap.trace(", trust radius decreased");
                    }
                }
                else
                {
                    alglib.ap.trace(System.String.Format(", trust radius forcibly decreased due to stagnation for {0,0:d} iterations", trustradstagnationlimit));
                }
                alglib.ap.trace("\n");
                if( increasemeritmu )
                {
                    alglib.ap.trace(System.String.Format("meritMu     = {0,0:E3} (increasing)\n", state.meritmu));
                }
            }
            
            //
            // Advance outer iteration counter
            //
            apserv.inc(ref state.repiterationscount, _params);
            state.fstagnationcnt = apserv.icase2(meritfstagnated, state.fstagnationcnt+1, 0, _params);
            goto lbl_6;
        lbl_7:
            
            //
            // Almost done
            //
            if( infinitiesdetected )
            {
                state.repterminationtype = apserv.icase2(failedtorecoverfrominfinities, -8, state.repterminationtype+800, _params);
            }
            if( dotrace )
            {
                apserv.stimerstop(state.timertotal, _params);
                alglib.ap.trace("\n=== STOPPED ========================================================================================\n");
                if( infinitiesdetected && failedtorecoverfrominfinities )
                {
                    alglib.ap.trace("> infinities were detected, but we failed to recover by decreasing trust radius; declaring failure with code -8\n");
                }
                alglib.ap.trace(System.String.Format("raw target:     {0,20:E12}\n", state.stepk.fi[0]*state.fscales[0]));
                alglib.ap.trace(System.String.Format("total time:     {0,10:F1} ms\n", apserv.stimergetms(state.timertotal, _params)));
                alglib.ap.trace(System.String.Format("* incl cbck:    {0,10:F1} ms\n", apserv.stimergetms(state.timercallback, _params)));
                alglib.ap.trace(System.String.Format("* incl QP:      {0,10:F1} ms\n", apserv.stimergetms(state.timerqp, _params)));
            }
            optserv.smoothnessmonitortracestatus(smonitor, dotrace, _params);
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rstate.ia[0] = n;
            state.rstate.ia[1] = nslack;
            state.rstate.ia[2] = nec;
            state.rstate.ia[3] = nic;
            state.rstate.ia[4] = nlec;
            state.rstate.ia[5] = nlic;
            state.rstate.ia[6] = i;
            state.rstate.ia[7] = j;
            state.rstate.ia[8] = subiterationidx;
            state.rstate.ia[9] = didx;
            state.rstate.ba[0] = trustradstagnated;
            state.rstate.ba[1] = dotrace;
            state.rstate.ba[2] = doprobingalways;
            state.rstate.ba[3] = doprobingonfailure;
            state.rstate.ba[4] = dodetailedtrace;
            state.rstate.ba[5] = increasemeritmu;
            state.rstate.ba[6] = meritfstagnated;
            state.rstate.ba[7] = socperformed;
            state.rstate.ba[8] = meritdecreasefailed;
            state.rstate.ba[9] = stepperformed;
            state.rstate.ba[10] = goodstep;
            state.rstate.ba[11] = firstrescale;
            state.rstate.ba[12] = infinitiesdetected;
            state.rstate.ba[13] = failedtorecoverfrominfinities;
            state.rstate.ba[14] = needsoc;
            state.rstate.ra[0] = v;
            state.rstate.ra[1] = vv;
            state.rstate.ra[2] = mx;
            state.rstate.ra[3] = deltamax;
            state.rstate.ra[4] = multiplyby;
            state.rstate.ra[5] = setscaleto;
            state.rstate.ra[6] = prevtrustrad;
            state.rstate.ra[7] = relativetargetdecrease;
            state.rstate.ra[8] = f0;
            state.rstate.ra[9] = f0raw;
            state.rstate.ra[10] = f1;
            state.rstate.ra[11] = tol;
            state.rstate.ra[12] = stepklagval;
            state.rstate.ra[13] = stepknlagval;
            state.rstate.ra[14] = expandedrad;
            state.rstate.ra[15] = d2trustradratio;
            state.rstate.ra[16] = sksk;
            state.rstate.ra[17] = ykyk;
            state.rstate.ra[18] = skyk;
            state.rstate.ra[19] = sumc1;
            state.rstate.ra[20] = sumc1soc;
            state.rstate.ra[21] = predictedchange;
            state.rstate.ra[22] = predictedchangemodel;
            state.rstate.ra[23] = predictedchangepenalty;
            return result;
        }


        /*************************************************************************
        This function initializes SQP subproblem.
        Should be called once in the beginning of the optimization.

        INPUT PARAMETERS:
            SState          -   solver state
            Subsolver       -   SQP subproblem to initialize
                                
                                
        RETURN VALUE:
            True on success
            False on failure of the QP solver (unexpected... but possible due to numerical errors)
                                

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        private static void initqpsubsolver(minsqpstate sstate,
            minsqpsubsolver subsolver,
            alglib.xparams _params)
        {
            int n = 0;
            int nslack = 0;
            int nec = 0;
            int nic = 0;
            int nlec = 0;
            int nlic = 0;
            int lccnt = 0;
            int nnz = 0;
            int offs = 0;
            int i = 0;
            int j = 0;

            n = sstate.n;
            nec = sstate.nec;
            nic = sstate.nic;
            nlec = sstate.nlec;
            nlic = sstate.nlic;
            nslack = n+2*(nec+nlec)+(nic+nlic);
            lccnt = nec+nic+nlec+nlic;
            
            //
            // Allocate temporaries
            //
            apserv.rvectorsetlengthatleast(ref subsolver.cural, lccnt, _params);
            apserv.rvectorsetlengthatleast(ref subsolver.curau, lccnt, _params);
            apserv.rvectorsetlengthatleast(ref subsolver.curbndl, nslack, _params);
            apserv.rvectorsetlengthatleast(ref subsolver.curbndu, nslack, _params);
            apserv.rvectorsetlengthatleast(ref subsolver.curb, nslack, _params);
            
            //
            // Linear constraints do not change across subiterations, that's
            // why we allocate storage for them at the start of the program.
            //
            // A full set of "raw" constraints is stored; later we will filter
            // out inequality ones which are inactive anywhere in the current
            // trust region.
            //
            // NOTE: because sparserawlc object stores only linear constraint
            //       (linearizations of nonlinear ones are not stored) we
            //       allocate only minimum necessary space.
            //
            nnz = 0;
            for(i=0; i<=nec+nic-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    if( sstate.scaledcleic[i,j]!=0.0 )
                    {
                        nnz = nnz+1;
                    }
                }
            }
            apserv.ivectorsetlengthatleast(ref subsolver.sparserawlc.ridx, nec+nic+1, _params);
            apserv.rvectorsetlengthatleast(ref subsolver.sparserawlc.vals, nnz, _params);
            apserv.ivectorsetlengthatleast(ref subsolver.sparserawlc.idx, nnz, _params);
            apserv.ivectorsetlengthatleast(ref subsolver.sparserawlc.didx, nec+nic, _params);
            apserv.ivectorsetlengthatleast(ref subsolver.sparserawlc.uidx, nec+nic, _params);
            offs = 0;
            subsolver.sparserawlc.ridx[0] = 0;
            for(i=0; i<=nec+nic-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    if( sstate.scaledcleic[i,j]!=0.0 )
                    {
                        
                        //
                        // Primary part of the matrix
                        //
                        subsolver.sparserawlc.vals[offs] = sstate.scaledcleic[i,j];
                        subsolver.sparserawlc.idx[offs] = j;
                        offs = offs+1;
                    }
                }
                subsolver.sparserawlc.ridx[i+1] = offs;
            }
            subsolver.sparserawlc.matrixtype = 1;
            subsolver.sparserawlc.ninitialized = subsolver.sparserawlc.ridx[nec+nic];
            subsolver.sparserawlc.m = nec+nic;
            subsolver.sparserawlc.n = n;
            sparse.sparseinitduidx(subsolver.sparserawlc, _params);
        }


        /*************************************************************************
        This function solves QP subproblem given by initial point X, function vector Fi
        and Jacobian Jac, and returns:
        * search direction D[]
        * estimates of Lagrangian multipliers
        * predicted change in the quadratic model of the target, and in the L1-penalty
          added to the model

        Additionally returns SumC1 - a sum of absolute errors AT THE BEGINNING of
        the step (this quantity is used to choose appropriate penalty parameter;
        it corresponds to |Ck|_1 at Nocedal and Wright, 'Numerical optimization' 2006,
        chapter 18, formula 18.33).

        The QP subproblem linear and quadratic terms are multiplied by the scalar
        multipliers AlphaG and AlphaH, which can be:
        * (1,1) when we want to compute a step direction
        * (0,0) when we want to compute best possible improvement in the linearized
           constraints over the trust region
        * (1,0) when we want to compute Lagrange multipliers using linearized model
          of the target instead of the quadratic one

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        private static bool qpsubproblemsolve(minsqpstate state,
            minsqpsubsolver subsolver,
            double[] x,
            double[] fi,
            double[,] jac,
            optserv.xbfgshessian hess,
            double alphag,
            double alphah,
            double[] d,
            double[] lagbcmult,
            double[] lagxcmult,
            bool dotrace,
            ref int terminationtype,
            ref double predictedchangemodel,
            ref double predictedchangepenalty,
            ref double sumc1,
            ref double d2trustradratio,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int nslack = 0;
            int nec = 0;
            int nic = 0;
            int nlec = 0;
            int nlic = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            double v = 0;
            double vv = 0;
            double vright = 0;
            double vmax = 0;
            int lccnt = 0;
            int offsslackec = 0;
            int offsslacknlec = 0;
            int offsslackic = 0;
            int offsslacknlic = 0;
            int offs = 0;
            int nnz = 0;
            int j0 = 0;
            int j1 = 0;
            double rescaleby = 0;

            terminationtype = 0;
            predictedchangemodel = 0;
            predictedchangepenalty = 0;
            sumc1 = 0;
            d2trustradratio = 0;

            alglib.ap.assert((double)(alphag)==(double)(0) || (double)(alphag)==(double)(1), "QPSubproblemSolve: AlphaG is neither 0 nor 1");
            alglib.ap.assert((double)(alphah)==(double)(0) || (double)(alphah)==(double)(1), "QPSubproblemSolve: AlphaH is neither 0 nor 1");
            n = state.n;
            nec = state.nec;
            nic = state.nic;
            nlec = state.nlec;
            nlic = state.nlic;
            nslack = n+2*(nec+nlec)+(nic+nlic);
            lccnt = nec+nic+nlec+nlic;
            
            //
            // Locations of slack variables
            //
            offsslackec = n;
            offsslacknlec = n+2*nec;
            offsslackic = n+2*nec+2*nlec;
            offsslacknlic = n+2*(nec+nlec)+nic;
            
            //
            // Prepare temporary structures
            //
            apserv.rvectorgrowto(ref subsolver.cural, lccnt, _params);
            apserv.rvectorgrowto(ref subsolver.curau, lccnt, _params);
            apserv.rvectorsetlengthatleast(ref subsolver.d0, nslack, _params);
            ablasf.rallocv(lccnt, ref subsolver.rescalelag, _params);
            
            //
            // Prepare default solution: all zeros
            //
            result = true;
            terminationtype = 0;
            sumc1 = 0;
            predictedchangemodel = 0;
            predictedchangepenalty = 0;
            d2trustradratio = 0.0;
            for(i=0; i<=nslack-1; i++)
            {
                d[i] = 0.0;
                subsolver.d0[i] = 0;
            }
            ablasf.rsetv(n, 0.0, lagbcmult, _params);
            ablasf.rsetv(lccnt, 0.0, lagxcmult, _params);
            
            //
            // Linear term B
            //
            // NOTE: elements [N,NSlack) are equal to MeritMu + perturbation to improve numeric properties of QP problem
            //
            for(i=0; i<=n-1; i++)
            {
                subsolver.curb[i] = alphag*jac[0,i];
            }
            for(i=n; i<=nslack-1; i++)
            {
                subsolver.curb[i] = state.meritmu;
            }
            
            //
            // Trust radius constraints for primary variables
            //
            ablasf.bsetallocv(n, false, ref subsolver.retainnegativebclm, _params);
            ablasf.bsetallocv(n, false, ref subsolver.retainpositivebclm, _params);
            for(i=0; i<=n-1; i++)
            {
                subsolver.curbndl[i] = -gettrustregionk(x, i, state.trustrad, _params);
                subsolver.curbndu[i] = gettrustregionk(x, i, state.trustrad, _params);
                if( state.hasbndl[i] && (double)(state.scaledbndl[i]-x[i])>(double)(subsolver.curbndl[i]) )
                {
                    subsolver.curbndl[i] = state.scaledbndl[i]-x[i];
                    subsolver.retainnegativebclm[i] = true;
                }
                if( state.hasbndu[i] && (double)(state.scaledbndu[i]-x[i])<(double)(subsolver.curbndu[i]) )
                {
                    subsolver.curbndu[i] = state.scaledbndu[i]-x[i];
                    subsolver.retainpositivebclm[i] = true;
                }
            }
            
            //
            // Prepare storage for "effective" constraining matrix
            //
            nnz = subsolver.sparserawlc.ridx[nec+nic];
            for(i=0; i<=nlec+nlic-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    if( jac[1+i,j]!=0.0 )
                    {
                        nnz = nnz+1;
                    }
                }
            }
            nnz = nnz+2*nec+nic;
            nnz = nnz+2*nlec+nlic;
            apserv.ivectorgrowto(ref subsolver.sparseefflc.ridx, lccnt+1, _params);
            apserv.rvectorgrowto(ref subsolver.sparseefflc.vals, nnz, _params);
            apserv.ivectorgrowto(ref subsolver.sparseefflc.idx, nnz, _params);
            apserv.ivectorsetlengthatleast(ref subsolver.sparseefflc.didx, lccnt, _params);
            apserv.ivectorsetlengthatleast(ref subsolver.sparseefflc.uidx, lccnt, _params);
            subsolver.sparseefflc.m = 0;
            subsolver.sparseefflc.n = nslack;
            subsolver.sparseefflc.matrixtype = 1;
            
            //
            // Append linear equality/inequality constraints
            //
            // Scan sparsified linear constraints stored in sparserawlc[], skip ones
            // which are inactive anywhere in the trust region.
            //
            apserv.rvectorsetlengthatleast(ref subsolver.tmp0, nslack, _params);
            for(i=0; i<=n-1; i++)
            {
                subsolver.tmp0[i] = x[i];
            }
            for(i=n; i<=nslack-1; i++)
            {
                subsolver.tmp0[i] = 0;
            }
            for(i=0; i<=nec+nic-1; i++)
            {
                
                //
                // Calculate:
                // * VRight - product of X[] (extended with zeros up to NSlack elements)
                //            and AR[i] - Ith row of sparserawlc matrix.
                // * VMax   - maximum value of X*ARi computed over trust region
                //
                vright = 0;
                vmax = 0;
                j0 = subsolver.sparserawlc.ridx[i];
                j1 = subsolver.sparserawlc.ridx[i+1]-1;
                for(k=j0; k<=j1; k++)
                {
                    j = subsolver.sparserawlc.idx[k];
                    v = x[j];
                    vv = subsolver.sparserawlc.vals[k];
                    vright = vright+vv*v;
                    if( vv>=0 )
                    {
                        vmax = vmax+vv*(v+subsolver.curbndu[j]);
                    }
                    else
                    {
                        vmax = vmax+vv*(v+subsolver.curbndl[j]);
                    }
                }
                
                //
                // Linear constraints are passed 'as is', without additional rescaling
                //
                subsolver.rescalelag[i] = 1.0;
                
                //
                // If constraint is an inequality one and guaranteed to be inactive
                // within trust region, it is skipped (the row itself is retained but
                // filled by zeros).
                //
                if( i>=nec && vmax<=state.scaledcleic[i,n] )
                {
                    offs = subsolver.sparseefflc.ridx[i];
                    subsolver.sparseefflc.vals[offs] = -1;
                    subsolver.sparseefflc.idx[offs] = offsslackic+(i-nec);
                    subsolver.sparseefflc.ridx[i+1] = offs+1;
                    subsolver.cural[i] = 0.0;
                    subsolver.curau[i] = 0.0;
                    subsolver.curbndl[offsslackic+(i-nec)] = 0;
                    subsolver.curbndu[offsslackic+(i-nec)] = 0;
                    subsolver.rescalelag[i] = 0.0;
                    continue;
                }
                
                //
                // Start working on row I
                //
                offs = subsolver.sparseefflc.ridx[i];
                
                //
                // Copy constraint from sparserawlc[] to sparseefflc[]
                //
                j0 = subsolver.sparserawlc.ridx[i];
                j1 = subsolver.sparserawlc.ridx[i+1]-1;
                for(k=j0; k<=j1; k++)
                {
                    subsolver.sparseefflc.idx[offs] = subsolver.sparserawlc.idx[k];
                    subsolver.sparseefflc.vals[offs] = subsolver.sparserawlc.vals[k];
                    offs = offs+1;
                }
                
                //
                // Set up slack variables
                //
                if( i<nec )
                {
                    subsolver.sparseefflc.vals[offs+0] = -1;
                    subsolver.sparseefflc.vals[offs+1] = 1;
                    subsolver.sparseefflc.idx[offs+0] = offsslackec+2*i+0;
                    subsolver.sparseefflc.idx[offs+1] = offsslackec+2*i+1;
                    offs = offs+2;
                }
                else
                {
                    
                    //
                    // Slack variables for inequality constraints
                    //
                    subsolver.sparseefflc.vals[offs] = -1;
                    subsolver.sparseefflc.idx[offs] = offsslackic+(i-nec);
                    offs = offs+1;
                }
                
                //
                // Finalize row
                //
                subsolver.sparseefflc.ridx[i+1] = offs;
                
                //
                // Set up bounds and slack part of D0.
                //
                // NOTE: bounds for equality and inequality constraints are
                //       handled differently
                //
                v = vright-state.scaledcleic[i,n];
                if( i<nec )
                {
                    sumc1 = sumc1+Math.Abs(v);
                    subsolver.cural[i] = -v;
                    subsolver.curau[i] = -v;
                    subsolver.curbndl[offsslackec+2*i+0] = 0;
                    subsolver.curbndl[offsslackec+2*i+1] = 0;
                    subsolver.curbndu[offsslackec+2*i+0] = Math.Abs(v);
                    subsolver.curbndu[offsslackec+2*i+1] = Math.Abs(v);
                    if( (double)(v)>=(double)(0) )
                    {
                        subsolver.d0[offsslackec+2*i+0] = Math.Abs(v);
                        subsolver.d0[offsslackec+2*i+1] = 0;
                    }
                    else
                    {
                        subsolver.d0[offsslackec+2*i+0] = 0;
                        subsolver.d0[offsslackec+2*i+1] = Math.Abs(v);
                    }
                }
                else
                {
                    sumc1 = sumc1+Math.Max(v, 0.0);
                    subsolver.cural[i] = Double.NegativeInfinity;
                    subsolver.curau[i] = -v;
                    subsolver.curbndl[offsslackic+(i-nec)] = 0;
                    subsolver.curbndu[offsslackic+(i-nec)] = Math.Max(v, 0);
                    subsolver.d0[offsslackic+(i-nec)] = Math.Max(v, 0);
                }
            }
            subsolver.sparseefflc.m = subsolver.sparseefflc.m+(nec+nic);
            
            //
            // Append nonlinear equality/inequality constraints
            //
            for(i=0; i<=nlec+nlic-1; i++)
            {
                
                //
                // Calculate:
                // * rescale coefficient used to normalize constraints
                // * VMax - maximum of constraint value over trust region
                //
                vmax = fi[1+i];
                vv = 0;
                for(j=0; j<=n-1; j++)
                {
                    v = jac[1+i,j];
                    vv = vv+v*v;
                    if( v>=0 )
                    {
                        vmax = vmax+v*subsolver.curbndu[j];
                    }
                    else
                    {
                        vmax = vmax+v*subsolver.curbndl[j];
                    }
                }
                rescaleby = 1/apserv.coalesce(Math.Sqrt(vv), 1, _params);
                
                //
                // Nonlinear constraints are passed with normalization
                //
                subsolver.rescalelag[nec+nic+i] = rescaleby;
                
                //
                // If constraint is an inequality one and guaranteed to be inactive
                // within trust region, it is skipped (row itself is retained but
                // filled by zeros).
                //
                if( i>=nlec && vmax<=0.0 )
                {
                    offs = subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i];
                    subsolver.sparseefflc.vals[offs] = -1;
                    subsolver.sparseefflc.idx[offs] = offsslacknlic+(i-nlec);
                    subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i+1] = offs+1;
                    subsolver.cural[subsolver.sparseefflc.m+i] = 0.0;
                    subsolver.curau[subsolver.sparseefflc.m+i] = 0.0;
                    subsolver.curbndl[offsslacknlic+(i-nlec)] = 0.0;
                    subsolver.curbndu[offsslacknlic+(i-nlec)] = 0.0;
                    subsolver.d0[offsslacknlic+(i-nlec)] = 0.0;
                    subsolver.rescalelag[nec+nic+i] = 0.0;
                    continue;
                }
                
                //
                // Copy scaled row
                //
                offs = subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i];
                for(j=0; j<=n-1; j++)
                {
                    if( jac[1+i,j]!=0.0 )
                    {
                        subsolver.sparseefflc.vals[offs] = rescaleby*jac[1+i,j];
                        subsolver.sparseefflc.idx[offs] = j;
                        offs = offs+1;
                    }
                }
                if( i<nlec )
                {
                    
                    //
                    // Add slack terms for equality constraints
                    //
                    subsolver.sparseefflc.vals[offs+0] = -1;
                    subsolver.sparseefflc.vals[offs+1] = 1;
                    subsolver.sparseefflc.idx[offs+0] = offsslacknlec+2*i+0;
                    subsolver.sparseefflc.idx[offs+1] = offsslacknlec+2*i+1;
                    offs = offs+2;
                }
                else
                {
                    
                    //
                    // Add slack terms for inequality constraints
                    //
                    subsolver.sparseefflc.vals[offs] = -1;
                    subsolver.sparseefflc.idx[offs] = offsslacknlic+(i-nlec);
                    offs = offs+1;
                }
                subsolver.sparseefflc.ridx[subsolver.sparseefflc.m+i+1] = offs;
                
                //
                // Set box constraints on slack variables and bounds on linear equality/inequality constraints
                //
                v = rescaleby*fi[1+i];
                if( i<nlec )
                {
                    
                    //
                    // Equality constraint
                    //
                    sumc1 = sumc1+Math.Abs(fi[1+i]);
                    subsolver.cural[subsolver.sparseefflc.m+i] = -v;
                    subsolver.curau[subsolver.sparseefflc.m+i] = -v;
                    subsolver.curbndl[offsslacknlec+2*i+0] = 0;
                    subsolver.curbndl[offsslacknlec+2*i+1] = 0;
                    subsolver.curbndu[offsslacknlec+2*i+0] = Math.Abs(v);
                    subsolver.curbndu[offsslacknlec+2*i+1] = Math.Abs(v);
                    if( (double)(v)>=(double)(0) )
                    {
                        subsolver.d0[offsslacknlec+2*i+0] = Math.Abs(v);
                        subsolver.d0[offsslacknlec+2*i+1] = 0;
                    }
                    else
                    {
                        subsolver.d0[offsslacknlec+2*i+0] = 0;
                        subsolver.d0[offsslacknlec+2*i+1] = Math.Abs(v);
                    }
                }
                else
                {
                    
                    //
                    // Inequality constraint
                    //
                    sumc1 = sumc1+Math.Max(fi[1+i], 0.0);
                    subsolver.cural[subsolver.sparseefflc.m+i] = Double.NegativeInfinity;
                    subsolver.curau[subsolver.sparseefflc.m+i] = -v;
                    subsolver.curbndl[offsslacknlic+(i-nlec)] = 0;
                    subsolver.curbndu[offsslacknlic+(i-nlec)] = Math.Max(v, 0);
                    subsolver.d0[offsslacknlic+(i-nlec)] = Math.Max(v, 0);
                }
            }
            subsolver.sparseefflc.m = subsolver.sparseefflc.m+(nlec+nlic);
            
            //
            // Finalize sparse matrix structure
            //
            alglib.ap.assert(subsolver.sparseefflc.ridx[subsolver.sparseefflc.m]<=alglib.ap.len(subsolver.sparseefflc.idx), "QPSubproblemSolve: critical integrity check failed");
            alglib.ap.assert(subsolver.sparseefflc.ridx[subsolver.sparseefflc.m]<=alglib.ap.len(subsolver.sparseefflc.vals), "QPSubproblemSolve: critical integrity check failed");
            subsolver.sparseefflc.ninitialized = subsolver.sparseefflc.ridx[subsolver.sparseefflc.m];
            sparse.sparseinitduidx(subsolver.sparseefflc, _params);
            
            //
            // Solve quadratic program with IPM.
            //
            // We always treat its result as a valid solution, even for TerminationType<=0.
            // In case anything is wrong with solution vector, we will detect it during line
            // search phase (merit function does not increase).
            //
            // NOTE: because we cleaned up constraints that are DEFINITELY inactive within
            //       trust region, we do not have to worry about StopOnExcessiveBounds option.
            //
            ablasf.rsetallocv(nslack, state.trustrad, ref subsolver.tmps, _params);
            for(i=0; i<=n-1; i++)
            {
                subsolver.tmps[i] = gettrustregionk(x, i, state.trustrad, _params);
            }
            ablasf.rsetallocv(nslack, 0.0, ref subsolver.tmporigin, _params);
            if( dotrace )
            {
                apserv.stimerstart(state.timerqp, _params);
            }
            if( state.usedensebfgs )
            {
                
                //
                // Dense BFGS is used to generate a quasi-Newton matrix,
                // dense IPM is used to solve QP subproblems.
                //
                optserv.hessiangetmatrix(hess, true, ref subsolver.denseh, _params);
                for(i=0; i<=n-1; i++)
                {
                    ablasf.rmulr(n, alphah, subsolver.denseh, i, _params);
                }
                vipmsolver.vipminitdensewithslacks(subsolver.ipmsolver, subsolver.tmps, subsolver.tmporigin, n, nslack, true, _params);
                vipmsolver.vipmsetquadraticlinear(subsolver.ipmsolver, subsolver.denseh, subsolver.sparsedummy, 0, true, subsolver.curb, _params);
                vipmsolver.vipmsetconstraints(subsolver.ipmsolver, subsolver.curbndl, subsolver.curbndu, subsolver.sparseefflc, subsolver.sparseefflc.m, subsolver.densedummy, 0, subsolver.cural, subsolver.curau, _params);
                vipmsolver.vipmoptimize(subsolver.ipmsolver, false, ref subsolver.tmp0, ref subsolver.tmp1, ref subsolver.tmp2, ref terminationtype, _params);
            }
            else
            {
                
                //
                // Low-rank quasi-Newton matrix with positive-only corrections is used,
                // sparse IPM with low-rank updates is used to solve QP subproblems.
                //
                optserv.hessiangetlowrankstabilized(hess, ref subsolver.tmpdiag, ref subsolver.tmpcorrc, ref subsolver.hesscorrd, ref subsolver.hessrank, _params);
                alglib.ap.assert((double)(alphah)==(double)(0) || (double)(alphah)==(double)(1), "QPSubproblemSolve: AlphaH is neither 0 nor 1");
                subsolver.hesssparsediag.matrixtype = 1;
                subsolver.hesssparsediag.m = nslack;
                subsolver.hesssparsediag.n = nslack;
                ablasf.iallocv(nslack+1, ref subsolver.hesssparsediag.ridx, _params);
                ablasf.iallocv(nslack, ref subsolver.hesssparsediag.idx, _params);
                ablasf.rallocv(nslack, ref subsolver.hesssparsediag.vals, _params);
                subsolver.hesssparsediag.ridx[0] = 0;
                for(i=0; i<=nslack-1; i++)
                {
                    subsolver.hesssparsediag.idx[i] = i;
                    subsolver.hesssparsediag.vals[i] = 0.0;
                    subsolver.hesssparsediag.ridx[i+1] = i+1;
                }
                ablasf.raddv(n, alphah, subsolver.tmpdiag, subsolver.hesssparsediag.vals, _params);
                sparse.sparsecreatecrsinplace(subsolver.hesssparsediag, _params);
                if( subsolver.hessrank>0 )
                {
                    ablasf.rsetallocm(subsolver.hessrank, nslack, 0.0, ref subsolver.hesscorrc, _params);
                    if( (double)(alphah)!=(double)(0) )
                    {
                        ablasf.rcopym(subsolver.hessrank, n, subsolver.tmpcorrc, subsolver.hesscorrc, _params);
                    }
                }
                ipm2solver.ipm2init(subsolver.ipm2, subsolver.tmps, subsolver.tmporigin, nslack, subsolver.densedummy, subsolver.hesssparsediag, 1, true, subsolver.hesscorrc, subsolver.hesscorrd, subsolver.hessrank, subsolver.curb, 0.0, subsolver.curbndl, subsolver.curbndu, subsolver.sparseefflc, subsolver.sparseefflc.m, subsolver.densedummy, 0, subsolver.cural, subsolver.curau, false, false, _params);
                ipm2solver.ipm2optimize(subsolver.ipm2, false, ref subsolver.tmp0, ref subsolver.tmp1, ref subsolver.tmp2, ref terminationtype, _params);
            }
            if( dotrace )
            {
                apserv.stimerstop(state.timerqp, _params);
            }
            
            //
            // Unpack results
            //
            ablasf.rcopyv(nslack, subsolver.tmp0, d, _params);
            for(i=0; i<=n-1; i++)
            {
                lagbcmult[i] = 0;
                if( subsolver.retainpositivebclm[i] && (double)(subsolver.tmp1[i])>(double)(0) )
                {
                    lagbcmult[i] = subsolver.tmp1[i];
                }
                if( subsolver.retainnegativebclm[i] && (double)(subsolver.tmp1[i])<(double)(0) )
                {
                    lagbcmult[i] = subsolver.tmp1[i];
                }
            }
            ablasf.rcopyv(lccnt, subsolver.tmp2, lagxcmult, _params);
            ablasf.rmergemulv(lccnt, subsolver.rescalelag, lagxcmult, _params);
            
            //
            // Compute predicted decrease in an L1-penalized quadratic model
            //
            predictedchangemodel = ablasf.rdotv(n, d, subsolver.curb, _params)+0.5*optserv.hessianvmv(hess, d, _params);
            predictedchangepenalty = 0;
            for(i=0; i<=nec+nic-1; i++)
            {
                v = ablasf.rdotvr(n, x, state.scaledcleic, i, _params)-state.scaledcleic[i,n];
                vv = v+ablasf.rdotvr(n, d, state.scaledcleic, i, _params);
                predictedchangepenalty = predictedchangepenalty+apserv.rcase2(i<nec, Math.Abs(vv)-Math.Abs(v), Math.Max(vv, 0)-Math.Max(v, 0), _params);
            }
            for(i=0; i<=nlec+nlic-1; i++)
            {
                v = fi[1+i];
                vv = v+ablasf.rdotvr(n, d, jac, 1+i, _params);
                predictedchangepenalty = predictedchangepenalty+apserv.rcase2(i<nlec, Math.Abs(vv)-Math.Abs(v), Math.Max(vv, 0)-Math.Max(v, 0), _params);
            }
            
            //
            // Analyze length of D
            //
            alglib.ap.assert((double)(d2trustradratio)==(double)(0.0), "SQP: integrity check 0157 failed");
            for(i=0; i<=n-1; i++)
            {
                d2trustradratio = Math.Max(d2trustradratio, Math.Abs(d[i]/gettrustregionk(x, i, state.trustrad, _params)));
            }
            return result;
        }


        /*************************************************************************
        Copies X to State.X
        *************************************************************************/
        private static void sqpsendx(minsqpstate state,
            double[] xs,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            n = state.n;
            for(i=0; i<=n-1; i++)
            {
                if( state.hasbndl[i] && xs[i]<=state.scaledbndl[i] )
                {
                    state.x[i] = state.scaledbndl[i];
                    continue;
                }
                if( state.hasbndu[i] && xs[i]>=state.scaledbndu[i] )
                {
                    state.x[i] = state.scaledbndu[i];
                    continue;
                }
                state.x[i] = xs[i];
            }
        }


        /*************************************************************************
        Retrieves F-vector and scaled Jacobian, copies them to FiS and JS.

        Returns True on success, False on failure (when F or J are not finite numbers).
        *************************************************************************/
        private static bool sqpretrievefij(minsqpstate state,
            optserv.varsfuncjac vfj,
            alglib.xparams _params)
        {
            bool result = new bool();
            int nlec = 0;
            int nlic = 0;
            int n = 0;
            int i = 0;
            int j = 0;
            double v = 0;
            double vv = 0;

            n = state.n;
            nlec = state.nlec;
            nlic = state.nlic;
            v = 0;
            for(i=0; i<=nlec+nlic; i++)
            {
                vv = 1/state.fscales[i];
                vfj.fi[i] = vv*state.fi[i];
                v = v+vfj.fi[i];
                for(j=0; j<=n-1; j++)
                {
                    vfj.jac[i,j] = vv*state.j[i,j];
                    v = v+vfj.jac[i,j];
                }
            }
            result = math.isfinite(v);
            return result;
        }


        /*************************************************************************
        This function calculates Lagrangian of the problem (in scaled variables):
        its value and gradient.

        Additionally it also estimates violation of linear constraints at the point
        as well as index of the most violated constraint
        *************************************************************************/
        private static void lagrangianfg(minsqpstate state,
            double[] x,
            double trustrad,
            double[] fi,
            double[,] j,
            double[] lagbcmult,
            double[] lagxcmult,
            bool uselagrangeterms,
            ref double f,
            double[] g,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;
            int nec = 0;
            int nic = 0;
            int nlec = 0;
            int nlic = 0;
            double v = 0;
            double vlag = 0;
            double vact = 0;
            double vd = 0;
            bool usesparsegemv = new bool();
            double lagalpha = 0;

            f = 0;

            n = state.n;
            nec = state.nec;
            nic = state.nic;
            nlec = state.nlec;
            nlic = state.nlic;
            lagalpha = apserv.rcase2(uselagrangeterms, 1, 0, _params);
            
            //
            // Target function
            //
            f = fi[0];
            for(i=0; i<=n-1; i++)
            {
                g[i] = j[0,i];
            }
            
            //
            // Lagrangian terms for box constraints
            //
            for(i=0; i<=n-1; i++)
            {
                
                //
                // Lagrangian terms
                //
                f = f+lagalpha*lagbcmult[i]*x[i];
                g[i] = g[i]+lagalpha*lagbcmult[i];
                
                //
                // Penalty term
                //
                if( state.hasbndl[i] && (double)(x[i])<(double)(state.scaledbndl[i]) )
                {
                    f = f+augmentationfactor*(x[i]-state.scaledbndl[i])*(x[i]-state.scaledbndl[i]);
                    g[i] = g[i]+2*augmentationfactor*(x[i]-state.scaledbndl[i]);
                }
                if( state.hasbndu[i] && (double)(x[i])>(double)(state.scaledbndu[i]) )
                {
                    f = f+augmentationfactor*(x[i]-state.scaledbndu[i])*(x[i]-state.scaledbndu[i]);
                    g[i] = g[i]+2*augmentationfactor*(x[i]-state.scaledbndu[i]);
                }
            }
            
            //
            // Lagrangian terms for linear constraints, constraint violations
            //
            if( nec+nic>0 )
            {
                usesparsegemv = state.subsolver.sparserawlc.ridx[nec+nic]<apserv.sparselevel2density(_params)*n*(nec+nic);
                apserv.rvectorsetlengthatleast(ref state.sclagtmp0, Math.Max(nec+nic, n), _params);
                apserv.rvectorsetlengthatleast(ref state.sclagtmp1, Math.Max(nec+nic, n), _params);
                if( usesparsegemv )
                {
                    sparse.sparsemv(state.subsolver.sparserawlc, x, ref state.sclagtmp0, _params);
                }
                else
                {
                    ablas.rmatrixgemv(nec+nic, n, 1.0, state.scaledcleic, 0, 0, 0, x, 0, 0.0, state.sclagtmp0, 0, _params);
                }
                for(i=0; i<=nec+nic-1; i++)
                {
                    
                    //
                    // Prepare
                    //
                    v = state.sclagtmp0[i]-state.scaledcleic[i,n];
                    vlag = lagalpha*lagxcmult[i];
                    state.sclagtmp1[i] = 0;
                    
                    //
                    // Primary Lagrangian term
                    //
                    vact = v;
                    vd = 1;
                    f = f+vlag*vact;
                    state.sclagtmp1[i] = state.sclagtmp1[i]+vlag*vd;
                    
                    //
                    // Quadratic augmentation term
                    //
                    if( i<nec || v>0 )
                    {
                        vact = v;
                    }
                    else
                    {
                        vact = 0;
                    }
                    f = f+0.5*augmentationfactor*vact*vact;
                    state.sclagtmp1[i] = state.sclagtmp1[i]+augmentationfactor*vact;
                }
                if( usesparsegemv )
                {
                    sparse.sparsemtv(state.subsolver.sparserawlc, state.sclagtmp1, ref state.sclagtmp0, _params);
                    for(i=0; i<=n-1; i++)
                    {
                        g[i] = g[i]+state.sclagtmp0[i];
                    }
                }
                else
                {
                    ablas.rmatrixgemv(n, nec+nic, 1.0, state.scaledcleic, 0, 0, 1, state.sclagtmp1, 0, 1.0, g, 0, _params);
                }
            }
            
            //
            // Lagrangian terms for nonlinear constraints
            //
            apserv.rvectorsetlengthatleast(ref state.sclagtmp1, nlec+nlic, _params);
            for(i=0; i<=nlec+nlic-1; i++)
            {
                v = fi[1+i];
                vlag = lagalpha*lagxcmult[nec+nic+i];
                state.sclagtmp1[i] = 0;
                
                //
                // Lagrangian term
                //
                vact = v;
                vd = 1;
                f = f+vlag*vact;
                state.sclagtmp1[i] = state.sclagtmp1[i]+vlag*vd;
                
                //
                // Augmentation term
                //
                if( i<nlec || v>0 )
                {
                    vact = v;
                }
                else
                {
                    vact = 0;
                }
                f = f+0.5*augmentationfactor*vact*vact;
                state.sclagtmp1[i] = state.sclagtmp1[i]+augmentationfactor*vact;
            }
            ablas.rmatrixgemv(n, nlec+nlic, 1.0, j, 1, 0, 1, state.sclagtmp1, 0, 1.0, g, 0, _params);
        }


        /*************************************************************************
        This function calculates L1-penalized merit function
        *************************************************************************/
        private static double meritfunction(minsqpstate state,
            optserv.varsfuncjac vfj,
            double meritmu,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            int n = 0;
            int nec = 0;
            int nic = 0;
            int nlec = 0;
            int nlic = 0;
            double v = 0;

            alglib.ap.assert(vfj.isdense, "SQP: integrity check 1057 failed");
            n = state.n;
            nec = state.nec;
            nic = state.nic;
            nlec = state.nlec;
            nlic = state.nlic;
            
            //
            // Merit function and Lagrangian: primary term
            //
            result = vfj.fi[0];
            
            //
            // Merit function: augmentation and penalty for linear constraints
            //
            apserv.rvectorsetlengthatleast(ref state.mftmp0, nec+nic, _params);
            ablas.rmatrixgemv(nec+nic, n, 1.0, state.scaledcleic, 0, 0, 0, vfj.x, 0, 0.0, state.mftmp0, 0, _params);
            for(i=0; i<=nec+nic-1; i++)
            {
                v = state.mftmp0[i]-state.scaledcleic[i,n];
                if( i<nec )
                {
                    
                    //
                    // Merit function: augmentation term + L1 penalty term
                    //
                    result = result+meritmu*Math.Abs(v);
                }
                else
                {
                    
                    //
                    // Merit function: augmentation term + L1 penalty term
                    //
                    result = result+meritmu*Math.Max(v, 0);
                }
            }
            
            //
            // Merit function: augmentation and penalty for nonlinear constraints
            //
            for(i=0; i<=nlec+nlic-1; i++)
            {
                v = vfj.fi[1+i];
                if( i<nlec )
                {
                    
                    //
                    // Merit function: augmentation term + L1 penalty term
                    //
                    result = result+meritmu*Math.Abs(v);
                }
                else
                {
                    
                    //
                    // Merit function: augmentation term + L1 penalty term
                    //
                    result = result+meritmu*Math.Max(v, 0);
                }
            }
            return result;
        }


        /*************************************************************************
        This function calculates raw (unaugmented and smooth) Lagrangian
        *************************************************************************/
        private static double rawlagrangian(minsqpstate state,
            double[] x,
            double[] fi,
            double[] lagbcmult,
            double[] lagxcmult,
            double meritmu,
            alglib.xparams _params)
        {
            double result = 0;
            double tmp0 = 0;
            double tmp1 = 0;

            meritfunctionandrawlagrangian(state, x, fi, lagbcmult, lagxcmult, meritmu, ref tmp0, ref tmp1, _params);
            result = tmp1;
            return result;
        }


        /*************************************************************************
        This function calculates L1-penalized merit function and raw  (smooth  and
        un-augmented) Lagrangian
        *************************************************************************/
        private static void meritfunctionandrawlagrangian(minsqpstate state,
            double[] x,
            double[] fi,
            double[] lagbcmult,
            double[] lagxcmult,
            double meritmu,
            ref double meritf,
            ref double rawlag,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;
            int nec = 0;
            int nic = 0;
            int nlec = 0;
            int nlic = 0;
            double v = 0;

            meritf = 0;
            rawlag = 0;

            n = state.n;
            nec = state.nec;
            nic = state.nic;
            nlec = state.nlec;
            nlic = state.nlic;
            
            //
            // Merit function and Lagrangian: primary term
            //
            meritf = fi[0];
            rawlag = fi[0];
            
            //
            // Lagrangian: handle box constraints
            //
            // NOTE: we do not add box constrained term to the merit function because
            //       box constraints are handled exactly and we do not violate them.
            //
            for(i=0; i<=n-1; i++)
            {
                rawlag = rawlag+lagbcmult[i]*x[i];
            }
            
            //
            // Merit function: augmentation and penalty for linear constraints
            //
            apserv.rvectorsetlengthatleast(ref state.mftmp0, nec+nic, _params);
            ablas.rmatrixgemv(nec+nic, n, 1.0, state.scaledcleic, 0, 0, 0, x, 0, 0.0, state.mftmp0, 0, _params);
            for(i=0; i<=nec+nic-1; i++)
            {
                v = state.mftmp0[i]-state.scaledcleic[i,n];
                if( i<nec )
                {
                    
                    //
                    // Merit function: augmentation term + L1 penalty term
                    //
                    meritf = meritf+meritmu*Math.Abs(v);
                    
                    //
                    // Raw Lagrangian
                    //
                    rawlag = rawlag+lagxcmult[i]*v;
                }
                else
                {
                    
                    //
                    // Merit function: augmentation term + L1 penalty term
                    //
                    meritf = meritf+meritmu*Math.Max(v, 0);
                    
                    //
                    // Raw Lagrangian
                    //
                    rawlag = rawlag+lagxcmult[i]*v;
                }
            }
            
            //
            // Merit function: augmentation and penalty for nonlinear constraints
            //
            for(i=0; i<=nlec+nlic-1; i++)
            {
                v = fi[1+i];
                if( i<nlec )
                {
                    
                    //
                    // Merit function: augmentation term + L1 penalty term
                    //
                    meritf = meritf+meritmu*Math.Abs(v);
                    
                    //
                    // Raw Lagrangian
                    //
                    rawlag = rawlag+lagxcmult[nec+nic+i]*v;
                }
                else
                {
                    
                    //
                    // Merit function: augmentation term + L1 penalty term
                    //
                    meritf = meritf+meritmu*Math.Max(v, 0);
                    
                    //
                    // Raw Lagrangian
                    //
                    rawlag = rawlag+lagxcmult[nec+nic+i]*v;
                }
            }
        }


        /*************************************************************************
        This function analyzes constraint linearizations at the proposed candidate
        point. Depending on outcome, proposes to increase MeritMu or not.

        If no update is necessary (the best outcome), False will be returned.

          -- ALGLIB --
             Copyright 13.03.2023 by Bochkanov Sergey
        *************************************************************************/
        private static bool penaltiesneedincrease(minsqpstate state,
            optserv.varsfuncjac currentlinearization,
            double[] dtrial,
            double predictedchangemodel,
            double predictedchangepenalty,
            bool dotrace,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int nec = 0;
            int nic = 0;
            int nlec = 0;
            int nlic = 0;
            int nslack = 0;
            int i = 0;
            int j = 0;
            int tt = 0;
            double tol = 0;
            double tol2 = 0;
            double constrval = 0;
            double allowederr = 0;
            bool failedtoenforce = new bool();
            bool failedtoenforceinf = new bool();
            bool infeasiblewithinbox = new bool();
            double dummy0 = 0;
            double dummy1 = 0;
            double dummy2 = 0;
            double dummy3 = 0;
            double penaltyatx = 0;
            double penaltyatd = 0;
            double penaltyatdinf = 0;
            double meritdecrease = 0;
            double penaltydecrease = 0;
            double mxd = 0;
            double expandedrad = 0;
            double cx = 0;
            double cxd = 0;
            double sumabs = 0;

            n = state.n;
            nec = state.nec;
            nic = state.nic;
            nlec = state.nlec;
            nlic = state.nlic;
            nslack = n+2*(nec+nlec)+(nic+nlic);
            result = false;
            tol = 1.0E-6*state.trustrad*(1+ablasf.rmaxabsv(n, currentlinearization.x, _params));
            
            //
            // Already too big, skip analysis
            //
            if( (double)(state.meritmu)>=(double)(0.9*maxmeritmu) )
            {
                return result;
            }
            
            //
            // Allocate storage
            //
            ablasf.rallocv(nslack, ref state.tmppend, _params);
            ablasf.rallocv(n, ref state.dummylagbcmult, _params);
            ablasf.rallocv(nec+nic+nlec+nlic, ref state.dummylagxcmult, _params);
            
            //
            // Compute the following quantities:
            // * penalty at X
            // * penalty at X+D
            // * whether we failed to enforce constraints at X+D or not
            // * whether any single constraint can be made feasible within max(|D|)-sized box (ignoring other constraints) or not
            //
            penaltyatx = 0;
            penaltyatd = 0;
            failedtoenforce = false;
            infeasiblewithinbox = false;
            mxd = ablasf.rmaxabsv(n, dtrial, _params);
            expandedrad = 1.1*mxd;
            tol2 = Math.Max(Math.Sqrt(math.machineepsilon)*state.trustrad, 1000*math.machineepsilon);
            for(i=0; i<=nec+nic-1; i++)
            {
                cx = ablasf.rdotvr(n, currentlinearization.x, state.scaledcleic, i, _params)-state.scaledcleic[i,n];
                cxd = cx+ablasf.rdotvr(n, dtrial, state.scaledcleic, i, _params);
                cx = apserv.rcase2(i<nec, cx, Math.Max(cx, 0.0), _params);
                cxd = apserv.rcase2(i<nec, cxd, Math.Max(cxd, 0.0), _params);
                sumabs = 0;
                for(j=0; j<=n-1; j++)
                {
                    sumabs = sumabs+Math.Abs(state.scaledcleic[i,j]);
                }
                infeasiblewithinbox = infeasiblewithinbox || (double)(Math.Abs(cx))>(double)(sumabs*expandedrad+tol2);
                penaltyatx = penaltyatx+Math.Abs(cx);
                penaltyatd = penaltyatd+Math.Abs(cxd);
                failedtoenforce = failedtoenforce || (double)(Math.Abs(cxd))>(double)(sumabs*tol);
            }
            for(i=1; i<=nlec+nlic; i++)
            {
                cx = currentlinearization.fi[i];
                cxd = cx+ablasf.rdotvr(n, dtrial, currentlinearization.jac, i, _params);
                cx = apserv.rcase2(i<1+nlec, cx, Math.Max(cx, 0.0), _params);
                cxd = apserv.rcase2(i<1+nlec, cxd, Math.Max(cxd, 0.0), _params);
                sumabs = 0;
                for(j=0; j<=n-1; j++)
                {
                    sumabs = sumabs+Math.Abs(currentlinearization.jac[i,j]);
                }
                infeasiblewithinbox = infeasiblewithinbox || (double)(Math.Abs(cx))>(double)(sumabs*expandedrad+tol2);
                penaltyatx = penaltyatx+Math.Abs(cx);
                penaltyatd = penaltyatd+Math.Abs(cxd);
                failedtoenforce = failedtoenforce || (double)(Math.Abs(cxd))>(double)(sumabs*tol);
            }
            if( infeasiblewithinbox && (double)(mxd)<(double)(0.9*state.trustrad) )
            {
                
                //
                // MeritMu must be increased if a short DTrial was proposed, but there are some
                // constraints that are infeasible within max|DTrial|-sized box
                //
                result = true;
                if( dotrace )
                {
                    alglib.ap.trace("> a short DTrial was proposed, but some constraints are infeasible within trust region; MeritMu increased, iteration skipped\n");
                }
            }
            
            //
            // We may need to increase MeritMu
            //
            if( failedtoenforce )
            {
                
                //
                // We failed to drive constraints linearizations to zero. But what is the best
                // theoretically possible reduction (ignoring quadratic model)?
                //
                if( !qpsubproblemsolve(state, state.subsolver, currentlinearization.x, currentlinearization.fi, currentlinearization.jac, state.hess, 0.0, 0.0, state.tmppend, state.dummylagbcmult, state.dummylagxcmult, dotrace, ref tt, ref dummy0, ref dummy1, ref dummy2, ref dummy3, _params) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> [WARNING] QP subproblem failed with TerminationType={0,0:d} when updating MeritMu\n", tt));
                    }
                    return result;
                }
                penaltyatdinf = 0;
                failedtoenforceinf = false;
                for(i=0; i<=nec+nic-1; i++)
                {
                    constrval = -state.scaledcleic[i,n];
                    allowederr = 0;
                    for(j=0; j<=n-1; j++)
                    {
                        constrval = constrval+state.scaledcleic[i,j]*(currentlinearization.x[j]+state.tmppend[j]);
                        allowederr = allowederr+Math.Abs(state.scaledcleic[i,j]*tol);
                    }
                    if( i>=nec )
                    {
                        constrval = Math.Max(constrval, 0.0);
                    }
                    penaltyatdinf = penaltyatdinf+Math.Abs(constrval);
                    failedtoenforceinf = failedtoenforceinf || (double)(Math.Abs(constrval))>(double)(allowederr);
                }
                for(i=0; i<=nlec+nlic-1; i++)
                {
                    constrval = currentlinearization.fi[1+i];
                    allowederr = 0;
                    for(j=0; j<=n-1; j++)
                    {
                        constrval = constrval+currentlinearization.jac[1+i,j]*state.tmppend[j];
                        allowederr = allowederr+Math.Abs(currentlinearization.jac[1+i,j]*tol);
                    }
                    if( i>=nlec )
                    {
                        constrval = Math.Max(constrval, 0.0);
                    }
                    penaltyatdinf = penaltyatdinf+Math.Abs(constrval);
                    failedtoenforceinf = failedtoenforceinf || (double)(Math.Abs(constrval))>(double)(allowederr);
                }
                
                //
                // Branch on the constraint status within trust region
                //
                if( failedtoenforceinf )
                {
                    
                    //
                    // Constraints are infeasible within the trust region, check that the actual penalty decrease
                    // is at least some fraction of the best possible decrease.
                    //
                    if( (double)(penaltyatx-penaltyatd)<(double)(meritmueps*Math.Max(penaltyatx-penaltyatdinf, 0.0)) && (double)(penaltyatdinf)<(double)(penaltyatx*(1-constraintsstagnationeps)) )
                    {
                        
                        //
                        // Merit function does not decrease fast enough, we must increase MeritMu
                        //
                        result = true;
                        if( dotrace )
                        {
                            alglib.ap.trace("> constraints infeasibility does not decrease fast enough, MeritMu increased, iteration skipped\n");
                        }
                    }
                }
                else
                {
                    
                    //
                    // Constraints are feasible within trust region, we must increase MeritMu
                    //
                    result = true;
                    if( dotrace )
                    {
                        alglib.ap.trace("> MeritMu penalty does not enforce constraints feasibility, MeritMu increased, iteration skipped\n");
                    }
                }
            }
            
            //
            // Now we check that decrease in the quadratic model + penalty is a significant fraction of
            // the decrease in the penalty.
            //
            meritdecrease = -(predictedchangemodel+state.meritmu*predictedchangepenalty);
            penaltydecrease = -(state.meritmu*predictedchangepenalty);
            if( (double)(meritdecrease)<(double)(meritmueps*penaltydecrease) )
            {
                result = true;
                if( dotrace )
                {
                    alglib.ap.trace("> sufficient negativity condition does not hold, MeritMu increased, iteration skipped\n");
                }
            }
            return result;
        }


        /*************************************************************************
        Returns k-th component of the trust region

          -- ALGLIB --
             Copyright 25.09.2023 by Bochkanov Sergey
        *************************************************************************/
        private static double gettrustregionk(double[] xcur,
            int k,
            double trustrad,
            alglib.xparams _params)
        {
            double result = 0;

            result = trustrad*Math.Max(Math.Abs(xcur[k]), 1);
            return result;
        }


        /*************************************************************************
        Adjusts merit function value using non-monotonic correction  (sets  it  to
        maximum among several last values, returns adjusted value)

          -- ALGLIB --
             Copyright 25.09.2023 by Bochkanov Sergey
        *************************************************************************/
        private static double nonmonotonicadjustment(minsqpstate state,
            double fraw,
            alglib.xparams _params)
        {
            double result = 0;
            optserv.varsfuncjac vfj = null;
            int i = 0;

            result = fraw;
            for(i=0; i<=Math.Min(state.nonmonotoniccnt, nonmonotoniclen)-1; i++)
            {
                state.nonmonotonicmem.get(i, ref vfj);
                result = Math.Max(result, meritfunction(state, vfj, state.meritmu, _params));
            }
            return result;
        }


        /*************************************************************************
        Saves current point to the nonmonotonic memory.

          -- ALGLIB --
             Copyright 25.09.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void nonmonotonicsave(minsqpstate state,
            optserv.varsfuncjac cur,
            alglib.xparams _params)
        {
            optserv.varsfuncjac vfj = null;

            if( nonmonotoniclen==0 )
            {
                return;
            }
            if( state.nonmonotoniccnt<nonmonotoniclen )
            {
                
                //
                // Append point to the buffer
                //
                alglib.ap.assert(state.nonmonotonicmem.getlength()==state.nonmonotoniccnt, "SQP: integrity check 3710 failed");
                vfj = new optserv.varsfuncjac();
                optserv.vfjcopy(cur, vfj, _params);
                state.nonmonotonicmem.append(vfj);
            }
            else
            {
                
                //
                // Rewrite one of points in the buffer
                //
                alglib.ap.assert(state.nonmonotonicmem.getlength()==nonmonotoniclen, "SQP: integrity check 3711 failed");
                state.nonmonotonicmem.get(state.nonmonotoniccnt%nonmonotoniclen, ref vfj);
                optserv.vfjcopy(cur, vfj, _params);
            }
            state.nonmonotoniccnt = state.nonmonotoniccnt+1;
        }


        /*************************************************************************
        Rescales target/constraints stored in the nonmonotonic memory.

          -- ALGLIB --
             Copyright 25.09.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void nonmonotonicmultiplyby(minsqpstate state,
            int jacrow,
            double v,
            alglib.xparams _params)
        {
            optserv.varsfuncjac vfj = null;
            int i = 0;

            for(i=0; i<=Math.Min(state.nonmonotoniccnt, nonmonotoniclen)-1; i++)
            {
                state.nonmonotonicmem.get(i, ref vfj);
                alglib.ap.assert(vfj.isdense, "SQP: integrity check 7600 failed");
                vfj.fi[jacrow] = vfj.fi[jacrow]*v;
                ablasf.rmulr(vfj.n, v, vfj.jac, jacrow, _params);
            }
        }


    }
    public partial class nlcaul
    {
        /*************************************************************************
        This object stores temporaries of AUL preconditioner.
        *************************************************************************/
        public class minaulpreconditioner : apobject
        {
            public int refreshfreq;
            public int modelage;
            public spchol.spcholanalysis analysis;
            public sparse.sparsematrix augsys;
            public int naug;
            public double[,] s;
            public double[,] y;
            public int updcnt;
            public double[,] tmpcorrc;
            public double[] tmpcorrd;
            public double[] tmpdiag;
            public int[] priorities;
            public double[] dx;
            public double[,] dummys;
            public double[,] dummyy;
            public double[] alphak;
            public double[] rhok;
            public minaulpreconditioner()
            {
                init();
            }
            public override void init()
            {
                analysis = new spchol.spcholanalysis();
                augsys = new sparse.sparsematrix();
                s = new double[0,0];
                y = new double[0,0];
                tmpcorrc = new double[0,0];
                tmpcorrd = new double[0];
                tmpdiag = new double[0];
                priorities = new int[0];
                dx = new double[0];
                dummys = new double[0,0];
                dummyy = new double[0,0];
                alphak = new double[0];
                rhok = new double[0];
            }
            public override alglib.apobject make_copy()
            {
                minaulpreconditioner _result = new minaulpreconditioner();
                _result.refreshfreq = refreshfreq;
                _result.modelage = modelage;
                _result.analysis = analysis!=null ? (spchol.spcholanalysis)analysis.make_copy() : null;
                _result.augsys = augsys!=null ? (sparse.sparsematrix)augsys.make_copy() : null;
                _result.naug = naug;
                _result.s = (double[,])s.Clone();
                _result.y = (double[,])y.Clone();
                _result.updcnt = updcnt;
                _result.tmpcorrc = (double[,])tmpcorrc.Clone();
                _result.tmpcorrd = (double[])tmpcorrd.Clone();
                _result.tmpdiag = (double[])tmpdiag.Clone();
                _result.priorities = (int[])priorities.Clone();
                _result.dx = (double[])dx.Clone();
                _result.dummys = (double[,])dummys.Clone();
                _result.dummyy = (double[,])dummyy.Clone();
                _result.alphak = (double[])alphak.Clone();
                _result.rhok = (double[])rhok.Clone();
                return _result;
            }
        };


        /*************************************************************************
