        public const double defaultinequalitylag = 1.0;
        public const double maxlagmult = 1.0E7;
        public const double minlagmult = 1.0E-10;
        public const double besterrstagnationcoeff = 0.75;
        public const int besterrstagnationlimit = 10;
        public const double stagnationepsf = 1.0E-12;
        public const double stabilizingpoint = 10.0;
        public const int fstagnationlimit = 20;
        public const double aulmaxgrowth = 10.0;
        public const double rhomax = 10000;
        public const double gtol = 0.25;
        public const double auldeltadecrease = 0.50;
        public const double auldeltaincrease = 0.99;
        public const double aulbigscale = 5.0;
        public const double aulsmallscale = 0.2;
        public const int xbfgsmemlen = 8;
        public const double xbfgsmaxhess = 1.0E3;


        /*************************************************************************
        This function initializes solver state
        *************************************************************************/
        public static void minaulinitbuf(double[] bndl,
            double[] bndu,
            double[] s,
            double[] x0,
            int n,
            sparse.sparsematrix a,
            double[] al,
            double[] au,
            int[] lcsrcidx,
            int cntlc,
            double[] nl,
            double[] nu,
            int cntnlc,
            optserv.nlpstoppingcriteria criteria,
            int maxouterits,
            minaulstate state,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(cntlc==0 || a.m==cntlc, "AUL: rows(A)<>CntLC");
            alglib.ap.assert(maxouterits>=0, "AUL: MaxOuterIts<0");
            
            //
            // Initialization
            //
            if( maxouterits==0 )
            {
                maxouterits = 20;
            }
            state.n = n;
            state.cntlc = cntlc;
            state.cntnlc = cntnlc;
            
            //
            // Prepare RCOMM state
            //
            state.rstate.ia = new int[9+1];
            state.rstate.ba = new bool[4+1];
            state.rstate.ra = new double[23+1];
            state.rstate.stage = -1;
            state.rstate.clear_handler();
            state.needsj = false;
            state.precrefreshupcoming = false;
            state.xupdated = false;
            state.x = new double[n];
            state.fi = new double[1+cntnlc];
            
            //
            // Allocate memory.
            //
            ablasf.rallocv(n, ref state.x0, _params);
            ablasf.rsetallocv(n, 1.0, ref state.s, _params);
            apserv.rvectorsetlengthatleast(ref state.fscales, 1+cntnlc, _params);
            apserv.rvectorsetlengthatleast(ref state.tracegamma, 1+cntnlc, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndl, n, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndu, n, _params);
            apserv.rvectorsetlengthatleast(ref state.scaledbndl, n, _params);
            apserv.rvectorsetlengthatleast(ref state.scaledbndu, n, _params);
            ablasf.rallocv(2*n, ref state.lagmultbc2, _params);
            apserv.rvectorsetlengthatleast(ref state.lagmultxc2, 2*(cntlc+cntnlc), _params);
            ablasf.rallocv(n, ref state.d, _params);
            ablasf.rallocv(n, ref state.du, _params);
            ablasf.rallocv(n, ref state.laggradcur, _params);
            ablasf.rallocv(n, ref state.modtgtgrad0, _params);
            ablasf.rallocv(n, ref state.modtgtgrad1, _params);
            
            //
            // Prepare scaled problem
            //
            ablasf.rsetallocv(n, -1.0E50, ref state.finitebndl, _params);
            ablasf.rsetallocv(n, 1.0E50, ref state.finitebndu, _params);
            for(i=0; i<=n-1; i++)
            {
                state.hasbndl[i] = math.isfinite(bndl[i]);
                state.hasbndu[i] = math.isfinite(bndu[i]);
                if( state.hasbndl[i] )
                {
                    state.scaledbndl[i] = bndl[i]/s[i];
                    state.finitebndl[i] = state.scaledbndl[i];
                }
                if( state.hasbndu[i] )
                {
                    state.scaledbndu[i] = bndu[i]/s[i];
                    state.finitebndu[i] = state.scaledbndu[i];
                }
                if( state.hasbndl[i] && state.hasbndu[i] )
                {
                    alglib.ap.assert((double)(bndl[i])<=(double)(bndu[i]), "AUL: integrity check failed, box constraints are inconsistent");
                }
                state.x0[i] = x0[i]/s[i];
                state.s[i] = s[i];
            }
            if( cntlc>0 )
            {
                ablasf.rsetallocv(n, 0.0, ref state.tmpzero, _params);
                sparse.sparsecopytocrsbuf(a, state.sparsea, _params);
                ablasf.rcopyallocv(cntlc, al, ref state.al, _params);
                ablasf.rcopyallocv(cntlc, au, ref state.au, _params);
                ablasf.icopyallocv(cntlc, lcsrcidx, ref state.lcsrcidx, _params);
                lpqpserv.scaleshiftmixedlcinplace(s, state.tmpzero, n, state.sparsea, cntlc, state.dummy2, 0, state.al, state.au, _params);
                lpqpserv.normalizesparselcinplace(state.sparsea, cntlc, state.al, state.au, n, true, ref state.ascales, true, _params);
                ablasf.ballocv(cntlc, ref state.hasal, _params);
                ablasf.ballocv(cntlc, ref state.hasau, _params);
                for(i=0; i<=cntlc-1; i++)
                {
                    state.hasal[i] = math.isfinite(state.al[i]);
                    state.hasau[i] = math.isfinite(state.au[i]);
                }
            }
            if( cntnlc>0 )
            {
                ablasf.rcopyallocv(cntnlc, nl, ref state.rawnl, _params);
                ablasf.rcopyallocv(cntnlc, nu, ref state.rawnu, _params);
                ablasf.ballocv(cntnlc, ref state.hasnl, _params);
                ablasf.ballocv(cntnlc, ref state.hasnu, _params);
                for(i=0; i<=cntnlc-1; i++)
                {
                    state.hasnl[i] = math.isfinite(state.rawnl[i]);
                    state.hasnu[i] = math.isfinite(state.rawnu[i]);
                }
            }
            optserv.enforceboundaryconstraints(state.x0, state.scaledbndl, state.hasbndl, state.scaledbndu, state.hasbndu, n, 0, _params);
            
            //
            // Stopping criteria and settings
            //
            optserv.critcopy(criteria, state.criteria, _params);
            state.maxouterits = maxouterits;
            state.restartfreq = 5;
            
            //
            // Report fields
            //
            state.repterminationtype = 0;
            state.repbcerr = 0;
            state.repbcidx = -1;
            state.replcerr = 0;
            state.replcidx = -1;
            state.repnlcerr = 0;
            state.repnlcidx = -1;
            state.repiterationscount = 0;
            
            //
            // Integrity checks
            //
            alglib.ap.assert((double)(auldeltadecrease)<(double)(auldeltaincrease), "MinAUL: integrity check failed");
        }


        /*************************************************************************
        This function performs actual processing for  AUL  algorithm.  It  expects
        that caller redirects its reverse communication  requests NeedFiJ/XUpdated
        to external user who will provide analytic derivative (or  handle  reports
        about progress).

        In case external user does not have analytic derivative, it is responsibility
        of caller to intercept NeedFiJ request and  replace  it  with  appropriate
        numerical differentiation scheme.

        Results are stored:
        * point - in State.StepKX

        IMPORTANT: this function works with scaled problem formulation; it is
                   responsibility of the caller to unscale request and scale
                   Jacobian.
                   
        NOTE: SMonitor is expected to be correctly initialized smoothness monitor.

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        public static bool minauliteration(minaulstate state,
            optserv.smoothnessmonitor smonitor,
            bool userterminationneeded,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int cntlc = 0;
            int cntnlc = 0;
            int nconstr = 0;
            bool dotrace = new bool();
            bool doprobingalways = new bool();
            bool dodetailedtrace = new bool();
            double lagcur = 0;
            double lag0 = 0;
            double lag1 = 0;
            double laga = 0;
            double lagb = 0;
            double ci = 0;
            double modtgt0 = 0;
            double modtgt1 = 0;
            int i = 0;
            int j = 0;
            int j0 = 0;
            int j1 = 0;
            int jj = 0;
            double mx = 0;
            double setscaleto = 0;
            double multiplyby = 0;
            int mcinfo = 0;
            bool inneriterationsstopped = new bool();
            double stpproposed = 0;
            double p = 0;
            double dp = 0;
            double d2p = 0;
            double steplengthtoprobe = 0;
            double v = 0;
            double vv = 0;
            bool stepaccepted = new bool();
            double errprim = 0;
            double errdual = 0;
            double errcmpl = 0;
            double preverrprim = 0;
            double preverrdual = 0;
            double preverrcmpl = 0;

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rstate.stage>=0 )
            {
                n = state.rstate.ia[0];
                cntlc = state.rstate.ia[1];
                cntnlc = state.rstate.ia[2];
                nconstr = state.rstate.ia[3];
                i = state.rstate.ia[4];
                j = state.rstate.ia[5];
                j0 = state.rstate.ia[6];
                j1 = state.rstate.ia[7];
                jj = state.rstate.ia[8];
                mcinfo = state.rstate.ia[9];
                dotrace = state.rstate.ba[0];
                doprobingalways = state.rstate.ba[1];
                dodetailedtrace = state.rstate.ba[2];
                inneriterationsstopped = state.rstate.ba[3];
                stepaccepted = state.rstate.ba[4];
                lagcur = state.rstate.ra[0];
                lag0 = state.rstate.ra[1];
                lag1 = state.rstate.ra[2];
                laga = state.rstate.ra[3];
                lagb = state.rstate.ra[4];
                ci = state.rstate.ra[5];
                modtgt0 = state.rstate.ra[6];
                modtgt1 = state.rstate.ra[7];
                mx = state.rstate.ra[8];
                setscaleto = state.rstate.ra[9];
                multiplyby = state.rstate.ra[10];
                stpproposed = state.rstate.ra[11];
                p = state.rstate.ra[12];
                dp = state.rstate.ra[13];
                d2p = state.rstate.ra[14];
                steplengthtoprobe = state.rstate.ra[15];
                v = state.rstate.ra[16];
                vv = state.rstate.ra[17];
                errprim = state.rstate.ra[18];
                errdual = state.rstate.ra[19];
                errcmpl = state.rstate.ra[20];
                preverrprim = state.rstate.ra[21];
                preverrdual = state.rstate.ra[22];
                preverrcmpl = state.rstate.ra[23];
            }
            else
            {
                n = 359;
                cntlc = -58;
                cntnlc = -919;
                nconstr = -909;
                i = 81;
                j = 255;
                j0 = 74;
                j1 = -788;
                jj = 809;
                mcinfo = 205;
                dotrace = false;
                doprobingalways = true;
                dodetailedtrace = false;
                inneriterationsstopped = true;
                stepaccepted = true;
                lagcur = -698.0;
                lag0 = -900.0;
                lag1 = -318.0;
                laga = -940.0;
                lagb = 1016.0;
                ci = -229.0;
                modtgt0 = -536.0;
                modtgt1 = 487.0;
                mx = -115.0;
                setscaleto = 886.0;
                multiplyby = 346.0;
                stpproposed = -722.0;
                p = -413.0;
                dp = -461.0;
                d2p = 927.0;
                steplengthtoprobe = 201.0;
                v = 922.0;
                vv = -154.0;
                errprim = 306.0;
                errdual = -1011.0;
                errcmpl = 951.0;
                preverrprim = -463.0;
                preverrdual = 88.0;
                preverrcmpl = -861.0;
            }
            if( state.rstate.stage==0 )
            {
                goto lbl_0;
            }
            if( state.rstate.stage==1 )
            {
                goto lbl_1;
            }
            if( state.rstate.stage==2 )
            {
                goto lbl_2;
            }
            if( state.rstate.stage==3 )
            {
                goto lbl_3;
            }
            if( state.rstate.stage==4 )
            {
                goto lbl_4;
            }
            if( state.rstate.stage==5 )
            {
                goto lbl_5;
            }
            
            //
            // Routine body
            //
            n = state.n;
            cntlc = state.cntlc;
            cntnlc = state.cntnlc;
            nconstr = state.cntlc+state.cntnlc;
            dotrace = ap.istraceenabled("AUL", _params);
            dodetailedtrace = dotrace && ap.istraceenabled("AUL.DETAILED", _params);
            doprobingalways = dotrace && ap.istraceenabled("AUL.PROBING", _params);
            
            //
            // Prepare rcomm interface
            //
            state.needsj = false;
            state.precrefreshupcoming = false;
            state.xupdated = false;
            
            //
            // Initialize algorithm state.
            //
            // Create two points that will be maintained during iterations:
            // * a 'virtual' point which is used by the AUL solver. This point is
            //   subject to box constraints, but they are enforced only approximately.
            //   Constraint violation in the intermediate points can be very large.
            //   However, the user does not see this point when we send a callback request.
            // * a 'true' point which actually sent to the user - obtained by clipping
            //   the virtual point to the box constrained area.
            //
            for(i=0; i<=cntnlc; i++)
            {
                state.fscales[i] = 1.0;
                state.tracegamma[i] = 0.0;
            }
            state.repterminationtype = 0;
            state.repiterationscount = 0;
            state.repnfev = 0;
            state.inneriterationscount = 0;
            state.outeriterationscount = 0;
            ablasf.rsetv(2*n, 0.0, state.lagmultbc2, _params);
            for(i=0; i<=n-1; i++)
            {
