            }
            
            //
            // Update iterations counts.
            // Check stopping criteria for inner iterations.
            //
            state.repiterationscount = state.repiterationscount+1;
            state.inneriterationscount = state.inneriterationscount+1;
            inneriterationsstopped = false;
            state.fstagnationcnt = apserv.icase2((double)(Math.Abs(lag1-lag0))<=(double)(stagnationepsf*apserv.rmax3(Math.Abs(lag1), Math.Abs(lag0), 1, _params)), state.fstagnationcnt+1, 0, _params);
            v = Math.Abs(lag1-lag0)/apserv.rmaxabs3(lag1, lag0, 1, _params);
            vv = Math.Abs(modtgt1-modtgt0)/apserv.rmaxabs3(modtgt1, modtgt0, 1, _params);
            if( (double)(Math.Max(v, vv))<=(double)(optserv.critgetepsf(state.criteria, _params)) )
            {
                inneriterationsstopped = true;
                if( dotrace )
                {
                    alglib.ap.trace(System.String.Format("> stopping condition for inner iterations met: function change is smaller than {0,0:E3}\n", optserv.critgetepsf(state.criteria, _params)));
                }
            }
            if( (double)(ablasf.rmaxabsv(n, state.d, _params)*state.stp)<=(double)(optserv.critgeteps(state.criteria, _params)) )
            {
                inneriterationsstopped = true;
                if( dotrace )
                {
                    alglib.ap.trace(System.String.Format("> stopping condition for inner iterations met: step is smaller than {0,0:E3}\n", optserv.critgeteps(state.criteria, _params)));
                }
            }
            if( (double)(ablasf.rmaxabsv(n, state.d, _params)*state.stp)<=(double)(0.001*Math.Sqrt(math.machineepsilon)) )
            {
                inneriterationsstopped = true;
                if( dotrace )
                {
                    alglib.ap.trace("> stopping condition for inner iterations met: step is smaller than the absolute minimum\n");
                }
            }
            if( optserv.critgetmaxits(state.criteria, _params)>0 && state.inneriterationscount>=optserv.critgetmaxits(state.criteria, _params) )
            {
                inneriterationsstopped = true;
                if( dotrace )
                {
                    alglib.ap.trace(System.String.Format("> stopping condition for inner iterations met: {0,0:d} iterations performed\n", state.inneriterationscount));
                }
            }
            if( state.fstagnationcnt>=fstagnationlimit )
            {
                if( dotrace )
                {
                    alglib.ap.trace(System.String.Format("> stopping criteria are too stringent: F stagnated for {0,0:d} its, stopping\n", state.fstagnationcnt));
                }
                inneriterationsstopped = true;
            }
            
            //
            // Inner iterations stopped (or user requested termination)
            //
            // Update Lagrange multipliers, penalties, check stopping criteria for outer iterations.
            //
            if( inneriterationsstopped || userterminationneeded )
            {
                
                //
                // Update best point so far
                //
                if( (double)(apserv.rmax3(errprim, errdual, errcmpl, _params))<(double)(state.besterr) )
                {
                    if( (double)(apserv.rmax3(errprim, errdual, errcmpl, _params))>(double)(besterrstagnationcoeff*state.besterr) )
                    {
                        state.besterrnegligibleupdates = state.besterrnegligibleupdates+1;
                    }
                    optserv.vfjcopy(state.xvirt, state.xvirtbest, _params);
                    optserv.vfjcopy(state.xtrue, state.xtruebest, _params);
                    state.besterr = apserv.rmax3(errprim, errdual, errcmpl, _params);
                    state.bestiteridx = state.outeriterationscount;
                }
                
                //
                // Advance outer iterations counter, reset inner iterations count, check stopping criteria
                //
                state.outeriterationscount = state.outeriterationscount+1;
                state.inneriterationscount = 0;
                state.fstagnationcnt = 0;
                if( ((double)(errprim)<=(double)(10*Math.Sqrt(math.machineepsilon)) && (double)(errdual)<=(double)(10*Math.Sqrt(math.machineepsilon))) && (double)(errcmpl)<=(double)(10*Math.Sqrt(math.machineepsilon)) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace("> primal, dual and complementary slackness errors are small, stopping\n");
                    }
                    state.repterminationtype = 1;
                    goto lbl_7;
                }
                if( state.besterrnegligibleupdates>=besterrstagnationlimit )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace("> primal/dual/complementary error had too many negligible updates, stopping\n");
                    }
                    state.repterminationtype = 7;
                    goto lbl_7;
                }
                if( state.bestiteridx<state.outeriterationscount-besterrstagnationlimit )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace("> primal/dual/complementary error stagnated for too long, stopping\n");
                    }
                    state.repterminationtype = 7;
                    goto lbl_7;
                }
                if( userterminationneeded )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace("> user requested termination, stopping\n");
                    }
                    state.repterminationtype = 8;
                    goto lbl_7;
                }
                if( state.outeriterationscount>=state.maxouterits )
                {
                    state.repterminationtype = 5;
                    goto lbl_7;
                }
                
                //
                // Save primal/dual/complementary error estimates
                //
                preverrprim = errprim;
                preverrdual = errdual;
                preverrcmpl = errcmpl;
                
                //
                // Update Lagrange multipliers
                //
                for(i=0; i<=n-1; i++)
                {
                    alglib.ap.assert((double)(aulmaxgrowth)>(double)(1.0), "AUL: integrity check 2444 failed");
                    if( !state.hasbndl[i] && !state.hasbndu[i] )
                    {
                        continue;
                    }
                    if( (state.hasbndl[i] && state.hasbndu[i]) && (double)(state.scaledbndl[i])==(double)(state.scaledbndu[i]) )
                    {
                        v = Math.Min(maxlagmult, aulmaxgrowth*(Math.Abs(state.lagmultbc2[2*i+0])+1));
                        state.lagmultbc2[2*i+0] = apserv.boundval(state.lagmultbc2[2*i+0]+state.rho*(state.xvirt.x[i]-state.scaledbndl[i]), -v, v, _params);
                        continue;
                    }
                    if( state.hasbndl[i] )
                    {
                        inequalityshiftedbarrierfunction((state.xvirt.x[i]-state.scaledbndl[i])*state.rho+1, ref p, ref dp, ref d2p, _params);
                        dp = Math.Abs(dp);
                        dp = Math.Min(dp, aulmaxgrowth);
                        dp = Math.Max(dp, 1/aulmaxgrowth);
                        state.lagmultbc2[2*i+0] = apserv.boundval(state.lagmultbc2[2*i+0]*dp, minlagmult, maxlagmult, _params);
                    }
                    if( state.hasbndu[i] )
                    {
                        inequalityshiftedbarrierfunction((state.scaledbndu[i]-state.xvirt.x[i])*state.rho+1, ref p, ref dp, ref d2p, _params);
                        dp = Math.Abs(dp);
                        dp = Math.Min(dp, aulmaxgrowth);
                        dp = Math.Max(dp, 1/aulmaxgrowth);
                        state.lagmultbc2[2*i+1] = apserv.boundval(state.lagmultbc2[2*i+1]*dp, minlagmult, maxlagmult, _params);
                    }
                }
                for(i=0; i<=cntlc-1; i++)
                {
                    j0 = state.sparsea.ridx[i];
                    j1 = state.sparsea.ridx[i+1]-1;
                    ci = 0;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        ci = ci+state.xvirt.x[state.sparsea.idx[jj]]*state.sparsea.vals[jj];
                    }
                    if( (state.hasal[i] && state.hasau[i]) && (double)(state.al[i])==(double)(state.au[i]) )
                    {
                        
                        //
                        // Equality constraint
                        //
                        state.lagmultxc2[2*i+0] = state.lagmultxc2[2*i+0]+state.rho*(ci-state.al[i]);
                    }
                    else
                    {
                        
                        //
                        // No constraints, inequality constraint or range constraint
                        //
                        if( state.hasal[i] )
                        {
                            inequalityshiftedbarrierfunction((ci-state.al[i])*state.rho+1, ref p, ref dp, ref d2p, _params);
                            dp = Math.Abs(dp);
                            dp = Math.Min(dp, aulmaxgrowth);
                            dp = Math.Max(dp, 1/aulmaxgrowth);
                            state.lagmultxc2[2*i+0] = apserv.boundval(state.lagmultxc2[2*i+0]*dp, minlagmult, maxlagmult, _params);
                        }
                        if( state.hasau[i] )
                        {
                            inequalityshiftedbarrierfunction((state.au[i]-ci)*state.rho+1, ref p, ref dp, ref d2p, _params);
                            dp = Math.Abs(dp);
                            dp = Math.Min(dp, aulmaxgrowth);
                            dp = Math.Max(dp, 1/aulmaxgrowth);
                            state.lagmultxc2[2*i+1] = apserv.boundval(state.lagmultxc2[2*i+1]*dp, minlagmult, maxlagmult, _params);
                        }
                    }
                }
                for(i=0; i<=cntnlc-1; i++)
                {
                    ci = state.xvirt.fi[1+i];
                    if( (state.hasnl[i] && state.hasnu[i]) && (double)(state.rawnl[i])==(double)(state.rawnu[i]) )
                    {
                        
                        //
                        // Equality constraint
                        //
                        state.lagmultxc2[2*cntlc+2*i+0] = state.lagmultxc2[2*cntlc+2*i+0]+state.rho*(ci-state.rawnl[i]);
                    }
                    else
                    {
                        
                        //
                        // No constraints, inequality constraint or range constraint
                        //
                        if( state.hasnl[i] )
                        {
                            inequalityshiftedbarrierfunction((ci-state.rawnl[i])*state.rho+1, ref p, ref dp, ref d2p, _params);
                            dp = Math.Abs(dp);
                            dp = Math.Min(dp, aulmaxgrowth);
                            dp = Math.Max(dp, 1/aulmaxgrowth);
                            state.lagmultxc2[2*cntlc+2*i+0] = apserv.boundval(state.lagmultxc2[2*cntlc+2*i+0]*dp, minlagmult, maxlagmult, _params);
                        }
                        if( state.hasnu[i] )
                        {
                            inequalityshiftedbarrierfunction((state.rawnu[i]-ci)*state.rho+1, ref p, ref dp, ref d2p, _params);
                            dp = Math.Abs(dp);
                            dp = Math.Min(dp, aulmaxgrowth);
                            dp = Math.Max(dp, 1/aulmaxgrowth);
                            state.lagmultxc2[2*cntlc+2*i+1] = apserv.boundval(state.lagmultxc2[2*cntlc+2*i+1]*dp, minlagmult, maxlagmult, _params);
                        }
                    }
                }
                
                //
                // Update upper bound on Hessian norm
                //
                optserv.hessiansetmaxhess(state.hessaug, xbfgsmaxhess*(1+state.rho)*Math.Max(1+ablasf.rmaxabsv(2*n, state.lagmultbc2, _params), 1+ablasf.rmaxabsv(2*cntlc+2*cntnlc, state.lagmultxc2, _params)), _params);
                state.rho = Math.Min(Math.Sqrt(2)*state.rho, rhomax);
            }
            goto lbl_6;
        lbl_7:
            
            //
            // Perform the final report
            //
            clearrequestfields(state, _params);
            aulsendtruepoint(state, state.xtruebest.x, _params);
            state.f = state.xtruebest.fi[0]*state.fscales[0];
            state.xupdated = true;
            state.rstate.stage = 5;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_5:
            state.xupdated = false;
            
            //
            // Almost done
            //
            if( dotrace )
            {
                alglib.ap.trace("\n=== STOPPED ========================================================================================\n");
                alglib.ap.trace(System.String.Format("raw target:     {0,20:E12}\n", state.xtruebest.fi[0]*state.fscales[0]));
            }
            optserv.smoothnessmonitortracestatus(smonitor, dotrace, _params);
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rstate.ia[0] = n;
            state.rstate.ia[1] = cntlc;
            state.rstate.ia[2] = cntnlc;
            state.rstate.ia[3] = nconstr;
            state.rstate.ia[4] = i;
            state.rstate.ia[5] = j;
            state.rstate.ia[6] = j0;
            state.rstate.ia[7] = j1;
            state.rstate.ia[8] = jj;
            state.rstate.ia[9] = mcinfo;
            state.rstate.ba[0] = dotrace;
            state.rstate.ba[1] = doprobingalways;
            state.rstate.ba[2] = dodetailedtrace;
            state.rstate.ba[3] = inneriterationsstopped;
            state.rstate.ba[4] = stepaccepted;
            state.rstate.ra[0] = lagcur;
            state.rstate.ra[1] = lag0;
            state.rstate.ra[2] = lag1;
            state.rstate.ra[3] = laga;
            state.rstate.ra[4] = lagb;
            state.rstate.ra[5] = ci;
            state.rstate.ra[6] = modtgt0;
            state.rstate.ra[7] = modtgt1;
            state.rstate.ra[8] = mx;
            state.rstate.ra[9] = setscaleto;
            state.rstate.ra[10] = multiplyby;
            state.rstate.ra[11] = stpproposed;
            state.rstate.ra[12] = p;
            state.rstate.ra[13] = dp;
            state.rstate.ra[14] = d2p;
            state.rstate.ra[15] = steplengthtoprobe;
            state.rstate.ra[16] = v;
            state.rstate.ra[17] = vv;
            state.rstate.ra[18] = errprim;
            state.rstate.ra[19] = errdual;
            state.rstate.ra[20] = errcmpl;
            state.rstate.ra[21] = preverrprim;
            state.rstate.ra[22] = preverrdual;
            state.rstate.ra[23] = preverrcmpl;
            return result;
        }


        /*************************************************************************
        Shifted barrier function for inequality constraints  which  is  multiplied
        by the corresponding Lagrange multiplier.

        Shift function must enter augmented Lagrangian as

            LagMult/Rho*SHIFT((x-lowerbound)*Rho+1)
            
        with corresponding changes being made for upper bound or  other  kinds  of
        constraints.

        INPUT PARAMETERS:
            Alpha   -   function argument. Typically, if we have active constraint
                        with precise Lagrange multiplier, we have Alpha  around 1.
                        Large positive Alpha's correspond to  inner  area  of  the
                        feasible set. Alpha<1 corresponds to  outer  area  of  the
                        feasible set.
                        
        OUTPUT PARAMETERS:
            F       -   F(Alpha)
            DF      -   DF=dF(Alpha)/dAlpha, exact derivative
            D2F     -   second derivative

          -- ALGLIB --
             Copyright 11.07.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void inequalityshiftedbarrierfunction(double alpha,
            ref double f,
            ref double df,
            ref double d2f,
            alglib.xparams _params)
        {
            f = 0;
            df = 0;
            d2f = 0;

            if( alpha>=0.5 )
            {
                f = -Math.Log(alpha);
                df = -(1/alpha);
                d2f = df*df;
            }
            else
            {
                f = 2*alpha*alpha-4*alpha+(Math.Log(2)+1.5);
                df = 4*alpha-4;
                d2f = 4;
            }
        }


        /*************************************************************************
        This function prepares preconditioner for subsequent computation.

        INPUT PARAMETERS:
            SState          -   solver state
            RefreshFreq     -   >=1, refresh frequency

        OUTPUT PARAMETERS:
            P               -   preconditioner object, ready to be computed
                                

          -- ALGLIB --
             Copyright 13.06.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void preconditionerinit(minaulstate sstate,
            int refreshfreq,
            minaulpreconditioner p,
            alglib.xparams _params)
        {
            p.refreshfreq = refreshfreq;
            p.modelage = refreshfreq;
        }


        /*************************************************************************
        This function sends updated target and augmented Lagrangian Hessians to the
        preconditioner. It is expected that this call corresponds to one update of
        Hessians.

          -- ALGLIB --
             Copyright 13.06.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void preconditionersendupdates(minaulstate state,
            minaulpreconditioner prec,
            optserv.varsfuncjac current,
            double rho,
            double[] lagmultbc2,
            double[] lagmultxc2,
            optserv.xbfgshessian hesstgt,
            optserv.xbfgshessian hessaug,
            alglib.xparams _params)
        {
            int n = 0;
            int cntlc = 0;
            double sigmatgt = 0;
            double dummy = 0;
            int dummyupdcnt = 0;
            double dampeps = 0;
            int nconstr = 0;
            int naug = 0;
            int offs = 0;
            int tgtrowidx = 0;
            double vd = 0;
            double p = 0;
            double dp = 0;
            double d2p = 0;
            double vcurvature = 0;
            double vsqrtcurvature = 0;
            int i = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            double ci = 0;
            double fi = 0;
            int facttype = 0;

            n = state.n;
            cntlc = state.cntlc;
            nconstr = state.cntlc+state.cntnlc;
            dampeps = 100*Math.Sqrt(math.machineepsilon)*(1+rho);
            
            //
            // Extract LBFGS memory:
            // * we extract only diagonal scaling factor Sigma from the mod-target Hessian, ignoring all updates
            // * we extract only S/Y updates from the augmented Lagrangian Hessian
            //
            optserv.hessiangetlowrankmemory(hesstgt, ref sigmatgt, ref prec.dummys, ref prec.dummyy, ref dummyupdcnt, _params);
            optserv.hessiangetlowrankmemory(hessaug, ref dummy, ref prec.s, ref prec.y, ref prec.updcnt, _params);
            alglib.ap.assert((double)(sigmatgt)>(double)(0), "AUL: sigma0<=0");
            
            //
            // Increase model age, skip factorization update if model age is small enough
            //
            prec.modelage = prec.modelage+1;
            if( prec.modelage<prec.refreshfreq )
            {
                return;
            }
            
            //
            // The model needs refactorization of the initial scaling matrix
            //
            prec.modelage = 0;
            
            //
            // Generate initial scaling matrix which is a diagonal scaling Sigma from the mod-target Hessian +
            // correction terms coming from penalized constraints.
            //
            naug = n+nconstr;
            prec.naug = naug;
            prec.augsys.matrixtype = 1;
            prec.augsys.m = naug;
            prec.augsys.n = naug;
            ablasf.iallocv(naug+1, ref prec.augsys.ridx, _params);
            prec.augsys.ridx[0] = 0;
            for(i=0; i<=n-1; i++)
            {
                vd = 0.0;
                if( (state.hasbndl[i] && state.hasbndu[i]) && (double)(state.scaledbndl[i])==(double)(state.scaledbndu[i]) )
                {
                    
                    //
                    // Equality constraint, quadratic penalty
                    //
                    vd = rho;
                }
                else
                {
                    if( state.hasbndl[i] )
                    {
                        inequalityshiftedbarrierfunction((current.x[i]-state.scaledbndl[i])*rho+1, ref p, ref dp, ref d2p, _params);
                        vd = vd+lagmultbc2[2*i+0]*d2p*rho;
                    }
                    if( state.hasbndu[i] )
                    {
                        inequalityshiftedbarrierfunction((state.scaledbndu[i]-current.x[i])*rho+1, ref p, ref dp, ref d2p, _params);
                        vd = vd+lagmultbc2[2*i+1]*d2p*rho;
                    }
                }
                
                //
                // Write the diagonal Hessian + diagonal correction coming from the box constraints
                //
                offs = prec.augsys.ridx[i];
                ablasf.igrowv(offs+naug, ref prec.augsys.idx, _params);
                ablasf.rgrowv(offs+naug, ref prec.augsys.vals, _params);
                prec.augsys.idx[offs] = i;
                prec.augsys.vals[offs] = sigmatgt+vd+dampeps;
                offs = offs+1;
                prec.augsys.ridx[i+1] = offs;
            }
            for(i=0; i<=state.cntlc-1; i++)
            {
                
                //
                // Compute curvature coming from I-th linear constraint
                //
                j0 = state.sparsea.ridx[i];
                j1 = state.sparsea.ridx[i+1]-1;
                ci = 0;
                for(jj=j0; jj<=j1; jj++)
                {
                    ci = ci+current.x[state.sparsea.idx[jj]]*state.sparsea.vals[jj];
                }
                vcurvature = 0.0;
                if( (state.hasal[i] && state.hasau[i]) && (double)(state.al[i])==(double)(state.au[i]) )
                {
                    
                    //
                    // Equality constraint Ai*x = ALi = AUi
                    //
                    vcurvature = rho;
                }
                else
                {
                    
                    //
                    // Inequality/range constraint
                    //
                    if( state.hasal[i] )
                    {
                        
                        //
                        // Add curvature from inequality constraint Ai*x >= ALi
                        //
                        inequalityshiftedbarrierfunction((ci-state.al[i])*rho+1, ref p, ref dp, ref d2p, _params);
                        vcurvature = vcurvature+lagmultxc2[2*i+0]*d2p*rho;
                    }
                    if( state.hasau[i] )
                    {
                        
                        //
                        // Add curvature from inequality constraint Ai*x <= AUi
                        //
                        inequalityshiftedbarrierfunction((state.au[i]-ci)*rho+1, ref p, ref dp, ref d2p, _params);
                        vcurvature = vcurvature+lagmultxc2[2*i+1]*d2p*rho;
                    }
                }
                
                //
                // Add modification to the Hessian
                //
                vsqrtcurvature = Math.Sqrt(Math.Max(vcurvature, 0.0));
                tgtrowidx = n+i;
                offs = prec.augsys.ridx[tgtrowidx];
                ablasf.igrowv(offs+naug, ref prec.augsys.idx, _params);
                ablasf.rgrowv(offs+naug, ref prec.augsys.vals, _params);
                j0 = state.sparsea.ridx[i];
                j1 = state.sparsea.ridx[i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    prec.augsys.idx[offs] = state.sparsea.idx[jj];
                    prec.augsys.vals[offs] = vsqrtcurvature*state.sparsea.vals[jj];
                    offs = offs+1;
                }
                prec.augsys.idx[offs] = tgtrowidx;
                prec.augsys.vals[offs] = -1.0;
                offs = offs+1;
                prec.augsys.ridx[tgtrowidx+1] = offs;
            }
            for(i=0; i<=state.cntnlc-1; i++)
            {
                
                //
                // Compute curvature coming from I-th nonlinear constraint
                //
                fi = current.fi[1+i];
                vcurvature = 0.0;
                if( (state.hasnl[i] && state.hasnu[i]) && (double)(state.rawnl[i])==(double)(state.rawnu[i]) )
                {
                    
                    //
                    // Equality constraint Ai*x = ALi = AUi
                    //
                    vcurvature = rho;
                }
                else
                {
                    
                    //
                    // Inequality/range constraint
                    //
                    if( state.hasnl[i] )
                    {
                        
                        //
                        // Add curvature from inequality constraint Ai*x >= ALi
                        //
                        inequalityshiftedbarrierfunction((fi-state.rawnl[i])*rho+1, ref p, ref dp, ref d2p, _params);
                        vcurvature = vcurvature+lagmultxc2[2*cntlc+2*i+0]*d2p*rho;
                    }
                    if( state.hasnu[i] )
                    {
                        
                        //
                        // Add curvature from inequality constraint Ai*x <= AUi
                        //
                        inequalityshiftedbarrierfunction((state.rawnu[i]-fi)*rho+1, ref p, ref dp, ref d2p, _params);
                        vcurvature = vcurvature+lagmultxc2[2*cntlc+2*i+1]*d2p*rho;
                    }
                }
                
                //
                // Add modification
                //
                vsqrtcurvature = Math.Sqrt(Math.Max(vcurvature, 0.0));
                tgtrowidx = n+cntlc+i;
                offs = prec.augsys.ridx[tgtrowidx];
                ablasf.igrowv(offs+naug, ref prec.augsys.idx, _params);
                ablasf.rgrowv(offs+naug, ref prec.augsys.vals, _params);
                j0 = current.sj.ridx[1+i];
                j1 = current.sj.ridx[1+i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    prec.augsys.idx[offs] = current.sj.idx[jj];
                    prec.augsys.vals[offs] = vsqrtcurvature*current.sj.vals[jj];
                    offs = offs+1;
                }
                prec.augsys.idx[offs] = tgtrowidx;
                prec.augsys.vals[offs] = -1.0;
                offs = offs+1;
                prec.augsys.ridx[tgtrowidx+1] = offs;
            }
            sparse.sparsecreatecrsinplace(prec.augsys, _params);
            
            //
            // Perform analysis and factorization
            //
            facttype = 21;
            ablasf.isetallocv(naug, 0, ref prec.priorities, _params);
            if( !spchol.spsymmanalyze(prec.augsys, prec.priorities, 0.0, 0, facttype, 3, 1, prec.analysis, _params) )
            {
                alglib.ap.assert(false, "AUL: integrity check 8126 failed");
            }
            if( !spchol.spsymmfactorize(prec.analysis, _params) )
            {
                alglib.ap.assert(false, "AUL: integrity check 8127 failed");
            }
        }


        /*************************************************************************
        This function computes gradient and applies preconditioner.

          -- ALGLIB --
             Copyright 13.06.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void preconditionersolve(minaulstate state,
            minaulpreconditioner prec,
            double[] g,
            double[] d,
            alglib.xparams _params)
        {
            int n = 0;
            int naug = 0;
            int k = 0;
            double betak = 0;

            alglib.ap.assert(prec.modelage<prec.refreshfreq, "AUL: preconditioner needs at least one update in order to properly initialize itself");
            n = state.n;
            naug = prec.naug;
            
            //
            //
            //
            ablasf.rallocv(prec.updcnt, ref prec.alphak, _params);
            ablasf.rallocv(prec.updcnt, ref prec.rhok, _params);
            ablasf.rcopymulv(n, -1.0, g, d, _params);
            for(k=prec.updcnt-1; k>=0; k--)
            {
                prec.rhok[k] = 1/ablasf.rdotrr(n, prec.s, k, prec.y, k, _params);
                prec.alphak[k] = prec.rhok[k]*ablasf.rdotvr(n, d, prec.s, k, _params);
                ablasf.raddrv(n, -prec.alphak[k], prec.y, k, d, _params);
            }
            ablasf.rsetallocv(naug, 0.0, ref prec.dx, _params);
            ablasf.rcopyv(n, d, prec.dx, _params);
            spchol.spsymmsolve(prec.analysis, prec.dx, _params);
            ablasf.rcopyv(n, prec.dx, d, _params);
            for(k=0; k<=prec.updcnt-1; k++)
            {
                betak = prec.rhok[k]*ablasf.rdotvr(n, d, prec.y, k, _params);
                ablasf.raddrv(n, prec.alphak[k]-betak, prec.s, k, d, _params);
            }
        }


        /*************************************************************************
        Sends virtual point to the user, enforcing box constraints on it and saving
        box-constrained copy to XTrue
        *************************************************************************/
        private static void aulsendvirtualpoint(minaulstate state,
            double[] xvirt,
            double[] xtrue,
            alglib.xparams _params)
        {
            int n = 0;

            n = state.n;
            alglib.ap.assert(alglib.ap.len(xvirt)>=n, "AUL: integrity check 6339 failed");
            alglib.ap.assert(alglib.ap.len(xtrue)>=n, "AUL: integrity check 6440 failed");
            ablasf.rcopyv(n, xvirt, state.x, _params);
            ablasf.rmergemaxv(n, state.finitebndl, state.x, _params);
            ablasf.rmergeminv(n, state.finitebndu, state.x, _params);
            ablasf.rcopyv(n, state.x, xtrue, _params);
        }


        /*************************************************************************
        Sends true point (one which is already box-constrained) to the user.
        *************************************************************************/
        private static void aulsendtruepoint(minaulstate state,
            double[] xtrue,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            n = state.n;
            alglib.ap.assert(alglib.ap.len(xtrue)>=n, "AUL: integrity check 0044 failed");
            for(i=0; i<=n-1; i++)
            {
                if( state.hasbndl[i] && xtrue[i]<state.scaledbndl[i] )
                {
                    alglib.ap.assert(false, "AUL: box constrained point falls outside of the box constrained area");
                }
                if( state.hasbndu[i] && xtrue[i]>state.scaledbndu[i] )
                {
                    alglib.ap.assert(false, "AUL: box constrained point falls outside of the box constrained area");
                }
                state.x[i] = xtrue[i];
            }
        }


        /*************************************************************************
        Retrieves raw functions vector and scaled Jacobian from the user data,
        fills two structures, XVirt and XTrue:

        * it is assumed that XVirt.X and XTrue.X are  already  initialized  -  the
          former is initialized with the virtual point (one which is  not  subject
          to box constraints) and the latter is initialized with  the  true  point
          (one which is box constrained and passed to the user)

        * XTrue.Fi and XTrue.SJ are initialized with the true values at XTrue.X

        * XVirt.Fi and XVirt.Sj are initialized with the  values  of  the  virtual
          model which coincides with the true function vector at  box  constrained
          points, but linearly extrapolates box constrained projection when  XVirt
          is not box-constrained.

        Returns True on success, False on failure (when F or J are not finite numbers).
        *************************************************************************/
        private static bool aulretrievesj(minaulstate state,
            optserv.varsfuncjac xvirt,
            optserv.varsfuncjac xtrue,
            alglib.xparams _params)
        {
            bool result = new bool();
            int m = 0;
            int n = 0;
            int i = 0;
            int j = 0;
            int j0 = 0;
            int j1 = 0;
            double v = 0;
            double vv = 0;
            int offs = 0;
            bool allsame = new bool();

            alglib.ap.assert(!xvirt.isdense, "AULRetrieveSJ: dense output was specified");
            alglib.ap.assert(!xtrue.isdense, "AULRetrieveSJ: dense output was specified");
            alglib.ap.assert(state.sj.n==state.n, "AULRetrieveSJ: integrity check 2200 failed");
            alglib.ap.assert(state.sj.m==1+state.cntnlc, "AULRetrieveSJ: integrity check 2300 failed");
            alglib.ap.assert(xvirt.n==state.n, "AULRetrieveSJ: integrity check 2359 failed");
            alglib.ap.assert(xvirt.m==1+state.cntnlc, "AULRetrieveSJ: integrity check 1125 failed");
            alglib.ap.assert(xtrue.n==state.n, "AULRetrieveSJ: integrity check 1126 failed");
            alglib.ap.assert(xtrue.m==1+state.cntnlc, "AULRetrieveSJ: integrity check 1127 failed");
            n = xtrue.n;
            m = xtrue.m;
            
            //
            // Fill true point with the raw data
            //
            v = 0;
            xtrue.sj.matrixtype = -10080;
            xtrue.sj.m = m;
            xtrue.sj.n = n;
            ablasf.iallocv(m+1, ref xtrue.sj.ridx, _params);
            xtrue.sj.ridx[0] = 0;
            for(i=0; i<=state.cntnlc; i++)
            {
                
                //
                // Function value
                //
                vv = 1/state.fscales[i];
                xtrue.fi[i] = vv*state.fi[i];
                v = v+xtrue.fi[i];
                
                //
                // Sparse Jacobian row (slacks are not added)
                //
                j0 = state.sj.ridx[i];
                j1 = state.sj.ridx[i+1]-1;
                offs = xtrue.sj.ridx[i];
                ablasf.igrowv(offs+(j1-j0+1), ref xtrue.sj.idx, _params);
                ablasf.rgrowv(offs+(j1-j0+1), ref xtrue.sj.vals, _params);
                for(j=j0; j<=j1; j++)
                {
                    xtrue.sj.idx[offs] = state.sj.idx[j];
                    xtrue.sj.vals[offs] = vv*state.sj.vals[j];
                    v = v+xtrue.sj.vals[offs];
                    offs = offs+1;
                }
                
                //
                // Done
                //
                xtrue.sj.ridx[i+1] = offs;
            }
            result = math.isfinite(v);
            
            //
            // Compute function values at the virtual point
            //
            ablasf.rsetallocv(n, 0.0, ref state.tmpretrdelta, _params);
            allsame = true;
            for(i=0; i<=n-1; i++)
            {
                state.tmpretrdelta[i] = xvirt.x[i]-xtrue.x[i];
                allsame = allsame && xtrue.x[i]==xvirt.x[i];
            }
            if( allsame )
            {
                optserv.vfjcopy(xtrue, xvirt, _params);
                return result;
            }
            xvirt.sj.matrixtype = -10080;
            xvirt.sj.m = m;
            xvirt.sj.n = n;
            ablasf.iallocv(m+1, ref xvirt.sj.ridx, _params);
            xvirt.sj.ridx[0] = 0;
            for(i=0; i<=state.cntnlc; i++)
            {
                j0 = xtrue.sj.ridx[i];
                j1 = xtrue.sj.ridx[i+1]-1;
                
                //
                // Function value
                //
                xvirt.fi[i] = xtrue.fi[i];
                for(j=j0; j<=j1; j++)
                {
                    xvirt.fi[i] = xvirt.fi[i]+xtrue.sj.vals[j]*state.tmpretrdelta[xtrue.sj.idx[j]];
                }
                
                //
                // Sparse Jacobian row
                //
                offs = xvirt.sj.ridx[i];
                ablasf.igrowv(offs+(j1-j0+1), ref xvirt.sj.idx, _params);
                ablasf.rgrowv(offs+(j1-j0+1), ref xvirt.sj.vals, _params);
                for(j=j0; j<=j1; j++)
                {
                    xvirt.sj.idx[offs] = xtrue.sj.idx[j];
                    xvirt.sj.vals[offs] = xtrue.sj.vals[j];
                    offs = offs+1;
                }
                
                //
                // Done
                //
                xvirt.sj.ridx[i+1] = offs;
            }
            return result;
        }


        /*************************************************************************
        This function calculates target and its gradient, with possibility of
        applying additional stabilizing modification which does not change
        constrained solution.
        *************************************************************************/
        private static void modtargetfg(minaulstate state,
            optserv.varsfuncjac s,
            double rhobc,
            double rhoxc,
            ref double f,
            double[] g,
            alglib.xparams _params)
        {
            int n = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;

            f = 0;

            n = state.n;
            alglib.ap.assert(alglib.ap.len(g)>=n, "AUL: integrity check 5717 failed");
            alglib.ap.assert(((!s.isdense && (s.sj.matrixtype==1 || s.sj.matrixtype==-10080)) && s.sj.m>=1) && s.sj.n==n, "AUL: integrity check 5820 failed");
            
            //
            // Target function
            //
            ablasf.rsetv(n, 0.0, g, _params);
            f = s.fi[0];
            j0 = s.sj.ridx[0];
            j1 = s.sj.ridx[1]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                g[s.sj.idx[jj]] = s.sj.vals[jj];
            }
        }


        /*************************************************************************
        This function calculates augmented (penalized) Lagrangian of the problem
        *************************************************************************/
        private static void auglagfg(minaulstate state,
            optserv.varsfuncjac s,
            double rho,
            double[] lagmultbc2,
            double[] lagmultxc2,
            ref double f,
            double[] g,
            alglib.xparams _params)
        {
            int n = 0;
            int cntlc = 0;
            int cntnlc = 0;
            int i = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            double ci = 0;
            double v = 0;
            double aix = 0;
            double fi = 0;
            double p = 0;
            double dp = 0;
            double d2p = 0;
            double invrho = 0;
            double stabrho = 0;
            double rhoci = 0;

            f = 0;

            n = state.n;
            cntlc = state.cntlc;
            cntnlc = state.cntnlc;
            alglib.ap.assert((double)(rho)>(double)(0), "AUL: integrity check 1459 failed");
            alglib.ap.assert(alglib.ap.len(g)>=n, "AUL: integrity check 7517 failed");
            alglib.ap.assert(((!s.isdense && (s.sj.matrixtype==1 || s.sj.matrixtype==-10080)) && s.sj.m>=1) && s.sj.n==n, "AUL: integrity check 7720 failed");
            alglib.ap.assert(state.cntlc==0 || ((state.sparsea.matrixtype==1 && state.sparsea.m==state.cntlc) && state.sparsea.n==n), "AUL: integrity check 3528 failed");
            invrho = 1/rho;
            
            //
            // Target function
            //
            modtargetfg(state, s, rho, rho, ref f, g, _params);
            
            //
            // Lagrangian terms for box constraints
            //
            for(i=0; i<=n-1; i++)
            {
                
                //
                // Handle equality constraint on a variable
                //
                if( (state.hasbndl[i] && state.hasbndu[i]) && state.scaledbndl[i]==state.scaledbndu[i] )
                {
                    ci = s.x[i]-state.scaledbndl[i];
                    f = f+0.5*rho*ci*ci+lagmultbc2[2*i+0]*ci;
                    g[i] = g[i]+rho*ci+lagmultbc2[2*i+0];
                    continue;
                }
                
                //
                // Handle lower bound (inequality or range with non-zero width)
                //
                if( state.hasbndl[i] )
                {
                    inequalityshiftedbarrierfunction((s.x[i]-state.scaledbndl[i])*rho+1, ref p, ref dp, ref d2p, _params);
                    f = f+p*invrho*lagmultbc2[2*i+0];
                    g[i] = g[i]+dp*lagmultbc2[2*i+0];
                }
                
                //
                // Handle upper bound (inequality or range with non-zero width)
                //
                if( state.hasbndu[i] )
                {
                    inequalityshiftedbarrierfunction((state.scaledbndu[i]-s.x[i])*rho+1, ref p, ref dp, ref d2p, _params);
                    f = f+p*invrho*lagmultbc2[2*i+1];
                    g[i] = g[i]-dp*lagmultbc2[2*i+1];
                }
            }
            
            //
            // Lagrangian and penalty terms for linear constraints
            //
            for(i=0; i<=state.cntlc-1; i++)
            {
                j0 = state.sparsea.ridx[i];
                j1 = state.sparsea.ridx[i+1]-1;
                
                //
                // Compute constraint value Ai*x
                //
                ci = 0;
                for(jj=j0; jj<=j1; jj++)
                {
                    ci = ci+s.x[state.sparsea.idx[jj]]*state.sparsea.vals[jj];
                }
                
                //
                // Handle Lagrangian and penalty terms
                //
                if( (state.hasal[i] && state.hasau[i]) && state.al[i]==state.au[i] )
                {
                    
                    //
                    // Equality constraint Ai*x = ALi = AUi
                    //
                    ci = ci-state.al[i];
                    f = f+lagmultxc2[2*i+0]*ci+0.5*rho*ci*ci;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = state.sparsea.idx[jj];
                        v = state.sparsea.vals[jj];
                        g[j] = g[j]+lagmultxc2[2*i+0]*v+rho*ci*v;
                    }
                }
                else
                {
                    
                    //
                    // Inequality/range constraint
                    //
                    if( state.hasal[i] )
                    {
                        inequalityshiftedbarrierfunction((ci-state.al[i])*rho+1, ref p, ref dp, ref d2p, _params);
                        f = f+lagmultxc2[2*i+0]*p*invrho;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = state.sparsea.idx[jj];
                            v = state.sparsea.vals[jj];
                            g[j] = g[j]+lagmultxc2[2*i+0]*dp*v;
                        }
                    }
                    if( state.hasau[i] )
                    {
                        inequalityshiftedbarrierfunction((state.au[i]-ci)*rho+1, ref p, ref dp, ref d2p, _params);
                        f = f+lagmultxc2[2*i+1]*p*invrho;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = state.sparsea.idx[jj];
                            v = state.sparsea.vals[jj];
                            g[j] = g[j]-lagmultxc2[2*i+1]*dp*v;
                        }
                    }
                }
            }
            
            //
            // Lagrangian and penalty terms for nonlinear constraints
            //
            for(i=0; i<=cntnlc-1; i++)
            {
                j0 = s.sj.ridx[1+i];
                j1 = s.sj.ridx[1+i+1]-1;
                ci = s.fi[1+i];
                
                //
                // Handle Lagrangian and penalty terms
                //
                if( (state.hasnl[i] && state.hasnu[i]) && state.rawnl[i]==state.rawnu[i] )
                {
                    
                    //
                    // Equality constraint Fi = NLi = NUi
                    //
                    ci = ci-state.rawnl[i];
                    f = f+lagmultxc2[2*cntlc+2*i+0]*ci+0.5*rho*ci*ci;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = s.sj.idx[jj];
                        v = s.sj.vals[jj];
                        g[j] = g[j]+lagmultxc2[2*cntlc+2*i+0]*v+rho*ci*v;
                    }
                }
                else
                {
                    
                    //
                    // Inequality/range constraint
                    //
                    if( state.hasnl[i] )
                    {
                        inequalityshiftedbarrierfunction((ci-state.rawnl[i])*rho+1, ref p, ref dp, ref d2p, _params);
                        f = f+lagmultxc2[2*cntlc+2*i+0]*p*invrho;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = s.sj.idx[jj];
                            v = s.sj.vals[jj];
                            g[j] = g[j]+lagmultxc2[2*cntlc+2*i+0]*dp*v;
                        }
                    }
                    if( state.hasnu[i] )
                    {
                        inequalityshiftedbarrierfunction((state.rawnu[i]-ci)*rho+1, ref p, ref dp, ref d2p, _params);
                        f = f+lagmultxc2[2*cntlc+2*i+1]*p*invrho;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = s.sj.idx[jj];
                            v = s.sj.vals[jj];
                            g[j] = g[j]-lagmultxc2[2*cntlc+2*i+1]*dp*v;
                        }
                    }
                }
            }
            
            //
            // Additional stabilizing penalty term which is inactive within the feasible area
            // and close to its boundaries. This term is intended to prevent long steps into
            // the infeasible area.
            //
            stabrho = stabilizingpoint/rho;
            for(i=0; i<=n-1; i++)
            {
                if( state.hasbndl[i] )
                {
                    ci = s.x[i]-state.scaledbndl[i]+stabrho;
                    if( ci<0.0 )
                    {
                        rhoci = rho*ci;
                        f = f+0.5*rhoci*ci;
                        g[i] = g[i]+rhoci;
                    }
                }
                if( state.hasbndu[i] )
                {
                    ci = state.scaledbndu[i]-s.x[i]+stabrho;
                    if( ci<0.0 )
                    {
                        rhoci = rho*ci;
                        f = f+0.5*rhoci*ci;
                        g[i] = g[i]-rhoci;
                    }
                }
            }
            for(i=0; i<=state.cntlc-1; i++)
            {
                j0 = state.sparsea.ridx[i];
                j1 = state.sparsea.ridx[i+1]-1;
                aix = 0;
                for(jj=j0; jj<=j1; jj++)
                {
                    aix = aix+s.x[state.sparsea.idx[jj]]*state.sparsea.vals[jj];
                }
                if( state.hasal[i] && aix-state.al[i]<-stabrho )
                {
                    ci = aix-state.al[i]+stabrho;
                    f = f+0.5*rho*ci*ci;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = state.sparsea.idx[jj];
                        v = state.sparsea.vals[jj];
                        g[j] = g[j]+rho*ci*v;
                    }
                }
                if( state.hasau[i] && state.au[i]-aix<-stabrho )
                {
                    ci = state.au[i]-aix+stabrho;
                    f = f+0.5*rho*ci*ci;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = state.sparsea.idx[jj];
                        v = state.sparsea.vals[jj];
                        g[j] = g[j]-rho*ci*v;
                    }
                }
            }
            for(i=0; i<=state.cntnlc-1; i++)
            {
                j0 = s.sj.ridx[1+i];
                j1 = s.sj.ridx[1+i+1]-1;
                fi = s.fi[1+i];
                if( state.hasnl[i] )
                {
                    ci = fi-state.rawnl[i]+stabrho;
                    if( ci<0.0 )
                    {
                        rhoci = rho*ci;
                        f = f+0.5*rhoci*ci;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = s.sj.idx[jj];
                            v = s.sj.vals[jj];
                            g[j] = g[j]+rhoci*v;
                        }
                    }
                }
                if( state.hasnu[i] )
                {
                    ci = state.rawnu[i]-fi+stabrho;
                    if( ci<0.0 )
                    {
                        rhoci = rho*ci;
                        f = f+0.5*rhoci*ci;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = s.sj.idx[jj];
                            v = s.sj.vals[jj];
                            g[j] = g[j]-rhoci*v;
                        }
                    }
                }
            }
        }


        /*************************************************************************
        This function calculates raw Lagrangian of the problem
        *************************************************************************/
        private static void rawlagfg(minaulstate state,
            optserv.varsfuncjac s,
            double[] lagmultbc2,
            double[] lagmultxc2,
            ref double f,
            double[] g,
            alglib.xparams _params)
        {
            int n = 0;
            int cntlc = 0;
            int i = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            double fi = 0;
            double ci = 0;
            double v = 0;

            f = 0;

            n = state.n;
            cntlc = state.cntlc;
            alglib.ap.assert(alglib.ap.len(g)>=n, "AUL: integrity check 7517 failed");
            alglib.ap.assert(((!s.isdense && (s.sj.matrixtype==1 || s.sj.matrixtype==-10080)) && s.sj.m>=1) && s.sj.n==n, "AUL: integrity check 7720 failed");
            alglib.ap.assert(state.cntlc==0 || ((state.sparsea.matrixtype==1 && state.sparsea.m==state.cntlc) && state.sparsea.n==n), "AUL: integrity check 3528 failed");
            
            //
            // Target function
            //
            ablasf.rsetv(n, 0.0, g, _params);
            f = s.fi[0];
            j0 = s.sj.ridx[0];
            j1 = s.sj.ridx[1]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                g[s.sj.idx[jj]] = s.sj.vals[jj];
            }
            
            //
            // Lagrangian terms for box constraints
            //
            for(i=0; i<=n-1; i++)
            {
                
                //
                // Handle equality constraint on a variable
                //
                if( (state.hasbndl[i] && state.hasbndu[i]) && (double)(state.scaledbndl[i])==(double)(state.scaledbndu[i]) )
                {
                    ci = s.x[i]-state.scaledbndl[i];
                    f = f+lagmultbc2[2*i+0]*ci;
                    g[i] = g[i]+lagmultbc2[2*i+0];
                    continue;
                }
                
                //
                // Handle lower bound (inequality or range with non-zero width)
                //
                if( state.hasbndl[i] )
                {
                    f = f-lagmultbc2[2*i+0]*(s.x[i]-state.scaledbndl[i]);
                    g[i] = g[i]-lagmultbc2[2*i+0];
                }
                
                //
                // Handle upper bound (inequality or range with non-zero width)
                //
                if( state.hasbndu[i] )
                {
                    f = f-lagmultbc2[2*i+1]*(state.scaledbndu[i]-s.x[i]);
                    g[i] = g[i]+lagmultbc2[2*i+1];
                }
            }
            
            //
            // Lagrangian and penalty terms for linear constraints
            //
            for(i=0; i<=state.cntlc-1; i++)
            {
                j0 = state.sparsea.ridx[i];
                j1 = state.sparsea.ridx[i+1]-1;
                
                //
                // Compute constraint value Ai*x
                //
                ci = 0;
                for(jj=j0; jj<=j1; jj++)
                {
                    ci = ci+s.x[state.sparsea.idx[jj]]*state.sparsea.vals[jj];
                }
                
                //
                // Handle Lagrangian and penalty terms
                //
                if( (state.hasal[i] && state.hasau[i]) && (double)(state.al[i])==(double)(state.au[i]) )
                {
                    
                    //
                    // Equality constraint Ai*x = ALi = AUi
                    //
                    ci = ci-state.al[i];
                    f = f+lagmultxc2[2*i+0]*ci;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = state.sparsea.idx[jj];
                        v = state.sparsea.vals[jj];
                        g[j] = g[j]+lagmultxc2[2*i+0]*v;
                    }
                }
                else
                {
                    
                    //
                    // Inequality/range constraint
                    //
                    if( state.hasal[i] )
                    {
                        f = f-lagmultxc2[2*i+0]*(ci-state.al[i]);
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = state.sparsea.idx[jj];
                            v = state.sparsea.vals[jj];
                            g[j] = g[j]-lagmultxc2[2*i+0]*v;
                        }
                    }
                    if( state.hasau[i] )
                    {
                        
                        //
                        // Inequality constraint Ai*x <= AUi
                        //
                        f = f-lagmultxc2[2*i+1]*(state.au[i]-ci);
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = state.sparsea.idx[jj];
                            v = state.sparsea.vals[jj];
                            g[j] = g[j]+lagmultxc2[2*i+1]*v;
                        }
                    }
                }
            }
            for(i=0; i<=state.cntnlc-1; i++)
            {
                j0 = s.sj.ridx[1+i];
                j1 = s.sj.ridx[1+i+1]-1;
                fi = s.fi[1+i];
                
                //
                // Handle Lagrangian and penalty terms
                //
                if( (state.hasnl[i] && state.hasnu[i]) && (double)(state.rawnl[i])==(double)(state.rawnu[i]) )
                {
                    
                    //
                    // Equality constraint Fi = NLi = NUi
                    //
                    ci = fi-state.rawnl[i];
                    f = f+lagmultxc2[2*cntlc+2*i+0]*ci;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = s.sj.idx[jj];
                        v = s.sj.vals[jj];
                        g[j] = g[j]+lagmultxc2[2*cntlc+2*i+0]*v;
                    }
                }
                else
                {
                    
                    //
                    // Inequality/range constraint
                    //
                    if( state.hasnl[i] )
                    {
                        
                        //
                        // Inequality constraint Ai*x >= ALi
                        //
                        f = f-lagmultxc2[2*cntlc+2*i+0]*(fi-state.rawnl[i]);
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = s.sj.idx[jj];
                            v = s.sj.vals[jj];
                            g[j] = g[j]-lagmultxc2[2*cntlc+2*i+0]*v;
                        }
                    }
                    if( state.hasnu[i] )
                    {
                        
                        //
                        // Inequality constraint Ai*x <= AUi
                        //
                        f = f-lagmultxc2[2*cntlc+2*i+1]*(state.rawnu[i]-fi);
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = s.sj.idx[jj];
                            v = s.sj.vals[jj];
                            g[j] = g[j]+lagmultxc2[2*cntlc+2*i+1]*v;
                        }
                    }
                }
            }
        }


        /*************************************************************************
        Clears request fileds (to be sure that we didn't forget to clear something)
        *************************************************************************/
        private static void clearrequestfields(minaulstate state,
            alglib.xparams _params)
        {
            state.needsj = false;
            state.precrefreshupcoming = false;
            state.xupdated = false;
        }


        /*************************************************************************
        Compute primal/dual/complementary slackness errors
        *************************************************************************/
        private static void computeerrors(minaulstate sstate,
            optserv.varsfuncjac s,
            ref double errprim,
            ref double errdual,
            ref double errcmpl,
            alglib.xparams _params)
        {
            int i = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int n = 0;
            int cntlc = 0;
            int cntnlc = 0;
            double ci = 0;
            double v = 0;

            errprim = 0;
            errdual = 0;
            errcmpl = 0;

            n = sstate.n;
            cntlc = sstate.cntlc;
            cntnlc = sstate.cntnlc;
            errprim = 0.0;
            for(i=0; i<=n-1; i++)
            {
                if( sstate.hasbndl[i] )
                {
                    errprim = Math.Max(errprim, sstate.scaledbndl[i]-s.x[i]);
                }
                if( sstate.hasbndu[i] )
                {
                    errprim = Math.Max(errprim, s.x[i]-sstate.scaledbndu[i]);
                }
            }
            for(i=0; i<=cntlc-1; i++)
            {
                j0 = sstate.sparsea.ridx[i];
                j1 = sstate.sparsea.ridx[i+1]-1;
                ci = 0;
                for(jj=j0; jj<=j1; jj++)
                {
                    ci = ci+s.x[sstate.sparsea.idx[jj]]*sstate.sparsea.vals[jj];
                }
                if( sstate.hasal[i] )
                {
                    errprim = Math.Max(errprim, sstate.al[i]-ci);
                }
                if( sstate.hasau[i] )
                {
                    errprim = Math.Max(errprim, ci-sstate.au[i]);
                }
            }
            for(i=0; i<=cntnlc-1; i++)
            {
                ci = s.fi[1+i];
                if( sstate.hasnl[i] )
                {
                    errprim = Math.Max(errprim, sstate.rawnl[i]-ci);
                }
                if( sstate.hasnu[i] )
                {
                    errprim = Math.Max(errprim, ci-sstate.rawnu[i]);
                }
            }
            ablasf.rallocv(n, ref sstate.tmpg, _params);
            rawlagfg(sstate, s, sstate.lagmultbc2, sstate.lagmultxc2, ref v, sstate.tmpg, _params);
            errdual = ablasf.rmaxabsv(n, sstate.tmpg, _params);
            errcmpl = 0.0;
            for(i=0; i<=n-1; i++)
            {
                if( (sstate.hasbndl[i] && sstate.hasbndu[i]) && (double)(sstate.scaledbndl[i])==(double)(sstate.scaledbndu[i]) )
                {
                    errcmpl = Math.Max(errcmpl, Math.Abs((sstate.scaledbndl[i]-s.x[i])*sstate.lagmultbc2[2*i+0]));
                    continue;
                }
                if( sstate.hasbndl[i] )
                {
                    errcmpl = Math.Max(errcmpl, Math.Abs((sstate.scaledbndl[i]-s.x[i])*sstate.lagmultbc2[2*i+0]));
                }
                if( sstate.hasbndu[i] )
                {
                    errcmpl = Math.Max(errcmpl, Math.Abs((s.x[i]-sstate.scaledbndu[i])*sstate.lagmultbc2[2*i+1]));
                }
            }
            for(i=0; i<=cntlc-1; i++)
            {
                j0 = sstate.sparsea.ridx[i];
                j1 = sstate.sparsea.ridx[i+1]-1;
                ci = 0;
                for(jj=j0; jj<=j1; jj++)
                {
                    ci = ci+s.x[sstate.sparsea.idx[jj]]*sstate.sparsea.vals[jj];
                }
                if( (sstate.hasal[i] && sstate.hasau[i]) && (double)(sstate.al[i])==(double)(sstate.au[i]) )
                {
                    
                    //
                    // Equality constraint
                    //
                    errcmpl = Math.Max(errcmpl, Math.Abs((ci-sstate.al[i])*sstate.lagmultxc2[2*i+0]));
                }
                else
                {
                    
                    //
                    // No constraints, inequality constraint or range constraint
                    //
                    if( sstate.hasal[i] )
                    {
                        errcmpl = Math.Max(errcmpl, Math.Abs((sstate.al[i]-ci)*sstate.lagmultxc2[2*i+0]));
                    }
                    if( sstate.hasau[i] )
                    {
                        errcmpl = Math.Max(errcmpl, Math.Abs((ci-sstate.au[i])*sstate.lagmultxc2[2*i+1]));
                    }
                }
            }
            for(i=0; i<=cntnlc-1; i++)
            {
                ci = s.fi[1+i];
                if( (sstate.hasnl[i] && sstate.hasnu[i]) && (double)(sstate.rawnl[i])==(double)(sstate.rawnu[i]) )
                {
                    
                    //
                    // Equality constraint
                    //
                    errcmpl = Math.Max(errcmpl, Math.Abs((ci-sstate.rawnl[i])*sstate.lagmultxc2[2*cntlc+2*i+0]));
                }
                else
                {
                    
                    //
                    // No constraints, inequality constraint or range constraint
                    //
                    if( sstate.hasnl[i] )
                    {
                        errcmpl = Math.Max(errcmpl, Math.Abs((sstate.rawnl[i]-ci)*sstate.lagmultxc2[2*cntlc+2*i+0]));
                    }
                    if( sstate.hasnu[i] )
                    {
                        errcmpl = Math.Max(errcmpl, Math.Abs((ci-sstate.rawnu[i])*sstate.lagmultxc2[2*cntlc+2*i+1]));
                    }
                }
            }
        }


    }
