                _result.fp = fp;
                _result.hp = hp;
                _result.xk = (double[])xk.Clone();
                _result.sk = (double[])sk.Clone();
                _result.xn = (double[])xn.Clone();
                _result.fkvec = (double[])fkvec.Clone();
                _result.fnvec = (double[])fnvec.Clone();
                _result.fk = fk;
                _result.hk = hk;
                _result.wrkset = (double[,])wrkset.Clone();
                _result.wrksetsize = wrksetsize;
                _result.rs = rs!=null ? (hqrnd.hqrndstate)rs.make_copy() : null;
                _result.tpsmodel = tpsmodel!=null ? (df2psmodel)tpsmodel.make_copy() : null;
                _result.lsamodel = lsamodel!=null ? (dfolsamodel)lsamodel.make_copy() : null;
                _result.rbfmodel = rbfmodel!=null ? (dforbfmodel)rbfmodel.make_copy() : null;
                _result.infinitiesencountered = infinitiesencountered;
                _result.recoveredfrominfinities = recoveredfrominfinities;
                _result.filter = filter!=null ? (optserv.nlpfilter)filter.make_copy() : null;
                _result.savepointstocloud = savepointstocloud;
                _result.clouddata = (double[,])clouddata.Clone();
                _result.cloudsize = cloudsize;
                _result.cloudpending = (double[,])cloudpending.Clone();
                _result.cloudpendingcnt = cloudpendingcnt;
                _result.successhistorylen = successhistorylen;
                _result.successhistorymax = successhistorymax;
                _result.successhistorynext = successhistorynext;
                _result.successhistory = (double[])successhistory.Clone();
                _result.restartstoperform = restartstoperform;
                _result.lasttrustrad = lasttrustrad;
                _result.lastjac = (double[,])lastjac.Clone();
                _result.trustradhistory = (double[])trustradhistory.Clone();
                _result.jacdiffhistory = (double[])jacdiffhistory.Clone();
                _result.iteridxhistory = (double[])iteridxhistory.Clone();
                _result.historylen = historylen;
                _result.historynext = historynext;
                _result.tmpi = (int[])tmpi.Clone();
                _result.tmp0 = (double[])tmp0.Clone();
                _result.tmp1 = (double[])tmp1.Clone();
                _result.tmp2 = (double[])tmp2.Clone();
                _result.tmpdeltas = (double[])tmpdeltas.Clone();
                _result.ipmsolver = ipmsolver!=null ? (vipmsolver.vipmstate)ipmsolver.make_copy() : null;
                _result.densedummy = (double[,])densedummy.Clone();
                _result.sparsedummy = sparsedummy!=null ? (sparse.sparsematrix)sparsedummy.make_copy() : null;
                _result.invrep = invrep!=null ? (matinv.matinvreport)invrep.make_copy() : null;
                _result.repterminationtype = repterminationtype;
                _result.repiterationscount = repiterationscount;
                _result.repnfev = repnfev;
                _result.repsubsolverits = repsubsolverits;
                return _result;
            }
        };




        public const double gammasafety = 0.5;
        public const double omegasafety = 0.1;
        public const double alpha1 = 0.1;
        public const double alpha2 = 0.5;
        public const double eta1 = 0.1;
        public const double eta2 = 0.7;
        public const double gammabad = 0.1;
        public const double gammadec = 0.5;
        public const double gammadec2 = 0.85;
        public const double gammainc = 2.0;
        public const double gammainc2 = 4.0;
        public const double twopsstep = 0.5;
        public const double twopssteplo = 0.15;
        public const double twopsstephi = 1.50;
        public const double lsaimprovementlimit = 1;
        public const double pointunacceptablyfar = 50.0;
        public const double pointtoofar = 2.0;
        public const double pointtooclose = 0.02;
        public const int minhistory = 5;
        public const int maxhistory = 30;
        public const double rbfmindist = 0.10;
        public const double rbftheta0 = 20.0;
        public const double rbftheta1 = 0.001;
        public const double rbfsubsolverepsx = 0.00001;


        /*************************************************************************
        Initialize derivative-free general model-based solver (DFGM)

        IMPORTANT: the solver does NOT support fixed variables. The caller has  to
                   preprocess the problem in order to drop all fixed vars.
        *************************************************************************/
        public static void dfgminitbuf(double[] bndl,
            double[] bndu,
            double[] s,
            double[] x0,
            int n,
            int m,
            bool isls,
            int modeltype,
            optserv.nlpstoppingcriteria criteria,
            int nnoisyrestarts,
            double rad0,
            int maxfev,
            dfgmstate state,
            alglib.xparams _params)
        {
            int i = 0;

            
            //
            // General initialization
            //
            alglib.ap.assert(isls || m==1, "DFGM: M<>1 for a non-least-squares problem");
            state.n = n;
            state.m = m;
            state.isleastsquares = isls;
            state.cntlc = 0;
            state.cntnlc = 0;
            state.rad0 = apserv.coalesce(rad0, 0.1, _params);
            state.nnoisyrestarts = nnoisyrestarts;
            
            //
            // Model type
            //
            alglib.ap.assert((modeltype==0 || modeltype==1) || modeltype==2, "DFGM: unexpected model type, check 0316 failed");
            alglib.ap.assert(modeltype!=0 || isls, "DFGM: ModelType=0 is possible only with least squares problems");
            alglib.ap.assert(modeltype!=1 || isls, "DFGM: ModelType=1 is possible only with least squares problems");
            alglib.ap.assert(modeltype!=2 || !isls, "DFGM: ModelType=2 is possible only with non-least squares problems");
            state.modeltype = modeltype;
            
            //
            //
            //
            alglib.ap.assert((modeltype==0 || modeltype==1) || modeltype==2, "DFGM: unexpected model type, check 256748 failed");
            
            //
            // Stopping criteria
            //
            state.epsx = optserv.critgetepswithdefault(criteria, 0.000001, _params);
            state.epsf = optserv.critgetepsf(criteria, _params);
            state.maxits = optserv.critgetmaxits(criteria, _params);
            state.maxfev = maxfev;
            state.toosmalltrustrad = apserv.coalesce(0.001*state.epsx, math.machineepsilon, _params);
            
            //
            // Prepare scaled problem
            //
            ablasf.rallocv(n, ref state.x0, _params);
            ablasf.rallocv(n, ref state.s, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndl, n, _params);
            apserv.bvectorsetlengthatleast(ref state.hasbndu, n, _params);
            apserv.rvectorsetlengthatleast(ref state.scaledbndl, n, _params);
            apserv.rvectorsetlengthatleast(ref state.scaledbndu, n, _params);
            ablasf.rsetallocv(n, -1.0E50, ref state.finitebndl, _params);
            ablasf.rsetallocv(n, 1.0E50, ref state.finitebndu, _params);
            for(i=0; i<=n-1; i++)
            {
                state.hasbndl[i] = math.isfinite(bndl[i]);
                state.hasbndu[i] = math.isfinite(bndu[i]);
                if( state.hasbndl[i] )
                {
                    state.scaledbndl[i] = bndl[i]/s[i];
                    state.finitebndl[i] = state.scaledbndl[i];
                }
                if( state.hasbndu[i] )
                {
                    state.scaledbndu[i] = bndu[i]/s[i];
                    state.finitebndu[i] = state.scaledbndu[i];
                }
                if( state.hasbndl[i] && state.hasbndu[i] )
                {
                    alglib.ap.assert((double)(bndl[i])<(double)(bndu[i]), "DFGM: integrity check 6007 failed, box constraints with no interior point");
                }
                state.x0[i] = x0[i]/s[i];
                state.s[i] = s[i];
            }
            optserv.enforceboundaryconstraints(state.x0, state.scaledbndl, state.hasbndl, state.scaledbndu, state.hasbndu, n, 0, _params);
            
            //
            // Internal RNG
            //
            hqrnd.hqrndseed(117564, 983549, state.rs, _params);
            
            //
            // Report fields
            //
            state.repterminationtype = 0;
            state.repiterationscount = 0;
            state.repnfev = 0;
            state.repsubsolverits = 0;
            
            //
            // Model-specific initialization
            //
            alglib.ap.assert((modeltype==0 || modeltype==1) || modeltype==2, "DFGM: unexpected model type, check 302739 failed");
            
            //
            // Trace status
            //
            alglib.ap.assert((modeltype==0 || modeltype==1) || modeltype==2, "DFGM: unexpected model type, check 0317 failed");
            state.dotrace = false;
            if( modeltype==0 )
            {
                state.dotrace = ap.istraceenabled("2PS", _params);
            }
            if( modeltype==1 )
            {
                state.dotrace = ap.istraceenabled("DFOLSA", _params);
            }
            if( modeltype==2 )
            {
                state.dotrace = ap.istraceenabled("ORBIT", _params);
            }
            state.dotrace = state.dotrace || ap.istraceenabled("DFGM", _params);
            
            //
            // RComm
            //
            state.rstate.ia = new int[4+1];
            state.rstate.ba = new bool[0+1];
            state.rstate.ra = new double[7+1];
            state.rstate.stage = -1;
            state.rstate.clear_handler();
        }


        /*************************************************************************
        Sets linear constraints. Supported only for ModelType=2
        *************************************************************************/
        public static void dfgmsetlc2(dfgmstate state,
            sparse.sparsematrix c,
            double[] cl,
            double[] cu,
            int m,
            alglib.xparams _params)
        {
            alglib.ap.assert(state.modeltype==2, "DFGMSetLC2: only modelType=2 is supported");
            alglib.ap.assert(m>=0, "DFGMSetLC2: M<0");
            alglib.ap.assert(m==0 || (c.m==m && c.n==state.n), "DFGMSetLC2: matrix size does not match problem statement");
            state.cntlc = m;
            if( m==0 )
            {
                return;
            }
            sparse.sparsecopytocrsbuf(c, state.c, _params);
            ablasf.rcopyallocv(m, cl, ref state.cl, _params);
            ablasf.rcopyallocv(m, cu, ref state.cu, _params);
            ablasf.rsetallocv(state.n, 0.0, ref state.tmp0, _params);
            lpqpserv.scaleshiftsparselcinplace(state.s, state.tmp0, state.n, state.c, m, state.cl, state.cu, _params);
            lpqpserv.normalizesparselcinplace(state.c, m, state.cl, state.cu, state.n, true, ref state.tmp0, false, _params);
        }


        /*************************************************************************
        Sets nonlinear constraints. Supported only for ModelType=2
        *************************************************************************/
        public static void dfgmsetnlc2(dfgmstate state,
            double[] nl,
            double[] nu,
            int m,
            alglib.xparams _params)
        {
            alglib.ap.assert(state.modeltype==2, "DFGMSetNLC2: only modelType=2 is supported");
            alglib.ap.assert(m>=0, "DFGMSetNLC2: M<0");
            state.cntnlc = m;
            if( m==0 )
            {
                return;
            }
            ablasf.rcopyallocv(m, nl, ref state.nl, _params);
            ablasf.rcopyallocv(m, nu, ref state.nu, _params);
        }


        /*************************************************************************

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        public static bool dfgmiteration(dfgmstate state,
            bool userterminationneeded,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int j = 0;
            int n = 0;
            int m = 0;
            int cntnlc = 0;
            double predf = 0;
            double predh = 0;
            double fnew = 0;
            double hnew = 0;
            double skrellen = 0;
            double v = 0;
            double v1 = 0;
            double vv = 0;
            bool accepted = new bool();

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rstate.stage>=0 )
            {
                i = state.rstate.ia[0];
                j = state.rstate.ia[1];
                n = state.rstate.ia[2];
                m = state.rstate.ia[3];
                cntnlc = state.rstate.ia[4];
                accepted = state.rstate.ba[0];
                predf = state.rstate.ra[0];
                predh = state.rstate.ra[1];
                fnew = state.rstate.ra[2];
                hnew = state.rstate.ra[3];
                skrellen = state.rstate.ra[4];
                v = state.rstate.ra[5];
                v1 = state.rstate.ra[6];
                vv = state.rstate.ra[7];
            }
            else
            {
                i = 359;
                j = -58;
                n = -919;
                m = -909;
                cntnlc = 81;
                accepted = true;
                predf = 74.0;
                predh = -788.0;
                fnew = 809.0;
                hnew = 205.0;
                skrellen = -838.0;
                v = 939.0;
                v1 = -526.0;
                vv = 763.0;
            }
            if( state.rstate.stage==0 )
            {
                goto lbl_0;
            }
            if( state.rstate.stage==1 )
            {
                goto lbl_1;
            }
            if( state.rstate.stage==2 )
            {
                goto lbl_2;
            }
            if( state.rstate.stage==3 )
            {
                goto lbl_3;
            }
            if( state.rstate.stage==4 )
            {
                goto lbl_4;
            }
            if( state.rstate.stage==5 )
            {
                goto lbl_5;
            }
            if( state.rstate.stage==6 )
            {
                goto lbl_6;
            }
            if( state.rstate.stage==7 )
            {
                goto lbl_7;
            }
            
            //
            // Routine body
            //
            n = state.n;
            m = state.m;
            cntnlc = state.cntnlc;
            if( state.dotrace )
            {
                alglib.ap.trace("> derivative-free model-based solver started\n");
                if( state.modeltype==0 )
                {
                    alglib.ap.trace("algorithm     = 2PS\n");
                }
                if( state.modeltype==1 )
                {
                    alglib.ap.trace("algorithm     = DFO-LSA\n");
                }
            }
            
            //
            // Initialization phase
            //
            // NOTE: TrustRadFactor is initialized by zero prior to calling UpdateTrustRegion()
            //       because this function expects some initial value to be present here.
            //
            initcloud(state, state.modeltype==2, _params);
            ablasf.rcopyallocv(n, state.x0, ref state.xk, _params);
            state.requesttype = 4;
            state.querysize = 1;
            ablasf.rcopyallocv(n, state.xk, ref state.querydata, _params);
            ablasf.rallocv(m+cntnlc, ref state.replyfi, _params);
            sendrequesttocloud(state, state.querydata, state.querysize, _params);
            state.rstate.stage = 0;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
            if( !apserv.isfinitevector(state.replyfi, (m+cntnlc)*state.querysize, _params) )
            {
                
                //
                // Critical failure - the target is infinite from the very beginning
                //
                if( state.dotrace )
                {
                    alglib.ap.trace("[ERROR] target at the initial point is infinite, stopping due to the critical failure\n");
                }
                state.infinitiesencountered = true;
                state.recoveredfrominfinities = false;
                state.repterminationtype = -8;
                result = false;
                return result;
            }
            sendreplytocloud(state, state.replyfi, _params);
            ablasf.rcopyallocv(m+cntnlc, state.replyfi, ref state.fkvec, _params);
            if( state.isleastsquares )
            {
                state.fk = 0.5*ablasf.rdotv2(m, state.fkvec, _params);
            }
            else
            {
                alglib.ap.assert(m==1, "DFGM: integrity check 458634 failed");
                state.fk = state.fkvec[0];
            }
            state.hk = 0;
            if( state.cntlc>0 )
            {
                ablasf.rallocv(n, ref state.tmp0, _params);
                ablasf.rcopyv(n, state.xk, state.tmp0, _params);
                sparse.sparsemv(state.c, state.tmp0, ref state.tmp1, _params);
                for(i=0; i<=state.cntlc-1; i++)
                {
                    if( math.isfinite(state.cl[i]) )
                    {
                        state.hk = state.hk+Math.Max(state.cl[i]-state.tmp1[i], 0.0);
                    }
                    if( math.isfinite(state.cu[i]) )
                    {
                        state.hk = state.hk+Math.Max(state.tmp1[i]-state.cu[i], 0.0);
                    }
                }
            }
            for(i=0; i<=cntnlc-1; i++)
            {
                if( math.isfinite(state.nl[i]) )
                {
                    state.hk = state.hk+Math.Max(state.nl[i]-state.fkvec[m+i], 0.0);
                }
                if( math.isfinite(state.nu[i]) )
                {
                    state.hk = state.hk+Math.Max(state.fkvec[m+i]-state.nu[i], 0.0);
                }
            }
            ablasf.rallocv(n, ref state.xp, _params);
            ablasf.rallocv(m+cntnlc, ref state.fpvec, _params);
            ablasf.rallocv(n, ref state.sk, _params);
            ablasf.rallocv(n, ref state.xn, _params);
            ablasf.rallocv(m+cntnlc, ref state.fnvec, _params);
            state.infinitiesencountered = false;
            state.recoveredfrominfinities = true;
            inithistory(state, _params);
            state.trustradfactor = 0;
            updatetrustregion(state, state.rad0, _params);
            state.trustradbnd = state.trustradfactor;
            state.wrksetsize = 0;
            optserv.nlpfinit(10*Math.Max(10, state.hk), state.filter, _params);
            state.filter.gammaf = 0.001;
            if( (double)(state.hk)>(double)(0) )
            {
                optserv.nlpfappend(state.filter, state.fk, state.hk, _params);
            }
            
            //
            // Start iterations
            //
        lbl_8:
            if( false )
            {
                goto lbl_9;
            }
            
            //
            // The working set is empty. It may happen during either the very first iteration of the solver,
            // or after the restart. Generate new working set from scratch, compute FkVec, Fk, Hk.
            //
            if( state.wrksetsize!=0 )
            {
                goto lbl_10;
            }
            state.rstateimprove.ia = new int[13+1];
            state.rstateimprove.ba = new bool[0+1];
            state.rstateimprove.ra = new double[12+1];
            state.rstateimprove.stage = -1;
            state.rstateimprove.clear_handler();
        lbl_12:
            if( !improveworkingsetgeometry(state, _params) )
            {
                goto lbl_13;
            }
            if( state.requesttype==4 )
            {
                state.repnfev = state.repnfev+state.querysize;
            }
            state.rstate.stage = 1;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            goto lbl_12;
        lbl_13:
            alglib.ap.assert(state.repterminationtype<=0, "DFGM: integrity check 4524 failed");
            if( state.repterminationtype<0 )
            {
                goto lbl_9;
            }
            alglib.ap.assert(state.wrksetsize>0, "DFGM: integrity check 0227 failed");
        lbl_10:
            
            //
            // Update history of changes in the trust radius and the Jacobian
            //
            updatehistory(state, _params);
            
            //
            // Report current point
            //
            state.requesttype = -1;
            ablasf.rcopyallocv(n, state.xk, ref state.reportx, _params);
            state.reportf = state.fk;
            if( state.isleastsquares )
            {
                state.reportf = 2*state.reportf;
            }
            state.rstate.stage = 2;
            if( state.rstate.rcomm2_handler!=null && state.rstate.requesttype!=0 && state.rstate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstate.rcomm2_handler(state.rstate, state.rstate.handler_p0, state.rstate.handler_p1, state.rstate.handler_p2, state.rstate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_2:
            
            //
            // Check stopping criteria
            //
            if( state.maxits>0 && state.repiterationscount>=state.maxits )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> stopping condition triggered: maximum number of iterations\n");
                }
                state.repterminationtype = 5;
                goto lbl_9;
            }
            if( state.maxfev>0 && state.repnfev>=state.maxfev )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> stopping condition triggered: maximum number of function evaluations\n");
                }
                state.repterminationtype = 5;
                goto lbl_9;
            }
            if( (double)(state.trustradbnd)<=(double)(Math.Max(state.epsx, state.toosmalltrustrad)) )
            {
                
                //
                // Trust radius decreased: either perform a restart or stop
                //
                if( state.restartstoperform>0 )
                {
                    updatetrustregion(state, state.rad0, _params);
                    state.trustradbnd = state.trustradfactor;
                    state.wrksetsize = 0;
                    clearhistoryonrestart(state, _params);
                    state.restartstoperform = state.restartstoperform-1;
                    if( state.dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> restart is performed due to a small trust region size ({0,0:d} restarts left)\n", state.restartstoperform));
                    }
                    goto lbl_8;
                }
                if( (double)(state.trustradbnd)<=(double)(state.epsx) )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> stopping condition triggered: step less than EpsX\n");
                    }
                    state.repterminationtype = 2;
                }
                else
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace("> stopping condition triggered: step is too small, emergency termination\n");
                    }
                    state.repterminationtype = 7;
                }
                goto lbl_9;
            }
            v = 0;
            for(i=0; i<=state.successhistorylen-1; i++)
            {
                v = v+state.successhistory[i];
            }
            if( state.successhistorylen==state.successhistorymax && (double)(Math.Abs(v))<=(double)(state.epsf*apserv.rmaxabs2(state.fk, 1, _params)) )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> stopping condition triggered: total progress over last N+1 successful its is less than EpsF\n");
                }
                state.repterminationtype = 1;
                goto lbl_9;
            }
            if( userterminationneeded )
            {
                if( state.dotrace )
                {
                    alglib.ap.trace("> user requested immediate termination\n");
                }
                state.repterminationtype = 8;
                goto lbl_9;
            }
            
            //
            // Trace output (if needed)
            //
            if( state.dotrace )
            {
                alglib.ap.trace(System.String.Format("\n=== ITERATION {0,5:d} STARTED ========================================================================\n", state.repiterationscount));
                alglib.ap.trace(System.String.Format("DeltaK        = {0,0:E3} (current trust radius factor)\n", state.trustradfactor));
                alglib.ap.trace(System.String.Format("RhoK          = {0,0:E3} (lower bound on the trust radius)\n", state.trustradbnd));
                alglib.ap.trace(System.String.Format("|x|inf        = {0,0:E3}\n", ablasf.rmaxabsv(n, state.xk, _params)));
                alglib.ap.trace("> stopping criteria:\n");
                v = 0;
                for(i=0; i<=state.successhistorylen-1; i++)
                {
