        public static void linregline(double[] x,
            double[] y,
            int n,
            ref double a,
            ref double b,
            ref double corrxy,
            alglib.xparams _params)
        {
            int i = 0;
            double ss = 0;
            double sx = 0;
            double sxx = 0;
            double sy = 0;
            double stt = 0;
            double e1 = 0;
            double e2 = 0;
            double t = 0;
            double varx = 0;
            double vary = 0;
            double meanx = 0;
            double meany = 0;

            a = 0;
            b = 0;
            corrxy = 0;

            alglib.ap.assert(n>=2, "DFGM: integrity check 6541 failed");
            
            //
            // Calculate S, SX, SY, SXX
            //
            ss = 0;
            sx = 0;
            sy = 0;
            sxx = 0;
            for(i=0; i<=n-1; i++)
            {
                ss = ss+1;
                sx = sx+x[i];
                sy = sy+y[i];
                sxx = sxx+math.sqr(x[i]);
            }
            
            //
            // Test for condition number
            //
            t = Math.Sqrt(4*math.sqr(sx)+math.sqr(ss-sxx));
            e1 = 0.5*(ss+sxx+t);
            e2 = 0.5*(ss+sxx-t);
            alglib.ap.assert((double)(Math.Min(e1, e2))>(double)(1000*math.machineepsilon*Math.Max(e1, e2)), "DFGM: integrity check 6702 failed");
            
            //
            // Calculate A, B
            //
            a = 0;
            b = 0;
            stt = 0;
            for(i=0; i<=n-1; i++)
            {
                t = x[i]-sx/ss;
                b = b+t*y[i];
                stt = stt+math.sqr(t);
            }
            b = b/stt;
            a = (sy-sx*b)/ss;
            
            //
            // Calculate other parameters
            //
            meanx = sx/n;
            meany = sy/n;
            varx = 0;
            vary = 0;
            corrxy = 0;
            for(i=0; i<=n-1; i++)
            {
                varx = varx+(x[i]-meanx)*(x[i]-meanx);
                vary = vary+(y[i]-meany)*(y[i]-meany);
                corrxy = corrxy+(x[i]-meanx)*(y[i]-meany);
            }
            corrxy = corrxy/Math.Sqrt(apserv.coalesce(varx*vary, 1, _params));
        }


        /*************************************************************************
        Initialize the following histories:
        * a history of changes in the trust radius and the Jacobian. If NNoisyRestarts
          is zero from the very beginning, this history is not tracked.
        * a history of changes in the objective, which is used to track

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void inithistory(dfgmstate state,
            alglib.xparams _params)
        {
            state.restartstoperform = state.nnoisyrestarts;
            state.historylen = 0;
            state.historynext = 0;
            state.lasttrustrad = 0;
            if( state.nnoisyrestarts>0 )
            {
                ablasf.rsetallocm(state.m+state.cntnlc, state.n, 0.0, ref state.lastjac, _params);
                ablasf.rallocv(maxhistory, ref state.trustradhistory, _params);
                ablasf.rallocv(maxhistory, ref state.jacdiffhistory, _params);
                ablasf.rallocv(maxhistory, ref state.iteridxhistory, _params);
            }
            
            //
            // Successful iterations history
            //
            state.successhistorymax = Math.Max(state.n+1, 5);
            state.successhistorylen = 0;
            state.successhistorynext = 0;
            ablasf.rsetallocv(state.successhistorymax, Math.Sqrt(math.maxrealnumber), ref state.successhistory, _params);
        }


        /*************************************************************************
        Updates history

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void updatehistory(dfgmstate state,
            alglib.xparams _params)
        {
            int n = 0;
            int m = 0;
            int cntnlc = 0;
            int i = 0;
            bool b = new bool();
            double jacdiff2 = 0;

            n = state.n;
            m = state.m;
            cntnlc = state.cntnlc;
            if( state.nnoisyrestarts==0 )
            {
                return;
            }
            
            //
            // Enqueue trust radius change
            //
            state.trustradhistory[state.historynext] = 0;
            if( (double)(state.trustradfactor)<(double)(0.999*state.lasttrustrad) )
            {
                state.trustradhistory[state.historynext] = -1;
            }
            if( (double)(state.trustradfactor)>(double)(1.001*state.lasttrustrad) )
            {
                state.trustradhistory[state.historynext] = 1;
            }
            state.lasttrustrad = state.trustradfactor;
            
            //
            // Compute difference in Jacobians, enqueue
            //
            ablasf.rallocv(n, ref state.tmp0, _params);
            jacdiff2 = 0;
            b = false;
            if( state.modeltype==0 )
            {
                for(i=0; i<=m+cntnlc-1; i++)
                {
                    ablasf.rcopyrv(n, state.tpsmodel.jac, i, state.tmp0, _params);
                    ablasf.raddrv(n, -1.0, state.lastjac, i, state.tmp0, _params);
                    jacdiff2 = jacdiff2+ablasf.rdotv2(n, state.tmp0, _params);
                }
                ablasf.rcopym(m+cntnlc, n, state.tpsmodel.jac, state.lastjac, _params);
                b = true;
            }
            if( state.modeltype==1 )
            {
                for(i=0; i<=m+cntnlc-1; i++)
                {
                    ablasf.rcopyrv(n, state.lsamodel.jac, i, state.tmp0, _params);
                    ablasf.raddrv(n, -1.0, state.lastjac, i, state.tmp0, _params);
                    jacdiff2 = jacdiff2+ablasf.rdotv2(n, state.tmp0, _params);
                }
                ablasf.rcopym(m+cntnlc, n, state.lsamodel.jac, state.lastjac, _params);
                b = true;
            }
            alglib.ap.assert(b, "DFGM: integrity check 5451 failed");
            state.jacdiffhistory[state.historynext] = Math.Log(apserv.coalesce(jacdiff2, math.machineepsilon*math.machineepsilon, _params));
            
            //
            // Enqueue iterations count
            //
            state.iteridxhistory[state.historynext] = state.repiterationscount;
            
            //
            // Update history size
            //
            state.historylen = Math.Min(state.historylen+1, maxhistory);
            state.historynext = (state.historynext+1)%maxhistory;
        }


        /*************************************************************************
        Clear history on restart

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void clearhistoryonrestart(dfgmstate state,
            alglib.xparams _params)
        {
            state.historylen = 0;
            state.historynext = 0;
            state.successhistorylen = 0;
            state.successhistorynext = 0;
            ablasf.rsetallocv(state.successhistorymax, Math.Sqrt(math.maxrealnumber), ref state.successhistory, _params);
            clearcloud(state, _params);
        }


        /*************************************************************************
        Compute per-variable trust region using trust region factor and a  current
        location State.Xk

        The trust region is stored to State.TrustRegion[], which is array[N], can
        be automatically allocated by this function.

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void updatetrustregion(dfgmstate state,
            double trustradfactor,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            n = state.n;
            state.trustradfactor = trustradfactor;
            ablasf.rallocv(n, ref state.trustregion, _params);
            ablasf.rallocv(n, ref state.invtrustregion, _params);
            for(i=0; i<=n-1; i++)
            {
                alglib.ap.assert((double)(state.finitebndl[i])<(double)(state.finitebndu[i]), "DFGM: integrity check 4230 failed");
                state.trustregion[i] = trustradfactor*Math.Min(1.0, state.finitebndu[i]-state.finitebndl[i]);
                state.invtrustregion[i] = 1/state.trustregion[i];
            }
        }


        /*************************************************************************
        Returns max(|x[i]|/State.TrustRegion[I])

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static double normrelativetotrustregion(dfgmstate state,
            double[] x,
            alglib.xparams _params)
        {
            double result = 0;
            int i = 0;
            int n = 0;

            n = state.n;
            result = 0;
            for(i=0; i<=n-1; i++)
            {
                result = Math.Max(result, Math.Abs(x[i]/state.trustregion[i]));
            }
            return result;
        }


        /*************************************************************************
        Prepares trial step Sk, Xn=Xk+Sk (guarded  against  box  constraints), loads
        RComm V2 request to  RequestType,  QuerySize,  QueryData  and preallocates
        ReplyFi.

        Returns predicted value of F (target) and sum of constraints violations H

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void preparetrialrequest(dfgmstate state,
            ref double predf,
            ref double predh,
            alglib.xparams _params)
        {
            int n = 0;
            int m = 0;
            int cntlc = 0;
            int cntnlc = 0;
            int nnz = 0;
            int ipmterminationtype = 0;
            int i = 0;
            int j = 0;
            int nx = 0;

            predf = 0;
            predh = 0;

            n = state.n;
            m = state.m;
            cntlc = state.cntlc;
            cntnlc = state.cntnlc;
            predf = 0;
            predh = 0;
            
            //
            // 2PS
            //
            if( state.modeltype==0 )
            {
                alglib.ap.assert(cntlc==0, "DFGM: integrity check 4429 failed");
                alglib.ap.assert(cntnlc==0, "DFGM: integrity check 4430 failed");
                alglib.ap.assert(state.isleastsquares, "DFGM: integrity check 4431 failed");
                
                //
                // Generate trial step
                //
                ablasf.rsetallocv(n, 0.0, ref state.tmp0, _params);
                vipmsolver.vipminitdense(state.ipmsolver, state.trustregion, state.tmp0, n, true, _params);
                vipmsolver.vipmsetquadraticlinear(state.ipmsolver, state.tpsmodel.q, state.sparsedummy, 0, true, state.tpsmodel.g, _params);
                ablasf.rallocv(n, ref state.tmp1, _params);
                for(i=0; i<=n-1; i++)
                {
                    state.tmp0[i] = -state.trustregion[i];
                    state.tmp1[i] = state.trustregion[i];
                    if( state.hasbndl[i] && (double)(state.scaledbndl[i]-state.xk[i])>(double)(state.tmp0[i]) )
                    {
                        state.tmp0[i] = state.scaledbndl[i]-state.xk[i];
                    }
                    if( state.hasbndu[i] && (double)(state.scaledbndu[i]-state.xk[i])<(double)(state.tmp1[i]) )
                    {
                        state.tmp1[i] = state.scaledbndu[i]-state.xk[i];
                    }
                }
                vipmsolver.vipmsetconstraints(state.ipmsolver, state.tmp0, state.tmp1, state.sparsedummy, 0, state.densedummy, 0, state.tmp0, state.tmp1, _params);
                vipmsolver.vipmoptimize(state.ipmsolver, false, ref state.tmp0, ref state.tmp1, ref state.tmp2, ref ipmterminationtype, _params);
                alglib.ap.assert(ipmterminationtype>0, "DFGM: integrity check 7740 failed");
                ablasf.rcopyv(n, state.tmp0, state.sk, _params);
                ablasf.rcopyv(n, state.xk, state.xn, _params);
                ablasf.raddv(n, 1.0, state.sk, state.xn, _params);
                optserv.enforceboundaryconstraints(state.xn, state.scaledbndl, state.hasbndl, state.scaledbndu, state.hasbndu, n, 0, _params);
                
                //
                // Predicted value of target and constraints
                //
                alglib.ap.assert(cntlc==0, "DFGM: integrity check 9544 failed");
                alglib.ap.assert(cntnlc==0, "DFGM: integrity check 9545 failed");
                ablasf.rallocv(n, ref state.tmp0, _params);
                ablasf.rgemv(n, n, 1.0, state.tpsmodel.q, 0, state.sk, 0.0, state.tmp0, _params);
                predf = state.fk+ablasf.rdotv(n, state.sk, state.tpsmodel.g, _params)+0.5*ablasf.rdotv(n, state.sk, state.tmp0, _params);
                predh = 0;
                
                //
                // Issue RComm V2 request
                //
                state.requesttype = 4;
                state.querysize = 1;
                ablasf.rcopyallocv(n, state.xn, ref state.querydata, _params);
                ablasf.rallocv(m+cntnlc, ref state.replyfi, _params);
                sendrequesttocloud(state, state.querydata, state.querysize, _params);
                
                //
                // Done
                //
                return;
            }
            
            //
            // DFO-LSA
            //
            if( state.modeltype==1 )
            {
                alglib.ap.assert(cntlc==0, "DFGM: integrity check 2539 failed");
                alglib.ap.assert(cntnlc==0, "DFGM: integrity check 2639 failed");
                alglib.ap.assert(state.isleastsquares, "DFGM: integrity check 2739 failed");
                
                //
                // Generate trial step
                //
                ablasf.rsetallocv(n, 0.0, ref state.tmp0, _params);
                vipmsolver.vipminitdense(state.ipmsolver, state.trustregion, state.tmp0, n, true, _params);
                vipmsolver.vipmsetquadraticlinear(state.ipmsolver, state.lsamodel.q, state.sparsedummy, 0, true, state.lsamodel.g, _params);
                ablasf.rallocv(n, ref state.tmp1, _params);
                for(i=0; i<=n-1; i++)
                {
                    state.tmp0[i] = -state.trustregion[i];
                    state.tmp1[i] = state.trustregion[i];
                    if( state.hasbndl[i] && (double)(state.scaledbndl[i]-state.xk[i])>(double)(state.tmp0[i]) )
                    {
                        state.tmp0[i] = state.scaledbndl[i]-state.xk[i];
                    }
                    if( state.hasbndu[i] && (double)(state.scaledbndu[i]-state.xk[i])<(double)(state.tmp1[i]) )
                    {
                        state.tmp1[i] = state.scaledbndu[i]-state.xk[i];
                    }
                }
                vipmsolver.vipmsetconstraints(state.ipmsolver, state.tmp0, state.tmp1, state.sparsedummy, 0, state.densedummy, 0, state.tmp0, state.tmp1, _params);
                vipmsolver.vipmoptimize(state.ipmsolver, false, ref state.tmp0, ref state.tmp1, ref state.tmp2, ref ipmterminationtype, _params);
                alglib.ap.assert(ipmterminationtype>0, "DFGM: integrity check 7740 failed");
                ablasf.rcopyv(n, state.tmp0, state.sk, _params);
                ablasf.rcopyv(n, state.xk, state.xn, _params);
                ablasf.raddv(n, 1.0, state.sk, state.xn, _params);
                optserv.enforceboundaryconstraints(state.xn, state.scaledbndl, state.hasbndl, state.scaledbndu, state.hasbndu, n, 0, _params);
                
                //
                // Predicted value of target and constraints
                //
                alglib.ap.assert(cntlc==0, "DFGM: integrity check 9544 failed");
                alglib.ap.assert(cntnlc==0, "DFGM: integrity check 9545 failed");
                ablasf.rallocv(n, ref state.tmp0, _params);
                ablasf.rgemv(n, n, 1.0, state.lsamodel.q, 0, state.sk, 0.0, state.tmp0, _params);
                predf = state.fk+ablasf.rdotv(n, state.sk, state.lsamodel.g, _params)+0.5*ablasf.rdotv(n, state.sk, state.tmp0, _params);
                predh = 0;
                
                //
                // Issue RComm V2 request
                //
                state.requesttype = 4;
                state.querysize = 1;
                ablasf.rcopyallocv(n, state.xn, ref state.querydata, _params);
                ablasf.rallocv(m+cntnlc, ref state.replyfi, _params);
                sendrequesttocloud(state, state.querydata, state.querysize, _params);
                
                //
                // Done
                //
                return;
            }
            
            //
            // ORBIT
            //
            if( state.modeltype==2 )
            {
                rbfinitializemodelfromworkingset(state, _params);
                optserv.critinitdefault(state.rbfmodel.crit, _params);
                optserv.critsetcondv1(state.rbfmodel.crit, 0.0, rbfsubsolverepsx, 0, _params);
                nx = n+2*cntlc+2*cntnlc;
                ablasf.rallocv(nx, ref state.rbfmodel.tmpbndl, _params);
                ablasf.rallocv(nx, ref state.rbfmodel.tmpbndu, _params);
                ablasf.rallocv(nx, ref state.rbfmodel.tmpx0, _params);
                ablasf.rallocv(nx, ref state.rbfmodel.tmps, _params);
                for(i=0; i<=n-1; i++)
                {
                    state.rbfmodel.tmpbndl[i] = state.xk[i]-state.trustregion[i];
                    state.rbfmodel.tmpbndu[i] = state.xk[i]+state.trustregion[i];
                    if( state.hasbndl[i] && (double)(state.scaledbndl[i])>(double)(state.rbfmodel.tmpbndl[i]) )
                    {
                        state.rbfmodel.tmpbndl[i] = state.scaledbndl[i];
                    }
                    if( state.hasbndu[i] && (double)(state.scaledbndu[i])<(double)(state.rbfmodel.tmpbndu[i]) )
                    {
                        state.rbfmodel.tmpbndu[i] = state.scaledbndu[i];
                    }
                    state.rbfmodel.tmpx0[i] = state.xk[i];
                    state.rbfmodel.tmps[i] = state.trustregion[i];
                }
                for(i=n; i<=nx-1; i++)
                {
                    state.rbfmodel.tmpbndl[i] = 0.0;
                    state.rbfmodel.tmpbndu[i] = Double.PositiveInfinity;
                    state.rbfmodel.tmps[i] = state.trustradfactor;
                    state.rbfmodel.tmpx0[i] = 0.0;
                }
                ablasf.rallocv(cntlc+1, ref state.rbfmodel.clx, _params);
                ablasf.rallocv(cntlc+1, ref state.rbfmodel.cux, _params);
                sparse.sparsecreatecrsemptybuf(nx, state.rbfmodel.cx, _params);
                ablasf.iallocv(nx, ref state.tmpi, _params);
                ablasf.rallocv(nx, ref state.tmp0, _params);
                for(i=0; i<=cntlc-1; i++)
                {
                    nnz = 0;
                    for(j=state.c.ridx[i]; j<=state.c.ridx[i+1]-1; j++)
                    {
                        state.tmpi[nnz] = state.c.idx[j];
                        state.tmp0[nnz] = state.c.vals[j];
                        nnz = nnz+1;
                    }
                    state.rbfmodel.clx[i] = state.cl[i];
                    if( math.isfinite(state.cl[i]) )
                    {
                        state.tmpi[nnz] = n+2*i+0;
                        state.tmp0[nnz] = 1.0;
                        nnz = nnz+1;
                    }
                    state.rbfmodel.cux[i] = state.cu[i];
                    if( math.isfinite(state.cu[i]) )
                    {
                        state.tmpi[nnz] = n+2*i+1;
                        state.tmp0[nnz] = -1.0;
                        nnz = nnz+1;
                    }
                    alglib.ap.assert(nnz<=nx, "DFGM: integrity check 345240 failed");
                    sparse.sparseappendcompressedrow(state.rbfmodel.cx, state.tmpi, state.tmp0, nnz, _params);
                }
                ablasf.iallocv(cntlc, ref state.tmpi, _params);
                for(i=0; i<=cntlc-1; i++)
                {
                    state.tmpi[i] = i;
                }
                nlcfsqp.minfsqpinitbuf(state.rbfmodel.tmpbndl, state.rbfmodel.tmpbndu, state.rbfmodel.tmps, state.rbfmodel.tmpx0, nx, state.rbfmodel.cx, state.rbfmodel.clx, state.rbfmodel.cux, state.tmpi, cntlc, state.nl, state.nu, cntnlc, state.rbfmodel.crit, false, state.rbfmodel.fsqpsolver, _params);
                optserv.smoothnessmonitorinit(state.rbfmodel.smonitor, state.rbfmodel.tmps, nx, 1+cntnlc, false, _params);
                while( nlcfsqp.minfsqpiteration(state.rbfmodel.fsqpsolver, state.rbfmodel.smonitor, false, _params) )
                {
                    if( state.rbfmodel.fsqpsolver.xupdated )
                    {
                        continue;
                    }
                    if( state.rbfmodel.fsqpsolver.needfisj )
                    {
                        
                        //
                        // Compute the original model in Fi[] and its gradient in tmp1[]
                        //
                        ablasf.rallocv(nx, ref state.tmp0, _params);
                        ablasf.rallocv((m+cntnlc)*n, ref state.tmp1, _params);
                        ablasf.rcopyv(nx, state.rbfmodel.fsqpsolver.x, state.tmp0, _params);
                        ablasf.rmergemulv(nx, state.rbfmodel.tmps, state.tmp0, _params);
                        ablasf.rmergemaxv(nx, state.rbfmodel.tmpbndl, state.tmp0, _params);
                        ablasf.rmergeminv(nx, state.rbfmodel.tmpbndu, state.tmp0, _params);
                        rbfcomputemodel(state, state.tmp0, state.rbfmodel.fsqpsolver.fi, true, state.tmp1, true, _params);
                        
                        //
                        // Modify the model by replacing objective with a sum of constraint violations and
                        // by adding slacks to nonlinear constraints.
                        //
                        ablasf.rsetallocv((m+cntnlc)*nx, 0.0, ref state.tmp2, _params);
                        state.rbfmodel.fsqpsolver.fi[0] = 0;
                        for(j=n; j<=nx-1; j++)
                        {
                            state.rbfmodel.fsqpsolver.fi[0] = state.rbfmodel.fsqpsolver.fi[0]+state.tmp0[j];
                            state.tmp2[j] = 1.0;
                        }
                        for(i=1; i<=cntnlc; i++)
                        {
                            ablasf.rcopyvx(n, state.tmp1, i*n, state.tmp2, i*nx, _params);
                            if( math.isfinite(state.nl[i-1]) )
                            {
                                j = n+2*cntlc+2*(i-1)+0;
                                state.rbfmodel.fsqpsolver.fi[i] = state.rbfmodel.fsqpsolver.fi[i]+state.tmp0[j];
                                state.tmp2[i*nx+j] = 1.0;
                            }
                            if( math.isfinite(state.nu[i-1]) )
                            {
                                j = n+2*cntlc+2*(i-1)+1;
                                state.rbfmodel.fsqpsolver.fi[i] = state.rbfmodel.fsqpsolver.fi[i]-state.tmp0[j];
                                state.tmp2[i*nx+j] = -1.0;
                            }
                        }
                        sparse.sparsecreatecrsfromdensev(state.tmp2, 1+cntnlc, nx, state.rbfmodel.fsqpsolver.sj, _params);
                        sparse.sparsemultiplycolsby(state.rbfmodel.fsqpsolver.sj, state.rbfmodel.tmps, _params);
                        continue;
                    }
                    alglib.ap.assert(false, "DFGM: integrity check 261738 failed");
                }
                alglib.ap.assert(state.rbfmodel.fsqpsolver.repterminationtype>0, "DFGM: integrity check 265740 failed");
                state.repsubsolverits = state.repsubsolverits+state.rbfmodel.fsqpsolver.repiterationscount;
                
                //
                // Extract stopping point and compute predicted decrease in constraint violation
                //
                ablasf.rcopyv(nx, state.rbfmodel.fsqpsolver.stepk.x, state.rbfmodel.tmpx0, _params);
                ablasf.rmergemulv(nx, state.rbfmodel.tmps, state.rbfmodel.tmpx0, _params);
                ablasf.rmergemaxv(nx, state.rbfmodel.tmpbndl, state.rbfmodel.tmpx0, _params);
                ablasf.rmergeminv(nx, state.rbfmodel.tmpbndu, state.rbfmodel.tmpx0, _params);
                predh = 0.0;
                for(i=n; i<=nx-1; i++)
                {
                    predh = predh+state.rbfmodel.tmpx0[i];
                }
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format("$$ {0,0:d} its, best pred H = {1,0:E3}\n", state.rbfmodel.fsqpsolver.repiterationscount, predh));
                }
                
                //
                // Append a constraint on maximum constraint violation to the original problem, solve it
                //
                ablasf.iallocv(nx, ref state.tmpi, _params);
                ablasf.rallocv(nx, ref state.tmp0, _params);
                nnz = 0;
                for(i=n; i<=nx-1; i++)
                {
                    state.tmpi[nnz] = i;
                    state.tmp0[nnz] = 1.0;
                    nnz = nnz+1;
                }
                alglib.ap.assert(alglib.ap.len(state.rbfmodel.clx)>=cntlc+1 && alglib.ap.len(state.rbfmodel.cux)>=cntlc+1, "DFGM: integrity check 423305 failed");
                sparse.sparseappendcompressedrow(state.rbfmodel.cx, state.tmpi, state.tmp0, nnz, _params);
                state.rbfmodel.clx[cntlc] = Double.NegativeInfinity;
                state.rbfmodel.cux[cntlc] = predh;
                ablasf.iallocv(cntlc+1, ref state.tmpi, _params);
                for(i=0; i<=cntlc; i++)
                {
                    state.tmpi[i] = i;
                }
                nlcfsqp.minfsqpinitbuf(state.rbfmodel.tmpbndl, state.rbfmodel.tmpbndu, state.rbfmodel.tmps, state.rbfmodel.tmpx0, nx, state.rbfmodel.cx, state.rbfmodel.clx, state.rbfmodel.cux, state.tmpi, cntlc+1, state.nl, state.nu, cntnlc, state.rbfmodel.crit, false, state.rbfmodel.fsqpsolver, _params);
                optserv.smoothnessmonitorinit(state.rbfmodel.smonitor, state.rbfmodel.tmps, nx, 1+cntnlc, false, _params);
                while( nlcfsqp.minfsqpiteration(state.rbfmodel.fsqpsolver, state.rbfmodel.smonitor, false, _params) )
                {
                    if( state.rbfmodel.fsqpsolver.xupdated )
                    {
                        continue;
                    }
                    if( state.rbfmodel.fsqpsolver.needfisj )
                    {
                        
                        //
                        // Compute the original model in Fi[] and its gradient in tmp1[]
                        //
                        ablasf.rallocv(nx, ref state.tmp0, _params);
                        ablasf.rallocv((m+cntnlc)*n, ref state.tmp1, _params);
                        ablasf.rcopyv(nx, state.rbfmodel.fsqpsolver.x, state.tmp0, _params);
                        ablasf.rmergemulv(nx, state.rbfmodel.tmps, state.tmp0, _params);
                        ablasf.rmergemaxv(nx, state.rbfmodel.tmpbndl, state.tmp0, _params);
                        ablasf.rmergeminv(nx, state.rbfmodel.tmpbndu, state.tmp0, _params);
                        rbfcomputemodel(state, state.tmp0, state.rbfmodel.fsqpsolver.fi, true, state.tmp1, true, _params);
                        
                        //
                        // Modify the model by adding slacks to nonlinear constraints.
                        //
                        ablasf.rsetallocv((m+cntnlc)*nx, 0.0, ref state.tmp2, _params);
                        ablasf.rcopyvx(n, state.tmp1, 0, state.tmp2, 0, _params);
                        for(i=1; i<=cntnlc; i++)
                        {
                            ablasf.rcopyvx(n, state.tmp1, i*n, state.tmp2, i*nx, _params);
                            if( math.isfinite(state.nl[i-1]) )
                            {
                                j = n+2*cntlc+2*(i-1)+0;
                                state.rbfmodel.fsqpsolver.fi[i] = state.rbfmodel.fsqpsolver.fi[i]+state.tmp0[j];
                                state.tmp2[i*nx+j] = 1.0;
                            }
                            if( math.isfinite(state.nu[i-1]) )
                            {
                                j = n+2*cntlc+2*(i-1)+1;
                                state.rbfmodel.fsqpsolver.fi[i] = state.rbfmodel.fsqpsolver.fi[i]-state.tmp0[j];
                                state.tmp2[i*nx+j] = -1.0;
                            }
                        }
                        sparse.sparsecreatecrsfromdensev(state.tmp2, 1+cntnlc, nx, state.rbfmodel.fsqpsolver.sj, _params);
                        sparse.sparsemultiplycolsby(state.rbfmodel.fsqpsolver.sj, state.rbfmodel.tmps, _params);
                        continue;
                    }
                    alglib.ap.assert(false, "DFGM: integrity check 261738 failed");
                }
                state.repsubsolverits = state.repsubsolverits+state.rbfmodel.fsqpsolver.repiterationscount;
                ablasf.rcopyv(n, state.rbfmodel.fsqpsolver.stepk.x, state.xn, _params);
                ablasf.rmergemulv(n, state.trustregion, state.xn, _params);
                ablasf.rmergemaxv(n, state.finitebndl, state.xn, _params);
                ablasf.rmergeminv(n, state.finitebndu, state.xn, _params);
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format("$$ {0,0:d} its in optimization phase\n", state.rbfmodel.fsqpsolver.repiterationscount));
                }
                
                //
                //
                //
                ablasf.rallocv(m+cntnlc, ref state.tmp1, _params);
                ablasf.rcopyv(n, state.xn, state.sk, _params);
                ablasf.raddv(n, -1.0, state.xk, state.sk, _params);
                rbfcomputemodel(state, state.xn, state.tmp1, true, state.tmp0, false, _params);
                predf = state.tmp1[0];
                predh = 0;
                if( cntlc>0 )
                {
                    sparse.sparsemv(state.c, state.xn, ref state.tmp0, _params);
                    for(i=0; i<=cntlc-1; i++)
                    {
                        if( math.isfinite(state.cl[i]) )
                        {
                            predh = predh+Math.Max(state.cl[i]-state.tmp0[i], 0.0);
                        }
                        if( math.isfinite(state.cu[i]) )
                        {
                            predh = predh+Math.Max(state.tmp0[i]-state.cu[i], 0.0);
                        }
                    }
                }
                for(i=0; i<=cntnlc-1; i++)
                {
                    if( math.isfinite(state.nl[i]) )
                    {
                        predh = predh+Math.Max(state.nl[i]-state.tmp1[m+i], 0.0);
                    }
                    if( math.isfinite(state.nu[i]) )
                    {
                        predh = predh+Math.Max(state.tmp1[m+i]-state.nu[i], 0.0);
                    }
                }
                
                //
                // Issue RComm V2 request
                //
                state.requesttype = 4;
                state.querysize = 1;
                ablasf.rcopyallocv(n, state.xn, ref state.querydata, _params);
                ablasf.rallocv(m+cntnlc, ref state.replyfi, _params);
                sendrequesttocloud(state, state.querydata, state.querysize, _params);
                
                //
                // Done
                //
                return;
            }
            
            //
            // Unexpected
            //
            alglib.ap.assert(false, "DFGM: PrepareTrialRequest() is unable to handle unexpected algorithm");
        }


        /*************************************************************************
        Processes results of the RComm V2 request for a trial point.

        Returns the value of F (target) and sum of constraints violations H

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void processtrialrequest(dfgmstate state,
            ref double f,
            ref double h,
            alglib.xparams _params)
        {
            int i = 0;
            int m = 0;
            int cntlc = 0;
            int cntnlc = 0;

            f = 0;
            h = 0;

            m = state.m;
            cntlc = state.cntlc;
            cntnlc = state.cntnlc;
            f = 0;
            h = 0;
            
            //
            // 2PS, LSA
            //
            if( state.modeltype==0 || state.modeltype==1 )
            {
                alglib.ap.assert(cntlc==0, "DFGM: integrity check 6222 failed");
                alglib.ap.assert(cntnlc==0, "DFGM: integrity check 6323 failed");
                alglib.ap.assert(state.isleastsquares, "DFGM: integrity check 6424 failed");
                alglib.ap.assert(state.querysize==1, "DFGM: integrity check 3540 failed");
                f = 0.5*ablasf.rdotv2(m, state.replyfi, _params);
                h = 0;
                ablasf.rcopyv(m+cntnlc, state.replyfi, state.fnvec, _params);
                sendreplytocloud(state, state.replyfi, _params);
                return;
            }
            
            //
            // ORBIT
            //
            if( state.modeltype==2 )
            {
                alglib.ap.assert(!state.isleastsquares, "DFGM: integrity check 240106 failed");
                alglib.ap.assert(state.querysize==1, "DFGM: integrity check 241107 failed");
                f = state.replyfi[0];
                h = 0;
                if( cntlc>0 )
                {
                    sparse.sparsemv(state.c, state.xn, ref state.tmp0, _params);
                    for(i=0; i<=cntlc-1; i++)
                    {
                        if( math.isfinite(state.cl[i]) )
                        {
                            h = h+Math.Max(state.cl[i]-state.tmp0[i], 0.0);
                        }
                        if( math.isfinite(state.cu[i]) )
                        {
                            h = h+Math.Max(state.tmp0[i]-state.cu[i], 0.0);
                        }
                    }
                }
                for(i=0; i<=cntnlc-1; i++)
                {
                    if( math.isfinite(state.nl[i]) )
                    {
                        h = h+Math.Max(state.nl[i]-state.replyfi[m+i], 0.0);
                    }
                    if( math.isfinite(state.nu[i]) )
                    {
                        h = h+Math.Max(state.replyfi[m+i]-state.nu[i], 0.0);
                    }
                }
                ablasf.rcopyv(m+cntnlc, state.replyfi, state.fnvec, _params);
                sendreplytocloud(state, state.replyfi, _params);
                return;
            }
            alglib.ap.assert(false, "DFGM: ProcessTrialRequest() is unable to handle unexpected algorithm");
        }


        /*************************************************************************
        Tests step acceptance.

        Input parameters:
        * Fk, Hk - current target Fk and a sum of constraint violations Hk at Xk
        * Fp, Hp - predicted values
        * Fn, Hn - actual values at Xn=Xk+Sk

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static bool testacceptancebyfilter(dfgmstate state,
            double fk,
            double hk,
            double fp,
            double hp,
            double fn,
            double hn,
            alglib.xparams _params)
        {
            bool result = new bool();

            
            //
            // Reject, if the step does not improve either F or H
            //
            if( (double)(fn)>=(double)(fk) && (double)(hn)>=(double)(hk) )
            {
                result = false;
                return result;
            }
            
            //
            // The step is an h-type step that reduces constraint violation, however
            // fails to reduce it to zero within the trust region.
            //
            if( ((double)(hk)>(double)(0) && (double)(hp)<(double)(hk)) && (double)(hp)>(double)(0.001*hk) )
            {
                result = (double)(hn-hk)<(double)(eta1*(hp-hk));
                return result;
            }
            
            //
            // The step is an f-type step
            //
            // NOTE: it is important to have this block after the previous one, not before;
            //       having it before in its present form means that steps that reduce constraint
            //       violation but increase objective will not be accepted.
            //
            if( (double)(fp)<(double)(fk) && (double)(fn-fk)>(double)(eta1*(fp-fk)) )
            {
                result = false;
                return result;
            }
            result = optserv.nlpfisacceptable(state.filter, fk, hk, fn, hn, _params);
            return result;
        }


        /*************************************************************************
        Sets signal that the step was accepted.

        Presently it does the following
        * inserts current iterate into the filter. If the iterate is not
          acceptable, it is silently denied.

        * if Fn<Fk, appends Fn-Fk to State.SuccessHistory

        Input parameters:
        * Fn, Hn - target Fk and a sum of constraint violations Hk at Xn=Xk+Sk

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void sendstepacceptancetomodel(dfgmstate state,
            double fk,
            double hk,
            double fn,
            double hn,
            alglib.xparams _params)
        {
            
            //
            // Append to the filter
            //
            if( optserv.nlpfisacceptable1(state.filter, fn, hn, _params) )
            {
                if( (double)(hk)>(double)(0) )
                {
                    optserv.nlpfappend(state.filter, fk, hk, _params);
                }
            }
            
            //
            // Append to the State.SuccessHistory
            //
            if( (double)(fn)<(double)(fk) )
            {
                state.successhistorylen = Math.Min(state.successhistorylen+1, state.successhistorymax);
                alglib.ap.assert(state.successhistorynext<=state.successhistorylen-1, "DFGM: integrity check 697019 failed");
                state.successhistory[state.successhistorynext] = fn-fk;
                state.successhistorynext = (state.successhistorynext+1)%state.successhistorymax;
            }
        }


        /*************************************************************************
        Sends information about denial of the current step.

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void sendstepdenialtomodel(dfgmstate state,
            alglib.xparams _params)
        {
            
            //
            // 2PS
            //
            if( state.modeltype==0 )
            {
                return;
            }
            
            //
            // LSA
            //
            if( state.modeltype==1 )
            {
                return;
            }
            
            //
            // ORBIT
            //
            if( state.modeltype==2 )
            {
                return;
            }
            alglib.ap.assert(false, "DFGM: SendDenialToModel() is unable to handle unexpected algorithm");
        }


        /*************************************************************************
        Returns true if State.DeltaK is roughly State.RhoK

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static bool deltakatminimum(dfgmstate state,
            alglib.xparams _params)
        {
            bool result = new bool();

            result = (double)(state.trustradfactor)<=(double)(state.trustradbnd*1.01);
            return result;
        }


        /*************************************************************************
        Returns true if restart is recommended right now

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static bool restartautodetected(dfgmstate state,
            alglib.xparams _params)
        {
            bool result = new bool();

            result = false;
            return result;
        }


        /*************************************************************************
        Returns true if working set needs improvement

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static bool workingsetneedsimprovement(dfgmstate state,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int i = 0;
            int j = 0;
            double mostdistant = 0;
            double leastdistant = 0;

            n = state.n;
            result = false;
            
            //
            // 2PS, LSA
            //
            if( state.modeltype==0 || state.modeltype==1 )
            {
                alglib.ap.assert(state.wrksetsize==n+1, "DFGM: integrity check 2111 failed");
                mostandleastdistant(state.invtrustregion, n, state.wrkset, state.wrksetsize, ref mostdistant, ref i, ref leastdistant, ref j, _params);
                if( state.modeltype==0 )
                {
                    result = (double)(mostdistant)>(double)(twopsstephi) || (double)(leastdistant)<(double)(twopssteplo);
                }
                else
                {
                    result = (double)(mostdistant)>(double)(pointtoofar) || (double)(leastdistant)<(double)(pointtooclose);
                }
                return result;
            }
            
            //
            // ORBIT
            //
            if( state.modeltype==2 )
            {
                
                //
                // ORBIT does not check this condition
                //
                result = false;
                return result;
            }
            alglib.ap.assert(false, "DFGM: WorkingSetNeedsImprovement() is unable to handle unexpected algorithm");
            return result;
        }


        /*************************************************************************
        Handle successful or failed step.

        This function updates working set and (for some solvers) issues additional
        RComm V2 requests if working set needs immediate revaluation.

        It also updates the model.

        On exit it may set State.RepTerminationType to a negative  code  (failure)
        if it encountered infinities in the target/constraints during  update  and
        failed to recover from the problem.

        !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
        It expects that State.Xk and State.FkVec were already updated at the moment
        this function is called.
        !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static bool updateworkingsetandmodel(dfgmstate state,
            double[] xk,
            double[] xn,
            double[] fnvec,
            double fn,
            double hn,
            bool successfulstep,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int m = 0;
            int cntlc = 0;
            int cntnlc = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            int replaceidx = 0;
            double rating = 0;
            double bestrating = 0;
            double v = 0;
            double vv = 0;
            double mx = 0;

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rstateupdate.stage>=0 )
            {
                n = state.rstateupdate.ia[0];
                m = state.rstateupdate.ia[1];
                cntlc = state.rstateupdate.ia[2];
                cntnlc = state.rstateupdate.ia[3];
                i = state.rstateupdate.ia[4];
                j = state.rstateupdate.ia[5];
                k = state.rstateupdate.ia[6];
                replaceidx = state.rstateupdate.ia[7];
                rating = state.rstateupdate.ra[0];
                bestrating = state.rstateupdate.ra[1];
                v = state.rstateupdate.ra[2];
                vv = state.rstateupdate.ra[3];
                mx = state.rstateupdate.ra[4];
            }
            else
            {
                n = -541;
                m = -698;
                cntlc = -900;
                cntnlc = -318;
                i = -940;
                j = 1016;
                k = -229;
                replaceidx = -536;
                rating = 487.0;
                bestrating = -115.0;
                v = 886.0;
                vv = 346.0;
                mx = -722.0;
            }
            if( state.rstateupdate.stage==0 )
            {
                goto lbl_0;
            }
            if( state.rstateupdate.stage==1 )
            {
                goto lbl_1;
            }
            
            //
            // Routine body
            //
            n = state.n;
            m = state.m;
            cntlc = state.cntlc;
            cntnlc = state.cntnlc;
            
            //
            // 2PS
            //
            if( state.modeltype!=0 )
            {
                goto lbl_2;
            }
            
            //
            // Do not update working set on unsuccessful steps because this solver uses fixed
            // stencil which does not allow inclusion of arbitrary points. The only way to update
            // working set is to rebuild it at a new point using the same stencil.
            //
            if( !successfulstep )
            {
                result = false;
                return result;
            }
            
            //
            // Clear working set (it will be recomputed from scratch on a new place) and call working set improvement code
            //
            state.wrksetsize = 0;
            state.rstateimprove.ia = new int[13+1];
            state.rstateimprove.ba = new bool[0+1];
            state.rstateimprove.ra = new double[12+1];
            state.rstateimprove.stage = -1;
            state.rstateimprove.clear_handler();
        lbl_4:
            if( !improveworkingsetgeometry(state, _params) )
            {
                goto lbl_5;
            }
            state.rstateupdate.stage = 0;
            if( state.rstateupdate.rcomm2_handler!=null && state.rstateupdate.requesttype!=0 && state.rstateupdate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstateupdate.rcomm2_handler(state.rstateupdate, state.rstateupdate.handler_p0, state.rstateupdate.handler_p1, state.rstateupdate.handler_p2, state.rstateupdate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
            goto lbl_4;
        lbl_5:
            result = false;
            return result;
        lbl_2:
            
            //
            // LSA
            //
            if( state.modeltype==1 )
            {
                
                //
                // If the step was not successful, we have to skip update if the new point
                // is too close to the center. When the step is successful, we can replace
                // the center. But it is not possible on unsuccessful steps.
                //
                if( !successfulstep )
                {
                    v = 0;
                    for(j=0; j<=n-1; j++)
                    {
                        v = Math.Max(v, Math.Abs(xn[j]-xk[j])*state.invtrustregion[j]);
                    }
                    if( (double)(v)<(double)(pointtooclose) )
                    {
                        result = false;
                        return result;
                    }
                }
                
                //
                // Select ReplaceIdx - index of a point to replace by the new point Xn,
                // with 0<=ReplaceIdx<N meaning replacing off-center points of the working
                // set, and ReplaceIdx=N meaning replacing (previously) central point.
                //
                ablasf.rallocv(n, ref state.tmp0, _params);
                ablasf.rallocv(n, ref state.tmp1, _params);
                replaceidx = -1;
                bestrating = 0;
                for(i=0; i<=n; i++)
                {
                    
                    //
                    // Skip central point if the step is not successful (we remain at the old
                    // place, so the central point can not be replaced)
                    //
                    if( i==n && !successfulstep )
                    {
                        break;
                    }
                    
                    //
                    // Compute Lagrange polynomial coefficients
                    //
                    if( i==n )
                    {
                        ablasf.rsetv(n, 0.0, state.tmp0, _params);
                        for(j=0; j<=n-1; j++)
                        {
                            ablasf.rcopycv(n, state.lsamodel.invw, j, state.tmp1, _params);
                            ablasf.raddv(n, -1.0, state.tmp1, state.tmp0, _params);
                        }
                    }
                    else
                    {
                        ablasf.rcopycv(n, state.lsamodel.invw, i, state.tmp0, _params);
                    }
                    
                    //
                    // Compute rating as |L(Xn-Xk)|*max(|Xn-Wrk[I]|/Scales,1)^2, compare with the best
                    //
                    ablasf.rcopyrv(n, state.wrkset, i, state.tmp1, _params);
                    ablasf.raddv(n, -1.0, xn, state.tmp1, _params);
                    rating = Math.Abs(ablasf.rdotv(n, xn, state.tmp0, _params)-ablasf.rdotv(n, xk, state.tmp0, _params)+apserv.rcase2(i==n, 1, 0, _params))*math.sqr(Math.Max(normrelativetotrustregion(state, state.tmp1, _params), 1));
                    if( replaceidx<0 || (double)(rating)>(double)(bestrating) )
                    {
                        replaceidx = i;
                        bestrating = rating;
                    }
                }
                alglib.ap.assert(replaceidx>=0, "DFGM: integrity check 2850 failed");
                if( state.dotrace )
                {
                    if( replaceidx<n )
                    {
                        alglib.ap.trace(System.String.Format(">> replacing point {0,0:d} (non-central)\n", replaceidx));
                    }
                    else
                    {
                        alglib.ap.trace(">> replacing previously central point\n");
                    }
                }
                
                //
                // Modify WrkSet
                //
                if( successfulstep )
                {
                    if( replaceidx<n )
                    {
                        
                        //
                        // Successful step, we replace off-central point by Xn.
                        //
                        // Because we always move Xn to N-th row of the working set, it means
                        // that we push the former central point from the row #N to the
                        // ReplaceIdx-th one.
                        //
                        ablasf.rcopyrr(n+m+cntnlc, state.wrkset, n, state.wrkset, replaceidx, _params);
                        ablasf.rcopyvr(n, xn, state.wrkset, n, _params);
                        for(i=0; i<=m+cntnlc-1; i++)
                        {
                            state.wrkset[n,n+i] = fnvec[i];
                        }
                    }
                    else
                    {
                        
                        //
                        // Successful step, we replace central point by Xn.
                        //
                        ablasf.rcopyvr(n, xn, state.wrkset, n, _params);
                        for(i=0; i<=m+cntnlc-1; i++)
                        {
                            state.wrkset[n,n+i] = fnvec[i];
                        }
                    }
                }
                else
                {
                    
                    //
                    // Non-successful step, only off-central point can be replaced. The center
                    // is not replaced or moved.
                    //
                    alglib.ap.assert(replaceidx<n, "DFGM: integrity check 6712 failed");
                    ablasf.rcopyvr(n, xn, state.wrkset, replaceidx, _params);
                    for(i=0; i<=m+cntnlc-1; i++)
                    {
                        state.wrkset[replaceidx,n+i] = fnvec[i];
                    }
                }
                
                //
                // Recompute matrices W and InvW
                //
                for(i=0; i<=n-1; i++)
                {
                    ablasf.rcopyrr(n, state.wrkset, i, state.lsamodel.w, i, _params);
                    ablasf.raddrr(n, -1.0, state.wrkset, n, state.lsamodel.w, i, _params);
                }
                ablasf.rcopym(n, n, state.lsamodel.w, state.lsamodel.invw, _params);
                matinv.rmatrixinverse(state.lsamodel.invw, n, state.invrep, _params);
                if( state.invrep.terminationtype<=0 )
                {
                    if( state.dotrace )
                    {
                        alglib.ap.trace(">> dataset matrix inverse failed, emergency termination with completion code +7\n");
                    }
                    state.repterminationtype = 7;
                    result = false;
                    return result;
                }
                if( state.dotrace )
                {
                    alglib.ap.trace(System.String.Format(">> successfully inverted dataset matrix, cond={0,0:E2}\n", 1/(state.invrep.r1+math.machineepsilon)));
                    ablasf.rallocv(n, ref state.tmp0, _params);
                    ablasf.rallocv(n, ref state.tmp1, _params);
                    v = 0;
                    for(i=0; i<=n; i++)
                    {
                        if( i==n )
                        {
                            ablasf.rsetv(n, 0.0, state.tmp0, _params);
                            for(j=0; j<=n-1; j++)
                            {
                                ablasf.rcopycv(n, state.lsamodel.invw, j, state.tmp1, _params);
                                ablasf.raddv(n, -1.0, state.tmp1, state.tmp0, _params);
                            }
                        }
                        else
                        {
                            ablasf.rcopycv(n, state.lsamodel.invw, i, state.tmp0, _params);
                        }
                        v = Math.Max(v, maxabslag(xn, n, state.trustregion, state.finitebndl, state.finitebndu, state.tmp0, apserv.rcase2(i==n, 1, 0, _params), state.tmp1, state.tmp2, false, _params));
                    }
                    alglib.ap.trace(System.String.Format(">> poisedness constant is {0,0:E2}\n", v));
                }
                
                //
                // The working set is ready, rebuild a quadratic model of the target.
                //
                // Below we rely on the specific ordering of the working set
                // (the central point comes last, N additional ones come first).
                //
                alglib.ap.assert(state.cntnlc==0, "DFGM: integrity check 4811 failed");
                alglib.ap.assert(state.wrksetsize==n+1, "DFGM: integrity check 0425 failed");
                ablasf.rallocm(n, m, ref state.lsamodel.tmprhs, _params);
                ablas.rmatrixcopy(n, m, state.wrkset, 0, n, state.lsamodel.tmprhs, 0, 0, _params);
                ablasf.rallocv(m, ref state.lsamodel.tmp0, _params);
                for(i=0; i<=m-1; i++)
                {
                    state.lsamodel.tmp0[i] = state.wrkset[n,n+i];
                }
                for(i=0; i<=n-1; i++)
                {
                    ablasf.raddvr(m, -1.0, state.lsamodel.tmp0, state.lsamodel.tmprhs, i, _params);
                }
                ablasf.rallocm(m, n, ref state.lsamodel.jac, _params);
                ablas.rmatrixgemm(m, n, n, 1.0, state.lsamodel.tmprhs, 0, 0, 1, state.lsamodel.invw, 0, 0, 1, 0.0, state.lsamodel.jac, 0, 0, _params);
                ablasf.rsetallocv(n, 0.0, ref state.lsamodel.g, _params);
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=m-1; j++)
                    {
                        state.lsamodel.g[i] = state.lsamodel.g[i]+state.wrkset[n,n+j]*state.lsamodel.jac[j,i];
                    }
                }
                ablasf.rallocm(n, n, ref state.lsamodel.q, _params);
                ablas.rmatrixgemm(n, n, m, 1.0, state.lsamodel.jac, 0, 0, 1, state.lsamodel.jac, 0, 0, 0, 0.0, state.lsamodel.q, 0, 0, _params);
                
                //
                // Done
                //
                result = false;
                return result;
            }
            
            //
            // ORBIT
            //
            if( state.modeltype!=2 )
            {
                goto lbl_6;
            }
            state.rstateimprove.ia = new int[13+1];
            state.rstateimprove.ba = new bool[0+1];
            state.rstateimprove.ra = new double[12+1];
            state.rstateimprove.stage = -1;
            state.rstateimprove.clear_handler();
        lbl_8:
            if( !improveworkingsetgeometry(state, _params) )
            {
                goto lbl_9;
            }
            state.rstateupdate.stage = 1;
            if( state.rstateupdate.rcomm2_handler!=null && state.rstateupdate.requesttype!=0 && state.rstateupdate.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstateupdate.rcomm2_handler(state.rstateupdate, state.rstateupdate.handler_p0, state.rstateupdate.handler_p1, state.rstateupdate.handler_p2, state.rstateupdate.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            goto lbl_8;
        lbl_9:
            result = false;
            return result;
        lbl_6:
            alglib.ap.assert(false, "DFGM: UpdateWorkingSetAndModel() is unable to handle unexpected algorithm");
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rstateupdate.ia[0] = n;
            state.rstateupdate.ia[1] = m;
            state.rstateupdate.ia[2] = cntlc;
            state.rstateupdate.ia[3] = cntnlc;
            state.rstateupdate.ia[4] = i;
            state.rstateupdate.ia[5] = j;
            state.rstateupdate.ia[6] = k;
            state.rstateupdate.ia[7] = replaceidx;
            state.rstateupdate.ra[0] = rating;
            state.rstateupdate.ra[1] = bestrating;
            state.rstateupdate.ra[2] = v;
            state.rstateupdate.ra[3] = vv;
            state.rstateupdate.ra[4] = mx;
            return result;
        }


        /*************************************************************************
        For State.WrkSetSize=0 this function assumes that we actually  perform  an
        initial model construction.  In  the  latter case we assume that the first
        element of the working set contains some  meaningful value,  in the latter
        case   the  working  set  is  built  completely  from scratch.

        For State.WrkSetSize>0 this function assumes that the working set was
        already initialized and we perform an update: modify working set and
        (for some solvers) issues additional RComm V2 requests if working set needs
        immediate revaluation.

        It also updates the model:
        * recomputes State.Fk and State.Hk
        * updates current model by (possibly) incorporating State.Xk and (possibly)
          removing some of the previously included points.

        On exit it may set State.RepTerminationType to a negative  code  (failure)
        if it encountered infinities in the target/constraints during  update  and
        failed to recover from the problem.

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static bool improveworkingsetgeometry(dfgmstate state,
            alglib.xparams _params)
        {
            bool result = new bool();
            int n = 0;
            int m = 0;
            int cntlc = 0;
            int cntnlc = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            double vlft = 0;
            double vrgt = 0;
            double v = 0;
            double vmin = 0;
            double vmax = 0;
            double x0i = 0;
            int improveidx = 0;
            int improvedfar = 0;
            bool workingsetchanged = new bool();
            int leastdistantidx = 0;
            int mostdistantidx = 0;
            double leastdistant = 0;
            double mostdistant = 0;
            double mx = 0;
            int replaceidx = 0;
            double rating = 0;
            double bestrating = 0;
            double vv = 0;
            double roundradius = 0;
            int roundidx = 0;
            int chosenduringround = 0;

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rstateimprove.stage>=0 )
            {
                n = state.rstateimprove.ia[0];
                m = state.rstateimprove.ia[1];
                cntlc = state.rstateimprove.ia[2];
                cntnlc = state.rstateimprove.ia[3];
                i = state.rstateimprove.ia[4];
                j = state.rstateimprove.ia[5];
                k = state.rstateimprove.ia[6];
                improveidx = state.rstateimprove.ia[7];
                improvedfar = state.rstateimprove.ia[8];
                leastdistantidx = state.rstateimprove.ia[9];
                mostdistantidx = state.rstateimprove.ia[10];
                replaceidx = state.rstateimprove.ia[11];
                roundidx = state.rstateimprove.ia[12];
                chosenduringround = state.rstateimprove.ia[13];
                workingsetchanged = state.rstateimprove.ba[0];
                vlft = state.rstateimprove.ra[0];
                vrgt = state.rstateimprove.ra[1];
                v = state.rstateimprove.ra[2];
                vmin = state.rstateimprove.ra[3];
                vmax = state.rstateimprove.ra[4];
                x0i = state.rstateimprove.ra[5];
                leastdistant = state.rstateimprove.ra[6];
                mostdistant = state.rstateimprove.ra[7];
                mx = state.rstateimprove.ra[8];
                rating = state.rstateimprove.ra[9];
                bestrating = state.rstateimprove.ra[10];
                vv = state.rstateimprove.ra[11];
                roundradius = state.rstateimprove.ra[12];
            }
            else
            {
                n = -413;
                m = -461;
                cntlc = 927;
                cntnlc = 201;
                i = 922;
                j = -154;
                k = 306;
                improveidx = -1011;
                improvedfar = 951;
                leastdistantidx = -463;
                mostdistantidx = 88;
                replaceidx = -861;
                roundidx = -678;
                chosenduringround = -731;
                workingsetchanged = true;
                vlft = -763.0;
                vrgt = -233.0;
                v = -936.0;
                vmin = -279.0;
                vmax = 94.0;
                x0i = -812.0;
                leastdistant = 427.0;
                mostdistant = 178.0;
                mx = -819.0;
                rating = -826.0;
                bestrating = 667.0;
                vv = 692.0;
                roundradius = 84.0;
            }
            if( state.rstateimprove.stage==0 )
            {
                goto lbl_0;
            }
            if( state.rstateimprove.stage==1 )
            {
                goto lbl_1;
            }
            if( state.rstateimprove.stage==2 )
            {
                goto lbl_2;
            }
            
            //
            // Routine body
            //
            n = state.n;
            m = state.m;
            cntlc = state.cntlc;
            cntnlc = state.cntnlc;
            
            //
            // If working set is empty (initialization) or algorithm rebuilds
            // working set from scratch every time (like 2PS), initialize
            // working set using the best geometry possible (orthogonal distribution).
            //
            // After the working set was generated, the model is data structures
            // are initialized.
            //
            // NOTE: this section gets the fresh data from the user even when the algorithm
            //       relies on a previously stored cloud.
            //
            workingsetchanged = false;
            if( !(state.wrksetsize==0 || state.modeltype==0) )
            {
                goto lbl_3;
            }
            
            //
            // Generate working set which satisfies box constraints
            //
            ablasf.rallocv(n, ref state.tmpdeltas, _params);
        lbl_5:
            if( false )
            {
                goto lbl_6;
            }
            
            //
            // Initialize working set
            //
            ablasf.rallocm(n+1, n+m+cntnlc, ref state.wrkset, _params);
            state.wrksetsize = 0;
            for(i=0; i<=n-1; i++)
            {
                if( state.hasbndl[i] && state.hasbndu[i] )
                {
                    alglib.ap.assert((double)(state.scaledbndu[i])>(double)(state.scaledbndl[i]), "DFGM: integrity check 7909 failed");
                }
                ablasf.rcopyvr(n, state.xk, state.wrkset, state.wrksetsize, _params);
                
                //
                // Evaluate two candidate points: one obtained by making a step to the left, and one obtained by making a step to the right
                //
                x0i = state.xk[i];
                vlft = apserv.boundval(x0i-twopsstep*state.trustregion[i], state.finitebndl[i], state.finitebndu[i], _params);
                vrgt = apserv.boundval(x0i+twopsstep*state.trustregion[i], state.finitebndl[i], state.finitebndu[i], _params);
                if( (double)(x0i-vlft)<=(double)(0.9*(vrgt-x0i)) )
                {
                    
                    //
                    // The left step is shorter than the right one due to box constraints, choose the right step
                    //
                    state.wrkset[state.wrksetsize,i] = vrgt;
                    state.tmpdeltas[i] = vrgt-x0i;
                    state.wrksetsize = state.wrksetsize+1;
                    continue;
                }
                if( (double)(vrgt-x0i)<=(double)(0.9*(x0i-vlft)) )
                {
                    
                    //
                    // The right step is shorter than the left one due to box constraints, choose the left step
                    //
                    state.wrkset[state.wrksetsize,i] = vlft;
                    state.tmpdeltas[i] = vlft-x0i;
                    state.wrksetsize = state.wrksetsize+1;
                    continue;
                }
                
                //
                // Both steps are equally good, choose the random one
                //
                state.wrkset[state.wrksetsize,i] = apserv.rcase2(hqrnd.hqrnduniformi(state.rs, 2, _params)==0, vlft, vrgt, _params);
                state.tmpdeltas[i] = state.wrkset[state.wrksetsize,i]-x0i;
                state.wrksetsize = state.wrksetsize+1;
            }
            ablasf.rcopyvr(n, state.xk, state.wrkset, state.wrksetsize, _params);
            state.wrksetsize = state.wrksetsize+1;
            alglib.ap.assert(state.wrksetsize==n+1, "DFGM: integrity check 1309 failed");
            for(i=0; i<=n-1; i++)
            {
                state.tmpdeltas[i] = apserv.coalesce(state.tmpdeltas[i], 1.0, _params);
            }
            
            //
            // Issue RComm V2 request, check that the reply does not contain infinities
            //
            state.requesttype = 4;
            state.querysize = state.wrksetsize;
            ablasf.rallocv(n*state.querysize, ref state.querydata, _params);
            ablasf.rallocv((m+cntnlc)*state.querysize, ref state.replyfi, _params);
            for(i=0; i<=state.wrksetsize-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    state.querydata[i*n+j] = state.wrkset[i,j];
                }
            }
            sendrequesttocloud(state, state.querydata, state.querysize, _params);
            state.rstateimprove.stage = 0;
            if( state.rstateimprove.rcomm2_handler!=null && state.rstateimprove.requesttype!=0 && state.rstateimprove.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstateimprove.rcomm2_handler(state.rstateimprove, state.rstateimprove.handler_p0, state.rstateimprove.handler_p1, state.rstateimprove.handler_p2, state.rstateimprove.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
            if( !apserv.isfinitevector(state.replyfi, (m+cntnlc)*state.querysize, _params) )
            {
                
                //
                // Decrease trust radius and retry
                //
                if( state.dotrace )
                {
                    alglib.ap.trace("[WARNING] target at the geometry-improving point is infinite, decreasing trust radius and restarting iteration\n");
                }
                state.infinitiesencountered = true;
                state.recoveredfrominfinities = false;
                updatetrustregion(state, gammabad*state.trustradfactor, _params);
                state.trustradbnd = Math.Min(state.trustradfactor, state.trustradbnd);
                if( (double)(state.trustradfactor)<(double)(apserv.coalesce(state.epsx, state.toosmalltrustrad, _params)) )
                {
                    state.repterminationtype = -8;
                    result = false;
                    return result;
                }
                goto lbl_5;
            }
            
            //
            // Accept the reply.
            // Save to the cloud, if requested by the algorith,
            //
            for(i=0; i<=state.wrksetsize-1; i++)
            {
                for(j=0; j<=m+cntnlc-1; j++)
                {
                    state.wrkset[i,n+j] = state.replyfi[i*(m+cntnlc)+j];
                }
            }
            sendreplytocloud(state, state.replyfi, _params);
            goto lbl_6;
            goto lbl_5;
        lbl_6:
            
            //
            // Initialize model data structures
            //
            alglib.ap.assert((state.modeltype==0 || state.modeltype==1) || state.modeltype==2, "DFGM: integrity check 0337 failed");
            if( state.modeltype==0 )
            {
                ablasf.rcopyallocv(n, state.tmpdeltas, ref state.tpsmodel.deltas, _params);
            }
            if( state.modeltype==1 )
            {
                ablasf.rsetallocm(n, n, 0.0, ref state.lsamodel.w, _params);
                ablasf.rsetallocm(n, n, 0.0, ref state.lsamodel.invw, _params);
                for(i=0; i<=n-1; i++)
                {
                    state.lsamodel.w[i,i] = state.tmpdeltas[i];
                    state.lsamodel.invw[i,i] = 1/state.tmpdeltas[i];
                }
            }
            workingsetchanged = true;
        lbl_3:
            
            //
            // 2PS.
            //
            if( state.modeltype==0 )
            {
                
                //
                // The working set was already computed, rebuild a quadratic model of the target.
                //
                // Below we rely on the specific ordering of the working set
                // (the central point comes last, N additional ones come first).
                //
                alglib.ap.assert(state.cntnlc==0, "DFGM: integrity check 7614 failed");
                alglib.ap.assert(state.wrksetsize==n+1, "DFGM: integrity check 0425 failed");
                ablasf.rsetallocv(n, 0.0, ref state.tpsmodel.g, _params);
                ablasf.rallocm(n, n, ref state.tpsmodel.q, _params);
                ablasf.rallocm(m, n, ref state.tpsmodel.jac, _params);
                for(i=0; i<=n-1; i++)
                {
                    for(j=0; j<=m-1; j++)
                    {
                        state.tpsmodel.jac[j,i] = (state.wrkset[i,n+j]-state.wrkset[n,n+j])/state.tpsmodel.deltas[i];
                        state.tpsmodel.g[i] = state.tpsmodel.g[i]+state.wrkset[n,n+j]*state.tpsmodel.jac[j,i];
                    }
                }
                ablas.rmatrixgemm(n, n, m, 1.0, state.tpsmodel.jac, 0, 0, 1, state.tpsmodel.jac, 0, 0, 0, 0.0, state.tpsmodel.q, 0, 0, _params);
                
                //
                // Done
                //
                result = false;
                return result;
            }
            
            //
            // DFO-LSA.
            //
            if( state.modeltype!=1 )
            {
                goto lbl_7;
            }
            
            //
            // Improve geometry of the dataset, if needed
            //
            alglib.ap.assert(state.wrksetsize==n+1, "DFGM: integrity check 9726 failed");
            improvedfar = 0;
            
            //
            // Repeat improvement rounds until there is no point selected for improvement.
            //
        lbl_9:
            
            //
            // Select a point to improve:
            // * improve location of all points that are too close
            // * improve location of a limited number of points that are too far
            //
            mostandleastdistant(state.invtrustregion, n, state.wrkset, state.wrksetsize, ref mostdistant, ref mostdistantidx, ref leastdistant, ref leastdistantidx, _params);
            improveidx = -1;
            if( leastdistantidx>=0 && (double)(leastdistant)<=(double)(pointtooclose*Math.Min(mostdistant, 1.0)) )
            {
                improveidx = leastdistantidx;
            }
            if( improveidx<0 && (double)(mostdistant)>=(double)(pointunacceptablyfar) )
            {
                improveidx = mostdistantidx;
            }
            if( (improveidx<0 && (double)(improvedfar)<(double)(lsaimprovementlimit)) && (double)(mostdistant)>=(double)(pointtoofar) )
            {
                improvedfar = improvedfar+1;
                improveidx = mostdistantidx;
            }
            
            //
            // Try to find a location for an improved point, handle possible infinities in the target
            // by decreasing the trust radius and recomputing the proposal.
            //
            // The loop below has the loop condition "ImproveIdx>=0", the intention is to execute
            // it continually (until we settle on an infinity-free trust region) when there is a
            // point to improve, but to skip it if there is no points to be improved
            //
            ablasf.rallocv(n, ref state.tmp0, _params);
            ablasf.rallocv(n, ref state.tmp1, _params);
            ablasf.rallocv(n, ref state.tmp2, _params);
        lbl_12:
            if( improveidx<0 )
            {
                goto lbl_13;
            }
            
            //
            // Insert new point to the location where Lagrange polynomial for ImproveIdx-th point
            // reaches its maximum absolute value.
            //
            // Lagrange polynomial for this problem is a linear function with coefficients stored
            // in the ImproveIdx-th column of State.lsaModel.InvW (the constant term is zero). We
            // solve the problem by finding min L(x) and max L(x) subject to trust radius constraints,
            // and then selecting a solution with maximum absolute value.
            //
            // NOTE: C0 parameter of MaxAbsLag() is zero because we always have ImproveIdx<N, which
            //       corresponds to a Lagrange function which is zero at the origin
            //
            alglib.ap.assert(improveidx<n, "DFGM: integrity check 9820 failed");
            ablasf.rcopycv(n, state.lsamodel.invw, improveidx, state.tmp2, _params);
            maxabslag(state.xk, n, state.trustregion, state.finitebndl, state.finitebndu, state.tmp2, 0.0, state.tmp0, state.tmp1, true, _params);
            ablasf.rcopyvr(n, state.tmp0, state.wrkset, improveidx, _params);
            
            //
            // Issue RComm V2 request, check that the reply does not contain infinities
            //
            state.requesttype = 4;
            state.querysize = 1;
            ablasf.rallocv(n*state.querysize, ref state.querydata, _params);
            ablasf.rallocv((m+cntnlc)*state.querysize, ref state.replyfi, _params);
            for(j=0; j<=n-1; j++)
            {
                state.querydata[j] = state.wrkset[improveidx,j];
            }
            sendrequesttocloud(state, state.querydata, state.querysize, _params);
            state.rstateimprove.stage = 1;
            if( state.rstateimprove.rcomm2_handler!=null && state.rstateimprove.requesttype!=0 && state.rstateimprove.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstateimprove.rcomm2_handler(state.rstateimprove, state.rstateimprove.handler_p0, state.rstateimprove.handler_p1, state.rstateimprove.handler_p2, state.rstateimprove.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            if( !apserv.isfinitevector(state.replyfi, (m+cntnlc)*state.querysize, _params) )
            {
                
                //
                // Decrease trust radius and retry
                //
                if( state.dotrace )
                {
                    alglib.ap.trace("[WARNING] target at the geometry-improving point is infinite, decreasing trust radius and restarting iteration\n");
                }
                state.infinitiesencountered = true;
                state.recoveredfrominfinities = false;
                updatetrustregion(state, gammabad*state.trustradfactor, _params);
                state.trustradbnd = Math.Min(state.trustradfactor, state.trustradbnd);
                if( (double)(state.trustradfactor)<(double)(apserv.coalesce(state.epsx, state.toosmalltrustrad, _params)) )
                {
                    state.repterminationtype = -8;
                    result = false;
                    return result;
                }
                goto lbl_12;
            }
            
            //
            // Accept the reply
            //
            sendreplytocloud(state, state.replyfi, _params);
            for(j=0; j<=m+cntnlc-1; j++)
            {
                state.wrkset[improveidx,n+j] = state.replyfi[j];
            }
            workingsetchanged = true;
            goto lbl_13;
            goto lbl_12;
        lbl_13:
            
            //
            // Quick exit: no changes in the working set at this point means that
            //             the working set will never change. We can exit now.
            //
            if( !workingsetchanged )
            {
                result = false;
                return result;
            }
            
            //
            // Recompute matrices W and InvW, if there was an improvement in the
            // working set (this phase is ignored if WorkingSetChanged=True,
            // but ImproveIdx<0, which happens during the initialization)
            //
            if( improveidx>=0 )
            {
                ablasf.rcopyrr(n, state.wrkset, improveidx, state.lsamodel.w, improveidx, _params);
                ablasf.raddvr(n, -1.0, state.xk, state.lsamodel.w, improveidx, _params);
                ablasf.rcopym(n, n, state.lsamodel.w, state.lsamodel.invw, _params);
                matinv.rmatrixinverse(state.lsamodel.invw, n, state.invrep, _params);
                if( state.invrep.terminationtype<=0 )
                {
                    state.repterminationtype = 7;
                    result = false;
                    return result;
                }
            }
            if( improveidx>=0 )
            {
                goto lbl_9;
            }
            
            //
            // The working set is ready, rebuild a quadratic model of the target.
            //
            // Below we rely on the specific ordering of the working set
            // (the central point comes last, N additional ones come first).
            //
            alglib.ap.assert(state.wrksetsize==n+1, "DFGM: integrity check 0425 failed");
            ablasf.rallocm(n, m, ref state.lsamodel.tmprhs, _params);
            ablas.rmatrixcopy(n, m, state.wrkset, 0, n, state.lsamodel.tmprhs, 0, 0, _params);
            ablasf.rallocv(m, ref state.lsamodel.tmp0, _params);
            for(i=0; i<=m-1; i++)
            {
                state.lsamodel.tmp0[i] = state.wrkset[n,n+i];
            }
            for(i=0; i<=n-1; i++)
            {
                ablasf.raddvr(m, -1.0, state.lsamodel.tmp0, state.lsamodel.tmprhs, i, _params);
            }
            ablasf.rallocm(m, n, ref state.lsamodel.jac, _params);
            ablas.rmatrixgemm(m, n, n, 1.0, state.lsamodel.tmprhs, 0, 0, 1, state.lsamodel.invw, 0, 0, 1, 0.0, state.lsamodel.jac, 0, 0, _params);
            ablasf.rsetallocv(n, 0.0, ref state.lsamodel.g, _params);
            for(i=0; i<=n-1; i++)
            {
                for(j=0; j<=m-1; j++)
                {
                    state.lsamodel.g[i] = state.lsamodel.g[i]+state.wrkset[n,n+j]*state.lsamodel.jac[j,i];
                }
            }
            ablasf.rallocm(n, n, ref state.lsamodel.q, _params);
            ablas.rmatrixgemm(n, n, m, 1.0, state.lsamodel.jac, 0, 0, 1, state.lsamodel.jac, 0, 0, 0, 0.0, state.lsamodel.q, 0, 0, _params);
            
            //
            // Done
            //
            result = false;
            return result;
        lbl_7:
            
            //
            // ORBIT
            //
            if( state.modeltype!=2 )
            {
                goto lbl_14;
            }
            
            //
            // Select subset of points from the cloud to work with.
            //
            // Initialize DistFromCenter[] and DistFromChosen[] (the latter is a copy
            // of DistFromCenter[]). Set availability flags.
            //
            alglib.ap.assert(state.savepointstocloud, "DFGM: integrity check 701531 failed");
            state.rbfmodel.currentcloudsize = 0;
            for(i=0; i<=state.cloudsize-1; i++)
            {
                v = 0;
                for(j=0; j<=n-1; j++)
                {
                    v = Math.Max(v, Math.Abs(state.clouddata[i,j]-state.xk[j])*state.invtrustregion[j]);
                }
                if( (double)(v)<=(double)(rbfmindist) || (double)(v)>(double)(rbftheta0) )
                {
                    continue;
                }
                ablasf.rgrowrowsfixedcolsm(state.rbfmodel.currentcloudsize+1, n+m+cntnlc, ref state.rbfmodel.currentcloud, _params);
                ablasf.rcopyrr(n+m+cntnlc, state.clouddata, i, state.rbfmodel.currentcloud, state.rbfmodel.currentcloudsize, _params);
                ablasf.rgrowappendv(state.rbfmodel.currentcloudsize+1, ref state.rbfmodel.distfromcenter, v, _params);
                ablasf.rgrowappendv(state.rbfmodel.currentcloudsize+1, ref state.rbfmodel.distfromchosen, v, _params);
                ablasf.bgrowappendv(state.rbfmodel.currentcloudsize+1, ref state.rbfmodel.available, true, _params);
                state.rbfmodel.currentcloudsize = state.rbfmodel.currentcloudsize+1;
            }
            
            //
            // Try to select initial affine-independent working set of N points (plus one central)
            // from the cloud, without performing additional evaluations
            //
            alglib.ap.assert((double)(rbfmindist)>(double)(0), "DFGM: integrity check 734622 failed");
            ablasf.rallocm(state.rbfmodel.currentcloudsize, n, ref state.rbfmodel.residualdisplacements, _params);
            for(i=0; i<=state.rbfmodel.currentcloudsize-1; i++)
            {
                ablasf.rcopyrr(n, state.rbfmodel.currentcloud, i, state.rbfmodel.residualdisplacements, i, _params);
                ablasf.raddvr(n, -1.0, state.xk, state.rbfmodel.residualdisplacements, i, _params);
                ablasf.rmergemulvr(n, state.invtrustregion, state.rbfmodel.residualdisplacements, i, _params);
            }
            state.rbfmodel.curwrksetsize = 0;
            while( state.rbfmodel.curwrksetsize<n )
            {
                
                //
                // Select largest residual displacement.
                //
                k = -1;
                v = 0;
                mx = rbftheta0;
                for(i=0; i<=state.rbfmodel.currentcloudsize-1; i++)
                {
                    if( !state.rbfmodel.available[i] )
                    {
                        continue;
                    }
                    if( (double)(state.rbfmodel.distfromchosen[i])<=(double)(rbfmindist) )
                    {
                        continue;
                    }
                    if( (double)(state.rbfmodel.distfromcenter[i])>(double)(mx) )
                    {
                        continue;
                    }
                    vv = ablasf.rdotrr(n, state.rbfmodel.residualdisplacements, i, state.rbfmodel.residualdisplacements, i, _params);
                    if( (double)(vv)==(double)(0) || (double)(vv)<(double)(rbftheta1*rbftheta1) )
                    {
                        continue;
                    }
                    if( k<0 || (double)(vv)>(double)(v) )
                    {
                        k = i;
                        v = vv;
                    }
                }
                if( k<0 )
                {
                    break;
                }
                i = k;
                
                //
                // Orthogonalize residual displacements with respect to the currently chosen one
                //
                ablasf.rallocv(n, ref state.rbfmodel.tmpcand, _params);
                ablasf.rcopyrv(n, state.rbfmodel.residualdisplacements, i, state.rbfmodel.tmpcand, _params);
                v = ablasf.rdotv2(n, state.rbfmodel.tmpcand, _params);
                for(j=0; j<=state.rbfmodel.currentcloudsize-1; j++)
                {
                    ablasf.raddvr(n, -(ablasf.rdotvr(n, state.rbfmodel.tmpcand, state.rbfmodel.residualdisplacements, j, _params)/v), state.rbfmodel.tmpcand, state.rbfmodel.residualdisplacements, j, _params);
                }
                ablasf.rmulv(n, 1/Math.Sqrt(v), state.rbfmodel.tmpcand, _params);
                
                //
                // Add to the working set and Q, mark as unavailable and update DistFromChosen[]
                //
                ablasf.rgrowrowsfixedcolsm(state.rbfmodel.curwrksetsize+1, n+m+cntnlc, ref state.rbfmodel.curwrkset, _params);
                ablasf.rcopyrr(n+m+cntnlc, state.rbfmodel.currentcloud, i, state.rbfmodel.curwrkset, state.rbfmodel.curwrksetsize, _params);
                ablasf.rgrowrowsfixedcolsm(state.rbfmodel.curwrksetsize+1, n, ref state.rbfmodel.q, _params);
                ablasf.rcopyvr(n, state.rbfmodel.tmpcand, state.rbfmodel.q, state.rbfmodel.curwrksetsize, _params);
                state.rbfmodel.available[i] = false;
                state.rbfmodel.curwrksetsize = state.rbfmodel.curwrksetsize+1;
                for(j=0; j<=state.rbfmodel.currentcloudsize-1; j++)
                {
                    v = 0;
                    for(k=0; k<=n-1; k++)
                    {
                        v = Math.Max(v, Math.Abs(state.rbfmodel.currentcloud[i,k]-state.rbfmodel.currentcloud[j,k])*state.invtrustregion[k]);
                    }
                    state.rbfmodel.distfromchosen[j] = Math.Min(state.rbfmodel.distfromchosen[j], v);
                }
            }
            alglib.ap.assert(state.rbfmodel.curwrksetsize<=n, "DFGM: integrity check 779633 failed");
            
            //
            // Failed to sample N linearly independent directions from the cloud; perform additional
            // sampling by generating random points within trust region. Due to box constraints it
            // is not easy to generate a direction orthogonal to the current Q which does not violate
            // box constraints, so we generate a random feasible point and check its orthogonality
            // properties with respect to Q. Actually, we generate many such points and perform a
            // competition amongst them.
            //
        lbl_16:
            if( state.rbfmodel.curwrksetsize>=n )
            {
                goto lbl_17;
            }
            
            //
            // Run the competition
            //
            state.rbfmodel.winnerrating = 0;
            ablasf.rcopyallocv(n, state.xk, ref state.rbfmodel.tmpwinner, _params);
            ablasf.rallocv(n, ref state.rbfmodel.tmpcand, _params);
            k = 0;
            while( k<5 || (double)(state.rbfmodel.winnerrating)==(double)(0) )
            {
                
                //
                // Generate random point within a box
                //
                for(i=0; i<=n-1; i++)
                {
                    v = Math.Max(state.xk[i]-state.trustregion[i], state.finitebndl[i]);
                    vv = Math.Min(state.xk[i]+state.trustregion[i], state.finitebndu[i]);
                    state.rbfmodel.tmpcand[i] = apserv.boundval(v+(vv-v)*hqrnd.hqrnduniformr(state.rs, _params), state.finitebndl[i], state.finitebndu[i], _params);
                }
                
                //
                // Compute displacement and orthogonalize it wrt Q, compare residual with the largest one so far
                //
                ablasf.rcopyallocv(n, state.rbfmodel.tmpcand, ref state.rbfmodel.tmpdisp, _params);
                ablasf.raddv(n, -1.0, state.xk, state.rbfmodel.tmpdisp, _params);
                ablasf.rmergemulv(n, state.invtrustregion, state.rbfmodel.tmpdisp, _params);
                ablasf.rmulv(n, 1/Math.Sqrt(math.machineepsilon+ablasf.rdotv2(n, state.rbfmodel.tmpdisp, _params)), state.rbfmodel.tmpdisp, _params);
                ablas.rowwisegramschmidt(state.rbfmodel.q, state.rbfmodel.curwrksetsize, n, state.rbfmodel.tmpdisp, ref state.tmp0, false, _params);
                v = Math.Sqrt(ablasf.rdotv2(n, state.rbfmodel.tmpdisp, _params));
                if( (double)(v)>(double)(0) && (double)(v)>(double)(state.rbfmodel.winnerrating) )
                {
                    state.rbfmodel.winnerrating = v;
                    ablasf.rcopyv(n, state.rbfmodel.tmpcand, state.rbfmodel.tmpwinner, _params);
                }
                
                //
                // Next try, check for eternal loop
                //
                k = k+1;
                alglib.ap.assert(k<1000, "DFGM: integrity check 848747 failed (eternal loop in model-improving points generation)");
            }
            
            //
            // Issue RComm V2 request for the winner, check that the reply does not contain infinities
            //
            state.requesttype = 4;
            state.querysize = 1;
            ablasf.rcopyallocv(n, state.rbfmodel.tmpwinner, ref state.querydata, _params);
            ablasf.rallocv(m+cntnlc, ref state.replyfi, _params);
            sendrequesttocloud(state, state.querydata, state.querysize, _params);
            state.rstateimprove.stage = 2;
            if( state.rstateimprove.rcomm2_handler!=null && state.rstateimprove.requesttype!=0 && state.rstateimprove.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rstateimprove.rcomm2_handler(state.rstateimprove, state.rstateimprove.handler_p0, state.rstateimprove.handler_p1, state.rstateimprove.handler_p2, state.rstateimprove.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_2:
            if( !apserv.isfinitevector(state.replyfi, (m+cntnlc)*state.querysize, _params) )
            {
                
                //
                // Decrease trust radius and retry
                //
                if( state.dotrace )
                {
                    alglib.ap.trace("[WARNING] target at the geometry-improving point is infinite, decreasing trust radius and restarting iteration\n");
                }
                state.infinitiesencountered = true;
                state.recoveredfrominfinities = false;
                updatetrustregion(state, gammabad*state.trustradfactor, _params);
                state.trustradbnd = Math.Min(state.trustradfactor, state.trustradbnd);
                if( (double)(state.trustradfactor)<(double)(apserv.coalesce(state.epsx, state.toosmalltrustrad, _params)) )
                {
                    state.repterminationtype = -8;
                    result = false;
                    return result;
                }
                goto lbl_16;
            }
            sendreplytocloud(state, state.replyfi, _params);
            ablasf.rgrowrowsfixedcolsm(state.rbfmodel.curwrksetsize+1, n+m+cntnlc, ref state.rbfmodel.curwrkset, _params);
            for(j=0; j<=n-1; j++)
            {
                state.rbfmodel.curwrkset[state.rbfmodel.curwrksetsize,j] = state.rbfmodel.tmpwinner[j];
            }
            for(j=0; j<=m+cntnlc-1; j++)
            {
                state.rbfmodel.curwrkset[state.rbfmodel.curwrksetsize,n+j] = state.replyfi[j];
            }
            ablasf.rcopyallocv(n, state.rbfmodel.tmpwinner, ref state.rbfmodel.tmpdisp, _params);
            ablasf.raddv(n, -1.0, state.xk, state.rbfmodel.tmpdisp, _params);
            ablasf.rmergemulv(n, state.invtrustregion, state.rbfmodel.tmpdisp, _params);
            ablas.rowwisegramschmidt(state.rbfmodel.q, state.rbfmodel.curwrksetsize, n, state.rbfmodel.tmpdisp, ref state.tmp0, false, _params);
            ablasf.rmulv(n, 1/Math.Sqrt(ablasf.rdotv2(n, state.rbfmodel.tmpdisp, _params)), state.rbfmodel.tmpdisp, _params);
            ablasf.rcopyvr(n, state.rbfmodel.tmpdisp, state.rbfmodel.q, state.rbfmodel.curwrksetsize, _params);
            state.rbfmodel.curwrksetsize = state.rbfmodel.curwrksetsize+1;
            goto lbl_16;
        lbl_17:
            alglib.ap.assert(state.rbfmodel.curwrksetsize==n, "DFGM: integrity check 902742 failed");
            
            //
            // Select additional points for RBF model, apply several rounds with search radius decreasing
            // by 2x each iteration. Such multilayered approach allows us to capture reuse and capture info
            // about both far away and close points.
            //
            roundradius = rbftheta0;
            for(roundidx=0; roundidx<=3; roundidx++)
            {
                chosenduringround = 0;
                while( chosenduringround<n+1 )
                {
                    
                    //
                    // Select largest distance from already selected points within distance
                    // specified by rbfTheta0
                    //
                    k = -1;
                    v = 0;
                    for(i=0; i<=state.rbfmodel.currentcloudsize-1; i++)
                    {
                        if( !state.rbfmodel.available[i] )
                        {
                            continue;
                        }
                        if( (double)(state.rbfmodel.distfromchosen[i])<=(double)(rbfmindist) )
                        {
                            continue;
                        }
                        if( (double)(state.rbfmodel.distfromcenter[i])>(double)(roundradius) )
                        {
                            continue;
                        }
                        vv = state.rbfmodel.distfromchosen[i];
                        if( k<0 || (double)(vv)>(double)(v) )
                        {
                            k = i;
                            v = vv;
                        }
                    }
                    if( k<0 )
                    {
                        break;
                    }
                    i = k;
                    
                    //
                    // Add to the working set and Q, mark as unavailable and update DistFromChosen[]
                    //
                    ablasf.rgrowrowsfixedcolsm(state.rbfmodel.curwrksetsize+1, n+m+cntnlc, ref state.rbfmodel.curwrkset, _params);
                    ablasf.rcopyrr(n+m+cntnlc, state.rbfmodel.currentcloud, i, state.rbfmodel.curwrkset, state.rbfmodel.curwrksetsize, _params);
                    state.rbfmodel.available[i] = false;
                    state.rbfmodel.curwrksetsize = state.rbfmodel.curwrksetsize+1;
                    for(j=0; j<=state.rbfmodel.currentcloudsize-1; j++)
                    {
                        v = 0;
                        for(k=0; k<=n-1; k++)
                        {
                            v = Math.Max(v, Math.Abs(state.rbfmodel.currentcloud[i,k]-state.rbfmodel.currentcloud[j,k])*state.invtrustregion[k]);
                        }
                        state.rbfmodel.distfromchosen[j] = Math.Min(state.rbfmodel.distfromchosen[j], v);
                    }
                    chosenduringround = chosenduringround+1;
                }
                roundradius = 0.5*roundradius;
            }
            
            //
            // Append the central point to the working set
            //
            ablasf.rgrowrowsfixedcolsm(state.rbfmodel.curwrksetsize+1, n+m+cntnlc, ref state.rbfmodel.curwrkset, _params);
            for(i=0; i<=n-1; i++)
            {
                state.rbfmodel.curwrkset[state.rbfmodel.curwrksetsize,i] = state.xk[i];
            }
            for(i=0; i<=m+cntnlc-1; i++)
            {
                state.rbfmodel.curwrkset[state.rbfmodel.curwrksetsize,n+i] = state.fkvec[i];
            }
            state.rbfmodel.curwrksetsize = state.rbfmodel.curwrksetsize+1;
            
            //
            // Replace working set with the newly constructed one
            //
            state.wrksetsize = state.rbfmodel.curwrksetsize;
            ablasf.rgrowrowsfixedcolsm(state.wrksetsize, n+m+cntnlc, ref state.wrkset, _params);
            ablasf.rcopym(state.wrksetsize, n+m+cntnlc, state.rbfmodel.curwrkset, state.wrkset, _params);
            
            //
            // Done
            //
            result = false;
            return result;
        lbl_14:
            alglib.ap.assert(false, "DFGM: ImproveWorkingSetGeometry() is unable to handle unexpected algorithm");
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rstateimprove.ia[0] = n;
            state.rstateimprove.ia[1] = m;
            state.rstateimprove.ia[2] = cntlc;
            state.rstateimprove.ia[3] = cntnlc;
            state.rstateimprove.ia[4] = i;
            state.rstateimprove.ia[5] = j;
            state.rstateimprove.ia[6] = k;
            state.rstateimprove.ia[7] = improveidx;
            state.rstateimprove.ia[8] = improvedfar;
            state.rstateimprove.ia[9] = leastdistantidx;
            state.rstateimprove.ia[10] = mostdistantidx;
            state.rstateimprove.ia[11] = replaceidx;
            state.rstateimprove.ia[12] = roundidx;
            state.rstateimprove.ia[13] = chosenduringround;
            state.rstateimprove.ba[0] = workingsetchanged;
            state.rstateimprove.ra[0] = vlft;
            state.rstateimprove.ra[1] = vrgt;
            state.rstateimprove.ra[2] = v;
            state.rstateimprove.ra[3] = vmin;
            state.rstateimprove.ra[4] = vmax;
            state.rstateimprove.ra[5] = x0i;
            state.rstateimprove.ra[6] = leastdistant;
            state.rstateimprove.ra[7] = mostdistant;
            state.rstateimprove.ra[8] = mx;
            state.rstateimprove.ra[9] = rating;
            state.rstateimprove.ra[10] = bestrating;
            state.rstateimprove.ra[11] = vv;
            state.rstateimprove.ra[12] = roundradius;
            return result;
        }


        /*************************************************************************
        Compute maximum absolute value of  a  Lagrange  polynomial  given  by  its
        coefficients vector C[] and value at the trust region center C0 over trust
        region.

        Returns maximum absolute value and, optionally, point  where  the  maximum
        is obtained.

        if NeedX is True, then X must be preallocated array[N], and tmpX must also
        be preallocated array[N]. If NeedX is False, X and tmpX are not referenced.

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static double maxabslag(double[] xk,
            int n,
            double[] trustregion,
            double[] finitebndl,
            double[] finitebndu,
            double[] c,
            double c0,
            double[] x,
            double[] tmpx,
            bool needx,
            alglib.xparams _params)
        {
            double result = 0;
            double vmin = 0;
            double vmax = 0;
            double vlft = 0;
            double vrgt = 0;
            double xmin = 0;
            double xmax = 0;
            double xki = 0;
            double ci = 0;
            int i = 0;

            alglib.ap.assert(!needx || alglib.ap.len(x)>=n, "DFGM: integrity check 5616 failed");
            alglib.ap.assert(!needx || alglib.ap.len(tmpx)>=n, "DFGM: integrity check 5716 failed");
            vmin = c0;
            vmax = c0;
            for(i=0; i<=n-1; i++)
            {
                xki = xk[i];
                ci = c[i];
                vlft = Math.Max(xki-trustregion[i], finitebndl[i]);
                vrgt = Math.Min(xki+trustregion[i], finitebndu[i]);
                xmin = apserv.rcase2((double)(ci)>=(double)(0), vlft, vrgt, _params);
                xmax = apserv.rcase2((double)(ci)<=(double)(0), vlft, vrgt, _params);
                vmin = vmin+(xmin-xki)*ci;
                vmax = vmax+(xmax-xki)*ci;
                if( needx )
                {
                    x[i] = xmin;
                    tmpx[i] = xmax;
                }
            }
            result = Math.Max(Math.Abs(vmin), Math.Abs(vmax));
            if( needx && (double)(Math.Abs(vmin))<(double)(Math.Abs(vmax)) )
            {
                ablasf.rcopyv(n, tmpx, x, _params);
            }
            return result;
        }


        /*************************************************************************
        Compute distance to the most distant and the least distant neighbors in the
        working set. The distance is computed using L-inf metric, per-variable
        distances are divided by min(DeltaK,BndU[I]-BndL[I]).

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        private static void mostandleastdistant(double[] invtrustregion,
            int n,
            double[,] wrkset,
            int wrksetsize,
            ref double mostdistant,
            ref int mostdistantidx,
            ref double leastdistant,
            ref int leastdistantidx,
            alglib.xparams _params)
        {
            double mx = 0;
            int i = 0;
            int j = 0;
            int centralidx = 0;

            mostdistant = 0;
            mostdistantidx = 0;
            leastdistant = 0;
            leastdistantidx = 0;

            
            //
            // Find most distant and least distant neighbors, 
            //
            mostdistant = 0.0;
            mostdistantidx = -1;
            leastdistant = 1.0E50;
            leastdistantidx = -1;
            centralidx = wrksetsize-1;
            for(i=0; i<=wrksetsize-2; i++)
            {
                mx = 0;
                for(j=0; j<=n-1; j++)
                {
                    mx = Math.Max(mx, Math.Abs(wrkset[i,j]-wrkset[centralidx,j])*invtrustregion[j]);
                }
                if( mostdistantidx<0 || (double)(mx)>(double)(mostdistant) )
                {
                    mostdistant = mx;
                    mostdistantidx = i;
                }
                if( leastdistantidx<0 || (double)(mx)<(double)(leastdistant) )
                {
                    leastdistant = mx;
                    leastdistantidx = i;
                }
            }
        }


        /*************************************************************************
        This function initializes state of the points cloud: whether all evaluated
        target values are saved to cloud or not.

          -- ALGLIB --
             Copyright 15.10.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void initcloud(dfgmstate state,
            bool savetocloud,
            alglib.xparams _params)
        {
            state.savepointstocloud = savetocloud;
            state.cloudsize = 0;
            state.cloudpendingcnt = 0;
        }


        /*************************************************************************
        This function saves request information to the cloud; points locations are
        saved in the special 'pending' queue, waiting to be augmented with request
        reply (target values).

        If the cloud is not used, it does nothing.

          -- ALGLIB --
             Copyright 15.10.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void sendrequesttocloud(dfgmstate state,
            double[] querydata,
            int requestsize,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;

            if( !state.savepointstocloud )
            {
                return;
            }
            ablasf.rgrowrowsfixedcolsm(requestsize, state.n, ref state.cloudpending, _params);
            for(i=0; i<=requestsize-1; i++)
            {
                for(j=0; j<=state.n-1; j++)
                {
                    state.cloudpending[i,j] = querydata[i*state.n+j];
                }
            }
            state.cloudpendingcnt = requestsize;
        }


        /*************************************************************************
        This function sends to the cloud target values at the pending points (ones
        previously posted with sendrequesttocloud). The amount of values sent now
        must exactly match amount of previously posted values.

        If cloud is not used, it does nothing.

          -- ALGLIB --
             Copyright 15.10.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void sendreplytocloud(dfgmstate state,
            double[] replyfi,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int replyentrysize = 0;

            if( !state.savepointstocloud )
            {
                return;
            }
            ablasf.rgrowrowsfixedcolsm(state.cloudsize+state.cloudpendingcnt, state.n+state.m+state.cntnlc, ref state.clouddata, _params);
            replyentrysize = state.m+state.cntnlc;
            for(i=0; i<=state.cloudpendingcnt-1; i++)
            {
                for(j=0; j<=state.n-1; j++)
                {
                    state.clouddata[state.cloudsize+i,j] = state.cloudpending[i,j];
                }
                for(j=0; j<=replyentrysize-1; j++)
                {
                    state.clouddata[state.cloudsize+i,state.n+j] = replyfi[i*replyentrysize+j];
                }
            }
            state.cloudsize = state.cloudsize+state.cloudpendingcnt;
            state.cloudpendingcnt = 0;
        }


        /*************************************************************************
        This function clears the points cloud.

          -- ALGLIB --
             Copyright 15.10.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void clearcloud(dfgmstate state,
            alglib.xparams _params)
        {
            state.cloudsize = 0;
            state.cloudpendingcnt = 0;
        }


        /*************************************************************************
        This function performs initial construction of an RBF model. It must be
        called once at the initial working set generation.

          -- ALGLIB --
             Copyright 15.10.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void rbfinitializemodelfromworkingset(dfgmstate state,
            alglib.xparams _params)
        {
            int n = 0;
            int ws = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            int fidx = 0;
            double v = 0;
            double[,] rbfsys = new double[0,0];
            double[] sol = new double[0];
            double[] rhs = new double[0];
            double[] sol2 = new double[0];
            double[,] rrhs = new double[0,0];
            double[,] ssol = new double[0,0];

            n = state.n;
            ws = state.wrksetsize;
            alglib.ap.assert(state.modeltype==2, "DFGM: integrity check 211136 failed");
            alglib.ap.assert(ws>=n+1, "DFGM: integrity check 211137 failed");
            alglib.ap.assert(state.m==1, "DFGM: integrity check 211138 failed");
            ablasf.rsetallocm(ws+n+1, ws+n+1, 0.0, ref rbfsys, _params);
            for(i=0; i<=ws-1; i++)
            {
                for(j=0; j<=i; j++)
                {
                    v = 0;
                    for(k=0; k<=n-1; k++)
                    {
                        v = v+math.sqr((state.wrkset[i,k]-state.wrkset[j,k])*state.invtrustregion[k]);
                    }
                    v = v*Math.Sqrt(v);
                    rbfsys[i,j] = v;
                    rbfsys[j,i] = v;
                }
            }
            for(i=0; i<=n-1; i++)
            {
                for(j=0; j<=ws-1; j++)
                {
                    rbfsys[ws+i,j] = (state.wrkset[j,i]-state.wrkset[ws-1,i])*state.invtrustregion[i];
                    rbfsys[j,ws+i] = rbfsys[ws+i,j];
                }
            }
            for(j=0; j<=ws-1; j++)
            {
                rbfsys[ws+n,j] = 1.0;
                rbfsys[j,ws+n] = 1.0;
            }
            state.rbfmodel.modelbase = state.wrkset[ws-1,n];
            v = 0;
            for(i=0; i<=ws-1; i++)
            {
                v = v+math.sqr(state.wrkset[i,n]-state.rbfmodel.modelbase);
            }
            state.rbfmodel.modelscale = Math.Sqrt(apserv.coalesce(v, 1, _params)/ws);
            state.rbfmodel.ncenters = ws;
            ablasf.rgrowrowsfixedcolsm(ws, n, ref state.rbfmodel.centers, _params);
            ablasf.rcopym(ws, n, state.wrkset, state.rbfmodel.centers, _params);
            ablasf.rallocv(n, ref state.rbfmodel.x0, _params);
            ablasf.rcopyrv(n, state.wrkset, ws-1, state.rbfmodel.x0, _params);
            ablasf.rcopyallocv(n, state.invtrustregion, ref state.rbfmodel.multscale, _params);
            ablasf.rsetallocm(1+state.cntnlc, ws+n+1, 0.0, ref rrhs, _params);
            ablasf.rallocm(1+state.cntnlc, ws, ref state.rbfmodel.crbf, _params);
            ablasf.rallocm(1+state.cntnlc, n+1, ref state.rbfmodel.clinear, _params);
            for(fidx=0; fidx<=state.cntnlc; fidx++)
            {
                for(i=0; i<=ws-1; i++)
                {
                    rrhs[fidx,i] = (state.wrkset[i,n+fidx]-state.rbfmodel.modelbase)/state.rbfmodel.modelscale;
                }
            }
            rbfsolvecpdm(rbfsys, rrhs, ws, 1+state.cntnlc, n, 0.0, true, ref ssol, _params);
            ablasf.rcopym(1+state.cntnlc, ws, ssol, state.rbfmodel.crbf, _params);
            for(fidx=0; fidx<=state.cntnlc; fidx++)
            {
                for(i=0; i<=n; i++)
                {
                    state.rbfmodel.clinear[fidx,i] = ssol[fidx,ws+i];
                }
            }
        }


        /*************************************************************************
        This function computes RBF model at the required point. May return model
        value and its gradient.

          -- ALGLIB --
             Copyright 15.10.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void rbfcomputemodel(dfgmstate state,
            double[] x,
            double[] f,
            bool needf,
            double[] g,
            bool needg,
            alglib.xparams _params)
        {
            int cntnlc = 0;
            int n = 0;
            int j = 0;
            int k = 0;
            int fidx = 0;
            double v = 0;
            double r = 0;
            double vf = 0;

            n = state.n;
            cntnlc = state.cntnlc;
            alglib.ap.assert(!needf || alglib.ap.len(f)>=1+state.cntnlc, "DFGM: integrity check 419111 failed");
            alglib.ap.assert(!needg || alglib.ap.len(g)>=(1+state.cntnlc)*n, "DFGM: integrity check 419112 failed");
            if( needf )
            {
                ablasf.rsetv(1+cntnlc, 0.0, f, _params);
            }
            if( needg )
            {
                ablasf.rsetv((1+state.cntnlc)*n, 0.0, g, _params);
            }
            for(fidx=0; fidx<=cntnlc; fidx++)
            {
                vf = 0;
                for(j=0; j<=state.rbfmodel.ncenters-1; j++)
                {
                    r = 0;
                    for(k=0; k<=n-1; k++)
                    {
                        v = (x[k]-state.rbfmodel.centers[j,k])*state.rbfmodel.multscale[k];
                        r = r+v*v;
                    }
                    r = Math.Sqrt(r);
                    vf = vf+state.rbfmodel.crbf[fidx,j]*(r*r*r);
                    if( needg )
                    {
                        for(k=0; k<=n-1; k++)
                        {
                            g[fidx*n+k] = g[fidx*n+k]+state.rbfmodel.crbf[fidx,j]*3*r*(x[k]-state.rbfmodel.centers[j,k])*state.rbfmodel.multscale[k]*state.rbfmodel.multscale[k];
                        }
                    }
                }
                for(k=0; k<=n-1; k++)
                {
                    vf = vf+state.rbfmodel.clinear[fidx,k]*(x[k]-state.rbfmodel.x0[k])*state.rbfmodel.multscale[k];
                    if( needg )
                    {
                        g[fidx*n+k] = g[fidx*n+k]+state.rbfmodel.clinear[fidx,k]*state.rbfmodel.multscale[k];
                    }
                }
                vf = vf+state.rbfmodel.clinear[fidx,n];
                if( needf )
                {
                    f[fidx] = vf*state.rbfmodel.modelscale+state.rbfmodel.modelbase;
                }
                if( needg )
                {
                    ablasf.rmulvx(n, state.rbfmodel.modelscale, g, fidx*n, _params);
                }
            }
        }


        /*************************************************************************
        This function solves RBF  system using conditionally positive definiteness
        if possible.

        INPUT PARAMETERS:
            A           array[NCenters+NX,NCenters], basis function matrix and
                        linear polynomial values
            B           array[NCenters], target values    
            NCenters    centers count
            NX          space dimensionality
            LambdaV     smoothing parameter, LambdaV>=0
            isCPD       whether basis is conditionally positive definite or not


          -- ALGLIB --
             Copyright 15.10.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void rbfsolvecpdm(double[,] a,
            double[,] bb,
            int ncenters,
            int nrhs,
            int nx,
            double lambdav,
            bool iscpd,
            ref double[,] ssol,
            alglib.xparams _params)
        {
            int ncoeff = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            double v = 0;
            double vv = 0;
            double mx = 0;
            double reg = 0;
            int ortbasissize = 0;
            double[,] q = new double[0,0];
            double[,] q1 = new double[0,0];
            double[,] r = new double[0,0];
            double[] c = new double[0];
            double[] y = new double[0];
            double[] z = new double[0];
            int[] ortbasismap = new int[0];
            double[] choltmp = new double[0];

            alglib.ap.assert((double)(lambdav)>=(double)(0), "DFGM: integrity check 854519 failed");
            alglib.ap.assert(iscpd, "DFGM: integrity check 855520 failed");
            ncoeff = ncenters+nx+1;
            reg = Math.Sqrt(math.machineepsilon);
            
            //
            // First, compute orthogonal basis of space spanned by polynomials of degree 1
            //
            ablasf.rallocm(ncenters, ncenters, ref r, _params);
            ablasf.rallocm(nx+1, ncenters, ref q1, _params);
            ablasf.iallocv(nx+1, ref ortbasismap, _params);
            ablasf.rsetr(ncenters, 1/Math.Sqrt(ncenters), q1, 0, _params);
            r[0,0] = Math.Sqrt(ncenters);
            ortbasismap[0] = nx;
            ortbasissize = 1;
            ablasf.rallocv(ncenters, ref z, _params);
            for(k=0; k<=nx-1; k++)
            {
                for(j=0; j<=ncenters-1; j++)
                {
                    z[j] = a[ncenters+k,j];
                }
                v = Math.Sqrt(ablasf.rdotv2(ncenters, z, _params));
                ablas.rowwisegramschmidt(q1, ortbasissize, ncenters, z, ref y, true, _params);
                vv = Math.Sqrt(ablasf.rdotv2(ncenters, z, _params));
                if( (double)(vv)>(double)(Math.Sqrt(math.machineepsilon)*(v+1)) )
                {
                    ablasf.rcopymulvr(ncenters, 1/vv, z, q1, ortbasissize, _params);
                    ablasf.rcopyvc(ortbasissize, y, r, ortbasissize, _params);
                    r[ortbasissize,ortbasissize] = vv;
                    ortbasismap[ortbasissize] = k;
                    ortbasissize = ortbasissize+1;
                }
            }
            
            //
            // Second, compute system matrix Q and target values for cardinal basis functions B.
            //
            // The Q is conditionally positive definite, i.e. x'*Q*x>0 for any x satisfying orthogonality conditions
            // (orthogonal with respect to basis stored in Q1).
            //
            ablasf.rsetallocm(ncenters, ncenters, 0.0, ref q, _params);
            for(i=0; i<=ncenters-1; i++)
            {
                ablasf.rcopyrr(ncenters, a, i, q, i, _params);
            }
            ablasf.rallocm(nrhs, ncoeff, ref ssol, _params);
            ablasf.rcopym(nrhs, ncenters, bb, ssol, _params);
            for(i=0; i<=ncenters-1; i++)
            {
                q[i,i] = q[i,i]+lambdav;
            }
            
            //
            // Transform Q from conditionally positive definite to the (simply) positive definite one:
            // multiply linear system Q*x=RHS from both sides by (I-Q1'*Q1), apply additional regularization.
            //
            // NOTE: RHS is also multiplied by (I-Q1'*Q1), but from the left only.
            //
            ablasf.rallocv(ncenters, ref z, _params);
            for(i=0; i<=ncenters-1; i++)
            {
                ablasf.rcopyrv(ncenters, q, i, z, _params);
                ablas.rowwisegramschmidt(q1, ortbasissize, ncenters, z, ref y, false, _params);
                ablasf.rcopyvr(ncenters, z, q, i, _params);
            }
            for(i=0; i<=ncenters-1; i++)
            {
                ablasf.rcopycv(ncenters, q, i, z, _params);
                ablas.rowwisegramschmidt(q1, ortbasissize, ncenters, z, ref y, false, _params);
                ablasf.rcopyvc(ncenters, z, q, i, _params);
            }
            for(i=0; i<=nrhs-1; i++)
            {
                ablasf.rcopyrv(ncenters, ssol, i, z, _params);
                ablas.rowwisegramschmidt(q1, ortbasissize, ncenters, z, ref y, false, _params);
                ablasf.rcopyvr(ncenters, z, ssol, i, _params);
            }
            mx = 1.0;
            for(i=0; i<=ncenters-1; i++)
            {
                mx = Math.Max(mx, Math.Abs(q[i,i]));
            }
            for(i=0; i<=ncenters-1; i++)
            {
                ablasf.rcopyrv(ncenters, q, i, z, _params);
                for(j=0; j<=ortbasissize-1; j++)
                {
                    ablasf.raddrv(ncenters, mx*q1[j,i], q1, j, z, _params);
                }
                ablasf.rcopyvr(ncenters, z, q, i, _params);
            }
            for(i=0; i<=ncenters-1; i++)
            {
                q[i,i] = q[i,i]+reg*mx;
            }
            
            //
            // Perform Cholesky factorization, solve and obtain RBF coefficients (we still have
            // to compute polynomial term - it will be done later)
            //
            if( !trfac.spdmatrixcholeskyrec(q, 0, ncenters, false, ref choltmp, _params) )
            {
                alglib.ap.assert(false, "GENMOD: RBF solver failed due to extreme degeneracy");
            }
            ablas.rmatrixrighttrsm(nrhs, ncenters, q, 0, 0, false, false, 1, ssol, 0, 0, _params);
            ablas.rmatrixrighttrsm(nrhs, ncenters, q, 0, 0, false, false, 0, ssol, 0, 0, _params);
            
            //
            // Now, having RBF coefficients we can compute residual from fitting ACBF targets
            // with pure RBF term and fit polynomial term to this residual. In the ideal world
            // it should result in the nice and precise polynomial coefficients.
            //
            ablasf.rallocv(ncenters, ref z, _params);
            ablasf.rallocv(ncenters, ref c, _params);
            for(i=0; i<=nrhs-1; i++)
            {
                ablasf.rcopyrv(ncenters, bb, i, z, _params);
                ablasf.rcopyrv(ncenters, ssol, i, c, _params);
                ablasf.rgemv(ncenters, ncenters, -1.0, a, 0, c, 1.0, z, _params);
                ablas.rowwisegramschmidt(q1, ortbasissize, ncenters, z, ref y, true, _params);
                ablas.rmatrixtrsv(ortbasissize, r, 0, 0, true, false, 0, y, 0, _params);
                for(j=0; j<=nx; j++)
                {
                    ssol[i,ncenters+j] = 0.0;
                }
                for(j=0; j<=ortbasissize-1; j++)
                {
                    ssol[i,ncenters+ortbasismap[j]] = y[j];
                }
            }
        }


    }
    public partial class dyncrs
    {
        public class dynamiccrs : apobject
        {
            public int m;
            public int n;
            public int maxallocated;
            public int[] rowbegin;
            public int[] rowend;
            public int[] idx;
            public double[] vals;
            public dynamiccrs()
            {
                init();
            }
            public override void init()
            {
                rowbegin = new int[0];
                rowend = new int[0];
                idx = new int[0];
                vals = new double[0];
            }
            public override alglib.apobject make_copy()
            {
                dynamiccrs _result = new dynamiccrs();
                _result.m = m;
                _result.n = n;
                _result.maxallocated = maxallocated;
                _result.rowbegin = (int[])rowbegin.Clone();
                _result.rowend = (int[])rowend.Clone();
                _result.idx = (int[])idx.Clone();
                _result.vals = (double[])vals.Clone();
                return _result;
            }
        };




        /*************************************************************************
        Initializes empty dynamic CRS matrix with either M or N equal to zero.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrsinitempty(dynamiccrs r,
            int n,
            int m,
            alglib.xparams _params)
        {
            alglib.ap.assert(n*m==0, "DynCRSInitEmpty: M*N<>0");
            r.m = m;
            r.n = n;
            if( m>0 )
            {
                ablasf.isetallocv(m, 0, ref r.rowbegin, _params);
                ablasf.isetallocv(m, 0, ref r.rowend, _params);
            }
            r.maxallocated = 0;
        }


        /*************************************************************************
        Copies dynamic CRS matrix

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrscopy(dynamiccrs src,
            dynamiccrs dst,
            alglib.xparams _params)
        {
            int i = 0;
            int m = 0;
            int n = 0;
            int rowsize = 0;

            m = src.m;
            n = src.n;
            dst.m = m;
            dst.n = n;
            dst.maxallocated = 0;
            ablasf.iallocv(m, ref dst.rowbegin, _params);
            ablasf.iallocv(m, ref dst.rowend, _params);
            for(i=0; i<=m-1; i++)
            {
                rowsize = src.rowend[i]-src.rowbegin[i];
                dst.rowbegin[i] = dst.maxallocated;
                dst.rowend[i] = dst.maxallocated+rowsize;
                dst.maxallocated = dst.rowend[i];
                ablasf.igrowv(dst.rowend[i], ref dst.idx, _params);
                ablasf.rgrowv(dst.rowend[i], ref dst.vals, _params);
                ablasf.icopyvx(rowsize, src.idx, src.rowbegin[i], dst.idx, dst.rowbegin[i], _params);
                ablasf.rcopyvx(rowsize, src.vals, src.rowbegin[i], dst.vals, dst.rowbegin[i], _params);
            }
        }


        /*************************************************************************
        Copies DynCRS matrix with deletion of row/column at position DeletePos
        (the matrix must be square), with 0<=DeletePos<N/M. Cols/rows at the
        position DeletePos and past it are shifted to the left. If N=M=1, then an
        empty matrix is correctly created.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrscopydeleterowcol(dynamiccrs src,
            int deletepos,
            dynamiccrs dst,
            alglib.xparams _params)
        {
            int isrc = 0;
            int idst = 0;
            int m = 0;
            int n = 0;
            int maxrowsize = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int j = 0;

            m = src.m;
            n = src.n;
            alglib.ap.assert(m==n, "DynCRSCopyDeleteRowCol: non-square input matrix");
            alglib.ap.assert(0<=deletepos && deletepos<n, "DynCRSCopyDeleteRowCol: incorrect DeletePos");
            dst.m = m-1;
            dst.n = n-1;
            dst.maxallocated = 0;
            ablasf.iallocv(m-1, ref dst.rowbegin, _params);
            ablasf.iallocv(m-1, ref dst.rowend, _params);
            idst = 0;
            for(isrc=0; isrc<=m-1; isrc++)
            {
                if( isrc!=deletepos )
                {
                    maxrowsize = src.rowend[isrc]-src.rowbegin[isrc];
                    dst.rowbegin[idst] = dst.maxallocated;
                    ablasf.igrowv(dst.maxallocated+maxrowsize, ref dst.idx, _params);
                    ablasf.rgrowv(dst.maxallocated+maxrowsize, ref dst.vals, _params);
                    j0 = src.rowbegin[isrc];
                    j1 = src.rowend[isrc]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        if( src.idx[jj]!=deletepos )
                        {
                            j = src.idx[jj];
                            if( j>deletepos )
                            {
                                j = j-1;
                            }
                            dst.idx[dst.maxallocated] = j;
                            dst.vals[dst.maxallocated] = src.vals[jj];
                            dst.maxallocated = dst.maxallocated+1;
                        }
                    }
                    dst.rowend[idst] = dst.maxallocated;
                    idst = idst+1;
                }
            }
        }


        /*************************************************************************
        Copies DynCRS matrix with deletion of rows/columns at positions in DeleteSet
        (the matrix must be square). Cols/rows are shifted to the left. The matrix
        must be a square one.

        Correctly creates an empty matrix if all rows/cols are removed.

        Buf must be a preallocated array, with at least Src.N elements.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrscopydeleterowscols(dynamiccrs src,
            apstruct.niset deleteset,
            dynamiccrs dst,
            int[] buf,
            alglib.xparams _params)
        {
            int isrc = 0;
            int idst = 0;
            int m = 0;
            int n = 0;
            int maxrowsize = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int j = 0;

            m = src.m;
            n = src.n;
            alglib.ap.assert(m==n, "DynCRSCopyDeleteRowsCols: non-square input matrix");
            alglib.ap.assert(alglib.ap.len(buf)>=n, "DynCRSCopyDeleteRowsCols: buf[] array is too short");
            alglib.ap.assert(0<=deleteset.nstored && deleteset.nstored<=n, "DynCRSCopyDeleteRowsCols: incorrect DeleteSet size");
            for(j=0; j<=deleteset.nstored-1; j++)
            {
                alglib.ap.assert(deleteset.items[j]>=0 && deleteset.items[j]<n, "DynCRSCopyDeleteRowsCols: items in DeleteSet are outside of [0,N) range");
            }
            idst = 0;
            for(j=0; j<=n-1; j++)
            {
                if( deleteset.locationof[j]<0 )
                {
                    buf[j] = idst;
                    idst = idst+1;
                }
                else
                {
                    buf[j] = -999999;
                }
            }
            dst.m = m-deleteset.nstored;
            dst.n = n-deleteset.nstored;
            dst.maxallocated = 0;
            ablasf.iallocv(dst.m, ref dst.rowbegin, _params);
            ablasf.iallocv(dst.m, ref dst.rowend, _params);
            idst = 0;
            for(isrc=0; isrc<=m-1; isrc++)
            {
                if( deleteset.locationof[isrc]<0 )
                {
                    maxrowsize = src.rowend[isrc]-src.rowbegin[isrc];
                    dst.rowbegin[idst] = dst.maxallocated;
                    ablasf.igrowv(dst.maxallocated+maxrowsize, ref dst.idx, _params);
                    ablasf.rgrowv(dst.maxallocated+maxrowsize, ref dst.vals, _params);
                    j0 = src.rowbegin[isrc];
                    j1 = src.rowend[isrc]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        if( deleteset.locationof[src.idx[jj]]<0 )
                        {
                            j = src.idx[jj];
                            j = buf[j];
                            dst.idx[dst.maxallocated] = j;
                            dst.vals[dst.maxallocated] = src.vals[jj];
                            dst.maxallocated = dst.maxallocated+1;
                        }
                    }
                    dst.rowend[idst] = dst.maxallocated;
                    idst = idst+1;
                }
            }
        }


        /*************************************************************************
        Copies DynCRS matrix with insertion of zero row/column at position InsertPos
        (the matrix must be square), with 0<=InsertPos<=N/M. Cols/rows at the
        position InsertPos and past it are shifted to the right. If N=M=1, then an
        empty matrix is correctly created.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrscopyinsertrowcol(dynamiccrs src,
            int insertpos,
            dynamiccrs dst,
            alglib.xparams _params)
        {
            int isrc = 0;
            int idst = 0;
            int m = 0;
            int n = 0;
            int maxrowsize = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int j = 0;

            m = src.m;
            n = src.n;
            alglib.ap.assert(m==n, "DynCRSCopyInsertRowCol: non-square input matrix");
            alglib.ap.assert(0<=insertpos && insertpos<=n, "DynCRSCopyInsertRowCol: incorrect InsertPos");
            dst.m = m+1;
            dst.n = n+1;
            dst.maxallocated = 0;
            ablasf.iallocv(m+1, ref dst.rowbegin, _params);
            ablasf.iallocv(m+1, ref dst.rowend, _params);
            idst = 0;
            for(isrc=0; isrc<=m; isrc++)
            {
                if( isrc==insertpos )
                {
                    dst.rowbegin[idst] = dst.maxallocated;
                    ablasf.igrowv(dst.maxallocated+1, ref dst.idx, _params);
                    ablasf.rgrowv(dst.maxallocated+1, ref dst.vals, _params);
                    dst.idx[dst.maxallocated] = idst;
                    dst.vals[dst.maxallocated] = 0.0;
                    dst.maxallocated = dst.maxallocated+1;
                    dst.rowend[idst] = dst.maxallocated;
                    idst = idst+1;
                }
                if( isrc<m )
                {
                    maxrowsize = src.rowend[isrc]-src.rowbegin[isrc];
                    dst.rowbegin[idst] = dst.maxallocated;
                    ablasf.igrowv(dst.maxallocated+maxrowsize, ref dst.idx, _params);
                    ablasf.rgrowv(dst.maxallocated+maxrowsize, ref dst.vals, _params);
                    j0 = src.rowbegin[isrc];
                    j1 = src.rowend[isrc]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = src.idx[jj];
                        if( j>=insertpos )
                        {
                            j = j+1;
                        }
                        dst.idx[dst.maxallocated] = j;
                        dst.vals[dst.maxallocated] = src.vals[jj];
                        dst.maxallocated = dst.maxallocated+1;
                    }
                    dst.rowend[idst] = dst.maxallocated;
                    idst = idst+1;
                }
            }
        }


        /*************************************************************************
        Initialize dynamic CRS matrix using SparseMatrix structure

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrsinitfromsparsecrs(sparse.sparsematrix s,
            dynamiccrs r,
            alglib.xparams _params)
        {
            int m = 0;
            int n = 0;

            m = s.m;
            n = s.n;
            alglib.ap.assert(s.matrixtype==1, "DynCRSInitFromSparseCRS: S is not CRS matrix");
            r.m = m;
            r.n = n;
            ablasf.icopyallocv(s.ridx[m], s.idx, ref r.idx, _params);
            ablasf.rcopyallocv(s.ridx[m], s.vals, ref r.vals, _params);
            ablasf.iallocv(m, ref r.rowbegin, _params);
            ablasf.iallocv(m, ref r.rowend, _params);
            ablasf.icopyvx(m, s.ridx, 0, r.rowbegin, 0, _params);
            ablasf.icopyvx(m, s.ridx, 1, r.rowend, 0, _params);
            r.maxallocated = r.rowend[m-1];
        }


        /*************************************************************************
        Drops numerical zeros from the matrix

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrsdropzeros(dynamiccrs a,
            alglib.xparams _params)
        {
            int m = 0;
            int i = 0;
            int j = 0;
            int jj = 0;
            int offs = 0;
            double v = 0;

            m = a.m;
            for(i=0; i<=m-1; i++)
            {
                offs = a.rowbegin[i];
                for(jj=a.rowbegin[i]; jj<=a.rowend[i]-1; jj++)
                {
                    j = a.idx[jj];
                    v = a.vals[jj];
                    if( v==0 )
                    {
                        continue;
                    }
                    a.idx[offs] = j;
                    a.vals[offs] = v;
                    offs = offs+1;
                }
                a.rowend[i] = offs;
            }
        }


        /*************************************************************************
        Drops offdiagonal numerical zeros from the matrix

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrsdropoffdiagonalzeros(dynamiccrs a,
            alglib.xparams _params)
        {
            int m = 0;
            int i = 0;
            int j = 0;
            int jj = 0;
            int offs = 0;
            double v = 0;

            m = a.m;
            for(i=0; i<=m-1; i++)
            {
                offs = a.rowbegin[i];
                for(jj=a.rowbegin[i]; jj<=a.rowend[i]-1; jj++)
                {
                    j = a.idx[jj];
                    v = a.vals[jj];
                    if( j!=i && v==0 )
                    {
                        continue;
                    }
                    a.idx[offs] = j;
                    a.vals[offs] = v;
                    offs = offs+1;
                }
                a.rowend[i] = offs;
            }
        }


        /*************************************************************************
        Removes rows

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrsclearrow(dynamiccrs a,
            int rowidx,
            alglib.xparams _params)
        {
            a.rowend[rowidx] = a.rowbegin[rowidx];
        }


        /*************************************************************************
        Removes element from the row

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrsremovefromrow(dynamiccrs a,
            int rowidx,
            int j,
            alglib.xparams _params)
        {
            int ii = 0;
            int offs = 0;

            offs = a.rowbegin[rowidx];
            for(ii=a.rowbegin[rowidx]; ii<=a.rowend[rowidx]-1; ii++)
            {
                if( a.idx[ii]!=j )
                {
                    a.idx[offs] = a.idx[ii];
                    a.vals[offs] = a.vals[ii];
                    offs = offs+1;
                }
            }
            a.rowend[rowidx] = offs;
        }


        /*************************************************************************
        Factors out element J from the row RowIdx by means of transformation

            X[J] = C0+C1*X[K].
            
        Depending on context, can be used to factor out elements from individual
        rows of a quadratic matrix H (in this case C0 can be zero because it does
        not actually used), or to factor out elements from the linear constraints
        matrix.

        The function returns the value of new element A[RowIdx,K]. A zero can be
        returned, e.g. if cancellation or nearly-cancellation has occurred.

        When used to process linear constraints, it also returns a shift that should be applied to row bounds,
        which is equal to C0*A[I,J]. Correctly handles the situation when factoring
        an element out results in a cancellation: if CheckCancellation is True,
        it removes canceled element from the row.

        When no element J is present in the row RowIdx, does nothing and returns zero.


          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrsfactoroutfromrow(dynamiccrs a,
            int rowidx,
            int j,
            double c0,
            double c1,
            int k,
            bool checkcancellation,
            ref double newval,
            ref double shift,
            alglib.xparams _params)
        {
            int ii = 0;
            int pos0 = 0;
            int pos1 = 0;
            int i = 0;
            int i0 = 0;
            int i1 = 0;
            double eps = 0;
            double mx = 0;
            double v = 0;

            newval = 0;
            shift = 0;

            eps = 10*math.machineepsilon;
            newval = 0.0;
            shift = 0.0;
            pos0 = a.rowend[rowidx];
            pos1 = a.rowend[rowidx];
            for(ii=a.rowbegin[rowidx]; ii<=a.rowend[rowidx]-1; ii++)
            {
                if( a.idx[ii]==j )
                {
                    pos0 = ii;
                }
                if( a.idx[ii]==k )
                {
                    pos1 = ii;
                }
            }
            if( pos0==a.rowend[rowidx] )
            {
                return;
            }
            shift = a.vals[pos0]*c0;
            if( pos1!=a.rowend[rowidx] )
            {
                mx = Math.Max(Math.Abs(a.vals[pos0]), Math.Abs(a.vals[pos1]));
                v = a.vals[pos1]+a.vals[pos0]*c1;
                a.vals[pos1] = v;
                newval = v;
                dyncrsremovefromrow(a, rowidx, j, _params);
                if( checkcancellation && (double)(Math.Abs(v))<=(double)(eps*mx) )
                {
                    dyncrsremovefromrow(a, rowidx, k, _params);
                    newval = 0.0;
                }
            }
            else
            {
                v = a.vals[pos0]*c1;
                a.idx[pos0] = k;
                a.vals[pos0] = v;
                newval = v;
                if( k>j )
                {
                    i0 = pos0;
                    i1 = a.rowend[rowidx]-1;
                    while( i0<i1 )
                    {
                        i = a.idx[i0+1];
                        if( i>k )
                        {
                            break;
                        }
                        a.idx[i0] = i;
                        a.vals[i0] = a.vals[i0+1];
                        a.idx[i0+1] = k;
                        a.vals[i0+1] = v;
                        i0 = i0+1;
                    }
                }
                else
                {
                    i0 = pos0;
                    i1 = a.rowbegin[rowidx];
                    while( i0>i1 )
                    {
                        i = a.idx[i0-1];
                        if( i<k )
                        {
                            break;
                        }
                        a.idx[i0] = i;
                        a.vals[i0] = a.vals[i0-1];
                        a.idx[i0-1] = k;
                        a.vals[i0-1] = v;
                        i0 = i0-1;
                    }
                }
            }
        }


        /*************************************************************************
        Adds Row0 times C to Row1. If RetainDiagonal is True, never removes diagonal
        elements from Row1 even if cancellation is present


          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrsaddrowto(dynamiccrs a,
            int row0,
            double c,
            int row1,
            bool retaindiagonal,
            bool checkcancellation,
            alglib.xparams _params)
        {
            int begin0 = 0;
            int begin1 = 0;
            int end0 = 0;
            int end1 = 0;
            int i0 = 0;
            int i1 = 0;
            double v0 = 0;
            double v1 = 0;
            double mx = 0;
            int beginr = 0;
            int endr = 0;
            double eps = 0;

            eps = 10*math.machineepsilon;
            if( (double)(c)==(double)(0.0) )
            {
                return;
            }
            begin0 = a.rowbegin[row0];
            begin1 = a.rowbegin[row1];
            end0 = a.rowend[row0];
            end1 = a.rowend[row1];
            if( begin0==end0 )
            {
                return;
            }
            ablasf.igrowv(a.maxallocated+(end0-begin0)+(end1-begin1), ref a.idx, _params);
            ablasf.rgrowv(a.maxallocated+(end0-begin0)+(end1-begin1), ref a.vals, _params);
            beginr = a.maxallocated;
            endr = beginr;
            while( begin0<end0 && begin1<end1 )
            {
                i0 = a.idx[begin0];
                i1 = a.idx[begin1];
                if( i0<i1 )
                {
                    a.idx[endr] = i0;
                    a.vals[endr] = c*a.vals[begin0];
                    endr = endr+1;
                    begin0 = begin0+1;
                    continue;
                }
                if( i1<i0 )
                {
                    a.idx[endr] = i1;
                    a.vals[endr] = a.vals[begin1];
                    endr = endr+1;
                    begin1 = begin1+1;
                    continue;
                }
                v0 = a.vals[begin0];
                v1 = a.vals[begin1];
                if( checkcancellation )
                {
                    mx = Math.Max(Math.Abs(v0), Math.Abs(v1));
                    if( (!retaindiagonal || i1!=row1) && ((double)(mx)==(double)(0) || Math.Abs(c*v0+v1)<=eps*mx) )
                    {
                        begin0 = begin0+1;
                        begin1 = begin1+1;
                        continue;
                    }
                }
                a.idx[endr] = i1;
                a.vals[endr] = c*v0+v1;
                endr = endr+1;
                begin0 = begin0+1;
                begin1 = begin1+1;
            }
            while( begin0<end0 )
            {
                a.idx[endr] = a.idx[begin0];
                a.vals[endr] = c*a.vals[begin0];
                endr = endr+1;
                begin0 = begin0+1;
            }
            while( begin1<end1 )
            {
                a.idx[endr] = a.idx[begin1];
                a.vals[endr] = a.vals[begin1];
                endr = endr+1;
                begin1 = begin1+1;
            }
            a.maxallocated = endr;
            a.rowbegin[row1] = beginr;
            a.rowend[row1] = endr;
        }


        /*************************************************************************
        Inserts sparse vector into the row, rewriting existing elements by new values.
        If a new value is zero, the element (if exists) is removed from the target
        row.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrsinsertwithrewrite(dynamiccrs a,
            int tgtrow,
            int[] idx,
            double[] vals,
            int cnt,
            alglib.xparams _params)
        {
            int begins = 0;
            int ends = 0;
            int begini = 0;
            int i0 = 0;
            int i1 = 0;
            int beginr = 0;
            int endr = 0;

            if( cnt==0 )
            {
                return;
            }
            begins = a.rowbegin[tgtrow];
            ends = a.rowend[tgtrow];
            ablasf.igrowv(a.maxallocated+(ends-begins)+cnt, ref a.idx, _params);
            ablasf.rgrowv(a.maxallocated+(ends-begins)+cnt, ref a.vals, _params);
            beginr = a.maxallocated;
            endr = beginr;
            begini = 0;
            while( begins<ends && begini<cnt )
            {
                i0 = a.idx[begins];
                i1 = idx[begini];
                if( i0<i1 )
                {
                    a.idx[endr] = i0;
                    a.vals[endr] = a.vals[begins];
                    endr = endr+1;
                    begins = begins+1;
                    continue;
                }
                if( i1<i0 )
                {
                    if( vals[begini]!=0.0 )
                    {
                        a.idx[endr] = i1;
                        a.vals[endr] = vals[begini];
                        endr = endr+1;
                    }
                    begini = begini+1;
                    continue;
                }
                if( vals[begini]!=0.0 )
                {
                    a.idx[endr] = i1;
                    a.vals[endr] = vals[begini];
                    endr = endr+1;
                }
                begins = begins+1;
                begini = begini+1;
            }
            while( begins<ends )
            {
                a.idx[endr] = a.idx[begins];
                a.vals[endr] = a.vals[begins];
                endr = endr+1;
                begins = begins+1;
            }
            while( begini<cnt )
            {
                if( vals[begini]!=0.0 )
                {
                    a.idx[endr] = idx[begini];
                    a.vals[endr] = vals[begini];
                    endr = endr+1;
                }
                begini = begini+1;
            }
            a.maxallocated = endr;
            a.rowbegin[tgtrow] = beginr;
            a.rowend[tgtrow] = endr;
        }


        /*************************************************************************
        Removes elements with indexes in the set from the row

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrsremovesetfromrow(dynamiccrs a,
            int rowidx,
            apstruct.niset s,
            alglib.xparams _params)
        {
            int ii = 0;
            int offs = 0;

            offs = a.rowbegin[rowidx];
            for(ii=a.rowbegin[rowidx]; ii<=a.rowend[rowidx]-1; ii++)
            {
                if( s.locationof[a.idx[ii]]<0 )
                {
                    a.idx[offs] = a.idx[ii];
                    a.vals[offs] = a.vals[ii];
                    offs = offs+1;
                }
            }
            a.rowend[rowidx] = offs;
        }


        /*************************************************************************
        Computes dot product of C[] elements from the set S with corresponding
        elements from A[RowIdx], and removes these elements from A[RowIdx]

          -- ALGLIB --
             Copyright 01.03.2026 by Bochkanov Sergey
        *************************************************************************/
        public static double dyncrsdotremovesetfromrow(dynamiccrs a,
            int rowidx,
            double[] c,
            apstruct.niset s,
            alglib.xparams _params)
        {
            double result = 0;
            int ii = 0;
            int i0 = 0;
            int i1 = 0;
            int offs = 0;
            int j = 0;

            result = 0;
            i0 = a.rowbegin[rowidx];
            i1 = a.rowend[rowidx]-1;
            offs = i0;
            for(ii=a.rowbegin[rowidx]; ii<=i1; ii++)
            {
                j = a.idx[ii];
                if( s.locationof[j]<0 )
                {
                    a.idx[offs] = j;
                    a.vals[offs] = a.vals[ii];
                    offs = offs+1;
                }
                else
                {
                    result = result+c[j]*a.vals[ii];
                }
            }
            a.rowend[rowidx] = offs;
            return result;
        }


        /*************************************************************************
        Get element that it known to exist in the matrix. If it does not, the
        function fails with an exception. O(log(row_size)) running time.


          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        public static double dyncrsgetexistingelement(dynamiccrs a,
            int i,
            int j,
            alglib.xparams _params)
        {
            double result = 0;
            int k = 0;

            k = apserv.ibinarysearchlft(a.idx, a.rowbegin[i], a.rowend[i], j, _params);
            alglib.ap.assert(k<a.rowend[i] && a.idx[k]==j, "DynCRSGetExistingElement: element not found");
            result = a.vals[k];
            return result;
        }


        /*************************************************************************
        Get element, return zero for non-existent element.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        public static double dyncrsgetelementifexists(dynamiccrs a,
            int i,
            int j,
            alglib.xparams _params)
        {
            double result = 0;
            int k = 0;

            k = apserv.ibinarysearchlft(a.idx, a.rowbegin[i], a.rowend[i], j, _params);
            result = 0;
            if( k<a.rowend[i] && a.idx[k]==j )
            {
                result = a.vals[k];
            }
            return result;
        }


        /*************************************************************************
        Sets an element that it known to exist in the matrix. If it does not, the
        function fails with an exception. O(log(row_size)) running time.


          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void dyncrssetexistingelement(dynamiccrs a,
            int i,
            int j,
            double v,
            alglib.xparams _params)
        {
            int k = 0;

            k = apserv.ibinarysearchlft(a.idx, a.rowbegin[i], a.rowend[i], j, _params);
            alglib.ap.assert(k<a.rowend[i] && a.idx[k]==j, "DynCRSSetExistingElement: element not found");
            a.vals[k] = v;
        }


        /*************************************************************************
        Gets nonzero count, has O(M) running time

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static int dyncrscountnonzeros(dynamiccrs a,
            alglib.xparams _params)
        {
            int result = 0;
            int rowidx = 0;

            result = 0;
            for(rowidx=0; rowidx<=a.m-1; rowidx++)
            {
                result = result+(a.rowend[rowidx]-a.rowbegin[rowidx]);
            }
            return result;
        }


    }
