        /*************************************************************************
        No presolve, just user-supplied scaling

          S, X0, BndL, BndU     -   variable scales, initial point, bounds
          IsIntegral, IsLinear  -   integrality and linearity masks
          N                     -   vars count
          A, AL, AU             -   AL<=A*x<=AU, MLC constraints
          LCSrcIdx              -   original indexes of constraints in a larger
                                    formulation. Used to determine proper LCIdx
                                    when reporting constraint violations.
          NL, NU, MNLC          -   nonlinear constraints
          IsHard                -   hardness mask for nonlinear constraints
          EPS                   -   tolerance
          DoTrace               -   report diagnostics

          -- ALGLIB --
             Copyright 01.03.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlppresolvenonescaleuser(double[] s,
            double[] x0,
            double[] bndl,
            double[] bndu,
            bool[] isintegral,
            bool[] islinear,
            int n,
            sparse.sparsematrix a,
            double[] al,
            double[] au,
            int[] lcsrcidx,
            int mlc,
            double[] nl,
            double[] nu,
            bool[] ishard,
            int mnlc,
            double eps,
            bool dotrace,
            nlppresolveinfo info,
            alglib.xparams _params)
        {
            int i = 0;

            info.problemstatus = 0;
            info.repbcerr = 0;
            info.repbcidx = -1;
            info.replcerr = 0;
            info.replcidx = -1;
            info.repnlcerr = 0;
            info.repnlcidx = -1;
            for(i=0; i<=n-1; i++)
            {
                if( (math.isfinite(bndl[i]) && math.isfinite(bndu[i])) && (double)(bndl[i])>(double)(bndu[i]) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> variable {0,0:d} is found to have infeasible box constraints, terminating\n", i));
                    }
                    info.problemstatus = -3;
                    info.repbcerr = bndl[i]-bndu[i];
                    info.repbcidx = i;
                    return;
                }
            }
            for(i=0; i<=mlc-1; i++)
            {
                if( (math.isfinite(al[i]) && math.isfinite(au[i])) && (double)(al[i])>(double)(au[i]) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> linear constraint {0,0:d} is found to have infeasible bounds, terminating\n", i));
                    }
                    info.problemstatus = -3;
                    info.replcerr = al[i]-au[i];
                    info.replcidx = lcsrcidx[i];
                    return;
                }
            }
            for(i=0; i<=mnlc-1; i++)
            {
                if( (math.isfinite(nl[i]) && math.isfinite(nu[i])) && (double)(nl[i])>(double)(nu[i]) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> nonlinear constraint {0,0:d} is found to have infeasible bounds, terminating\n", i));
                    }
                    info.problemstatus = -3;
                    info.repnlcerr = nl[i]-nu[i];
                    info.repnlcidx = i;
                    return;
                }
            }
            info.eps = eps;
            info.oldn = n;
            info.oldmlc = mlc;
            info.oldmnlc = mnlc;
            ablasf.rcopyallocv(n, x0, ref info.oldx0, _params);
            ablasf.rcopyallocv(n, bndl, ref info.oldbndl, _params);
            ablasf.rcopyallocv(n, bndu, ref info.oldbndu, _params);
            ablasf.rcopyallocv(n, bndl, ref info.oldfinitebndl, _params);
            ablasf.rcopyallocv(n, bndu, ref info.oldfinitebndu, _params);
            ablasf.rcopyallocv(n, s, ref info.olds, _params);
            for(i=0; i<=n-1; i++)
            {
                if( isintegral[i] )
                {
                    info.olds[i] = 1.0;
                }
                if( Double.IsNegativeInfinity(bndl[i]) )
                {
                    info.oldfinitebndl[i] = -math.maxrealnumber;
                }
                if( Double.IsPositiveInfinity(bndu[i]) )
                {
                    info.oldfinitebndu[i] = math.maxrealnumber;
                }
            }
            ablasf.bcopyallocv(n, isintegral, ref info.oldintegralmask, _params);
            ablasf.bcopyallocv(n, islinear, ref info.oldlinearmask, _params);
            if( mlc>0 )
            {
                sparse.sparsecopybuf(a, info.olda, _params);
                ablasf.rcopyallocv(mlc, al, ref info.oldal, _params);
                ablasf.rcopyallocv(mlc, au, ref info.oldau, _params);
                ablasf.icopyallocv(mlc, lcsrcidx, ref info.oldlcsrcidx, _params);
            }
            if( mnlc>0 )
            {
                ablasf.rcopyallocv(mnlc, nl, ref info.oldnl, _params);
                ablasf.rcopyallocv(mnlc, nu, ref info.oldnu, _params);
                ablasf.bcopyallocv(mnlc, ishard, ref info.oldhardmask, _params);
            }
            ablasf.bsetallocv(n, false, ref info.isoldfixed, _params);
            ablasf.rsetallocv(n, 0.0, ref info.fixedvals, _params);
            ablasf.iallocv(n, ref info.packxperm, _params);
            ablasf.iallocv(n, ref info.unpackxperm, _params);
            for(i=0; i<=n-1; i++)
            {
                info.packxperm[i] = i;
                info.unpackxperm[i] = i;
            }
            info.kxx = 0;
            info.justscale = true;
            ablasf.rcopyallocv(n, s, ref info.packeds, _params);
            info.newn = n;
            info.newmlc = mlc;
            info.newmnlc = mnlc;
            ablasf.rcopyallocv(n, x0, ref info.newx0, _params);
            ablasf.rcopyallocv(n, bndl, ref info.newbndl, _params);
            ablasf.rcopyallocv(n, bndu, ref info.newbndu, _params);
            ablasf.rmergedivv(n, info.olds, info.newx0, _params);
            ablasf.rmergedivv(n, info.olds, info.newbndl, _params);
            ablasf.rmergedivv(n, info.olds, info.newbndu, _params);
            ablasf.rsetallocv(n, 1.0, ref info.news, _params);
            ablasf.bcopyallocv(n, isintegral, ref info.newintegralmask, _params);
            ablasf.bcopyallocv(n, islinear, ref info.newlinearmask, _params);
            if( mlc>0 )
            {
                copylcwithrescaleandrenorm(info.olds, n, a, al, au, lcsrcidx, mlc, info.newa, ref info.newal, ref info.newau, ref info.newlcsrcidx, ref info.newlcscales, _params);
            }
            if( mnlc>0 )
            {
                ablasf.rcopyallocv(mnlc, nl, ref info.newnl, _params);
                ablasf.rcopyallocv(mnlc, nu, ref info.newnu, _params);
                ablasf.bcopyallocv(mnlc, ishard, ref info.newhardmask, _params);
            }
        }


        /*************************************************************************
        Powerful presolver that makes it impossible to restore Lagrange multipliers

          S, X0, BndL, BndU     -   variable scales, initial point, bounds
          IsIntegral, IsLinear  -   integrality and linearity masks
          N                     -   vars count
          A, AL, AU             -   AL<=A*x<=AU, MLC constraints
          LCSrcIdx              -   original indexes of constraints in a larger
                                    formulation. Used to determine proper LCIdx
                                    when reporting constraint violations.
          NL, NU, MNLC          -   nonlinear constraints
          IsHard                -   hardness mask for nonlinear constraints
          EPS                   -   tolerance
          DoTrace               -   report diagnostics

          -- ALGLIB --
             Copyright 01.03.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlppresolvepowerfulnolagrangemults(double[] s,
            double[] x0,
            double[] bndl,
            double[] bndu,
            bool[] isintegral,
            bool[] islinear,
            int n,
            sparse.sparsematrix a,
            double[] al,
            double[] au,
            int[] lcsrcidx,
            int mlc,
            double[] nl,
            double[] nu,
            bool[] ishard,
            int mnlc,
            double eps,
            bool dotrace,
            nlppresolveinfo info,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int offs = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int nnz = 0;
            double v = 0;

            info.problemstatus = 0;
            info.repbcerr = 0;
            info.repbcidx = -1;
            info.replcerr = 0;
            info.replcidx = -1;
            info.repnlcerr = 0;
            info.repnlcidx = -1;
            for(i=0; i<=n-1; i++)
            {
                if( (math.isfinite(bndl[i]) && math.isfinite(bndu[i])) && (double)(bndl[i])>(double)(bndu[i]) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> variable {0,0:d} is found to have infeasible box constraints, terminating\n", i));
                    }
                    info.problemstatus = -3;
                    info.repbcerr = bndl[i]-bndu[i];
                    info.repbcidx = i;
                    return;
                }
            }
            for(i=0; i<=mlc-1; i++)
            {
                if( (math.isfinite(al[i]) && math.isfinite(au[i])) && (double)(al[i])>(double)(au[i]) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> linear constraint {0,0:d} is found to have infeasible bounds, terminating\n", i));
                    }
                    info.problemstatus = -3;
                    info.replcerr = al[i]-au[i];
                    info.replcidx = lcsrcidx[i];
                    return;
                }
            }
            for(i=0; i<=mnlc-1; i++)
            {
                if( (math.isfinite(nl[i]) && math.isfinite(nu[i])) && (double)(nl[i])>(double)(nu[i]) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> nonlinear constraint {0,0:d} is found to have infeasible bounds, terminating\n", i));
                    }
                    info.problemstatus = -3;
                    info.repnlcerr = nl[i]-nu[i];
                    info.repnlcidx = i;
                    return;
                }
            }
            info.eps = eps;
            info.oldn = n;
            info.oldmlc = mlc;
            info.oldmnlc = mnlc;
            ablasf.rcopyallocv(n, x0, ref info.oldx0, _params);
            ablasf.rcopyallocv(n, bndl, ref info.oldbndl, _params);
            ablasf.rcopyallocv(n, bndu, ref info.oldbndu, _params);
            ablasf.rcopyallocv(n, bndl, ref info.oldfinitebndl, _params);
            ablasf.rcopyallocv(n, bndu, ref info.oldfinitebndu, _params);
            ablasf.rcopyallocv(n, s, ref info.olds, _params);
            for(i=0; i<=n-1; i++)
            {
                if( isintegral[i] )
                {
                    info.olds[i] = 1.0;
                }
                if( Double.IsNegativeInfinity(bndl[i]) )
                {
                    info.oldfinitebndl[i] = -math.maxrealnumber;
                }
                if( Double.IsPositiveInfinity(bndu[i]) )
                {
                    info.oldfinitebndu[i] = math.maxrealnumber;
                }
            }
            ablasf.bcopyallocv(n, isintegral, ref info.oldintegralmask, _params);
            ablasf.bcopyallocv(n, islinear, ref info.oldlinearmask, _params);
            if( mlc>0 )
            {
                sparse.sparsecopybuf(a, info.olda, _params);
                ablasf.rcopyallocv(mlc, al, ref info.oldal, _params);
                ablasf.rcopyallocv(mlc, au, ref info.oldau, _params);
                ablasf.icopyallocv(mlc, lcsrcidx, ref info.oldlcsrcidx, _params);
            }
            if( mnlc>0 )
            {
                ablasf.rcopyallocv(mnlc, nl, ref info.oldnl, _params);
                ablasf.rcopyallocv(mnlc, nu, ref info.oldnu, _params);
                ablasf.bcopyallocv(mnlc, ishard, ref info.oldhardmask, _params);
            }
            info.wrk.n = n;
            info.wrk.mlc = mlc;
            info.wrk.mnlc = mnlc;
            ablasf.rcopyallocv(n, x0, ref info.wrk.x0, _params);
            ablasf.rcopyallocv(n, bndl, ref info.wrk.bndl, _params);
            ablasf.rcopyallocv(n, bndu, ref info.wrk.bndu, _params);
            ablasf.rmergedivv(n, info.olds, info.wrk.x0, _params);
            ablasf.rmergedivv(n, info.olds, info.wrk.bndl, _params);
            ablasf.rmergedivv(n, info.olds, info.wrk.bndu, _params);
            ablasf.bcopyallocv(n, isintegral, ref info.wrk.integralmask, _params);
            ablasf.bcopyallocv(n, islinear, ref info.wrk.linearmask, _params);
            if( mlc>0 )
            {
                copylcwithrescaleandrenorm(info.olds, info.oldn, a, al, au, lcsrcidx, mlc, info.tmpa, ref info.wrk.al, ref info.wrk.au, ref info.wrk.lcsrcidx, ref info.wrk.lcscales, _params);
                sparse.sparsecopytransposecrsbuf(info.tmpa, info.tmpat, _params);
                dyncrs.dyncrsinitfromsparsecrs(info.tmpa, info.wrk.a, _params);
                dyncrs.dyncrsinitfromsparsecrs(info.tmpat, info.wrk.at, _params);
            }
            if( mnlc>0 )
            {
                ablasf.rcopyallocv(mnlc, nl, ref info.wrk.nl, _params);
                ablasf.rcopyallocv(mnlc, nu, ref info.wrk.nu, _params);
                ablasf.bcopyallocv(mnlc, ishard, ref info.wrk.hardmask, _params);
            }
            dopowerfulpresolve(info.wrk, eps, dotrace, _params);
            if( info.wrk.problemstatus<0 )
            {
                info.problemstatus = info.wrk.problemstatus;
                return;
            }
            if( info.wrk.problemstatus==1 )
            {
                info.problemstatus = 1;
                info.kxx = 0;
                info.justscale = false;
                ablasf.bcopyallocv(n, info.wrk.isfixed, ref info.isoldfixed, _params);
                ablasf.rcopyallocv(n, info.wrk.fixedvals, ref info.fixedvals, _params);
                info.newn = 0;
                info.repbcerr = 0;
                info.repbcidx = -1;
                info.replcerr = 0;
                info.replcidx = -1;
                info.repnlcerr = 0;
                info.repnlcidx = -1;
                info.newmlc = 0;
                info.newmnlc = mnlc;
                if( mnlc>0 )
                {
                    ablasf.rcopyallocv(mnlc, info.wrk.nl, ref info.newnl, _params);
                    ablasf.rcopyallocv(mnlc, info.wrk.nu, ref info.newnu, _params);
                    ablasf.bcopyallocv(mnlc, info.wrk.hardmask, ref info.newhardmask, _params);
                }
                return;
            }
            alglib.ap.assert(info.wrk.problemstatus==0, "NLPPRESOLVER: 452022 failed");
            info.kxx = 0;
            info.justscale = false;
            ablasf.bcopyallocv(n, info.wrk.isfixed, ref info.isoldfixed, _params);
            ablasf.rcopyallocv(n, info.wrk.fixedvals, ref info.fixedvals, _params);
            info.newn = 0;
            ablasf.rallocv(n, ref info.newx0, _params);
            ablasf.rallocv(n, ref info.newbndl, _params);
            ablasf.rallocv(n, ref info.newbndu, _params);
            ablasf.rallocv(n, ref info.news, _params);
            ablasf.rallocv(n, ref info.packeds, _params);
            ablasf.ballocv(n, ref info.newintegralmask, _params);
            ablasf.ballocv(n, ref info.newlinearmask, _params);
            ablasf.isetallocv(n, -999999999, ref info.packxperm, _params);
            ablasf.isetallocv(n, -999999999, ref info.unpackxperm, _params);
            for(i=0; i<=n-1; i++)
            {
                if( !info.wrk.isfixed[i] )
                {
                    info.packxperm[i] = info.newn;
                    info.unpackxperm[info.newn] = i;
                    info.newx0[info.newn] = info.wrk.x0[i];
                    info.newbndl[info.newn] = info.wrk.bndl[i];
                    info.newbndu[info.newn] = info.wrk.bndu[i];
                    info.news[info.newn] = 1.0;
                    info.packeds[info.newn] = info.olds[i];
                    info.newintegralmask[info.newn] = info.wrk.integralmask[i];
                    info.newlinearmask[info.newn] = info.wrk.linearmask[i];
                    info.newn = info.newn+1;
                }
            }
            alglib.ap.assert(info.newn>=1, "NLPPRESOLVER: integrity check 466948 failed");
            info.newmlc = 0;
            if( mlc>0 )
            {
                alglib.ap.assert(info.wrk.a.m==mlc, "NLPPRESOLVER: integrity check 480200 failed");
                nnz = dyncrs.dyncrscountnonzeros(info.wrk.a, _params);
                ablasf.rallocv(mlc, ref info.newal, _params);
                ablasf.rallocv(mlc, ref info.newau, _params);
                ablasf.iallocv(mlc, ref info.newlcsrcidx, _params);
                ablasf.rallocv(mlc, ref info.newlcscales, _params);
                info.newa.matrixtype = 1;
                info.newa.m = 0;
                info.newa.n = info.newn;
                ablasf.iallocv(mlc+1, ref info.newa.ridx, _params);
                ablasf.iallocv(nnz, ref info.newa.idx, _params);
                ablasf.rallocv(nnz, ref info.newa.vals, _params);
                info.newa.ridx[0] = 0;
                offs = 0;
                for(i=0; i<=mlc-1; i++)
                {
                    if( !info.wrk.isdroppedlc[i] )
                    {
                        j0 = info.wrk.a.rowbegin[i];
                        j1 = info.wrk.a.rowend[i]-1;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = info.wrk.a.idx[jj];
                            v = info.wrk.a.vals[jj];
                            if( !info.wrk.isfixed[j] && v!=0.0 )
                            {
                                info.newa.idx[offs] = info.packxperm[j];
                                info.newa.vals[offs] = v;
                                offs = offs+1;
                            }
                        }
                        info.newa.ridx[info.newa.m+1] = offs;
                        info.newal[info.newa.m] = info.wrk.al[i];
                        info.newau[info.newa.m] = info.wrk.au[i];
                        info.newlcsrcidx[info.newa.m] = info.wrk.lcsrcidx[i];
                        info.newlcscales[info.newa.m] = info.wrk.lcscales[i];
                        info.newa.m = info.newa.m+1;
                    }
                }
                if( info.newa.m>0 )
                {
                    sparse.sparseinitduidx(info.newa, _params);
                    info.newa.ninitialized = offs;
                }
                info.newmlc = info.newa.m;
            }
            info.newmnlc = mnlc;
            if( mnlc>0 )
            {
                ablasf.rcopyallocv(mnlc, info.wrk.nl, ref info.newnl, _params);
                ablasf.rcopyallocv(mnlc, info.wrk.nu, ref info.newnu, _params);
                ablasf.bcopyallocv(mnlc, info.wrk.hardmask, ref info.newhardmask, _params);
            }
        }


        /*************************************************************************
        Convert point from presolved to original space

          -- ALGLIB --
             Copyright 01.03.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlppresolverunpackpoint(nlppresolveinfo info,
            double[] newx,
            double[] oldx,
            alglib.xparams _params)
        {
            alglib.ap.assert(alglib.ap.len(oldx)>=info.oldn, "NLPPresolverUnpackPoint: output buffer is too short");
            alglib.ap.assert(info.kxx==0, "NLPPresolverUnpackPoint: 277832 failed");
            ablasf.rcopyv(info.oldn, info.fixedvals, oldx, _params);
            ablasf.rscattercopyv(info.newn, newx, oldx, info.unpackxperm, _params);
            ablasf.rmergemulv(info.oldn, info.olds, oldx, _params);
            ablasf.rmergemaxv(info.oldn, info.oldfinitebndl, oldx, _params);
            ablasf.rmergeminv(info.oldn, info.oldfinitebndu, oldx, _params);
        }


        /*************************************************************************
        Packs RCommV2 reply (in unpresolved variables) to a presolved representation
        with the sparse Jaconian

          -- ALGLIB --
             Copyright 01.03.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlppresolverpackreplytosparse(nlppresolveinfo info,
            double[] replyfi,
            double[] replydj,
            sparse.sparsematrix replysj,
            bool isdensereply,
            double[] psfi,
            sparse.sparsematrix pssj,
            double[] psfs,
            alglib.xparams _params)
        {
            alglib.ap.assert(alglib.ap.len(psfi)>=1+info.newmnlc, "NLPPresolverPackReplyToSparse: output buffer is too short");
            alglib.ap.assert(alglib.ap.len(psfs)>=1+info.newmnlc, "NLPPresolverPackReplyToSparse: output buffer is too short");
            alglib.ap.assert(info.kxx==0 && info.oldmnlc==info.newmnlc, "NLPPresolverPackReplyToSparse: 334309 failed");
            ablasf.rcopyv(1+info.newmnlc, replyfi, psfi, _params);
            if( isdensereply )
            {
                crsfromdensevwithfixandscale(replydj, 1+info.oldmnlc, info.oldn, info.isoldfixed, info.olds, info.packxperm, info.newn, pssj, psfs, ref info.wrk.tmp0, ref info.wrk.tmp1, _params);
            }
            else
            {
                sparsecopycrstocrswithfixandscale(replysj, info.isoldfixed, info.olds, info.packxperm, info.newn, pssj, psfs, ref info.wrk.tmp0, ref info.wrk.tmp1, _params);
            }
        }


        /*************************************************************************
        Packs RComm V1 reply (in unpresolved variables) to a presolved representation
        with the sparse Jaconian

          -- ALGLIB --
