        /*************************************************************************
        Unpack solution and Lagrange multipliers.

        When presolver was created in a mode that does not allow to restore
        Lagrange multipliers, output is filled by zeros.

          -- ALGLIB --
             Copyright 01.03.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlppresolverunpacksolution(nlppresolveinfo info,
            double[] psxs,
            double[] psnlrep,
            double[] pslagbc,
            double[] pslaglc,
            double[] pslagnlc,
            double[] xs,
            double[] nlrep,
            double[] lagbc,
            double[] laglc,
            double[] lagnlc,
            alglib.xparams _params)
        {
            if( info.justscale )
            {
                alglib.ap.assert((((info.kxx==0 && info.justscale) && info.oldn==info.newn) && info.oldmlc==info.newmlc) && info.oldmnlc==info.newmnlc, "NLPPresolverUnpackSolution: 387330 failed");
                ablasf.rcopyv(info.newn, psxs, xs, _params);
                ablasf.rcopyv(info.newn, psnlrep, nlrep, _params);
                ablasf.rmergemulv(info.oldn, info.olds, xs, _params);
                ablasf.rmergemaxv(info.oldn, info.oldfinitebndl, xs, _params);
                ablasf.rmergeminv(info.oldn, info.oldfinitebndu, xs, _params);
                ablasf.rcopyv(info.oldn, pslagbc, lagbc, _params);
                ablasf.rmergedivv(info.oldn, info.olds, lagbc, _params);
                ablasf.rcopyv(info.oldmlc, pslaglc, laglc, _params);
                ablasf.rmergedivv(info.oldmlc, info.newlcscales, laglc, _params);
                ablasf.rcopyv(info.oldmnlc, pslagnlc, lagnlc, _params);
            }
            else
            {
                alglib.ap.assert(info.kxx==0, "NLPPresolverUnpackSolution: 387330 failed");
                ablasf.rcopyv(info.oldn, info.fixedvals, xs, _params);
                ablasf.rscattercopyv(info.newn, psxs, xs, info.unpackxperm, _params);
                ablasf.rsetv(info.oldn, 0.0, nlrep, _params);
                ablasf.rscattercopyv(info.newn, psnlrep, nlrep, info.unpackxperm, _params);
                ablasf.rmergemulv(info.oldn, info.olds, xs, _params);
                ablasf.rmergemaxv(info.oldn, info.oldfinitebndl, xs, _params);
                ablasf.rmergeminv(info.oldn, info.oldfinitebndu, xs, _params);
                ablasf.rsetv(info.oldn, 0.0, lagbc, _params);
                ablasf.rsetv(info.oldmlc, 0.0, laglc, _params);
                ablasf.rsetv(info.oldmnlc, 0.0, lagnlc, _params);
            }
        }


        /*************************************************************************
        Unpack constraints violation report

          -- ALGLIB --
             Copyright 01.03.2026 by Bochkanov Sergey
        *************************************************************************/
        public static void nlppresolverunpackerrors(nlppresolveinfo info,
            double psrepbcerr,
            int psrepbcidx,
            double psreplcerr,
            int psreplcidx,
            double psrepnlcerr,
            int psrepnlcidx,
            double psrepsclerr,
            ref double repbcerr,
            ref int repbcidx,
            ref double replcerr,
            ref int replcidx,
            ref double repnlcerr,
            ref int repnlcidx,
            ref double repsclfeaserr,
            alglib.xparams _params)
        {
            repbcerr = 0;
            repbcidx = 0;
            replcerr = 0;
            replcidx = 0;
            repnlcerr = 0;
            repnlcidx = 0;
            repsclfeaserr = 0;

            alglib.ap.assert(info.kxx==0, "NLPPresolverUnpackErrors: 423330 failed");
            repbcidx = -1;
            replcidx = -1;
            repbcerr = psrepbcerr;
            if( psrepbcidx>=0 )
            {
                repbcidx = info.unpackxperm[psrepbcidx];
            }
            replcerr = psreplcerr;
            if( psreplcidx>=0 )
            {
                replcidx = info.newlcsrcidx[psreplcidx];
            }
            repnlcerr = psrepnlcerr;
            repnlcidx = psrepnlcidx;
            repsclfeaserr = psrepsclerr;
        }


        /*************************************************************************
        Returns true if both bounds are finite and the difference is less than Eps.

        Used to provide consistent way of checking for fixed vars across the unit.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static bool isfixed(double bndl,
            double bndu,
            double eps,
            alglib.xparams _params)
        {
            bool result = new bool();

            result = (math.isfinite(bndl) && math.isfinite(bndu)) && (double)(bndl)>=(double)(bndu-eps);
            return result;
        }


        /*************************************************************************
        Powerful presolver - actual implementation

          -- ALGLIB --
             Copyright 01.03.2026 by Bochkanov Sergey
        *************************************************************************/
        private static void dopowerfulpresolve(nlppresolveworkspace wrk,
            double eps,
            bool dotrace,
            alglib.xparams _params)
        {
            int n = 0;
            int mlc = 0;
            int i = 0;
            int presolverounds = 0;
            bool somethingchanged = new bool();
            int analyzealllc = 0;
            int nfreevars = 0;

            analyzealllc = -1;
            n = wrk.n;
            mlc = wrk.mlc;
            wrk.dbgemptycol = 0;
            wrk.dbgemptylc = 0;
            wrk.dbgnonbindingrows = 0;
            wrk.dbgfixed = 0;
            wrk.dbgsingletonrow = 0;
            wrk.dbgdoubletonrow = 0;
            wrk.dbgforcing = 0;
            wrk.dbgirrelevant = 0;
            wrk.dbgnobounds = 0;
            wrk.problemstatus = 0;
            ablasf.rsetallocv(n, 0.0, ref wrk.fixedvals, _params);
            ablasf.bsetallocv(n, false, ref wrk.isfixed, _params);
            ablasf.bsetallocv(mlc, false, ref wrk.isdroppedlc, _params);
            apstruct.nisinitemptyslow(n, wrk.setn, _params);
            apstruct.nisinitemptyslow(n, wrk.setn2, _params);
            apstruct.nisinitemptyslow(Math.Max(mlc, 1), wrk.setm, _params);
            presolverounds = 0;
            somethingchanged = true;
            while( somethingchanged )
            {
                somethingchanged = false;
                if( !fixvariables(wrk, eps, dotrace, ref somethingchanged, _params) )
                {
                    return;
                }
                if( !analyzelc(wrk, analyzealllc, eps, dotrace, ref somethingchanged, _params) )
                {
                    return;
                }
                presolverounds = presolverounds+1;
            }
            nfreevars = 0;
            for(i=0; i<=wrk.n-1; i++)
            {
                if( !wrk.isfixed[i] )
                {
                    nfreevars = nfreevars+1;
                }
            }
            if( nfreevars==0 )
            {
                wrk.problemstatus = 1;
                return;
            }
        }


        /*************************************************************************
        This function scans box constraints list and tries  to  fix  variables  by
        removing them from the A and AT matrices and by  recording  transformation
        in trfStack.

        If infeasibility is detected, returns False.

        INPUT PARAMETERS:
            Wrk         -   workplace
            Eps         -   tolerance to resolve slightly infeasible constraints
            DoTrace     -   whether tracing is needed or not
            SomethingChanged-flag variable
                            
        OUTPUT PARAMETERS:
            Wrk         -   updated by the function

        RESULT:
            if infeasibility is detected, returns False.
            True otherwise.

          -- ALGLIB --
             Copyright 01.03.2026 by Bochkanov Sergey
        *************************************************************************/
        private static bool fixvariables(nlppresolveworkspace wrk,
            double eps,
            bool dotrace,
            ref bool somethingchanged,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int k = 0;
            int ii = 0;
            double v = 0;
            double vfixed = 0;

            result = true;
            apstruct.nisclear(wrk.setn, _params);
            apstruct.nisclear(wrk.setm, _params);
            for(i=0; i<=wrk.n-1; i++)
            {
                if( !wrk.isfixed[i] && isfixed(wrk.bndl[i], wrk.bndu[i], eps, _params) )
                {
                    if( (double)(wrk.bndl[i])>(double)(wrk.bndu[i]+eps) )
                    {
                        if( dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> box constraints on variable {0,0:d} became infeasible during presolve, hence the initial problem is infeasible\n", i));
                        }
                        somethingchanged = true;
                        wrk.problemstatus = -3;
                        result = false;
                        return result;
                    }
                    vfixed = apserv.boundval(0.5*(wrk.bndl[i]+wrk.bndu[i]), wrk.bndl[i], wrk.bndu[i], _params);
                    somethingchanged = true;
                    wrk.dbgfixed = wrk.dbgfixed+1;
                    wrk.x0[i] = vfixed;
                    wrk.bndl[i] = vfixed;
                    wrk.bndu[i] = vfixed;
                    wrk.isfixed[i] = true;
                    wrk.fixedvals[i] = vfixed;
                    apstruct.nisaddelement(wrk.setn, i, _params);
                    if( wrk.mlc!=0 )
                    {
                        j0 = wrk.at.rowbegin[i];
                        j1 = wrk.at.rowend[i]-1;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            apstruct.nisaddelement(wrk.setm, wrk.at.idx[jj], _params);
                        }
                    }
                }
            }
            if( !somethingchanged )
            {
                return result;
            }
            if( wrk.mlc>0 )
            {
                for(k=0; k<=wrk.setn.nstored-1; k++)
                {
                    dyncrs.dyncrsclearrow(wrk.at, wrk.setn.items[k], _params);
                }
                for(ii=0; ii<=wrk.setm.nstored-1; ii++)
                {
                    i = wrk.setm.items[ii];
                    v = dyncrs.dyncrsdotremovesetfromrow(wrk.a, i, wrk.fixedvals, wrk.setn, _params);
                    if( math.isfinite(wrk.al[i]) )
                    {
                        wrk.al[i] = wrk.al[i]-v;
                    }
                    if( math.isfinite(wrk.au[i]) )
                    {
                        wrk.au[i] = wrk.au[i]-v;
                    }
                }
            }
            return result;
        }


        /*************************************************************************
        This function scans linear constraints list and tries to detect infeasible,
        forcing or redundant constraints.

        If infeasibility is detected, returns False.

        INPUT PARAMETERS:
            Wrk         -   workplace
            RowIdx      -   row to analyze; -1 to analyze all rows.
            Eps         -   tolerance to resolve slightly infeasible constraints
            DoTrace     -   whether tracing is needed or not
            SomethingChanged-flag variable
                            
        OUTPUT PARAMETERS:
            Wrk         -   updated by the function

        RESULT:
            if infeasibility is detected, returns False.
            True otherwise.

          -- ALGLIB --
             Copyright 01.03.2026 by Bochkanov Sergey
        *************************************************************************/
        private static bool analyzelc(nlppresolveworkspace wrk,
            int rowidx,
            double eps,
            bool dotrace,
            ref bool somethingchanged,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int i0 = 0;
            int i1 = 0;
            int j0 = 0;
            int j1 = 0;
            int jj = 0;
            int j = 0;
            double v = 0;
            double vl = 0;
            double vu = 0;
            double midpoint = 0;
            double wrkal = 0;
            double wrkau = 0;
            double prevbndl = 0;
            double prevbndu = 0;
            bool finitevl = new bool();
            bool finitevu = new bool();

            result = true;
            if( rowidx>=0 )
            {
                i0 = rowidx;
                i1 = rowidx;
            }
            else
            {
                i0 = 0;
                i1 = wrk.mlc-1;
            }
            apstruct.nisclear(wrk.setn, _params);
            apstruct.nisclear(wrk.setm, _params);
            for(i=i0; i<=i1; i++)
            {
                if( !wrk.isdroppedlc[i] )
                {
                    if( wrk.a.rowbegin[i]==wrk.a.rowend[i] )
                    {
                        if( (math.isfinite(wrk.al[i]) && (double)(wrk.al[i])>(double)(eps)) || (math.isfinite(wrk.au[i]) && (double)(wrk.au[i])<(double)(-eps)) )
                        {
                            if( dotrace )
                            {
                                alglib.ap.trace(System.String.Format("> the linear constraints are infeasible (row {0,0:d} is empty, initially or due to reductions, updated constraint range does not include zero)\n", i));
                            }
                            wrk.problemstatus = -3;
                            somethingchanged = true;
                            result = false;
                            return result;
                        }
                        wrk.isdroppedlc[i] = true;
                        somethingchanged = true;
                        wrk.dbgemptylc = wrk.dbgemptylc+1;
                        continue;
                    }
                    if( Double.IsNegativeInfinity(wrk.al[i]) && Double.IsPositiveInfinity(wrk.au[i]) )
                    {
                        apstruct.nisaddelement(wrk.setm, i, _params);
                        for(jj=wrk.a.rowbegin[i]; jj<=wrk.a.rowend[i]-1; jj++)
                        {
                            apstruct.nisaddelement(wrk.setn, wrk.a.idx[jj], _params);
                        }
                        wrk.isdroppedlc[i] = true;
                        somethingchanged = true;
                        wrk.dbgnobounds = wrk.dbgnobounds+1;
                        continue;
                    }
                    if( wrk.a.rowbegin[i]+1==wrk.a.rowend[i] && Math.Abs(wrk.a.vals[wrk.a.rowbegin[i]])>smlcoeff )
                    {
                        j = wrk.a.idx[wrk.a.rowbegin[i]];
                        v = wrk.a.vals[wrk.a.rowbegin[i]];
                        alglib.ap.assert(!wrk.isdroppedlc[i] && !wrk.isfixed[j], "NLPPRESOLVER: 554047 failed");
                        wrkal = wrk.al[i];
                        wrkau = wrk.au[i];
                        if( (double)(v)<(double)(0) )
                        {
                            apserv.swapr(ref wrkal, ref wrkau, _params);
                            wrkal = -wrkal;
                            wrkau = -wrkau;
                            v = -v;
                        }
                        wrkal = wrkal/v;
                        wrkau = wrkau/v;
                        prevbndl = wrk.bndl[j];
                        prevbndu = wrk.bndu[j];
                        if( (double)(prevbndl)>(double)(prevbndu+eps) )
                        {
                            if( dotrace )
                            {
                                alglib.ap.trace(System.String.Format("> the problem is infeasible (box constraint for variable {0,0:d})\n", j));
                            }
                            wrk.problemstatus = -3;
                            somethingchanged = true;
                            result = false;
                            return result;
                        }
                        if( (double)(wrkal)>(double)(prevbndu+eps) || (double)(wrkau)<(double)(prevbndl-eps) )
                        {
                            if( dotrace )
                            {
                                alglib.ap.trace(System.String.Format("> the problem is infeasible (singleton row {0,0:d} is incompatible with box constraints for variable {1,0:d})\n", i, j));
                            }
                            wrk.problemstatus = -3;
                            somethingchanged = true;
                            result = false;
                            return result;
                        }
                        if( math.isfinite(wrkal) && (double)(wrkal)>(double)(prevbndl) )
                        {
                            wrk.bndl[j] = wrkal;
                        }
                        if( math.isfinite(wrkau) && (double)(wrkau)<(double)(prevbndu) )
                        {
                            wrk.bndu[j] = wrkau;
                        }
                        if( (double)(wrk.bndu[j])<(double)(wrk.bndl[j]) )
                        {
                            midpoint = 0.5*(wrk.bndu[j]+wrk.bndl[j]);
                            wrk.bndl[j] = midpoint;
                            wrk.bndu[j] = midpoint;
                        }
                        apstruct.nisaddelement(wrk.setm, i, _params);
                        apstruct.nisaddelement(wrk.setn, j, _params);
                        wrk.isdroppedlc[i] = true;
                        somethingchanged = true;
                        wrk.dbgsingletonrow = wrk.dbgsingletonrow+1;
                        continue;
                    }
                    j0 = wrk.a.rowbegin[i];
                    j1 = wrk.a.rowend[i]-1;
                    alglib.ap.assert(j0<=j1, "NLPPRESOLVER: 550122 failed");
                    vl = 0.0;
                    vu = 0.0;
                    finitevl = true;
                    finitevu = true;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = wrk.a.idx[jj];
                        v = wrk.a.vals[jj];
                        if( finitevl )
                        {
                            if( v>0.0 )
                            {
                                finitevl = math.isfinite(wrk.bndl[j]);
                                if( finitevl )
                                {
                                    vl = vl+v*wrk.bndl[j];
                                }
                            }
                            if( v<0.0 )
                            {
                                finitevl = math.isfinite(wrk.bndu[j]);
                                if( finitevl )
                                {
                                    vl = vl+v*wrk.bndu[j];
                                }
                            }
                        }
                        if( finitevu )
                        {
                            if( v>0.0 )
                            {
                                finitevu = math.isfinite(wrk.bndu[j]);
                                if( finitevu )
                                {
                                    vu = vu+v*wrk.bndu[j];
                                }
                            }
                            if( v<0.0 )
                            {
                                finitevu = math.isfinite(wrk.bndl[j]);
                                if( finitevu )
                                {
                                    vu = vu+v*wrk.bndl[j];
                                }
                            }
                        }
                    }
                    if( (math.isfinite(wrk.al[i]) && finitevu) && vu<wrk.al[i]-eps )
                    {
                        if( dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> the linear constraints are infeasible (row {0,0:d} has implied upper bound less than its lower bound)\n", i));
                        }
                        wrk.problemstatus = -3;
                        somethingchanged = true;
                        result = false;
                        return result;
                    }
                    if( (math.isfinite(wrk.au[i]) && finitevl) && vl>wrk.au[i]+eps )
                    {
                        if( dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> the linear constraints are infeasible (row {0,0:d} has implied lower bound greater than its upper bound)\n", i));
                        }
                        wrk.problemstatus = -3;
                        somethingchanged = true;
                        result = false;
                        return result;
                    }
                    if( (math.isfinite(wrk.al[i]) && finitevu) && vu<wrk.al[i]+eps )
                    {
                        apstruct.nisaddelement(wrk.setm, i, _params);
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = wrk.a.idx[jj];
                            v = wrk.a.vals[jj];
                            if( v>0.0 )
                            {
                                wrk.bndl[j] = wrk.bndu[j];
                            }
                            if( v<0.0 )
                            {
                                wrk.bndu[j] = wrk.bndl[j];
                            }
                            apstruct.nisaddelement(wrk.setn, j, _params);
                        }
                        wrk.dbgforcing = wrk.dbgforcing+1;
                        wrk.isdroppedlc[i] = true;
                        somethingchanged = true;
                        continue;
                    }
                    if( (math.isfinite(wrk.au[i]) && finitevl) && vl>wrk.au[i]-eps )
                    {
                        apstruct.nisaddelement(wrk.setm, i, _params);
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = wrk.a.idx[jj];
                            v = wrk.a.vals[jj];
                            if( v>0.0 )
                            {
                                wrk.bndu[j] = wrk.bndl[j];
                            }
                            if( v<0.0 )
                            {
                                wrk.bndl[j] = wrk.bndu[j];
                            }
                            apstruct.nisaddelement(wrk.setn, j, _params);
                        }
                        wrk.dbgforcing = wrk.dbgforcing+1;
                        wrk.isdroppedlc[i] = true;
                        somethingchanged = true;
                        continue;
                    }
                    if( (!math.isfinite(wrk.al[i]) || (finitevl && vl>wrk.al[i]-eps)) && (!math.isfinite(wrk.au[i]) || (finitevu && vu<wrk.au[i]+eps)) )
                    {
                        apstruct.nisaddelement(wrk.setm, i, _params);
                        for(jj=j0; jj<=j1; jj++)
                        {
                            apstruct.nisaddelement(wrk.setn, wrk.a.idx[jj], _params);
                        }
                        wrk.dbgirrelevant = wrk.dbgirrelevant+1;
                        wrk.isdroppedlc[i] = true;
                        somethingchanged = true;
                        continue;
                    }
                }
            }
            for(jj=0; jj<=wrk.setm.nstored-1; jj++)
            {
                dyncrs.dyncrsclearrow(wrk.a, wrk.setm.items[jj], _params);
            }
            for(jj=0; jj<=wrk.setn.nstored-1; jj++)
            {
                dyncrs.dyncrsremovesetfromrow(wrk.at, wrk.setn.items[jj], wrk.setm, _params);
            }
            return result;
        }


        /*************************************************************************
        Convert dense Jacobian (packed into a vector) to a sparse  matrix  without
        checks for NAN/INF performed by the similar function from the SPARSE subpackage.

        Additionally computes objective/constraint scales - after applying variable
        scales but prior to fixing vars.

        Special version for variable fixing, assuming that PackPerm[] does not reorder
        non-fixed variables.

        Correctly computes FS when NewN=0
        *************************************************************************/
        private static void crsfromdense2dwithfixandscale(double[,] a,
            int oldm,
            int oldn,
            bool[] fixedvars,
            double[] olds,
            int[] packperm,
            int newn,
            sparse.sparsematrix s,
            double[] fs,
            ref double[] tmp0,
            ref double[] tmp1,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            int nnz = 0;
            int offs = 0;
            double va = 0;
            double vs = 0;
            double sa = 0;
            double rowscale = 0;

            alglib.ap.assert(alglib.ap.len(fs)>=oldm, "CRSFromDense2DWithFixAndScale: 811104 failed");
            nnz = 0;
            for(i=0; i<=oldm-1; i++)
            {
                for(j=0; j<=oldn-1; j++)
                {
                    if( !fixedvars[j] && a[i,j]!=0.0 )
                    {
                        nnz = nnz+1;
                    }
                }
            }
            s.matrixtype = 1;
            s.ninitialized = nnz;
            s.m = oldm;
            s.n = newn;
            ablasf.iallocv(oldm+1, ref s.ridx, _params);
            ablasf.iallocv(nnz, ref s.idx, _params);
            ablasf.rallocv(nnz, ref s.vals, _params);
            s.ridx[0] = 0;
            offs = 0;
            for(i=0; i<=oldm-1; i++)
            {
                rowscale = 0.0;
                for(j=0; j<=oldn-1; j++)
                {
                    va = a[i,j];
                    if( va!=0.0 )
                    {
                        vs = olds[j];
                        sa = vs*va;
                        rowscale = rowscale+sa*sa;
                        if( !fixedvars[j] )
                        {
                            s.idx[offs] = packperm[j];
                            s.vals[offs] = sa;
                            offs = offs+1;
                        }
                    }
                }
                if( math.isfinite(rowscale) )
                {
                    rowscale = Math.Sqrt(rowscale);
                    if( i==0 )
                    {
                        k = 0;
                        for(j=0; j<=oldn-1; j++)
                        {
                            va = a[i,j];
                            if( va!=0.0 )
                            {
                                vs = olds[j];
                                sa = vs*va;
                                ablasf.rgrowappendv(k+1, ref tmp0, Math.Abs(sa), _params);
                                k = k+1;
                            }
                        }
                        if( k>0 )
                        {
                            tsort.tagsortfast(ref tmp0, ref tmp1, k, _params);
                            rowscale = Math.Min(rowscale, Math.Max(f0scalemedianlimit*tmp0[k/2], 1));
                        }
                    }
                }
                s.ridx[i+1] = offs;
                fs[i] = rowscale;
            }
            alglib.ap.assert(offs==nnz, "CRSFromDense2DWithFixAndScale: integrity check 6447 failed");
            if( s.n>0 && s.m>0 )
            {
                sparse.sparseinitduidx(s, _params);
            }
        }


