            ablasf.iallocv(oldm+1, ref s.ridx, _params);
            ablasf.iallocv(nnz, ref s.idx, _params);
            ablasf.rallocv(nnz, ref s.vals, _params);
            s.ridx[0] = 0;
            offs = 0;
            for(i=0; i<=oldm-1; i++)
            {
                rowscale = 0.0;
                for(j=0; j<=oldn-1; j++)
                {
                    va = a[i*oldn+j];
                    if( va!=0.0 )
                    {
                        vs = olds[j];
                        sa = vs*va;
                        rowscale = rowscale+sa*sa;
                        if( !fixedvars[j] )
                        {
                            s.idx[offs] = packperm[j];
                            s.vals[offs] = sa;
                            offs = offs+1;
                        }
                    }
                }
                if( math.isfinite(rowscale) )
                {
                    rowscale = Math.Sqrt(rowscale);
                    if( i==0 )
                    {
                        k = 0;
                        for(j=0; j<=oldn-1; j++)
                        {
                            va = a[i*oldn+j];
                            if( va!=0.0 )
                            {
                                vs = olds[j];
                                sa = vs*va;
                                ablasf.rgrowappendv(k+1, ref tmp0, Math.Abs(sa), _params);
                                k = k+1;
                            }
                        }
                        if( k>0 )
                        {
                            tsort.tagsortfast(ref tmp0, ref tmp1, k, _params);
                            rowscale = Math.Min(rowscale, Math.Max(f0scalemedianlimit*tmp0[k/2], 1));
                        }
                    }
                }
                s.ridx[i+1] = offs;
                fs[i] = rowscale;
            }
            alglib.ap.assert(offs==nnz, "CRSFromDenseVWithFixAndScale: integrity check 6447 failed");
            if( s.n>0 && s.m>0 )
            {
                sparse.sparseinitduidx(s, _params);
            }
        }


        /*************************************************************************
        Special version for variable fixing, assuming that PackPerm[] does not reorder
        non-fixed variables.

        Additionally computes objective/constraint scales - after applying variable
        scales but prior to fixing vars.

        Correctly computes FS when NewN=0
        *************************************************************************/
        private static void sparsecopycrstocrswithfixandscale(sparse.sparsematrix replysj,
            bool[] fixedvars,
            double[] olds,
            int[] packperm,
            int newn,
            sparse.sparsematrix s,
            double[] fs,
            ref double[] tmp0,
            ref double[] tmp1,
            alglib.xparams _params)
        {
            int i = 0;
            int j0 = 0;
            int j1 = 0;
            int jj = 0;
            int j = 0;
            int k = 0;
            int offs = 0;
            double va = 0;
            double vs = 0;
            double sa = 0;
            double rowscale = 0;

            alglib.ap.assert(alglib.ap.len(fs)>=replysj.m, "SparseCopyCRSToCRSWithFixAndScale: 811104 failed");
            s.matrixtype = 1;
            s.m = replysj.m;
            s.n = newn;
            ablasf.iallocv(s.m+1, ref s.ridx, _params);
            ablasf.iallocv(replysj.ridx[replysj.m], ref s.idx, _params);
            ablasf.rallocv(replysj.ridx[replysj.m], ref s.vals, _params);
            s.ridx[0] = 0;
            offs = 0;
            for(i=0; i<=s.m-1; i++)
            {
                rowscale = 0.0;
                j0 = replysj.ridx[i];
                j1 = replysj.ridx[i+1]-1;
                for(jj=j0; jj<=j1; jj++)
                {
                    j = replysj.idx[jj];
                    va = replysj.vals[jj];
                    if( va!=0.0 )
                    {
                        vs = olds[j];
                        sa = vs*va;
                        rowscale = rowscale+sa*sa;
                        if( !fixedvars[j] )
                        {
                            s.idx[offs] = packperm[j];
                            s.vals[offs] = sa;
                            offs = offs+1;
                        }
                    }
                }
                if( math.isfinite(rowscale) )
                {
                    rowscale = Math.Sqrt(rowscale);
                    if( i==0 )
                    {
                        k = 0;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = replysj.idx[jj];
                            va = replysj.vals[jj];
                            if( va!=0.0 )
                            {
                                vs = olds[j];
                                sa = vs*va;
                                ablasf.rgrowappendv(k+1, ref tmp0, Math.Abs(sa), _params);
                                k = k+1;
                            }
                        }
                        if( k>0 )
                        {
                            tsort.tagsortfast(ref tmp0, ref tmp1, k, _params);
                            rowscale = Math.Min(rowscale, Math.Max(f0scalemedianlimit*tmp0[k/2], 1));
                        }
                    }
                }
                s.ridx[i+1] = offs;
                fs[i] = rowscale;
            }
            s.ninitialized = offs;
            if( s.n>0 && s.m>0 )
            {
                sparse.sparseinitduidx(s, _params);
            }
        }


        /*************************************************************************
        Copy linear constraints with rescale and renormalization
        *************************************************************************/
        private static void copylcwithrescaleandrenorm(double[] s,
            int n,
            sparse.sparsematrix a,
            double[] al,
            double[] au,
            int[] lcsrcidx,
            int m,
            sparse.sparsematrix wrka,
            ref double[] wrkal,
            ref double[] wrkau,
            ref int[] wrklcsrcidx,
            ref double[] wrklcscales,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int offs = 0;
            double rescales = 0;
            double rescalea = 0;
            double vs = 0;
            double v = 0;

            if( m==0 )
            {
                return;
            }
            alglib.ap.assert(a.m==m && a.n==n, "NLPPRESOLVER: 877211 failed");
            ablasf.rallocv(m, ref wrkal, _params);
            ablasf.rallocv(m, ref wrkau, _params);
            ablasf.iallocv(m, ref wrklcsrcidx, _params);
            ablasf.rallocv(m, ref wrklcscales, _params);
            ablasf.iallocv(m+1, ref wrka.ridx, _params);
            wrka.matrixtype = 1;
            wrka.m = m;
            wrka.n = n;
            ablasf.iallocv(a.ridx[a.m], ref wrka.idx, _params);
            ablasf.rallocv(a.ridx[a.m], ref wrka.vals, _params);
            wrka.ridx[0] = 0;
            offs = 0;
            for(i=0; i<=m-1; i++)
            {
                wrkal[i] = al[i];
                wrkau[i] = au[i];
                wrklcsrcidx[i] = lcsrcidx[i];
                wrklcscales[i] = 1.0;
                j0 = a.ridx[i];
                j1 = a.ridx[i+1]-1;
                if( j1<j0 )
                {
                    wrka.ridx[i+1] = offs;
                    continue;
                }
                rescales = 0.0;
                for(jj=j0; jj<=j1; jj++)
                {
                    rescales = Math.Max(rescales, s[a.idx[jj]]);
                }
                if( rescales==0.0 )
                {
                    alglib.ap.assert(false, "NLPPRESOLVER: 905213 failed");
                }
                rescales = 1/Math.Min(rescales, 1.0);
                rescalea = 0.0;
                for(jj=j0; jj<=j1; jj++)
                {
                    v = rescales*s[a.idx[jj]]*a.vals[jj];
                    rescalea = rescalea+v*v;
                }
                rescalea = 1/Math.Max(Math.Sqrt(rescalea), 1.0);
                vs = rescales*rescalea;
                for(jj=j0; jj<=j1; jj++)
                {
                    j = a.idx[jj];
                    wrka.idx[offs] = j;
                    wrka.vals[offs] = vs*s[j]*a.vals[jj];
                    offs = offs+1;
                }
                if( math.isfinite(wrkal[i]) )
                {
                    wrkal[i] = vs*wrkal[i];
                }
                if( math.isfinite(wrkau[i]) )
                {
                    wrkau[i] = vs*wrkau[i];
                }
                wrklcscales[i] = 1/vs;
                wrka.ridx[i+1] = offs;
            }
            wrka.ninitialized = offs;
            if( wrka.n>0 && wrka.m>0 )
            {
                sparse.sparseinitduidx(wrka, _params);
            }
        }


