                        sparse.sparseinitduidx(state.aulsolverstate.sj, _params);
                    }
                    else
                    {
                        
                        //
                        // Copy sparse Jacobian and scale
                        //
                        sparse.sparsecopytocrsbuf(state.rcommv2.replysj, state.aulsolverstate.sj, _params);
                        sparse.sparsemultiplycolsby(state.aulsolverstate.sj, state.s, _params);
                    }
                    b = true;
                }
                if( state.solvertype==2 || state.solvertype==3 )
                {
                    
                    //
                    // SQP solver
                    //
                    if( state.protocolversion==2 )
                    {
                        state.sqpsolverstate.fi[0] = state.rcommv2.replyfi[0];
                        if( !densejac )
                        {
                            ablasf.rsetr(n, 0.0, state.sqpsolverstate.j, 0, _params);
                            j0 = state.rcommv2.replysj.ridx[0];
                            j1 = state.rcommv2.replysj.ridx[1]-1;
                            for(jj=j0; jj<=j1; jj++)
                            {
                                state.sqpsolverstate.j[0,state.rcommv2.replysj.idx[jj]] = state.rcommv2.replysj.vals[jj];
                            }
                        }
                        else
                        {
                            ablasf.rcopyvr(n, state.rcommv2.replydj, state.sqpsolverstate.j, 0, _params);
                        }
                        ablasf.rmergemulvr(n, state.s, state.sqpsolverstate.j, 0, _params);
                        for(i=0; i<=state.nlcnlec+state.nlcnlic-1; i++)
                        {
                            state.sqpsolverstate.fi[i+1] = state.rcommv2.replyfi[1+state.nlcidx[i]]*state.nlcmul[i]+state.nlcadd[i];
                            k = 1+state.nlcidx[i];
                            if( !densejac )
                            {
                                ablasf.rsetr(n, 0.0, state.sqpsolverstate.j, i+1, _params);
                                j0 = state.rcommv2.replysj.ridx[k];
                                j1 = state.rcommv2.replysj.ridx[k+1]-1;
                                for(jj=j0; jj<=j1; jj++)
                                {
                                    state.sqpsolverstate.j[i+1,state.rcommv2.replysj.idx[jj]] = state.rcommv2.replysj.vals[jj];
                                }
                            }
                            else
                            {
                                for(j=0; j<=n-1; j++)
                                {
                                    state.sqpsolverstate.j[i+1,j] = state.rcommv2.replydj[k*n+j];
                                }
                            }
                            ablasf.rmergemulvr(n, state.s, state.sqpsolverstate.j, i+1, _params);
                            ablasf.rmulr(n, state.nlcmul[i], state.sqpsolverstate.j, i+1, _params);
                        }
                    }
                    else
                    {
                        alglib.ap.assert(state.protocolversion==1, "MINNLC: integrity check 2222 failed");
                        state.sqpsolverstate.fi[0] = state.fi[0];
                        ablasf.rcopyrr(n, state.j, 0, state.sqpsolverstate.j, 0, _params);
                        ablasf.rmergemulvr(n, state.s, state.sqpsolverstate.j, 0, _params);
                        for(i=0; i<=state.nlcnlec+state.nlcnlic-1; i++)
                        {
                            state.sqpsolverstate.fi[i+1] = state.fi[1+state.nlcidx[i]]*state.nlcmul[i]+state.nlcadd[i];
                            ablasf.rcopyrr(n, state.j, 1+state.nlcidx[i], state.sqpsolverstate.j, i+1, _params);
                            ablasf.rmergemulvr(n, state.s, state.sqpsolverstate.j, i+1, _params);
                            ablasf.rmulr(n, state.nlcmul[i], state.sqpsolverstate.j, i+1, _params);
                        }
                    }
                    b = true;
                }
                if( state.solvertype==4 || state.solvertype==5 )
                {
                    
                    //
                    // FSQP solver
                    //
                    if( state.protocolversion==2 )
                    {
                        ablasf.rcopyv(nnlc+1, state.rcommv2.replyfi, state.fsqpsolverstate.fi, _params);
                        if( densejac )
                        {
                            crsfromdensev(state.rcommv2.replydj, state.nnlc+1, n, state.fsqpsolverstate.sj, _params);
                        }
                        else
                        {
                            sparse.sparsecopytocrsbuf(state.rcommv2.replysj, state.fsqpsolverstate.sj, _params);
                        }
                        sparse.sparsemultiplycolsby(state.fsqpsolverstate.sj, state.s, _params);
                    }
                    else
                    {
                        alglib.ap.assert(state.protocolversion==1, "MINNLC: integrity check 2222 failed");
                        alglib.ap.assert(densejac, "MINNLC: integrity check 2223 failed");
                        ablasf.rcopyv(nnlc+1, state.fi, state.fsqpsolverstate.fi, _params);
                        crsfromdense(state.j, state.nnlc+1, n, state.fsqpsolverstate.sj, _params);
                        sparse.sparsemultiplycolsby(state.fsqpsolverstate.sj, state.s, _params);
                    }
                    b = true;
                }
                if( state.solvertype==9 || state.solvertype==10 )
                {
                    
                    //
                    // NLPIPM solver
                    //
                    if( state.protocolversion==2 )
                    {
                        nlppresolve.nlppresolverpackreplytosparse(state.presolver, state.rcommv2.replyfi, state.rcommv2.replydj, state.rcommv2.replysj, densejac, state.gipm3solver.rawreplyfi, state.gipm3solver.rawreplysj, state.gipm3solver.rawreplyfs, _params);
                    }
                    else
                    {
                        alglib.ap.assert(state.protocolversion==1, "MINNLC: integrity check 2222 failed");
                        alglib.ap.assert(densejac, "MINNLC: integrity check 2223 failed");
                        nlppresolve.nlppresolverpackreplytosparsev1(state.presolver, state.fi, state.j, state.gipm3solver.rawreplyfi, state.gipm3solver.rawreplysj, state.gipm3solver.rawreplyfs, _params);
                    }
                    b = true;
                }
            }
            if( originalrequest==4 )
            {
                if( state.solvertype==6 )
                {
                    
                    //
                    // ORBIT solver
                    //
                    ablasf.rcopyv((nnlc+1)*originalquerysize, state.rcommv2.replyfi, state.orbitsolver.replyfi, _params);
                    b = true;
                }
            }
            alglib.ap.assert(b, "MINNLC: integrity check 0038 failed");
            goto lbl_51;
        lbl_52:
            
            //
            // Results phase
            //
            b = false;
            if( state.solvertype==0 )
            {
                
                //
                // AUL results
                //
                state.repterminationtype = state.aulsolverstate.repterminationtype;
                state.repouteriterationscount = 1;
                state.repinneriterationscount = state.aulsolverstate.repiterationscount;
                state.repbcerr = state.aulsolverstate.repbcerr;
                state.repbcidx = state.aulsolverstate.repbcidx;
                state.replcerr = state.aulsolverstate.replcerr;
                state.replcidx = state.aulsolverstate.replcidx;
                state.repnlcerr = state.aulsolverstate.repnlcerr;
                state.repnlcidx = state.aulsolverstate.repnlcidx;
                state.repsclfeaserr = apserv.rmaxabs3(state.repbcerr, state.replcerr, state.repnlcerr, _params);
                unscale(state, state.aulsolverstate.xtruebest.x, state.aulsolverstate.scaledbndl, state.aulsolverstate.scaledbndu, state.xc, _params);
                b = true;
            }
            if( state.solvertype==2 || state.solvertype==3 )
            {
                state.repterminationtype = state.sqpsolverstate.repterminationtype;
                state.repouteriterationscount = state.sqpsolverstate.repiterationscount;
                state.repinneriterationscount = state.sqpsolverstate.repiterationscount;
                state.repbcerr = state.sqpsolverstate.repbcerr;
                state.repbcidx = state.sqpsolverstate.repbcidx;
                state.replcerr = state.sqpsolverstate.replcerr;
                state.replcidx = state.sqpsolverstate.replcidx;
                state.repnlcerr = state.sqpsolverstate.repnlcerr;
                state.repnlcidx = state.sqpsolverstate.repnlcidx;
                state.repsclfeaserr = apserv.rmaxabs3(state.repbcerr, state.replcerr, state.repnlcerr, _params);
                unscale(state, state.sqpsolverstate.stepk.x, state.sqpsolverstate.scaledbndl, state.sqpsolverstate.scaledbndu, state.xc, _params);
                b = true;
            }
            if( state.solvertype==4 || state.solvertype==5 )
            {
                state.repterminationtype = state.fsqpsolverstate.repterminationtype;
                state.repouteriterationscount = state.fsqpsolverstate.repiterationscount;
                state.repinneriterationscount = state.fsqpsolverstate.repiterationscount;
                state.repbcerr = state.fsqpsolverstate.repbcerr;
                state.repbcidx = state.fsqpsolverstate.repbcidx;
                state.replcerr = state.fsqpsolverstate.replcerr;
                state.replcidx = state.fsqpsolverstate.replcidx;
                state.repnlcerr = state.fsqpsolverstate.repnlcerr;
                state.repnlcidx = state.fsqpsolverstate.repnlcidx;
                state.repsclfeaserr = state.fsqpsolverstate.repsclerr;
                unscale(state, state.fsqpsolverstate.stepk.x, state.fsqpsolverstate.scaledbndl, state.fsqpsolverstate.scaledbndu, state.xc, _params);
                ablasf.rcopyv(state.n, state.fsqpsolverstate.replagbc, state.replagbc, _params);
                ablasf.rcopyv(state.n, state.fsqpsolverstate.replagbc, state.replagbcnz, _params);
                for(i=0; i<=state.n-1; i++)
                {
                    if( (state.hasbndl[i] && state.hasbndu[i]) && state.bndl[i]==state.bndu[i] )
                    {
                        state.replagbc[i] = 0.0;
                        if( state.diffstep!=0 )
                        {
                            state.replagbcnz[i] = 0.0;
                        }
                    }
                }
                for(i=0; i<=state.xlc.nsparse+state.xlc.ndense-1; i++)
                {
                    state.replaglc[state.xlc.lcsrcidx[i]] = state.replaglc[state.xlc.lcsrcidx[i]]+state.fsqpsolverstate.replaglc[i];
                }
                for(i=0; i<=nnlc-1; i++)
                {
                    state.replagnlc[i] = state.fsqpsolverstate.replagnlc[i];
                }
                b = true;
            }
            if( state.solvertype==6 )
            {
                state.repterminationtype = state.orbitsolver.repterminationtype;
                state.repouteriterationscount = state.orbitsolver.repiterationscount;
                state.repinneriterationscount = state.orbitsolver.repiterationscount;
                state.repbcerr = 0.0;
                state.repbcidx = -1;
                state.replcerr = 0.0;
                state.replcidx = -1;
                unscalebatch(state, state.orbitsolver.xk, 1, state.idxraw2red, state.nreduced, state.orbitsolver.scaledbndl, state.orbitsolver.scaledbndu, state.xc, _params);
                if( state.xlc.nsparse+state.xlc.ndense>0 )
                {
                    optserv.xlcconverttosparse(state.xlc, _params);
                    optserv.checklc2violation(state.xlc.effsparsea, state.xlc.effal, state.xlc.effau, state.xlc.lcsrcidx, state.xlc.nsparse+state.xlc.ndense, state.xc, ref state.replcerr, ref state.replcidx, _params);
                }
                optserv.checknlc2violation(state.orbitsolver.fkvec, state.nl, state.nu, nnlc, ref state.repnlcerr, ref state.repnlcidx, _params);
                state.repsclfeaserr = apserv.rmaxabs3(state.repbcerr, state.replcerr, state.repnlcerr, _params);
                ablasf.rsetv(state.n, 0.0, state.replagbc, _params);
                ablasf.rsetv(state.n, 0.0, state.replagbcnz, _params);
                ablasf.rsetv(state.xlc.nsparse+state.xlc.ndense, 0.0, state.replaglc, _params);
                ablasf.rsetv(nnlc, 0.0, state.replagnlc, _params);
                b = true;
            }
            if( state.solvertype==9 || state.solvertype==10 )
            {
                state.repterminationtype = state.gipm3solver.repterminationtype;
                state.repouteriterationscount = state.gipm3solver.repiterationscount;
                state.repinneriterationscount = state.gipm3solver.repiterationscount;
                state.repearlyerrorestimate = state.gipm3solver.repearlyerrorestimate;
                ablasf.rallocv(n, ref state.tmp0, _params);
                ablasf.rallocv(state.xlc.nsparse+state.xlc.ndense, ref state.tmp1, _params);
                ablasf.rallocv(nnlc, ref state.tmp2, _params);
                nlppresolve.nlppresolverunpacksolution(state.presolver, state.gipm3solver.xs, state.gipm3solver.repnonlinearityreport, state.gipm3solver.replagbc, state.gipm3solver.replaglc, state.gipm3solver.replagnlc, state.xc, state.repnonlinearityreport, state.tmp0, state.tmp1, state.tmp2, _params);
                nlppresolve.nlppresolverunpackerrors(state.presolver, state.gipm3solver.repbcerr, state.gipm3solver.repbcidx, state.gipm3solver.replcerr, state.gipm3solver.replcidx, state.gipm3solver.repnlcerr, state.gipm3solver.repnlcidx, state.gipm3solver.repsclerr, ref state.repbcerr, ref state.repbcidx, ref state.replcerr, ref state.replcidx, ref state.repnlcerr, ref state.repnlcidx, ref state.repsclfeaserr, _params);
                ablasf.rcopyv(state.n, state.tmp0, state.replagbc, _params);
                ablasf.rcopyv(state.n, state.tmp0, state.replagbcnz, _params);
                for(i=0; i<=state.n-1; i++)
                {
                    if( (state.hasbndl[i] && state.hasbndu[i]) && state.bndl[i]==state.bndu[i] )
                    {
                        state.replagbc[i] = 0.0;
                        if( state.diffstep!=0 )
                        {
                            state.replagbcnz[i] = 0.0;
                        }
                    }
                }
                for(i=0; i<=state.xlc.nsparse+state.xlc.ndense-1; i++)
                {
                    state.replaglc[state.xlc.lcsrcidx[i]] = state.replaglc[state.xlc.lcsrcidx[i]]+state.tmp1[i];
                }
                for(i=0; i<=nnlc-1; i++)
                {
                    state.replagnlc[i] = state.tmp2[i];
                }
                b = true;
            }
            alglib.ap.assert(b, "MINNLC: integrity check 2219 failed");
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rcommv2.ia[0] = i;
            state.rcommv2.ia[1] = j;
            state.rcommv2.ia[2] = k;
            state.rcommv2.ia[3] = j0;
            state.rcommv2.ia[4] = j1;
            state.rcommv2.ia[5] = jj;
            state.rcommv2.ia[6] = n;
            state.rcommv2.ia[7] = nnlc;
            state.rcommv2.ia[8] = offs;
            state.rcommv2.ia[9] = originalrequest;
            state.rcommv2.ia[10] = originalquerysize;
            state.rcommv2.ba[0] = b;
            state.rcommv2.ba[1] = dotrace;
            state.rcommv2.ba[2] = densejac;
            state.rcommv2.ra[0] = vleft;
            state.rcommv2.ra[1] = vright;
            state.rcommv2.ra[2] = v;
            return result;
        }


        /*************************************************************************
        This  function  activates/deactivates verification  of  the  user-supplied
        analytic gradient/Jacobian.

        Upon  activation  of  this  option  OptGuard  integrity  checker  performs
        numerical differentiation of your target  function  (constraints)  at  the
        initial point (note: future versions may also perform check  at  the final
        point) and compares numerical gradient/Jacobian with analytic one provided
        by you.

        If difference is too large, an error flag is set and optimization  session
        continues. After optimization session is over, you can retrieve the report
        which stores both gradients/Jacobians, and specific components highlighted
        as suspicious by the OptGuard.

        The primary OptGuard report can be retrieved with minnlcoptguardresults().

        IMPORTANT: gradient check is a high-overhead option which  will  cost  you
                   about 3*N additional function evaluations. In many cases it may
                   cost as much as the rest of the optimization session.
                   
                   YOU SHOULD NOT USE IT IN THE PRODUCTION CODE UNLESS YOU WANT TO
                   CHECK DERIVATIVES PROVIDED BY SOME THIRD PARTY.

        NOTE: unlike previous incarnation of the gradient checking code,  OptGuard
              does NOT interrupt optimization even if it discovers bad gradient.
              
        INPUT PARAMETERS:
            State       -   structure used to store algorithm state
            TestStep    -   verification step used for numerical differentiation:
                            * TestStep=0 turns verification off
                            * TestStep>0 activates verification
                            You should carefully choose TestStep. Value  which  is
                            too large (so large that  function  behavior  is  non-
                            cubic at this scale) will lead  to  false  alarms. Too
                            short step will result in rounding  errors  dominating
                            numerical derivative.
                            
                            You may use different step for different parameters by
                            means of setting scale with minnlcsetscale().

        === EXPLANATION ==========================================================                    

        In order to verify gradient algorithm performs following steps:
          * two trial steps are made to X[i]-TestStep*S[i] and X[i]+TestStep*S[i],
            where X[i] is i-th component of the initial point and S[i] is a  scale
            of i-th parameter
          * F(X) is evaluated at these trial points
          * we perform one more evaluation in the middle point of the interval
          * we  build  cubic  model using function values and derivatives at trial
            points and we compare its prediction with actual value in  the  middle
            point

          -- ALGLIB --
             Copyright 15.06.2014 by Bochkanov Sergey
        *************************************************************************/
        public static void minnlcoptguardgradient(minnlcstate state,
            double teststep,
            alglib.xparams _params)
        {
            alglib.ap.assert(math.isfinite(teststep), "MinNLCOptGuardGradient: TestStep contains NaN or INF");
            alglib.ap.assert((double)(teststep)>=(double)(0), "MinNLCOptGuardGradient: invalid argument TestStep(TestStep<0)");
            state.teststep = teststep;
        }


        /*************************************************************************
        This  function  activates/deactivates nonsmoothness monitoring  option  of
        the  OptGuard  integrity  checker. Smoothness  monitor  silently  observes
        solution process and tries to detect ill-posed problems, i.e. ones with:
        a) discontinuous target function (non-C0) and/or constraints
        b) nonsmooth     target function (non-C1) and/or constraints

        Smoothness monitoring does NOT interrupt optimization  even if it suspects
        that your problem is nonsmooth. It just sets corresponding  flags  in  the
        OptGuard report which can be retrieved after optimization is over.

        Smoothness monitoring is a moderate overhead option which often adds  less
        than 1% to the optimizer running time. Thus, you can use it even for large
        scale problems.

        NOTE: OptGuard does  NOT  guarantee  that  it  will  always  detect  C0/C1
              continuity violations.
              
              First, minor errors are hard to  catch - say, a 0.0001 difference in
              the model values at two sides of the gap may be due to discontinuity
              of the model - or simply because the model has changed.
              
              Second, C1-violations  are  especially  difficult  to  detect  in  a
              noninvasive way. The optimizer usually  performs  very  short  steps
              near the nonsmoothness, and differentiation  usually   introduces  a
              lot of numerical noise.  It  is  hard  to  tell  whether  some  tiny
              discontinuity in the slope is due to real nonsmoothness or just  due
              to numerical noise alone.
              
              Our top priority was to avoid false positives, so in some rare cases
              minor errors may went unnoticed (however, in most cases they can  be
              spotted with restart from different initial point).

        INPUT PARAMETERS:
            state   -   algorithm state
            level   -   monitoring level:
                        * 0 - monitoring is disabled
                        * 1 - noninvasive low-overhead monitoring; function values
                              and/or gradients are recorded, but OptGuard does not
                              try to perform additional evaluations  in  order  to
                              get more information about suspicious locations.
                              This kind of monitoring does not work well with  SQP
                              because SQP solver needs just 1-2 function evaluations
                              per step, which is not enough for OptGuard  to  make
                              any conclusions.
          
        === EXPLANATION ==========================================================

        One major source of headache during optimization  is  the  possibility  of
        the coding errors in the target function/constraints (or their gradients).
        Such  errors   most   often   manifest   themselves  as  discontinuity  or
        nonsmoothness of the target/constraints.

        Another frequent situation is when you try to optimize something involving
        lots of min() and max() operations, i.e. nonsmooth target. Although not  a
        coding error, it is nonsmoothness anyway - and smooth  optimizers  usually
        stop right after encountering nonsmoothness, well before reaching solution.

        OptGuard integrity checker helps you to catch such situations: it monitors
        function values/gradients being passed  to  the  optimizer  and  tries  to
        errors. Upon discovering suspicious pair of points it  raises  appropriate
        flag (and allows you to continue optimization). When optimization is done,
        you can study OptGuard result.

          -- ALGLIB --
             Copyright 21.11.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void minnlcoptguardsmoothness(minnlcstate state,
            int level,
            alglib.xparams _params)
        {
            alglib.ap.assert(level==0 || level==1, "MinNLCOptGuardSmoothness: unexpected value of level parameter");
            state.smoothnessguardlevel = level;
        }


        /*************************************************************************
        Results of OptGuard integrity check, should be called  after  optimization
        session is over.

        === PRIMARY REPORT =======================================================

        OptGuard performs several checks which are intended to catch common errors
        in the implementation of nonlinear function/gradient:
        * incorrect analytic gradient
        * discontinuous (non-C0) target functions (constraints)
        * nonsmooth     (non-C1) target functions (constraints)

        Each of these checks is activated with appropriate function:
        * minnlcoptguardgradient() for gradient verification
        * minnlcoptguardsmoothness() for C0/C1 checks

        Following flags are set when these errors are suspected:
        * rep.badgradsuspected, and additionally:
          * rep.badgradfidx for specific function (Jacobian row) suspected
          * rep.badgradvidx for specific variable (Jacobian column) suspected
          * rep.badgradxbase, a point where gradient/Jacobian is tested
          * rep.badgraduser, user-provided gradient/Jacobian
          * rep.badgradnum, reference gradient/Jacobian obtained via numerical
            differentiation
        * rep.nonc0suspected, and additionally:
          * rep.nonc0fidx - an index of specific function violating C0 continuity
        * rep.nonc1suspected, and additionally
          * rep.nonc1fidx - an index of specific function violating C1 continuity
        Here function index 0 means  target function, index 1  or  higher  denotes
        nonlinear constraints.

        === ADDITIONAL REPORTS/LOGS ==============================================
            
        Several different tests are performed to catch C0/C1 errors, you can  find
        out specific test signaled error by looking to:
        * rep.nonc0test0positive, for non-C0 test #0
        * rep.nonc1test0positive, for non-C1 test #0
        * rep.nonc1test1positive, for non-C1 test #1

        Additional information (including line search logs)  can  be  obtained  by
        means of:
        * minnlcoptguardnonc1test0results()
        * minnlcoptguardnonc1test1results()
        which return detailed error reports, specific points where discontinuities
        were found, and so on.

        ==========================================================================
             
        INPUT PARAMETERS:
            state   -   algorithm state

        OUTPUT PARAMETERS:
            rep     -   generic OptGuard report;  more  detailed  reports  can  be
                        retrieved with other functions.

        NOTE: false negatives (nonsmooth problems are not identified as  nonsmooth
              ones) are possible although unlikely.
              
              The reason  is  that  you  need  to  make several evaluations around
              nonsmoothness  in  order  to  accumulate  enough  information  about
              function curvature. Say, if you start right from the nonsmooth point,
              optimizer simply won't get enough data to understand what  is  going
              wrong before it terminates due to abrupt changes in the  derivative.
              It is also  possible  that  "unlucky"  step  will  move  us  to  the
              termination too quickly.
              
              Our current approach is to have less than 0.1%  false  negatives  in
              our test examples  (measured  with  multiple  restarts  from  random
              points), and to have exactly 0% false positives.
           
          -- ALGLIB --
             Copyright 21.11.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void minnlcoptguardresults(minnlcstate state,
            optguardapi.optguardreport rep,
            alglib.xparams _params)
        {
            optserv.smoothnessmonitorexportreport(state.smonitor, rep, _params);
        }


        /*************************************************************************
        Detailed results of the OptGuard integrity check for nonsmoothness test #0

        Nonsmoothness (non-C1) test #0 studies  function  values  (not  gradient!)
        obtained during line searches and monitors  behavior  of  the  directional
        derivative estimate.

        This test is less powerful than test #1, but it does  not  depend  on  the
        gradient values and thus it is more robust against artifacts introduced by
        numerical differentiation.

        Two reports are returned:
        * a "strongest" one, corresponding  to  line   search  which  had  highest
          value of the nonsmoothness indicator
        * a "longest" one, corresponding to line search which  had  more  function
          evaluations, and thus is more detailed

        In both cases following fields are returned:

        * positive - is TRUE  when test flagged suspicious point;  FALSE  if  test
          did not notice anything (in the latter cases fields below are empty).
        * fidx - is an index of the function (0 for  target  function, 1 or higher
          for nonlinear constraints) which is suspected of being "non-C1"
        * x0[], d[] - arrays of length N which store initial point  and  direction
          for line search (d[] can be normalized, but does not have to)
        * stp[], f[] - arrays of length CNT which store step lengths and  function
          values at these points; f[i] is evaluated in x0+stp[i]*d.
        * stpidxa, stpidxb - we  suspect  that  function  violates  C1  continuity
          between steps #stpidxa and #stpidxb (usually we have  stpidxb=stpidxa+3,
          with  most  likely  position  of  the  violation  between  stpidxa+1 and
          stpidxa+2.
          
        ==========================================================================
        = SHORTLY SPEAKING: build a 2D plot of (stp,f) and look at it -  you  will
        =                   see where C1 continuity is violated.
        ==========================================================================
             
        INPUT PARAMETERS:
            state   -   algorithm state

        OUTPUT PARAMETERS:
            strrep  -   C1 test #0 "strong" report
            lngrep  -   C1 test #0 "long" report
            
          -- ALGLIB --
             Copyright 21.11.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void minnlcoptguardnonc1test0results(minnlcstate state,
            optguardapi.optguardnonc1test0report strrep,
            optguardapi.optguardnonc1test0report lngrep,
            alglib.xparams _params)
        {
            optguardapi.smoothnessmonitorexportc1test0report(state.smonitor.nonc1test0strrep, state.lastscaleused, strrep, _params);
            optguardapi.smoothnessmonitorexportc1test0report(state.smonitor.nonc1test0lngrep, state.lastscaleused, lngrep, _params);
        }


        /*************************************************************************
        Detailed results of the OptGuard integrity check for nonsmoothness test #1

        Nonsmoothness (non-C1)  test  #1  studies  individual  components  of  the
        gradient computed during line search.

        When precise analytic gradient is provided this test is more powerful than
        test #0  which  works  with  function  values  and  ignores  user-provided
        gradient.  However,  test  #0  becomes  more   powerful   when   numerical
        differentiation is employed (in such cases test #1 detects  higher  levels
        of numerical noise and becomes too conservative).

        This test also tells specific components of the gradient which violate  C1
        continuity, which makes it more informative than #0, which just tells that
        continuity is violated.

        Two reports are returned:
        * a "strongest" one, corresponding  to  line   search  which  had  highest
          value of the nonsmoothness indicator
        * a "longest" one, corresponding to line search which  had  more  function
          evaluations, and thus is more detailed

        In both cases following fields are returned:

        * positive - is TRUE  when test flagged suspicious point;  FALSE  if  test
          did not notice anything (in the latter cases fields below are empty).
        * fidx - is an index of the function (0 for  target  function, 1 or higher
          for nonlinear constraints) which is suspected of being "non-C1"
        * vidx - is an index of the variable in [0,N) with nonsmooth derivative
        * x0[], d[] - arrays of length N which store initial point  and  direction
          for line search (d[] can be normalized, but does not have to)
        * stp[], g[] - arrays of length CNT which store step lengths and  gradient
          values at these points; g[i] is evaluated in  x0+stp[i]*d  and  contains
          vidx-th component of the gradient.
        * stpidxa, stpidxb - we  suspect  that  function  violates  C1  continuity
          between steps #stpidxa and #stpidxb (usually we have  stpidxb=stpidxa+3,
          with  most  likely  position  of  the  violation  between  stpidxa+1 and
          stpidxa+2.
          
        ==========================================================================
        = SHORTLY SPEAKING: build a 2D plot of (stp,f) and look at it -  you  will
        =                   see where C1 continuity is violated.
        ==========================================================================
             
        INPUT PARAMETERS:
            state   -   algorithm state

        OUTPUT PARAMETERS:
            strrep  -   C1 test #1 "strong" report
            lngrep  -   C1 test #1 "long" report
            
          -- ALGLIB --
             Copyright 21.11.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void minnlcoptguardnonc1test1results(minnlcstate state,
            optguardapi.optguardnonc1test1report strrep,
            optguardapi.optguardnonc1test1report lngrep,
            alglib.xparams _params)
        {
            optguardapi.smoothnessmonitorexportc1test1report(state.smonitor.nonc1test1strrep, state.lastscaleused, strrep, _params);
            optguardapi.smoothnessmonitorexportc1test1report(state.smonitor.nonc1test1lngrep, state.lastscaleused, lngrep, _params);
        }


        /*************************************************************************
        MinNLC results:  the  solution  found,  completion  codes  and  additional
        information.

        If you activated OptGuard integrity checking functionality and want to get
        OptGuard report, it can be retrieved with:
        * minnlcoptguardresults() - for a primary report about (a) suspected C0/C1
          continuity violations and (b) errors in the analytic gradient.
        * minnlcoptguardnonc1test0results() - for C1 continuity violation test #0,
          detailed line search log
        * minnlcoptguardnonc1test1results() - for C1 continuity violation test #1,
          detailed line search log

        INPUT PARAMETERS:
            State   -   algorithm state

        OUTPUT PARAMETERS:
            X       -   array[0..N-1], solution
            Rep     -   optimization report, contains information about completion
                        code, constraint violation at the solution and so on.
                        
                        rep.f contains objective value at the solution.
                        
                        You   should   check   rep.terminationtype  in  order   to
                        distinguish successful termination from unsuccessful one:
                        
                        === FAILURE CODES ===
                        * -9    initial point violates hard constraints,  stopping
                                immediately 
                        * -8    internal  integrity control  detected  infinite or
                                NAN  values  in  function/gradient,  recovery  was
                                impossible. Abnormal termination signalled.
                        * -6    one of hard constraints has both  bounds  present;
                                this option is not supported.
                        * -4    the problem is likely  to  be unbounded; presently
                                only NLPIPM solver reports  this  code.   For  NLP
                                problems (not LP/QP) it is generally impossible to
                                provide  an  unboundedness  certificate,  so  only
                                heuristics  are  possible,  based on growth of |x|
                                and decrease of f compared to |f(x0)|. It  is  the
                                only failure code than returns something meaningful
                                in X.
                        * -3    box  constraints are infeasible.
                                Note: infeasibility of  non-box  constraints  does
                                      NOT trigger emergency completion;  you  have
                                      to examine rep.bcerr/rep.lcerr/rep.nlcerr to
                                      detect possibly inconsistent constraints.

                        When a failure code, different from -4, is  returned,  the
                        X is filled by NANs. When failure code is  equal  to -4, a
                        point where unboundedness suspicions  were  triggered,  is
                        returned.
                                      
                        === SUCCESS CODES ===
                        *  1   small objective decrease indicates convergence
                        *  2   scaled step is no more than EpsX.
                        *  5   MaxIts steps were taken.
                        *  7   stopping conditions are  too  stringent,  returning
                               the best point so far
                        *  8   user   requested    algorithm    termination    via
                               minnlcrequesttermination(), last accepted point  is
                               returned.
                               
                        === ADDITIONAL CODES ===
                        * +800      if   during  algorithm  execution  the  solver
                                    encountered NAN/INF values in  the  target  or
                                    constraints but managed to recover by reducing
                                    trust region radius, the  solver  returns  one
                                    of SUCCESS codes but adds +800 to the code.
                        
                        Some  solvers  (as  of ALGLIB 4.08, SQP and NLPIPM) return
                        Lagrange multipliers in rep.lagbc/lagbcnz,  laglc,  lagnlc
                        fields.
                        
                        More information about fields of this  structure  can  be
                        found in the comments on the minnlcreport datatype.
           
          -- ALGLIB --
             Copyright 18.01.2024 by Bochkanov Sergey
        *************************************************************************/
        public static void minnlcresults(minnlcstate state,
            ref double[] x,
            minnlcreport rep,
            alglib.xparams _params)
        {
            x = new double[0];

            minnlcresultsbuf(state, ref x, rep, _params);
        }


        /*************************************************************************
        NLC results

        Buffered implementation of MinNLCResults() which uses pre-allocated buffer
        to store X[]. If buffer size is  too  small,  it  resizes  buffer.  It  is
        intended to be used in the inner cycles of performance critical algorithms
        where array reallocation penalty is too large to be ignored.

          -- ALGLIB --
             Copyright 28.11.2010 by Bochkanov Sergey
        *************************************************************************/
        public static void minnlcresultsbuf(minnlcstate state,
            ref double[] x,
            minnlcreport rep,
            alglib.xparams _params)
        {
            rep.f = state.repf;
            rep.iterationscount = state.repinneriterationscount;
            rep.nfev = state.repnfev;
            rep.terminationtype = state.repterminationtype;
            rep.bcerr = state.repbcerr;
            rep.bcidx = state.repbcidx;
            rep.lcerr = state.replcerr;
            rep.lcidx = state.replcidx;
            rep.nlcerr = state.repnlcerr;
            rep.nlcidx = state.repnlcidx;
            rep.sclfeaserr = state.repsclfeaserr;
            rep.dbgphase0its = state.repdbgphase0its;
            if( state.repterminationtype>0 )
            {
                ablasf.rcopyallocv(state.n, state.replagbc, ref rep.lagbc, _params);
                ablasf.rcopyallocv(state.n, state.replagbcnz, ref rep.lagbcnz, _params);
                ablasf.rcopyallocv(state.xlc.ndense+state.xlc.nsparse, state.replaglc, ref rep.laglc, _params);
                ablasf.rcopyallocv(state.nnlc, state.replagnlc, ref rep.lagnlc, _params);
                ablasf.rcopyallocv(state.n, state.xc, ref x, _params);
            }
            else
            {
                ablasf.rsetallocv(state.n, 0.0, ref rep.lagbc, _params);
                ablasf.rsetallocv(state.n, 0.0, ref rep.lagbcnz, _params);
                ablasf.rsetallocv(state.xlc.nec+state.xlc.nic, 0.0, ref rep.laglc, _params);
                ablasf.rsetallocv(state.nnlc, 0.0, ref rep.lagnlc, _params);
                if( state.repterminationtype!=-4 )
                {
                    ablasf.rsetallocv(state.n, Double.NaN, ref x, _params);
                }
                else
                {
                    ablasf.rcopyallocv(state.n, state.xc, ref x, _params);
                }
            }
        }


        /*************************************************************************
        This subroutine submits request for termination of running  optimizer.  It
        should be called from user-supplied callback when user decides that it  is
        time to "smoothly" terminate optimization process.  As  result,  optimizer
        stops at point which was "current accepted" when termination  request  was
        submitted and returns error code 8 (successful termination).

        INPUT PARAMETERS:
            State   -   optimizer structure

        NOTE: after  request  for  termination  optimizer  may   perform   several
              additional calls to user-supplied callbacks. It does  NOT  guarantee
              to stop immediately - it just guarantees that these additional calls
              will be discarded later.

        NOTE: calling this function on optimizer which is NOT running will have no
              effect.
              
        NOTE: multiple calls to this function are possible. First call is counted,
              subsequent calls are silently ignored.

          -- ALGLIB --
             Copyright 08.10.2014 by Bochkanov Sergey
        *************************************************************************/
        public static void minnlcrequesttermination(minnlcstate state,
            alglib.xparams _params)
        {
            state.userterminationneeded = true;
        }


        /*************************************************************************
        This subroutine restarts algorithm from new point.
        All optimization parameters (including constraints) are left unchanged.

        This  function  allows  to  solve multiple  optimization  problems  (which
        must have  same number of dimensions) without object reallocation penalty.

        INPUT PARAMETERS:
            State   -   structure previously allocated with MinNLCCreate call.
            X       -   new starting point.

          -- ALGLIB --
             Copyright 28.11.2010 by Bochkanov Sergey
        *************************************************************************/
        public static void minnlcrestartfrom(minnlcstate state,
            double[] x,
            alglib.xparams _params)
        {
            int n = 0;
            int i_ = 0;

            n = state.n;
            
            //
            // First, check for errors in the inputs
            //
            alglib.ap.assert(alglib.ap.len(x)>=n, "MinNLCRestartFrom: Length(X)<N");
            alglib.ap.assert(apserv.isfinitevector(x, n, _params), "MinNLCRestartFrom: X contains infinite or NaN values!");
            
            //
            // Set XC
            //
            for(i_=0; i_<=n-1;i_++)
            {
                state.xstart[i_] = x[i_];
            }
            
            //
            // prepare RComm facilities
            //
            state.rcommv2.ia = new int[10+1];
            state.rcommv2.ba = new bool[2+1];
            state.rcommv2.ra = new double[2+1];
            state.rcommv2.stage = -1;
            state.rcommv2.clear_handler();
            clearrequestfields(state, _params);
        }


        /*************************************************************************
        This function sets the number additional iterations that can be  performed
        after reaching MaxIts limit, if the current  point  is  infeasible (scaled
        constraint violation is above CTol), but there was a feasible point in the
        optimization history.

        Up to AddIts iterations will be performed, with iterations being terminated
        immediately after reaching CTol level of error.

        Only FSQP solver respects this function.

        INPUT PARAMETERS:
            State           -   solver state
            AddIts          -   additional iterations, zero to turn off
            CTol            -   scaled constraint violation tolerance. Points with
                                violation below or at CTol are considered feasible
                                
                                Do not use zero value  because  it  is  likely  to
                                reject points with even a tiny violation of
                                constraints.

          -- ALGLIB --
             Copyright 05.03.2018 by Bochkanov Sergey
        *************************************************************************/
        public static void minnlcsetfsqpadditsforctol(minnlcstate state,
            int addits,
            double ctol,
            alglib.xparams _params)
        {
            state.fsqpadditsforctol = addits;
            state.fsqpctol = ctol;
        }


        /*************************************************************************
        Set V1 reverse communication protocol
        *************************************************************************/
        public static void minnlcsetprotocolv1(minnlcstate state,
            alglib.xparams _params)
        {
            state.protocolversion = 1;
            state.issuesparserequests = false;
            state.fi = new double[1+state.nnlc];
            state.j = new double[1+state.nnlc, state.n];
            state.rcommv2.ia = new int[10+1];
            state.rcommv2.ba = new bool[2+1];
            state.rcommv2.ra = new double[2+1];
            state.rcommv2.stage = -1;
            state.rcommv2.clear_handler();
        }


        /*************************************************************************
        Set V2 reverse communication protocol with dense requests
        *************************************************************************/
        public static void minnlcsetprotocolv2(minnlcstate state,
            alglib.xparams _params)
        {
            state.protocolversion = 2;
            state.issuesparserequests = false;
            state.rcommv2.ia = new int[10+1];
            state.rcommv2.ba = new bool[2+1];
            state.rcommv2.ra = new double[2+1];
            state.rcommv2.stage = -1;
            state.rcommv2.clear_handler();
            state.rcommv2.clear_handler();
        }


        /*************************************************************************
        Set V2 reverse communication protocol with sparse requests
        *************************************************************************/
        public static void minnlcsetprotocolv2s(minnlcstate state,
            alglib.xparams _params)
        {
            state.protocolversion = 2;
            state.issuesparserequests = true;
            state.rcommv2.ia = new int[10+1];
            state.rcommv2.ba = new bool[2+1];
            state.rcommv2.ra = new double[2+1];
            state.rcommv2.stage = -1;
            state.rcommv2.clear_handler();
            state.rcommv2.clear_handler();
        }


        /*************************************************************************
        Clears request fileds (to be sure that we don't forget to clear something)
        *************************************************************************/
        private static void clearrequestfields(minnlcstate state,
            alglib.xparams _params)
        {
            state.needfi = false;
            state.needfij = false;
            state.xupdated = false;
        }


        /*************************************************************************
        Internal initialization subroutine.
        Sets default NLC solver with default criteria.
        *************************************************************************/
        private static void minnlcinitinternal(int n,
            double[] x,
            double diffstep,
            minnlcstate state,
            alglib.xparams _params)
        {
            int i = 0;
            double[,] c = new double[0,0];
            int[] ct = new int[0];

            state.protocolversion = 1;
            state.issuesparserequests = false;
            
            //
            // Smoothness monitor, default init
            //
            state.teststep = 0;
            state.smoothnessguardlevel = 0;
            optserv.smoothnessmonitorinit(state.smonitor, state.s, 0, 0, false, _params);
            
            //
            // Initialize other params
            //
            optserv.critinitdefault(state.criteria, _params);
            state.n = n;
            state.diffstep = diffstep;
            state.userterminationneeded = false;
            state.bndl = new double[n];
            state.hasbndl = new bool[n];
            state.bndu = new double[n];
            state.hasbndu = new bool[n];
            state.s = new double[n];
            state.lastscaleused = new double[n];
            state.xstart = new double[n];
            state.xc = new double[n];
            state.x = new double[n];
            for(i=0; i<=n-1; i++)
            {
                state.bndl[i] = Double.NegativeInfinity;
                state.hasbndl[i] = false;
                state.bndu[i] = Double.PositiveInfinity;
                state.hasbndu[i] = false;
                state.s[i] = 1.0;
                state.lastscaleused[i] = 1.0;
                state.xstart[i] = x[i];
                state.xc[i] = x[i];
            }
            optserv.xlcinit(n, state.xlc, _params);
            minnlcsetnlc(state, 0, 0, _params);
            minnlcsetxrep(state, false, _params);
            minnlcsetalgosqp(state, _params);
            minnlcsetstpmax(state, 0.0, _params);
            minnlcsetnumdiff(state, 5, _params);
            minnlcrestartfrom(state, x, _params);
            state.primalbound = Double.PositiveInfinity;
            ablasf.bsetallocv(n, false, ref state.islinear, _params);
            state.eshasintmask = false;
            state.esdualbound = Double.NegativeInfinity;
            state.esprimbound = Double.PositiveInfinity;
            state.esminits = 0;
            state.estol = 1.0E-6;
            ablasf.bsetallocv(n, false, ref state.esintmask, _params);
            state.presolvermode = 0;
            state.dononlinearityreports = false;
            
            //
            // Default values of solver-specific params
            //
            state.fsqpadditsforctol = 0;
            state.fsqpctol = 0;
            state.qnmemlen = 0;
        }


        /*************************************************************************
        Unscales X (converts from scaled variables to original ones), paying special
        attention to box constraints (output is always feasible; active constraints
        are mapped to active ones).
        *************************************************************************/
        private static void unscale(minnlcstate state,
            double[] xs,
            double[] scaledbndl,
            double[] scaledbndu,
            double[] xu,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            n = state.n;
            for(i=0; i<=n-1; i++)
            {
                if( state.hasbndl[i] && xs[i]<=scaledbndl[i] )
                {
                    xu[i] = state.bndl[i];
                    continue;
                }
                if( state.hasbndu[i] && xs[i]>=scaledbndu[i] )
                {
                    xu[i] = state.bndu[i];
                    continue;
                }
                xu[i] = xs[i]*state.s[i];
                if( state.hasbndl[i] && xu[i]<state.bndl[i] )
                {
                    xu[i] = state.bndl[i];
                }
                if( state.hasbndu[i] && xu[i]>state.bndu[i] )
                {
                    xu[i] = state.bndu[i];
                }
            }
        }


        /*************************************************************************
        Convert dense Jacobian to a sparse  matrix  without
        checks for NAN/INF performed by the similar function from the SPARSE subpackage.
        *************************************************************************/
        private static void crsfromdense(double[,] a,
            int m,
            int n,
            sparse.sparsematrix s,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int nnz = 0;
            int offs = 0;

            alglib.ap.assert(m>0, "CreateCRSFromDenseBuf: M<=0");
            alglib.ap.assert(n>0, "CreateCRSFromDenseBuf: N<=0");
            alglib.ap.assert(alglib.ap.rows(a)>=m, "CreateCRSFromDenseBuf: rows(A)<M");
            alglib.ap.assert(alglib.ap.cols(a)>=n, "CreateCRSFromDenseBuf: cols(A)<N");
            nnz = 0;
            for(i=0; i<=m-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    if( a[i,j]!=0.0 )
                    {
                        nnz = nnz+1;
                    }
                }
            }
            s.matrixtype = 1;
            s.ninitialized = nnz;
            s.m = m;
            s.n = n;
            ablasf.iallocv(m+1, ref s.ridx, _params);
            ablasf.iallocv(nnz, ref s.idx, _params);
            ablasf.rallocv(nnz, ref s.vals, _params);
            s.ridx[0] = 0;
            offs = 0;
            for(i=0; i<=m-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    if( a[i,j]!=0.0 )
                    {
                        s.idx[offs] = j;
                        s.vals[offs] = a[i,j];
                        offs = offs+1;
                    }
                }
                s.ridx[i+1] = offs;
            }
            alglib.ap.assert(offs==nnz, "CreateCRSFromDenseBuf: integrity check 6447 failed");
            sparse.sparseinitduidx(s, _params);
        }


        /*************************************************************************
        Convert dense Jacobian (packed into a vector) to a sparse  matrix  without
        checks for NAN/INF performed by the similar function from the SPARSE subpackage.
        *************************************************************************/
        private static void crsfromdensev(double[] a,
            int m,
            int n,
            sparse.sparsematrix s,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int nnz = 0;
            int offs = 0;

            alglib.ap.assert(m>0, "CreateCRSFromDenseVBuf: M<=0");
            alglib.ap.assert(n>0, "CreateCRSFromDenseVBuf: N<=0");
            alglib.ap.assert(alglib.ap.len(a)>=m*n, "CreateCRSFromDenseVBuf: length(A)<M*N");
            nnz = 0;
            for(i=0; i<=m-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    if( a[i*n+j]!=0.0 )
                    {
                        nnz = nnz+1;
                    }
                }
            }
            s.matrixtype = 1;
            s.ninitialized = nnz;
            s.m = m;
            s.n = n;
            ablasf.iallocv(m+1, ref s.ridx, _params);
            ablasf.iallocv(nnz, ref s.idx, _params);
            ablasf.rallocv(nnz, ref s.vals, _params);
            s.ridx[0] = 0;
            offs = 0;
            for(i=0; i<=m-1; i++)
            {
                for(j=0; j<=n-1; j++)
                {
                    if( a[i*n+j]!=0.0 )
                    {
                        s.idx[offs] = j;
                        s.vals[offs] = a[i*n+j];
                        offs = offs+1;
                    }
                }
                s.ridx[i+1] = offs;
            }
            alglib.ap.assert(offs==nnz, "CreateCRSFromDenseVBuf: integrity check 6447 failed");
            sparse.sparseinitduidx(s, _params);
        }


        /*************************************************************************
        Unscales X (converts from scaled variables to original ones), paying special
        attention to box constraints (output is always feasible; active constraints
        are mapped to active ones).

        Can handle batch requests. Can handle problems with some variables being
        fixed and removed from consideration.

        Parameters:
            State           solver
            XS              array[NReduced*BatchSize] - variables after scaling and
                            removal of fixed vars
            idxRaw2Red      array[NRaw], maps original variable indexes to ones
                            after removal of fixed vars. Contains -1 for fixed vars.
            scaledBndL,
            ScaledBndU      array[NReduced], lower/upper bounds after removal of
                            the fixed vars
                            
        output:
            XU              array[NRaw*BatchSize], vars after unscaling and
                            substitution of the fixed vars
        *************************************************************************/
        private static void unscalebatch(minnlcstate state,
            double[] xs,
            int batchsize,
            int[] idxraw2red,
            int nreduced,
            double[] scaledbndl,
            double[] scaledbndu,
            double[] xu,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            int jr = 0;
            int nraw = 0;
            double vs = 0;

            nraw = state.n;
            if( nreduced==nraw )
            {
                
                //
                // No fixed vars, simple code
                //
                for(k=0; k<=batchsize-1; k++)
                {
                    for(j=0; j<=nraw-1; j++)
                    {
                        i = k*nraw+j;
                        vs = xs[i];
                        if( state.hasbndl[j] && vs<=scaledbndl[j] )
                        {
                            xu[i] = state.bndl[j];
                            continue;
                        }
                        if( state.hasbndu[j] && vs>=scaledbndu[j] )
                        {
                            xu[i] = state.bndu[j];
                            continue;
                        }
                        xu[i] = vs*state.s[j];
                        if( state.hasbndl[j] && xu[i]<state.bndl[j] )
                        {
                            xu[i] = state.bndl[j];
                        }
                        if( state.hasbndu[j] && xu[i]>state.bndu[j] )
                        {
                            xu[i] = state.bndu[j];
                        }
                    }
                }
            }
            else
            {
                
                //
                // Some vars are fixed
                //
                for(k=0; k<=batchsize-1; k++)
                {
                    for(j=0; j<=nraw-1; j++)
                    {
                        i = k*nraw+j;
                        jr = idxraw2red[j];
                        if( jr<0 )
                        {
                            xu[i] = state.bndl[j];
                            continue;
                        }
                        vs = xs[k*nreduced+jr];
                        if( state.hasbndl[j] && vs<=scaledbndl[jr] )
                        {
                            xu[i] = state.bndl[j];
                            continue;
                        }
                        if( state.hasbndu[j] && vs>=scaledbndu[jr] )
                        {
                            xu[i] = state.bndu[j];
                            continue;
                        }
                        xu[i] = vs*state.s[j];
                        if( state.hasbndl[j] && xu[i]<state.bndl[j] )
                        {
                            xu[i] = state.bndl[j];
                        }
                        if( state.hasbndu[j] && xu[i]>state.bndu[j] )
                        {
                            xu[i] = state.bndu[j];
                        }
                    }
                }
            }
        }


    }
    public partial class qqpsolver
    {
        /*************************************************************************
        This object stores settings for QQP solver.
        It must be initialized with QQPLoadDefaults().
        After initialization you may change settings.
        *************************************************************************/
        public class qqpsettings : apobject
        {
            public double epsg;
            public double epsf;
            public double epsx;
            public int maxouterits;
            public bool cgphase;
            public bool cnphase;
            public int cgminits;
            public int cgmaxits;
            public int cnmaxupdates;
            public int sparsesolver;
            public qqpsettings()
            {
                init();
            }
