        /*************************************************************************
        MinDF results

        INPUT PARAMETERS:
            State   -   algorithm state

        OUTPUT PARAMETERS:
            X       -   array[0..N-1], solution
            Rep     -   optimization report:
            
                        rep.f stores objective value at the solution
            
                        You  should     check  rep.terminationtype  in   order  to
                        distinguish successful termination from unsuccessful one:
                        * -8   internal integrity control  detected  infinite  or
                               NAN   values   in   function/gradient.    Abnormal
                               termination signalled.
                        * -3   box constraints are inconsistent
                        * -1   inconsistent parameters were passed:
                               * penalty parameter is zero, but we have nonlinear
                                 constraints set by MinDFsetnlc2()
                        *  1   successful termination according to a solver-specific
                               set of conditions
                        *  8   User requested termination via minnsrequesttermination()
                        
                        If you activated timers  with  mindfusetimers(),  you  can
                        also find out how much time was spent in various code parts:
                        * rep.timetotal    - for a total time in seconds
                        * rep.timesolver   - for a time spent in the solver itself
                        * rep.timecallback - for a time spent in user callbacks
                        See comments on mindfreport structure for more information
                        about timers and their accuracy.

          -- ALGLIB --
             Copyright 25.07.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void mindfresults(mindfstate state,
            ref double[] x,
            mindfreport rep,
            alglib.xparams _params)
        {
            x = new double[0];

            mindfresultsbuf(state, ref x, rep, _params);
        }


        /*************************************************************************

        Buffered implementation of MinDFresults() which uses pre-allocated buffer
        to store X[]. If buffer size is  too  small,  it  resizes  buffer.  It  is
        intended to be used in the inner cycles of performance critical algorithms
        where array reallocation penalty is too large to be ignored.

          -- ALGLIB --
             Copyright 25.07.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void mindfresultsbuf(mindfstate state,
            ref double[] x,
            mindfreport rep,
            alglib.xparams _params)
        {
            rep.f = state.repf;
            rep.iterationscount = state.repiterationscount;
            rep.nfev = state.repnfunc;
            rep.terminationtype = state.repterminationtype;
            rep.bcerr = state.repbcerr;
            rep.lcerr = state.replcerr;
            rep.nlcerr = state.repnlcerr;
            rep.timetotal = state.reptimetotal;
            rep.timecallback = Math.Min(state.reptimetotal, state.reptimecallback);
            rep.timesolver = rep.timetotal-rep.timecallback;
            if( state.repterminationtype>0 )
            {
                ablasf.rcopyallocv(state.n, state.xf, ref x, _params);
            }
            else
            {
                ablasf.rsetallocv(state.n, Double.NaN, ref x, _params);
            }
        }


        /*************************************************************************
        Set V2 reverse communication protocol:
        * prepare iteration function, as mandated by protocol
        * clear handler, as mandated by protocol
        *************************************************************************/
        public static void mindfsetprotocolv2(mindfstate state,
            alglib.xparams _params)
        {
            state.protocolversion = 2;
            state.rcommv2.ia = new int[2+1];
            state.rcommv2.ba = new bool[0+1];
            state.rcommv2.stage = -1;
            state.rcommv2.clear_handler();
            state.rcommv2.clear_handler();
        }


        /*************************************************************************
        Unscales X (converts from scaled variables to original ones)
        *************************************************************************/
        private static void unscale(mindfstate state,
            double[] xs,
            double[] xu,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            n = state.n;
            for(i=0; i<=n-1; i++)
            {
                xu[i] = xs[i]*state.s[i];
            }
        }


    }
