            }
            public override void init()
            {
                criteria = new optserv.nlpstoppingcriteria();
                s = new double[0];
                x0 = new double[0];
                hasbndl = new bool[0];
                hasbndu = new bool[0];
                bndl = new double[0];
                bndu = new double[0];
                idxraw2red = new int[0];
                redbl = new double[0];
                redbu = new double[0];
                reds = new double[0];
                redx0 = new double[0];
                rcommv2 = new ap.rcommstate();
                dfgmsolver = new dfgenmod.dfgmstate();
                xc = new double[0];
                unscaled = new double[0];
                combined = new double[0];
            }
            public override alglib.apobject make_copy()
            {
                nlsstate _result = new nlsstate();
                _result.protocolversion = protocolversion;
                _result.n = n;
                _result.m = m;
                _result.problemtype = problemtype;
                _result.algorithm = algorithm;
                _result.diffstep = diffstep;
                _result.criteria = criteria!=null ? (optserv.nlpstoppingcriteria)criteria.make_copy() : null;
                _result.xrep = xrep;
                _result.s = (double[])s.Clone();
                _result.x0 = (double[])x0.Clone();
