                _result.redbu = (double[])redbu.Clone();
                _result.reds = (double[])reds.Clone();
                _result.redx0 = (double[])redx0.Clone();
                _result.userterminationneeded = userterminationneeded;
                _result.rcommv2 = rcommv2!=null ? (ap.rcommstate)rcommv2.make_copy() : null;
                _result.dfgmsolver = dfgmsolver!=null ? (dfgenmod.dfgmstate)dfgmsolver.make_copy() : null;
                _result.dotrace = dotrace;
                _result.xc = (double[])xc.Clone();
                _result.repnfunc = repnfunc;
