        /*************************************************************************
        Optimization report, filled by NLSResults() function

        FIELDS:
        * TerminationType, completion code, which is a sum of a BASIC code and  an
        ADDITIONAL code.

          The following basic codes denote failure:
            * -8    optimizer detected NAN/INF  either  in  the  function  itself,
                    or its Jacobian; recovery was impossible, abnormal termination
                    reported.
            * -3    box constraints are inconsistent
          
          The following basic codes denote success:
            *  2    relative step is no more than EpsX.
            *  5    MaxIts steps was taken
            *  7    stopping conditions are too stringent,
                    further improvement is impossible
            *  8    terminated   by  user  who  called  NLSRequestTermination().
                    X contains point which was "current accepted" when termination
                    request was submitted.
          
          Additional codes can be set on success, but not on failure:
            * +800  if   during   algorithm   execution   the   solver encountered
                    NAN/INF values in the target or  constraints  but  managed  to
                    recover by reducing trust region radius,  the  solver  returns
                    one of SUCCESS codes but adds +800 to the code.
                    
        * IterationsCount, contains iterations count
        * NFunc, number of function calculations
        *************************************************************************/
        public class nlsreport : apobject
        {
            public int iterationscount;
            public int terminationtype;
            public int nfunc;
            public nlsreport()
            {
                init();
            }
            public override void init()
            {
            }
            public override alglib.apobject make_copy()
            {
                nlsreport _result = new nlsreport();
                _result.iterationscount = iterationscount;
                _result.terminationtype = terminationtype;
                _result.nfunc = nfunc;
                return _result;
            }
        };




        /*************************************************************************
                        DERIVATIVE-FREE NONLINEAR LEAST SQUARES

        DESCRIPTION:

        This function creates a NLS  solver  configured  to  solve  a  constrained
        nonlinear least squares problem

            min F(x) = f[0]^2 + f[1]^2 + ... + f[m-1]^2

        where f[i] are available, but not their derivatives.

        The  functions  f[i]  are  assumed  to  be   smooth,  but  may  have  some
        amount of numerical noise (either  random  noise  or  deterministic  noise
        arising from numerical simulations or other complex numerical processes).

        INPUT PARAMETERS:
            N       -   dimension, N>1
                        * if given, only leading N elements of X are used
                        * if not given, automatically determined from size of X
            M       -   number of functions f[i], M>=1
            X       -   initial point, array[N]

        OUTPUT PARAMETERS:
            State   -   structure which stores algorithm state

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void nlscreatedfo(int n,
            int m,
            double[] x,
            nlsstate state,
            alglib.xparams _params)
        {
            alglib.ap.assert(n>=1, "NLSCreateDFO: N<1!");
            alglib.ap.assert(m>=1, "NLSCreateDFO: M<1!");
            alglib.ap.assert(alglib.ap.len(x)>=n, "NLSCreateDFO: Length(X)<N!");
            alglib.ap.assert(apserv.isfinitevector(x, n, _params), "NLSCreateDFO: X contains infinite or NaN values!");
            
            //
            // initialize
            //
            state.protocolversion = 2;
            state.n = n;
            state.m = m;
            state.problemtype = 0;
            state.diffstep = 0;
            state.xrep = false;
            state.rad0 = 0;
            state.maxfev = 0;
            optserv.critinitdefault(state.criteria, _params);
            ablasf.bsetallocv(n, false, ref state.hasbndl, _params);
            ablasf.bsetallocv(n, false, ref state.hasbndu, _params);
            ablasf.rsetallocv(n, Double.NegativeInfinity, ref state.bndl, _params);
            ablasf.rsetallocv(n, Double.PositiveInfinity, ref state.bndu, _params);
            state.nnlc = 0;
            state.cntlc = 0;
            ablasf.rsetallocv(n, 1.0, ref state.s, _params);
            nlssetalgo2ps(state, 0, _params);
            nlsrestartfrom(state, x, _params);
        }


        /*************************************************************************
        This function sets the derivative-free NLS optimization algorithm  to  the
        2PS (2-Point Stencil) algorithm.

        This solver is recommended for the following cases:
        * an expensive target function is minimized  by the commercial ALGLIB with
          callback  parallelism  activated  (see  ALGLIB Reference Manual for more
          information about parallel callbacks)
        * an inexpensive target function is minimized by any ALGLIB edition  (free
          or commercial)

        This function works only with solvers created with nlscreatedfo(), i.e. in
        the derivative-free mode.

        See the end of this comment for more information about the algorithm.

        INPUT PARAMETERS:
            State           -   solver; must be created with nlscreatedfo() call -
                                passing  an  object   initialized   with   another
                                constructor function will result in an exception.
            NNoisyRestarts  -   number of restarts performed to combat a noise  in
                                the target. (see below, section 'RESTARTS', for  a
                                detailed discussion):
                                * 0     means that no restarts is performed, the
                                        solver stops as soon as stopping  criteria
                                        are met. Recommended for noise-free tasks.
                                * >0    means  that when the stopping criteria are
                                        met, the solver will  perform  a  restart:
                                        increase the trust   radius  and  resample
                                        points. It often helps to  solve  problems
                                        with random or deterministic noise.
                        
        ALGORITHM DESCRIPTION AND DISCUSSION

        The 2PS algorithm is a derivative-free model-based nonlinear least squares
        solver which builds local models by evaluating the target at  N additional
        points around the current one, with geometry similar to the 2-point finite
        difference stencil.

        Similarly to the Levenberg-Marquardt algorithm, the solver shows quadratic
        convergence despite the fact that it builds linear models.

        When compared with the DFO-LSA solver, the 2PS algorithm has the following
        distinctive properties:
        * the 2PS algorithm performs more target function evaluations per iteration
          (at least N+1 instead of 1-2 usually performed by the DFO-LSA)
        * 2PS requires several times less iterations than the DFO-LSA because each
          iteration extracts and utilizes more information about the  target. This
          difference tends to exaggerate when N increases
        * contrary to that, DFO-LSA is much better at reuse of previously computed
          points. Thus, DFO-LSA needs several times less target  evaluations  than
          2PS, usually about 3-4 times less (this ratio seems to be more  or  less
          constant independently of N).

        The summary is that:
        * for  expensive  targets  2PS  provides better parallelism potential than
          DFO-LSA because the former issues many  simultaneous  target  evaluation
          requests which can be easily parallelized. It  is  possible  for  2PS to
          outperform DFO-LSA by parallelism  alone,  despite  the  fact  that  the
          latter needs 3-4 times less target function evaluations.
        * for inexpensive targets 2PS may win  because  it  needs many  times less
          iterations, and thus the overhead associated with the working set updates
          is also many times less.
          
        RESTARTS

        Restarts is a strategy used to deal with random and deterministic noise in
        the target/constraints.

        Noise in the objective function can be random, arising from measurement or
        simulation   uncertainty,  or  deterministic,   resulting   from   complex
        underlying phenomena like numerical errors or branches in the target.  Its
        influence is especially high at last stages of the optimization, when  all
        computations are performed with small values of a trust radius.

        Restarts allow the optimization algorithm to be robust against both  types
        of noise by temporarily increasing a trust radius in order  to  capture  a
        global structure of the target and avoid being trapped  by  noise-produced
        local features.

        A restart is usually performed when the stopping criteria  are  triggered.
        Instead of stopping, the solver increases  trust  radius  to  its  initial
        value and tries to rebuild a model.

        If you decide to optimize with restarts,  it  is  recommended  to  perform
        a small amount of restarts, up to 5. Generally, restarts do not allow  one
        to completely solve the problem of noise, but still   it  is  possible  to
        achieve some additional progress.

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void nlssetalgo2ps(nlsstate state,
            int nnoisyrestarts,
            alglib.xparams _params)
        {
            alglib.ap.assert(state.problemtype==0, "NLSSetAlgo2PS: the solver MUST be created in a derivative-free mode (i.e. with nlscreatedfo() function)");
            alglib.ap.assert(nnoisyrestarts>=0, "NLSSetAlgo2PS: negative NNoisyRestarts");
            state.algorithm = 0;
            state.nnoisyrestarts = nnoisyrestarts;
        }


        /*************************************************************************
        This function sets the derivative-free NLS optimization algorithm  to  the
        DFO-LSA algorithm, an ALGLIB implementation (with several modifications)of
        the original DFO-LS algorithm  by  Cartis, C., Fiala, J., Marteau, B.  and
        Roberts, L. ('Improving the  Flexibility  and  Robustness  of  Model-Based
        Derivative-Free Optimization Solvers', 2019). The A in DFO-LSA stands  for
        ALGLIB, in order to distinguish our slightly modified implementation  from
        the original algorithm.

        This solver is recommended for the following  case:  an  expensive  target
        function is minimized without parallelism being used (either  free  ALGLIB
        is used or commercial one is used but the target callback is non-reentrant
        i.e. it can not be simultaneously called from multiple threads)

        This function works only with solvers created with nlscreatedfo(), i.e. in
        the derivative-free mode.

        See the end of this comment for more information about the algorithm.

        INPUT PARAMETERS:
            State           -   solver; must be created with nlscreatedfo() call -
                                passing  an  object   initialized   with   another
                                constructor function will result in an exception.
            NNoisyRestarts  -   number of restarts performed to combat a noise  in
                                the target. (see below, section 'RESTARTS', for  a
                                detailed discussion):
                                * 0     means that no restarts is performed, the
                                        solver stops as soon as stopping  criteria
                                        are met. Recommended for noise-free tasks.
                                * >0    means  that when the stopping criteria are
                                        met, the solver will  perform  a  restart:
                                        increase the trust   radius  and  resample
                                        points. It often helps to  solve  problems
                                        with random or deterministic noise.

        ALGORITHM DESCRIPTION AND DISCUSSION

        The DFO-LSA algorithm is a derivative-free model-based  NLS  solver  which
        builds local models by remembering N+1 previously computed  target  values
        and updating them as optimization progresses.

        Similarly to the Levenberg-Marquardt algorithm, the solver shows quadratic
        convergence  despite  the  fact  that  it  builds   linear   models.   Our
        implementation generally follows the same lines as the  original  DFO-LSA,
        with several modifications to trust radius  update  strategies,  stability
        fixes (unlike original DFO-LS, our implementation can handle  and  recover
        from the target breaking down due to infeasible arguments) and other minor
        implementation details.

        When compared with the 2PS solver, the DFO-LSA algorithm has the following
        distinctive properties:
        * the 2PS algorithm performs more target function evaluations per iteration
          (at least N+1 instead of 1-2 usually performed by DFO-LSA)
        * 2PS requires several times less iterations  than  DFO-LSA  because  each
          iterations extracts and utilizes more information about the target. This
          difference tends to exaggerate when N increases
        * contrary to that, DFO-LSA is much better at reuse of previously computed
          points. Thus, DFO-LSA needs several times less target  evaluations  than
          2PS, usually about 3-4 times less (this ratio seems to be more  or  less
          constant independently of N).

        The summary is that:
        * for  expensive  targets DFO-LSA is much more efficient than 2PS  because
          it reuses previously computed target values as much as possible.
        * however, DFO-LSA has little parallelism potential because  (unlike  2PS)
          it  does  not  evaluate the target  in several points simultaneously and
          independently
        * additionally, because DFO-LSA performs many times more  iterations  than
          2PS, iteration overhead (working set updates and matrix  inversions)  is
          an issue here. For inexpensive targets it is possible for DFO-LSA to  be
          outperformed by 2PS merely because of the linear algebra cost.
          
        RESTARTS

        Restarts is a strategy used to deal with random and deterministic noise in
        the target/constraints.

        Noise in the objective function can be random, arising from measurement or
        simulation   uncertainty,  or  deterministic,   resulting   from   complex
        underlying phenomena like numerical errors or branches in the target.  Its
        influence is especially high at last stages of the optimization, when  all
        computations are performed with small values of a trust radius.

        Restarts allow the optimization algorithm to be robust against both  types
        of noise by temporarily increasing a trust radius in order  to  capture  a
        global structure of the target and avoid being trapped  by  noise-produced
        local features.

        A restart is usually performed when the stopping criteria  are  triggered.
        Instead of stopping, the solver increases  trust  radius  to  its  initial
        value and tries to rebuild a model.

        If you decide to optimize with restarts,  it  is  recommended  to  perform
        a small amount of restarts, up to 5. Generally, restarts do not allow  one
        to completely solve the problem of noise, but still   it  is  possible  to
        achieve some additional progress.

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void nlssetalgodfolsa(nlsstate state,
            int nnoisyrestarts,
            alglib.xparams _params)
        {
            alglib.ap.assert(state.problemtype==0, "NLSSetAlgoDFOLSA: the solver MUST be created in a derivative-free mode (i.e. with nlscreatedfo() function)");
            alglib.ap.assert(nnoisyrestarts>=0, "NLSSetAlgo2PS: negative NNoisyRestarts");
            state.algorithm = 1;
            state.nnoisyrestarts = nnoisyrestarts;
        }


        /*************************************************************************
        This function sets stopping conditions

        INPUT PARAMETERS:
            State   -   structure which stores algorithm state
            EpsX    -   stop when the scaled trust region radius is  smaller  than
                        EpsX.
            MaxIts  -   maximum number of iterations. If MaxIts=0, the  number  of
                        iterations   is    unlimited.

        Passing  EpsX=0  and  MaxIts=0  (simultaneously)  will  lead  to automatic
        stopping criterion selection (small EpsX).

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void nlssetcond(nlsstate state,
            double epsx,
            int maxits,
            alglib.xparams _params)
        {
            alglib.ap.assert(math.isfinite(epsx), "NLSSetCond: EpsX is not finite number!");
            alglib.ap.assert((double)(epsx)>=(double)(0), "NLSSetCond: negative EpsX!");
            alglib.ap.assert(maxits>=0, "NLSSetCond: negative MaxIts!");
            if( (double)(epsx)==(double)(0) && maxits==0 )
            {
                epsx = 1.0E-6;
            }
            optserv.critsetcondv1(state.criteria, 0.0, epsx, maxits, _params);
        }


        /*************************************************************************
        This function turns on/off reporting.

        INPUT PARAMETERS:
            State   -   structure which stores algorithm state
            NeedXRep-   whether iteration reports are needed or not

        If NeedXRep is True, algorithm will call rep() callback function if  it is
        provided to NLSOptimize().

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void nlssetxrep(nlsstate state,
            bool needxrep,
            alglib.xparams _params)
        {
            state.xrep = needxrep;
        }


        /*************************************************************************
        This function sets variable scales

        ALGLIB optimizers use scaling matrices to test stopping  conditions  (step
        size and gradient are scaled before comparison with tolerances).  Scale of
        the I-th variable is a translation invariant measure of:
        a) "how large" the variable is
        b) how large the step should be to make significant changes in the function

        Generally, scale is NOT considered to be a  form  of  preconditioner.  But
        derivative-free optimizers often use scaling matrix both  in  the stopping
        condition tests and as a preconditioner.

        Proper scaling is very important for the algorithm performance. It is less
        important for the quality of results, but still has some influence (it  is
        easier  to  converge  when  variables  are  properly  scaled, so premature
        stopping is possible when very badly scalled variables are  combined  with
        relaxed stopping conditions).

        INPUT PARAMETERS:
            State   -   structure stores algorithm state
            S       -   array[N], non-zero scaling coefficients
                        S[i] may be negative, sign doesn't matter.

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void nlssetscale(nlsstate state,
            double[] s,
            alglib.xparams _params)
        {
            int i = 0;

            alglib.ap.assert(alglib.ap.len(s)>=state.n, "NLSSetScale: Length(S)<N");
            for(i=0; i<=state.n-1; i++)
            {
                alglib.ap.assert(math.isfinite(s[i]), "NLSSetScale: S contains infinite or NAN elements");
                alglib.ap.assert((double)(s[i])!=(double)(0), "NLSSetScale: S contains zero elements");
                state.s[i] = Math.Abs(s[i]);
            }
        }


        /*************************************************************************
        This function sets box constraints

        Box constraints are inactive by default (after initial creation). They are
        preserved until explicitly turned off with another SetBC() call.

        INPUT PARAMETERS:
            State   -   structure stores algorithm state
            BndL    -   lower bounds, array[N].
                        If some (all) variables are unbounded, you may specify
                        very small number or -INF (the latter is recommended).
            BndU    -   upper bounds, array[N].
                        If some (all) variables are unbounded, you may specify
                        very large number or +INF (the latter is recommended).

        NOTE 1: it is possible to specify BndL[i]=BndU[i]. In this case I-th
        variable will be "frozen" at X[i]=BndL[i]=BndU[i].

        NOTE 2: unless  explicitly  mentioned  in  the   specific   NLS  algorithm
                description, the following holds:
                * box constraints are always satisfied exactly
                * the target is NOT evaluated outside of the box-constrained area

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void nlssetbc(nlsstate state,
            double[] bndl,
            double[] bndu,
            alglib.xparams _params)
        {
            int i = 0;
            int n = 0;

            n = state.n;
            alglib.ap.assert(alglib.ap.len(bndl)>=n, "NLSSetBC: Length(BndL)<N");
            alglib.ap.assert(alglib.ap.len(bndu)>=n, "NLSSetBC: Length(BndU)<N");
            for(i=0; i<=n-1; i++)
            {
                alglib.ap.assert(math.isfinite(bndl[i]) || Double.IsNegativeInfinity(bndl[i]), "NLSSetBC: BndL contains NAN or +INF");
                alglib.ap.assert(math.isfinite(bndu[i]) || Double.IsPositiveInfinity(bndu[i]), "NLSSetBC: BndU contains NAN or -INF");
                state.bndl[i] = bndl[i];
                state.hasbndl[i] = math.isfinite(bndl[i]);
                state.bndu[i] = bndu[i];
                state.hasbndu[i] = math.isfinite(bndu[i]);
            }
        }


        /*************************************************************************

        CALLBACK PARALLELISM

        The  NLS  optimizer  supports   parallel   model   evaluation   ('callback
        parallelism').  This  feature,  which  is  present  in  commercial  ALGLIB
        editions, greatly accelerates  optimization  when  using  a  solver  which
        issues batch requests, i.e. multiple requests  for  target  values,  which
        can be computed independently by different threads.

        Callback parallelism is  usually   beneficial  when   processing  a  batch
        request requires more than several  milliseconds.  It  also  requires  the
        solver which issues requests in convenient batches, e.g. 2PS solver.

        See ALGLIB Reference Manual, 'Working with commercial version' section for
        more information.

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        public static bool nlsiteration(nlsstate state,
            alglib.xparams _params)
        {
            bool result = new bool();
            int nraw = 0;
            int nreduced = 0;
            int m = 0;
            int nnlc = 0;
            int i = 0;
            int originalrequest = 0;
            bool b = new bool();

            
            //
            // Reverse communication preparations
            //
            // This code initializes locals by:
            // * random values determined during code
            //   generation - on first subroutine call
            // * values from previous call - on subsequent calls
            //
            if( state.rcommv2.stage>=0 )
            {
                nraw = state.rcommv2.ia[0];
                nreduced = state.rcommv2.ia[1];
                m = state.rcommv2.ia[2];
                nnlc = state.rcommv2.ia[3];
                i = state.rcommv2.ia[4];
                originalrequest = state.rcommv2.ia[5];
                b = state.rcommv2.ba[0];
            }
            else
            {
                nraw = 359;
                nreduced = -58;
                m = -919;
                nnlc = -909;
                i = 81;
                originalrequest = 255;
                b = false;
            }
            if( state.rcommv2.stage==0 )
            {
                goto lbl_0;
            }
            if( state.rcommv2.stage==1 )
            {
                goto lbl_1;
            }
            
            //
            // Routine body
            //
            
            //
            // prepare
            //
            nraw = state.n;
            m = state.m;
            nnlc = state.nnlc;
            state.repiterationscount = 0;
            state.repterminationtype = 0;
            state.repnrequests = 0;
            state.repnfunc = 0;
            state.userterminationneeded = false;
            
            //
            // Trace status
            //
            state.dotrace = false;
            b = false;
            if( state.algorithm==0 )
            {
                state.dotrace = ap.istraceenabled("2PS", _params) || ap.istraceenabled("DFGM", _params);
                b = true;
            }
            if( state.algorithm==1 )
            {
                state.dotrace = ap.istraceenabled("DFOLSA", _params) || ap.istraceenabled("DFGM", _params);
                b = true;
            }
            alglib.ap.assert(b, "NLS: integrity check 8718 failed");
            if( state.dotrace )
            {
                alglib.ap.trace("\n\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace("//  NLS SOLVER STARTED                                                                            //\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace(System.String.Format("N             = {0,6:d} (original variables count)\n", nraw));
            }
            
            //
            // Check correctness of box constraints, remove fixed variables (most derivative-free solvers do not allow
            // fixed variables because it overcomplicates geometry improvement code).
            //
            ablasf.iallocv(nraw, ref state.idxraw2red, _params);
            ablasf.rallocv(nraw, ref state.redbl, _params);
            ablasf.rallocv(nraw, ref state.redbu, _params);
            ablasf.rallocv(nraw, ref state.reds, _params);
            ablasf.rallocv(nraw, ref state.redx0, _params);
            nreduced = 0;
            for(i=0; i<=nraw-1; i++)
            {
                if( math.isfinite(state.bndl[i]) && math.isfinite(state.bndu[i]) )
                {
                    if( (double)(state.bndl[i])>(double)(state.bndu[i]) )
                    {
                        if( state.dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> variable {0,0:d} has inconsistent box constraints, terminating with code -3\n", i));
                        }
                        state.repterminationtype = -3;
                        result = false;
                        return result;
                    }
                    if( (double)(state.bndl[i])==(double)(state.bndu[i]) )
                    {
                        state.idxraw2red[i] = -1;
                        continue;
                    }
                }
                state.redx0[nreduced] = state.x0[i];
                state.reds[nreduced] = state.s[i];
                state.redbl[nreduced] = state.bndl[i];
                state.redbu[nreduced] = state.bndu[i];
                state.idxraw2red[i] = nreduced;
                nreduced = nreduced+1;
            }
            if( nreduced==0 )
            {
                
                //
                // All variables are fixed, quick exit
                //
                if( state.dotrace )
                {
                    alglib.ap.trace("> all variables are fixed by their box constraints, no need to run the solver. Success!\n");
                }
                state.repterminationtype = 2;
                state.repiterationscount = 0;
                ablasf.rcopyv(nraw, state.bndl, state.xc, _params);
                result = false;
                return result;
            }
            if( state.dotrace )
            {
                alglib.ap.trace(System.String.Format("N_reduced     = {0,6:d} (variables after removing fixed ones)\n", nreduced));
                alglib.ap.trace(System.String.Format("M             = {0,6:d} (nonlinear least squares target functions)\n", m));
                alglib.ap.trace(System.String.Format("cntLC         = {0,6:d} (linear constraints)\n", state.cntlc));
                alglib.ap.trace(System.String.Format("cntNLC        = {0,6:d} (nonlinear constraints)\n", state.nnlc));
            }
            
            //
            // Allocate temporaries, as mandated by the V2 protocol
            //
            alglib.ap.assert(state.protocolversion==2, "NLS: integrity check 5124 failed");
            b = false;
            if( state.problemtype==0 )
            {
                ablasf.rallocv(nraw, ref state.rcommv2.reportx, _params);
                ablasf.rallocv(m+nnlc, ref state.rcommv2.tmpf1, _params);
                ablasf.rallocv(nraw, ref state.rcommv2.tmpg1, _params);
                ablasf.rallocv(nraw, ref state.rcommv2.tmpx1, _params);
                b = true;
            }
            alglib.ap.assert(b, "NLS: integrity check 6628 failed");
            
            //
            // Initialization phase
            //
            b = false;
            if( state.algorithm==0 || state.algorithm==1 )
            {
                
                //
                // Initialize 2PS solver
                //
                i = -999999;
                if( state.algorithm==0 )
                {
                    i = 0;
                }
                if( state.algorithm==1 )
                {
                    i = 1;
                }
                alglib.ap.assert(i>=0, "NLS: integrity check 7930 failed");
                dfgenmod.dfgminitbuf(state.redbl, state.redbu, state.reds, state.redx0, nreduced, m, true, i, state.criteria, state.nnoisyrestarts, state.rad0, state.maxfev, state.dfgmsolver, _params);
                b = true;
            }
            alglib.ap.assert(b, "NLS: integrity check 1620 failed");
            
            //
            // Iteration phase
            //
        lbl_2:
            if( false )
            {
                goto lbl_3;
            }
            
            //
            // Run iteration function and load evaluation point
            //
            state.rcommv2.requesttype = 0;
            b = false;
            if( state.algorithm==0 || state.algorithm==1 )
            {
                
                //
                // 2PS solver
                //
                if( !dfgenmod.dfgmiteration(state.dfgmsolver, state.userterminationneeded, _params) )
                {
                    goto lbl_3;
                }
                if( state.dfgmsolver.requesttype==4 )
                {
                    ablasf.rallocv(nraw*state.dfgmsolver.querysize, ref state.unscaled, _params);
                    state.batchsize = state.dfgmsolver.querysize;
                    unscalebatch(state, state.dfgmsolver.querydata, state.dfgmsolver.querysize, state.idxraw2red, nreduced, state.dfgmsolver.scaledbndl, state.dfgmsolver.scaledbndu, state.unscaled, _params);
                    originalrequest = 4;
                    b = true;
                }
                if( state.dfgmsolver.requesttype==-1 )
                {
                    unscalebatch(state, state.dfgmsolver.reportx, 1, state.idxraw2red, nreduced, state.dfgmsolver.scaledbndl, state.dfgmsolver.scaledbndu, state.rcommv2.reportx, _params);
                    state.rcommv2.reportf = state.dfgmsolver.reportf;
                    state.rcommv2.requesttype = -1;
                    originalrequest = -1;
                    b = true;
                }
            }
            alglib.ap.assert(b, "NLS: integrity check 5510 failed");
            
            //
            // Process evaluation request, perform numerical differentiation if necessary, offload results back to the optimizer
            //
            b = false;
            if( originalrequest!=-1 )
            {
                goto lbl_4;
            }
            
            //
            // Report
            //
            alglib.ap.assert(state.protocolversion==2, "NLS: integrity check 6811 failed");
            if( !state.xrep )
            {
                goto lbl_6;
            }
            state.rcommv2.stage = 0;
            if( state.rcommv2.rcomm2_handler!=null && state.rcommv2.requesttype!=0 && state.rcommv2.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rcommv2.rcomm2_handler(state.rcommv2, state.rcommv2.handler_p0, state.rcommv2.handler_p1, state.rcommv2.handler_p2, state.rcommv2.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_0:
        lbl_6:
            b = true;
        lbl_4:
            if( originalrequest!=4 )
            {
                goto lbl_8;
            }
            state.repnfunc = state.repnfunc+state.batchsize;
            state.repnrequests = state.repnrequests+1;
            ablasf.rallocv(nraw, ref state.rcommv2.querydata, _params);
            ablasf.rallocv(m+nnlc, ref state.rcommv2.replyfi, _params);
            ablasf.rallocv((m+nnlc)*state.batchsize, ref state.combined, _params);
            i = 0;
        lbl_10:
            if( i>state.batchsize-1 )
            {
                goto lbl_12;
            }
            state.rcommv2.requesttype = 4;
            state.rcommv2.queryfuncs = m+nnlc;
            state.rcommv2.queryvars = nraw;
            state.rcommv2.querydim = 0;
            state.rcommv2.querysize = 1;
            ablasf.rcopyvx(nraw, state.unscaled, i*nraw, state.rcommv2.querydata, 0, _params);
            state.rcommv2.stage = 1;
            if( state.rcommv2.rcomm2_handler!=null && state.rcommv2.requesttype!=0 && state.rcommv2.requesttype<=ap._ALGLIB_MAX_RCOMMV2_REQUEST )
                state.rcommv2.rcomm2_handler(state.rcommv2, state.rcommv2.handler_p0, state.rcommv2.handler_p1, state.rcommv2.handler_p2, state.rcommv2.handler_p3, _params);
            else
                goto lbl_rcomm;
        lbl_1:
            ablasf.rcopyvx(m+nnlc, state.rcommv2.replyfi, 0, state.combined, i*(m+nnlc), _params);
            i = i+1;
            goto lbl_10;
        lbl_12:
            b = true;
        lbl_8:
            alglib.ap.assert(b, "NLS: integrity check 7814 failed");
            
            //
            // Send results back to the optimizer
            //
            alglib.ap.assert(originalrequest==-1 || originalrequest==4, "NLS: integrity check 8314 failed");
            b = false;
            if( originalrequest==-1 )
            {
                
                //
                // Do nothing
                //
                b = true;
            }
            if( originalrequest==4 && (state.algorithm==0 || state.algorithm==1) )
            {
                
                //
                // 2PS solver
                //
                alglib.ap.assert(state.protocolversion==2, "NLS: integrity check 9915 failed");
                ablasf.rcopyv((m+nnlc)*state.batchsize, state.combined, state.dfgmsolver.replyfi, _params);
                b = true;
            }
            alglib.ap.assert(b, "MINNLC: integrity check 0038 failed");
            goto lbl_2;
        lbl_3:
            
            //
            // Results phase
            //
            b = false;
            if( state.algorithm==0 || state.algorithm==1 )
            {
                
                //
                // 2PS results
                //
                state.repterminationtype = state.dfgmsolver.repterminationtype;
                state.repiterationscount = state.dfgmsolver.repiterationscount;
                unscalebatch(state, state.dfgmsolver.xk, 1, state.idxraw2red, nreduced, state.dfgmsolver.scaledbndl, state.dfgmsolver.scaledbndu, state.xc, _params);
                b = true;
            }
            alglib.ap.assert(b, "NLS: integrity check 1825 failed");
            if( state.dotrace )
            {
                alglib.ap.trace("> analyzing callback parallelism potential:\n");
                alglib.ap.trace(System.String.Format("best_speedup  = {0,0:F1} (assuming expensive target function and negligible iteration overhead)\n", (double)state.repnfunc/(double)state.repnrequests));
            }
            result = false;
            return result;
            
            //
            // Saving state
            //
        lbl_rcomm:
            result = true;
            state.rcommv2.ia[0] = nraw;
            state.rcommv2.ia[1] = nreduced;
            state.rcommv2.ia[2] = m;
            state.rcommv2.ia[3] = nnlc;
            state.rcommv2.ia[4] = i;
            state.rcommv2.ia[5] = originalrequest;
            state.rcommv2.ba[0] = b;
            return result;
        }


        /*************************************************************************
        Nonlinear least squares solver results

        INPUT PARAMETERS:
            State   -   algorithm state

        OUTPUT PARAMETERS:
            X       -   array[N], solution
            Rep     -   optimization  report;  includes  termination   codes   and
                        additional information. Termination codes are returned  in
                        rep.terminationtype field, its possible values are  listed
                        below, see comments for this structure for more info.
                        
                        The termination code is a sum of a basic code (success  or
                        failure)  and  one/several  additional  codes.  Additional
                        codes are returned only for successful termination.
                        
                        The following basic codes can be returned:
                        * -8    optimizer detected NAN/INF values in the target or
                                nonlinear constraints and failed to recover
                        * -3    box constraints are inconsistent
                        *  2    relative step is no more than EpsX.
                        *  5    MaxIts steps was taken
                        *  7    stopping conditions are too stringent,
                                further improvement is impossible
                        *  8    terminated by user who called nlsrequesttermination().
                                X contains point which was "current accepted" when
                                termination request was submitted.
                                
                        The following additional codes can be returned  (added  to
                        a basic code):
                        * +800      if   during  algorithm  execution  the  solver
                                    encountered NAN/INF values in  the  target  or
                                    constraints but managed to recover by reducing
                                    trust region radius, the  solver  returns  one
                                    of SUCCESS codes but adds +800 to the code.

          -- ALGLIB --
             Copyright 15.10.2023 by Bochkanov Sergey
        *************************************************************************/
        public static void nlsresults(nlsstate state,
            ref double[] x,
            nlsreport rep,
            alglib.xparams _params)
        {
            x = new double[0];

            nlsresultsbuf(state, ref x, rep, _params);
        }


        /*************************************************************************
        Buffered implementation of NLSResults(), which uses pre-allocated buffer
        to store X[]. If buffer size is  too  small,  it  resizes  buffer.  It  is
        intended to be used in the inner cycles of performance critical algorithms
        where array reallocation penalty is too large to be ignored.

          -- ALGLIB --
             Copyright 10.03.2009 by Bochkanov Sergey
        *************************************************************************/
        public static void nlsresultsbuf(nlsstate state,
            ref double[] x,
            nlsreport rep,
            alglib.xparams _params)
        {
            if( alglib.ap.len(x)<state.n )
            {
                x = new double[state.n];
            }
            ablasf.rcopyv(state.n, state.xc, x, _params);
            rep.iterationscount = state.repiterationscount;
            rep.terminationtype = state.repterminationtype;
            rep.nfunc = state.repnfunc;
        }


        /*************************************************************************
        This  subroutine  restarts solver from the new point. All optimization
        parameters are left unchanged.

        This  function  allows  to  solve multiple  optimization  problems  (which
        must have same number of dimensions) without object reallocation penalty.

        INPUT PARAMETERS:
            State   -   optimizer
            X       -   new starting point.

          -- ALGLIB --
             Copyright 30.07.2010 by Bochkanov Sergey
        *************************************************************************/
        public static void nlsrestartfrom(nlsstate state,
            double[] x,
            alglib.xparams _params)
        {
            alglib.ap.assert(alglib.ap.len(x)>=state.n, "NLSRestartFrom: Length(X)<N!");
            alglib.ap.assert(apserv.isfinitevector(x, state.n, _params), "NLSRestartFrom: X contains infinite or NaN values!");
            ablasf.rcopyallocv(state.n, x, ref state.x0, _params);
            ablasf.rcopyallocv(state.n, x, ref state.xc, _params);
            state.rcommv2.ia = new int[5+1];
            state.rcommv2.ba = new bool[0+1];
            state.rcommv2.stage = -1;
            state.rcommv2.clear_handler();
        }


        /*************************************************************************
        This subroutine submits request for termination of running  optimizer.  It
        should be called from user-supplied callback when user decides that it  is
        time to "smoothly" terminate optimization process.  As  result,  optimizer
        stops at point which was "current accepted" when termination  request  was
        submitted and returns error code 8 (successful termination).

        INPUT PARAMETERS:
            State   -   optimizer structure

        NOTE: after  request  for  termination  optimizer  may   perform   several
              additional calls to user-supplied callbacks. It does  NOT  guarantee
              to stop immediately - it just guarantees that these additional calls
              will be discarded later.

        NOTE: calling this function on optimizer which is NOT running will have no
              effect.
              
        NOTE: multiple calls to this function are possible. First call is counted,
              subsequent calls are silently ignored.

          -- ALGLIB --
             Copyright 08.10.2014 by Bochkanov Sergey
        *************************************************************************/
        public static void nlsrequesttermination(nlsstate state,
            alglib.xparams _params)
        {
            state.userterminationneeded = true;
        }


        /*************************************************************************
        Set V2 reverse communication protocol
        *************************************************************************/
        public static void nlssetprotocolv2(nlsstate state,
            alglib.xparams _params)
        {
            state.protocolversion = 2;
            state.rcommv2.ia = new int[5+1];
            state.rcommv2.ba = new bool[0+1];
            state.rcommv2.stage = -1;
            state.rcommv2.clear_handler();
            state.rcommv2.clear_handler();
        }


        /*************************************************************************
        Unscales X (converts from scaled variables to original ones), paying special
        attention to box constraints (output is always feasible; active constraints
        are mapped to active ones).

        Can handle batch requests. Can handle problems with some variables being
        fixed and removed from consideration.

        Parameters:
            State           solver
            XS              array[NReduced*BatchSize] - variables after scaling and
                            removal of fixed vars
            idxRaw2Red      array[NRaw], maps original variable indexes to ones
                            after removal of fixed vars. Contains -1 for fixed vars.
            scaledBndL,
            ScaledBndU      array[NReduced], lower/upper bounds after removal of
                            the fixed vars
                            
        output:
            XU              array[NRaw*BatchSize], vars after unscaling and
                            substitution of the fixed vars
        *************************************************************************/
        private static void unscalebatch(nlsstate state,
            double[] xs,
            int batchsize,
            int[] idxraw2red,
            int nreduced,
            double[] scaledbndl,
            double[] scaledbndu,
            double[] xu,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int k = 0;
            int jr = 0;
            int nraw = 0;
            double vs = 0;

            nraw = state.n;
            if( nreduced==nraw )
            {
                
                //
                // No fixed vars, simple code
                //
                for(k=0; k<=batchsize-1; k++)
                {
                    for(j=0; j<=nraw-1; j++)
                    {
                        i = k*nraw+j;
                        vs = xs[i];
                        if( state.hasbndl[j] && vs<=scaledbndl[j] )
                        {
                            xu[i] = state.bndl[j];
                            continue;
                        }
                        if( state.hasbndu[j] && vs>=scaledbndu[j] )
                        {
                            xu[i] = state.bndu[j];
                            continue;
                        }
                        xu[i] = vs*state.s[j];
                        if( state.hasbndl[j] && xu[i]<state.bndl[j] )
                        {
                            xu[i] = state.bndl[j];
                        }
                        if( state.hasbndu[j] && xu[i]>state.bndu[j] )
                        {
                            xu[i] = state.bndu[j];
                        }
                    }
                }
            }
            else
            {
                
                //
                // Some vars are fixed
                //
                for(k=0; k<=batchsize-1; k++)
                {
                    for(j=0; j<=nraw-1; j++)
                    {
                        i = k*nraw+j;
                        jr = idxraw2red[j];
                        if( jr<0 )
                        {
                            xu[i] = state.bndl[j];
                            continue;
                        }
                        vs = xs[k*nreduced+jr];
                        if( state.hasbndl[j] && vs<=scaledbndl[jr] )
                        {
                            xu[i] = state.bndl[j];
                            continue;
                        }
                        if( state.hasbndu[j] && vs>=scaledbndu[jr] )
                        {
                            xu[i] = state.bndu[j];
                            continue;
                        }
                        xu[i] = vs*state.s[j];
                        if( state.hasbndl[j] && xu[i]<state.bndl[j] )
                        {
                            xu[i] = state.bndl[j];
                        }
                        if( state.hasbndu[j] && xu[i]>state.bndu[j] )
                        {
                            xu[i] = state.bndu[j];
                        }
                    }
                }
            }
        }


    }
    public partial class lpqppresolve
    {
        /*************************************************************************
        This object stores single quadratic constraint in the dynamic CRS format
        *************************************************************************/
        public class dynamiccrsqconstraint : apobject
        {
            public int nvars;
            public int[] varidx;
            public double[] b;
            public dyncrs.dynamiccrs fullq;
            public double cl;
            public double cu;
            public bool applyorigin;
            public dynamiccrsqconstraint()
            {
                init();
            }
            public override void init()
            {
                varidx = new int[0];
                b = new double[0];
                fullq = new dyncrs.dynamiccrs();
            }
            public override alglib.apobject make_copy()
            {
                dynamiccrsqconstraint _result = new dynamiccrsqconstraint();
                _result.nvars = nvars;
                _result.varidx = (int[])varidx.Clone();
                _result.b = (double[])b.Clone();
                _result.fullq = fullq!=null ? (dyncrs.dynamiccrs)fullq.make_copy() : null;
                _result.cl = cl;
                _result.cu = cu;
                _result.applyorigin = applyorigin;
                return _result;
            }
        };


