        /*************************************************************************
        This object stores a sequence of transformations  applied  to  the  linear
        problem. It can be used to 'playback'  these  transformations  to  restore
        solution for the untransformed problem.

        TrfType is an array[NTrf] which stores transformation types:
        * 0         cost scaling
        * 1         column scaling
        * 2         row scaling
        * 3         drop empty column
        * 4         drop empty row
        * 5         convert singleton row to box constraint
        * 6         fix variable
        * 7         explicit slack
        * 8         implicit slack
        *************************************************************************/
        public class presolverstack : apobject
        {
            public int n;
            public int m;
            public int mqc;
            public int mcc;
            public int ntrf;
            public int[] trftype;
            public int[] idata;
            public double[] rdata;
            public int[] idataridx;
            public int[] rdataridx;
            public int sourceidx;
            public int isrc;
            public int rsrc;
            public int[] sparseidx0;
            public int[] sparseidx1;
            public int[] sparseidx2;
            public int[] sparseidx3;
            public double[] sparseval0;
            public double[] sparseval1;
            public double[] sparseval2;
            public double[] sparseval3;
            public presolverstack()
            {
                init();
            }
            public override void init()
            {
                trftype = new int[0];
                idata = new int[0];
                rdata = new double[0];
                idataridx = new int[0];
                rdataridx = new int[0];
                sparseidx0 = new int[0];
                sparseidx1 = new int[0];
                sparseidx2 = new int[0];
                sparseidx3 = new int[0];
                sparseval0 = new double[0];
                sparseval1 = new double[0];
                sparseval2 = new double[0];
                sparseval3 = new double[0];
            }
            public override alglib.apobject make_copy()
            {
                presolverstack _result = new presolverstack();
                _result.n = n;
                _result.m = m;
                _result.mqc = mqc;
                _result.mcc = mcc;
                _result.ntrf = ntrf;
                _result.trftype = (int[])trftype.Clone();
                _result.idata = (int[])idata.Clone();
                _result.rdata = (double[])rdata.Clone();
                _result.idataridx = (int[])idataridx.Clone();
                _result.rdataridx = (int[])rdataridx.Clone();
                _result.sourceidx = sourceidx;
                _result.isrc = isrc;
                _result.rsrc = rsrc;
                _result.sparseidx0 = (int[])sparseidx0.Clone();
                _result.sparseidx1 = (int[])sparseidx1.Clone();
                _result.sparseidx2 = (int[])sparseidx2.Clone();
                _result.sparseidx3 = (int[])sparseidx3.Clone();
                _result.sparseval0 = (double[])sparseval0.Clone();
                _result.sparseval1 = (double[])sparseval1.Clone();
                _result.sparseval2 = (double[])sparseval2.Clone();
                _result.sparseval3 = (double[])sparseval3.Clone();
                return _result;
            }
        };


