            public opts.xconicconstraints rawxcc;
            public int problemstatus;
            public bool[] lagrangefromresidual;
            public double[] c;
            public double[] bndl;
            public double[] bndu;
            public sparse.sparsematrix sparseh;
            public sparse.sparsematrix sparsea;
            public double[] al;
            public double[] au;
