                rawbndu = new double[0];
                rawh = new sparse.sparsematrix();
                rawa = new sparse.sparsematrix();
                rawxqc = new opts.xquadraticconstraints();
                rawxcc = new opts.xconicconstraints();
                lagrangefromresidual = new bool[0];
                c = new double[0];
                bndl = new double[0];
                bndu = new double[0];
                sparseh = new sparse.sparsematrix();
                sparsea = new sparse.sparsematrix();
                al = new double[0];
                au = new double[0];
                xqc = new opts.xquadraticconstraints();
                xcc = new opts.xconicconstraints();
                packxperm = new int[0];
                packyperm = new int[0];
                packqcperm = new int[0];
                packccperm = new int[0];
                packstatperm = new int[0];
                unpackxperm = new int[0];
                unpackyperm = new int[0];
                unpackqcperm = new int[0];
                unpackccperm = new int[0];
                unpackstatperm = new int[0];
                trfstack = new presolverstack();
                s1 = new int[0];
                bc1 = new double[0];
                x1 = new double[0];
                y1 = new double[0];
                yqc = new double[0];
                d = new double[0];
                tmpi = new int[0];
                buf = new presolvebuffers();
            }
            public override alglib.apobject make_copy()
            {
                presolveinfo _result = new presolveinfo();
                _result.eps = eps;
                _result.newn = newn;
                _result.oldn = oldn;
                _result.oldmqc = oldmqc;
                _result.oldmcc = oldmcc;
                _result.newm = newm;
                _result.oldm = oldm;
                _result.newmqc = newmqc;
                _result.newmcc = newmcc;
                _result.rawc = (double[])rawc.Clone();
                _result.rawbndl = (double[])rawbndl.Clone();
                _result.rawbndu = (double[])rawbndu.Clone();
                _result.hash = hash;
                _result.rawh = rawh!=null ? (sparse.sparsematrix)rawh.make_copy() : null;
                _result.rawa = rawa!=null ? (sparse.sparsematrix)rawa.make_copy() : null;
                _result.rawxqc = rawxqc!=null ? (opts.xquadraticconstraints)rawxqc.make_copy() : null;
                _result.rawxcc = rawxcc!=null ? (opts.xconicconstraints)rawxcc.make_copy() : null;
                _result.problemstatus = problemstatus;
                _result.lagrangefromresidual = (bool[])lagrangefromresidual.Clone();
                _result.c = (double[])c.Clone();
                _result.bndl = (double[])bndl.Clone();
                _result.bndu = (double[])bndu.Clone();
                _result.sparseh = sparseh!=null ? (sparse.sparsematrix)sparseh.make_copy() : null;
                _result.sparsea = sparsea!=null ? (sparse.sparsematrix)sparsea.make_copy() : null;
                _result.al = (double[])al.Clone();
                _result.au = (double[])au.Clone();
                _result.xqc = xqc!=null ? (opts.xquadraticconstraints)xqc.make_copy() : null;
                _result.xcc = xcc!=null ? (opts.xconicconstraints)xcc.make_copy() : null;
                _result.packxperm = (int[])packxperm.Clone();
                _result.packyperm = (int[])packyperm.Clone();
                _result.packqcperm = (int[])packqcperm.Clone();
                _result.packccperm = (int[])packccperm.Clone();
                _result.packstatperm = (int[])packstatperm.Clone();
                _result.unpackxperm = (int[])unpackxperm.Clone();
                _result.unpackyperm = (int[])unpackyperm.Clone();
                _result.unpackqcperm = (int[])unpackqcperm.Clone();
                _result.unpackccperm = (int[])unpackccperm.Clone();
                _result.unpackstatperm = (int[])unpackstatperm.Clone();
                _result.trfstack = trfstack!=null ? (presolverstack)trfstack.make_copy() : null;
                _result.s1 = (int[])s1.Clone();
                _result.bc1 = (double[])bc1.Clone();
                _result.x1 = (double[])x1.Clone();
                _result.y1 = (double[])y1.Clone();
                _result.yqc = (double[])yqc.Clone();
                _result.d = (double[])d.Clone();
                _result.tmpi = (int[])tmpi.Clone();
                _result.buf = buf!=null ? (presolvebuffers)buf.make_copy() : null;
                return _result;
            }
        };




        public const int pstobjectivescaling = 0;
        public const int pstcolscaling = 1;
        public const int pstrowscaling = 2;
        public const int pstdropemptycol = 3;
        public const int pstdropemptyrow = 4;
        public const int pstsingletonrow = 5;
        public const int pstfixedvar = 6;
        public const int pstexplicitslack = 7;
        public const int pstimplicitslack = 8;
        public const int pstcolshifting = 9;
        public const int pstdoubletoneq = 10;
        public const int pstqcscaling = 11;
        public const int pstdropemptyqc = 12;
        public const int actlowerboundonk0 = 0;
        public const int actupperboundonk0 = 1;
        public const int actlowerboundonk1 = 2;
        public const int actupperboundonk1 = 3;
        public const int actnone = -1;
        public const double smlcoeff = 0.001;
        public const double maxcoeffgrowth = 100.0;


        /*************************************************************************
        No presolve, just user-supplied scaling + constraint and cost vector
        normalization.

        INPUT PARAMETERS:
            S           -   array[N], user-supplied scale vector, S[I]>0
            C           -   array[N], costs
            BndL        -   array[N], lower bounds (may contain -INF)
            BndU        -   array[N], upper bounds (may contain +INF)
            N           -   variable count, N>0
            SparseA     -   matrix[K,N], sparse constraints
            AL          -   array[K], lower constraint bounds (may contain -INF)
            AU          -   array[K], upper constraint bounds (may contain +INF)
            K           -   constraint count, K>=0
            Info        -   presolve info structure; temporaries allocated during
                            previous calls may be reused by this function.
                            
        OUTPUT PARAMETERS:
            Info        -   contains transformed C, BndL, bndU,  SparseA,  AL,  AU
                            and   information   necessary   to   perform  backward
                            transformation.
                            Following fields can be accessed:
                            * ProblemStatus    which is:
                                               *  0 for successful transformation
                                               * -3 for infeasible problem
                                               * -4 for unbounded problem
                            
                            If Info.ProblemStatus=0, then the following fields can
                            be accessed:
                            * Info.NewN>0  for transformed problem size
                            * Info.NewM>=0 for transformed linear constraint count
                            * Info.NewMQC>=0 for transformed quadratic constraint count
                            * always:          Info.C, Info.BndL, Info.BndU - array[NewN]
                            * for Info.NewM>0: Info.SparseA, Info.AL, Info.AU
                            * for Info.NewMQC>0: Info.XQC
            
        NOTE: this routine does not reallocate arrays if NNew<=NOld and/or KNew<=KOld.

          -- ALGLIB --
             Copyright 01.07.2020 by Bochkanov Sergey
        *************************************************************************/
        public static void presolvenonescaleuser(double[] s,
            double[] xorigin,
            double[] c,
            double[] bndl,
            double[] bndu,
            sparse.sparsematrix sparseh,
            bool isupper,
            bool hash,
            int n,
            sparse.sparsematrix sparsea,
            double[] al,
            double[] au,
            int k,
            opts.xquadraticconstraints xqc,
            opts.xconicconstraints xcc,
            bool dotrace,
            presolveinfo info,
            alglib.xparams _params)
        {
            int i = 0;
            opts.xconicconstraint cc = null;

            
            //
            // Integrity checks
            //
            alglib.ap.assert(alglib.ap.len(bndl)>=n, "PresolveNoneScaleUser: Length(BndL)<N");
            alglib.ap.assert(alglib.ap.len(bndu)>=n, "PresolveNoneScaleUser: Length(BndU)<N");
            alglib.ap.assert(alglib.ap.len(s)>=n, "PresolveNoneScaleUser: Length(S)<N");
            alglib.ap.assert(apserv.isfinitevector(s, n, _params), "PresolveNoneScaleUser: S contains infinite or NaN elements");
            alglib.ap.assert(alglib.ap.len(c)>=n, "PresolveNoneScaleUser: Length(C)<N");
            alglib.ap.assert(apserv.isfinitevector(c, n, _params), "PresolveNoneScaleUser: C contains infinite or NaN elements");
            alglib.ap.assert(k>=0, "PresolveNoneScaleUser: K<0");
            alglib.ap.assert(k==0 || sparse.sparseiscrs(sparsea, _params), "PresolveNoneScaleUser: A is not CRS");
            alglib.ap.assert(k==0 || sparsea.m==k, "PresolveNoneScaleUser: rows(A)<>K");
            alglib.ap.assert(k==0 || sparsea.n==n, "PresolveNoneScaleUser: cols(A)<>N");
            alglib.ap.assert(!hash || sparse.sparseiscrs(sparseh, _params), "PresolveNoneScaleUser: A is not CRS");
            
            //
            // Initial check for constraint feasibility and canonicity
            //
            for(i=0; i<=n-1; i++)
            {
                if( (math.isfinite(bndl[i]) && math.isfinite(bndu[i])) && (double)(bndl[i])>(double)(bndu[i]) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> variable {0,0:d} is found to have infeasible box constraints, terminating\n", i));
                    }
                    info.problemstatus = -3;
                    return;
                }
            }
            for(i=0; i<=k-1; i++)
            {
                if( (math.isfinite(al[i]) && math.isfinite(au[i])) && (double)(al[i])>(double)(au[i]) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> linear constraint {0,0:d} is found to have infeasible bounds, terminating\n", i));
                    }
                    info.problemstatus = -3;
                    return;
                }
            }
            for(i=0; i<=optserv.xccgetcount(xcc, _params)-1; i++)
            {
                xcc.constraints.get(i, ref cc);
                alglib.ap.assert(cc.conetype>=0, "PresolveNoneScaleUser: one of the conic constraints has non-canonic form");
            }
            
            //
            // Reallocate storage
            //
            apserv.rvectorgrowto(ref info.rawc, n, _params);
            apserv.rvectorgrowto(ref info.rawbndl, n, _params);
            apserv.rvectorgrowto(ref info.rawbndu, n, _params);
            
            //
            // Save original problem formulation
            //
            presolverstackinit(n, k, opts.xqcgetcount(xqc, _params), optserv.xccgetcount(xcc, _params), info.trfstack, _params);
            info.eps = math.machineepsilon;
            info.problemstatus = 0;
            info.newn = n;
            info.oldn = n;
            info.newm = k;
            info.oldm = k;
            info.oldmqc = opts.xqcgetcount(xqc, _params);
            info.newmqc = info.oldmqc;
            info.oldmcc = optserv.xccgetcount(xcc, _params);
            info.newmcc = info.oldmcc;
            ablasf.bsetallocv(n, false, ref info.lagrangefromresidual, _params);
            ablasf.iallocv(n, ref info.packxperm, _params);
            ablasf.iallocv(n, ref info.unpackxperm, _params);
            for(i=0; i<=n-1; i++)
            {
                alglib.ap.assert(s[i]>0, "PresolveNoneScaleUser: S<=0");
                alglib.ap.assert(math.isfinite(bndl[i]) || Double.IsNegativeInfinity(bndl[i]), "PresolveNoneScaleUser: BndL contains NAN or +INF");
                alglib.ap.assert(math.isfinite(bndu[i]) || Double.IsPositiveInfinity(bndu[i]), "PresolveNoneScaleUser: BndU contains NAN or -INF");
                info.rawc[i] = c[i];
                info.rawbndl[i] = bndl[i];
                info.rawbndu[i] = bndu[i];
                info.packxperm[i] = i;
                info.unpackxperm[i] = i;
            }
            info.hash = hash;
            if( hash )
            {
                copyexpandh(sparseh, isupper, info.rawh, _params);
                sparse.sparsecopybuf(info.rawh, info.sparseh, _params);
            }
            ablasf.iallocv(k, ref info.packyperm, _params);
            ablasf.iallocv(k, ref info.unpackyperm, _params);
            for(i=0; i<=k-1; i++)
            {
                info.packyperm[i] = i;
                info.unpackyperm[i] = i;
            }
            ablasf.iallocv(info.newmqc, ref info.packqcperm, _params);
            ablasf.iallocv(info.newmqc, ref info.unpackqcperm, _params);
            for(i=0; i<=info.newmqc-1; i++)
            {
                info.packqcperm[i] = i;
                info.unpackqcperm[i] = i;
            }
            ablasf.iallocv(n+k, ref info.packstatperm, _params);
            ablasf.iallocv(n+k, ref info.unpackstatperm, _params);
            for(i=0; i<=n+k-1; i++)
            {
                info.packstatperm[i] = i;
                info.unpackstatperm[i] = i;
            }
            sparse.sparsecopytocrsbuf(sparsea, info.rawa, _params);
            opts.xqccopy(xqc, info.rawxqc, _params);
            optserv.xcccopy(xcc, info.rawxcc, _params);
            
            //
            // Scale cost and box constraints
            //
            ablasf.rcopyallocv(n, c, ref info.c, _params);
            ablasf.rcopyallocv(n, bndl, ref info.bndl, _params);
            ablasf.rcopyallocv(n, bndu, ref info.bndu, _params);
            if( k>0 )
            {
                ablasf.rcopyallocv(k, al, ref info.al, _params);
                ablasf.rcopyallocv(k, au, ref info.au, _params);
                sparse.sparsecopybuf(sparsea, info.sparsea, _params);
            }
            opts.xqccopy(xqc, info.xqc, _params);
            optserv.xcccopy(xcc, info.xcc, _params);
            scaleshiftobjectiveandconstraints(s, xorigin, n, info.c, info.bndl, info.bndu, info.sparseh, hash, info.sparsea, info.al, info.au, k, info.xqc, info.xcc, info.trfstack, _params);
        }


        /*************************************************************************
        Extensive presolving for an LP problem, all techniques are used

        INPUT PARAMETERS:
            S           -   array[N], user-supplied scale vector, S[I]>0
            C           -   array[N], costs
            BndL        -   array[N], lower bounds (may contain -INF)
            BndU        -   array[N], upper bounds (may contain +INF)
            N           -   variable count, N>0
            SparseA     -   matrix[K,N], sparse constraints
            AL          -   array[K], lower constraint bounds (may contain -INF)
            AU          -   array[K], upper constraint bounds (may contain +INF)
            K           -   constraint count, K>=0
            XQC         -   quadratic constraints; can be empty, but must be correctly
                            initialized with xqcInit()
            XCC         -   conic constraints; can be empty, but must be correctly
                            initialized with xccInit()
            Info        -   presolve info structure; temporaries allocated during
                            previous calls may be reused by this function.
                            
        OUTPUT PARAMETERS:
            Info        -   contains transformed C, BndL, bndU,  SparseA,  AL,  AU
                            and   information   necessary   to   perform  backward
                            transformation.
                            Following fields can be acessed:
                            * Info.NewN>0  for transformed problem size
                            * Info.NewM>=0 for transformed constraint count
                            * always:          Info.C, Info.BndL, Info.BndU - array[NewN]
                            * for Info.NewM>0: Info.SparseA, Info.AL, Info.AU
            
        NOTE: this routine does not reallocate arrays if NNew<=NOld and/or KNew<=KOld.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void presolvelp(double[] raws,
            double[] rawc,
            double[] rawbndl,
            double[] rawbndu,
            int n,
            sparse.sparsematrix rawsparsea,
            double[] rawal,
            double[] rawau,
            int m,
            opts.xquadraticconstraints xqc,
            opts.xconicconstraints xcc,
            bool dotrace,
            presolveinfo presolved,
            alglib.xparams _params)
        {
            sparse.sparsematrix dummyh = new sparse.sparsematrix();
            double[] dummyorigin = new double[0];

            ablasf.rsetallocv(n, 0.0, ref dummyorigin, _params);
            presolveqp(raws, dummyorigin, rawc, rawbndl, rawbndu, dummyh, false, false, n, rawsparsea, rawal, rawau, m, xqc, xcc, dotrace, presolved, _params);
        }


        /*************************************************************************
        Extensive presolving for an QP problem, all techniques are used

        INPUT PARAMETERS:
            S           -   array[N], user-supplied scale vector, S[I]>0
            C           -   array[N], costs
            BndL        -   array[N], lower bounds (may contain -INF)
            BndU        -   array[N], upper bounds (may contain +INF)
            H           -   if HasH=True, lower/upper triangular quadratic term
            HasH        -   if false, H is ignored
            N           -   variable count, N>0
            SparseA     -   matrix[K,N], sparse constraints
            AL          -   array[K], lower constraint bounds (may contain -INF)
            AU          -   array[K], upper constraint bounds (may contain +INF)
            K           -   constraint count, K>=0
            XQC         -   quadratic constraints; can be empty, but must be correctly
                            initialized with xqcInit(). Not modified, however it
                            is passed as shared because we access it with
                            objArray...() family of functions.
            XCC         -   conic constraints; can be empty, but must be correctly
                            initialized with xccInit(). Not modified, however it
                            is passed as shared because we access it with
                            objArray...() family of functions.
            Info        -   presolve info structure; temporaries allocated during
                            previous calls may be reused by this function.
                            
        OUTPUT PARAMETERS:
            Info        -   contains transformed C, BndL, bndU,  SparseA,  AL,  AU
                            and   information   necessary   to   perform  backward
                            transformation.
                            Following fields can be acessed:
                            * Info.NewN>0  for transformed problem size
                            * Info.NewM>=0 for transformed constraint count
                            * always:          Info.C, Info.BndL, Info.BndU - array[NewN]
                            * for Info.NewM>0: Info.SparseA, Info.AL, Info.AU
            
        NOTE: this routine does not reallocate arrays if NNew<=NOld and/or KNew<=KOld.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        public static void presolveqp(double[] raws,
            double[] xorigin,
            double[] rawc,
            double[] rawbndl,
            double[] rawbndu,
            sparse.sparsematrix rawsparseh,
            bool isupper,
            bool hash,
            int n,
            sparse.sparsematrix rawsparsea,
            double[] rawal,
            double[] rawau,
            int m,
            opts.xquadraticconstraints rawxqc,
            opts.xconicconstraints rawxcc,
            bool dotrace,
            presolveinfo presolved,
            alglib.xparams _params)
        {
            bool somethingchanged = new bool();
            sparse.sparsematrix normsparsea = new sparse.sparsematrix();
            sparse.sparsematrix normsparseat = new sparse.sparsematrix();
            opts.xquadraticconstraints normxqc = new opts.xquadraticconstraints();
            opts.xconicconstraints normxcc = new opts.xconicconstraints();
            dyncrs.dynamiccrs sparseh = new dyncrs.dynamiccrs();
            dyncrs.dynamiccrs a = new dyncrs.dynamiccrs();
            dyncrs.dynamiccrs at = new dyncrs.dynamiccrs();
            dynamiccrsqconstraints qc = new dynamiccrsqconstraints();
            double[] c = new double[0];
            double[] bndl = new double[0];
            double[] bndu = new double[0];
            double[] al = new double[0];
            double[] au = new double[0];
            int i = 0;
            int k = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int mqc = 0;
            int mcc = 0;
            int nv = 0;
            int offs = 0;
            int dbgemptycol = 0;
            int dbgemptyrow = 0;
            int dbgemptyqc = 0;
            int dbgnonbindingrows = 0;
            int dbgnonbindingqc = 0;
            int dbgfixed = 0;
            int dbgsingletonrow = 0;
            int dbgdoubletonrow = 0;
            int dbgslackvars = 0;
            int dbgimplicitslacks = 0;
            int dbgfreecolumnsingletons = 0;
            double eps = 0;
            int presolverounds = 0;
            sparse.sparsematrix sparsetmp = new sparse.sparsematrix();
            dynamiccrsqconstraint qci = null;
            opts.xconicconstraint cci = null;
            opts.xquadraticconstraint xqci = null;
            presolvervcstats vcstats = new presolvervcstats();
            int kpow = 0;
            bool donecc = new bool();

            alglib.ap.assert(m==0 || sparse.sparseiscrs(rawsparsea, _params), "PRESOLVER: A is non-CRS sparse matrix");
            alglib.ap.assert(!hash || sparse.sparseiscrs(rawsparseh, _params), "PRESOLVER: quadratic term must be stored in the CRS format");
            mqc = opts.xqcgetcount(rawxqc, _params);
            mcc = optserv.xccgetcount(rawxcc, _params);
            
            //
            // Trace
            //
            dotrace = (dotrace || (ap.istraceenabled("PRESOLVER.LP", _params) && !hash)) || ap.istraceenabled("PRESOLVER.QP", _params);
            if( dotrace )
            {
                alglib.ap.trace("\n\n");
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                if( hash )
                {
                    alglib.ap.trace("// QP PRESOLVER STARTED                                                                           //\n");
                }
                else
                {
                    alglib.ap.trace("// LP PRESOLVER STARTED                                                                           //\n");
                }
                alglib.ap.trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
                alglib.ap.trace("----- printing input problem metrics ---------------------------------------------------------------\n");
                alglib.ap.trace(System.String.Format("N            = {0,10:d} (variables)\n", n));
                alglib.ap.trace(System.String.Format("M            = {0,10:d} (linear constraints)\n", m));
                if( m!=0 )
                {
                    alglib.ap.trace(System.String.Format("nz(A)        = {0,10:d} (nonzeros in linear constraints)\n", rawsparsea.ridx[rawsparsea.m]));
                }
                alglib.ap.trace(System.String.Format("MQC          = {0,10:d} (quadratic constraints)\n", mqc));
                alglib.ap.trace(System.String.Format("MCC          = {0,10:d} (conic constraints)\n", mcc));
            }
            
            //
            // Initial check for constraint feasibility
            //
            for(i=0; i<=n-1; i++)
            {
                if( (math.isfinite(rawbndl[i]) && math.isfinite(rawbndu[i])) && (double)(rawbndl[i])>(double)(rawbndu[i]) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> variable {0,0:d} is found to have infeasible box constraints, terminating\n", i));
                    }
                    presolved.problemstatus = -3;
                    return;
                }
            }
            for(i=0; i<=m-1; i++)
            {
                if( (math.isfinite(rawal[i]) && math.isfinite(rawau[i])) && (double)(rawal[i])>(double)(rawau[i]) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> linear constraint {0,0:d} is found to have infeasible bounds, terminating\n", i));
                    }
                    presolved.problemstatus = -3;
                    return;
                }
            }
            for(i=0; i<=mqc-1; i++)
            {
                rawxqc.constraints.get(i, ref xqci);
                if( (math.isfinite(xqci.cl) && math.isfinite(xqci.cu)) && (double)(xqci.cl)>(double)(xqci.cu) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> quadratic constraint {0,0:d} is found to have infeasible bounds, terminating\n", i));
                    }
                    presolved.problemstatus = -3;
                    return;
                }
            }
            
            //
            // Starting output
            //
            ablasf.rcopyallocv(n, rawc, ref presolved.rawc, _params);
            ablasf.rcopyallocv(n, rawbndl, ref presolved.rawbndl, _params);
            ablasf.rcopyallocv(n, rawbndu, ref presolved.rawbndu, _params);
            if( m>0 )
            {
                sparse.sparsecopytocrsbuf(rawsparsea, presolved.rawa, _params);
            }
            opts.xqccopy(rawxqc, presolved.rawxqc, _params);
            optserv.xcccopy(rawxcc, presolved.rawxcc, _params);
            presolved.hash = hash;
            if( hash )
            {
                copyexpandh(rawsparseh, isupper, presolved.rawh, _params);
            }
            
            //
            // Trace counters
            //
            dbgemptycol = 0;
            dbgemptyrow = 0;
            dbgemptyqc = 0;
            dbgnonbindingrows = 0;
            dbgnonbindingqc = 0;
            dbgfixed = 0;
            dbgsingletonrow = 0;
            dbgdoubletonrow = 0;
            dbgslackvars = 0;
            dbgimplicitslacks = 0;
            dbgfreecolumnsingletons = 0;
            
            //
            // Initial state of the presolver
            //
            eps = (1000+n+m)*math.machineepsilon+Math.Pow(math.machineepsilon, 0.75);
            presolved.eps = eps;
            presolverstackinit(n, m, opts.xqcgetcount(rawxqc, _params), optserv.xccgetcount(rawxcc, _params), presolved.trfstack, _params);
            presolved.problemstatus = 0;
            ablasf.rcopyallocv(n, rawc, ref c, _params);
            ablasf.rcopyallocv(n, rawbndl, ref bndl, _params);
            ablasf.rcopyallocv(n, rawbndu, ref bndu, _params);
            if( m>0 )
            {
                sparse.sparsecopybuf(rawsparsea, normsparsea, _params);
                ablasf.rcopyallocv(m, rawal, ref al, _params);
                ablasf.rcopyallocv(m, rawau, ref au, _params);
            }
            opts.xqccopy(rawxqc, normxqc, _params);
            optserv.xcccopy(rawxcc, normxcc, _params);
            if( hash )
            {
                sparse.sparsecopybuf(presolved.rawh, sparsetmp, _params);
            }
            scaleshiftobjectiveandconstraints(raws, xorigin, n, c, bndl, bndu, sparsetmp, hash, normsparsea, al, au, m, normxqc, normxcc, presolved.trfstack, _params);
            if( hash )
            {
                dyncrs.dyncrsinitfromsparsecrs(sparsetmp, sparseh, _params);
                dyncrs.dyncrsdropoffdiagonalzeros(sparseh, _params);
            }
            if( m>0 )
            {
                sparse.sparsecopytransposecrsbuf(normsparsea, normsparseat, _params);
                dyncrs.dyncrsinitfromsparsecrs(normsparsea, a, _params);
                dyncrs.dyncrsinitfromsparsecrs(normsparseat, at, _params);
                dyncrs.dyncrsdropzeros(a, _params);
                dyncrs.dyncrsdropzeros(at, _params);
            }
            else
            {
                dyncrs.dyncrsinitempty(a, 0, n, _params);
                dyncrs.dyncrsinitempty(at, n, 0, _params);
            }
            ablasf.bsetallocv(n, false, ref presolved.lagrangefromresidual, _params);
            presolvebuffersinit(presolved.buf, n, m, _params);
            
            //
            // Initial state of QC and CC-related variables
            //
            ablasf.bsetallocv(n, false, ref vcstats.isdroppedcol, _params);
            ablasf.bsetallocv(m, false, ref vcstats.isdroppedlc, _params);
            ablasf.isetallocv(n, 0, ref vcstats.nlcpervar, _params);
            ablasf.isetallocv(n, 0, ref vcstats.cntdownwardaxial, _params);
            ablasf.isetallocv(n, 0, ref vcstats.cntupwardaxial, _params);
            ablasf.isetallocv(n, 0, ref vcstats.cntaxial, _params);
            ablasf.isetallocv(n, 0, ref vcstats.cntradial, _params);
            dynqcinitfromxqc(normxqc, qc, _params);
            ablasf.bsetallocv(mqc, false, ref vcstats.isdroppedqc, _params);
            apstruct.knisinitunsorted(n, mqc, 0, vcstats.varbyqc, _params);
            for(i=0; i<=mqc-1; i++)
            {
                qc.constraints.get(i, ref qci);
                for(j=0; j<=qci.nvars-1; j++)
                {
                    k = qci.varidx[j];
                    vcstats.nlcpervar[k] = vcstats.nlcpervar[k]+1;
                    apstruct.knisaddnewelement(vcstats.varbyqc, k, i, _params);
                }
            }
            ablasf.bsetallocv(mcc, false, ref vcstats.isdroppedcc, _params);
            apstruct.knisinitunsorted(n, mcc, 0, vcstats.varbycc, _params);
            for(i=0; i<=mcc-1; i++)
            {
                normxcc.constraints.get(i, ref cci);
                nv = cci.nvars;
                for(j=0; j<=nv-1; j++)
                {
                    k = cci.varidx[j];
                    vcstats.nlcpervar[k] = vcstats.nlcpervar[k]+1;
                    apstruct.knisaddnewelement(vcstats.varbycc, k, i, _params);
                }
                donecc = false;
                if( cci.conetype==optserv.xccprimitiveconetype(_params) )
                {
                    for(j=0; j<=nv-2; j++)
                    {
                        vcstats.cntradial[cci.varidx[j]] = vcstats.cntradial[cci.varidx[j]]+1;
                    }
                    k = cci.varidx[nv-1];
                    vcstats.cntaxial[k] = vcstats.cntaxial[k]+1;
                    if( (double)(cci.diaga[nv-1])>(double)(0) )
                    {
                        vcstats.cntupwardaxial[k] = vcstats.cntupwardaxial[k]+1;
                    }
                    if( (double)(cci.diaga[nv-1])<(double)(0) )
                    {
                        vcstats.cntdownwardaxial[k] = vcstats.cntdownwardaxial[k]+1;
                    }
                    donecc = true;
                }
                if( cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                {
                    kpow = cci.kpow;
                    for(j=0; j<=nv-kpow-1; j++)
                    {
                        vcstats.cntradial[cci.varidx[j]] = vcstats.cntradial[cci.varidx[j]]+1;
                    }
                    for(j=nv-kpow; j<=nv-1; j++)
                    {
                        k = cci.varidx[j];
                        vcstats.cntaxial[k] = vcstats.cntaxial[k]+1;
                        if( (double)(cci.diaga[j])>(double)(0) )
                        {
                            vcstats.cntupwardaxial[k] = vcstats.cntupwardaxial[k]+1;
                        }
                        if( (double)(cci.diaga[j])<(double)(0) )
                        {
                            vcstats.cntdownwardaxial[k] = vcstats.cntdownwardaxial[k]+1;
                        }
                    }
                    donecc = true;
                }
                alglib.ap.assert(donecc, "PRESOLVER: integrity check 485227 failed");
            }
            
            //
            // While something changes, keep iterating
            //
            presolverounds = 0;
            somethingchanged = true;
            while( somethingchanged )
            {
                somethingchanged = false;
                if( !dropemptycol(c, bndl, bndu, vcstats, presolved.lagrangefromresidual, sparseh, hash, n, a, at, al, au, m, eps, dotrace, presolved.buf, presolved.trfstack, ref presolved.problemstatus, ref somethingchanged, ref dbgemptycol, _params) )
                {
                    return;
                }
                if( !dropclearlynonbindingrows(n, vcstats, a, at, al, au, m, qc, normxcc, eps, dotrace, presolved.buf, presolved.trfstack, ref presolved.problemstatus, ref somethingchanged, ref dbgemptyrow, ref dbgemptyqc, ref dbgnonbindingrows, ref dbgnonbindingqc, _params) )
                {
                    return;
                }
                if( !singletonrowtobc(bndl, bndu, vcstats, n, a, at, al, au, m, eps, dotrace, presolved.buf, presolved.trfstack, ref presolved.problemstatus, ref somethingchanged, ref dbgsingletonrow, _params) )
                {
                    return;
                }
                if( !doubletonrow(c, bndl, bndu, vcstats, sparseh, hash, n, a, at, al, au, m, qc, normxcc, eps, dotrace, presolved.buf, presolved.trfstack, ref presolved.problemstatus, ref somethingchanged, ref dbgdoubletonrow, _params) )
                {
                    return;
                }
                if( !fixvariables(c, bndl, bndu, vcstats, sparseh, hash, n, a, at, al, au, m, qc, normxcc, eps, dotrace, presolved.buf, presolved.trfstack, ref presolved.problemstatus, ref somethingchanged, ref dbgfixed, _params) )
                {
                    return;
                }
                if( !singletoncols(c, bndl, bndu, vcstats, sparseh, hash, n, a, at, al, au, m, eps, dotrace, presolved.buf, presolved.trfstack, ref presolved.problemstatus, ref somethingchanged, ref dbgslackvars, ref dbgimplicitslacks, ref dbgfreecolumnsingletons, _params) )
                {
                    return;
                }
                presolverounds = presolverounds+1;
            }
            
            //
            // Integrity checks
            // * A and AT have the same number of elements (we do not check actual elements, only their total count)
            // * VCStats.NLCPerVar is zero after we subtract all non-dropped constraints
            //
            if( m>0 )
            {
                j0 = 0;
                for(j=0; j<=m-1; j++)
                {
                    j0 = j0+(a.rowend[j]-a.rowbegin[j]);
                }
                j1 = 0;
                for(j=0; j<=n-1; j++)
                {
                    j1 = j1+(at.rowend[j]-at.rowbegin[j]);
                }
                alglib.ap.assert(j0==j1, "PRESOLVER: integrity check 4347 failed");
            }
            for(i=0; i<=n-1; i++)
            {
                alglib.ap.assert(vcstats.nlcpervar[i]==apstruct.kniscountkth(vcstats.varbyqc, i, _params)+apstruct.kniscountkth(vcstats.varbycc, i, _params), "PRESOLVER: integrity check 566152 failed");
            }
            for(i=0; i<=mqc-1; i++)
            {
                if( vcstats.isdroppedqc[i] )
                {
                    continue;
                }
                qc.constraints.get(i, ref qci);
                for(j=0; j<=qci.nvars-1; j++)
                {
                    if( vcstats.isdroppedcol[qci.varidx[j]] )
                    {
                        alglib.ap.assert(false, "PRESOLVER: integrity check 2602 failed");
                    }
                    vcstats.nlcpervar[qci.varidx[j]] = vcstats.nlcpervar[qci.varidx[j]]-1;
                }
            }
            for(i=0; i<=mcc-1; i++)
            {
                if( vcstats.isdroppedcc[i] )
                {
                    continue;
                }
                normxcc.constraints.get(i, ref cci);
                for(j=0; j<=cci.nvars-1; j++)
                {
                    if( vcstats.isdroppedcol[cci.varidx[j]] )
                    {
                        alglib.ap.assert(false, "PRESOLVER: integrity check 529049 failed");
                    }
                    vcstats.nlcpervar[cci.varidx[j]] = vcstats.nlcpervar[cci.varidx[j]]-1;
                }
            }
            for(i=0; i<=n-1; i++)
            {
                if( vcstats.nlcpervar[i]!=0 )
                {
                    alglib.ap.assert(false, "PRESOLVER: integrity check 3303 failed");
                }
            }
            
            //
            // Output data that are permuted by XPerm[]
            //
            presolved.oldn = n;
            presolved.newn = 0;
            ablasf.isetallocv(n, -1, ref presolved.packxperm, _params);
            ablasf.isetallocv(n, -1, ref presolved.unpackxperm, _params);
            for(i=0; i<=n-1; i++)
            {
                if( !vcstats.isdroppedcol[i] )
                {
                    presolved.unpackxperm[presolved.newn] = i;
                    presolved.packxperm[i] = presolved.newn;
                    presolved.newn = presolved.newn+1;
                }
            }
            ablasf.rallocv(presolved.newn, ref presolved.bndl, _params);
            ablasf.rallocv(presolved.newn, ref presolved.bndu, _params);
            ablasf.rallocv(presolved.newn, ref presolved.c, _params);
            for(i=0; i<=presolved.newn-1; i++)
            {
                presolved.c[i] = c[presolved.unpackxperm[i]];
                presolved.bndl[i] = bndl[presolved.unpackxperm[i]];
                presolved.bndu[i] = bndu[presolved.unpackxperm[i]];
            }
            if( hash )
            {
                presolved.sparseh.n = presolved.newn;
                presolved.sparseh.m = presolved.newn;
                ablasf.iallocv(presolved.newn+1, ref presolved.sparseh.ridx, _params);
                presolved.sparseh.ridx[0] = 0;
                for(i=0; i<=presolved.newn-1; i++)
                {
                    offs = presolved.sparseh.ridx[i];
                    ablasf.igrowv(offs+n, ref presolved.sparseh.idx, _params);
                    ablasf.rgrowv(offs+n, ref presolved.sparseh.vals, _params);
                    k = presolved.unpackxperm[i];
                    j0 = sparseh.rowbegin[k];
                    j1 = sparseh.rowend[k]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = presolved.packxperm[sparseh.idx[jj]];
                        if( j<0 || j>i )
                        {
                            continue;
                        }
                        presolved.sparseh.idx[offs] = j;
                        presolved.sparseh.vals[offs] = sparseh.vals[jj];
                        offs = offs+1;
                    }
                    presolved.sparseh.ridx[i+1] = offs;
                }
                sparse.sparsecreatecrsinplace(presolved.sparseh, _params);
            }
            
            //
            // Output data that are permuted by YPerm[]
            //
            presolved.oldm = m;
            presolved.newm = 0;
            ablasf.isetallocv(m, -1, ref presolved.packyperm, _params);
            ablasf.isetallocv(m, -1, ref presolved.unpackyperm, _params);
            for(i=0; i<=m-1; i++)
            {
                if( !vcstats.isdroppedlc[i] )
                {
                    presolved.unpackyperm[presolved.newm] = i;
                    presolved.packyperm[i] = presolved.newm;
                    presolved.newm = presolved.newm+1;
                }
            }
            ablasf.rallocv(presolved.newm, ref presolved.al, _params);
            ablasf.rallocv(presolved.newm, ref presolved.au, _params);
            for(i=0; i<=presolved.newm-1; i++)
            {
                presolved.al[i] = al[presolved.unpackyperm[i]];
                presolved.au[i] = au[presolved.unpackyperm[i]];
            }
            
            //
            // Output A which is permuted by both XPerm[] and YPerm[]
            //
            presolved.sparsea.m = 0;
            presolved.sparsea.n = presolved.newn;
            ablasf.iallocv(presolved.newm+1, ref presolved.sparsea.ridx, _params);
            presolved.sparsea.ridx[0] = 0;
            for(i=0; i<=m-1; i++)
            {
                if( !vcstats.isdroppedlc[i] )
                {
                    offs = presolved.sparsea.ridx[presolved.sparsea.m];
                    ablasf.igrowv(offs+n, ref presolved.sparsea.idx, _params);
                    ablasf.rgrowv(offs+n, ref presolved.sparsea.vals, _params);
                    j0 = a.rowbegin[i];
                    j1 = a.rowend[i]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = presolved.packxperm[a.idx[jj]];
                        alglib.ap.assert(j>=0, "PRESOLVE: integrity check 54fc failed");
                        presolved.sparsea.idx[offs] = j;
                        presolved.sparsea.vals[offs] = a.vals[jj];
                        offs = offs+1;
                    }
                    presolved.sparsea.m = presolved.sparsea.m+1;
                    presolved.sparsea.ridx[presolved.sparsea.m] = offs;
                }
            }
            alglib.ap.assert(presolved.sparsea.m==presolved.newm, "PRESOLVE: integrity check ee3a failed");
            sparse.sparsecreatecrsinplace(presolved.sparsea, _params);
            
            //
            // Output data permuted by QCPerm[] and XPerm[]
            //
            presolved.xqc.n = n;
            presolved.xqc.constraints.clear();
            presolved.oldmqc = mqc;
            presolved.newmqc = 0;
            ablasf.isetallocv(mqc, -1, ref presolved.packqcperm, _params);
            ablasf.isetallocv(mqc, -1, ref presolved.unpackqcperm, _params);
            for(i=0; i<=mqc-1; i++)
            {
                if( !vcstats.isdroppedqc[i] )
                {
                    presolved.unpackqcperm[presolved.newmqc] = i;
                    presolved.packqcperm[i] = presolved.newmqc;
                    presolved.newmqc = presolved.newmqc+1;
                    qc.constraints.get(i, ref qci);
                    xqci = new opts.xquadraticconstraint();
                    dynqcpermtoxqc(qci, presolved.packxperm, presolved.unpackxperm, xqci, _params);
                    presolved.xqc.constraints.append(xqci);
                }
            }
            
            //
            // Output data permuted by CCPerm and XPerm
            //
            presolved.oldmcc = mcc;
            presolved.newmcc = 0;
            ablasf.isetallocv(mcc, -1, ref presolved.packccperm, _params);
            ablasf.isetallocv(mcc, -1, ref presolved.unpackccperm, _params);
            for(i=0; i<=mcc-1; i++)
            {
                if( !vcstats.isdroppedcc[i] )
                {
                    presolved.unpackccperm[presolved.newmcc] = i;
                    presolved.packccperm[i] = presolved.newmcc;
                    presolved.newmcc = presolved.newmcc+1;
                }
            }
            optserv.xcccopywithskipandpack(normxcc, vcstats.isdroppedcc, presolved.packxperm, presolved.xcc, _params);
            alglib.ap.assert(presolved.newmcc==optserv.xccgetcount(presolved.xcc, _params), "PRESOLVER: integrity check 682108 failed");
            
            //
            // Prepare permutation for constraint Stats[]
            //
            ablasf.isetallocv(n+m, -1, ref presolved.packstatperm, _params);
            ablasf.isetallocv(n+m, -1, ref presolved.unpackstatperm, _params);
            offs = 0;
            for(i=0; i<=n-1; i++)
            {
                if( !vcstats.isdroppedcol[i] )
                {
                    presolved.packstatperm[i] = offs;
                    offs = offs+1;
                }
            }
            for(i=0; i<=m-1; i++)
            {
                if( !vcstats.isdroppedlc[i] )
                {
                    presolved.packstatperm[n+i] = offs;
                    offs = offs+1;
                }
            }
            alglib.ap.assert(offs==presolved.newn+presolved.newm, "PRESOLVE: integrity check 3632 failed");
            for(i=0; i<=n+m-1; i++)
            {
                if( presolved.packstatperm[i]>=0 )
                {
                    presolved.unpackstatperm[presolved.packstatperm[i]] = i;
                }
            }
            
            //
            // Trace output
            //
            if( dotrace )
            {
                alglib.ap.trace(System.String.Format("done in {0,0:d} rounds\n\n", presolverounds));
                alglib.ap.trace("----- printing information about reductions --------------------------------------------------------\n");
                alglib.ap.trace(System.String.Format("fixed vars           = {0,10:d} (fixed variables)\n", dbgfixed));
                alglib.ap.trace(System.String.Format("empty cols           = {0,10:d} (empty constraint columns)\n", dbgemptycol));
                alglib.ap.trace(System.String.Format("empty rows           = {0,10:d} (empty constraint rows)\n", dbgemptyrow));
                alglib.ap.trace(System.String.Format("empty QC             = {0,10:d} (empty quadratic constraints)\n", dbgemptyqc));
                alglib.ap.trace(System.String.Format("nonbinding rows      = {0,10:d} (irrelevant LC due to bounds)\n", dbgnonbindingrows));
                alglib.ap.trace(System.String.Format("nonbinding QC        = {0,10:d} (irrelevant QC due to bounds)\n", dbgnonbindingqc));
                alglib.ap.trace(System.String.Format("singleton rows       = {0,10:d} (singleton rows converted to box constraints)\n", dbgsingletonrow));
                alglib.ap.trace(System.String.Format("doubleton rows       = {0,10:d} (doubleton equality constraints used to factor out variables)\n", dbgdoubletonrow));
                alglib.ap.trace(System.String.Format("slack variables      = {0,10:d} (singleton cols with zero cost, recognized as explicit slacks)\n", dbgslackvars));
                alglib.ap.trace(System.String.Format("implicit slacks      = {0,10:d} (singleton cols at equality rows, recognized as implicit slacks)\n", dbgimplicitslacks));
                alglib.ap.trace(System.String.Format("free col singletons  = {0,10:d} (free singleton columns)\n", dbgfreecolumnsingletons));
                alglib.ap.trace("----- printing output problem metrics --------------------------------------------------------------\n");
                alglib.ap.trace(System.String.Format("N            = {0,10:d} (variables)\n", presolved.newn));
                alglib.ap.trace(System.String.Format("M            = {0,10:d} (constraints)\n", presolved.newm));
                alglib.ap.trace(System.String.Format("MQC          = {0,10:d} (quadratic constraints)\n", presolved.newmqc));
                if( m!=0 )
                {
                    alglib.ap.trace(System.String.Format("nz(A)        = {0,10:d} (nonzeros in A)\n", presolved.sparsea.ridx[presolved.sparsea.m]));
                }
            }
        }


        /*************************************************************************
        Forward transformation which transforms a set of original variables (e.g.
        an initial point) to the converted problem format.

        INPUT PARAMETERS:
            Info        -   presolve info structure
            X           -   array[NOld], original point
                            
        OUTPUT PARAMETERS:
            X           -   array[NNew], transformed point
            
        NOTE: this routine does not reallocate arrays if NOld<=NNew and/or KOld<=KNew.

          -- ALGLIB --
             Copyright 01.07.2020 by Bochkanov Sergey
        *************************************************************************/
        public static void presolvefwd(presolveinfo s,
            ref double[] xx,
            alglib.xparams _params)
        {
            int tidx = 0;
            int tt = 0;
            int i = 0;
            int k = 0;
            double v = 0;

            ablasf.rcopyallocv(s.oldn, xx, ref s.x1, _params);
            for(tidx=0; tidx<=s.trfstack.ntrf-1; tidx++)
            {
                tt = s.trfstack.trftype[tidx];
                if( tt==pstobjectivescaling )
                {
                    continue;
                }
                if( tt==pstcolscaling )
                {
                    
                    //
                    // Column scaling
                    //
                    presolverselectstreamsource(s.trfstack, tidx, _params);
                    presolverunstreamir(s.trfstack, ref k, ref v, _params);
                    presolverasserteos(s.trfstack, _params);
                    s.x1[k] = s.x1[k]*v;
                    continue;
                }
                if( tt==pstcolshifting )
                {
                    
                    //
                    // Variable shifting
                    //
                    presolverselectstreamsource(s.trfstack, tidx, _params);
                    presolverunstreamir(s.trfstack, ref k, ref v, _params);
                    presolverasserteos(s.trfstack, _params);
                    s.x1[k] = s.x1[k]+v;
                    continue;
                }
                if( tt==pstrowscaling )
                {
                    continue;
                }
                if( tt==pstqcscaling )
                {
                    continue;
                }
                if( tt==pstdropemptycol )
                {
                    continue;
                }
                if( tt==pstdropemptyrow )
                {
                    continue;
                }
                if( tt==pstdropemptyqc )
                {
                    continue;
                }
                if( tt==pstsingletonrow )
                {
                    continue;
                }
                if( tt==pstfixedvar )
                {
                    continue;
                }
                if( tt==pstexplicitslack )
                {
                    continue;
                }
                if( tt==pstimplicitslack )
                {
                    continue;
                }
                if( tt==pstdoubletoneq )
                {
                    continue;
                }
                alglib.ap.assert(false, "PresolverFwd: unexpected transform type");
            }
            ablasf.rallocv(s.newn, ref xx, _params);
            for(i=0; i<=s.newn-1; i++)
            {
                xx[i] = s.x1[s.unpackxperm[i]];
            }
        }


        /*************************************************************************
        Backward transformation which extracts original solution from that of  the
        converted problem.

        Below NNew/KNew correspond to transformed problem size (as returned by the
        presolve routine) and NOld/KOld correspond to original  problem  size  (as
        specified by caller). We expect that caller knows  these  sizes,  so  this
        routine does not report them.

        INPUT PARAMETERS:
            Info        -   presolve info structure
            X           -   array[NNew], transformed solution (primal variables)
            Stats       -   array[NNew+MNew], transformed constraint status (negative -
                            at lower bound, positive -  at  upper  bound,  zero  -
                            inactive).
            LagBC       -   array[NNew], transformed Lagrange multipliers
            LagLC       -   array[KNew], transformed Lagrange multipliers
            LagQC       -   array[MQCNew], transformed Lagrange multipliers
                            
        OUTPUT PARAMETERS:
            X           -   array[NOld], original solution (primal variables)
            Stats       -   array[NOld+MOld], original constraint status
            LagBC       -   array[NOld], Lagrange multipliers
            LagLC       -   array[KOld], Lagrange multipliers
            LagQC       -   array[MQCOld], transformed Lagrange multipliers
            
        NOTE: this routine does not reallocate arrays if NOld<=NNew and/or KOld<=KNew.

          -- ALGLIB --
             Copyright 01.07.2020 by Bochkanov Sergey
        *************************************************************************/
        public static void presolvebwd(presolveinfo info,
            ref double[] x,
            ref int[] stats,
            bool needstats,
            ref double[] lagbc,
            ref double[] laglc,
            ref double[] lagqc,
            alglib.xparams _params)
        {
            int i = 0;

            
            //
            // Read state of the transformed problem into storage allocated for the original problem
            //
            if( needstats )
            {
                ablasf.isetallocv(info.oldn+info.oldm, 0, ref info.s1, _params);
                for(i=0; i<=info.newn+info.newm-1; i++)
                {
                    info.s1[info.unpackstatperm[i]] = stats[i];
                }
            }
            ablasf.rsetallocv(info.oldn, 0.0, ref info.x1, _params);
            for(i=0; i<=info.newn-1; i++)
            {
                info.x1[info.unpackxperm[i]] = x[i];
            }
            ablasf.rsetallocv(info.oldn, 0.0, ref info.bc1, _params);
            for(i=0; i<=info.newn-1; i++)
            {
                info.bc1[info.unpackxperm[i]] = lagbc[i];
            }
            ablasf.rsetallocv(info.oldm, 0.0, ref info.y1, _params);
            for(i=0; i<=info.newm-1; i++)
            {
                info.y1[info.unpackyperm[i]] = laglc[i];
            }
            ablasf.rsetallocv(info.oldmqc, 0.0, ref info.yqc, _params);
            for(i=0; i<=info.newmqc-1; i++)
            {
                info.yqc[info.unpackqcperm[i]] = lagqc[i];
            }
            
            //
            // Apply reverse transformation
            //
            presolverrestoresolution(info.trfstack, info.x1, info.bc1, info.y1, info.yqc, info.s1, needstats, info.eps, _params);
            
            //
            // Polish X according to box constraints and info from newly recovered Stats[]
            // Recompute coefficients corresponding to variables fixed during presolve using residual costs.
            //
            for(i=0; i<=info.oldn-1; i++)
            {
                if( math.isfinite(info.rawbndl[i]) )
                {
                    info.x1[i] = Math.Max(info.x1[i], info.rawbndl[i]);
                }
                if( math.isfinite(info.rawbndu[i]) )
                {
                    info.x1[i] = Math.Min(info.x1[i], info.rawbndu[i]);
                }
                if( needstats )
                {
                    if( info.s1[i]<0 )
                    {
                        info.x1[i] = info.rawbndl[i];
                    }
                    if( info.s1[i]>0 )
                    {
                        info.x1[i] = info.rawbndu[i];
                    }
                }
            }
            ablasf.rcopyallocv(info.oldn, info.rawc, ref info.d, _params);
            if( info.oldm>0 )
            {
                sparse.sparsegemv(info.rawa, 1.0, 1, info.y1, 0, 1.0, info.d, 0, _params);
            }
            for(i=0; i<=info.oldn-1; i++)
            {
                if( info.lagrangefromresidual[i] )
                {
                    info.bc1[i] = -info.d[i];
                }
            }
            
            //
            // Output
            //
            ablasf.rcopyallocv(info.oldn, info.x1, ref x, _params);
            ablasf.rcopyallocv(info.oldmqc, info.yqc, ref lagqc, _params);
            ablasf.rcopyallocv(info.oldm, info.y1, ref laglc, _params);
            if( needstats )
            {
                ablasf.icopyallocv(info.oldn+info.oldm, info.s1, ref stats, _params);
            }
            ablasf.rcopyallocv(info.oldn, info.bc1, ref lagbc, _params);
        }


        /*************************************************************************
        Returns true if both bounds are finite and the difference is less than Eps.

        Used to provide consistent way of checking for fixed vars across the unit.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static bool isfixed(double bndl,
            double bndu,
            double eps,
            alglib.xparams _params)
        {
            bool result = new bool();

            result = (math.isfinite(bndl) && math.isfinite(bndu)) && (double)(bndl)>=(double)(bndu-eps);
            return result;
        }


        /*************************************************************************
        Initialize dynamic-CRS-based quadratic constraints from the standard ones

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void dynqcinitfromxqc(opts.xquadraticconstraints src,
            dynamiccrsqconstraints dst,
            alglib.xparams _params)
        {
            int i = 0;
            int cnt = 0;
            int nv = 0;
            opts.xquadraticconstraint qcsrc = null;
            dynamiccrsqconstraint qcdst = null;
            sparse.sparsematrix fullq = new sparse.sparsematrix();

            cnt = opts.xqcgetcount(src, _params);
            dst.constraints.clear();
            for(i=0; i<=cnt-1; i++)
            {
                src.constraints.get(i, ref qcsrc);
                qcdst = new dynamiccrsqconstraint();
                nv = qcsrc.nvars;
                qcdst.nvars = nv;
                qcdst.cl = qcsrc.cl;
                qcdst.cu = qcsrc.cu;
                qcdst.applyorigin = qcsrc.applyorigin;
                if( nv>0 )
                {
                    ablasf.icopyallocv(nv, qcsrc.varidx, ref qcdst.varidx, _params);
                    ablasf.rcopyallocv(nv, qcsrc.b, ref qcdst.b, _params);
                    copyexpandh(qcsrc.lowerq, false, fullq, _params);
                    dyncrs.dyncrsinitfromsparsecrs(fullq, qcdst.fullq, _params);
                }
                dst.constraints.append(qcdst);
            }
        }


        /*************************************************************************
        Copy structure

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void dynqccopy(dynamiccrsqconstraint src,
            dynamiccrsqconstraint dst,
            alglib.xparams _params)
        {
            dst.nvars = src.nvars;
            ablasf.icopyallocv(src.nvars, src.varidx, ref dst.varidx, _params);
            ablasf.rcopyallocv(src.nvars, src.b, ref dst.b, _params);
            dyncrs.dyncrscopy(src.fullq, dst.fullq, _params);
            dst.cl = src.cl;
            dst.cu = src.cu;
            dst.applyorigin = src.applyorigin;
        }


        /*************************************************************************
        Copies quadratic constraint with insertion of variable VIdx into  position
        InsertPos, with 0<=InsertPos<=NVars. Variables at position  InsertPos  and
        past it are shifted to the right.

        The function checks that Src.VarIdx[InsertPos-1]<VIdx<Src.VarIdx[InsertPos].

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void dynqccopyinsertrowcol(dynamiccrsqconstraint src,
            int vidx,
            int insertpos,
            dynamiccrsqconstraint dst,
            alglib.xparams _params)
        {
            int i = 0;
            int offs = 0;

            alglib.ap.assert(insertpos>=0 && insertpos<=src.nvars, "dynqcCopyInsertRowCol: incorrect InsertPos");
            alglib.ap.assert(insertpos==0 || src.varidx[insertpos-1]<vidx, "dynqcCopyInsertRowCol: VIdx is out of order (left)");
            alglib.ap.assert(insertpos==src.nvars || src.varidx[insertpos]>vidx, "dynqcCopyInsertRowCol: VIdx is out of order (right)");
            dst.nvars = src.nvars+1;
            dst.cl = src.cl;
            dst.cu = src.cu;
            dst.applyorigin = src.applyorigin;
            ablasf.iallocv(dst.nvars, ref dst.varidx, _params);
            ablasf.rallocv(dst.nvars, ref dst.b, _params);
            offs = 0;
            for(i=0; i<=src.nvars; i++)
            {
                if( i==insertpos )
                {
                    dst.varidx[offs] = vidx;
                    dst.b[offs] = 0.0;
                    offs = offs+1;
                }
                if( i<src.nvars )
                {
                    dst.varidx[offs] = src.varidx[i];
                    dst.b[offs] = src.b[i];
                    offs = offs+1;
                }
            }
            alglib.ap.assert(offs==dst.nvars, "PRESOLVER: integrity check 4228 failed");
            dyncrs.dyncrscopyinsertrowcol(src.fullq, insertpos, dst.fullq, _params);
        }


        /*************************************************************************
        Copies quadratic constraint with deletion of variable at position DeletePos,
        with 0<=DeletePos<NVars. Variables at the position DeletePos and  past  it
        are shifted to the left. If NVars=1, then an empty quadratic constraint is
        correctly created.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void dynqccopydeleterowcol(dynamiccrsqconstraint src,
            int deletepos,
            dynamiccrsqconstraint dst,
            alglib.xparams _params)
        {
            int i = 0;
            int offs = 0;

            alglib.ap.assert(deletepos>=0 && deletepos<src.nvars, "dynqcCopyDeleteRowCol: incorrect DeletePos");
            dst.nvars = src.nvars-1;
            dst.cl = src.cl;
            dst.cu = src.cu;
            dst.applyorigin = src.applyorigin;
            if( dst.nvars==0 )
            {
                dst.fullq.n = 0;
                dst.fullq.m = 0;
                return;
            }
            ablasf.iallocv(dst.nvars, ref dst.varidx, _params);
            ablasf.rallocv(dst.nvars, ref dst.b, _params);
            offs = 0;
            for(i=0; i<=src.nvars-1; i++)
            {
                if( i!=deletepos )
                {
                    dst.varidx[offs] = src.varidx[i];
                    dst.b[offs] = src.b[i];
                    offs = offs+1;
                }
            }
            dyncrs.dyncrscopydeleterowcol(src.fullq, deletepos, dst.fullq, _params);
        }


        /*************************************************************************
        Copies quadratic constraint with deletion of  variables  DeleteSet  and  a
        corresponding shifts to the left in variables indexes.

        If NVars=|DeleteSet|, then an empty quadratic constraint is correctly created.

        Buf must be a preallocated array, with at least Src.NVars elements.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void dynqccopydeleterowscols(dynamiccrsqconstraint src,
            apstruct.niset deleteset,
            dynamiccrsqconstraint dst,
            int[] buf,
            alglib.xparams _params)
        {
            int i = 0;
            int offs = 0;

            alglib.ap.assert(alglib.ap.len(buf)>=src.nvars, "dynqcCopyDeleteRowsCols: buf is too short");
            alglib.ap.assert(deleteset.nstored>=0 && deleteset.nstored<=src.nvars, "dynqcCopyDeleteRowsCols: incorrect DeletePos");
            for(i=0; i<=deleteset.nstored-1; i++)
            {
                alglib.ap.assert(deleteset.items[i]>=0 && deleteset.items[i]<src.nvars, "dynqcCopyDeleteRowsCols: items in DeleteSet are outside of [0,NVars) range");
            }
            dst.nvars = src.nvars-deleteset.nstored;
            dst.cl = src.cl;
            dst.cu = src.cu;
            dst.applyorigin = src.applyorigin;
            if( dst.nvars==0 )
            {
                dst.fullq.n = 0;
                dst.fullq.m = 0;
                return;
            }
            ablasf.iallocv(dst.nvars, ref dst.varidx, _params);
            ablasf.rallocv(dst.nvars, ref dst.b, _params);
            offs = 0;
            for(i=0; i<=src.nvars-1; i++)
            {
                if( deleteset.locationof[i]<0 )
                {
                    dst.varidx[offs] = src.varidx[i];
                    dst.b[offs] = src.b[i];
                    offs = offs+1;
                }
            }
            dyncrs.dyncrscopydeleterowscols(src.fullq, deleteset, dst.fullq, buf, _params);
        }


        /*************************************************************************
        Factors out variable K0 from a  quadratic  form  c'x + 0.5x'Hx by making a
        substitution X[k0]:=alpha0 + alpha1*X[k1]  and  correspondingly  rewriting
        c and H.

        Returns constant term that is produced as a result of such a transformation.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double factoroutfromquadratic(dyncrs.dynamiccrs h,
            double[] c,
            int k0,
            double alpha0,
            double alpha1,
            int k1,
            alglib.xparams _params)
        {
            double result = 0;
            double h00 = 0;
            double h11 = 0;
            double h01 = 0;
            double v = 0;
            double v0 = 0;
            double v1 = 0;
            int ii = 0;
            int j = 0;

            result = 0;
            
            //
            // Modify linear term with an update to C[K1] from C[K0]
            //
            c[k1] = c[k1]+c[k0]*alpha1;
            result = result+c[k0]*alpha0;
            c[k0] = 0;
            
            //
            // Handle updates coming from the quadratic term
            //
            // Analyze how 2x2 quadratic [h00 h01 ; h10 h11] changes when we
            // substitute x0 := alpha0 + alpha1*x1.
            //
            // We have
            //
            //     h00*(alpha0+alpha1*x1)^2 + 2*h01*(alpha0+alpha1*x1)*x1 + h11*x1^2 =
            //     h00*alpha0^2 + 2*h00*alpha0*alpha1*x1 + h00*alpha1^2*x1^2   +   2*h01*alpha0*x1+2*h01*alpha1*x1^2 + h11*x1^2 =
            //     h00*alpha0^2 + 2*(h00*alpha0*alpha1+h01*alpha0)*x1 + (h00*alpha1^2+2*h01*alpha1+h11)*x1^2
            //
            h00 = dyncrs.dyncrsgetexistingelement(h, k0, k0, _params);
            h11 = dyncrs.dyncrsgetexistingelement(h, k1, k1, _params);
            h01 = dyncrs.dyncrsgetelementifexists(h, k0, k1, _params);
            
            //
            // Handle updates coming from modification of elements of H that are outside of the
            // [k0,k1]x[k0,k1] diagonal block. The constant term in X[K0]:=Alpha0+Alpha1*X[K1]
            // updates the linear term C[], the linear term Alpha1 updates the matrix H.
            //
            // The matrix H is updates applied to its column K1, then to its row K1. The row update
            // modifies the [k0,k1]x[k0,k1] diagonal block because there is no easy way to do it
            // without touching elements that we want to process later. We handle it by saving
            // H00, H01, H11 prior to this block and by discarding and rewriting diagonal completely
            // after calling DynCRSAddRowTo().
            //
            for(ii=h.rowbegin[k0]; ii<=h.rowend[k0]-1; ii++)
            {
                j = h.idx[ii];
                if( j!=k0 && j!=k1 )
                {
                    
                    //
                    // Update C[] and column K1 of H.
                    //
                    v = h.vals[ii];
                    c[j] = c[j]+v*alpha0;
                    dyncrs.dyncrsfactoroutfromrow(h, j, k0, 0.0, alpha1, k1, false, ref v0, ref v1, _params);
                }
            }
            dyncrs.dyncrsaddrowto(h, k0, alpha1, k1, true, false, _params);
            dyncrs.dyncrsclearrow(h, k0, _params);
            dyncrs.dyncrsremovefromrow(h, k1, k0, _params);
            
            //
            // Handle updates coming from substituting X[K0]:=Alpha0+Alpha1*X[K1] to the
            // [k0,k1]x[k0,k1] diagonal block.
            //
            result = result+0.5*h00*alpha0*alpha0;
            c[k1] = c[k1]+(h00*alpha0*alpha1+h01*alpha0);
            dyncrs.dyncrssetexistingelement(h, k1, k1, h00*alpha1*alpha1+2*h01*alpha1+h11, _params);
            return result;
        }


        /*************************************************************************
        Fixed single variable at the quadratic form c'x + 0.5x'Hx and correspondingly
        rewrites c and H, clearing entries (but not removing them).

        Returns constant term that is produced as a result of such a transformation.

          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static double fixquadraticvariable(dyncrs.dynamiccrs h,
            double[] c,
            int fixidx,
            double fixval,
            alglib.xparams _params)
        {
            double result = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int j = 0;
            int n = 0;

            alglib.ap.assert(h.n==h.m, "PRESOLVER: integrity check 5812 failed");
            alglib.ap.assert(fixidx>=0 && fixidx<h.n, "PRESOLVER: integrity check 5813 failed");
            result = 0;
            n = h.n;
            if( n==0 )
            {
                return result;
            }
            
            //
            // Modify linear term
            //
            result = result+c[fixidx]*fixval;
            c[fixidx] = 0.0;
            
            //
            // Modify quadratic term: scan FixIdx-th row, for each off-diagonal element found
            // clear (set to zero) corresponding element from FixIdx-th column
            //
            j0 = h.rowbegin[fixidx];
            j1 = h.rowend[fixidx]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                j = h.idx[jj];
                if( j!=fixidx )
                {
                    
                    //
                    // Offdiagonal element
                    //
                    c[j] = c[j]+h.vals[jj]*fixval;
                    h.vals[jj] = 0.0;
                    h.vals[apserv.ibinarysearchexisting(h.idx, h.rowbegin[j], h.rowend[j], fixidx, _params)] = 0.0;
                }
                else
                {
                    
                    //
                    // Diagonal element
                    //
                    result = result+0.5*h.vals[jj]*fixval*fixval;
                    h.vals[jj] = 0.0;
                }
            }
            return result;
        }


        /*************************************************************************
        convert single quadratic constraint between formats


          -- ALGLIB --
             Copyright 01.07.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void dynqcpermtoxqc(dynamiccrsqconstraint src,
            int[] packxperm,
            int[] unpackxperm,
            opts.xquadraticconstraint dst,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int offs = 0;
            int nv = 0;
            int jprev = 0;

            nv = src.nvars;
            dst.nvars = nv;
            dst.cl = src.cl;
            dst.cu = src.cu;
            dst.applyorigin = src.applyorigin;
            if( nv>0 )
            {
                ablasf.iallocv(nv, ref dst.varidx, _params);
                for(i=0; i<=nv-1; i++)
                {
                    dst.varidx[i] = packxperm[src.varidx[i]];
                }
                for(i=0; i<=nv-2; i++)
                {
                    alglib.ap.assert(dst.varidx[i]<dst.varidx[i+1], "PRESOLVER: integrity check 1658 failed");
                }
                ablasf.rcopyallocv(nv, src.b, ref dst.b, _params);
                dst.lowerq.matrixtype = 1;
                dst.lowerq.m = nv;
                dst.lowerq.n = nv;
                ablasf.iallocv(nv, ref dst.lowerq.didx, _params);
                ablasf.iallocv(nv, ref dst.lowerq.uidx, _params);
                ablasf.iallocv(nv+1, ref dst.lowerq.ridx, _params);
                dst.lowerq.ridx[0] = 0;
                for(i=0; i<=nv-1; i++)
                {
                    offs = dst.lowerq.ridx[i];
                    ablasf.igrowv(offs+nv, ref dst.lowerq.idx, _params);
                    ablasf.rgrowv(offs+nv, ref dst.lowerq.vals, _params);
                    jprev = -1;
                    j0 = src.fullq.rowbegin[i];
                    j1 = src.fullq.rowend[i]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = src.fullq.idx[jj];
                        if( j<=jprev )
                        {
                            alglib.ap.assert(false, "PRESOLVER: integrity check 381649 failed");
                        }
                        jprev = j;
                        if( j>i )
                        {
                            continue;
                        }
                        dst.lowerq.idx[offs] = j;
                        dst.lowerq.vals[offs] = src.fullq.vals[jj];
                        offs = offs+1;
                    }
                    alglib.ap.assert(offs>dst.lowerq.ridx[i] && dst.lowerq.idx[offs-1]==i, "PRESOLVER: integrity check 389651 failed");
                    dst.lowerq.didx[i] = offs-1;
                    dst.lowerq.uidx[i] = offs;
                    dst.lowerq.ridx[i+1] = offs;
                }
                dst.lowerq.ninitialized = dst.lowerq.ridx[nv];
            }
        }


        /*************************************************************************
        Initialize presolver stack

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverstackinit(int n,
            int m,
            int mqc,
            int mcc,
            presolverstack s,
            alglib.xparams _params)
        {
            s.n = n;
            s.m = m;
            s.mqc = mqc;
            s.mcc = mcc;
            s.ntrf = 0;
            ablasf.isetallocv(1, 0, ref s.idataridx, _params);
            ablasf.isetallocv(1, 0, ref s.rdataridx, _params);
        }


        /*************************************************************************
        Streams boolean value to the presolver stack data storage (the data
        are appended to the last transform on top of the stack).

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverstreamb(presolverstack s,
            bool b,
            alglib.xparams _params)
        {
            int ilast = 0;

            ilast = s.idataridx[s.ntrf];
            ablasf.igrowv(ilast+1, ref s.idata, _params);
            s.idata[ilast] = apserv.icase2(b, 1, 0, _params);
            s.idataridx[s.ntrf] = ilast+1;
        }


        /*************************************************************************
        Streams integer value to the presolver stack data storage (the data
        are appended to the last transform on top of the stack).

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverstreami(presolverstack s,
            int i,
            alglib.xparams _params)
        {
            int ilast = 0;

            ilast = s.idataridx[s.ntrf];
            ablasf.igrowv(ilast+1, ref s.idata, _params);
            s.idata[ilast] = i;
            s.idataridx[s.ntrf] = ilast+1;
        }


        /*************************************************************************
        Streams real value to the presolver stack data storage (the data
        are appended to the last transform on top of the stack).

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverstreamr(presolverstack s,
            double v,
            alglib.xparams _params)
        {
            int rlast = 0;

            rlast = s.rdataridx[s.ntrf];
            ablasf.rgrowv(rlast+1, ref s.rdata, _params);
            s.rdata[rlast] = v;
            s.rdataridx[s.ntrf] = rlast+1;
        }


        /*************************************************************************
        Streams a integer/real pair to the presolver stack data storage (the data
        are appended to the last transform on top of the stack).

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverstreamir(presolverstack s,
            int i,
            double v,
            alglib.xparams _params)
        {
            int ilast = 0;
            int rlast = 0;

            ilast = s.idataridx[s.ntrf];
            rlast = s.rdataridx[s.ntrf];
            ablasf.igrowv(ilast+1, ref s.idata, _params);
            ablasf.rgrowv(rlast+1, ref s.rdata, _params);
            s.idata[ilast] = i;
            s.rdata[rlast] = v;
            s.idataridx[s.ntrf] = ilast+1;
            s.rdataridx[s.ntrf] = rlast+1;
        }


        /*************************************************************************
        Streams DynamicCRS row.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverstreamcrsrow(presolverstack s,
            dyncrs.dynamiccrs a,
            int i,
            alglib.xparams _params)
        {
            int k = 0;

            presolverstreami(s, a.rowend[i]-a.rowbegin[i], _params);
            for(k=a.rowbegin[i]; k<=a.rowend[i]-1; k++)
            {
                presolverstreamir(s, a.idx[k], a.vals[k], _params);
            }
        }


        /*************************************************************************
        Streams DynamicCRS row, except for element in the column NotIdx (if such an
        element is present)

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverstreamcrsrownot1(presolverstack s,
            dyncrs.dynamiccrs a,
            int i,
            int notidx,
            alglib.xparams _params)
        {
            int k = 0;
            int j0 = 0;
            int j1 = 0;
            int cnt = 0;

            j0 = a.rowbegin[i];
            j1 = a.rowend[i]-1;
            cnt = 0;
            for(k=j0; k<=j1; k++)
            {
                if( a.idx[k]!=notidx )
                {
                    cnt = cnt+1;
                }
            }
            presolverstreami(s, cnt, _params);
            for(k=j0; k<=j1; k++)
            {
                if( a.idx[k]!=notidx )
                {
                    presolverstreamir(s, a.idx[k], a.vals[k], _params);
                }
            }
        }


        /*************************************************************************
        Streams entries of a DynamicCRS row that have corresponding flags set to false.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverstreamcrsrownonflagged(presolverstack s,
            dyncrs.dynamiccrs a,
            int i,
            bool[] flags,
            alglib.xparams _params)
        {
            int k = 0;
            int cnt = 0;
            int j0 = 0;
            int j1 = 0;

            j0 = a.rowbegin[i];
            j1 = a.rowend[i]-1;
            cnt = 0;
            for(k=j0; k<=j1; k++)
            {
                if( !flags[a.idx[k]] )
                {
                    cnt = cnt+1;
                }
            }
            presolverstreami(s, cnt, _params);
            for(k=j0; k<=j1; k++)
            {
                if( !flags[a.idx[k]] )
                {
                    presolverstreamir(s, a.idx[k], a.vals[k], _params);
                }
            }
        }


        /*************************************************************************
        Select transformation TIdx as the source for stream reads

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverselectstreamsource(presolverstack s,
            int tidx,
            alglib.xparams _params)
        {
            s.sourceidx = tidx;
            s.isrc = s.idataridx[tidx];
            s.rsrc = s.rdataridx[tidx];
        }


        /*************************************************************************
        Reads from presolver stack boolean value, advances stream pointer

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverunstreamb(presolverstack s,
            ref bool v,
            alglib.xparams _params)
        {
            v = new bool();

            v = s.idata[s.isrc]!=0;
            s.isrc = s.isrc+1;
        }


        /*************************************************************************
        Reads from presolver stack boolean value, advances stream pointer.
        Function instead of a proceduring

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static bool presolverunstreambf(presolverstack s,
            alglib.xparams _params)
        {
            bool result = new bool();

            result = s.idata[s.isrc]!=0;
            s.isrc = s.isrc+1;
            return result;
        }


        /*************************************************************************
        Reads from presolver stack integer value, advances stream pointer

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverunstreami(presolverstack s,
            ref int v,
            alglib.xparams _params)
        {
            v = 0;

            v = s.idata[s.isrc];
            s.isrc = s.isrc+1;
        }


        /*************************************************************************
        Reads from presolver stack real value, advances stream pointer

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverunstreamr(presolverstack s,
            ref double v,
            alglib.xparams _params)
        {
            v = 0;

            v = s.rdata[s.rsrc];
            s.rsrc = s.rsrc+1;
        }


        /*************************************************************************
        Reads from presolver stack int/real pair, advances stream pointers

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverunstreamir(presolverstack s,
            ref int vi,
            ref double vr,
            alglib.xparams _params)
        {
            vi = 0;
            vr = 0;

            vi = s.idata[s.isrc];
            s.isrc = s.isrc+1;
            vr = s.rdata[s.rsrc];
            s.rsrc = s.rsrc+1;
        }


        /*************************************************************************
        Reads from presolver stack compressed sparse vector, advances stream pointers

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverunstreamsparsevec(presolverstack s,
            ref int cnt,
            ref int[] idx,
            ref double[] vals,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            double v = 0;

            presolverunstreami(s, ref cnt, _params);
            ablasf.iallocv(cnt, ref idx, _params);
            ablasf.rallocv(cnt, ref vals, _params);
            for(i=0; i<=cnt-1; i++)
            {
                presolverunstreamir(s, ref j, ref v, _params);
                idx[i] = j;
                vals[i] = v;
            }
        }


        /*************************************************************************
        Checks that we are at the end of the stream corresponding to transfrom #TIdx

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverasserteos(presolverstack s,
            alglib.xparams _params)
        {
            alglib.ap.assert(s.isrc==s.idataridx[s.sourceidx+1], "PresolverAssertEOS: unread integers in the stream");
            alglib.ap.assert(s.rsrc==s.rdataridx[s.sourceidx+1], "PresolverAssertEOS: unread reals in the stream");
        }


        /*************************************************************************
        Appends transform placeholder

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverappendtrf(presolverstack s,
            int tt,
            alglib.xparams _params)
        {
            ablasf.igrowv(s.ntrf+1, ref s.trftype, _params);
            ablasf.igrowv(s.ntrf+2, ref s.idataridx, _params);
            ablasf.igrowv(s.ntrf+2, ref s.rdataridx, _params);
            s.trftype[s.ntrf] = tt;
            s.idataridx[s.ntrf+1] = s.idataridx[s.ntrf];
            s.rdataridx[s.ntrf+1] = s.rdataridx[s.ntrf];
            s.ntrf = s.ntrf+1;
        }


