        /*************************************************************************
        Appends command to fix variable.

        Parameters:
            ColIdx, FixVal  -   column index and value for fixing
            Ci              -   C[i], linear term
            SparseH         -   if HasH=True, quadratic term; may contain already
                                dropped elements. Both triangles are included.
            IsDroppedCol    -   flags for variables that were already dropped.
                                The ColIdx-th one must NOT be included.
                                Used to correctly output elements of H and QC when
                                multiple variables are fixed sequentially.
            HasH            -   if False, SparseH/IsDroppedCol are ignored.
            AT              -   if HasAT=True, linear constraints matrix (transposed)
            HasAT           -   if False, AT is ignored
            QC              -   quadratic constraints, if any

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverappendfixedvar(presolverstack s,
            int colidx,
            double fixval,
            double ci,
            dyncrs.dynamiccrs sparseh,
            presolvervcstats vcstats,
            bool hash,
            dyncrs.dynamiccrs at,
            bool hasat,
            dynamiccrsqconstraints qc,
            alglib.xparams _params)
        {
            dynamiccrsqconstraint qci = null;
            int qidx = 0;
            int qccnt = 0;
            int k = 0;
            int varpos = 0;
            int cntout = 0;

            alglib.ap.assert(!vcstats.isdroppedcol[colidx], "PRESOLVER: integrity check 6632 failed");
            presolverappendtrf(s, pstfixedvar, _params);
            presolverstreami(s, colidx, _params);
            presolverstreamr(s, fixval, _params);
            presolverstreamr(s, ci, _params);
            presolverstreamb(s, hash, _params);
            if( hash )
            {
                presolverstreamcrsrownonflagged(s, sparseh, colidx, vcstats.isdroppedcol, _params);
            }
            
            //
            // Stream linear constraints column, or zero (denoting zero-length array) if no linear constraint
            //
            if( hasat )
            {
                presolverstreamcrsrow(s, at, colidx, _params);
            }
            else
            {
                presolverstreami(s, 0, _params);
            }
            
            //
            // Stream quadratic constraints
            //
            qccnt = qc.constraints.getlength();
            for(qidx=0; qidx<=qccnt-1; qidx++)
            {
                
                //
                // Skip constraints that are dropped at this moment
                //
                if( vcstats.isdroppedqc[qidx] )
                {
                    continue;
                }
                
                //
                // Skip constraints that do not include the fixed variable
                //
                qc.constraints.get(qidx, ref qci);
                varpos = apserv.ibinarysearchlft(qci.varidx, 0, qci.nvars, colidx, _params);
                if( varpos==qci.nvars || qci.varidx[varpos]!=colidx )
                {
                    continue;
                }
                
                //
                // The constraint is accepted and streamed
                //
                presolverstreamb(s, true, _params);
                presolverstreami(s, qidx, _params);
                presolverstreamr(s, qci.b[varpos], _params);
                cntout = 0;
                for(k=qci.fullq.rowbegin[varpos]; k<=qci.fullq.rowend[varpos]-1; k++)
                {
                    if( !vcstats.isdroppedcol[qci.varidx[qci.fullq.idx[k]]] )
                    {
                        cntout = cntout+1;
                    }
                }
                presolverstreami(s, cntout, _params);
                for(k=qci.fullq.rowbegin[varpos]; k<=qci.fullq.rowend[varpos]-1; k++)
                {
                    if( !vcstats.isdroppedcol[qci.varidx[qci.fullq.idx[k]]] )
                    {
                        presolverstreamir(s, qci.varidx[qci.fullq.idx[k]], qci.fullq.vals[k], _params);
                    }
                }
            }
            presolverstreamb(s, false, _params);
        }


        /*************************************************************************
        Appends explicit slack transformation

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverappendexplicitslack(presolverstack s,
            int i,
            int j,
            double aij,
            double slackbndl,
            double slackbndu,
            double al,
            double au,
            dyncrs.dynamiccrs a,
            alglib.xparams _params)
        {
            presolverappendtrf(s, pstexplicitslack, _params);
            presolverstreami(s, i, _params);
            presolverstreami(s, j, _params);
            presolverstreamr(s, aij, _params);
            presolverstreamr(s, slackbndl, _params);
            presolverstreamr(s, slackbndu, _params);
            presolverstreamr(s, al, _params);
            presolverstreamr(s, au, _params);
            presolverstreamcrsrow(s, a, i, _params);
        }


        /*************************************************************************
        Appends implicit slack transformation

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverappendimplicitslack(presolverstack s,
            int i,
            int j,
            double aij,
            double cj,
            double equalitybnd,
            dyncrs.dynamiccrs a,
            alglib.xparams _params)
        {
            presolverappendtrf(s, pstimplicitslack, _params);
            presolverstreami(s, i, _params);
            presolverstreami(s, j, _params);
            presolverstreamr(s, aij, _params);
            presolverstreamr(s, cj, _params);
            presolverstreamr(s, equalitybnd, _params);
            presolverstreamcrsrow(s, a, i, _params);
        }


        /*************************************************************************
        Appends doubleton row which is used to factor out variable Col0 using
        substitution X[COL0] := (ABnd-Ai1*X[COL1])/Ai0.

        AT and SparseH (if HasH=True) must contain original linear constraints prior to substitution.

          -- ALGLIB --
             Copyright 11.06.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverappenddoubletonfactorout(presolverstack s,
            presolvervcstats vcstats,
            int rowidx,
            int col0,
            double bndl0,
            double bndu0,
            int col1,
            double bndl1,
            double bndu1,
            double c0,
            double c1,
            dyncrs.dynamiccrs sparseh,
            bool hash,
            dyncrs.dynamiccrs at,
            dynamiccrsqconstraints qc,
            double ai0,
            double ai1,
            double abnd,
            double newbndl1,
            double newbndu1,
            int bndlactivates,
            int bnduactivates,
            alglib.xparams _params)
        {
            dynamiccrsqconstraint qci = null;
            int qccnt = 0;
            int k = 0;
            int qidx = 0;
            int pos0 = 0;
            int pos1 = 0;

            qccnt = qc.constraints.getlength();
            presolverappendtrf(s, pstdoubletoneq, _params);
            presolverstreami(s, rowidx, _params);
            presolverstreami(s, col0, _params);
            presolverstreamr(s, bndl0, _params);
            presolverstreamr(s, bndu0, _params);
            presolverstreami(s, col1, _params);
            presolverstreamr(s, bndl1, _params);
            presolverstreamr(s, bndu1, _params);
            presolverstreamr(s, ai0, _params);
            presolverstreamr(s, ai1, _params);
            presolverstreamr(s, abnd, _params);
            presolverstreamr(s, newbndl1, _params);
            presolverstreamr(s, newbndu1, _params);
            presolverstreami(s, bndlactivates, _params);
            presolverstreami(s, bnduactivates, _params);
            presolverstreamr(s, c0, _params);
            presolverstreamr(s, c1, _params);
            presolverstreamb(s, hash, _params);
            if( hash )
            {
                presolverstreamcrsrow(s, sparseh, col0, _params);
                presolverstreamcrsrow(s, sparseh, col1, _params);
            }
            presolverstreamcrsrownot1(s, at, col0, rowidx, _params);
            presolverstreamcrsrownot1(s, at, col1, rowidx, _params);
            for(qidx=0; qidx<=qccnt-1; qidx++)
            {
                
                //
                // Skip constraints that are dropped at this moment
                //
                if( vcstats.isdroppedqc[qidx] )
                {
                    continue;
                }
                
                //
                // Skip constraints that do not include at least one of these variables
                //
                qc.constraints.get(qidx, ref qci);
                pos0 = apserv.ibinarysearchlft(qci.varidx, 0, qci.nvars, col0, _params);
                pos1 = apserv.ibinarysearchlft(qci.varidx, 0, qci.nvars, col1, _params);
                if( (pos0==qci.nvars || qci.varidx[pos0]!=col0) && (pos1==qci.nvars || qci.varidx[pos1]!=col1) )
                {
                    continue;
                }
                
                //
                // The constraint is accepted and streamed
                //
                presolverstreamb(s, true, _params);
                presolverstreami(s, qidx, _params);
                if( pos0<qci.nvars && qci.varidx[pos0]==col0 )
                {
                    presolverstreamr(s, qci.b[pos0], _params);
                    presolverstreami(s, qci.fullq.rowend[pos0]-qci.fullq.rowbegin[pos0], _params);
                    for(k=qci.fullq.rowbegin[pos0]; k<=qci.fullq.rowend[pos0]-1; k++)
                    {
                        presolverstreamir(s, qci.varidx[qci.fullq.idx[k]], qci.fullq.vals[k], _params);
                    }
                }
                else
                {
                    presolverstreamr(s, 0.0, _params);
                    presolverstreami(s, 0, _params);
                }
                if( pos1<qci.nvars && qci.varidx[pos1]==col1 )
                {
                    presolverstreamr(s, qci.b[pos1], _params);
                    presolverstreami(s, qci.fullq.rowend[pos1]-qci.fullq.rowbegin[pos1], _params);
                    for(k=qci.fullq.rowbegin[pos1]; k<=qci.fullq.rowend[pos1]-1; k++)
                    {
                        presolverstreamir(s, qci.varidx[qci.fullq.idx[k]], qci.fullq.vals[k], _params);
                    }
                }
                else
                {
                    presolverstreamr(s, 0.0, _params);
                    presolverstreami(s, 0, _params);
                }
            }
            presolverstreamb(s, false, _params);
        }


        /*************************************************************************
        This function restores original solution, given the solution of the
        transformed problem.

        Below N and M denote column/row count for both the original problem and
        transformed one PRIOR to removal of dropped columns and rows.

        INPUT PARAMETERS:
            S   -           a sequence of presolve transformations
            X   -           array[N], transformed solution after permutation
                            that restores original variable order (moves all
                            fixed variables to their positions)
            LagBC-          array[N], Lagrange coeffs for box constraints
            LagLC-          array[M], Lagrange coeffs for linear constraints
                            after permutation that restores original row order
                            (moves all dropped rows to their positions)
            LagQC-          array[MQC], Lagrange coeffs for quadratic constraints
                            after permutation that restores original row order
                            (moves all dropped rows to their positions)
            Stats-          array[N+M], constraint stats for box and linear constraints;
                            quadratic constraints are not included.
                            Ignored if NeedStats=False
            EPS -           stopping criteria, >=0, used to regularize some computations
                            (the idea is that the more regularization, the better, as
                            long as it is below EPS).
            
        OUTPUT PARAMETERS:
            X, LagBC, LagLC, Stats-restored solution
            

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolverrestoresolution(presolverstack s,
            double[] x,
            double[] lagbc,
            double[] laglc,
            double[] lagqc,
            int[] stats,
            bool needstats,
            double eps,
            alglib.xparams _params)
        {
            int tidx = 0;
            int tt = 0;
            int i = 0;
            int j = 0;
            int k = 0;
            int cnt = 0;
            int vstat = 0;
            double aij = 0;
            double v = 0;
            double vv = 0;
            double vvar = 0;
            double vlag = 0;
            double vswap = 0;
            double fixval = 0;
            double ci = 0;
            double cj = 0;
            double c0 = 0;
            double c1 = 0;
            double equalitybnd = 0;
            double bndl = 0;
            double bndu = 0;
            double al = 0;
            double au = 0;
            bool bndlisbc = new bool();
            bool bnduisbc = new bool();
            bool transferlagtobc = new bool();
            double ratingl = 0;
            double ratingu = 0;
            bool hash = new bool();
            int rowidx = 0;
            int col0 = 0;
            double bndl0 = 0;
            double bndu0 = 0;
            int col1 = 0;
            double bndl1 = 0;
            double bndu1 = 0;
            double ai0 = 0;
            double ai1 = 0;
            double abnd = 0;
            double newbndl1 = 0;
            double newbndu1 = 0;
            int bndlactivates = 0;
            int bnduactivates = 0;
            int cnt0 = 0;
            int cnt1 = 0;
            int cnt2 = 0;
            int cnt3 = 0;
            int cntq = 0;
            double g0 = 0;
            double g1 = 0;
            int relevantboundactivatedby = 0;
            int qcidx = 0;
            double d = 0;
            double cs = 0;
            double sn = 0;
            double s00 = 0;
            double s01 = 0;
            double s10 = 0;
            double s11 = 0;
            double s20 = 0;
            double s21 = 0;
            double r0 = 0;
            double r1 = 0;
            double r2 = 0;
            double v0 = 0;
            double v1 = 0;

            for(tidx=s.ntrf-1; tidx>=0; tidx--)
            {
                tt = s.trftype[tidx];
                if( tt==pstobjectivescaling )
                {
                    
                    //
                    // Reverse cost scaling
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreamr(s, ref v, _params);
                    presolverasserteos(s, _params);
                    ablasf.rmulv(s.n, 1/v, lagbc, _params);
                    ablasf.rmulv(s.m, 1/v, laglc, _params);
                    ablasf.rmulv(s.mqc, 1/v, lagqc, _params);
                    continue;
                }
                if( tt==pstcolscaling )
                {
                    
                    //
                    // Reverse column scaling
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreamir(s, ref k, ref v, _params);
                    presolverasserteos(s, _params);
                    x[k] = x[k]/v;
                    lagbc[k] = lagbc[k]*v;
                    continue;
                }
                if( tt==pstcolshifting )
                {
                    
                    //
                    // Reverse variable shifting
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreamir(s, ref k, ref v, _params);
                    presolverasserteos(s, _params);
                    x[k] = x[k]-v;
                    continue;
                }
                if( tt==pstrowscaling )
                {
                    
                    //
                    // Reverse row scaling
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreamir(s, ref k, ref v, _params);
                    presolverasserteos(s, _params);
                    laglc[k] = laglc[k]*v;
                    continue;
                }
                if( tt==pstqcscaling )
                {
                    
                    //
                    // Reverse QC scaling
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreamir(s, ref k, ref v, _params);
                    presolverasserteos(s, _params);
                    lagqc[k] = lagqc[k]*v;
                    continue;
                }
                if( tt==pstdropemptycol )
                {
                    
                    //
                    // Reverse dropping empty col
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreami(s, ref k, _params);
                    presolverunstreamr(s, ref vvar, _params);
                    presolverunstreamr(s, ref vlag, _params);
                    presolverunstreami(s, ref vstat, _params);
                    presolverasserteos(s, _params);
                    x[k] = vvar;
                    lagbc[k] = vlag;
                    if( needstats )
                    {
                        stats[k] = vstat;
                    }
                    continue;
                }
                if( tt==pstdropemptyrow )
                {
                    
                    //
                    // Reverse dropping empty row
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreami(s, ref k, _params);
                    presolverasserteos(s, _params);
                    laglc[k] = 0;
                    if( needstats )
                    {
                        stats[k] = 0;
                    }
                    continue;
                }
                if( tt==pstdropemptyqc )
                {
                    
                    //
                    // Reverse dropping QC
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreami(s, ref k, _params);
                    presolverasserteos(s, _params);
                    lagqc[k] = 0;
                    continue;
                }
                if( tt==pstsingletonrow )
                {
                    
                    //
                    // Handle singleton row.
                    // Read data from stream.
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreami(s, ref i, _params);
                    presolverunstreami(s, ref j, _params);
                    presolverunstreamr(s, ref v, _params);
                    presolverunstreamr(s, ref vswap, _params);
                    presolverunstreamr(s, ref bndl, _params);
                    presolverunstreamb(s, ref bndlisbc, _params);
                    presolverunstreamr(s, ref bndu, _params);
                    presolverunstreamb(s, ref bnduisbc, _params);
                    presolverasserteos(s, _params);
                    
                    //
                    // Determine bound that is "most active" using rating that combines Lagrangian magnitude
                    //
                    alglib.ap.assert(math.isfinite(bndl) || math.isfinite(bndu), "PRESOLVE: singleton row with both bounds absent");
                    alglib.ap.assert((double)(Math.Abs(vswap))==(double)(1), "PRESOLVE: unexpected VSwap");
                    ratingl = x[j]-bndl+Math.Max(lagbc[j], 0.0);
                    ratingu = bndu-x[j]+Math.Max(-lagbc[j], 0.0);
                    if( (double)(ratingl)<(double)(ratingu) )
                    {
                        
                        //
                        // Lower bound is more likely
                        //
                        transferlagtobc = bndlisbc;
                    }
                    else
                    {
                        
                        //
                        // Upper bound is more likely
                        //
                        transferlagtobc = bnduisbc;
                    }
                    
                    //
                    // Transfer constraint activity from the transformed problem to the original one
                    //
                    if( transferlagtobc )
                    {
                        
                        //
                        // Box constraint of the original problem is active, linear singleton constraint is inactive
                        //
                        laglc[i] = 0.0;
                        if( needstats )
                        {
                            stats[s.n+i] = 0;
                        }
                    }
                    else
                    {
                        
                        //
                        // Linear constraint of the original problem is active, box constraint is inactive.
                        //
                        laglc[i] = lagbc[j]/v*vswap;
                        lagbc[j] = 0;
                        if( needstats )
                        {
                            stats[s.n+i] = (int)Math.Round(stats[j]*vswap);
                            stats[j] = 0;
                        }
                    }
                    continue;
                }
                if( tt==pstfixedvar )
                {
                    
                    //
                    // Fixed variable
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreami(s, ref j, _params);
                    presolverunstreamr(s, ref fixval, _params);
                    
                    //
                    // Restore variable
                    //
                    x[j] = fixval;
                    
                    //
                    // Unstream linear term and start computing gradient for the J-th variable
                    //
                    presolverunstreamr(s, ref ci, _params);
                    g0 = ci;
                    
                    //
                    // Unstream quadratic term and update gradient
                    //
                    presolverunstreamb(s, ref hash, _params);
                    if( hash )
                    {
                        presolverunstreamsparsevec(s, ref cnt, ref s.sparseidx0, ref s.sparseval0, _params);
                        for(i=0; i<=cnt-1; i++)
                        {
                            g0 = g0+s.sparseval0[i]*x[s.sparseidx0[i]];
                        }
                    }
                    
                    //
                    // Unstream linear constraints and update gradient
                    //
                    presolverunstreamsparsevec(s, ref cnt, ref s.sparseidx0, ref s.sparseval0, _params);
                    for(i=0; i<=cnt-1; i++)
                    {
                        g0 = g0+s.sparseval0[i]*laglc[s.sparseidx0[i]];
                    }
                    
                    //
                    // Unstream quadratic constraints and update gradient
                    //
                    while( presolverunstreambf(s, _params) )
                    {
                        presolverunstreami(s, ref qcidx, _params);
                        presolverunstreamr(s, ref v, _params);
                        presolverunstreami(s, ref cntq, _params);
                        for(i=0; i<=cntq-1; i++)
                        {
                            presolverunstreamir(s, ref k, ref vv, _params);
                            v = v+vv*x[k];
                        }
                        g0 = g0+lagqc[qcidx]*v;
                    }
                    
                    //
                    // Check EOS
                    //
                    presolverasserteos(s, _params);
                    
                    //
                    // Recompute Lagrange multiplier for the constraint
                    //
                    lagbc[j] = -g0;
                    if( needstats )
                    {
                        stats[j] = Math.Sign(lagbc[j]);
                    }
                    continue;
                }
                if( tt==pstexplicitslack )
                {
                    
                    //
                    // Explicit slack variable:
                    // * deduce its bounds from row activity
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreami(s, ref i, _params);
                    presolverunstreami(s, ref j, _params);
                    presolverunstreamr(s, ref aij, _params);
                    presolverunstreamr(s, ref bndl, _params);
                    presolverunstreamr(s, ref bndu, _params);
                    presolverunstreamr(s, ref al, _params);
                    presolverunstreamr(s, ref au, _params);
                    presolverunstreamsparsevec(s, ref cnt, ref s.sparseidx0, ref s.sparseval0, _params);
                    presolverasserteos(s, _params);
                    x[j] = 0;
                    v = 0;
                    for(k=0; k<=cnt-1; k++)
                    {
                        v = v+s.sparseval0[k]*x[s.sparseidx0[k]];
                    }
                    if( math.isfinite(al) )
                    {
                        al = (al-v)/aij;
                    }
                    if( math.isfinite(au) )
                    {
                        au = (au-v)/aij;
                    }
                    if( (double)(aij)<(double)(0) )
                    {
                        apserv.swapr(ref al, ref au, _params);
                        if( !math.isfinite(al) )
                        {
                            al = Double.NegativeInfinity;
                        }
                        if( !math.isfinite(au) )
                        {
                            au = Double.PositiveInfinity;
                        }
                    }
                    if( math.isfinite(al) && (double)(al)>(double)(bndl) )
                    {
                        bndl = al;
                    }
                    if( math.isfinite(au) && (double)(au)<(double)(bndu) )
                    {
                        bndu = au;
                    }
                    if( math.isfinite(bndl) )
                    {
                        x[j] = bndl;
                    }
                    else
                    {
                        if( math.isfinite(bndu) )
                        {
                            x[j] = bndu;
                        }
                        else
                        {
                            x[j] = 0;
                        }
                    }
                    lagbc[j] = -(aij*laglc[i]);
                    if( needstats )
                    {
                        stats[j] = -(Math.Sign(aij)*stats[s.n+i]);
                    }
                    continue;
                }
                if( tt==pstimplicitslack )
                {
                    
                    //
                    // Implicit slack variable:
                    // * deduce its bounds from row activity
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreami(s, ref i, _params);
                    presolverunstreami(s, ref j, _params);
                    presolverunstreamr(s, ref aij, _params);
                    presolverunstreamr(s, ref cj, _params);
                    presolverunstreamr(s, ref equalitybnd, _params);
                    presolverunstreamsparsevec(s, ref cnt, ref s.sparseidx0, ref s.sparseval0, _params);
                    presolverasserteos(s, _params);
                    x[j] = 0;
                    v = 0;
                    for(k=0; k<=cnt-1; k++)
                    {
                        v = v+s.sparseval0[k]*x[s.sparseidx0[k]];
                    }
                    x[j] = (equalitybnd-v)/aij;
                    lagbc[j] = -(aij*laglc[i]);
                    laglc[i] = laglc[i]-cj/aij;
                    if( needstats )
                    {
                        stats[j] = -(Math.Sign(aij)*stats[s.n+i]);
                    }
                    continue;
                }
                if( tt==pstdoubletoneq )
                {
                    
                    //
                    // Doubleton equality transformation: unstream data and compute residual gradient wrt variables col0 and col1
                    //
                    presolverselectstreamsource(s, tidx, _params);
                    presolverunstreami(s, ref rowidx, _params);
                    presolverunstreami(s, ref col0, _params);
                    presolverunstreamr(s, ref bndl0, _params);
                    presolverunstreamr(s, ref bndu0, _params);
                    presolverunstreami(s, ref col1, _params);
                    presolverunstreamr(s, ref bndl1, _params);
                    presolverunstreamr(s, ref bndu1, _params);
                    presolverunstreamr(s, ref ai0, _params);
                    presolverunstreamr(s, ref ai1, _params);
                    presolverunstreamr(s, ref abnd, _params);
                    presolverunstreamr(s, ref newbndl1, _params);
                    presolverunstreamr(s, ref newbndu1, _params);
                    presolverunstreami(s, ref bndlactivates, _params);
                    presolverunstreami(s, ref bnduactivates, _params);
                    
                    //
                    // Restore variable Col0
                    //
                    x[col0] = apserv.boundval((abnd-ai1*x[col1])/ai0, bndl0, bndu0, _params);
                    
                    //
                    // Unstream linear term and start computing gradient
                    //
                    presolverunstreamr(s, ref c0, _params);
                    presolverunstreamr(s, ref c1, _params);
                    g0 = c0;
                    g1 = c1;
                    
                    //
                    // Unstream quadratic term, add to the residual gradient
                    //
                    presolverunstreamb(s, ref hash, _params);
                    if( hash )
                    {
                        presolverunstreamsparsevec(s, ref cnt0, ref s.sparseidx0, ref s.sparseval0, _params);
                        presolverunstreamsparsevec(s, ref cnt1, ref s.sparseidx1, ref s.sparseval1, _params);
                    }
                    else
                    {
                        cnt0 = 0;
                        cnt1 = 0;
                    }
                    for(i=0; i<=cnt0-1; i++)
                    {
                        g0 = g0+s.sparseval0[i]*x[s.sparseidx0[i]];
                    }
                    for(i=0; i<=cnt1-1; i++)
                    {
                        g1 = g1+s.sparseval1[i]*x[s.sparseidx1[i]];
                    }
                    
                    //
                    // Unstream linear term, add to the residual gradient
                    //
                    presolverunstreamsparsevec(s, ref cnt2, ref s.sparseidx2, ref s.sparseval2, _params);
                    presolverunstreamsparsevec(s, ref cnt3, ref s.sparseidx3, ref s.sparseval3, _params);
                    for(i=0; i<=cnt2-1; i++)
                    {
                        g0 = g0+s.sparseval2[i]*laglc[s.sparseidx2[i]];
                    }
                    for(i=0; i<=cnt3-1; i++)
                    {
                        g1 = g1+s.sparseval3[i]*laglc[s.sparseidx3[i]];
                    }
                    
                    //
                    // Unstream quadratic constraints, add to the residual gradient
                    //
                    while( presolverunstreambf(s, _params) )
                    {
                        presolverunstreami(s, ref qcidx, _params);
                        presolverunstreamr(s, ref v, _params);
                        presolverunstreami(s, ref cntq, _params);
                        for(i=0; i<=cntq-1; i++)
                        {
                            presolverunstreamir(s, ref j, ref vv, _params);
                            v = v+vv*x[j];
                        }
                        g0 = g0+lagqc[qcidx]*v;
                        presolverunstreamr(s, ref v, _params);
                        presolverunstreami(s, ref cntq, _params);
                        for(i=0; i<=cntq-1; i++)
                        {
                            presolverunstreamir(s, ref j, ref vv, _params);
                            v = v+vv*x[j];
                        }
                        g1 = g1+lagqc[qcidx]*v;
                    }
                    
                    //
                    // The stream was fully processed
                    //
                    presolverasserteos(s, _params);
                    
                    //
                    // Compute Lagrange multipliers for box and linear constraints. In order to do
                    // it we solve the following system:
                    //
                    //     [ E0  Ai0 ] [ lagBC ]   [ -(C0 + SUM(lagLC[j]*Aj0)) ]
                    //     [         ] [       ] = [                           ]
                    //     [ E1  Ai1 ] [ lagLC ]   [ -(C1 + SUM(lagLC[j]*Aj1)) ]
                    //
                    // where [E0,E1] is either [0,1], [1,0] or [0,0], depending on which box constraint
                    // is active, if active at all.
                    //
                    // Here LagLC corresponds to the doubleton equality row being handled, and LagBC
                    // corresponds to one of the variable bounds (the specific one is determined
                    // during analysis of the solution recovered).
                    //
                    // We try all three options: no bounds active, bound on col0 is active, bound
                    // on col1 is active, and compare dual and complementarity errors. The option
                    // which gives the smallest error is chosen.
                    //
                    // The current box constraint on variable COL1 is an amalgamation of original
                    // box constraints coming from variables COL0 and COL1. First, we have to determine
                    // whether the constraint is at the upper or at the lower bound. Lagrange
                    // multiplier sign is not a good measure because nearly-zero multipliers can have
                    // their sign flipped due to rounding errors. In order to do so we compute
                    // rating for lower and upper bounds. After comparing them we determine
                    // which bound is active.
                    //
                    v = (-(g0*ai0)-g1*ai1)/(ai0*ai0+ai1*ai1);
                    if( math.isfinite(newbndl1) || math.isfinite(newbndu1) )
                    {
                        ratingl = math.maxrealnumber;
                        ratingu = math.maxrealnumber;
                        if( math.isfinite(newbndl1) )
                        {
                            ratingl = Math.Abs(x[col1]-newbndl1)*Math.Max(-lagbc[col1], 0.0)+Math.Max(x[col1]-newbndl1, 0.0)+Math.Max(lagbc[col1], 0.0);
                        }
                        if( math.isfinite(newbndu1) )
                        {
                            ratingu = Math.Abs(newbndu1-x[col1])*Math.Max(lagbc[col1], 0.0)+Math.Max(newbndu1-x[col1], 0.0)+Math.Max(-lagbc[col1], 0.0);
                        }
                        relevantboundactivatedby = apserv.icase2((double)(ratingl)<(double)(ratingu), bndlactivates, bnduactivates, _params);
                    }
                    else
                    {
                        relevantboundactivatedby = actnone;
                    }
                    if( relevantboundactivatedby==actlowerboundonk0 || relevantboundactivatedby==actupperboundonk0 )
                    {
                        
                        //
                        // The system to be solved in the least-squares sense is
                        //
                        //     [ 1  Ai0 ]             [ -(G0 + SUM(lagLC[j]*Aj0)) ]
                        //     [        ] [ lagBC ]   [                           ]
                        //     [    Ai1 ]*[       ] = [ -(G1 + SUM(lagLC[j]*Aj1)) ]
                        //     [        ] [ lagLC ]   [                           ]
                        //     [ D      ]             [             0             ]
                        //
                        // where D=|X0-BNDL0|+eps or D=|X0-BNDU0|+eps, depending on RelevantBoundActivatedBy.
                        // The first two rows come from requirement for Lagrangian gradient to be zero,
                        // the last row comes from complementarity conditions for lagBC, with EPS being added
                        // to help regularize the problem.
                        //
                        // The system is rewritten as
                        //
                        //     [ S00 S01 ]             [ R0 ]
                        //     [         ] [ lagBC ]   [    ]
                        //     [     S11 ]*[       ] = [ R1 ]
                        //     [         ] [ lagLC ]   [    ]
                        //     [ S20     ]             [ R2 ]
                        //
                        // and is solved by applying a sequence of rotations that converts it to an upper
                        // triangular form.
                        //
                        d = Math.Abs(x[col0]-apserv.rcase2(relevantboundactivatedby==actlowerboundonk0, bndl0, bndu0, _params))+eps;
                        s00 = 1;
                        s01 = ai0;
                        s11 = ai1;
                        s20 = d;
                        r0 = -g0;
                        r1 = -g1;
                        r2 = 0;
                        rotations.generaterotation(s00, s20, ref cs, ref sn, ref v, _params);
                        s00 = v;
                        v0 = s01;
                        s01 = cs*v0;
                        s21 = -(sn*v0);
                        v0 = r0;
                        v1 = r2;
                        r0 = cs*v0+sn*v1;
                        r2 = -(sn*v0)+cs*v1;
                        rotations.generaterotation(s11, s21, ref cs, ref sn, ref v, _params);
                        s11 = v;
                        v0 = r1;
                        v1 = r2;
                        r1 = cs*v0+sn*v1;
                        r2 = -(sn*v0)+cs*v1;
                        alglib.ap.assert((double)(s11)!=(double)(0), "PRESOLVE: integrity check 781139 failed");
                        laglc[rowidx] = r1/s11;
                        lagbc[col0] = (r0-s01*laglc[rowidx])/s00;
                        lagbc[col1] = 0;
                        if( needstats )
                        {
                            
                            //
                            // Determine constraint status; the linear equality constraint is always
                            // active, the question is whether box constraint is actually active or
                            // not. We compare the rating for the activity (Lagrangian multiplier value)
                            // with the rating for inactivity (a distance towards corresponding bound),
                            // and depending on that we set constraint status.
                            //
                            stats[col0] = 0;
                            stats[col1] = 0;
                            if( math.isfinite(bndl0) && Math.Max(-lagbc[col0], 0.0)>x[col0]-bndl0 )
                            {
                                stats[col0] = -1;
                            }
                            if( math.isfinite(bndu0) && Math.Max(lagbc[col0], 0.0)>bndu0-x[col0] )
                            {
                                stats[col0] = 1;
                            }
                            stats[s.n+rowidx] = apserv.ipossign(laglc[rowidx], _params);
                        }
                        continue;
                    }
                    if( relevantboundactivatedby==actlowerboundonk1 || relevantboundactivatedby==actupperboundonk1 )
                    {
                        
                        //
                        // The system is
                        //
                        //     [    Ai0 ]             [ -(G0 + SUM(lagLC[j]*Aj0)) ]
                        //     [        ] [ lagBC ]   [                           ]
                        //     [ 1  Ai1 ]*[       ] = [ -(G1 + SUM(lagLC[j]*Aj1)) ]
                        //     [        ] [ lagLC ]   [                           ]
                        //     [ D      ]             [             0             ]
                        //
                        // where D=|X1-BNDL1|+eps or D=|X1-BNDU1|+eps, depending on RelevantBoundActivatedBy.
                        // The first two rows come from requirement for Lagrangian gradient to be zero,
                        // the last row comes from complementarity conditions for lagBC, with EPS being added
                        // to help regularize the problem.
                        //
                        // The system is rewritten as
                        //
                        //     [     S01 ]             [ R0 ]
                        //     [         ] [ lagBC ]   [    ]
                        //     [ S10 S11 ]*[       ] = [ R1 ]
                        //     [         ] [ lagLC ]   [    ]
                        //     [ S20     ]             [ R2 ]
                        //
                        // and is solved by applying a sequence of rotations that converts it to a
                        // triangular form.
                        //
                        d = Math.Abs(x[col1]-apserv.rcase2(relevantboundactivatedby==actlowerboundonk1, bndl1, bndu1, _params))+eps;
                        s10 = 1;
                        s01 = ai0;
                        s11 = ai1;
                        s20 = d;
                        r0 = -g0;
                        r1 = -g1;
                        r2 = 0;
                        rotations.generaterotation(s10, s20, ref cs, ref sn, ref v, _params);
                        s10 = v;
                        v0 = s11;
                        s11 = cs*v0;
                        s21 = -(sn*v0);
                        v0 = r1;
                        v1 = r2;
                        r1 = cs*v0+sn*v1;
                        r2 = -(sn*v0)+cs*v1;
                        rotations.generaterotation(s01, s21, ref cs, ref sn, ref v, _params);
                        s01 = v;
                        v0 = r0;
                        v1 = r2;
                        r0 = cs*v0+sn*v1;
                        r2 = -(sn*v0)+cs*v1;
                        laglc[rowidx] = r0/s01;
                        lagbc[col0] = 0;
                        lagbc[col1] = (r1-s11*laglc[rowidx])/s10;
                        if( needstats )
                        {
                            
                            //
                            // Determine constraint status; the linear equality constraint is always
                            // active, the question is whether box constraint is actually active or
                            // not. We compare the rating for the activity (Lagrangian multiplier value)
                            // with the rating for inactivity (a distance towards corresponding bound),
                            // and depending on that we set constraint status.
                            //
                            stats[col0] = 0;
                            stats[col1] = 0;
                            if( math.isfinite(bndl1) && Math.Max(-lagbc[col1], 0.0)>x[col1]-bndl1 )
                            {
                                stats[col1] = -1;
                            }
                            if( math.isfinite(bndu1) && Math.Max(lagbc[col1], 0.0)>bndu1-x[col1] )
                            {
                                stats[col1] = 1;
                            }
                            stats[s.n+rowidx] = apserv.ipossign(laglc[rowidx], _params);
                        }
                        continue;
                    }
                    if( relevantboundactivatedby==actnone )
                    {
                        
                        //
                        // No box constraints active at the solution, determine Lagrange multiplier for
                        // the linear constraints by solving a least-squares system
                        //
                        //     [ Ai0 ] [ lagBC ]   [ -(G0 + SUM(lagLC[j]*Aj0)) ]
                        //     [     ] [       ] = [                           ]
                        //     [ Ai1 ] [ lagLC ]   [ -(G1 + SUM(lagLC[j]*Aj1)) ]
                        //
                        lagbc[col0] = 0;
                        lagbc[col1] = 0;
                        laglc[rowidx] = (-(g0*ai0)-g1*ai1)/(ai0*ai0+ai1*ai1);
                        if( needstats )
                        {
                            stats[col0] = 0;
                            stats[col1] = 0;
                            stats[s.n+rowidx] = apserv.ipossign(laglc[rowidx], _params);
                        }
                        continue;
                    }
                    alglib.ap.assert(false, "PRESOLVER: integrity check 8410 failed");
                }
                alglib.ap.assert(false, "PresolverRestoreSolution: unexpected transform type");
            }
        }


        /*************************************************************************
        Convert sparse H given by a single triangle into a full symmetric matrix.

        INPUT PARAMETERS:
            H           -   lower/upper triangular quadratic term
            IsUpper     -   whether H is upper or lower triangular (the other triangle
                            is ignored)
            sparseTmp   -   possibly preallocated buffer; memory is reused if possible
            FullH       -   possibly preallocated matrix; memory is reused if possible
                            
        OUTPUT PARAMETERS:
            FullH       -   NxN CRS matrix, fully symmetric H

          -- ALGLIB --
             Copyright 01.06.2024 by Bochkanov Sergey
        *************************************************************************/
        private static void copyexpandh(sparse.sparsematrix rawh,
            bool isupper,
            sparse.sparsematrix fullh,
            alglib.xparams _params)
        {
            int i = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int n = 0;
            int j = 0;
            int k = 0;
            double v = 0;

            alglib.ap.assert(sparse.sparseiscrs(rawh, _params) && rawh.n==rawh.m, "PRESOLVE: integrity check 0935 failed");
            n = rawh.n;
            
            //
            // Compute row sizes for an expanded matrix
            //
            ablasf.isetallocv(n+1, 0, ref fullh.ridx, _params);
            for(i=0; i<=n-1; i++)
            {
                if( isupper )
                {
                    j0 = rawh.uidx[i];
                    j1 = rawh.ridx[i+1]-1;
                }
                else
                {
                    j0 = rawh.ridx[i];
                    j1 = rawh.didx[i]-1;
                }
                fullh.ridx[i+1] = fullh.ridx[i+1]+(j1-j0+1);
                for(jj=j0; jj<=j1; jj++)
                {
                    j = rawh.idx[jj];
                    fullh.ridx[j+1] = fullh.ridx[j+1]+1;
                }
                fullh.ridx[i+1] = fullh.ridx[i+1]+1;
            }
            for(i=0; i<=n-1; i++)
            {
                fullh.ridx[i+1] = fullh.ridx[i+1]+fullh.ridx[i];
            }
            
            //
            // Copy/transpose/merge, use UIdx[] as a temporary buffer to store insert position
            //
            ablasf.iallocv(fullh.ridx[n], ref fullh.idx, _params);
            ablasf.rallocv(fullh.ridx[n], ref fullh.vals, _params);
            ablasf.iallocv(n, ref fullh.didx, _params);
            ablasf.iallocv(n, ref fullh.uidx, _params);
            if( isupper )
            {
                ablasf.icopyvx(n, fullh.ridx, 1, fullh.uidx, 0, _params);
                for(i=n-1; i>=0; i--)
                {
                    j0 = rawh.uidx[i];
                    j1 = rawh.ridx[i+1]-1;
                    for(jj=j1; jj>=j0; jj--)
                    {
                        j = rawh.idx[jj];
                        v = rawh.vals[jj];
                        k = fullh.uidx[i]-1;
                        fullh.idx[k] = j;
                        fullh.vals[k] = v;
                        fullh.uidx[i] = k;
                        k = fullh.uidx[j]-1;
                        fullh.idx[k] = i;
                        fullh.vals[k] = v;
                        fullh.uidx[j] = k;
                    }
                    k = fullh.uidx[i]-1;
                    fullh.idx[k] = i;
                    if( rawh.uidx[i]>rawh.didx[i] )
                    {
                        fullh.vals[k] = rawh.vals[rawh.didx[i]];
                    }
                    else
                    {
                        fullh.vals[k] = 0.0;
                    }
                    fullh.didx[i] = k;
                    fullh.uidx[i] = k;
                }
            }
            else
            {
                ablasf.icopyvx(n, fullh.ridx, 0, fullh.uidx, 0, _params);
                for(i=0; i<=n-1; i++)
                {
                    j0 = rawh.ridx[i];
                    j1 = rawh.didx[i]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        j = rawh.idx[jj];
                        v = rawh.vals[jj];
                        k = fullh.uidx[i];
                        fullh.idx[k] = j;
                        fullh.vals[k] = v;
                        fullh.uidx[i] = k+1;
                        k = fullh.uidx[j];
                        fullh.idx[k] = i;
                        fullh.vals[k] = v;
                        fullh.uidx[j] = k+1;
                    }
                    k = fullh.uidx[i];
                    fullh.idx[k] = i;
                    if( rawh.uidx[i]>rawh.didx[i] )
                    {
                        fullh.vals[k] = rawh.vals[rawh.didx[i]];
                    }
                    else
                    {
                        fullh.vals[k] = 0.0;
                    }
                    fullh.didx[i] = k;
                    fullh.uidx[i] = k+1;
                }
            }
            
            //
            // Recompute UIdx[]
            //
            for(i=0; i<=n-1; i++)
            {
                fullh.uidx[i] = fullh.didx[i]+1;
            }
            
            //
            // Set up sparse matrix metrics
            //
            fullh.matrixtype = 1;
            fullh.m = n;
            fullh.n = n;
            fullh.ninitialized = fullh.ridx[n];
        }


        /*************************************************************************
        Prepare temporaries

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void presolvebuffersinit(presolvebuffers buf,
            int n,
            int m,
            alglib.xparams _params)
        {
            if( n>0 )
            {
                apstruct.nisinitemptyslow(n, buf.setn, _params);
                apstruct.nisinitemptyslow(n, buf.setn2, _params);
                apstruct.nisinitemptyslow(n, buf.setn3, _params);
            }
            if( m>0 )
            {
                apstruct.nisinitemptyslow(m, buf.setm, _params);
            }
            else
            {
                apstruct.nisinitemptyslow(1, buf.setm, _params);
            }
        }


        /*************************************************************************
        This function drops empty columns from the matrix. It may detect unbounded
        problems (when unboundedness is caused by unconstrained column).

        INPUT PARAMETERS:
            C, BndL, BndU  -   array[N], current cost and box constraints.
            IsDroppedCol-   array[N], column statuses; only non-dropped ones are examined.
            LagrangeFromResidual- array[N], whether we want to compute Lagrange coeffs
                            for box constraints using residual costs
            H           -   if HasH=True, a full symmetric H with both triangles;
                            diagonal elements are always present, even if zero.
                            If HasH=False, ignored.
            N           -   variables count (including both fixed and non-fixed)
            A, AT       -   current A and AT, dynamic CRS matrices
            AL, AU      -   array[M], lower/upper bounds for linear constraints
            M           -   linear constraints count
            Eps         -   unboundedness is checked subject to small dual feasibility
                            error tolerance
            DoTrace     -   whether tracing is needed or not
            SomethingChanged-flag variable
            CntFixed    -   debug counter, updated by the function
            trfStack    -   sequence of already applied transformations
                            
        OUTPUT PARAMETERS:
            IsDroppedCol-   array[N], dropped columns are marked
            LagrangeFromResidual-
                            array[N], dropped cols are marked
            ProblemStatus-  on failure (unboundedness detected) is set to -2,
                            unchanged otherwise
            SomethingChanged-is set to True if at least one col was dropped
                            It is not changed otherwise.
            CntDropped  -   debug counter, updated by the function
            trfStack -      updated with new transforms
            
        RESULT:
            if unboundedness was detected, False is returned.
            True is returned otherwise.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static bool dropemptycol(double[] c,
            double[] bndl,
            double[] bndu,
            presolvervcstats vcstats,
            bool[] lagrangefromresidual,
            dyncrs.dynamiccrs sparseh,
            bool hash,
            int n,
            dyncrs.dynamiccrs a,
            dyncrs.dynamiccrs at,
            double[] al,
            double[] au,
            int m,
            double eps,
            bool dotrace,
            presolvebuffers buf,
            presolverstack trfstack,
            ref int problemstatus,
            ref bool somethingchanged,
            ref int cntdropped,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            double v = 0;
            int statsval = 0;

            alglib.ap.assert((double)(eps)>=(double)(0), "LPPRESOLVE: Eps<0");
            result = true;
            
            //
            // Scan columns, search for an empty one
            //
            for(i=0; i<=n-1; i++)
            {
                
                //
                // Skip:
                // * already dropped columns
                // * columns that have non-empty A
                // * columns that have non-empty H
                //
                if( vcstats.isdroppedcol[i] )
                {
                    continue;
                }
                if( m!=0 && at.rowbegin[i]!=at.rowend[i] )
                {
                    continue;
                }
                if( hash && ((sparseh.rowbegin[i]+1!=sparseh.rowend[i] || sparseh.idx[sparseh.rowbegin[i]]!=i) || (double)(sparseh.vals[sparseh.rowbegin[i]])!=(double)(0.0)) )
                {
                    continue;
                }
                if( vcstats.nlcpervar[i]!=0 )
                {
                    continue;
                }
                
                //
                // First, try to detect unboundedness
                //
                if( (c[i]<-eps && Double.IsPositiveInfinity(bndu[i])) || (c[i]>eps && Double.IsNegativeInfinity(bndl[i])) )
                {
                    if( dotrace )
                    {
                        alglib.ap.trace(System.String.Format("> the target is unbounded (column {0,0:d} is empty, C[{1,0:d}]<>0, box constraints are insufficient)\n", i, i));
                    }
                    problemstatus = -2;
                    somethingchanged = true;
                    cntdropped = cntdropped+1;
                    result = false;
                    return result;
                }
                
                //
                // Mark variable as fixed and issue transformation
                //
                vcstats.isdroppedcol[i] = true;
                somethingchanged = true;
                cntdropped = cntdropped+1;
                v = 0;
                statsval = 0;
                if( c[i]>0 && math.isfinite(bndl[i]) )
                {
                    
                    //
                    // Variable has to be fixed at the lower bound
                    //
                    v = bndl[i];
                    statsval = -1;
                }
                if( c[i]<0 && math.isfinite(bndu[i]) )
                {
                    
                    //
                    // Variable has to be fixed at the upper bound
                    //
                    v = bndu[i];
                    statsval = 1;
                }
                if( statsval==0 )
                {
                    
                    //
                    // Variable value can be chosen arbitrarily, choose as close to zero as possible
                    //
                    if( math.isfinite(bndl[i]) )
                    {
                        v = Math.Max(v, bndl[i]);
                    }
                    if( math.isfinite(bndu[i]) )
                    {
                        v = Math.Min(v, bndu[i]);
                    }
                }
                presolverappenddropemptycol(trfstack, i, v, -c[i], statsval, _params);
            }
            return result;
        }


        /*************************************************************************
        This function drops clearly nonbinding constraines: empty ones and ones
        with infinite bounds.

        It may detect infeasible problems (when infeasibility is caused by
        constraint ranges  that  do  not include zero - the only value possible for
        an empty constraint).

        INPUT PARAMETERS:
            N           -   vars count
            VCStats     -   variable/constraint statistics
            A, AT       -   current A and AT, dynamic CRS matrices
            AL, AU      -   array[M], lower/upper bounds for linear constraints
            M           -   linear constraints count
            Eps         -   small primal feasibility error is allowed
            DoTrace     -   whether tracing is needed or not
            SomethingChanged-flag variable
            TrfYLag, TrfYTgt, TrfStat, TrfStatTgt -
                            sequence of already applied transformations
                            
        OUTPUT PARAMETERS:
            VCStats.IsDroppedLC/QC-   dropped rows are marked
            ProblemStatus-  on failure (infeasibility detected) is set to -3,
                            unchanged otherwise
            SomethingChanged-is set to True if at least one row was dropped
                            It is not changed otherwise.
            CntEmpty    -   debug counter, updated by the function
            CntNoBounds -   debug counter, updated by the function
            TrfYLag, TrfYTgt, TrfStat, TrfStatTgt -
                            sequence of already applied transformations
            
        RESULT:
            if infeasibility was detected, False is returned.
            True is returned otherwise.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static bool dropclearlynonbindingrows(int n,
            presolvervcstats vcstats,
            dyncrs.dynamiccrs a,
            dyncrs.dynamiccrs at,
            double[] al,
            double[] au,
            int m,
            dynamiccrsqconstraints qc,
            opts.xconicconstraints cc,
            double eps,
            bool dotrace,
            presolvebuffers buf,
            presolverstack trfstack,
            ref int problemstatus,
            ref bool somethingchanged,
            ref int cntempty,
            ref int cntemptyqc,
            ref int cntnobounds,
            ref int cntnoboundsqc,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int ii = 0;
            int jj = 0;
            dynamiccrsqconstraint qci = null;
            int qcidx = 0;
            int qccnt = 0;

            result = true;
            
            //
            // Scan linear constraints
            //
            apstruct.nisclear(buf.setn, _params);
            apstruct.nisclear(buf.setm, _params);
            for(i=0; i<=m-1; i++)
            {
                if( !vcstats.isdroppedlc[i] )
                {
                    
                    //
                    // Empty row
                    //
                    if( a.rowbegin[i]==a.rowend[i] )
                    {
                        
                        //
                        // Try to detect infeasibility
                        //
                        if( (math.isfinite(al[i]) && (double)(al[i])>(double)(eps)) || (math.isfinite(au[i]) && (double)(au[i])<(double)(-eps)) )
                        {
                            if( dotrace )
                            {
                                alglib.ap.trace(System.String.Format("> the constraints are infeasible (row {0,0:d} is empty, initially or due to reductions, updated constraint range does not include zero)\n", i));
                            }
                            problemstatus = -3;
                            somethingchanged = true;
                            result = false;
                            return result;
                        }
                        
                        //
                        // Mark row as dropped and issue transformation
                        //
                        vcstats.isdroppedlc[i] = true;
                        somethingchanged = true;
                        cntempty = cntempty+1;
                        presolverappenddropemptyrow(trfstack, i, _params);
                        continue;
                    }
                    
                    //
                    // No bounds
                    //
                    if( Double.IsNegativeInfinity(al[i]) && Double.IsPositiveInfinity(au[i]) )
                    {
                        
                        //
                        // Add row and column containing its elements to the cleanup list
                        //
                        apstruct.nisaddelement(buf.setm, i, _params);
                        for(jj=a.rowbegin[i]; jj<=a.rowend[i]-1; jj++)
                        {
                            apstruct.nisaddelement(buf.setn, a.idx[jj], _params);
                        }
                        
                        //
                        // Mark row as dropped and issue transformation
                        //
                        vcstats.isdroppedlc[i] = true;
                        somethingchanged = true;
                        cntnobounds = cntnobounds+1;
                        presolverappenddropemptyrow(trfstack, i, _params);
                        continue;
                    }
                }
            }
            for(ii=0; ii<=buf.setm.nstored-1; ii++)
            {
                a.rowend[buf.setm.items[ii]] = a.rowbegin[buf.setm.items[ii]];
            }
            for(jj=0; jj<=buf.setn.nstored-1; jj++)
            {
                dyncrs.dyncrsremovesetfromrow(at, buf.setn.items[jj], buf.setm, _params);
            }
            
            //
            // Scan quadratic constraints
            //
            qccnt = qc.constraints.getlength();
            for(qcidx=0; qcidx<=qccnt-1; qcidx++)
            {
                if( vcstats.isdroppedqc[qcidx] )
                {
                    continue;
                }
                qc.constraints.get(qcidx, ref qci);
                
                //
                // Handle empty constraint
                //
                if( qci.nvars==0 )
                {
                    if( (math.isfinite(qci.cl) && (double)(qci.cl)>(double)(eps)) || (math.isfinite(qci.cu) && (double)(qci.cu)<(double)(-eps)) )
                    {
                        if( dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> the quadratic constraints are infeasible (row {0,0:d} is empty, initially or due to reductions, updated constraint range does not include zero)\n", qcidx));
                        }
                        problemstatus = -3;
                        somethingchanged = true;
                        result = false;
                        return result;
                    }
                    vcstats.isdroppedqc[qcidx] = true;
                    somethingchanged = true;
                    cntemptyqc = cntemptyqc+1;
                    presolverappenddropemptyqc(trfstack, qcidx, _params);
                    continue;
                }
                
                //
                // Handle constraint with no bounds
                //
                if( Double.IsNegativeInfinity(qci.cl) && Double.IsPositiveInfinity(qci.cu) )
                {
                    for(i=0; i<=qci.nvars-1; i++)
                    {
                        vcstats.nlcpervar[qci.varidx[i]] = vcstats.nlcpervar[qci.varidx[i]]-1;
                    }
                    vcstats.isdroppedqc[qcidx] = true;
                    somethingchanged = true;
                    cntnoboundsqc = cntnoboundsqc+1;
                    presolverappenddropemptyqc(trfstack, qcidx, _params);
                    continue;
                }
            }
            return result;
        }


        /*************************************************************************
        This function scans rows and converts singleton rows to box constraints.

        INPUT PARAMETERS:
            BndL, BndU  -   array[N], box constraints.
            VCStats     -   var/constr statistics
            N           -   variables count (including both fixed and non-fixed)
            A, AT       -   current A and AT, dynamic CRS matrices
            AL, AU      -   array[M], lower/upper bounds for linear constraints
            M           -   linear constraints count
            Eps         -   tolerance used to resolve infeasibilities
            DoTrace     -   whether tracing is needed or not
            SomethingChanged-flag variable
            CntFixed    -   debug counter, updated by the function
            trfStack    -   sequence of already applied transformations
                            
        OUTPUT PARAMETERS:
            IsDroppedCol-   array[N], dropped columns are marked
            ProblemStatus-  on failure (unboundedness detected) is set to -2,
                            unchanged otherwise
            SomethingChanged-is set to True if at least one col was dropped
                            It is not changed otherwise.
            CntDropped  -   debug counter, updated by the function
            trfStack -      updated with new transforms
            
        RESULT:
            if unboundedness was detected, False is returned.
            True is returned otherwise.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static bool singletonrowtobc(double[] bndl,
            double[] bndu,
            presolvervcstats vcstats,
            int n,
            dyncrs.dynamiccrs a,
            dyncrs.dynamiccrs at,
            double[] al,
            double[] au,
            int m,
            double eps,
            bool dotrace,
            presolvebuffers buf,
            presolverstack trfstack,
            ref int problemstatus,
            ref bool somethingchanged,
            ref int cntsingleton,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int j = 0;
            int ii = 0;
            int offs = 0;
            double v = 0;
            double prevbndl = 0;
            double prevbndu = 0;
            double wrkal = 0;
            double wrkau = 0;
            double swapsign = 0;
            double midpoint = 0;
            bool lowerboundisbc = new bool();
            bool upperboundisbc = new bool();

            result = true;
            for(i=0; i<=m-1; i++)
            {
                if( (!vcstats.isdroppedlc[i] && a.rowbegin[i]+1==a.rowend[i]) && (math.isfinite(al[i]) || math.isfinite(au[i])) )
                {
                    
                    //
                    // Read singleton row, perform integrity checks and normalization
                    //
                    j = a.idx[a.rowbegin[i]];
                    v = a.vals[a.rowbegin[i]];
                    if( (double)(Math.Abs(v))<=(double)(smlcoeff) )
                    {
                        
                        //
                        // The constraint coefficient is too small, factoring it out may result in numerical instability
                        //
                        continue;
                    }
                    alglib.ap.assert(!vcstats.isdroppedlc[i], "SingletonRowToBC: integrity check 6363 failed");
                    alglib.ap.assert(!vcstats.isdroppedcol[j], "SingletonRowToBC: integrity check 6364 failed");
                    alglib.ap.assert((double)(v)!=(double)(0), "SingletonRowToBC: integrity check 6366 failed");
                    wrkal = al[i];
                    wrkau = au[i];
                    swapsign = 1;
                    if( (double)(v)<(double)(0) )
                    {
                        apserv.swapr(ref wrkal, ref wrkau, _params);
                        wrkal = -wrkal;
                        wrkau = -wrkau;
                        v = -v;
                        swapsign = -1;
                    }
                    wrkal = wrkal/v;
                    wrkau = wrkau/v;
                    prevbndl = bndl[j];
                    prevbndu = bndu[j];
                    
                    //
                    // Check feasibility
                    //
                    if( (double)(prevbndl)>(double)(prevbndu+eps) )
                    {
                        if( dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> the problem is infeasible (box constraint for variable {0,0:d})\n", j));
                        }
                        problemstatus = -3;
                        somethingchanged = true;
                        result = false;
                        return result;
                    }
                    if( (double)(wrkal)>(double)(prevbndu+eps) || (double)(wrkau)<(double)(prevbndl-eps) )
                    {
                        if( dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> the problem is infeasible (singleton row {0,0:d} is incompatible with box constraints for variable {1,0:d})\n", i, j));
                        }
                        problemstatus = -3;
                        somethingchanged = true;
                        result = false;
                        return result;
                    }
                    
                    //
                    // Check compatibility with conic constraints
                    //
                    if( math.isfinite(wrkal) && vcstats.cntdownwardaxial[j]>0 )
                    {
                        
                        //
                        // Constraint enforces lower bound on a downward axial variable (a conically
                        // constrained variable with cone axis oriented towards -INF), skip.
                        //
                        continue;
                    }
                    if( math.isfinite(wrkau) && vcstats.cntupwardaxial[j]>0 )
                    {
                        
                        //
                        // Constraint enforces lower bound on a downward axial variable (a conically
                        // constrained variable with cone axis oriented towards -INF), skip.
                        //
                        continue;
                    }
                    
                    //
                    // Modify problem, perform constraint harmonization for slightly infeasible box constraints
                    //
                    lowerboundisbc = true;
                    upperboundisbc = true;
                    if( math.isfinite(wrkal) && (double)(wrkal)>(double)(prevbndl) )
                    {
                        bndl[j] = wrkal;
                        lowerboundisbc = false;
                    }
                    if( math.isfinite(wrkau) && (double)(wrkau)<(double)(prevbndu) )
                    {
                        bndu[j] = wrkau;
                        upperboundisbc = false;
                    }
                    if( (double)(bndu[j])<(double)(bndl[j]) )
                    {
                        midpoint = 0.5*(bndu[j]+bndl[j]);
                        bndl[j] = midpoint;
                        bndu[j] = midpoint;
                    }
                    a.rowend[i] = a.rowbegin[i];
                    offs = at.rowbegin[j];
                    for(ii=at.rowbegin[j]; ii<=at.rowend[j]-1; ii++)
                    {
                        if( at.idx[ii]!=i )
                        {
                            at.idx[offs] = at.idx[ii];
                            at.vals[offs] = at.vals[ii];
                            offs = offs+1;
                        }
                    }
                    at.rowend[j] = offs;
                    vcstats.isdroppedlc[i] = true;
                    somethingchanged = true;
                    cntsingleton = cntsingleton+1;
                    presolverappendsingletonrow(trfstack, i, j, v, swapsign, bndl[j], lowerboundisbc, bndu[j], upperboundisbc, _params);
                }
            }
            return result;
        }


        /*************************************************************************
        This function scans rows and uses doubleton equality rows to factor out
        linear/quadratic variables.

        INPUT PARAMETERS:
            BndL, BndU  -   array[N], box constraints.
            VCStats     -   variable/constr stats
            H           -   if HasH=True, a full symmetric H with both triangles;
                            diagonal elements are always present, even if zero.
                            If HasH=False, ignored.
            N           -   variables count (including both fixed and non-fixed)
            A, AT       -   current A and AT, dynamic CRS matrices
            AL, AU      -   array[M], lower/upper bounds for linear constraints
            M           -   linear constraints count
            QC          -   DynCRS-based quadratic constraints
            Eps         -   tolerance used to resolve infeasibilities
            DoTrace     -   whether tracing is needed or not
            SomethingChanged-flag variable
            CntFixed    -   debug counter, updated by the function
            trfStack    -   sequence of already applied transformations
                            
        OUTPUT PARAMETERS:
            VCStats     -   dropped columns and rows are marked
            ProblemStatus-  on failure (unboundedness detected) is set to -2,
                            unchanged otherwise
            SomethingChanged-is set to True if at least one col was dropped
                            It is not changed otherwise.
            CntDropped  -   debug counter, updated by the function
            trfStack -      updated with new transforms
            
        RESULT:
            if unboundedness was detected, False is returned.
            True is returned otherwise.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static bool doubletonrow(double[] c,
            double[] bndl,
            double[] bndu,
            presolvervcstats vcstats,
            dyncrs.dynamiccrs sparseh,
            bool hash,
            int n,
            dyncrs.dynamiccrs a,
            dyncrs.dynamiccrs at,
            double[] al,
            double[] au,
            int m,
            dynamiccrsqconstraints qc,
            opts.xconicconstraints cc,
            double eps,
            bool dotrace,
            presolvebuffers buf,
            presolverstack trfstack,
            ref int problemstatus,
            ref bool somethingchanged,
            ref int cntdoubleton,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int j = 0;
            int k = 0;
            int k0 = 0;
            int k1 = 0;
            int ii = 0;
            int cnt = 0;
            int qcidx = 0;
            int ccidx = 0;
            double v = 0;
            double v0 = 0;
            double v1 = 0;
            double h00 = 0;
            double h01 = 0;
            double h11 = 0;
            double shift = 0;
            double abnd = 0;
            double proposedbndl = 0;
            double proposedbndu = 0;
            int proposedactl = 0;
            int proposedactu = 0;
            double oribndl0 = 0;
            double oribndl1 = 0;
            double oribndu0 = 0;
            double oribndu1 = 0;
            double wrkbndl = 0;
            double wrkbndu = 0;
            double alpha0 = 0;
            double alpha1 = 0;
            int bndlactivates = 0;
            int bnduactivates = 0;
            dynamiccrsqconstraint qci = null;
            opts.xconicconstraint cci = null;
            int localk0 = 0;
            int localk1 = 0;
            bool hadk0 = new bool();
            bool hadk1 = new bool();
            double dummy0 = 0;
            double dummy1 = 0;
            int addedtok1 = 0;

            result = true;
            for(i=0; i<=m-1; i++)
            {
                if( (((!vcstats.isdroppedlc[i] && a.rowbegin[i]+2==a.rowend[i]) && math.isfinite(al[i])) && math.isfinite(au[i])) && Math.Abs(au[i]-al[i])<=eps )
                {
                    
                    //
                    // Read doubleton row, perform integrity checks and normalization.
                    //
                    // We factor out X[K0] from the problem and retain X[K1]. We arrange equations
                    // in such a way that |A[i,k0||>=|A[i,k1||
                    //
                    k0 = a.idx[a.rowbegin[i]];
                    k1 = a.idx[a.rowbegin[i]+1];
                    if( isfixed(bndl[k0], bndu[k0], eps, _params) || isfixed(bndl[k1], bndu[k1], eps, _params) )
                    {
                        
                        //
                        // If at least one of variables is fixed, we skip doubleton transformation.
                        //
                        continue;
                    }
                    if( vcstats.cntaxial[k0]+vcstats.cntaxial[k1]>0 )
                    {
                        
                        //
                        // If at least one of variables is axial for some conic constraint, we skip doubleton transformation
                        //
                        continue;
                    }
                    v0 = a.vals[a.rowbegin[i]];
                    v1 = a.vals[a.rowbegin[i]+1];
                    if( (double)(v0*v1)==(double)(0) )
                    {
                        continue;
                    }
                    alglib.ap.assert(!vcstats.isdroppedcol[k0], "PRESOLVER: integrity check 4253 failed");
                    alglib.ap.assert(!vcstats.isdroppedcol[k1], "PRESOLVER: integrity check 4254 failed");
                    if( (double)(Math.Abs(v0))<(double)(Math.Abs(v1)) )
                    {
                        apserv.swapi(ref k0, ref k1, _params);
                        apserv.swapr(ref v0, ref v1, _params);
                    }
                    if( (double)(Math.Abs(v0))<(double)(smlcoeff) )
                    {
                        
                        //
                        // Row magnitude is too small, do not perform substitution because it may result in
                        // the loss of numerical stability
                        //
                        continue;
                    }
                    abnd = 0.5*(al[i]+au[i]);
                    alpha0 = abnd/v0;
                    alpha1 = -(v1/v0);
                    
                    //
                    // Compute updated bounds on X[K1], for each bound compute variable being activated:
                    // *  0 means that reduced variable at this bound activates lower bound on X0
                    // *  1 means that reduced variable at this bound activates upper bound on X0
                    // *  2 means that reduced variable at this bound activates lower bound on X1
                    // *  3 means that reduced variable at this bound activates upper bound on X1
                    // * -1 denotes absent bound
                    //
                    // Check feasibility.
                    //
                    oribndl0 = bndl[k0];
                    oribndu0 = bndu[k0];
                    oribndl1 = bndl[k1];
                    oribndu1 = bndu[k1];
                    wrkbndl = bndl[k1];
                    wrkbndu = bndu[k1];
                    bndlactivates = apserv.icase2(math.isfinite(wrkbndl), actlowerboundonk1, actnone, _params);
                    bnduactivates = apserv.icase2(math.isfinite(wrkbndu), actupperboundonk1, actnone, _params);
                    proposedactl = actnone;
                    proposedactu = actnone;
                    proposedbndl = 0.0;
                    proposedbndu = 0.0;
                    if( (double)(v0*v1)>(double)(0) )
                    {
                        if( math.isfinite(bndu[k0]) )
                        {
                            proposedbndl = (abnd-v0*bndu[k0])/v1;
                            proposedactl = actupperboundonk0;
                        }
                        if( math.isfinite(bndl[k0]) )
                        {
                            proposedbndu = (abnd-v0*bndl[k0])/v1;
                            proposedactu = actlowerboundonk0;
                        }
                    }
                    else
                    {
                        if( math.isfinite(bndl[k0]) )
                        {
                            proposedbndl = (abnd-v0*bndl[k0])/v1;
                            proposedactl = actlowerboundonk0;
                        }
                        if( math.isfinite(bndu[k0]) )
                        {
                            proposedbndu = (abnd-v0*bndu[k0])/v1;
                            proposedactu = actupperboundonk0;
                        }
                    }
                    if( proposedactl!=actnone && proposedbndl>wrkbndl )
                    {
                        wrkbndl = proposedbndl;
                        bndlactivates = proposedactl;
                    }
                    if( proposedactu!=actnone && proposedbndu<wrkbndu )
                    {
                        wrkbndu = proposedbndu;
                        bnduactivates = proposedactu;
                    }
                    if( (double)(wrkbndl)>(double)(wrkbndu+eps) )
                    {
                        if( dotrace )
                        {
                            alglib.ap.trace(System.String.Format("> the problem is infeasible (equality constraint {0,0:d} is incompatible with bounds on variable {1,0:d} and {2,0:d})\n", i, k0, k1));
                        }
                        problemstatus = -3;
                        somethingchanged = true;
                        result = false;
                        return result;
                    }
                    if( (double)(wrkbndl)>(double)(wrkbndu) )
                    {
                        alglib.ap.assert(math.isfinite(wrkbndl) && math.isfinite(wrkbndu), "PRESOLVER: integrity check 2124 failed");
                        v = 0.5*(wrkbndl+wrkbndu);
                        wrkbndl = v;
                        wrkbndu = v;
                    }
                    
                    //
                    // Modify constraints:
                    // * issue transformation
                    // * drop variable K0
                    // * drop constraint I
                    // * factor out variable K0 from all constraints where it is present
                    // * change bounds for K1
                    //
                    presolverappenddoubletonfactorout(trfstack, vcstats, i, k0, oribndl0, oribndu0, k1, oribndl1, oribndu1, c[k0], c[k1], sparseh, hash, at, qc, v0, v1, abnd, wrkbndl, wrkbndu, bndlactivates, bnduactivates, _params);
                    vcstats.isdroppedcol[k0] = true;
                    vcstats.isdroppedlc[i] = true;
                    dyncrs.dyncrsclearrow(a, i, _params);
                    dyncrs.dyncrsremovefromrow(at, k0, i, _params);
                    dyncrs.dyncrsremovefromrow(at, k1, i, _params);
                    cnt = 0;
                    ablasf.iallocv(at.rowend[k0]-at.rowbegin[k0], ref buf.sparseidx, _params);
                    ablasf.rallocv(at.rowend[k0]-at.rowbegin[k0], ref buf.sparsevals, _params);
                    for(ii=at.rowbegin[k0]; ii<=at.rowend[k0]-1; ii++)
                    {
                        k = at.idx[ii];
                        dyncrs.dyncrsfactoroutfromrow(a, k, k0, alpha0, alpha1, k1, true, ref v, ref shift, _params);
                        buf.sparseidx[cnt] = k;
                        buf.sparsevals[cnt] = v;
                        cnt = cnt+1;
                        if( math.isfinite(al[k]) )
                        {
                            al[k] = al[k]-shift;
                        }
                        if( math.isfinite(au[k]) )
                        {
                            au[k] = au[k]-shift;
                        }
                    }
                    dyncrs.dyncrsinsertwithrewrite(at, k1, buf.sparseidx, buf.sparsevals, cnt, _params);
                    dyncrs.dyncrsclearrow(at, k0, _params);
                    bndl[k1] = wrkbndl;
                    bndu[k1] = wrkbndu;
                    
                    //
                    // Modify linear term with an update to C[K1] from C[K0]
                    //
                    c[k1] = c[k1]+c[k0]*alpha1;
                    
                    //
                    // Handle updates coming from the quadratic term, if we have it; clear H.
                    //
                    if( hash )
                    {
                        
                        //
                        // Analyze how 2x2 quadratic [h00 h01 ; h10 h11] changes when we
                        // substitute x0 := alpha0 + alpha1*x1.
                        //
                        // We have
                        //
                        //     h00*(alpha0+alpha1*x1)^2 + 2*h01*(alpha0+alpha1*x1)*x1 + h11*x1^2 =
                        //     h00*alpha0^2 + 2*h00*alpha0*alpha1*x1 + h00*alpha1^2*x1^2   +   2*h01*alpha0*x1+2*h01*alpha1*x1^2 + h11*x1^2 =
                        //     2*(h00*alpha0*alpha1+h01*alpha0)*x1 + (h00*alpha1^2+2*h01*alpha1+h11)*x1^2
                        //
                        h00 = dyncrs.dyncrsgetexistingelement(sparseh, k0, k0, _params);
                        h11 = dyncrs.dyncrsgetexistingelement(sparseh, k1, k1, _params);
                        h01 = dyncrs.dyncrsgetelementifexists(sparseh, k0, k1, _params);
                        
                        //
                        // Handle updates coming from modification of elements of H that are outside of the
                        // [k0,k1]x[k0,k1] diagonal block. The constant term in X[K0]:=Alpha0+Alpha1*X[K1]
                        // updates the linear term C[], the linear term Alpha1 updates the matrix H.
                        //
                        // The matrix H is updates applied to its column K1, then to its row K1. The row update
                        // modifies the [k0,k1]x[k0,k1] diagonal block because there is no easy way to do it
                        // without touching elements that we want to process later. We handle it by saving
                        // H00, H01, H11 prior to this block and by discarding and rewriting diagonal completely
                        // after calling DynCRSAddRowTo().
                        //
                        for(ii=sparseh.rowbegin[k0]; ii<=sparseh.rowend[k0]-1; ii++)
                        {
                            j = sparseh.idx[ii];
                            if( j!=k0 && j!=k1 )
                            {
                                
                                //
                                // Update C[] and column K1 of H.
                                //
                                v = sparseh.vals[ii];
                                c[j] = c[j]+v*alpha0;
                                dyncrs.dyncrsfactoroutfromrow(sparseh, j, k0, 0.0, alpha1, k1, false, ref dummy0, ref dummy1, _params);
                            }
                        }
                        dyncrs.dyncrsaddrowto(sparseh, k0, alpha1, k1, true, false, _params);
                        dyncrs.dyncrsclearrow(sparseh, k0, _params);
                        dyncrs.dyncrsremovefromrow(sparseh, k1, k0, _params);
                        
                        //
                        // Handle updates coming from substituting X[K0]:=Alpha0+Alpha1*X[K1] to the
                        // [k0,k1]x[k0,k1] diagonal block.
                        //
                        c[k1] = c[k1]+(h00*alpha0*alpha1+h01*alpha0);
                        dyncrs.dyncrssetexistingelement(sparseh, k1, k1, h00*alpha1*alpha1+2*h01*alpha1+h11, _params);
                    }
                    
                    //
                    // Update quadratic and conic constraints
                    //
                    if( vcstats.nlcpervar[k0]+vcstats.nlcpervar[k1]>0 )
                    {
                        
                        //
                        // Update quadratic constraints:
                        // * use VarByQC for quick navigation (no need to enumerate all constraints)
                        // * pop indexes of constraints referencing K0 from VarByQC
                        // * save indexes of constraints added to K1 in Buf.tmp0[] (we can't immediately call 
                        //   knisAddNewElement because it can invalidate pointers used for direct access)
                        // * tell VarByQC that memory occupied by the K0-th set can be reclaimed
                        //
                        addedtok1 = 0;
                        while( apstruct.kniscountkth(vcstats.varbyqc, k0, _params)>0 )
                        {
                            qcidx = apstruct.knispoplast(vcstats.varbyqc, k0, _params);
                            alglib.ap.assert(!vcstats.isdroppedqc[qcidx], "PRESOLVER: integrity check 635245 failed");
                            qc.constraints.get(qcidx, ref qci);
                            localk0 = -1;
                            localk1 = -1;
                            for(j=0; j<=qci.nvars-1; j++)
                            {
                                if( qci.varidx[j]==k0 )
                                {
                                    localk0 = j;
                                }
                                if( qci.varidx[j]==k1 )
                                {
                                    localk1 = j;
                                }
                            }
                            hadk1 = localk1>=0;
                            if( localk0<0 )
                            {
                                continue;
                            }
                            if( localk1<0 )
                            {
                                localk1 = apserv.ibinarysearchlft(qci.varidx, 0, qci.nvars, k1, _params);
                                if( localk0>=localk1 )
                                {
                                    localk0 = localk0+1;
                                }
                                dynqccopyinsertrowcol(qci, k1, localk1, buf.qc, _params);
                            }
                            else
                            {
                                dynqccopy(qci, buf.qc, _params);
                            }
                            v = factoroutfromquadratic(buf.qc.fullq, buf.qc.b, localk0, alpha0, alpha1, localk1, _params);
                            if( math.isfinite(buf.qc.cl) )
                            {
                                buf.qc.cl = buf.qc.cl-v;
                            }
                            if( math.isfinite(buf.qc.cu) )
                            {
                                buf.qc.cu = buf.qc.cu-v;
                            }
                            dynqccopydeleterowcol(buf.qc, localk0, qci, _params);
                            vcstats.nlcpervar[k0] = vcstats.nlcpervar[k0]-1;
                            if( !hadk1 )
                            {
                                vcstats.nlcpervar[k1] = vcstats.nlcpervar[k1]+1;
                                ablasf.igrowappendv(addedtok1+1, ref buf.tmp0, qcidx, _params);
                                addedtok1 = addedtok1+1;
                            }
                        }
                        for(qcidx=0; qcidx<=addedtok1-1; qcidx++)
                        {
                            apstruct.knisaddnewelement(vcstats.varbyqc, k1, buf.tmp0[qcidx], _params);
                        }
                        apstruct.knisclearkthreclaim(vcstats.varbyqc, k0, _params);
                        
                        //
                        // Update conic constraints:
                        // * use VarByCC for quick navigation (no need to enumerate all constraints)
                        // * pop indexes of constraints referencing K0 from VarByCC
                        // * save indexes of constraints added to K1 in Buf.tmp0[] (we can't immediately call 
                        //   knisAddNewElement because it can invalidate pointers used for direct access)
                        // * tell VarByCC that memory occupied by the K0-th set can be reclaimed
                        //
                        addedtok1 = 0;
                        while( apstruct.kniscountkth(vcstats.varbycc, k0, _params)>0 )
                        {
                            ccidx = apstruct.knispoplast(vcstats.varbycc, k0, _params);
                            alglib.ap.assert(!vcstats.isdroppedcc[ccidx], "PRESOLVER: integrity check 4672221 failed");
                            cc.constraints.get(ccidx, ref cci);
                            optserv.xccfactoroutnonaxial(cci, k0, alpha0, alpha1, k1, ref hadk0, ref hadk1, _params);
                            alglib.ap.assert(hadk0, "PRESOLVER: integrity check 675222 failed");
                            vcstats.cntradial[k0] = vcstats.cntradial[k0]-1;
                            vcstats.nlcpervar[k0] = vcstats.nlcpervar[k0]-1;
                            if( !hadk1 )
                            {
                                vcstats.cntradial[k1] = vcstats.cntradial[k1]+1;
                                vcstats.nlcpervar[k1] = vcstats.nlcpervar[k1]+1;
                                ablasf.igrowappendv(addedtok1+1, ref buf.tmp0, ccidx, _params);
                                addedtok1 = addedtok1+1;
                            }
                        }
                        for(ccidx=0; ccidx<=addedtok1-1; ccidx++)
                        {
                            apstruct.knisaddnewelement(vcstats.varbycc, k1, buf.tmp0[ccidx], _params);
                        }
                        apstruct.knisclearkthreclaim(vcstats.varbycc, k0, _params);
                    }
                    
                    //
                    // Done
                    //
                    somethingchanged = true;
                    cntdoubleton = cntdoubleton+1;
                }
            }
            return result;
        }


        /*************************************************************************
        This function tries to process singleton cols using various heuristics:
        * detect explicit slacks

        INPUT PARAMETERS:
            C. BndL, BndU-  array[N], cost and box constraints.
            IsDroppedCol-   array[N], column statuses, used for integrity checks
            H           -   if HasH=True, a full symmetric H with both triangles;
                            diagonal elements are always present, even if zero.
                            If HasH=False, ignored.
            N           -   variables count (including both fixed and non-fixed)
            A, AT       -   current A and AT, dynamic CRS matrices
            AL, AU      -   array[M], lower/upper bounds for linear constraints
            M           -   linear constraints count
            Eps         -   tolerance used to resolve infeasibilities
            DoTrace     -   whether tracing is needed or not
            SomethingChanged-flag variable
            CntFixed    -   debug counter, updated by the function
            trfStack    -   sequence of already applied transformations
                            
        OUTPUT PARAMETERS:
            C, BndL, BndU-  may be modified
            IsDroppedCol-   array[N], dropped columns are marked
            ProblemStatus-  on failure (unboundedness detected) is set to -2,
                            unchanged otherwise
            SomethingChanged-is set to True if at least one col was dropped
                            It is not changed otherwise.
            CntSlackVars-   debug counter, updated by the function
            trfStack -      updated with new transforms
            
        RESULT:
            if infeasibility or unboundedness was detected, False is returned.
            True is returned otherwise.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static bool singletoncols(double[] c,
            double[] bndl,
            double[] bndu,
            presolvervcstats vcstats,
            dyncrs.dynamiccrs sparseh,
            bool hash,
            int n,
            dyncrs.dynamiccrs a,
            dyncrs.dynamiccrs at,
            double[] al,
            double[] au,
            int m,
            double eps,
            bool dotrace,
            presolvebuffers buf,
            presolverstack trfstack,
            ref int problemstatus,
            ref bool somethingchanged,
            ref int cntslackvars,
            ref int cntimplicitslacks,
            ref int cntfreecolumnsingletons,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int j = 0;
            int ii = 0;
            double preval = 0;
            double prevau = 0;
            double prevabnd = 0;
            double aij = 0;
            double aslk = 0;
            double vslk = 0;
            double v = 0;
            double cj = 0;

            result = true;
            if( m==0 )
            {
                return result;
            }
            for(j=0; j<=n-1; j++)
            {
                
                //
                // skip:
                // * already dropped columns
                // * non-singleton columns
                // * columns with non-zero quadratic term
                //
                if( vcstats.isdroppedcol[j] )
                {
                    continue;
                }
                if( at.rowbegin[j]+1!=at.rowend[j] )
                {
                    continue;
                }
                if( hash && ((sparseh.rowbegin[j]+1!=sparseh.rowend[j] || sparseh.idx[sparseh.rowbegin[j]]!=j) || (double)(sparseh.vals[sparseh.rowbegin[j]])!=(double)(0.0)) )
                {
                    continue;
                }
                if( vcstats.nlcpervar[j]>0 )
                {
                    continue;
                }
                
                //
                // Proceed
                //
                i = at.idx[at.rowbegin[j]];
                cj = c[j];
                aij = at.vals[at.rowbegin[j]];
                if( (double)(Math.Abs(aij))<=(double)(smlcoeff) )
                {
                    continue;
                }
                
                //
                // Skip rows with no bounds, at least one bound is expected for the transformations below
                //
                if( !(math.isfinite(al[i]) || math.isfinite(au[i])) )
                {
                    continue;
                }
                
                //
                // Is it an explicit slack?
                //
                if( (double)(Math.Abs(cj))<=(double)(eps) )
                {
                    
                    //
                    // Clear Cj
                    // Update constraint bounds
                    // Issue "explicit slack" transformation
                    //
                    c[j] = 0;
                    preval = al[i];
                    prevau = au[i];
                    if( (double)(aij)>(double)(0) )
                    {
                        if( math.isfinite(bndl[j]) )
                        {
                            au[i] = au[i]-aij*bndl[j];
                        }
                        else
                        {
                            au[i] = Double.PositiveInfinity;
                        }
                        if( math.isfinite(bndu[j]) )
                        {
                            al[i] = al[i]-aij*bndu[j];
                        }
                        else
                        {
                            al[i] = Double.NegativeInfinity;
                        }
                    }
                    else
                    {
                        if( math.isfinite(bndu[j]) )
                        {
                            au[i] = au[i]-aij*bndu[j];
                        }
                        else
                        {
                            au[i] = Double.PositiveInfinity;
                        }
                        if( math.isfinite(bndl[j]) )
                        {
                            al[i] = al[i]-aij*bndl[j];
                        }
                        else
                        {
                            al[i] = Double.NegativeInfinity;
                        }
                    }
                    presolverappendexplicitslack(trfstack, i, j, aij, bndl[j], bndu[j], preval, prevau, a, _params);
                    
                    //
                    // Remove variable from A and AT
                    //
                    dyncrs.dyncrsclearrow(at, j, _params);
                    dyncrs.dyncrsremovefromrow(a, i, j, _params);
                    vcstats.isdroppedcol[j] = true;
                    
                    //
                    // Done
                    //
                    somethingchanged = true;
                    cntslackvars = cntslackvars+1;
                    continue;
                }
                
                //
                // Is it equality row? The variable can be treated as an implicit slack
                //
                if( ((math.isfinite(al[i]) && math.isfinite(au[i])) && (double)(Math.Abs(al[i]-au[i]))<=(double)(eps)) && (double)(Math.Abs(aij)*maxcoeffgrowth)>=(double)(Math.Abs(cj)) )
                {
                    
                    //
                    // Enforce AL=AU, set Cj to zero
                    //
                    prevabnd = 0.5*(al[i]+au[i]);
                    al[i] = prevabnd;
                    au[i] = prevabnd;
                    v = cj/aij;
                    for(ii=a.rowbegin[i]; ii<=a.rowend[i]-1; ii++)
                    {
                        c[a.idx[ii]] = c[a.idx[ii]]-v*a.vals[ii];
                    }
                    c[j] = 0;
                    
                    //
                    // Update constraint bounds
                    // Issue "implicit slack" transformation
                    //
                    if( (double)(aij)>(double)(0) )
                    {
                        if( math.isfinite(bndl[j]) )
                        {
                            au[i] = au[i]-aij*bndl[j];
                        }
                        else
                        {
                            au[i] = Double.PositiveInfinity;
                        }
                        if( math.isfinite(bndu[j]) )
                        {
                            al[i] = al[i]-aij*bndu[j];
                        }
                        else
                        {
                            al[i] = Double.NegativeInfinity;
                        }
                    }
                    else
                    {
                        if( math.isfinite(bndu[j]) )
                        {
                            au[i] = au[i]-aij*bndu[j];
                        }
                        else
                        {
                            au[i] = Double.PositiveInfinity;
                        }
                        if( math.isfinite(bndl[j]) )
                        {
                            al[i] = al[i]-aij*bndl[j];
                        }
                        else
                        {
                            al[i] = Double.NegativeInfinity;
                        }
                    }
                    presolverappendimplicitslack(trfstack, i, j, aij, cj, prevabnd, a, _params);
                    
                    //
                    // Remove variable from A and AT, set Cj to zero
                    //
                    dyncrs.dyncrsclearrow(at, j, _params);
                    dyncrs.dyncrsremovefromrow(a, i, j, _params);
                    vcstats.isdroppedcol[j] = true;
                    
                    //
                    // Done
                    //
                    somethingchanged = true;
                    cntimplicitslacks = cntimplicitslacks+1;
                    continue;
                }
                
                //
                // Is it a free column singleton?
                //
                if( (!math.isfinite(bndl[j]) && !math.isfinite(bndu[j])) && (double)(Math.Abs(aij)*maxcoeffgrowth)>=(double)(Math.Abs(cj)) )
                {
                    
                    //
                    // Handle single-sided linear constraints or two-sided one.
                    //
                    // A general inequality/range constraint is converted to an equality one by
                    // adding temporary slack variable SLK. This variable is not actually added
                    // to the problem - we analytically remove it right after the addition.
                    //
                    // See 3.2.2 from "A modular presolve procedure for large scale linear programming"
                    // by Swietanowski for more information
                    //
                    if( !math.isfinite(al[i]) || !math.isfinite(au[i]) )
                    {
                        
                        //
                        // Single-sided constraint
                        //
                        // Determine multiplier for the artificial temporary slack variable S.
                        // Check for unboundedness. If bounded, the slack S is zero, right-hand
                        // side of the equality constraint is not modified.
                        //
                        aslk = apserv.rcase2(math.isfinite(au[i]), 1, -1, _params);
                        if( (double)(aslk*cj/aij)>(double)(eps) )
                        {
                            if( dotrace )
                            {
                                alglib.ap.trace(System.String.Format("> the problem is unbounded (deduced from free column singleton analysis for variable {0,0:d}, row {1,0:d})\n", j, i));
                            }
                            problemstatus = -2;
                            somethingchanged = true;
                            result = false;
                            return result;
                        }
                        vslk = 0;
                        if( !math.isfinite(au[i]) )
                        {
                            au[i] = al[i];
                        }
                    }
                    else
                    {
                        
                        //
                        // Two-sided constraint
                        //
                        // Determine value of the temporary slack variable, modify right-hand side
                        // of the constraint.
                        //
                        vslk = apserv.rcase2((double)(cj/aij)>(double)(0), au[i]-al[i], 0.0, _params);
                    }
                    v = cj/aij;
                    for(ii=a.rowbegin[i]; ii<=a.rowend[i]-1; ii++)
                    {
                        c[a.idx[ii]] = c[a.idx[ii]]-v*a.vals[ii];
                    }
                    c[j] = 0;
                    presolverappendimplicitslack(trfstack, i, j, aij, cj, au[i]-vslk, a, _params);
                    al[i] = Double.NegativeInfinity;
                    au[i] = Double.PositiveInfinity;
                    dyncrs.dyncrsclearrow(at, j, _params);
                    dyncrs.dyncrsremovefromrow(a, i, j, _params);
                    vcstats.isdroppedcol[j] = true;
                    cntfreecolumnsingletons = cntfreecolumnsingletons+1;
                    continue;
                }
            }
            return result;
        }


        /*************************************************************************
        This function scans box constraints list and tries  to  fix  variables  by
        removing them from the A and AT matrices and by  recording  transformation
        in trfStack.

        If infeasibility is detected, returns False.

        INPUT PARAMETERS:
            BndL, BndU  -   array[N], current set of box constraints. Only entries
                            with IsDroppedCol[]=False are examined. Entries corresponding
                            to fixed variables are forced to be equal.
            VCStats     -   variable/constr stats
            H           -   if HasH=True, a full symmetric H with both triangles;
                            diagonal elements are always present, even if zero.
                            If HasH=False, ignored.
            N           -   variables count (including both fixed and non-fixed)
            A, AT       -   current A and AT, dynamic CRS matrices
            AL, AU      -   array[M], lower/upper bounds for linear constraints
            M           -   linear constraints count
            Eps         -   tolerance to resolve slightly infeasible constraints
            DoTrace     -   whether tracing is needed or not
            SomethingChanged-flag variable
            CntFixed    -   debug counter, updated by the function
                            
        OUTPUT PARAMETERS:
            VCStats     -   fixed vars are marked
            A           -   columns corresponding to fixed vars are removed from A.
                            The matrix size does not change.
            AT          -   rows corresponding to fixed vars are removed from A.
                            The matrix size does not change.
            AL, AU      -   updated with fixed values
            SomethingChanged-is set to True if at least one variable was fixed.
                            It is not changed otherwise.
            CntFixed    -   debug counter, updated by the function

        RESULT:
            if infeasibility is detected, returns False.
            True otherwise.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static bool fixvariables(double[] c,
            double[] bndl,
            double[] bndu,
            presolvervcstats vcstats,
            dyncrs.dynamiccrs sparseh,
            bool hash,
            int n,
            dyncrs.dynamiccrs a,
            dyncrs.dynamiccrs at,
            double[] al,
            double[] au,
            int m,
            dynamiccrsqconstraints qc,
            opts.xconicconstraints cc,
            double eps,
            bool dotrace,
            presolvebuffers buf,
            presolverstack trfstack,
            ref int problemstatus,
            ref bool somethingchanged,
            ref int cntfixed,
            alglib.xparams _params)
        {
            bool result = new bool();
            int i = 0;
            int j = 0;
            int ii = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int k = 0;
            int offs = 0;
            double v = 0;
            double vfixed = 0;
            int qcidx = 0;
            int qccnt = 0;
            int ccidx = 0;
            dynamiccrsqconstraint qci = null;
            opts.xconicconstraint cci = null;
            bool hadk0 = new bool();
            bool hadk1 = new bool();

            result = true;
            qccnt = qc.constraints.getlength();
            
            //
            // Scan variables, determine rows to update
            //
            apstruct.nisclear(buf.setn, _params);
            apstruct.nisclear(buf.setm, _params);
            if( hash )
            {
                apstruct.nisclear(buf.setn2, _params);
            }
            for(i=0; i<=n-1; i++)
            {
                if( !vcstats.isdroppedcol[i] && isfixed(bndl[i], bndu[i], eps, _params) )
                {
                    
                    //
                    // Detect infeasibility
                    //
                    if( (double)(bndl[i])>(double)(bndu[i]+eps) )
                    {
                        somethingchanged = true;
                        problemstatus = -3;
                        result = false;
                        return result;
                    }
                    
                    //
                    // Ignore axial variables
                    //
                    if( vcstats.cntaxial[i]>0 )
                    {
                        continue;
                    }
                    
                    //
                    // Fix variable and issue transformation
                    //
                    vfixed = apserv.boundval(0.5*(bndl[i]+bndu[i]), bndl[i], bndu[i], _params);
                    somethingchanged = true;
                    cntfixed = cntfixed+1;
                    bndl[i] = vfixed;
                    bndu[i] = vfixed;
                    presolverappendfixedvar(trfstack, i, vfixed, c[i], sparseh, vcstats, hash, at, m!=0, qc, _params);
                    vcstats.isdroppedcol[i] = true;
                    
                    //
                    // Modify linear term due to modification of a quadratic one, save rows of H that contain I-th variable for further cleaning at the end
                    //
                    if( hash )
                    {
                        j0 = sparseh.rowbegin[i];
                        j1 = sparseh.rowend[i]-1;
                        for(jj=j0; jj<=j1; jj++)
                        {
                            j = sparseh.idx[jj];
                            if( vcstats.isdroppedcol[j] )
                            {
                                continue;
                            }
                            c[j] = c[j]+vfixed*sparseh.vals[jj];
                            apstruct.nisaddelement(buf.setn2, j, _params);
                        }
                    }
                    
                    //
                    // Save dependent linear constraints to SetM
                    //
                    apstruct.nisaddelement(buf.setn, i, _params);
                    if( m!=0 )
                    {
                        for(jj=at.rowbegin[i]; jj<=at.rowend[i]-1; jj++)
                        {
                            apstruct.nisaddelement(buf.setm, at.idx[jj], _params);
                        }
                    }
                    
                    //
                    // Modify quadratic constraints
                    //
                    while( apstruct.kniscountkth(vcstats.varbyqc, i, _params)>0 )
                    {
                        qcidx = apstruct.knispoplast(vcstats.varbyqc, i, _params);
                        alglib.ap.assert(!vcstats.isdroppedqc[qcidx], "PRESOLVER: integrity check 148217 failed");
                        qc.constraints.get(qcidx, ref qci);
                        k = apserv.ibinarysearchlft(qci.varidx, 0, qci.nvars, i, _params);
                        alglib.ap.assert(k<qci.nvars && qci.varidx[k]==i, "PRESOLVER: integrity check 151219 failed");
                        vcstats.nlcpervar[i] = vcstats.nlcpervar[i]-1;
                        v = fixquadraticvariable(qci.fullq, qci.b, k, vfixed, _params);
                        if( math.isfinite(qci.cl) )
                        {
                            qci.cl = qci.cl-v;
                        }
                        if( math.isfinite(qci.cu) )
                        {
                            qci.cu = qci.cu-v;
                        }
                    }
                    apstruct.knisclearkthreclaim(vcstats.varbyqc, i, _params);
                    
                    //
                    // Modify conic constraints
                    //
                    while( apstruct.kniscountkth(vcstats.varbycc, i, _params)>0 )
                    {
                        ccidx = apstruct.knispoplast(vcstats.varbycc, i, _params);
                        alglib.ap.assert(!vcstats.isdroppedcc[ccidx], "PRESOLVER: integrity check 166221 failed");
                        cc.constraints.get(ccidx, ref cci);
                        optserv.xccfactoroutnonaxial(cci, i, vfixed, 0.0, -1, ref hadk0, ref hadk1, _params);
                        alglib.ap.assert(hadk0, "PRESOLVER: integrity check 169221 failed");
                        vcstats.cntradial[i] = vcstats.cntradial[i]-1;
                        vcstats.nlcpervar[i] = vcstats.nlcpervar[i]-1;
                    }
                    apstruct.knisclearkthreclaim(vcstats.varbycc, i, _params);
                }
            }
            if( !somethingchanged )
            {
                return result;
            }
            
            //
            // If linear constraints are present, clear them
            //
            if( m>0 )
            {
                
                //
                // Clear columns of AT corresponding to fixed variables
                //
                for(jj=0; jj<=buf.setn.nstored-1; jj++)
                {
                    i = buf.setn.items[jj];
                    dyncrs.dyncrsclearrow(at, i, _params);
                }
                
                //
                // Scan marked rows of A and remove fixed variables
                //
                for(ii=0; ii<=buf.setm.nstored-1; ii++)
                {
                    i = buf.setm.items[ii];
                    offs = a.rowbegin[i];
                    v = 0;
                    for(jj=a.rowbegin[i]; jj<=a.rowend[i]-1; jj++)
                    {
                        j = a.idx[jj];
                        if( buf.setn.locationof[j]>=0 )
                        {
                            
                            //
                            // Update constraint bounds with fixed variables, remove from linear constraint
                            //
                            v = v+bndl[j]*a.vals[jj];
                        }
                        else
                        {
                            
                            //
                            // Non-fixed variable, retain it
                            //
                            a.idx[offs] = j;
                            a.vals[offs] = a.vals[jj];
                            offs = offs+1;
                        }
                    }
                    a.rowend[i] = offs;
                    if( math.isfinite(al[i]) )
                    {
                        al[i] = al[i]-v;
                    }
                    if( math.isfinite(au[i]) )
                    {
                        au[i] = au[i]-v;
                    }
                }
            }
            
            //
            // Clear flagged rows/columns of SparseH
            //
            if( hash )
            {
                for(ii=0; ii<=buf.setn.nstored-1; ii++)
                {
                    sparseh.rowend[buf.setn.items[ii]] = sparseh.rowbegin[buf.setn.items[ii]];
                }
                for(jj=0; jj<=buf.setn2.nstored-1; jj++)
                {
                    dyncrs.dyncrsremovesetfromrow(sparseh, buf.setn2.items[jj], buf.setn, _params);
                }
            }
            
            //
            // Clear quadratic constraints
            //
            for(qcidx=0; qcidx<=qccnt-1; qcidx++)
            {
                if( vcstats.isdroppedqc[qcidx] )
                {
                    continue;
                }
                qc.constraints.get(qcidx, ref qci);
                apstruct.nisclear(buf.setn3, _params);
                for(j=0; j<=qci.nvars-1; j++)
                {
                    if( buf.setn.locationof[qci.varidx[j]]>=0 )
                    {
                        apstruct.nisaddelement(buf.setn3, j, _params);
                    }
                }
                if( buf.setn3.nstored==0 )
                {
                    continue;
                }
                dynqccopy(qci, buf.qc, _params);
                ablasf.igrowv(buf.qc.nvars, ref buf.tmp0, _params);
                dynqccopydeleterowscols(buf.qc, buf.setn3, qci, buf.tmp0, _params);
            }
            return result;
        }


        /*************************************************************************
        Scale cost vector and constraints, normalize cost.

          -- ALGLIB --
             Copyright 01.07.2022 by Bochkanov Sergey
        *************************************************************************/
        private static void scaleshiftobjectiveandconstraints(double[] s,
            double[] xorigin,
            int n,
            double[] c,
            double[] bndl,
            double[] bndu,
            sparse.sparsematrix sparseh,
            bool hash,
            sparse.sparsematrix sparsea,
            double[] al,
            double[] au,
            int m,
            opts.xquadraticconstraints xqc,
            opts.xconicconstraints xcc,
            presolverstack trfstack,
            alglib.xparams _params)
        {
            int i = 0;
            int j = 0;
            int jj = 0;
            int j0 = 0;
            int j1 = 0;
            int nv = 0;
            double objscale = 0;
            double v = 0;
            double vv = 0;
            double vshift = 0;
            double rowscale = 0;
            double qcscale = 0;
            double ccscale = 0;
            double maxscale = 0;
            int mqc = 0;
            int mcc = 0;
            opts.xquadraticconstraint xqci = null;
            opts.xconicconstraint cci = null;
            double[] bufs = new double[0];
            double[] bufori = new double[0];
            double[] bufqx = new double[0];
            bool done = new bool();

            mqc = opts.xqcgetcount(xqc, _params);
            mcc = optserv.xccgetcount(xcc, _params);
            
            //
            // Apply scaling to linear/quadratic term, determine additional scaling due to normalization 
            //
            objscale = 0;
            for(i=0; i<=n-1; i++)
            {
                c[i] = c[i]*s[i];
                objscale = Math.Max(objscale, Math.Abs(c[i]));
            }
            if( hash )
            {
                for(i=0; i<=n-1; i++)
                {
                    j0 = sparseh.ridx[i];
                    j1 = sparseh.ridx[i+1]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        sparseh.vals[jj] = sparseh.vals[jj]*s[i]*s[sparseh.idx[jj]];
                        objscale = Math.Max(objscale, Math.Abs(sparseh.vals[jj]));
                    }
                }
            }
            objscale = apserv.coalesce(objscale, 1, _params);
            ablasf.rmulv(n, 1/objscale, c, _params);
            if( hash )
            {
                ablasf.rmulv(sparseh.ridx[n], 1/objscale, sparseh.vals, _params);
            }
            presolverappendcostscaling(trfstack, 1/objscale, _params);
            
            //
            // Apply column scaling/shifting to box constraints
            //
            for(i=0; i<=n-1; i++)
            {
                
                //
                // Transform problem
                //
                presolverappendcolshifting(trfstack, i, -xorigin[i], _params);
                presolverappendcolscaling(trfstack, i, 1/s[i], _params);
                bndl[i] = (bndl[i]-xorigin[i])/s[i];
                bndu[i] = (bndu[i]-xorigin[i])/s[i];
            }
            
            //
            // Process linear constraints
            //
            maxscale = 0;
            for(i=0; i<=m-1; i++)
            {
                rowscale = 0;
                vshift = 0;
                j0 = sparsea.ridx[i];
                j1 = sparsea.ridx[i+1]-1;
                for(j=j0; j<=j1; j++)
                {
                    vshift = vshift+sparsea.vals[j]*xorigin[sparsea.idx[j]];
                    v = s[sparsea.idx[j]]*sparsea.vals[j];
                    sparsea.vals[j] = v;
                    rowscale = Math.Max(rowscale, Math.Abs(v));
                }
                al[i] = al[i]-vshift;
                au[i] = au[i]-vshift;
                maxscale = Math.Max(maxscale, rowscale);
                rowscale = Math.Max(rowscale, 1.0);
                
                //
                // Apply transformation to A/AL/AU
                //
                v = 1/rowscale;
                for(j=j0; j<=j1; j++)
                {
                    sparsea.vals[j] = v*sparsea.vals[j];
                }
                al[i] = al[i]*v;
                au[i] = au[i]*v;
                presolverappendrowscaling(trfstack, i, 1/rowscale, _params);
            }
            
            //
            // Process quadratic constraints
            //
            maxscale = 0;
            for(i=0; i<=mqc-1; i++)
            {
                xqc.constraints.get(i, ref xqci);
                nv = xqci.nvars;
                if( nv==0 )
                {
                    continue;
                }
                ablasf.rgrowv(nv, ref bufs, _params);
                ablasf.rgrowv(nv, ref bufori, _params);
                for(j=0; j<=nv-1; j++)
                {
                    bufs[j] = s[xqci.varidx[j]];
                    bufori[j] = xorigin[xqci.varidx[j]];
                }
                
                //
                // First, apply origin:
                //
                //  x := (x-ori) + ori
                //  b'(x+ori) + 0.5(x+ori)'Q(x+ori) = 
                //      = b'x + b'ori + 0.5*[ x'Qx + 2*ori'Qx + ori'*Q*ori ]
                //      = (b+Q*ori)'x + 0.5*x'Qx + [b'ori + 0.5*ori'*Q*ori]
                //
                if( !xqci.applyorigin )
                {
                    ablasf.rallocv(nv, ref bufqx, _params);
                    sparse.sparsesmv(xqci.lowerq, false, bufori, ref bufqx, _params);
                    vshift = ablasf.rdotv(nv, xqci.b, bufori, _params)+0.5*ablasf.rdotv(nv, bufori, bufqx, _params);
                    xqci.cl = xqci.cl-vshift;
                    xqci.cu = xqci.cu-vshift;
                    ablasf.raddv(nv, 1.0, bufqx, xqci.b, _params);
                }
                
                //
                // Second, apply column scales and normalization
                //
                qcscale = 0;
                for(j=0; j<=nv-1; j++)
                {
                    v = xqci.b[j]*bufs[j];
                    xqci.b[j] = v;
                    qcscale = Math.Max(qcscale, Math.Abs(v));
                    j0 = xqci.lowerq.ridx[j];
                    j1 = xqci.lowerq.ridx[j+1]-1;
                    for(jj=j0; jj<=j1; jj++)
                    {
                        v = bufs[j]*xqci.lowerq.vals[jj]*bufs[xqci.lowerq.idx[jj]];
                        xqci.lowerq.vals[jj] = v;
                        qcscale = Math.Max(qcscale, Math.Abs(v));
                    }
                }
                maxscale = Math.Max(maxscale, qcscale);
                qcscale = Math.Max(qcscale, 1);
                if( (double)(qcscale)>(double)(1) )
                {
                    v = 1/qcscale;
                    ablasf.rmulv(nv, v, xqci.b, _params);
                    ablasf.rmulv(xqci.lowerq.ridx[nv], v, xqci.lowerq.vals, _params);
                    xqci.cl = xqci.cl*v;
                    xqci.cu = xqci.cu*v;
                    presolverappendqcscaling(trfstack, i, 1/qcscale, _params);
                }
            }
            
            //
            // Process conic constraints
            //
            maxscale = 0;
            for(i=0; i<=mcc-1; i++)
            {
                xcc.constraints.get(i, ref cci);
                alglib.ap.assert(cci.conetype>=0, "PRESOLVER: unexpected constraint type (non-canonic)");
                nv = cci.nvars;
                if( nv==0 )
                {
                    continue;
                }
                ablasf.rgrowv(nv, ref bufs, _params);
                ablasf.rgrowv(nv, ref bufori, _params);
                for(j=0; j<=nv-1; j++)
                {
                    bufs[j] = s[cci.varidx[j]];
                    bufori[j] = xorigin[cci.varidx[j]];
                }
                
                //
                // First, handle origin, if origin is not included into the constraint
                //
                if( !cci.applyorigin )
                {
                    for(j=0; j<=nv-1; j++)
                    {
                        cci.shftc[j] = cci.shftc[j]+bufori[j]*cci.diaga[j];
                    }
                }
                
                //
                // Second, apply column scales and normalization
                //
                done = false;
                if( cci.conetype==optserv.xccprimitiveconetype(_params) )
                {
                    ccscale = 0;
                    for(j=0; j<=nv-1; j++)
                    {
                        v = cci.diaga[j]*bufs[j];
                        cci.diaga[j] = v;
                        ccscale = Math.Max(ccscale, Math.Abs(v));
                    }
                    maxscale = Math.Max(maxscale, ccscale);
                    ccscale = Math.Max(ccscale, 1);
                    if( (double)(ccscale)>(double)(1) )
                    {
                        v = 1/ccscale;
                        ablasf.rmulv(nv, v, cci.diaga, _params);
                        ablasf.rmulv(nv, v, cci.shftc, _params);
                        cci.shftc[nv] = cci.shftc[nv]*v*v;
                        presolverappendccscaling(trfstack, i, 1/ccscale, _params);
                    }
                    done = true;
                }
                if( cci.conetype==optserv.xccprimitivepowerconetype(_params) )
                {
                    v = 1;
                    for(j=nv-cci.kpow; j<=nv-1; j++)
                    {
                        vv = apserv.coalesce(apserv.rmaxabs2(cci.diaga[j]*bufs[j], cci.shftc[j], _params), 1, _params);
                        v = v*Math.Pow(vv, cci.alphapow[j-(nv-cci.kpow)]);
                        cci.diaga[j] = cci.diaga[j]*bufs[j]/vv;
                        cci.shftc[j] = cci.shftc[j]/vv;
                    }
                    ccscale = v;
                    maxscale = Math.Max(maxscale, ccscale);
                    ablasf.rmergemulv(nv-cci.kpow, bufs, cci.diaga, _params);
                    ablasf.rmulv(nv-cci.kpow, 1/ccscale, cci.diaga, _params);
                    ablasf.rmulv(nv-cci.kpow, 1/ccscale, cci.shftc, _params);
                    cci.shftc[nv] = cci.shftc[nv]/math.sqr(ccscale);
                    presolverappendccscaling(trfstack, i, 1/ccscale, _params);
                    done = true;
                }
                alglib.ap.assert(done, "PRESOLVER: integrity check 707240 failed");
            }
        }


    }
