                _result.rawbndu = (double[])rawbndu.Clone();
                _result.ns = ns;
                _result.m = m;
                _result.a = a!=null ? (sparse.sparsematrix)a.make_copy() : null;
                _result.at = at!=null ? (sparse.sparsematrix)at.make_copy() : null;
